			};

			mockSessionManager.getSession.mockResolvedValue(mockSession);

			// Make 10 rapid requests
			const startTime = Date.now();
			const requests = Array.from({ length: 10 }, () =>
				request(app).get(`/api/sessions/${sessionId}/history`)
			);

			const responses = await Promise.all(requests);
			const duration = Date.now() - startTime;

			// All requests should succeed
			responses.forEach(response => {
				expect(response.status).toBe(200);
			});

			// Should complete reasonably quickly (not timeout)
			expect(duration).toBeLessThan(5000); // 5 seconds max
		});

		it('should prevent API overload with proper error handling', async () => {
			// Simulate overloaded system
			mockSessionManager.listSessions.mockImplementation(async () => {
				await new Promise(resolve => setTimeout(resolve, 100)); // Simulate delay
				throw new Error('System overloaded');
			});

			const startTime = Date.now();
			const response = await request(app).get('/api/sessions').expect(500);

			const duration = Date.now() - startTime;

			expect(response.body.error.message).toBe('System overloaded');
			expect(duration).toBeGreaterThan(90); // Should include the delay
			expect(duration).toBeLessThan(1000); // But not hang indefinitely
		});
	});

	describe('Error Response Format Consistency', () => {
		it('should return consistent error format across all endpoints', async () => {
			const endpoints = [
				{ method: 'get', path: '/api/sessions' },
				{ method: 'post', path: '/api/sessions' },
				{ method: 'delete', path: '/api/sessions/test' },
				{ method: 'get', path: '/api/sessions/test/history' },
			];

			// Mock all operations to fail
			mockSessionManager.listSessions.mockRejectedValue(new Error('Test error'));
			mockSessionManager.createSession.mockRejectedValue(new Error('Test error'));
			mockSessionManager.deleteSession.mockRejectedValue(new Error('Test error'));
			mockSessionManager.getSession.mockRejectedValue(new Error('Test error'));

			for (const endpoint of endpoints) {
				let response;

				if (endpoint.method === 'post') {
					response = await request(app).post(endpoint.path).send({ sessionId: 'test' });
				} else if (endpoint.method === 'delete') {
					response = await request(app).delete(endpoint.path);
				} else {
					response = await request(app).get(endpoint.path);
				}

				// All error responses should have consistent format
				expect(response.status).toBeGreaterThanOrEqual(400);
				expect(response.body.error).toBeDefined();
				expect(response.body.error.message).toBeDefined();
				expect(response.body.error.code).toBeDefined();
				expect(typeof response.body.error.message).toBe('string');
				expect(response.body.error.message).not.toBe('[object Object]');
			}
		});
	});
});

import { Request, Response, NextFunction } from 'express';
import { v4 as uuidv4 } from 'uuid';
import { logger } from '@core/logger/index.js';

// Extend Express Request interface to include requestId
declare global {
	namespace Express {
		interface Request {
			requestId: string;
			startTime: number;
		}
	}
}

/**
 * Request ID middleware - adds unique request ID to each request
 */
export function requestIdMiddleware(req: Request, res: Response, next: NextFunction): void {
	req.requestId = uuidv4();
	req.startTime = Date.now();

	// Add request ID to response headers
	res.setHeader('X-Request-ID', req.requestId);

	next();
}

/**
 * Request logging middleware - logs incoming requests and responses
 */
export function requestLoggingMiddleware(req: Request, res: Response, next: NextFunction): void {
	const { method, url, ip, headers } = req;
	const userAgent = headers['user-agent'] || 'unknown';

	// Log incoming request
	logger.info('API Request', {
		requestId: req.requestId,
		method,
		url,
		ip,
		userAgent,
		contentType: headers['content-type'],
	});

	// Override res.end to log response
	const originalEnd = res.end;
	res.end = function (chunk?: any, encoding?: any): any {
		const duration = Date.now() - req.startTime;
		const { statusCode } = res;

		// Log response
		logger.info('API Response', {
			requestId: req.requestId,
			method,
			url,
			statusCode,
			duration: `${duration}ms`,
			responseSize: res.get('content-length') || 'unknown',
		});

		// Call original end method
		return originalEnd.call(this, chunk, encoding);
	};

	next();
}

/**
 * Error logging middleware - logs errors with request context
 */
export function errorLoggingMiddleware(
	err: Error,
	req: Request,
	res: Response,
	next: NextFunction
): void {
	logger.error('API Error', {
		requestId: req.requestId,
		method: req.method,
		url: req.url,
		error: err.message,
		stack: err.stack,
		userAgent: req.headers['user-agent'],
	});

	next(err);
}

import { Request, Response, NextFunction } from 'express';
import { body, param, query, validationResult } from 'express-validator';
import { errorResponse, ERROR_CODES } from '../utils/response.js';
import { sanitizeInput, isValidSessionId } from '../utils/security.js';

/**
 * Middleware to check validation results and return error if validation failed
 */
export function handleValidationErrors(req: Request, res: Response, next: NextFunction): void {
	const errors = validationResult(req);

	if (!errors.isEmpty()) {
		errorResponse(
			res,
			ERROR_CODES.VALIDATION_ERROR,
			'Validation failed',
			400,
			errors.array(),
			req.requestId
		);
		return;
	}

	next();
}

/**
 * Sanitize text input middleware
 */
export function sanitizeTextInput(fields: string[]) {
	return (req: Request, res: Response, next: NextFunction): void => {
		for (const field of fields) {
			if (req.body[field] && typeof req.body[field] === 'string') {
				req.body[field] = sanitizeInput(req.body[field]);
			}
		}
		next();
	};
}

// Validation schemas for different endpoints

/**
 * Message processing validation
 */
export const validateMessageRequest = [
	body('message')
		.isString()
		.isLength({ min: 1, max: 50000 })
		.withMessage('Message must be a string between 1 and 50000 characters'),
	body('sessionId')
		.optional()
		.custom(value => {
			if (value && !isValidSessionId(value)) {
				throw new Error('Invalid session ID format');
			}
			return true;
		}),
	body('images').optional().isArray().withMessage('Images must be an array'),
	body('images.*').optional().isString().withMessage('Each image must be a base64 string'),
	sanitizeTextInput(['message']),
	handleValidationErrors,
];

/**
 * Session ID parameter validation
 */
export const validateSessionId = [
	param('sessionId').custom(value => {
		if (!isValidSessionId(value)) {
			throw new Error('Invalid session ID format');
		}
		return true;
	}),
	handleValidationErrors,
];

/**
 * Session creation validation
 */
export const validateCreateSession = [
	body('sessionId')
		.optional()
		.custom(value => {
			if (value && !isValidSessionId(value)) {
				throw new Error('Invalid session ID format');
			}
			return true;
		}),
	body('config').optional().isObject().withMessage('Config must be an object'),
	handleValidationErrors,
];

/**
 * MCP server configuration validation
 */
export const validateMcpServerConfig = [
	body('name')
		.isString()
		.isLength({ min: 1, max: 100 })
		.withMessage('Server name must be between 1 and 100 characters'),
	body('command').optional().isString().withMessage('Command must be a string'),
	body('args').optional().isArray().withMessage('Args must be an array'),
	body('env').optional().isObject().withMessage('Environment must be an object'),
	body('transport')
		.optional()
		.isIn(['stdio', 'sse', 'streamable-http'])
		.withMessage('Transport must be stdio, sse, or streamable-http'),
	body('connectionMode')
		.optional()
		.isIn(['strict', 'lenient'])
		.withMessage('Connection mode must be strict or lenient'),
	sanitizeTextInput(['name', 'command']),
	handleValidationErrors,
];

/**
 * MCP server ID validation
 */
export const validateMcpServerId = [
	param('serverId')
		.isString()
		.isLength({ min: 1, max: 100 })
		.withMessage('Server ID must be between 1 and 100 characters'),
	handleValidationErrors,
];

/**
 * Tool execution validation
 */
export const validateToolExecution = [
	param('serverId')
		.isString()
		.isLength({ min: 1, max: 100 })
		.withMessage('Server ID must be between 1 and 100 characters'),
	param('toolName')
		.isString()
		.isLength({ min: 1, max: 100 })
		.withMessage('Tool name must be between 1 and 100 characters'),
	body('arguments').optional().isObject().withMessage('Arguments must be an object'),
	handleValidationErrors,
];

/**
 * LLM configuration validation
 */
export const validateLlmConfig = [
	body('provider')
		.isString()
		.isIn(['openai', 'anthropic', 'openrouter', 'ollama', 'qwen', 'aws', 'azure'])
		.withMessage(
			'Provider must be one of: openai, anthropic, openrouter, ollama, qwen, aws, azure'
		),
	body('model')
		.isString()
		.isLength({ min: 1, max: 100 })
		.withMessage('Model must be between 1 and 100 characters'),
	body('config').optional().isObject().withMessage('Config must be an object'),
	// AWS-specific validations
	body('config.aws.region').optional().isString().withMessage('AWS region must be a string'),
	body('config.aws.accessKeyId')
		.optional()
		.isString()
		.withMessage('AWS access key ID must be a string'),
	body('config.aws.secretAccessKey')
		.optional()
		.isString()
		.withMessage('AWS secret access key must be a string'),
	body('config.aws.sessionToken')
		.optional()
		.isString()
		.withMessage('AWS session token must be a string'),
	// Azure-specific validations
	body('config.azure.endpoint')
		.optional()
		.isURL()
		.withMessage('Azure endpoint must be a valid URL'),
	body('config.azure.deploymentName')
		.optional()
		.isString()
		.withMessage('Azure deployment name must be a string'),
	// Conditional validation - Azure requires endpoint
	body().custom(value => {
		if (value.provider === 'azure' && !value.config?.azure?.endpoint) {
			throw new Error('Azure provider requires config.azure.endpoint to be provided');
		}
		if (value.provider === 'aws' && !value.config?.aws) {
			throw new Error('AWS provider requires config.aws object to be provided');
		}
		return true;
	}),
	sanitizeTextInput(['provider', 'model']),
	handleValidationErrors,
];

/**
 * Query parameter validation
 */
export const validateListParams = [
	query('limit')
		.optional()
		.isInt({ min: 1, max: 100 })
		.withMessage('Limit must be between 1 and 100'),
	query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
	handleValidationErrors,
];

import { Router, Request, Response } from 'express';
import { MemAgent } from '@core/brain/memAgent/index.js';
import { successResponse, errorResponse, ERROR_CODES } from '../utils/response.js';
import { redactSensitiveData } from '../utils/security.js';
import { logger } from '@core/logger/index.js';
import { dump as yamlDump } from 'js-yaml';

export function createConfigRoutes(agent: MemAgent): Router {
	const router = Router();

	/**
	 * GET /api/config.yaml
	 * Export current configuration as YAML with sensitive data redacted
	 */
	router.get('/yaml', async (req: Request, res: Response) => {
		try {
			logger.info('Exporting configuration as YAML', { requestId: req.requestId });

			// Get effective configuration
			const config = agent.getEffectiveConfig();

			// Redact sensitive information
			const redactedConfig = redactSensitiveData(config);

			// Convert to YAML
			const yamlConfig = yamlDump(redactedConfig, {
				indent: 2,
				lineWidth: 120,
				noRefs: true,
			});

			// Set appropriate headers for YAML response
			res.setHeader('Content-Type', 'application/x-yaml; charset=utf-8');
			res.setHeader('Content-Disposition', 'attachment; filename="cipher-config.yml"');
			res.setHeader('X-Request-ID', req.requestId);

			res.send(yamlConfig);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to export configuration', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to export configuration: ${errorMsg}`,
				500,
				undefined,
				req.requestId
			);
		}
	});

	/**
	 * GET /api/config
	 * Get current configuration as JSON with sensitive data redacted
	 */
	router.get('/', async (req: Request, res: Response) => {
		try {
			logger.info('Getting current configuration', { requestId: req.requestId });

			// Get effective configuration
			const config = agent.getEffectiveConfig();

			// Redact sensitive information
			const redactedConfig = redactSensitiveData(config);

			successResponse(
				res,
				{
					config: redactedConfig,
					timestamp: new Date().toISOString(),
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to get configuration', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to get configuration: ${errorMsg}`,
				500,
				undefined,
				req.requestId
			);
		}
	});

	/**
	 * GET /api/config/session/:sessionId
	 * Get session-specific configuration
	 */
	router.get('/session/:sessionId', async (req: Request, res: Response) => {
		try {
			const { sessionId } = req.params;

			if (!sessionId) {
				errorResponse(
					res,
					ERROR_CODES.BAD_REQUEST,
					'Session ID is required',
					400,
					undefined,
					req.requestId
				);
				return;
			}

			logger.info('Getting session-specific configuration', {
				requestId: req.requestId,
				sessionId,
			});

			// Check if session exists
			const session = await agent.getSession(sessionId);
			if (!session) {
				errorResponse(
					res,
					ERROR_CODES.SESSION_NOT_FOUND,
					`Session ${sessionId} not found`,
					404,
					undefined,
					req.requestId
				);
				return;
			}

			// Get session-specific configuration
			const config = agent.getEffectiveConfig(sessionId);

			// Redact sensitive information
			const redactedConfig = redactSensitiveData(config);

			successResponse(
				res,
				{
					sessionId,
					config: redactedConfig,
					timestamp: new Date().toISOString(),
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to get session configuration', {
				requestId: req.requestId,
				sessionId: req.params.sessionId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to get session configuration: ${errorMsg}`,
				500,
				undefined,
				req.requestId
			);
		}
	});

	return router;
}

import { Router, Request, Response } from 'express';
import { MemAgent } from '@core/brain/memAgent/index.js';
import { successResponse, errorResponse, ERROR_CODES } from '../utils/response.js';
import { validateLlmConfig } from '../middleware/validation.js';
