import { Router, Request, Response } from 'express';
import { MemAgent } from '@core/brain/memAgent/index.js';
import { successResponse, errorResponse, ERROR_CODES } from '../utils/response.js';
import {
	validateMcpServerConfig,
	validateMcpServerId,
	validateToolExecution,
	validateListParams,
} from '../middleware/validation.js';
import { logger } from '@core/logger/index.js';

export function createMcpRoutes(agent: MemAgent): Router {
	const router = Router();

	/**
	 * GET /api/mcp/tools
	 * Get all tools from all connected MCP servers (global view)
	 */
	router.get('/tools', validateListParams, async (req: Request, res: Response) => {
		try {
			logger.info('Getting all MCP tools from all servers', { requestId: req.requestId });

			const mcpClients = agent.getMcpClients();
			const allTools: any[] = [];

			// Collect tools from all connected servers
			for (const [serverId, client] of mcpClients.entries()) {
				try {
					const tools = await client.getTools();

					// Check if tools exist and is an array
					if (tools && Array.isArray(tools)) {
						// Add server context to each tool
						const serverTools = tools.map((tool: any) => ({
							...tool,
							serverId,
							serverName: serverId, // Could be enhanced with actual server names
						}));

						allTools.push(...serverTools);
					}
				} catch (error) {
					logger.warn('Failed to get tools from MCP server', {
						requestId: req.requestId,
						serverId,
						error: error instanceof Error ? error.message : String(error),
					});
					// Continue with other servers
				}
			}

			successResponse(
				res,
				{
					tools: allTools,
					totalTools: allTools.length,
					connectedServers: mcpClients.size,
					timestamp: new Date().toISOString(),
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to get all MCP tools', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.MCP_SERVER_ERROR,
				`Failed to get MCP tools: ${errorMsg}`,
				500,
				undefined,
				req.requestId
			);
		}
	});

	/**
	 * GET /api/mcp/servers
	 * List all connected and failed MCP servers
	 */
	router.get('/servers', validateListParams, async (req: Request, res: Response) => {
		try {
			logger.info('Listing MCP servers', { requestId: req.requestId });

			// Use the new comprehensive method that includes all server data
			const allServers = agent.getAllMcpServers();

			const connectedCount = allServers.filter(
				(s: { status: string }) => s.status === 'connected'
			).length;
			const failedCount = allServers.filter((s: { status: string }) => s.status === 'error').length;

			successResponse(
				res,
				{
					servers: allServers,
					totalConnected: connectedCount,
					totalFailed: failedCount,
					totalServers: allServers.length,
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to list MCP servers', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.MCP_SERVER_ERROR,
				`Failed to list MCP servers: ${errorMsg}`,
				500,
				undefined,
				req.requestId
			);
		}
	});

	/**
	 * POST /api/mcp/servers
	 * Connect a new MCP server
	 */
	router.post('/servers', validateMcpServerConfig, async (req: Request, res: Response) => {
		try {
			const { name, transport, command, args, url, env, headers, timeout, connectionMode } =
				req.body;

			logger.info('Connecting MCP server', {
				requestId: req.requestId,
				serverName: name,
				serverType: transport,
			});

			// Construct proper MCP server config based on transport type
			let config: any = {
				type: transport, // Map transport back to type for MCP config
				timeout: timeout || 30000,
				connectionMode: connectionMode || 'lenient',
				enabled: true,
			};

			// Add type-specific fields
			if (transport === 'stdio') {
				config.command = command;
				config.args = args || [];
				config.env = env || {};
			} else if (transport === 'sse' || transport === 'streamable-http') {
				config.url = url;
				config.headers = headers || {};
			}

			await agent.connectMcpServer(name, config);

			successResponse(
				res,
				{
					serverName: name,
					connected: true,
					timestamp: new Date().toISOString(),
				},
				201,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to connect MCP server', {
				requestId: req.requestId,
				serverName: req.body.name,
				error: errorMsg,
			});

			// Determine appropriate status code based on error
			let statusCode = 500;
			if (errorMsg.includes('already exists') || errorMsg.includes('duplicate')) {
				statusCode = 409; // Conflict
			} else if (errorMsg.includes('Invalid') || errorMsg.includes('validation')) {
				statusCode = 400; // Bad Request
			}

			errorResponse(
				res,
				ERROR_CODES.MCP_SERVER_ERROR,
				`Failed to connect MCP server: ${errorMsg}`,
				statusCode,
				undefined,
				req.requestId
			);
		}
	});

	/**
	 * DELETE /api/mcp/servers/:serverId
	 * Disconnect an MCP server
	 */
	router.delete('/servers/:serverId', validateMcpServerId, async (req: Request, res: Response) => {
		try {
			const { serverId } = req.params;

			if (!serverId) {
				errorResponse(
					res,
					ERROR_CODES.BAD_REQUEST,
					'Server ID is required',
					400,
					undefined,
					req.requestId
				);
				return;
			}

			logger.info('Disconnecting MCP server', {
				requestId: req.requestId,
				serverId,
			});

			await agent.removeMcpServer(serverId);

			successResponse(
				res,
				{
					serverId,
					disconnected: true,
					timestamp: new Date().toISOString(),
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to disconnect MCP server', {
				requestId: req.requestId,
				serverId: req.params.serverId,
				error: errorMsg,
			});

			if (errorMsg.includes('not found')) {
				errorResponse(
					res,
					ERROR_CODES.NOT_FOUND,
					`MCP server ${req.params.serverId} not found`,
					404,
					undefined,
					req.requestId
				);
			} else {
				errorResponse(
					res,
					ERROR_CODES.MCP_SERVER_ERROR,
					`Failed to disconnect MCP server: ${errorMsg}`,
					500,
					undefined,
					req.requestId
				);
			}
		}
	});

	/**
	 * GET /api/mcp/servers/:serverId/tools
	 * List tools for a specific MCP server
	 */
	router.get(
		'/servers/:serverId/tools',
		validateMcpServerId,
		async (req: Request, res: Response) => {
			try {
				const { serverId } = req.params;

				if (!serverId) {
					errorResponse(
						res,
						ERROR_CODES.BAD_REQUEST,
						'Server ID is required',
						400,
						undefined,
						req.requestId
					);
					return;
				}

				logger.info('Listing tools for MCP server', {
					requestId: req.requestId,
					serverId,
				});

				const clients = agent.getMcpClients();
				const client = clients.get(serverId);

				if (!client) {
					errorResponse(
						res,
						ERROR_CODES.NOT_FOUND,
						`MCP server ${serverId} not found or not connected`,
						404,
						undefined,
						req.requestId
					);
					return;
				}

				// Get tools from the client
				const toolSet = await client.getTools();
				const tools = Object.entries(toolSet).map(([name, tool]) => ({
					name,
					description: tool.description,
					parameters: tool.parameters,
				}));

				successResponse(
					res,
					{
						serverId,
						tools,
						count: tools.length,
					},
					200,
					req.requestId
				);
			} catch (error) {
				const errorMsg = error instanceof Error ? error.message : String(error);
				logger.error('Failed to list tools for MCP server', {
					requestId: req.requestId,
					serverId: req.params.serverId,
					error: errorMsg,
				});

				errorResponse(
					res,
					ERROR_CODES.MCP_SERVER_ERROR,
					`Failed to list tools: ${errorMsg}`,
					500,
					undefined,
					req.requestId
				);
			}
		}
	);

	/**
	 * POST /api/mcp/servers/:serverId/tools/:toolName/execute
	 * Execute a tool on a specific MCP server
	 */
	router.post(
		'/servers/:serverId/tools/:toolName/execute',
		validateToolExecution,
		async (req: Request, res: Response) => {
			try {
				const { serverId, toolName } = req.params;

				if (!serverId || !toolName) {
					errorResponse(
						res,
						ERROR_CODES.BAD_REQUEST,
						'Server ID and tool name are required',
						400,
						undefined,
						req.requestId
					);
					return;
				}
				const { arguments: toolArgs } = req.body;

				logger.info('Executing MCP tool', {
					requestId: req.requestId,
					serverId,
					toolName,
					hasArguments: Boolean(toolArgs),
				});

				// Check if server exists
				const clients = agent.getMcpClients();
				const client = clients.get(serverId);

				if (!client) {
					errorResponse(
						res,
						ERROR_CODES.NOT_FOUND,
						`MCP server ${serverId} not found or not connected`,
						404,
						undefined,
						req.requestId
					);
					return;
				}

				// Execute the tool through the agent's unified tool manager
				const result = await agent.executeMcpTool(toolName, toolArgs || {});

				successResponse(
					res,
					{
						serverId,
						toolName,
						result,
						executed: true,
						timestamp: new Date().toISOString(),
					},
					200,
					req.requestId
				);
			} catch (error) {
				const errorMsg = error instanceof Error ? error.message : String(error);
				logger.error('Failed to execute MCP tool', {
					requestId: req.requestId,
					serverId: req.params.serverId,
					toolName: req.params.toolName,
					error: errorMsg,
				});

				// Determine appropriate status code
				let statusCode = 500;
				if (errorMsg.includes('not found') || errorMsg.includes('unknown tool')) {
					statusCode = 404;
				} else if (errorMsg.includes('invalid') || errorMsg.includes('validation')) {
					statusCode = 400;
				}

				errorResponse(
					res,
					ERROR_CODES.MCP_SERVER_ERROR,
					`Failed to execute tool: ${errorMsg}`,
					statusCode,
					undefined,
					req.requestId
				);
			}
		}
	);

	return router;
}

import { Router, Request, Response } from 'express';
import { MemAgent } from '@core/brain/memAgent/index.js';
import { successResponse, errorResponse, ERROR_CODES } from '../utils/response.js';
import { validateMessageRequest } from '../middleware/validation.js';
import { logger } from '@core/logger/index.js';

/**
 * Process message asynchronously without blocking the response
 */
async function processMessageAsync(
	agent: MemAgent,
	message: string,
	options: { sessionId?: string; images?: string[]; imageData?: string; fileData?: any },
	requestId?: string
): Promise<void> {
	try {
		// If sessionId is provided, ensure that session is loaded
		if (options.sessionId) {
			try {
				await agent.loadSession(options.sessionId);
			} catch {
				// Create new session with the provided ID
				await agent.createSession(options.sessionId);
			}
		}

		// Convert image data to expected format
		let imageData: { image: string; mimeType: string } | undefined;
		if (options.images && options.images.length > 0 && options.images[0]) {
			imageData = {
				image: options.images[0],
				mimeType: 'image/jpeg',
			};
		} else if (options.imageData && typeof options.imageData === 'string') {
			imageData = {
				image: options.imageData,
				mimeType: 'image/jpeg',
			};
		}

		// Process the message through the agent
		const { backgroundOperations } = await agent.run(message, imageData, options.sessionId);
		await backgroundOperations;

		logger.info('Async message processing completed', {
			requestId,
			sessionId: agent.getCurrentSessionId(),
		});
	} catch (error) {
		logger.error('Async message processing failed', {
			requestId,
			error: error instanceof Error ? error.message : String(error),
		});
	}
}

export function createMessageRoutes(agent: MemAgent): Router {
	const router = Router();

	/**
	 * POST /api/message
	 * Process a message asynchronously and return 202 status immediately
	 */
	router.post('/', validateMessageRequest, async (req: Request, res: Response) => {
		try {
			const { message, sessionId, images, imageData, fileData, streaming = true } = req.body;

			logger.info('Processing async message request', {
				requestId: req.requestId,
				sessionId: sessionId || 'default',
				hasImages: Boolean(images && images.length > 0),
				hasImageData: Boolean(imageData),
				hasFileData: Boolean(fileData),
				messageLength: message.length,
				streaming,
			});

			// Return 202 immediately for async processing
			successResponse(
				res,
				{
					message: 'Message accepted for processing',
					sessionId: sessionId || agent.getCurrentSessionId(),
					requestId: req.requestId,
					timestamp: new Date().toISOString(),
				},
				202,
				req.requestId
			);

			// Process message asynchronously (no await)
			processMessageAsync(
				agent,
				message,
				{ sessionId, images, imageData, fileData },
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Async message processing setup failed', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Message processing setup failed: ${errorMsg}`,
				500,
				process.env.NODE_ENV === 'development' ? error : undefined,
				req.requestId
			);
		}
	});

	/**
	 * POST /api/message-sync
	 * Process a message synchronously and return the full response
	 */
	router.post('/sync', validateMessageRequest, async (req: Request, res: Response) => {
		try {
			const { message, sessionId, images } = req.body;

			logger.info('Processing message request', {
				requestId: req.requestId,
				sessionId: sessionId || 'default',
				hasImages: Boolean(images && images.length > 0),
				messageLength: message.length,
			});

			// If sessionId is provided, ensure that session is loaded
			if (sessionId) {
				try {
					const session = await agent.loadSession(sessionId);
					logger.info(`Loaded session: ${session.id}`, { requestId: req.requestId });
				} catch (error) {
					const errorMsg = error instanceof Error ? error.message : String(error);
					logger.warn(`Session ${sessionId} not found, will create new one: ${errorMsg}`, {
						requestId: req.requestId,
					});

					// Create new session with the provided ID
					try {
						const newSession = await agent.createSession(sessionId);
						logger.info(`Created new session: ${newSession.id}`, { requestId: req.requestId });
					} catch (createError) {
						errorResponse(
							res,
							ERROR_CODES.SESSION_NOT_FOUND,
							`Failed to create session: ${createError instanceof Error ? createError.message : String(createError)}`,
							400,
							undefined,
							req.requestId
						);
						return;
					}
				}
			}

			// Process the message through the agent
			// Convert images array to single image if provided
			let imageData: { image: string; mimeType: string } | undefined;
			if (images && images.length > 0) {
				// For now, use the first image (could be enhanced to handle multiple images)
				imageData = {
					image: images[0],
					mimeType: 'image/jpeg', // Default, could be enhanced to detect actual type
				};
			}

			const { response, backgroundOperations } = await agent.run(message, imageData, sessionId);
			// In API mode, always wait for background operations to complete before returning response
			await backgroundOperations;

			successResponse(
				res,
				{
					response,
					sessionId: agent.getCurrentSessionId(),
					timestamp: new Date().toISOString(),
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Message processing failed', {
				requestId: req.requestId,
				error: errorMsg,
				stack: error instanceof Error ? error.stack : undefined,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Message processing failed: ${errorMsg}`,
				500,
				process.env.NODE_ENV === 'development' ? error : undefined,
				req.requestId
			);
		}
	});

	/**
	 * POST /api/message/reset
	 * Reset conversation state for the current or specified session
	 */
	router.post('/reset', async (req: Request, res: Response) => {
		try {
			const { sessionId } = req.body;

			logger.info('Processing reset request', {
				requestId: req.requestId,
				sessionId: sessionId || 'current',
			});

			if (sessionId) {
				// Reset specific session
				const success = await agent.removeSession(sessionId);
				if (!success) {
					errorResponse(
						res,
						ERROR_CODES.SESSION_NOT_FOUND,
						`Session ${sessionId} not found`,
						404,
						undefined,
						req.requestId
					);
					return;
				}

				// Create a new session with the same ID
				const newSession = await agent.createSession(sessionId);

				successResponse(
					res,
					{
						message: `Session ${sessionId} has been reset`,
						sessionId: newSession.id,
						timestamp: new Date().toISOString(),
					},
					200,
					req.requestId
				);
			} else {
				// Reset current session
				const currentSessionId = agent.getCurrentSessionId();

				if (currentSessionId) {
					await agent.removeSession(currentSessionId);
				}

				// Create a new session
				const newSession = await agent.createSession();

				successResponse(
					res,
					{
						message: 'Current session has been reset',
						sessionId: newSession.id,
						timestamp: new Date().toISOString(),
					},
					200,
					req.requestId
				);
			}
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Reset operation failed', {
				requestId: req.requestId,
				error: errorMsg,
				stack: error instanceof Error ? error.stack : undefined,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Reset operation failed: ${errorMsg}`,
				500,
				process.env.NODE_ENV === 'development' ? error : undefined,
				req.requestId
			);
		}
	});

	return router;
}

