import { Router, Request, Response } from 'express';
import { MemAgent } from '@core/brain/memAgent/index.js';
import { successResponse, errorResponse, ERROR_CODES } from '../utils/response.js';
import {
	validateSessionId,
	validateCreateSession,
	validateListParams,
} from '../middleware/validation.js';
import { logger } from '@core/logger/index.js';

export function createSessionRoutes(agent: MemAgent): Router {
	const router = Router();

	/**
	 * GET /api/sessions
	 * List all active sessions with metadata - OPTIMIZED for performance
	 */
	router.get('/', validateListParams, async (req: Request, res: Response) => {
		const startTime = Date.now();
		try {
			logger.info('Listing sessions', { requestId: req.requestId });

			// PERFORMANCE OPTIMIZATION: Get session IDs with optimized batch processing
			let sessionIds: string[] = [];
			try {
				sessionIds = await agent.listSessions();
				logger.debug(
					`Agent returned ${sessionIds.length} session IDs in ${Date.now() - startTime}ms`
				);
			} catch (listError) {
				logger.error('Failed to get session IDs from agent:', listError);
				// Continue with empty list rather than failing completely
				sessionIds = [];
			}

			if (sessionIds.length === 0) {
				logger.debug('No sessions found, returning empty list');
				successResponse(
					res,
					{
						sessions: [],
						count: 0,
						currentSession: agent.getCurrentSessionId?.() || null,
						processingTime: Date.now() - startTime,
					},
					200,
					req.requestId
				);
				return;
			}

			// PERFORMANCE OPTIMIZATION: Use batch processing for session metadata
			const sessionManager = agent.sessionManager;
			let sessionsMetadata: Map<string, any>;

			try {
				// Use the new batch processing method for optimal performance
				sessionsMetadata = await sessionManager.getBatchSessionMetadata(sessionIds);
				logger.debug(`Batch loaded ${sessionsMetadata.size} session metadata entries`);
			} catch (batchError) {
				logger.warn(
					'Batch metadata loading failed, falling back to individual processing:',
					batchError
				);
				// Fallback to individual processing if batch fails
				sessionsMetadata = new Map();
				for (const sessionId of sessionIds.slice(0, 50)) {
					// Limit to prevent overload
					try {
						const metadata = await agent.getSessionMetadata(sessionId);
						if (metadata) {
							sessionsMetadata.set(sessionId, metadata);
						}
					} catch (error) {
						logger.debug(`Failed to get metadata for session ${sessionId}:`, error);
					}
				}
			}

			// CRITICAL FIX: Filter out sessions with 0 messages to prevent phantom sessions
			const validSessions = Array.from(sessionsMetadata.values()).filter(session => {
				return session.messageCount > 0;
			});

			const processingTime = Date.now() - startTime;

			logger.info(
				`Successfully listed ${validSessions.length}/${Array.from(sessionsMetadata.values()).length} valid sessions in ${processingTime}ms`
			);

			successResponse(
				res,
				{
					sessions: validSessions,
					count: validSessions.length,
					currentSession: agent.getCurrentSessionId?.() || null,
					processingTime,
				},
				200,
				req.requestId
			);
			return;
		} catch (error) {
			// CRITICAL FIX: Properly extract error message to prevent [object Object] display
			let errorMsg: string;
			try {
				errorMsg = error instanceof Error ? error.message : String(error);
			} catch {
				errorMsg = 'Unknown error occurred during session listing';
			}

			logger.error('Error listing sessions:', error);
			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				'Failed to list sessions',
				500,
				{ details: errorMsg, processingTime: Date.now() - startTime },
				req.requestId
			);
		}
	});

	/**
	 * POST /api/sessions
	 * Create a new session
	 */
	/**
	 * Validate and sanitize session ID to prevent problematic IDs
	 */
	function sanitizeSessionId(sessionId: string | undefined): string | null {
		if (!sessionId) return null; // Auto-generate

		// Remove problematic patterns and characters
		const sanitized = sessionId
			.trim()
			.replace(/[^\w-]/g, '-') // Replace non-alphanumeric with hyphens
			.replace(/^empty-?/i, '') // Remove "empty" prefix
			.replace(/^null-?/i, '') // Remove "null" prefix
			.replace(/^undefined-?/i, '') // Remove "undefined" prefix
			.replace(/^-+|-+$/g, '') // Remove leading/trailing hyphens
			.replace(/-+/g, '-') // Collapse multiple hyphens
			.substring(0, 64); // Limit length

		// If sanitization results in empty string, return null for auto-generation
		if (!sanitized || sanitized.length < 3) return null;

		return sanitized;
	}

	router.post('/', validateCreateSession, async (req: Request, res: Response) => {
		try {
			const { sessionId: rawSessionId } = req.body;
			const sessionId = sanitizeSessionId(rawSessionId);

			logger.info('Creating new session', {
				requestId: req.requestId,
				originalSessionId: rawSessionId,
				sessionId: sessionId || 'auto-generated',
			});

			const session = await agent.createSession(sessionId || undefined);

			successResponse(
				res,
				{
					session: {
						id: session.id,
						// Only include serializable session properties
						createdAt: new Date().toISOString(),
					},
					created: true,
					timestamp: new Date().toISOString(),
				},
				201,
				req.requestId
			);
		} catch (error) {
			// Safely extract error message to avoid circular reference issues
			let errorMsg: string;
			try {
				errorMsg = error instanceof Error ? error.message : String(error);
			} catch {
				errorMsg = 'Unknown error occurred during session creation';
			}

			logger.error('Failed to create session', {
				requestId: req.requestId,
				error: errorMsg,
			});

			// Check if error is due to duplicate session ID
			if (errorMsg.includes('already exists') || errorMsg.includes('duplicate')) {
				errorResponse(
					res,
					ERROR_CODES.BAD_REQUEST,
					`Session creation failed: ${errorMsg}`,
					400,
					undefined,
					req.requestId
				);
			} else {
				errorResponse(
					res,
					ERROR_CODES.INTERNAL_ERROR,
					`Failed to create session: ${errorMsg}`,
					500,
					undefined,
					req.requestId
				);
			}
		}
	});

	/**
	 * GET /api/sessions/current
	 * Get current working session
	 */
	router.get('/current', async (req: Request, res: Response) => {
		try {
			const currentSessionId = agent.getCurrentSessionId();
			const metadata = await agent.getSessionMetadata(currentSessionId);

			if (!metadata) {
				errorResponse(
					res,
					ERROR_CODES.SESSION_NOT_FOUND,
					'Current session not found',
					404,
					undefined,
					req.requestId
				);
				return;
			}

			successResponse(
				res,
				{
					sessionId: currentSessionId,
					metadata,
					isCurrent: true,
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to get current session', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to get current session: ${errorMsg}`,
				500,
				undefined,
				req.requestId
			);
		}
	});

	/**
	 * GET /api/sessions/:sessionId
	 * Get session details
	 */
	router.get('/:sessionId', validateSessionId, async (req: Request, res: Response) => {
		try {
			const { sessionId } = req.params;

			if (!sessionId) {
				errorResponse(
					res,
					ERROR_CODES.BAD_REQUEST,
					'Session ID is required',
					400,
					undefined,
					req.requestId
				);
				return;
			}

			logger.info('Getting session details', {
				requestId: req.requestId,
				sessionId,
			});

			const session = await agent.getSession(sessionId);
			if (!session) {
				errorResponse(
					res,
					ERROR_CODES.SESSION_NOT_FOUND,
					`Session ${sessionId} not found`,
					404,
					undefined,
					req.requestId
				);
				return;
			}

			const metadata = await agent.getSessionMetadata(sessionId);

			successResponse(
				res,
				{
					sessionId,
					metadata,
					isCurrent: sessionId === agent.getCurrentSessionId(),
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to get session details', {
				requestId: req.requestId,
				sessionId: req.params.sessionId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to get session details: ${errorMsg}`,
				500,
				undefined,
				req.requestId
			);
		}
	});

	/**
	 * POST /api/sessions/:sessionId/load
	 * Load session as current
	 */
	router.post('/:sessionId/load', validateSessionId, async (req: Request, res: Response) => {
		try {
			const { sessionId: rawSessionId } = req.params;

			// Validate and sanitize session ID
			const sessionId = sanitizeSessionId(rawSessionId);
			if (!sessionId) {
				logger.warn('Attempted to load session with invalid ID:', rawSessionId);
				errorResponse(
					res,
					ERROR_CODES.BAD_REQUEST,
					'Invalid session ID provided',
					400,
					undefined,
					req.requestId
				);
				return;
			}

			logger.info('Loading session', {
				requestId: req.requestId,
				sessionId,
			});

			// CRITICAL FIX: Handle non-existent sessions gracefully
			let session;
			try {
				session = await agent.loadSession(sessionId);
			} catch (loadError) {
				const errorMsg = loadError instanceof Error ? loadError.message : String(loadError);
				logger.warn(`Session ${sessionId} not found, creating new session:`, {
					originalSessionId: rawSessionId,
					sanitizedSessionId: sessionId,
					error: errorMsg,
					requestId: req.requestId,
				});

				// Create new session with the requested ID
				try {
					session = await agent.createSession(sessionId);
					logger.info(`Created new session: ${sessionId}`);
				} catch (createError) {
					const createErrorMsg =
						createError instanceof Error ? createError.message : String(createError);
					logger.error(`Failed to create session ${sessionId}:`, createErrorMsg);

					// If we can't create with the specific ID, create with auto-generated ID
					session = await agent.createSession();
					logger.info(`Created auto-generated session: ${session.id}`);
				}
			}

			// CRITICAL FIX: Ensure conversation history is available in the loaded session
			// This is essential for UI mode to display previous messages when switching sessions
			let conversationHistory: any[] = [];
			try {
				// Force refresh conversation history after loading
				if (session && typeof session.refreshConversationHistory === 'function') {
					await session.refreshConversationHistory();
					logger.debug(`Session ${sessionId}: Refreshed conversation history after loading`);
				}

				// Get the conversation history to return with the response
				if (session && typeof session.getConversationHistory === 'function') {
					conversationHistory = await session.getConversationHistory();
					logger.info(
						`Session ${sessionId}: Loaded with ${conversationHistory.length} messages in conversation history`
					);
				}
			} catch (historyError) {
				logger.warn(`Session ${sessionId}: Failed to refresh history after loading:`, historyError);
				// Continue even if history refresh fails
			}

			successResponse(
				res,
				{
					sessionId: session.id,
					loaded: true,
					currentSession: agent.getCurrentSessionId(),
					conversationHistory, // CRITICAL FIX: Return history with session load
					timestamp: new Date().toISOString(),
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to load session', {
				requestId: req.requestId,
				sessionId: req.params.sessionId,
				error: errorMsg,
			});

			if (errorMsg.includes('not found')) {
				errorResponse(
					res,
					ERROR_CODES.SESSION_NOT_FOUND,
					`Session ${req.params.sessionId} not found`,
					404,
					undefined,
					req.requestId
				);
			} else {
				errorResponse(
					res,
					ERROR_CODES.INTERNAL_ERROR,
					`Failed to load session: ${errorMsg}`,
					500,
					undefined,
					req.requestId
				);
			}
		}
	});

	/**
	 * GET /api/sessions/:sessionId/history
	 * Get session conversation history - OPTIMIZED with caching
	 */
	router.get('/:sessionId/history', validateSessionId, async (req: Request, res: Response) => {
		const startTime = Date.now();
		try {
			const { sessionId } = req.params;

			// Handle null or invalid session IDs
			if (!sessionId || sessionId === 'null' || sessionId === 'undefined') {
				logger.warn('Attempted to get history for session with invalid ID:', sessionId);
				errorResponse(
					res,
					ERROR_CODES.BAD_REQUEST,
					'Invalid session ID provided',
					400,
					undefined,
					req.requestId
				);
				return;
			}

			logger.info('Getting session history', {
				requestId: req.requestId,
				sessionId,
			});

			// PERFORMANCE OPTIMIZATION: Use optimized history retrieval with request deduplication
			const sessionManager = agent.sessionManager;
			const cacheKey = `history_${sessionId}`;

			// Check if there's already a pending request for this session's history
			if ((sessionManager as any).requestDeduplicator?.has(cacheKey)) {
				logger.debug(`Deduplicating concurrent history request for session ${sessionId}`);
				const history = await (sessionManager as any).requestDeduplicator.get(cacheKey);
				successResponse(
					res,
					{
						sessionId,
						history: history || [],
						count: (history || []).length,
						timestamp: new Date().toISOString(),
						processingTime: Date.now() - startTime,
						source: 'deduplication',
					},
					200,
					req.requestId
				);
				return;
			}

			let history = [];
			let historySource = 'none';

			// PERFORMANCE OPTIMIZATION: Parallel data retrieval
			const historyPromise = (async () => {
				// Try session manager first (fastest)
				try {
					const session = await agent.getSession(sessionId);
					if (session) {
						const sessionHistory = await agent.getSessionHistory(sessionId);
						if (sessionHistory && sessionHistory.length > 0) {
							return { history: sessionHistory, source: 'session-manager' };
						}
					}
				} catch {
					logger.debug(`Session ${sessionId} not found in session manager`);
				}

				// Try database storage (parallel queries for better performance)
				try {
					const storageManager = (sessionManager as any).storageManager;
					if (storageManager?.isConnected()) {
						const backends = storageManager.getBackends();
						if (backends?.database) {
							// Query both message and session keys in parallel
							const [messageHistory, sessionData] = await Promise.allSettled([
								backends.database.get(`messages:${sessionId}`),
								backends.database.get(`session:${sessionId}`),
							]);

							// Priority: messages key first
							if (
								messageHistory.status === 'fulfilled' &&
								messageHistory.value &&
								Array.isArray(messageHistory.value)
							) {
								return { history: messageHistory.value, source: 'database-messages' };
							}

							// Fallback: session conversation history
							if (
								sessionData.status === 'fulfilled' &&
								sessionData.value?.conversationHistory &&
								Array.isArray(sessionData.value.conversationHistory)
							) {
								return {
									history: sessionData.value.conversationHistory,
									source: 'database-session',
								};
							}
						}
					}
				} catch (error) {
					logger.warn(`Failed to get history from database for session ${sessionId}:`, error);
				}

				return { history: [], source: 'none' };
			})();

			// Store promise for request deduplication
			if ((sessionManager as any).requestDeduplicator) {
				(sessionManager as any).requestDeduplicator.set(
					cacheKey,
					historyPromise.then(result => result.history)
				);
			}

			try {
				const result = await historyPromise;
				history = result.history;
				historySource = result.source;
			} finally {
				// Clean up deduplication
				if ((sessionManager as any).requestDeduplicator) {
					(sessionManager as any).requestDeduplicator.delete(cacheKey);
				}
			}

			const processingTime = Date.now() - startTime;

			// Log the final result
			logger.info(
				`Session ${sessionId} history retrieval: ${history.length} messages from ${historySource} in ${processingTime}ms`
			);

			successResponse(
				res,
				{
					sessionId,
					history,
					count: history.length,
					timestamp: new Date().toISOString(),
					processingTime,
					source: historySource,
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			const processingTime = Date.now() - startTime;
			logger.error('Failed to get session history', {
				requestId: req.requestId,
				sessionId: req.params.sessionId,
				error: errorMsg,
				processingTime,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to get session history: ${errorMsg}`,
				500,
				{ processingTime },
				req.requestId
			);
		}
	});

	/**
	 * DELETE /api/sessions/:sessionId
	 * Delete session
	 */
	router.delete('/:sessionId', validateSessionId, async (req: Request, res: Response) => {
		try {
			const { sessionId } = req.params;

			// Handle null or invalid session IDs
			if (!sessionId || sessionId === 'null' || sessionId === 'undefined') {
				logger.warn('Attempted to delete session with invalid ID:', sessionId);
				errorResponse(
					res,
					ERROR_CODES.BAD_REQUEST,
					'Invalid session ID provided',
					400,
					undefined,
					req.requestId
				);
				return;
			}

			logger.info('Deleting session', {
				requestId: req.requestId,
				sessionId,
			});

			// CRITICAL FIX: Always return success for deletion to prevent frontend inconsistencies
			// The session manager will handle cleanup of non-existent sessions gracefully
			const success = await agent.removeSession(sessionId);

			// Always return success for deletions to prevent UI inconsistencies
			// Even if session wasn't found, it's effectively "deleted" from the user's perspective

			// CRITICAL FIX: Always return success to prevent UI inconsistencies
			// The frontend should show the session as deleted immediately
			successResponse(
				res,
				{
					sessionId,
					deleted: true,
					successful: success,
					timestamp: new Date().toISOString(),
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to delete session', {
				requestId: req.requestId,
				sessionId: req.params.sessionId,
				error: errorMsg,
			});

			if (errorMsg.includes('Cannot remove the currently active session')) {
				errorResponse(
					res,
					ERROR_CODES.BAD_REQUEST,
					'Cannot delete the currently active session. Switch to another session first.',
					400,
					undefined,
					req.requestId
				);
			} else {
				errorResponse(
					res,
					ERROR_CODES.INTERNAL_ERROR,
					`Failed to delete session: ${errorMsg}`,
					500,
					undefined,
					req.requestId
				);
			}
		}
	});

	/**
	 * GET /api/sessions/stats
	 * Get session performance statistics - MONITORING ENDPOINT
	 */
	router.get('/stats', async (req: Request, res: Response) => {
		try {
			logger.info('Getting session performance stats', { requestId: req.requestId });

			const sessionManager = agent.sessionManager;
			const stats = await sessionManager.getSessionStats();

			// Add additional runtime metrics
			const runtimeStats = {
				uptime: process.uptime(),
				memoryUsage: process.memoryUsage(),
				timestamp: new Date().toISOString(),
				requestId: req.requestId,
			};

			successResponse(
				res,
				{
					sessionStats: stats,
					runtimeStats,
					optimizationStatus: {
						cachingEnabled: true,
						batchProcessingEnabled: true,
						requestDeduplicationEnabled: true,
						performanceMonitoringEnabled: true,
					},
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to get session stats', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to get session stats: ${errorMsg}`,
				500,
				undefined,
				req.requestId
			);
		}
	});

	return router;
}

import { Router, Request, Response } from 'express';
import { MemAgent } from '@core/brain/memAgent/index.js';
import { successResponse, errorResponse, ERROR_CODES } from '../utils/response.js';
import { logger } from '@core/logger/index.js';
import { randomUUID } from 'crypto';

// Simple in-memory webhook storage (in production, this should be persistent)
interface WebhookData {
	id: string;
	url: string;
	events: string[];
	active: boolean;
	createdAt: string;
	lastTriggered?: string;
}

const webhooks = new Map<string, WebhookData>();

export function createWebhookRoutes(_agent: MemAgent): Router {
	const router = Router();

	/**
	 * POST /api/webhooks
	 * Register webhook endpoint
	 */
	router.post('/', async (req: Request, res: Response) => {
		try {
			const { url, events = ['*'] } = req.body;

			if (!url || typeof url !== 'string') {
				return errorResponse(
					res,
					ERROR_CODES.VALIDATION_ERROR,
					'URL parameter is required',
					400,
					undefined,
					req.requestId
				);
			}

			// Validate URL format
			try {
				new URL(url);
			} catch {
				return errorResponse(
					res,
					ERROR_CODES.VALIDATION_ERROR,
					'Invalid URL format',
					400,
					undefined,
					req.requestId
				);
			}

			// Generate unique webhook ID
			const webhookId = randomUUID();

			const webhookData: WebhookData = {
				id: webhookId,
				url,
				events: Array.isArray(events) ? events : ['*'],
				active: true,
				createdAt: new Date().toISOString(),
			};

			webhooks.set(webhookId, webhookData);

			logger.info('Webhook registered', {
				requestId: req.requestId,
				webhookId,
				url,
				events: webhookData.events,
			});

			successResponse(
				res,
				{
					webhook: webhookData,
					message: 'Webhook registered successfully',
				},
				201,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Webhook registration failed', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Webhook registration failed: ${errorMsg}`,
				500,
				process.env.NODE_ENV === 'development' ? error : undefined,
				req.requestId
			);
		}
	});

	/**
	 * GET /api/webhooks
	 * List registered webhooks
	 */
	router.get('/', async (req: Request, res: Response) => {
		try {
			const webhookList = Array.from(webhooks.values());

			logger.info('Listing webhooks', {
				requestId: req.requestId,
				count: webhookList.length,
			});

			successResponse(
				res,
				{
					webhooks: webhookList,
					total: webhookList.length,
					timestamp: new Date().toISOString(),
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to list webhooks', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to list webhooks: ${errorMsg}`,
				500,
				process.env.NODE_ENV === 'development' ? error : undefined,
				req.requestId
			);
		}
	});

	/**
	 * GET /api/webhooks/:webhookId
	 * Get specific webhook details
	 */
	router.get('/:webhookId', async (req: Request, res: Response) => {
		try {
			const { webhookId } = req.params;

			if (!webhookId) {
				return errorResponse(
					res,
					ERROR_CODES.VALIDATION_ERROR,
					'Webhook ID is required',
					400,
					undefined,
					req.requestId
				);
			}

			const webhook = webhooks.get(webhookId);
			if (!webhook) {
				return errorResponse(
					res,
					ERROR_CODES.NOT_FOUND,
					`Webhook ${webhookId} not found`,
					404,
					undefined,
					req.requestId
				);
			}

			logger.info('Retrieved webhook details', {
				requestId: req.requestId,
				webhookId,
			});

			successResponse(
				res,
				{
					webhook,
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to get webhook details', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to get webhook details: ${errorMsg}`,
				500,
				process.env.NODE_ENV === 'development' ? error : undefined,
				req.requestId
			);
		}
	});

	/**
	 * DELETE /api/webhooks/:webhookId
	 * Remove webhook
	 */
	router.delete('/:webhookId', async (req: Request, res: Response) => {
		try {
			const { webhookId } = req.params;

			if (!webhookId) {
				return errorResponse(
					res,
					ERROR_CODES.VALIDATION_ERROR,
					'Webhook ID is required',
					400,
					undefined,
					req.requestId
				);
			}

			const webhook = webhooks.get(webhookId);
			if (!webhook) {
				return errorResponse(
					res,
					ERROR_CODES.NOT_FOUND,
					`Webhook ${webhookId} not found`,
					404,
					undefined,
					req.requestId
				);
			}

			webhooks.delete(webhookId);

			logger.info('Webhook removed', {
				requestId: req.requestId,
				webhookId,
			});

			successResponse(
				res,
				{
					message: `Webhook ${webhookId} removed successfully`,
					webhookId,
				},
				200,
				req.requestId
			);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to remove webhook', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to remove webhook: ${errorMsg}`,
				500,
				process.env.NODE_ENV === 'development' ? error : undefined,
				req.requestId
			);
		}
	});

	/**
	 * POST /api/webhooks/:webhookId/test
	 * Test webhook endpoint
	 */
	router.post('/:webhookId/test', async (req: Request, res: Response) => {
		try {
			const { webhookId } = req.params;

			if (!webhookId) {
				return errorResponse(
					res,
					ERROR_CODES.VALIDATION_ERROR,
					'Webhook ID is required',
					400,
					undefined,
					req.requestId
				);
			}

			const webhook = webhooks.get(webhookId);
			if (!webhook) {
				return errorResponse(
					res,
					ERROR_CODES.NOT_FOUND,
					`Webhook ${webhookId} not found`,
					404,
					undefined,
					req.requestId
				);
			}

			// Perform test HTTP request to webhook URL
			const testPayload = {
				event: 'webhook_test',
				data: {
					message: 'This is a test webhook call from Cipher',
					timestamp: new Date().toISOString(),
					webhookId,
				},
				source: 'cipher-agent',
			};

			try {
				const response = await fetch(webhook.url, {
					method: 'POST',
					headers: {
						'Content-Type': 'application/json',
						'User-Agent': 'Cipher-Agent-Webhook/1.0',
					},
					body: JSON.stringify(testPayload),
				});

				// Update last triggered time
				webhook.lastTriggered = new Date().toISOString();
				webhooks.set(webhookId, webhook);

				logger.info('Webhook test completed', {
					requestId: req.requestId,
					webhookId,
					status: response.status,
					ok: response.ok,
				});

				successResponse(
					res,
					{
						message: 'Webhook test completed',
						webhookId,
						testResult: {
							status: response.status,
							ok: response.ok,
							url: webhook.url,
							timestamp: new Date().toISOString(),
						},
					},
					200,
					req.requestId
				);
			} catch (fetchError) {
				logger.error('Webhook test failed', {
					requestId: req.requestId,
					webhookId,
					error: fetchError instanceof Error ? fetchError.message : String(fetchError),
				});

				successResponse(
					res,
					{
						message: 'Webhook test completed with error',
						webhookId,
						testResult: {
							status: 0,
							ok: false,
							error: fetchError instanceof Error ? fetchError.message : String(fetchError),
							url: webhook.url,
							timestamp: new Date().toISOString(),
						},
					},
					200, // Still return 200 as the test was executed
					req.requestId
				);
			}
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			logger.error('Failed to test webhook', {
				requestId: req.requestId,
				error: errorMsg,
			});

			errorResponse(
				res,
				ERROR_CODES.INTERNAL_ERROR,
				`Failed to test webhook: ${errorMsg}`,
				500,
				process.env.NODE_ENV === 'development' ? error : undefined,
				req.requestId
			);
		}
	});

	return router;
}

import express, { Application, Request, Response, NextFunction } from 'express';
import cors from 'cors';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import http from 'http';
import { WebSocketServer, WebSocket } from 'ws';
import { MemAgent } from '@core/brain/memAgent/index.js';
import { logger } from '@core/logger/index.js';
import { errorResponse, successResponse, ERROR_CODES } from './utils/response.js';
import {
	requestIdMiddleware,
	requestLoggingMiddleware,
	errorLoggingMiddleware,
} from './middleware/logging.js';
import { Server as McpServer } from '@modelcontextprotocol/sdk/server/index.js';
import { SSEServerTransport } from '@modelcontextprotocol/sdk/server/sse.js';
import { initializeMcpServer, initializeAgentCardResource } from '@app/mcp/mcp_handler.js';

// Import WebSocket components
import { WebSocketConnectionManager } from './websocket/connection-manager.js';
import { WebSocketMessageRouter } from './websocket/message-router.js';
import { WebSocketEventSubscriber } from './websocket/event-subscriber.js';
import { WebSocketMessage, WebSocketConfig } from './websocket/types.js';

// Import route handlers
import { createMessageRoutes } from './routes/message.js';
import { createSessionRoutes } from './routes/session.js';
import { createMcpRoutes } from './routes/mcp.js';
import { createConfigRoutes } from './routes/config.js';
import { createLlmRoutes } from './routes/llm.js';
import { createSearchRoutes } from './routes/search.js';
import { createWebhookRoutes } from './routes/webhook.js';

export interface ApiServerConfig {
	port: number;
	host?: string;
	corsOrigins?: string[];
	rateLimitWindowMs?: number;
	rateLimitMaxRequests?: number;
	mcpTransportType?: 'stdio' | 'sse' | 'http';
	mcpPort?: number;
	// WebSocket configuration
	enableWebSocket?: boolean;
	webSocketConfig?: WebSocketConfig;
	// API prefix configuration
	apiPrefix?: string;
}

export class ApiServer {
	private app: Application;
	private agent: MemAgent;
	private config: ApiServerConfig;
	private apiPrefix: string;
	private mcpServer?: McpServer;
	private activeMcpSseTransports: Map<string, SSEServerTransport> = new Map();

	// WebSocket components
	private httpServer?: http.Server;
	private wss?: WebSocketServer;
	private wsConnectionManager?: WebSocketConnectionManager;
	private wsMessageRouter?: WebSocketMessageRouter;
	private wsEventSubscriber?: WebSocketEventSubscriber;
	private heartbeatInterval?: NodeJS.Timeout;

	constructor(agent: MemAgent, config: ApiServerConfig) {
		this.agent = agent;
		this.config = config;

		// Validate and set API prefix
		this.apiPrefix = this.validateAndNormalizeApiPrefix(config.apiPrefix);

		this.app = express();
		this.setupMiddleware();
		this.setupRoutes();
		this.setupErrorHandling();

		// Note: MCP setup is now handled in start() method to properly handle async operations
	}

	/**
	 * Validate and normalize API prefix configuration
	 */
	private validateAndNormalizeApiPrefix(prefix?: string): string {
		// Default to '/api' for backward compatibility
		if (prefix === undefined) {
			return '/api';
		}

		// Allow empty string to disable prefix
		if (prefix === '') {
			return '';
		}

		// Validate prefix format
		if (typeof prefix !== 'string') {
			throw new Error('API prefix must be a string');
		}

		// Ensure prefix starts with '/' if not empty
		if (!prefix.startsWith('/')) {
			prefix = '/' + prefix;
		}

		// Remove trailing slash to normalize
		if (prefix.endsWith('/') && prefix !== '/') {
			prefix = prefix.slice(0, -1);
		}

		logger.info(`[API Server] Using API prefix: '${prefix || '(none)'}'`);
		return prefix;
	}

	/**
	 * Helper method to construct API route paths
	 */
	private buildApiRoute(route: string): string {
		if (!this.apiPrefix || this.apiPrefix === '') {
			return route;
		}
		return `${this.apiPrefix}${route}`;
	}

	private async setupMcpServer(
		transportType: 'stdio' | 'sse' | 'http',
		_port?: number
	): Promise<void> {
		logger.info(`[API Server] Setting up MCP server with transport type: ${transportType}`);
		try {
			// Initialize agent card data
			const agentCard = this.agent.getEffectiveConfig().agentCard;
			const agentCardInput = agentCard
				? Object.fromEntries(Object.entries(agentCard).filter(([, value]) => value !== undefined))
				: {};
			const agentCardData = initializeAgentCardResource(agentCardInput);

			// Check MCP_SERVER_MODE environment variable to determine server type
			const mcpServerMode = process.env.MCP_SERVER_MODE || 'default';
			logger.info(`[API Server] MCP server mode: ${mcpServerMode}`);

			// Load aggregator configuration if needed
			let aggregatorConfig: any = undefined;
			if (mcpServerMode === 'aggregator') {
				aggregatorConfig = await this.loadAggregatorConfig();
			}

			// Initialize MCP server instance with appropriate mode
			this.mcpServer = await initializeMcpServer(
				this.agent,
				agentCardData,
				mcpServerMode as 'default' | 'aggregator',
				aggregatorConfig
			);

			if (transportType === 'sse') {
				this.setupMcpSseRoutes(); // Renamed for clarity as it sets up both GET and POST
			} else if (transportType === 'stdio') {
				// For stdio, we need to explicitly connect the server to a StdioServerTransport
				// This usually means the process runs as a standalone MCP server, not integrated into Express
				// This case is typically handled by the CLI directly, not via ApiServer
				logger.warn(
					`[API Server] MCP transport type 'stdio' is typically handled by the CLI directly and not integrated into the API server.`
				);
				// If a StdioServerTransport needs to be managed by ApiServer, its lifecycle would be handled here.
				// For now, we assume 'stdio' mode implies a different execution path.
			} else {
				logger.warn(
					`[API Server] MCP transport type '${transportType}' not fully implemented for API server integration yet.`
				);
			}
		} catch (error) {
			logger.error(
				`[API Server] Failed to set up MCP server: ${error instanceof Error ? error.message : String(error)}`
			);
		}
	}

	/**
	 * Load aggregator configuration from environment variables
	 * Aggregator mode now uses agent's unifiedToolManager which automatically includes MCP servers from cipher.yml
	 */
	private async loadAggregatorConfig(): Promise<any> {
		const defaultConfig = {
			type: 'aggregator' as const,
			servers: {}, // No longer needed - using unifiedToolManager
			conflictResolution: (process.env.AGGREGATOR_CONFLICT_RESOLUTION as any) || 'prefix',
			autoDiscovery: false,
			timeout: parseInt(process.env.AGGREGATOR_TIMEOUT || '60000'),
			connectionMode: 'lenient' as const,
		};

		logger.info('[API Server] Using aggregator configuration with env vars', {
			conflictResolution: defaultConfig.conflictResolution,
			timeout: defaultConfig.timeout,
		});
		return defaultConfig;
	}

	private setupMcpSseRoutes(): void {
		if (!this.mcpServer) {
			logger.error('[API Server] MCP Server not initialized for SSE route setup.');
			return;
		}

		// Handle SSE GET endpoint (for client to establish SSE connection)
		this.app.get(this.buildApiRoute('/mcp/sse'), (req: Request, res: Response) => {
			logger.info('[API Server] New MCP SSE client attempting connection.');
			logger.debug('[API Server] SSE Request Headers:', req.headers);
			logger.debug('[API Server] SSE Request URL:', req.url);

			// Create SSE transport instance. The buildApiRoute('/mcp') is the endpoint where client will POST messages.
			// The SSEServerTransport will handle setting the SSE headers itself
			const sseTransport = new SSEServerTransport(this.buildApiRoute('/mcp'), res);
			logger.debug(
				`[API Server] SSEServerTransport created with endpoint ${this.buildApiRoute('/mcp')}`
			);

			// Connect MCP server to this SSE transport (this will call sseTransport.start() and set headers)
			this.mcpServer?.connect(sseTransport);
			logger.debug('[API Server] MCP server connected to SSE transport');

			// Store the transport keyed by its session ID
			this.activeMcpSseTransports.set(sseTransport.sessionId, sseTransport);
			logger.info(
				`[API Server] MCP SSE client connected with session ID: ${sseTransport.sessionId}`
			);
			logger.debug(`[API Server] Active SSE transports count: ${this.activeMcpSseTransports.size}`);

			// Handle client disconnect
			req.on('close', () => {
				logger.info(
					`[API Server] MCP SSE client with session ID ${sseTransport.sessionId} disconnected.`
				);
				logger.debug('[API Server] Cleaning up SSE transport and connection');
				sseTransport.close(); // Close the transport when client disconnects
				this.activeMcpSseTransports.delete(sseTransport.sessionId); // Remove from active transports
				logger.debug(
					`[API Server] Active SSE transports count after cleanup: ${this.activeMcpSseTransports.size}`
				);
			});
		});

		// Handle POST requests for MCP messages over HTTP (part of Streamable HTTP)
		this.app.post(this.buildApiRoute('/mcp'), async (req: Request, res: Response) => {
			logger.debug('[API Server] MCP POST request received');
			logger.debug('[API Server] POST Request Headers:', req.headers);
			logger.debug('[API Server] POST Request Body:', req.body);
			logger.debug('[API Server] POST Request Query:', req.query);

			if (!this.mcpServer) {
				logger.error('[API Server] MCP Server not initialized for POST route.');
				return errorResponse(res, ERROR_CODES.INTERNAL_ERROR, 'MCP Server not ready', 500);
			}

			// The SSEServerTransport expects the session ID to be part of the endpoint it provides,
			// typically as a query parameter in the POST URL (e.g., /mcp?sessionId=...).
			// We need to retrieve the correct transport instance based on this.
			const sessionId = req.query.sessionId as string;

			if (!sessionId) {
				logger.error('[API Server] MCP POST request received without session ID.');
				logger.debug('[API Server] Available query parameters:', Object.keys(req.query));
				return errorResponse(
					res,
					ERROR_CODES.BAD_REQUEST,
					'Missing sessionId in query parameters',
					400
				);
			}

			logger.debug(`[API Server] Looking for SSE transport with session ID: ${sessionId}`);
			logger.debug(
				`[API Server] Available session IDs: ${Array.from(this.activeMcpSseTransports.keys()).join(', ')}`
			);

			const sseTransport = this.activeMcpSseTransports.get(sessionId);

			if (!sseTransport) {
				logger.error(`[API Server] No active MCP SSE transport found for session ID: ${sessionId}`);
				return errorResponse(
					res,
					ERROR_CODES.NOT_FOUND,
					`No active session found for ID: ${sessionId}`,
					404
				);
			}

			try {
				logger.debug(
					`[API Server] Delegating POST message to SSE transport for session: ${sessionId}`
				);
				// Delegate handling of the POST message to the specific SSEServerTransport instance
				// Pass req.body as the third parameter since Express has already parsed it
				await sseTransport.handlePostMessage(req, res, req.body);
				logger.debug(`[API Server] POST message handled successfully for session: ${sessionId}`);
			} catch (error) {
				logger.error(
					`[API Server] Error handling MCP POST request for session ${sessionId}: ${error instanceof Error ? error.message : String(error)}`
				);
				logger.debug(
					`[API Server] POST error stack:`,
					error instanceof Error ? error.stack : 'No stack available'
				);
				errorResponse(
					res,
					ERROR_CODES.INTERNAL_ERROR,
					'Error processing MCP request',
					500,
					error instanceof Error ? error.stack : undefined
				);
			}
		});

		const mcpSseRoute = this.buildApiRoute('/mcp/sse');
		const mcpPostRoute = this.buildApiRoute('/mcp');
		logger.info(
			`[API Server] MCP SSE (GET ${mcpSseRoute}) and POST (${mcpPostRoute}?sessionId=...) routes registered.`
		);
	}

	/**
	 * Set up WebSocket server and event handling
	 */
	private setupWebSocket(): void {
		if (!this.config.enableWebSocket || !this.httpServer) {
			logger.debug('[API Server] WebSocket disabled or HTTP server not available');
			return;
		}

		const wsConfig = this.config.webSocketConfig || {};

		// Create WebSocket server
		this.wss = new WebSocketServer({
			server: this.httpServer,
			path: wsConfig.path || '/ws',
			...(wsConfig.maxConnections && { maxClients: wsConfig.maxConnections }),
			...(wsConfig.enableCompression !== undefined && {
				perMessageDeflate: wsConfig.enableCompression,
			}),
		});

		// Initialize WebSocket components
		this.wsConnectionManager = new WebSocketConnectionManager(
			wsConfig.maxConnections || 1000,
			wsConfig.connectionTimeout || 300000
		);

		this.wsMessageRouter = new WebSocketMessageRouter(this.agent, this.wsConnectionManager);

		this.wsEventSubscriber = new WebSocketEventSubscriber(
			this.wsConnectionManager,
			this.agent.services.eventManager
		);

		// Wire up the connection manager to notify the event subscriber
		this.wsConnectionManager.setEventSubscriber(this.wsEventSubscriber);

		// Set up WebSocket connection handler
		this.wss.on('connection', (ws: WebSocket, request) => {
			this.handleWebSocketConnection(ws, request);
		});

		// Start event subscription
		this.wsEventSubscriber.subscribe();

		// Set up heartbeat if configured
		if (wsConfig.heartbeatInterval && wsConfig.heartbeatInterval > 0) {
			this.heartbeatInterval = setInterval(() => {
				this.wsConnectionManager?.sendHeartbeat();
			}, wsConfig.heartbeatInterval);
		}

		// Set up graceful shutdown handling
		process.on('SIGTERM', () => {
			this.shutdownWebSocket();
		});

		process.on('SIGINT', () => {
			this.shutdownWebSocket();
		});

		logger.info('[API Server] WebSocket server initialized', {
			path: wsConfig.path || '/ws',
			maxConnections: wsConfig.maxConnections || 1000,
			compression: wsConfig.enableCompression !== false,
			heartbeat: wsConfig.heartbeatInterval || 'disabled',
		});
	}

	/**
	 * Handle new WebSocket connection
	 */
	private handleWebSocketConnection(ws: WebSocket, request: http.IncomingMessage): void {
		try {
			// Extract session ID from query parameters if provided
			const url = new URL(request.url || '', `http://${request.headers.host}`);
			const sessionId = url.searchParams.get('sessionId') || undefined;

			// Add connection to manager
			const connectionId = this.wsConnectionManager!.addConnection(ws, sessionId);

			logger.info('[API Server] New WebSocket connection established', {
				connectionId,
				sessionId,
				origin: request.headers.origin,
				userAgent: request.headers['user-agent'],
			});

			// Set up message handler
			ws.on('message', async (data: Buffer) => {
				try {
					const message = JSON.parse(data.toString()) as WebSocketMessage;
					await this.wsMessageRouter!.routeMessage(ws, connectionId, message);
				} catch (error) {
					logger.error('[API Server] Error parsing WebSocket message', {
						connectionId,
						error: error instanceof Error ? error.message : String(error),
						rawData: data.toString().substring(0, 200), // Log first 200 chars
					});

					// Send error response
					if (ws.readyState === WebSocket.OPEN) {
						ws.send(
							JSON.stringify({
								event: 'error',
								error: 'Invalid message format',
								data: {
									message: 'Failed to parse JSON message',
									code: 'INVALID_JSON',
								},
								timestamp: Date.now(),
							})
						);
					}
				}
			});

			// Send welcome message
			if (ws.readyState === WebSocket.OPEN) {
				ws.send(
					JSON.stringify({
						event: 'connected',
						data: {
							connectionId,
							sessionId,
							serverVersion: process.env.npm_package_version || 'unknown',
							capabilities: ['streaming', 'tools', 'memory', 'reset'],
						},
						timestamp: Date.now(),
					})
				);
			}
		} catch (error) {
			logger.error('[API Server] Error handling WebSocket connection', {
				error: error instanceof Error ? error.message : String(error),
				origin: request.headers.origin,
			});

			if (ws.readyState === WebSocket.OPEN) {
				ws.close(1011, 'Server error during connection setup');
			}
		}
	}

	/**
	 * Shutdown WebSocket server gracefully
	 */
	private shutdownWebSocket(): void {
		if (this.heartbeatInterval) {
			clearInterval(this.heartbeatInterval);
		}

		if (this.wsEventSubscriber) {
			this.wsEventSubscriber.dispose();
		}

		if (this.wsConnectionManager) {
			this.wsConnectionManager.dispose();
		}

		if (this.wss) {
			this.wss.close(() => {
				logger.info('[API Server] WebSocket server closed');
			});
		}
	}

	private setupMiddleware(): void {
		// Security middleware
		this.app.use(
			helmet({
				contentSecurityPolicy: false, // Disable CSP for API
				crossOriginEmbedderPolicy: false,
			})
		);

		// CORS configuration
		this.app.use(
			cors({
				origin: this.config.corsOrigins || ['http://localhost:3000'],
				methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
				allowedHeaders: ['Content-Type', 'Authorization', 'X-Request-ID'],
				credentials: true,
			})
		);

		// Rate limiting
		const limiter = rateLimit({
			windowMs: this.config.rateLimitWindowMs || 15 * 60 * 1000, // 15 minutes
			max: this.config.rateLimitMaxRequests || 100, // limit each IP to 100 requests per windowMs
			message: {
				success: false,
				error: {
					code: ERROR_CODES.RATE_LIMIT_EXCEEDED,
					message: 'Too many requests from this IP, please try again later.',
				},
			},
			standardHeaders: true,
			legacyHeaders: false,
		});
		// Apply rate limiting to API routes if prefix is configured
		if (this.apiPrefix) {
			this.app.use(`${this.apiPrefix}/`, limiter);
		}

		// Body parsing middleware
		this.app.use(express.json({ limit: '10mb' })); // Support for image data
		this.app.use(express.urlencoded({ extended: true }));

		// Custom middleware
		this.app.use(requestIdMiddleware);
		this.app.use(requestLoggingMiddleware);
	}

	private setupRoutes(): void {
		// Health check endpoint
		this.app.get('/health', (_req: Request, res: Response) => {
			const healthData: any = {
				status: 'healthy',
				timestamp: new Date().toISOString(),
				uptime: process.uptime(),
				version: process.env.npm_package_version || 'unknown',
			};

			// Add WebSocket health if enabled
			if (this.config.enableWebSocket) {
				healthData.websocket = {
					enabled: true,
					active: this.isWebSocketActive(),
					stats: this.getWebSocketStats(),
				};
			}

			res.json(healthData);
		});

		// WebSocket stats endpoint
		this.app.get('/ws/stats', (_req: Request, res: Response) => {
			if (!this.config.enableWebSocket) {
				return res.status(404).json({
					success: false,
					error: {
						code: 'WEBSOCKET_DISABLED',
						message: 'WebSocket is not enabled',
					},
				});
			}

			const stats = this.getWebSocketStats();
			return res.json({
				success: true,
				data: {
					enabled: true,
					active: this.isWebSocketActive(),
					...stats,
				},
			});
		});

		// API routes
		this.app.use(this.buildApiRoute('/message'), createMessageRoutes(this.agent));
		this.app.use(this.buildApiRoute('/sessions'), createSessionRoutes(this.agent));
		this.app.use(this.buildApiRoute('/mcp'), createMcpRoutes(this.agent));
		this.app.use(this.buildApiRoute('/llm'), createLlmRoutes(this.agent));
		this.app.use(this.buildApiRoute('/config'), createConfigRoutes(this.agent));
		this.app.use(this.buildApiRoute('/search'), createSearchRoutes(this.agent));
		this.app.use(this.buildApiRoute('/webhooks'), createWebhookRoutes(this.agent));

		// Legacy endpoint for MCP server connection
		this.app.post(this.buildApiRoute('/connect-server'), (req: Request, res: Response) => {
			// Forward to MCP routes
			req.url = '/servers';
			createMcpRoutes(this.agent)(req, res, () => {});
		});

		// Chrome DevTools compatibility endpoint (prevents 404 errors in console)
		this.app.get(
			'/.well-known/appspecific/com.chrome.devtools.json',
			(req: Request, res: Response) => {
				res.status(204).end(); // No Content - indicates no DevTools integration available
			}
		);

		// A2A (Agent-to-Agent) discovery endpoint
		this.app.get('/.well-known/agent.json', (req: Request, res: Response) => {
			try {
				const agentCard = {
					name: 'Cipher Agent',
					description: 'Memory-powered AI agent framework with real-time communication',
					version: process.env.npm_package_version || '1.0.0',
					capabilities: ['conversation', 'memory', 'tools', 'mcp', 'websocket', 'streaming'],
					endpoints: {
						base: `${req.protocol}://${req.get('host')}`,
						api: `${req.protocol}://${req.get('host')}${this.apiPrefix || ''}`,
						websocket: `ws://${req.get('host')}/ws`,
						health: `${req.protocol}://${req.get('host')}/health`,
					},
					contact: {
						support: 'https://github.com/byterover/cipher',
					},
					protocols: ['http', 'websocket', 'mcp'],
					timestamp: new Date().toISOString(),
				};

				res.json(agentCard);
			} catch (error) {
				logger.error('Failed to generate agent card', {
					requestId: req.requestId,
					error: error instanceof Error ? error.message : String(error),
				});

				errorResponse(
					res,
					ERROR_CODES.INTERNAL_ERROR,
					'Failed to generate agent discovery data',
					500,
					undefined,
					req.requestId
				);
			}
		});

		// Global reset endpoint
		this.app.post(this.buildApiRoute('/reset'), async (req: Request, res: Response) => {
			try {
				const { sessionId } = req.body;

				logger.info('Processing global reset request', {
					requestId: req.requestId,
					sessionId: sessionId || 'all',
				});

				if (sessionId) {
					// Reset specific session
					const success = await this.agent.removeSession(sessionId);
					if (!success) {
						return errorResponse(
							res,
							ERROR_CODES.SESSION_NOT_FOUND,
							`Session ${sessionId} not found`,
							404,
							undefined,
							req.requestId
						);
					}
				} else {
					// Reset all sessions
					const sessionIds = await this.agent.listSessions();
					for (const id of sessionIds) {
						await this.agent.removeSession(id);
					}
				}

				successResponse(
					res,
					{
						message: sessionId ? `Session ${sessionId} reset` : 'All sessions reset',
						timestamp: new Date().toISOString(),
					},
					200,
					req.requestId
				);
			} catch (error) {
				const errorMsg = error instanceof Error ? error.message : String(error);
				logger.error('Global reset failed', {
					requestId: req.requestId,
					error: errorMsg,
				});

				errorResponse(
					res,
					ERROR_CODES.INTERNAL_ERROR,
					`Reset failed: ${errorMsg}`,
					500,
					process.env.NODE_ENV === 'development' ? error : undefined,
					req.requestId
				);
			}
		});
		// Note: 404 handler moved to setup404Handler() and called after MCP routes setup
	}

	private setup404Handler(): void {
		// 404 handler for unknown routes - must be registered AFTER all other routes
		this.app.use((req: Request, res: Response) => {
			errorResponse(
				res,
				ERROR_CODES.NOT_FOUND,
				`Route ${req.method} ${req.originalUrl} not found`,
				404,
				undefined,
				req.requestId
			);
		});
	}

	private setupErrorHandling(): void {
		// Error logging middleware
		this.app.use(errorLoggingMiddleware);

		// Global error handler
		this.app.use((err: Error, req: Request, res: Response, next: NextFunction) => {
			// If response already sent, delegate to default Express error handler
			if (res.headersSent) {
				return next(err);
			}

			// Determine error type and status code
			let statusCode = 500;
			let errorCode: string = ERROR_CODES.INTERNAL_ERROR;

			if (err.name === 'ValidationError') {
				statusCode = 400;
				errorCode = ERROR_CODES.VALIDATION_ERROR;
			} else if (err.name === 'UnauthorizedError') {
				statusCode = 401;
				errorCode = ERROR_CODES.UNAUTHORIZED;
			}

			errorResponse(
				res,
				errorCode,
				err.message || 'An unexpected error occurred',
				statusCode,
				process.env.NODE_ENV === 'development' ? err.stack : undefined,
				req.requestId
			);
		});
	}

	public async start(): Promise<void> {
		// Set up MCP server BEFORE starting HTTP server if transport type is provided
		if (this.config.mcpTransportType) {
			try {
				await this.setupMcpServer(this.config.mcpTransportType, this.config.mcpPort);
				logger.info(`[API Server] MCP server setup completed successfully`);
			} catch (error) {
				logger.error(
					`[API Server] Failed to setup MCP server: ${error instanceof Error ? error.message : String(error)}`
				);
				throw error;
			}
		}

		// Set up 404 handler AFTER all routes (including MCP) are registered
		this.setup404Handler();

		return new Promise((resolve, reject) => {
			try {
				// Create HTTP server from Express app
				this.httpServer = http.createServer(this.app);

				// Set up WebSocket server if enabled
				if (this.config.enableWebSocket) {
					this.setupWebSocket();
				}

				this.httpServer.listen(this.config.port, this.config.host || 'localhost', () => {
					logger.info(
						`API Server started on ${this.config.host || 'localhost'}:${this.config.port}`,
						null,
						'green'
					);
					if (this.config.mcpTransportType) {
						const mcpSseEndpoint = this.buildApiRoute('/mcp/sse');
						const mcpEndpoint = this.buildApiRoute('/mcp');
						logger.info(
							`[API Server] MCP SSE endpoints available at ${mcpSseEndpoint} and ${mcpEndpoint}`,
							null,
							'green'
						);
					}
					if (this.config.enableWebSocket) {
						const wsPath = this.config.webSocketConfig?.path || '/ws';
						logger.info(
							`[API Server] WebSocket server available at ws://${this.config.host || 'localhost'}:${this.config.port}${wsPath}`,
							null,
							'green'
						);
					}
					resolve();
				});

				this.httpServer.on('error', err => {
					const errorMessage = err.message || err.toString() || 'Unknown error';
					logger.error('Failed to start API server:', errorMessage);
					logger.error('Error details:', err);
					reject(err);
				});

				// Graceful shutdown
				process.on('SIGTERM', () => {
					logger.info('SIGTERM received, shutting down API server gracefully');
					this.shutdownWebSocket();
					this.httpServer?.close(() => {
						logger.info('API server stopped');
						process.exit(0);
					});
				});

				process.on('SIGINT', () => {
					logger.info('SIGINT received, shutting down API server gracefully');
					this.shutdownWebSocket();
					this.httpServer?.close(() => {
						logger.info('API server stopped');
						process.exit(0);
					});
				});
			} catch (error) {
				reject(error);
			}
		});
	}

	public getApp(): Application {
		return this.app;
	}

	/**
	 * Get WebSocket statistics
	 */
	public getWebSocketStats(): any {
		if (!this.wsConnectionManager || !this.wsEventSubscriber) {
			return null;
		}

		return {
			connections: this.wsConnectionManager.getStats(),
			events: this.wsEventSubscriber.getStats(),
			router: this.wsMessageRouter?.getStats(),
		};
	}

	/**
	 * Send system message to all WebSocket connections
	 */
	public broadcastSystemMessage(
		message: string,
		level: 'info' | 'warning' | 'error' = 'info'
	): void {
		if (this.wsEventSubscriber) {
			this.wsEventSubscriber.sendSystemMessage(message, level);
		}
	}

	/**
	 * Check if WebSocket is enabled and active
	 */
	public isWebSocketActive(): boolean {
		return !!(this.config.enableWebSocket && this.wss && this.wsEventSubscriber?.isActive());
	}
}

import { Response } from 'express';

// Standard API response structure
export interface ApiResponse<T = any> {
	success: boolean;
	data?: T;
	error?: {
		code: string;
		message: string;
		details?: any;
	};
	meta?: {
		timestamp: string;
		requestId?: string;
	};
}

// Success response helper
export function successResponse<T>(
	res: Response,
	data: T,
	statusCode: number = 200,
	requestId?: string
): void {
	const response: ApiResponse<T> = {
		success: true,
		data,
		meta: {
			timestamp: new Date().toISOString(),
			...(requestId && { requestId }),
		},
	};

	res.status(statusCode).json(response);
}

// CRITICAL FIX: Enhanced error response helper to prevent [object Object] display
export function errorResponse(
	res: Response,
	code: string,
	message: string,
	statusCode: number = 500,
	details?: any,
	requestId?: string
): void {
	// CRITICAL FIX: Sanitize error message and details to ensure they're serializable
	let sanitizedMessage = message;
	let sanitizedDetails = details;

	// Ensure message is always a string
	if (typeof message !== 'string') {
		try {
			sanitizedMessage =
				(message as any) instanceof Error ? (message as Error).message : String(message);
		} catch {
			sanitizedMessage = 'Unknown error occurred';
		}
	}

	// Sanitize details to prevent circular references and [object Object] display
	if (details !== undefined && details !== null) {
		try {
			if (details instanceof Error) {
				sanitizedDetails = {
					message: details.message,
					name: details.name,
					...(details.stack && { stack: details.stack.split('\n').slice(0, 3).join('\n') }),
				};
			} else if (typeof details === 'object') {
				// Safely stringify object, handling circular references
				sanitizedDetails = JSON.parse(
					JSON.stringify(details, (key, value) => {
						// Handle circular references and functions
						if (typeof value === 'function') return '[Function]';
						if (typeof value === 'symbol') return '[Symbol]';
						if (value instanceof Error) return { message: value.message, name: value.name };
						return value;
					})
				);
			} else {
				sanitizedDetails = String(details);
			}
		} catch {
			// If serialization fails, convert to string
			sanitizedDetails = { message: String(details), serializationError: true };
		}
	}

	const response: ApiResponse = {
		success: false,
		error: {
			code,
			message: sanitizedMessage,
			...(sanitizedDetails !== undefined && { details: sanitizedDetails }),
		},
		meta: {
			timestamp: new Date().toISOString(),
			...(requestId && { requestId }),
		},
	};

	res.status(statusCode).json(response);
}

// Common error codes
export const ERROR_CODES = {
	VALIDATION_ERROR: 'VALIDATION_ERROR',
	NOT_FOUND: 'NOT_FOUND',
	UNAUTHORIZED: 'UNAUTHORIZED',
	INTERNAL_ERROR: 'INTERNAL_ERROR',
	BAD_REQUEST: 'BAD_REQUEST',
	SESSION_NOT_FOUND: 'SESSION_NOT_FOUND',
	MCP_SERVER_ERROR: 'MCP_SERVER_ERROR',
	LLM_ERROR: 'LLM_ERROR',
	RATE_LIMIT_EXCEEDED: 'RATE_LIMIT_EXCEEDED',
} as const;

export type ErrorCode = keyof typeof ERROR_CODES;

// Security utilities for API server

// Sensitive field patterns that should be redacted
const SENSITIVE_PATTERNS = [
	/api[_-]?key/i,
	/secret/i,
	/token/i,
	/password/i,
	/auth/i,
	/credential/i,
	/private[_-]?key/i,
];

// Environment variables that should be redacted
const SENSITIVE_ENV_VARS = [
	'OPENAI_API_KEY',
	'ANTHROPIC_API_KEY',
	'OPENROUTER_API_KEY',
	'DATABASE_URL',
	'REDIS_URL',
	'QDRANT_API_KEY',
	'MILVUS_TOKEN',
];

/**
 * Redacts sensitive information from any object
 */
export function redactSensitiveData(obj: any): any {
	if (typeof obj !== 'object' || obj === null) {
		return obj;
	}

	if (Array.isArray(obj)) {
		return obj.map(item => redactSensitiveData(item));
	}

	const redacted: any = {};

	for (const [key, value] of Object.entries(obj)) {
		// Check if key matches sensitive patterns
		const isSensitive = SENSITIVE_PATTERNS.some(pattern => pattern.test(key));

		if (isSensitive && typeof value === 'string') {
			redacted[key] = maskValue(value);
		} else if (typeof value === 'object') {
			redacted[key] = redactSensitiveData(value);
		} else {
			redacted[key] = value;
		}
	}

	return redacted;
}

/**
 * Masks a string value, showing only first and last few characters
 */
function maskValue(value: string): string {
	if (!value || value.length <= 8) {
		return '***';
	}

	const start = value.slice(0, 4);
	const end = value.slice(-4);
	const middle = '*'.repeat(Math.max(4, value.length - 8));

	return `${start}${middle}${end}`;
}

/**
 * Redacts sensitive environment variables
 */
export function redactEnvironmentVars(
	env: Record<string, string | undefined>
): Record<string, string | undefined> {
	const redacted: Record<string, string | undefined> = {};

	for (const [key, value] of Object.entries(env)) {
		if (SENSITIVE_ENV_VARS.includes(key) && value) {
			redacted[key] = maskValue(value);
		} else {
			redacted[key] = value;
		}
	}

	return redacted;
}

/**
 * Sanitizes user input to prevent injection attacks
 */
export function sanitizeInput(input: string): string {
	if (typeof input !== 'string') {
		return input;
	}

	// Remove null bytes and control characters except newlines and tabs
	// eslint-disable-next-line no-control-regex
	return input.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '');
}

/**
 * Validates that a string is a valid UUID
 */
export function isValidUUID(uuid: string): boolean {
	const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
	return uuidRegex.test(uuid);
}

/**
 * Validates session ID format (allows UUID or custom format)
 */
export function isValidSessionId(sessionId: string): boolean {
	// Allow UUID format or alphanumeric with hyphens/underscores (max 50 chars)
	return isValidUUID(sessionId) || /^[a-zA-Z0-9_-]{1,50}$/.test(sessionId);
}

import { WebSocket } from 'ws';
import { v4 as uuidv4 } from 'uuid';
import { logger } from '@core/logger/index.js';
import {
	WebSocketConnection,
	WebSocketResponse,
	WebSocketConnectionStats,
	WebSocketEventType,
} from './types.js';

export class WebSocketConnectionManager {
	private connections = new Map<string, WebSocketConnection>();
	private sessionConnections = new Map<string, Set<string>>();
	private connectionSessions = new Map<string, string>();
	private stats = {
		totalMessagesReceived: 0,
		totalMessagesSent: 0,
		connectionsCreated: 0,
	};
	private eventSubscriber?: any; // We'll set this after initialization

	constructor(
		private maxConnections: number = 1000,
		private connectionTimeout: number = 300000 // 5 minutes
	) {
		// Start connection cleanup interval
		setInterval(() => {
			this.cleanupStaleConnections();
		}, 60000); // Check every minute
	}

	/**
	 * Set the event subscriber to notify when sessions are bound
	 */
	setEventSubscriber(eventSubscriber: any): void {
		this.eventSubscriber = eventSubscriber;
	}

	/**
	 * Add a new WebSocket connection
	 */
	addConnection(ws: WebSocket, sessionId?: string): string {
		if (this.connections.size >= this.maxConnections) {
			logger.warn('WebSocket connection limit reached', {
				currentConnections: this.connections.size,
				maxConnections: this.maxConnections,
			});
			ws.close(1013, 'Server overloaded');
			throw new Error('Maximum connections exceeded');
		}

		const connectionId = uuidv4();
		const now = Date.now();

		const connection: WebSocketConnection = {
			id: connectionId,
			ws,
			sessionId: sessionId || undefined,
			subscribedEvents: new Set(),
			connectedAt: now,
			lastActivity: now,
		};

		this.connections.set(connectionId, connection);
		this.connectionSessions.set(connectionId, sessionId || '');
		this.stats.connectionsCreated++;

		if (sessionId) {
			this.bindToSession(connectionId, sessionId);
		}

		// Set up WebSocket event handlers
		this.setupConnectionHandlers(connection);

		logger.info('WebSocket connection added', {
			connectionId,
			sessionId,
			totalConnections: this.connections.size,
		});

		return connectionId;
	}

	/**
	 * Remove a WebSocket connection
	 */
	removeConnection(connectionId: string): void {
		const connection = this.connections.get(connectionId);
		if (!connection) {
			return;
		}

		// Remove from session bindings
		if (connection.sessionId) {
			const sessionConnections = this.sessionConnections.get(connection.sessionId);
			if (sessionConnections) {
				sessionConnections.delete(connectionId);
				if (sessionConnections.size === 0) {
					this.sessionConnections.delete(connection.sessionId);
				}
			}
		}

		// Clean up mappings
		this.connections.delete(connectionId);
		this.connectionSessions.delete(connectionId);

		// Close WebSocket if still open
		if (connection.ws.readyState === WebSocket.OPEN) {
			connection.ws.close();
		}

		logger.info('WebSocket connection removed', {
			connectionId,
			sessionId: connection.sessionId,
			totalConnections: this.connections.size,
		});
	}

	/**
	 * Bind a connection to a session
	 */
	bindToSession(connectionId: string, sessionId: string): void {
		const connection = this.connections.get(connectionId);
		if (!connection) {
			logger.warn('Attempted to bind non-existent connection to session', {
				connectionId,
				sessionId,
			});
			return;
		}

		// Update connection
		connection.sessionId = sessionId;
		this.connectionSessions.set(connectionId, sessionId);

		// Add to session mapping
		if (!this.sessionConnections.has(sessionId)) {
			this.sessionConnections.set(sessionId, new Set());
		}
		this.sessionConnections.get(sessionId)!.add(connectionId);

		// Send connection update to notify client of session binding
		this.sendConnectionUpdate(connectionId);

		// Notify event subscriber to start listening to this session's events
		if (this.eventSubscriber) {
			this.eventSubscriber.subscribeToSession(sessionId);
		}

		logger.debug('Connection bound to session', {
			connectionId,
			sessionId,
		});
	}

	/**
	 * Get the session ID for a connection
	 */
	getConnectionSessionId(connectionId: string): string | undefined {
		const connection = this.connections.get(connectionId);
		return connection?.sessionId;
	}

	/**
	 * Send updated connection info to a specific connection
	 */
	sendConnectionUpdate(connectionId: string): void {
		const connection = this.connections.get(connectionId);
		if (!connection || connection.ws.readyState !== WebSocket.OPEN) {
			return;
		}

		const updateMessage = {
			event: 'connectionUpdated',
			data: {
				connectionId,
				sessionId: connection.sessionId,
				timestamp: Date.now(),
			},
			timestamp: Date.now(),
		};

		try {
			connection.ws.send(JSON.stringify(updateMessage));
			logger.debug('Sent connection update', {
				connectionId,
				sessionId: connection.sessionId,
			});
		} catch (error) {
			logger.error('Failed to send connection update', {
				connectionId,
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}

	/**
	 * Subscribe a connection to specific event types
	 */
	subscribeToEvents(connectionId: string, eventTypes: WebSocketEventType[]): void {
		const connection = this.connections.get(connectionId);
		if (!connection) {
			logger.warn('Attempted to subscribe non-existent connection to events', {
				connectionId,
				eventTypes,
			});
			return;
		}

		eventTypes.forEach(eventType => {
			connection.subscribedEvents!.add(eventType);
		});

		logger.debug('Connection subscribed to events', {
			connectionId,
			eventTypes,
			totalSubscriptions: connection.subscribedEvents!.size,
		});
	}

	/**
	 * Unsubscribe a connection from specific event types
	 */
	unsubscribeFromEvents(connectionId: string, eventTypes: WebSocketEventType[]): void {
		const connection = this.connections.get(connectionId);
		if (!connection) {
			return;
		}

		eventTypes.forEach(eventType => {
			connection.subscribedEvents!.delete(eventType);
		});

		logger.debug('Connection unsubscribed from events', {
			connectionId,
			eventTypes,
			totalSubscriptions: connection.subscribedEvents!.size,
		});
	}

	/**
	 * Broadcast message to all connections in a session
	 */
	broadcastToSession(sessionId: string, message: WebSocketResponse): void {
		const connectionIds = this.sessionConnections.get(sessionId);
		if (!connectionIds || connectionIds.size === 0) {
			return;
		}

		for (const connectionId of connectionIds) {
			this.sendToConnection(connectionId, message);
		}
	}

	/**
	 * Broadcast message to all active connections
	 */
	broadcastToAll(message: WebSocketResponse): void {
		let sentCount = 0;
		for (const connectionId of this.connections.keys()) {
			if (this.sendToConnection(connectionId, message)) {
				sentCount++;
			}
		}

		logger.debug('Message broadcast to all connections', {
			totalConnections: this.connections.size,
			sentCount,
			event: message.event,
		});
	}

	/**
	 * Broadcast message to connections subscribed to specific event type
	 */
	broadcastToSubscribers(eventType: WebSocketEventType, message: WebSocketResponse): void {
		let sentCount = 0;
		for (const connection of this.connections.values()) {
			// If no subscriptions, send all events (default behavior)
			// If has subscriptions, only send subscribed events
			const shouldSend =
				connection.subscribedEvents!.size === 0 || connection.subscribedEvents!.has(eventType);

			if (shouldSend && this.sendToConnection(connection.id, message)) {
				sentCount++;
			}
		}

		logger.debug('Message broadcast to subscribers', {
			eventType,
			totalConnections: this.connections.size,
			sentCount,
			event: message.event,
		});
	}

	/**
	 * Send message to a specific connection
	 */
	private sendToConnection(connectionId: string, message: WebSocketResponse): boolean {
		const connection = this.connections.get(connectionId);
		if (!connection || connection.ws.readyState !== WebSocket.OPEN) {
			return false;
		}
		try {
			const messageStr = JSON.stringify(message);
			connection.ws.send(messageStr);
			connection.lastActivity = Date.now();
			this.stats.totalMessagesSent++;
			return true;
		} catch (error: any) {
			logger.error('Failed to send WebSocket message', {
				connectionId,
				error: error.message,
			});
			return false;
		}
	}

	/**
	 * Get connection statistics
	 */
	getStats(): WebSocketConnectionStats {
		const now = Date.now();
		let totalDuration = 0;
		let activeConnections = 0;
		const activeSessions = new Set<string>();

		for (const connection of this.connections.values()) {
			if (connection.ws.readyState === WebSocket.OPEN) {
				activeConnections++;
				totalDuration += now - connection.connectedAt;
				if (connection.sessionId) {
					activeSessions.add(connection.sessionId);
				}
			}
		}

		const averageConnectionDuration = activeConnections > 0 ? totalDuration / activeConnections : 0;

		return {
			totalConnections: this.stats.connectionsCreated,
			activeConnections,
			totalSessions: this.sessionConnections.size,
			activeSessions: activeSessions.size,
			totalMessagesReceived: this.stats.totalMessagesReceived,
			totalMessagesSent: this.stats.totalMessagesSent,
			averageConnectionDuration,
		};
	}

	/**
	 * Get all active session IDs
	 */
	getActiveSessions(): string[] {
		return Array.from(this.sessionConnections.keys()).filter(sessionId => {
			const connections = this.sessionConnections.get(sessionId);
			return connections && connections.size > 0;
		});
	}

	/**
	 * Check if a session has active connections
	 */
	hasActiveConnections(sessionId: string): boolean {
		const connections = this.sessionConnections.get(sessionId);
		if (!connections) return false;

		for (const connectionId of connections) {
			const connection = this.connections.get(connectionId);
			if (connection && connection.ws.readyState === WebSocket.OPEN) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Set up WebSocket event handlers for a connection
	 */
	private setupConnectionHandlers(connection: WebSocketConnection): void {
		connection.ws.on('close', () => {
			this.removeConnection(connection.id);
		});

		connection.ws.on('error', error => {
			logger.error('WebSocket connection error', {
				connectionId: connection.id,
				error: error.message,
			});
			this.removeConnection(connection.id);
		});

		connection.ws.on('pong', () => {
			connection.lastActivity = Date.now();
		});
	}

	/**
	 * Clean up stale connections
	 */
	private cleanupStaleConnections(): void {
		const now = Date.now();
		const staleConnections: string[] = [];

		for (const [connectionId, connection] of this.connections) {
			// Check if connection is stale
			const isStale =
				now - connection.lastActivity > this.connectionTimeout ||
				connection.ws.readyState !== WebSocket.OPEN;

			if (isStale) {
				staleConnections.push(connectionId);
			}
		}

		if (staleConnections.length > 0) {
			logger.info('Cleaning up stale WebSocket connections', {
				staleCount: staleConnections.length,
				totalConnections: this.connections.size,
			});

			staleConnections.forEach(connectionId => {
				this.removeConnection(connectionId);
			});
		}
	}

	/**
	 * Send heartbeat pings to all connections
	 */
	sendHeartbeat(): void {
		for (const connection of this.connections.values()) {
			if (connection.ws.readyState === WebSocket.OPEN) {
				try {
					connection.ws.ping();
				} catch (error) {
					logger.warn('Failed to send heartbeat ping', {
						connectionId: connection.id,
						error: error instanceof Error ? error.message : String(error),
					});
					this.removeConnection(connection.id);
				}
			}
		}
	}

	/**
	 * Record incoming message for stats
	 */
	recordIncomingMessage(): void {
		this.stats.totalMessagesReceived++;
	}

	/**
	 * Dispose of the connection manager
	 */
	dispose(): void {
		// Close all connections
		for (const connection of this.connections.values()) {
			if (connection.ws.readyState === WebSocket.OPEN) {
				connection.ws.close();
			}
		}

		// Clear all maps
		this.connections.clear();
		this.sessionConnections.clear();
		this.connectionSessions.clear();

		logger.info('WebSocket connection manager disposed');
	}
}

import { EventManager } from '@core/events/event-manager.js';
import { logger } from '@core/logger/index.js';
import { WebSocketConnectionManager } from './connection-manager.js';
import { WebSocketResponse, WebSocketEventType } from './types.js';

/**
 * WebSocket Event Bridge - Advanced event routing and transformation
 *
 * This class provides additional event transformation and routing capabilities
 * beyond the basic WebSocketEventSubscriber. It's useful for custom event
 * handling, filtering, and transformation logic.
 */
export class WebSocketEventBridge {
	private eventFilters = new Map<WebSocketEventType, (data: any) => boolean>();
	private eventTransformers = new Map<WebSocketEventType, (data: any) => any>();
	private routingRules = new Map<WebSocketEventType, 'session' | 'global' | 'subscribers'>();

	constructor(
		private connectionManager: WebSocketConnectionManager,
		private eventManager: EventManager
	) {
		this.setupDefaultRoutingRules();
	}

	/**
	 * Set up default routing rules for different event types
	 */
	private setupDefaultRoutingRules(): void {
		// Session-specific events
		this.routingRules.set('thinking', 'session');
		this.routingRules.set('chunk', 'session');
		this.routingRules.set('response', 'session');
		this.routingRules.set('toolCall', 'session');
		this.routingRules.set('toolResult', 'session');
		this.routingRules.set('conversationReset', 'session');
		this.routingRules.set('memoryOperation', 'session');
		this.routingRules.set('sessionCreated', 'session');
		this.routingRules.set('sessionEnded', 'session');

		// Global events
		this.routingRules.set('systemMessage', 'global');
		this.routingRules.set('mcpServerConnected', 'global');
		this.routingRules.set('mcpServerDisconnected', 'global');

		// Subscriber-based events (filtered by subscription)
		this.routingRules.set('error', 'subscribers');
		this.routingRules.set('availableToolsUpdated', 'subscribers');
	}

	/**
	 * Register an event filter
	 */
	registerEventFilter(eventType: WebSocketEventType, filter: (data: any) => boolean): void {
		this.eventFilters.set(eventType, filter);
		logger.debug('WebSocket event filter registered', { eventType });
	}

	/**
	 * Register an event transformer
	 */
	registerEventTransformer(eventType: WebSocketEventType, transformer: (data: any) => any): void {
		this.eventTransformers.set(eventType, transformer);
		logger.debug('WebSocket event transformer registered', { eventType });
	}

	/**
	 * Set routing rule for an event type
	 */
	setRoutingRule(eventType: WebSocketEventType, rule: 'session' | 'global' | 'subscribers'): void {
		this.routingRules.set(eventType, rule);
		logger.debug('WebSocket routing rule set', { eventType, rule });
	}

	/**
	 * Process and route an event
	 */
	processEvent(eventType: WebSocketEventType, data: any): void {
		try {
			// Apply filter if exists
			const filter = this.eventFilters.get(eventType);
			if (filter && !filter(data)) {
				logger.debug('Event filtered out', { eventType });
				return;
			}

			// Apply transformer if exists
			const transformer = this.eventTransformers.get(eventType);
			const transformedData = transformer ? transformer(data) : data;

			// Create WebSocket response
			const response: WebSocketResponse = {
				event: eventType,
				data: transformedData,
				timestamp: Date.now(),
			};

			// Add sessionId if present
			if (
				transformedData &&
				typeof transformedData === 'object' &&
				'sessionId' in transformedData
			) {
				response.sessionId = transformedData.sessionId;
			}

			// Route based on routing rule
			const routingRule = this.routingRules.get(eventType) || 'subscribers';
			this.routeEvent(routingRule, eventType, response);
		} catch (error) {
			logger.error('Error processing WebSocket event', {
				eventType,
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}

	/**
	 * Route event based on routing rule
	 */
	private routeEvent(
		rule: 'session' | 'global' | 'subscribers',
		eventType: WebSocketEventType,
		response: WebSocketResponse
	): void {
		switch (rule) {
			case 'session':
				if (response.sessionId) {
					this.connectionManager.broadcastToSession(response.sessionId, response);
				} else {
					logger.warn('Session routing requested but no sessionId provided', { eventType });
				}
				break;

			case 'global':
				this.connectionManager.broadcastToAll(response);
				break;

			case 'subscribers':
				this.connectionManager.broadcastToSubscribers(eventType, response);
				break;

			default:
				logger.warn('Unknown routing rule', { rule, eventType });
		}
	}

	/**
	 * Setup common event filters
	 */
	setupCommonFilters(): void {
		// Filter out noisy debug events in production
		if (process.env.NODE_ENV === 'production') {
			this.registerEventFilter('thinking', data => {
				// Only show thinking for sessions with active connections
				return data.sessionId && this.connectionManager.hasActiveConnections(data.sessionId);
			});
		}

		// Filter memory operations by success status
		this.registerEventFilter('memoryOperation', data => {
			// Only broadcast successful memory operations unless specifically requested
			return data.success !== false;
		});

		// Filter tool results by importance
		this.registerEventFilter('toolResult', data => {
			// Always show failed tool executions, but successful ones only for subscribed clients
			return !data.success || data.important;
		});

		logger.info('Common WebSocket event filters setup completed');
	}

	/**
	 * Setup common event transformers
	 */
	setupCommonTransformers(): void {
		// Transform error events to include more context
		this.registerEventTransformer('error', data => ({
			...data,
			timestamp: Date.now(),
			severity: this.getErrorSeverity(data.code || data.message),
			suggestions: this.getErrorSuggestions(data.code || data.message),
		}));

		// Transform chunk events to include progress information
		this.registerEventTransformer('chunk', data => ({
			...data,
			timestamp: Date.now(),
			// Add progress estimation if we can determine it
			...(data.messageId && { progress: this.estimateProgress(data) }),
		}));

		// Transform tool call events to include execution context
		this.registerEventTransformer('toolCall', data => ({
			...data,
			timestamp: Date.now(),
			category: this.getToolCategory(data.toolName),
			expectedDuration: this.getExpectedToolDuration(data.toolName),
		}));

		logger.info('Common WebSocket event transformers setup completed');
	}

	/**
	 * Get error severity level
	 */
	private getErrorSeverity(errorCode: string): 'low' | 'medium' | 'high' | 'critical' {
		const criticalErrors = ['SYSTEM_ERROR', 'DATABASE_ERROR', 'MEMORY_ERROR'];
		const highErrors = ['PROCESSING_ERROR', 'LLM_ERROR', 'TOOL_ERROR'];
		const mediumErrors = ['VALIDATION_ERROR', 'AUTHENTICATION_ERROR'];

		if (criticalErrors.some(code => errorCode.includes(code))) return 'critical';
		if (highErrors.some(code => errorCode.includes(code))) return 'high';
		if (mediumErrors.some(code => errorCode.includes(code))) return 'medium';
		return 'low';
	}

	/**
	 * Get error suggestions
	 */
	private getErrorSuggestions(errorCode: string): string[] {
		const suggestions: Record<string, string[]> = {
			WEBSOCKET_ERROR: ['Check your internet connection', 'Try refreshing the page'],
			PROCESSING_ERROR: [
				'Try rephrasing your request',
				'Check if all required fields are provided',
			],
			VALIDATION_ERROR: ['Check your input format', 'Ensure all required fields are provided'],
			AUTHENTICATION_ERROR: ['Please log in again', 'Check your session is still valid'],
		};

		for (const [code, hints] of Object.entries(suggestions)) {
			if (errorCode.includes(code)) {
				return hints;
			}
		}

		return ['Try again in a few moments', 'Contact support if the issue persists'];
	}

	/**
	 * Estimate progress for chunk events
	 */
	private estimateProgress(data: any): number {
		// This is a simple estimation - in a real implementation,
		// you might track message length and estimate based on typical response sizes
		if (data.isComplete) return 100;
		if (data.text && data.text.length > 0) {
			// Simple heuristic: assume we're 10-90% done based on current text length
			const estimatedProgress = Math.min(90, Math.max(10, data.text.length / 10));
			return Math.round(estimatedProgress);
		}
		return 10;
	}

	/**
	 * Get tool category
	 */
	private getToolCategory(toolName: string): string {
		const categories: Record<string, string[]> = {
			memory: ['store_memory', 'search_memory', 'extract_knowledge'],
			knowledge: ['add_node', 'search_graph', 'extract_entities'],
			system: ['reset', 'config', 'health'],
			processing: ['run', 'execute', 'process'],
		};

		for (const [category, tools] of Object.entries(categories)) {
			if (tools.some(tool => toolName.toLowerCase().includes(tool))) {
				return category;
			}
		}

		return 'general';
	}

	/**
	 * Get expected tool duration in milliseconds
	 */
	private getExpectedToolDuration(toolName: string): number {
		const durations: Record<string, number> = {
			store_memory: 2000,
			search_memory: 1500,
			extract_knowledge: 3000,
			add_node: 1000,
			search_graph: 2000,
			reset: 500,
			config: 300,
		};

		const lowerToolName = toolName.toLowerCase();
		for (const [tool, duration] of Object.entries(durations)) {
			if (lowerToolName.includes(tool)) {
				return duration;
			}
		}

		return 2000; // Default 2 seconds
	}

	/**
	 * Get bridge statistics
	 */
	getStats(): {
		filtersRegistered: number;
		transformersRegistered: number;
		routingRules: Record<string, string>;
		eventsProcessed: number;
	} {
		return {
			filtersRegistered: this.eventFilters.size,
			transformersRegistered: this.eventTransformers.size,
			routingRules: Object.fromEntries(this.routingRules),
			eventsProcessed: 0, // TODO: Track this
		};
	}

	/**
	 * Clear all filters, transformers, and routing rules
	 */
	clear(): void {
		this.eventFilters.clear();
		this.eventTransformers.clear();
		this.routingRules.clear();
		this.setupDefaultRoutingRules();
		logger.info('WebSocket event bridge cleared and reset to defaults');
	}
}

import { EventManager } from '@core/events/event-manager.js';
import { logger } from '@core/logger/index.js';
import { WebSocketConnectionManager } from './connection-manager.js';
import { WebSocketResponse, WebSocketEventType, WebSocketEventData } from './types.js';

export class WebSocketEventSubscriber {
	private abortController: AbortController | null = null;
	private subscribedSessions = new Set<string>();
	private subscriptionStats = {
		totalEventsReceived: 0,
		totalEventsBroadcast: 0,
		eventTypeStats: new Map<string, number>(),
		lastEventTime: 0,
	};

	constructor(
		private connectionManager: WebSocketConnectionManager,
		private eventManager: EventManager
	) {}

	/**
	 * Subscribe to events from the EventManager
	 */
	subscribe(): void {
		if (this.abortController) {
			logger.warn('WebSocket event subscriber already active');
			return;
		}

		this.abortController = new AbortController();
		const { signal } = this.abortController;

		// Set higher max listeners limit to prevent memory leak warnings
		// Note: AbortSignal doesn't have setMaxListeners, but we can set it on the AbortController
		try {
			if (
				'setMaxListeners' in this.abortController &&
				typeof this.abortController.setMaxListeners === 'function'
			) {
				this.abortController.setMaxListeners(100);
			}
		} catch {
			// Ignore if setMaxListeners is not available
		}

		logger.info('Starting WebSocket event subscription');

		// Subscribe to Service Events
		this.subscribeToServiceEvents(signal);

		// Subscribe to Session Events (we'll handle session-specific events dynamically)
		this.subscribeToSessionEvents(signal);

		logger.info('WebSocket event subscriptions established');
	}

	/**
	 * Subscribe to service-level events
	 */
	private subscribeToServiceEvents(signal: AbortSignal): void {
		const serviceBus = this.eventManager.getServiceEventBus();

		// MCP Events
		serviceBus.on(
			'cipher:mcpClientConnected',
			data => {
				this.handleEvent(
					'mcpServerConnected',
					{
						serverName: data.serverName,
						capabilities: [],
					},
					signal
				);
			},
			{ signal }
		);

		serviceBus.on(
			'cipher:mcpClientDisconnected',
			data => {
				this.handleEvent(
					'mcpServerDisconnected',
					{
						serverName: data.serverName,
						...(data.reason && { reason: data.reason }),
					},
					signal
				);
			},
			{ signal }
		);

		// Tool Events
		serviceBus.on(
			'cipher:toolRegistered',
			data => {
				this.handleEvent(
					'availableToolsUpdated',
					{
						tools: [data.toolName],
					},
					signal
				);
			},
			{ signal }
		);

		// Memory Events
		serviceBus.on(
			'cipher:memoryOperationCompleted',
			data => {
				this.handleEvent(
					'memoryOperation',
					{
						operation: data.operation as 'store' | 'retrieve' | 'search',
						success: true,
						sessionId: data.sessionId || '',
						details: {
							operation: data.operation,
							duration: data.duration,
						},
					},
					signal
				);
			},
			{ signal }
		);

		serviceBus.on(
			'cipher:memoryOperationFailed',
			data => {
				this.handleEvent(
					'memoryOperation',
					{
						operation: data.operation as 'store' | 'retrieve' | 'search',
						success: false,
						sessionId: data.sessionId || '',
						details: {
							error: data.error,
						},
					},
					signal
				);
			},
			{ signal }
		);

		// System Events
		serviceBus.on(
			'cipher:error',
			data => {
				this.handleEvent(
					'error',
					{
						message: data.error || 'System error',
						code: 'SYSTEM_ERROR',
						...(data.stack && { stack: data.stack }),
					},
					signal
				);
			},
			{ signal }
		);
	}

	/**
	 * Subscribe to session-specific events dynamically
	 */
	private subscribeToSessionEvents(signal: AbortSignal): void {
		// Listen for all active sessions and subscribe to their events
		const activeSessions = this.eventManager.getActiveSessionIds();

		activeSessions.forEach(sessionId => {
			if (!this.subscribedSessions.has(sessionId)) {
				this.subscribeToSingleSessionEvents(sessionId, signal);
				this.subscribedSessions.add(sessionId);
			}
		});

		logger.debug('Session event subscriptions ready for existing sessions', {
			existingSessionCount: activeSessions.length,
			subscribedSessionCount: this.subscribedSessions.size,
		});
	}

	/**
	 * Subscribe to a session's events on-demand (called when session is bound to connection)
	 */
	public subscribeToSession(sessionId: string): void {
		if (this.abortController && !this.subscribedSessions.has(sessionId)) {
			logger.debug('Dynamically subscribing to session events', { sessionId });
			this.subscribeToSingleSessionEvents(sessionId, this.abortController.signal);
			this.subscribedSessions.add(sessionId);
		} else if (this.subscribedSessions.has(sessionId)) {
			logger.debug('Session already subscribed, skipping', { sessionId });
		}
	}

	/**
	 * Remove session from tracking when it's deleted
	 */
	public unsubscribeFromSession(sessionId: string): void {
		if (this.subscribedSessions.has(sessionId)) {
			this.subscribedSessions.delete(sessionId);
			logger.debug('Session removed from subscription tracking', { sessionId });
		}
	}

	/**
	 * Subscribe to events for a specific session
	 */
	private subscribeToSingleSessionEvents(sessionId: string, signal: AbortSignal): void {
		const sessionBus = this.eventManager.getSessionEventBus(sessionId);

		// LLM Events
		sessionBus.on(
			'llm:thinking',
			data => {
				this.handleEvent(
					'thinking',
					{
						sessionId: data.sessionId,
					},
					signal
				);
			},
			{ signal }
		);

		sessionBus.on(
			'llm:responseStarted',
			data => {
				// Don't send another thinking event, just log it
				logger.debug('LLM response started', { sessionId: data.sessionId });
			},
			{ signal }
		);

		// Add streaming chunk event listener
		sessionBus.on(
			'llm:responseChunk',
			(data: any) => {
				this.handleEvent(
					'chunk',
					{
						text: data.chunk || data.text || '',
						isComplete: false,
						sessionId: data.sessionId,
						messageId: data.messageId,
					},
					signal
				);
			},
			{ signal }
		);

		sessionBus.on(
			'llm:responseCompleted',
			async (data: any) => {
				// Use the actual response content from the event data
				const content = data.response || data.content || 'Response completed';

				const sessionId = data.sessionId;
				const messageId = data.messageId;

				// Break down the response into chunks and emit them
				if (content && typeof content === 'string') {
					const chunkSize = 50; // Emit chunks of 50 characters
					for (let i = 0; i < content.length; i += chunkSize) {
						const chunk = content.slice(i, i + chunkSize);
						const isComplete = i + chunkSize >= content.length;

						this.handleEvent(
							'chunk',
							{
								text: chunk,
								isComplete,
								sessionId,
								messageId,
							},
							signal
						);

						// Add a small delay between chunks to simulate real streaming
						if (!isComplete) {
							await new Promise(resolve => setTimeout(resolve, 50));
						}
					}
				}

				// Emit the final response event
				this.handleEvent(
					'response',
					{
						content: content,
						sessionId: data.sessionId,
						messageId: data.messageId,
						metadata: {
							model: data.model,
							tokenCount: data.tokenCount,
							duration: data.duration,
						},
					},
					signal
				);
			},
			{ signal }
		);

		sessionBus.on(
			'llm:responseError',
			data => {
				this.handleEvent(
					'error',
					{
						message: data.error || 'LLM processing error',
						code: 'LLM_ERROR',
						sessionId: data.sessionId,
					},
					signal
				);
			},
			{ signal }
		);

		// Tool Events
		sessionBus.on(
			'tool:executionStarted',
			data => {
				logger.debug('WebSocket: Received tool:executionStarted event', {
					toolName: data.toolName,
					sessionId: data.sessionId,
					executionId: data.executionId,
				});

				// Send the specific tool execution started event
				this.handleEvent(
					'toolExecutionStarted',
					{
						toolName: data.toolName,
						sessionId: data.sessionId,
						callId: data.executionId,
						executionId: data.executionId,
					},
					signal
				);
			},
			{ signal }
		);

		sessionBus.on(
			'tool:executionCompleted',
			(data: any) => {
				// Send specific completion event
				this.handleEvent(
					'toolExecutionCompleted',
					{
						toolName: data.toolName,
						success: data.success,
						sessionId: data.sessionId,
						callId: data.executionId,
						executionId: data.executionId,
					},
					signal
				);
			},
			{ signal }
		);

		sessionBus.on(
			'tool:executionFailed',
			(data: any) => {
				// Send specific failure event
				this.handleEvent(
					'toolExecutionFailed',
					{
						toolName: data.toolName,
						error: data.error,
						sessionId: data.sessionId,
						callId: data.executionId,
						executionId: data.executionId,
					},
					signal
				);
			},
			{ signal }
		);

		// Memory Events
		sessionBus.on(
			'memory:stored',
			(data: any) => {
				this.handleEvent(
					'memoryOperation',
					{
						operation: 'store',
						success: true,
						sessionId: data.sessionId,
						details: {
							type: data.type,
							size: data.size,
						},
					},
					signal
				);
			},
			{ signal }
		);

		sessionBus.on(
			'memory:retrieved',
			(data: any) => {
				this.handleEvent(
					'memoryOperation',
					{
						operation: 'retrieve',
						success: true,
						sessionId: data.sessionId,
						details: {
							count: data.count,
							type: data.type,
						},
					},
					signal
				);
			},
			{ signal }
		);

		sessionBus.on(
			'memory:searched',
			(data: any) => {
				this.handleEvent(
					'memoryOperation',
					{
						operation: 'search',
						success: true,
						sessionId: data.sessionId,
						details: {
							query: data.query,
							resultCount: data.resultCount,
							duration: data.duration,
						},
					},
					signal
				);
			},
			{ signal }
		);

		// Session Lifecycle Events
		sessionBus.on(
			'session:created',
			data => {
				this.handleEvent(
					'sessionCreated',
					{
						sessionId: data.sessionId,
						timestamp: data.timestamp,
					},
					signal
				);
			},
			{ signal }
		);

		sessionBus.on(
			'session:deleted',
			data => {
				// Clean up session subscription tracking
				this.unsubscribeFromSession(data.sessionId);

				this.handleEvent(
					'sessionEnded',
					{
						sessionId: data.sessionId,
						timestamp: data.timestamp,
					},
					signal
				);
			},
			{ signal }
		);

		// Conversation Events
		sessionBus.on(
			'conversation:cleared',
			data => {
				this.handleEvent(
					'conversationReset',
					{
						sessionId: data.sessionId,
					},
					signal
				);
			},
			{ signal }
		);
	}

	/**
	 * Handle an event and broadcast to appropriate WebSocket connections
	 */
	private handleEvent<T extends WebSocketEventType>(
		eventType: T,
		data: WebSocketEventData[T],
		signal: AbortSignal
	): void {
		if (signal.aborted) {
			return;
		}

		const response: WebSocketResponse = {
			event: eventType,
			data: data,
			timestamp: Date.now(),
		};

		// Broadcast to all sessions if no specific sessionId
		const sessionId = (data as any)?.sessionId;
		if (!sessionId) {
			this.broadcastMessage(response);
		} else {
			this.broadcastToSession(sessionId, response);
		}

		// Update stats
		this.subscriptionStats.totalEventsBroadcast++;
		this.subscriptionStats.lastEventTime = Date.now();
		this.subscriptionStats.eventTypeStats.set(
			eventType,
			(this.subscriptionStats.eventTypeStats.get(eventType) || 0) + 1
		);
	}

	/**
	 * Unsubscribe from events
	 */
	unsubscribe(): void {
		if (this.abortController) {
			this.abortController.abort();
			this.abortController = null;
			this.subscribedSessions.clear();
			logger.info('WebSocket event subscriptions terminated');
		}
	}

	/**
	 * Get subscription statistics
	 */
	getStats(): {
		isActive: boolean;
		totalEventsReceived: number;
		totalEventsBroadcast: number;
		lastEventTime: number;
		eventTypeStats: Record<string, number>;
		subscribedSessionCount: number;
		connectionStats: any;
	} {
		return {
			isActive: !!this.abortController && !this.abortController.signal.aborted,
			totalEventsReceived: this.subscriptionStats.totalEventsReceived,
			totalEventsBroadcast: this.subscriptionStats.totalEventsBroadcast,
			lastEventTime: this.subscriptionStats.lastEventTime,
			eventTypeStats: Object.fromEntries(this.subscriptionStats.eventTypeStats),
			subscribedSessionCount: this.subscribedSessions.size,
			connectionStats: this.connectionManager.getStats(),
		};
	}

	/**
	 * Manually broadcast a message to all connections
	 */
	broadcastMessage(message: WebSocketResponse): void {
		this.connectionManager.broadcastToAll(message);
		this.subscriptionStats.totalEventsBroadcast++;
	}

	/**
	 * Manually broadcast a message to a specific session
	 */
	broadcastToSession(sessionId: string, message: WebSocketResponse): void {
		this.connectionManager.broadcastToSession(sessionId, message);
		this.subscriptionStats.totalEventsBroadcast++;
	}

	/**
	 * Send a system message to all connections
	 */
	sendSystemMessage(message: string, level: 'info' | 'warning' | 'error' = 'info'): void {
		const response: WebSocketResponse = {
			event: 'systemMessage',
			data: {
				message,
				level,
				timestamp: Date.now(),
			},
			timestamp: Date.now(),
		};

		this.broadcastMessage(response);

		logger.info('System message broadcast via WebSocket', {
			message,
			level,
		});
	}

	/**
	 * Check if subscriber is active
	 */
	isActive(): boolean {
		return !!this.abortController && !this.abortController.signal.aborted;
	}

	/**
	 * Dispose of the event subscriber
	 */
	dispose(): void {
		this.unsubscribe();

		// Reset statistics
		this.subscriptionStats = {
			totalEventsReceived: 0,
			totalEventsBroadcast: 0,
			eventTypeStats: new Map<string, number>(),
			lastEventTime: 0,
		};

		// Clear subscribed sessions
		this.subscribedSessions.clear();

		logger.info('WebSocket event subscriber disposed');
	}
}

export { WebSocketConnectionManager } from './connection-manager.js';
export { WebSocketMessageRouter } from './message-router.js';
export { WebSocketEventSubscriber } from './event-subscriber.js';
export * from './types.js';

// Convenience re-exports
export type {
	WebSocketMessage,
	WebSocketResponse,
	WebSocketConnection,
	WebSocketConnectionStats,
	WebSocketConfig,
	WebSocketEventType,
	WebSocketEventData,
} from './types.js';

import { WebSocket } from 'ws';
import { MemAgent } from '@core/brain/memAgent/index.js';
import { logger } from '@core/logger/index.js';
import { WebSocketMessage, WebSocketResponse, WebSocketEventType } from './types.js';
import { WebSocketConnectionManager } from './connection-manager.js';
// import { v4 as uuidv4 } from 'uuid'; // Not currently used

export class WebSocketMessageRouter {
	constructor(
		private agent: MemAgent,
		private connectionManager: WebSocketConnectionManager
	) {}

	/**
	 * Route incoming WebSocket message to appropriate handler
	 */
	async routeMessage(
		ws: WebSocket,
		connectionId: string,
		message: WebSocketMessage
	): Promise<void> {
		try {
			// Record incoming message for stats
			this.connectionManager.recordIncomingMessage();

			// Validate message format
			if (!this.isValidMessage(message)) {
				this.sendError(ws, 'Invalid message format', connectionId);
				return;
			}

			// Log incoming message
			logger.debug('WebSocket message received', {
				connectionId,
				type: message.type,
				sessionId: message.sessionId,
				hasContent: !!message.content,
			});

			// Route based on message type
			switch (message.type) {
				case 'message':
					await this.handleChatMessage(ws, connectionId, message);
					break;
				case 'reset':
					await this.handleReset(ws, connectionId, message);
					break;
				case 'subscribe':
					await this.handleSubscribe(ws, connectionId, message);
					break;
				case 'unsubscribe':
					await this.handleUnsubscribe(ws, connectionId, message);
					break;
				default:
					this.sendError(ws, `Unknown message type: ${message.type}`, connectionId);
			}
		} catch (error) {
			logger.error('Error routing WebSocket message', {
				connectionId,
				error: error instanceof Error ? error.message : String(error),
				stack: error instanceof Error ? error.stack : undefined,
			});
			this.sendError(
				ws,
				error instanceof Error ? error.message : 'Internal server error',
				connectionId
			);
		}
	}

	/**
	 * Handle chat message - process through MemAgent
	 */
	private async handleChatMessage(
		ws: WebSocket,
		connectionId: string,
		message: WebSocketMessage
	): Promise<void> {
		if (!message.content && !message.imageData) {
			this.sendError(ws, 'Message content or image data is required', connectionId);
			return;
		}

		let sessionId = message.sessionId;

		// Auto-create session if not provided
		if (!sessionId) {
			try {
				const session = await this.agent.sessionManager.createSession();
				sessionId = session.id;

				// Bind connection to new session
				this.connectionManager.bindToSession(connectionId, sessionId);

				// Notify client of session creation
				this.sendResponse(ws, {
					event: 'sessionCreated',
					data: { sessionId },
					sessionId,
				});

				logger.info('Auto-created session for WebSocket connection', {
					connectionId,
					sessionId,
				});
			} catch (error) {
				logger.error('Failed to create session for WebSocket connection', {
					connectionId,
					error: error instanceof Error ? error.message : String(error),
				});
				this.sendError(ws, 'Failed to create session', connectionId);
				return;
			}
		} else {
			// Bind connection to existing session
			this.connectionManager.bindToSession(connectionId, sessionId);
		}

		// Validate session exists
		try {
			const session = await this.agent.sessionManager.getSession(sessionId);
			if (!session) {
				this.sendError(ws, `Session ${sessionId} not found`, connectionId);
				return;
			}
		} catch (error) {
			logger.error('Error validating session', {
				sessionId,
				connectionId,
				error: error instanceof Error ? error.message : String(error),
			});
			this.sendError(ws, 'Session validation failed', connectionId);
			return;
		}

		// Process message through MemAgent with streaming enabled
		try {
			logger.info('Processing WebSocket chat message', {
				connectionId,
				sessionId,
				contentLength: message.content?.length || 0,
				hasImageData: !!message.imageData,
				hasFileData: !!message.fileData,
				stream: message.stream ?? true,
			});

			// Run the agent with streaming enabled
			// Convert imageData to the expected format if provided
			const imageData = message.imageData
				? {
						image: message.imageData.base64,
						mimeType: message.imageData.mimeType,
					}
				: undefined;

			await this.agent.run(message.content || '', imageData, sessionId, message.stream ?? true);

			logger.debug('WebSocket chat message processed successfully', {
				connectionId,
				sessionId,
			});
		} catch (error) {
			logger.error('Error processing chat message through MemAgent', {
				connectionId,
				sessionId,
				error: error instanceof Error ? error.message : String(error),
				stack: error instanceof Error ? error.stack : undefined,
			});

			// Send error to client
			this.connectionManager.broadcastToSession(sessionId, {
				event: 'error',
				data: {
					message: error instanceof Error ? error.message : 'Processing failed',
					code: 'PROCESSING_ERROR',
					sessionId,
				},
				sessionId,
				error: error instanceof Error ? error.message : 'Processing failed',
			});
		}
	}

	/**
	 * Handle conversation reset
	 */
	private async handleReset(
		ws: WebSocket,
		connectionId: string,
		message: WebSocketMessage
	): Promise<void> {
		const sessionId = message.sessionId;
		if (!sessionId) {
			this.sendError(ws, 'Session ID is required for reset', connectionId);
			return;
		}

		try {
			// Get session and reset it
			const session = await this.agent.getSession(sessionId);
			if (!session) {
				this.sendError(ws, `Session ${sessionId} not found`, connectionId);
				return;
			}

			// Clear conversation history - this will depend on the session implementation
			// For now, we'll emit the reset event and let the client handle it

			// Notify client of successful reset
			this.sendResponse(ws, {
				event: 'conversationReset',
				data: { sessionId },
				sessionId,
			});

			logger.info('Conversation reset via WebSocket', {
				connectionId,
				sessionId,
			});
		} catch (error) {
			logger.error('Error resetting conversation', {
				connectionId,
				sessionId,
				error: error instanceof Error ? error.message : String(error),
			});
			this.sendError(ws, 'Failed to reset conversation', connectionId);
		}
	}

	/**
	 * Handle event subscription
	 */
	private async handleSubscribe(
		ws: WebSocket,
		connectionId: string,
		message: WebSocketMessage
	): Promise<void> {
		if (!message.eventTypes || message.eventTypes.length === 0) {
			this.sendError(ws, 'Event types are required for subscription', connectionId);
			return;
		}

		try {
			// Validate event types
			const validEventTypes = message.eventTypes.filter(eventType =>
				this.isValidEventType(eventType)
			) as WebSocketEventType[];

			if (validEventTypes.length === 0) {
				this.sendError(ws, 'No valid event types provided', connectionId);
				return;
			}

			// Subscribe connection to events
			this.connectionManager.subscribeToEvents(connectionId, validEventTypes);

			// Confirm subscription
			this.sendResponse(ws, {
				event: 'subscribed',
				data: {
					eventTypes: validEventTypes,
					connectionId,
				},
			});

			logger.info('WebSocket connection subscribed to events', {
				connectionId,
				eventTypes: validEventTypes,
			});
		} catch (error) {
			logger.error('Error handling event subscription', {
				connectionId,
				error: error instanceof Error ? error.message : String(error),
			});
			this.sendError(ws, 'Failed to subscribe to events', connectionId);
		}
	}

	/**
	 * Handle event unsubscription
	 */
	private async handleUnsubscribe(
		ws: WebSocket,
		connectionId: string,
		message: WebSocketMessage
	): Promise<void> {
		if (!message.eventTypes || message.eventTypes.length === 0) {
			this.sendError(ws, 'Event types are required for unsubscription', connectionId);
			return;
		}

		try {
			// Validate event types
			const validEventTypes = message.eventTypes.filter(eventType =>
				this.isValidEventType(eventType)
			) as WebSocketEventType[];

			// Unsubscribe connection from events
			this.connectionManager.unsubscribeFromEvents(connectionId, validEventTypes);

			// Confirm unsubscription
			this.sendResponse(ws, {
				event: 'unsubscribed',
				data: {
					eventTypes: validEventTypes,
					connectionId,
				},
			});

			logger.info('WebSocket connection unsubscribed from events', {
				connectionId,
				eventTypes: validEventTypes,
			});
		} catch (error) {
			logger.error('Error handling event unsubscription', {
				connectionId,
				error: error instanceof Error ? error.message : String(error),
			});
			this.sendError(ws, 'Failed to unsubscribe from events', connectionId);
		}
	}

	/**
	 * Send error response to WebSocket client
	 */
	private sendError(ws: WebSocket, message: string, connectionId?: string): void {
		try {
			const errorResponse: WebSocketResponse = {
				event: 'error',
				error: message,
				data: {
					message,
					code: 'WEBSOCKET_ERROR',
					timestamp: Date.now(),
					...(connectionId && { connectionId }),
				},
				timestamp: Date.now(),
			};

			if (ws.readyState === WebSocket.OPEN) {
				ws.send(JSON.stringify(errorResponse));
			}

			logger.warn('WebSocket error sent to client', {
				connectionId,
				message,
			});
		} catch (error) {
			logger.error('Failed to send error response', {
				connectionId,
				originalMessage: message,
				sendError: error instanceof Error ? error.message : String(error),
			});
		}
	}

	/**
	 * Send response to WebSocket client
	 */
	private sendResponse(ws: WebSocket, response: WebSocketResponse): void {
		try {
			if (!response.timestamp) {
				response.timestamp = Date.now();
			}

			if (ws.readyState === WebSocket.OPEN) {
				ws.send(JSON.stringify(response));
			}
		} catch (error) {
			logger.error('Failed to send WebSocket response', {
				event: response.event,
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}

	/**
	 * Validate incoming message format
	 */
	private isValidMessage(message: any): message is WebSocketMessage {
		if (!message || typeof message !== 'object') {
			return false;
		}

		// Check required type field
		if (!message.type || typeof message.type !== 'string') {
			return false;
		}

		// Validate type values
		const validTypes = ['message', 'reset', 'subscribe', 'unsubscribe'];
		if (!validTypes.includes(message.type)) {
			return false;
		}

		// Type-specific validation
		switch (message.type) {
			case 'message':
				return (
					(typeof message.content === 'string' && message.content.length > 0) ||
					(message.imageData &&
						typeof message.imageData === 'object' &&
						message.imageData.base64 &&
						message.imageData.mimeType)
				);
			case 'reset':
				return typeof message.sessionId === 'string';
			case 'subscribe':
			case 'unsubscribe':
				return Array.isArray(message.eventTypes) && message.eventTypes.length > 0;
			default:
				return false;
		}
	}

	/**
	 * Validate event type
	 */
	private isValidEventType(eventType: string): boolean {
		const validEventTypes: WebSocketEventType[] = [
			'thinking',
			'chunk',
			'toolCall',
			'toolResult',
			'response',
			'error',
			'conversationReset',
			'memoryOperation',
			'systemMessage',
			'sessionCreated',
			'sessionEnded',
			'mcpServerConnected',
			'mcpServerDisconnected',
			'availableToolsUpdated',
		];
		return validEventTypes.includes(eventType as WebSocketEventType);
	}

	/**
	 * Get router statistics
	 */
	getStats(): {
		messagesProcessed: number;
		errorsHandled: number;
		activeSessions: number;
	} {
		return {
			messagesProcessed: this.connectionManager.getStats().totalMessagesReceived,
			errorsHandled: 0, // TODO: Track errors
			activeSessions: this.connectionManager.getActiveSessions().length,
		};
	}
}

import { WebSocket } from 'ws';

export interface WebSocketMessage {
	type: 'message' | 'reset' | 'subscribe' | 'unsubscribe';
	content?: string;
	sessionId?: string;
	stream?: boolean;
	imageData?: {
		base64: string;
		mimeType: string;
	};
	fileData?: any;
	eventTypes?: string[];
}

export interface WebSocketResponse {
	event: string;
	data?: Record<string, any>;
	sessionId?: string;
	error?: string;
	timestamp?: number;
}

export interface WebSocketConnection {
	id: string;
	ws: WebSocket;
	sessionId?: string | undefined;
	subscribedEvents: Set<string>;
	connectedAt: number;
	lastActivity: number;
}

export interface WebSocketConnectionStats {
	totalConnections: number;
	activeConnections: number;
	totalSessions: number;
	activeSessions: number;
	totalMessagesReceived: number;
	totalMessagesSent: number;
	averageConnectionDuration: number;
}

export interface WebSocketConfig {
	path?: string;
	heartbeatInterval?: number;
	connectionTimeout?: number;
	maxConnections?: number;
	maxMessageSize?: number;
	enableCompression?: boolean;
}

export type WebSocketEventType =
	| 'thinking'
	| 'chunk'
	| 'toolCall'
	| 'toolExecutionStarted'
	| 'toolExecutionProgress'
	| 'toolResult'
	| 'toolExecutionCompleted'
	| 'toolExecutionFailed'
	| 'response'
	| 'error'
	| 'conversationReset'
	| 'memoryOperation'
	| 'systemMessage'
	| 'sessionCreated'
	| 'sessionEnded'
	| 'connectionUpdated'
	| 'mcpServerConnected'
	| 'mcpServerDisconnected'
	| 'availableToolsUpdated';

export interface WebSocketEventData {
	thinking: { sessionId: string };
	chunk: {
		text: string;
		isComplete: boolean;
		sessionId: string;
		messageId?: string;
	};
	toolCall: {
		toolName: string;
		args: Record<string, any>;
		sessionId: string;
		callId?: string;
	};
	toolExecutionStarted: {
		toolName: string;
		sessionId: string;
		callId?: string;
		executionId?: string;
	};
	toolExecutionProgress: {
		toolName: string;
		progress: string;
		sessionId: string;
		callId?: string;
		executionId?: string;
	};
	toolResult: {
		toolName: string;
		result: any;
		success: boolean;
		sessionId: string;
		callId?: string;
	};
	toolExecutionCompleted: {
		toolName: string;
		success: boolean;
		sessionId: string;
		callId?: string;
		executionId?: string;
	};
	toolExecutionFailed: {
		toolName: string;
		error: string;
		sessionId: string;
		callId?: string;
		executionId?: string;
	};
	response: {
		content: string;
		sessionId: string;
		messageId?: string;
		metadata?: Record<string, any>;
	};
	error: {
		message: string;
		code?: string;
		sessionId?: string;
		stack?: string;
	};
	conversationReset: { sessionId: string };
	memoryOperation: {
		operation: 'store' | 'retrieve' | 'search';
		success: boolean;
		sessionId: string;
		details?: Record<string, any>;
	};
	systemMessage: {
		message: string;
		level: 'info' | 'warning' | 'error';
		sessionId?: string;
	};
	sessionCreated: { sessionId: string; timestamp: number };
	sessionEnded: { sessionId: string; timestamp: number };
	connectionUpdated: { connectionId: string; sessionId?: string; timestamp: number };
	mcpServerConnected: { serverName: string; capabilities: string[] };
	mcpServerDisconnected: { serverName: string; reason?: string };
	availableToolsUpdated: { tools: string[]; sessionId?: string };
}

import { describe, it, expect, beforeEach } from 'vitest';
import { CommandParser } from '../parser.js';
import { MemAgent } from '@core/index.js';
import { describe as describeMeta, it as itMeta, expect as expectMeta } from 'vitest';
import { parseMetaString } from '../cli.js';

describe('CommandParser', () => {
	let parser: CommandParser;
	let mockAgent: MemAgent;

	beforeEach(() => {
		parser = new CommandParser();
		mockAgent = {} as MemAgent; // Mock agent for testing
	});

	describe('parseInput', () => {
		it('should identify slash commands correctly', () => {
			const result = parser.parseInput('/help');
			expect(result.isCommand).toBe(true);
			expect(result.command).toBe('help');
			expect(result.args).toEqual([]);
			expect(result.rawInput).toBe('/help');
		});

		it('should parse command with arguments', () => {
			const result = parser.parseInput('/memory search test query');
			expect(result.isCommand).toBe(true);
			expect(result.command).toBe('memory');
			expect(result.args).toEqual(['search', 'test', 'query']);
		});

		it('should identify regular prompts correctly', () => {
			const result = parser.parseInput('Hello, how are you?');
			expect(result.isCommand).toBe(false);
			expect(result.command).toBeUndefined();
			expect(result.args).toBeUndefined();
			expect(result.rawInput).toBe('Hello, how are you?');
		});

		it('should handle empty commands', () => {
			const result = parser.parseInput('/');
			expect(result.isCommand).toBe(true);
			expect(result.command).toBe('');
			expect(result.args).toEqual([]);
		});

		it('should filter out empty parts', () => {
			const result = parser.parseInput('/help   arg1    arg2   ');
			expect(result.isCommand).toBe(true);
			expect(result.command).toBe('help');
			expect(result.args).toEqual(['arg1', 'arg2']);
		});
	});

	describe('getCommandSuggestions', () => {
		it('should return suggestions for partial command names', () => {
			const suggestions = parser.getCommandSuggestions('he');
			expect(suggestions.some(s => s.name === 'help')).toBe(true);
		});

		it('should return suggestions for aliases', () => {
			const suggestions = parser.getCommandSuggestions('h');
			expect(suggestions.some(s => s.name === 'h')).toBe(true);
		});

		it('should return empty array for non-matching partial', () => {
			const suggestions = parser.getCommandSuggestions('xyz');
			expect(suggestions).toEqual([]);
		});

		it('should sort suggestions alphabetically', () => {
			const suggestions = parser.getCommandSuggestions('');
			const names = suggestions.map(s => s.name);
			const sortedNames = [...names].sort();
			expect(names).toEqual(sortedNames);
		});
	});

	describe('hasCommand', () => {
		it('should return true for existing commands', () => {
			expect(parser.hasCommand('help')).toBe(true);
			expect(parser.hasCommand('clear')).toBe(true);
		});

		it('should return true for aliases', () => {
			expect(parser.hasCommand('h')).toBe(true);
			expect(parser.hasCommand('?')).toBe(true);
		});

		it('should return false for non-existing commands', () => {
			expect(parser.hasCommand('nonexistent')).toBe(false);
		});
	});

	describe('registerCommand', () => {
		it('should register new commands', () => {
			const testCommand = {
				name: 'test',
				description: 'Test command',
				handler: async () => true,
			};

			parser.registerCommand(testCommand);
			expect(parser.hasCommand('test')).toBe(true);
		});

		it('should register command aliases', () => {
			const testCommand = {
				name: 'test',
				description: 'Test command',
				aliases: ['t', 'testing'],
				handler: async () => true,
			};

			parser.registerCommand(testCommand);
			expect(parser.hasCommand('test')).toBe(true);
			expect(parser.hasCommand('t')).toBe(true);
			expect(parser.hasCommand('testing')).toBe(true);
		});
	});

	describe('formatCommandHelp', () => {
		it('should format basic help correctly', () => {
			const help = parser.formatCommandHelp('help', false);
			expect(help).toContain('/help');
			expect(help).toContain('Show help information');
		});

		it('should format detailed help correctly', () => {
			const help = parser.formatCommandHelp('help', true);
			expect(help).toContain('/help');
			expect(help).toContain('Usage:');
			expect(help).toContain('Aliases:');
		});

		it('should handle non-existent commands', () => {
			const help = parser.formatCommandHelp('nonexistent');
			expect(help).toContain('Command not found');
		});
	});

	describe('command execution', () => {
		it('should execute help command successfully', async () => {
			const result = await parser.executeCommand('help', [], mockAgent);
			expect(result).toBe(true);
		});

		it('should handle unknown commands', async () => {
			const result = await parser.executeCommand('unknown', [], mockAgent);
			expect(result).toBe(false);
		});

		it('should resolve aliases correctly', async () => {
			const result = await parser.executeCommand('h', [], mockAgent);
			expect(result).toBe(true);
		});
	});

	describe('built-in commands', () => {
		it('should have core commands registered', () => {
			const expectedCommands = ['help', 'clear', 'config', 'stats', 'tools', 'prompt', 'exit'];

			for (const cmd of expectedCommands) {
				expect(parser.hasCommand(cmd)).toBe(true);
			}
		});

		it('should have help command aliases', () => {
			expect(parser.hasCommand('h')).toBe(true);
			expect(parser.hasCommand('?')).toBe(true);
		});

		it('should have exit command aliases', () => {
			expect(parser.hasCommand('quit')).toBe(true);
			expect(parser.hasCommand('q')).toBe(true);
		});

		it('should have clear command aliases', () => {
			expect(parser.hasCommand('reset')).toBe(true);
		});
	});
});

describeMeta('parseMetaString', () => {
	itMeta('parses single key-value pair', () => {
		const result = parseMetaString('foo=bar');
		expectMeta(result).toEqual({ foo: 'bar' });
	});

	itMeta('parses multiple key-value pairs', () => {
		const result = parseMetaString('foo=bar,baz=qux');
		expectMeta(result).toEqual({ foo: 'bar', baz: 'qux' });
	});

	itMeta('trims spaces around keys and values', () => {
		const result = parseMetaString(' foo = bar , baz = qux ');
		expectMeta(result).toEqual({ foo: 'bar', baz: 'qux' });
	});

	itMeta('returns empty object for empty string', () => {
		const result = parseMetaString('');
		expectMeta(result).toEqual({});
	});

	itMeta('throws error for missing value', () => {
		expectMeta(() => parseMetaString('foo=')).toThrow();
	});

	itMeta('throws error for missing key', () => {
		expectMeta(() => parseMetaString('=bar')).toThrow();
	});

	itMeta('throws error for missing =', () => {
		expectMeta(() => parseMetaString('foobar')).toThrow();
	});
});

import { MemAgent, logger } from '@core/index.js';
import * as readline from 'readline';
import chalk from 'chalk';
import { executeCommand } from './commands.js';
import { commandParser } from './parser.js';
import type { AggregatorConfig } from '@core/mcp/types.js';

// Constants for compression display
const COMPRESSION_CHECK_DELAY = 100;

// State tracking for compression display
let lastCompressionHistoryLength = 0;

/**
 * Start headless CLI mode for one-shot command execution
 * @param agent - The MemAgent instance
 * @param input - The user input/prompt to execute
 */
export async function startHeadlessCli(agent: MemAgent, input: string): Promise<void> {
	await _initCli(agent);

	if (input.trim().startsWith('!meta ')) {
		const metaAndMessage = input.trim().substring(6).split(' ');
		const metaStr = metaAndMessage[0];
		const message = metaAndMessage.slice(1).join(' ');
		let metadata: Record<string, any> = {};
		try {
			// Add null check for metaStr before passing to parseMetaString
			if (metaStr) {
				metadata = parseMetaString(metaStr);
			}
		} catch {
			console.log(chalk.red('❌ Invalid metadata format. Use key=value,key2=value2 ...'));
			return;
		}
		console.log(chalk.gray('🤔 Processing (with metadata)...'));
		const result = await agent.run(message, undefined, undefined, false, {
			memoryMetadata: metadata,
		});
		if (result && result.backgroundOperations) {
			try {
				await result.backgroundOperations;
			} catch {
				/* no-op: background operation errors are intentionally ignored */
			}
		}
		if (result && result.response) {
			logger.displayAIResponse(result.response);
		} else {
			console.log(chalk.gray('No response received.'));
		}
	} else {
		console.log(chalk.gray('🤔 Processing...'));
		const result = await agent.run(input);
		if (result && result.backgroundOperations) {
			try {
				await result.backgroundOperations;
			} catch {
				/* no-op: background operation errors are intentionally ignored */
			}
		}
		if (result && result.response) {
			logger.displayAIResponse(result.response);
		} else {
			console.log(chalk.gray('No response received.'));
		}
	}
}

/**
 * Start interactive CLI mode where user can continuously chat with the agent
 */
export async function startInteractiveCli(agent: MemAgent): Promise<void> {
	// Common initialization
	await _initCli(agent);
	await _initializeSessionAndCompression(agent);

	console.log(chalk.cyan('🚀 Welcome to Cipher Interactive CLI!'));
	console.log(chalk.gray('Your memory-powered coding assistant is ready.'));
	console.log(chalk.gray('• Type /help to see available commands'));
	console.log(chalk.gray('• Use /exit or /quit to end the session'));
	console.log(chalk.gray('• Regular messages will be sent to the AI agent\n'));

	const rl = readline.createInterface({
		input: process.stdin,
		output: process.stdout,
		prompt: chalk.blue('cipher> '),
	});

	// Set up graceful shutdown
	const handleExit = () => {
		console.log(chalk.yellow('\n👋 Goodbye! Your conversation has been saved to memory.'));
		rl.close();
		process.exit(0);
	};

	rl.on('SIGINT', handleExit);
	rl.on('SIGTERM', handleExit);

	rl.prompt();

	rl.on('line', async (input: string) => {
		const trimmedInput = input.trim();

		// Skip empty inputs
		if (!trimmedInput) {
			rl.prompt();
			return;
		}

		try {
			// Parse input to determine if it's a command or regular prompt
			if (trimmedInput.startsWith('!meta ')) {
				// Parse metadata command: !meta key=value,key2=value2 message
				const metaAndMessage = trimmedInput.substring(6).split(' ');
				const metaStr = metaAndMessage[0];
				const message = metaAndMessage.slice(1).join(' ');
				let metadata: Record<string, any> = {};
				try {
					// Add null check for metaStr before passing to parseMetaString
					if (metaStr) {
						metadata = parseMetaString(metaStr);
					}
				} catch {
					console.log(chalk.red('❌ Invalid metadata format. Use key=value,key2=value2 ...'));
					rl.prompt();
					return;
				}
				console.log(chalk.gray('🤔 Thinking (with metadata)...'));
				const result = await agent.run(message, undefined, undefined, false, {
					memoryMetadata: metadata,
				});
				if (result && result.backgroundOperations) {
					try {
						await result.backgroundOperations;
					} catch {
						/* no-op: background operation errors are intentionally ignored */
					}
				}
				if (result && result.response) {
					logger.displayAIResponse(result.response);
				} else {
					console.log(chalk.gray('No response received.'));
				}

				// Show compression info after processing
				await _showCompressionInfo(agent);

				// At info log level, display prompt immediately and let background operations run silently
				if (result && result.backgroundOperations) {
					// Check if we're at info log level or higher (info level = 2, anything higher means less verbose)
					const currentLogLevel = process.env.CIPHER_LOG_LEVEL || 'info';
					const isInfoLevelOrHigher = ['error', 'warn', 'info'].includes(currentLogLevel);

					if (isInfoLevelOrHigher) {
						// At info level, show prompt immediately
						rl.prompt();

						// Let background operations run silently in the background
						result.backgroundOperations.catch(() => {
							// Background operation errors are intentionally ignored at info level
						});
					} else {
						// At debug/verbose levels, wait for background operations to complete
						result.backgroundOperations
							.catch(() => {
								// Background operations failures are already logged, don't show to user
							})
							.finally(() => {
								// Small delay to ensure any error logs are fully written before redisplaying prompt
								setTimeout(() => {
									rl.prompt();
								}, COMPRESSION_CHECK_DELAY);
							});
					}
				} else {
					rl.prompt();
				}
			} else {
				const parsedInput = commandParser.parseInput(trimmedInput);

				if (parsedInput.isCommand) {
					// Handle slash command
					if (parsedInput.command && parsedInput.args !== undefined) {
						const commandSuccess = await executeCommand(
							parsedInput.command,
							parsedInput.args,
							agent
						);

						if (!commandSuccess) {
							console.log(chalk.gray('Command execution failed or was cancelled.'));
						}
					} else {
						console.log(chalk.red('❌ Invalid command format'));
						commandParser.displayHelp();
					}
					// Always redisplay prompt after slash commands
					rl.prompt();
				} else {
					// Handle regular user prompt - pass to agent
					console.log(chalk.gray('🤔 Thinking...'));
					const result = await agent.run(trimmedInput);

					// Display the AI response immediately
					if (result && result.response) {
						// Display the AI response with nice formatting
						logger.displayAIResponse(result.response);
					} else {
						console.log(chalk.gray('No response received.'));
					}

					// Show compression info after processing
					await _showCompressionInfo(agent);

					// At info log level, display prompt immediately and let background operations run silently
					if (result && result.backgroundOperations) {
						// Check if we're at info log level or higher (info level = 2, anything higher means less verbose)
						const currentLogLevel = process.env.CIPHER_LOG_LEVEL || 'info';
						const isInfoLevelOrHigher = ['error', 'warn', 'info'].includes(currentLogLevel);

						if (isInfoLevelOrHigher) {
							// At info level, show prompt immediately
							rl.prompt();

							// Let background operations run silently in the background
							result.backgroundOperations.catch(() => {
								// Background operation errors are intentionally ignored at info level
							});
						} else {
							// At debug/verbose levels, wait for background operations to complete
							result.backgroundOperations
								.catch(() => {
									// Background operations failures are already logged, don't show to user
								})
								.finally(() => {
									// Small delay to ensure any error logs are fully written before redisplaying prompt
									setTimeout(() => {
										rl.prompt();
									}, COMPRESSION_CHECK_DELAY);
								});
						}
					} else {
						rl.prompt();
					}
				}
			}
		} catch (error) {
			logger.error(
				`Error processing input: ${error instanceof Error ? error.message : String(error)}`
			);
			rl.prompt();
		}
	});

	rl.on('close', () => {
		console.log(chalk.yellow('\n👋 Session ended. Your conversation has been saved to memory.'));
		process.exit(0);
	});
}

/**
 * Start MCP server mode for Model Context Protocol integration
 */
export async function startMcpMode(agent: MemAgent, opts?: any): Promise<void> {
	// DO NOT use console.log in MCP mode - it interferes with stdio protocol
	// Log redirection is already done in index.ts before calling this function

	// Initialize CLI without additional logging
	if (!agent) {
		throw new Error('Agent is not initialized');
	}

	// Check MCP_SERVER_MODE environment variable to determine server type
	// Default to 'default' if not specified (backward compatibility)
	const mcpServerMode = process.env.MCP_SERVER_MODE || 'default';

	try {
		switch (mcpServerMode) {
			case 'aggregator':
				await startAggregatorMode(agent, opts);
				break;
			case 'default':
			default:
				await startDefaultMcpMode(agent, opts);
				break;
		}
	} catch (error) {
		const errorMessage = error instanceof Error ? error.message : String(error);
		logger.error(`[MCP Mode] Failed to start MCP server (mode: ${mcpServerMode}): ${errorMessage}`);
		process.exit(1);
	}
}

/**
 * Start the default MCP server mode with ask_cipher tool
 */
async function startDefaultMcpMode(agent: MemAgent, opts?: any): Promise<void> {
	// Import MCP handler functions
	const { createMcpTransport, initializeMcpServer, initializeAgentCardResource } = await import(
		'../mcp/mcp_handler.js'
	);

	// Get agent configuration for agent card
	const config = agent.getEffectiveConfig();
	// Filter out undefined properties to comply with exactOptionalPropertyTypes
	const agentCardInput = config.agentCard
		? Object.fromEntries(
				Object.entries(config.agentCard).filter(([, value]) => value !== undefined)
			)
		: {};
	const agentCardData = initializeAgentCardResource(agentCardInput);

	// Get transport type and configuration from CLI options
	const transportType = opts?.mcpTransportType || 'stdio';
	const mcpPort = opts?.mcpPort ? parseInt(opts.mcpPort, 10) : undefined;
	const mcpHost = opts?.mcpHost || 'localhost';
	const mcpDnsRebindingProtection = opts?.mcpDnsRebindingProtection || false;

	// Initialize MCP server with agent capabilities (default mode)
	logger.info('[MCP Mode] Initializing default MCP server with agent capabilities');
	const server = await initializeMcpServer(agent, agentCardData, 'default');

	// Create transport for MCP mode
	logger.info(`[MCP Mode] Creating ${transportType} transport for default MCP server`);
	const mcpTransportResult = await createMcpTransport(
		transportType,
		mcpPort,
		server,
		mcpHost,
		mcpDnsRebindingProtection
	);

	// Handle transport connection based on type
	if (transportType === 'stdio') {
		// For stdio, connect server to transport
		await server.connect(mcpTransportResult.server);
	} else {
		// For HTTP-based transports (SSE/streamable-http), the HTTP server handles connections
		// The server is already connected via the HTTP server setup
		logger.info(`[MCP Mode] HTTP server started for ${transportType} transport`);
	}

	// Set up graceful shutdown handling
	let isShuttingDown = false;
	const handleShutdown = async () => {
		if (isShuttingDown) return;
		isShuttingDown = true;

		logger.info('[MCP Mode] Shutting down default MCP server...');

		if (mcpTransportResult.cleanup) {
			try {
				await mcpTransportResult.cleanup();
			} catch (error) {
				logger.error(
					'[MCP Mode] Error during cleanup:',
					error instanceof Error ? error.message : String(error)
				);
			}
		}

		logger.info('[MCP Mode] Default MCP server stopped');
		process.exit(0);
	};

	// Register shutdown handlers
	process.on('SIGTERM', handleShutdown);
	process.on('SIGINT', handleShutdown);

	// Server is now running - keep process alive
	logger.info('[MCP Mode] Cipher agent is now running as default MCP server');

	if (transportType === 'stdio') {
		process.stdin.resume();
	} else {
		// For HTTP transports, keep the event loop active
		setInterval(() => {}, 1000);
	}
}

