/**
 * Load aggregator configuration from environment variables
 * Aggregator mode now uses agent's unifiedToolManager which automatically includes MCP servers from cipher.yml
 */
async function loadAggregatorConfig(): Promise<AggregatorConfig> {
	const defaultConfig: AggregatorConfig = {
		type: 'aggregator',
		servers: {}, // No longer needed - using unifiedToolManager
		conflictResolution: (process.env.AGGREGATOR_CONFLICT_RESOLUTION as any) || 'prefix',
		autoDiscovery: false,
		timeout: parseInt(process.env.AGGREGATOR_TIMEOUT || '60000'),
		connectionMode: 'lenient',
	};

	logger.info('[MCP Aggregator] Using simplified configuration with env vars', {
		conflictResolution: defaultConfig.conflictResolution,
		timeout: defaultConfig.timeout,
	});
	return defaultConfig;
}

/**
 * Common CLI initialization logic
 */
async function _initCli(agent: MemAgent): Promise<void> {
	logger.info('Initializing CLI interface...');

	// Ensure agent is started
	if (!agent) {
		throw new Error('Agent is not initialized');
	}

	logger.info('CLI interface ready');
}

/**
 * Initialize session and display compression startup info (only for interactive mode)
 */
async function _initializeSessionAndCompression(agent: MemAgent): Promise<void> {
	// Wait a bit for session to be ready
	await new Promise(resolve => setTimeout(resolve, 50));

	const session = await agent.getSession(agent.getCurrentSessionId());

	if (session && typeof session.init === 'function') {
		await session.init();
	}

	// Wait a bit more for compression system to be fully initialized
	await new Promise(resolve => setTimeout(resolve, 50));

	await _showCompressionStartup(agent);
	await new Promise(res => process.stderr.write('', res));
}

/**
 * Show compression system startup information
 */
async function _showCompressionStartup(agent: MemAgent): Promise<void> {
	try {
		const session = await agent.getSession(agent.getCurrentSessionId());

		if (!session) {
			// Session not ready yet, skip compression info silently
			return;
		}

		const ctx = session.getContextManager();
		if (!ctx) {
			return;
		}

		const stats = ctx.getTokenStats();

		if (stats.maxTokens > 0) {
			console.log(chalk.green('🧠 Token-Aware Compression System is ACTIVE'));
			console.log(
				chalk.gray(
					`• Max tokens: ${stats.maxTokens}, Compression strategy: ${ctx['compressionStrategy']?.name || 'unknown'}`
				)
			);

			lastCompressionHistoryLength = ctx['compressionHistory']?.length || 0;
		}
	} catch {
		// Intentionally empty - compression info is optional
	}
}

/**
 * Show compression info after each interaction
 */
async function _showCompressionInfo(agent: MemAgent): Promise<void> {
	try {
		const session = await agent.getSession(agent.getCurrentSessionId());

		if (!session) {
			return;
		}

		const ctx = session.getContextManager();
		const history = ctx['compressionHistory'];

		if (Array.isArray(history) && history.length > lastCompressionHistoryLength) {
			const _event = history[history.length - 1];
			_displayCompressionEvent(_event);
			lastCompressionHistoryLength = history.length;
		}
	} catch {
		// Intentionally empty - compression info is optional
	}
}

/**
 * Display compression event information
 */
function _displayCompressionEvent(_event: any): void {
	console.log(chalk.yellowBright('⚡ Context has been compressed.'));
}

// Add utility for parsing metadata from CLI
export function parseMetaString(metaStr: string): Record<string, any> {
	const metadata: Record<string, any> = {};
	if (!metaStr) return metadata;
	const pairs = metaStr.split(',');
	for (const pair of pairs) {
		const [key, value] = pair.split('=');
		if (!key || value === undefined || value === '') {
			throw new Error('Invalid metadata pair');
		}
		metadata[key.trim()] = value.trim();
	}
	return metadata;
}

import { MemAgent } from '@core/index.js';
import { commandParser } from './parser.js';

/**
 * Cipher slash command execution
 * This function integrates with the command parser to handle slash commands
 */
export async function executeCommand(
	command: string,
	args: string[],
	agent: MemAgent
): Promise<boolean> {
	return await commandParser.executeCommand(command, args, agent);
}

import chalk from 'chalk';
import { MemAgent } from '@core/index.js';
import { EnhancedPromptManager } from '@core/brain/systemPrompt/enhanced-manager.js';

/**
 * Interface for command execution results
 */
export interface CommandResult {
	success: boolean;
	message?: string;
	data?: any;
}

/**
 * Interface for command definition with hierarchical support
 */
export interface CommandDefinition {
	name: string;
	description: string;
	usage?: string;
	aliases?: string[];
	category?: string;
	handler: (args: string[], agent: MemAgent) => Promise<boolean>;
	subcommands?: CommandDefinition[];
}

/**
 * Input classification result
 */
export interface ParsedInput {
	isCommand: boolean;
	command?: string;
	args?: string[];
	rawInput: string;
}

/**
 * Command suggestion for auto-completion
 */
export interface CommandSuggestion {
	name: string;
	description: string;
	category?: string;
}

/**
 * Comprehensive command parser for Cipher CLI
 */
export class CommandParser {
	private commands: Map<string, CommandDefinition> = new Map();
	private aliases: Map<string, string> = new Map();

	constructor() {
		this.initializeCommands();
	}

	/**
	 * Parse input to determine if it's a command or regular prompt
	 */
	parseInput(input: string): ParsedInput {
		const trimmed = input.trim();

		// Check if input starts with slash (command indicator)
		if (trimmed.startsWith('/')) {
			// Parse as slash command
			const parts = trimmed
				.slice(1)
				.split(' ')
				.filter(part => part.length > 0);
			const command = parts[0] || '';
			const args = parts.slice(1);

			return {
				isCommand: true,
				command,
				args,
				rawInput: input,
			};
		} else {
			// Treat as regular user prompt
			return {
				isCommand: false,
				rawInput: input,
			};
		}
	}

	/**
	 * Execute a parsed command
	 */
	async executeCommand(command: string, args: string[], agent: MemAgent): Promise<boolean> {
		try {
			const commandDef =
				this.commands.get(command) || this.commands.get(this.aliases.get(command) || '');
			if (!commandDef) {
				console.log(chalk.red(`❌ Unknown command: /${command}`));
				console.log(chalk.gray('💡 Use /help to see all available commands'));
				return false;
			}

			// Handle subcommands
			if (commandDef.subcommands && args.length > 0) {
				const subcommandName = args[0];
				if (subcommandName) {
					// Add null check
					const subcommand = commandDef.subcommands.find(
						sub => sub.name === subcommandName || sub.aliases?.includes(subcommandName)
					);

					if (subcommand) {
						return await subcommand.handler(args.slice(1), agent);
					}
				}
			}

			return await commandDef.handler(args, agent);
		} catch (error) {
			console.log(
				chalk.red(
					`❌ Error executing command /${command}: ${error instanceof Error ? error.message : String(error)}`
				)
			);
			return false;
		}
	}

	/**
	 * Get command suggestions for auto-completion
	 */
	getCommandSuggestions(partial: string): CommandSuggestion[] {
		const suggestions: CommandSuggestion[] = [];

		// Check main commands
		for (const [name, definition] of this.commands) {
			if (name.startsWith(partial)) {
				suggestions.push({
					name,
					description: definition.description,
					category: definition.category || 'uncategorized', // Add fallback for undefined
				});
			}
		}

		// Check aliases
		for (const [alias, actualCommand] of this.aliases) {
			if (alias.startsWith(partial)) {
				const commandDef = this.commands.get(actualCommand);
				if (commandDef) {
					suggestions.push({
						name: alias,
						description: `${commandDef.description} (alias)`,
						category: commandDef.category || 'uncategorized', // Add fallback for undefined
					});
				}
			}
		}

		// Sort suggestions alphabetically
		return suggestions.sort((a, b) => a.name.localeCompare(b.name));
	}

	/**
	 * Format command help - supports both basic and detailed modes
	 */
	formatCommandHelp(commandName: string, detailed: boolean = false): string {
		const commandDef = this.commands.get(commandName);
		if (!commandDef) {
			return chalk.red(`Command not found: ${commandName}`);
		}

		let help = chalk.cyan(`/${commandName}`) + ` - ${commandDef.description}`;

		if (detailed) {
			if (commandDef.usage) {
				help += `\n  ${chalk.yellow('Usage:')} ${commandDef.usage}`;
			}

			if (commandDef.aliases && commandDef.aliases.length > 0) {
				help += `\n  ${chalk.yellow('Aliases:')} ${commandDef.aliases.map(a => chalk.cyan(`/${a}`)).join(', ')}`;
			}

			if (commandDef.subcommands && commandDef.subcommands.length > 0) {
				help += `\n  ${chalk.yellow('Subcommands:')}`;
				for (const sub of commandDef.subcommands) {
					help += `\n    ${chalk.cyan(`/${commandName} ${sub.name}`)} - ${sub.description}`;
				}
			}
		}

		return help;
	}

	/**
	 * Display all commands in categorized format
	 */
	displayAllCommands(): void {
		// Define category order
		const categoryOrder = ['basic', 'memory', 'session', 'tools', 'system', 'help'];

		// Initialize empty categories
		const categorizedCommands: Map<string, CommandDefinition[]> = new Map();
		const uncategorizedCommands: CommandDefinition[] = [];

		// Initialize categories
		categoryOrder.forEach(cat => categorizedCommands.set(cat, []));

		// Categorize each command
		for (const commandDef of this.commands.values()) {
			const category = commandDef.category || 'uncategorized';
			if (categorizedCommands.has(category)) {
				categorizedCommands.get(category)!.push(commandDef);
			} else {
				uncategorizedCommands.push(commandDef);
			}
		}

		console.log(chalk.cyan('\n📋 Available Commands:\n'));

		// Display in predefined order
		for (const category of categoryOrder) {
			const commands = categorizedCommands.get(category);
			if (commands && commands.length > 0) {
				console.log(chalk.yellow(`${category.toUpperCase()}:`));
				for (const cmd of commands.sort((a, b) => a.name.localeCompare(b.name))) {
					console.log(`  ${this.formatCommandHelp(cmd.name, false)}`);
				}
				console.log('');
			}
		}

		// Show uncategorized commands last
		if (uncategorizedCommands.length > 0) {
			console.log(chalk.yellow('OTHER:'));
			for (const cmd of uncategorizedCommands.sort((a, b) => a.name.localeCompare(b.name))) {
				console.log(`  ${this.formatCommandHelp(cmd.name, false)}`);
			}
			console.log('');
		}

		console.log(
			chalk.gray('💡 Use /help <command> for detailed information about a specific command')
		);
		console.log(chalk.gray('💡 Use <Tab> for command auto-completion'));
	}

	/**
	 * Display basic help information
	 */
	displayHelp(commandName?: string): void {
		if (commandName) {
			console.log('\n' + this.formatCommandHelp(commandName, true) + '\n');
		} else {
			this.displayAllCommands();
		}
	}

	/**
	 * Register a new command
	 */
	registerCommand(definition: CommandDefinition): void {
		this.commands.set(definition.name, definition);

		// Register aliases
		if (definition.aliases) {
			for (const alias of definition.aliases) {
				this.aliases.set(alias, definition.name);
			}
		}
	}

	/**
	 * Check if a command exists
	 */
	hasCommand(command: string): boolean {
		return this.commands.has(command) || this.aliases.has(command);
	}

	/**
	 * Get all registered commands
	 */
	getAllCommands(): CommandDefinition[] {
		return Array.from(this.commands.values());
	}

	/**
	 * Initialize built-in commands
