							console.log(chalk.yellow('📈 **Per-Provider Breakdown**'));
							for (const r of result.providerResults) {
								console.log(
									`   - ${r.providerId}: ${r.success ? '✅' : '❌'} | ${r.generationTimeMs} ms | ${r.content.length} chars`
