/**
 * Global command parser instance
 */
export const commandParser = new CommandParser();

import { z } from 'zod';
import { logger } from '@core/index.js';

export function validateCliOptions(opts: any): void {
	// Remove debug logging for CLI validation to reduce noise
	const cliOptionShape = z.object({
		verbose: z.boolean().optional().default(true),
		mode: z
			.enum(['cli', 'mcp', 'api', 'ui'], {
				errorMap: () => ({ message: 'Mode must be either cli, mcp, api, or ui' }),
			})
			.optional()
			.default('cli'),
		strict: z.boolean().optional().default(false),
		newSession: z.union([z.boolean(), z.string()]).optional(),
		port: z.string().optional(),
		uiPort: z.string().optional(),
		host: z.string().optional(),
		mcpTransportType: z
			.enum(['stdio', 'sse', 'streamable-http'], {
				errorMap: () => ({ message: 'MCP transport type must be stdio, sse, or streamable-http' }),
			})
			.optional()
			.default('stdio'),
		mcpPort: z.string().optional(),
		mcpHost: z.string().optional(),
		mcpDnsRebindingProtection: z.boolean().optional(),
	});

	const cliOptionSchema = cliOptionShape;

	const result = cliOptionSchema.safeParse({
		verbose: opts.verbose,
		mode: opts.mode,
		strict: opts.strict,
		newSession: opts.newSession,
		port: opts.port,
		uiPort: opts.uiPort,
		host: opts.host,
		mcpTransportType: opts.mcpTransportType,
		mcpPort: opts.mcpPort,
		mcpHost: opts.mcpHost,
		mcpDnsRebindingProtection: opts.mcpDnsRebindingProtection,
	});

	if (!result.success) {
		throw result.error;
	}

	// CLI options validated - no logging to reduce noise
}

export function handleCliOptionsError(error: unknown): never {
	if (error instanceof z.ZodError) {
		logger.error('Invalid command-line options detected:');
		error.errors.forEach(err => {
			const fieldName = err.path.join('.') || 'Unknown Option';
			logger.error(`- Option '${fieldName}': ${err.message}`);
		});
		logger.error('Please check your command-line arguments or run with --help for usage details.');
	} else {
		logger.error(
			`Validation error: ${error instanceof Error ? error.message : JSON.stringify(error)}`
		);
	}
	process.exit(1);
}

#!/usr/bin/env node

// Fix EventTarget memory leak by setting max listeners early
import { EventEmitter } from 'events';
EventEmitter.defaultMaxListeners = 20;

// Increase AbortSignal max listeners to prevent memory leak warnings
if (typeof globalThis !== 'undefined' && globalThis.EventTarget) {
	const originalAddEventListener = globalThis.EventTarget.prototype.addEventListener;
	const listenerCounts = new WeakMap();

	globalThis.EventTarget.prototype.addEventListener = function (type, listener, options) {
		if (type === 'abort' && this.constructor.name === 'AbortSignal') {
			const currentCount = listenerCounts.get(this) || 0;
			if (currentCount >= 15) {
				console.warn(`AbortSignal has ${currentCount} listeners, potential memory leak`);
			}
			listenerCounts.set(this, currentCount + 1);
		}
		return originalAddEventListener.call(this, type, listener, options);
	};
}

import { env } from '@core/env.js';
import { Command } from 'commander';
import pkg from '../../package.json' with { type: 'json' };
import { existsSync } from 'fs';
import { DEFAULT_CONFIG_PATH, logger, MemAgent } from '@core/index.js';
import { resolveConfigPath } from '@core/utils/path.js';
import { handleCliOptionsError, validateCliOptions } from './cli/utils/options.js';
import { loadAgentConfig } from '../core/brain/memAgent/loader.js';
import { startInteractiveCli, startHeadlessCli, startMcpMode } from './cli/cli.js';
import { ApiServer } from './api/server.js';
import { WebServerManager } from './web/web-server.js';
import path from 'path';
import os from 'os';
import { fileURLToPath } from 'url';

// Helper function to resolve .env file path
function resolveEnvPath(): string {
	// Try current working directory first
	if (existsSync('.env')) {
		return '.env';
	}

	// Try relative to project root (where package.json is located)
	const currentFileUrl = import.meta.url;
	const currentFilePath = fileURLToPath(currentFileUrl);
	const projectRoot = path.resolve(path.dirname(currentFilePath), '../..');
	const envPath = path.resolve(projectRoot, '.env');

	return envPath;
}

// ===== EARLY MCP MODE DETECTION AND LOG REDIRECTION =====
// Following Cipher's best practices to prevent stdio interference
// This must happen BEFORE any logging operations
const detectAndRedirectMcpLogs = () => {
	const args = process.argv;
	const isMcpMode = args.includes('--mode') && args[args.indexOf('--mode') + 1] === 'mcp';

	if (isMcpMode) {
		// Redirect logs immediately to prevent stdout contamination
		const logFile = process.env.CIPHER_MCP_LOG_FILE || path.join(os.tmpdir(), 'cipher-mcp.log');
		logger.redirectToFile(logFile);

		// Use stderr for critical startup messages only
		process.stderr.write(`[CIPHER-MCP] Log redirection activated: ${logFile}\n`);
	}
};

// Apply early redirection before any other operations
detectAndRedirectMcpLogs();

const program = new Command();

program
	.name('cipher')
	.description(
		'Memory-powered AI agent framework with real-time WebSocket communication and MCP integration'
	)
	.version(pkg.version, '-v, --version', 'output the current version')
	.argument(
		'[prompt...]',
		'Natural-language prompt to run once. If not passed, cipher will start in interactive mode'
	)
	.option('--no-verbose', 'Disable verbose output')
	.option('-a, --agent <path>', 'Path to agent config file', DEFAULT_CONFIG_PATH)
	.option('-s, --strict', 'Require all MCP server connections to succeed')
	.option('--new-session [sessionId]', 'Start with a new session (optionally specify session ID)')
	.option(
		'--mode <mode>',
		'The application mode for cipher memory agent - cli | mcp | api | ui',
		'cli'
	)
	.option('--port <port>', 'Port for API server (only used with --mode api or ui)', '3001')
	.option('--ui-port <port>', 'Port for UI server (only used with --mode ui)', '3000')
	.option('--host <host>', 'Host for API server (only used with --mode api or ui)', 'localhost')
	.option(
		'--api-prefix <prefix>',
		'API prefix for routes (default: /api, use empty string to disable)',
		'/api'
	)
	.option(
		'--mcp-transport-type <type>',
		'MCP transport type (stdio, sse, streamable-http)',
		'stdio'
	)
	.option('--mcp-port <port>', 'Port for MCP server (only used with sse, streamable-http)', '3000')
	.option(
		'--mcp-host <host>',
		'Host for MCP server (only used with sse, streamable-http)',
		'localhost'
	)
	.option(
		'--mcp-dns-rebinding-protection',
		'Enable DNS rebinding protection for MCP server',
		false
	);

program
	.description(
		'Cipher CLI allows you to interact with cipher memory agent.\n' +
			'Run cipher in interactive mode with `cipher` or run a one-shot prompt with `cipher <prompt>`\n\n' +
			'Available modes:\n' +
			'  - cli: Interactive command-line interface (default)\n' +
			'  - mcp: Model Context Protocol server mode\n' +
			'  - api: REST API server mode with WebSocket support\n' +
			'  - ui: Full-stack web application with UI and API server\n\n' +
			'WebSocket Features (API mode):\n' +
			'  • Real-time AI responses and streaming\n' +
			'  • Live tool execution notifications\n' +
			'  • Memory operation events\n' +
			'  • Session management and error handling\n' +
			'  • Available at ws://localhost:3001/ws\n\n' +
			'Options:\n' +
			'  -s, --strict: Require all MCP server connections to succeed (overrides individual server connection modes)\n' +
			'  --new-session [sessionId]: Start with a new session (optionally specify session ID)\n' +
			'  --port <port>: Port for API server (default: 3001, only used with --mode api or ui)\n' +
			'  --ui-port <port>: Port for UI server (default: 3000, only used with --mode ui)\n' +
			'  --host <host>: Host for API server (default: localhost, only used with --mode api or ui)'
	)
	/**
	 * Main CLI action handler for the Cipher agent.
	 *
	 * Strict Mode Behavior:
	 * When the --strict flag is used, all MCP server connectionMode properties
	 * are overridden to 'strict', requiring all server connections to succeed.
	 * This takes precedence over individual server configuration settings.
	 *
	 * If any MCP server fails to connect in strict mode, the application will
	 * exit with an error. Without strict mode, failed connections are logged
	 * as warnings but don't prevent startup.
	 *
	 * New Session Behavior:
	 * When the --new-session flag is used, a new conversation session is created
	 * and made available for the CLI interaction. The session ID parameter is optional:
	 * - --new-session: Creates a session with auto-generated UUID
	 * - --new-session mySessionId: Creates a session with the specified ID
	 *
	 * Created sessions persist for the duration of the CLI session and follow
	 * the agent's session management lifecycle and TTL settings.
	 *
	 * One-Shot Mode Behavior:
	 * When prompt arguments are provided, cipher runs in headless mode:
	 * - Executes the prompt once and exits
	 * - Works with all existing flags and options
	 * - Example: cipher "help me debug this error"
	 */
	.action(async (prompt: string[] = []) => {
		// Process prompt arguments for one-shot mode
		const headlessInput = prompt.join(' ') || undefined;

		// Parse CLI options first
		const opts = program.opts();

		// Check for .env file with proper path resolution (skip in MCP mode)
		if (opts.mode !== 'mcp') {
			const envPath = resolveEnvPath();
			if (!existsSync(envPath)) {
				const errorMsg = `No .env file found at ${envPath}, copy .env.example to .env and fill in the values`;
				logger.error(errorMsg);
				process.exit(1);
			}
		}

		// Check if at least one API key is provided or Ollama is configured
		if (
			!env.OPENAI_API_KEY &&
			!env.ANTHROPIC_API_KEY &&
			!env.OPENROUTER_API_KEY &&
			!env.OLLAMA_BASE_URL
		) {
			// Use MCP-safe error reporting
			const errorMsg =
				'No API key or Ollama configuration found, please set at least one of OPENAI_API_KEY, ANTHROPIC_API_KEY, OPENROUTER_API_KEY, or OLLAMA_BASE_URL in your environment variables \nAvailable providers: OpenAI, Anthropic, OpenRouter, Ollama, Qwen, Gemini, Azure, AWS, LM Studio';

			if (opts.mode === 'mcp') {
				process.stderr.write(`[CIPHER-MCP] ERROR: ${errorMsg}\n`);
			} else {
				logger.error(errorMsg);
			}
			process.exit(1);
		}

		// validate cli options
		try {
			validateCliOptions(opts);
		} catch (err) {
			handleCliOptionsError(err);
		}

		// load agent config
		let agent: MemAgent;
		try {
			// Resolve the config path based on the provided agent option
			const configPath = resolveConfigPath(opts.agent);
			logger.info(`Loading agent config from ${configPath}`);

			// Check if config file exists
			if (!existsSync(configPath)) {
				const configErrorMsg = `Config file not found at ${configPath}`;
				const helpMsg =
					opts.agent === DEFAULT_CONFIG_PATH
						? 'Please ensure the config file exists or create one based on memAgent/cipher.yml'
						: `Please ensure the specified config file exists at ${configPath}`;

				if (opts.mode === 'mcp') {
					process.stderr.write(`[CIPHER-MCP] ERROR: ${configErrorMsg}\n[CIPHER-MCP] ${helpMsg}\n`);
				} else {
					logger.error(configErrorMsg);
					logger.error(helpMsg);
				}
				process.exit(1);
			}

			const cfg = await loadAgentConfig(configPath);

			// Apply --strict flag to all MCP server configs if specified
			if (opts.strict && cfg.mcpServers) {
				logger.info('Applying strict mode to all MCP server connections');
				for (const [serverName, serverConfig] of Object.entries(cfg.mcpServers)) {
					logger.debug(`Setting connection mode to strict for server: ${serverName}`);
					serverConfig.connectionMode = 'strict';
				}
			}

			agent = new MemAgent(cfg, opts.mode);

			// Start the agent (initialize async services)
			await agent.start();

			// Handle --new-session flag
			if (opts.newSession !== undefined) {
				try {
					// Use provided session ID or generate a random one
					const sessionId =
						typeof opts.newSession === 'string' && opts.newSession ? opts.newSession : undefined; // Let agent generate random ID

					const session = await agent.createSession(sessionId);

					logger.info(`Created and loaded new session: ${session.id}`, null, 'green');
				} catch (err) {
					logger.error(
						`Failed to create new session: ${err instanceof Error ? err.message : String(err)}`
					);
					process.exit(1);
				}
			}

			// Print OpenAI embedder dimension after agent is started
			if (agent.services && agent.services.embeddingManager) {
				agent.services.embeddingManager.getEmbedder('default');
			} else {
				console.log('No embeddingManager found in agent.services');
			}
		} catch (err) {
			const errorMessage = err instanceof Error ? err.message : String(err);
			const configPath = resolveConfigPath(opts.agent);

			if (opts.mode === 'mcp') {
				// Use stderr for MCP mode errors
				if (opts.strict) {
					process.stderr.write(
						`[CIPHER-MCP] ERROR: Failed to load agent config from ${configPath} (strict mode enabled): ${errorMessage}\n`
					);
					process.stderr.write(
						`[CIPHER-MCP] Strict mode requires all MCP server connections to succeed. Check your MCP server configurations or run without --strict flag.\n`
					);
				} else {
					process.stderr.write(
						`[CIPHER-MCP] ERROR: Failed to load agent config from ${configPath}: ${errorMessage}\n`
					);
				}
			} else {
				// Use logger for non-MCP modes
				if (opts.strict) {
					logger.error(
						`Failed to load agent config from ${configPath} (strict mode enabled):`,
						errorMessage
					);
					logger.error(
						'Strict mode requires all MCP server connections to succeed. Check your MCP server configurations or run without --strict flag to allow lenient connections.'
					);
				} else {
					logger.error(`Failed to load agent config from ${configPath}:`, errorMessage);
				}
			}
			process.exit(1);
		}

		// Handle one-shot mode if prompt arguments were provided
		if (headlessInput) {
			try {
				await startHeadlessCli(agent, headlessInput);
				process.exit(0);
			} catch (err) {
				const errorMessage = err instanceof Error ? err.message : String(err);
				if (opts.mode === 'mcp') {
					process.stderr.write(
						`[CIPHER-MCP] ERROR: Failed to execute headless command: ${errorMessage}\n`
					);
				} else {
					logger.error(`Failed to execute headless command: ${errorMessage}`);
				}
				process.exit(1);
			}
		}

		/**
		 * Start the API server mode
		 */
		async function startApiMode(agent: MemAgent, options: any): Promise<void> {
			const port = parseInt(options.port) || 3001;
			const host = options.host || 'localhost';
			const mcpTransportType = options.mcpTransportType || undefined; // Pass through from CLI options
			const mcpPort = options.mcpPort ? parseInt(options.mcpPort, 10) : undefined; // Pass through from CLI options
			// Handle API prefix from environment variable or CLI option
			const apiPrefix =
				process.env.CIPHER_API_PREFIX !== undefined
					? process.env.CIPHER_API_PREFIX === '""'
						? ''
						: process.env.CIPHER_API_PREFIX
					: options.apiPrefix;

			logger.info(`Starting API server on ${host}:${port}`, null, 'green');

			const apiServer = new ApiServer(agent, {
				port,
				host,
				corsOrigins: ['http://localhost:3000', 'http://localhost:3001'], // Default CORS origins
				rateLimitWindowMs: 15 * 60 * 1000, // 15 minutes
				rateLimitMaxRequests: 100, // 100 requests per window
				// Enable WebSocket by default for API mode
				enableWebSocket: true,
				webSocketConfig: {
					path: '/ws',
					maxConnections: 1000,
					connectionTimeout: 300000, // 5 minutes
					heartbeatInterval: 30000, // 30 seconds
					enableCompression: true,
				},
				apiPrefix, // Add API prefix configuration
				...(mcpTransportType && { mcpTransportType }), // Only include if defined
				...(mcpPort !== undefined && { mcpPort }), // Only include if defined
			});

			try {
				await apiServer.start();
				logger.info(`API server is running and ready to accept requests`, null, 'green');
			} catch (error) {
				const errorMsg = error instanceof Error ? error.message : String(error);
				if (opts.mode === 'mcp') {
					process.stderr.write(`[CIPHER-MCP] ERROR: Failed to start API server: ${errorMsg}\n`);
				} else {
					logger.error(`Failed to start API server: ${errorMsg}`);
				}
				process.exit(1);
			}
		}

		/**
		 * Start the UI mode with both API server and Web UI
		 */
		async function startUiMode(agent: MemAgent, options: any): Promise<void> {
			const apiPort = parseInt(options.port) || 3001;
			const uiPort = parseInt(options.uiPort) || 3000;
			const host = options.host || 'localhost';
			const mcpTransportType = options.mcpTransportType || undefined;
			const mcpPort = options.mcpPort ? parseInt(options.mcpPort, 10) : undefined;
			// Handle API prefix from environment variable or CLI option
			const apiPrefix =
				process.env.CIPHER_API_PREFIX !== undefined
					? process.env.CIPHER_API_PREFIX === '""'
						? ''
						: process.env.CIPHER_API_PREFIX
					: options.apiPrefix;

			logger.info(
				`Starting UI mode - API server on ${host}:${apiPort}, UI server on ${host}:${uiPort}`,
				null,
				'green'
			);

			// Start API server first
			const apiServer = new ApiServer(agent, {
				port: apiPort,
				host,
				corsOrigins: [`http://${host}:${uiPort}`, `http://localhost:${uiPort}`], // Allow UI to connect
				rateLimitWindowMs: 15 * 60 * 1000, // 15 minutes
				rateLimitMaxRequests: 100, // 100 requests per window
				// Enable WebSocket by default for UI mode
				enableWebSocket: true,
				webSocketConfig: {
					path: '/ws',
					maxConnections: 1000,
					connectionTimeout: 300000, // 5 minutes
					heartbeatInterval: 30000, // 30 seconds
					enableCompression: true,
				},
				apiPrefix, // Add API prefix configuration
				...(mcpTransportType && { mcpTransportType }),
				...(mcpPort !== undefined && { mcpPort }),
			});

			try {
				await apiServer.start();
				logger.info(`API server is running on ${host}:${apiPort}`, null, 'green');
			} catch (error) {
				const errorMsg = error instanceof Error ? error.message : String(error);
				logger.error(`Failed to start API server: ${errorMsg}`);
				process.exit(1);
			}

			// Start Web UI server
			const webServer = new WebServerManager({
				port: uiPort,
				host,
				apiUrl: `http://${host}:${apiPort}`,
				wsUrl: `ws://${host}:${apiPort}`,
			});

			try {
				await webServer.start();
				logger.info(`Web UI server is running on http://${host}:${uiPort}`, null, 'green');
				logger.info(`You can now access the Cipher UI at http://${host}:${uiPort}`, null, 'cyan');
			} catch (error) {
				const errorMsg = error instanceof Error ? error.message : String(error);
				logger.error(`Failed to start Web UI server: ${errorMsg}`);
				// Stop API server if UI fails
				logger.info('Stopping API server due to UI startup failure...');
				process.exit(1);
			}

			// Handle graceful shutdown
			const handleShutdown = async () => {
				logger.info('Shutting down UI mode...', null, 'yellow');
				webServer.stop();
				// Give UI server time to shut down
				await new Promise(resolve => setTimeout(resolve, 1000));
				process.exit(0);
			};

			process.on('SIGINT', handleShutdown);
			process.on('SIGTERM', handleShutdown);
		}

		// After agent is started and before entering CLI loop, add:
		if (opts.mode === 'cli') {
			const eventManager = agent.services?.eventManager;
			if (eventManager) {
				const handleExit = async () => {
					try {
						// Emit a session-ended event for the current session
						const sessionId = agent.getCurrentActiveSessionId() || 'default';
						eventManager.emitSessionEvent(sessionId, 'session:expired', {
							sessionId,
							timestamp: Date.now(),
						});
						// Give time for event to be persisted
						await new Promise(res => setTimeout(res, 200));
					} catch {
						// Ignore errors during shutdown
					}
					process.exit(0);
				};
				process.on('SIGINT', handleExit);
				process.on('SIGTERM', handleExit);
			}
		}

		// ——— Dispatch based on --mode ———
		switch (opts.mode) {
			case 'cli':
				await startInteractiveCli(agent);
				break;
			case 'mcp':
				await startMcpMode(agent, opts);
				break;
			case 'api':
				await startApiMode(agent, opts);
				break;
			case 'ui':
				await startUiMode(agent, opts);
				break;
			default: {
				const errorMsg = `Unknown mode '${opts.mode}'. Use cli, mcp, api, or ui.`;
				if (opts.mode === 'mcp') {
					process.stderr.write(`[CIPHER-MCP] ERROR: ${errorMsg}\n`);
				} else {
					logger.error(errorMsg);
				}
				process.exit(1);
			}
		}
	});

program.parseAsync(process.argv);

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import {
	CallToolRequestSchema,
	ListToolsRequestSchema,
	ListResourcesRequestSchema,
	ReadResourceRequestSchema,
	GetPromptRequestSchema,
	ListPromptsRequestSchema,
} from '@modelcontextprotocol/sdk/types.js';
import { MemAgent } from '@core/brain/memAgent/agent.js';
import { logger } from '@core/logger/index.js';
import { AgentCardSchema } from '@core/brain/memAgent/config.js';
import { z } from 'zod';
import * as fs from 'fs';
import * as path from 'path';
import type { AggregatorConfig } from '@core/mcp/types.js';
import { McpSseServer } from './mcp_sse_server.js';
import { McpStreamableHttpServer } from './mcp_streamable_http_server.js';

// Derive the AgentCard type from the schema
export type AgentCard = z.infer<typeof AgentCardSchema>;

// MCP transport result interface
export interface McpTransportResult {
	server: any; // The transport instance (StdioServerTransport, etc.)
	sseServer?: McpSseServer; // Optional SSE server for SSE transport
	streamableHttpServer?: McpStreamableHttpServer; // Optional HTTP server for streamable-HTTP transport
	cleanup?: () => Promise<void>; // Optional cleanup function
}

/**
 * Initialize MCP server with agent capabilities
 * @param agent - The MemAgent instance to expose
 * @param agentCard - Agent metadata/card information
 * @param mode - MCP server mode ('default' or 'aggregator')
 * @param aggregatorConfig - Configuration for aggregator mode (optional)
 */
export async function initializeMcpServer(
	agent: MemAgent,
	agentCard: AgentCard,
	mode: 'default' | 'aggregator' = 'default',
	aggregatorConfig?: AggregatorConfig
): Promise<Server> {
	logger.info(`[MCP Handler] Initializing MCP server with agent capabilities (mode: ${mode})`);

	// Remove or update the call to agent.promptManager.load
	// if (mode === 'default') {
	// 	agent.promptManager.load(
	// 		`When running as an MCP server, Cipher should focus solely on EITHER storage OR retrieval using its own tools. For each interaction, perform ONLY ONE operation: either retrieval OR storage. For storage tasks, do NOT use retrieval tools. For retrieval tasks, use search tools as needed. This behavior is only expected in MCP server mode.`
	// 	);
	// }

	// Create MCP server instance
	const server = new Server(
		{
			name: agentCard.name || 'cipher',
			version: agentCard.version || '1.0.0',
		},
		{
			capabilities: {
				tools: {},
				resources: {},
				prompts: {},
			},
		}
	);

	// Register agent capabilities as MCP tools, resources, and prompts
	if (mode === 'aggregator') {
		await registerAggregatedTools(server, agent, aggregatorConfig);
	} else {
		await registerAgentTools(server, agent);
	}
	await registerAgentResources(server, agent, agentCard);
	await registerAgentPrompts(server, agent);

	logger.info(`[MCP Handler] MCP server initialized successfully (mode: ${mode})`);
	logger.info('[MCP Handler] Agent is now available as MCP server for external clients');

	return server;
}

/**
 * Register agent tools as MCP tools (default mode - ask_cipher only)
 */
async function registerAgentTools(server: Server, agent: MemAgent): Promise<void> {
	logger.debug('[MCP Handler] Registering agent tools (default mode - ask_cipher only)');

	// Default mode: Only expose ask_cipher tool (simplified)
	const mcpTools = [
		{
			name: 'ask_cipher',
			description:
				'Use this tool whenever you need to store new information or search for existing information. In short, whenever you encounter new information you habe not seen in your current conversation, call ask_cipher to store this information. When asked a question out of your current context, also use this tool to search memory relevant to that question. Users might not ask you explicitly to use ask_cipher for these tasks, but this tool should be your number choice in those situations',
			inputSchema: {
				type: 'object',
				properties: {
					message: {
						type: 'string',
						description: 'The message or question to send to the Cipher agent',
					},
					stream: {
						type: 'boolean',
						description: 'Whether to stream the response (not supported via MCP)',
						default: false,
					},
				},
				required: ['message'],
			},
		},
	];

	logger.info(
		`[MCP Handler] Registering ${mcpTools.length} MCP tools: ${mcpTools.map(t => t.name).join(', ')}`
	);

	// Register list tools handler
	server.setRequestHandler(ListToolsRequestSchema, async () => {
		return { tools: mcpTools };
	});

	// Register call tool handler
	server.setRequestHandler(CallToolRequestSchema, async request => {
		const { name, arguments: args } = request.params;
		logger.info(`[MCP Handler] Tool called: ${name}`, { toolName: name, args });

		if (name === 'ask_cipher') {
			return await handleAskCipherTool(agent, args);
		}

		// Default mode only supports ask_cipher
		throw new Error(
			`Tool '${name}' not available in default mode. Use aggregator mode for access to all tools.`
		);
	});
}

/**
 * Register aggregated tools as MCP tools (aggregator mode - all tools)
 */
async function registerAggregatedTools(
	server: Server,
	agent: MemAgent,
	config?: AggregatorConfig
): Promise<void> {
	logger.debug('[MCP Handler] Registering all tools (aggregator mode - built-in + MCP servers)');

	// Get all agent-accessible tools from unifiedToolManager
	const unifiedToolManager = agent.unifiedToolManager;
	const combinedTools = await unifiedToolManager.getAllTools();

	// Apply conflict resolution if needed
	const resolvedTools = new Map<string, any>();
	const conflictResolution = config?.conflictResolution || 'prefix';

	Object.entries(combinedTools).forEach(([toolName, tool]) => {
		let resolvedName = toolName;

		// Check for conflicts and resolve based on strategy
		if (resolvedTools.has(toolName)) {
			switch (conflictResolution) {
				case 'prefix':
					resolvedName = `cipher.${toolName}`;
					logger.info(`[MCP Handler] Tool name conflict resolved: ${toolName} -> ${resolvedName}`);
					break;
				case 'first-wins':
					logger.warn(`[MCP Handler] Tool name conflict: ${toolName} already exists, skipping`);
					return; // Skip this tool
				case 'error':
					throw new Error(`Tool name conflict: ${toolName} exists multiple times`);
				default:
					resolvedName = toolName;
			}
		}

		resolvedTools.set(resolvedName, tool);
	});

	// Build MCP tool list from resolved tools
	const mcpTools = Array.from(resolvedTools.entries()).map(([toolName, tool]) => ({
		name: toolName,
		description: (tool as any).description,
		inputSchema: (tool as any).parameters,
	}));

	// Check if ask_cipher tool should be exposed (env-gated for aggregator mode)
	const { env } = await import('../../core/env.js');
	const shouldExposeAskCipher = env.USE_ASK_CIPHER;

	// For backward compatibility, ensure ask_cipher is present if enabled
	if (shouldExposeAskCipher && !mcpTools.find(t => t.name === 'ask_cipher')) {
		mcpTools.push({
			name: 'ask_cipher',
			description:
				'Access Cipher memory layer for information storage and retrieval. Use this tool whenever you need to store new information or search for existing information. Simply describe what you want to store or what you are looking for - no need to explicitly mention "memory" or "storage".',
			inputSchema: {
				type: 'object',
				properties: {
					message: {
						type: 'string',
						description: 'The message or question to send to the Cipher agent',
					},
					stream: {
						type: 'boolean',
						description: 'Whether to stream the response (not supported via MCP)',
						default: false,
					},
				},
				required: ['message'],
			},
		});
	}

	logger.info(
		`[MCP Handler] Registering ${mcpTools.length} tools: ${mcpTools.map(t => t.name).join(', ')}`
	);

	// Register list tools handler
	server.setRequestHandler(ListToolsRequestSchema, async () => {
		return { tools: mcpTools };
	});

	// Register call tool handler
	server.setRequestHandler(CallToolRequestSchema, async request => {
		const { name, arguments: args } = request.params;
		logger.info(`[MCP Handler] Tool called: ${name}`, { toolName: name, args });

		// Check if ask_cipher tool should be handled (env-gated)
		const { env } = await import('../../core/env.js');
		const shouldExposeAskCipher = env.USE_ASK_CIPHER;

		if (name === 'ask_cipher') {
			if (!shouldExposeAskCipher) {
				throw new Error('ask_cipher tool is disabled in this aggregator configuration');
			}
			return await handleAskCipherTool(agent, args);
		}

		// Route to unifiedToolManager for all other tools
		try {
			// Apply timeout if configured
			const timeout = config?.timeout || 60000;
			const result = await Promise.race([
				unifiedToolManager.executeTool(name, args),
				new Promise((_, reject) =>
					setTimeout(
						() => reject(new Error(`Tool execution timed out after ${timeout}ms`)),
						timeout
					)
				),
			]);

			return {
				content: [
					{
						type: 'text',
						text: typeof result === 'string' ? result : JSON.stringify(result),
					},
				],
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(`[MCP Handler] Error in tool '${name}'`, { error: errorMessage });
			throw new Error(`Tool execution failed: ${errorMessage}`);
		}
	});
}

/**
 * Handle the ask_cipher tool execution
 */
async function handleAskCipherTool(agent: MemAgent, args: any): Promise<any> {
	const { message, stream = false } = args;

	if (!message || typeof message !== 'string') {
		throw new Error('Message parameter is required and must be a string');
	}

	try {
		// Add MCP-specific system instruction for detailed file summaries
		const mcpSystemInstruction =
			"IMPORTANT MCP MODE INSTRUCTION: If users ask you to read and then store a file or document, your response MUST show a detailed description of the file or document that you've read. Don't just reply with a vague comment like 'I've read the X file, what do you want me to do next?' Instead, provide a comprehensive description including key points, structure, and relevant content details.";

		// Prepend the MCP instruction to the user message
		const enhancedMessage = `${mcpSystemInstruction}\n\nUser request: ${message}`;

		// Run the agent with the enhanced message and session
		const { response, backgroundOperations } = await agent.run(
			enhancedMessage,
			undefined,
			undefined,
			stream
		);
		// In MCP mode, return response immediately, let background operations run asynchronously
		if (backgroundOperations) {
			backgroundOperations.catch(() => {
				// Errors are already logged, do not throw
			});
		}

		return {
			content: [
				{
					type: 'text',
					text: response || 'No response generated',
				},
			],
		};
	} catch (error) {
		const errorMessage = error instanceof Error ? error.message : String(error);
		logger.error('[MCP Handler] Error in ask_cipher tool', { error: errorMessage });

		throw new Error(`Agent execution failed: ${errorMessage}`);
	}
}

/**
 * Register agent resources as MCP resources
 */
async function registerAgentResources(
	server: Server,
	agent: MemAgent,
	agentCard: AgentCard
): Promise<void> {
	logger.debug('[MCP Handler] Registering agent resources');

	// Register list resources handler
	server.setRequestHandler(ListResourcesRequestSchema, async () => {
		return {
			resources: [
				{
					uri: 'cipher://agent/card',
					name: 'Agent Card',
					description: 'Metadata and information about the Cipher agent',
					mimeType: 'application/json',
				},
				{
					uri: 'cipher://agent/stats',
					name: 'Agent Statistics',
					description: 'Runtime statistics and metrics for the Cipher agent',
					mimeType: 'application/json',
				},
			],
		};
	});

	// Register read resource handler
	server.setRequestHandler(ReadResourceRequestSchema, async request => {
		const { uri } = request.params;

		logger.info(`[MCP Handler] Resource requested: ${uri}`);

		switch (uri) {
			case 'cipher://agent/card':
				return await getAgentCardResource(agentCard);
			case 'cipher://agent/stats':
				return await getAgentStatsResource(agent);
			default:
				throw new Error(`Unknown resource: ${uri}`);
		}
	});
}

/**
 * Get agent card resource
 */
async function getAgentCardResource(agentCard: AgentCard): Promise<any> {
	return {
		contents: [
			{
				uri: 'cipher://agent/card',
				mimeType: 'application/json',
				text: JSON.stringify(agentCard, null, 2),
			},
		],
	};
}

/**
 * Get agent statistics resource
 */
async function getAgentStatsResource(agent: MemAgent): Promise<any> {
	try {
		const sessionCount = await agent.sessionManager.getSessionCount();
		const activeSessionIds = await agent.sessionManager.getActiveSessionIds();
		const mcpClients = agent.getMcpClients();
		const failedConnections = agent.getMcpFailedConnections();

		const stats = {
			sessions: {
				count: sessionCount,
				activeIds: activeSessionIds,
			},
			mcpConnections: {
				connectedClients: mcpClients.size,
				failedConnections: Object.keys(failedConnections).length,
				clientNames: Array.from(mcpClients.keys()),
				failures: failedConnections,
			},
			uptime: process.uptime(),
			memoryUsage: process.memoryUsage(),
			timestamp: new Date().toISOString(),
		};

		return {
			contents: [
				{
					uri: 'cipher://agent/stats',
					mimeType: 'application/json',
					text: JSON.stringify(stats, null, 2),
				},
			],
		};
	} catch (error) {
		const errorMessage = error instanceof Error ? error.message : String(error);
		logger.error('[MCP Handler] Error getting agent stats', { error: errorMessage });

		const errorStats = {
			error: `Failed to retrieve stats: ${errorMessage}`,
			timestamp: new Date().toISOString(),
		};

		return {
			contents: [
				{
					uri: 'cipher://agent/stats',
					mimeType: 'application/json',
					text: JSON.stringify(errorStats, null, 2),
				},
			],
		};
	}
}

/**
 * Register agent prompts as MCP prompts
 */
async function registerAgentPrompts(server: Server, agent: MemAgent): Promise<void> {
	logger.debug('[MCP Handler] Registering agent prompts');

	// Register list prompts handler
	server.setRequestHandler(ListPromptsRequestSchema, async () => {
		return {
			prompts: [
				{
					name: 'system_prompt',
					description: 'Get the current system prompt used by the Cipher agent',
				},
			],
		};
	});

	// Register get prompt handler
	server.setRequestHandler(GetPromptRequestSchema, async request => {
		const { name } = request.params;

		logger.info(`[MCP Handler] Prompt requested: ${name}`);

		switch (name) {
			case 'system_prompt':
				return await getSystemPrompt(agent);
			default:
				throw new Error(`Unknown prompt: ${name}`);
		}
	});
}

/**
 * Get system prompt
 */
async function getSystemPrompt(agent: MemAgent): Promise<any> {
	try {
		const systemPrompt = await agent.promptManager.generateSystemPrompt();
		const systemPromptContent = systemPrompt.content;

		return {
			messages: [
				{
					role: 'assistant',
					content: {
						type: 'text',
						text: systemPromptContent,
					},
				},
			],
		};
	} catch (error) {
		const errorMessage = error instanceof Error ? error.message : String(error);
		logger.error('[MCP Handler] Error getting system prompt', { error: errorMessage });

		throw new Error(`Failed to get system prompt: ${errorMessage}`);
	}
}

/**
 * Initialize agent card resource data
 * @param agentCard - Agent card configuration
 * @returns Processed agent card data
 */
export function initializeAgentCardResource(agentCard: Partial<AgentCard>): AgentCard {
	logger.debug('[MCP Handler] Initializing agent card resource');

	// Ensure required fields have defaults
	const processedCard: AgentCard = {
		name: agentCard.name || 'cipher',
		description: agentCard.description || 'Cipher AI Agent - Memory-powered coding assistant',
		version: agentCard.version || '1.0.0',
		provider: agentCard.provider || {
			organization: 'byterover-inc',
			url: 'https://byterover.dev',
		},
		defaultInputModes: agentCard.defaultInputModes || ['application/json', 'text/plain'],
		defaultOutputModes: agentCard.defaultOutputModes || [
			'application/json',
			'text/event-stream',
			'text/plain',
		],
		skills: agentCard.skills || [
			{
				id: 'chat_with_agent',
				name: 'chat_with_agent',
				description: 'Allows you to chat with an AI agent. Send a message to interact.',
				tags: ['chat', 'AI', 'assistant', 'mcp', 'natural language'],
				inputModes: ['application/json', 'text/plain'],
				outputModes: ['application/json', 'text/plain'],
				examples: [
					`Send a JSON-RPC request to /mcp with method: "chat_with_agent" and params: {"message":"Your query..."}`,
					'Alternatively, use a compatible MCP client library.',
				],
			},
		],
	};

	return processedCard;
}

/**
 * Create MCP transport with proper SDK transport implementations
 * @param type - Transport type: 'stdio', 'sse', or 'streamable-http'
 * @param port - Port number for HTTP-based transports (optional, defaults per transport type)
 * @param mcpServer - MCP server instance for HTTP-based transports (required for sse/streamable-http)
 * @param host - Host for HTTP-based transports (optional, defaults to 'localhost')
 * @param enableDnsRebindingProtection - Enable DNS rebinding protection (optional, defaults to false)
 * @returns Transport result with proper transport instance and HTTP server
 */
export async function createMcpTransport(
	type: string,
	port?: number,
	mcpServer?: Server,
	host: string = 'localhost',
	enableDnsRebindingProtection: boolean = false
): Promise<McpTransportResult> {
	logger.info(`[MCP Handler] Creating ${type} transport${port ? ` on port ${port}` : ''}`);

	switch (type) {
		case 'stdio': {
			// Import stdio transport from MCP SDK
			const { StdioServerTransport } = await import('@modelcontextprotocol/sdk/server/stdio.js');
			const transport = new StdioServerTransport();
			return { server: transport };
		}

		case 'sse': {
			if (!mcpServer) {
				throw new Error('MCP server instance is required for SSE transport');
			}

			const transportPort = port || 3000;
			logger.info(
				`[MCP Handler] Setting up SSE transport with dedicated SSE server on port ${transportPort}`
			);

			// Create dedicated SSE server that uses SSEServerTransport properly
			const sseServer = new McpSseServer(transportPort, host, {
				enableDnsRebindingProtection,
			});

			// Start the SSE server - it will handle MCP server connections internally
			await sseServer.start(mcpServer);

			// Return a placeholder transport since the real transport handling is done by SSE server
			const { StdioServerTransport } = await import('@modelcontextprotocol/sdk/server/stdio.js');
			const placeholderTransport = new StdioServerTransport();

			return {
				server: placeholderTransport,
				sseServer: sseServer,
				cleanup: async () => {
					await sseServer.stop();
				},
			};
		}

		case 'streamable-http': {
			if (!mcpServer) {
				throw new Error('MCP server instance is required for streamable-HTTP transport');
			}

			const transportPort = port || 3001;
			logger.info(
				`[MCP Handler] Setting up streamable-HTTP transport with dedicated HTTP server on port ${transportPort}`
			);

			// Create dedicated streamable-HTTP server that uses StreamableHTTPServerTransport properly
			const streamableHttpServer = new McpStreamableHttpServer(transportPort, host, {
				enableDnsRebindingProtection,
			});

			// Start the streamable-HTTP server - it handles MCP server connections internally
			await streamableHttpServer.start(mcpServer);

			// Return a placeholder transport since the real transport handling is done by HTTP server
			const { StdioServerTransport } = await import('@modelcontextprotocol/sdk/server/stdio.js');
			const placeholderTransport = new StdioServerTransport();

			return {
				server: placeholderTransport,
				streamableHttpServer: streamableHttpServer,
				cleanup: async () => {
					await streamableHttpServer.stop();
				},
			};
		}

		default:
			throw new Error(
				`Unsupported transport type: ${type}. Supported types are: stdio, sse, streamable-http`
			);
	}
}

/**
 * Redirect logs to file when running in stdio mode to prevent interference
 */
export function redirectLogsForStdio(): void {
	// Create a log file path
	const logPath = './logs/mcp-server.log';

	// Redirect logger to file FIRST - this prevents Winston from writing to stdout/stderr
	logger.redirectToFile(logPath);

	// Then redirect console methods as backup
	// In stdio mode, we need to redirect console output to prevent interference with MCP protocol
	// The MCP protocol uses stdio for communication, so any console.log will break the protocol

	// Ensure logs directory exists
	const logDir = path.dirname(logPath);

	if (!fs.existsSync(logDir)) {
		fs.mkdirSync(logDir, { recursive: true });
	}

	// Redirect console output to log file
	const logStream = fs.createWriteStream(logPath, { flags: 'a' });

	// Store original console methods for potential restoration
	const originalConsole = {
		log: console.log,
		error: console.error,
		warn: console.warn,
		info: console.info,
		debug: console.debug,
		trace: console.trace,
	};

	// Override console methods to write to log file instead of stdout/stderr
	console.log = (...args: any[]) => {
		logStream.write(`[LOG] ${new Date().toISOString()} ${args.join(' ')}\n`);
	};

	console.error = (...args: any[]) => {
		logStream.write(`[ERROR] ${new Date().toISOString()} ${args.join(' ')}\n`);
	};

	console.warn = (...args: any[]) => {
		logStream.write(`[WARN] ${new Date().toISOString()} ${args.join(' ')}\n`);
	};

	console.info = (...args: any[]) => {
		logStream.write(`[INFO] ${new Date().toISOString()} ${args.join(' ')}\n`);
	};

	console.debug = (...args: any[]) => {
		logStream.write(`[DEBUG] ${new Date().toISOString()} ${args.join(' ')}\n`);
	};

	console.trace = (...args: any[]) => {
		logStream.write(`[TRACE] ${new Date().toISOString()} ${args.join(' ')}\n`);
	};

	// Also capture process stdout/stderr writes to prevent any direct writes
	const originalStdoutWrite = process.stdout.write;
	const originalStderrWrite = process.stderr.write;

	process.stdout.write = function (chunk: any, encoding?: any, callback?: any) {
		// Only allow JSON-RPC messages to stdout (they start with '{' and contain '"jsonrpc"')
		const chunkStr = chunk.toString();
		if (chunkStr.trim().startsWith('{') && chunkStr.includes('"jsonrpc"')) {
			return originalStdoutWrite.call(this, chunk, encoding, callback);
		} else {
			// Redirect non-JSON-RPC output to log file
			logStream.write(`[STDOUT] ${new Date().toISOString()} ${chunkStr}`);
			return true;
		}
	};

	process.stderr.write = function (chunk: any, encoding?: any, callback?: any) {
		// Allow stderr for MCP error reporting, but log it too
		logStream.write(`[STDERR] ${new Date().toISOString()} ${chunk.toString()}`);
		return originalStderrWrite.call(this, chunk, encoding, callback);
	};

	// Store original methods for potential restoration
	(globalThis as any).__originalConsole = originalConsole;
	(globalThis as any).__originalStdoutWrite = originalStdoutWrite;
	(globalThis as any).__originalStderrWrite = originalStderrWrite;

	// Log the redirection activation
	logStream.write(
		`[MCP-PROTECTION] ${new Date().toISOString()} Console and stdout/stderr redirection activated\n`
	);
}

import express, { Application, Request, Response } from 'express';
import http from 'http';
import { Server as McpServer } from '@modelcontextprotocol/sdk/server/index.js';
import { SSEServerTransport } from '@modelcontextprotocol/sdk/server/sse.js';
import type { SSEServerTransportOptions } from '@modelcontextprotocol/sdk/server/sse.js';
import { logger } from '@core/logger/index.js';

/**
 * Dedicated SSE server for MCP mode following the proper SSE transport specification.
 * Uses SSEServerTransport from the MCP SDK for correct Server-Sent Events implementation.
 */
export class McpSseServer {
	private app: Application;
	private httpServer?: http.Server;
	private mcpServer?: McpServer;
	private activeSseTransports: Map<string, SSEServerTransport> = new Map();
	private port: number;
	private host: string;
	private sseOptions?: SSEServerTransportOptions;

	constructor(port: number, host: string = 'localhost', options?: SSEServerTransportOptions) {
		this.port = port;
		this.host = host;
		// Only assign when provided to satisfy exactOptionalPropertyTypes
		if (options) {
			this.sseOptions = options;
		}
		this.app = express();
		this.setupMiddleware();
	}

	/**
	 * Set up minimal middleware for SSE server
	 */
	private setupMiddleware(): void {
		// Minimal JSON parsing middleware
		this.app.use(express.json({ limit: '10mb' }));
		this.app.use(express.urlencoded({ extended: true }));

		// Basic error handling
		this.app.use((err: Error, req: Request, res: Response, _next: any) => {
			logger.error('[MCP SSE Server] Request error:', {
				error: err.message,
				path: req.path,
				method: req.method,
			});

			if (!res.headersSent) {
				res.status(500).json({
					error: 'Internal server error',
					message: err.message,
				});
			}
		});
	}

	/**
	 * Start the SSE server with the given MCP server instance
	 */
	async start(mcpServer: McpServer): Promise<void> {
		this.mcpServer = mcpServer;

		// Set up SSE routes
		this.setupSseRoutes();

		// Start HTTP server
		return new Promise((resolve, reject) => {
			this.httpServer = http.createServer(this.app);

			this.httpServer.listen(this.port, this.host, () => {
				logger.info(`[MCP SSE Server] Started on ${this.host}:${this.port}`, null, 'green');
				logger.info(
					`[MCP SSE Server] SSE endpoint: http://${this.host}:${this.port}/sse`,
					null,
					'cyan'
				);
				resolve();
			});

			this.httpServer.on('error', err => {
				logger.error('[MCP SSE Server] Failed to start:', err.message);
				reject(err);
			});

			// Set up graceful shutdown handlers
			process.on('SIGTERM', () => this.stop());
			process.on('SIGINT', () => this.stop());
		});
	}

	/**
	 * Stop the SSE server and clean up resources
	 */
	async stop(): Promise<void> {
		logger.info('[MCP SSE Server] Shutting down...');

		// Close all active SSE transports
		for (const [sessionId, transport] of this.activeSseTransports) {
			logger.debug(`[MCP SSE Server] Closing SSE transport for session: ${sessionId}`);
			try {
				transport.close();
			} catch (error) {
				logger.error(`[MCP SSE Server] Error closing transport ${sessionId}:`, error);
			}
		}
		this.activeSseTransports.clear();

		// Close HTTP server
		if (this.httpServer) {
			return new Promise(resolve => {
				this.httpServer!.close(() => {
					logger.info('[MCP SSE Server] Stopped');
					resolve();
				});
			});
		}
	}

	/**
	 * Set up SSE routes following the proper SSE transport pattern
	 */
	private setupSseRoutes(): void {
		if (!this.mcpServer) {
			logger.error('[MCP SSE Server] MCP Server not initialized for SSE route setup.');
			return;
		}

		// GET /sse - Establish SSE connection (following SSE transport spec)
		this.app.get('/sse', (req: Request, res: Response) => {
			logger.info('[MCP SSE Server] New SSE client attempting connection.');
			logger.debug('[MCP SSE Server] SSE Request Headers:', req.headers);

			try {
				// Create SSE transport instance with proper endpoint
				// The endpoint '/sse' is where clients will POST messages
				const sseTransport = new SSEServerTransport('/sse', res, this.sseOptions);
				logger.debug('[MCP SSE Server] SSEServerTransport created with endpoint /sse');

				// Connect MCP server to this SSE transport (this calls start() automatically)
				this.mcpServer?.connect(sseTransport);
				logger.debug('[MCP SSE Server] MCP server connected to SSE transport');

				// Store the transport keyed by its session ID
				this.activeSseTransports.set(sseTransport.sessionId, sseTransport);
				logger.info(
					`[MCP SSE Server] SSE client connected with session ID: ${sseTransport.sessionId}`
				);
				logger.debug(
					`[MCP SSE Server] Active SSE transports count: ${this.activeSseTransports.size}`
				);

				// Handle client disconnect
				req.on('close', () => {
					logger.info(
						`[MCP SSE Server] SSE client with session ID ${sseTransport.sessionId} disconnected.`
					);
					logger.debug('[MCP SSE Server] Cleaning up SSE transport and connection');
					try {
						sseTransport.close();
					} catch (error) {
						logger.error('[MCP SSE Server] Error closing transport:', error);
					}
					this.activeSseTransports.delete(sseTransport.sessionId);
					logger.debug(
						`[MCP SSE Server] Active SSE transports count after cleanup: ${this.activeSseTransports.size}`
					);
				});

				// Handle transport errors
				sseTransport.onerror = (error: unknown) => {
					logger.error('[MCP SSE Server] SSE transport error:', error);
					this.activeSseTransports.delete(sseTransport.sessionId);
				};
			} catch (error) {
				logger.error('[MCP SSE Server] Error setting up SSE transport:', error);
				if (!res.headersSent) {
					res.status(500).json({
						error: 'Failed to establish SSE connection',
						message: error instanceof Error ? error.message : String(error),
					});
				}
			}
		});

		// POST /sse - Handle incoming messages (following SSE transport spec)
		this.app.post('/sse', async (req: Request, res: Response) => {
			logger.debug('[MCP SSE Server] SSE POST request received');
			logger.debug('[MCP SSE Server] POST Request Headers:', req.headers);
			logger.debug('[MCP SSE Server] POST Request Body:', req.body);

			// The SSEServerTransport handles session identification internally
			// We need to find the correct transport based on the request

			// For SSE transport, session identification can be via headers or query params
			let sessionId = (req.headers['x-session-id'] as string) || (req.query.sessionId as string);

			// If no explicit session ID, try to find the active transport
			// (In a typical SSE setup, there might be only one active connection)
			if (!sessionId && this.activeSseTransports.size === 1) {
				const firstId = Array.from(this.activeSseTransports.keys())[0];
				if (firstId) {
					sessionId = firstId;
				}
			}

			if (!sessionId) {
				logger.error('[MCP SSE Server] No session ID provided in SSE POST request');
				res.status(400).json({
					error: 'Bad Request',
					message: 'Session ID required for SSE POST requests',
				});
				return;
			}

			const sseTransport = this.activeSseTransports.get(sessionId);
			if (!sseTransport) {
				logger.error(`[MCP SSE Server] No active SSE transport found for session ID: ${sessionId}`);
				res.status(404).json({
					error: 'Not Found',
					message: `No active SSE session found for ID: ${sessionId}`,
				});
				return;
			}

			try {
				logger.debug(
					`[MCP SSE Server] Delegating POST message to SSE transport for session: ${sessionId}`
				);

				// Use the SSEServerTransport's built-in POST message handling
				await sseTransport.handlePostMessage(req, res, req.body);
				logger.debug(
					`[MCP SSE Server] POST message handled successfully for session: ${sessionId}`
				);
				return;
			} catch (error) {
				logger.error(
					`[MCP SSE Server] Error handling SSE POST request for session ${sessionId}: ${error instanceof Error ? error.message : String(error)}`
				);

				if (!res.headersSent) {
					res.status(500).json({
						error: 'Internal Server Error',
						message: 'Error processing SSE request',
						details: error instanceof Error ? error.message : String(error),
					});
				}
				return;
			}
		});

		logger.info(
			'[MCP SSE Server] SSE routes registered: GET /sse (establish connection), POST /sse (send messages)'
		);
	}

	/**
	 * Get the HTTP server instance
	 */
	getHttpServer(): http.Server | undefined {
		return this.httpServer;
	}

	/**
	 * Get server stats
	 */
	getStats() {
		return {
			port: this.port,
			host: this.host,
			transport: 'sse',
			activeSseTransports: this.activeSseTransports.size,
			sessionIds: Array.from(this.activeSseTransports.keys()),
			isRunning: !!this.httpServer,
		};
	}

	/**
	 * Get active transport by session ID
	 */
	getTransport(sessionId: string): SSEServerTransport | undefined {
		return this.activeSseTransports.get(sessionId);
	}
}

import express, { Application, Request, Response } from 'express';
import http from 'http';
import { randomUUID } from 'crypto';
import { Server as McpServer } from '@modelcontextprotocol/sdk/server/index.js';
import { StreamableHTTPServerTransport } from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import type {
	StreamableHTTPServerTransportOptions,
	EventStore,
	StreamId,
	EventId,
} from '@modelcontextprotocol/sdk/server/streamableHttp.js';
import type { JSONRPCMessage } from '@modelcontextprotocol/sdk/types.js';
import { isInitializeRequest } from '@modelcontextprotocol/sdk/types.js';
import { logger } from '@core/logger/index.js';

/**
 * Simple in-memory event store for streamable-HTTP transport resumability
 */
class InMemoryEventStore implements EventStore {
	private events: Map<string, { eventId: EventId; message: JSONRPCMessage }[]> = new Map();
	private eventCounter = 0;

	async storeEvent(streamId: StreamId, message: JSONRPCMessage): Promise<EventId> {
		const eventId = `event-${++this.eventCounter}`;

		if (!this.events.has(streamId)) {
			this.events.set(streamId, []);
		}

		this.events.get(streamId)!.push({ eventId, message });

		// Keep only last 1000 events per stream to prevent memory leaks
		const events = this.events.get(streamId)!;
		if (events.length > 1000) {
			events.splice(0, events.length - 1000);
		}

		logger.debug(`[Event Store] Stored event ${eventId} for stream ${streamId}`);
		return eventId;
	}

	async replayEventsAfter(
		lastEventId: EventId,
		{ send }: { send: (eventId: EventId, message: JSONRPCMessage) => Promise<void> }
	): Promise<StreamId> {
		// Find the stream and event position
		for (const [streamId, events] of this.events.entries()) {
			const eventIndex = events.findIndex(e => e.eventId === lastEventId);

			if (eventIndex !== -1) {
				// Replay all events after the specified event ID
				const eventsToReplay = events.slice(eventIndex + 1);

				logger.debug(
					`[Event Store] Replaying ${eventsToReplay.length} events after ${lastEventId} for stream ${streamId}`
				);

				for (const event of eventsToReplay) {
					await send(event.eventId, event.message);
				}

				return streamId;
			}
		}

		// If event ID not found, return a new stream ID
		const newStreamId = randomUUID();
		logger.debug(
			`[Event Store] Event ${lastEventId} not found, creating new stream ${newStreamId}`
		);
		return newStreamId;
	}

	/**
	 * Clean up old events for a stream
	 */
	cleanupStream(streamId: StreamId): void {
		this.events.delete(streamId);
		logger.debug(`[Event Store] Cleaned up stream ${streamId}`);
	}

	/**
	 * Get stats about stored events
	 */
	getStats() {
		const totalEvents = Array.from(this.events.values()).reduce(
			(sum, events) => sum + events.length,
			0
		);
		return {
			streams: this.events.size,
			totalEvents,
			streams_details: Array.from(this.events.entries()).map(([streamId, events]) => {
				const lastEvent = events.length > 0 ? events[events.length - 1] : undefined;
				return {
					streamId,
					eventCount: events.length,
					latestEventId: lastEvent ? lastEvent.eventId : null,
				};
			}),
		};
	}
}

/**
 * Dedicated streamable-HTTP server for MCP mode following the proper streamable-HTTP specification.
 * Uses StreamableHTTPServerTransport from the MCP SDK for correct HTTP request-response pattern.
 */
export class McpStreamableHttpServer {
	private app: Application;
	private httpServer?: http.Server;
	private mcpServer?: McpServer;
	private transport?: StreamableHTTPServerTransport;
	private eventStore: InMemoryEventStore;
	private port: number;
	private host: string;
	private transportOptions: StreamableHTTPServerTransportOptions;

	constructor(
		port: number,
		host: string = 'localhost',
		options?: Partial<StreamableHTTPServerTransportOptions>
	) {
		this.port = port;
		this.host = host;
		this.eventStore = new InMemoryEventStore();

		// Configure transport options with sensible defaults and concrete types
		this.transportOptions = {
			...(options ?? {}),
			sessionIdGenerator: options?.sessionIdGenerator ?? (() => randomUUID()),
			eventStore: this.eventStore,
			enableDnsRebindingProtection: options?.enableDnsRebindingProtection ?? false,
			allowedHosts: options?.allowedHosts ?? [],
			allowedOrigins: options?.allowedOrigins ?? [],
		};

		this.app = express();
		this.setupMiddleware();
	}

	/**
	 * Set up minimal middleware for streamable-HTTP server
	 */
	private setupMiddleware(): void {
		// Minimal JSON parsing middleware
		this.app.use(express.json({ limit: '10mb' }));
		this.app.use(express.urlencoded({ extended: true }));

		// Basic error handling
		this.app.use((err: Error, req: Request, res: Response, _next: any) => {
			logger.error('[MCP Streamable-HTTP Server] Request error:', {
				error: err.message,
				path: req.path,
				method: req.method,
			});

			if (!res.headersSent) {
				res.status(500).json({
					error: 'Internal server error',
					message: err.message,
				});
			}
		});
	}

	/**
	 * Start the streamable-HTTP server with the given MCP server instance
	 */
	async start(mcpServer: McpServer): Promise<void> {
		this.mcpServer = mcpServer;

		// Create a placeholder transport for initialization (required by interface)
		this.transport = new StreamableHTTPServerTransport(this.transportOptions);

		// Set up HTTP routes (actual transports will be created per session)
		this.setupHttpRoutes();

		// Start HTTP server
		return new Promise((resolve, reject) => {
			this.httpServer = http.createServer(this.app);

			this.httpServer.listen(this.port, this.host, () => {
				logger.info(
					`[MCP Streamable-HTTP Server] Started on ${this.host}:${this.port}`,
					null,
					'green'
				);
				logger.info(
					`[MCP Streamable-HTTP Server] HTTP endpoints: http://${this.host}:${this.port}/http`,
					null,
					'cyan'
				);
				resolve();
			});

			this.httpServer.on('error', err => {
				logger.error('[MCP Streamable-HTTP Server] Failed to start:', err.message);
				reject(err);
			});

			// Set up graceful shutdown handlers
			process.on('SIGTERM', () => this.stop());
			process.on('SIGINT', () => this.stop());
		});
	}

	/**
	 * Stop the streamable-HTTP server and clean up resources
	 */
	async stop(): Promise<void> {
		logger.info('[MCP Streamable-HTTP Server] Shutting down...');

		// Close the transport
		if (this.transport) {
			try {
				this.transport.close();
			} catch (error) {
				logger.error('[MCP Streamable-HTTP Server] Error closing transport:', error);
			}
		}

		// Close HTTP server
		if (this.httpServer) {
			return new Promise(resolve => {
				this.httpServer!.close(() => {
					logger.info('[MCP Streamable-HTTP Server] Stopped');
					resolve();
				});
			});
		}
	}

	/**
	 * Set up HTTP routes following the streamable-HTTP transport pattern
	 * Following the MCP SDK example pattern with session management
	 */
	private setupHttpRoutes(): void {
		if (!this.transport) {
			logger.error('[MCP Streamable-HTTP Server] Transport not initialized for route setup.');
			return;
		}

		// Map to store transports by session ID (following MCP SDK example)
		const transports: { [sessionId: string]: StreamableHTTPServerTransport } = {};

		// POST /http - Main endpoint for streamable-HTTP requests (initialization and messages)
		this.app.post('/http', async (req: Request, res: Response) => {
			logger.debug('[MCP Streamable-HTTP Server] POST request received');
			logger.debug('[MCP Streamable-HTTP Server] POST Request Headers:', req.headers);
			logger.debug('[MCP Streamable-HTTP Server] POST Request Body:', req.body);

			const sessionId = req.headers['mcp-session-id'] as string;

			try {
				let transport: StreamableHTTPServerTransport;

				if (sessionId && transports[sessionId]) {
					// Reuse existing transport
					transport = transports[sessionId];
					logger.debug(
						`[MCP Streamable-HTTP Server] Using existing transport for session: ${sessionId}`
					);
				} else if (!sessionId && isInitializeRequest(req.body)) {
					// New initialization request - create new transport
					transport = new StreamableHTTPServerTransport({
						sessionIdGenerator: this.transportOptions.sessionIdGenerator ?? (() => randomUUID()),
						eventStore: this.eventStore,
						enableDnsRebindingProtection:
							this.transportOptions.enableDnsRebindingProtection ?? false,
						allowedHosts: this.transportOptions.allowedHosts ?? [],
						allowedOrigins: this.transportOptions.allowedOrigins ?? [],
						onsessioninitialized: (newSessionId: string) => {
							logger.info(`[MCP Streamable-HTTP Server] Session initialized: ${newSessionId}`);
							transports[newSessionId] = transport;
						},
					});

					// Set up onclose handler
					transport.onclose = () => {
						const sid = transport.sessionId;
						if (sid && transports[sid]) {
							logger.info(`[MCP Streamable-HTTP Server] Transport closed for session ${sid}`);
							delete transports[sid];
						}
					};

					// Connect transport to MCP server
					await this.mcpServer!.connect(transport);
					logger.debug('[MCP Streamable-HTTP Server] New transport connected to MCP server');
				} else {
					// Invalid request
					logger.error(
						'[MCP Streamable-HTTP Server] Invalid request - no session ID or not initialization'
					);
					return res.status(400).json({
						jsonrpc: '2.0',
						error: {
							code: -32000,
							message: 'Bad Request: No valid session ID provided',
						},
						id: null,
					});
				}

				// Handle the request with the transport
				await transport.handleRequest(req, res, req.body);
				logger.debug('[MCP Streamable-HTTP Server] POST request handled successfully');
				return;
			} catch (error) {
				logger.error('[MCP Streamable-HTTP Server] Error handling POST request:', error);
				if (!res.headersSent) {
					res.status(500).json({
						jsonrpc: '2.0',
						error: {
							code: -32603,
							message: 'Internal server error',
						},
						id: null,
					});
				}
				return;
			}
		});

		// GET /http - Handle SSE streams for existing sessions
		this.app.get('/http', async (req: Request, res: Response) => {
			logger.info('[MCP Streamable-HTTP Server] GET request for SSE stream');
			logger.debug('[MCP Streamable-HTTP Server] GET Request Headers:', req.headers);

			const sessionId = req.headers['mcp-session-id'] as string;
			if (!sessionId || !transports[sessionId]) {
				logger.error('[MCP Streamable-HTTP Server] Invalid or missing session ID for SSE stream');
				return res.status(400).send('Invalid or missing session ID');
			}

			// Check for resumability
			const lastEventId = req.headers['last-event-id'] as string;
			if (lastEventId) {
				logger.info(
					`[MCP Streamable-HTTP Server] Client reconnecting with Last-Event-ID: ${lastEventId}`
				);
			} else {
				logger.info(
					`[MCP Streamable-HTTP Server] Establishing new SSE stream for session ${sessionId}`
				);
			}

			try {
				const transport = transports[sessionId];
				await transport.handleRequest(req, res);
				logger.debug('[MCP Streamable-HTTP Server] GET request handled successfully');
				return;
			} catch (error) {
				logger.error('[MCP Streamable-HTTP Server] Error handling GET request:', error);
				if (!res.headersSent) {
					res.status(500).send('Error establishing SSE stream');
				}
				return;
			}
		});

		// DELETE /http - Handle session termination
		this.app.delete('/http', async (req: Request, res: Response) => {
			logger.info('[MCP Streamable-HTTP Server] DELETE request for session termination');
			logger.debug('[MCP Streamable-HTTP Server] DELETE Request Headers:', req.headers);

			const sessionId = req.headers['mcp-session-id'] as string;
			if (!sessionId || !transports[sessionId]) {
				logger.error('[MCP Streamable-HTTP Server] Invalid or missing session ID for termination');
				return res.status(400).send('Invalid or missing session ID');
			}

			try {
				const transport = transports[sessionId];
				await transport.handleRequest(req, res);
				logger.debug('[MCP Streamable-HTTP Server] DELETE request handled successfully');
				return;
			} catch (error) {
				logger.error('[MCP Streamable-HTTP Server] Error handling DELETE request:', error);
				if (!res.headersSent) {
					res.status(500).send('Error processing session termination');
				}
				return;
			}
		});

		// GET /http/stats - Get server statistics (debugging endpoint)
		this.app.get('/http/stats', (req: Request, res: Response) => {
			const stats = this.getStats();
			res.json(stats);
		});

		logger.info('[MCP Streamable-HTTP Server] Streamable-HTTP routes registered:');
		logger.info(
			'  GET /http (establish stream), POST /http (send/receive), DELETE /http (cleanup)'
		);
	}

	/**
	 * Get the HTTP server instance
	 */
	getHttpServer(): http.Server | undefined {
		return this.httpServer;
	}

	/**
	 * Get server stats
	 */
	getStats() {
		return {
			port: this.port,
			host: this.host,
			transport: 'streamable-http',
			isRunning: !!this.httpServer,
			eventStore: this.eventStore.getStats(),
			transportOptions: {
				hasSessionIdGenerator: !!this.transportOptions.sessionIdGenerator,
				hasEventStore: !!this.transportOptions.eventStore,
				enableDnsRebindingProtection: this.transportOptions.enableDnsRebindingProtection,
				allowedHosts: this.transportOptions.allowedHosts?.length || 0,
				allowedOrigins: this.transportOptions.allowedOrigins?.length || 0,
			},
		};
	}

	/**
	 * Get the transport instance
	 */
	getTransport(): StreamableHTTPServerTransport | undefined {
		return this.transport;
	}

	/**
	 * Clean up a specific stream from the event store
	 */
	cleanupStream(streamId: string): void {
		this.eventStore.cleanupStream(streamId);
	}
}

