import type { NextConfig } from 'next';
import os from 'os';

// Determine allowed development origins (local network IPs on port 3000)
const interfaces = os.networkInterfaces();
const allowedOrigins: string[] = ['http://localhost:3000'];
Object.values(interfaces).forEach(list =>
	list?.forEach(iface => {
		if (iface.family === 'IPv4' && !iface.internal) {
			allowedOrigins.push(`http://${iface.address}:3000`);
		}
	})
);

// const _isDev = process.env.NODE_ENV === 'development'; // Not currently used
const isStandalone = process.env.BUILD_STANDALONE === 'true';

const nextConfig: NextConfig = {
	reactStrictMode: true,
	// Use standalone output for production builds
	...(isStandalone && { output: 'standalone' as const }),
	// Disable ESLint during build to avoid config issues
	eslint: {
		ignoreDuringBuilds: true,
	},
	// Allow static asset requests from these origins in dev mode
	allowedDevOrigins: allowedOrigins,
	async rewrites() {
		const apiPort = process.env.API_PORT ?? '3001';
		return [
			{
				source: '/api/:path*',
				destination: `http://localhost:${apiPort}/api/:path*`, // Proxy to backend
			},
		];
	},
	// Allow cross-origin requests for Next.js static and HMR assets during dev
	async headers() {
		return [
			{
				source: '/_next/:path*',
				headers: [{ key: 'Access-Control-Allow-Origin', value: '*' }],
			},
		];
	},
};

export default nextConfig;

const config = {
  plugins: {
    "@tailwindcss/postcss": {},
    autoprefixer: {},
  },
};

export default config;

'use client'

import { useEffect } from 'react'

export default function Error({
  error,
  reset,
}: {
  error: Error & { digest?: string }
  reset: () => void
}) {
  useEffect(() => {
    console.error('Application error:', error)
  }, [error])

  return (
    <div className="min-h-screen flex items-center justify-center">
      <div className="text-center space-y-6 max-w-md">
        <div className="space-y-2">
          <h2 className="text-2xl font-bold text-destructive">
            Something went wrong!
          </h2>
          <p className="text-muted-foreground">
            An error occurred while loading the application.
          </p>
        </div>

        <div className="bg-destructive/10 border border-destructive/20 rounded-lg p-4">
          <p className="text-sm text-destructive font-mono">
            {error.message || 'Unknown error occurred'}
          </p>
        </div>

        <button
          onClick={reset}
          className="bg-primary hover:bg-primary/90 text-primary-foreground px-4 py-2 rounded-lg transition-colors"
        >
          Try again
        </button>
      </div>
    </div>
  )
}

@import "tailwindcss";

:root {
    font-family: Inter, sans-serif;
    background: var(--color-background);
    background-color: var(--color-background);
}

@theme {
    /* Base colors */
    --color-background: #0F0F0F;
    --color-foreground: #fafafa;

    /* Primary colors */
    --color-primary: #099250;
    --color-primary-foreground: #fff;

    /* Status colors */
    --color-destructive: #D92D20;
    --color-destructive-foreground: #fff;
    --color-warning: #CA8504;
    --color-warning-foreground: #fff;
    --color-success: #099250;
    --color-success-foreground: #fff;

    /* Surface colors */
    --color-secondary: #1a1a1a;
    --color-secondary-foreground: #fafafa;
    --color-muted: #262626;
    --color-muted-foreground: #a1a1aa;
    --color-accent: #262626;
    --color-accent-foreground: #fafafa;

    /* UI element colors */
    --color-card: #0a0a0a;
    --color-card-foreground: #fafafa;
    --color-popover: #0a0a0a;
    --color-popover-foreground: #fafafa;
    --color-border: #262626;
    --color-input: #262626;
    --color-ring: #099250;

    /* Glass effect variables */
    --color-glass-bg: rgba(255, 255, 255, 0.05);
    --color-glass-border: rgba(255, 255, 255, 0.1);

    /* Spacing and sizing */
    --radius: 0.5rem;
    --radius-sm: 0.25rem;
    --radius-lg: 0.75rem;

    /* Typography */
    --font-sans: Inter, ui-sans-serif, system-ui, sans-serif;
    --font-mono: "JetBrains Mono", ui-monospace, monospace;
}

* {
    border-color: var(--color-border);
}

body {
    color: var(--color-foreground);
    background: var(--color-background);
    font-family: var(--font-sans);
}

/* Glass effect utilities */
.glass {
    background: var(--color-glass-bg);
    backdrop-filter: blur(12px);
    border: 1px solid var(--color-glass-border);
}

/* Smooth transitions */
.transition-smooth {
    transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Custom scrollbar */
.scrollbar-thin::-webkit-scrollbar {
    width: 6px;
}

.scrollbar-thin::-webkit-scrollbar-track {
    background: var(--color-muted);
    border-radius: var(--radius-sm);
}

.scrollbar-thin::-webkit-scrollbar-thumb {
    background: var(--color-border);
    border-radius: var(--radius-sm);
}

.scrollbar-thin::-webkit-scrollbar-thumb:hover {
    background: var(--color-muted-foreground);
}

/* Focus styles */
.focus-visible:focus-visible {
    outline: 2px solid var(--color-ring);
    outline-offset: 2px;
}

