        ...(currentSessionId && { sessionId: currentSessionId })
      }

      const response = await fetch('/api/llm/switch', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestBody)
      })

      const result = await response.json()

      if (result.success) {
        setCurrentModel(model.name)
        setModelSwitchError(null)
      } else {
        setModelSwitchError(result.error || 'Failed to switch model')
      }
    } catch (error) {
      setModelSwitchError('Network error while switching model')
    } finally {
      setIsLoadingModel(false)
    }
  }
  */

  // Current model fetching - Temporarily disabled (will be developed later)
  /*
  React.useEffect(() => {
    const fetchCurrentModel = async () => {
      try {
        const url = currentSessionId
          ? `/api/llm/current?sessionId=${currentSessionId}`
          : '/api/llm/current'

        const response = await fetch(url)
        if (response.ok) {
          const config = await response.json()
          // Handle the correct API response structure: data.llmConfig
          const llmConfig = config.data?.llmConfig

          if (llmConfig) {
            const matchedModel = models.find(m => m.model === llmConfig.model)

            setCurrentModel(matchedModel
              ? matchedModel.name
              : `${llmConfig.provider}/${llmConfig.model}`
            )
          } else {
            console.warn('Unexpected API response structure:', config)
            setCurrentModel('Unknown')
          }
        }
      } catch (error) {
        console.error('Failed to fetch current model:', error)
        setCurrentModel('Unknown')
      }
    }

    fetchCurrentModel()
  }, [currentSessionId, models])
  */

  // Send handler logic
  const handleSend = () => {
    const trimmed = text.trim()
    // Allow sending if we have text OR image
    if (!trimmed && !imageData) return

    onSend(trimmed, imageData ?? undefined)

    // Reset state
    setText('')
    setImageData(null)

    // Reset textarea height
    if (textareaRef.current) {
      textareaRef.current.style.height = 'auto'
      textareaRef.current.style.overflowY = 'hidden'
    }
  }

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault()
      handleSend()
    }
  }


  const canSend = (text.trim() || imageData) && !disabled
  const hasAttachments = imageData

  return (
    <div className="border rounded-lg bg-background">
      {/* Hidden file inputs */}
      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        onChange={handleImageUpload}
        className="hidden"
      />

      {/* Error messages */}
      {fileUploadError && (
        <div className="p-3 border-b">
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              {fileUploadError}
            </AlertDescription>
          </Alert>
        </div>
      )}

      {/* Model selector - Temporarily removed (will be developed later) */}
      {/*
      <div className="flex items-center justify-between p-3 border-b">
        <div className="flex items-center gap-2">
          <span className="text-sm font-medium">Model:</span>
          <Select
            value={currentModel}
            onValueChange={(modelName) => {
              const model = models.find(m => m.name === modelName)
              if (model) handleModelSwitch(model)
            }}
            disabled={isLoadingModel || disabled}
          >
            <SelectTrigger className="w-48">
              <SelectValue>
                {isLoadingModel ? (
                  <div className="flex items-center gap-2">
                    <Loader2 className="w-4 h-4 animate-spin" />
                    <span>Switching...</span>
                  </div>
                ) : (
                  currentModel
                )}
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {models.map((model) => (
                <SelectItem key={model.model} value={model.name}>
                  {model.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>
      */}

      {/* Attachment previews */}
      {hasAttachments && (
        <div className="p-3 border-b">
          {imageData && (
            <div className="flex items-center gap-3 p-3 bg-muted rounded-lg">
              <img
                src={`data:${imageData.mimeType};base64,${imageData.base64}`}
                alt="Uploaded"
                className="w-12 h-12 object-cover rounded"
              />
              <div className="flex-1">
                <p className="text-sm font-medium">Image uploaded</p>
                <p className="text-xs text-muted-foreground">{imageData.mimeType}</p>
              </div>
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setImageData(null)}
                disabled={disabled}
              >
                <X className="w-4 h-4" />
              </Button>
            </div>
          )}

        </div>
      )}

      {/* Input area */}
      <div className="p-3">
        <div className="flex gap-2">
          <div className="flex-1">
            <Textarea
              ref={textareaRef}
              value={text}
              onChange={(e) => setText(e.target.value)}
              onKeyDown={handleKeyDown}
              placeholder={placeholder}
              disabled={disabled}
              className="min-h-9 resize-none border-0 shadow-none focus-visible:ring-0 p-0"
              style={{ overflow: 'hidden' }}
            />
          </div>

          <div className="flex items-end gap-1">
            {/* Attachment buttons */}
            <Button
              variant="ghost"
              size="sm"
              onClick={() => fileInputRef.current?.click()}
              disabled={disabled}
              className="shrink-0"
              title="Upload image"
            >
              <ImageIcon className="w-4 h-4" />
            </Button>


            {/* Send button */}
            <Button
              onClick={handleSend}
              disabled={!canSend}
              size="sm"
              className="shrink-0"
            >
              <Send className="w-4 h-4" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { RefreshCw, Zap, AlertCircle } from "lucide-react"
import { cn } from "@/lib/utils"

interface LlmConfig {
  provider: string
  model: string
  maxIterations?: number
}

interface LlmModelDisplayProps {
  className?: string
}

export function LlmModelDisplay({ className }: LlmModelDisplayProps) {
  const [llmConfig, setLlmConfig] = React.useState<LlmConfig | null>(null)
  const [isLoading, setIsLoading] = React.useState(true)
  const [error, setError] = React.useState<string | null>(null)

  const fetchLlmConfig = React.useCallback(async () => {
    try {
      setIsLoading(true)
      setError(null)

      const response = await fetch('/api/llm/config')
      if (!response.ok) {
        throw new Error(`Failed to fetch LLM config: ${response.statusText}`)
      }

      const data = await response.json()
      if (data.success && data.data?.llmConfig) {
        setLlmConfig(data.data.llmConfig)
      } else {
        throw new Error('Invalid response format')
      }
    } catch (err) {
      console.error('Error fetching LLM config:', err)
      setError(err instanceof Error ? err.message : 'Failed to load LLM config')
    } finally {
      setIsLoading(false)
    }
  }, [])

  // Fetch config on mount
  React.useEffect(() => {
    fetchLlmConfig()
  }, [fetchLlmConfig])

  const getProviderDisplayName = (provider: string): string => {
    const providerNames: Record<string, string> = {
      openai: 'OpenAI',
      anthropic: 'Anthropic',
      gemini: 'Gemini',
      openrouter: 'OpenRouter',
      ollama: 'Ollama',
      aws: 'AWS Bedrock',
      azure: 'Azure OpenAI',
      qwen: 'Qwen'
    }
    return providerNames[provider] || provider
  }

  const getProviderIcon = (provider: string): React.ReactNode => {
    switch (provider) {
      case 'openai':
        return <span className="text-green-600">🤖</span>
      case 'anthropic':
        return <span className="text-orange-600">🧠</span>
      case 'gemini':
        return <span className="text-blue-600">✨</span>
      case 'openrouter':
        return <span className="text-purple-600">🔀</span>
      case 'ollama':
        return <span className="text-gray-600">🦙</span>
      case 'aws':
        return <span className="text-orange-500">☁️</span>
      case 'azure':
        return <span className="text-blue-500">🌐</span>
      case 'qwen':
        return <span className="text-red-600">🔥</span>
      default:
        return <Zap className="w-3 h-3" />
    }
  }

  if (isLoading) {
    return (
      <div className={cn("flex items-center space-x-2", className)}>
        <RefreshCw className="w-3 h-3 animate-spin text-muted-foreground" />
        <span className="text-xs text-muted-foreground">Loading...</span>
      </div>
    )
  }

  if (error) {
    return (
      <div className={cn("flex items-center space-x-2", className)}>
        <AlertCircle className="w-3 h-3 text-red-500" />
        <Button
          variant="ghost"
          size="sm"
          onClick={fetchLlmConfig}
          className="h-auto p-0 text-xs text-red-500 hover:text-red-600"
        >
          Retry
        </Button>
      </div>
    )
  }

  if (!llmConfig) {
    return (
      <div className={cn("flex items-center space-x-2", className)}>
        <AlertCircle className="w-3 h-3 text-muted-foreground" />
        <span className="text-xs text-muted-foreground">No LLM configured</span>
      </div>
    )
  }

  return (
    <div className={cn("flex items-center space-x-2", className)}>
      <Badge 
        variant="secondary" 
        className="text-xs flex items-center gap-1 bg-muted/50 text-muted-foreground border-border/50"
      >
        {getProviderIcon(llmConfig.provider)}
        <span className="font-medium">{getProviderDisplayName(llmConfig.provider)}</span>
        <span className="text-muted-foreground/80">•</span>
        <span className="font-mono">{llmConfig.model}</span>
      </Badge>
      <Button
        variant="ghost"
        size="sm"
        onClick={fetchLlmConfig}
        className="h-auto p-1 opacity-50 hover:opacity-100 transition-opacity"
        title="Refresh LLM config"
      >
        <RefreshCw className="w-3 h-3" />
      </Button>
    </div>
  )
}

"use client"

import * as React from "react"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { 
  Settings,
  ChevronDown,
  ChevronUp,
  Loader2,
  AlertCircle,
  CheckCircle,
  Key,
  Globe,
  Zap
} from "lucide-react"
import { cn } from "@/lib/utils"
import { LLMProvider, LLMConfig, LLMSwitchRequest } from "@/types/server-registry"

interface LLMSelectorProps {
  isOpen: boolean
  onClose: () => void
  currentSessionId?: string
  onConfigChange?: (config: LLMConfig) => void
}

export function LLMSelector({ isOpen, onClose, currentSessionId, onConfigChange }: LLMSelectorProps) {
  // State management
  const [providers, setProviders] = React.useState<Record<string, LLMProvider>>({})
  const [currentConfig, setCurrentConfig] = React.useState<LLMConfig | null>(null)
  const [selectedProvider, setSelectedProvider] = React.useState<string>('')
  const [selectedModel, setSelectedModel] = React.useState<string>('')
  const [selectedRouter, setSelectedRouter] = React.useState<string>('vercel')
  const [apiKey, setApiKey] = React.useState<string>('')
  const [baseURL, setBaseURL] = React.useState<string>('')
  const [showAdvanced, setShowAdvanced] = React.useState(false)
  const [isLoading, setIsLoading] = React.useState(false)
  const [isSwitching, setIsSwitching] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const [success, setSuccess] = React.useState<string | null>(null)
  const [hasExistingApiKey, setHasExistingApiKey] = React.useState<boolean>(false)

  // Base URL validation logic
  const validateBaseURL = (url: string): { isValid: boolean; error?: string } => {
    if (!url.trim()) {
      return { isValid: true } // Empty URL is valid (optional field)
    }

    try {
      const parsedUrl = new URL(url)

      // Check if protocol is http or https
      if (!['http:', 'https:'].includes(parsedUrl.protocol)) {
        return {
          isValid: false,
          error: 'URL must use http:// or https:// protocol'
        }
      }

      // Check if URL includes '/v1' for OpenAI compatibility
      if (!parsedUrl.pathname.includes('/v1')) {
        return {
          isValid: false,
          error: 'URL must include "/v1" path for OpenAI compatibility'
        }
      }

      return { isValid: true }
    } catch (error) {
      return {
        isValid: false,
        error: 'Invalid URL format'
      }
    }
  }

  // Data fetching logic
  React.useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true)
      try {
        const [currentRes, providersRes] = await Promise.all([
          fetch('/api/llm/current'),
          fetch('/api/llm/providers')
        ])

        if (currentRes.ok) {
          const current = await currentRes.json()
          setCurrentConfig(current)
          setHasExistingApiKey(!!current.config.apiKey)
        }

        if (providersRes.ok) {
          const providersData = await providersRes.json()
          setProviders(providersData.providers)
        }
      } catch (err) {
        console.error('Failed to fetch LLM data:', err)
        setError('Failed to load LLM configuration')
      } finally {
        setIsLoading(false)
      }
    }

    fetchData()
  }, [])

  // Form reset logic
  React.useEffect(() => {
    if (isOpen && currentConfig) {
      setSelectedProvider(currentConfig.config.provider)
      setSelectedModel(currentConfig.config.model)
      setSelectedRouter(currentConfig.serviceInfo.router || 'vercel')

      // Keep existing apiKey value instead of resetting to empty
      if (!hasExistingApiKey) {
        setApiKey('')
      }

      setBaseURL(currentConfig.config.baseURL || '')
      setShowAdvanced(false)
      setError(null)
      setSuccess(null)
    }
  }, [isOpen, currentConfig, hasExistingApiKey])

  // Dependent field management
  React.useEffect(() => {
    if (selectedProvider) {
      setSelectedModel('') // Reset model when provider changes

      // Auto-select appropriate router if current one isn't supported
      const provider = providers[selectedProvider]
      if (provider && !provider.supportedRouters.includes(selectedRouter)) {
        setSelectedRouter(provider.supportedRouters[0] || 'vercel')
      }

      // Clear baseURL if provider doesn't support it
      if (provider && !provider.supportsBaseURL) {
        setBaseURL('')
      }
    }
  }, [selectedProvider, providers, selectedRouter])

  // Error handling logic
  const handleSwitchError = (result: any) => {
    if (result.errors && result.errors.length > 0) {
      const primaryError = result.errors[0]
      let errorMessage = primaryError.message

      // For API key errors, show the suggested action
      if (primaryError.type === 'missing_api_key' && primaryError.suggestedAction) {
        errorMessage += `. ${primaryError.suggestedAction}`
      }

      setError(errorMessage)
    } else {
      // Fallback to old format or generic error
      setError(result.error || 'Failed to switch LLM')
    }
  }

  // Model switch handler
  const handleSwitch = async () => {
    if (!selectedProvider || !selectedModel || !selectedRouter) {
      setError('Please select provider, model, and router')
      return
    }

    // Validate baseURL if provided
    if (baseURL) {
      const urlValidation = validateBaseURL(baseURL)
      if (!urlValidation.isValid) {
        setError(urlValidation.error || 'Invalid base URL')
        return
      }
    }

    setIsSwitching(true)
    setError(null)
    setSuccess(null)

    try {
      const requestBody: LLMSwitchRequest = {
        provider: selectedProvider,
        model: selectedModel,
        router: selectedRouter
      }

      if (apiKey) requestBody.apiKey = apiKey
      if (baseURL) requestBody.baseURL = baseURL
      if (currentSessionId) requestBody.sessionId = currentSessionId

      const response = await fetch('/api/llm/switch', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestBody)
      })

      const result = await response.json()

      if (result.success) {
        setCurrentConfig(result.config)
        setSuccess(result.message)
        onConfigChange?.(result.config)

        setTimeout(() => {
          onClose()
          setSuccess(null)
        }, 1500)
      } else {
        handleSwitchError(result)
      }
    } catch (err) {
      setError('Network error while switching LLM')
    } finally {
      setIsSwitching(false)
    }
  }

  // Helper functions
  const getCurrentDisplayName = () => {
    if (!currentConfig) return 'Loading...'
    const provider = providers[currentConfig.config.provider]
    return `${provider?.name || currentConfig.config.provider} / ${currentConfig.config.model}`
  }

  const getAvailableRouters = () => {
    if (!selectedProvider || !providers[selectedProvider]) return []
    return providers[selectedProvider].supportedRouters
  }

  const supportsBaseURL = () => {
    return selectedProvider && providers[selectedProvider]?.supportsBaseURL
  }

  const hasRouterChoice = () => {
    return getAvailableRouters().length > 1
  }

  const getSelectedProviderModels = () => {
    if (!selectedProvider || !providers[selectedProvider]) return []
    return providers[selectedProvider].models
  }

  if (isLoading) {
    return (
      <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
        <DialogContent className="max-w-md">
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
            <span className="ml-2 text-muted-foreground">Loading LLM configuration...</span>
          </div>
        </DialogContent>
      </Dialog>
    )
  }

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Settings className="w-5 h-5" />
            LLM Model Selector
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4">
          {/* Current configuration display */}
          <div className="bg-muted/50 rounded-lg p-3">
            <p className="text-sm font-medium mb-1">Current Configuration</p>
            <p className="text-sm text-muted-foreground">{getCurrentDisplayName()}</p>
          </div>

          {/* Error/Success messages */}
          {error && (
            <Alert variant="destructive">
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}

          {success && (
            <Alert className="border-green-200 bg-green-50">
              <CheckCircle className="h-4 w-4 text-green-600" />
              <AlertDescription className="text-green-800">{success}</AlertDescription>
            </Alert>
          )}

          {/* Provider selection */}
          <div>
            <label className="text-sm font-medium mb-2 block">Provider *</label>
            <Select
              value={selectedProvider}
              onValueChange={setSelectedProvider}
              disabled={isSwitching}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select a provider" />
              </SelectTrigger>
              <SelectContent>
                {Object.entries(providers).map(([key, provider]) => (
                  <SelectItem key={key} value={key}>
                    <div className="flex items-center gap-2">
                      <Zap className="w-4 h-4" />
                      {provider.name}
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Model selection */}
          <div>
            <label className="text-sm font-medium mb-2 block">Model *</label>
            <Select
              value={selectedModel}
              onValueChange={setSelectedModel}
              disabled={!selectedProvider || isSwitching}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select a model" />
              </SelectTrigger>
              <SelectContent>
                {getSelectedProviderModels().map((model) => (
                  <SelectItem key={model} value={model}>
                    {model}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Router selection (only show if multiple options) */}
          {hasRouterChoice() && (
            <div>
              <label className="text-sm font-medium mb-2 block">Router *</label>
              <Select
                value={selectedRouter}
                onValueChange={setSelectedRouter}
                disabled={isSwitching}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {getAvailableRouters().map((router) => (
                    <SelectItem key={router} value={router}>
                      <div className="flex items-center gap-2">
                        <Globe className="w-4 h-4" />
                        {router}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Advanced options toggle */}
          <Button
            type="button"
            variant="ghost"
            onClick={() => setShowAdvanced(!showAdvanced)}
            className="w-full justify-between"
            disabled={isSwitching}
          >
            <span>Advanced Options</span>
            {showAdvanced ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </Button>

          {/* Advanced options */}
          {showAdvanced && (
            <div className="space-y-4 border-t pt-4">
              {/* API Key */}
              <div>
                <label className="text-sm font-medium mb-2 block flex items-center gap-2">
                  <Key className="w-4 h-4" />
                  API Key
                  {hasExistingApiKey && (
                    <span className="text-xs text-muted-foreground">(leave empty to keep existing)</span>
                  )}
                </label>
                <Input
                  type="password"
                  value={apiKey}
                  onChange={(e) => setApiKey(e.target.value)}
                  placeholder={hasExistingApiKey ? "Enter new API key (optional)" : "Enter API key"}
                  disabled={isSwitching}
                />
              </div>

              {/* Base URL (only show if provider supports it) */}
              {supportsBaseURL() && (
                <div>
                  <label className="text-sm font-medium mb-2 block flex items-center gap-2">
                    <Globe className="w-4 h-4" />
                    Base URL
                  </label>
                  <Input
                    value={baseURL}
                    onChange={(e) => setBaseURL(e.target.value)}
                    placeholder="https://api.example.com/v1"
                    disabled={isSwitching}
                  />
                  <p className="text-xs text-muted-foreground mt-1">
                    Custom API endpoint (must include /v1 path)
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <DialogFooter>
          <Button
            type="button"
            variant="outline"
            onClick={onClose}
            disabled={isSwitching}
          >
            Cancel
          </Button>
          <Button
            onClick={handleSwitch}
            disabled={!selectedProvider || !selectedModel || !selectedRouter || isSwitching}
          >
            {isSwitching ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin mr-2" />
                Switching...
              </>
            ) : (
              'Switch Model'
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Avatar, AvatarFallback } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { 
  User, 
  Settings, 
  Wrench,
  ChevronDown,
  ChevronUp,
  Loader2,
  AlertTriangle,
  CheckCircle,
  FileText
} from "lucide-react"
import Image from "next/image"
import { cn, formatTimestamp } from "@/lib/utils"
import { Message, ContentPart } from "@/types/server-registry"
import { ThinkingIndicator } from "./thinking-indicator"

interface MessageListProps {
  messages: Message[]
  className?: string
  maxHeight?: string
}

export function MessageList({ messages, className, maxHeight = "h-full" }: MessageListProps) {
  const [toolResultsExpanded, setToolResultsExpanded] = React.useState<Record<string, boolean>>({})
  const [toolPanelsExpanded, setToolPanelsExpanded] = React.useState<Record<string, boolean>>({})
  const endRef = React.useRef<HTMLDivElement>(null)
  const scrollAreaRef = React.useRef<HTMLDivElement>(null)

  // Auto-scroll to bottom when new messages arrive
  React.useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' })
    if (scrollAreaRef.current) {
      scrollAreaRef.current.scrollTop = scrollAreaRef.current.scrollHeight
    }
  }, [messages])

  // Data URI validation for security
  function isValidDataUri(src: string): boolean {
    const dataUriRegex = /^data:image\/(png|jpeg|jpg|gif|webp|svg\+xml);base64,[A-Za-z0-9+/]+={0,2}$/i
    return dataUriRegex.test(src)
  }

  // Message classification logic
  const classifyMessage = (msg: Message, idx: number, totalMessages: number) => {
    const isUser = msg.role === 'user'
    const isAi = msg.role === 'assistant'
    const isSystem = msg.role === 'system'
    const isLastMessage = idx === totalMessages - 1
    const isToolCall = !!(msg.toolName && msg.toolArgs)
    const isToolResult = !!(msg.toolName && msg.toolResult)

    // Also consider system messages with tool indicators as tool related
    const isSystemToolMessage = isSystem && msg.content !== null && msg.content !== undefined && (
      String(msg.content).includes('🔧 Using tool:') || 
      String(msg.content).includes('📋 Tool Result:') ||
      String(msg.content).includes('⏳') ||
      String(msg.content).includes('✅ Tool') ||
      String(msg.content).includes('❌ Tool')
    )

    const isToolRelated = isToolCall || isToolResult || isSystemToolMessage


    return {
      isUser,
      isAi,
      isSystem,
      isLastMessage,
      isToolCall,
      isToolResult,
      isToolRelated,
      isSystemToolMessage
    }
  }

  // Tool expansion logic (for detailed tool info within panels)
  const getExpandedState = (msg: Message, isToolRelated: boolean, isLastMessage: boolean) => {
    // Auto-expand tool messages with results
    if (msg.role === 'tool' && msg.toolResult) {
      return true;
    }
    // Auto-expand system tool result messages
    if (msg.role === 'system' && msg.content !== null && msg.content !== undefined && String(msg.content).includes('📋 Tool Result:')) {
      return true;
    }
    // Default to expanded for tool details within panels
    return isToolRelated && isLastMessage
  }


  const toggleToolResultExpansion = (messageId: string) => {
    setToolResultsExpanded(prev => ({
      ...prev,
      [messageId]: !prev[messageId]
    }))
  }


  const toggleToolPanelExpansion = (messageId: string) => {
    setToolPanelsExpanded(prev => ({
      ...prev,
      [messageId]: !prev[messageId]
    }))
  }

  const isToolPanelExpanded = (messageId: string) => {
    return toolPanelsExpanded[messageId] ?? false // Default to expanded
  }

  // Dynamic styling logic
  const getMessageContainerClass = (isUser: boolean, isSystem: boolean, isToolProgress?: boolean, isSystemToolMessage?: boolean) => {
    return cn(
      "flex items-end w-full gap-2 mb-4",
      isUser ? "justify-end" : "justify-start",
      isSystem && !isToolProgress && !isSystemToolMessage && "justify-center",
      (isToolProgress || isSystemToolMessage) && "justify-start"
    )
  }

  const getBubbleClass = (role: string, isUser: boolean, isAi: boolean, isSystem: boolean, isToolProgress?: boolean, isSystemToolMessage?: boolean) => {
    return cn(
      role === 'tool'
        ? "max-w-lg w-full overflow-auto text-muted-foreground/70 bg-secondary border border-muted/30 rounded-md text-sm p-3 min-h-[2rem]"
        : isSystemToolMessage
        ? "max-w-lg w-full overflow-auto text-muted-foreground/70 bg-secondary border border-muted/30 rounded-md text-sm p-3 min-h-[2rem]"
        : isUser
        ? "p-3 rounded-xl shadow-sm max-w-[75%] bg-primary text-primary-foreground rounded-br-none text-sm"
        : isAi
        ? "p-3 rounded-xl shadow-sm max-w-[75%] bg-card text-card-foreground border border-border rounded-bl-none text-sm"
        : isSystem && isToolProgress
        ? "p-2 px-3 rounded-lg text-xs bg-secondary/50 border border-muted/30 text-muted-foreground font-mono max-w-fit"
        : isSystem
        ? "p-3 shadow-none w-full bg-transparent text-xs text-muted-foreground italic text-center border-none"
        : ""
    )
  }

  // Tool result type checking
  const isToolResultError = (toolResult: any) => {
    return toolResult && (toolResult.error || toolResult.isError)
  }

  const isToolResultContent = (toolResult: any) => {
    return toolResult && toolResult.content && Array.isArray(toolResult.content)
  }

  const isImagePart = (part: any) => {
    return part && (part.type === 'image' || part.base64 || part.mimeType?.startsWith('image/'))
  }

  const isTextPart = (part: any) => {
    return part && (part.type === 'text' || part.text)
  }

  const isFilePart = (part: any) => {
    return part && (part.type === 'file' || part.filename)
  }

  // Content part rendering
  const renderImagePart = (part: any, index: number) => {
    const src = part.base64 && part.mimeType
      ? `data:${part.mimeType};base64,${part.base64}`
      : part.base64

    if (src && src.startsWith('data:') && !isValidDataUri(src)) {
      return null
    }

    return (
      <img 
        key={index} 
        src={src} 
        alt="Content image" 
        className="my-1 max-h-48 w-auto rounded border border-border" 
      />
    )
  }

  const renderTextPart = (part: any, index: number) => {
    return (
      <pre key={index} className="whitespace-pre-wrap overflow-auto bg-background/50 p-2 rounded text-xs text-muted-foreground my-1">
        {part.text}
      </pre>
    )
  }

  const renderFilePart = (part: any, index: number) => {
    return (
      <div key={index} className="my-1 flex items-center gap-2 p-2 rounded border border-border bg-muted/50">
        <FileText className="h-4 w-4 text-muted-foreground" />
        <span className="text-xs text-muted-foreground">
          {part.filename || 'File attachment'} ({part.mimeType})
        </span>
      </div>
    )
  }

  const renderUnknownPart = (part: any, index: number) => {
    return (
      <pre key={index} className="whitespace-pre-wrap overflow-auto bg-muted/50 p-2 rounded text-xs my-1">
        {JSON.stringify(part, null, 2)}
      </pre>
    )
  }

  const renderGenericResult = (toolResult: any) => {
    return (
      <pre className="whitespace-pre-wrap overflow-auto bg-background/50 p-2 rounded text-xs text-muted-foreground">
        {typeof toolResult === 'object' 
          ? JSON.stringify(toolResult, null, 2) 
          : String(toolResult)}
      </pre>
    )
  }

  // Tool result rendering logic
  const renderToolResult = (toolResult: any) => {
    if (isToolResultError(toolResult)) {
      return (
        <pre className="whitespace-pre-wrap overflow-auto bg-red-100 text-red-700 p-2 rounded text-xs">
          {typeof toolResult.error === 'object'
            ? JSON.stringify(toolResult.error, null, 2)
            : String(toolResult.error)}
        </pre>
      )
    }

    if (isToolResultContent(toolResult)) {
      return toolResult.content.map((part: any, index: number) => {
        if (isImagePart(part)) {
          return renderImagePart(part, index)
        }
        if (isTextPart(part)) {
          return renderTextPart(part, index)
        }
        if (isFilePart(part)) {
          return renderFilePart(part, index)
        }
        return renderUnknownPart(part, index)
      })
    }

    return renderGenericResult(toolResult)
  }


  // Tool status indicators
  const getToolStatusIcon = (msg: Message, allMessages: Message[]) => {
    // For tool messages, check their own result
    if (msg.toolResult) {
      if (isToolResultError(msg.toolResult)) {
        return <AlertTriangle className="mx-2 h-4 w-4 text-red-500" />
      }
      return <CheckCircle className="mx-2 h-4 w-4 text-green-500" />
    }

    // For system tool messages, check if there's a corresponding result message
    if (msg.role === 'system' && msg.toolExecutionId) {
      const hasResult = allMessages.some(m => 
        m.role === 'system' && 
        m.toolExecutionId === msg.toolExecutionId && 
        m.content && 
        String(m.content).includes('📋 Tool Result:')
      );

      if (hasResult) {
        return <CheckCircle className="mx-2 h-4 w-4 text-green-500" />
      }
    }

    // Default to loading state
    return <Loader2 className="mx-2 h-4 w-4 animate-spin text-muted-foreground" />
  }

  // Message metadata display
  const renderMessageMetadata = (msg: Message, isAi: boolean, timestampStr: string) => {
    return (
      <div className="text-xs text-muted-foreground mt-1 px-1 flex items-center gap-2">
        <span>{timestampStr}</span>
        {isAi && msg.tokenCount && (
          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-muted/50 text-xs">
            <span className="w-1.5 h-1.5 rounded-full bg-green-500"></span>
            {msg.tokenCount} tokens
          </span>
        )}
        {isAi && msg.model && (
          <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-muted/30 text-xs">
            {msg.model}
          </span>
        )}
      </div>
    )
  }

  // Role icon
  const getRoleIcon = (role: string) => {
    switch (role) {
      case 'user':
        return <User className="w-4 h-4" />
      case 'assistant':
        return (
          <Image 
            src="/cipher-logo.svg" 
            alt="Cipher" 
            width={16} 
            height={16} 
            className="w-4 h-4"
          />
        )
      case 'system':
        return <Settings className="w-4 h-4" />
      case 'tool':
        return <Wrench className="w-4 h-4" />
      default:
        return (
          <Image 
            src="/cipher-logo.svg" 
            alt="Cipher" 
            width={16} 
            height={16} 
            className="w-4 h-4"
          />
        )
    }
  }

  // Content rendering
  const renderContent = (msg: Message, isToolProgress?: boolean) => {
    // Handle null/undefined content for tool messages
    if (msg.content === null || msg.content === undefined) {
      // For tool messages with results, show the result or a summary
      if (msg.role === 'tool' && msg.toolResult) {
        const resultText = typeof msg.toolResult === 'string' 
          ? msg.toolResult 
          : JSON.stringify(msg.toolResult, null, 2);

        return (
          <div className="text-sm text-muted-foreground">
            {resultText.length > 100 
              ? `${resultText.substring(0, 100)}... (Click to view full details)`
              : resultText}
          </div>
        );
      }
      // For tool messages without results, show a placeholder
      if (msg.role === 'tool') {
        return (
          <div className="text-sm text-muted-foreground italic">
            Tool execution in progress...
          </div>
        );
      }
      return <div></div>;
    }

    if (typeof msg.content === 'string') {
      // Handle empty strings for tool messages
      if (msg.role === 'tool' && msg.content === '') {
        return null;
      }

      // Add animation for progress messages
      if (isToolProgress && msg.content !== null && msg.content !== undefined && String(msg.content).includes('⏳')) {
        return (
          <div className="flex items-center gap-2 whitespace-pre-wrap">
            <Loader2 className="h-3 w-3 animate-spin" />
            <span>{String(msg.content).replace('⏳ ', '')}</span>
          </div>
        )
      }

      // Enhanced formatting for tool result messages
      if (isToolProgress && msg.content !== null && msg.content !== undefined && String(msg.content).includes('📋 Tool Result:')) {
        const [header, ...contentParts] = String(msg.content).split('\n');
        const resultContent = contentParts.join('\n');
        const isExpanded = false;

        return (
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <div className="font-medium text-sm">{header}</div>
              {resultContent && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => toggleToolResultExpansion(msg.id)}
                  className="h-6 w-6 p-0"
                >
                  {isExpanded ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
                </Button>
              )}
            </div>
            {resultContent && isExpanded && (
              <pre className="whitespace-pre-wrap overflow-auto bg-muted/30 p-3 rounded-md text-xs border border-muted/50 max-h-48">
                {resultContent}
              </pre>
            )}
            {resultContent && !isExpanded && (
              <div className="text-xs text-muted-foreground italic">
                Tool result collapsed. Click to expand.
              </div>
            )}
          </div>
        )
      }

      return <div className="whitespace-pre-wrap">{msg.content}</div>
    }

    if (Array.isArray(msg.content)) {
      return msg.content.map((part: ContentPart, index: number) => {
        if (isImagePart(part)) {
          return renderImagePart(part, index)
        }
        if (isTextPart(part)) {
          return <div key={index} className="whitespace-pre-wrap">{part.text}</div>
        }
        if (isFilePart(part)) {
          return renderFilePart(part, index)
        }
        return renderUnknownPart(part, index)
      })
    }

    if (typeof msg.content === 'object') {
      return (
        <pre className="whitespace-pre-wrap overflow-auto bg-muted/50 p-2 rounded text-xs">
          {JSON.stringify(msg.content, null, 2)}
        </pre>
      )
    }

    return <div>{String(msg.content)}</div>
  }

  // Check if there's a thinking message
  const hasThinkingMessage = messages.some(
    msg => msg.role === 'system' && msg.content === 'Cipher is thinking...'
  );

  return (
    <ScrollArea className={cn(maxHeight, className, "flex-1 scrollbar-thin")} ref={scrollAreaRef}>
      <div className="space-y-1 p-4">
        {messages
          .filter(msg => {
            // Filter out thinking messages as they'll be handled by ThinkingIndicator
            if (msg.role === 'system' && msg.content === 'Cipher is thinking...') {
              return false;
            }

            // Filter out empty messages, but allow tool messages with null content
            if (msg.role === 'tool') {
              // Tool messages should be displayed even with null content
              return true;
            }

            if (!msg.content || 
                (typeof msg.content === 'string' && msg.content.trim() === '') ||
                (Array.isArray(msg.content) && msg.content.length === 0)) {
              return false;
            }
            return true;
          })
          .map((msg, idx) => {
          const {
            isUser,
            isAi,
            isSystem,
            isLastMessage,
            isToolRelated,
            isSystemToolMessage
          } = classifyMessage(msg, idx, messages.length)

          // Detect tool progress messages
          const isToolProgress = !!(isSystem && msg.toolExecutionId && 
            msg.content !== null && msg.content !== undefined && (
             String(msg.content).includes('🔧') || 
             String(msg.content).includes('⏳') || 
             String(msg.content).includes('✅') || 
             String(msg.content).includes('❌')))

          const timestampStr = formatTimestamp(msg.createdAt)
          const isExpanded = getExpandedState(msg, isToolRelated, isLastMessage)

          return (
            <div key={msg.id} className={getMessageContainerClass(isUser, isSystem, isToolProgress, isSystemToolMessage)}>
              {/* Avatar */}
              {!isSystem || isToolProgress || isSystemToolMessage ? (
                <Avatar className="w-8 h-8 shrink-0">
                  <AvatarFallback className="text-xs">
                    {(isToolProgress || isSystemToolMessage) ? <Wrench className="w-4 h-4" /> : getRoleIcon(msg.role)}
                  </AvatarFallback>
                </Avatar>
              ) : null}

              {/* Message bubble */}
              <div className={msg.role === 'tool' || isSystemToolMessage ? "flex flex-col w-full" : "flex flex-col max-w-[75%]"}>
                <div className={getBubbleClass(msg.role, isUser, isAi, isSystem, isToolProgress, isSystemToolMessage)}>
                  {/* Tool header */}
                  {(isToolRelated || (msg.role === 'system' && msg.content !== null && msg.content !== undefined && (
                    String(msg.content).includes('🔧 Using tool:') || 
                    String(msg.content).includes('📋 Tool Result:')
                  ))) && (
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center gap-2">
                        <Wrench className="h-4 w-4" />
                        <span className="font-medium text-sm">
                          {msg.toolName || 
                           (msg.content !== null && msg.content !== undefined && String(msg.content).includes('🔧 Using tool:') 
                             ? String(msg.content).replace('🔧 Using tool: ', '').split('\n')[0]
                             : 'Tool Execution')}
                        </span>
                        {getToolStatusIcon(msg, messages)}
                      </div>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => toggleToolPanelExpansion(msg.id)}
                        className="h-6 w-6 p-0"
                      >
                        {isToolPanelExpanded(msg.id) ? <ChevronUp className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
                      </Button>
                    </div>
                  )}

                  {/* Tool content - show content for tool messages, expandable for others */}
                  {(msg.role === 'tool' || (isToolRelated && isToolPanelExpanded(msg.id)) || (!isToolRelated)) && (
                    <>
                      {/* Main content */}
                      {renderContent(msg, isToolProgress)}

                      {/* Image attachment */}
                      {msg.imageData && (
                        <div className="mt-2">
                          <img
                            src={`data:${msg.imageData.mimeType};base64,${msg.imageData.base64}`}
                            alt="Message attachment"
                            className="max-h-48 w-auto rounded border border-border"
                          />
                        </div>
                      )}


                      {/* Tool details (expanded) */}
                      {isToolRelated && isExpanded && isToolPanelExpanded(msg.id) && (
                        <div className="mt-3 space-y-2 border-t pt-2">
                          {/* Tool arguments */}
                          {msg.toolArgs && (
                            <div>
                              <div className="text-xs font-medium mb-1">Arguments:</div>
                              <pre className="whitespace-pre-wrap overflow-auto bg-muted/50 p-2 rounded text-xs">
                                {JSON.stringify(msg.toolArgs, null, 2)}
                              </pre>
                            </div>
                          )}

                          {/* Tool result */}
                          {msg.toolResult && (
                            <div>
                              <div className="text-xs font-medium mb-1">Result:</div>
                              {renderToolResult(msg.toolResult)}
                            </div>
                          )}

                        </div>
                      )}
                    </>
                  )}

                  {/* Collapsed state indicator */}
                  {!isToolPanelExpanded(msg.id) && (isToolRelated || isSystemToolMessage) && msg.role !== 'tool' && (
                    <div className="text-xs text-muted-foreground italic mt-2">
                      Tool details collapsed. Click to expand.
                    </div>
                  )}
                </div>

                {/* Message metadata */}
                {!isSystem && renderMessageMetadata(msg, isAi, timestampStr)}
              </div>
            </div>
          )
        })}

        {/* Thinking indicator */}
        {hasThinkingMessage && (
          <ThinkingIndicator className="mb-4" />
        )}

        {/* Auto-scroll anchor */}
        <div ref={endRef} />
      </div>
    </ScrollArea>
  )
}

"use client"

import * as React from "react"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { KeyValueEditor, KeyValuePair } from "@/components/ui/key-value-editor"
import { generateId } from "@/lib/utils"
import { ServerRegistryEntry, ServerCategory, ServerType, ServerPlatform } from "@/types/server-registry"

interface AddCustomServerModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onSubmit: (server: ServerRegistryEntry) => Promise<void>
}

const createEmptyKeyValuePair = (): KeyValuePair => ({
  key: '',
  value: '',
  id: generateId()
})

export function AddCustomServerModal({ open, onOpenChange, onSubmit }: AddCustomServerModalProps) {
  const [isSubmitting, setIsSubmitting] = React.useState(false)
  const [formData, setFormData] = React.useState<Partial<ServerRegistryEntry>>({
    name: '',
    description: '',
    category: 'custom',
    icon: '',
    version: '1.0.0',
    author: '',
    homepage: '',
    config: {
      type: 'stdio',
      command: '',
      args: [],
      url: '',
      env: {},
      headers: {},
      timeout: 30000,
    },
    tags: [],
    isInstalled: false,
    requirements: {
      platform: 'all',
      node: '',
      python: '',
      dependencies: [],
    },
  })

  // Input states for parsed fields
  const [argsInput, setArgsInput] = React.useState('')
  const [tagsInput, setTagsInput] = React.useState('')
  const [envInput, setEnvInput] = React.useState('')
  const [dependenciesInput, setDependenciesInput] = React.useState('')
  const [headers, setHeaders] = React.useState<KeyValuePair[]>([createEmptyKeyValuePair()])

  const [errors, setErrors] = React.useState<Record<string, string>>({})

  const resetForm = () => {
    setFormData({
      name: '',
      description: '',
      category: 'custom',
      icon: '',
      version: '1.0.0',
      author: '',
      homepage: '',
      config: {
        type: 'stdio',
        command: '',
        args: [],
        url: '',
        env: {},
        headers: {},
        timeout: 30000,
      },
      tags: [],
      isInstalled: false,
      requirements: {
        platform: 'all',
        node: '',
        python: '',
        dependencies: [],
      },
    })
    setArgsInput('')
    setTagsInput('')
    setEnvInput('')
    setDependenciesInput('')
    setHeaders([createEmptyKeyValuePair()])
    setErrors({})
  }

  const updateFormData = (field: keyof ServerRegistryEntry, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }))
  }

  const updateConfigData = (field: keyof ServerRegistryEntry['config'], value: any) => {
    setFormData(prev => ({
      ...prev,
      config: { ...prev.config!, [field]: value }
    }))
  }

  const updateRequirementsData = (field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      requirements: { ...prev.requirements!, [field]: value }
    }))
  }

  const parseCommaSeparated = (input: string): string[] => {
    return input.split(',').map(s => s.trim()).filter(Boolean)
  }

  const parseEnvironmentVariables = (input: string): Record<string, string> => {
    const env: Record<string, string> = {}
    const envLines = input.split('\n')

    for (const line of envLines) {
      const trimmedLine = line.trim()
      if (!trimmedLine) continue

      const equalIndex = trimmedLine.indexOf('=')
      if (equalIndex > 0) {
        const key = trimmedLine.substring(0, equalIndex).trim()
        const value = trimmedLine.substring(equalIndex + 1).trim()
        if (key) env[key] = value
      }
    }

    return env
  }

  const parseHeaders = (pairs: KeyValuePair[]): Record<string, string> => {
    const result: Record<string, string> = {}
    pairs.forEach(pair => {
      if (pair.key.trim() && pair.value.trim()) {
        result[pair.key.trim()] = pair.value.trim()
      }
    })
    return result
  }

  const validateForm = (): boolean => {
    const newErrors: Record<string, string> = {}

    if (!formData.name?.trim()) {
      newErrors.name = 'Name is required'
    }

    if (!formData.description?.trim()) {
      newErrors.description = 'Description is required'
    }

    if (formData.config?.type === 'stdio') {
      if (!formData.config.command?.trim()) {
        newErrors.command = 'Command is required for stdio servers'
      }
    } else if (formData.config?.type === 'sse' || formData.config?.type === 'streamable-http') {
      if (!formData.config.url?.trim()) {
        newErrors.url = 'URL is required for SSE/HTTP servers'
      }
    }

    setErrors(newErrors)
    return Object.keys(newErrors).length === 0
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) return

    setIsSubmitting(true)
    try {
      const serverEntry: ServerRegistryEntry = {
        ...formData,
        id: formData.id || `custom-${Date.now()}`,
        name: formData.name!,
        description: formData.description!,
        category: formData.category!,
        icon: formData.icon || '🔧',
        version: formData.version || '1.0.0',
        author: formData.author || '',
        homepage: formData.homepage || '',
        config: {
          ...formData.config!,
          args: parseCommaSeparated(argsInput),
          env: parseEnvironmentVariables(envInput),
          headers: parseHeaders(headers),
        },
        tags: parseCommaSeparated(tagsInput),
        isInstalled: false,
        isOfficial: false,
        lastUpdated: new Date(),
        requirements: {
          ...formData.requirements!,
          dependencies: parseCommaSeparated(dependenciesInput),
        },
      }

      await onSubmit(serverEntry)
      resetForm()
      onOpenChange(false)
    } catch (error) {
      console.error('Failed to add server:', error)
    } finally {
      setIsSubmitting(false)
    }
  }

  const isStdioType = formData.config?.type === 'stdio'
  const isUrlType = formData.config?.type === 'sse' || formData.config?.type === 'streamable-http'

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Add Custom MCP Server</DialogTitle>
          <DialogDescription>
            Configure a new MCP server with its connection details and metadata.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-6">
          {/* Basic Information */}
          <div className="space-y-4">
            <h3 className="text-lg font-medium">Basic Information</h3>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Name *</label>
                <Input
                  value={formData.name || ''}
                  onChange={(e) => updateFormData('name', e.target.value)}
                  placeholder="My Custom Server"
                  className={errors.name ? 'border-red-500' : ''}
                />
                {errors.name && <p className="text-sm text-red-500 mt-1">{errors.name}</p>}
              </div>

              <div>
                <label className="text-sm font-medium">Version</label>
                <Input
                  value={formData.version || ''}
                  onChange={(e) => updateFormData('version', e.target.value)}
                  placeholder="1.0.0"
                />
              </div>
            </div>

            <div>
              <label className="text-sm font-medium">Description *</label>
              <Textarea
                value={formData.description || ''}
                onChange={(e) => updateFormData('description', e.target.value)}
                placeholder="Brief description of what this server does"
                className={errors.description ? 'border-red-500' : ''}
              />
              {errors.description && <p className="text-sm text-red-500 mt-1">{errors.description}</p>}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Category</label>
                <Select value={formData.category} onValueChange={(value: ServerCategory) => updateFormData('category', value)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="productivity">Productivity</SelectItem>
                    <SelectItem value="development">Development</SelectItem>
                    <SelectItem value="research">Research</SelectItem>
                    <SelectItem value="data">Data</SelectItem>
                    <SelectItem value="communication">Communication</SelectItem>
                    <SelectItem value="custom">Custom</SelectItem>
                  </SelectContent>  
                </Select>
              </div>

              <div>
                <label className="text-sm font-medium">Icon</label>
                <Input
                  value={formData.icon || ''}
                  onChange={(e) => updateFormData('icon', e.target.value)}
                  placeholder="🔧"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Author</label>
                <Input
                  value={formData.author || ''}
                  onChange={(e) => updateFormData('author', e.target.value)}
                  placeholder="Your Name"
                />
              </div>

              <div>
                <label className="text-sm font-medium">Homepage</label>
                <Input
                  value={formData.homepage || ''}
                  onChange={(e) => updateFormData('homepage', e.target.value)}
                  placeholder="https://github.com/user/repo"
                />
              </div>
            </div>
          </div>

          {/* Server Configuration */}
          <div className="space-y-4">
            <h3 className="text-lg font-medium">Server Configuration</h3>

            <div>
              <label className="text-sm font-medium">Server Type</label>
              <Select value={formData.config?.type} onValueChange={(value: ServerType) => updateConfigData('type', value)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="stdio">Standard I/O (Local Process)</SelectItem>
                  <SelectItem value="sse">Server-Sent Events</SelectItem>
                  <SelectItem value="streamable-http">Streamable HTTP</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {isStdioType && (
              <>
                <div>
                  <label className="text-sm font-medium">Command *</label>
                  <Input
                    value={formData.config?.command || ''}
                    onChange={(e) => updateConfigData('command', e.target.value)}
                    placeholder="node"
                    className={errors.command ? 'border-red-500' : ''}
                  />
                  {errors.command && <p className="text-sm text-red-500 mt-1">{errors.command}</p>}
                </div>

                <div>
                  <label className="text-sm font-medium">Arguments</label>
                  <Input
                    value={argsInput}
                    onChange={(e) => setArgsInput(e.target.value)}
                    placeholder="server.js, --port=3000"
                  />
                  <p className="text-xs text-muted-foreground mt-1">Comma-separated arguments</p>
                </div>

                <div>
                  <label className="text-sm font-medium">Environment Variables</label>
                  <Textarea
                    value={envInput}
                    onChange={(e) => setEnvInput(e.target.value)}
                    placeholder="API_KEY=your_key&#10;DEBUG=true"
                    rows={3}
                  />
                  <p className="text-xs text-muted-foreground mt-1">KEY=value format, one per line</p>
                </div>
              </>
            )}

            {isUrlType && (
              <>
                <div>
                  <label className="text-sm font-medium">URL *</label>
                  <Input
                    value={formData.config?.url || ''}
                    onChange={(e) => updateConfigData('url', e.target.value)}
                    placeholder="https://api.example.com/mcp"
                    className={errors.url ? 'border-red-500' : ''}
                  />
                  {errors.url && <p className="text-sm text-red-500 mt-1">{errors.url}</p>}
                </div>

                <div>
                  <label className="text-sm font-medium">Headers</label>
                  <KeyValueEditor
                    pairs={headers}
                    onChange={setHeaders}
                    placeholder={{ key: "Authorization", value: "Bearer token" }}
                  />
                </div>
              </>
            )}

            <div>
              <label className="text-sm font-medium">Timeout (ms)</label>
              <Input
                type="number"
                value={formData.config?.timeout || 30000}
                onChange={(e) => updateConfigData('timeout', parseInt(e.target.value) || 30000)}
                placeholder="30000"
              />
            </div>
          </div>

          {/* Requirements */}
          <div className="space-y-4">
            <h3 className="text-lg font-medium">Requirements</h3>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Platform</label>
                <Select value={formData.requirements?.platform} onValueChange={(value: ServerPlatform) => updateRequirementsData('platform', value)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Platforms</SelectItem>
                    <SelectItem value="darwin">macOS</SelectItem>
                    <SelectItem value="linux">Linux</SelectItem>
                    <SelectItem value="win32">Windows</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <label className="text-sm font-medium">Node Version</label>
                <Input
                  value={formData.requirements?.node || ''}
                  onChange={(e) => updateRequirementsData('node', e.target.value)}
                  placeholder=">=18.0.0"
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-sm font-medium">Python Version</label>
                <Input
                  value={formData.requirements?.python || ''}
                  onChange={(e) => updateRequirementsData('python', e.target.value)}
                  placeholder=">=3.8"
                />
              </div>

              <div>
                <label className="text-sm font-medium">Dependencies</label>
                <Input
                  value={dependenciesInput}
                  onChange={(e) => setDependenciesInput(e.target.value)}
                  placeholder="numpy, pandas"
                />
                <p className="text-xs text-muted-foreground mt-1">Comma-separated packages</p>
              </div>
            </div>
          </div>

          {/* Tags */}
          <div>
            <label className="text-sm font-medium">Tags</label>
            <Input
              value={tagsInput}
              onChange={(e) => setTagsInput(e.target.value)}
              placeholder="api, database, utility"
            />
            <p className="text-xs text-muted-foreground mt-1">Comma-separated tags</p>
          </div>

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button type="submit" disabled={isSubmitting}>
              {isSubmitting ? 'Adding...' : 'Add Server'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { KeyValueEditor, KeyValuePair } from "@/components/ui/key-value-editor"
import { Alert, AlertDescription } from "@/components/ui/alert"
import { generateId } from "@/lib/utils"
import { McpServerConfig, HeaderPair } from "@/types/server-registry"

interface ConnectServerModalProps {
  isOpen: boolean
  onClose: () => void
  onSuccess?: () => void
}

const createEmptyHeaderPair = (): HeaderPair => ({
  key: '',
  value: '',
  id: generateId()
})

export function ConnectServerModal({ isOpen, onClose, onSuccess }: ConnectServerModalProps) {
  const [serverName, setServerName] = React.useState('')
  const [serverType, setServerType] = React.useState<'stdio' | 'sse' | 'http'>('stdio')
  const [command, setCommand] = React.useState('')
  const [args, setArgs] = React.useState('')
  const [url, setUrl] = React.useState('')
  const [headerPairs, setHeaderPairs] = React.useState<HeaderPair[]>([createEmptyHeaderPair()])
  const [error, setError] = React.useState<string | null>(null)
  const [isSubmitting, setIsSubmitting] = React.useState(false)

  // Reset form with delay when modal closes
  React.useEffect(() => {
    if (!isOpen) {
      const timer = setTimeout(() => {
        setServerName('')
        setServerType('stdio')
        setCommand('')
        setArgs('')
        setUrl('')
        setHeaderPairs([createEmptyHeaderPair()])
        setError(null)
        setIsSubmitting(false)
      }, 300) // Delay to allow modal close animation

      return () => clearTimeout(timer)
    }
  }, [isOpen])

  const headersToRecord = (pairs: HeaderPair[]): Record<string, string> => {
    const headers: Record<string, string> = {}
    pairs.forEach((pair) => {
      if (pair.key.trim() && pair.value.trim()) {
        headers[pair.key.trim()] = pair.value.trim()
      }
    })
    return headers
  }

  const generateConfig = (): McpServerConfig => {
    if (serverType === 'stdio') {
      return {
        type: 'stdio',
        command: command.trim(),
        args: args.split(',').map(s => s.trim()).filter(Boolean),
        env: {},
        timeout: 30000,
        connectionMode: 'lenient',
      }
    } else if (serverType === 'sse') {
      return {
        type: 'sse',
        url: url.trim(),
        headers: headerPairs.length ? headersToRecord(headerPairs) : {},
        timeout: 30000,
        connectionMode: 'lenient',
      }
    } else { // http
      return {
        type: 'http',
        url: url.trim(),
        headers: headerPairs.length ? headersToRecord(headerPairs) : {},
        timeout: 30000,
        connectionMode: 'lenient',
      }
    }
  }

  const validateForm = (): string | null => {
    if (!serverName.trim()) {
      return 'Server name is required.'
    }

    if (serverType === 'stdio') {
      if (!command.trim()) {
        return 'Command is required for stdio servers.'
      }
    } else { // sse or http
      if (!url.trim()) {
        return `URL is required for ${serverType.toUpperCase()} servers.`
      }
      try {
        new URL(url.trim())
      } catch (_) {
        return `Invalid URL format for ${serverType.toUpperCase()} server.`
      }
    }

    return null
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setError(null)
    setIsSubmitting(true)

    const validationError = validateForm()
    if (validationError) {
      setError(validationError)
      setIsSubmitting(false)
      return
    }

    const config = generateConfig()

    try {
      const response = await fetch('/api/connect-server', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: serverName.trim(),
          config
        }),
      })

      const result = await response.json()

      if (!response.ok) {
        setError(result.error || `Server returned status ${response.status}`)
        setIsSubmitting(false)
        return
      }

      // Success - close modal and call success callback
      onClose()
      onSuccess?.()
    } catch (err: any) {
      setError(err.message || 'Failed to connect server')
    } finally {
      setIsSubmitting(false)
    }
  }

  const convertHeaderPairsToKeyValuePairs = (pairs: HeaderPair[]): KeyValuePair[] => {
    return pairs.map(pair => ({
      key: pair.key,
      value: pair.value,
      id: pair.id
    }))
  }

  const convertKeyValuePairsToHeaderPairs = (pairs: KeyValuePair[]): HeaderPair[] => {
    return pairs.map(pair => ({
      key: pair.key,
      value: pair.value,
      id: pair.id
    }))
  }

  const isStdioType = serverType === 'stdio'
  const isUrlType = serverType === 'sse' || serverType === 'http'

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle>Connect MCP Server</DialogTitle>
          <DialogDescription>
            Connect to an existing MCP server by providing its configuration details.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          {error && (
            <Alert variant="destructive">
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}

          <div>
            <label className="text-sm font-medium mb-2 block">Server Name *</label>
            <Input
              value={serverName}
              onChange={(e) => setServerName(e.target.value)}
              placeholder="my-mcp-server"
              disabled={isSubmitting}
            />
          </div>

          <div>
            <label className="text-sm font-medium mb-2 block">Server Type *</label>
            <Select
              value={serverType}
              onValueChange={(value: 'stdio' | 'sse' | 'http') => setServerType(value)}
              disabled={isSubmitting}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="stdio">Standard I/O (Local Process)</SelectItem>
                <SelectItem value="sse">Server-Sent Events</SelectItem>
                <SelectItem value="http">HTTP</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {isStdioType && (
            <>
              <div>
                <label className="text-sm font-medium mb-2 block">Command *</label>
                <Input
                  value={command}
                  onChange={(e) => setCommand(e.target.value)}
                  placeholder="node"
                  disabled={isSubmitting}
                />
                <p className="text-xs text-muted-foreground mt-1">
                  The command to execute the MCP server
                </p>
              </div>

              <div>
                <label className="text-sm font-medium mb-2 block">Arguments</label>
                <Input
                  value={args}
                  onChange={(e) => setArgs(e.target.value)}
                  placeholder="server.js, --port=3000"
                  disabled={isSubmitting}
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Comma-separated command arguments
                </p>
              </div>
            </>
          )}

          {isUrlType && (
            <>
              <div>
                <label className="text-sm font-medium mb-2 block">URL *</label>
                <Input
                  value={url}
                  onChange={(e) => setUrl(e.target.value)}
                  placeholder="https://api.example.com/mcp"
                  disabled={isSubmitting}
                />
                <p className="text-xs text-muted-foreground mt-1">
                  Complete URL to the MCP server endpoint
                </p>
              </div>

              <div>
                <label className="text-sm font-medium mb-2 block">Headers</label>
                <KeyValueEditor
                  pairs={convertHeaderPairsToKeyValuePairs(headerPairs)}
                  onChange={(pairs) => setHeaderPairs(convertKeyValuePairsToHeaderPairs(pairs))}
                  placeholder={{ key: "Authorization", value: "Bearer token" }}
                />
                <p className="text-xs text-muted-foreground mt-1">
                  HTTP headers to include with requests
                </p>
              </div>
            </>
          )}

          <DialogFooter>
            <Button
              type="button"
              variant="outline"
              onClick={onClose}
              disabled={isSubmitting}
            >
              Cancel
            </Button>
            <Button
              type="submit"
              disabled={isSubmitting}
            >
              {isSubmitting ? 'Connecting...' : 'Connect Server'}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { ScrollArea } from "@/components/ui/scroll-area"
import { 
  User, 
  Bot, 
  Settings, 
  MessageSquare, 
  Search,
  Loader2,
  AlertCircle,
  Keyboard
} from "lucide-react"
import { cn } from "@/lib/utils"
import { SearchResult, SearchResponse } from "@/types/search"

interface GlobalSearchModalProps {
  isOpen: boolean
  onClose: () => void
  onNavigateToSession: (sessionId: string, messageIndex: number) => void
}

export function GlobalSearchModal({ isOpen, onClose, onNavigateToSession }: GlobalSearchModalProps) {
  const [searchQuery, setSearchQuery] = React.useState('')
  const [results, setResults] = React.useState<SearchResult[]>([])
  const [isLoading, setIsLoading] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const [selectedIndex, setSelectedIndex] = React.useState(0)

  const inputRef = React.useRef<HTMLInputElement>(null)

  // Debounced search function
  const performSearch = React.useCallback(async (query: string) => {
    if (!query.trim()) {
      setResults([])
      setError(null)
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      const params = new URLSearchParams({
        q: query,
        limit: '10',
        offset: '0'
      })

      const response = await fetch(`/api/search/messages?${params}`)
      if (!response.ok) {
        const errorText = await response.text()
        throw new Error(`Search failed: ${response.status} ${errorText}`)
      }

      const data: SearchResponse = await response.json()
      setResults(data.results)
      setSelectedIndex(0)
    } catch (err) {
      console.error('Search error:', err)
      setResults([])
      setError(err instanceof Error ? err.message : 'Search failed')
    } finally {
      setIsLoading(false)
    }
  }, [])

  // Debounced search with 300ms delay
  React.useEffect(() => {
    const timeoutId = setTimeout(() => {
      performSearch(searchQuery)
    }, 300)

    return () => clearTimeout(timeoutId)
  }, [searchQuery, performSearch])

  // Modal state reset
  React.useEffect(() => {
    if (isOpen) {
      setSearchQuery('')
      setResults([])
      setError(null)
      setSelectedIndex(0)
      // Auto-focus on input when modal opens
      setTimeout(() => {
        inputRef.current?.focus()
      }, 0)
    }
  }, [isOpen])

  // Text highlighting logic
  const highlightText = React.useCallback((text: string, query: string) => {
    if (!query) return text

    const escapedQuery = query.replace(/[.*+?^${}()|\[\]\\]/g, '\\$&')
    const regex = new RegExp(`(${escapedQuery})`, 'gi')
    const parts = text.split(regex)

    return parts.map((part, index) =>
      regex.test(part) ? (
        <mark key={index} className="bg-yellow-200 dark:bg-yellow-800 font-medium rounded px-1">
          {part}
        </mark>
      ) : part
    )
  }, [])

  // Role-based icons and colors
  const getRoleIcon = (role: string) => {
    switch (role) {
      case 'user':
        return <User className="w-4 h-4" />
      case 'assistant':
        return <Bot className="w-4 h-4" />
      case 'system':
        return <Settings className="w-4 h-4" />
      default:
        return <MessageSquare className="w-4 h-4" />
    }
  }

  const getRoleColor = (role: string) => {
    switch (role) {
      case 'user':
        return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200'
      case 'assistant':
        return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
      case 'system':
        return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200'
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-200'
    }
  }

  // Result click handler
  const handleResultClick = (result: SearchResult) => {
    onNavigateToSession(result.sessionId, result.messageIndex)
    onClose()
  }

  // Keyboard navigation handler
  React.useEffect(() => {
    if (!isOpen) return

    const handleKeyDown = (e: KeyboardEvent) => {
      if (!isOpen) return

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault()
          e.stopPropagation()
          setSelectedIndex(prev => Math.min(prev + 1, results.length - 1))
          break
        case 'ArrowUp':
          e.preventDefault()
          e.stopPropagation()
          setSelectedIndex(prev => Math.max(prev - 1, 0))
          break
        case 'Enter':
          e.preventDefault()
          e.stopPropagation()
          if (results[selectedIndex]) {
            handleResultClick(results[selectedIndex])
          }
          break
        case 'Escape':
          e.preventDefault()
          e.stopPropagation()
          onClose()
          break
      }
    }

    document.addEventListener('keydown', handleKeyDown)
    return () => document.removeEventListener('keydown', handleKeyDown)
  }, [isOpen, results, selectedIndex, onClose])

  const truncateSessionId = (sessionId: string) => {
    return sessionId.length > 8 ? `${sessionId.substring(0, 8)}...` : sessionId
  }

  const showEmptyState = !searchQuery.trim() && !isLoading
  const showNoResults = searchQuery.trim() && results.length === 0 && !isLoading && !error

  return (
    <Dialog open={isOpen} onOpenChange={(open) => {
      !open && onClose();
    }}>
      <DialogContent className="max-w-2xl max-h-[80vh] p-0">
        <DialogHeader className="px-6 pt-6 pb-4">
          <DialogTitle className="flex items-center gap-2">
            <Search className="w-5 h-5" />
            Global Search
          </DialogTitle>
        </DialogHeader>

        <div className="px-6">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input
              ref={inputRef}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search messages..."
              className="pl-10"
            />
          </div>
        </div>

        <ScrollArea className="flex-1 max-h-96">
          <div className="px-6 pb-6">
            {showEmptyState && (
              <div className="text-center py-8 text-muted-foreground">
                <Search className="w-12 h-12 mx-auto mb-4 opacity-50" />
                <p className="text-lg font-medium mb-2">Search your conversations</p>
                <p className="text-sm mb-4">Find messages, responses, and context across all sessions</p>
                <div className="flex items-center justify-center gap-4 text-xs">
                  <div className="flex items-center gap-1">
                    <Keyboard className="w-3 h-3" />
                    <span>↑↓ Navigate</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Keyboard className="w-3 h-3" />
                    <span>Enter Select</span>
                  </div>
                  <div className="flex items-center gap-1">
                    <Keyboard className="w-3 h-3" />
                    <span>Esc Close</span>
                  </div>
                </div>
              </div>
            )}

            {isLoading && (
              <div className="flex items-center justify-center py-8">
                <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
                <span className="ml-2 text-muted-foreground">Searching...</span>
              </div>
            )}

            {error && (
              <div className="flex items-center justify-center py-8 text-red-500">
                <AlertCircle className="w-6 h-6 mr-2" />
                <span>{error}</span>
              </div>
            )}

            {showNoResults && (
              <div className="text-center py-8 text-muted-foreground">
                <Search className="w-12 h-12 mx-auto mb-4 opacity-50" />
                <p className="text-lg font-medium mb-2">No results found</p>
                <p className="text-sm">Try different keywords or check your spelling</p>
              </div>
            )}

            {results.length > 0 && (
              <div className="space-y-2 py-4">
                {results.map((result, index) => (
                  <div
                    key={`${result.sessionId}-${result.messageIndex}`}
                    className={cn(
                      "p-4 rounded-lg border cursor-pointer transition-colors",
                      index === selectedIndex
                        ? "bg-accent border-accent-foreground/20"
                        : "bg-card hover:bg-accent/50"
                    )}
                    onClick={() => handleResultClick(result)}
                  >
                    <div className="flex items-start gap-3">
                      <div className={cn(
                        "flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium",
                        getRoleColor(result.message.role)
                      )}>
                        {getRoleIcon(result.message.role)}
                        <span className="capitalize">{result.message.role}</span>
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 mb-2">
                          <span className="text-xs text-muted-foreground font-mono">
                            Session: {truncateSessionId(result.sessionId)}
                          </span>
                          <span className="text-xs text-muted-foreground">
                            Message #{result.messageIndex + 1}
                          </span>
                        </div>
                        <div className="text-sm">
                          <div className="font-medium mb-1">
                            {highlightText(result.matchedText, searchQuery)}
                          </div>
                          {result.context && (
                            <div className="text-muted-foreground text-xs line-clamp-2">
                              {highlightText(result.context, searchQuery)}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </ScrollArea>
      </DialogContent>
    </Dialog>
  )
}

export { AddCustomServerModal } from './add-custom-server-modal';
export { ConnectServerModal } from './connect-server-modal';
export { GlobalSearchModal } from './global-search-modal';

