"use client"

import React from 'react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { ReactQueryDevtools } from '@tanstack/react-query-devtools'

// Create a client optimized for immediate UI updates
function makeQueryClient() {
  return new QueryClient({
    defaultOptions: {
      queries: {
        // Balance between performance and freshness for session data
        staleTime: 30 * 1000, // 30 seconds - fresh enough for real-time feel
        gcTime: 5 * 60 * 1000, // 5 minutes garbage collection
        refetchOnWindowFocus: false, // Prevent unnecessary refetches
        refetchOnMount: true, // Always fetch on mount for consistency
        retry: (failureCount, error: any) => {
          // Don't retry on 4xx errors except 408 (timeout) and 429 (rate limit)
          if (error?.status >= 400 && error?.status < 500 && 
              error?.status !== 408 && error?.status !== 429) {
            return false
          }
          // Retry up to 3 times for other errors
          return failureCount < 3
        },
        retryDelay: (attemptIndex) => Math.min(1000 * 2 ** attemptIndex, 30000),
      },
      mutations: {
        // Optimistic UI updates with proper error handling
        retry: (failureCount, error: any) => {
          // Don't retry mutations on client errors
          if (error?.status >= 400 && error?.status < 500) {
            return false
          }
          // Retry mutations once for server errors
          return failureCount < 1
        },
        // Enable network mode for offline resilience
        networkMode: 'offlineFirst',
      },
    },
  })
}

let browserQueryClient: QueryClient | undefined = undefined

function getQueryClient() {
  if (typeof window === 'undefined') {
    // Server: always make a new query client
    return makeQueryClient()
  } else {
    // Browser: make a new query client if we don't already have one
    if (!browserQueryClient) browserQueryClient = makeQueryClient()
    return browserQueryClient
  }
}

interface QueryProviderProps {
  children: React.ReactNode
}

export function QueryProvider({ children }: QueryProviderProps) {
  const queryClient = getQueryClient()

  return (
    <QueryClientProvider client={queryClient}>
      {children}
      {process.env.NODE_ENV === 'development' && (
        <ReactQueryDevtools 
          initialIsOpen={false} 
          buttonPosition="bottom-left"
        />
      )}
    </QueryClientProvider>
  )
}

"use client"

import * as React from "react"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Badge } from "@/components/ui/badge"
import { ScrollArea } from "@/components/ui/scroll-area"
import { 
  Search,
  MessageSquare,
  Clock,
  User,
  Bot,
  Settings,
  ChevronRight,
  Loader2,
  AlertCircle
} from "lucide-react"
import { cn } from "@/lib/utils"
import { 
  SearchResult, 
  SearchResponse, 
  SessionSearchResult, 
  SessionSearchResponse, 
  SearchMode 
} from "@/types/search"

interface SearchPanelProps {
  isOpen?: boolean
  onClose?: () => void
  onNavigateToSession: (sessionId: string, messageIndex: number) => void
  variant?: 'modal' | 'inline'
  className?: string
}

export function SearchPanel({ 
  isOpen = true, 
  onClose, 
  onNavigateToSession,
  variant = 'modal',
  className 
}: SearchPanelProps) {
  // State management
  const [searchQuery, setSearchQuery] = React.useState('')
  const [searchMode, setSearchMode] = React.useState<SearchMode>('messages')
  const [messageResults, setMessageResults] = React.useState<SearchResult[]>([])
  const [sessionResults, setSessionResults] = React.useState<SessionSearchResult[]>([])
  const [isLoading, setIsLoading] = React.useState(false)
  const [error, setError] = React.useState<string | null>(null)
  const [roleFilter, setRoleFilter] = React.useState<string>('all')
  const [sessionFilter, setSessionFilter] = React.useState<string>('')
  const [hasMore, setHasMore] = React.useState(false)
  const [total, setTotal] = React.useState(0)

  // Text highlighting logic
  const highlightText = React.useCallback((text: string, query: string) => {
    if (!query) return text

    const escapedQuery = query.replace(/[.*+?^${}()|\[\]\\]/g, '\\$&')
    const regex = new RegExp(`(${escapedQuery})`, 'gi')
    const parts = text.split(regex)

    return parts.map((part, index) =>
      regex.test(part) ? (
        <mark key={index} className="bg-yellow-200 dark:bg-yellow-800 font-medium rounded px-1">
          {part}
        </mark>
      ) : part
    )
  }, [])

  // Role-based UI helpers
  const getRoleIcon = (role: string) => {
    switch (role) {
      case 'user':
        return <User className="w-4 h-4" />
      case 'assistant':
        return <Bot className="w-4 h-4" />
      case 'system':
        return <Settings className="w-4 h-4" />
      default:
        return <MessageSquare className="w-4 h-4" />
    }
  }

  const getRoleColor = (role: string) => {
    switch (role) {
      case 'user':
        return 'bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200'
      case 'assistant':
        return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200'
      case 'system':
        return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200'
      default:
        return 'bg-gray-100 text-gray-800 dark:bg-gray-800 dark:text-gray-200'
    }
  }

  // Date/time formatting
  const formatDate = (timestamp: number) => {
    return new Date(timestamp).toLocaleDateString()
  }

  const formatTime = (timestamp: number) => {
    return new Date(timestamp).toLocaleTimeString([], {
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  // Message search implementation
  const performMessageSearch = React.useCallback(async (query: string) => {
    const params = new URLSearchParams({
      q: query,
      limit: '20',
      offset: '0'
    })

    if (roleFilter !== 'all') {
      params.append('role', roleFilter)
    }

    if (sessionFilter) {
      params.append('sessionId', sessionFilter)
    }

    const response = await fetch(`/api/search/messages?${params}`)
    if (!response.ok) {
      throw new Error('Message search failed')
    }

    const data: SearchResponse = await response.json()
    setMessageResults(data.results)
    setTotal(data.total)
    setHasMore(data.hasMore)
  }, [roleFilter, sessionFilter])

  // Session search implementation
  const performSessionSearch = React.useCallback(async (query: string) => {
    const params = new URLSearchParams({ q: query })
    const response = await fetch(`/api/search/sessions?${params}`)
    if (!response.ok) {
      throw new Error('Session search failed')
    }

    const data: SessionSearchResponse = await response.json()
    setSessionResults(data.results)
    setTotal(data.total)
    setHasMore(data.hasMore)
  }, [])

  // Debounced search logic
  const performSearch = React.useCallback(async (query: string, mode: SearchMode) => {
    if (!query.trim()) {
      setMessageResults([])
      setSessionResults([])
      setTotal(0)
      setHasMore(false)
      setError(null)
      return
    }

    setIsLoading(true)
    setError(null)

    try {
      if (mode === 'messages') {
        await performMessageSearch(query)
      } else {
        await performSessionSearch(query)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Search failed')
      setMessageResults([])
      setSessionResults([])
      setTotal(0)
      setHasMore(false)
    } finally {
      setIsLoading(false)
    }
  }, [performMessageSearch, performSessionSearch])

  // Debounced search with 300ms delay
  React.useEffect(() => {
    const timeoutId = setTimeout(() => {
      performSearch(searchQuery, searchMode)
    }, 300)

    return () => clearTimeout(timeoutId)
  }, [searchQuery, searchMode, performSearch])

  // Result click handlers
  const handleResultClick = (result: SearchResult) => {
    onNavigateToSession(result.sessionId, result.messageIndex)
    onClose?.()
  }

  const handleSessionResultClick = (sessionResult: SessionSearchResult) => {
    onNavigateToSession(sessionResult.sessionId, sessionResult.firstMatch.messageIndex)
    onClose?.()
  }

  // Search mode toggle
  const SearchModeToggle = () => (
    <div className="flex gap-2">
      <Button
        variant={searchMode === 'messages' ? 'default' : 'outline'}
        size="sm"
        onClick={() => setSearchMode('messages')}
        className="flex-1"
      >
        <MessageSquare className="w-4 h-4 mr-2" />
        Messages
      </Button>
      <Button
        variant={searchMode === 'sessions' ? 'default' : 'outline'}
        size="sm"
        onClick={() => setSearchMode('sessions')}
        className="flex-1"
      >
        <Clock className="w-4 h-4 mr-2" />
        Sessions
      </Button>
    </div>
  )

  // Filter controls
  const FilterControls = () => (
    searchMode === 'messages' && (
      <div className="flex gap-2">
        <Select value={roleFilter} onValueChange={setRoleFilter}>
          <SelectTrigger className="w-28">
            <SelectValue placeholder="Role" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All</SelectItem>
            <SelectItem value="user">User</SelectItem>
            <SelectItem value="assistant">Assistant</SelectItem>
            <SelectItem value="system">System</SelectItem>
          </SelectContent>
        </Select>

        <Input
          placeholder="Session ID (optional)"
          value={sessionFilter}
          onChange={(e) => setSessionFilter(e.target.value)}
          className="flex-1 text-sm"
        />
      </div>
    )
  )

  // Results summary
  const ResultsSummary = () => (
    searchQuery && (
      <div className="mb-4 text-sm text-muted-foreground">
        {total > 0 ? (
          <>Found {total} {searchMode === 'messages' ? 'messages' : 'sessions'} matching &quot;{searchQuery}&quot;</>
        ) : (
          <>No {searchMode === 'messages' ? 'messages' : 'sessions'} found matching &quot;{searchQuery}&quot;</>
        )}
      </div>
    )
  )

  // Message result card
  const MessageResultCard = ({ result, onClick }: { result: SearchResult, onClick: () => void }) => (
    <div
      className="p-3 rounded-lg border border-border/50 bg-card hover:bg-muted/50 transition-all cursor-pointer"
      onClick={onClick}
    >
      <div className="flex items-start justify-between mb-2">
        <div className="flex items-center gap-2">
          <Badge className={cn("text-xs", getRoleColor(result.message.role))}>
            {getRoleIcon(result.message.role)}
            <span className="ml-1 capitalize">{result.message.role}</span>
          </Badge>
          <span className="text-sm text-muted-foreground">
            Session: {result.sessionId.slice(0, 8)}...
          </span>
        </div>
        <ChevronRight className="w-4 h-4 text-muted-foreground" />
      </div>

      <div className="text-sm">
        {highlightText(result.context, searchQuery)}
      </div>
    </div>
  )

  // Session result card
  const SessionResultCard = ({ sessionResult, onClick }: { sessionResult: SessionSearchResult, onClick: () => void }) => (
    <div
      className="p-3 rounded-lg border border-border/50 bg-card hover:bg-muted/50 transition-all cursor-pointer"
      onClick={onClick}
    >
      <div className="flex items-start justify-between mb-2">
        <div className="flex items-center gap-2">
          <MessageSquare className="w-4 h-4 text-muted-foreground" />
          <span className="font-medium">
            {sessionResult.sessionId.slice(0, 12)}...
          </span>
          <Badge variant="secondary" className="text-xs">
            {sessionResult.matchCount} matches
          </Badge>
        </div>
        <ChevronRight className="w-4 h-4 text-muted-foreground" />
      </div>

      <div className="text-sm text-muted-foreground mb-2">
        {sessionResult.metadata.messageCount} messages •
        Created {formatDate(sessionResult.metadata.createdAt)} •
        Last active {formatTime(sessionResult.metadata.lastActivity)}
      </div>

      <div className="text-sm">
        {highlightText(sessionResult.firstMatch.context, searchQuery)}
      </div>
    </div>
  )

  // Main content
  const SearchContent = () => (
    <div className="space-y-4">
      {/* Search input */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
        <Input
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          placeholder="Search messages and sessions..."
          className="pl-10"
        />
      </div>

      {/* Search mode toggle */}
      <SearchModeToggle />

      {/* Filter controls */}
      <FilterControls />

      {/* Results summary */}
      <ResultsSummary />

      {/* Error state */}
      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-50 text-red-700 dark:bg-red-900/20 dark:text-red-400">
          <AlertCircle className="w-4 h-4" />
          <span className="text-sm">{error}</span>
        </div>
      )}

      {/* Loading state */}
      {isLoading && (
        <div className="flex items-center justify-center py-8">
          <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
          <span className="ml-2 text-muted-foreground">Searching...</span>
        </div>
      )}

      {/* Results */}
      {!isLoading && searchQuery && (
        <ScrollArea className="h-96">
          <div className="space-y-2">
            {searchMode === 'messages' 
              ? messageResults.map((result) => (
                  <MessageResultCard
                    key={`${result.sessionId}-${result.messageIndex}`}
                    result={result}
                    onClick={() => handleResultClick(result)}
                  />
                ))
              : sessionResults.map((sessionResult) => (
                  <SessionResultCard
                    key={sessionResult.sessionId}
                    sessionResult={sessionResult}
                    onClick={() => handleSessionResultClick(sessionResult)}
                  />
                ))
            }
          </div>
        </ScrollArea>
      )}

      {/* Empty state */}
      {!isLoading && !searchQuery && (
        <div className="text-center py-8 text-muted-foreground">
          <Search className="w-12 h-12 mx-auto mb-4 opacity-50" />
          <p className="text-lg font-medium mb-2">Search your conversations</p>
          <p className="text-sm">
            Find messages and sessions across all your conversations
          </p>
        </div>
      )}
    </div>
  )

  if (variant === 'modal') {
    if (!isOpen) return null;

    return (
      <div 
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundColor: 'rgba(0, 0, 0, 0.8)',
          zIndex: 50,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '16px'
        }}
        onClick={(e) => {
          if (e.target === e.currentTarget) {
            onClose?.();
          }
        }}
      >
        <div 
          style={{
            backgroundColor: 'var(--color-background)',
            border: '1px solid var(--color-border)',
            borderRadius: '8px',
            maxWidth: '672px',
            width: '100%',
            maxHeight: '80vh',
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column'
          }}
        >
          {/* Header */}
          <div style={{
            padding: '24px 24px 0 24px',
            borderBottom: '1px solid var(--color-border)'
          }}>
            <div style={{
              display: 'flex',
              alignItems: 'center',
              gap: '8px',
              marginBottom: '16px'
            }}>
              <Search className="w-5 h-5" />
              <h2 style={{
                fontSize: '18px',
                fontWeight: '600',
                color: 'var(--color-foreground)'
              }}>Search</h2>
              <button
                onClick={onClose}
                style={{
                  marginLeft: 'auto',
                  background: 'none',
                  border: 'none',
                  color: 'var(--color-muted-foreground)',
                  cursor: 'pointer',
                  padding: '4px'
                }}
              >
                ✕
              </button>
            </div>
          </div>

          {/* Content */}
          <div style={{
            padding: '24px',
            overflow: 'auto',
            flex: 1
          }}>
            <SearchContent />
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className={cn("p-4 border rounded-lg bg-background", className)}>
      <SearchContent />
    </div>
  )
}

// Hook for managing search panel state
export function useSearchPanel() {
  const [isOpen, setIsOpen] = React.useState(false)

  const openPanel = React.useCallback(() => {
    setIsOpen(true)
  }, [])

  const closePanel = React.useCallback(() => {
    setIsOpen(false)
  }, [])

  return {
    isOpen,
    openPanel,
    closePanel,
  }
}

"use client"

import * as React from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog"
import { Badge } from "@/components/ui/badge"
import { Separator } from "@/components/ui/separator"
import { 
  Settings,
  FolderOpen,
  Key,
  Globe,
  Terminal,
  AlertCircle,
  Info,
  CheckCircle
} from "lucide-react"
import { cn } from "@/lib/utils"
import { ServerRegistryEntry } from "@/types/server-registry"

interface ServerConfigModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  server: ServerRegistryEntry | null
  onInstall: (server: ServerRegistryEntry, customConfig?: any) => Promise<void>
}

interface ConfigField {
  key: string
  label: string
  description: string
  type: 'text' | 'textarea' | 'password' | 'number'
  required: boolean
  placeholder: string
  value: string
}

export function ServerConfigModal({ 
  open, 
  onOpenChange, 
  server, 
  onInstall 
}: ServerConfigModalProps) {
  const [configFields, setConfigFields] = React.useState<ConfigField[]>([])
  const [envVars, setEnvVars] = React.useState<ConfigField[]>([])
  const [isInstalling, setIsInstalling] = React.useState(false)

  // Generate configuration fields based on server type and requirements
  React.useEffect(() => {
    if (!server) {
      setConfigFields([])
      setEnvVars([])
      return
    }

    const fields: ConfigField[] = []
    const envFields: ConfigField[] = []

    // Type-specific configuration
    if (server.config.type === 'stdio') {
      // Command configuration
      fields.push({
        key: 'command',
        label: 'Command',
        description: 'The command to execute (usually already set)',
        type: 'text',
        required: true,
        placeholder: server.config.command || 'npx',
        value: server.config.command || 'npx'
      })

      // Args configuration - handle special cases
      if (server.id === 'filesystem') {
        fields.push({
          key: 'directory',
          label: 'Allowed Directory',
          description: 'Directory path that the file system server can access (absolute path)',
          type: 'text',
          required: true,
          placeholder: '/Users/username/Documents',
          value: ''
        })
      } else if (server.id === 'sqlite') {
        fields.push({
          key: 'database',
          label: 'Database Path',
          description: 'Path to the SQLite database file',
          type: 'text',
          required: true,
          placeholder: '/path/to/database.db',
          value: ''
        })
      } else if (server.id === 'postgresql') {
        fields.push({
          key: 'connection_string',
          label: 'Connection String',
          description: 'PostgreSQL connection string',
          type: 'text',
          required: true,
          placeholder: 'postgresql://username:password@localhost:5432/database',
          value: ''
        })
      } else if (server.id === 'git') {
        fields.push({
          key: 'repository',
          label: 'Repository Path',
          description: 'Path to the Git repository',
          type: 'text',
          required: true,
          placeholder: '/path/to/git/repo',
          value: ''
        })
      }

      // Environment variables
      if (server.config.env) {
        Object.entries(server.config.env).forEach(([key, defaultValue]) => {
          if (key && defaultValue === '') {
            envFields.push({
              key,
              label: key.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase()),
              description: getEnvDescription(key),
              type: key.toLowerCase().includes('secret') || key.toLowerCase().includes('token') || key.toLowerCase().includes('key') ? 'password' : 'text',
              required: true,
              placeholder: getEnvPlaceholder(key),
              value: ''
            })
          }
        })
      }
    } else if (server.config.type === 'sse' || server.config.type === 'streamable-http') {
      fields.push({
        key: 'url',
        label: 'Server URL',
        description: 'The URL of the MCP server endpoint',
        type: 'text',
        required: true,
        placeholder: server.config.url || 'https://api.example.com/mcp',
        value: server.config.url || ''
      })

      // Headers for authentication
      if (server.config.headers) {
        Object.entries(server.config.headers).forEach(([key, defaultValue]) => {
          if (key && (defaultValue === '' || defaultValue.includes('your-'))) {
            envFields.push({
              key: `header_${key}`,
              label: `Header: ${key}`,
              description: `Value for the ${key} header`,
              type: key.toLowerCase().includes('authorization') ? 'password' : 'text',
              required: key.toLowerCase().includes('authorization'),
              placeholder: defaultValue || '',
              value: ''
            })
          }
        })
      }
    }

    setConfigFields(fields)
    setEnvVars(envFields)
  }, [server])

  const getEnvDescription = (key: string): string => {
    switch (key.toLowerCase()) {
      case 'github_personal_access_token':
        return 'GitHub Personal Access Token for repository access'
      case 'brave_search_api_key':
        return 'Brave Search API key for web searches'
      case 'slack_bot_token':
        return 'Slack Bot Token for workspace access'
      case 'google_application_credentials':
        return 'Path to Google service account credentials JSON file'
      default:
        return `Environment variable: ${key}`
    }
  }

  const getEnvPlaceholder = (key: string): string => {
    switch (key.toLowerCase()) {
      case 'github_personal_access_token':
        return 'ghp_xxxxxxxxxxxxxxxxxxxx'
      case 'brave_search_api_key':
        return 'BSA-xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx'
      case 'slack_bot_token':
        return 'xoxb-xxxxxxxxxx-xxxxxxxxxxxx-xxxxxxxxxxxxxxxxxxxxxxxx'
      case 'google_application_credentials':
        return '/path/to/credentials.json'
      default:
        return `Enter ${key.toLowerCase()}`
    }
  }

  const updateField = (key: string, value: string, isEnv: boolean = false) => {
    if (isEnv) {
      setEnvVars(prev => prev.map(field => 
        field.key === key ? { ...field, value } : field
      ))
    } else {
      setConfigFields(prev => prev.map(field => 
        field.key === key ? { ...field, value } : field
      ))
    }
  }

  const validateFields = (): boolean => {
    const allFields = [...configFields, ...envVars]
    return allFields.every(field => !field.required || field.value.trim() !== '')
  }

  const handleInstall = async () => {
    if (!server || !validateFields()) return

    setIsInstalling(true)
    try {
      // Build custom configuration
      const customConfig = { ...server.config }

      // Apply configuration fields
      configFields.forEach(field => {
        if (field.key === 'directory' && server.id === 'filesystem') {
          // Replace the placeholder directory in args
          customConfig.args = ['-y', '@modelcontextprotocol/server-filesystem', field.value]
        } else if (field.key === 'database' && server.id === 'sqlite') {
          // Replace the placeholder database path in args
          customConfig.args = ['-y', '@modelcontextprotocol/server-sqlite', field.value]
        } else if (field.key === 'connection_string' && server.id === 'postgresql') {
          // Replace the placeholder connection string in args
          customConfig.args = ['-y', '@modelcontextprotocol/server-postgres', field.value]
        } else if (field.key === 'repository' && server.id === 'git') {
          // Replace the placeholder repository path in args
          customConfig.args = ['mcp-server-git', '--repository', field.value]
        } else if (field.key === 'url') {
          customConfig.url = field.value
        } else if (field.key === 'command') {
          customConfig.command = field.value
        }
      })

      // Apply environment variables
      const newEnv = { ...customConfig.env }
      envVars.forEach(field => {
        if (field.key.startsWith('header_')) {
          // Handle headers
          const headerKey = field.key.replace('header_', '')
          if (!customConfig.headers) customConfig.headers = {}
          customConfig.headers[headerKey] = field.value
        } else {
          // Handle environment variables
          newEnv[field.key] = field.value
        }
      })
      customConfig.env = newEnv

      const configuredServer = { ...server, config: customConfig }
      await onInstall(configuredServer, customConfig)
      onOpenChange(false)
    } catch (error) {
      console.error('Failed to install server:', error)
    } finally {
      setIsInstalling(false)
    }
  }

  if (!server) return null

  const hasRequiredFields = configFields.some(f => f.required) || envVars.some(f => f.required)

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Settings className="w-5 h-5" />
            Configure {server.name}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-6">
          {/* Server Info */}
          <div className="flex items-start gap-4 p-4 bg-muted/50 rounded-lg">
            <span className="text-2xl">{server.icon}</span>
            <div className="flex-1">
              <h3 className="font-semibold">{server.name}</h3>
              <p className="text-sm text-muted-foreground">{server.description}</p>
              <div className="flex items-center gap-2 mt-2">
                <Badge variant="secondary" className="capitalize">
                  {server.config.type}
                </Badge>
                <Badge variant="outline">
                  {server.category}
                </Badge>
              </div>
            </div>
          </div>

          {/* Information */}
          {hasRequiredFields ? (
            <div className="flex items-start gap-3 p-3 bg-blue-50 border border-blue-200 rounded-lg">
              <Info className="w-4 h-4 text-blue-600 mt-0.5" />
              <div className="text-sm">
                <p className="font-medium text-blue-900">Configuration Required</p>
                <p className="text-blue-700">This server requires additional configuration before installation.</p>
              </div>
            </div>
          ) : (
            <div className="flex items-start gap-3 p-3 bg-green-50 border border-green-200 rounded-lg">
              <CheckCircle className="w-4 h-4 text-green-600 mt-0.5" />
              <div className="text-sm">
                <p className="font-medium text-green-900">Ready to Install</p>
                <p className="text-green-700">This server is ready to install with default configuration.</p>
              </div>
            </div>
          )}

          {/* Configuration Fields */}
          {configFields.length > 0 && (
            <div className="space-y-4">
              <div className="flex items-center gap-2">
                <Terminal className="w-4 h-4" />
                <h4 className="font-medium">Server Configuration</h4>
              </div>

              {configFields.map((field) => (
                <div key={field.key} className="space-y-2">
                  <Label htmlFor={field.key} className="flex items-center gap-2">
                    {field.label}
                    {field.required && <span className="text-red-500">*</span>}
                  </Label>
                  <Input
                    id={field.key}
                    type={field.type}
                    value={field.value}
                    onChange={(e) => updateField(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className={cn(
                      field.required && !field.value && "border-red-300"
                    )}
                  />
                  <p className="text-xs text-muted-foreground">{field.description}</p>
                </div>
              ))}
            </div>
          )}

          {/* Environment Variables */}
          {envVars.length > 0 && (
            <>
              {configFields.length > 0 && <Separator />}
              <div className="space-y-4">
                <div className="flex items-center gap-2">
                  <Key className="w-4 h-4" />
                  <h4 className="font-medium">Environment Variables & Authentication</h4>
                </div>

                {envVars.map((field) => (
                  <div key={field.key} className="space-y-2">
                    <Label htmlFor={field.key} className="flex items-center gap-2">
                      {field.label}
                      {field.required && <span className="text-red-500">*</span>}
                    </Label>
                    {field.type === 'textarea' ? (
                      <Textarea
                        id={field.key}
                        value={field.value}
                        onChange={(e) => updateField(field.key, e.target.value, true)}
                        placeholder={field.placeholder}
                        className={cn(
                          field.required && !field.value && "border-red-300"
                        )}
                        rows={3}
                      />
                    ) : (
                      <Input
                        id={field.key}
                        type={field.type}
                        value={field.value}
                        onChange={(e) => updateField(field.key, e.target.value, true)}
                        placeholder={field.placeholder}
                        className={cn(
                          field.required && !field.value && "border-red-300"
                        )}
                      />
                    )}
                    <p className="text-xs text-muted-foreground">{field.description}</p>
                  </div>
                ))}
              </div>
            </>
          )}

          {/* Requirements Warning */}
          {server.requirements && (
            <>
              <Separator />
              <div className="space-y-2">
                <h4 className="font-medium flex items-center gap-2">
                  <AlertCircle className="w-4 h-4" />
                  Requirements
                </h4>
                <div className="text-sm text-muted-foreground space-y-1">
                  <p>Platform: {server.requirements.platform}</p>
                  {server.requirements.node && <p>Node.js: {server.requirements.node}</p>}
                  {server.requirements.python && <p>Python: {server.requirements.python}</p>}
                  {server.requirements.dependencies && (
                    <p>Dependencies: {server.requirements.dependencies.join(', ')}</p>
                  )}
                </div>
              </div>
            </>
          )}
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => onOpenChange(false)}
            disabled={isInstalling}
          >
            Cancel
          </Button>
          <Button
            onClick={handleInstall}
            disabled={isInstalling || (hasRequiredFields && !validateFields())}
          >
            {isInstalling ? 'Installing...' : 'Install Server'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Badge } from "@/components/ui/badge"
import { ScrollArea } from "@/components/ui/scroll-area"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { 
  Search,
  Filter,
  Download,
  Check,
  Star,
  ExternalLink,
  Loader2,
  AlertCircle,
  Package,
  Shield,
  Clock,
  User,
  Settings
} from "lucide-react"
import { cn } from "@/lib/utils"
import { useServerRegistry } from "@/hooks/use-server-registry"
import { ServerRegistryEntry, ServerRegistryFilter } from "@/types/server-registry"
import { ServerConfigModal } from "@/components/server-config-modal"

interface ServerRegistryBrowserProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onInstall?: (entry: ServerRegistryEntry, customConfig?: any) => Promise<void>
}

export function ServerRegistryBrowser({ 
  open, 
  onOpenChange, 
  onInstall 
}: ServerRegistryBrowserProps) {
  const {
    entries,
    isLoading,
    error,
    filter,
    categories,
    allTags,
    updateFilter,
    markAsInstalled,
    clearError,
    refreshEntries
  } = useServerRegistry({ autoLoad: true })

  const [searchQuery, setSearchQuery] = React.useState('')
  const [selectedCategory, setSelectedCategory] = React.useState<string>('')
  const [selectedTags, setSelectedTags] = React.useState<string[]>([])
  const [showInstalledOnly, setShowInstalledOnly] = React.useState(false)
  const [showOfficialOnly, setShowOfficialOnly] = React.useState(true) // Official entries shown by default
  const [isInstalling, setIsInstalling] = React.useState<string | null>(null)
  const [configModalOpen, setConfigModalOpen] = React.useState(false)
  const [selectedServerForConfig, setSelectedServerForConfig] = React.useState<ServerRegistryEntry | null>(null)

  // Update filter when search criteria change
  React.useEffect(() => {
    const newFilter: ServerRegistryFilter = {}

    if (searchQuery.trim()) newFilter.search = searchQuery.trim()
    if (selectedCategory) newFilter.category = selectedCategory
    if (selectedTags.length > 0) newFilter.tags = selectedTags
    if (showInstalledOnly) newFilter.installed = true
    // Only set official filter when explicitly toggled off (to show custom entries)
    if (!showOfficialOnly) newFilter.official = false

    updateFilter(newFilter)
  }, [searchQuery, selectedCategory, selectedTags, showInstalledOnly, showOfficialOnly, updateFilter])

  const handleInstall = async (entry: ServerRegistryEntry) => {
    if (entry.isInstalled || isInstalling === entry.id) return

    // Check if server needs configuration
    const needsConfig = needsConfiguration(entry)

    if (needsConfig) {
      setSelectedServerForConfig(entry)
      setConfigModalOpen(true)
      return
    }

    // Install directly if no config needed
    setIsInstalling(entry.id)
    try {
      if (onInstall) {
        await onInstall(entry, undefined)
      }
      // Only mark as installed if the installation was successful
      await markAsInstalled(entry.id)
    } catch (error) {
      console.error('Failed to install server:', error)
      // Don't mark as installed if there was an error
    } finally {
      setIsInstalling(null)
    }
  }

  const handleConfiguredInstall = async (entry: ServerRegistryEntry, customConfig?: any) => {
    setIsInstalling(entry.id)
    try {
      if (onInstall) {
        await onInstall(entry, customConfig)
      }
      // Only mark as installed if the installation was successful
      await markAsInstalled(entry.id)
    } catch (error) {
      console.error('Failed to install configured server:', error)
      // Don't mark as installed if there was an error
    } finally {
      setIsInstalling(null)
    }
  }

  const needsConfiguration = (entry: ServerRegistryEntry): boolean => {
    // Check if server has placeholder values that need user input
    if (entry.config.type === 'stdio') {
      // Check for placeholder directories/paths in args
      const hasPlaceholders = entry.config.args?.some(arg => 
        arg.includes('/path/to/') || 
        arg.includes('your-') ||
        arg === '/path/to/allowed/directory' ||
        arg === '/path/to/database.db' ||
        arg === 'postgresql://localhost/mydb' ||
        arg === '/path/to/git/repo'
      )

      // Check for empty env variables that need API keys
      const hasEmptyEnv = entry.config.env && Object.values(entry.config.env).some(val => val === '')

      return hasPlaceholders || hasEmptyEnv || false
    }

    if (entry.config.type === 'sse' || entry.config.type === 'streamable-http') {
      // Check for placeholder URLs or headers
      const hasPlaceholderUrl = !entry.config.url || entry.config.url.includes('example.com')
      const hasPlaceholderHeaders = entry.config.headers && Object.values(entry.config.headers).some(val => 
        val.includes('your-') || val.includes('Bearer token') || val === ''
      )

      return hasPlaceholderUrl || hasPlaceholderHeaders || false
    }

    return false
  }

  const toggleTag = (tag: string) => {
    setSelectedTags(prev => 
      prev.includes(tag) 
        ? prev.filter(t => t !== tag)
        : [...prev, tag]
    )
  }

  const clearFilters = () => {
    setSearchQuery('')
    setSelectedCategory('')
    setSelectedTags([])
    setShowInstalledOnly(false)
    setShowOfficialOnly(true) // Reset to default (official only)
  }

  const ServerCard = ({ entry }: { entry: ServerRegistryEntry }) => (
    <div className="p-4 border rounded-lg bg-card hover:bg-muted/50 transition-colors">
      <div className="flex items-start justify-between mb-3">
        <div className="flex items-center gap-3 min-w-0 flex-1">
          {entry.icon && (
            <span className="text-2xl flex-shrink-0">{entry.icon}</span>
          )}
          <div className="min-w-0 flex-1">
            <div className="flex items-center gap-2 mb-1">
              <h3 className="font-semibold truncate">{entry.name}</h3>
              {entry.isOfficial && (
                <Badge variant="secondary" className="text-xs">
                  <Shield className="w-3 h-3 mr-1" />
                  Official
                </Badge>
              )}
              {entry.popularity && entry.popularity > 85 && (
                <Badge variant="outline" className="text-xs">
                  <Star className="w-3 h-3 mr-1" />
                  Popular
                </Badge>
              )}
            </div>
            <p className="text-sm text-muted-foreground line-clamp-2 mb-2">
              {entry.description}
            </p>
            <div className="flex items-center gap-4 text-xs text-muted-foreground">
              {entry.author && (
                <span className="flex items-center gap-1">
                  <User className="w-3 h-3" />
                  {entry.author}
                </span>
              )}
              {entry.version && (
                <span className="flex items-center gap-1">
                  <Package className="w-3 h-3" />
                  v{entry.version}
                </span>
              )}
              <span className="flex items-center gap-1">
                <Clock className="w-3 h-3" />
                {entry.lastUpdated.toLocaleDateString()}
              </span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2 flex-shrink-0">
          {entry.homepage && (
            <Button
              variant="ghost"
              size="sm"
              onClick={() => window.open(entry.homepage, '_blank')}
              className="h-8 w-8 p-0"
            >
              <ExternalLink className="w-3 h-3" />
            </Button>
          )}
          <Button
            onClick={() => handleInstall(entry)}
            disabled={entry.isInstalled || isInstalling === entry.id}
            size="sm"
            variant={entry.isInstalled ? "secondary" : "default"}
            className="min-w-[100px]"
          >
            {isInstalling === entry.id ? (
              <Loader2 className="w-3 h-3 animate-spin mr-1" />
            ) : entry.isInstalled ? (
              <Check className="w-3 h-3 mr-1" />
            ) : needsConfiguration(entry) ? (
              <Settings className="w-3 h-3 mr-1" />
            ) : (
              <Download className="w-3 h-3 mr-1" />
            )}
            {entry.isInstalled ? 'Installed' : needsConfiguration(entry) ? 'Configure' : 'Install'}
          </Button>
        </div>
      </div>

      {/* Tags */}
      {entry.tags && entry.tags.length > 0 && (
        <div className="flex flex-wrap gap-1 mb-3">
          {entry.tags.slice(0, 4).map((tag) => (
            <Badge
              key={tag}
              variant="outline"
              className="text-xs cursor-pointer hover:bg-accent"
              onClick={() => toggleTag(tag)}
            >
              {tag}
            </Badge>
          ))}
          {entry.tags.length > 4 && (
            <Badge variant="outline" className="text-xs">
              +{entry.tags.length - 4} more
            </Badge>
          )}
        </div>
      )}

      {/* Category and Type */}
      <div className="flex items-center justify-between text-xs">
        <Badge variant="secondary" className="capitalize">
          {entry.category}
        </Badge>
        <span className="text-muted-foreground uppercase">
          {entry.config.type}
        </span>
      </div>
    </div>
  )

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-4xl max-h-[90vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Package className="w-5 h-5" />
            MCP Server Registry
          </DialogTitle>
        </DialogHeader>

        {/* Search and Filters */}
        <div className="space-y-4 border-b pb-4">
          <div className="flex gap-2">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                placeholder="Search servers..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="pl-9"
              />
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={refreshEntries}
              disabled={isLoading}
            >
              <Loader2 className={cn("w-4 h-4", isLoading && "animate-spin")} />
            </Button>
          </div>

          <div className="flex flex-wrap gap-2 items-center">
            <Select value={selectedCategory || "all"} onValueChange={(value) => setSelectedCategory(value === "all" ? "" : value)}>
              <SelectTrigger className="w-32">
                <SelectValue placeholder="Category" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Categories</SelectItem>
                {categories.map((category) => (
                  <SelectItem key={category} value={category} className="capitalize">
                    {category}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            <Button
              variant={showOfficialOnly ? "default" : "outline"}
              size="sm"
              onClick={() => setShowOfficialOnly(!showOfficialOnly)}
              title={showOfficialOnly ? "Showing official servers only" : "Show custom servers too"}
            >
              <Shield className="w-3 h-3 mr-1" />
              {showOfficialOnly ? "Official Only" : "Include Custom"}
            </Button>

            <Button
              variant={showInstalledOnly ? "default" : "outline"}
              size="sm"
              onClick={() => setShowInstalledOnly(!showInstalledOnly)}
            >
              <Check className="w-3 h-3 mr-1" />
              Installed
            </Button>

            {(searchQuery || selectedCategory || selectedTags.length > 0 || showInstalledOnly || !showOfficialOnly) && (
              <Button variant="ghost" size="sm" onClick={clearFilters}>
                Clear Filters
              </Button>
            )}
          </div>

          {/* Selected Tags */}
          {selectedTags.length > 0 && (
            <div className="flex flex-wrap gap-1">
              <span className="text-sm text-muted-foreground mr-2">Tags:</span>
              {selectedTags.map((tag) => (
                <Badge
                  key={tag}
                  variant="default"
                  className="text-xs cursor-pointer"
                  onClick={() => toggleTag(tag)}
                >
                  {tag} ×
                </Badge>
              ))}
            </div>
          )}
        </div>

        {/* Error Display */}
        {error && (
          <div className="flex items-center gap-2 p-3 bg-red-50 border border-red-200 rounded-lg text-red-700">
            <AlertCircle className="w-4 h-4" />
            <span className="text-sm">{error}</span>
            <Button variant="ghost" size="sm" onClick={clearError} className="ml-auto">
              Dismiss
            </Button>
          </div>
        )}

        {/* Server List */}
        <ScrollArea className="flex-1 min-h-0">
          {isLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="w-6 h-6 animate-spin text-muted-foreground mr-2" />
              <span className="text-muted-foreground">Loading servers...</span>
            </div>
          ) : entries.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground">
              <Package className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p className="font-medium mb-1">No servers found</p>
              <p className="text-sm">Try adjusting your search criteria</p>
            </div>
          ) : (
            <div className="grid gap-3 p-1">
              {entries.map((entry) => (
                <ServerCard key={entry.id} entry={entry} />
              ))}
            </div>
          )}
        </ScrollArea>

        {/* Footer */}
        <div className="flex items-center justify-between pt-4 border-t text-sm text-muted-foreground">
          <span>
            {entries.length} server{entries.length !== 1 ? 's' : ''} found
          </span>
          <span>
            {entries.filter(e => e.isInstalled).length} installed
          </span>
        </div>
      </DialogContent>

      {/* Server Configuration Modal */}
      <ServerConfigModal
        open={configModalOpen}
        onOpenChange={setConfigModalOpen}
        server={selectedServerForConfig}
        onInstall={handleConfiguredInstall}
      />
    </Dialog>
  )
}

"use client"

import * as React from "react"
import { Button } from "@/components/ui/button"
import { ScrollArea } from "@/components/ui/scroll-area"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
// import { AddCustomServerModal } from "@/components/modals" // Temporarily disabled
import { ServerRegistryBrowser } from "@/components/server-registry-browser"
import { 
  Server,
  Plus,
  X,
  Trash2,
  Wrench,
  ChevronDown,
  ChevronUp,
  Loader2,
  AlertCircle,
  RefreshCw,
  Zap,
  Package,
  Settings
} from "lucide-react"
import { cn } from "@/lib/utils"
import { McpServer, McpTool, ServerRegistryEntryForPanel } from "@/types/server-registry"

interface ServersPanelProps {
  isOpen?: boolean
  onClose?: () => void
  variant?: 'overlay' | 'inline'
  className?: string
}

export function ServersPanel({ 
  isOpen = true, 
  onClose, 
  variant = 'overlay',
  className 
}: ServersPanelProps) {
  // State management
  const [servers, setServers] = React.useState<McpServer[]>([])
  const [selectedServerId, setSelectedServerId] = React.useState<string | null>(null)
  const [tools, setTools] = React.useState<McpTool[]>([])
  const [isLoadingServers, setIsLoadingServers] = React.useState(false)
  const [isLoadingTools, setIsLoadingTools] = React.useState(false)
  const [serverError, setServerError] = React.useState<string | null>(null)
  const [toolsError, setToolsError] = React.useState<string | null>(null)
  const [isToolsExpanded, setIsToolsExpanded] = React.useState(false)
  const [isDeletingServer, setIsDeletingServer] = React.useState<string | null>(null)
  const [isRegistryModalOpen, setIsRegistryModalOpen] = React.useState(false)
  const [isRegistryBrowserOpen, setIsRegistryBrowserOpen] = React.useState(false)

  // Error handling logic
  const handleError = React.useCallback((message: string, area: 'servers' | 'tools' | 'delete') => {
    console.error(`ServersPanel Error (${area}):`, message)
    if (area === 'servers') setServerError(message)
    if (area === 'tools') setToolsError(message)
  }, [])

  // Server fetching with auto-selection
  const fetchServers = React.useCallback(async (signal?: AbortSignal) => {
    setIsLoadingServers(true)
    setServerError(null)
    setServers([]) // Clear existing servers
    setSelectedServerId(null) // Reset selected server
    setTools([]) // Clear tools
    setToolsError(null)

    try {
      const response = await fetch(`/api/mcp/servers`, signal ? { signal } : {})
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({ error: 'Failed to fetch servers' }))
        throw new Error(errorData.message || errorData.error || `Server List: ${response.statusText}`)
      }

      const data = await response.json()
      const fetchedServers = data.data?.servers || data.servers || []
      setServers(fetchedServers)

      if (fetchedServers.length > 0) {
        // Auto-select the first connected server if available
        const firstConnected = fetchedServers.find((s: McpServer) => s.status === 'connected')
        if (firstConnected) {
          setSelectedServerId(firstConnected.id)
        } else if (fetchedServers.length > 0) {
          setSelectedServerId(fetchedServers[0].id) // Select first server if none are connected
        }
      }
    } catch (err: any) {
      if (err.name !== 'AbortError') {
        handleError(err.message, 'servers')
      }
    } finally {
      if (!signal?.aborted) {
        setIsLoadingServers(false)
      }
    }
  }, [handleError])

  // Tools fetching logic
  const handleServerSelect = React.useCallback(async (serverId: string, signal?: AbortSignal) => {
    const server = servers.find(s => s.id === serverId)
    setTools([])
    setToolsError(null)

    console.log(`🔧 Fetching tools for server: ${serverId}`, { server, status: server?.status })

    if (!server || server.status !== 'connected') {
      console.warn(`Server "${server?.name || serverId}" is not connected or not found. Cannot fetch tools.`)
      return
    }

    setIsLoadingTools(true)
    try {
      const encodedServerId = encodeURIComponent(serverId)
      const url = `/api/mcp/servers/${encodedServerId}/tools`
      console.log(`🌐 Fetching tools from: ${url} (original serverId: "${serverId}")`)
      const response = await fetch(url, signal ? { signal } : {})
      console.log(`📡 Tools API response status:`, response.status, response.statusText)

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({ error: `Failed to fetch tools for ${server.name}` }))
        throw new Error(errorData.message || errorData.error || `Tool List (${server.name}): ${response.statusText}`)
      }

      const data = await response.json()
      console.log(`📊 Tools API response for ${serverId}:`, data)
      const tools = data.data?.tools || data.tools || []
      console.log(`🔨 Extracted ${tools.length} tools for ${serverId}:`, tools.map((t: McpTool) => t.name))

      if (!signal?.aborted) {
        setTools(tools)
      }

      if (tools.length === 0) {
        console.log(`No tools found for server "${server.name}".`)
      }
    } catch (err: any) {
      if (err.name !== 'AbortError') {
        handleError(err.message, 'tools')
      }
    } finally {
      if (!signal?.aborted) {
        setIsLoadingTools(false)
      }
    }
  }, [servers, handleError])

  // Server installation logic
  const handleInstallServer = async (entry: ServerRegistryEntryForPanel) => {
    setIsRegistryModalOpen(false)

    // Prepare the config for the connect API
    const payload = {
      name: entry.name,
      transport: entry.config.type, // Map 'type' to 'transport' as expected by validation
      command: entry.config.command,
      args: entry.config.args || [],
      url: entry.config.url,
      env: entry.config.env || {},
      headers: entry.config.headers || {},
      timeout: entry.config.timeout || 30000,
    }

    try {
      console.log(`🚀 Installing server: ${entry.name}`)
      const res = await fetch('/api/connect-server', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      })

      const result = await res.json()
      if (!res.ok) {
        throw new Error(result.error || `Server returned status ${res.status}`)
      }

      console.log(`✅ Server ${entry.name} installed successfully`)

      // Refresh the servers list
      await fetchServers()

      // Auto-select the newly installed server for immediate tools display
      setSelectedServerId(entry.name)
      console.log(`🎯 Auto-selected newly installed server: ${entry.name}`)

    } catch (error: any) {
      console.error(`❌ Failed to install server ${entry.name}:`, error)
      handleError(error.message || 'Failed to install server', 'servers')
      // Re-throw error so ServerRegistryBrowser doesn't mark it as installed
      throw error
    }
  }

  // Server deletion logic
  const handleDeleteServer = async (serverId: string) => {
    const server = servers.find(s => s.id === serverId)
    if (!server) return

    if (!window.confirm(`Are you sure you want to remove server "${server.name}"?`)) {
      return
    }

    setIsDeletingServer(serverId)
    setServerError(null)

    try {
      const encodedServerId = encodeURIComponent(serverId)
      const response = await fetch(`/api/mcp/servers/${encodedServerId}`, { method: 'DELETE' })
      if (!response.ok) {
        const errorData = await response.json().catch(() => ({ error: 'Failed to remove server' }))
        throw new Error(errorData.message || errorData.error || `Server Removal: ${response.statusText}`)
      }

      // If this was the selected server, deselect it
      if (selectedServerId === serverId) {
        setSelectedServerId(null)
        setTools([])
      }

      // Notify other components that a server was uninstalled
      window.dispatchEvent(new CustomEvent('mcp-server-uninstalled', { 
        detail: { serverId, serverName: server.name }
      }))

      await fetchServers() // Refresh server list
    } catch (err: any) {
      handleError(err.message, 'servers')
    } finally {
      setIsDeletingServer(null)
    }
  }

  // Panel lifecycle management
  React.useEffect(() => {
    if (!isOpen) return
    const controller = new AbortController()
    fetchServers(controller.signal)
    // When panel opens, ensure no server is stuck in deleting state from a previous quick close
    setIsDeletingServer(null)
    return () => {
      controller.abort()
    }
  }, [isOpen, fetchServers])

  React.useEffect(() => {
    console.log(`🔄 selectedServerId changed to: ${selectedServerId}`)
    if (!selectedServerId) return
    const controller = new AbortController()
    handleServerSelect(selectedServerId, controller.signal)
    return () => {
      controller.abort()
    }
  }, [selectedServerId, handleServerSelect])

  // Server status indicator
  const getServerStatusColor = (status: string) => {
    switch (status) {
      case 'connected':
        return 'bg-green-500'
      case 'error':
        return 'bg-red-500'
      case 'disconnected':
        return 'bg-gray-500'
      default:
        return 'bg-yellow-500'
    }
  }

  const getServerStatusText = (status: string) => {
    switch (status) {
      case 'connected':
        return 'Connected'
      case 'error':
        return 'Error'
      case 'disconnected':
        return 'Disconnected'
      default:
        return 'Unknown'
    }
  }

  const getServerTypeIcon = (type: string) => {
    switch (type) {
      case 'stdio':
        return <Zap className="w-3 h-3" />
      case 'sse':
        return <Package className="w-3 h-3" />
      case 'streamable-http':
        return <Settings className="w-3 h-3" />
      default:
        return <Server className="w-3 h-3" />
    }
  }

  const ServerStatusIndicator = ({ status }: { status: string }) => (
    <div className={cn(
      "w-2 h-2 rounded-full flex-shrink-0",
      getServerStatusColor(status)
    )} />
  )

  // Tool parameters display
  const ToolParametersDisplay = ({ tool }: { tool: McpTool }) => {
    const properties = tool.parameters?.properties || tool.inputSchema?.properties
    return properties ? (
      <div className="flex flex-wrap gap-1 mt-2">
        {Object.keys(properties).slice(0, 3).map((param) => (
          <span
            key={param}
            className="inline-flex items-center px-2 py-1 rounded-md bg-muted text-xs font-medium"
          >
            {param}
          </span>
        ))}
        {Object.keys(properties).length > 3 && (
          <span className="text-xs text-muted-foreground">
            +{Object.keys(properties).length - 3} more
          </span>
        )}
      </div>
    ) : null
  }

  // Variant-based styling
  const getVariantClasses = (variant: 'overlay' | 'inline', isOpen: boolean) => {
    if (variant === 'overlay') {
      return cn(
        "fixed top-0 right-0 z-40 h-screen w-80 bg-card border-l border-border shadow-xl transition-transform transform flex flex-col",
        isOpen ? "translate-x-0" : "translate-x-full"
      )
    }
    return "h-full w-full flex flex-col bg-card"
  }

  const selectedServer = servers.find(s => s.id === selectedServerId)

  return (
    <div className={cn(getVariantClasses(variant, isOpen), className)}>
      {/* Header */}
      <div className="flex items-center justify-between p-4 border-b">
        <div className="flex items-center gap-2">
          <Server className="w-5 h-5" />
          <h2 className="font-semibold">MCP Servers</h2>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => fetchServers()}
            disabled={isLoadingServers}
          >
            <RefreshCw className={cn("w-4 h-4", isLoadingServers && "animate-spin")} />
          </Button>
          {variant === 'overlay' && onClose && (
            <Button variant="ghost" size="sm" onClick={onClose}>
              <X className="w-4 h-4" />
            </Button>
          )}
        </div>
      </div>

      {/* Error display */}
      {serverError && (
        <div className="mx-4 mt-4 p-3 bg-red-50 border border-red-200 rounded-lg">
          <div className="flex items-center gap-2 text-red-700">
            <AlertCircle className="w-4 h-4" />
            <span className="text-sm font-medium">Server Error</span>
          </div>
          <p className="text-sm text-red-600 mt-1">{serverError}</p>
        </div>
      )}

      {/* Main content area */}
      <div className="flex-1 flex flex-col min-h-0">
        {/* Server list section */}
        <div className="p-4 border-b">
          <div className="flex items-center justify-between mb-3">
            <h3 className="text-sm font-medium">Connected Servers ({servers.length})</h3>
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline" size="sm">
                  <Plus className="w-4 h-4 mr-1" />
                  Add
                  <ChevronDown className="w-3 h-3 ml-1" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem onClick={() => setIsRegistryBrowserOpen(true)}>
                  <Package className="w-4 h-4 mr-2" />
                  Browse Registry
                </DropdownMenuItem>
                {/* Temporarily hidden - will develop later
                <DropdownMenuItem onClick={() => setIsRegistryModalOpen(true)}>
                  <Settings className="w-4 h-4 mr-2" />
                  Custom Server
                </DropdownMenuItem>
                */}
              </DropdownMenuContent>
            </DropdownMenu>
          </div>

          {isLoadingServers ? (
            <div className="flex items-center justify-center py-8">
              <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
              <span className="ml-2 text-sm text-muted-foreground">Loading servers...</span>
            </div>
          ) : servers.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              <Server className="w-12 h-12 mx-auto mb-3 opacity-50" />
              <p className="text-sm font-medium mb-1">No servers connected</p>
              <p className="text-xs">Add a server to get started</p>
            </div>
          ) : (
            <div className="space-y-2">
              {servers.map((server) => (
                <div
                  key={server.id}
                  className={cn(
                    "p-3 rounded-lg border cursor-pointer transition-colors",
                    selectedServerId === server.id
                      ? "bg-accent border-accent-foreground/20"
                      : "bg-card hover:bg-muted/50"
                  )}
                  onClick={() => {
                    console.log(`🖱️ Server clicked: ${server.id} (${server.name})`)
                    setSelectedServerId(server.id)
                  }}
                >
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3 min-w-0">
                      <ServerStatusIndicator status={server.status} />
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-2 mb-1">
                          <p className="text-sm font-medium truncate">{server.name}</p>
                          <div className="flex items-center gap-1">
                            {getServerTypeIcon(server.config?.type || 'stdio')}
                            <span className="text-xs text-muted-foreground uppercase font-mono">
                              {server.config?.type || 'stdio'}
                            </span>
                          </div>
                        </div>
                        <div className="flex items-center gap-2">
                          <span className={cn(
                            "text-xs px-1.5 py-0.5 rounded text-white font-medium",
                            getServerStatusColor(server.status)
                          )}>
                            {getServerStatusText(server.status)}
                          </span>
                          {server.lastSeen && (
                            <span className="text-xs text-muted-foreground">
                              Last seen: {new Date(server.lastSeen).toLocaleTimeString()}
                            </span>
                          )}
                        </div>
                      </div>
                    </div>
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={(e) => {
                        e.stopPropagation()
                        handleDeleteServer(server.id)
                      }}
                      disabled={isDeletingServer === server.id}
                      className="h-6 w-6 p-0"
                    >
                      {isDeletingServer === server.id ? (
                        <Loader2 className="w-3 h-3 animate-spin" />
                      ) : (
                        <Trash2 className="w-3 h-3" />
                      )}
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Tools section - takes remaining space */}
        {selectedServer && (
          <div className="flex-1 flex flex-col min-h-0">
            <div className="p-4 border-b">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Wrench className="w-4 h-4" />
                  <h3 className="text-sm font-medium">Tools ({tools.length})</h3>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setIsToolsExpanded(!isToolsExpanded)}
                  className="h-6 w-6 p-0"
                >
                  {isToolsExpanded ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                </Button>
              </div>

              {toolsError && (
                <div className="mt-3 p-2 bg-red-50 border border-red-200 rounded text-xs text-red-600">
                  <div className="flex items-center gap-1">
                    <AlertCircle className="w-3 h-3" />
                    <span>{toolsError}</span>
                  </div>
                </div>
              )}
            </div>

            {isToolsExpanded && (
              <div className="flex-1 flex flex-col min-h-0">
                {isLoadingTools ? (
                  <div className="flex items-center justify-center py-8">
                    <Loader2 className="w-4 h-4 animate-spin text-muted-foreground" />
                    <span className="ml-2 text-xs text-muted-foreground">Loading tools...</span>
                  </div>
                ) : tools.length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <Wrench className="w-8 h-8 mx-auto mb-2 opacity-50" />
                    <p className="text-xs">No tools available</p>
                  </div>
                ) : (
                  <ScrollArea className="flex-1 px-4">
                    <div className="space-y-2 pb-4">
                      {tools.map((tool) => (
                        <div key={tool.name} className="p-2 bg-muted/50 rounded text-xs">
                          <div className="flex items-center gap-2 mb-1">
                            <Zap className="w-3 h-3 text-muted-foreground" />
                            <span className="font-medium">{tool.name}</span>
                          </div>
                          {tool.description && (
                            <p className="text-muted-foreground mb-1 text-xs">{tool.description}</p>
                          )}
                          <ToolParametersDisplay tool={tool} />
                        </div>
                      ))}
                    </div>
                  </ScrollArea>
                )}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Server Registry Browser */}
      <ServerRegistryBrowser
        open={isRegistryBrowserOpen}
        onOpenChange={setIsRegistryBrowserOpen}
        onInstall={async (entry, customConfig) => {
          // Convert ServerRegistryEntry to ServerRegistryEntryForPanel and install
          const panelEntry: ServerRegistryEntryForPanel = {
            id: entry.id,
            name: entry.name,
            config: customConfig || entry.config
          }
          await handleInstallServer(panelEntry)
        }}
      />

      {/* Add Server Modal - Temporarily hidden for development
      <AddCustomServerModal
        open={isRegistryModalOpen}
        onOpenChange={setIsRegistryModalOpen}
        onSubmit={async (serverEntry) => {
          // Convert ServerRegistryEntry to ServerRegistryEntryForPanel
          const panelEntry: ServerRegistryEntryForPanel = {
            id: Date.now().toString(),
            name: serverEntry.name,
            config: serverEntry.config
          }
          await handleInstallServer(panelEntry)
        }}
      />
      */}
    </div>
  )
}

// Hook for managing servers panel state
export function useServersPanel() {
  const [isOpen, setIsOpen] = React.useState(false)

  const openPanel = React.useCallback(() => {
    setIsOpen(true)
  }, [])

  const closePanel = React.useCallback(() => {
    setIsOpen(false)
  }, [])

  return {
    isOpen,
    openPanel,
    closePanel,
  }
}

"use client"

import React from 'react'
import { AlertCircle, RefreshCw } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { useSessionStore } from '@/stores/session-store'

interface SessionErrorBoundaryState {
  hasError: boolean
  error: Error | null
  errorInfo: React.ErrorInfo | null
}

interface SessionErrorBoundaryProps {
  children: React.ReactNode
  fallback?: (error: Error, retry: () => void) => React.ReactNode
}

export class SessionErrorBoundary extends React.Component<
  SessionErrorBoundaryProps,
  SessionErrorBoundaryState
> {
  constructor(props: SessionErrorBoundaryProps) {
    super(props)
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    }
  }

  static getDerivedStateFromError(error: Error): Partial<SessionErrorBoundaryState> {
    return {
      hasError: true,
      error,
    }
  }

  componentDidCatch(error: Error, errorInfo: React.ErrorInfo) {
    console.error('Session Error Boundary caught an error:', error, errorInfo)
    this.setState({
      error,
      errorInfo,
    })

    // Clear potentially corrupted session cache
    try {
      useSessionStore.getState().clearSessionCache()
    } catch (clearError) {
      console.error('Failed to clear session cache:', clearError)
    }
  }

  handleRetry = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
    })
  }

  render() {
    if (this.state.hasError && this.state.error) {
      if (this.props.fallback) {
        return this.props.fallback(this.state.error, this.handleRetry)
      }

      return (
        <div className="flex flex-col items-center justify-center p-8 text-center">
          <AlertCircle className="w-12 h-12 text-destructive mb-4" />
          <h2 className="text-lg font-semibold mb-2">Session Error</h2>
          <p className="text-sm text-muted-foreground mb-4 max-w-md">
            An error occurred while managing sessions. This might be due to network issues or
            corrupted session data.
          </p>
          <div className="space-y-2">
            <Button onClick={this.handleRetry} className="flex items-center gap-2">
              <RefreshCw className="w-4 h-4" />
              Try Again
            </Button>
            <details className="text-xs text-muted-foreground mt-4">
              <summary className="cursor-pointer">Error Details</summary>
              <pre className="mt-2 p-2 bg-muted rounded text-left overflow-auto max-w-md">
                {this.state.error.message}
                {process.env.NODE_ENV === 'development' && this.state.errorInfo && (
                  <>
                    {'\n\n'}
                    {this.state.errorInfo.componentStack}
                  </>
                )}
              </pre>
            </details>
          </div>
        </div>
      )
    }

    return this.props.children
  }
}

// Hook version for functional components
export function useSessionErrorHandler() {
  const { clearSessionCache, setEnableOptimizations } = useSessionStore()

  const handleSessionError = React.useCallback((error: Error) => {
    console.error('Session operation failed:', error)

    // If it's a network error, disable optimizations temporarily
    if (error.message.includes('fetch') || error.message.includes('network')) {
      setEnableOptimizations(false)

      // Re-enable after 30 seconds
      setTimeout(() => {
        setEnableOptimizations(true)
      }, 30000)
    }

    // If it's a cache-related error, clear the cache
    if (error.message.includes('cache') || error.message.includes('expired')) {
      clearSessionCache()
    }
  }, [clearSessionCache, setEnableOptimizations])

  return { handleSessionError }
}

// Session loading fallback component
export function SessionLoadingFallback({ 
  message = "Loading session...",
  timeout = 10000 // 10 seconds
}: { 
  message?: string
  timeout?: number 
}) {
  const [showError, setShowError] = React.useState(false)

  React.useEffect(() => {
    const timer = setTimeout(() => {
      setShowError(true)
    }, timeout)

    return () => clearTimeout(timer)
  }, [timeout])

  if (showError) {
    return (
      <div className="flex flex-col items-center justify-center p-8 text-center">
        <AlertCircle className="w-8 h-8 text-yellow-500 mb-4" />
        <p className="text-sm text-muted-foreground">
          Session is taking longer than expected to load...
        </p>
      </div>
    )
  }

  return (
    <div className="flex flex-col items-center justify-center p-8 text-center">
      <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary mb-4"></div>
      <p className="text-sm text-muted-foreground">{message}</p>
    </div>
  )
}

// Session not found fallback component
export function SessionNotFoundFallback({ 
  sessionId, 
  onCreateNew,
  onGoBack 
}: { 
  sessionId: string
  onCreateNew?: () => void
  onGoBack?: () => void 
}) {
  return (
    <div className="flex flex-col items-center justify-center p-8 text-center">
      <AlertCircle className="w-12 h-12 text-muted-foreground mb-4" />
      <h2 className="text-lg font-semibold mb-2">Session Not Found</h2>
      <p className="text-sm text-muted-foreground mb-4 max-w-md">
        The session &quot;{sessionId}&quot; could not be found. It may have been deleted or is no longer available.
      </p>
      <div className="flex gap-2">
        {onGoBack && (
          <Button variant="outline" onClick={onGoBack}>
            Go Back
          </Button>
        )}
        {onCreateNew && (
          <Button onClick={onCreateNew}>
            Create New Session
          </Button>
        )}
      </div>
    </div>
  )
}

"use client"

import * as React from "react"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Badge } from "@/components/ui/badge"
import { ScrollArea } from "@/components/ui/scroll-area"
import { 
  MessageSquare,
  Plus,
  Trash2,
  Clock,
  Calendar,
  Hash,
  Loader2,
  AlertCircle,
  X,
  RefreshCw
} from "lucide-react"
import { cn } from "@/lib/utils"
import { Session } from "@/types/server-registry"
import { useCreateSession, useSessions, useDeleteSession } from "@/hooks/use-sessions"
import { useSessionStore } from "@/stores/session-store"

interface SessionPanelProps {
  isOpen: boolean
  onClose: () => void
  currentSessionId?: string | null
  onSessionChange: (sessionId: string) => void
  returnToWelcome: () => void
  variant?: 'inline' | 'modal'
  className?: string
}

export function SessionPanel({ 
  isOpen, 
  onClose, 
  currentSessionId, 
  onSessionChange, 
  returnToWelcome,
  variant = 'modal',
  className 
}: SessionPanelProps) {
  // Use React Query hooks as single source of truth for immediate UI updates
  const { sessions, isLoading: loading, error: fetchError, refetch: refetchSessions } = useSessions()
  const createSessionMutation = useCreateSession()
  const deleteSessionMutation = useDeleteSession()

  // Get deleting session state from store
  const { deletingSessionId } = useSessionStore()

  // Local state management
  const [error, setError] = React.useState<string | null>(null)
  const [isNewSessionOpen, setNewSessionOpen] = React.useState(false)
  const [newSessionId, setNewSessionId] = React.useState('')

  // Scroll position preservation
  const scrollAreaRef = React.useRef<HTMLDivElement>(null)
  const savedScrollPosition = React.useRef<number>(0)

  // Conversation management states
  const [isDeleteConversationDialogOpen, setDeleteConversationDialogOpen] = React.useState(false)
  const [selectedSessionForAction, setSelectedSessionForAction] = React.useState<string | null>(null)
  const [isDeletingConversation, setIsDeletingConversation] = React.useState(false)

  // Date/time formatting logic
  const formatDate = React.useCallback((dateString: string | null) => {
    if (!dateString) return 'Unknown'
    const date = new Date(dateString)
    return date.toLocaleDateString() + ' ' + date.toLocaleTimeString([], {
      hour: '2-digit',
      minute: '2-digit'
    })
  }, [])

  const formatRelativeTime = React.useCallback((dateString: string | null) => {
    if (!dateString) return 'Unknown'
    const date = new Date(dateString)
    const now = new Date()
    const diff = now.getTime() - date.getTime()
    const minutes = Math.floor(diff / 60000)
    const hours = Math.floor(diff / 3600000)
    const days = Math.floor(diff / 86400000)

    if (minutes < 1) return 'Just now'
    if (minutes < 60) return `${minutes}m ago`
    if (hours < 24) return `${hours}h ago`
    return `${days}d ago`
  }, [])

  // Handle fetch errors
  React.useEffect(() => {
    if (fetchError) {
      setError(fetchError)
    } else {
      setError(null)
    }
  }, [fetchError])

  // Optional refresh when panel opens (but React Query handles most cases automatically)
  React.useEffect(() => {
    if (isOpen) {
      // Only refetch if data is stale, React Query will decide
      refetchSessions()
    }
  }, [isOpen, refetchSessions])

  // Session creation with optimistic updates (no manual refresh needed)
  const handleCreateSession = async () => {
    try {
      const sessionId = newSessionId.trim() || undefined
      const session = await createSessionMutation.mutateAsync(sessionId)

      setNewSessionId('')
      setNewSessionOpen(false)

      // React Query optimistic updates handle UI changes automatically
      // Switch to the new session
      onSessionChange(session.id)

    } catch (err) {
      console.error('Error creating session:', err)
      setError(err instanceof Error ? err.message : 'Failed to create session')
    }
  }

  // Session deletion with optimistic updates (no manual refresh needed)
  const handleDeleteSession = async (sessionId: string) => {
    try {
      // If we're deleting the current session, switch away from it first
      if (currentSessionId === sessionId) {
        returnToWelcome()
        // Brief delay to ensure backend processes the session switch
        await new Promise(resolve => setTimeout(resolve, 100))
      }

      // React Query optimistic updates handle UI changes automatically
      await deleteSessionMutation.mutateAsync(sessionId)

    } catch (err) {
      console.error('Error deleting session:', err)
      setError(err instanceof Error ? err.message : 'Failed to delete session')
    }
  }

  // Conversation deletion with optimistic updates
  const handleDeleteConversation = async () => {
    if (!selectedSessionForAction) return

    setIsDeletingConversation(true)
    try {
      // If we're deleting the current session, switch away from it first
      if (currentSessionId === selectedSessionForAction) {
        returnToWelcome()
        // Brief delay to ensure backend processes the session switch
        await new Promise(resolve => setTimeout(resolve, 100))
      }

      // React Query optimistic updates handle UI changes automatically
      await deleteSessionMutation.mutateAsync(selectedSessionForAction)

      setDeleteConversationDialogOpen(false)
      setSelectedSessionForAction(null)
    } catch (error) {
      console.error('Error deleting conversation:', error)
      setError(error instanceof Error ? error.message : 'Failed to delete conversation')
    } finally {
      setIsDeletingConversation(false)
    }
  }

  // Session actions component
  const SessionActions = ({ session, onDeleteConversation, onDeleteSession }: {
    session: Session
    onDeleteConversation: () => void
    onDeleteSession: () => void
  }) => (
    <div className="flex items-center space-x-1">
      {session.messageCount > 0 ? (
        <Button
          variant="ghost"
          size="sm"
          onClick={(e) => {
            e.stopPropagation()
            onDeleteConversation()
          }}
          className="h-8 w-8 p-0 opacity-0 group-hover:opacity-100 transition-opacity"
          title="Delete Conversation"
        >
          <Trash2 className="h-4 w-4 text-destructive" />
        </Button>
      ) : (
        <Button
          variant="ghost"
          size="sm"
          onClick={(e) => {
            e.stopPropagation()
            onDeleteSession()
          }}
          className="h-8 w-8 p-0 opacity-0 group-hover:opacity-100 transition-opacity"
          title="Delete Session"
          disabled={deletingSessionId === session.id}
        >
          {deletingSessionId === session.id ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Trash2 className="h-4 w-4 text-destructive" />
          )}
        </Button>
      )}
    </div>
  )

  // Enhanced session change handler with scroll preservation
  const handleSessionSelect = React.useCallback((sessionId: string) => {
    // Save current scroll position
    if (scrollAreaRef.current) {
      savedScrollPosition.current = scrollAreaRef.current.scrollTop
    }

    // Call the original session change handler
    onSessionChange(sessionId)

    // Restore scroll position after state updates
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (scrollAreaRef.current && savedScrollPosition.current > 0) {
          scrollAreaRef.current.scrollTop = savedScrollPosition.current
        }
      })
    })
  }, [onSessionChange])

  // Session card component
  const SessionCard = ({ session, isActive, onSelect, onDelete }: {
    session: Session
    isActive: boolean
    onSelect: () => void
    onDelete: () => void
  }) => {
    return (
      <div
        className={cn(
          "group p-3 rounded-lg border border-border/50 bg-card hover:bg-muted/50 transition-all cursor-pointer",
          isActive && "ring-2 ring-primary bg-primary/5"
        )}
        onClick={onSelect}
      >
      <div className="flex items-start justify-between">
        <div className="flex-1 min-w-0">
          <div className="flex items-center space-x-2 mb-2">
            <h3 className="font-medium text-sm truncate">
              {session.id}
            </h3>
            {isActive && (
              <Badge variant="secondary" className="text-xs">
                Active
              </Badge>
            )}
          </div>

          <div className="space-y-1 text-xs text-muted-foreground">
            <div className="flex items-center space-x-4">
              <div className="flex items-center space-x-1">
                <Hash className="h-3 w-3" />
                <span>{session.messageCount || 0} messages</span>
              </div>
              <div className="flex items-center space-x-1">
                <Clock className="h-3 w-3" />
                <span>{formatRelativeTime(session.lastActivity)}</span>
              </div>
            </div>

            {session.createdAt && (
              <div className="flex items-center space-x-1">
                <Calendar className="h-3 w-3" />
                <span>Created {formatDate(session.createdAt)}</span>
              </div>
            )}
          </div>
        </div>

        <SessionActions
          session={session}
          onDeleteConversation={onDelete}
          onDeleteSession={() => handleDeleteSession(session.id)}
        />
      </div>
    </div>
    )
  }

  // Handle dialog close
  const handleDialogClose = React.useCallback(() => {
    setNewSessionOpen(false)
    setNewSessionId('')
  }, [])

  // Handle input change
  const handleInputChange = React.useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setNewSessionId(e.target.value)
  }, [])

  // Handle key down for Enter key
  const handleKeyDown = React.useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter' && !createSessionMutation.isPending) {
      e.preventDefault()
      const sessionId = newSessionId.trim() || undefined
      createSessionMutation.mutateAsync(sessionId).then((session) => {
        setNewSessionId('')
        setNewSessionOpen(false)
        onSessionChange(session.id)
      }).catch((err) => {
        console.error('Error creating session:', err)
        setError(err instanceof Error ? err.message : 'Failed to create session')
      })
    }
  }, [createSessionMutation, newSessionId, onSessionChange])

  // Delete confirmation dialog
  const DeleteConfirmationDialog = ({
    isOpen,
    onClose,
    onConfirm,
    sessionId,
    isDeleting
  }: {
    isOpen: boolean
    onClose: () => void
    onConfirm: () => void
    sessionId: string | null
    isDeleting: boolean
  }) => (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center space-x-2">
            <Trash2 className="h-5 w-5 text-destructive" />
            <span>Delete Conversation</span>
          </DialogTitle>
          <DialogDescription>
            This will permanently delete this conversation and all its messages. This action cannot be undone.
            {sessionId && (
              <span className="block mt-2 font-medium">
                Session: <span className="font-mono">{sessionId}</span>
              </span>
            )}
          </DialogDescription>
        </DialogHeader>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button 
            variant="destructive"
            onClick={onConfirm}
            disabled={isDeleting}
            className="flex items-center space-x-2"
          >
            <Trash2 className="h-4 w-4" />
            <span>{isDeleting ? 'Deleting...' : 'Delete Conversation'}</span>
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )

  // Main content
  const SessionContent = () => (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center justify-between mb-4 flex-shrink-0">
        <div className="flex items-center gap-2">
          <MessageSquare className="w-5 h-5" />
          <h2 className="font-semibold">Sessions ({sessions.length})</h2>
          {loading && <Loader2 className="w-4 h-4 animate-spin" />}
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => refetchSessions()}
            disabled={loading}
            title="Refresh sessions"
          >
            <RefreshCw className={cn("w-4 h-4", loading && "animate-spin")} />
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setNewSessionOpen(true)}
          >
            <Plus className="w-4 h-4 mr-1" />
            New Session
          </Button>
          <Button variant="ghost" size="sm" onClick={onClose}>
            <X className="w-4 h-4" />
          </Button>
        </div>
      </div>

      {/* Error display */}
      {error && (
        <div className="p-3 bg-red-50 border border-red-200 rounded-lg mb-4 flex-shrink-0">
          <div className="flex items-center gap-2 text-red-700">
            <AlertCircle className="w-4 h-4" />
            <span className="text-sm font-medium">Error</span>
          </div>
          <p className="text-sm text-red-600 mt-1">{error}</p>
        </div>
      )}

      {/* Sessions list - flex-1 to take remaining space */}
      <div className="flex-1 min-h-0">
        {loading ? (
          <div className="flex items-center justify-center py-8">
            <Loader2 className="w-6 h-6 animate-spin text-muted-foreground" />
            <span className="ml-2 text-sm text-muted-foreground">Loading sessions...</span>
          </div>
        ) : sessions.length === 0 ? (
          <div className="text-center py-8 text-muted-foreground">
            <MessageSquare className="w-12 h-12 mx-auto mb-3 opacity-50" />
            <p className="text-sm font-medium mb-1">No sessions found</p>
            <p className="text-xs">Create a new session to get started</p>
          </div>
        ) : (
          <ScrollArea className="h-full" ref={scrollAreaRef}>
            <div className="space-y-2 pr-4">
              {sessions.map((session) => (
                <SessionCard
                  key={session.id}
                  session={session}
                  isActive={currentSessionId === session.id}
                  onSelect={() => handleSessionSelect(session.id)}
                  onDelete={() => {
                    setSelectedSessionForAction(session.id)
                    setDeleteConversationDialogOpen(true)
                  }}
                />
              ))}
            </div>
          </ScrollArea>
        )}
      </div>

      {/* Dialogs */}
      <Dialog open={isNewSessionOpen} onOpenChange={(open) => !open && handleDialogClose()}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Create New Session</DialogTitle>
          </DialogHeader>

          <div className="space-y-4">
            <div className="space-y-2">
              <Label htmlFor="new-session-id">Session ID</Label>
              <Input
                id="new-session-id"
                value={newSessionId}
                onChange={handleInputChange}
                onKeyDown={handleKeyDown}
                placeholder="e.g., user-123, project-alpha"
                className="font-mono"
                autoComplete="off"
                autoFocus
              />
              <p className="text-xs text-muted-foreground">
                Leave empty to auto-generate a unique ID
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={handleDialogClose}>
              Cancel
            </Button>
            <Button 
              onClick={handleCreateSession}
              disabled={createSessionMutation.isPending}
            >
              {createSessionMutation.isPending ? 'Creating...' : 'Create Session'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      <DeleteConfirmationDialog
        isOpen={isDeleteConversationDialogOpen}
        onClose={() => {
          setDeleteConversationDialogOpen(false)
          setSelectedSessionForAction(null)
        }}
        onConfirm={handleDeleteConversation}
        sessionId={selectedSessionForAction}
        isDeleting={isDeletingConversation}
      />
    </div>
  )

  if (variant === 'modal') {
    return (
      <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
        <DialogContent className="max-w-2xl max-h-[80vh]">
          <SessionContent />
        </DialogContent>
      </Dialog>
    )
  }

  return (
    <div className={cn("h-full", className)}>
      <SessionContent />
    </div>
  )
}

// Hook for managing session panel state
export function useSessionPanel() {
  const [isOpen, setIsOpen] = React.useState(false)

  const openPanel = React.useCallback(() => {
    setIsOpen(true)
  }, [])

  const closePanel = React.useCallback(() => {
    setIsOpen(false)
  }, [])

  return {
    isOpen,
    openPanel,
    closePanel,
  }
}

