"use client"

import * as React from "react"
import { useEffect, useRef, useState, useCallback } from "react"
import * as d3 from "d3"

interface Task {
  id: string
  name: string
  status: 'pending' | 'in_progress' | 'completed'
  dependencies: string[]
}

interface WorkflowEvent {
  type: string
  data: any
  timestamp: string
}

interface WorkflowGraphProps {
  events: WorkflowEvent[]
  className?: string
}

interface Node extends d3.SimulationNodeDatum {
  id: string
  name: string
  status: 'pending' | 'in_progress' | 'completed'
  group: number
}

interface Link {
  source: string | Node
  target: string | Node
}

export function WorkflowGraph({ events, className }: WorkflowGraphProps) {
  const svgRef = useRef<SVGSVGElement>(null)
  const [tasks, setTasks] = useState<Task[]>([])
  const [dimensions, setDimensions] = useState({ width: 800, height: 600 })

  // Sync with Shrimp Task Manager API
  const syncWithShrimp = useCallback(async () => {
    try {
      const response = await fetch('http://localhost:62369/api/tasks')
      if (response.ok) {
        const data = await response.json()
        // Transform Shrimp API response to our Task format
        const shrimpTasks: Task[] = data.tasks?.map((task: any) => ({
          id: task.id || task.taskId,
          name: task.name || task.title || 'Unnamed Task',
          status: task.status || 'pending',
          dependencies: task.dependencies || []
        })) || []
        setTasks(shrimpTasks)
      }
    } catch (error) {
      console.error('Failed to sync with Shrimp API:', error)
      // Fallback to mock data for development
      setTasks([
        { id: '1', name: 'Setup Infrastructure', status: 'completed', dependencies: [] },
        { id: '2', name: 'WorkflowGraph Component', status: 'in_progress', dependencies: ['1'] },
        { id: '3', name: 'Backend API', status: 'pending', dependencies: ['1'] },
        { id: '4', name: 'Python Bridge', status: 'pending', dependencies: ['1'] },
        { id: '5', name: 'Integration', status: 'pending', dependencies: ['2', '3', '4'] }
      ])
    }
  }, [])

  // Update workflow from WebSocket events
  const updateWorkflowFromEvents = useCallback(() => {
    if (!events.length) return

    const latestEvents = events.slice(-10) // Process latest 10 events

    latestEvents.forEach(event => {
      if (event.type === 'task_update' || event.type === 'workflow_update') {
        setTasks(prevTasks => {
          const updatedTasks = [...prevTasks]
          const taskData = event.data

          if (taskData.taskId) {
            const taskIndex = updatedTasks.findIndex(t => t.id === taskData.taskId)
            if (taskIndex >= 0) {
              updatedTasks[taskIndex] = {
                ...updatedTasks[taskIndex],
                status: taskData.status || updatedTasks[taskIndex].status,
                name: taskData.name || updatedTasks[taskIndex].name
              }
            }
          }

          return updatedTasks
        })
      }
    })
  }, [events])

  // Handle window resize
  useEffect(() => {
    const handleResize = () => {
      if (svgRef.current) {
        const container = svgRef.current.parentElement
        if (container) {
          setDimensions({
            width: container.clientWidth,
            height: Math.max(400, container.clientHeight)
          })
        }
      }
    }

    handleResize()
    window.addEventListener('resize', handleResize)
    return () => window.removeEventListener('resize', handleResize)
  }, [])

  // Initial sync and setup polling
  useEffect(() => {
    syncWithShrimp()
    const interval = setInterval(syncWithShrimp, 5000) // Poll every 5 seconds
    return () => clearInterval(interval)
  }, [syncWithShrimp])

  // Update from events
  useEffect(() => {
    updateWorkflowFromEvents()
  }, [updateWorkflowFromEvents])

  // D3.js force simulation and rendering
  useEffect(() => {
    if (!tasks.length || !svgRef.current) return

    const svg = d3.select(svgRef.current)
    svg.selectAll("*").remove() // Clear previous render

    const { width, height } = dimensions

    // Prepare nodes and links
    const nodes: Node[] = tasks.map(task => ({
      id: task.id,
      name: task.name,
      status: task.status,
      group: task.status === 'completed' ? 2 : task.status === 'in_progress' ? 1 : 0
    }))

    const links: Link[] = []
    tasks.forEach(task => {
      task.dependencies.forEach(depId => {
        if (tasks.find(t => t.id === depId)) {
          links.push({ source: depId, target: task.id })
        }
      })
    })

    // Color scale for status
    const color = d3.scaleOrdinal<string>()
      .domain(['pending', 'in_progress', 'completed'])
      .range(['#6b7280', '#f59e0b', '#10b981']) // gray, orange, green

    // Create force simulation
    const simulation = d3.forceSimulation<Node>(nodes)
      .force("link", d3.forceLink<Node, Link>(links).id(d => d.id).distance(100))
      .force("charge", d3.forceManyBody().strength(-300))
      .force("center", d3.forceCenter(width / 2, height / 2))
      .force("collision", d3.forceCollide().radius(30))

    // Create container for zoom
    const container = svg.append("g")

    // Add zoom behavior
    const zoom = d3.zoom<SVGSVGElement, unknown>()
      .scaleExtent([0.1, 3])
      .on("zoom", (event) => {
        container.attr("transform", event.transform)
      })

    svg.call(zoom)

    // Create links
    const link = container.append("g")
      .selectAll("line")
      .data(links)
      .enter().append("line")
      .attr("stroke", "#999")
      .attr("stroke-opacity", 0.6)
      .attr("stroke-width", 2)

    // Create nodes
    const node = container.append("g")
      .selectAll("g")
      .data(nodes)
      .enter().append("g")
      .attr("class", "node")
      .style("cursor", "pointer")

    // Add circles for nodes
    node.append("circle")
      .attr("r", 20)
      .attr("fill", d => color(d.status))
      .attr("stroke", "#fff")
      .attr("stroke-width", 2)

    // Add text labels
    node.append("text")
      .text(d => d.name.length > 15 ? d.name.substring(0, 15) + '...' : d.name)
      .attr("text-anchor", "middle")
      .attr("dy", 30)
      .attr("font-size", "12px")
      .attr("fill", "#374151")
      .attr("font-weight", "500")

    // Add status indicators
    node.append("text")
      .text(d => d.status === 'completed' ? '✓' : d.status === 'in_progress' ? '⟳' : '○')
      .attr("text-anchor", "middle")
      .attr("dy", 5)
      .attr("font-size", "14px")
      .attr("fill", "#fff")

    // Add hover effects
    node.on("mouseover", function(event, d) {
      d3.select(this).select("circle")
        .transition()
        .duration(200)
        .attr("r", 25)
        .attr("stroke-width", 3)

      // Show tooltip
      const tooltip = container.append("g")
        .attr("class", "tooltip")
        .attr("transform", `translate(${d.x! + 30}, ${d.y! - 30})`)

      const rect = tooltip.append("rect")
        .attr("fill", "#1f2937")
        .attr("stroke", "#374151")
        .attr("rx", 4)
        .attr("ry", 4)
        .attr("opacity", 0.9)

      const text = tooltip.append("text")
        .attr("fill", "#fff")
        .attr("font-size", "12px")
        .attr("x", 8)
        .attr("y", 16)
        .text(`${d.name} (${d.status})`)

      const bbox = text.node()!.getBBox()
      rect.attr("width", bbox.width + 16)
        .attr("height", bbox.height + 8)
    })
    .on("mouseout", function(event, d) {
      d3.select(this).select("circle")
        .transition()
        .duration(200)
        .attr("r", 20)
        .attr("stroke-width", 2)

      container.select(".tooltip").remove()
    })

    // Add drag behavior
    const drag = d3.drag<SVGGElement, Node>()
      .on("start", (event, d) => {
        if (!event.active) simulation.alphaTarget(0.3).restart()
        d.fx = d.x
        d.fy = d.y
      })
      .on("drag", (event, d) => {
        d.fx = event.x
        d.fy = event.y
      })
      .on("end", (event, d) => {
        if (!event.active) simulation.alphaTarget(0)
        d.fx = null
        d.fy = null
      })

    node.call(drag)

    // Update positions on simulation tick
    simulation.on("tick", () => {
      link
        .attr("x1", (d: any) => d.source.x)
        .attr("y1", (d: any) => d.source.y)
        .attr("x2", (d: any) => d.target.x)
        .attr("y2", (d: any) => d.target.y)

      node
        .attr("transform", d => `translate(${d.x},${d.y})`)
    })

    // Cleanup
    return () => {
      simulation.stop()
    }

  }, [tasks, dimensions])

  return (
    <div className={`w-full h-full min-h-[400px] border border-gray-200 rounded-lg bg-white ${className || ''}`}>
      <div className="p-4 border-b border-gray-200">
        <h3 className="text-lg font-semibold text-gray-900">Workflow Graph</h3>
        <p className="text-sm text-gray-600 mt-1">
          Task dependencies and status visualization • {tasks.length} tasks
        </p>
      </div>
      <div className="relative w-full h-full">
        <svg
          ref={svgRef}
          width={dimensions.width}
          height={dimensions.height}
          className="w-full h-full"
        >
          {/* SVG content will be rendered by D3 */}
        </svg>

        {/* Legend */}
        <div className="absolute top-4 right-4 bg-white bg-opacity-90 backdrop-blur-sm border border-gray-200 rounded-lg p-3 shadow-sm">
          <div className="text-xs font-semibold text-gray-700 mb-2">Status</div>
          <div className="space-y-1">
            <div className="flex items-center space-x-2">
              <div className="w-3 h-3 rounded-full bg-gray-400"></div>
              <span className="text-xs text-gray-600">Pending</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-3 h-3 rounded-full bg-amber-500"></div>
              <span className="text-xs text-gray-600">In Progress</span>
            </div>
            <div className="flex items-center space-x-2">
              <div className="w-3 h-3 rounded-full bg-emerald-500"></div>
              <span className="text-xs text-gray-600">Completed</span>
            </div>
          </div>
        </div>

        {/* Pattern Reuse Metrics */}
        <div className="absolute bottom-4 left-4 bg-white bg-opacity-90 backdrop-blur-sm border border-gray-200 rounded-lg p-3 shadow-sm">
          <div className="text-xs font-semibold text-gray-700 mb-2">Metrics</div>
          <div className="space-y-1 text-xs text-gray-600">
            <div>Tasks: {tasks.length}</div>
            <div>Completed: {tasks.filter(t => t.status === 'completed').length}</div>
            <div>Active: {tasks.filter(t => t.status === 'in_progress').length}</div>
          </div>
        </div>
      </div>
    </div>
  )
}

"use client"

import React, { createContext, useContext, useState, useCallback, useEffect, useRef } from 'react';
import { useChat } from '@/hooks/use-chat';
import { 
  ChatContextType, 
  ChatProviderProps, 
  ChatMessage, 
  SessionMessage,
  ConnectionStatus 
} from '@/types/chat';
import {
  getWebSocketUrl,
  createAutoSession,
  loadSession,
  loadSessionHistory,
  convertHistoryToUIMessages,
  resetBackendSession
} from '@/lib/chat-config';
import { useSessionStore, sessionStoreActions } from '@/stores/session-store';
import { useSessionSwitch, useCreateSession, useSessionOperations } from '@/hooks/use-sessions';

// Create the context
const ChatContext = createContext<ChatContextType | null>(null);

export function ChatProvider({ 
  children, 
  wsUrl: customWsUrl,
  autoConnect = true 
}: ChatProviderProps) {
