  const wsUrl = getWebSocketUrl(customWsUrl);

  // Get session state from store
  const { 
    currentSessionId, 
    isWelcomeState, 
    enableOptimizations,
    getCachedSession 
  } = useSessionStore();

  // Local streaming state
  const [isStreaming, setIsStreaming] = useState(true);

  // Session operations hooks
  const { switchToSession, isSwitching } = useSessionSwitch();
  const createSessionMutation = useCreateSession();

  // Initialize session operations to handle cache refresh events
  useSessionOperations();

  // Chat hook integration
  const {
    messages,
    sendMessage: originalSendMessage,
    status,
    reset: originalReset,
    setMessages,
    websocket,
    clearMessages
  } = useChat(wsUrl, {
    autoConnect,
    onMessage: (message) => {
      // Emit custom event for message
      if (typeof window !== 'undefined') {
        window.dispatchEvent(
          new CustomEvent('cipher:newMessage', {
            detail: { message, sessionId: currentSessionId }
          })
        );
      }
    },
    onError: (error) => {
      console.error('Chat WebSocket error:', error);
      // Emit custom event for error
      if (typeof window !== 'undefined') {
        window.dispatchEvent(
          new CustomEvent('cipher:error', {
            detail: { error, sessionId: currentSessionId }
          })
        );
      }
    },
    onStatusChange: (status) => {
      console.log('Chat WebSocket status changed:', status);
      // Emit custom event for status change
      if (typeof window !== 'undefined') {
        window.dispatchEvent(
          new CustomEvent('cipher:statusChange', {
            detail: { status, sessionId: currentSessionId }
          })
        );
      }
    }
  });

  // Load session history with caching support
  const loadHistory = useCallback(async (sessionId: string) => {
    try {
      console.log('Loading history for session:', sessionId);

      // Check cache first if optimizations enabled
      if (enableOptimizations) {
        const cached = getCachedSession(sessionId);
        if (cached && cached.messages.length > 0) {
          console.log('Using cached messages:', cached.messages.length);
          setMessages(cached.messages);
          return;
        }
      }

      // Load from server
      const history = await loadSessionHistory(sessionId);
      console.log('History loaded:', history.length, 'messages');
      const uiMessages = convertHistoryToUIMessages(history, sessionId);
      console.log('UI messages converted:', uiMessages.length, 'messages');
      setMessages(uiMessages);
    } catch (error) {
      console.error('Error loading session history:', error);
      // On error, just clear messages and continue
      setMessages([]);
    }
  }, [setMessages, enableOptimizations, getCachedSession]);

  // Enhanced switch session using optimized hooks
  const switchSession = useCallback(async (sessionId: string) => {
    if (sessionId === currentSessionId || isSwitching) {
      return;
    }

    console.log('Switching to session:', sessionId);

    try {
      // Clear current messages immediately to prevent UI conflicts
      setMessages([]);

      // Use the optimized session switch hook (handles both switching and loading messages)
      await switchToSession(sessionId);

      // Get messages from the session cache after switching
      if (enableOptimizations) {
        const cachedSession = getCachedSession(sessionId);
        if (cachedSession?.messages) {
          console.log('Setting messages from cache:', cachedSession.messages.length);
          setMessages(cachedSession.messages);
        } else {
          console.log('No cached messages found, loading from server');
          await loadHistory(sessionId);
        }
      } else {
        // Fallback to loading history if optimizations disabled
        await loadHistory(sessionId);
      }

    } catch (error) {
      console.error('Error switching session:', error);
      throw error;
    }
  }, [currentSessionId, isSwitching, switchToSession, setMessages, loadHistory]);

  // Helper function to ensure "default" session exists
  const ensureDefaultSession = useCallback(async (): Promise<string> => {
    const { sessions } = useSessionStore.getState();

    // Check if "default" session already exists
    const defaultSession = sessions.find(s => s.id === 'default');

    if (defaultSession) {
      console.log('📋 Using existing default session');
      // Switch to default session if not already current
      if (currentSessionId !== 'default') {
        await switchSession('default');
      }
      return 'default';
    }

    // Create "default" session if it doesn't exist
    console.log('🆕 Creating new default session');
    try {
      const newSession = await new Promise<{ id: string }>((resolve, reject) => {
        createSessionMutation.mutate('default', {
          onSuccess: resolve,
          onError: reject,
        });
      });

      // Load the new session as the current working session
      await loadSession(newSession.id);
      return newSession.id;
    } catch (error) {
      console.error('Error creating default session:', error);
      throw error;
    }
  }, [currentSessionId, switchSession, createSessionMutation, loadSession]);

  // Enhanced send message with default session management
  const sendMessage = useCallback(async (
    content: string,
    imageData?: { base64: string; mimeType: string }
  ) => {
    let sessionId = currentSessionId;

    // Auto-create or switch to "default" session if needed
    if (!sessionId && isWelcomeState) {
      sessionId = await ensureDefaultSession();
      // Update UI state to reflect that we're no longer in welcome state
      sessionStoreActions.switchToSession(sessionId);
    }

    if (sessionId) {
      originalSendMessage(content, imageData, sessionId, isStreaming);
    } else {
      console.error('No session available for sending message');
      throw new Error('No session available for sending message');
    }
  }, [
    originalSendMessage, 
    currentSessionId, 
    isWelcomeState, 
    isStreaming,
    ensureDefaultSession
  ]);

  // Quick action send message - always uses "default" session
  const sendQuickActionMessage = useCallback(async (content: string) => {
    try {
      // Always ensure we're using the "default" session for quick actions
      const sessionId = await ensureDefaultSession();
      originalSendMessage(content, undefined, sessionId, isStreaming);
    } catch (error) {
      console.error('Error sending quick action message:', error);
      throw error;
    }
  }, [originalSendMessage, ensureDefaultSession, isStreaming]);

  // Return to welcome state
  const returnToWelcome = useCallback(() => {
    const previousSessionId = currentSessionId;

    sessionStoreActions.returnToWelcome();
    clearMessages();

    // Reset the backend to no default session
    resetBackendSession();

    // Emit custom event for returning to welcome
    if (typeof window !== 'undefined') {
      window.dispatchEvent(
        new CustomEvent('cipher:returnToWelcome', {
          detail: { previousSessionId }
        })
      );
    }
  }, [currentSessionId, clearMessages]);

  // Enhanced reset function
  const reset = useCallback(() => {
    if (currentSessionId) {
      originalReset(currentSessionId);

      // Emit custom event for conversation reset
      if (typeof window !== 'undefined') {
        window.dispatchEvent(
          new CustomEvent('cipher:conversationReset', {
            detail: { sessionId: currentSessionId }
          })
        );
      }
    }
  }, [originalReset, currentSessionId]);

  // Set streaming preference
  const setStreaming = useCallback((streaming: boolean) => {
    setIsStreaming(streaming);

    // Emit custom event for streaming preference change
    if (typeof window !== 'undefined') {
      window.dispatchEvent(
        new CustomEvent('cipher:streamingChanged', {
          detail: { streaming, sessionId: currentSessionId }
        })
      );
    }
  }, [currentSessionId]);

  // Event system integration
  useEffect(() => {
    const handleConfigChange = (event: CustomEvent) => {
      console.log('Config changed:', event.detail);
      // Trigger UI updates based on config changes
      // This could trigger a re-fetch of server configurations, etc.
    };

    const handleServersChange = (event: CustomEvent) => {
      console.log('Servers changed:', event.detail);
      // Trigger UI updates based on server changes
      // This could trigger a re-connect or server list refresh
    };

    const handleSessionReset = (event: CustomEvent) => {
      const { sessionId } = event.detail || {};
      if (sessionId === currentSessionId) {
        setMessages([]);
      }
    };

    const handleExternalSessionSwitch = (event: CustomEvent) => {
      const { sessionId } = event.detail || {};
      if (sessionId && sessionId !== currentSessionId) {
        switchSession(sessionId).catch(error => {
          console.error('Error handling external session switch:', error);
        });
      }
    };

    const handleWelcomeRequest = (event: CustomEvent) => {
      returnToWelcome();
    };

    const handleSessionChanged = (event: CustomEvent) => {
      const { sessionId, cached } = event.detail || {};
      console.log('Session changed event:', sessionId, 'cached:', cached);

      // Load messages for the new session (both cached and non-cached scenarios)
      if (sessionId) {
        loadHistory(sessionId).catch(error => {
          console.error('Error loading session history:', error);
        });
      }
    };

    if (typeof window !== 'undefined') {
      // Listen for configuration and server changes
      window.addEventListener('cipher:configChanged', handleConfigChange as EventListener);
      window.addEventListener('cipher:serversChanged', handleServersChange as EventListener);

      // Listen for session-related events from other components
      window.addEventListener('cipher:conversationReset', handleSessionReset as EventListener);
      window.addEventListener('cipher:switchSession', handleExternalSessionSwitch as EventListener);
      window.addEventListener('cipher:requestWelcome', handleWelcomeRequest as EventListener);
      window.addEventListener('cipher:sessionChanged', handleSessionChanged as EventListener);

      return () => {
        window.removeEventListener('cipher:configChanged', handleConfigChange as EventListener);
        window.removeEventListener('cipher:serversChanged', handleServersChange as EventListener);
        window.removeEventListener('cipher:conversationReset', handleSessionReset as EventListener);
        window.removeEventListener('cipher:switchSession', handleExternalSessionSwitch as EventListener);
        window.removeEventListener('cipher:requestWelcome', handleWelcomeRequest as EventListener);
        window.removeEventListener('cipher:sessionChanged', handleSessionChanged as EventListener);
      };
    }
  }, [currentSessionId, setMessages, switchSession, returnToWelcome, loadHistory]);

  // Load current session history on mount and session change
  useEffect(() => {
    if (currentSessionId && !isWelcomeState) {
      console.log('Loading history for current session:', currentSessionId);
      loadHistory(currentSessionId).catch(error => {
        console.error('Error loading current session history:', error);
      });
    }
  }, [currentSessionId, isWelcomeState, loadHistory]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      // Clear any pending operations
      setMessages([]);

      console.log('ChatContext: Cleanup completed on unmount');
    };
  }, [setMessages]);

  // Create session creation function for external use
  const createNewSession = useCallback(async (): Promise<string> => {
    try {
      const sessionId = await createAutoSession();
      await loadSession(sessionId);
      return sessionId;
    } catch (error) {
      console.error('Error creating new session:', error);
      throw error;
    }
  }, []);

  // Context value
  const contextValue: ChatContextType = {
    messages,
    sendMessage,
    sendQuickActionMessage,
    status,
    reset,
    currentSessionId,
    switchSession,
    loadSessionHistory: loadHistory,
    isWelcomeState,
    returnToWelcome,
    isStreaming,
    setStreaming,
    websocket,
  };

  return (
    <ChatContext.Provider value={contextValue}>
      {children}
    </ChatContext.Provider>
  );
}

// Custom hook to use the chat context
export function useChatContext(): ChatContextType {
  const context = useContext(ChatContext);
  if (!context) {
    throw new Error('useChatContext must be used within a ChatProvider');
  }
  return context;
}

// Additional utility hooks
export function useChatSession() {
  const { currentSessionId, switchSession, returnToWelcome, isWelcomeState } = useChatContext();

  return {
    currentSessionId,
    switchSession,
    returnToWelcome,
    isWelcomeState,
    hasActiveSession: !isWelcomeState && currentSessionId !== null,
  };
}

export function useChatMessages() {
  const { messages, sendMessage, reset } = useChatContext();

  return {
    messages,
    sendMessage,
    reset,
    messageCount: messages.length,
    hasMessages: messages.length > 0,
  };
}

export function useChatStatus() {
  const { status, websocket, isStreaming, setStreaming } = useChatContext();

  return {
    status,
    websocket,
    isStreaming,
    setStreaming,
    isConnected: status === 'open',
    isConnecting: status === 'connecting',
    isDisconnected: status === 'closed',
  };
}

export {
	ChatProvider,
	useChatContext,
	useChatSession,
	useChatMessages,
	useChatStatus,
} from './chat-context';

export { useServerRegistry } from './use-server-registry';
export { useChat } from './use-chat';
export { useWorkflowEvents } from './use-workflow-events';
export * from './use-sessions';

'use client';

import { useState, useRef, useCallback, useEffect } from 'react';
import {
	ChatMessage,
	ConnectionStatus,
	UseChatOptions,
	OutgoingMessage,
	IncomingMessage,
	TextPart,
	ImagePart,
} from '@/types/chat';
import { generateUniqueId, extractImageFromToolResult, dispatchChatEvent } from '@/lib/chat-utils';

export function useChat(wsUrl: string, options: UseChatOptions = {}) {
	const { autoConnect = true, onMessage, onError, onStatusChange } = options;

	// State management
	const wsRef = useRef<WebSocket | null>(null);
	const [messages, setMessages] = useState<ChatMessage[]>([]);
	const [status, setStatus] = useState<ConnectionStatus>('connecting');
	const lastImageUriRef = useRef<string | null>(null);
	const isMountedRef = useRef(true);

	// Status change handler
	const handleStatusChange = useCallback(
		(newStatus: ConnectionStatus) => {
			setStatus(newStatus);
			onStatusChange?.(newStatus);
		},
		[onStatusChange]
	);

	// WebSocket message handler
	const handleWebSocketMessage = useCallback((event: { data: string }) => {
		let msg: IncomingMessage;
		try {
			msg = JSON.parse(event.data);
		} catch (err) {
			console.error('WebSocket message parse error:', event.data, err);
			return;
		}

		const payload = msg.data || {};

		switch (msg.event) {
			case 'thinking':
				handleThinkingEvent();
				break;
			case 'chunk':
				handleChunkEvent(payload);
				break;
			case 'response':
				handleResponseEvent(payload);
				break;
			case 'conversationReset':
				handleConversationReset();
				break;

			case 'toolExecutionStarted':
				handleToolExecutionStarted(payload);
				break;
			case 'toolExecutionProgress':
				handleToolExecutionProgress(payload);
				break;
			case 'toolResult':
				handleToolResultEvent(payload);
				break;
			case 'toolExecutionCompleted':
				handleToolExecutionCompleted(payload);
				break;
			case 'toolExecutionFailed':
				handleToolExecutionFailed(payload);
				break;
			case 'error':
				handleErrorEvent(payload);
				break;
			case 'connected':
				// WebSocket connection confirmed by backend
				console.log('WebSocket connection confirmed by backend');
				break;
			case 'connectionUpdated':
				// Connection update from backend (e.g., session binding)
				console.log('WebSocket connection updated:', payload);
				break;
			default:
				console.warn('Unknown WebSocket event:', msg.event);
				break;
		}
	}, []);

	// Event handlers
	const handleThinkingEvent = useCallback(() => {
		if (!isMountedRef.current) return;

		setMessages(ms => {
			// Check if there's already a thinking message - if so, don't add another
			const hasThinking = ms.some(
				m => m.role === 'system' && m.content === 'Cipher is thinking...'
			);
			if (hasThinking) {
				return ms; // Don't add duplicate thinking message
			}

			const thinkingMessage: ChatMessage = {
				id: generateUniqueId(),
				role: 'system',
				content: 'Cipher is thinking...',
				createdAt: Date.now(),
			};

			return [...ms, thinkingMessage];
		});
	}, []);

	// Track processed message content and streaming state
	const processedChunks = useRef<Set<string>>(new Set());
	const currentStreamingMessage = useRef<string | null>(null);

	const handleChunkEvent = useCallback((payload: IncomingMessage['data']) => {
		if (!isMountedRef.current) return;

		const text = typeof payload.text === 'string' ? payload.text : '';
		const messageId = payload.messageId || '';

		// Skip empty chunks
		if (!text) return;

		// Create unique chunk identifier using message ID and actual content
		const chunkKey = `${messageId}-${text}`;

		// Skip if we've already processed this exact chunk content
		if (processedChunks.current.has(chunkKey)) {
			console.warn('Skipping duplicate chunk:', text.slice(0, 50) + '...');
			return;
		}

		processedChunks.current.add(chunkKey);

		setMessages(ms => {
			// Remove any existing 'thinking' system messages
			const cleaned = ms.filter(
				m => !(m.role === 'system' && m.content === 'Cipher is thinking...')
			);

			const last = cleaned[cleaned.length - 1];

			// If we have an existing assistant message, append to it
			if (last && last.role === 'assistant' && typeof last.content === 'string') {
				// Track the streaming message to detect context switches
				if (currentStreamingMessage.current === null) {
					currentStreamingMessage.current = last.id;
				}

				// If this is a different message stream, create new message
				if (messageId && last.id !== messageId) {
					currentStreamingMessage.current = messageId;
					const newMessage: ChatMessage = {
						id: messageId || generateUniqueId(),
						role: 'assistant',
						content: text,
						createdAt: Date.now(),
					};
					return [...cleaned, newMessage];
				}

				// Append to existing message
				const newContent = last.content + text;
				const updated: ChatMessage = {
					...last,
					content: newContent,
					createdAt: Date.now(),
				};
				return [...cleaned.slice(0, -1), updated];
			}

			// Create new assistant message
			const newMessageId = messageId || generateUniqueId();
			currentStreamingMessage.current = newMessageId;

			const newMessage: ChatMessage = {
				id: newMessageId,
				role: 'assistant',
				content: text,
				createdAt: Date.now(),
			};

			return [...cleaned, newMessage];
		});
	}, []);

	const handleResponseEvent = useCallback(
		(payload: IncomingMessage['data']) => {
			if (!isMountedRef.current) return;

			// Handle both 'content' and 'text' fields for backward compatibility
			const text =
				typeof payload.text === 'string'
					? payload.text
					: typeof payload.content === 'string'
						? payload.content
						: '';
			const tokenCount = typeof payload.tokenCount === 'number' ? payload.tokenCount : undefined;
			const model = typeof payload.model === 'string' ? payload.model : undefined;
			const sessionId = typeof payload.sessionId === 'string' ? payload.sessionId : undefined;

			setMessages(ms => {
				// Remove 'thinking' placeholders
				const cleaned = ms.filter(
					m => !(m.role === 'system' && m.content === 'Cipher is thinking...')
				);

				// Embed image part in content if available
				let content: string | Array<TextPart | ImagePart> = text;
				if (lastImageUriRef.current) {
					const uri = lastImageUriRef.current;
					const [, base64] = uri.split(',');
					const mimeMatch = uri.match(/data:(.*);base64/);
					const mimeType = mimeMatch ? mimeMatch[1] : 'image/png';
					const imagePart: ImagePart = { type: 'image', base64, mimeType };
					content = text.trim() ? [{ type: 'text', text }, imagePart] : [imagePart];
				}

				// Prepare new AI message
				const newMsg: ChatMessage = {
					id: generateUniqueId(),
					role: 'assistant',
					content,
					createdAt: Date.now(),
					tokenCount,
					model,
					sessionId,
				};

				// Check if this response is updating an existing message
				const lastMsg = cleaned[cleaned.length - 1];
				if (lastMsg && lastMsg.role === 'assistant') {
					// If the existing message has content (from streaming), just update metadata
					if (lastMsg.content && typeof lastMsg.content === 'string' && lastMsg.content.trim()) {
						const updatedMsg: ChatMessage = {
							...lastMsg,
							tokenCount,
							model,
							sessionId,
							createdAt: Date.now(), // Update timestamp for completion
						};
						return [...cleaned.slice(0, -1), updatedMsg];
					}
					// If no content yet, replace with new message
					return [...cleaned.slice(0, -1), newMsg];
				}
				return [...cleaned, newMsg];
			});

			// Emit DOM event for other components
			dispatchChatEvent('cipher:response', {
				text,
				sessionId,
				tokenCount,
				model,
				timestamp: Date.now(),
			});

			// Clear the last image for the next message
			lastImageUriRef.current = null;

			// Reset streaming state when response is complete
			currentStreamingMessage.current = null;

			// Emit event to trigger cache update for session history
			if (sessionId) {
				dispatchChatEvent('cipher:responseComplete', {
					sessionId,
					timestamp: Date.now(),
				});
			}

			// Call onMessage callback if provided
			if (onMessage) {
				const message: ChatMessage = {
					id: generateUniqueId(),
					role: 'assistant',
					content: text,
					createdAt: Date.now(),
					tokenCount,
					model,
					sessionId,
				};
				onMessage(message);
			}
		},
		[onMessage]
	);

	const handleToolResultEvent = useCallback((payload: IncomingMessage['data']) => {
		if (!isMountedRef.current) return;

		const name = payload.toolName;
		const result = payload.result;

		// Skip if result is the generic completion message
		if (result === 'Tool execution completed') {
			return;
		}

		// Extract image URI from tool result
		const uri = result ? extractImageFromToolResult(result) : null;
		lastImageUriRef.current = uri;

		// Add a formatted tool result message similar to terminal output
		const resultMessage: ChatMessage = {
			id: generateUniqueId(),
			role: 'system',
			content: `📋 Tool Result:\n${typeof result === 'string' ? result : JSON.stringify(result, null, 2)}`,
			createdAt: Date.now(),
			toolExecutionId: payload.callId || payload.executionId,
		};

		// Merge toolResult into the existing toolCall message AND add result message
		setMessages(ms => {
			const idx = ms.findIndex(
				m => m.role === 'tool' && m.toolName === name && m.toolResult === undefined
			);
			if (idx !== -1) {
				const updatedMsg: ChatMessage = { ...ms[idx], toolResult: result };
				return [...ms.slice(0, idx), updatedMsg, ...ms.slice(idx + 1), resultMessage];
			}
			console.warn(`No matching tool call found for result of ${name}`);
			return [...ms, resultMessage];
		});
	}, []);

	const handleToolExecutionStarted = useCallback((payload: IncomingMessage['data']) => {
		if (!isMountedRef.current) return;

		const name = payload.toolName;
		const callId = payload.callId || payload.executionId;

		// Add a tool message to show tool execution started
		const startMessage: ChatMessage = {
			id: generateUniqueId(),
			role: 'tool',
			content: `🔧 Using tool: ${name}`,
			toolName: name,
			toolArgs: payload.args || {},
			createdAt: Date.now(),
			toolExecutionId: callId,
		};
		setMessages(ms => [...ms, startMessage]);
	}, []);

	const handleToolExecutionProgress = useCallback((payload: IncomingMessage['data']) => {
		if (!isMountedRef.current) return;

		const progress = payload.progress || payload.message;
		const callId = payload.callId || payload.executionId;

		if (progress) {
			// Update or add progress message
			setMessages(ms => {
				const progressMessageId = `progress-${callId}`;
				const existingIdx = ms.findIndex(m => m.id === progressMessageId);

				const progressMessage: ChatMessage = {
					id: progressMessageId,
					role: 'system',
					content: `⏳ ${progress}`,
					createdAt: Date.now(),
					toolExecutionId: callId,
				};

				if (existingIdx !== -1) {
					// Update existing progress message
					return [...ms.slice(0, existingIdx), progressMessage, ...ms.slice(existingIdx + 1)];
				} else {
					// Add new progress message
					return [...ms, progressMessage];
				}
			});
		}
	}, []);

	const handleToolExecutionCompleted = useCallback((payload: IncomingMessage['data']) => {
		if (!isMountedRef.current) return;

		const result = payload.result || 'Tool execution completed';
		const callId = payload.callId || payload.executionId;

		setMessages(ms => {
			// Remove any progress messages for this execution
			const withoutProgress = ms.filter(m => !m.id?.startsWith(`progress-${callId}`));

			// Update the existing tool message with the result
			const updatedMessages = withoutProgress.map(msg => {
				if (msg.toolExecutionId === callId && msg.role === 'tool') {
					return {
						...msg,
						toolResult: result,
					};
				}
				return msg;
			});

			return updatedMessages;
		});
	}, []);

	const handleToolExecutionFailed = useCallback((payload: IncomingMessage['data']) => {
		if (!isMountedRef.current) return;

		const name = payload.toolName;
		const error = payload.error || 'Unknown error';
		const callId = payload.callId || payload.executionId;

		setMessages(ms => {
			// Remove any progress messages for this execution
			const withoutProgress = ms.filter(m => !m.id?.startsWith(`progress-${callId}`));

			// Add error message
			const errorMessage: ChatMessage = {
				id: generateUniqueId(),
				role: 'system',
				content: `❌ Tool ${name} failed: ${error}`,
				createdAt: Date.now(),
				toolExecutionId: callId,
			};

			return [...withoutProgress, errorMessage];
		});
	}, []);

	const handleConversationReset = useCallback(() => {
		if (!isMountedRef.current) return;
		setMessages([]);
		// Clear processed chunks and streaming state for new conversation
		processedChunks.current.clear();
		currentStreamingMessage.current = null;
	}, []);

	const handleErrorEvent = useCallback(
		(payload: IncomingMessage['data']) => {
			if (!isMountedRef.current) return;

			const rawMsg = payload.message ?? 'Unknown error';
			const errMsg = typeof rawMsg === 'string' ? rawMsg : JSON.stringify(rawMsg, null, 2);

			const errorMessage: ChatMessage = {
				id: generateUniqueId(),
				role: 'system',
				content: errMsg,
				createdAt: Date.now(),
			};

			setMessages(ms => [...ms, errorMessage]);
			onError?.(errMsg);
		},
		[onError]
	);

	// WebSocket connection management
	const connect = useCallback(() => {
		if (
			wsRef.current?.readyState === WebSocket.OPEN ||
			wsRef.current?.readyState === WebSocket.CONNECTING
		) {
			return; // Already connected or connecting
		}

		// Close any existing connection first
		if (wsRef.current) {
			wsRef.current.close();
			wsRef.current = null;
		}

		try {
			console.log('Creating WebSocket connection to:', wsUrl);
			const ws = new WebSocket(wsUrl);
			wsRef.current = ws;

			ws.onopen = () => {
				console.log('WebSocket connected successfully');
				handleStatusChange('open');
			};

			ws.onclose = event => {
				console.log('WebSocket disconnected', event.code, event.reason);
				handleStatusChange('closed');

				// Only attempt to reconnect if not intentionally closed and still mounted
				if (event.code !== 1000 && isMountedRef.current && autoConnect) {
					// Add a delay before reconnecting to prevent rapid reconnection loops
					setTimeout(() => {
						if (isMountedRef.current && wsRef.current?.readyState !== WebSocket.OPEN) {
							console.log('Attempting to reconnect...');
							connect();
						}
					}, 3000);
				}
			};

			ws.onerror = error => {
				console.error('WebSocket error:', error);
				onError?.('WebSocket connection error');
			};

			ws.onmessage = handleWebSocketMessage;

			handleStatusChange('connecting');
		} catch (error) {
			console.error('Failed to create WebSocket connection:', error);
			handleStatusChange('closed');
			onError?.('Failed to establish WebSocket connection');
		}
	}, [wsUrl, autoConnect, handleStatusChange, handleWebSocketMessage, onError]);

	const disconnect = useCallback(() => {
		if (wsRef.current) {
			wsRef.current.close(1000, 'Intentional disconnect');
			wsRef.current = null;
		}
	}, []);

	// Send message functionality
	const sendMessage = useCallback(
		(
			content: string,
			imageData?: { base64: string; mimeType: string },
			sessionId?: string,
			stream = true
		) => {
			if (wsRef.current?.readyState === WebSocket.OPEN) {
				const message: OutgoingMessage = {
					type: 'message',
					content,
					imageData,
					sessionId,
					stream,
				};

				try {
					wsRef.current.send(JSON.stringify(message));

					// Add user message to local state immediately (optimistic update)
					const userMessage: ChatMessage = {
						id: generateUniqueId(),
						role: 'user',
						content,
						createdAt: Date.now(),
						sessionId,
						imageData,
					};

					setMessages(ms => [...ms, userMessage]);

					// Emit DOM event for other components
					dispatchChatEvent('cipher:message', {
						content,
						sessionId,
						timestamp: Date.now(),
					});

					// Also emit newMessage event for cache updates
					dispatchChatEvent('cipher:newMessage', {
						sessionId,
						timestamp: Date.now(),
					});

					onMessage?.(userMessage);
				} catch (error) {
					console.error('Failed to send message:', error);
					onError?.('Failed to send message');
				}
			} else {
				console.warn('WebSocket is not connected. Cannot send message.');
				onError?.('Not connected to chat service');
			}
		},
		[onMessage, onError]
	);

	// Reset conversation functionality
	const reset = useCallback(
		(sessionId?: string) => {
			if (wsRef.current?.readyState === WebSocket.OPEN) {
				const resetMessage: OutgoingMessage = {
					type: 'reset',
					sessionId,
				};

				try {
					wsRef.current.send(JSON.stringify(resetMessage));
				} catch (error) {
					console.error('Failed to send reset message:', error);
					onError?.('Failed to reset conversation');
				}
			}

			// Clear local messages regardless of WebSocket state
			setMessages([]);
		},
		[onError]
	);

	// Clear messages locally
	const clearMessages = useCallback(() => {
		setMessages([]);
		// Clear processed chunks and streaming state
		processedChunks.current.clear();
		currentStreamingMessage.current = null;
	}, []);

	// Auto-connect effect
	useEffect(() => {
		if (autoConnect) {
			connect();
		}

		return () => {
			isMountedRef.current = false;
			if (wsRef.current) {
				wsRef.current.close(1000, 'Component unmounting');
				wsRef.current = null;
			}
		};
	}, [autoConnect]); // Only depend on autoConnect to prevent connection loops

	// Cleanup effect
	useEffect(() => {
		return () => {
			isMountedRef.current = false;
			if (wsRef.current) {
				wsRef.current.close();
			}
		};
	}, []);

	return {
		// State
		messages,
		status,
		isConnected: status === 'open',
		isConnecting: status === 'connecting',

		// Actions
		sendMessage,
		reset,
		clearMessages,
		connect,
		disconnect,

		// Utilities
		setMessages,
		websocket: wsRef.current,
	};
}

'use client';

import { useState, useRef, useCallback, useEffect } from 'react';
import {
	ServerRegistryEntry,
	ServerRegistryFilter,
	UseServerRegistryOptions,
} from '@/types/server-registry';
import { serverRegistry } from '@/lib/server-registry-service';

export function useServerRegistry(options: UseServerRegistryOptions = {}) {
	const { autoLoad = true, initialFilter } = options;

	// State management
	const [entries, setEntries] = useState<ServerRegistryEntry[]>([]);
	const [isLoading, setIsLoading] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [filter, setFilter] = useState<ServerRegistryFilter>(initialFilter || {});

	// Refs for cleanup and cancellation
	const isMountedRef = useRef(true);
	const abortControllerRef = useRef<AbortController | null>(null);

	// Main data loading function with request cancellation
	const loadEntries = useCallback(
		async (newFilter?: ServerRegistryFilter) => {
			// Cancel any ongoing request
			if (abortControllerRef.current) {
				abortControllerRef.current.abort();
			}

			// Create new AbortController for this request
			const abortController = new AbortController();
			abortControllerRef.current = abortController;

			// Only update state if component is still mounted
			if (!isMountedRef.current) return;

			setIsLoading(true);
			setError(null);

			try {
				const filterToUse = newFilter || filter;
				const registryEntries = await serverRegistry.getEntries(filterToUse);

				// Check if component is still mounted and request wasn't aborted
				if (isMountedRef.current && !abortController.signal.aborted) {
					setEntries(registryEntries);
				}
			} catch (err: unknown) {
				// Only set error if component is still mounted and request wasn't aborted
				if (isMountedRef.current && !abortController.signal.aborted) {
					const errorMessage =
						err instanceof Error ? err.message : 'Failed to load server registry';
					setError(errorMessage);
				}
			} finally {
				// Only update loading state if component is still mounted and request wasn't aborted
				if (isMountedRef.current && !abortController.signal.aborted) {
					setIsLoading(false);
				}
			}
		},
		[filter]
	);

	// Filter management
	const updateFilter = useCallback((newFilter: ServerRegistryFilter) => {
		if (isMountedRef.current) {
			setFilter(newFilter);
		}
	}, []);

	// Installation status management with optimistic updates
	const markAsInstalled = useCallback(async (entryId: string) => {
		if (!isMountedRef.current) return;

		// Optimistic update
		setEntries(prev =>
			prev.map(entry => (entry.id === entryId ? { ...entry, isInstalled: true } : entry))
		);

		try {
			await serverRegistry.setInstalled(entryId, true);
		} catch (err: unknown) {
			// Rollback optimistic update on error
			if (isMountedRef.current) {
				setEntries(prev =>
					prev.map(entry => (entry.id === entryId ? { ...entry, isInstalled: false } : entry))
				);
				const errorMessage =
					err instanceof Error ? err.message : 'Failed to mark server as installed';
				setError(errorMessage);
			}
		}
	}, []);

	// Mark as uninstalled
	const markAsUninstalled = useCallback(async (entryId: string) => {
		if (!isMountedRef.current) return;

		// Optimistic update
		setEntries(prev =>
			prev.map(entry => (entry.id === entryId ? { ...entry, isInstalled: false } : entry))
		);

		try {
			await serverRegistry.setInstalled(entryId, false);
		} catch (err: unknown) {
			// Rollback optimistic update on error
			if (isMountedRef.current) {
				setEntries(prev =>
					prev.map(entry => (entry.id === entryId ? { ...entry, isInstalled: true } : entry))
				);
				const errorMessage =
					err instanceof Error ? err.message : 'Failed to mark server as uninstalled';
				setError(errorMessage);
			}
		}
	}, []);

	// Custom entry addition
	const addCustomEntry = useCallback(
		async (entry: Omit<ServerRegistryEntry, 'id' | 'isOfficial' | 'lastUpdated'>) => {
			if (!isMountedRef.current) return;

			try {
				const newEntry = await serverRegistry.addCustomEntry(entry);
				if (isMountedRef.current) {
					setEntries(prev => [newEntry, ...prev]);
				}
				return newEntry;
			} catch (err: unknown) {
				if (isMountedRef.current) {
					const errorMessage = err instanceof Error ? err.message : 'Failed to add custom server';
					setError(errorMessage);
				}
				throw err;
			}
		},
		[]
	);

	// Remove entry (for custom entries)
	const removeEntry = useCallback(async (entryId: string) => {
		if (!isMountedRef.current) return;

		try {
			await serverRegistry.removeEntry(entryId);

			if (isMountedRef.current) {
				setEntries(prev => prev.filter(entry => entry.id !== entryId));
			}
		} catch (err: unknown) {
			if (isMountedRef.current) {
				const errorMessage = err instanceof Error ? err.message : 'Failed to remove server entry';
				setError(errorMessage);
			}
			throw err;
		}
	}, []);

	// Error management
	const clearError = useCallback(() => {
		if (isMountedRef.current) {
			setError(null);
		}
	}, []);

	// Refresh entries
	const refreshEntries = useCallback(() => {
		if (isMountedRef.current) {
			loadEntries();
		}
	}, [loadEntries]);

	// Find entry by ID
	const findEntry = useCallback(
		(entryId: string): ServerRegistryEntry | undefined => {
			return entries.find(entry => entry.id === entryId);
		},
		[entries]
	);

	// Get filtered entries (client-side filtering for additional performance)
	const getFilteredEntries = useCallback(
		(clientFilter?: Partial<ServerRegistryFilter>): ServerRegistryEntry[] => {
			if (!clientFilter) return entries;

			return entries.filter(entry => {
				if (clientFilter.installed !== undefined && entry.isInstalled !== clientFilter.installed)
					return false;
				if (clientFilter.official !== undefined && entry.isOfficial !== clientFilter.official)
					return false;
				if (clientFilter.category && entry.category !== clientFilter.category) return false;
				if (clientFilter.search) {
					const searchLower = clientFilter.search.toLowerCase();
					const matchesSearch =
						entry.name.toLowerCase().includes(searchLower) ||
						entry.description.toLowerCase().includes(searchLower) ||
						entry.tags?.some(tag => tag.toLowerCase().includes(searchLower));
					if (!matchesSearch) return false;
				}
				if (clientFilter.tags && clientFilter.tags.length > 0) {
					const hasMatchingTag = clientFilter.tags.some(tag => entry.tags?.includes(tag));
					if (!hasMatchingTag) return false;
				}
				return true;
			});
		},
		[entries]
	);

	// Auto-reload when filter changes
	useEffect(() => {
		if (isMountedRef.current) {
			loadEntries();
		}
	}, [filter, loadEntries]);

	// Auto-loading effect
	useEffect(() => {
		if (autoLoad && isMountedRef.current) {
			loadEntries();
		}
	}, [autoLoad, loadEntries]);

	// Listen for server uninstall events from other components
	useEffect(() => {
		const handleServerUninstalled = (event: any) => {
			const { serverId } = event.detail;
			if (isMountedRef.current) {
				console.log(`📨 Received server uninstalled event for: ${serverId}`);
				// Find the server by name (serverId is actually the server name in this context)
				const entry = entries.find(e => e.name === serverId || e.id === serverId);
				if (entry) {
					markAsUninstalled(entry.id);
				}
			}
		};

		window.addEventListener('mcp-server-uninstalled', handleServerUninstalled);

		return () => {
			window.removeEventListener('mcp-server-uninstalled', handleServerUninstalled);
		};
	}, [entries, markAsUninstalled]);

	// Cleanup effect - prevent memory leaks
	useEffect(() => {
		return () => {
			isMountedRef.current = false;
			if (abortControllerRef.current) {
				abortControllerRef.current.abort();
			}
		};
	}, []);

	// Derived state
	const installedEntries = entries.filter(entry => entry.isInstalled);
	const officialEntries = entries.filter(entry => entry.isOfficial);
	const customEntries = entries.filter(entry => !entry.isOfficial);
	const categories = Array.from(new Set(entries.map(entry => entry.category)));
	const allTags = Array.from(new Set(entries.flatMap(entry => entry.tags || [])));

	return {
		// State
		entries,
		isLoading,
		error,
		filter,

		// Derived state
		installedEntries,
		officialEntries,
		customEntries,
		categories,
		allTags,

		// Actions
		loadEntries,
		updateFilter,
		markAsInstalled,
		markAsUninstalled,
		addCustomEntry,
		removeEntry,
		clearError,
		refreshEntries,

		// Utilities
		findEntry,
		getFilteredEntries,
	};
}

'use client';

import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useCallback, useEffect } from 'react';
import { Session } from '@/types/server-registry';
import { ChatMessage, SessionMessage } from '@/types/chat';
import { useSessionStore, sessionStoreActions } from '@/stores/session-store';
import { convertHistoryToUIMessages, loadSession, loadSessionHistory } from '@/lib/chat-config';

// Browser event types
declare global {
	interface WindowEventMap {
		'cipher:newMessage': CustomEvent;
		'cipher:response': CustomEvent;
		'cipher:responseComplete': CustomEvent;
	}
}

// Simplified session sync (React Query handles most synchronization automatically)
export function useSessionsSync() {
	const queryClient = useQueryClient();

	const syncSessions = useCallback(() => {
		queryClient.invalidateQueries({ queryKey: sessionQueryKeys.lists() });
	}, [queryClient]);

	return { syncSessions };
}

// Query keys
export const sessionQueryKeys = {
	all: ['sessions'] as const,
	lists: () => [...sessionQueryKeys.all, 'list'] as const,
	list: (filters?: any) => [...sessionQueryKeys.lists(), filters] as const,
	details: () => [...sessionQueryKeys.all, 'detail'] as const,
	detail: (id: string) => [...sessionQueryKeys.details(), id] as const,
	history: (id: string) => [...sessionQueryKeys.detail(id), 'history'] as const,
};

// API functions
async function fetchSessions(): Promise<Session[]> {
	const response = await fetch('/api/sessions');
	if (!response.ok) {
		const errorData = await response.json().catch(() => ({}));
		throw new Error(errorData.error?.message || errorData.message || 'Failed to fetch sessions');
	}

	const data = await response.json();
	const sessions = data.data?.sessions || data.sessions || [];

	// CRITICAL FIX: Filter out sessions with 0 messages and enhance with message counts
	const sessionsWithCounts = await Promise.all(
		sessions.map(async (session: Session) => {
			try {
				const historyResponse = await fetch(`/api/sessions/${session.id}/history`);
				if (historyResponse.ok) {
					const historyData = await historyResponse.json();
					const history = historyData.data?.history || historyData.history || [];
					// Filter to only include user and assistant messages (excluding tool calls)
					const filteredHistory = history.filter((msg: any) => {
						// Include user messages
						if (msg.role === 'user') return true;
						// Include assistant messages that don't have tool calls
						if (msg.role === 'assistant' && (!msg.toolCalls || msg.toolCalls.length === 0))
							return true;
						// Exclude everything else
						return false;
					});
					return { ...session, messageCount: filteredHistory.length };
				}
			} catch (error) {
				console.warn(`Failed to load message count for session ${session.id}:`, error);
			}
			return { ...session, messageCount: session.messageCount || 0 };
		})
	);

	// Filter out phantom sessions with 0 messages to prevent UI inconsistencies
	const validSessions = sessionsWithCounts.filter(session => session.messageCount > 0);

	console.log(
		`📊 Sessions filtered: ${sessions.length} → ${validSessions.length} (removed ${sessions.length - validSessions.length} phantom sessions)`
	);

	return validSessions;
}

async function fetchSessionHistory(sessionId: string): Promise<SessionMessage[]> {
	return loadSessionHistory(sessionId);
}

async function createSession(sessionId?: string): Promise<Session> {
	const response = await fetch('/api/sessions', {
		method: 'POST',
		headers: { 'Content-Type': 'application/json' },
		body: JSON.stringify(sessionId ? { sessionId } : {}),
	});

	if (!response.ok) {
		const errorData = await response.json().catch(() => ({}));
		throw new Error(errorData.error?.message || errorData.message || 'Failed to create session');
	}

	const data = await response.json();
	const session = data.data?.session || data.session;

	if (!session || !session.id) {
		throw new Error('Invalid session response format');
	}

	return session;
}

async function deleteSession(sessionId: string): Promise<void> {
	console.log('🗑️ Deleting session:', sessionId);
	const response = await fetch(`/api/sessions/${sessionId}`, {
		method: 'DELETE',
	});

	if (!response.ok) {
		const errorData = await response.json().catch(() => ({}));
		console.error('❌ Session deletion failed:', sessionId, errorData);
		throw new Error(errorData.error?.message || errorData.message || 'Failed to delete session');
	}

	console.log('✅ Session deletion successful:', sessionId);
}

async function loadSessionData(
	sessionId: string
): Promise<{ session: Session; messages: ChatMessage[] }> {
	// Load session on backend first
	const sessionData = await loadSession(sessionId);

	// Get session details from the sessions list or fetch individually
	let session: Session;
	const cachedSession = useSessionStore.getState().getCachedSession(sessionId);

	if (cachedSession?.session) {
		session = cachedSession.session;
	} else {
		// Fetch session details if not cached
		try {
			const response = await fetch(`/api/sessions/${sessionId}`);
			if (response.ok) {
				const data = await response.json();
				session = data.data?.session ||
					data.session || {
						id: sessionId,
						createdAt: null,
						lastActivity: null,
						messageCount: 0,
					};
			} else {
				throw new Error('Session not found');
			}
		} catch {
			// Fallback session object
			session = {
				id: sessionId,
				createdAt: null,
				lastActivity: null,
				messageCount: 0,
			};
		}
	}

	// Convert history to UI messages
	const history = sessionData.conversationHistory || [];
	const messages = convertHistoryToUIMessages(history, sessionId);

	return { session, messages };
}

// Hook for fetching sessions list - React Query as single source of truth
export function useSessions() {
	const { setSessions, setSessionsLoading, setSessionsError } = useSessionStore();

	const query = useQuery({
		queryKey: sessionQueryKeys.lists(),
		queryFn: fetchSessions,
		staleTime: 30 * 1000, // 30 seconds - longer to prevent disappearing sessions
		gcTime: 5 * 60 * 1000, // 5 minutes garbage collection
		refetchOnWindowFocus: false, // Don't refetch on focus to prevent disappearing sessions
		refetchOnMount: 'always', // Always fetch fresh data on mount
		refetchOnReconnect: true, // Refetch when network reconnects
	});

	// Sync with Zustand store for compatibility with legacy code
	useEffect(() => {
		if (query.data) {
			setSessions(query.data);
		}
	}, [query.data, setSessions]);

	useEffect(() => {
		setSessionsLoading(query.isLoading || query.isFetching);
	}, [query.isLoading, query.isFetching, setSessionsLoading]);

	useEffect(() => {
		setSessionsError(query.error?.message || null);
	}, [query.error, setSessionsError]);

	// Return React Query data as single source of truth for immediate UI updates
	return {
		sessions: query.data || [],
		isLoading: query.isLoading || query.isFetching,
		error: query.error?.message || null,
		refetch: query.refetch,
		isRefetching: query.isRefetching,
	};
}

// Hook for fetching session details and history
export function useSession(sessionId: string | null) {
	const { getCachedSession, setCachedSession, enableOptimizations } = useSessionStore();

	const query = useQuery({
		queryKey: sessionQueryKeys.detail(sessionId!),
		queryFn: () => loadSessionData(sessionId!),
		enabled: !!sessionId,
		staleTime: enableOptimizations ? 60000 : 0, // 1 minute
		gcTime: enableOptimizations ? 10 * 60 * 1000 : 0, // 10 minutes
		refetchOnWindowFocus: false,
	});

	// Cache the session data when loaded
	useEffect(() => {
		if (query.data && sessionId && enableOptimizations) {
			setCachedSession(sessionId, {
				session: query.data.session,
				messages: query.data.messages,
				lastAccessed: Date.now(),
				isLoaded: true,
			});
		}
	}, [query.data, sessionId, setCachedSession, enableOptimizations]);

	// Return cached data if available and optimizations enabled
	const cachedData = sessionId && enableOptimizations ? getCachedSession(sessionId) : null;

	return {
		session: cachedData?.session || query.data?.session || null,
		messages: cachedData?.messages || query.data?.messages || [],
		isLoading: query.isLoading,
		error: query.error?.message || null,
		refetch: query.refetch,
		isCached: !!cachedData,
	};
}

// Hook for session history only
export function useSessionHistory(sessionId: string | null) {
	return useQuery({
		queryKey: sessionQueryKeys.history(sessionId!),
		queryFn: () => fetchSessionHistory(sessionId!),
		enabled: !!sessionId,
		staleTime: 30000, // 30 seconds
		gcTime: 5 * 60 * 1000, // 5 minutes
	});
}

// Hook for creating sessions with proper optimistic updates
export function useCreateSession() {
	const queryClient = useQueryClient();
	const { setCreatingSession } = useSessionStore();

	return useMutation({
		mutationFn: createSession,
		onMutate: async sessionId => {
			setCreatingSession(true);

			// Cancel any outgoing refetches to prevent race conditions
			await queryClient.cancelQueries({ queryKey: sessionQueryKeys.lists() });

			// Get current sessions for rollback
			const previousSessions =
				(queryClient.getQueryData(sessionQueryKeys.lists()) as Session[]) || [];

			// Optimistic update - add temporary session immediately for instant UI feedback
			const optimisticSession: Session = {
				id: sessionId || `temp-${Date.now()}`,
				createdAt: new Date().toISOString(),
				lastActivity: new Date().toISOString(),
				messageCount: 0,
			};

			// Update React Query cache immediately
			queryClient.setQueryData(sessionQueryKeys.lists(), [optimisticSession, ...previousSessions]);

			return { optimisticSession, previousSessions };
		},
		onError: (error, variables, context) => {
			console.error('Failed to create session:', error);
			setCreatingSession(false);

			// Rollback on error
			if (context?.previousSessions) {
				queryClient.setQueryData(sessionQueryKeys.lists(), context.previousSessions);
			}
		},
		onSuccess: (newSession, variables, context) => {
			setCreatingSession(false);

			// Replace optimistic session with real session data
			queryClient.setQueryData(sessionQueryKeys.lists(), (oldSessions: Session[] = []) => {
				const filteredSessions = context?.optimisticSession
					? oldSessions.filter(s => s.id !== context.optimisticSession.id)
					: oldSessions.filter(s => s.id !== newSession.id);

				return [newSession, ...filteredSessions];
			});

			// Update store for compatibility
			const store = useSessionStore.getState();
			store.addSessionToList(newSession);

			// Cache the new session
			store.setCachedSession(newSession.id, {
				session: newSession,
				messages: [],
				lastAccessed: Date.now(),
				isLoaded: true,
			});

			// Emit creation event
			if (typeof window !== 'undefined') {
				window.dispatchEvent(
					new CustomEvent('cipher:sessionCreated', {
						detail: { sessionId: newSession.id, session: newSession },
					})
				);
			}
		},
	});
}

// Hook for deleting sessions with proper optimistic updates
export function useDeleteSession() {
	const queryClient = useQueryClient();
	const { setDeletingSessionId, currentSessionId } = useSessionStore();

	return useMutation({
		mutationFn: deleteSession,
		onMutate: async sessionId => {
			console.log('🔄 Starting optimistic deletion for session:', sessionId);
			setDeletingSessionId(sessionId);

			// Cancel any outgoing refetches to prevent race conditions
			await queryClient.cancelQueries({ queryKey: sessionQueryKeys.lists() });

			// Get current sessions for rollback
			const previousSessions =
				(queryClient.getQueryData(sessionQueryKeys.lists()) as Session[]) || [];
			const sessionToDelete = previousSessions.find(s => s.id === sessionId);

			if (!sessionToDelete) {
				console.warn('⚠️ Session not found in cache for deletion:', sessionId);
				return { previousSessions };
			}

			// Optimistic update - immediately remove from cache for instant UI feedback
			queryClient.setQueryData(sessionQueryKeys.lists(), (oldSessions: Session[] = []) => {
				const filtered = oldSessions.filter(session => session.id !== sessionId);
				console.log(
					'📝 Optimistically removed session from cache. Before:',
					oldSessions.length,
					'After:',
					filtered.length
				);
				return filtered;
			});

			return { sessionToDelete, previousSessions };
		},
		onError: (error, sessionId, context) => {
			console.error('Failed to delete session:', error);
			setDeletingSessionId(null);

			// Rollback on error
			if (context?.previousSessions) {
				queryClient.setQueryData(sessionQueryKeys.lists(), context.previousSessions);
			}
		},
		onSuccess: (_, sessionId, context) => {
			console.log('✅ Session deletion confirmed by server:', sessionId);
			setDeletingSessionId(null);

			// Clean up all related queries
			queryClient.removeQueries({ queryKey: sessionQueryKeys.detail(sessionId) });
			queryClient.removeQueries({ queryKey: sessionQueryKeys.history(sessionId) });

			// CRITICAL FIX: Force refetch with no cache to prevent phantom sessions
			console.log('🔄 Force refetching sessions list to ensure no phantom sessions...');
			queryClient.refetchQueries({
				queryKey: sessionQueryKeys.lists(),
				type: 'active',
			});

			// Also invalidate to ensure any cached data is cleared
			queryClient.invalidateQueries({ queryKey: sessionQueryKeys.lists() });

			// Update store for compatibility
			const store = useSessionStore.getState();
			store.removeSessionFromList(sessionId);
			store.removeCachedSession(sessionId);

			// Handle current session deletion
			if (currentSessionId === sessionId) {
				sessionStoreActions.returnToWelcome();
			}

			// Emit deletion event
			if (typeof window !== 'undefined') {
				window.dispatchEvent(
					new CustomEvent('cipher:sessionDeleted', {
						detail: { sessionId, session: context?.sessionToDelete },
					})
				);
			}

			console.log('🎯 Session deletion process completed for:', sessionId);
		},
	});
}

// Hook for switching sessions with caching
export function useSessionSwitch() {
	const {
		switchingSession,
		setSwitchingSession,
		getCachedSession,
		setCachedSession,
		enableOptimizations,
		currentSessionId,
	} = useSessionStore();

	const switchToSession = useCallback(
		async (sessionId: string) => {
			if (sessionId === currentSessionId || switchingSession) {
				return;
			}

			setSwitchingSession(true);

			try {
				// Check cache first if optimizations enabled
				if (enableOptimizations) {
					const cached = getCachedSession(sessionId);
					console.log('🔍 Cache check for session', sessionId);
					console.log('   - Cache hit:', !!cached);
					console.log('   - Is loaded:', cached?.isLoaded);
					console.log('   - Messages count:', cached?.messages?.length || 0);
					console.log('   - Optimizations enabled:', enableOptimizations);

					if (cached && cached.isLoaded) {
						console.log(
							'✅ Using cached session data for',
							sessionId,
							'with',
							cached.messages?.length || 0,
							'messages'
						);
						// Use cached data
						sessionStoreActions.switchToSession(sessionId);
						setSwitchingSession(false);

						// Emit session change event
						if (typeof window !== 'undefined') {
							window.dispatchEvent(
								new CustomEvent('cipher:sessionChanged', {
									detail: { sessionId, previousSessionId: currentSessionId, cached: true },
								})
							);
						}
						return;
					}
				}

				// Load session data from server (fallback)
				console.log('❌ Session not cached, loading from server:', sessionId);
				const { session, messages } = await loadSessionData(sessionId);

				// Cache the data if optimizations enabled
				if (enableOptimizations) {
					setCachedSession(sessionId, {
						session,
						messages,
						lastAccessed: Date.now(),
						isLoaded: true,
					});
				}

				// Switch to session
				sessionStoreActions.switchToSession(sessionId);

				// Emit session change event
				if (typeof window !== 'undefined') {
					window.dispatchEvent(
						new CustomEvent('cipher:sessionChanged', {
							detail: { sessionId, previousSessionId: currentSessionId, cached: false },
						})
					);
				}
			} catch (error) {
				console.error('Failed to switch session:', error);

				// Emit error event
				if (typeof window !== 'undefined') {
					window.dispatchEvent(
						new CustomEvent('cipher:sessionSwitchError', {
							detail: {
								sessionId,
								error: error instanceof Error ? error.message : String(error),
							},
						})
					);
				}

				throw error;
			} finally {
				setSwitchingSession(false);
			}
		},
		[
			currentSessionId,
			switchingSession,
			setSwitchingSession,
			getCachedSession,
			setCachedSession,
			enableOptimizations,
		]
	);

	return {
		switchToSession,
		isSwitching: switchingSession,
	};
}

// Hook for preloading sessions
export function useSessionPreloader() {
	const { getCachedSession, setCachedSession, enableOptimizations } = useSessionStore();

	const preloadSession = useCallback(
		async (sessionId: string) => {
			if (!enableOptimizations) return;

			// Check if already cached
			if (getCachedSession(sessionId)) return;

			try {
				const { session, messages } = await loadSessionData(sessionId);
				setCachedSession(sessionId, {
					session,
					messages,
					lastAccessed: Date.now(),
					isLoaded: true,
				});
			} catch (error) {
				console.warn('Failed to preload session:', sessionId, error);
			}
		},
		[getCachedSession, setCachedSession, enableOptimizations]
	);

	return { preloadSession };
}

// Hook for managing session cache
export function useSessionCache() {
	const {
		getCacheStats,
		clearSessionCache,
		removeCachedSession,
		enableOptimizations,
		setEnableOptimizations,
		maxCacheSize,
		setMaxCacheSize,
	} = useSessionStore();

	return {
		stats: getCacheStats(),
		clearCache: clearSessionCache,
		removeFromCache: removeCachedSession,
		enableOptimizations,
		setEnableOptimizations,
		maxCacheSize,
		setMaxCacheSize,
	};
}

// Hook for refreshing session cache
export function useSessionCacheRefresh() {
	const { getCachedSession, setCachedSession, enableOptimizations } = useSessionStore();

	const refreshSessionCache = useCallback(
		async (sessionId: string) => {
			if (!enableOptimizations || !sessionId) return;

			try {
				console.log('🔄 Refreshing cache for session:', sessionId);

				// Fetch fresh session data
				const { session, messages } = await loadSessionData(sessionId);

				// Update cache with fresh data
				setCachedSession(sessionId, {
					session,
					messages,
					lastAccessed: Date.now(),
					isLoaded: true,
				});

				console.log(
					'✅ Cache refreshed for session:',
					sessionId,
					'with',
					messages.length,
					'messages'
				);
			} catch (error) {
				console.error('❌ Failed to refresh session cache:', sessionId, error);
			}
		},
		[getCachedSession, setCachedSession, enableOptimizations]
	);

	return { refreshSessionCache };
}

// Hook for session operations with real-time updates
export function useSessionOperations() {
	const createMutation = useCreateSession();
	const deleteMutation = useDeleteSession();
	const { switchToSession } = useSessionSwitch();
	const { refreshSessionCache } = useSessionCacheRefresh();
	const queryClient = useQueryClient();

	// Listen for WebSocket events to update cache when needed
	useEffect(() => {
		const handleNewMessage = (event: Event) => {
			const customEvent = event as CustomEvent;
			const { sessionId } = customEvent.detail || {};
			if (sessionId) {
				// Only increment message count for user messages (cipher:newMessage)
				// Don't increment for cipher:response as it might be a tool call
				const isUserMessage = event.type === 'cipher:newMessage';

				queryClient.setQueryData(sessionQueryKeys.lists(), (oldSessions: Session[] = []) => {
					return oldSessions.map(session =>
						session.id === sessionId
							? {
									...session,
									lastActivity: new Date().toISOString(),
									messageCount: isUserMessage
										? (session.messageCount || 0) + 1
										: session.messageCount,
								}
							: session
					);
				});

				// Also update store for compatibility
				useSessionStore.getState().updateSessionInList(sessionId, {
					lastActivity: new Date().toISOString(),
				});
			}
		};

		// Handle response complete event to refresh cache
		const handleResponseComplete = (event: Event) => {
			const customEvent = event as CustomEvent;
			const { sessionId } = customEvent.detail || {};
			if (sessionId) {
				console.log('🎯 Response complete for session:', sessionId, '- refreshing cache');
				// Add a small delay to ensure the backend has processed the message
				setTimeout(() => {
					refreshSessionCache(sessionId);
				}, 500);
			}
		};

		if (typeof window !== 'undefined') {
			window.addEventListener('cipher:newMessage', handleNewMessage as EventListener);
			window.addEventListener('cipher:response', handleNewMessage as EventListener);
			window.addEventListener('cipher:responseComplete', handleResponseComplete as EventListener);

			return () => {
				window.removeEventListener('cipher:newMessage', handleNewMessage as EventListener);
				window.removeEventListener('cipher:response', handleNewMessage as EventListener);
				window.removeEventListener(
					'cipher:responseComplete',
					handleResponseComplete as EventListener
				);
			};
		}
	}, [queryClient, refreshSessionCache]);

	return {
		createSession: createMutation.mutate,
		deleteSession: deleteMutation.mutate,
		switchToSession,
		refreshSessionCache,
		isCreating: createMutation.isPending,
		isDeleting: deleteMutation.isPending,
		createError: createMutation.error?.message || null,
		deleteError: deleteMutation.error?.message || null,
	};
}

import { useState, useEffect, useCallback } from 'react'
import { useChatContext } from '@/contexts/chat-context'

interface WorkflowEvent {
  type: string
  data: any
  timestamp: string
}

export function useWorkflowEvents() {
  const [events, setEvents] = useState<WorkflowEvent[]>([])
  const { websocket } = useChatContext()

  // Add a workflow event
  const addEvent = useCallback((type: string, data: any) => {
    const newEvent: WorkflowEvent = {
      type,
      data,
      timestamp: new Date().toISOString()
    }

    setEvents(prev => {
      // Keep last 100 events to prevent memory issues
      const updated = [...prev, newEvent].slice(-100)
      return updated
    })
  }, [])

  // Clear events
  const clearEvents = useCallback(() => {
    setEvents([])
  }, [])

  // Listen for Cipher WebSocket events
  useEffect(() => {
    const handleCipherMessage = (event: CustomEvent) => {
      const { message, sessionId } = event.detail
      if (message) {
        addEvent('cipher_message', {
          content: message.content,
          role: message.role,
          sessionId,
          messageId: message.id
        })
      }
    }

    const handleCipherError = (event: CustomEvent) => {
      const { error, sessionId } = event.detail
      addEvent('cipher_error', {
        error: error.message || error,
        sessionId
      })
    }

    const handleCipherStatusChange = (event: CustomEvent) => {
      const { status, sessionId } = event.detail
      addEvent('cipher_status', {
        status,
        sessionId
      })
    }

    const handleConversationReset = (event: CustomEvent) => {
      const { sessionId } = event.detail
      addEvent('conversation_reset', {
        sessionId
      })
    }

    const handleSessionChanged = (event: CustomEvent) => {
      const { sessionId, cached } = event.detail
      addEvent('session_change', {
        sessionId,
        cached
      })
    }

    const handleReturnToWelcome = (event: CustomEvent) => {
      const { previousSessionId } = event.detail
      addEvent('return_to_welcome', {
        previousSessionId
      })
    }

    // Listen for custom workflow events from Shrimp Task Manager
    const handleShrimpTaskUpdate = (event: CustomEvent) => {
      const { task } = event.detail
      addEvent('task_update', {
        taskId: task.id,
        status: task.status,
        name: task.name,
        dependencies: task.dependencies
      })
    }

    const handleWorkflowProgress = (event: CustomEvent) => {
      const { progress } = event.detail
      addEvent('workflow_progress', {
        completedTasks: progress.completed,
        totalTasks: progress.total,
        currentTask: progress.current
      })
    }

    if (typeof window !== 'undefined') {
      // Cipher events
      window.addEventListener('cipher:newMessage', handleCipherMessage as EventListener)
      window.addEventListener('cipher:error', handleCipherError as EventListener)
      window.addEventListener('cipher:statusChange', handleCipherStatusChange as EventListener)
      window.addEventListener('cipher:conversationReset', handleConversationReset as EventListener)
      window.addEventListener('cipher:sessionChanged', handleSessionChanged as EventListener)
      window.addEventListener('cipher:returnToWelcome', handleReturnToWelcome as EventListener)

      // Workflow-specific events
      window.addEventListener('shrimp:taskUpdate', handleShrimpTaskUpdate as EventListener)
      window.addEventListener('workflow:progress', handleWorkflowProgress as EventListener)

      return () => {
        window.removeEventListener('cipher:newMessage', handleCipherMessage as EventListener)
        window.removeEventListener('cipher:error', handleCipherError as EventListener)
        window.removeEventListener('cipher:statusChange', handleCipherStatusChange as EventListener)
        window.removeEventListener('cipher:conversationReset', handleConversationReset as EventListener)
        window.removeEventListener('cipher:sessionChanged', handleSessionChanged as EventListener)
        window.removeEventListener('cipher:returnToWelcome', handleReturnToWelcome as EventListener)
        window.removeEventListener('shrimp:taskUpdate', handleShrimpTaskUpdate as EventListener)
        window.removeEventListener('workflow:progress', handleWorkflowProgress as EventListener)
      }
    }
  }, [addEvent])

  return {
    events,
    addEvent,
    clearEvents,
    eventCount: events.length,
    latestEvent: events[events.length - 1] || null
  }
}

import { ApiResponse, SessionInfo, MessageResponse, SystemHealth, LLMConfig } from '@/types/api';

const DEFAULT_BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3001';

export class ApiClient {
	private baseUrl: string;

	constructor(baseUrl?: string) {
		this.baseUrl = baseUrl || DEFAULT_BASE_URL;
	}

	private async request<T>(endpoint: string, options: RequestInit = {}): Promise<ApiResponse<T>> {
		const url = `${this.baseUrl}${endpoint}`;

		const defaultHeaders = {
			'Content-Type': 'application/json',
		};

		try {
			const response = await fetch(url, {
				...options,
				headers: {
					...defaultHeaders,
					...options.headers,
				},
			});

			const data = await response.json();

			if (!response.ok) {
				return {
					success: false,
					error: {
						code: data.error?.code || 'HTTP_ERROR',
						message: data.error?.message || `HTTP ${response.status}: ${response.statusText}`,
						details: data.error?.details,
					},
					requestId: data.requestId,
				};
			}

			return data;
		} catch (error) {
			return {
				success: false,
				error: {
					code: 'NETWORK_ERROR',
					message: error instanceof Error ? error.message : 'Network request failed',
				},
			};
		}
	}

	// Health check
	async getHealth(): Promise<ApiResponse<SystemHealth>> {
		return this.request<SystemHealth>('/health');
	}

	// WebSocket stats
	async getWebSocketStats(): Promise<ApiResponse<any>> {
		return this.request<any>('/ws/stats');
	}

	// Session management
	async createSession(): Promise<ApiResponse<SessionInfo>> {
		return this.request<SessionInfo>('/api/sessions', {
			method: 'POST',
		});
	}

	async getSession(sessionId: string): Promise<ApiResponse<SessionInfo>> {
		return this.request<SessionInfo>(`/api/sessions/${sessionId}`);
	}

	async getSessions(): Promise<ApiResponse<SessionInfo[]>> {
		return this.request<SessionInfo[]>('/api/sessions');
	}

	async deleteSession(sessionId: string): Promise<ApiResponse<void>> {
		return this.request<void>(`/api/sessions/${sessionId}`, {
			method: 'DELETE',
		});
	}

	// Message handling
	async sendMessage(
		message: string,
		sessionId?: string,
		imageData?: string
	): Promise<ApiResponse<MessageResponse>> {
		return this.request<MessageResponse>('/api/message', {
			method: 'POST',
			body: JSON.stringify({
				message,
				sessionId,
				imageData,
			}),
		});
	}

	// LLM configuration
	async getLLMConfig(): Promise<ApiResponse<LLMConfig>> {
		return this.request<LLMConfig>('/api/llm/config');
	}

	async updateLLMConfig(config: Partial<LLMConfig>): Promise<ApiResponse<LLMConfig>> {
		return this.request<LLMConfig>('/api/llm/config', {
			method: 'PUT',
			body: JSON.stringify(config),
		});
	}

	// MCP server management
	async getMCPServers(): Promise<ApiResponse<any>> {
		return this.request<any>('/api/mcp/servers');
	}

	async getMCPTools(): Promise<ApiResponse<any>> {
		return this.request<any>('/api/mcp/tools');
	}

	async addMCPServer(name: string, config: any): Promise<ApiResponse<any>> {
		return this.request<any>('/api/mcp/servers', {
			method: 'POST',
			body: JSON.stringify({ name, config }),
		});
	}

	async removeMCPServer(serverId: string): Promise<ApiResponse<void>> {
		return this.request<void>(`/api/mcp/servers/${serverId}`, {
			method: 'DELETE',
		});
	}

	async getServerTools(serverId: string): Promise<ApiResponse<any>> {
		return this.request<any>(`/api/mcp/servers/${serverId}/tools`);
	}

	async executeServerTool(
		serverId: string,
		toolName: string,
		params: any
	): Promise<ApiResponse<any>> {
		return this.request<any>(`/api/mcp/servers/${serverId}/tools/${toolName}/execute`, {
			method: 'POST',
			body: JSON.stringify(params),
		});
	}

	// Session management extensions
	async loadSession(sessionId: string): Promise<ApiResponse<SessionInfo>> {
		return this.request<SessionInfo>(`/api/sessions/${sessionId}/load`, {
			method: 'POST',
		});
	}

	async getSessionHistory(sessionId: string): Promise<ApiResponse<any>> {
		return this.request<any>(`/api/sessions/${sessionId}/history`);
	}

	async getCurrentSession(): Promise<ApiResponse<SessionInfo>> {
		return this.request<SessionInfo>('/api/sessions/current');
	}

	// Webhook management
	async getWebhooks(): Promise<ApiResponse<any>> {
		return this.request<any>('/api/webhooks');
	}

	async createWebhook(url: string, events?: string[]): Promise<ApiResponse<any>> {
		return this.request<any>('/api/webhooks', {
			method: 'POST',
			body: JSON.stringify({ url, events }),
		});
	}

	async deleteWebhook(webhookId: string): Promise<ApiResponse<void>> {
		return this.request<void>(`/api/webhooks/${webhookId}`, {
			method: 'DELETE',
		});
	}

	async testWebhook(webhookId: string): Promise<ApiResponse<any>> {
		return this.request<any>(`/api/webhooks/${webhookId}/test`, {
			method: 'POST',
		});
	}

	// Global operations
	async globalReset(sessionId?: string): Promise<ApiResponse<any>> {
		return this.request<any>('/api/reset', {
			method: 'POST',
			body: JSON.stringify({ sessionId }),
		});
	}

	// A2A Discovery
	async getAgentCard(): Promise<ApiResponse<any>> {
		return this.request<any>('/.well-known/agent.json');
	}

	// LLM Provider information
	async getLLMProviders(): Promise<ApiResponse<any>> {
		return this.request<any>('/api/llm/providers');
	}

	async getLLMStatus(): Promise<ApiResponse<any>> {
		return this.request<any>('/api/llm/status');
	}

	async switchLLM(
		provider: string,
		model: string,
		config?: any,
		sessionId?: string
	): Promise<ApiResponse<any>> {
		return this.request<any>('/api/llm/switch', {
			method: 'POST',
			body: JSON.stringify({ provider, model, config, sessionId }),
		});
	}
}

// Default client instance
export const apiClient = new ApiClient();

import { SessionMessage, ChatMessage, ToolCall } from '@/types/chat';

// API base URL configuration
const API_BASE_URL = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:3001';

// WebSocket URL configuration
export function getWebSocketUrl(customUrl?: string): string {
	let wsUrl = customUrl || process.env.NEXT_PUBLIC_WS_URL || 'ws://localhost:3001/ws';

	if (typeof window !== 'undefined') {
		try {
			const urlObj = new URL(wsUrl);
			if (urlObj.hostname === 'localhost') {
				// Replace localhost with current hostname for network access
				urlObj.hostname = window.location.hostname;
				wsUrl = urlObj.toString();
			}
		} catch {
			console.warn('Invalid WS URL:', wsUrl);
		}
	}

	return wsUrl;
}

// Auto-session creation
export async function createAutoSession(): Promise<string> {
	try {
		const response = await fetch('/api/sessions', {
			method: 'POST',
			headers: { 'Content-Type': 'application/json' },
			body: JSON.stringify({}), // Let server generate random UUID
		});

		if (!response.ok) {
			throw new Error('Failed to create session');
		}

		const data = await response.json();
		// Handle the standardized API response format
		if (data.success && data.data?.session?.id) {
			return data.data.session.id;
		} else if (data.data?.sessionId) {
			return data.data.sessionId;
		} else {
			console.error('Unexpected session response format:', data);
			throw new Error('Invalid session response format');
		}
	} catch (error) {
		console.error('Error creating auto session:', error);
		// Fallback to a simple timestamp-based session ID
		return `chat-${Date.now()}`;
	}
}

// Load session on backend
export async function loadSession(
	sessionId: string
): Promise<{ conversationHistory?: SessionMessage[] }> {
	const response = await fetch(`/api/sessions/${sessionId}/load`, {
		method: 'POST',
		headers: { 'Content-Type': 'application/json' },
	});

	if (!response.ok) {
		throw new Error('Failed to load session on backend');
	}

	const data = await response.json();
	return {
		conversationHistory: data.data?.conversationHistory || [],
	};
}

// Load session history
export async function loadSessionHistory(sessionId: string): Promise<SessionMessage[]> {
	const response = await fetch(`/api/sessions/${sessionId}/history`);

	if (!response.ok) {
		if (response.status === 404) {
			// Session doesn't exist, create it
			const createResponse = await fetch('/api/sessions', {
				method: 'POST',
				headers: { 'Content-Type': 'application/json' },
				body: JSON.stringify({ sessionId }),
			});

			if (!createResponse.ok) {
				throw new Error('Failed to create session');
			}

			// New session has no history
			return [];
		}
		throw new Error('Failed to load session history');
	}

	const data = await response.json();
	return data.data?.history || data.history || [];
}

// Convert session history to UI messages
export function convertHistoryToUIMessages(
	history: SessionMessage[],
	sessionId: string
): ChatMessage[] {
	const uiMessages: ChatMessage[] = [];

	for (let index = 0; index < history.length; index++) {
		const msg = history[index];
		const baseMessage: ChatMessage = {
			id: `session-${sessionId}-${index}`,
			role: msg.role as ChatMessage['role'],
			content: msg.content,
			createdAt: Date.now() - (history.length - index) * 1000, // Approximate timestamps
			sessionId: sessionId,
		};

		if (msg.role === 'assistant' && msg.toolCalls && msg.toolCalls.length > 0) {
			// Handle assistant messages with tool calls
			if (msg.content) {
				uiMessages.push(baseMessage);
			}

			// Add tool call messages for each tool call
			msg.toolCalls.forEach((toolCall: ToolCall, toolIndex: number) => {
				const toolArgs = toolCall.function ? JSON.parse(toolCall.function.arguments || '{}') : {};
				const toolName = toolCall.function?.name || 'unknown';

				// Look for corresponding tool result in subsequent messages
				let toolResult: string | undefined = undefined;
				for (let j = index + 1; j < history.length; j++) {
					const nextMsg = history[j];
					if (nextMsg.role === 'tool' && nextMsg.toolCallId === toolCall.id) {
						toolResult = nextMsg.content;
						break;
					}
				}

				uiMessages.push({
					id: `session-${sessionId}-${index}-tool-${toolIndex}`,
					role: 'tool',
					content: null,
					createdAt: Date.now() - (history.length - index) * 1000 + toolIndex,
					sessionId: sessionId,
					toolName: toolName,
					toolArgs: toolArgs,
					toolResult: toolResult,
				});
			});
		} else if (msg.role === 'tool') {
			// Skip standalone tool messages as they're handled above
			continue;
		} else {
			// Handle regular messages (user, system, assistant without tool calls)
			uiMessages.push(baseMessage);
		}
	}

	return uiMessages;
}

// Reset backend session
export async function resetBackendSession(): Promise<void> {
	try {
		// Instead of trying to load a null session, we'll create a new default session
		// or just clear the current session state
		const response = await fetch('/api/sessions', {
			method: 'POST',
			headers: { 'Content-Type': 'application/json' },
			body: JSON.stringify({}), // Create a new default session
		});

		if (response.ok) {
			const data = await response.json();
			if (data.success && data.data?.session?.id) {
				// Load the new default session
				await fetch(`/api/sessions/${data.data.session.id}/load`, {
					method: 'POST',
					headers: { 'Content-Type': 'application/json' },
				});
			}
		}
	} catch (error) {
		console.warn('Error resetting backend session:', error);
	}
}

// Create new session with optional ID
export async function createSession(sessionId?: string): Promise<{ id: string }> {
	const response = await fetch(`${API_BASE_URL}/api/sessions`, {
		method: 'POST',
		headers: { 'Content-Type': 'application/json' },
		body: JSON.stringify(sessionId ? { sessionId } : {}),
	});

	if (!response.ok) {
		throw new Error('Failed to create session');
	}

	const data = await response.json();
	// Handle the standardized API response format
	if (data.success && data.data?.session) {
		return data.data.session;
	} else if (data.data?.sessionId) {
		return { id: data.data.sessionId };
	} else {
		console.error('Unexpected session response format:', data);
		throw new Error('Invalid session response format');
	}
}

import {
	TextPart,
	ImagePart,
	FilePart,
	ToolResult,
	ToolResultError,
	ToolResultContent,
} from '@/types/chat';

// Type guards for content parts
export function isTextPart(part: unknown): part is TextPart {
	return (
		typeof part === 'object' &&
		part !== null &&
		'type' in part &&
		(part as { type: unknown }).type === 'text' &&
		'text' in part &&
		typeof (part as { text: unknown }).text === 'string'
	);
}

export function isImagePart(part: unknown): part is ImagePart {
	return (
		typeof part === 'object' &&
		part !== null &&
		'type' in part &&
		(part as { type: unknown }).type === 'image' &&
		'base64' in part &&
		'mimeType' in part &&
		typeof (part as { base64: unknown }).base64 === 'string' &&
		typeof (part as { mimeType: unknown }).mimeType === 'string'
	);
}

export function isFilePart(part: unknown): part is FilePart {
	return (
		typeof part === 'object' &&
		part !== null &&
		'type' in part &&
		(part as { type: unknown }).type === 'file' &&
		'data' in part &&
		'mimeType' in part &&
		typeof (part as { data: unknown }).data === 'string' &&
		typeof (part as { mimeType: unknown }).mimeType === 'string'
	);
}

// Type guards for tool results
export function isToolResultError(result: unknown): result is ToolResultError {
	return typeof result === 'object' && result !== null && 'error' in result;
}

export function isToolResultContent(result: unknown): result is ToolResultContent {
	return (
		typeof result === 'object' &&
		result !== null &&
		'content' in result &&
		Array.isArray((result as ToolResultContent).content)
	);
}

// ID generation utility
export const generateUniqueId = (): string =>
	`msg-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;

// Utility to extract image URI from tool result
export function extractImageFromToolResult(result: ToolResult): string | null {
	if (typeof result === 'string' && result.startsWith('data:image')) {
		return result;
	}

	if (isToolResultContent(result)) {
		const imgPart = result.content.find(
			(p): p is ImagePart => isImagePart(p) || (p as any).type === 'image'
		);
		if (imgPart) {
			return `data:${imgPart.mimeType};base64,${imgPart.base64}`;
		}
	}

	if (typeof result === 'object' && result !== null) {
		const resultObj = result as Record<string, unknown>;

		// Handle various image field formats
		if ('data' in resultObj && 'mimeType' in resultObj) {
			return `data:${resultObj.mimeType};base64,${resultObj.data}`;
		}

		if ('screenshot' in resultObj && typeof resultObj.screenshot === 'string') {
			return resultObj.screenshot;
		}

		if ('image' in resultObj && typeof resultObj.image === 'string') {
			return resultObj.image;
		}

		if (
			'url' in resultObj &&
			typeof resultObj.url === 'string' &&
			resultObj.url.startsWith('data:image')
		) {
			return resultObj.url;
		}
	}

	return null;
}

// Utility to format tool result for display
export function formatToolResult(result: ToolResult): string {
	if (typeof result === 'string') {
		return result;
	}

	if (isToolResultError(result)) {
		return typeof result.error === 'string' ? result.error : JSON.stringify(result.error, null, 2);
	}

	if (isToolResultContent(result)) {
		return result.content
			.filter(isTextPart)
			.map(part => part.text)
			.join('\n');
	}

	return JSON.stringify(result, null, 2);
}

// Utility to check if message has image content
export function hasImageContent(content: string | null | Array<TextPart | ImagePart>): boolean {
	if (Array.isArray(content)) {
		return content.some(isImagePart);
	}
	return false;
}

// Utility to extract text from message content
export function extractTextFromContent(
	content: string | null | Array<TextPart | ImagePart>
): string {
	if (typeof content === 'string') {
		return content || '';
	}

	if (Array.isArray(content)) {
		return content
			.filter(isTextPart)
			.map(part => part.text)
			.join(' ');
	}

	return '';
}

// Utility to create custom DOM events
export function dispatchChatEvent(eventName: string, detail: Record<string, unknown>): void {
	if (typeof window !== 'undefined') {
		window.dispatchEvent(new CustomEvent(eventName, { detail }));
	}
}

// Convert ChatMessage to Message for compatibility
export function convertChatMessageToMessage(chatMessage: any): any {
	const converted = {
		...chatMessage,
		// For tool messages, keep content as null to ensure proper rendering
		content:
			chatMessage.role === 'tool'
				? chatMessage.content
				: chatMessage.content === null
					? ''
					: chatMessage.content,
	};

	// Convert array content to proper format if needed
	if (Array.isArray(chatMessage.content)) {
		converted.content = chatMessage.content.map((part: any) => ({
			type: part.type,
			text: part.text,
			base64: part.base64,
			mimeType: part.mimeType,
			data: part.data,
			filename: part.filename,
		}));
	}

	return converted;
}

import type { ServerRegistryEntry, ServerRegistryFilter } from '@/types/server-registry';

/**
 * MCP Server Registry Service
 * Manages a registry of available MCP servers that can be quickly added to agents
 */
export class ServerRegistryService {
	private static instance: ServerRegistryService;
	private registryEntries: ServerRegistryEntry[] = [];
	private isInitialized = false;

	private constructor() {
		// Private constructor for singleton
	}

	static getInstance(): ServerRegistryService {
		if (!ServerRegistryService.instance) {
			ServerRegistryService.instance = new ServerRegistryService();
		}
		return ServerRegistryService.instance;
	}

	/**
	 * Initialize the registry with default entries and load from external sources
	 */
	async initialize(): Promise<void> {
		if (this.isInitialized) return;

		// Load built-in registry entries
		this.registryEntries = this.getBuiltinEntries();

		// Load custom entries from localStorage
		await this.loadCustomEntries();

		// TODO: Load from external registry sources (GitHub, npm, etc.)
		// await this.loadExternalRegistries();

		this.isInitialized = true;
	}

	/**
	 * Get all registry entries with optional filtering
	 */
	async getEntries(filter?: ServerRegistryFilter): Promise<ServerRegistryEntry[]> {
		await this.initialize();

		let filtered = [...this.registryEntries];

		// Show only official entries by default
		filtered = filtered.filter(entry => entry.isOfficial === true);

		if (filter?.category) {
			filtered = filtered.filter(entry => entry.category === filter.category);
		}

		if (filter?.tags?.length) {
			filtered = filtered.filter(entry => filter.tags!.some(tag => entry.tags?.includes(tag)));
		}

		if (filter?.search) {
			const searchLower = filter.search.toLowerCase();
			filtered = filtered.filter(
				entry =>
					entry.name.toLowerCase().includes(searchLower) ||
					entry.description.toLowerCase().includes(searchLower) ||
					entry.tags?.some(tag => tag.toLowerCase().includes(searchLower))
			);
		}

		if (filter?.installed !== undefined) {
			filtered = filtered.filter(entry => entry.isInstalled === filter.installed);
		}

		// Allow explicit override to show non-official entries
		if (filter?.official !== undefined) {
			filtered = this.registryEntries.filter(entry => entry.isOfficial === filter.official);

			// Re-apply other filters if official filter is explicitly set
			if (filter?.category) {
				filtered = filtered.filter(entry => entry.category === filter.category);
			}
			if (filter?.tags?.length) {
				filtered = filtered.filter(entry => filter.tags!.some(tag => entry.tags?.includes(tag)));
			}
			if (filter?.search) {
				const searchLower = filter.search.toLowerCase();
				filtered = filtered.filter(
					entry =>
						entry.name.toLowerCase().includes(searchLower) ||
						entry.description.toLowerCase().includes(searchLower) ||
						entry.tags?.some(tag => tag.toLowerCase().includes(searchLower))
				);
			}
			if (filter?.installed !== undefined) {
				filtered = filtered.filter(entry => entry.isInstalled === filter.installed);
			}
		}

		return filtered.sort((a, b) => {
			// Sort by: installed first, then official, then popularity, then name
			if (a.isInstalled !== b.isInstalled) {
				return a.isInstalled ? -1 : 1;
			}
			if (a.isOfficial !== b.isOfficial) {
				return a.isOfficial ? -1 : 1;
			}
			if (a.popularity !== b.popularity) {
				return (b.popularity || 0) - (a.popularity || 0);
			}
			return a.name.localeCompare(b.name);
		});
	}

	/**
	 * Add a custom server to the registry
	 */
	async addCustomEntry(
		entry: Omit<ServerRegistryEntry, 'id' | 'isOfficial' | 'lastUpdated'>
	): Promise<ServerRegistryEntry> {
		const newEntry: ServerRegistryEntry = {
			...entry,
			id: `custom-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`,
			isOfficial: false,
			lastUpdated: new Date(),
		};

		this.registryEntries.push(newEntry);
		await this.saveCustomEntries();

		return newEntry;
	}

	/**
	 * Update an existing registry entry
	 */
	async updateEntry(id: string, updates: Partial<ServerRegistryEntry>): Promise<boolean> {
		const index = this.registryEntries.findIndex(entry => entry.id === id);
		if (index === -1) return false;

		this.registryEntries[index] = {
			...this.registryEntries[index],
			...updates,
			lastUpdated: new Date(),
		};

		await this.saveCustomEntries();
		return true;
	}

	/**
	 * Mark a server as installed/uninstalled
	 */
	async setInstalled(id: string, installed: boolean): Promise<void> {
		const success = await this.updateEntry(id, { isInstalled: installed });
		if (!success) {
			throw new Error(`Server with id "${id}" not found`);
		}
	}

	/**
	 * Remove a custom server entry
	 */
	async removeEntry(id: string): Promise<void> {
		const index = this.registryEntries.findIndex(entry => entry.id === id);
		if (index === -1) {
			throw new Error(`Server with id "${id}" not found`);
		}

		// Only allow removal of custom entries
		const entry = this.registryEntries[index];
		if (entry.isOfficial) {
			throw new Error('Cannot remove official server entries');
		}

		this.registryEntries.splice(index, 1);
		await this.saveCustomEntries();
	}

	/**
	 * Get server configuration for connecting
	 */
	async getServerConfig(id: string): Promise<ServerRegistryEntry | null> {
		await this.initialize();
		return this.registryEntries.find(entry => entry.id === id) || null;
	}

	/**
	 * Built-in registry entries for popular MCP servers
	 */
	private getBuiltinEntries(): ServerRegistryEntry[] {
		return [
			{
				id: 'filesystem',
				name: 'File System',
				description:
					'Secure file operations with configurable access controls for reading and writing files',
				category: 'productivity',
				icon: '📁',
				config: {
					type: 'stdio',
					command: 'npx',
					args: ['-y', '@modelcontextprotocol/server-filesystem', '/path/to/allowed/directory'],
					timeout: 30000,
				},
				tags: ['file', 'directory', 'filesystem', 'io'],
				isOfficial: true,
				isInstalled: false,
				popularity: 95,
				lastUpdated: new Date(),
				requirements: {
					platform: 'all',
					node: '>=20.0.0',
				},
				author: 'Anthropic',
				version: '0.6.0',
				homepage: 'https://github.com/modelcontextprotocol/servers',
			},
			{
				id: 'github',
				name: 'GitHub',
				description:
					'Repository management, file operations, search repositories, manage issues and pull requests',
				category: 'development',
				icon: '🐙',
				config: {
					type: 'stdio',
					command: 'npx',
					args: ['-y', '@modelcontextprotocol/server-github'],
					env: {
						GITHUB_PERSONAL_ACCESS_TOKEN: '',
					},
					timeout: 30000,
				},
				tags: ['git', 'repository', 'version-control', 'issues', 'pr'],
				isOfficial: true,
				isInstalled: false,
				popularity: 92,
				lastUpdated: new Date(),
				requirements: {
					platform: 'all',
					node: '>=20.0.0',
				},
				author: 'GitHub',
				version: '0.6.0',
				homepage: 'https://github.com/modelcontextprotocol/servers',
			},
			{
				id: 'brave-search',
				name: 'Brave Search',
				description:
					"Web and local search using Brave's Search API for real-time information retrieval",
				category: 'research',
				icon: '🔍',
				config: {
					type: 'stdio',
					command: 'npx',
					args: ['-y', '@modelcontextprotocol/server-brave-search'],
					env: {
						BRAVE_SEARCH_API_KEY: '',
					},
					timeout: 30000,
				},
				tags: ['search', 'web', 'research', 'information'],
				isOfficial: true,
