describe('Embedding Factory', () => {
	beforeEach(() => {
		vi.clearAllMocks();
		// Clear environment variables
		delete process.env.OPENAI_API_KEY;
		delete process.env.GEMINI_API_KEY;
		delete process.env.OLLAMA_BASE_URL;
		delete process.env.LMSTUDIO_BASE_URL;
		delete process.env.QWEN_API_KEY;
		delete process.env.DASHSCOPE_API_KEY;
		delete process.env.AWS_ACCESS_KEY_ID;
		delete process.env.AWS_SECRET_ACCESS_KEY;
		delete process.env.VOYAGE_API_KEY;
	});

	describe('Provider Support', () => {
		it('should return all supported providers', () => {
			const providers = getSupportedProviders();
			expect(providers).toContain('openai');
			expect(providers).toContain('gemini');
			expect(providers).toContain('ollama');
			expect(providers).toContain('voyage');
			expect(providers).toContain('qwen');
			expect(providers).toContain('aws-bedrock');
			expect(providers).toContain('lmstudio');
			expect(providers).toHaveLength(7);
		});

		it('should correctly identify supported providers', () => {
			expect(isProviderSupported('openai')).toBe(true);
			expect(isProviderSupported('gemini')).toBe(true);
			expect(isProviderSupported('ollama')).toBe(true);
			expect(isProviderSupported('voyage')).toBe(true);
			expect(isProviderSupported('qwen')).toBe(true);
			expect(isProviderSupported('aws-bedrock')).toBe(true);
			expect(isProviderSupported('lmstudio')).toBe(true);
			expect(isProviderSupported('unsupported')).toBe(false);
		});

		it('should have factory instances for all supported providers', () => {
			const providers = getSupportedProviders();
			providers.forEach(provider => {
				expect(EMBEDDING_FACTORIES.has(provider)).toBe(true);
				expect(EMBEDDING_FACTORIES.get(provider)).toBeDefined();
			});
		});
	});

	describe('Factory Classes', () => {
		describe('OpenAIEmbeddingFactory', () => {
			const factory = new OpenAIEmbeddingFactory();

			it('should validate correct config', () => {
				expect(factory.validateConfig({ type: 'openai' })).toBe(true);
				expect(factory.validateConfig({ type: 'gemini' })).toBe(false);
				expect(factory.validateConfig(null)).toBe(false);
			});

			it('should return correct provider type', () => {
				expect(factory.getProviderType()).toBe('openai');
			});

			it('should create embedder for valid config', async () => {
				const config: BackendConfig = { type: 'openai', apiKey: 'test-key' };
				const embedder = await factory.createEmbedder(config);
				expect(embedder).toBeDefined();
			});

			it('should reject invalid config type', async () => {
				const config = { type: 'gemini' } as any;
				await expect(factory.createEmbedder(config)).rejects.toThrow(EmbeddingValidationError);
			});
		});

		describe('LMStudioEmbeddingFactory', () => {
			const factory = new LMStudioEmbeddingFactory();

			it('should validate correct config', () => {
				expect(factory.validateConfig({ type: 'lmstudio' })).toBe(true);
				expect(factory.validateConfig({ type: 'openai' })).toBe(false);
				expect(factory.validateConfig(null)).toBe(false);
			});

			it('should return correct provider type', () => {
				expect(factory.getProviderType()).toBe('lmstudio');
			});

			it('should create embedder for valid config', async () => {
				const config: BackendConfig = {
					type: 'lmstudio',
					baseUrl: 'http://localhost:1234/v1',
					model: 'nomic-embed-text-v1.5',
				};
				const embedder = await factory.createEmbedder(config);
				expect(embedder).toBeDefined();
			});

			it('should reject invalid config type', async () => {
				const config = { type: 'openai' } as any;
				await expect(factory.createEmbedder(config)).rejects.toThrow(EmbeddingValidationError);
			});
		});
	});

	describe('createEmbedder', () => {
		it('should create embedders for all supported providers', async () => {
			const configs: BackendConfig[] = [
				{ type: 'openai', apiKey: 'test-key' },
				{ type: 'gemini', apiKey: 'test-key' },
				{ type: 'ollama', baseUrl: 'http://localhost:11434' },
				{ type: 'voyage', apiKey: 'test-key' },
				{ type: 'qwen', apiKey: 'test-key' },
				{ type: 'aws-bedrock', region: 'us-east-1' },
				{ type: 'lmstudio', baseUrl: 'http://localhost:1234/v1' },
			];

			for (const config of configs) {
				const embedder = await createEmbedder(config);
				expect(embedder).toBeDefined();
				expect(embedder.getConfig().type).toBe(config.type);
			}
		});

		it('should throw error for unsupported provider', async () => {
			const config = { type: 'unsupported' } as any;
			await expect(createEmbedder(config)).rejects.toThrow(EmbeddingValidationError);
		});
	});

	describe('createEmbedderFromEnv', () => {
		it('should create OpenAI embedder when OPENAI_API_KEY is set', async () => {
			process.env.OPENAI_API_KEY = 'test-openai-key';

			const result = await createEmbedderFromEnv();

			expect(result).toBeDefined();
			expect(result!.info.provider).toBe('openai');
			expect(result!.embedder).toBeDefined();
		});

		it('should create Gemini embedder when GEMINI_API_KEY is set', async () => {
			process.env.GEMINI_API_KEY = 'test-gemini-key';

			const result = await createEmbedderFromEnv();

			expect(result).toBeDefined();
			expect(result!.info.provider).toBe('gemini');
			expect(result!.embedder).toBeDefined();
		});

		it('should create Ollama embedder when OLLAMA_BASE_URL is set', async () => {
			process.env.OLLAMA_BASE_URL = 'http://localhost:11434';

			const result = await createEmbedderFromEnv();

			expect(result).toBeDefined();
			expect(result!.info.provider).toBe('ollama');
			expect(result!.embedder).toBeDefined();
		});

		it('should create LM Studio embedder when LMSTUDIO_BASE_URL is set', async () => {
			process.env.LMSTUDIO_BASE_URL = 'http://localhost:1234/v1';

			const result = await createEmbedderFromEnv();

			expect(result).toBeDefined();
			expect(result!.info.provider).toBe('lmstudio');
			expect(result!.embedder).toBeDefined();
		});

		it('should create Qwen embedder when QWEN_API_KEY is set', async () => {
			process.env.QWEN_API_KEY = 'test-qwen-key';

			const result = await createEmbedderFromEnv();

			expect(result).toBeDefined();
			expect(result!.info.provider).toBe('qwen');
			expect(result!.embedder).toBeDefined();
		});

		it('should create AWS Bedrock embedder when AWS credentials are set', async () => {
			process.env.AWS_ACCESS_KEY_ID = 'test-access-key';
			process.env.AWS_SECRET_ACCESS_KEY = 'test-secret-key';

			const result = await createEmbedderFromEnv();

			expect(result).toBeDefined();
			expect(result!.info.provider).toBe('aws-bedrock');
			expect(result!.embedder).toBeDefined();
		});

		it('should return null when no environment configuration is found', async () => {
			const result = await createEmbedderFromEnv();
			expect(result).toBeNull();
		});

		it('should prioritize OpenAI over other providers', async () => {
			process.env.OPENAI_API_KEY = 'test-openai-key';
			process.env.GEMINI_API_KEY = 'test-gemini-key';
			process.env.OLLAMA_BASE_URL = 'http://localhost:11434';

			const result = await createEmbedderFromEnv();

			expect(result).toBeDefined();
			expect(result!.info.provider).toBe('openai');
		});
	});

	describe('validateEmbeddingConfiguration', () => {
		it('should validate correct configurations', () => {
			const validConfigs = [
				{ type: 'openai', apiKey: 'test-key' },
				{ type: 'gemini', apiKey: 'test-key' },
				{ type: 'ollama', baseUrl: 'http://localhost:11434' },
				{ type: 'voyage', apiKey: 'test-key' },
				{ type: 'qwen', apiKey: 'test-key' },
				{ type: 'aws-bedrock', region: 'us-east-1' },
				{ type: 'lmstudio', baseUrl: 'http://localhost:1234/v1' },
			];

			validConfigs.forEach(config => {
				expect(validateEmbeddingConfiguration(config)).toBe(true);
			});
		});

		it('should reject invalid configurations', () => {
			const invalidConfigs = [
				null,
				undefined,
				'not an object',
				{},
				{ type: 'unsupported' },
				{ provider: 'openai' }, // Wrong property name
			];

			invalidConfigs.forEach(config => {
				expect(validateEmbeddingConfiguration(config)).toBe(false);
			});
		});
	});

	describe('Error Handling', () => {
		it('should handle factory creation errors gracefully', async () => {
			// Mock a factory that throws during embedder creation
			const mockFactory = {
				createEmbedder: vi.fn().mockRejectedValue(new Error('Creation failed')),
				validateConfig: vi.fn().mockReturnValue(true),
				getProviderType: vi.fn().mockReturnValue('mock'),
			};

			EMBEDDING_FACTORIES.set('mock', mockFactory);

			const config = { type: 'mock' } as any;
			await expect(createEmbedder(config)).rejects.toThrow('Creation failed');

			// Clean up
			EMBEDDING_FACTORIES.delete('mock');
		});

		it('should handle environment parsing errors gracefully', async () => {
			// Clear any existing environment variables that might interfere
			delete process.env.OPENAI_API_KEY;
			delete process.env.GEMINI_API_KEY;
			delete process.env.OLLAMA_BASE_URL;
			delete process.env.LMSTUDIO_BASE_URL;

			// Test with no environment variables - should return null
			const result = await createEmbedderFromEnv();
			expect(result).toBeNull();
		});
	});
});

/**
 * LM Studio Embedding Backend Tests
 *
 * Tests for the LM Studio embedding implementation including unit tests
 * for embedding generation, error handling, and configuration validation.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { LMStudioEmbedder } from '../lmstudio.js';
import type { LMStudioEmbeddingConfig } from '../types.js';
import {
	EmbeddingConnectionError,
	EmbeddingValidationError,
	EmbeddingDimensionError,
} from '../types.js';

// Mock OpenAI client
const mockOpenAI = {
	embeddings: {
		create: vi.fn(),
	},
};

vi.mock('openai', () => ({
	default: vi.fn(() => mockOpenAI),
}));

describe('LMStudioEmbedder', () => {
	let embedder: LMStudioEmbedder;
	let config: LMStudioEmbeddingConfig;

	beforeEach(() => {
		config = {
			type: 'lmstudio',
			baseUrl: 'http://localhost:1234/v1',
			model: 'nomic-embed-text-v1.5',
			timeout: 30000,
			maxRetries: 3,
		};
		embedder = new LMStudioEmbedder(config);
		vi.clearAllMocks();
	});

	afterEach(() => {
		vi.resetAllMocks();
	});

	describe('constructor', () => {
		it('should initialize with default configuration', () => {
			const defaultConfig: LMStudioEmbeddingConfig = {
				type: 'lmstudio',
			};
			const defaultEmbedder = new LMStudioEmbedder(defaultConfig);

			expect(defaultEmbedder.getDimension()).toBe(768); // Default for nomic-embed-text-v1.5
			const config = defaultEmbedder.getConfig();
			expect(config.type).toBe('lmstudio');
			// Other properties may have different defaults or be undefined in constructor
		});

		it('should use custom configuration', () => {
			const customConfig: LMStudioEmbeddingConfig = {
				type: 'lmstudio',
				baseUrl: 'http://localhost:8080/v1',
				model: 'bge-large',
				dimensions: 1024,
				timeout: 60000,
				maxRetries: 5,
			};
			const customEmbedder = new LMStudioEmbedder(customConfig);

			expect(customEmbedder.getDimension()).toBe(1024);
			expect(customEmbedder.getConfig()).toMatchObject(customConfig);
		});

		it('should set dimensions based on known models', () => {
			const configs = [
				{ model: 'nomic-embed-text-v1.5', expectedDimension: 768 },
				{ model: 'bge-large', expectedDimension: 1024 },
				{ model: 'bge-base', expectedDimension: 768 },
				{ model: 'bge-small', expectedDimension: 384 },
				{ model: 'all-minilm', expectedDimension: 384 },
				{ model: 'unknown-model', expectedDimension: 768 }, // Default
			];

			configs.forEach(({ model, expectedDimension }) => {
				const testConfig: LMStudioEmbeddingConfig = { type: 'lmstudio', model };
				const testEmbedder = new LMStudioEmbedder(testConfig);
				expect(testEmbedder.getDimension()).toBe(expectedDimension);
			});
		});
	});

	describe('embed', () => {
		it('should successfully create single embedding', async () => {
			const mockEmbedding = Array.from({ length: 768 }, () => Math.random());
			mockOpenAI.embeddings.create.mockResolvedValue({
				data: [{ embedding: mockEmbedding }],
			});

			const result = await embedder.embed('test text');

			expect(result).toEqual(mockEmbedding);
			expect(mockOpenAI.embeddings.create).toHaveBeenCalledWith({
				model: 'nomic-embed-text-v1.5',
				input: 'test text',
			});
		});

		it('should handle text with newlines', async () => {
			const mockEmbedding = Array.from({ length: 768 }, () => Math.random());
			mockOpenAI.embeddings.create.mockResolvedValue({
				data: [{ embedding: mockEmbedding }],
			});

			const result = await embedder.embed('test\ntext\nwith\nnewlines');

			expect(result).toEqual(mockEmbedding);
			expect(mockOpenAI.embeddings.create).toHaveBeenCalledWith({
				model: 'nomic-embed-text-v1.5',
				input: 'test text with newlines', // Newlines replaced with spaces
			});
		});

		it('should handle custom dimensions', async () => {
			const customConfig: LMStudioEmbeddingConfig = {
				type: 'lmstudio',
				model: 'nomic-embed-text-v1.5',
				dimensions: 512,
			};
			const customEmbedder = new LMStudioEmbedder(customConfig);

			const mockEmbedding = Array.from({ length: 512 }, () => Math.random());
			mockOpenAI.embeddings.create.mockResolvedValue({
				data: [{ embedding: mockEmbedding }],
			});

			const result = await customEmbedder.embed('test text');

			expect(result).toEqual(mockEmbedding);
			expect(mockOpenAI.embeddings.create).toHaveBeenCalledWith({
				model: 'nomic-embed-text-v1.5',
				input: 'test text',
				dimensions: 512,
			});
		});

		it('should validate input text', async () => {
			// Empty text
			await expect(embedder.embed('')).rejects.toThrow(EmbeddingValidationError);

			// Text too long
			const longText = 'a'.repeat(40000);
			await expect(embedder.embed(longText)).rejects.toThrow(EmbeddingValidationError);
		});

		it('should validate embedding dimensions', async () => {
			const wrongSizeEmbedding = Array.from({ length: 512 }, () => Math.random());
			mockOpenAI.embeddings.create.mockResolvedValue({
				data: [{ embedding: wrongSizeEmbedding }],
			});

			await expect(embedder.embed('test text')).rejects.toThrow(EmbeddingDimensionError);
		});

		it('should handle API errors', async () => {
			const apiError = {
				status: 404,
				message: 'Model not found',
			};
			mockOpenAI.embeddings.create.mockRejectedValue(apiError);

			await expect(embedder.embed('test text')).rejects.toThrow(EmbeddingConnectionError);
		});

		it(
			'should handle connection errors',
			async () => {
				const connectionError = new Error('ECONNREFUSED');
				mockOpenAI.embeddings.create.mockRejectedValue(connectionError);

				await expect(embedder.embed('test text')).rejects.toThrow(EmbeddingConnectionError);
			},
			{ timeout: 1000 }
		);

		it('should retry on retryable errors', async () => {
			const retriableError = { status: 500, message: 'Internal server error' };
			const mockEmbedding = Array.from({ length: 768 }, () => Math.random());

			mockOpenAI.embeddings.create
				.mockRejectedValueOnce(retriableError)
				.mockRejectedValueOnce(retriableError)
				.mockResolvedValueOnce({
					data: [{ embedding: mockEmbedding }],
				});

			const result = await embedder.embed('test text');

			expect(result).toHaveLength(768);
			expect(mockOpenAI.embeddings.create).toHaveBeenCalledTimes(3);
		});
	});

	describe('embedBatch', () => {
		it('should successfully create batch embeddings', async () => {
			const mockEmbeddings = [
				Array.from({ length: 768 }, () => Math.random()),
				Array.from({ length: 768 }, () => Math.random()),
			];
			mockOpenAI.embeddings.create.mockResolvedValue({
				data: mockEmbeddings.map(embedding => ({ embedding })),
			});

			const result = await embedder.embedBatch(['text 1', 'text 2']);

			expect(result).toEqual(mockEmbeddings);
			expect(mockOpenAI.embeddings.create).toHaveBeenCalledWith({
				model: 'nomic-embed-text-v1.5',
				input: ['text 1', 'text 2'],
			});
		});

		it('should handle batch with newlines', async () => {
			const mockEmbeddings = [
				Array.from({ length: 768 }, () => Math.random()),
				Array.from({ length: 768 }, () => Math.random()),
			];
			mockOpenAI.embeddings.create.mockResolvedValue({
				data: mockEmbeddings.map(embedding => ({ embedding })),
			});

			const result = await embedder.embedBatch(['text\n1', 'text\n2']);

			expect(result).toEqual(mockEmbeddings);
			expect(mockOpenAI.embeddings.create).toHaveBeenCalledWith({
				model: 'nomic-embed-text-v1.5',
				input: ['text 1', 'text 2'], // Newlines replaced
			});
		});

		it('should validate batch input', async () => {
			// Empty array
			await expect(embedder.embedBatch([])).rejects.toThrow(EmbeddingValidationError);

			// Array too large
			const largeBatch = Array.from({ length: 3000 }, (_, i) => `text ${i}`);
			await expect(embedder.embedBatch(largeBatch)).rejects.toThrow(EmbeddingValidationError);

			// Invalid text in batch
			await expect(embedder.embedBatch(['valid text', ''])).rejects.toThrow(
				EmbeddingValidationError
			);
		});
	});

	describe('isHealthy', () => {
		it('should return true when embedding succeeds', async () => {
			const mockEmbedding = Array.from({ length: 768 }, () => Math.random());
			mockOpenAI.embeddings.create.mockResolvedValue({
				data: [{ embedding: mockEmbedding }],
			});

			const healthy = await embedder.isHealthy();

			expect(healthy).toBe(true);
			expect(mockOpenAI.embeddings.create).toHaveBeenCalledWith({
				model: 'nomic-embed-text-v1.5',
				input: 'health check',
			});
		});

		it(
			'should return false when embedding fails',
			async () => {
				mockOpenAI.embeddings.create.mockRejectedValue(new Error('Connection failed'));

				const healthy = await embedder.isHealthy();

				expect(healthy).toBe(false);
			},
			{ timeout: 1000 }
		);
	});

	describe('disconnect', () => {
		it('should disconnect without errors', async () => {
			await expect(embedder.disconnect()).resolves.toBeUndefined();
		});
	});

	describe('error handling', () => {
		it('should handle different HTTP status codes', async () => {
			// Test just the 400 status case to debug
			const mockError = new Error('HTTP 400 error') as Error & { status?: number };
			mockError.status = 400;
			console.log('Mock error object:', mockError);
			console.log('Mock error has status:', 'status' in mockError);
			console.log('Mock error status:', mockError.status);

			mockOpenAI.embeddings.create.mockRejectedValueOnce(mockError);

			try {
				await embedder.embed('test');
			} catch (error) {
				if (error && typeof error === 'object' && 'constructor' in error) {
					console.log('Error type:', (error as any).constructor.name);
				}
				if (error && typeof error === 'object' && 'message' in error) {
					console.log('Error message:', (error as any).message);
				}
				expect(error).toBeInstanceOf(EmbeddingValidationError);
			}
		});

		it(
			'should provide helpful error messages for connection issues',
			async () => {
				const connectionError = new Error('fetch failed');
				mockOpenAI.embeddings.create.mockRejectedValue(connectionError);

				try {
					await embedder.embed('test');
				} catch (error) {
					expect(error).toBeInstanceOf(EmbeddingConnectionError);
					expect((error as EmbeddingConnectionError).message).toContain(
						'Cannot connect to LM Studio server'
					);
					expect((error as EmbeddingConnectionError).message).toContain('localhost:1234/v1');
				}
			},
			{ timeout: 1000 }
		);
	});

	describe('configuration', () => {
		it('should return immutable config copy', () => {
			const originalConfig = embedder.getConfig();
			originalConfig.model = 'modified';

			const newConfig = embedder.getConfig();
			expect(newConfig.model).toBe('nomic-embed-text-v1.5');
		});

		it('should handle missing response data', async () => {
			mockOpenAI.embeddings.create.mockResolvedValue({
				data: null,
			});

			await expect(embedder.embed('test')).rejects.toThrow('did not return a valid embedding');
		});

		it('should handle malformed response', async () => {
			mockOpenAI.embeddings.create.mockResolvedValue({
				data: [{}], // Missing embedding
			});

			await expect(embedder.embed('test')).rejects.toThrow('did not return a valid embedding');
		});
	});
});

/**
 * AWS Bedrock Embedding Backend
 *
 * Implementation of the AWS Bedrock embedding provider supporting Amazon Titan
 * and Cohere embedding models through the Bedrock Runtime API.
 */

import {
	BedrockRuntimeClient,
	BedrockRuntimeClientConfig,
	InvokeModelCommand,
} from '@aws-sdk/client-bedrock-runtime';
import { TextDecoder } from 'util';
import type { Embedder, EmbeddingConfig } from './types.js';
import { EmbeddingError, EmbeddingValidationError } from './types.js';

/**
 * AWS Bedrock-specific configuration interface
 */
export interface AWSBedrockEmbeddingConfig extends EmbeddingConfig {
	type: 'aws-bedrock';
	model?: 'amazon.titan-embed-text-v2:0' | 'cohere.embed-english-v3';
	region?: string;
	accessKeyId?: string;
	secretAccessKey?: string;
	sessionToken?: string;
	dimensions?: 1024 | 512 | 256; // For Titan V2
}

/**
 * AWS Bedrock embedding provider implementation
 */
export class AWSBedrockEmbedder implements Embedder {
	private readonly config: AWSBedrockEmbeddingConfig;
	private readonly client: BedrockRuntimeClient;
	private readonly model: string;
	private readonly dimensions: number;

	constructor(config: AWSBedrockEmbeddingConfig) {
		this.config = config;
		this.model = config.model || 'amazon.titan-embed-text-v2:0';
		this.dimensions = config.dimensions || 1024;

		// Configure AWS Bedrock client
		const clientConfig: BedrockRuntimeClientConfig = {
			region: config.region || process.env.AWS_DEFAULT_REGION || 'us-east-1',
		};

		// Add credentials if provided
		const accessKeyId = config.accessKeyId || process.env.AWS_ACCESS_KEY_ID;
		const secretAccessKey = config.secretAccessKey || process.env.AWS_SECRET_ACCESS_KEY;
		const sessionToken = config.sessionToken || process.env.AWS_SESSION_TOKEN;

		if (accessKeyId && secretAccessKey) {
			clientConfig.credentials = {
				accessKeyId,
				secretAccessKey,
				...(sessionToken && { sessionToken }),
			};
		}

		this.client = new BedrockRuntimeClient(clientConfig);
	}

	async embed(text: string): Promise<number[]> {
		try {
			const body = this.buildRequestBody(text);
			const command = new InvokeModelCommand({
				modelId: this.model,
				body: JSON.stringify(body),
				contentType: 'application/json',
				accept: 'application/json',
			});

			const response = await this.client.send(command);
			const responseBody = JSON.parse(new TextDecoder().decode(response.body));

			return this.extractEmbedding(responseBody);
		} catch (error) {
			if (error instanceof EmbeddingError) {
				throw error;
			}
			throw new EmbeddingError(`Failed to generate AWS Bedrock embedding: ${error}`);
		}
	}

	async embedBatch(texts: string[]): Promise<number[][]> {
		try {
			// AWS Bedrock typically processes one text at a time, so we batch manually
			const results: number[][] = [];

			for (const text of texts) {
				const embedding = await this.embed(text);
				results.push(embedding);
			}

			return results;
		} catch (error) {
			if (error instanceof EmbeddingError) {
				throw error;
			}
			throw new EmbeddingError(`Failed to generate AWS Bedrock batch embeddings: ${error}`);
		}
	}

	getDimension(): number {
		return this.dimensions;
	}

	getConfig(): AWSBedrockEmbeddingConfig {
		return { ...this.config };
	}

	async isHealthy(): Promise<boolean> {
		try {
			await this.embed('test');
			return true;
		} catch {
			return false;
		}
	}

	async disconnect(): Promise<void> {
		// AWS SDK handles connection management automatically
		this.client.destroy();
	}

	private buildRequestBody(text: string): any {
		if (this.model.startsWith('amazon.titan-embed')) {
			return {
				inputText: text,
				dimensions: this.dimensions,
			};
		} else if (this.model.startsWith('cohere.embed')) {
			return {
				texts: [text],
				input_type: 'search_document',
				embedding_types: ['float'],
			};
		}

		throw new EmbeddingValidationError(`Unsupported AWS Bedrock model: ${this.model}`);
	}

	private extractEmbedding(response: any): number[] {
		if (this.model.startsWith('amazon.titan-embed')) {
			if (!response.embedding) {
				throw new EmbeddingError('No embedding data received from AWS Bedrock Titan API');
			}
			return response.embedding;
		} else if (this.model.startsWith('cohere.embed')) {
			if (!response.embeddings || response.embeddings.length === 0) {
				throw new EmbeddingError('No embedding data received from AWS Bedrock Cohere API');
			}
			return response.embeddings[0].values;
		}

		throw new EmbeddingError(`Unknown response format for model: ${this.model}`);
	}
}

/**
 * Factory function to create an AWS Bedrock embedder
 */
export function createAWSBedrockEmbedder(config: AWSBedrockEmbeddingConfig): AWSBedrockEmbedder {
	return new AWSBedrockEmbedder(config);
}

/**
 * Gemini Embedding Backend
 *
 * Implementation of the Embedder interface for Google's Gemini embedding models.
 * Supports the latest gemini-embedding-001 model with configurable dimensions.
 *
 * @module embedding/backend/gemini
 */

import { logger } from '../../../logger/index.js';
import {
	type Embedder,
	type GeminiEmbeddingConfig,
	type EmbeddingConfig,
	EmbeddingError,
	EmbeddingConnectionError,
	EmbeddingRateLimitError,
	EmbeddingDimensionError,
	EmbeddingValidationError,
} from './types.js';
import { LOG_PREFIXES, VALIDATION_LIMITS, RETRY_CONFIG, HTTP_STATUS } from '../constants.js';

/**
 * Gemini API response for text embedding
 */
interface GeminiEmbeddingResponse {
	embedding: {
		values: number[];
	};
}

/**
 * Gemini API error response
 */
interface GeminiErrorResponse {
	error: {
		code: number;
		message: string;
		status?: string;
	};
}

/**
 * Gemini Embedder Implementation
 *
 * Provides embedding functionality using Google's Gemini embedding models.
 * Supports configurable dimensions and comprehensive error handling.
 */
export class GeminiEmbedder implements Embedder {
	private readonly config: GeminiEmbeddingConfig;
	private readonly baseUrl: string;
	private readonly apiKey: string;
	private readonly model: string;
	private readonly dimension: number;
	private readonly timeout: number;
	private readonly maxRetries: number;

	constructor(config: GeminiEmbeddingConfig) {
		this.config = config;
		this.apiKey = config.apiKey || '';
		this.model = config.model || 'gemini-embedding-001';
		this.dimension = config.dimensions || 1536; // Default to 1536 for compatibility
		this.timeout = config.timeout || 30000;
		this.maxRetries = config.maxRetries || 3;
		this.baseUrl = config.baseUrl || 'https://generativelanguage.googleapis.com/v1beta';

		logger.debug(`${LOG_PREFIXES.EMBEDDING} Gemini embedder initialized`, {
			model: this.model,
			dimension: this.dimension,
			baseUrl: this.baseUrl,
		});
	}

	async embed(text: string): Promise<number[]> {
		if (!text || text.trim().length === 0) {
			throw new EmbeddingValidationError('Text cannot be empty');
		}

		if (text.length > VALIDATION_LIMITS.MAX_TEXT_LENGTH) {
			throw new EmbeddingValidationError(
				`Text length ${text.length} exceeds maximum of ${VALIDATION_LIMITS.MAX_TEXT_LENGTH} characters`
			);
		}

		const startTime = Date.now();

		try {
			logger.debug(`${LOG_PREFIXES.EMBEDDING} Starting Gemini embedding`, {
				textLength: text.length,
				model: this.model,
			});

			const response = await this.makeRequest('/models/' + this.model + ':embedContent', {
				content: {
					parts: [{ text }],
				},
				outputDimensionality: this.dimension,
			});

			const embedding = response.embedding.values;
			const processingTime = Date.now() - startTime;

			if (embedding.length !== this.dimension) {
				throw new EmbeddingDimensionError(
					`Expected ${this.dimension} dimensions, got ${embedding.length}`,
					this.dimension,
					embedding.length,
					'gemini'
				);
			}

			logger.debug(`${LOG_PREFIXES.EMBEDDING} Gemini embedding completed`, {
				dimension: embedding.length,
				processingTime,
			});

			return embedding;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.EMBEDDING} Gemini embedding failed`, {
				error: error instanceof Error ? error.message : String(error),
				errorType: error?.constructor?.name,
				stack: error instanceof Error ? error.stack : undefined,
				processingTime,
			});

			if (error instanceof EmbeddingError) {
				throw error;
			}

			throw new EmbeddingError(
				`Gemini embedding failed: ${error instanceof Error ? error.message : String(error)}`,
				'gemini',
				error instanceof Error ? error : undefined
			);
		}
	}

	async embedBatch(texts: string[]): Promise<number[][]> {
		if (!texts || texts.length === 0) {
			throw new EmbeddingValidationError('Text array cannot be empty');
		}

		if (texts.length > VALIDATION_LIMITS.MAX_BATCH_SIZE) {
			throw new EmbeddingValidationError(
				`Batch size ${texts.length} exceeds maximum of ${VALIDATION_LIMITS.MAX_BATCH_SIZE}`
			);
		}

		// Validate individual texts
		for (let i = 0; i < texts.length; i++) {
			const text = texts[i];
			if (!text || text.trim().length === 0) {
				throw new EmbeddingValidationError(`Text at index ${i} cannot be empty`);
			}
			if (text.length > VALIDATION_LIMITS.MAX_TEXT_LENGTH) {
				throw new EmbeddingValidationError(
					`Text at index ${i} length ${text.length} exceeds maximum of ${VALIDATION_LIMITS.MAX_TEXT_LENGTH} characters`
				);
			}
		}

		const startTime = Date.now();

		try {
			logger.debug(`${LOG_PREFIXES.EMBEDDING} Starting Gemini batch embedding`, {
				batchSize: texts.length,
				model: this.model,
			});

			// Gemini API doesn't support true batch embedding, so we'll process sequentially
			// In a production implementation, you might want to parallelize with rate limiting
			const embeddings: number[][] = [];

			for (const text of texts) {
				const embedding = await this.embed(text);
				embeddings.push(embedding);
			}

			const processingTime = Date.now() - startTime;

			logger.debug(`${LOG_PREFIXES.EMBEDDING} Gemini batch embedding completed`, {
				batchSize: embeddings.length,
				dimension: embeddings[0]?.length,
				processingTime,
			});

			return embeddings;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.EMBEDDING} Gemini batch embedding failed`, {
				error: error instanceof Error ? error.message : String(error),
				batchSize: texts.length,
				processingTime,
			});

			if (error instanceof EmbeddingError) {
				throw error;
			}

			throw new EmbeddingError(
				`Gemini batch embedding failed: ${error instanceof Error ? error.message : String(error)}`,
				'gemini',
				error instanceof Error ? error : undefined
			);
		}
	}

	async isHealthy(): Promise<boolean> {
		try {
			logger.debug(`${LOG_PREFIXES.HEALTH} Checking Gemini embedder health`);

			// Test with a simple text
			await this.embed('health check');

			logger.debug(`${LOG_PREFIXES.HEALTH} Gemini embedder is healthy`);
			return true;
		} catch (error) {
			logger.warn(`${LOG_PREFIXES.HEALTH} Gemini embedder health check failed`, {
				error: error instanceof Error ? error.message : String(error),
			});
			return false;
		}
	}

	getDimension(): number {
		return this.dimension;
	}

	getModel(): string {
		return this.model;
	}

	getProvider(): string {
		return 'gemini';
	}

	getConfig(): EmbeddingConfig {
		return this.config;
	}

	async disconnect(): Promise<void> {
		// Gemini API is stateless, no cleanup needed
		logger.debug(`${LOG_PREFIXES.EMBEDDING} Gemini embedder disconnected`);
	}

	/**
	 * Make authenticated request to Gemini API
	 */
	private async makeRequest(endpoint: string, body: any): Promise<GeminiEmbeddingResponse> {
		const url = `${this.baseUrl}${endpoint}?key=${this.apiKey}`;

		let lastError: Error | undefined;
		let delay: number = RETRY_CONFIG.INITIAL_DELAY;

		for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
			try {
				logger.silly(`${LOG_PREFIXES.EMBEDDING} Making Gemini API request`, {
					attempt: attempt + 1,
					maxRetries: this.maxRetries + 1,
					endpoint,
				});

				const controller = new AbortController();
				const timeoutId = setTimeout(() => controller.abort(), this.timeout);

				const response = await globalThis.fetch(url, {
					method: 'POST',
					headers: {
						'Content-Type': 'application/json',
					},
					body: JSON.stringify(body),
					signal: controller.signal,
				});

				clearTimeout(timeoutId);

				if (!response.ok) {
					const errorData = (await response.json().catch(() => ({}))) as GeminiErrorResponse;
					const errorMessage = errorData.error?.message || `HTTP ${response.status}`;

					switch (response.status) {
						case HTTP_STATUS.UNAUTHORIZED:
							throw new EmbeddingError(`Invalid Gemini API key: ${errorMessage}`, 'gemini');
						case HTTP_STATUS.FORBIDDEN:
							throw new EmbeddingError(`Gemini API access forbidden: ${errorMessage}`, 'gemini');
						case HTTP_STATUS.TOO_MANY_REQUESTS:
							throw new EmbeddingRateLimitError(`Gemini API rate limit exceeded: ${errorMessage}`);
						case HTTP_STATUS.BAD_REQUEST:
							throw new EmbeddingValidationError(`Invalid request to Gemini API: ${errorMessage}`);
						default:
							throw new EmbeddingConnectionError(`Gemini API error: ${errorMessage}`);
					}
				}

				const data = (await response.json()) as GeminiEmbeddingResponse;

				if (!data.embedding?.values) {
					throw new EmbeddingError('Invalid response format from Gemini API', 'gemini');
				}

				return data;
			} catch (error) {
				lastError = error instanceof Error ? error : new Error(String(error));

				// Don't retry on validation errors or auth errors
				if (error instanceof EmbeddingValidationError || error instanceof EmbeddingError) {
					throw error;
				}

				// If this was the last attempt, throw the error
				if (attempt === this.maxRetries) {
					break;
				}

				// Wait before retrying
				logger.debug(`${LOG_PREFIXES.EMBEDDING} Retrying Gemini request in ${delay}ms`, {
					attempt: attempt + 1,
					error: lastError.message,
				});

				await new Promise(resolve => setTimeout(resolve, delay));
				delay = Math.min(delay * RETRY_CONFIG.BACKOFF_MULTIPLIER, 60000);
			}
		}

		throw new EmbeddingConnectionError(
			`Failed to connect to Gemini API after ${this.maxRetries + 1} attempts: ${lastError?.message}`,
			'gemini',
			lastError
		);
	}
}

/**
 * Embedding Backend Module
 *
 * Exports all embedding backend types and implementations.
 * Provides a unified interface for different embedding providers.
 *
 * @module embedding/backend
 */

// Export core types
export type {
	Embedder,
	EmbeddingConfig,
	BackendConfig,
	OpenAIEmbeddingConfig,
	GeminiEmbeddingConfig,
	OllamaEmbeddingConfig,
	VoyageEmbeddingConfig,
	QwenEmbeddingConfig,
	AWSBedrockEmbeddingConfig,
	LMStudioEmbeddingConfig,
	EmbeddingResult,
	BatchEmbeddingResult,
} from './types.js';

// Export error classes
export {
	EmbeddingError,
	EmbeddingConnectionError,
	EmbeddingDimensionError,
	EmbeddingRateLimitError,
	EmbeddingQuotaError,
	EmbeddingValidationError,
} from './types.js';

// Export backend implementations
export { OpenAIEmbedder } from './openai.js';
export { GeminiEmbedder } from './gemini.js';
export { OllamaEmbedder } from './ollama.js';
export { VoyageEmbedder } from './voyage.js';
export { QwenEmbedder } from './qwen.js';
export { AWSBedrockEmbedder } from './aws.js';
export { LMStudioEmbedder } from './lmstudio.js';

/**
 * LM Studio Embedding Backend
 *
 * Implementation of the Embedder interface for LM Studio's embedding services.
 * Supports LM Studio's OpenAI-compatible embedding API with local models
 * like nomic-embed-text-v1.5 and other BERT-based models in GGUF format.
 *
 * @module embedding/backend/lmstudio
 */

import OpenAI from 'openai';
import { logger } from '../../../logger/index.js';
import {
	Embedder,
	EmbeddingConfig,
	EmbeddingConnectionError,
	EmbeddingRateLimitError,
	EmbeddingValidationError,
	EmbeddingError,
	EmbeddingDimensionError,
} from './types.js';
import { VALIDATION_LIMITS, LOG_PREFIXES, HTTP_STATUS } from '../constants.js';

/**
 * LM Studio-specific embedding configuration
 */
export interface LMStudioEmbeddingConfig extends EmbeddingConfig {
	type: 'lmstudio';
	model?: 'nomic-embed-text-v1.5' | 'text-embedding-nomic-embed-text-v1.5' | string;
	/** Base URL for LM Studio server, defaults to http://localhost:1234/v1 */
	baseUrl?: string;
	/** Custom dimensions if supported by the model */
	dimensions?: number;
}

/**
 * Default dimension mappings for common LM Studio embedding models
 */
const LM_STUDIO_MODEL_DIMENSIONS: Record<string, number> = {
	'nomic-embed-text-v1.5': 768,
	'text-embedding-nomic-embed-text-v1.5': 768,
	'all-minilm': 384,
	'bge-large': 1024,
	'bge-base': 768,
	'bge-small': 384,
} as const;

/**
 * LM Studio Embedder Implementation
 *
 * Provides embedding functionality using LM Studio's local embedding API.
 * Supports OpenAI-compatible endpoints with local BERT models in GGUF format.
 */
export class LMStudioEmbedder implements Embedder {
	private openai: OpenAI;
	private readonly config: LMStudioEmbeddingConfig;
	private readonly model: string;
	private readonly dimension: number;

	constructor(config: LMStudioEmbeddingConfig) {
		this.config = config;
		this.model = config.model || 'nomic-embed-text-v1.5';

		// Initialize OpenAI client pointing to LM Studio
		this.openai = new OpenAI({
			apiKey: 'lm-studio', // LM Studio uses this as a placeholder
			baseURL: config.baseUrl || 'http://localhost:1234/v1',
			timeout: config.timeout || 30000,
			maxRetries: config.maxRetries || 3,
		});

		// Set dimension based on model and config
		this.dimension = config.dimensions || LM_STUDIO_MODEL_DIMENSIONS[this.model] || 768; // Default to 768 for most BERT-based models

		// Reduce retry delays for testing
		this.config.maxRetries = config.maxRetries || 3;
		this.config.timeout = config.timeout || 30000;

		logger.debug(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Initialized LM Studio embedder`, {
			model: this.model,
			dimension: this.dimension,
			baseUrl: config.baseUrl || 'http://localhost:1234/v1',
		});
	}

	async embed(text: string): Promise<number[]> {
		const { model } = this;
		logger.silly(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Embedding single text`, {
			textLength: text.length,
			model: this.model,
		});

		// Validate input
		this.validateInput(text);

		const startTime = Date.now();

		try {
			// Clean text by replacing newlines with spaces (LM Studio recommendation)
			const cleanText = text.replace(/\n/g, ' ');

			const params: { model: string; input: string; dimensions?: number } = {
				model: this.model,
				input: cleanText,
			};

			if (this.config.dimensions !== undefined) {
				params.dimensions = this.config.dimensions;
			}

			const response = await this.createEmbeddingWithRetry(params);

			if (
				!response.data ||
				!Array.isArray(response.data) ||
				!response.data[0] ||
				!response.data[0].embedding
			) {
				throw new EmbeddingError('LM Studio API did not return a valid embedding', 'lmstudio');
			}

			const embedding = response.data[0].embedding;
			this.validateEmbeddingDimension(embedding);

			const processingTime = Date.now() - startTime;
			logger.debug(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Successfully created embedding`, {
				model,
				dimension: embedding.length,
				processingTime,
			});

			return embedding;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Failed to create embedding`, {
				error: error instanceof Error ? error.message : String(error),
				model: this.model,
				processingTime,
				textLength: text.length,
			});

			// Don't wrap if it's already an EmbeddingError
			if (error instanceof EmbeddingError) {
				throw error;
			}
			throw this.handleApiError(error);
		}
	}

	async embedBatch(texts: string[]): Promise<number[][]> {
		const { model } = this;
		logger.debug(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Embedding batch of texts`, {
			count: texts.length,
			model: this.model,
		});

		// Validate batch input
		this.validateBatchInput(texts);

		const startTime = Date.now();

		try {
			// Clean texts by replacing newlines with spaces
			const cleanTexts = texts.map(text => text.replace(/\n/g, ' '));

			const batchParams: { model: string; input: string[]; dimensions?: number } = {
				model: this.model,
				input: cleanTexts,
			};

			if (this.config.dimensions !== undefined) {
				batchParams.dimensions = this.config.dimensions;
			}

			const response = await this.createEmbeddingWithRetry(batchParams);
			const embeddings = response.data.map(item => item.embedding);

			// Validate all embeddings
			embeddings.forEach(this.validateEmbeddingDimension.bind(this));

			const processingTime = Date.now() - startTime;
			logger.debug(
				`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Successfully created batch embeddings`,
				{
					model,
					count: embeddings.length,
					processingTime,
				}
			);

			return embeddings;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Failed to create batch embeddings`, {
				error: error instanceof Error ? error.message : String(error),
				model,
				processingTime,
				count: texts.length,
			});

			// Don't wrap if it's already an EmbeddingError
			if (error instanceof EmbeddingError) {
				throw error;
			}
			throw this.handleApiError(error);
		}
	}

	getDimension(): number {
		return this.dimension;
	}

	getConfig(): LMStudioEmbeddingConfig {
		return { ...this.config };
	}

	async isHealthy(): Promise<boolean> {
		try {
			logger.silly(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Checking LM Studio embedder health`);

			// Try a simple embedding request with minimal text
			await this.embed('health check');

			logger.debug(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} LM Studio embedder is healthy`);
			return true;
		} catch (error) {
			logger.warn(
				`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} LM Studio embedder health check failed`,
				{
					error: error instanceof Error ? error.message : String(error),
					baseUrl: this.config.baseUrl || 'http://localhost:1234/v1',
				}
			);
			return false;
		}
	}

	async disconnect(): Promise<void> {
		logger.debug(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Disconnecting LM Studio embedder`);
		// LM Studio client doesn't require explicit cleanup
		// This is here for interface compliance and future extensibility
	}

	/**
	 * Create embedding with retry logic
	 */
	private async createEmbeddingWithRetry(params: {
		model: string;
		input: string | string[];
		dimensions?: number;
	}): Promise<OpenAI.Embeddings.CreateEmbeddingResponse> {
		let lastError: Error | undefined;
		let delay: number = 100; // Shorter delay for testing

		for (let attempt = 0; attempt <= this.config.maxRetries!; attempt++) {
			try {
				if (attempt > 0) {
					logger.debug(`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Retrying embedding request`, {
						attempt,
						delay,
						maxRetries: this.config.maxRetries,
					});

					// Wait before retry
					await new Promise(resolve => setTimeout(resolve, delay));

					// Calculate next delay with exponential backoff (shorter for testing)
					delay = Math.min(delay * 2, 500); // Max 500ms for testing
				}

				const response = await this.openai.embeddings.create(params);

				if (attempt > 0) {
					logger.info(
						`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Embedding request succeeded after retry`,
						{
							attempt,
							model: params.model,
						}
					);
				}

				return response;
			} catch (error) {
				lastError = error instanceof Error ? error : new Error(String(error));

				logger.debug(`Attempt ${attempt + 1} failed with error:`, {
					errorType:
						error && typeof error === 'object' && 'constructor' in error
							? (error as any).constructor.name
							: undefined,
					errorMessage:
						error && typeof error === 'object' && 'message' in error
							? (error as any).message
							: String(error),
					hasStatus: error && typeof error === 'object' && 'status' in error,
					status:
						error && typeof error === 'object' && 'status' in error
							? (error as any).status
							: 'none',
				});

				// Check if we should retry based on error type
				if (!this.shouldRetry(error, attempt)) {
					logger.debug(`Not retrying - error is not retryable`);
					break;
				}

				logger.warn(
					`${LOG_PREFIXES.LMSTUDIO || '[LMSTUDIO]'} Embedding request failed, will retry`,
					{
						attempt: attempt + 1,
						maxRetries: this.config.maxRetries,
						error: lastError.message,
						nextDelay: delay,
					}
				);
			}
		}

		// All retries exhausted
		if (lastError) {
			// Don't wrap the error again if it's already an EmbeddingError
			if (lastError instanceof EmbeddingError) {
				throw lastError;
			}
			throw this.handleApiError(lastError);
		}
		throw new EmbeddingError('Unknown error during embedding request', 'lmstudio');
	}

	/**
	 * Determine if an error is retryable
	 */
	private shouldRetry(error: unknown, attempt: number): boolean {
		if (attempt >= this.config.maxRetries!) {
			return false;
		}

		// Handle OpenAI API errors (LM Studio uses OpenAI-compatible format)
		if (error && typeof error === 'object' && 'status' in error) {
			const status = (error as any).status;

			// Retry on server errors and rate limits
			return [
				HTTP_STATUS.TOO_MANY_REQUESTS,
				HTTP_STATUS.INTERNAL_SERVER_ERROR,
				HTTP_STATUS.SERVICE_UNAVAILABLE,
			].includes(status);
		}

		// Retry on network errors (common with local servers)
		if (error instanceof Error) {
			const message = error.message.toLowerCase();
			return (
				message.includes('network') ||
				message.includes('timeout') ||
				message.includes('connection') ||
				message.includes('econnreset') ||
				message.includes('enotfound') ||
				message.includes('econnrefused') || // Common with local servers
				message.includes('fetch failed')
			);
		}

		return false;
	}

	/**
	 * Handle and categorize API errors
	 */
	private handleApiError(error: unknown): EmbeddingError {
		logger.debug(`handleApiError called with:`, {
			errorType: error?.constructor?.name,
			errorMessage: error instanceof Error ? error.message : String(error),
			hasStatus: error && typeof error === 'object' && 'status' in error,
			status:
				error && typeof error === 'object' && 'status' in error ? (error as any).status : 'none',
			errorKeys: error && typeof error === 'object' ? Object.keys(error as any) : [],
		});

		if (error && typeof error === 'object' && 'status' in error) {
			const apiError = error as any;
			const status = apiError.status;
			const message = apiError.message || String(error);

			logger.debug(`Handling API error with status ${status}: ${message}`);

			switch (status) {
				case HTTP_STATUS.UNAUTHORIZED:
					return new EmbeddingConnectionError(
						'LM Studio server rejected the request. Ensure the embedding model is loaded.',
						'lmstudio',
						apiError
					);

				case HTTP_STATUS.TOO_MANY_REQUESTS:
					return new EmbeddingRateLimitError(
						'LM Studio server is busy. Try again later.',
						undefined,
						'lmstudio',
						apiError
					);

				case HTTP_STATUS.BAD_REQUEST:
					return new EmbeddingValidationError(
						`LM Studio server rejected the request: ${message}`,
						'lmstudio',
						apiError
					);

				case HTTP_STATUS.NOT_FOUND:
					return new EmbeddingConnectionError(
						`LM Studio embedding model '${this.model}' not found. Ensure the model is loaded.`,
						'lmstudio',
						apiError
					);

				default:
					return new EmbeddingConnectionError(
						`LM Studio server error (${status}): ${message}`,
						'lmstudio',
						apiError
					);
			}
		}

		// Handle network and connection errors
		if (error instanceof Error) {
			const message = error.message.toLowerCase();

			if (message.includes('econnrefused') || message.includes('fetch failed')) {
				return new EmbeddingConnectionError(
					'Cannot connect to LM Studio server at ' +
						(this.config.baseUrl || 'http://localhost:1234/v1') +
						'. Ensure LM Studio is running and the embedding model is loaded.',
					'lmstudio',
					error
				);
			}

			return new EmbeddingConnectionError(error.message, 'lmstudio', error);
		}

		return new EmbeddingError(String(error), 'lmstudio');
	}

	/**
	 * Validate single text input
	 */
	private validateInput(text: string): void {
		if (!text || text.length < VALIDATION_LIMITS.MIN_TEXT_LENGTH) {
			throw new EmbeddingValidationError('Text input cannot be empty', 'lmstudio');
		}

		if (text.length > VALIDATION_LIMITS.MAX_TEXT_LENGTH) {
			throw new EmbeddingValidationError(
				`Text too long: ${text.length} characters exceeds limit of ${VALIDATION_LIMITS.MAX_TEXT_LENGTH}`,
				'lmstudio'
			);
		}
	}

	/**
	 * Validate batch input
	 */
	private validateBatchInput(texts: string[]): void {
		if (!Array.isArray(texts) || texts.length === 0) {
			throw new EmbeddingValidationError('Batch input must be a non-empty array', 'lmstudio');
		}

		if (texts.length > VALIDATION_LIMITS.MAX_BATCH_SIZE) {
			throw new EmbeddingValidationError(
				`Batch too large: ${texts.length} items exceeds limit of ${VALIDATION_LIMITS.MAX_BATCH_SIZE}`,
				'lmstudio'
			);
		}

		// Validate each text in the batch
		texts.forEach((text, index) => {
			try {
				this.validateInput(text);
			} catch (error) {
				if (error instanceof EmbeddingValidationError) {
					throw new EmbeddingValidationError(
						`Batch item ${index}: ${error.message}`,
						'lmstudio',
						error
					);
				}
				throw error;
			}
		});
	}

	/**
	 * Validate embedding dimension
	 */
	private validateEmbeddingDimension(embedding: number[]): void {
		if (embedding.length !== this.dimension) {
			throw new EmbeddingDimensionError(
				`Embedding dimension mismatch: expected ${this.dimension}, got ${embedding.length}`,
				this.dimension,
				embedding.length,
				'lmstudio'
			);
		}
	}
}

/**
 * Ollama Embedding Backend
 *
 * Implementation of the Embedder interface for Ollama's local embedding models.
 * Supports various open-source embedding models running locally via Ollama.
 *
 * @module embedding/backend/ollama
 */

import { logger } from '../../../logger/index.js';
import {
	type Embedder,
	type OllamaEmbeddingConfig,
	type EmbeddingConfig,
	EmbeddingError,
	EmbeddingConnectionError,
	EmbeddingValidationError,
} from './types.js';
import {
	LOG_PREFIXES,
	VALIDATION_LIMITS,
	RETRY_CONFIG,
	HTTP_STATUS,
	MODEL_DIMENSIONS,
} from '../constants.js';

/**
 * Ollama API response for text embedding
 */
interface OllamaEmbeddingResponse {
	embedding: number[];
}

/**
 * Ollama API error response
 */
interface OllamaErrorResponse {
	error: string;
}

/**
 * Ollama Embedder Implementation
 *
 * Provides embedding functionality using local Ollama embedding models.
 * Supports various open-source models like nomic-embed-text, all-minilm, etc.
 */
export class OllamaEmbedder implements Embedder {
	private readonly config: OllamaEmbeddingConfig;
	private readonly baseUrl: string;
	private readonly model: string;
	private readonly dimension: number;
	private readonly timeout: number;
	private readonly maxRetries: number;

	constructor(config: OllamaEmbeddingConfig) {
		this.config = config;
		this.model = config.model || 'nomic-embed-text';
		this.timeout = config.timeout || 30000;
		this.maxRetries = config.maxRetries || 3;

		// Normalize base URL for Ollama embedding service
		// Embeddings use /api/embeddings endpoint, so we need to remove /v1 suffix if present
		let baseUrl = config.baseUrl || 'http://localhost:11434';
		baseUrl = baseUrl.replace(/\/$/, ''); // Remove trailing slash

		// For Ollama embeddings, remove /v1 suffix if present since we use /api/embeddings endpoint
		if (baseUrl.endsWith('/v1')) {
			baseUrl = baseUrl.replace(/\/v1$/, '');
		}

		this.baseUrl = baseUrl;

		// Get dimension from model constants or use default
		this.dimension =
			config.dimensions || MODEL_DIMENSIONS[this.model as keyof typeof MODEL_DIMENSIONS] || 768;

		logger.debug(`${LOG_PREFIXES.EMBEDDING} Ollama embedder initialized`, {
			model: this.model,
			dimension: this.dimension,
			baseUrl: this.baseUrl,
		});
	}

	async embed(text: string): Promise<number[]> {
		if (!text || text.trim().length === 0) {
			throw new EmbeddingValidationError('Text cannot be empty');
		}

		if (text.length > VALIDATION_LIMITS.MAX_TEXT_LENGTH) {
			throw new EmbeddingValidationError(
				`Text length ${text.length} exceeds maximum of ${VALIDATION_LIMITS.MAX_TEXT_LENGTH} characters`
			);
		}

		const startTime = Date.now();

		try {
			logger.debug(`${LOG_PREFIXES.EMBEDDING} Starting Ollama embedding`, {
				textLength: text.length,
				model: this.model,
			});

			const response = await this.makeRequest('/api/embeddings', {
				model: this.model,
				prompt: text,
			});

			const embedding = response.embedding;
			const processingTime = Date.now() - startTime;

			if (!embedding || !Array.isArray(embedding)) {
				throw new EmbeddingError('Invalid embedding response from Ollama API', 'ollama');
			}

			// Update dimension if it differs from expected
			if (embedding.length !== this.dimension) {
				logger.debug(
					`${LOG_PREFIXES.EMBEDDING} Updating dimension from ${this.dimension} to ${embedding.length}`
				);
				(this as any).dimension = embedding.length;
			}

			logger.debug(`${LOG_PREFIXES.EMBEDDING} Ollama embedding completed`, {
				dimension: embedding.length,
				processingTime,
			});

			return embedding;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.EMBEDDING} Ollama embedding failed`, {
				error: error instanceof Error ? error.message : String(error),
				processingTime,
			});

			if (error instanceof EmbeddingError) {
				throw error;
			}

			throw new EmbeddingError(
				`Ollama embedding failed: ${error instanceof Error ? error.message : String(error)}`,
				'ollama',
				error instanceof Error ? error : undefined
			);
		}
	}

	async embedBatch(texts: string[]): Promise<number[][]> {
		if (!texts || texts.length === 0) {
			throw new EmbeddingValidationError('Text array cannot be empty');
		}

		if (texts.length > VALIDATION_LIMITS.MAX_BATCH_SIZE) {
			throw new EmbeddingValidationError(
				`Batch size ${texts.length} exceeds maximum of ${VALIDATION_LIMITS.MAX_BATCH_SIZE}`
			);
		}

		// Validate individual texts
		for (let i = 0; i < texts.length; i++) {
			const text = texts[i];
			if (!text || text.trim().length === 0) {
				throw new EmbeddingValidationError(`Text at index ${i} cannot be empty`);
			}
			if (text.length > VALIDATION_LIMITS.MAX_TEXT_LENGTH) {
				throw new EmbeddingValidationError(
					`Text at index ${i} length ${text.length} exceeds maximum of ${VALIDATION_LIMITS.MAX_TEXT_LENGTH} characters`
				);
			}
		}

		const startTime = Date.now();

		try {
			logger.debug(`${LOG_PREFIXES.EMBEDDING} Starting Ollama batch embedding`, {
				batchSize: texts.length,
				model: this.model,
			});

			// Ollama doesn't support batch embeddings, so process sequentially
			// For better performance, we could parallelize with a concurrency limit
			const embeddings: number[][] = [];

			for (const text of texts) {
				const embedding = await this.embed(text);
				embeddings.push(embedding);
			}

			const processingTime = Date.now() - startTime;

			logger.debug(`${LOG_PREFIXES.EMBEDDING} Ollama batch embedding completed`, {
				batchSize: embeddings.length,
				dimension: embeddings[0]?.length,
				processingTime,
			});

			return embeddings;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.EMBEDDING} Ollama batch embedding failed`, {
				error: error instanceof Error ? error.message : String(error),
				batchSize: texts.length,
				processingTime,
			});

			if (error instanceof EmbeddingError) {
				throw error;
			}

			throw new EmbeddingError(
				`Ollama batch embedding failed: ${error instanceof Error ? error.message : String(error)}`,
				'ollama',
				error instanceof Error ? error : undefined
			);
		}
	}

	async isHealthy(): Promise<boolean> {
		try {
			logger.debug(`${LOG_PREFIXES.EMBEDDING} Checking Ollama embedder health`);

			// Test connection with a simple text
			await this.embed('health check');

			logger.debug(`${LOG_PREFIXES.EMBEDDING} Ollama embedder is healthy`);
			return true;
		} catch (error) {
			logger.warn(`${LOG_PREFIXES.EMBEDDING} Ollama embedder health check failed`, {
				error: error instanceof Error ? error.message : String(error),
			});
			return false;
		}
	}

	getDimension(): number {
		return this.dimension;
	}

	getModel(): string {
		return this.model;
	}

	getProvider(): string {
		return 'ollama';
	}

	getConfig(): EmbeddingConfig {
		return this.config;
	}

	async disconnect(): Promise<void> {
		// Ollama API is stateless, no cleanup needed
		logger.debug(`${LOG_PREFIXES.EMBEDDING} Ollama embedder disconnected`);
	}

	/**
	 * Make request to Ollama API
	 */
	private async makeRequest(endpoint: string, body: any): Promise<OllamaEmbeddingResponse> {
		const url = `${this.baseUrl}${endpoint}`;

		let lastError: Error | undefined;
		let delay: number = RETRY_CONFIG.INITIAL_DELAY;

		for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
			try {
				logger.silly(`${LOG_PREFIXES.EMBEDDING} Making Ollama API request`, {
					attempt: attempt + 1,
					maxRetries: this.maxRetries + 1,
					endpoint,
					baseUrl: this.baseUrl,
				});

				const controller = new AbortController();
				const timeoutId = setTimeout(() => controller.abort(), this.timeout);

				const response = await globalThis.fetch(url, {
					method: 'POST',
					headers: {
						'Content-Type': 'application/json',
					},
					body: JSON.stringify(body),
					signal: controller.signal,
				});

				clearTimeout(timeoutId);

				if (!response.ok) {
					const errorText = await response.text().catch(() => 'Unknown error');
					let errorData: OllamaErrorResponse;

					try {
						errorData = JSON.parse(errorText) as OllamaErrorResponse;
					} catch {
						errorData = { error: errorText };
					}

					const errorMessage = errorData.error || `HTTP ${response.status}`;

					switch (response.status) {
						case HTTP_STATUS.NOT_FOUND:
							throw new EmbeddingValidationError(
								`Ollama model '${this.model}' not found. Make sure the model is pulled: ollama pull ${this.model}`
							);
						case HTTP_STATUS.BAD_REQUEST:
							throw new EmbeddingValidationError(`Invalid request to Ollama API: ${errorMessage}`);
						case HTTP_STATUS.SERVICE_UNAVAILABLE:
							throw new EmbeddingConnectionError(
								`Ollama service unavailable. Make sure Ollama is running: ${errorMessage}`
							);
						default:
							throw new EmbeddingConnectionError(`Ollama API error: ${errorMessage}`);
					}
				}

				const data = (await response.json()) as OllamaEmbeddingResponse;

				if (!data.embedding) {
					throw new EmbeddingError('Invalid response format from Ollama API', 'ollama');
				}

				return data;
			} catch (error) {
				lastError = error instanceof Error ? error : new Error(String(error));

				logger.error(`${LOG_PREFIXES.EMBEDDING} Ollama API request failed`, {
					attempt: attempt + 1,
					error: lastError.message,
					errorType: lastError.constructor.name,
					stack: lastError.stack,
					url,
					body: JSON.stringify(body),
				});

				// Don't retry on validation errors
				if (error instanceof EmbeddingValidationError || error instanceof EmbeddingError) {
					throw error;
				}

				// If this was the last attempt, throw the error
				if (attempt === this.maxRetries) {
					break;
				}

				// Wait before retrying
				logger.debug(`${LOG_PREFIXES.EMBEDDING} Retrying Ollama request in ${delay}ms`, {
					attempt: attempt + 1,
					error: lastError.message,
				});

				await new Promise(resolve => setTimeout(resolve, delay));
				delay = Math.min(delay * RETRY_CONFIG.BACKOFF_MULTIPLIER, 60000);
			}
		}

		throw new EmbeddingConnectionError(
			`Failed to connect to Ollama API after ${this.maxRetries + 1} attempts: ${lastError?.message}. Make sure Ollama is running at ${this.baseUrl}`,
			'ollama',
			lastError
		);
	}
}

/**
 * OpenAI Embedding Backend
 *
 * Implementation of the Embedder interface for OpenAI's embedding services.
 * Supports all OpenAI embedding models with batch processing, retry logic,
 * and comprehensive error handling.
 *
 * @module embedding/backend/openai
 */

import OpenAI from 'openai';
import { logger } from '../../../logger/index.js';
import {
	Embedder,
	OpenAIEmbeddingConfig,
	EmbeddingConnectionError,
	EmbeddingRateLimitError,
	EmbeddingQuotaError,
	EmbeddingValidationError,
	EmbeddingError,
	EmbeddingDimensionError,
} from './types.js';
import {
	MODEL_DIMENSIONS,
	VALIDATION_LIMITS,
	ERROR_MESSAGES,
	LOG_PREFIXES,
	RETRY_CONFIG,
	HTTP_STATUS,
} from '../constants.js';

/**
 * OpenAI Embedder Implementation
 *
 * Provides embedding functionality using OpenAI's embedding API.
 * Implements comprehensive error handling, retry logic, and batch processing.
 */
export class OpenAIEmbedder implements Embedder {
	private openai: OpenAI;
	private readonly config: OpenAIEmbeddingConfig;
	private readonly model: string;
	private readonly dimension: number;

	constructor(config: OpenAIEmbeddingConfig) {
		this.config = config;
		this.model = config.model || 'text-embedding-3-small';

		// Validate that API key is provided
		if (!config.apiKey || config.apiKey.trim() === '') {
			throw new EmbeddingError('OpenAI API key is required', 'openai');
		}

		// Initialize OpenAI client with proper handling of undefined values
		// Only pass defined values to avoid OpenAI SDK initialization issues
		const openaiConfig: {
			apiKey: string;
			baseURL?: string;
			organization?: string;
			timeout: number;
			maxRetries: number;
		} = {
			apiKey: config.apiKey,
			timeout: config.timeout || 30000, // Default to 30 seconds if not specified
			maxRetries: config.maxRetries || 3, // Default to 3 retries if not specified
		};

		// Only add optional fields if they are defined and not empty
		if (config.baseUrl && config.baseUrl.trim() !== '') {
			openaiConfig.baseURL = config.baseUrl;
		}
		if (config.organization && config.organization.trim() !== '') {
			openaiConfig.organization = config.organization;
		}

		this.openai = new OpenAI(openaiConfig);

		// Set dimension based on model and config
		this.dimension =
			config.dimensions || MODEL_DIMENSIONS[this.model as keyof typeof MODEL_DIMENSIONS] || 1536;

		logger.debug(`${LOG_PREFIXES.OPENAI} Initialized OpenAI embedder`, {
			model: this.model,
			dimension: this.dimension,
			baseUrl: config.baseUrl,
			hasOrganization: !!config.organization,
		});
	}

	async embed(text: string): Promise<number[]> {
		logger.silly(`${LOG_PREFIXES.OPENAI} Embedding single text`, {
			textLength: text.length,
			model: this.model,
		});

		// Validate input
		this.validateInput(text);

		const startTime = Date.now();

		try {
			const params: { model: string; input: string; dimensions?: number } = {
				model: this.model,
				input: text,
			};
			if (this.config.dimensions !== undefined) {
				params.dimensions = this.config.dimensions;
			}
			const response = await this.createEmbeddingWithRetry(params);
			if (
				!response.data ||
				!Array.isArray(response.data) ||
				!response.data[0] ||
				!response.data[0].embedding
			) {
				throw new EmbeddingError('OpenAI API did not return a valid embedding', 'openai');
			}
			const embedding = response.data[0].embedding;
			this.validateEmbeddingDimension(embedding);
			return embedding;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.OPENAI} Failed to create embedding`, {
				error: error instanceof Error ? error.message : String(error),
				model: this.model,
				processingTime,
				textLength: text.length,
			});

			throw this.handleApiError(error);
		}
	}

	async embedBatch(texts: string[]): Promise<number[][]> {
		logger.debug(`${LOG_PREFIXES.BATCH} Embedding batch of texts`, {
			count: texts.length,
			model: this.model,
		});

		// Validate batch input
		this.validateBatchInput(texts);

		const startTime = Date.now();

		try {
			const batchParams: { model: string; input: string[]; dimensions?: number } = {
				model: this.model,
				input: texts,
			};
			if (this.config.dimensions !== undefined) {
				batchParams.dimensions = this.config.dimensions;
			}
			const response = await this.createEmbeddingWithRetry(batchParams);
			const embeddings = response.data.map(item => item.embedding);
			embeddings.forEach(this.validateEmbeddingDimension.bind(this));
			return embeddings;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.BATCH} Failed to create batch embeddings`, {
				error: error instanceof Error ? error.message : String(error),
				model: this.model,
				processingTime,
				count: texts.length,
			});

			throw this.handleApiError(error);
		}
	}

	getDimension(): number {
		return this.dimension;
	}

	getConfig(): OpenAIEmbeddingConfig {
		return { ...this.config };
	}

	async isHealthy(): Promise<boolean> {
		try {
			logger.silly(`${LOG_PREFIXES.HEALTH} Checking OpenAI embedder health`);

			// Try a simple embedding request with minimal text
			await this.embed('test');

			logger.debug(`${LOG_PREFIXES.HEALTH} OpenAI embedder is healthy`);
			return true;
		} catch (error) {
			logger.warn(`${LOG_PREFIXES.HEALTH} OpenAI embedder health check failed`, {
				error: error instanceof Error ? error.message : String(error),
			});
			return false;
		}
	}

	async disconnect(): Promise<void> {
		logger.debug(`${LOG_PREFIXES.OPENAI} Disconnecting OpenAI embedder`);
		// OpenAI client doesn't require explicit cleanup
		// This is here for interface compliance and future extensibility
	}

	/**
	 * Create embedding with retry logic
	 */
	private async createEmbeddingWithRetry(params: {
		model: string;
		input: string | string[];
		dimensions?: number;
	}): Promise<OpenAI.Embeddings.CreateEmbeddingResponse> {
		let lastError: Error | undefined;
		let delay: number = RETRY_CONFIG.INITIAL_DELAY;

		for (let attempt = 0; attempt <= this.config.maxRetries!; attempt++) {
			try {
				if (attempt > 0) {
					logger.debug(`${LOG_PREFIXES.OPENAI} Retrying embedding request`, {
						attempt,
						delay,
						maxRetries: this.config.maxRetries,
					});

					// Wait before retry
					await new Promise(resolve => setTimeout(resolve, delay));

					// Calculate next delay with exponential backoff and jitter
					delay = Math.min(delay * RETRY_CONFIG.BACKOFF_MULTIPLIER, RETRY_CONFIG.MAX_DELAY);

					// Add jitter to avoid thundering herd
					const jitter = delay * RETRY_CONFIG.JITTER_FACTOR * Math.random();
					delay = Math.floor(delay + jitter);
				}

				const response = await this.openai.embeddings.create(params);

				if (attempt > 0) {
					logger.info(`${LOG_PREFIXES.OPENAI} Embedding request succeeded after retry`, {
						attempt,
						model: params.model,
					});
				}

				return response;
			} catch (error) {
				lastError = error instanceof Error ? error : new Error(String(error));

				// Check if we should retry based on error type
				if (!this.shouldRetry(error, attempt)) {
					break;
				}

				logger.warn(`${LOG_PREFIXES.OPENAI} Embedding request failed, will retry`, {
					attempt: attempt + 1,
					maxRetries: this.config.maxRetries,
					error: lastError.message,
					nextDelay: delay,
				});
			}
		}

		// All retries exhausted
		throw lastError || new EmbeddingError('Unknown error during embedding request', 'openai');
	}

	/**
	 * Determine if an error is retryable
	 */
	private shouldRetry(error: unknown, attempt: number): boolean {
		if (attempt >= this.config.maxRetries!) {
			return false;
		}

		// Handle OpenAI API errors
		if (error && typeof error === 'object' && 'status' in error) {
			const status = (error as any).status;

			// Retry on server errors and rate limits
			return [
				HTTP_STATUS.TOO_MANY_REQUESTS,
				HTTP_STATUS.INTERNAL_SERVER_ERROR,
				HTTP_STATUS.SERVICE_UNAVAILABLE,
			].includes(status);
		}

		// Retry on network errors
		if (error instanceof Error) {
			const message = error.message.toLowerCase();
			return (
				message.includes('network') ||
				message.includes('timeout') ||
				message.includes('connection') ||
				message.includes('econnreset') ||
				message.includes('enotfound')
			);
		}

		return false;
	}

	/**
	 * Handle and categorize API errors
	 */
	private handleApiError(error: unknown): EmbeddingError {
		if (error && typeof error === 'object' && 'status' in error) {
			const apiError = error as any;
			const status = apiError.status;
			const message = apiError.message || String(error);

			switch (status) {
				case HTTP_STATUS.UNAUTHORIZED:
					return new EmbeddingConnectionError(
						ERROR_MESSAGES.INVALID_API_KEY('OpenAI'),
						'openai',
						apiError
					);

				case HTTP_STATUS.TOO_MANY_REQUESTS: {
					const retryAfter = apiError.headers?.['retry-after'];
					return new EmbeddingRateLimitError(
						ERROR_MESSAGES.RATE_LIMIT_EXCEEDED,
						retryAfter ? parseInt(retryAfter, 10) : undefined,
						'openai',
						apiError
					);
				}

				case HTTP_STATUS.FORBIDDEN:
					return new EmbeddingQuotaError(ERROR_MESSAGES.QUOTA_EXCEEDED, 'openai', apiError);

				case HTTP_STATUS.BAD_REQUEST:
					return new EmbeddingValidationError(message, 'openai', apiError);

				default:
					return new EmbeddingConnectionError(
						ERROR_MESSAGES.CONNECTION_FAILED('OpenAI'),
						'openai',
						apiError
					);
			}
		}

		// Handle network and other errors
		if (error instanceof Error) {
			return new EmbeddingConnectionError(error.message, 'openai', error);
		}

		return new EmbeddingError(String(error), 'openai');
	}

	/**
	 * Validate single text input
	 */
	private validateInput(text: string): void {
		if (!text || text.length < VALIDATION_LIMITS.MIN_TEXT_LENGTH) {
			throw new EmbeddingValidationError(ERROR_MESSAGES.EMPTY_TEXT, 'openai');
		}

		if (text.length > VALIDATION_LIMITS.MAX_TEXT_LENGTH) {
			throw new EmbeddingValidationError(
				ERROR_MESSAGES.TEXT_TOO_LONG(text.length, VALIDATION_LIMITS.MAX_TEXT_LENGTH),
				'openai'
			);
		}
	}

	/**
	 * Validate batch input
	 */
	private validateBatchInput(texts: string[]): void {
		if (!Array.isArray(texts) || texts.length === 0) {
			throw new EmbeddingValidationError('Batch input must be a non-empty array', 'openai');
		}

		if (texts.length > VALIDATION_LIMITS.MAX_BATCH_SIZE) {
			throw new EmbeddingValidationError(
				ERROR_MESSAGES.BATCH_TOO_LARGE(texts.length, VALIDATION_LIMITS.MAX_BATCH_SIZE),
				'openai'
			);
		}

		// Validate each text in the batch
		texts.forEach((text, index) => {
			try {
				this.validateInput(text);
			} catch (error) {
				if (error instanceof EmbeddingValidationError) {
					throw new EmbeddingValidationError(
						`Batch item ${index}: ${error.message}`,
						'openai',
						error
					);
				}
				throw error;
			}
		});
	}

	/**
	 * Validate embedding dimension
	 */
	private validateEmbeddingDimension(embedding: number[]): void {
		if (embedding.length !== this.dimension) {
			throw new EmbeddingDimensionError(
				ERROR_MESSAGES.DIMENSION_MISMATCH(this.dimension, embedding.length),
				this.dimension,
				embedding.length,
				'openai'
			);
		}
	}
}

/**
 * Qwen Embedding Backend
 *
 * Implementation of the Alibaba Cloud Qwen (DashScope) embedding provider.
 * Supports the text-embedding-v3 model through DashScope API.
 */

import type { Embedder, EmbeddingConfig } from './types.js';
import { EmbeddingError, EmbeddingConnectionError, EmbeddingValidationError } from './types.js';

/**
 * Qwen-specific configuration interface
 */
export interface QwenEmbeddingConfig extends EmbeddingConfig {
	type: 'qwen';
	model?: 'text-embedding-v3';
	baseUrl?: string;
	dimensions?: 1024 | 768 | 512;
}

/**
 * Qwen embedding provider implementation using DashScope API
 */
export class QwenEmbedder implements Embedder {
	private readonly config: QwenEmbeddingConfig;
	private readonly apiKey: string;
	private readonly baseUrl: string;
	private readonly model: string;
	private readonly dimensions: number;

	constructor(config: QwenEmbeddingConfig) {
		this.config = config;
		this.apiKey = config.apiKey || process.env.QWEN_API_KEY || process.env.DASHSCOPE_API_KEY || '';
		this.baseUrl = config.baseUrl || 'https://dashscope-intl.aliyuncs.com/compatible-mode/v1';
		this.model = config.model || 'text-embedding-v3';
		this.dimensions = config.dimensions || 1024;

		if (!this.apiKey) {
			throw new EmbeddingValidationError(
				'Qwen API key is required (QWEN_API_KEY or DASHSCOPE_API_KEY)'
			);
		}
	}

	async embed(text: string): Promise<number[]> {
		try {
			const response = await this.makeRequest({
				model: this.model,
				input: [text],
				dimensions: this.dimensions,
			});

			if (!response.data || response.data.length === 0) {
				throw new EmbeddingError('No embedding data received from Qwen API');
			}

			return response.data[0].embedding;
		} catch (error) {
			if (error instanceof EmbeddingError) {
				throw error;
			}
			throw new EmbeddingError(`Failed to generate Qwen embedding: ${error}`);
		}
	}

	async embedBatch(texts: string[]): Promise<number[][]> {
		try {
			// Qwen supports up to 10 texts per request
			const batchSize = 10;
			const results: number[][] = [];

			for (let i = 0; i < texts.length; i += batchSize) {
				const batch = texts.slice(i, i + batchSize);
				const response = await this.makeRequest({
					model: this.model,
					input: batch,
					dimensions: this.dimensions,
				});

				if (!response.data || response.data.length !== batch.length) {
					throw new EmbeddingError('Unexpected response format from Qwen API');
				}

				results.push(...response.data.map((item: any) => item.embedding));
			}

			return results;
		} catch (error) {
			if (error instanceof EmbeddingError) {
				throw error;
			}
			throw new EmbeddingError(`Failed to generate Qwen batch embeddings: ${error}`);
		}
	}

	getDimension(): number {
		return this.dimensions;
	}

	getConfig(): QwenEmbeddingConfig {
		return { ...this.config };
	}

	async isHealthy(): Promise<boolean> {
		try {
			await this.embed('test');
			return true;
		} catch {
			return false;
		}
	}

	async disconnect(): Promise<void> {
		// No persistent connections to close for HTTP-based API
	}

	private async makeRequest(body: any): Promise<any> {
		const timeout = this.config.timeout || 30000;
		const maxRetries = this.config.maxRetries || 3;

		for (let attempt = 1; attempt <= maxRetries; attempt++) {
			try {
				const controller = new AbortController();
				const timeoutId = setTimeout(() => controller.abort(), timeout);

				const response = await globalThis.fetch(`${this.baseUrl}/embeddings`, {
					method: 'POST',
					headers: {
						'Content-Type': 'application/json',
						Authorization: `Bearer ${this.apiKey}`,
					},
					body: JSON.stringify(body),
					signal: controller.signal,
				});

				clearTimeout(timeoutId);

				if (!response.ok) {
					const errorText = await response.text();
					if (response.status === 429) {
						if (attempt < maxRetries) {
							await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
							continue;
						}
					}
					throw new EmbeddingConnectionError(`Qwen API error: ${response.status} ${errorText}`);
				}

				return await response.json();
			} catch (error) {
				if (error instanceof EmbeddingError) {
					throw error;
				}
				if (attempt === maxRetries) {
					throw new EmbeddingConnectionError(
						`Failed to connect to Qwen API after ${maxRetries} attempts: ${error}`
					);
				}
				await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
			}
		}
	}
}

/**
 * Factory function to create a Qwen embedder
 */
export function createQwenEmbedder(config: QwenEmbeddingConfig): QwenEmbedder {
	return new QwenEmbedder(config);
}

/**
 * Embedding Backend Types and Interfaces
 *
 * Core type definitions for the embedding system backends.
 * Provides the fundamental interfaces that all embedding providers must implement.
 *
 * @module embedding/backend/types
 */

/**
 * Core interface for embedding providers
 *
 * All embedding backends must implement this interface to provide
 * consistent embedding functionality across different providers.
 */
export interface Embedder {
	/**
	 * Generate embedding for a single text input
	 *
	 * @param text - The text to embed
	 * @returns Promise resolving to the embedding vector
	 */
	embed(text: string): Promise<number[]>;

	/**
	 * Generate embeddings for multiple text inputs in batch
	 *
	 * @param texts - Array of texts to embed
	 * @returns Promise resolving to array of embedding vectors
	 */
	embedBatch(texts: string[]): Promise<number[][]>;

	/**
	 * Get the dimension of embeddings produced by this embedder
	 *
	 * @returns The vector dimension
	 */
	getDimension(): number;

	/**
	 * Get the configuration used by this embedder
	 *
	 * @returns The embedder configuration
	 */
	getConfig(): EmbeddingConfig;

	/**
	 * Check if the embedder is healthy and can process requests
	 *
	 * @returns Promise resolving to health status
	 */
	isHealthy(): Promise<boolean>;

	/**
	 * Clean up resources and close connections
	 */
	disconnect(): Promise<void>;
}

/**
 * Base configuration interface for all embedding providers
 */
export interface EmbeddingConfig {
	/** The embedding provider type */
	type: string;

	/** API key for the provider */
	apiKey?: string;

	/** Model name to use for embeddings */
	model?: string;

	/** Base URL for the provider API */
	baseUrl?: string;

	/** Request timeout in milliseconds */
	timeout?: number;

	/** Maximum number of retry attempts */
	maxRetries?: number;

	/** Provider-specific options */
	options?: Record<string, any>;
}

/**
 * OpenAI-specific embedding configuration
 */
export interface OpenAIEmbeddingConfig extends EmbeddingConfig {
	type: 'openai';
	model?: 'text-embedding-3-small' | 'text-embedding-3-large' | 'text-embedding-ada-002';
	/** Organization ID for OpenAI API */
	organization?: string;
	/** Custom dimensions for embedding-3 models */
	dimensions?: number;
}

/**
 * Gemini-specific embedding configuration
 */
export interface GeminiEmbeddingConfig extends EmbeddingConfig {
	type: 'gemini';
	model?: 'text-embedding-004' | 'gemini-embedding-001' | 'embedding-001';
	/** Custom dimensions for Gemini models */
	dimensions?: number;
}

/**
 * Ollama-specific embedding configuration
 */
export interface OllamaEmbeddingConfig extends EmbeddingConfig {
	type: 'ollama';
	model?: 'nomic-embed-text' | 'all-minilm' | 'mxbai-embed-large' | string;
	/** Custom dimensions if supported by the model */
	dimensions?: number;
}

/**
 * Voyage-specific embedding configuration
 */
export interface VoyageEmbeddingConfig extends EmbeddingConfig {
	type: 'voyage';
	model?: 'voyage-3-large' | 'voyage-3' | 'voyage-2';
}

/**
 * Qwen-specific embedding configuration
 */
export interface QwenEmbeddingConfig extends EmbeddingConfig {
	type: 'qwen';
	model?: 'text-embedding-v3';
	/** Custom dimensions for Qwen models */
	dimensions?: 1024 | 768 | 512;
}

/**
 * AWS Bedrock-specific embedding configuration
 */
export interface AWSBedrockEmbeddingConfig extends EmbeddingConfig {
	type: 'aws-bedrock';
	model?: 'amazon.titan-embed-text-v2:0' | 'cohere.embed-english-v3';
	region?: string;
	accessKeyId?: string;
	secretAccessKey?: string;
	sessionToken?: string;
	/** Custom dimensions for Titan V2 */
	dimensions?: 1024 | 512 | 256;
}

/**
 * LM Studio-specific embedding configuration
 */
export interface LMStudioEmbeddingConfig extends EmbeddingConfig {
	type: 'lmstudio';
	model?: 'nomic-embed-text-v1.5' | 'text-embedding-nomic-embed-text-v1.5' | string;
	/** Base URL for LM Studio server, defaults to http://localhost:1234/v1 */
	baseUrl?: string;
	/** Custom dimensions if supported by the model */
	dimensions?: number;
}

/**
 * Union type for all supported backend configurations
 */
export type BackendConfig =
	| OpenAIEmbeddingConfig
	| GeminiEmbeddingConfig
	| OllamaEmbeddingConfig
	| VoyageEmbeddingConfig
	| QwenEmbeddingConfig
	| AWSBedrockEmbeddingConfig
	| LMStudioEmbeddingConfig;

/**
 * Result from embedding operation with metadata
 */
export interface EmbeddingResult {
	/** The embedding vector */
	embedding: number[];
	/** Metadata about the embedding operation */
	metadata: {
		/** Model used for embedding */
		model: string;
		/** Token count for the input text */
		tokens?: number;
		/** Processing time in milliseconds */
		processingTime?: number;
	};
}

/**
 * Batch embedding result
 */
export interface BatchEmbeddingResult {
	/** Array of embedding vectors */
	embeddings: number[][];
	/** Metadata about the batch operation */
	metadata: {
		/** Model used for embedding */
		model: string;
		/** Total token count for all inputs */
		totalTokens?: number;
		/** Processing time in milliseconds */
		processingTime?: number;
		/** Number of successful embeddings */
		successCount: number;
		/** Number of failed embeddings */
		failureCount: number;
	};
}

/**
 * Base error class for embedding operations
 */
export class EmbeddingError extends Error {
	public readonly provider?: string;
	public override readonly cause?: Error;

	constructor(message: string, provider?: string, cause?: Error) {
		super(message);
		this.name = 'EmbeddingError';
		if (provider !== undefined) {
			this.provider = provider;
		}
		if (cause !== undefined) {
			this.cause = cause;
		}
	}
}

/**
 * Error thrown when connection to embedding provider fails
 */
export class EmbeddingConnectionError extends EmbeddingError {
	constructor(message: string, provider?: string, cause?: Error) {
		super(message, provider, cause);
		this.name = 'EmbeddingConnectionError';
	}
}

/**
 * Error thrown when embedding dimensions don't match expected values
 */
export class EmbeddingDimensionError extends EmbeddingError {
	constructor(
		message: string,
		public readonly expected: number,
		public readonly actual: number,
		provider?: string
	) {
		super(message, provider);
		this.name = 'EmbeddingDimensionError';
	}
}

/**
 * Error thrown when API rate limits are exceeded
 */
export class EmbeddingRateLimitError extends EmbeddingError {
	constructor(
		message: string,
		public readonly retryAfter?: number,
		provider?: string,
		cause?: Error
	) {
		super(message, provider, cause);
		this.name = 'EmbeddingRateLimitError';
	}
}

/**
 * Error thrown when API quota is exceeded
 */
export class EmbeddingQuotaError extends EmbeddingError {
	constructor(message: string, provider?: string, cause?: Error) {
		super(message, provider, cause);
		this.name = 'EmbeddingQuotaError';
	}
}

/**
 * Error thrown when input validation fails
 */
export class EmbeddingValidationError extends EmbeddingError {
	constructor(message: string, provider?: string, cause?: Error) {
		super(message, provider, cause);
		this.name = 'EmbeddingValidationError';
	}
}

/**
 * Voyage Embedding Backend
 *
 * Implementation of the Voyage AI embedding provider for the Cipher embedding system.
 * Provides support for Voyage's embedding models including voyage-3-large.
 */

import { logger } from '../../../logger/index.js';
import type { Embedder, EmbeddingConfig } from './types.js';
import { EmbeddingError, EmbeddingConnectionError, EmbeddingValidationError } from './types.js';
import { LOG_PREFIXES } from '../constants.js';

/**
 * Voyage-specific configuration interface
 */
export interface VoyageEmbeddingConfig extends EmbeddingConfig {
	type: 'voyage';
	model?: 'voyage-3-large' | 'voyage-3' | 'voyage-2';
	baseUrl?: string;
}

/**
 * Voyage embedding provider implementation
 */
export class VoyageEmbedder implements Embedder {
	private readonly config: VoyageEmbeddingConfig;
	private readonly apiKey: string;
	private readonly baseUrl: string;
	private readonly model: string;
	private readonly dimension: number;

	constructor(config: VoyageEmbeddingConfig) {
		this.config = config;
		this.apiKey = config.apiKey || process.env.VOYAGE_API_KEY || '';
		this.baseUrl = config.baseUrl || 'https://api.voyageai.com/v1';
		this.model = config.model || 'voyage-3-large';

		// Set dimension based on model (all Voyage models have 1024 dimensions)
		this.dimension = 1024;

		if (!this.apiKey) {
			throw new EmbeddingValidationError('Voyage API key is required');
		}

		logger.debug(`${LOG_PREFIXES.VOYAGE} Initialized Voyage embedder`, {
			model: this.model,
			dimension: this.dimension,
			baseUrl: this.baseUrl,
			hasApiKey: !!this.apiKey,
		});
	}

	async embed(text: string): Promise<number[]> {
		logger.silly(`${LOG_PREFIXES.VOYAGE} Generating Voyage embedding`, {
			textLength: text.length,
			model: this.model,
		});

		const startTime = Date.now();

		try {
			const response = await this.makeRequest({
				input: [text],
				model: this.model,
			});

			if (!response.data || response.data.length === 0) {
				throw new EmbeddingError('No embedding data received from Voyage API');
			}

			const embedding = response.data[0].embedding;
			const processingTime = Date.now() - startTime;

			logger.debug(`${LOG_PREFIXES.VOYAGE} Successfully generated Voyage embedding`, {
				model: this.model,
				dimension: embedding.length,
				processingTime: `${processingTime}ms`,
				textLength: text.length,
			});

			return embedding;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.VOYAGE} Failed to generate Voyage embedding`, {
				error: error instanceof Error ? error.message : String(error),
				model: this.model,
				processingTime,
				textLength: text.length,
			});

			if (error instanceof EmbeddingError) {
				throw error;
			}
			throw new EmbeddingError(`Failed to generate Voyage embedding: ${error}`);
		}
	}

	async embedBatch(texts: string[]): Promise<number[][]> {
		logger.debug(`${LOG_PREFIXES.VOYAGE} Generating Voyage batch embeddings`, {
			count: texts.length,
			model: this.model,
		});

		const startTime = Date.now();

		try {
			const response = await this.makeRequest({
				input: texts,
				model: this.model,
			});

			if (!response.data || response.data.length !== texts.length) {
				throw new EmbeddingError('Unexpected response format from Voyage API');
			}

			const embeddings = response.data.map((item: any) => item.embedding);
			const processingTime = Date.now() - startTime;

			logger.debug(`${LOG_PREFIXES.VOYAGE} Successfully generated Voyage batch embeddings`, {
				model: this.model,
				count: embeddings.length,
				dimension: embeddings[0]?.length || 0,
				processingTime: `${processingTime}ms`,
			});

			return embeddings;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error(`${LOG_PREFIXES.VOYAGE} Failed to generate Voyage batch embeddings`, {
				error: error instanceof Error ? error.message : String(error),
				model: this.model,
				processingTime,
				count: texts.length,
			});

			if (error instanceof EmbeddingError) {
				throw error;
			}
			throw new EmbeddingError(`Failed to generate Voyage batch embeddings: ${error}`);
		}
	}

	getDimension(): number {
		return this.dimension;
	}

	getConfig(): VoyageEmbeddingConfig {
		return { ...this.config };
	}

	async isHealthy(): Promise<boolean> {
		try {
			await this.embed('test');
			return true;
		} catch {
			return false;
		}
	}

	async disconnect(): Promise<void> {
		// No persistent connections to close for HTTP-based API
		logger.debug(`${LOG_PREFIXES.VOYAGE} Voyage embedder disconnected`);
	}

	private async makeRequest(body: any): Promise<any> {
		const timeout = this.config.timeout || 30000;
		const maxRetries = this.config.maxRetries || 3;

		for (let attempt = 1; attempt <= maxRetries; attempt++) {
			try {
				const controller = new AbortController();
				const timeoutId = setTimeout(() => controller.abort(), timeout);

				const response = await globalThis.fetch(`${this.baseUrl}/embeddings`, {
					method: 'POST',
					headers: {
						'Content-Type': 'application/json',
						Authorization: `Bearer ${this.apiKey}`,
					},
					body: JSON.stringify(body),
					signal: controller.signal,
				});

				clearTimeout(timeoutId);

				if (!response.ok) {
					const errorText = await response.text();
					if (response.status === 429) {
						if (attempt < maxRetries) {
							await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
							continue;
						}
					}
					throw new EmbeddingConnectionError(`Voyage API error: ${response.status} ${errorText}`);
				}

				return await response.json();
			} catch (error) {
				if (error instanceof EmbeddingError) {
					throw error;
				}
				if (attempt === maxRetries) {
					throw new EmbeddingConnectionError(
						`Failed to connect to Voyage API after ${maxRetries} attempts: ${error}`
					);
				}
				await new Promise(resolve => setTimeout(resolve, 1000 * attempt));
			}
		}
	}
}

/**
 * Factory function to create a Voyage embedder
 */
export function createVoyageEmbedder(config: VoyageEmbeddingConfig): VoyageEmbedder {
	return new VoyageEmbedder(config);
}

/**
 * Circuit Breaker Pattern for Embedding Operations
 *
 * Implements circuit breaker pattern to prevent cascading failures
 * and provide automatic recovery for embedding services.
 */

import { logger } from '../../logger/index.js';
import { LOG_PREFIXES } from './constants.js';

export enum CircuitState {
	CLOSED = 'CLOSED', // Normal operation
	OPEN = 'OPEN', // Failing, reject all calls
	HALF_OPEN = 'HALF_OPEN', // Testing recovery
}

export interface CircuitBreakerConfig {
	/** Number of failures before opening circuit */
	failureThreshold: number;
	/** Time to wait before attempting recovery (ms) */
	recoveryTimeout: number;
	/** Number of successful calls needed to close circuit */
	successThreshold: number;
	/** Time window for failure counting (ms) */
	timeWindow: number;
}

export interface CircuitBreakerStats {
	state: CircuitState;
	failureCount: number;
	successCount: number;
	lastFailureTime: number | null;
	lastSuccessTime: number | null;
	totalOperations: number;
	totalFailures: number;
}

/**
 * Circuit Breaker for Embedding Operations
 */
export class EmbeddingCircuitBreaker {
	private state: CircuitState = CircuitState.CLOSED;
	private failureCount = 0;
	private successCount = 0;
	private lastFailureTime: number | null = null;
	private lastSuccessTime: number | null = null;
	private totalOperations = 0;
	private totalFailures = 0;
	private readonly config: CircuitBreakerConfig;
	private readonly name: string;

	constructor(name: string, config: Partial<CircuitBreakerConfig> = {}) {
		this.name = name;
		this.config = {
			failureThreshold: config.failureThreshold || 5,
			recoveryTimeout: config.recoveryTimeout || 60000, // 1 minute
			successThreshold: config.successThreshold || 3,
			timeWindow: config.timeWindow || 300000, // 5 minutes
		};

		logger.debug(`${LOG_PREFIXES.CIRCUIT_BREAKER} Circuit breaker initialized`, {
			name: this.name,
			config: this.config,
		});
	}

	/**
	 * Execute operation with circuit breaker protection
	 */
	async execute<T>(operation: () => Promise<T>): Promise<T> {
		this.totalOperations++;

		// Check circuit state
		if (this.state === CircuitState.OPEN) {
			if (this.shouldAttemptRecovery()) {
				this.state = CircuitState.HALF_OPEN;
				this.successCount = 0;
				logger.info(`${LOG_PREFIXES.CIRCUIT_BREAKER} Circuit entering HALF_OPEN state`, {
					name: this.name,
				});
			} else {
				const error = new Error(`Circuit breaker OPEN for ${this.name}`);
				logger.debug(`${LOG_PREFIXES.CIRCUIT_BREAKER} Circuit breaker rejecting operation`, {
					name: this.name,
					state: this.state,
				});
				throw error;
			}
		}

		try {
			const result = await operation();
			this.onSuccess();
			return result;
		} catch (error) {
			this.onFailure(error);
			throw error;
		}
	}

	/**
	 * Check if circuit breaker allows operation
	 */
	isOperationAllowed(): boolean {
		if (this.state === CircuitState.CLOSED) {
			return true;
		}
		if (this.state === CircuitState.HALF_OPEN) {
			return true;
		}
		if (this.state === CircuitState.OPEN) {
			return this.shouldAttemptRecovery();
		}
		return false;
	}

	/**
	 * Get current circuit breaker statistics
	 */
	getStats(): CircuitBreakerStats {
		return {
			state: this.state,
			failureCount: this.failureCount,
			successCount: this.successCount,
			lastFailureTime: this.lastFailureTime,
			lastSuccessTime: this.lastSuccessTime,
			totalOperations: this.totalOperations,
			totalFailures: this.totalFailures,
		};
	}

	/**
	 * Reset circuit breaker to closed state
	 */
	reset(): void {
		this.state = CircuitState.CLOSED;
		this.failureCount = 0;
		this.successCount = 0;
		this.lastFailureTime = null;

		logger.info(`${LOG_PREFIXES.CIRCUIT_BREAKER} Circuit breaker reset`, {
			name: this.name,
		});
	}

	/**
	 * Force circuit breaker to open state
	 */
	forceOpen(): void {
		this.state = CircuitState.OPEN;
		this.lastFailureTime = Date.now();

		logger.warn(`${LOG_PREFIXES.CIRCUIT_BREAKER} Circuit breaker forced OPEN`, {
			name: this.name,
		});
	}

	private onSuccess(): void {
		this.lastSuccessTime = Date.now();
		this.successCount++;

		if (this.state === CircuitState.HALF_OPEN) {
			if (this.successCount >= this.config.successThreshold) {
				this.state = CircuitState.CLOSED;
				this.failureCount = 0;
				this.successCount = 0;

				logger.info(`${LOG_PREFIXES.CIRCUIT_BREAKER} Circuit breaker CLOSED - service recovered`, {
					name: this.name,
					successCount: this.successCount,
				});
			}
		} else if (this.state === CircuitState.CLOSED) {
			// Reset failure count on success in closed state
			this.failureCount = Math.max(0, this.failureCount - 1);
		}
	}

	private onFailure(error: any): void {
		this.lastFailureTime = Date.now();
		this.failureCount++;
		this.totalFailures++;

		const errorMessage = error instanceof Error ? error.message : String(error);

		logger.warn(`${LOG_PREFIXES.CIRCUIT_BREAKER} Operation failed`, {
			name: this.name,
			error: errorMessage,
			failureCount: this.failureCount,
			state: this.state,
		});

		if (this.state === CircuitState.CLOSED || this.state === CircuitState.HALF_OPEN) {
			if (this.failureCount >= this.config.failureThreshold) {
				this.state = CircuitState.OPEN;
				this.successCount = 0;

				logger.error(`${LOG_PREFIXES.CIRCUIT_BREAKER} Circuit breaker OPENED - too many failures`, {
					name: this.name,
					failureCount: this.failureCount,
					threshold: this.config.failureThreshold,
				});
			}
		}
	}

	private shouldAttemptRecovery(): boolean {
		if (!this.lastFailureTime) {
			return true;
		}

		const timeSinceLastFailure = Date.now() - this.lastFailureTime;
		return timeSinceLastFailure >= this.config.recoveryTimeout;
	}
}

/**
 * Circuit Breaker Manager for managing multiple circuit breakers
 */
export class CircuitBreakerManager {
	private circuitBreakers = new Map<string, EmbeddingCircuitBreaker>();

	/**
	 * Get or create circuit breaker for a specific service
	 */
	getCircuitBreaker(name: string, config?: Partial<CircuitBreakerConfig>): EmbeddingCircuitBreaker {
		if (!this.circuitBreakers.has(name)) {
			const circuitBreaker = new EmbeddingCircuitBreaker(name, config);
			this.circuitBreakers.set(name, circuitBreaker);
		}
		return this.circuitBreakers.get(name)!;
	}

	/**
	 * Get all circuit breaker statistics
	 */
	getAllStats(): Record<string, CircuitBreakerStats> {
		const stats: Record<string, CircuitBreakerStats> = {};
		for (const [name, circuitBreaker] of this.circuitBreakers) {
			stats[name] = circuitBreaker.getStats();
		}
		return stats;
	}

	/**
	 * Reset all circuit breakers
	 */
	resetAll(): void {
		for (const circuitBreaker of this.circuitBreakers.values()) {
			circuitBreaker.reset();
		}
		logger.info(`${LOG_PREFIXES.CIRCUIT_BREAKER} All circuit breakers reset`);
	}

	/**
	 * Get circuit breakers that are currently open
	 */
	getOpenCircuits(): string[] {
		const openCircuits: string[] = [];
		for (const [name, circuitBreaker] of this.circuitBreakers) {
			if (circuitBreaker.getStats().state === CircuitState.OPEN) {
				openCircuits.push(name);
			}
		}
		return openCircuits;
	}

	/**
	 * Check if any circuit breakers are open
	 */
	hasOpenCircuits(): boolean {
		return this.getOpenCircuits().length > 0;
	}
}

/**
 * Embedding Configuration Schema and Utilities
 *
 * This module provides Zod schemas for validating embedding configurations
 * and utilities for parsing configurations from environment variables.
 */

import { z } from 'zod';

/**
 * OpenAI embedding configuration schema
 */
export const OpenAIEmbeddingConfigSchema = z.object({
	type: z.literal('openai'),
	apiKey: z.string().optional(),
	model: z
		.enum(['text-embedding-3-small', 'text-embedding-3-large', 'text-embedding-ada-002'])
		.default('text-embedding-3-small'),
	baseUrl: z.string().optional(),
	organization: z.string().optional(),
	dimensions: z.number().optional(),
	timeout: z.number().default(30000),
	maxRetries: z.number().default(3),
});

/**
 * Gemini embedding configuration schema
 */
export const GeminiEmbeddingConfigSchema = z.object({
	type: z.literal('gemini'),
	apiKey: z.string().optional(),
	model: z.enum(['gemini-embedding-001', 'text-embedding-004']).default('gemini-embedding-001'),
	baseUrl: z.string().optional(),
	timeout: z.number().default(30000),
	maxRetries: z.number().default(3),
});

/**
 * Ollama embedding configuration schema
 */
export const OllamaEmbeddingConfigSchema = z.object({
	type: z.literal('ollama'),
	baseUrl: z.string().default('http://localhost:11434'),
	model: z.string().default('nomic-embed-text'),
	timeout: z.number().default(30000),
	maxRetries: z.number().default(3),
});

/**
 * Voyage embedding configuration schema (for Claude/Anthropic fallback)
 */
export const VoyageEmbeddingConfigSchema = z.object({
	type: z.literal('voyage'),
	apiKey: z.string().optional(),
	model: z.enum(['voyage-3-large', 'voyage-3', 'voyage-2']).default('voyage-3-large'),
	baseUrl: z.string().optional(),
	timeout: z.number().default(30000),
	maxRetries: z.number().default(3),
});

/**
 * Qwen embedding configuration schema
 */
export const QwenEmbeddingConfigSchema = z.object({
	type: z.literal('qwen'),
	apiKey: z.string().optional(),
	model: z.enum(['text-embedding-v3']).default('text-embedding-v3'),
	baseUrl: z.string().optional(),
	dimensions: z
		.number()
		.refine(val => [1024, 768, 512].includes(val))
		.default(1024),
	timeout: z.number().default(30000),
	maxRetries: z.number().default(3),
});

/**
 * AWS Bedrock embedding configuration schema
 */
export const AWSBedrockEmbeddingConfigSchema = z.object({
	type: z.literal('aws-bedrock'),
	model: z
		.enum(['amazon.titan-embed-text-v2:0', 'cohere.embed-english-v3'])
		.default('amazon.titan-embed-text-v2:0'),
	region: z.string().optional(),
	accessKeyId: z.string().optional(),
	secretAccessKey: z.string().optional(),
	sessionToken: z.string().optional(),
	dimensions: z
		.number()
		.refine(val => [1024, 512, 256].includes(val))
		.default(1024),
	timeout: z.number().default(30000),
	maxRetries: z.number().default(3),
});

/**
 * LM Studio embedding configuration schema
 */
export const LMStudioEmbeddingConfigSchema = z.object({
	type: z.literal('lmstudio'),
	baseUrl: z.string().default('http://localhost:1234/v1'),
	model: z.string().default('nomic-embed-text-v1.5'),
	dimensions: z.number().optional(),
	timeout: z.number().default(30000),
	maxRetries: z.number().default(3),
});

/**
 * Main embedding configuration schema
 */
export const EmbeddingConfigSchema = z.union([
	OpenAIEmbeddingConfigSchema,
	GeminiEmbeddingConfigSchema,
	OllamaEmbeddingConfigSchema,
	VoyageEmbeddingConfigSchema,
	QwenEmbeddingConfigSchema,
	AWSBedrockEmbeddingConfigSchema,
	LMStudioEmbeddingConfigSchema,
]);

/**
 * Environment configuration type
 */
export interface EmbeddingEnvConfig {
	type: string;
	apiKey?: string | undefined;
	baseUrl?: string | undefined;
	model?: string | undefined;
	region?: string | undefined;
	accessKeyId?: string | undefined;
	secretAccessKey?: string | undefined;
	sessionToken?: string | undefined;
}

/**
 * Parse embedding configuration from environment variables
 */
export function parseEmbeddingConfigFromEnv(): EmbeddingEnvConfig | null {
	// Priority order: OpenAI > Gemini > Ollama
	if (process.env.OPENAI_API_KEY) {
		return {
			type: 'openai',
			apiKey: process.env.OPENAI_API_KEY,
			baseUrl: process.env.OPENAI_BASE_URL,
			model: process.env.OPENAI_EMBEDDING_MODEL || 'text-embedding-3-small',
		};
	}

	if (process.env.GEMINI_API_KEY) {
		return {
			type: 'gemini',
			apiKey: process.env.GEMINI_API_KEY,
			baseUrl: process.env.GEMINI_BASE_URL,
			model: process.env.GEMINI_EMBEDDING_MODEL || 'gemini-embedding-001',
		};
	}

	if (process.env.QWEN_API_KEY || process.env.DASHSCOPE_API_KEY) {
		return {
			type: 'qwen',
			apiKey: process.env.QWEN_API_KEY || process.env.DASHSCOPE_API_KEY,
			baseUrl: process.env.QWEN_BASE_URL,
			model: process.env.QWEN_EMBEDDING_MODEL || 'text-embedding-v3',
		};
	}

	if (process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY) {
		return {
			type: 'aws-bedrock',
			region: process.env.AWS_DEFAULT_REGION || 'us-east-1',
			accessKeyId: process.env.AWS_ACCESS_KEY_ID,
			secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
			sessionToken: process.env.AWS_SESSION_TOKEN,
			model: process.env.AWS_BEDROCK_EMBEDDING_MODEL || 'amazon.titan-embed-text-v2:0',
		};
	}

	if (process.env.OLLAMA_BASE_URL) {
		return {
			type: 'ollama',
			baseUrl: process.env.OLLAMA_BASE_URL,
			model: process.env.OLLAMA_EMBEDDING_MODEL || 'nomic-embed-text',
		};
	}

	if (process.env.LMSTUDIO_BASE_URL) {
		return {
			type: 'lmstudio',
			baseUrl: process.env.LMSTUDIO_BASE_URL,
			model: process.env.LMSTUDIO_EMBEDDING_MODEL || 'nomic-embed-text-v1.5',
		};
	}

	return null;
}

/**
 * Parse and validate embedding configuration
 */
export function parseEmbeddingConfig(config: unknown): z.infer<typeof EmbeddingConfigSchema> {
	return EmbeddingConfigSchema.parse(config);
}

/**
 * Validate embedding configuration
 */
export function validateEmbeddingConfig(config: unknown): boolean {
	try {
		EmbeddingConfigSchema.parse(config);
		return true;
	} catch {
		return false;
	}
}

