/**
 * Registry of available embedding factories
 */
export const EMBEDDING_FACTORIES = new Map<string, EmbeddingFactory>([
	['openai', new OpenAIEmbeddingFactory()],
	['gemini', new GeminiEmbeddingFactory()],
	['ollama', new OllamaEmbeddingFactory()],
	['voyage', new VoyageEmbeddingFactory()],
	['qwen', new QwenEmbeddingFactory()],
	['aws-bedrock', new AWSBedrockEmbeddingFactory()],
	['lmstudio', new LMStudioEmbeddingFactory()],
]);

/**
 * Create embedder from configuration
 */
export async function createEmbedder(config: BackendConfig): Promise<Embedder> {
	const factory = EMBEDDING_FACTORIES.get(config.type);
	if (!factory) {
		throw new EmbeddingValidationError(`Unsupported embedding provider: ${config.type}`);
	}

	logger.debug('Creating embedder', { provider: config.type, model: config.model });
	return factory.createEmbedder(config);
}

/**
 * Create embedder from environment configuration
 */
export async function createEmbedderFromEnv(): Promise<{ embedder: Embedder; info: any } | null> {
	const envConfig = parseEmbeddingConfigFromEnv();
	if (!envConfig) {
		logger.debug('No embedding configuration found in environment');
		return null;
	}

	try {
		// Convert env config to proper backend config
		const backendConfig: BackendConfig = {
			...envConfig,
			timeout: 30000,
			maxRetries: 3,
		} as BackendConfig;

		const embedder = await createEmbedder(backendConfig);
		const info = {
			provider: envConfig.type,
			model: envConfig.model || 'default',
			dimension: embedder.getDimension(),
		};

		return { embedder, info };
	} catch (error) {
		logger.warn('Failed to create embedder from environment config', {
			error: error instanceof Error ? error.message : String(error),
			type: envConfig.type,
		});
		return null;
	}
}

/**
 * Validate embedding configuration
 */
export function validateEmbeddingConfiguration(config: unknown): boolean {
	if (!config || typeof config !== 'object') {
		return false;
	}

	const configObj = config as any;
	const factory = EMBEDDING_FACTORIES.get(configObj.type);
	return factory ? factory.validateConfig(config) : false;
}

/**
 * Get supported embedding providers
 */
export function getSupportedProviders(): string[] {
	return Array.from(EMBEDDING_FACTORIES.keys());
}

/**
 * Check if provider is supported
 */
export function isProviderSupported(provider: string): boolean {
	return EMBEDDING_FACTORIES.has(provider);
}

/**
 * Embedding Module
 *
 * High-performance text embedding system supporting multiple providers.
 * Provides a unified API for generating embeddings with comprehensive
 * error handling, retry logic, and lifecycle management.
 *
 * Features:
 * - Multiple provider support (OpenAI, future: Anthropic, Cohere, etc.)
 * - Batch operations for efficient processing
 * - Type-safe configuration with runtime validation
 * - Comprehensive error handling and retry logic
 * - Health monitoring and statistics collection
 * - Graceful fallback and connection management
 *
 * @module embedding
 *
 * @example
 * ```typescript
 * import { createEmbedder, EmbeddingManager } from './embedding';
 *
 * // Create a single embedder
 * const embedder = await createEmbedder({
 *   type: 'openai',
 *   apiKey: process.env.OPENAI_API_KEY,
 *   model: 'text-embedding-3-small'
 * });
 *
 * // Generate embeddings
 * const embedding = await embedder.embed('Hello world');
 * const embeddings = await embedder.embedBatch(['Hello', 'World']);
 *
 * // Use embedding manager for multiple embedders
 * const manager = new EmbeddingManager();
 * const { embedder: managedEmbedder } = await manager.createEmbedder({
 *   type: 'openai',
 *   apiKey: process.env.OPENAI_API_KEY
 * });
 *
 * // Health monitoring
 * manager.startHealthChecks();
 * const healthResults = await manager.checkAllHealth();
 *
 * // Cleanup
 * await manager.disconnect();
 * ```
 */

// Export types
export type {
	Embedder,
	EmbeddingConfig,
	OpenAIEmbeddingConfig,
	BackendConfig,
	EmbeddingResult,
	BatchEmbeddingResult,
	HealthCheckResult,
	EmbedderInfo,
	EmbeddingStats,
	EmbeddingEnvConfig,
} from './types.js';

// Export error classes
export {
	EmbeddingError,
	EmbeddingConnectionError,
	EmbeddingDimensionError,
	EmbeddingRateLimitError,
	EmbeddingQuotaError,
	EmbeddingValidationError,
} from './types.js';

// Export factory functions
export {
	createEmbedder,
	createEmbedderFromEnv,
	getSupportedProviders,
	isProviderSupported,
	validateEmbeddingConfiguration,
	EMBEDDING_FACTORIES,
	type EmbeddingFactory,
} from './factory.js';

// Export manager
export { EmbeddingManager, SessionEmbeddingState } from './manager.js';

// Export configuration utilities
export {
	parseEmbeddingConfig,
	parseEmbeddingConfigFromEnv,
	validateEmbeddingConfig,
	EmbeddingConfigSchema,
} from './config.js';

// Export constants for external use
export {
	PROVIDER_TYPES,
	OPENAI_MODELS,
	MODEL_DIMENSIONS,
	DEFAULTS,
	VALIDATION_LIMITS,
} from './constants.js';

// Export utilities
export {
	getEmbeddingConfigFromEnv,
	isEmbeddingConfigAvailable,
	getEmbeddingConfigSummary,
	validateEmbeddingEnv,
	analyzeProviderConfiguration,
} from './utils.js';

/**
 * Embedding Manager Module
 *
 * Provides lifecycle management, health monitoring, and connection management
 * for embedding services. Manages multiple embedder instances and provides
 * centralized monitoring and cleanup capabilities.
 *
 * @module embedding/manager
 */

import { logger } from '../../logger/index.js';
import { type Embedder, type BackendConfig } from './backend/index.js';
import {
	createEmbedder,
	createEmbedderFromEnv,
	type BackendConfig as FactoryBackendConfig,
} from './factory.js';
import { LOG_PREFIXES } from './constants.js';
import { type EmbeddingConfig } from './config.js';
// Removed complex resilient embedder and circuit breaker infrastructure

/**
 * Simple session-specific embedding state
 */
export class SessionEmbeddingState {
	private disabled = false;
	private disabledReason = '';

	disableForSession(reason: string): void {
		this.disabled = true;
		this.disabledReason = reason;
		logger.warn(`${LOG_PREFIXES.MANAGER} Embeddings disabled for this session: ${reason}`);
	}

	isDisabled(): boolean {
		return this.disabled;
	}

	getDisabledReason(): string {
		return this.disabledReason;
	}
}

/**
 * Health check result for an embedder instance
 */
export interface HealthCheckResult {
	/** Whether the embedder is healthy */
	healthy: boolean;
	/** Provider type */
	provider: string;
	/** Model being used */
	model: string;
	/** Embedding dimension */
	dimension?: number;
	/** Response time in milliseconds */
	responseTime?: number;
	/** Error message if unhealthy */
	error?: string;
	/** Timestamp of the health check */
	timestamp: Date;
}

/**
 * Information about an embedder instance
 */
export interface EmbedderInfo {
	/** Unique identifier for this embedder */
	id: string;
	/** Provider type */
	provider: string;
	/** Model being used */
	model: string;
	/** Embedding dimension */
	dimension: number;
	/** Configuration used */
	config: BackendConfig;
	/** Creation timestamp */
	createdAt: Date;
	/** Last health check result */
	lastHealthCheck?: HealthCheckResult;
}

/**
 * Statistics about embedding operations
 */
export interface EmbeddingStats {
	/** Total number of single embed operations */
	totalEmbeds: number;
	/** Total number of batch embed operations */
	totalBatchEmbeds: number;
	/** Total number of texts processed */
	totalTexts: number;
	/** Total processing time in milliseconds */
	totalProcessingTime: number;
	/** Number of successful operations */
	successfulOperations: number;
	/** Number of failed operations */
	failedOperations: number;
	/** Average processing time per operation */
	averageProcessingTime: number;
}

/**
 * Embedding Manager
 *
 * Manages the lifecycle of embedding instances, providing centralized
 * health monitoring, statistics collection, and resource cleanup.
 */
export class EmbeddingManager {
	private embedders = new Map<string, Embedder>();
	private embedderInfo = new Map<string, EmbedderInfo>();
	private sessionState = new SessionEmbeddingState();

	constructor() {
		logger.debug(`${LOG_PREFIXES.MANAGER} Simple embedding manager initialized`);
	}

	/**
	 * Create and register an embedder instance
	 *
	 * @param config - Embedding configuration
	 * @param id - Optional custom ID for the embedder
	 * @returns Promise resolving to embedder instance and info
	 */
	async createEmbedder(
		config: BackendConfig,
		id?: string
	): Promise<{ embedder: Embedder; info: EmbedderInfo }> {
		const embedderId = id || this.generateId();

		logger.debug(`${LOG_PREFIXES.MANAGER} Creating embedder`, {
			id: embedderId,
			type: config.type,
		});

		try {
			const configWithApiKey = { ...config, apiKey: config.apiKey || '' };
			const baseEmbedder = await createEmbedder(configWithApiKey as any);

			// No complex wrapping - use embedder directly

			const info: EmbedderInfo = {
				id: embedderId,
				provider: config.type,
				model: config.model || 'unknown',
				dimension: baseEmbedder.getDimension(),
				config,
				createdAt: new Date(),
			};

			this.embedders.set(embedderId, baseEmbedder);
			this.embedderInfo.set(embedderId, info);
			// Removed resilient embedders - using simple embedders

			logger.info(`${LOG_PREFIXES.MANAGER} Successfully created embedder`, {
				id: embedderId,
				provider: info.provider,
				model: info.model,
				dimension: info.dimension,
			});

			return { embedder: baseEmbedder, info };
		} catch (error) {
			logger.error(`${LOG_PREFIXES.MANAGER} Failed to create embedder`, {
				id: embedderId,
				type: config.type,
				error: error instanceof Error ? error.message : String(error),
			});

			throw error;
		}
	}

	/**
	 * Create and register an embedder from YAML configuration
	 *
	 * @param config - Embedding configuration from YAML
	 * @param id - Optional custom ID for the embedder
	 * @returns Promise resolving to embedder instance and info, or null
	 */
	async createEmbedderFromConfig(
		config: EmbeddingConfig,
		id?: string
	): Promise<{ embedder: Embedder; info: EmbedderInfo } | null> {
		logger.debug(`${LOG_PREFIXES.MANAGER} Creating embedder from YAML configuration`, {
			provider: config.type,
			model: config.model,
		});

		// Check if embeddings are explicitly disabled in config
		if ('disabled' in config && config.disabled) {
			logger.info(`${LOG_PREFIXES.MANAGER} Embeddings are disabled via YAML configuration`);
			return null;
		}

		const embedder = await createEmbedder(config as FactoryBackendConfig);
		if (!embedder) {
			logger.warn(`${LOG_PREFIXES.MANAGER} Failed to create embedder from YAML configuration`);
			return null;
		}

		const embedderId = id || this.generateId();
		const backendConfig = embedder.getConfig() as BackendConfig;

		const info: EmbedderInfo = {
			id: embedderId,
			provider: backendConfig.type,
			model: backendConfig.model || 'unknown',
			dimension: embedder.getDimension(),
			config: backendConfig,
			createdAt: new Date(),
		};

		// Simple storage - no complex wrapping
		this.embedders.set(embedderId, embedder);
		this.embedderInfo.set(embedderId, info);

		// Enhanced logging with provider-specific details
		const logDetails: any = {
			id: embedderId,
			provider: info.provider,
			model: info.model,
			dimension: info.dimension,
		};

		// Add provider-specific details
		if (info.provider === 'voyage') {
			logDetails.voyageModel = info.model;
			logDetails.voyageDimensions = info.dimension;
			logger.info(
				`${LOG_PREFIXES.MANAGER} Voyage embedder registered successfully from YAML`,
				logDetails
			);
		} else if (info.provider === 'openai') {
			logDetails.openaiModel = info.model;
			logDetails.openaiDimensions = info.dimension;
			logger.info(
				`${LOG_PREFIXES.MANAGER} OpenAI embedder registered successfully from YAML`,
				logDetails
			);
		} else if (info.provider === 'qwen') {
			logDetails.qwenModel = info.model;
			logDetails.qwenDimensions = info.dimension;
			logger.info(
				`${LOG_PREFIXES.MANAGER} Qwen embedder registered successfully from YAML`,
				logDetails
			);
		} else {
			logger.info(`${LOG_PREFIXES.MANAGER} Embedder registered successfully from YAML`, logDetails);
		}

		return { embedder, info };
	}

	/**
	 * Handle runtime embedding failure and disable globally if needed
	 *
	 * This method is called when any embedding-related tool fails.
	 * It immediately disables embeddings globally to prevent further failures
	 * and allow the application to continue in chat-only mode.
	 */
	handleRuntimeFailure(error: Error, provider: string): void {
		const errorMessage = error.message.toLowerCase();

		// Check for critical errors that should immediately disable embeddings
		const isCriticalError =
			errorMessage.includes('unauthorized') ||
			errorMessage.includes('invalid api key') ||
			errorMessage.includes('authentication') ||
			errorMessage.includes('401') ||
			errorMessage.includes('403') ||
			errorMessage.includes('api key') ||
			errorMessage.includes('model is not embedding') ||
			errorMessage.includes('failed to load model') ||
			errorMessage.includes('cannot connect') ||
			errorMessage.includes('connection') ||
			errorMessage.includes('not found') ||
			errorMessage.includes('model not found') ||
			errorMessage.includes('server rejected') ||
			errorMessage.includes('econnrefused') ||
			errorMessage.includes('fetch failed') ||
			errorMessage.includes('timeout') ||
			errorMessage.includes('network') ||
			// LM Studio specific errors
			errorMessage.includes('lm studio server') ||
			errorMessage.includes('embedding model') ||
			errorMessage.includes('ensure the model is loaded');

		if (isCriticalError) {
			logger.error(
				`${LOG_PREFIXES.MANAGER} Critical embedding failure - disabling for this session`,
				{
					provider,
					error: error.message,
				}
			);

			this.sessionState.disableForSession(`${provider} embedding failed: ${error.message}`);
		} else {
			// For other errors, just log but don't disable
			logger.warn(`${LOG_PREFIXES.MANAGER} Embedding operation failed but will retry`, {
				provider,
				error: error.message,
			});
		}
	}

	/**
	 * Create embedder from environment variables
	 *
	 * @param id - Optional custom ID for the embedder
	 * @returns Promise resolving to embedder instance and info, or null
	 */
	async createEmbedderFromEnv(
		id?: string
	): Promise<{ embedder: Embedder; info: EmbedderInfo } | null> {
		logger.debug(`${LOG_PREFIXES.MANAGER} Creating embedder from environment`);

		// Check if embeddings are explicitly disabled
		if (process.env.DISABLE_EMBEDDINGS === 'true' || process.env.EMBEDDING_DISABLED === 'true') {
			logger.info(`${LOG_PREFIXES.MANAGER} Embeddings are disabled via environment variable`);
			return null;
		}

		const result = await createEmbedderFromEnv();
		if (!result) {
			logger.warn(`${LOG_PREFIXES.MANAGER} No embedder configuration found in environment`);
			return null;
		}

		const { embedder } = result;
		const embedderId = id || this.generateId();
		const config = embedder.getConfig() as BackendConfig;

		const info: EmbedderInfo = {
			id: embedderId,
			provider: config.type,
			model: config.model || 'unknown',
			dimension: embedder.getDimension(),
			config,
			createdAt: new Date(),
		};

		this.embedders.set(embedderId, embedder);
		this.embedderInfo.set(embedderId, info);

		logger.info(`${LOG_PREFIXES.MANAGER} Successfully created embedder from environment`, {
			id: embedderId,
			provider: info.provider,
			model: info.model,
		});

		return { embedder, info };
	}

	/**
	 * Get embedder instance by ID
	 *
	 * @param id - Embedder ID
	 * @returns Embedder instance or undefined
	 */
	getEmbedder(id: string): Embedder | undefined {
		return this.embedders.get(id);
	}

	/**
	 * Get embedder information by ID
	 *
	 * @param id - Embedder ID
	 * @returns Embedder information or undefined
	 */
	getEmbedderInfo(id: string): EmbedderInfo | undefined {
		return this.embedderInfo.get(id);
	}

	/**
	 * Get all registered embedders
	 *
	 * @returns Map of embedder ID to embedder instance
	 */
	getAllEmbedders(): Map<string, Embedder> {
		return new Map(this.embedders);
	}

	/**
	 * Get all embedder information
	 *
	 * @returns Map of embedder ID to embedder information
	 */
	getAllEmbedderInfo(): Map<string, EmbedderInfo> {
		return new Map(this.embedderInfo);
	}

	/**
	 * Remove and disconnect an embedder
	 *
	 * @param id - Embedder ID
	 * @returns Promise resolving to true if removed, false if not found
	 */
	async removeEmbedder(id: string): Promise<boolean> {
		const embedder = this.embedders.get(id);
		if (!embedder) {
			logger.warn(`${LOG_PREFIXES.MANAGER} Embedder not found for removal`, { id });
			return false;
		}

		logger.debug(`${LOG_PREFIXES.MANAGER} Removing embedder`, { id });

		try {
			await embedder.disconnect();
			this.embedders.delete(id);
			this.embedderInfo.delete(id);

			logger.info(`${LOG_PREFIXES.MANAGER} Successfully removed embedder`, { id });
			return true;
		} catch (error) {
			logger.error(`${LOG_PREFIXES.MANAGER} Error disconnecting embedder`, {
				id,
				error: error instanceof Error ? error.message : String(error),
			});

			// Remove anyway to prevent memory leaks
			this.embedders.delete(id);
			this.embedderInfo.delete(id);
			return true;
		}
	}

	/**
	 * Perform health check on a specific embedder
	 *
	 * @param id - Embedder ID
	 * @returns Promise resolving to health check result
	 */
	async checkHealth(id: string): Promise<HealthCheckResult | null> {
		const embedder = this.embedders.get(id);
		const info = this.embedderInfo.get(id);

		if (!embedder || !info) {
			logger.warn(`${LOG_PREFIXES.HEALTH} Embedder not found for health check`, { id });
			return null;
		}

		logger.silly(`${LOG_PREFIXES.HEALTH} Performing health check`, { id });

		const startTime = Date.now();
		try {
			const healthy = await embedder.isHealthy();
			const responseTime = Date.now() - startTime;

			const result: HealthCheckResult = {
				healthy,
				provider: info.provider,
				model: info.model || 'unknown',
				dimension: info.dimension,
				responseTime,
				timestamp: new Date(),
			};

			// Update embedder info with latest health check
			this.embedderInfo.set(id, {
				...info,
				lastHealthCheck: result,
			});

			logger.debug(`${LOG_PREFIXES.HEALTH} Health check completed`, {
				id,
				healthy,
				responseTime,
			});

			return result;
		} catch (error) {
			const responseTime = Date.now() - startTime;
			const result: HealthCheckResult = {
				healthy: false,
				provider: info.provider,
				model: info.model || 'unknown',
				dimension: info.dimension,
				responseTime,
				error: error instanceof Error ? error.message : String(error),
				timestamp: new Date(),
			};

			// Update embedder info with latest health check
			this.embedderInfo.set(id, {
				...info,
				lastHealthCheck: result,
			});

			logger.warn(`${LOG_PREFIXES.HEALTH} Health check failed`, {
				id,
				error: result.error,
				responseTime,
			});

			return result;
		}
	}

	/**
	 * Perform health check on all embedders
	 *
	 * @returns Promise resolving to map of embedder ID to health check result
	 */
	async checkAllHealth(): Promise<Map<string, HealthCheckResult>> {
		logger.debug(`${LOG_PREFIXES.HEALTH} Performing health check on all embedders`);

		const results = new Map<string, HealthCheckResult>();
		const healthCheckPromises = Array.from(this.embedders.keys()).map(async id => {
			const result = await this.checkHealth(id);
			if (result) {
				results.set(id, result);
			}
		});

		await Promise.all(healthCheckPromises);

		logger.debug(`${LOG_PREFIXES.HEALTH} Completed health check on all embedders`, {
			total: this.embedders.size,
			checked: results.size,
		});

		return results;
	}

	/**
	 * Start periodic health checks (simplified - no automatic scheduling)
	 *
	 * @param intervalMs - Health check interval in milliseconds (default: 5 minutes)
	 */
	startHealthChecks(_intervalMs: number = 5 * 60 * 1000): void {
		logger.debug(`${LOG_PREFIXES.HEALTH} Health checks can be run manually via checkAllHealth()`);
	}

	/**
	 * Stop periodic health checks (simplified - no automatic scheduling)
	 */
	stopHealthChecks(): void {
		logger.debug(`${LOG_PREFIXES.HEALTH} No periodic health checks to stop`);
	}

	/**
	 * Get current statistics (simplified - basic stats only)
	 *
	 * @returns Current embedding statistics
	 */
	getStats(): EmbeddingStats {
		return {
			totalEmbeds: 0,
			totalBatchEmbeds: 0,
			totalTexts: 0,
			totalProcessingTime: 0,
			successfulOperations: 0,
			failedOperations: 0,
			averageProcessingTime: 0,
		};
	}

	/**
	 * Reset statistics (simplified - no-op)
	 */
	resetStats(): void {
		logger.debug(`${LOG_PREFIXES.MANAGER} Statistics reset (simplified implementation)`);
	}

	/**
	 * Update statistics (simplified - no-op)
	 */
	private updateStats(
		type: 'embed' | 'batch',
		textCount: number,
		processingTime: number,
		success: boolean
	): void {
		// Simplified implementation - no statistics tracking
		logger.silly(`${LOG_PREFIXES.MANAGER} Operation completed`, {
			type,
			textCount,
			processingTime,
			success,
		});
	}

	/**
	 * Get embedding status for all embedders
	 */
	getEmbeddingStatus(): Record<
		string,
		{
			status: 'HEALTHY' | 'DISABLED';
			provider: string;
			isHealthy: boolean;
			stats: any;
		}
	> {
		const status: Record<string, any> = {};

		for (const [id] of this.embedders) {
			const info = this.embedderInfo.get(id);
			if (info) {
				const isDisabled = this.sessionState.isDisabled();
				status[id] = {
					status: isDisabled ? 'DISABLED' : 'HEALTHY',
					provider: info.provider,
					isHealthy: !isDisabled,
					stats: { disabled: isDisabled, reason: this.sessionState.getDisabledReason() },
				};
			}
		}

		return status;
	}

	/**
	 * Check if embeddings are available for this session
	 */
	hasAvailableEmbeddings(): boolean {
		// If disabled for this session, return false
		if (this.sessionState.isDisabled()) {
			return false;
		}
		// Otherwise, check if we have any embedders
		return this.embedders.size > 0;
	}

	/**
	 * Get session embedding state
	 */
	getSessionState(): SessionEmbeddingState {
		return this.sessionState;
	}

	// Removed complex circuit breaker and resilient embedder methods

	/**
	 * Disconnect all embedders and cleanup
	 */
	async disconnect(): Promise<void> {
		logger.info(`${LOG_PREFIXES.MANAGER} Disconnecting all embedders`);

		// Stop health checks
		this.stopHealthChecks();

		// Disconnect all embedders
		const disconnectPromises = Array.from(this.embedders.entries()).map(async ([id, embedder]) => {
			try {
				await embedder.disconnect();
				logger.debug(`${LOG_PREFIXES.MANAGER} Disconnected embedder`, { id });
			} catch (error) {
				logger.warn(`${LOG_PREFIXES.MANAGER} Error disconnecting embedder`, {
					id,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		});

		await Promise.all(disconnectPromises);

		// Clear all maps
		this.embedders.clear();
		this.embedderInfo.clear();
		// Removed resilientEmbedders map

		logger.info(`${LOG_PREFIXES.MANAGER} Successfully disconnected all embedders`);
	}

	/**
	 * Generate a unique ID for embedders
	 */
	private generateId(): string {
		return `embedder_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
	}
}

/**
 * Resilient Embedder Wrapper
 *
 * Provides fault-tolerant embedding operations with automatic fallback,
 * circuit breaker protection, and graceful degradation.
 */

import { logger } from '../../logger/index.js';
import { LOG_PREFIXES } from './constants.js';
import { EmbeddingCircuitBreaker, CircuitState } from './circuit-breaker.js';
import type { Embedder, EmbeddingConfig } from './backend/types.js';
import {
	EmbeddingError,
	EmbeddingConnectionError,
	EmbeddingValidationError,
} from './backend/types.js';

export interface ResilientEmbedderConfig {
	/** Enable circuit breaker protection */
	enableCircuitBreaker: boolean;
	/** Enable automatic fallback to disabled state */
	enableFallback: boolean;
	/** Health check interval in milliseconds */
	healthCheckInterval: number;
	/** Maximum consecutive failures before disabling */
	maxConsecutiveFailures: number;
	/** Recovery attempt interval in milliseconds */
	recoveryInterval: number;
}

export interface EmbeddingOperationResult<T> {
	success: boolean;
	data?: T;
	error?: Error;
	fallbackActivated: boolean;
	circuitOpen: boolean;
}

export enum EmbeddingStatus {
	HEALTHY = 'HEALTHY',
	DEGRADED = 'DEGRADED',
	DISABLED = 'DISABLED',
	RECOVERING = 'RECOVERING',
}

/**
 * Resilient wrapper for embedding operations
 */
export class ResilientEmbedder implements Embedder {
	private readonly embedder: Embedder;
	private readonly circuitBreaker: EmbeddingCircuitBreaker;
	private readonly config: ResilientEmbedderConfig;
	private readonly providerName: string;

	private status: EmbeddingStatus = EmbeddingStatus.HEALTHY;
	private consecutiveFailures = 0;
	private lastHealthCheck: number = 0;
	private lastRecoveryAttempt: number = 0;
	private isTemporarilyDisabled = false;

	private healthCheckTimer: NodeJS.Timeout | null = null;

	constructor(
		embedder: Embedder,
		providerName: string,
		config: Partial<ResilientEmbedderConfig> = {}
	) {
		this.embedder = embedder;
		this.providerName = providerName;
		this.config = {
			enableCircuitBreaker: config.enableCircuitBreaker ?? true,
			enableFallback: config.enableFallback ?? true,
			healthCheckInterval: config.healthCheckInterval ?? 300000, // 5 minutes
			maxConsecutiveFailures: config.maxConsecutiveFailures ?? 5,
			recoveryInterval: config.recoveryInterval ?? 60000, // 1 minute
		};

		// Initialize circuit breaker
		this.circuitBreaker = new EmbeddingCircuitBreaker(`${providerName}-embedder`, {
			failureThreshold: this.config.maxConsecutiveFailures,
			recoveryTimeout: this.config.recoveryInterval,
			successThreshold: 3,
			timeWindow: 300000, // 5 minutes
		});

		// Start health checking if enabled
		if (this.config.enableCircuitBreaker) {
			this.startHealthChecking();
		}

		logger.debug(`${LOG_PREFIXES.FALLBACK} Resilient embedder initialized`, {
			provider: this.providerName,
			config: this.config,
		});
	}

	async embed(text: string): Promise<number[]> {
		const result = await this.executeWithFallback(() => this.embedder.embed(text));

		if (!result.success) {
			if (result.fallbackActivated) {
				throw new Error(
					`Embedding temporarily unavailable for ${this.providerName} - operating in chat-only mode`
				);
			}
			throw result.error || new Error('Embedding operation failed');
		}

		return result.data!;
	}

	async embedBatch(texts: string[]): Promise<number[][]> {
		const result = await this.executeWithFallback(() => this.embedder.embedBatch(texts));

		if (!result.success) {
			if (result.fallbackActivated) {
				throw new Error(
					`Batch embedding temporarily unavailable for ${this.providerName} - operating in chat-only mode`
				);
			}
			throw result.error || new Error('Batch embedding operation failed');
		}

		return result.data!;
	}

	async isHealthy(): Promise<boolean> {
		// If temporarily disabled, always return false
		if (this.isTemporarilyDisabled) {
			return false;
		}

		try {
			// Use circuit breaker to check health
			if (this.config.enableCircuitBreaker && !this.circuitBreaker.isOperationAllowed()) {
				return false;
			}

			return await this.embedder.isHealthy();
		} catch (error) {
			logger.debug(`${LOG_PREFIXES.FALLBACK} Health check failed for ${this.providerName}`, {
				error: error instanceof Error ? error.message : String(error),
			});
			return false;
		}
	}

	getDimension(): number {
		return this.embedder.getDimension();
	}

	getConfig(): EmbeddingConfig {
		return this.embedder.getConfig();
	}

	async disconnect(): Promise<void> {
		// Stop health checking
		if (this.healthCheckTimer) {
			clearInterval(this.healthCheckTimer);
			this.healthCheckTimer = null;
		}

		// Disconnect underlying embedder
		await this.embedder.disconnect();

		logger.debug(`${LOG_PREFIXES.FALLBACK} Resilient embedder disconnected`, {
			provider: this.providerName,
		});
	}

	/**
	 * Get current embedding status
	 */
	getStatus(): EmbeddingStatus {
		return this.status;
	}

	/**
	 * Get detailed statistics
	 */
	getStats() {
		return {
			status: this.status,
			consecutiveFailures: this.consecutiveFailures,
			isTemporarilyDisabled: this.isTemporarilyDisabled,
			lastHealthCheck: this.lastHealthCheck,
			lastRecoveryAttempt: this.lastRecoveryAttempt,
			circuitBreakerStats: this.circuitBreaker.getStats(),
		};
	}

	/**
	 * Force disable embeddings
	 */
	forceDisable(): void {
		this.isTemporarilyDisabled = true;
		this.status = EmbeddingStatus.DISABLED;
		this.circuitBreaker.forceOpen();

		logger.warn(`${LOG_PREFIXES.FALLBACK} Embeddings force-disabled for ${this.providerName}`);
	}

	/**
	 * Reset to healthy state
	 */
	reset(): void {
		this.isTemporarilyDisabled = false;
		this.consecutiveFailures = 0;
		this.status = EmbeddingStatus.HEALTHY;
		this.circuitBreaker.reset();

		logger.info(
			`${LOG_PREFIXES.FALLBACK} Embeddings reset to healthy state for ${this.providerName}`
		);
	}

	/**
	 * Execute operation with fallback protection
	 */
	private async executeWithFallback<T>(
		operation: () => Promise<T>
	): Promise<EmbeddingOperationResult<T>> {
		// Check if temporarily disabled
		if (this.isTemporarilyDisabled) {
			return {
				success: false,
				fallbackActivated: true,
				circuitOpen: false,
				error: new Error(`Embeddings temporarily disabled for ${this.providerName}`),
			};
		}

		// Check circuit breaker
		if (this.config.enableCircuitBreaker) {
			const circuitStats = this.circuitBreaker.getStats();
			if (circuitStats.state === CircuitState.OPEN) {
				return {
					success: false,
					fallbackActivated: true,
					circuitOpen: true,
					error: new Error(`Circuit breaker OPEN for ${this.providerName}`),
				};
			}
		}

		try {
			let result: T;

			if (this.config.enableCircuitBreaker) {
				// Execute with circuit breaker protection
				result = await this.circuitBreaker.execute(operation);
			} else {
				// Execute directly
				result = await operation();
			}

			// Operation succeeded
			this.onOperationSuccess();

			return {
				success: true,
				data: result,
				fallbackActivated: false,
				circuitOpen: false,
			};
		} catch (error) {
			// Operation failed
			const shouldFallback = this.onOperationFailure(error);

			return {
				success: false,
				error: error instanceof Error ? error : new Error(String(error)),
				fallbackActivated: shouldFallback,
				circuitOpen: this.circuitBreaker.getStats().state === CircuitState.OPEN,
			};
		}
	}

	/**
	 * Handle successful operation
	 */
	private onOperationSuccess(): void {
		// Reset failure count
		if (this.consecutiveFailures > 0) {
			logger.info(`${LOG_PREFIXES.FALLBACK} ${this.providerName} embeddings recovered`, {
				previousFailures: this.consecutiveFailures,
			});
		}

		this.consecutiveFailures = 0;

		// Update status based on current state
		if (this.status === EmbeddingStatus.RECOVERING) {
			this.status = EmbeddingStatus.HEALTHY;
			logger.info(`${LOG_PREFIXES.FALLBACK} ${this.providerName} embeddings fully recovered`);
		} else if (this.status === EmbeddingStatus.DISABLED) {
			this.status = EmbeddingStatus.RECOVERING;
			logger.info(`${LOG_PREFIXES.FALLBACK} ${this.providerName} embeddings started recovery`);
		}
	}

	/**
	 * Handle failed operation
	 */
	private onOperationFailure(error: any): boolean {
		this.consecutiveFailures++;

		const errorMessage = error instanceof Error ? error.message : String(error);
		const errorType = this.classifyError(error);

		logger.warn(`${LOG_PREFIXES.FALLBACK} ${this.providerName} embedding operation failed`, {
			error: errorMessage,
			errorType,
			consecutiveFailures: this.consecutiveFailures,
			maxFailures: this.config.maxConsecutiveFailures,
		});

		// Check if we should activate fallback
		if (
			this.config.enableFallback &&
			this.consecutiveFailures >= this.config.maxConsecutiveFailures
		) {
			this.isTemporarilyDisabled = true;
			this.status = EmbeddingStatus.DISABLED;

			logger.error(
				`${LOG_PREFIXES.FALLBACK} ${this.providerName} embeddings disabled after ${this.consecutiveFailures} consecutive failures - switching to chat-only mode`
			);

			return true; // Fallback activated
		}

		// Update status to degraded if not yet disabled
		if (this.status === EmbeddingStatus.HEALTHY) {
			this.status = EmbeddingStatus.DEGRADED;
		}

		return false; // No fallback yet
	}

	/**
	 * Classify error type for better handling
	 */
	private classifyError(error: any): string {
		if (error instanceof EmbeddingValidationError) {
			return 'validation';
		}
		if (error instanceof EmbeddingConnectionError) {
			return 'connection';
		}
		if (error instanceof EmbeddingError) {
			return 'embedding';
		}

		const message =
			error instanceof Error ? error.message.toLowerCase() : String(error).toLowerCase();

		if (message.includes('timeout') || message.includes('timed out')) {
			return 'timeout';
		}
		if (message.includes('rate limit') || message.includes('429')) {
			return 'rate_limit';
		}
		if (message.includes('quota') || message.includes('exceeded')) {
			return 'quota';
		}
		if (message.includes('unauthorized') || message.includes('401')) {
			return 'auth';
		}
		if (message.includes('network') || message.includes('connection')) {
			return 'network';
		}

		return 'unknown';
	}

	/**
	 * Start periodic health checking
	 */
	private startHealthChecking(): void {
		if (this.healthCheckTimer) {
			return; // Already started
		}

		this.healthCheckTimer = setInterval(async () => {
			await this.performHealthCheck();
		}, this.config.healthCheckInterval);

		logger.debug(`${LOG_PREFIXES.FALLBACK} Health checking started for ${this.providerName}`, {
			interval: this.config.healthCheckInterval,
		});
	}

	/**
	 * Perform health check and attempt recovery if needed
	 */
	private async performHealthCheck(): Promise<void> {
		this.lastHealthCheck = Date.now();

		try {
			// Only attempt recovery if we're in a failed state
			if (this.status === EmbeddingStatus.DISABLED) {
				// Check if enough time has passed since last recovery attempt
				const timeSinceLastAttempt = Date.now() - this.lastRecoveryAttempt;
				if (timeSinceLastAttempt < this.config.recoveryInterval) {
					return; // Too soon to retry
				}

				this.lastRecoveryAttempt = Date.now();

				logger.debug(`${LOG_PREFIXES.FALLBACK} Attempting recovery for ${this.providerName}`);

				// Try a simple health check
				const isHealthy = await this.embedder.isHealthy();

				if (isHealthy) {
					// Service appears to be back online
					this.isTemporarilyDisabled = false;
					this.consecutiveFailures = 0;
					this.status = EmbeddingStatus.RECOVERING;
					this.circuitBreaker.reset();

					logger.info(
						`${LOG_PREFIXES.FALLBACK} ${this.providerName} embeddings health check passed - enabling recovery mode`
					);
				}
			}
		} catch (error) {
			logger.debug(`${LOG_PREFIXES.FALLBACK} Health check failed for ${this.providerName}`, {
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}
}

/**
 * Safe Embedding Operations
 *
 * Provides safe wrappers for embedding operations that gracefully handle
 * failures and provide meaningful error messages for fallback scenarios.
 */

import { logger } from '../../logger/index.js';
import { LOG_PREFIXES } from './constants.js';

export interface SafeOperationResult<T> {
	success: boolean;
	data?: T | undefined;
	error?: string;
	fallbackActivated: boolean;
}

/**
 * Safe wrapper for embedding operations that may fail
 */
export async function safeEmbeddingOperation<T>(
	operation: () => Promise<T>,
	operationName: string,
	fallbackValue?: T
): Promise<SafeOperationResult<T>> {
	try {
		const result = await operation();
		return {
			success: true,
			data: result,
			fallbackActivated: false,
		};
	} catch (error) {
		const errorMessage = error instanceof Error ? error.message : String(error);

		// Check if this is a fallback scenario (embedding temporarily unavailable)
		const isFallbackScenario =
			errorMessage.includes('temporarily unavailable') ||
			errorMessage.includes('chat-only mode') ||
			errorMessage.includes('Circuit breaker OPEN') ||
			errorMessage.includes('embeddings disabled');

		if (isFallbackScenario) {
			logger.debug(`${LOG_PREFIXES.FALLBACK} ${operationName} skipped due to embedding fallback`, {
				reason: errorMessage,
				fallbackValue: fallbackValue !== undefined,
			});

			return {
				success: fallbackValue !== undefined,
				data: fallbackValue,
				error: errorMessage,
				fallbackActivated: true,
			};
		}

		// This is a real error, not a fallback scenario
		logger.error(`${LOG_PREFIXES.FALLBACK} ${operationName} failed with error`, {
			error: errorMessage,
		});

		return {
			success: false,
			error: errorMessage,
			fallbackActivated: false,
		};
	}
}

/**
 * Safe wrapper for vector store operations
 */
export async function safeVectorStoreOperation<T>(
	operation: () => Promise<T>,
	operationName: string,
	_fallbackMessage?: string
): Promise<SafeOperationResult<T>> {
	return safeEmbeddingOperation(operation, `Vector store ${operationName}`, undefined);
}

/**
 * Safe wrapper for memory operations with user-friendly fallback messages
 */
export async function safeMemoryOperation<T>(
	operation: () => Promise<T>,
	operationName: string,
	userFriendlyFallback: string
): Promise<SafeOperationResult<T>> {
	const result = await safeEmbeddingOperation(operation, operationName);

	if (result.fallbackActivated) {
		// Override with user-friendly message
		return {
			...result,
			error: userFriendlyFallback,
		};
	}

	return result;
}

/**
 * Check if an error indicates embedding fallback mode
 */
export function isEmbeddingFallbackError(error: any): boolean {
	const message = error instanceof Error ? error.message : String(error);
	return (
		message.includes('temporarily unavailable') ||
		message.includes('chat-only mode') ||
		message.includes('Circuit breaker OPEN') ||
		message.includes('embeddings disabled') ||
		message.includes('embedding-dependent tools will be disabled')
	);
}

/**
 * Get user-friendly error message for embedding fallback
 */
export function getFriendlyFallbackMessage(operationType: string): string {
	const messages = {
		search:
			'Memory search is temporarily unavailable. The system is operating in chat-only mode. Your conversation history is still maintained.',
		store:
			'Memory storage is temporarily unavailable. The system is operating in chat-only mode. Your current conversation will continue normally.',
		reasoning:
			'Reasoning pattern analysis is temporarily unavailable. The system is operating in chat-only mode with basic conversation capabilities.',
		knowledge:
			'Knowledge graph operations are temporarily unavailable. The system is operating in chat-only mode.',
		default:
			'This feature is temporarily unavailable due to embedding service issues. The system is operating in chat-only mode.',
	};

	return messages[operationType as keyof typeof messages] || messages.default;
}

/**
 * Log embedding status for debugging
 */
export function logEmbeddingStatus(embeddingManager?: any): void {
	if (!embeddingManager) {
		logger.debug(
			`${LOG_PREFIXES.FALLBACK} No embedding manager available - operating in chat-only mode`
		);
		return;
	}

	try {
		const hasAvailable = embeddingManager.hasAvailableEmbeddings?.();
		const status = embeddingManager.getEmbeddingStatus?.();

		logger.debug(`${LOG_PREFIXES.FALLBACK} Embedding status check`, {
			hasAvailableEmbeddings: hasAvailable,
			embeddingStatus: status,
		});
	} catch (error) {
		logger.debug(`${LOG_PREFIXES.FALLBACK} Could not get embedding status`, {
			error: error instanceof Error ? error.message : String(error),
		});
	}
}

/**
 * Embedding Module Public API Types
 *
 * This module re-exports all the necessary types and interfaces for the embedding system.
 * It provides a simplified, clean API surface for consumers of the embedding module.
 *
 * The embedding system architecture:
 * - Multiple provider support (OpenAI, future: Anthropic, Cohere, etc.)
 * - Consistent API across different providers
 * - Strong type safety with TypeScript and runtime validation with Zod
 * - Factory pattern for creating embedders
 * - Manager pattern for lifecycle management
 *
 * @module embedding/types
 *
 * @example
 * ```typescript
 * import type { Embedder, EmbeddingConfig } from './embedding/types.js';
 *
 * // Configure embedder
 * const config: EmbeddingConfig = {
 *   type: 'openai',
 *   apiKey: process.env.OPENAI_API_KEY,
 *   model: 'text-embedding-3-small'
 * };
 *
 * // Use embedder
 * const embedder = await createEmbedder(config);
 * const embedding = await embedder.embed('Hello world');
 * ```
 */

/**
 * Re-export core embedding types
 *
 * These exports provide the complete type system needed to work with
 * the embedding module without exposing internal implementation details.
 */
export type {
	// Core interfaces
	Embedder, // Interface for embedding providers
	EmbeddingConfig, // Base configuration interface
	OpenAIEmbeddingConfig, // OpenAI-specific configuration
	BackendConfig, // Union type for all provider configurations

	// Result types
	EmbeddingResult, // Single embedding result with metadata
	BatchEmbeddingResult, // Batch embedding result with metadata
} from './backend/types.js';

/**
 * Re-export error classes
 *
 * Comprehensive error hierarchy for embedding operations.
 */
export {
	EmbeddingError, // Base error class
	EmbeddingConnectionError, // Connection-related errors
	EmbeddingDimensionError, // Dimension mismatch errors
	EmbeddingRateLimitError, // Rate limiting errors
	EmbeddingQuotaError, // Quota exceeded errors
	EmbeddingValidationError, // Input validation errors
} from './backend/types.js';

/**
 * Re-export factory types
 *
 * Types related to embedding factory functionality.
 */
export type {
	EmbeddingFactory, // Factory interface for creating embedders
} from './factory.js';

/**
 * Re-export manager types
 *
 * Types related to embedding lifecycle management.
 */
export type {
	HealthCheckResult, // Health check result structure
	EmbedderInfo, // Information about embedder instances
	EmbeddingStats, // Statistics about embedding operations
} from './manager.js';

/**
 * Re-export configuration types and utilities
 *
 * Configuration validation and parsing utilities.
 */
export type {
	EmbeddingEnvConfig, // Environment-based configuration
} from './config.js';

/**
 * Embedding Utilities
 *
 * Utility functions for working with embedding configuration and
 * environment variables. Provides convenient access to environment-based
 * configuration for the embedding system.
 *
 * @module embedding/utils
 */

import { env } from '../../env.js';
import { type OpenAIEmbeddingConfig } from './backend/types.js';
import { DEFAULTS } from './constants.js';

/**
 * Get embedding configuration from environment variables
 *
 * Uses the centralized env configuration to build embedding config.
 * Falls back to sensible defaults when environment variables are not set.
 *
 * @returns OpenAI embedding configuration or null if no API key
 *
 * @example
 * ```typescript
 * const config = getEmbeddingConfigFromEnv();
 * if (config) {
 *   const embedder = await createEmbedder(config);
 * }
 * ```
 */
export function getEmbeddingConfigFromEnv(): OpenAIEmbeddingConfig | null {
	// Check if we have a required API key
	if (!env.OPENAI_API_KEY) {
		return null;
	}

	const config: OpenAIEmbeddingConfig = {
		type: 'openai',
		apiKey: env.OPENAI_API_KEY!,
		model: (env.EMBEDDING_MODEL as any) || DEFAULTS.OPENAI_MODEL,
		baseUrl: env.OPENAI_BASE_URL || DEFAULTS.OPENAI_BASE_URL,
		timeout: env.EMBEDDING_TIMEOUT || DEFAULTS.TIMEOUT,
		maxRetries: env.EMBEDDING_MAX_RETRIES || DEFAULTS.MAX_RETRIES,
		organization: env.OPENAI_ORG_ID || '',
	};

	return config;
}

/**
 * Check if embedding configuration is available in environment
 *
 * @returns True if embedding can be configured from environment variables
 *
 * @example
 * ```typescript
 * if (isEmbeddingConfigAvailable()) {
 *   const embedder = await createEmbedderFromEnv();
 * } else {
 *   console.log('Please set OPENAI_API_KEY environment variable');
 * }
 * ```
 */
export function isEmbeddingConfigAvailable(): boolean {
	return !!env.OPENAI_API_KEY;
}

/**
 * Get embedding configuration summary for logging/debugging
 *
 * Returns safe configuration info without exposing sensitive data.
 *
 * @returns Configuration summary object
 *
 * @example
 * ```typescript
 * const summary = getEmbeddingConfigSummary();
 * console.log('Embedding config:', summary);
 * // Output: { hasApiKey: true, model: 'text-embedding-3-small', ... }
 * ```
 */
export function getEmbeddingConfigSummary(): {
	hasApiKey: boolean;
	model?: string;
	baseUrl?: string;
	timeout?: number;
	maxRetries?: number;
	hasOrganization: boolean;
} {
	return {
		hasApiKey: !!env.OPENAI_API_KEY,
		model: env.EMBEDDING_MODEL || DEFAULTS.OPENAI_MODEL,
		baseUrl: env.OPENAI_BASE_URL || DEFAULTS.OPENAI_BASE_URL,
		timeout: env.EMBEDDING_TIMEOUT || DEFAULTS.TIMEOUT,
		maxRetries: env.EMBEDDING_MAX_RETRIES || DEFAULTS.MAX_RETRIES,
		hasOrganization: !!env.OPENAI_ORG_ID,
	};
}

/**
 * Validate that required environment variables are set for embeddings
 *
 * @returns Validation result with details
 *
 * @example
 * ```typescript
 * const validation = validateEmbeddingEnv();
 * if (!validation.valid) {
 *   console.error('Embedding setup issues:', validation.issues);
 * }
 * ```
 */
export function validateEmbeddingEnv(): {
	valid: boolean;
	issues: string[];
} {
	const issues: string[] = [];

	// Check required variables
	if (!env.OPENAI_API_KEY) {
		// Check if other LLM providers are configured
		const hasOtherProviders = env.ANTHROPIC_API_KEY || env.OPENROUTER_API_KEY;
		if (hasOtherProviders) {
			issues.push(
				'OPENAI_API_KEY is required for embedding functionality, even when using Anthropic or OpenRouter for LLM services'
			);
		} else {
			issues.push('OPENAI_API_KEY is required for embedding functionality');
		}
	}

	// Check API key format
	if (env.OPENAI_API_KEY && !env.OPENAI_API_KEY.startsWith('sk-')) {
		issues.push('OPENAI_API_KEY should start with "sk-"');
	}

	// Check numeric values
	if (env.EMBEDDING_TIMEOUT && env.EMBEDDING_TIMEOUT <= 0) {
		issues.push('EMBEDDING_TIMEOUT must be a positive number');
	}

	if (env.EMBEDDING_MAX_RETRIES && env.EMBEDDING_MAX_RETRIES < 0) {
		issues.push('EMBEDDING_MAX_RETRIES must be a non-negative number');
	}

	// Check URL format
	if (env.OPENAI_BASE_URL) {
		try {
			new URL(env.OPENAI_BASE_URL);
		} catch {
			issues.push('OPENAI_BASE_URL must be a valid URL');
		}
	}

	return {
		valid: issues.length === 0,
		issues,
	};
}

/**
 * Check for mixed provider configuration and provide helpful guidance
 *
 * @returns Configuration analysis with recommendations
 *
 * @example
 * ```typescript
 * const analysis = analyzeProviderConfiguration();
 * if (analysis.warnings.length > 0) {
 *   console.warn('Configuration warnings:', analysis.warnings);
 * }
 * ```
 */
export function analyzeProviderConfiguration(): {
	usingMixedProviders: boolean;
	llmProvider: 'openai' | 'anthropic' | 'openrouter' | 'none' | 'multiple';
	embeddingProvider: 'openai' | 'none';
	warnings: string[];
	recommendations: string[];
} {
	const warnings: string[] = [];
	const recommendations: string[] = [];

	// Detect which LLM providers are configured
	const hasOpenAI = !!env.OPENAI_API_KEY;
	const hasAnthropic = !!env.ANTHROPIC_API_KEY;
	const hasOpenRouter = !!env.OPENROUTER_API_KEY;

	let llmProvider: 'openai' | 'anthropic' | 'openrouter' | 'none' | 'multiple';
	const configuredProviders = [
		hasOpenAI && 'openai',
		hasAnthropic && 'anthropic',
		hasOpenRouter && 'openrouter',
	].filter(Boolean);

	if (configuredProviders.length === 0) {
		llmProvider = 'none';
		warnings.push('No LLM provider API keys configured');
	} else if (configuredProviders.length === 1) {
		llmProvider = configuredProviders[0] as 'openai' | 'anthropic' | 'openrouter';
	} else {
		llmProvider = 'multiple';
		recommendations.push(
			'Multiple LLM provider API keys detected. The system will use the configured provider in your LLM service setup.'
		);
	}

	// Embedding provider analysis
	const embeddingProvider = hasOpenAI ? 'openai' : 'none';
	const usingMixedProviders = (hasAnthropic || hasOpenRouter) && hasOpenAI;

	// Generate specific warnings and recommendations
	if (!hasOpenAI && (hasAnthropic || hasOpenRouter)) {
		warnings.push('Embedding functionality will not work without OPENAI_API_KEY');
		recommendations.push(
			'Add OPENAI_API_KEY to enable embedding features, even when using Anthropic or OpenRouter for LLM'
		);
	}

	if (usingMixedProviders) {
		recommendations.push(
			'You are using a mixed provider setup (non-OpenAI for LLM + OpenAI for embeddings). This is a valid configuration.'
		);
	}

	if (hasOpenAI && !hasAnthropic && !hasOpenRouter) {
		recommendations.push(
			'Using OpenAI for both LLM and embeddings - this is the simplest configuration.'
		);
	}

	return {
		usingMixedProviders,
		llmProvider,
		embeddingProvider,
		warnings,
		recommendations,
	};
}

export * from './memAgent/index.js';
export * from './llm/index.js';
export * from './reasoning/index.js';

import { describe, it, expect } from 'vitest';
import {
	createCompressionStrategy,
	createCompressionStrategySync,
	getCompressionConfigForProvider,
} from '../factory.js';
import { MiddleRemovalStrategy } from '../strategies/middle-removal.js';
import { OldestRemovalStrategy } from '../strategies/oldest-removal.js';
import { HybridStrategy } from '../strategies/hybrid.js';
import { CompressionConfigSchema } from '../types.js';

describe('Compression Factory', () => {
	describe('createCompressionStrategy (async with caching)', () => {
		it('should create MiddleRemovalStrategy', async () => {
			const config = {
				strategy: 'middle-removal' as const,
				maxTokens: 4096,
				warningThreshold: 0.8,
				compressionThreshold: 0.9,
				preserveStart: 4,
				preserveEnd: 5,
				minMessagesToKeep: 4,
			};

			const strategy = await createCompressionStrategy(config);
			expect(strategy).toBeInstanceOf(MiddleRemovalStrategy);
			expect(strategy.name).toBe('middle-removal');
		});

		it('should create OldestRemovalStrategy', async () => {
			const config = {
				strategy: 'oldest-removal' as const,
				maxTokens: 4096,
				warningThreshold: 0.8,
				compressionThreshold: 0.9,
				preserveStart: 4,
				preserveEnd: 5,
				minMessagesToKeep: 4,
			};

			const strategy = await createCompressionStrategy(config);
			expect(strategy).toBeInstanceOf(OldestRemovalStrategy);
			expect(strategy.name).toBe('oldest-removal');
		});

		it('should create HybridStrategy', async () => {
			const config = {
				strategy: 'hybrid' as const,
				maxTokens: 4096,
				warningThreshold: 0.8,
				compressionThreshold: 0.9,
				preserveStart: 4,
				preserveEnd: 5,
				minMessagesToKeep: 4,
			};

			const strategy = await createCompressionStrategy(config);
			expect(strategy).toBeInstanceOf(HybridStrategy);
			expect(strategy.name).toBe('hybrid');
		});

		it('should validate config schema', async () => {
			const invalidConfig = {
				strategy: 'invalid-strategy',
				maxTokens: -100, // Invalid negative value
			};

			await expect(createCompressionStrategy(invalidConfig as any)).rejects.toThrow();
		});
	});

	describe('createCompressionStrategySync (backward compatibility)', () => {
		it('should create MiddleRemovalStrategy synchronously', () => {
			const config = {
				strategy: 'middle-removal' as const,
				maxTokens: 4096,
				warningThreshold: 0.8,
				compressionThreshold: 0.9,
				preserveStart: 4,
				preserveEnd: 5,
				minMessagesToKeep: 4,
			};

			const strategy = createCompressionStrategySync(config);
			expect(strategy).toBeInstanceOf(MiddleRemovalStrategy);
