import { describe, it, expect, beforeEach } from 'vitest';
import { MiddleRemovalStrategy } from '../strategies/middle-removal.js';
import { OldestRemovalStrategy } from '../strategies/oldest-removal.js';
import { HybridStrategy } from '../strategies/hybrid.js';
import { EnhancedInternalMessage, CompressionConfig, CompressionLevel } from '../types.js';

describe('Compression Strategies', () => {
	const baseConfig: CompressionConfig = {
		strategy: 'middle-removal',
		maxTokens: 1000,
		warningThreshold: 0.8,
		compressionThreshold: 0.9,
		preserveStart: 2,
		preserveEnd: 2,
		minMessagesToKeep: 4,
	};

	const createTestMessages = (count: number): EnhancedInternalMessage[] => {
		return Array.from({ length: count }, (_, i) => ({
			role: i === 0 ? 'system' : i % 2 === 1 ? 'user' : 'assistant',
			content: `Message ${i} content with some text to test token counting`,
			messageId: `msg_${i}`,
			timestamp: Date.now() - (count - i) * 1000,
			tokenCount: 50, // Approximate token count
			priority: i === 0 ? 'critical' : 'normal',
		}));
	};

	describe('MiddleRemovalStrategy', () => {
		let strategy: MiddleRemovalStrategy;

		beforeEach(() => {
			strategy = new MiddleRemovalStrategy(baseConfig);
		});

		it('should preserve start and end messages', async () => {
			const messages = createTestMessages(10);
			const currentTokens = 500;
			const targetTokens = 300;

			const result = await strategy.compress(messages, currentTokens, targetTokens);

			expect(result.compressedMessages.length).toBeGreaterThanOrEqual(baseConfig.minMessagesToKeep);
			expect(result.compressedMessages.length).toBeLessThan(messages.length);

			// Should preserve system message (critical priority)
			const systemMessages = result.compressedMessages.filter(m => m.role === 'system');
			expect(systemMessages.length).toBe(1);

			// Should preserve some start and end messages
			expect(result.compressedMessages.length).toBeGreaterThan(2);
		});

		it('should not compress if target is already met', async () => {
			const messages = createTestMessages(5);
			const currentTokens = 200;
			const targetTokens = 300;

			const result = await strategy.compress(messages, currentTokens, targetTokens);

			expect(result.compressedMessages.length).toBe(messages.length);
			expect(result.removedMessages.length).toBe(0);
		});

		it('should respect minimum messages to keep', async () => {
			const messages = createTestMessages(6); // Create more than minMessagesToKeep
			const currentTokens = 500;
			const targetTokens = 50; // Very aggressive target

			const result = await strategy.compress(messages, currentTokens, targetTokens);

			// Should keep at least minMessagesToKeep (4) messages
			expect(result.compressedMessages.length).toBeGreaterThanOrEqual(baseConfig.minMessagesToKeep);
		});
	});

	describe('OldestRemovalStrategy', () => {
		let strategy: OldestRemovalStrategy;

		beforeEach(() => {
			strategy = new OldestRemovalStrategy({ ...baseConfig, strategy: 'oldest-removal' });
		});

		it('should remove oldest messages first', async () => {
			const messages = createTestMessages(8);
			const currentTokens = 400;
			const targetTokens = 250;

			const result = await strategy.compress(messages, currentTokens, targetTokens);

			expect(result.compressedMessages.length).toBeLessThan(messages.length);
			expect(result.removedMessages.length).toBeGreaterThan(0);

			// Should preserve system message
			const systemMessages = result.compressedMessages.filter(m => m.role === 'system');
			expect(systemMessages.length).toBe(1);

			// Removed messages should be older than kept messages (excluding system)
			const keptTimestamps = result.compressedMessages
				.filter(m => m.role !== 'system')
				.map(m => m.timestamp || 0);
			const removedTimestamps = result.removedMessages.map(m => m.timestamp || 0);

			if (removedTimestamps.length > 0 && keptTimestamps.length > 0) {
				const oldestKept = Math.min(...keptTimestamps);
				const newestRemoved = Math.max(...removedTimestamps);
				expect(newestRemoved).toBeLessThanOrEqual(oldestKept);
			}
		});
	});

	describe('HybridStrategy', () => {
		let strategy: HybridStrategy;

		beforeEach(() => {
			strategy = new HybridStrategy({ ...baseConfig, strategy: 'hybrid' });
		});

		it('should choose appropriate strategy based on conversation characteristics', async () => {
			const messages = createTestMessages(6);
			const currentTokens = 350;
			const targetTokens = 200;

			const result = await strategy.compress(messages, currentTokens, targetTokens);

			expect(result.compressedMessages.length).toBeLessThan(messages.length);
			expect(result.strategy).toBe('hybrid');
			expect(result.compressionRatio).toBeLessThan(1);
		});

		it('should handle adaptive compression when no clear strategy emerges', async () => {
			// Create a balanced conversation that doesn't strongly favor either strategy
			const messages = createTestMessages(10);
			const currentTokens = 500;
			const targetTokens = 300;

			const result = await strategy.compress(messages, currentTokens, targetTokens);

			expect(result).toBeDefined();
			expect(result.strategy).toBe('hybrid');
			expect(result.compressedMessages.length).toBeGreaterThanOrEqual(baseConfig.minMessagesToKeep);
		});
	});

	describe('Compression Level Detection', () => {
		let strategy: MiddleRemovalStrategy;

		beforeEach(() => {
			strategy = new MiddleRemovalStrategy(baseConfig);
		});

		it('should detect NONE level for low token usage', () => {
			const level = strategy.getCompressionLevel(700); // 70% of 1000
			expect(level).toBe(CompressionLevel.NONE);
		});

		it('should detect WARNING level for medium token usage', () => {
			const level = strategy.getCompressionLevel(850); // 85% of 1000
			expect(level).toBe(CompressionLevel.WARNING);
		});

		it('should detect SOFT level for high token usage', () => {
			const level = strategy.getCompressionLevel(920); // 92% of 1000
			expect(level).toBe(CompressionLevel.SOFT);
		});

		it('should detect HARD level for very high token usage', () => {
			const level = strategy.getCompressionLevel(970); // 97% of 1000
			expect(level).toBe(CompressionLevel.HARD);
		});

		it('should detect EMERGENCY level for exceeded limits', () => {
			const level = strategy.getCompressionLevel(1100); // 110% of 1000
			expect(level).toBe(CompressionLevel.EMERGENCY);
		});
	});

	describe('shouldCompress', () => {
		let strategy: MiddleRemovalStrategy;

		beforeEach(() => {
			strategy = new MiddleRemovalStrategy(baseConfig);
		});

		it('should not compress below threshold', () => {
			expect(strategy.shouldCompress(800)).toBe(false); // 80% < 90% threshold
		});

		it('should compress at or above threshold', () => {
			expect(strategy.shouldCompress(900)).toBe(true); // 90% >= 90% threshold
			expect(strategy.shouldCompress(1100)).toBe(true); // 110% >= 90% threshold
		});
	});
});

import { ICompressionStrategy, CompressionConfigSchema } from './types.js';
import { MiddleRemovalStrategy } from './strategies/middle-removal.js';
import { OldestRemovalStrategy } from './strategies/oldest-removal.js';
import { HybridStrategy } from './strategies/hybrid.js';
import { logger } from '../../../logger/index.js';
import { getServiceCache, createServiceKey } from '../../memory/service-cache.js';
import { z } from 'zod';

export type CompressionFactoryConfig = z.infer<typeof CompressionConfigSchema>;

/**
 * Create a compression strategy instance based on configuration with caching
 */
export async function createCompressionStrategy(
	config: CompressionFactoryConfig
): Promise<ICompressionStrategy> {
	const validatedConfig = CompressionConfigSchema.parse(config);

	// Use ServiceCache to prevent duplicate compression strategy creation
	const serviceCache = getServiceCache();
	const cacheKey = createServiceKey('compressionStrategy', validatedConfig);

	return await serviceCache.getOrCreate(cacheKey, async () => {
		logger.debug('Creating compression strategy', {
			strategy: validatedConfig.strategy,
			maxTokens: validatedConfig.maxTokens,
		});

		switch (validatedConfig.strategy) {
			case 'middle-removal':
				return new MiddleRemovalStrategy(validatedConfig);
			case 'oldest-removal':
				return new OldestRemovalStrategy(validatedConfig);
			case 'hybrid':
				return new HybridStrategy(validatedConfig);
			default:
				logger.warn('Unknown compression strategy, falling back to middle-removal', {
					strategy: validatedConfig.strategy,
				});
				return new MiddleRemovalStrategy(validatedConfig);
		}
	});
}

/**
 * Synchronous version for backward compatibility (creates without caching)
 */
export function createCompressionStrategySync(
	config: CompressionFactoryConfig
): ICompressionStrategy {
	const validatedConfig = CompressionConfigSchema.parse(config);

	logger.debug('Creating compression strategy (sync)', {
		strategy: validatedConfig.strategy,
		maxTokens: validatedConfig.maxTokens,
	});

	switch (validatedConfig.strategy) {
		case 'middle-removal':
			return new MiddleRemovalStrategy(validatedConfig);
		case 'oldest-removal':
			return new OldestRemovalStrategy(validatedConfig);
		case 'hybrid':
			return new HybridStrategy(validatedConfig);
		default:
			logger.warn('Unknown compression strategy, falling back to middle-removal', {
				strategy: validatedConfig.strategy,
			});
			return new MiddleRemovalStrategy(validatedConfig);
	}
}

/**
 * Get recommended compression config for a provider/model
 */
export function getCompressionConfigForProvider(
	provider: string,
	model?: string,
	contextWindow?: number
): CompressionFactoryConfig {
	const baseConfig: CompressionFactoryConfig = {
		strategy: 'hybrid',
		maxTokens: contextWindow || 8192,
		warningThreshold: 0.8,
		compressionThreshold: 0.9,
		preserveStart: 4,
		preserveEnd: 5,
		minMessagesToKeep: 4,
	};

	// Provider-specific optimizations
	switch (provider) {
		case 'openai':
			if (model?.startsWith('gpt-4')) {
				return {
					...baseConfig,
					strategy: 'hybrid',
					preserveStart: 6,
					preserveEnd: 6,
					warningThreshold: 0.85,
				};
			}
			if (model?.startsWith('o1-')) {
				return {
					...baseConfig,
					strategy: 'middle-removal',
					preserveStart: 8,
					preserveEnd: 8,
					warningThreshold: 0.9,
					compressionThreshold: 0.95,
				};
			}
			break;

		case 'anthropic':
			return {
				...baseConfig,
				strategy: 'oldest-removal',
				preserveStart: 5,
				preserveEnd: 7,
				warningThreshold: 0.85,
				compressionThreshold: 0.92,
			};

		case 'lmstudio':
		case 'ollama':
			// Local models typically have smaller context windows
			return {
				...baseConfig,
				strategy: 'hybrid',
				warningThreshold: 0.7,
				compressionThreshold: 0.8,
				preserveStart: 3,
				preserveEnd: 4,
				minMessagesToKeep: 3,
			};

		case 'google':
			if (model?.includes('1.5')) {
				// Large context models need less aggressive compression
				return {
					...baseConfig,
					strategy: 'middle-removal',
					warningThreshold: 0.9,
					compressionThreshold: 0.95,
					preserveStart: 10,
					preserveEnd: 10,
				};
			}
			break;
	}

	return baseConfig;
}

/**
 * Create adaptive compression config that adjusts based on usage patterns
 */
export function createAdaptiveCompressionConfig(
	baseConfig: CompressionFactoryConfig,
	usageHistory: {
		avgMessageLength: number;
		compressionFrequency: number;
		conversationLength: number;
	}
): CompressionFactoryConfig {
	const adaptedConfig = { ...baseConfig };

	// Adjust thresholds based on compression frequency
	if (usageHistory.compressionFrequency > 0.3) {
		// Frequent compression - be more aggressive
		adaptedConfig.warningThreshold *= 0.9;
		adaptedConfig.compressionThreshold *= 0.95;
	} else if (usageHistory.compressionFrequency < 0.1) {
		// Rare compression - be more conservative
		adaptedConfig.warningThreshold *= 1.1;
		adaptedConfig.compressionThreshold *= 1.05;
	}

	// Adjust preservation based on conversation length
	if (usageHistory.conversationLength > 50) {
		// Long conversations - preserve more context
		adaptedConfig.preserveStart = Math.min(adaptedConfig.preserveStart + 2, 10);
		adaptedConfig.preserveEnd = Math.min(adaptedConfig.preserveEnd + 2, 10);
	}

	// Adjust strategy based on message characteristics
	if (usageHistory.avgMessageLength > 1000) {
		// Long messages - prefer middle removal to maintain flow
		adaptedConfig.strategy = 'middle-removal';
	} else if (usageHistory.avgMessageLength < 100) {
		// Short messages - oldest removal might be better
		adaptedConfig.strategy = 'oldest-removal';
	}

	// Ensure values stay within valid ranges
	adaptedConfig.warningThreshold = Math.max(0.5, Math.min(0.95, adaptedConfig.warningThreshold));
	adaptedConfig.compressionThreshold = Math.max(
		0.6,
		Math.min(0.98, adaptedConfig.compressionThreshold)
	);

	logger.debug('Created adaptive compression config', {
		original: baseConfig,
		adapted: adaptedConfig,
		usageHistory,
	});

	return adaptedConfig;
}

// Compression module exports
export * from './types.js';
export * from './factory.js';
export * from './utils.js';

// Strategy exports
export { MiddleRemovalStrategy } from './strategies/middle-removal.js';
export { OldestRemovalStrategy } from './strategies/oldest-removal.js';
export { HybridStrategy } from './strategies/hybrid.js';

import {
	ICompressionStrategy,
	CompressionConfig,
	CompressionResult,
	EnhancedInternalMessage,
	CompressionLevel,
} from '../types.js';
import {
	assignMessagePriorities,
	calculateTotalTokens,
	validateCompressionResult,
	logCompressionOperation,
	ensureMessageIds,
	calculateCompressionEfficiency,
} from '../utils.js';
import { MiddleRemovalStrategy } from './middle-removal.js';
import { OldestRemovalStrategy } from './oldest-removal.js';
import { logger } from '../../../../logger/index.js';

/**
 * Hybrid Strategy
 * Intelligently combines middle-removal and oldest-removal strategies
 * Chooses the best approach based on conversation characteristics
 */
export class HybridStrategy implements ICompressionStrategy {
	public readonly name = 'hybrid';
	public readonly config: CompressionConfig;

	private middleRemovalStrategy: MiddleRemovalStrategy;
	private oldestRemovalStrategy: OldestRemovalStrategy;

	constructor(config: CompressionConfig) {
		this.config = config;
		this.middleRemovalStrategy = new MiddleRemovalStrategy(config);
		this.oldestRemovalStrategy = new OldestRemovalStrategy(config);

		logger.debug('HybridStrategy initialized', config);
	}

	async compress(
		messages: EnhancedInternalMessage[],
		currentTokenCount: number,
		targetTokenCount: number
	): Promise<CompressionResult> {
		const startTime = Date.now();

		// Ensure messages have IDs and priorities
		let processedMessages = ensureMessageIds(messages);
		processedMessages = assignMessagePriorities(processedMessages);

		logger.debug('Starting hybrid compression', {
			messageCount: processedMessages.length,
			currentTokens: currentTokenCount,
			targetTokens: targetTokenCount,
			tokensToRemove: currentTokenCount - targetTokenCount,
		});

		// Analyze conversation characteristics to choose strategy
		const conversationAnalysis = this.analyzeConversation(
			processedMessages,
			currentTokenCount,
			targetTokenCount
		);

		logger.debug('Conversation analysis for hybrid strategy', conversationAnalysis);

		let result: CompressionResult;

		if (conversationAnalysis.recommendedStrategy === 'middle-removal') {
			logger.debug('Hybrid strategy choosing middle-removal');
			result = await this.middleRemovalStrategy.compress(
				messages,
				currentTokenCount,
				targetTokenCount
			);
		} else if (conversationAnalysis.recommendedStrategy === 'oldest-removal') {
			logger.debug('Hybrid strategy choosing oldest-removal');
			result = await this.oldestRemovalStrategy.compress(
				messages,
				currentTokenCount,
				targetTokenCount
			);
		} else {
			// Adaptive approach: try both and choose the better result
			logger.debug('Hybrid strategy using adaptive approach');
			result = await this.adaptiveCompress(messages, currentTokenCount, targetTokenCount);
		}

		// Update result to reflect hybrid strategy
		result.strategy = this.name;

		const duration = Date.now() - startTime;
		logCompressionOperation('hybrid compression completed', result, {
			duration,
			analysis: conversationAnalysis,
			chosenStrategy: conversationAnalysis.recommendedStrategy || 'adaptive',
		});

		return result;
	}

	private async adaptiveCompress(
		messages: EnhancedInternalMessage[],
		currentTokenCount: number,
		targetTokenCount: number
	): Promise<CompressionResult> {
		// Try both strategies and compare results
		const middleResult = await this.middleRemovalStrategy.compress(
			messages,
			currentTokenCount,
			targetTokenCount
		);
		const oldestResult = await this.oldestRemovalStrategy.compress(
			messages,
			currentTokenCount,
			targetTokenCount
		);

		// Calculate efficiency scores for both results
		const middleEfficiency = calculateCompressionEfficiency(middleResult);
		const oldestEfficiency = calculateCompressionEfficiency(oldestResult);

		logger.debug('Comparing compression strategies', {
			middleEfficiency,
			oldestEfficiency,
			middleTokens: middleResult.compressedTokenCount,
			oldestTokens: oldestResult.compressedTokenCount,
		});

		// Choose the more efficient strategy
		if (middleEfficiency >= oldestEfficiency) {
			return middleResult;
		} else {
			return oldestResult;
		}
	}

	private analyzeConversation(
		messages: EnhancedInternalMessage[],
		currentTokenCount: number,
		targetTokenCount: number
	): ConversationAnalysis {
		const totalMessages = messages.length;
		const avgMessageLength = currentTokenCount / totalMessages;
		const compressionRatio = targetTokenCount / currentTokenCount;

		// Analyze message distribution
		const recentMessages = messages.slice(-5);
		const recentTokens = calculateTotalTokens(recentMessages);
		const recentRatio = recentTokens / currentTokenCount;

		// Analyze conversation patterns
		const hasLongMessages = messages.some(m => (m.tokenCount || 0) > 300);
		const hasSystemMessages = messages.some(m => m.role === 'system');
		const hasToolMessages = messages.some(m => m.role === 'tool');

		// Determine compression severity
		const compressionSeverity = this.getCompressionSeverity(compressionRatio);

		let recommendedStrategy: string | null = null;
		let confidence = 0;

		// Decision logic based on conversation characteristics
		if (compressionSeverity === 'light' && totalMessages < 20) {
			// Light compression on short conversations - prefer middle removal
			recommendedStrategy = 'middle-removal';
			confidence = 0.8;
		} else if (compressionSeverity === 'heavy' && totalMessages > 30) {
			// Heavy compression on long conversations - prefer oldest removal
			recommendedStrategy = 'oldest-removal';
			confidence = 0.9;
		} else if (recentRatio > 0.4) {
			// Recent messages are token-heavy - prefer middle removal to preserve recent context
			recommendedStrategy = 'middle-removal';
			confidence = 0.7;
		} else if (hasLongMessages && compressionSeverity !== 'light') {
			// Has long messages and significant compression needed - oldest removal might be better
			recommendedStrategy = 'oldest-removal';
			confidence = 0.6;
		} else if (hasToolMessages || hasSystemMessages) {
			// Has important message types - be more conservative with middle removal
			recommendedStrategy = 'middle-removal';
			confidence = 0.7;
		}

		// If confidence is low, use adaptive approach
		if (confidence < 0.6) {
			recommendedStrategy = null; // Will trigger adaptive approach
		}

		return {
			totalMessages,
			avgMessageLength,
			compressionRatio,
			recentRatio,
			compressionSeverity,
			hasLongMessages,
			hasSystemMessages,
			hasToolMessages,
			recommendedStrategy,
			confidence,
		};
	}

	private getCompressionSeverity(compressionRatio: number): 'light' | 'moderate' | 'heavy' {
		if (compressionRatio > 0.8) return 'light';
		if (compressionRatio > 0.6) return 'moderate';
		return 'heavy';
	}

	shouldCompress(currentTokenCount: number): boolean {
		const threshold = this.config.maxTokens * this.config.compressionThreshold;
		return currentTokenCount >= threshold;
	}

	getCompressionLevel(currentTokenCount: number): number {
		const warningThreshold = this.config.maxTokens * this.config.warningThreshold;
		const compressionThreshold = this.config.maxTokens * this.config.compressionThreshold;

		if (currentTokenCount < warningThreshold) {
			return CompressionLevel.NONE;
		} else if (currentTokenCount < compressionThreshold) {
			return CompressionLevel.WARNING;
		} else if (currentTokenCount < this.config.maxTokens * 0.95) {
			return CompressionLevel.SOFT;
		} else if (currentTokenCount < this.config.maxTokens) {
			return CompressionLevel.HARD;
		} else {
			return CompressionLevel.EMERGENCY;
		}
	}

	validateCompression(result: CompressionResult): boolean {
		return validateCompressionResult(result, this.config.minMessagesToKeep);
	}

	/**
	 * Get strategy-specific statistics
	 */
	getStrategyStats(): any {
		return {
			name: this.name,
			compressionType: 'hybrid',
			strategies: ['middle-removal', 'oldest-removal'],
			bestFor: 'adaptive compression based on conversation characteristics',
			decisionFactors: [
				'conversation length',
				'compression severity',
				'recent context weight',
				'message types',
				'token distribution',
			],
		};
	}
}

/**
 * Analysis result for conversation characteristics
 */
interface ConversationAnalysis {
	totalMessages: number;
	avgMessageLength: number;
	compressionRatio: number;
	recentRatio: number;
	compressionSeverity: 'light' | 'moderate' | 'heavy';
	hasLongMessages: boolean;
	hasSystemMessages: boolean;
	hasToolMessages: boolean;
	recommendedStrategy: string | null;
	confidence: number;
}

import {
	ICompressionStrategy,
	CompressionConfig,
	CompressionResult,
	EnhancedInternalMessage,
	CompressionLevel,
} from '../types.js';
import {
	assignMessagePriorities,
	getPreservableMessages,
	getRemovableMessages,
	calculateTotalTokens,
	createCompressionResult,
	validateCompressionResult,
	logCompressionOperation,
	ensureMessageIds,
} from '../utils.js';
import { logger } from '../../../../logger/index.js';

/**
 * Middle Removal Strategy
 * Preserves conversation start and end, removes messages from the middle
 * Best for maintaining conversation flow and recent context
 */
export class MiddleRemovalStrategy implements ICompressionStrategy {
	public readonly name = 'middle-removal';
	public readonly config: CompressionConfig;

	constructor(config: CompressionConfig) {
		this.config = config;
		logger.debug('MiddleRemovalStrategy initialized', config);
	}

	async compress(
		messages: EnhancedInternalMessage[],
		currentTokenCount: number,
		targetTokenCount: number
	): Promise<CompressionResult> {
		const startTime = Date.now();

		const originalMessages = [...messages];
		// Ensure messages have IDs and priorities
		let processedMessages = ensureMessageIds(messages);
		processedMessages = assignMessagePriorities(processedMessages);

		logger.debug('Starting middle removal compression', {
			messageCount: processedMessages.length,
			currentTokens: currentTokenCount,
			targetTokens: targetTokenCount,
			tokensToRemove: currentTokenCount - targetTokenCount,
		});

		// Use configuration values instead of hardcoded ones
		const minMessagesToKeep = this.config.minMessagesToKeep;
		const preserveStart = Math.min(this.config.preserveStart, processedMessages.length);
		const preserveEnd = Math.min(this.config.preserveEnd, processedMessages.length);

		const preservableMessages = getPreservableMessages(processedMessages);
		const removableMessages = getRemovableMessages(processedMessages);

		if (removableMessages.length === 0) {
			logger.warn('No removable messages found for compression');
			return createCompressionResult(originalMessages, processedMessages, [], this.name);
		}

		// Sort removable messages by their original position
		const sortedRemovable = removableMessages.sort((a, b) => {
			const aIndex = processedMessages.indexOf(a);
			const bIndex = processedMessages.indexOf(b);
			return aIndex - bIndex;
		});

		// Identify start, middle, and end sections
		const startMessages = sortedRemovable.slice(0, preserveStart);
		const endMessages = sortedRemovable.slice(-preserveEnd);
		const middleMessages = sortedRemovable.slice(
			preserveStart,
			sortedRemovable.length - preserveEnd
		);

		// Start with all preservable messages and the start/end messages we want to keep
		let compressedMessages = [...preservableMessages, ...startMessages, ...endMessages];
		let removedMessages: EnhancedInternalMessage[] = [];
		let currentTokens = calculateTotalTokens(compressedMessages);

		// Remove middle messages until we reach target or run out of removable messages
		for (const message of middleMessages) {
			// Check if removing this message would violate minimum message count
			if (compressedMessages.length <= minMessagesToKeep) {
				break;
			}

			// Check if we've already reached our target
			if (currentTokens <= targetTokenCount) {
				break;
			}

			// Actually remove the message from compressedMessages
			const messageIndex = compressedMessages.findIndex(m => m.messageId === message.messageId);
			if (messageIndex !== -1) {
				compressedMessages.splice(messageIndex, 1);
			}

			// Add to removed messages and update token count
			removedMessages.push(message);
			currentTokens = calculateTotalTokens(compressedMessages);

			logger.debug('Removed middle message', {
				messageId: message.messageId,
				tokensAfterRemoval: currentTokens,
				targetTokens: targetTokenCount,
				messagesRemaining: compressedMessages.length,
			});
		}

		// Ensure we maintain minimum message count
		if (compressedMessages.length < minMessagesToKeep) {
			const restoreCount = minMessagesToKeep - compressedMessages.length;
			const toRestore = removedMessages.slice(-restoreCount);

			compressedMessages.push(...toRestore);
			removedMessages = removedMessages.slice(0, -restoreCount);

			logger.warn('Restored messages to meet minMessagesToKeep', {
				restoreCount,
				minMessagesToKeep,
				messagesRestored: toRestore.map(m => m.messageId),
			});
		}

		// Sort final messages to maintain original conversation order
		compressedMessages = compressedMessages.sort((a, b) => {
			const aIndex = processedMessages.indexOf(a);
			const bIndex = processedMessages.indexOf(b);
			return aIndex - bIndex;
		});

		logger.debug('Compression summary before validate', {
			messagesRemaining: compressedMessages.length,
			minMessagesToKeep,
			messagesRemoved: removedMessages.length,
			finalTokenCount: calculateTotalTokens(compressedMessages),
		});

		const result = createCompressionResult(
			originalMessages,
			compressedMessages,
			removedMessages,
			this.name
		);

		if (!validateCompressionResult(result, minMessagesToKeep)) {
			logger.warn('Middle removal compression validation failed, returning original messages');
			return createCompressionResult(originalMessages, originalMessages, [], this.name);
		}

		const duration = Date.now() - startTime;
		logCompressionOperation('middle removal completed', result, { duration });

		return result;
	}

	shouldCompress(currentTokenCount: number): boolean {
		const threshold = this.config.maxTokens * this.config.compressionThreshold;
		return currentTokenCount >= threshold;
	}

	getCompressionLevel(currentTokenCount: number): number {
		const warningThreshold = this.config.maxTokens * this.config.warningThreshold;
		const compressionThreshold = this.config.maxTokens * this.config.compressionThreshold;

		if (currentTokenCount < warningThreshold) {
			return CompressionLevel.NONE;
		} else if (currentTokenCount < compressionThreshold) {
			return CompressionLevel.WARNING;
		} else if (currentTokenCount < this.config.maxTokens * 0.95) {
			return CompressionLevel.SOFT;
		} else if (currentTokenCount < this.config.maxTokens) {
			return CompressionLevel.HARD;
		} else {
			return CompressionLevel.EMERGENCY;
		}
	}

	validateCompression(result: CompressionResult): boolean {
		return validateCompressionResult(result, this.config.minMessagesToKeep);
	}

	/**
	 * Get strategy-specific statistics
	 */
	getStrategyStats(): any {
		return {
			name: this.name,
			preserveStart: this.config.preserveStart,
			preserveEnd: this.config.preserveEnd,
			compressionType: 'middle-removal',
			bestFor: 'maintaining conversation flow and recent context',
		};
	}
}

import {
	ICompressionStrategy,
	CompressionConfig,
	CompressionResult,
	EnhancedInternalMessage,
	CompressionLevel,
} from '../types.js';
import {
	assignMessagePriorities,
	getPreservableMessages,
	getRemovableMessages,
	sortMessagesByRemovalPriority,
	calculateTotalTokens,
	createCompressionResult,
	validateCompressionResult,
	logCompressionOperation,
	ensureMessageIds,
} from '../utils.js';
import { logger } from '../../../../logger/index.js';

/**
 * Oldest Removal Strategy
 * Removes oldest messages first while preserving minimum message count
 * Best for long conversations where recent context is most important
 */
export class OldestRemovalStrategy implements ICompressionStrategy {
	public readonly name = 'oldest-removal';
	public readonly config: CompressionConfig;

	constructor(config: CompressionConfig) {
		this.config = config;
		logger.debug('OldestRemovalStrategy initialized', config);
	}

	async compress(
		messages: EnhancedInternalMessage[],
		currentTokenCount: number,
		targetTokenCount: number
	): Promise<CompressionResult> {
		const startTime = Date.now();
		const originalMessages = [...messages];

		let processedMessages = ensureMessageIds(messages);
		processedMessages = assignMessagePriorities(processedMessages);

		logger.debug('Starting oldest removal compression', {
			messageCount: processedMessages.length,
			currentTokens: currentTokenCount,
			targetTokens: targetTokenCount,
			tokensToRemove: currentTokenCount - targetTokenCount,
		});

		// Use configuration values instead of hardcoded ones
		const minMessagesToKeep = this.config.minMessagesToKeep;
		const preserveStart = Math.min(this.config.preserveStart, processedMessages.length);
		const preserveEnd = Math.min(this.config.preserveEnd, processedMessages.length);

		const preservableMessages = getPreservableMessages(processedMessages);
		const removableMessages = getRemovableMessages(processedMessages);

		if (removableMessages.length === 0) {
			logger.warn('No removable messages found for compression');
			return createCompressionResult(originalMessages, processedMessages, [], this.name);
		}

		// Sort messages by timestamp (oldest first) for removal priority
		const sortedForRemoval = sortMessagesByRemovalPriority(removableMessages).sort(
			(a, b) => (a.timestamp || 0) - (b.timestamp || 0)
		);

		logger.debug('Oldest removal strategy analysis', {
			totalRemovable: removableMessages.length,
			preserveStart,
			preserveEnd,
			sortedForRemovalCount: sortedForRemoval.length,
		});

		// Start with all preservable messages + all removable messages
		let compressedMessages = [...preservableMessages, ...sortedForRemoval];
		let removedMessages: EnhancedInternalMessage[] = [];

		// Remove oldest messages until we reach target or minimum
		while (
			calculateTotalTokens(compressedMessages) > targetTokenCount &&
			compressedMessages.length > minMessagesToKeep
		) {
			// Find the oldest removable message still in compressed set
			let oldestIndex = -1;
			let oldestTimestamp = Infinity;

			for (let i = 0; i < compressedMessages.length; i++) {
				const message = compressedMessages[i];
				if (!message) continue;
				// Skip preservable messages
				if (preservableMessages.includes(message)) continue;

				const timestamp = message.timestamp || 0;
				if (timestamp < oldestTimestamp) {
					oldestTimestamp = timestamp;
					oldestIndex = i;
				}
			}

			// If we found an oldest message, remove it
			if (oldestIndex >= 0) {
				const removedMessage = compressedMessages.splice(oldestIndex, 1)[0];
				if (removedMessage) {
					removedMessages.push(removedMessage);
					logger.debug('Removed oldest message', {
						messageId: removedMessage.messageId,
						timestamp: removedMessage.timestamp,
						priority: removedMessage.priority,
						remainingMessages: compressedMessages.length,
						currentTokens: calculateTotalTokens(compressedMessages),
					});
				}
			} else {
				// No more removable messages found
				break;
			}
		}

		// Sort final messages to maintain original conversation order
		compressedMessages = compressedMessages.sort((a, b) => {
			const aIndex = processedMessages.indexOf(a);
			const bIndex = processedMessages.indexOf(b);
			return aIndex - bIndex;
		});

		logger.debug('Compression summary before validate', {
			messagesRemaining: compressedMessages.length,
			minMessagesToKeep,
			messagesRemoved: removedMessages.length,
			finalTokenCount: calculateTotalTokens(compressedMessages),
		});

		const result = createCompressionResult(
			originalMessages,
			compressedMessages,
			removedMessages,
			this.name
		);

		if (!validateCompressionResult(result, minMessagesToKeep)) {
			logger.warn('Oldest removal compression validation failed, returning original messages');
			return createCompressionResult(originalMessages, originalMessages, [], this.name);
		}

		const duration = Date.now() - startTime;
		logCompressionOperation('oldest removal completed', result, { duration });

		return result;
	}

	shouldCompress(currentTokenCount: number): boolean {
		const threshold = this.config.maxTokens * this.config.compressionThreshold;
		return currentTokenCount >= threshold;
	}

	getCompressionLevel(currentTokenCount: number): number {
		const warningThreshold = this.config.maxTokens * this.config.warningThreshold;
		const compressionThreshold = this.config.maxTokens * this.config.compressionThreshold;

		if (currentTokenCount < warningThreshold) {
			return CompressionLevel.NONE;
		} else if (currentTokenCount < compressionThreshold) {
			return CompressionLevel.WARNING;
		} else if (currentTokenCount < this.config.maxTokens * 0.95) {
			return CompressionLevel.SOFT;
		} else if (currentTokenCount < this.config.maxTokens) {
			return CompressionLevel.HARD;
		} else {
			return CompressionLevel.EMERGENCY;
		}
	}

	validateCompression(result: CompressionResult): boolean {
		return validateCompressionResult(result, this.config.minMessagesToKeep);
	}

	getStrategyStats(): any {
		return {
			name: this.name,
			preserveStart: this.config.preserveStart,
			preserveEnd: this.config.preserveEnd,
			minMessagesToKeep: this.config.minMessagesToKeep,
			compressionType: 'oldest-removal',
			bestFor: 'long conversations where recent context is most important',
		};
	}
}

import { z } from 'zod';
import { InternalMessage } from '../messages/types.js';

/**
 * Configuration schema for compression settings
 */
export const CompressionConfigSchema = z.object({
	strategy: z.enum(['middle-removal', 'oldest-removal', 'hybrid']),
	maxTokens: z.number().positive(),
	warningThreshold: z.number().min(0).max(1).default(0.8),
	compressionThreshold: z.number().min(0).max(1).default(0.9),
	preserveStart: z.number().min(1).default(4),
	preserveEnd: z.number().min(1).default(5),
	minMessagesToKeep: z.number().min(1).default(4),
});

export type CompressionConfig = z.infer<typeof CompressionConfigSchema>;

/**
 * Enhanced message interface with compression metadata
 */
export interface EnhancedInternalMessage extends InternalMessage {
	priority?: 'critical' | 'high' | 'normal' | 'low';
	preserveInCompression?: boolean;
	tokenCount?: number;
	timestamp?: number;
	messageId?: string;
}

/**
 * Compression result interface
 */
export interface CompressionResult {
	compressedMessages: EnhancedInternalMessage[];
	removedMessages: EnhancedInternalMessage[];
	originalTokenCount: number;
	compressedTokenCount: number;
	compressionRatio: number;
	strategy: string;
	timestamp: number;
}

/**
 * Compression statistics for monitoring
 */
export interface CompressionStats {
	totalCompressions: number;
	averageCompressionRatio: number;
	messagesRemoved: number;
	tokensRemoved: number;
	lastCompressionTime: number;
}

/**
 * Compression strategy interface
 */
export interface ICompressionStrategy {
	readonly name: string;
	readonly config: CompressionConfig;

	/**
	 * Compress messages according to strategy
	 */
	compress(
		messages: EnhancedInternalMessage[],
		currentTokenCount: number,
		targetTokenCount: number
	): Promise<CompressionResult>;

	/**
	 * Check if compression is needed
	 */
	shouldCompress(currentTokenCount: number): boolean;

	/**
	 * Get compression level (0-1) based on current usage
	 */
	getCompressionLevel(currentTokenCount: number): number;

	/**
	 * Validate that the compression preserves essential messages
	 */
	validateCompression(result: CompressionResult): boolean;
}

/**
 * Message priority levels
 */
export enum MessagePriority {
	CRITICAL = 'critical',
	HIGH = 'high',
	NORMAL = 'normal',
	LOW = 'low',
}

/**
 * Compression levels based on token usage
 */
export enum CompressionLevel {
	NONE = 0,
	WARNING = 1,
	SOFT = 2,
	HARD = 3,
	EMERGENCY = 4,
}

/**
 * Compression event types for monitoring
 */
export interface CompressionEvent {
	type: 'compression_started' | 'compression_completed' | 'compression_failed';
	timestamp: number;
	strategy: string;
	beforeTokens: number;
	afterTokens?: number;
	messagesRemoved?: number;
	error?: string;
}

import { EnhancedInternalMessage, CompressionResult, MessagePriority } from './types.js';
import { extractTextFromMessage } from '../tokenizer/utils.js';
import { logger } from '../../../logger/index.js';

/**
 * Calculate token count for a message (uses cached value if available)
 */
export function getMessageTokenCount(message: EnhancedInternalMessage): number {
	if (message.tokenCount !== undefined) {
		return message.tokenCount;
	}

	// Fallback to character-based estimation
	const text = extractTextFromMessage(message);

	const approxToken = Math.ceil(text.length / 4); // 4 chars per token approximation
	if (approxToken > 10000) {
		console.warn('Token estimation unusually high:', {
			textLength: text.length,
			approxToken,
			message,
		});
	}
	return approxToken;
}

/**
 * Calculate total token count for an array of messages
 */
export function calculateTotalTokens(messages: EnhancedInternalMessage[]): number {
	return messages.reduce((total, message) => total + getMessageTokenCount(message), 0);
}

/**
 * Assign priorities to messages based on role and content
 */
export function assignMessagePriorities(
	messages: EnhancedInternalMessage[]
): EnhancedInternalMessage[] {
	return messages.map((message, index) => {
		if (message.priority !== undefined) {
			return message;
		}

		let priority: MessagePriority = MessagePriority.NORMAL;
		const tokenCount = getMessageTokenCount(message);
		const textContent = typeof message.content === 'string' ? message.content : '';

		if (message.role === 'system') {
			priority = MessagePriority.CRITICAL;
		} else if (message.role === 'tool') {
			priority = MessagePriority.HIGH;
		} else if (index < 2 || index >= messages.length - 2) {
			priority = MessagePriority.HIGH;
		} else if (tokenCount > 800) {
			priority = MessagePriority.HIGH;
		} else if (tokenCount < 20 && !textContent.includes('?')) {
			priority = MessagePriority.LOW;
		} else if (
			(message as any).function_call ||
			(message as any).tool_calls ||
			(message as any).name
		) {
			priority = MessagePriority.HIGH;
		}

		return {
			...message,
			priority,
			timestamp: message.timestamp || Date.now(),
		};
	});
}

/**
 * Filter messages that should be preserved during compression
 */
export function getPreservableMessages(
	messages: EnhancedInternalMessage[]
): EnhancedInternalMessage[] {
	return messages.filter(
		message =>
			message.preserveInCompression === true ||
			message.priority === MessagePriority.CRITICAL ||
			message.role === 'system'
	);
}

/**
 * Filter messages that can be removed during compression
 */
export function getRemovableMessages(
	messages: EnhancedInternalMessage[]
): EnhancedInternalMessage[] {
	const removable = [];
	const debugInfo = [];
	for (const message of messages) {
		if (
			message.preserveInCompression !== true &&
			message.priority !== MessagePriority.CRITICAL &&
			message.role !== 'system'
		) {
			removable.push(message);
			debugInfo.push({
				messageId: message.messageId,
				role: message.role,
				priority: message.priority,
				preserveInCompression: message.preserveInCompression,
				removable: true,
			});
		} else {
			let reason = '';
			if (message.preserveInCompression === true) reason += 'preserveInCompression=true; ';
			if (message.priority === MessagePriority.CRITICAL) reason += 'priority=CRITICAL; ';
			if (message.role === 'system') reason += 'role=system; ';
			debugInfo.push({
				messageId: message.messageId,
				role: message.role,
				priority: message.priority,
				preserveInCompression: message.preserveInCompression,
				removable: false,
				reason,
			});
		}
	}
	logger.debug('Removable message debug info:', debugInfo);
	return removable;
}

/**
 * Sort messages by priority (for removal order)
 */
export function sortMessagesByRemovalPriority(
	messages: EnhancedInternalMessage[]
): EnhancedInternalMessage[] {
	return [...messages].sort((a, b) => {
		// First sort by priority (low priority removed first)
		const priorityOrder = {
			[MessagePriority.LOW]: 0,
			[MessagePriority.NORMAL]: 1,
			[MessagePriority.HIGH]: 2,
			[MessagePriority.CRITICAL]: 3,
		};

		const aPriority = priorityOrder[a.priority || MessagePriority.NORMAL];
		const bPriority = priorityOrder[b.priority || MessagePriority.NORMAL];

		if (aPriority !== bPriority) {
			return aPriority - bPriority;
		}

		// Then sort by timestamp (older messages removed first)
		const aTime = a.timestamp || 0;
		const bTime = b.timestamp || 0;

		return aTime - bTime;
	});
}

/**
 * Create compression result object
 */
export function createCompressionResult(
	originalMessages: EnhancedInternalMessage[],
	compressedMessages: EnhancedInternalMessage[],
	removedMessages: EnhancedInternalMessage[],
	strategy: string
): CompressionResult {
	const originalTokenCount = calculateTotalTokens(originalMessages);
	const compressedTokenCount = calculateTotalTokens(compressedMessages);

	let compressionRatio = 1;
	if (originalTokenCount > 0) {
		compressionRatio = compressedTokenCount / originalTokenCount;
		if (compressionRatio > 1) {
			compressionRatio = 1; // Clamp to 1 if logic error
		}
	}

	return {
		compressedMessages,
		removedMessages,
		originalTokenCount,
		compressedTokenCount,
		compressionRatio,
		strategy,
		timestamp: Date.now(),
	};
}

/**
 * Validate compression result to ensure quality
 */
export function validateCompressionResult(
	result: CompressionResult,
	minMessagesToKeep: number
): boolean {
	// Check minimum message count
	if (result.compressedMessages.length < minMessagesToKeep) {
		logger.warn('Compression removed too many messages', {
			remaining: result.compressedMessages.length,
			minimum: minMessagesToKeep,
		});
		return false;
	}

	// Must preserve system messages
	const allMessages = result.compressedMessages.concat(result.removedMessages);
	const systemMessages = result.compressedMessages.filter(m => m.role === 'system');
	const originalSystemMessages = allMessages.filter(m => m.role === 'system');

	if (systemMessages.length !== originalSystemMessages.length) {
		logger.warn('Compression removed system messages');
		return false;
	}

	// Must preserve critical messages
	const criticalMessages = result.compressedMessages.filter(
		m => m.priority === MessagePriority.CRITICAL
	);
	const originalCriticalMessages = allMessages.filter(m => m.priority === MessagePriority.CRITICAL);

	if (criticalMessages.length !== originalCriticalMessages.length) {
		logger.warn('Compression removed critical messages');
		return false;
	}

	// Should achieve some compression
	if (result.compressionRatio >= 1) {
		logger.warn('Compression achieved no token reduction', {
			ratio: result.compressionRatio,
		});
		return false;
	}

	return true;
}

/**
 * Add message IDs if not present
 */
export function ensureMessageIds(messages: EnhancedInternalMessage[]): EnhancedInternalMessage[] {
	return messages.map((message, index) => ({
		...message,
		messageId: message.messageId || `msg_${Date.now()}_${index}`,
	}));
}

/**
 * Log compression operation
 */
export function logCompressionOperation(
	operation: string,
	result: CompressionResult,
	context?: any
): void {
	logger.debug(`Compression: ${operation}`, {
		strategy: result.strategy,
		originalTokens: result.originalTokenCount,
		compressedTokens: result.compressedTokenCount,
		ratio: result.compressionRatio,
		messagesRemoved: result.removedMessages.length,
		messagesRemaining: result.compressedMessages.length,
		...context,
	});
}

/**
 * Calculate compression efficiency score
 */
export function calculateCompressionEfficiency(result: CompressionResult): number {
	// Efficiency considers both token reduction and message preservation
	const tokenReduction = 1 - result.compressionRatio;
	const messagePreservation =
		result.compressedMessages.length /
		(result.compressedMessages.length + result.removedMessages.length);

	// Weighted score (60% token reduction, 40% message preservation)
	return tokenReduction * 0.6 + messagePreservation * 0.4;
}

import { z } from 'zod';

const AwsConfigSchema = z.object({
	region: z
		.string()
		.optional()
		.describe('AWS region (defaults to us-east-1 or AWS_DEFAULT_REGION)'),
	accessKeyId: z
		.string()
		.optional()
		.describe('AWS Access Key ID (can use AWS_ACCESS_KEY_ID env var)'),
	secretAccessKey: z
		.string()
		.optional()
		.describe('AWS Secret Access Key (can use AWS_SECRET_ACCESS_KEY env var)'),
	sessionToken: z
		.string()
		.optional()
		.describe('AWS Session Token (can use AWS_SESSION_TOKEN env var)'),
	inferenceProfileArn: z
		.string()
		.optional()
		.describe(
			'ARN of the AWS Bedrock provisioned throughput (inference profile) for the selected model'
		),
});

const AzureConfigSchema = z.object({
	endpoint: z.string().url().describe('Azure OpenAI endpoint URL (required for Azure)'),
	deploymentName: z
		.string()
		.optional()
		.describe('Azure deployment name (defaults to model name if not provided)'),
});

export const LLMConfigSchema = z
	.object({
		provider: z
			.string()
			.nonempty()
			.describe(
				"The LLM provider (e.g., 'openai', 'anthropic', 'openrouter', 'ollama', 'lmstudio', 'qwen', 'aws', 'azure', 'gemini')"
			),
		model: z.string().nonempty().describe('The specific model name for the selected provider'),
		apiKey: z
			.string()
			.optional()
			.describe(
				'API key for the LLM provider (can also be set via environment variables using $VAR syntax). Not required for Ollama, LM Studio, or AWS (if using IAM roles).'
			),
		maxIterations: z
			.number()
			.int()
			.positive()
			.optional()
			.default(50)
			.describe(
				'Maximum number of iterations for agentic loops or chained LLM calls, defaults to 50'
			),
		baseURL: z
			.string()
			.url()
			.optional()
			.describe(
				'Base URL for the LLM provider (e.g., https://api.openai.com/v1, https://openrouter.ai/api/v1, http://localhost:1234/v1). \nSupported for OpenAI, OpenRouter, Ollama, LM Studio, and Qwen providers.'
			),
		qwenOptions: z
			.object({
				enableThinking: z.boolean().optional(),
				thinkingBudget: z.number().int().positive().optional(),
				temperature: z.number().min(0).max(2).optional(),
				top_p: z.number().min(0).max(1).optional(),
			})
			.optional()
			.describe('Qwen-specific options for advanced configuration'),
		aws: AwsConfigSchema.optional().describe('AWS-specific configuration options'),
		azure: AzureConfigSchema.optional().describe('Azure-specific configuration options'),
	})
	.strict()
	.superRefine((data, ctx) => {
		const providerLower = data.provider?.toLowerCase();
		const supportedProvidersList = [
			'openai',
			'anthropic',
			'openrouter',
			'ollama',
			'lmstudio', // Added LM Studio as a supported provider
			'qwen',
			'aws',
			'azure',
			'gemini',
		];
		if (!supportedProvidersList.includes(providerLower)) {
			ctx.addIssue({
				code: z.ZodIssueCode.custom,
				path: ['provider'],
				message: `Provider '${data.provider}' is not supported. Supported: ${supportedProvidersList.join(', ')}`,
			});
		}

		// Provider-specific validation
		if (providerLower === 'aws') {
			// AWS requires aws config object
			if (!data.aws) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					path: ['aws'],
					message: 'AWS configuration object is required when using AWS provider',
				});
			}
		} else if (providerLower === 'azure') {
			// Azure requires azure config object with endpoint
			if (!data.azure) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					path: ['azure'],
					message: 'Azure configuration object is required when using Azure provider',
				});
			} else if (!data.azure.endpoint) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					path: ['azure', 'endpoint'],
					message: 'Azure endpoint is required when using Azure provider',
				});
			}
			// Azure requires API key
			if (!data.apiKey || data.apiKey.trim().length === 0) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					path: ['apiKey'],
					message: 'API key is required for Azure OpenAI provider',
				});
			}
		} else if (
			providerLower !== 'ollama' &&
			providerLower !== 'aws' &&
			providerLower !== 'lmstudio'
		) {
			// Non-Ollama, non-AWS, non-LMStudio providers require an API key
			if (!data.apiKey || data.apiKey.trim().length === 0) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					path: ['apiKey'],
					message: `API key is required for provider '${data.provider}'. Only Ollama, LM Studio, and AWS (with IAM roles) don't require an API key.`,
				});
			}
		}
	});

export type LLMConfig = z.infer<typeof LLMConfigSchema>;
export type AwsConfig = z.infer<typeof AwsConfigSchema>;
export type AzureConfig = z.infer<typeof AzureConfigSchema>;

export class CantInferProviderError extends Error {
	constructor(model: string) {
		super(`Unrecognized model '${model}'. Could not infer provider.`);
		this.name = 'CantInferProviderError';
	}
}

