import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ContextManager } from '../manager.js';
import { IMessageFormatter } from '../formatters/types.js';
import { InternalMessage } from '../types.js';
import { CompressionLevel } from '../../compression/types.js';

// Mock logger
vi.mock('../../../../logger/index.js', () => ({
	logger: {
		debug: vi.fn(),
		info: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
	},
}));

// Mock formatter
class MockFormatter implements IMessageFormatter {
	format(message: InternalMessage, _systemPrompt?: string): any[] {
		return [
			{
				role: message.role,
				content: message.content,
			},
		];
