// Mock prompt manager
class MockPromptManager {
	async getCompleteSystemPrompt(): Promise<string> {
		return 'System prompt for testing';
	}
}

describe('ContextManager Token-Aware Compression Integration', () => {
	let contextManager: ContextManager;
	let mockFormatter: MockFormatter;
	let mockPromptManager: MockPromptManager;

	beforeEach(() => {
		mockFormatter = new MockFormatter();
		mockPromptManager = new MockPromptManager();
		contextManager = new ContextManager(
			mockFormatter,
			mockPromptManager as any,
			undefined,
			undefined
		);
	});

	describe('Compression Configuration', () => {
		it('should configure compression for OpenAI', async () => {
			await contextManager.configureCompression('openai', 'gpt-4', 8192);

			const stats = contextManager.getTokenStats();
			expect(stats.maxTokens).toBe(8192);
			expect(stats.compressionLevel).toBe(CompressionLevel.NONE);
		});

		it('should configure compression for Anthropic', async () => {
			await contextManager.configureCompression('anthropic', 'claude-3-sonnet', 200000);

			const stats = contextManager.getTokenStats();
			expect(stats.maxTokens).toBe(200000);
		});

		it('should configure compression for Google', async () => {
			await contextManager.configureCompression('google', 'gemini-pro', 32760);

			const stats = contextManager.getTokenStats();
			expect(stats.maxTokens).toBe(32760);
		});
	});

	describe('Token Counting and Compression', () => {
		beforeEach(async () => {
			// Configure with a small context window for easier testing
			await contextManager.configureCompression('openai', 'gpt-3.5-turbo', 1000);
		});

		it('should track token count as messages are added', async () => {
			await contextManager.addMessage({
				role: 'system',
				content: 'You are a helpful assistant.',
			});

			await contextManager.addMessage({
				role: 'user',
				content: 'Hello, how are you?',
			});

			const stats = contextManager.getTokenStats();
			expect(stats.currentTokens).toBeGreaterThan(0);
			expect(stats.utilization).toBeGreaterThan(0);
		});

		it('should trigger compression when threshold is reached', async () => {
			// Add a system message (critical priority)
			await contextManager.addMessage({
				role: 'system',
				content: 'You are a helpful assistant.',
			});

			// Add many user/assistant message pairs to trigger compression
			for (let i = 0; i < 20; i++) {
				await contextManager.addMessage({
					role: 'user',
					content: `This is user message ${i} with enough content to accumulate tokens and trigger compression when the context window limit is approached.`,
				});

				await contextManager.addMessage({
					role: 'assistant',
					content: `This is assistant response ${i} with enough content to accumulate tokens and trigger compression when the context window limit is approached.`,
				});
			}

			const stats = contextManager.getTokenStats();
			const messages = contextManager.getRawMessages();

			// Should have compressed if we exceeded threshold
			expect(stats.compressionHistory).toBeGreaterThanOrEqual(0);

			// Should preserve system message
			const systemMessages = messages.filter(m => m.role === 'system');
			expect(systemMessages.length).toBe(1);
		});

		it('should provide accurate token statistics', async () => {
			await contextManager.addMessage({
				role: 'user',
				content: 'Short message',
			});

			const stats = contextManager.getTokenStats();

			expect(stats.currentTokens).toBeGreaterThan(0);
			expect(stats.maxTokens).toBe(1000);
			expect(stats.utilization).toBeGreaterThan(0);
			expect(stats.utilization).toBeLessThan(1);
			expect(Object.values(CompressionLevel)).toContain(stats.compressionLevel);
		});

		it('should force compression when requested', async () => {
			// Add some messages
			for (let i = 0; i < 5; i++) {
				await contextManager.addMessage({
					role: 'user',
					content: `Message ${i}`,
				});
			}

			try {
				const result = await contextManager.forceCompression();
				// If compression was configured and successful, result should exist
				if (result) {
					expect(result.strategy).toBeDefined();
					expect(result.compressionRatio).toBeLessThanOrEqual(1);
				}
			} catch (error) {
				// If compression wasn't configured, this is expected
				expect((error as Error).message).toContain('not configured');
			}
		});
	});

	describe('Message Priority and Preservation', () => {
		beforeEach(async () => {
			await contextManager.configureCompression('openai', 'gpt-4', 1000);
		});

		it('should preserve system messages during compression', async () => {
			// Add system message
			await contextManager.addMessage({
				role: 'system',
				content: 'You are a helpful assistant with specific instructions.',
			});

			// Add many other messages
			for (let i = 0; i < 15; i++) {
				await contextManager.addMessage({
					role: 'user',
					content: `User message ${i} with substantial content to trigger compression`,
				});

				await contextManager.addMessage({
					role: 'assistant',
					content: `Assistant response ${i} with substantial content`,
				});
			}

			const messages = contextManager.getRawMessages();
			const systemMessages = messages.filter(m => m.role === 'system');

			// System messages should always be preserved
			expect(systemMessages.length).toBe(1);
			expect(systemMessages[0]?.content).toContain('helpful assistant');
		});

		it('should handle tool messages appropriately', async () => {
			await contextManager.addMessage({
				role: 'assistant',
				content: null,
				toolCalls: [
					{
						id: 'call_1',
						type: 'function',
						function: {
							name: 'test_function',
							arguments: '{"param": "value"}',
						},
					},
				],
			});

			await contextManager.addToolResult('call_1', 'test_function', 'Tool result');

			const messages = contextManager.getRawMessages();
			expect(messages.length).toBe(2);

			const toolMessage = messages.find(m => m.role === 'tool');
			expect(toolMessage).toBeDefined();
			expect(toolMessage?.toolCallId).toBe('call_1');
		});
	});

	describe('Compression Level Detection', () => {
		beforeEach(async () => {
			await contextManager.configureCompression('openai', 'gpt-4', 1000);
		});

		it('should detect compression levels correctly', async () => {
			// Start with no messages - should be NONE
			let level = contextManager.getCompressionLevel();
			expect(level).toBe(CompressionLevel.NONE);

			// Add messages progressively and check levels
			const messageContent =
				'This is a test message with enough content to count tokens properly and test compression level detection.';

			for (let i = 0; i < 10; i++) {
				await contextManager.addMessage({
					role: 'user',
					content: `${messageContent} Message ${i}`,
				});

				level = contextManager.getCompressionLevel();
				expect(Object.values(CompressionLevel)).toContain(level);
			}
		});
	});
});

/**
 * OpenAI Message Flow Validation Tests
 *
 * Tests for the OpenAI message flow validation and repair functionality.
 * Ensures that tool messages always follow assistant messages with tool_calls.
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ContextManager } from '../manager.js';
import { OpenAIMessageFormatter } from '../formatters/openai.js';
import { EnhancedPromptManager } from '../../../brain/systemPrompt/enhanced-manager.js';
import { InternalMessage } from '../types.js';

// Mock the logger
const mockLogger = {
	debug: vi.fn(),
	warn: vi.fn(),
	error: vi.fn(),
	info: vi.fn(),
};

vi.mock('../../../logger/index.js', () => ({
	logger: mockLogger,
}));

// Mock the prompt manager
const mockPromptManager = {
	generateSystemPrompt: vi.fn().mockResolvedValue({ content: 'Test system prompt' }),
} as unknown as EnhancedPromptManager;

describe('OpenAI Message Flow Validation', () => {
	let contextManager: ContextManager;
	let formatter: OpenAIMessageFormatter;

	beforeEach(() => {
		formatter = new OpenAIMessageFormatter();
		contextManager = new ContextManager(formatter, mockPromptManager, undefined, undefined);
		// Reset mock calls before each test
		vi.clearAllMocks();
	});

	describe('Valid Message Flows', () => {
		it('should handle normal conversation flow', async () => {
			await contextManager.addUserMessage('Hello');
			await contextManager.addAssistantMessage('Hi there!');
			await contextManager.addUserMessage('How are you?');
			await contextManager.addAssistantMessage('I am doing well, thank you!');

			const formatted = await contextManager.getAllFormattedMessages();

			// Should have system + 4 conversation messages
			expect(formatted).toHaveLength(5);
			expect(formatted[0].role).toBe('system');
			expect(formatted[1].role).toBe('user');
			expect(formatted[2].role).toBe('assistant');
			expect(formatted[3].role).toBe('user');
			expect(formatted[4].role).toBe('assistant');
		});

		it('should handle valid tool call flow', async () => {
			await contextManager.addUserMessage('What is the weather?');

			// Assistant message with tool calls
			await contextManager.addAssistantMessage('Let me check the weather for you.', [
				{
					id: 'call_123',
					type: 'function',
					function: {
						name: 'get_weather',
						arguments: '{"location": "New York"}',
					},
				},
			]);

			// Tool response
			await contextManager.addToolResult('call_123', 'get_weather', {
				temperature: 72,
				condition: 'sunny',
			});

			// Final assistant response
			await contextManager.addAssistantMessage('The weather in New York is 72°F and sunny.');

			const formatted = await contextManager.getAllFormattedMessages();

			// Should have system + user + assistant_with_tools + tool + assistant
			expect(formatted).toHaveLength(5);
			expect(formatted[0].role).toBe('system');
			expect(formatted[1].role).toBe('user');
			expect(formatted[2].role).toBe('assistant');
			expect(formatted[2].tool_calls).toBeDefined();
			expect(formatted[3].role).toBe('tool');
			expect(formatted[3].tool_call_id).toBe('call_123');
			expect(formatted[4].role).toBe('assistant');
		});
	});

	describe('Invalid Message Flows - Repair Logic', () => {
		it('should remove orphaned tool messages', async () => {
			// Manually add messages that would create an invalid flow
			const messages: InternalMessage[] = [
				{ role: 'user', content: [{ type: 'text', text: 'Hello' }] },
				{ role: 'assistant', content: 'Hi there!' },
				// This tool message has no corresponding assistant with tool_calls
				{ role: 'tool', content: 'Tool result', toolCallId: 'call_orphan', name: 'orphaned_tool' },
				{ role: 'user', content: [{ type: 'text', text: 'Continue' }] },
			];

			// Directly access the private method for testing
			const validateMethod = (contextManager as any).validateAndRepairMessageFlow.bind(
				contextManager
			);
			const repairedMessages = validateMethod(messages);

			// Should remove the orphaned tool message
			expect(repairedMessages).toHaveLength(3);
			expect(repairedMessages.map(m => m.role)).toEqual(['user', 'assistant', 'user']);
		});

		it('should keep valid tool messages and remove invalid ones', async () => {
			const messages: InternalMessage[] = [
				{ role: 'user', content: [{ type: 'text', text: 'Hello' }] },
				// Valid assistant with tool calls
				{
					role: 'assistant',
					content: 'Let me help you.',
					toolCalls: [
						{
							id: 'call_valid',
							type: 'function',
							function: { name: 'valid_tool', arguments: '{}' },
						},
					],
				},
				// Valid tool response
				{ role: 'tool', content: 'Valid result', toolCallId: 'call_valid', name: 'valid_tool' },
				// Invalid orphaned tool response
				{
					role: 'tool',
					content: 'Invalid result',
					toolCallId: 'call_invalid',
					name: 'invalid_tool',
				},
				{ role: 'assistant', content: 'Here is the result.' },
			];

			const validateMethod = (contextManager as any).validateAndRepairMessageFlow.bind(
				contextManager
			);
			const repairedMessages = validateMethod(messages);

			// Should keep valid tool message, remove invalid one
			expect(repairedMessages).toHaveLength(4);
			expect(repairedMessages.map(m => m.role)).toEqual(['user', 'assistant', 'tool', 'assistant']);
			expect(repairedMessages[2].toolCallId).toBe('call_valid');
		});

		it('should handle multiple tool calls correctly', async () => {
			const messages: InternalMessage[] = [
				{ role: 'user', content: [{ type: 'text', text: 'Do multiple things' }] },
				// Assistant with multiple tool calls
				{
					role: 'assistant',
					content: 'I will do multiple things.',
					toolCalls: [
						{
							id: 'call_1',
							type: 'function',
							function: { name: 'tool_1', arguments: '{}' },
						},
						{
							id: 'call_2',
							type: 'function',
							function: { name: 'tool_2', arguments: '{}' },
						},
					],
				},
				// Valid tool responses
				{ role: 'tool', content: 'Result 1', toolCallId: 'call_1', name: 'tool_1' },
				{ role: 'tool', content: 'Result 2', toolCallId: 'call_2', name: 'tool_2' },
				// Invalid tool response with wrong ID
				{ role: 'tool', content: 'Invalid result', toolCallId: 'call_3', name: 'tool_3' },
				{ role: 'assistant', content: 'Done with both tasks.' },
			];

			const validateMethod = (contextManager as any).validateAndRepairMessageFlow.bind(
				contextManager
			);
			const repairedMessages = validateMethod(messages);

			// Should keep the 2 valid tool messages, remove the invalid one
			expect(repairedMessages).toHaveLength(5);
			const roles = repairedMessages.map(m => m.role);
			expect(roles).toEqual(['user', 'assistant', 'tool', 'tool', 'assistant']);

			// Check that correct tool call IDs are preserved
			const toolMessages = repairedMessages.filter(m => m.role === 'tool');
			expect(toolMessages.map(m => m.toolCallId)).toEqual(['call_1', 'call_2']);
		});

		it('should reset tool call tracking after user messages', async () => {
			const messages: InternalMessage[] = [
				// First conversation
				{ role: 'user', content: [{ type: 'text', text: 'First question' }] },
				{
					role: 'assistant',
					content: 'Let me help.',
					toolCalls: [
						{
							id: 'call_first',
							type: 'function',
							function: { name: 'first_tool', arguments: '{}' },
						},
					],
				},
				{ role: 'tool', content: 'First result', toolCallId: 'call_first', name: 'first_tool' },

				// New user message should reset tracking
				{ role: 'user', content: [{ type: 'text', text: 'Second question' }] },

				// This tool message should be orphaned now (no recent assistant with tool calls)
				{ role: 'tool', content: 'Orphaned result', toolCallId: 'call_first', name: 'first_tool' },

				{ role: 'assistant', content: 'Second answer.' },
			];

			const validateMethod = (contextManager as any).validateAndRepairMessageFlow.bind(
				contextManager
			);
			const repairedMessages = validateMethod(messages);

			// Should remove the orphaned tool message after the second user message
			expect(repairedMessages).toHaveLength(5);
			expect(repairedMessages.map(m => m.role)).toEqual([
				'user',
				'assistant',
				'tool',
				'user',
				'assistant',
			]);
		});
	});

	describe('Edge Cases', () => {
		it('should handle empty message list', async () => {
			const validateMethod = (contextManager as any).validateAndRepairMessageFlow.bind(
				contextManager
			);
			const repairedMessages = validateMethod([]);

			expect(repairedMessages).toHaveLength(0);
		});

		it('should handle messages without toolCalls property', async () => {
			const messages: InternalMessage[] = [
				{ role: 'user', content: [{ type: 'text', text: 'Hello' }] },
				{ role: 'assistant', content: 'Hi!' }, // No toolCalls property
				{ role: 'tool', content: 'Tool result', toolCallId: 'call_123', name: 'tool' },
			];

			const validateMethod = (contextManager as any).validateAndRepairMessageFlow.bind(
				contextManager
			);
			const repairedMessages = validateMethod(messages);

			// Should remove the orphaned tool message
			expect(repairedMessages).toHaveLength(2);
			expect(repairedMessages.map(m => m.role)).toEqual(['user', 'assistant']);
		});

		it('should handle assistant messages with empty toolCalls array', async () => {
			const messages: InternalMessage[] = [
				{ role: 'user', content: [{ type: 'text', text: 'Hello' }] },
				{ role: 'assistant', content: 'Hi!', toolCalls: [] }, // Empty toolCalls
				{ role: 'tool', content: 'Tool result', toolCallId: 'call_123', name: 'tool' },
			];

			const validateMethod = (contextManager as any).validateAndRepairMessageFlow.bind(
				contextManager
			);
			const repairedMessages = validateMethod(messages);

			// Should remove the orphaned tool message
			expect(repairedMessages).toHaveLength(2);
			expect(repairedMessages.map(m => m.role)).toEqual(['user', 'assistant']);
		});
	});
});

import { LLMConfig, LLMConfigSchema } from '../config.js';
import { OpenAIMessageFormatter } from './formatters/openai.js';
import { AnthropicMessageFormatter } from './formatters/anthropic.js';
import { AzureMessageFormatter } from './formatters/azure.js';
import { IMessageFormatter } from './formatters/types.js';
import { ContextManager } from './manager.js';
import { logger } from '../../../logger/index.js';
import { EnhancedPromptManager } from '../../systemPrompt/enhanced-manager.js';
import { IConversationHistoryProvider } from './history/types.js';

function getFormatter(provider: string): IMessageFormatter {
	const normalizedProvider = provider.toLowerCase();
	let formatter: IMessageFormatter;
	switch (normalizedProvider) {
		case 'openai':
		case 'openrouter':
		case 'ollama':
		case 'lmstudio':
		case 'qwen':
		case 'gemini':
			formatter = new OpenAIMessageFormatter();
			break;
		case 'azure':
			formatter = new AzureMessageFormatter();
			break;
		case 'anthropic':
		case 'aws':
			formatter = new AnthropicMessageFormatter();
			break;
		default:
			throw new Error(
				`Unsupported provider: ${provider}. Supported providers: openai, anthropic, openrouter, ollama, lmstudio, qwen, aws, azure, gemini`
			);
	}
	return formatter;
}

/**
 * Creates a new ContextManager instance with the appropriate formatter for the specified LLM config
 * @param config - The LLM configuration
 * @param promptManager - The prompt manager
 * @param historyProvider - Optional conversation history provider
 * @param sessionId - Optional session ID for history isolation
 * @returns A new ContextManager instance
 * @throws Error if the config is invalid or the provider is unsupported
 */
export function createContextManager(
	config: LLMConfig,
	promptManager: EnhancedPromptManager,
	historyProvider?: IConversationHistoryProvider,
	sessionId?: string
): ContextManager {
	try {
		LLMConfigSchema.parse(config);
	} catch (error) {
		logger.error('Invalid LLM configuration provided to createContextManager', {
			config,
			error: error instanceof Error ? error.message : String(error),
			validationIssues: error instanceof Error && 'issues' in error ? error.issues : undefined,
		});
		throw new Error(
			`Invalid LLM configuration: ${error instanceof Error ? error.message : String(error)}`
		);
	}
	const { provider, model } = config;
	try {
		const formatter = getFormatter(provider);
		logger.debug('Created context manager', {
			provider: provider.toLowerCase(),
			model: model.toLowerCase(),
			formatterType: formatter.constructor.name,
		});
		return new ContextManager(formatter, promptManager, historyProvider, sessionId);
	} catch (error) {
		logger.error('Failed to create context manager', {
			provider,
			model,
			error: error instanceof Error ? error.message : String(error),
		});
		throw error;
	}
}

import { logger } from '../../../../logger/index.js';
import { InternalMessage } from '../types.js';
import { getImageData } from '../utils.js';
import { IMessageFormatter } from './types.js';

/**
 * Message formatter for Anthropic
 *
 * Usage examples:
 *
 * // For single messages without needing an array wrapper:
 * const singleMsg = formatter.formatSingle(message);
 *
 * // For single messages with system prompt (returns array):
 * const withSystem = formatter.formatSingle(message, systemPrompt);
 *
 * // For multiple messages efficiently:
 * const multipleFormatted = formatter.formatMultiple(messages, systemPrompt);
 *
 * // For interface compatibility (always returns array):
 * const compatibleFormat = formatter.format(message, systemPrompt);
 */
export class AnthropicMessageFormatter implements IMessageFormatter {
	/**
	 * Format the message into the specific structure of target LLM API.
	 * This method maintains compatibility with the interface but is more efficient for single messages.
	 *
	 * @param message - The message to format.
	 * @param systemPrompt - The system prompt to include (optional).
	 * @returns The formatted message array.
	 */
	format(message: Readonly<InternalMessage>, systemPrompt: string | null = null): any[] {
		const result = this.formatSingle(message, systemPrompt);
		return Array.isArray(result) ? result : [result];
	}

	/**
	 * Format a single message more efficiently without always creating an array.
	 * Use this when you know you're processing a single message and want optimal performance.
	 *
	 * @param message - The message to format.
	 * @param systemPrompt - The system prompt to include (optional).
	 * @returns A single formatted message object or array if system prompt is included.
	 */
	formatSingle(
		message: Readonly<InternalMessage>,
		systemPrompt: string | null = null
	): any | any[] {
		// Anthropic handles system prompts differently - they're passed separately to the API
		// So we don't include system prompts in the message formatting
		if (systemPrompt) {
			logger.debug(
				'System prompt provided for Anthropic formatter - will be handled separately by the service'
			);
		}

		// For Anthropic, we always return just the formatted message
		// System prompts are handled at the API level, not in message formatting
		return this.formatMessageOnly(message);
	}

	/**
	 * Format multiple messages efficiently.
	 *
	 * @param messages - Array of messages to format.
	 * @param systemPrompt - The system prompt to include (optional).
	 * @returns Array of formatted messages.
	 */
	formatMultiple(messages: Readonly<InternalMessage[]>, systemPrompt: string | null = null): any[] {
		if (systemPrompt) {
			logger.debug(
				'System prompt provided for Anthropic formatter - will be handled separately by the service'
			);
		}

		return messages.map(message => this.formatMessageOnly(message));
	}

	/**
	 * Format a single message without any system prompt handling.
	 * This is the core formatting logic extracted for reuse.
	 *
	 * @param message - The message to format.
	 * @returns The formatted message object.
	 */
	private formatMessageOnly(message: Readonly<InternalMessage>): any {
		switch (message.role) {
			case 'system':
				// System messages are handled separately in Anthropic API
				logger.warn(
					'System message encountered in Anthropic formatter - should be handled at API level'
				);
				return null;

			case 'user':
				// Handle tool results as special user messages
				if (message.toolCallId) {
					return {
						role: 'user',
						content: [
							{
								type: 'tool_result',
								tool_use_id: message.toolCallId,
								content: message.content,
							},
						],
					};
				}
				// Regular user message
				return {
					role: 'user',
					content: this.formatUserContent(message.content),
				};

			case 'assistant':
				if (message.toolCalls && message.toolCalls.length > 0) {
					const contentArray = [];

					// Add text content if present
					if (message.content) {
						contentArray.push({
							type: 'text',
							text: message.content,
						});
					}

					// Add tool calls
					for (const toolCall of message.toolCalls) {
						contentArray.push({
							type: 'tool_use',
							id: toolCall.id,
							name: toolCall.function.name,
							input: JSON.parse(toolCall.function.arguments),
						});
					}

					return {
						role: 'assistant',
						content: contentArray,
					};
				} else {
					return {
						role: 'assistant',
						content: message.content,
					};
				}

			case 'tool':
				// Tool messages are converted to user messages with tool_result content
				return {
					role: 'user',
					content: [
						{
							type: 'tool_result',
							tool_use_id: message.toolCallId!,
							content: message.content!,
						},
					],
				};

			default:
				throw new Error(`Unsupported message role: ${(message as any).role}`);
		}
	}

	parseResponse(response: any): InternalMessage[] {
		const internal: InternalMessage[] = [];
		if (!response || !Array.isArray(response.content)) {
			return internal;
		}
		let combinedText: string | null = null;
		const calls: InternalMessage['toolCalls'] = [];
		for (const block of response.content) {
			if (block.type === 'text') {
				combinedText = (combinedText ?? '') + block.text;
			} else if (block.type === 'tool_use') {
				calls.push({
					id: block.id,
					type: 'function',
					function: {
						name: block.name,
						arguments: JSON.stringify(block.input),
					},
				});
			}
		}
		const assistantMessage: any = {
			role: 'assistant',
			content: combinedText,
		};
		if (calls.length > 0) {
			assistantMessage.toolCalls = calls;
		}
		internal.push(assistantMessage);
		return internal;
	}

	/**
	 * Format the user content into the specific structure of Anthropic API.
	 *
	 * @param content - The user content to format.
	 * @returns The formatted user content.
	 */
	private formatUserContent(content: InternalMessage['content']): any {
		if (!Array.isArray(content)) {
			return content;
		}
		return content
			.map(part => {
				if (part.type === 'text') {
					return { type: 'text', text: part.text };
				}
				if (part.type === 'image') {
					const raw = getImageData(part);
					let source: any;
					if (raw.startsWith('http://') || raw.startsWith('https://')) {
						source = { type: 'url', url: raw };
					} else if (raw.startsWith('data:')) {
						// Data URI: split metadata and base64 data
						const [meta, b64] = raw.split(',', 2);
						const mediaTypeMatch = meta?.match(/data:(.*);base64/);
						const media_type =
							(mediaTypeMatch && mediaTypeMatch[1]) || part.mimeType || 'application/octet-stream';
						source = { type: 'base64', media_type, data: b64 };
					} else {
						// Plain base64 string
						source = { type: 'base64', media_type: part.mimeType, data: raw };
					}
					return { type: 'image', source };
				}
				return null;
			})
			.filter(Boolean);
	}
}

import { IMessageFormatter } from './types.js';
import { InternalMessage } from '../types.js';

// Anthropic (Claude) formatter
export class BedrockAnthropicMessageFormatter implements IMessageFormatter {
	format(
		message: Readonly<InternalMessage>,
		_systemPrompt: string | null = null,
		_tools?: any[]
	): any[] {
		const role = message.role;
		let contentArr: any[] = [];

		// Handle different message roles and content types
		if (role === 'user' || role === 'assistant') {
			if (typeof message.content === 'string') {
				// String content - convert to text block
				if (message.content.trim()) {
					contentArr.push({ type: 'text', text: message.content });
				}
			} else if (Array.isArray(message.content)) {
				// Array content - process each item
				for (const c of message.content) {
					if (typeof c === 'string') {
						const textContent = c as string;
						if (textContent.trim()) {
							contentArr.push({ type: 'text', text: textContent });
						}
					} else if (c && typeof c === 'object' && 'type' in c) {
						if (c.type === 'image' && 'image' in c) {
							contentArr.push({ type: 'image', image: c.image, mimeType: c.mimeType });
						} else if (c.type === 'text' && 'text' in c && typeof c.text === 'string') {
							if (c.text.trim()) {
								contentArr.push({ type: 'text', text: c.text });
							}
						}
					}
				}
			}
		} else if (role === 'tool') {
			// Tool messages should be converted to user messages with tool_result content
			// This is handled in the AWS service, not here
			return [];
		} else if (role === 'system') {
			// System messages are handled separately in the AWS service
			return [];
		}

		// AWS Bedrock requires non-empty text content blocks
		// If we have no content, skip this message entirely
		if (contentArr.length === 0) {
			return [];
		}

		return [{ role, content: contentArr }];
	}
	parseResponse(response: any): InternalMessage[] {
		const internal: InternalMessage[] = [];
		if (!response || !response.content) return internal;
		for (const block of response.content) {
			if (block.type === 'text') {
				internal.push({ role: 'assistant', content: block.text });
			} else if (block.type === 'tool_use') {
				internal.push({
					role: 'assistant',
					content: '',
					toolCalls: [
						{
							id: block.id,
							type: 'function',
							function: {
								name: block.name,
								arguments: JSON.stringify(block.input),
							},
						},
					],
				});
			}
		}
		return internal;
	}
	formatTools(_tools: any): any[] {
		if (!_tools || typeof _tools !== 'object') return [];
		return Object.entries(_tools).map(([toolName, tool]: [string, any]) => ({
			name: toolName,
			description: tool.description,
			input_schema: tool.parameters,
		}));
	}
}

// Llama formatter
export class BedrockLlamaMessageFormatter implements IMessageFormatter {
	format(message: Readonly<InternalMessage>, _systemPrompt: string | null = null): any[] {
		let prompt = '<|begin_of_text|>';
		if (_systemPrompt) {
			prompt += `<|start_header_id|>system<|end_header_id|> ${_systemPrompt} <|eot_id|>`;
		}
		const role = message.role === 'assistant' ? 'assistant' : 'user';
		const content = Array.isArray(message.content)
			? message.content
					.filter((c: any) => c.type === 'text')
					.map((c: any) => c.text)
					.join('')
			: message.content;
		prompt += `<|start_header_id|>${role}<|end_header_id|> ${content} <|eot_id|>`;
		prompt += '<|start_header_id|>assistant<|end_header_id|>';
		return [
			{
				prompt,
				max_gen_len: 512,
				temperature: 0.5,
				top_p: 0.9,
			},
		];
	}
	parseResponse(response: any): InternalMessage[] {
		return [{ role: 'assistant', content: response.generation }];
	}
	formatTools(_tools: any): any[] {
		return [];
	}
}

// Titan formatter
export class BedrockTitanMessageFormatter implements IMessageFormatter {
	format(message: Readonly<InternalMessage>, systemPrompt: string | null = null): any[] {
		let inputText = '';
		if (systemPrompt) {
			inputText += `${systemPrompt}\n\n`;
		}
		const role = message.role === 'assistant' ? 'Bot' : 'User';
		const content = Array.isArray(message.content)
			? message.content
					.filter((c: any) => c.type === 'text')
					.map((c: any) => c.text)
					.join('')
			: message.content;
		inputText += `${role}: ${content}\n`;
		inputText += 'Bot:';
		return [
			{
				inputText,
				textGenerationConfig: {
					maxTokenCount: 512,
					temperature: 0.7,
					topP: 0.9,
					stopSequences: [],
				},
			},
		];
	}
	parseResponse(response: any): InternalMessage[] {
		const textContent = response.results.map((result: any) => result.outputText).join('');
		return [{ role: 'assistant', content: textContent }];
	}
	formatTools(_tools: any): any[] {
		return [];
	}
}

// DeepSeek formatter
export class BedrockDeepSeekMessageFormatter implements IMessageFormatter {
	format(message: Readonly<InternalMessage>, systemPrompt: string | null = null): any[] {
		let prompt = '<｜begin of sentence｜>';
		let firstUserMessage = true;
		const content = Array.isArray(message.content)
			? message.content
					.filter((c: any) => c.type === 'text')
					.map((c: any) => c.text)
					.join('')
			: message.content;
		if (message.role === 'user') {
			let userContent = content;
			if (firstUserMessage && systemPrompt) {
				userContent = `${systemPrompt}\n\n${content}`;
				firstUserMessage = false;
			}
			prompt += ' ' + userContent;
		} else if (message.role === 'assistant') {
			prompt += ' ' + content;
		}
		prompt += ' <think>\n';
		return [
			{
				prompt,
				temperature: 0.5,
				top_p: 0.9,
				max_tokens: 512,
			},
		];
	}
	parseResponse(response: any): InternalMessage[] {
		const textContent = response.choices.map((choice: any) => choice.text).join('');
		return [{ role: 'assistant', content: textContent }];
	}
	formatTools(_tools: any): any[] {
		return [];
	}
}

// AI21 formatter
export class BedrockAI21MessageFormatter implements IMessageFormatter {
	format(message: Readonly<InternalMessage>, systemPrompt: string | null = null): any[] {
		const ai21Messages: Array<{ role: 'system' | 'user' | 'assistant'; content: string }> = [];
		if (systemPrompt) {
			ai21Messages.push({ role: 'system', content: systemPrompt });
		}
		const content = Array.isArray(message.content)
			? message.content
					.filter((c: any) => c.type === 'text')
					.map((c: any) => c.text)
					.join('')
			: message.content;
		ai21Messages.push({
			role: message.role as 'user' | 'assistant' | 'system',
			content: content || '',
		});
		return [
			{
				messages: ai21Messages,
				temperature: 1.0,
				top_p: 1.0,
				max_tokens: 4096,
				frequency_penalty: 0,
				presence_penalty: 0,
			},
		];
	}
	parseResponse(response: any): InternalMessage[] {
		const textContent = response.choices.map((choice: any) => choice.message.content).join('');
		return [{ role: 'assistant', content: textContent }];
	}
	formatTools(_tools: any): any[] {
		return [];
	}
}

import { InternalMessage } from '../types.js';
import { getImageData } from '../utils.js';
import { IMessageFormatter } from './types.js';

/**
 * Message formatter for Azure OpenAI
 *
 * Azure OpenAI uses mostly OpenAI-compatible format but has specific field naming differences:
 * - Azure expects: toolCallId (camelCase) in tool response messages
 * - OpenAI expects: tool_call_id (snake_case) in tool response messages
 *
 * Usage examples:
 *
 * // For single messages without needing an array wrapper:
 * const singleMsg = formatter.formatSingle(message);
 *
 * // For single messages with system prompt (returns array):
 * const withSystem = formatter.formatSingle(message, systemPrompt);
 *
 * // For multiple messages efficiently:
 * const multipleFormatted = formatter.formatMultiple(messages, systemPrompt);
 *
 * // For interface compatibility (always returns array):
 * const compatibleFormat = formatter.format(message, systemPrompt);
 */
export class AzureMessageFormatter implements IMessageFormatter {
	/**
	 * Format the message into the specific structure of Azure OpenAI API.
	 * This method maintains compatibility with the interface but is more efficient for single messages.
	 *
	 * @param message - The message to format.
	 * @param systemPrompt - The system prompt to include (optional).
	 * @returns The formatted message array.
	 */
	format(message: Readonly<InternalMessage>, systemPrompt: string | null = null): any[] {
		const result = this.formatSingle(message, systemPrompt);
		return Array.isArray(result) ? result : [result];
	}

	/**
	 * Format a single message more efficiently without always creating an array.
	 * Use this when you know you're processing a single message and want optimal performance.
	 *
	 * @param message - The message to format.
	 * @param systemPrompt - The system prompt to include (optional).
	 * @returns A single formatted message object or array if system prompt is included.
	 */
	formatSingle(
		message: Readonly<InternalMessage>,
		systemPrompt: string | null = null
	): any | any[] {
		// If we have a system prompt, we need to return an array with system message first
		if (systemPrompt) {
			const systemMessage = {
				role: 'system',
				content: systemPrompt,
			};
			const formattedMessage = this.formatMessageOnly(message);
			return [systemMessage, formattedMessage];
		}

		// For single message without system prompt, return just the formatted message
		return this.formatMessageOnly(message);
	}

	/**
	 * Format multiple messages efficiently.
	 *
	 * @param messages - Array of messages to format.
	 * @param systemPrompt - The system prompt to include (optional).
	 * @returns Array of formatted messages.
	 */
	formatMultiple(messages: Readonly<InternalMessage[]>, systemPrompt: string | null = null): any[] {
		const formatted = [];

		if (systemPrompt) {
			formatted.push({
				role: 'system',
				content: systemPrompt,
			});
		}

		for (const message of messages) {
			formatted.push(this.formatMessageOnly(message));
		}

		return formatted;
	}

	/**
	 * Format a single message without any system prompt handling.
	 * This is the core formatting logic extracted for reuse.
	 *
	 * Handles Azure OpenAI specific field naming requirements.
	 *
	 * @param message - The message to format.
	 * @returns The formatted message object.
	 */
	private formatMessageOnly(message: Readonly<InternalMessage>): any {
		switch (message.role) {
			case 'system':
				return {
					role: 'system',
					content: message.content,
				};

			case 'user':
				return {
					role: 'user',
					content: this.formatUserContent(message.content),
				};

			case 'assistant':
				if (message.toolCalls && message.toolCalls.length > 0) {
					return {
						role: 'assistant',
						content: message.content,
						tool_calls: message.toolCalls,
					};
				} else {
					return {
						role: 'assistant',
						content: message.content,
					};
				}

			case 'tool':
				// Azure OpenAI expects toolCallId (camelCase) instead of tool_call_id (snake_case)
				return {
					role: 'tool',
					content: message.content,
					toolCallId: message.toolCallId, // Use camelCase for Azure
					name: message.name,
				};

			default:
				throw new Error(`Unsupported message role: ${(message as any).role}`);
		}
	}

	parseResponse(response: any): InternalMessage[] {
		const internal: InternalMessage[] = [];
		if (!response.choices || !Array.isArray(response.choices)) return internal;

		for (const choice of response.choices) {
			const msg = (choice as any).message;
			if (!msg || !msg.role) continue;

			const role = msg.role as InternalMessage['role'];
			if (role === 'assistant') {
				const content = msg.content ?? null;

				// Handle multiple Azure OpenAI tool call formats
				const toolCalls =
					msg.tool_calls ||
					msg.toolCalls ||
					(msg.functionCall
						? [
								{
									id: `call_${Date.now()}`,
									type: 'function',
									function: {
										name: msg.functionCall.name,
										arguments: msg.functionCall.arguments,
									},
								},
							]
						: null);

				if (toolCalls && Array.isArray(toolCalls) && toolCalls.length > 0) {
					const calls = toolCalls.map((call: any) => ({
						id: call.id,
						type: 'function' as const,
						function: {
							name: call.function.name,
							arguments: call.function.arguments,
						},
					}));
					internal.push({ role: 'assistant', content, toolCalls: calls });
				} else {
					internal.push({ role: 'assistant', content });
				}
			} else if (role === 'tool') {
				internal.push({
					role: 'tool',
					content: msg.content!,
					// Handle both Azure (toolCallId) and OpenAI (tool_call_id) formats
					toolCallId: msg.toolCallId || msg.tool_call_id!,
					name: msg.name!,
				});
			} else if (role === 'user' || role === 'system') {
				if (msg.content) {
					internal.push({ role, content: msg.content });
				}
			}
		}
		return internal;
	}

	/**
	 * Format the user content into the specific structure of Azure OpenAI API.
	 *
	 * @param content - The user content to format.
	 * @returns The formatted user content.
	 */
	private formatUserContent(content: InternalMessage['content']): any {
		if (!Array.isArray(content)) {
			return content;
		}
		return content
			.map(part => {
				if (part.type === 'text') {
					return { type: 'text', text: part.text };
				}
				if (part.type === 'image') {
					const raw = getImageData(part);
					const url =
						raw.startsWith('http://') || raw.startsWith('https://') || raw.startsWith('data:')
							? raw
							: `data:${part.mimeType || 'application/octet-stream'};base64,${raw}`;
					return { type: 'image_url', image_url: { url } };
				}
				return null;
			})
			.filter(Boolean);
	}
}

// Message formatters for different LLM providers
// OpenAI-compatible providers: OpenAI, OpenRouter, Ollama, LM Studio, Qwen, Gemini
export { OpenAIMessageFormatter } from './openai.js';
export { AnthropicMessageFormatter } from './anthropic.js';
export { AzureMessageFormatter } from './azure.js';
export { BedrockAnthropicMessageFormatter } from './aws.js';
export type { IMessageFormatter } from './types.js';

import { InternalMessage } from '../types.js';
import { getImageData } from '../utils.js';
import { IMessageFormatter } from './types.js';

/**
 * Message formatter for OpenAI
 *
 * Usage examples:
 *
 * // For single messages without needing an array wrapper:
 * const singleMsg = formatter.formatSingle(message);
 *
 * // For single messages with system prompt (returns array):
 * const withSystem = formatter.formatSingle(message, systemPrompt);
 *
 * // For multiple messages efficiently:
 * const multipleFormatted = formatter.formatMultiple(messages, systemPrompt);
 *
 * // For interface compatibility (always returns array):
 * const compatibleFormat = formatter.format(message, systemPrompt);
 */
export class OpenAIMessageFormatter implements IMessageFormatter {
	/**
	 * Format the message into the specific structure of target LLM API.
	 * This method maintains compatibility with the interface but is more efficient for single messages.
	 *
	 * @param message - The message to format.
	 * @param systemPrompt - The system prompt to include (optional).
	 * @returns The formatted message array.
	 */
	format(message: Readonly<InternalMessage>, systemPrompt: string | null = null): any[] {
		const result = this.formatSingle(message, systemPrompt);
		return Array.isArray(result) ? result : [result];
	}

	/**
	 * Format a single message more efficiently without always creating an array.
	 * Use this when you know you're processing a single message and want optimal performance.
	 *
	 * @param message - The message to format.
	 * @param systemPrompt - The system prompt to include (optional).
	 * @returns A single formatted message object or array if system prompt is included.
	 */
	formatSingle(
		message: Readonly<InternalMessage>,
		systemPrompt: string | null = null
	): any | any[] {
		// If we have a system prompt, we need to return an array with system message first
		if (systemPrompt) {
			const systemMessage = {
				role: 'system',
				content: systemPrompt,
			};
			const formattedMessage = this.formatMessageOnly(message);
			return [systemMessage, formattedMessage];
		}

		// For single message without system prompt, return just the formatted message
		return this.formatMessageOnly(message);
	}

	/**
	 * Format multiple messages efficiently.
	 *
	 * @param messages - Array of messages to format.
	 * @param systemPrompt - The system prompt to include (optional).
	 * @returns Array of formatted messages.
	 */
	formatMultiple(messages: Readonly<InternalMessage[]>, systemPrompt: string | null = null): any[] {
		const formatted = [];

		if (systemPrompt) {
			formatted.push({
				role: 'system',
				content: systemPrompt,
			});
		}

		for (const message of messages) {
			formatted.push(this.formatMessageOnly(message));
		}

		return formatted;
	}

	/**
	 * Format a single message without any system prompt handling.
	 * This is the core formatting logic extracted for reuse.
	 *
	 * @param message - The message to format.
	 * @returns The formatted message object.
	 */
	private formatMessageOnly(message: Readonly<InternalMessage>): any {
		switch (message.role) {
			case 'system':
				return {
					role: 'system',
					content: message.content,
				};

			case 'user':
				return {
					role: 'user',
					content: this.formatUserContent(message.content),
				};

			case 'assistant':
				if (message.toolCalls && message.toolCalls.length > 0) {
					return {
						role: 'assistant',
						content: message.content,
						tool_calls: message.toolCalls,
					};
				} else {
					return {
						role: 'assistant',
						content: message.content,
					};
				}

			case 'tool':
				return {
					role: 'tool',
					content: message.content,
					tool_call_id: message.toolCallId,
					name: message.name,
				};

			default:
				throw new Error(`Unsupported message role: ${(message as any).role}`);
		}
	}

	parseResponse(response: any): InternalMessage[] {
		const internal: InternalMessage[] = [];
		if (!response.choices || !Array.isArray(response.choices)) return internal;
		for (const choice of response.choices) {
			const msg = (choice as any).message;
			if (!msg || !msg.role) continue;
			const role = msg.role as InternalMessage['role'];
			if (role === 'assistant') {
				const content = msg.content ?? null;
				if (msg.tool_calls && Array.isArray(msg.tool_calls) && msg.tool_calls.length > 0) {
					const calls = msg.tool_calls.map((call: any) => ({
						id: call.id,
						type: 'function' as const,
						function: {
							name: call.function.name,
							arguments: call.function.arguments,
						},
					}));
					internal.push({ role: 'assistant', content, toolCalls: calls });
				} else {
					internal.push({ role: 'assistant', content });
				}
			} else if (role === 'tool') {
				internal.push({
					role: 'tool',
					content: msg.content!,
					toolCallId: msg.tool_call_id!,
					name: msg.name!,
				});
			} else if (role === 'user' || role === 'system') {
				if (msg.content) {
					internal.push({ role, content: msg.content });
				}
			}
		}
		return internal;
	}

	/**
	 * Format the user content into the specific structure of OpenAI API.
	 *
	 * @param content - The user content to format.
	 * @returns The formatted user content.
	 */
	private formatUserContent(content: InternalMessage['content']): any {
		if (!Array.isArray(content)) {
			return content;
		}
		return content
			.map(part => {
				if (part.type === 'text') {
					return { type: 'text', text: part.text };
				}
				if (part.type === 'image') {
					const raw = getImageData(part);
					const url =
						raw.startsWith('http://') || raw.startsWith('https://') || raw.startsWith('data:')
							? raw
							: `data:${part.mimeType || 'application/octet-stream'};base64,${raw}`;
					return { type: 'image_url', image_url: { url } };
				}
				return null;
			})
			.filter(Boolean);
	}
}

import { InternalMessage } from '../types.js';

export interface IMessageFormatter {
	/**
	 * Format a single message into the specific structure of target LLM API.
	 * This method always returns an array for interface compatibility.
	 *
	 * @param message - The message to format.
	 * @param systemPrompt - Optional system prompt to include.
	 * @returns Array of formatted messages.
	 */
	format(message: Readonly<InternalMessage>, systemPrompt?: string | null): any[];

	/**
	 * Parse the response from the LLM into a list of internal messages
	 * @param response - The response from the LLM
	 * @returns A list of internal messages
	 */
	parseResponse(response: any): InternalMessage[];

	/**
	 * Parse the stream response from the LLM into a list of internal messages
	 * @param response - The stream response from the LLM
	 * @returns A list of internal messages
	 */
	parseStreamResponse?(response: any): Promise<InternalMessage[]>;
}

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { DatabaseHistoryProvider } from '../database.js';
import { StorageManager } from '../../../../../storage/manager.js';
import type { InternalMessage } from '../../types.js';
import { InMemoryBackend } from '../../../../../storage/backend/in-memory.js';

function makeMessage(i = 0): InternalMessage {
	return { role: 'user' as const, content: `msg${i}` };
}

describe('DatabaseHistoryProvider', () => {
	let provider: DatabaseHistoryProvider;
	let storageManager: StorageManager;
	let sessionId: string;
	let message: InternalMessage;
	let backend: any;

	beforeEach(async () => {
		sessionId = 'test-session';
		message = { role: 'user', content: 'hello' };
		backend = new InMemoryBackend();
		await backend.connect();
		storageManager = {
			getBackends: () => ({ database: backend }),
		} as any;
		provider = new DatabaseHistoryProvider(storageManager);
		await provider.clearHistory(sessionId);
	});

	afterEach(async () => {
		await provider.clearHistory(sessionId);
		if (typeof storageManager.disconnect === 'function') {
			await storageManager.disconnect();
		}
		vi.restoreAllMocks();
	});

	it('should save and retrieve messages in order', async () => {
		await provider.saveMessage(sessionId, message);
		const history = await provider.getHistory(sessionId);
		expect(history).toEqual([message]);
	});

	it('should enforce message limit', async () => {
		const many = Array(1005).fill(message);
		await backend.set(`messages:${sessionId}`, many);
		await provider.saveMessage(sessionId, message);
		const saved = await provider.getHistory(sessionId);
		expect(saved.length).toBeLessThanOrEqual(1000);
	});

	it('should clear history', async () => {
		await provider.saveMessage(sessionId, message);
		await provider.clearHistory(sessionId);
		const history = await provider.getHistory(sessionId);
		expect(history.length).toBe(0);
	});

	it('should log and handle getHistory error gracefully', async () => {
		const spy = vi.spyOn(backend, 'get').mockRejectedValueOnce(new Error('fail'));
		const result = await provider.getHistory(sessionId);
		expect(result).toEqual([]);
		spy.mockRestore();
	});

	it('should log and handle saveMessage error gracefully', async () => {
		const spy = vi.spyOn(backend, 'set').mockRejectedValueOnce(new Error('fail'));
		await provider.saveMessage(sessionId, message);
		spy.mockRestore();
	});

	it('should log and handle clearHistory error gracefully', async () => {
		const spy = vi.spyOn(backend, 'delete').mockRejectedValueOnce(new Error('fail'));
		await provider.clearHistory(sessionId);
		spy.mockRestore();
	});

	it('should truncate and redact content in debug logs', async () => {
		const longMessage = { role: 'user' as const, content: 'a'.repeat(200) };
		const spy = vi.spyOn(backend, 'set');
		await provider.saveMessage(sessionId, longMessage);
		expect(spy).toHaveBeenCalled();
		spy.mockRestore();
	});

	it('should perform under 100ms for 1000+ messages', async () => {
		const many = Array.from({ length: 1200 }, (_, i) => makeMessage(i));
		await backend.set(`messages:${sessionId}`, many);
		const start = Date.now();
		await provider.saveMessage(sessionId, makeMessage(1201));
		const duration = Date.now() - start;
		expect(duration).toBeLessThan(100); // Adjust threshold as needed
	});
});

import { describe, it, expect } from 'vitest';
import { StorageManager } from '../../../../../storage/manager.js';
import { createDatabaseHistoryProvider } from '../factory.js';
import { DatabaseHistoryProvider } from '../database.js';

describe('createDatabaseHistoryProvider', () => {
	it('should create a DatabaseHistoryProvider instance for in-memory backend', async () => {
		const config = {
			cache: { type: 'in-memory' as const },
			database: { type: 'in-memory' as const },
		};
		const storageManager = new StorageManager(config);
		await storageManager.connect();
		const provider = createDatabaseHistoryProvider(storageManager);
		expect(provider).toBeInstanceOf(DatabaseHistoryProvider);
	});
	it('should create a DatabaseHistoryProvider instance for in-memory backend', async () => {
		const config = {
			cache: { type: 'in-memory' as const },
			database: { type: 'in-memory' as const },
		};
		const storageManager = new StorageManager(config);
		await storageManager.connect();
		const provider = createDatabaseHistoryProvider(storageManager);
		expect(provider).toBeInstanceOf(DatabaseHistoryProvider);
	});

	it('should create a DatabaseHistoryProvider instance for SQLite backend', async () => {
		let hasSqlite = true;
		try {
			require('better-sqlite3');
		} catch {
			hasSqlite = false;
		}
		if (!hasSqlite) {
			console.warn('Skipping SQLite test: better-sqlite3 not installed');
			return;
		}
		const config = {
			cache: { type: 'in-memory' as const },
			database: { type: 'sqlite' as const, path: ':memory:' },
		};
		const storageManager = new StorageManager(config);
		await storageManager.connect();
		const provider = createDatabaseHistoryProvider(storageManager);
		expect(provider).toBeInstanceOf(DatabaseHistoryProvider);
	});

	it('should create a DatabaseHistoryProvider instance for PostgreSQL backend', async () => {
		let hasPg = true;
		try {
			require('pg');
		} catch {
			hasPg = false;
		}
		if (!hasPg) {
			console.warn('Skipping PostgreSQL test: pg not installed');
			return;
		}
		const config = {
			cache: { type: 'in-memory' as const },
			database: {
				type: 'postgres' as const,
				url: 'postgres://testuser:testpass@localhost:5432/testdb',
			},
		};
		const storageManager = new StorageManager(config);
		try {
			await storageManager.connect();
		} catch (err) {
			console.warn('Skipping PostgreSQL test: could not connect to database', err);
			return;
		}
		const provider = createDatabaseHistoryProvider(storageManager);
		expect(provider).toBeInstanceOf(DatabaseHistoryProvider);
	}, 20000);

	it('should throw for misconfigured backend', async () => {
		const config = { cache: { type: 'in-memory' as const }, database: { type: 'unknown' as any } };
		// StorageManager constructor should throw synchronously for invalid config
		expect(() => new StorageManager(config)).toThrow(/Invalid backend type/);
	});
	it('should throw for misconfigured backend', async () => {
		const config = { cache: { type: 'in-memory' as const }, database: { type: 'unknown' as any } };
		// StorageManager constructor should throw synchronously for invalid config
		expect(() => new StorageManager(config)).toThrow(/Invalid backend type/);
	});
});

