						message: {
							content: 'I will use the available tools.',
							tool_calls: [
								{
									id: 'call_1',
									function: {
										name: 'test_file_operation',
										arguments: '{"path": "/test/file.txt", "operation": "read"}',
									},
								},
							],
						},
					},
				],
			};

			mockOpenAI.chat.completions.create.mockResolvedValue(mockResponse);

			await qwenService.generate('Use available tools');

			// Verify that getToolsForProvider was called with 'qwen'
			expect(mockUnifiedToolManager.getToolsForProvider).toHaveBeenCalledWith('qwen');
		});

		it('should handle empty tool calls gracefully', async () => {
			// Mock the context manager to return properly formatted messages
			mockGetFormattedMessage.mockResolvedValue([
				{ role: 'system', content: 'You are a helpful AI assistant.' },
				{ role: 'user', content: 'Simple question' },
			]);

			const mockResponse = {
				choices: [
					{
						message: {
							content: 'I can help you without using any tools.',
							// Explicitly set tool_calls to undefined to test graceful handling
							tool_calls: undefined,
						},
					},
				],
			};

			mockOpenAI.chat.completions.create.mockResolvedValue(mockResponse);

			const result = await qwenService.generate('Simple question');

			expect(result).toBe('I can help you without using any tools.');
			expect(mockUnifiedToolManager.executeTool).not.toHaveBeenCalled();
		});

		it('should maintain conversation context across multiple calls', async () => {
			// Setup mock to return different messages for different calls
			let callCount = 0;
			mockGetFormattedMessage.mockImplementation(() => {
				if (callCount === 0) {
					return Promise.resolve([
						{ role: 'system', content: 'You are a helpful AI assistant.' },
						{ role: 'user', content: 'Hello, can you help me?' },
					]);
				} else {
					return Promise.resolve([
						{ role: 'system', content: 'You are a helpful AI assistant.' },
						{ role: 'user', content: 'Hello, can you help me?' },
						{ role: 'assistant', content: 'Hello! How can I help you today?' },
						{ role: 'user', content: 'What did we discuss earlier?' },
					]);
				}
			});

			const responses = [
				{
					choices: [
						{
							message: {
								content: 'Hello! How can I help you today?',
							},
						},
					],
				},
				{
					choices: [
						{
							message: {
								content:
									'I remember you asked about that earlier. Here is the updated information.',
							},
						},
					],
				},
			];

			mockOpenAI.chat.completions.create.mockImplementation(() => {
				return Promise.resolve(responses[callCount++]);
			});

			// First call
			await qwenService.generate('Hello, can you help me?');

			// Second call - should include context from first call
			const result = await qwenService.generate('What did we discuss earlier?');

			expect(mockOpenAI.chat.completions.create).toHaveBeenCalledTimes(2);
			expect(result).toContain('remember you asked about that earlier');
		});
	});

	describe('Configuration and Setup Tests', () => {
		it('should initialize with correct configuration', () => {
			const config = qwenService.getConfig();
			expect(config).toEqual({
				provider: 'qwen',
				model: 'qwen2.5-72b-instruct',
			});
		});

		it('should handle different Qwen models', async () => {
			const qwenServiceSmall = new QwenService(
				mockOpenAI as any,
				'qwen2.5-7b-instruct',
				mockMCPManager,
				mockContextManager,
				5,
				mockOptions,
				mockUnifiedToolManager
			);

			const config = qwenServiceSmall.getConfig();
			expect(config.model).toBe('qwen2.5-7b-instruct');
		});

		it('should handle different Qwen options', async () => {
			const customOptions: QwenOptions = {
				enableThinking: false,
				thinkingBudget: 500,
				temperature: 0.5,
			};

			// Mock the context manager to return properly formatted messages
			mockGetFormattedMessage.mockResolvedValue([
				{ role: 'system', content: 'You are a helpful AI assistant.' },
				{ role: 'user', content: 'Test' },
			]);

			const mockResponse = {
				choices: [
					{
						message: {
							content: 'Test response from Qwen',
						},
					},
				],
			};

			mockOpenAI.chat.completions.create.mockResolvedValue(mockResponse);

			const qwenServiceCustom = new QwenService(
				mockOpenAI as any,
				'qwen2.5-72b-instruct',
				mockMCPManager,
				mockContextManager,
				3,
				customOptions,
				mockUnifiedToolManager
			);

			await qwenServiceCustom.generate('Test');

			expect(mockOpenAI.chat.completions.create).toHaveBeenCalledWith(
				expect.objectContaining({
					enable_thinking: false,
					thinking_budget: 500,
					temperature: 0.5,
				})
			);
		});
	});
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { QwenService, QwenOptions } from '../qwen.js';
import { MCPManager } from '../../../../mcp/manager.js';
import { ContextManager } from '../../messages/manager.js';
import { UnifiedToolManager } from '../../../tools/unified-tool-manager.js';

// Mock OpenAI client
const mockOpenAI = {
	chat: {
		completions: {
			create: vi.fn(),
		},
	},
};

// Mock dependencies
const mockMCPManager = {
	getAllTools: vi.fn().mockResolvedValue([]),
	executeTool: vi.fn(),
} as unknown as MCPManager;

const mockContextManager = {
	addUserMessage: vi.fn().mockResolvedValue(undefined),
	addAssistantMessage: vi.fn().mockResolvedValue(undefined),
	addToolResult: vi.fn().mockResolvedValue(undefined),
	getFormattedMessage: vi.fn().mockResolvedValue([{ role: 'user', content: 'test message' }]),
} as unknown as ContextManager;

const mockUnifiedToolManager = {
	getToolsForProvider: vi.fn().mockResolvedValue([]),
	executeTool: vi.fn(),
} as unknown as UnifiedToolManager;

describe('QwenService', () => {
	let qwenService: QwenService;
	const mockOptions: QwenOptions = {
		enableThinking: true,
		thinkingBudget: 1000,
	};

	beforeEach(() => {
		vi.clearAllMocks();
		qwenService = new QwenService(
			mockOpenAI as any,
			'qwen2.5-72b-instruct',
			mockMCPManager,
			mockContextManager,
			5,
			mockOptions,
			mockUnifiedToolManager
		);
	});

	describe('constructor', () => {
		it('should create QwenService with correct configuration', () => {
			expect(qwenService).toBeInstanceOf(QwenService);
		});
	});

	describe('getConfig', () => {
		it('should return correct configuration', () => {
			const config = qwenService.getConfig();
			expect(config).toEqual({
				provider: 'qwen',
				model: 'qwen2.5-72b-instruct',
			});
		});
	});

	describe('directGenerate', () => {
		it('should generate response without conversation context', async () => {
			const mockResponse = {
				choices: [
					{
						message: {
							content: 'Test response from Qwen',
						},
					},
				],
			};

			mockOpenAI.chat.completions.create.mockResolvedValue(mockResponse);

			const result = await qwenService.directGenerate('test input', 'test system prompt');

			expect(mockOpenAI.chat.completions.create).toHaveBeenCalledWith({
				model: 'qwen2.5-72b-instruct',
				messages: [
					{ role: 'system', content: 'test system prompt' },
					{ role: 'user', content: 'test input' },
				],
				enable_thinking: true,
				thinking_budget: 1000,
			});

			expect(result).toBe('Test response from Qwen');
		});

		it('should handle errors gracefully', async () => {
			const error = new Error('API Error');
			mockOpenAI.chat.completions.create.mockRejectedValue(error);

			await expect(qwenService.directGenerate('test input')).rejects.toThrow(
				'[QwenService] Direct generate failed: API Error'
			);
		});
	});

	describe('generate', () => {
		it('should handle conversation with tool calls', async () => {
			const mockResponses = [
				{
					choices: [
						{
							message: {
								content: 'I will help you with that',
								tool_calls: [
									{
										id: 'call_1',
										function: {
											name: 'test_tool',
											arguments: '{"param": "value"}',
										},
									},
								],
							},
						},
					],
				},
				{
					choices: [
						{
							message: {
								content: 'Tool result: success',
							},
						},
					],
				},
			];
			let callCount = 0;
			mockOpenAI.chat.completions.create.mockImplementation(() => {
				return Promise.resolve(mockResponses[callCount++]);
			});
			(mockUnifiedToolManager.executeTool as any).mockResolvedValue({ result: 'success' });

			const result = await qwenService.generate('test input');

			expect(mockOpenAI.chat.completions.create).toHaveBeenCalled();
			expect(result).toContain('success');
		});

		it('should handle responses without tool calls', async () => {
			const mockResponse = {
				choices: [
					{
						message: {
							content: 'Simple response from Qwen',
						},
					},
				],
			};

			mockOpenAI.chat.completions.create.mockResolvedValue(mockResponse);

			const result = await qwenService.generate('test input');

			expect(result).toBe('Simple response from Qwen');
		});
	});
});

import { logger } from 'src/core/logger/index.js';

export class AnthropicService {
	private contextManager: any;
	private unifiedToolManager: any;
	private config: any;

	constructor(contextManager: any, unifiedToolManager: any, config: any) {
		this.contextManager = contextManager;
		this.unifiedToolManager = unifiedToolManager;
		this.config = config;
	}

	async generate(
		input: string,
		imageDataInput?: { image: string; mimeType: string },
		stream: boolean = false
	): Promise<string> {
		try {
			// Check for file references in user input and attempt to find them
			const fileReferences = this.extractFileReferences(input);
			let contextualInfo = '';

			if (fileReferences.length > 0 && this.unifiedToolManager) {
				contextualInfo = await this.searchForReferencedFiles(fileReferences);
			}

			// Add the user message to context
			this.contextManager.addUserMessage(input, imageDataInput);

			// Get the current context for the API call
			const messages = this.contextManager.getMessages();

			// Add contextual file information if found
			if (contextualInfo) {
				// Insert context before the last user message
				const lastUserMessageIndex = messages.length - 1;
				if (lastUserMessageIndex >= 0 && messages[lastUserMessageIndex].role === 'user') {
					const lastMessage = messages[lastUserMessageIndex];
					if (Array.isArray(lastMessage.content) && lastMessage.content.length > 0) {
						const lastContent = lastMessage.content[lastMessage.content.length - 1];
						if (lastContent.type === 'text') {
							lastContent.text = `${contextualInfo}\n\n${lastContent.text}`;
						}
					}
				}
			}

			const systemMessage = this.contextManager.getSystemMessage();

			logger.debug('AnthropicService: Sending request to Anthropic API', {
				messageCount: messages.length,
				hasSystem: !!systemMessage,
				stream,
				model: this.config.anthropic?.model || 'claude-3-5-sonnet-20241022',
				hasFileContext: !!contextualInfo,
			});

			// ... existing code ...
			// ... existing code ...
			// Add a dummy return for now (replace with actual result if available)
			return '';
		} catch (error) {
			logger.error('AnthropicService: Error generating response', { error });
			throw error;
		}
	}

	/**
	 * Extract potential file references from user input
	 */
	private extractFileReferences(input: string): string[] {
		const fileReferences: string[] = [];

		// Look for common file patterns
		const patterns = [
			// Files with extensions
			/\b[\w-]+\.[a-zA-Z0-9]{1,10}\b/g,
			// Quoted filenames
			/["'`]([^"'`]*\.[a-zA-Z0-9]{1,10})["'`]/g,
			// Files in paths
			/[\w\-/.]+\.[a-zA-Z0-9]{1,10}/g,
		];

		for (const pattern of patterns) {
			const matches = input.match(pattern);
			if (matches) {
				fileReferences.push(...matches.map(match => match.replace(/["'`]/g, '').trim()));
			}
		}

		// Remove duplicates and filter out common non-file extensions
		const excludeExtensions = ['com', 'org', 'net', 'edu', 'gov', 'io', 'co'];
		return [...new Set(fileReferences)].filter(ref => {
			const ext = ref.split('.').pop()?.toLowerCase();
			return ext && !excludeExtensions.includes(ext) && ref.length < 100;
		});
	}

	/**
	 * Search for referenced files and return contextual information
	 */
	private async searchForReferencedFiles(fileReferences: string[]): Promise<string> {
		if (!this.unifiedToolManager || fileReferences.length === 0) {
			return '';
		}

		const foundFiles: string[] = [];

		for (const fileRef of fileReferences.slice(0, 3)) {
			// Limit to 3 files to avoid spam
			try {
				// Use file_search tool to find the file
				const searchResult = await this.unifiedToolManager.executeTool(
					'file_search',
					{
						query: fileRef,
						explanation: `Searching for file referenced by user: ${fileRef}`,
					},
					undefined
				); // No sessionId available in this context

				if (searchResult && Array.isArray(searchResult) && searchResult.length > 0) {
					foundFiles.push(`Found file: ${fileRef} at ${searchResult[0]}`);
				}
			} catch (error) {
				// Silently continue if file search fails
				logger.debug('AnthropicService: File search failed', {
					file: fileRef,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}

		if (foundFiles.length > 0) {
			return `[Context: Located referenced files]\n${foundFiles.join('\n')}\n`;
		}

		return '';
	}
}

import Anthropic from '@anthropic-ai/sdk';
import { ToolSet } from '../../../mcp/types.js';
import { MCPManager } from '../../../mcp/manager.js';
import { UnifiedToolManager, CombinedToolSet } from '../../tools/unified-tool-manager.js';
import { ContextManager } from '../messages/manager.js';
import { ImageData } from '../messages/types.js';
import { ILLMService, LLMServiceConfig } from './types.js';
import { logger } from '../../../logger/index.js';
import { formatToolResult } from '../utils/tool-result-formatter.js';
import { EventManager } from '../../../events/event-manager.js';
import { SessionEvents } from '../../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

export class AnthropicService implements ILLMService {
	private anthropic: Anthropic;
	private model: string;
	private mcpManager: MCPManager;
	private unifiedToolManager: UnifiedToolManager | undefined;
	private contextManager: ContextManager;
	private maxIterations: number;
	private eventManager?: EventManager;

	constructor(
		anthropic: Anthropic,
		model: string,
		mcpManager: MCPManager,
		contextManager: ContextManager,
		maxIterations: number = 5,
		unifiedToolManager?: UnifiedToolManager
	) {
		this.anthropic = anthropic;
		this.model = model;
		this.mcpManager = mcpManager;
		this.contextManager = contextManager;
		this.maxIterations = maxIterations;
		this.unifiedToolManager = unifiedToolManager;
	}

	/**
	 * Set the event manager for emitting LLM response events
	 */
	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	async generate(userInput: string, imageData?: ImageData, _stream?: boolean): Promise<string> {
		await this.contextManager.addUserMessage(userInput, imageData);

		const messageId = uuidv4();
		const startTime = Date.now();

		// Try to get sessionId from contextManager if available, otherwise undefined
		const sessionId = (this.contextManager as any)?.sessionId;

		// Emit LLM response started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
				sessionId,
				messageId,
				model: this.model,
				timestamp: startTime,
			});
		}

		// Use unified tool manager if available, otherwise fall back to MCP manager
		let formattedTools: any[];
		if (this.unifiedToolManager) {
			formattedTools = await this.unifiedToolManager.getToolsForProvider('anthropic');
		} else {
			const rawTools = await this.mcpManager.getAllTools();
			formattedTools = this.formatToolsForAnthropic(rawTools);
		}

		logger.silly(`Formatted tools: ${JSON.stringify(formattedTools, null, 2)}`);

		let iterationCount = 0;
		try {
			while (iterationCount < this.maxIterations) {
				iterationCount++;

				// Attempt to get a response, with retry logic
				const { response } = await this.getAIResponseWithRetries(formattedTools, userInput);

				// Extract text content and tool uses
				let textContent = '';
				const toolUses = [];

				for (const content of response.content) {
					if (content.type === 'text') {
						textContent += content.text;
					} else if (content.type === 'tool_use') {
						toolUses.push(content);
					}
				}

				// If there are no tool uses, we're done
				if (toolUses.length === 0) {
					// Add assistant message to history
					await this.contextManager.addAssistantMessage(textContent);

					// Emit LLM response completed event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_COMPLETED, {
							sessionId,
							messageId,
							model: this.model,
							duration: Date.now() - startTime,
							timestamp: Date.now(),
							response: textContent,
						});
					}

					return textContent;
				}

				// Log thinking steps when assistant provides reasoning before tool calls
				if (textContent && textContent.trim()) {
					logger.info(`💭 ${textContent.trim()}`);

					// Emit thinking event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_THINKING, {
							sessionId,
							messageId,
							timestamp: Date.now(),
						});
					}
				}

				// Transform tool uses into the format expected by ContextManager
				const formattedToolCalls = toolUses.map((toolUse: any) => ({
					id: toolUse.id,
					type: 'function' as const,
					function: {
						name: toolUse.name,
						arguments: JSON.stringify(toolUse.input),
					},
				}));

				// Add assistant message with tool calls to history
				await this.contextManager.addAssistantMessage(textContent, formattedToolCalls);

				// Handle tool uses
				for (const toolUse of toolUses) {
					logger.debug(`Tool call initiated: ${JSON.stringify(toolUse, null, 2)}`);
					logger.info(`🔧 Using tool: ${toolUse.name}`);
					const toolName = toolUse.name;
					const args = toolUse.input;
					const toolUseId = toolUse.id;

					// Execute tool
					try {
						let result: any;
						if (this.unifiedToolManager) {
							result = await this.unifiedToolManager.executeTool(toolName, args, sessionId);
						} else {
							result = await this.mcpManager.executeTool(toolName, args);
						}

						// Display formatted tool result
						const formattedResult = formatToolResult(toolName, result);
						logger.info(`📋 Tool Result:\n${formattedResult}`);

						// Add tool result to message manager
						await this.contextManager.addToolResult(toolUseId, toolName, result);
					} catch (error) {
						// Handle tool execution error
						const errorMessage = error instanceof Error ? error.message : String(error);
						logger.error(`Tool execution error for ${toolName}: ${errorMessage}`);

						// Add error as tool result
						await this.contextManager.addToolResult(toolUseId, toolName, {
							error: errorMessage,
						});
					}
				}
			}

			// If we reached max iterations, return a message
			logger.warn(`Reached maximum iterations (${this.maxIterations}) for task.`);
			const finalResponse = 'Task completed but reached maximum tool call iterations.';
			await this.contextManager.addAssistantMessage(finalResponse);
			return finalResponse;
		} catch (error) {
			// Handle API errors
			const errorMessage = error instanceof Error ? error.message : String(error);

			// Emit LLM response error event
			if (this.eventManager && sessionId) {
				this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_ERROR, {
					sessionId,
					messageId,
					model: this.model,
					error: errorMessage,
					timestamp: Date.now(),
				});
			}
			logger.error(`Error in Anthropic service API call: ${errorMessage}`, { error });
			await this.contextManager.addAssistantMessage(`Error processing request: ${errorMessage}`);
			return `Error processing request: ${errorMessage}`;
		}
	}

	/**
	 * Direct generate method that bypasses conversation context
	 * Used for internal tool operations that shouldn't pollute conversation history
	 * @param userInput - The input to generate a response for
	 * @param systemPrompt - Optional system prompt to use
	 * @returns Promise<string> - The generated response
	 */
	async directGenerate(_userInput: string, systemPrompt?: string): Promise<string> {
		let attempts = 0;
		const MAX_ATTEMPTS = 3;

		logger.debug('AnthropicService: Direct generate call (bypassing conversation context)', {
			inputLength: _userInput.length,
			hasSystemPrompt: !!systemPrompt,
		});

		while (attempts < MAX_ATTEMPTS) {
			attempts++;
			try {
				// Create a minimal message array for direct API call
				const messages = [
					{
						role: 'user' as const,
						content: _userInput,
					},
				];

				// Make direct API call without adding to conversation context
				const response = await this.anthropic.messages.create({
					model: this.model,
					messages: messages,
					...(systemPrompt && { system: systemPrompt }),
					max_tokens: 4096,
					// No tools for direct calls - this is for simple text generation
				});

				// Extract text content from response
				let textContent = '';
				for (const content of response.content) {
					if (content.type === 'text') {
						textContent += content.text;
					}
				}

				logger.debug('AnthropicService: Direct generate completed', {
					responseLength: textContent.length,
				});

				return textContent;
			} catch (error) {
				const apiError = error as any;
				const errorStatus = apiError.status || apiError.error?.status;
				const errorType = apiError.error?.type || 'unknown_error';
				const errorMessage = apiError.message || apiError.error?.message || 'Unknown error';

				logger.error(
					`Error in Anthropic direct generate call (Attempt ${attempts}/${MAX_ATTEMPTS}): ${errorMessage}`,
					{
						status: errorStatus,
						type: errorType,
						attempt: attempts,
						maxAttempts: MAX_ATTEMPTS,
						inputLength: _userInput.length,
					}
				);

				// Check if this is a retryable error
				const isRetryable = this.isRetryableError(errorStatus, errorType);

				if (attempts >= MAX_ATTEMPTS || !isRetryable) {
					if (!isRetryable) {
						logger.error(`Non-retryable error in direct generate: ${errorType} (${errorStatus})`);
					} else {
						logger.error(`Failed direct generate after ${MAX_ATTEMPTS} attempts.`);
					}
					throw new Error(`Direct generate failed: ${errorMessage}`);
				}

				// Calculate delay with exponential backoff and jitter
				const delay = this.calculateRetryDelay(attempts, errorStatus, errorType);
				logger.info(
					`Retrying direct generate in ${delay}ms... (Attempt ${attempts + 1}/${MAX_ATTEMPTS})`
				);

				await new Promise(resolve => setTimeout(resolve, delay));
			}
		}

		throw new Error('Direct generate failed after maximum retry attempts');
	}

	async getAllTools(): Promise<ToolSet | CombinedToolSet> {
		if (this.unifiedToolManager) {
			return await this.unifiedToolManager.getAllTools();
		}
		return this.mcpManager.getAllTools();
	}

	getConfig(): LLMServiceConfig {
		return {
			provider: 'anthropic',
			model: this.model,
		};
	}

	// Helper methods
	private async getAIResponseWithRetries(
		tools: any[],
		_userInput: string
	): Promise<{ response: any }> {
		let attempts = 0;
		const MAX_ATTEMPTS = 3;

		// Add a log of the number of tools in response
		logger.debug(`Tools in response: ${tools.length}`);

		while (attempts < MAX_ATTEMPTS) {
			attempts++;
			try {
				// Get all formatted messages from conversation history
				const formattedMessages = await this.contextManager.getAllFormattedMessages();

				// For Anthropic, we need to separate system messages from the messages array
				const systemMessage = formattedMessages.find(msg => msg.role === 'system');
				const nonSystemMessages = formattedMessages.filter(msg => msg.role !== 'system');

				// Call Anthropic API
				const response = await this.anthropic.messages.create({
					model: this.model,
					messages: nonSystemMessages,
					...(systemMessage && { system: systemMessage.content }),
					tools: attempts === 1 ? tools : [], // Only offer tools on first attempt
					max_tokens: 4096,
				});

				logger.silly('ANTHROPIC MESSAGE RESPONSE: ', JSON.stringify(response, null, 2));

				if (!response || !response.content) {
					throw new Error('Received empty response from Anthropic API');
				}

				return { response };
			} catch (error) {
				const apiError = error as any;
				const errorStatus = apiError.status || apiError.error?.status;
				const errorType = apiError.error?.type || 'unknown_error';
				const errorMessage = apiError.message || apiError.error?.message || 'Unknown error';

				logger.error(
					`Error in Anthropic API call (Attempt ${attempts}/${MAX_ATTEMPTS}): ${errorMessage}`,
					{
						status: errorStatus,
						type: errorType,
						attempt: attempts,
						maxAttempts: MAX_ATTEMPTS,
					}
				);

				// Handle specific error types
				if (
					errorType === 'invalid_request_error' &&
					errorMessage.includes('maximum context length')
				) {
					logger.warn(
						`Context length exceeded. ContextManager compression might not be sufficient. Error details: ${JSON.stringify(apiError.error)}`
					);
				}

				// Check if this is a retryable error
				const isRetryable = this.isRetryableError(errorStatus, errorType);

				if (attempts >= MAX_ATTEMPTS || !isRetryable) {
					if (!isRetryable) {
						logger.error(`Non-retryable error encountered: ${errorType} (${errorStatus})`);
					} else {
						logger.error(`Failed to get response from Anthropic after ${MAX_ATTEMPTS} attempts.`);
					}
					throw error;
				}

				// Calculate delay with exponential backoff and jitter
				const delay = this.calculateRetryDelay(attempts, errorStatus, errorType);
				logger.info(`Retrying in ${delay}ms... (Attempt ${attempts + 1}/${MAX_ATTEMPTS})`);

				await new Promise(resolve => setTimeout(resolve, delay));
			}
		}

		throw new Error('Failed to get response after maximum retry attempts');
	}

	/**
	 * Determines if an error is retryable based on status code and error type
	 */
	private isRetryableError(status: number, errorType: string): boolean {
		// Non-retryable errors
		if (status === 400 || status === 401 || status === 403 || status === 404) {
			return false;
		}

		if (errorType === 'invalid_request_error' || errorType === 'authentication_error') {
			return false;
		}

		// Retryable errors: 429, 500, 502, 503, 504, 529, network errors, etc.
		return status >= 429 || status >= 500 || errorType === 'overloaded_error' || !status;
	}

	/**
	 * Calculates retry delay with exponential backoff and jitter
	 */
	private calculateRetryDelay(attempt: number, status: number, errorType: string): number {
		let baseDelay = 1000; // Base delay of 1 second

		// Special handling for overloaded errors (529)
		if (status === 529 || errorType === 'overloaded_error') {
			baseDelay = 3000; // Start with 3 seconds for overloaded errors
		}

		// Exponential backoff: 2^attempt * baseDelay
		const exponentialDelay = Math.pow(2, attempt - 1) * baseDelay;

		// Add jitter (random factor between 0.5 and 1.5)
		const jitter = 0.5 + Math.random();
		const finalDelay = Math.min(exponentialDelay * jitter, 30000); // Cap at 30 seconds

		return Math.round(finalDelay);
	}

	private formatToolsForAnthropic(tools: ToolSet): any[] {
		// Convert the ToolSet object to an array of tools in Anthropic's format
		return Object.entries(tools).map(([toolName, tool]) => {
			const input_schema: { type: string; properties: any; required: string[] } = {
				type: 'object',
				properties: {},
				required: [],
			};

			// Map tool parameters to JSON Schema format
			if (tool.parameters) {
				// The actual parameters structure appears to be a JSON Schema object
				const jsonSchemaParams = tool.parameters as any;

				if (jsonSchemaParams.type === 'object' && jsonSchemaParams.properties) {
					input_schema.properties = jsonSchemaParams.properties;
					if (Array.isArray(jsonSchemaParams.required)) {
						input_schema.required = jsonSchemaParams.required;
					}
				} else {
					logger.warn(`Unexpected parameters format for tool ${toolName}:`, jsonSchemaParams);
				}
			} else {
				// Handle case where tool might have no parameters
				logger.debug(`Tool ${toolName} has no defined parameters.`);
			}

			return {
				name: toolName,
				description: tool.description,
				input_schema: input_schema,
			};
		});
	}
}

import {
	BedrockRuntimeClient,
	BedrockRuntimeClientConfig,
	InvokeModelCommand,
} from '@aws-sdk/client-bedrock-runtime';
import { ILLMService, LLMServiceConfig } from './types.js';
import { AwsConfig } from '../config.js';
import { MCPManager } from '../../../mcp/manager.js';
import { ContextManager } from '../messages/manager.js';
import { UnifiedToolManager, CombinedToolSet } from '../../tools/unified-tool-manager.js';
import { ImageData } from '../messages/types.js';
import { ToolSet } from '../../../mcp/types.js';
import { logger } from '../../../logger/index.js';
import { formatToolResult } from '../utils/tool-result-formatter.js';
import { TextDecoder } from 'util';
import {
	BedrockAnthropicMessageFormatter,
	BedrockLlamaMessageFormatter,
	BedrockTitanMessageFormatter,
	BedrockDeepSeekMessageFormatter,
	BedrockAI21MessageFormatter,
} from '../messages/formatters/aws.js';
import { EventManager } from '../../../events/event-manager.js';
import { SessionEvents } from '../../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

// Complete AWS Bedrock model families (2025)
enum ModelFamily {
	ANTHROPIC = 'anthropic',
	META_LLAMA = 'meta',
	AMAZON_TITAN = 'amazon.titan',
	AMAZON_NOVA = 'amazon.nova',
	AI21_LABS = 'ai21',
	COHERE = 'cohere',
	DEEPSEEK = 'deepseek',
	LUMA_AI = 'luma',
	MISTRAL_AI = 'mistral',
	STABILITY_AI = 'stability',
	TWELVELABS = 'twelvelabs',
	WRITER = 'writer',
}

export class AwsService implements ILLMService {
	private client: BedrockRuntimeClient;
	private model: string;
	private mcpManager: MCPManager;
	private unifiedToolManager: UnifiedToolManager | undefined;
	private contextManager: ContextManager;
	private maxIterations: number;
	private modelFamily: ModelFamily;
	private inferenceProfileArn: string | undefined;
	private formatter: any; // Should be IMessageFormatter, but use any for now if needed
	private eventManager?: EventManager;

	constructor(
		model: string,
		mcpManager: MCPManager,
		contextManager: ContextManager,
		unifiedToolManager?: UnifiedToolManager,
		maxIterations = 10,
		awsConfig?: AwsConfig
	) {
		this.model = model;
		this.mcpManager = mcpManager;
		this.unifiedToolManager = unifiedToolManager;
		this.contextManager = contextManager;
		this.maxIterations = maxIterations;
		this.modelFamily = this.detectModelFamily(model);
		this.inferenceProfileArn =
			awsConfig?.inferenceProfileArn || process.env.AWS_BEDROCK_INFERENCE_PROFILE_ARN;

		switch (this.modelFamily) {
			case ModelFamily.ANTHROPIC:
				this.formatter = new BedrockAnthropicMessageFormatter();
				break;
			case ModelFamily.META_LLAMA:
				this.formatter = new BedrockLlamaMessageFormatter();
				break;
			case ModelFamily.AMAZON_TITAN:
				this.formatter = new BedrockTitanMessageFormatter();
				break;
			case ModelFamily.DEEPSEEK:
				this.formatter = new BedrockDeepSeekMessageFormatter();
				break;
			case ModelFamily.AI21_LABS:
				this.formatter = new BedrockAI21MessageFormatter();
				break;
			default:
				this.formatter = new BedrockAnthropicMessageFormatter();
		}

		const clientConfig: BedrockRuntimeClientConfig = {
			region: awsConfig?.region || process.env.AWS_DEFAULT_REGION || 'us-east-1',
		};

		// Handle credentials from config or environment
		const accessKeyId = awsConfig?.accessKeyId || process.env.AWS_ACCESS_KEY_ID;
		const secretAccessKey = awsConfig?.secretAccessKey || process.env.AWS_SECRET_ACCESS_KEY;
		const sessionToken = awsConfig?.sessionToken || process.env.AWS_SESSION_TOKEN;

		if (accessKeyId && secretAccessKey) {
			const credentials: any = {
				accessKeyId,
				secretAccessKey,
			};
			if (sessionToken) {
				credentials.sessionToken = sessionToken;
			}
			clientConfig.credentials = credentials;
		}

		this.client = new BedrockRuntimeClient(clientConfig);

		logger.info(
			`AWS Bedrock service initialized with model: ${model} (family: ${this.modelFamily}) in region: ${clientConfig.region}`
		);
	}

	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	private detectModelFamily(modelId: string): ModelFamily {
		const id = modelId.toLowerCase();

		logger.info(`Detecting model family for: ${id}`);

		if (id.startsWith('anthropic.') || id.startsWith('us.anthropic.')) {
			logger.info(`Detected ANTHROPIC model family`);
			return ModelFamily.ANTHROPIC;
		}
		if (id.startsWith('meta.') || id.startsWith('us.meta.')) {
			logger.info(`Detected META_LLAMA model family`);
			return ModelFamily.META_LLAMA;
		}
		if (id.startsWith('amazon.titan')) {
			logger.debug(`Detected AMAZON_TITAN model family`);
			return ModelFamily.AMAZON_TITAN;
		}
		if (id.startsWith('amazon.nova')) {
			logger.debug(`Detected AMAZON_NOVA model family`);
			return ModelFamily.AMAZON_NOVA;
		}
		if (id.startsWith('ai21.') || id.startsWith('us.ai21.')) {
			logger.debug(`Detected AI21_LABS model family`);
			return ModelFamily.AI21_LABS;
		}
		if (id.startsWith('cohere.') || id.startsWith('us.cohere.')) {
			logger.debug(`Detected COHERE model family`);
			return ModelFamily.COHERE;
		}
		if (id.startsWith('deepseek') || id.startsWith('us.deepseek')) {
			logger.debug(`Detected DEEPSEEK model family`);
			return ModelFamily.DEEPSEEK;
		}
		if (id.startsWith('luma.')) {
			logger.debug(`Detected LUMA_AI model family`);
			return ModelFamily.LUMA_AI;
		}
		if (id.startsWith('mistral.') || id.startsWith('us.mistral.')) {
			logger.debug(`Detected MISTRAL_AI model family`);
			return ModelFamily.MISTRAL_AI;
		}
		if (id.startsWith('stability.')) {
			logger.debug(`Detected STABILITY_AI model family`);
			return ModelFamily.STABILITY_AI;
		}
		if (id.startsWith('twelvelabs.')) {
			logger.debug(`Detected TWELVELABS model family`);
			return ModelFamily.TWELVELABS;
		}
		if (id.startsWith('writer.')) {
			logger.debug(`Detected WRITER model family`);
			return ModelFamily.WRITER;
		}

		// Default to Anthropic for backward compatibility
		logger.warn(`Unknown model family for ${modelId}, defaulting to Anthropic format`);
		return ModelFamily.ANTHROPIC;
	}

	async generate(userInput: string, imageData?: ImageData): Promise<string> {
		await this.contextManager.addUserMessage(userInput, imageData);

		const messageId = uuidv4();
		const startTime = Date.now();

		// Try to get sessionId from contextManager if available, otherwise undefined
		const sessionId = (this.contextManager as any)?.sessionId;

		// Emit LLM response started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
				sessionId,
				messageId,
				model: this.model,
				timestamp: startTime,
			});
		}

		// Get formatted tools
		let formattedTools: any[];
		if (this.unifiedToolManager) {
			formattedTools = await this.unifiedToolManager.getToolsForProvider('aws');
		} else {
			const rawTools = await this.mcpManager.getAllTools();
			formattedTools = this.formatToolsForBedrock(rawTools);
		}

		let iterationCount = 0;
		try {
			while (iterationCount < this.maxIterations) {
				iterationCount++;

				// Get AI response
				const response = await this.getAIResponse(formattedTools);
				const { textContent, toolCalls } = this.parseResponse(response);

				// If there are no tool calls, we're done
				if (!toolCalls || toolCalls.length === 0) {
					// Add assistant message to history
					await this.contextManager.addAssistantMessage(textContent);

					// Emit LLM response completed event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_COMPLETED, {
							sessionId,
							messageId,
							model: this.model,
							duration: Date.now() - startTime,
							timestamp: Date.now(),
							response: textContent,
						});
					}

					return textContent;
				}

				// Log thinking steps when assistant provides reasoning before tool calls
				if (textContent && textContent.trim()) {
					logger.info(`💭 ${textContent.trim()}`);

					// Emit thinking event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_THINKING, {
							sessionId,
							messageId,
							timestamp: Date.now(),
						});
					}
				}

				await this.contextManager.addAssistantMessage(textContent, toolCalls);

				// Handle tool calls for supported model families
				if (toolCalls.length > 0) {
					for (const toolCall of toolCalls) {
						logger.debug(`Tool call initiated: ${JSON.stringify(toolCall, null, 2)}`);
						logger.info(`🔧 Using tool: ${toolCall.function.name}`);

						const toolName = toolCall.function.name;
						const args = JSON.parse(toolCall.function.arguments);

						try {
							let toolResult: string;
							if (this.unifiedToolManager) {
								toolResult = await this.unifiedToolManager.executeTool(toolName, args, sessionId);
							} else {
								const toolExecutionResult = await this.mcpManager.executeTool(toolName, args);
								toolResult = toolExecutionResult.content;
							}

							const formattedResult = formatToolResult(toolName, toolResult);
							await this.contextManager.addToolResult(toolCall.id, toolName, formattedResult);
							logger.debug(`Tool result: ${formattedResult}`);
						} catch (error) {
							const errorMessage = `Tool execution failed: ${error instanceof Error ? error.message : 'Unknown error'}`;
							await this.contextManager.addToolResult(toolCall.id, toolName, errorMessage);
							logger.error(`Tool execution error: ${errorMessage}`);
						}
					}
				}
			}

			throw new Error(`Maximum iterations (${this.maxIterations}) reached without completion`);
		} catch (error) {
			logger.error('AWS Bedrock generation error:', error);
			logger.error('Error details:', {
				message: error instanceof Error ? error.message : String(error),
				stack: error instanceof Error ? error.stack : undefined,
				iterationCount,
				modelFamily: this.modelFamily,
				model: this.model,
			});
			throw error;
		}
	}

	async directGenerate(userInput: string, systemPrompt?: string): Promise<string> {
		let messages;
		if (this.modelFamily === ModelFamily.ANTHROPIC) {
			messages = await this.contextManager.getAllFormattedMessages(false);
			if (!messages || messages.length === 0) {
				messages = [
					{
						role: 'user',
						content: [{ type: 'text', text: userInput }],
					},
				];
			}
		} else {
			messages = await this.contextManager.getAllFormattedMessages();
		}

		let request: any;

		const formattedMessage = this.formatter.format(messages[0], systemPrompt)[0];
		if (this.modelFamily === ModelFamily.ANTHROPIC) {
			request = {
				messages: [formattedMessage],
				anthropic_version: 'bedrock-2023-05-31',
				max_tokens: 4096,
				temperature: 0.7,
				...(systemPrompt ? { system: systemPrompt } : {}),
			};
		} else {
			request = formattedMessage;
		}

		const commandParams: any = {
			modelId: this.model,
			contentType: 'application/json',
			accept: 'application/json',
			body: JSON.stringify(request),
		};
		if (this.inferenceProfileArn) {
			commandParams.inferenceConfig = { profileId: this.inferenceProfileArn };
		}
		const command = new InvokeModelCommand(commandParams);

		const response = (await this.client.send(command)) as any;
		const responseBody = JSON.parse(new TextDecoder().decode(response.body)) as any; // BedrockResponse type removed

		const { textContent } = this.parseResponse(responseBody);
		return textContent;
	}

	async getAllTools(): Promise<ToolSet> {
		if (this.unifiedToolManager) {
			const combinedTools: CombinedToolSet = await this.unifiedToolManager.getAllTools();
			// Convert CombinedToolSet to ToolSet format
			const toolSet: ToolSet = {};
			for (const [toolName, toolInfo] of Object.entries(combinedTools)) {
				toolSet[toolName] = {
					description: toolInfo.description,
					parameters: toolInfo.parameters,
				};
			}
			return toolSet;
		}
		return this.mcpManager.getAllTools();
	}

	getConfig(): LLMServiceConfig {
		return {
			provider: 'aws',
			model: this.model,
		};
	}

	private async getAIResponse(formattedTools: any[]): Promise<any> {
		// BedrockResponse type removed
		logger.info('Getting formatted messages from context manager');
		let messages;
		if (this.modelFamily === ModelFamily.ANTHROPIC) {
			messages = await this.contextManager.getAllFormattedMessages(false);
		} else {
			messages = await this.contextManager.getAllFormattedMessages();
		}
		logger.info(`Got ${messages.length} messages from context`);

		logger.info('Getting system prompt from context manager');
		const systemPrompt = await this.contextManager.getSystemPrompt();
		logger.info(`Got system prompt: ${systemPrompt ? 'yes' : 'no'}`);

		logger.info(`Building request for model family: ${this.modelFamily}`);
		let request: any;

		if (this.modelFamily === ModelFamily.ANTHROPIC) {
			const formattedMessages = messages
				.map((msg: any) => this.formatter.format(msg, systemPrompt))
				.flat()
				.filter((msg: any) => msg !== null && msg !== undefined);
			request = {
				messages: formattedMessages,
				anthropic_version: 'bedrock-2023-05-31',
				max_tokens: 4096,
				temperature: 0.7,
				...(systemPrompt ? { system: systemPrompt } : {}),
			};
			if (formattedTools && formattedTools.length > 0) {
				request.tools = formattedTools;
				// Use 'auto' tool choice to let the model decide when to use tools
				// This prevents over-eager tool calling for simple questions
				request.tool_choice = { type: 'auto' };
			}
		} else {
			request = this.formatter.format(messages[0], systemPrompt)[0];
		}

		logger.info('Creating InvokeModelCommand');
		const commandParams: any = {
			modelId: this.model,
			contentType: 'application/json',
			accept: 'application/json',
			body: JSON.stringify(request),
		};
		if (this.inferenceProfileArn) {
			commandParams.inferenceConfig = { profileId: this.inferenceProfileArn };
		}
		const command = new InvokeModelCommand(commandParams);

		logger.info('Sending command to Bedrock client');
		const response = (await this.client.send(command)) as any;
		logger.info('Got response from Bedrock, parsing...');

		const parsedResponse = JSON.parse(new TextDecoder().decode(response.body)) as any; // BedrockResponse type removed
		logger.info('Response parsed successfully');
		return parsedResponse;
	}

	private parseResponse(response: any): { textContent: string; toolCalls: any[] } {
		// BedrockResponse type removed
		switch (this.modelFamily) {
			case ModelFamily.ANTHROPIC:
				return this.parseAnthropicResponse(response);
			case ModelFamily.META_LLAMA:
				return this.parseLlamaResponse(response);
			case ModelFamily.AMAZON_TITAN:
				return this.parseTitanResponse(response);
			case ModelFamily.AI21_LABS:
				return this.parseAI21Response(response);
			case ModelFamily.DEEPSEEK:
				return this.parseDeepSeekResponse(response);
			default:
				// Fallback to Anthropic parsing
				return this.parseAnthropicResponse(response);
		}
	}

	private parseAnthropicResponse(response: any): { textContent: string; toolCalls: any[] } {
		// BedrockResponse type removed
		const toolUseBlocks = response.content.filter((block: any) => block.type === 'tool_use');
		const textContent = response.content
			.filter((block: any) => block.type === 'text')
			.map((block: any) => block.text)
			.join('');

		const toolCalls = toolUseBlocks.map((block: any) => ({
			id: block.id!,
			type: 'function' as const,
			function: {
				name: block.name!,
				arguments: JSON.stringify(block.input),
			},
		}));

		return { textContent, toolCalls };
	}

	private parseLlamaResponse(response: any): { textContent: string; toolCalls: any[] } {
		// BedrockResponse type removed
		return {
			textContent: response.generation,
			toolCalls: [], // Llama models don't support tool calling
		};
	}

	private parseTitanResponse(response: any): { textContent: string; toolCalls: any[] } {
		// BedrockResponse type removed
		const textContent = response.results.map((result: any) => result.outputText).join('');
		return {
			textContent,
			toolCalls: [], // Titan models don't support tool calling
		};
	}

	private parseAI21Response(response: any): { textContent: string; toolCalls: any[] } {
		// BedrockResponse type removed
		const textContent = response.choices.map((choice: any) => choice.message.content).join('');
		return {
			textContent,
			toolCalls: [], // AI21 models don't support tool calling in this implementation
		};
	}

	private parseDeepSeekResponse(response: any): { textContent: string; toolCalls: any[] } {
		// BedrockResponse type removed
		const textContent = response.choices.map((choice: any) => choice.text).join('');
		return {
			textContent,
			toolCalls: [], // DeepSeek models don't support tool calling
		};
	}

	private formatToolsForBedrock(rawTools: ToolSet): any[] {
		if (!rawTools || typeof rawTools !== 'object') return [];
		return Object.entries(rawTools).map(([toolName, tool]) => ({
			name: toolName,
			description: tool.description,
			input_schema: tool.parameters,
		}));
	}
}

import { OpenAIClient, AzureKeyCredential } from '@azure/openai';
import { ILLMService, LLMServiceConfig } from './types.js';
import { AzureConfig } from '../config.js';
import { MCPManager } from '../../../mcp/manager.js';
import { ContextManager } from '../messages/manager.js';
import { UnifiedToolManager, CombinedToolSet } from '../../tools/unified-tool-manager.js';
import { ImageData } from '../messages/types.js';
import { ToolSet } from '../../../mcp/types.js';
import { logger } from '../../../logger/index.js';
import { formatToolResult } from '../utils/tool-result-formatter.js';
import { EventManager } from '../../../events/event-manager.js';
import { SessionEvents } from '../../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

export class AzureService implements ILLMService {
	private client: OpenAIClient;
	private model: string;
	private mcpManager: MCPManager;
	private unifiedToolManager: UnifiedToolManager | undefined;
	private contextManager: ContextManager;
	private maxIterations: number;
	private deploymentName: string;
	private eventManager?: EventManager;

	constructor(
		model: string,
		mcpManager: MCPManager,
		contextManager: ContextManager,
		unifiedToolManager?: UnifiedToolManager,
		maxIterations: number = 5,
		azureConfig?: AzureConfig
	) {
		this.model = model;
		this.mcpManager = mcpManager;
		this.unifiedToolManager = unifiedToolManager;
		this.contextManager = contextManager;
		this.maxIterations = maxIterations;

		const endpoint = azureConfig?.endpoint || process.env.AZURE_OPENAI_ENDPOINT;
		const apiKey = process.env.AZURE_OPENAI_API_KEY;

		if (!endpoint) {
			throw new Error(
				'Azure OpenAI endpoint is required. Provide via config.azure.endpoint or AZURE_OPENAI_ENDPOINT environment variable'
			);
		}

		if (!apiKey) {
			throw new Error('AZURE_OPENAI_API_KEY environment variable is required');
		}

		// Use provided deployment name or fall back to model name
		this.deploymentName = azureConfig?.deploymentName || model;

		this.client = new OpenAIClient(endpoint, new AzureKeyCredential(apiKey));

		logger.info(
			`Azure OpenAI service initialized with deployment: ${this.deploymentName}, endpoint: ${endpoint}`
		);
	}

	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	async generate(userInput: string, imageData?: ImageData): Promise<string> {
		await this.contextManager.addUserMessage(userInput, imageData);

		const messageId = uuidv4();
		const startTime = Date.now();

		// Try to get sessionId from contextManager if available, otherwise undefined
		const sessionId = (this.contextManager as any)?.sessionId;

		// Emit LLM response started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
				sessionId,
				messageId,
				model: this.model,
				timestamp: startTime,
			});
		}

		// Use unified tool manager if available, otherwise fall back to MCP manager
		let formattedTools: any[];
		if (this.unifiedToolManager) {
			formattedTools = await this.unifiedToolManager.getToolsForProvider('azure');
		} else {
			const rawTools = await this.mcpManager.getAllTools();
			formattedTools = this.formatToolsForAzure(rawTools);
		}

		logger.silly(`Formatted tools: ${JSON.stringify(formattedTools, null, 2)}`);

		let iterationCount = 0;
		try {
			while (iterationCount < this.maxIterations) {
				iterationCount++;

				// Attempt to get a response, with retry logic
				const { message } = await this.getAIResponseWithRetries(formattedTools, userInput);

				// If there are no tool calls, we're done
				if (!message.tool_calls || message.tool_calls.length === 0) {
					const responseText = message.content || '';
					// Add assistant message to history
					await this.contextManager.addAssistantMessage(responseText);

					// Emit LLM response completed event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_COMPLETED, {
							sessionId,
							messageId,
							model: this.model,
							duration: Date.now() - startTime,
							timestamp: Date.now(),
							response: responseText,
						});
					}

					return responseText;
				}

				// Log thinking steps when assistant provides reasoning before tool calls
				if (message.content && message.content.trim()) {
					logger.info(`💭 ${message.content.trim()}`);

					// Emit thinking event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_THINKING, {
							sessionId,
							messageId,
							timestamp: Date.now(),
						});
					}
				}

				// Add assistant message with tool calls to history
				await this.contextManager.addAssistantMessage(message.content, message.tool_calls);

				// Handle tool calls
				for (const toolCall of message.tool_calls) {
					logger.debug(`Tool call initiated: ${JSON.stringify(toolCall, null, 2)}`);
					logger.info(`🔧 Using tool: ${toolCall.function.name}`);
					const toolName = toolCall.function.name;
					let args: any = {};

					try {
						args = JSON.parse(toolCall.function.arguments);
					} catch (e) {
						logger.error(`Error parsing arguments for ${toolName}:`, e);
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: `Failed to parse arguments: ${e}`,
						});
						continue;
					}

					// Execute tool
					try {
						let result: any;
						if (this.unifiedToolManager) {
							result = await this.unifiedToolManager.executeTool(toolName, args, sessionId);
						} else {
							result = await this.mcpManager.executeTool(toolName, args);
						}

						// Display formatted tool result
						const formattedResult = formatToolResult(toolName, result);
						logger.info(`📋 Tool Result:\n${formattedResult}`);

						// Add tool result to message manager
						await this.contextManager.addToolResult(toolCall.id, toolName, result);
					} catch (error) {
						// Handle tool execution error
						const errorMessage = error instanceof Error ? error.message : String(error);
						logger.error(`Tool execution error for ${toolName}: ${errorMessage}`);

						// Add error as tool result
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: errorMessage,
						});
					}
				}
			}

			// If we reached max iterations, return a message
			logger.warn(`Reached maximum iterations (${this.maxIterations}) for task.`);
			const finalResponse = 'Task completed but reached maximum tool call iterations.';
			await this.contextManager.addAssistantMessage(finalResponse);
			return finalResponse;
		} catch (error) {
			// Handle API errors
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(`Error in Azure OpenAI service API call: ${errorMessage}`, { error });
			await this.contextManager.addAssistantMessage(`Error processing request: ${errorMessage}`);
			return `Error processing request: ${errorMessage}`;
		}
	}

	/**
	 * Direct generate method that bypasses conversation context
	 * Used for internal tool operations that shouldn't pollute conversation history
	 * @param userInput - The input to generate a response for
	 * @param systemPrompt - Optional system prompt to use
	 * @returns Promise<string> - The generated response
	 */
	async directGenerate(userInput: string, systemPrompt?: string): Promise<string> {
		try {
			logger.debug('AzureService: Direct generate call (bypassing conversation context)', {
				inputLength: userInput.length,
				hasSystemPrompt: !!systemPrompt,
			});

			// Create a minimal message array for direct API call
			const messages: any[] = [];

			if (systemPrompt) {
				messages.push({
					role: 'system',
					content: systemPrompt,
				});
			}

			messages.push({
				role: 'user',
				content: userInput,
			});

			// Make direct API call without adding to conversation context
			const response = await this.client.getChatCompletions(this.deploymentName, messages, {
				temperature: 0.7,
				maxTokens: 4096,
				topP: 1,
				// No tools for direct calls - this is for simple text generation
			});

			const choice = response.choices[0];
			if (!choice) {
				throw new Error('No choices returned from Azure OpenAI');
			}

			const responseText = choice.message?.content || '';

			logger.debug('AzureService: Direct generate completed', {
				responseLength: responseText.length,
			});

			return responseText;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('AzureService: Direct generate failed', {
				error: errorMessage,
				inputLength: userInput.length,
			});
			throw new Error(`Direct generate failed: ${errorMessage}`);
		}
	}

	async getAllTools(): Promise<ToolSet | CombinedToolSet> {
		if (this.unifiedToolManager) {
			return await this.unifiedToolManager.getAllTools();
		}
		return this.mcpManager.getAllTools();
	}

	getConfig(): LLMServiceConfig {
		return {
			provider: 'azure',
			model: this.model,
		};
	}

	// Helper methods
	private async getAIResponseWithRetries(
		tools: any[],
		userInput: string
	): Promise<{ message: any }> {
		let attempts = 0;
		const MAX_ATTEMPTS = 3;

		// Add a log of the number of tools in response
		logger.debug(`Tools in response: ${tools.length}`);

		while (attempts < MAX_ATTEMPTS) {
			attempts++;
			try {
				// Use the new method that implements proper flow: get system prompt, compress history, format messages
				const formattedMessages = await this.contextManager.getFormattedMessage({
					role: 'user',
					content: userInput,
				});

				// Debug log: Show exactly what messages are being sent to Azure OpenAI
				logger.debug(`Sending ${formattedMessages.length} formatted messages to Azure OpenAI:`, {
					messages: formattedMessages.map((msg, idx) => ({
						index: idx,
						role: msg.role,
						hasContent: !!msg.content,
						hasToolCalls: !!msg.tool_calls,
						toolCallId: msg.toolCallId || msg.tool_call_id,
						name: msg.name,
					})),
				});

				// Call Azure OpenAI API
				const requestOptions: any = {
					temperature: 0.7,
					maxTokens: 4096,
					topP: 1,
				};

				// Add tools if available - Azure uses different property names
				if (attempts === 1 && tools.length > 0) {
					requestOptions.tools = tools;
					requestOptions.toolChoice = 'auto'; // Azure uses toolChoice instead of tool_choice
				}

				const response = await this.client.getChatCompletions(
					this.deploymentName,
					formattedMessages,
					requestOptions
				);

				logger.silly('AZURE OPENAI CHAT COMPLETION RESPONSE: ', JSON.stringify(response, null, 2));

				// Get the response message and normalize tool calls format
				const choice = response.choices[0];
				if (!choice) {
					throw new Error('Received empty message from Azure OpenAI API');
				}

				const message = choice.message as any; // Azure API has different types than expected

				// Azure OpenAI may return tool calls in different formats, normalize to OpenAI format
				// Create a normalized message object that our code expects
				const normalizedMessage = {
					...message,
					tool_calls:
						message.toolCalls ||
						message.tool_calls ||
						(message.functionCall
							? [
									{
										id: `call_${Date.now()}`,
										type: 'function' as const,
										function: {
											name: message.functionCall.name,
											arguments: message.functionCall.arguments,
										},
									},
								]
							: undefined),
				};

				return { message: normalizedMessage };
			} catch (error) {
				const apiError = error as any;
				logger.error(
					`Error in Azure OpenAI API call (Attempt ${attempts}/${MAX_ATTEMPTS}): ${apiError.message || JSON.stringify(apiError, null, 2)}`,
					{ status: apiError.status, headers: apiError.headers }
				);

				// Azure OpenAI specific error handling
				if (apiError.status === 400) {
					if (
						apiError.message?.includes('context_length_exceeded') ||
						apiError.message?.includes('maximum context length')
					) {
						logger.warn(
							`Context length exceeded in Azure OpenAI. ContextManager compression might not be sufficient. Error details: ${JSON.stringify(apiError)}`
						);
					}
					if (apiError.message?.includes('tool_call_id')) {
						logger.warn(
							`Azure OpenAI tool_call_id error. This indicates message format issues. Error details: ${JSON.stringify(apiError)}`
						);
					}
				}

				if (attempts >= MAX_ATTEMPTS) {
					logger.error(`Failed to get response from Azure OpenAI after ${MAX_ATTEMPTS} attempts.`);
					throw error;
				}

				await new Promise(resolve => setTimeout(resolve, 500 * attempts));
			}
		}

		throw new Error('Failed to get response after maximum retry attempts');
	}

	private formatToolsForAzure(tools: ToolSet): any[] {
		// Keep the existing implementation
		// Convert the ToolSet object to an array of tools in Azure OpenAI's format (same as OpenAI)
		return Object.entries(tools).map(([name, tool]) => {
			return {
				type: 'function',
				function: {
					name,
					description: tool.description,
					parameters: tool.parameters,
				},
			};
		});
	}
}

import { MCPManager } from '../../../mcp/manager.js';
import { UnifiedToolManager } from '../../tools/unified-tool-manager.js';
import { ContextManager } from '../messages/manager.js';
import { LLMConfig } from '../config.js';
import { ILLMService } from './types.js';
import { env } from '../../../env.js';
import { logger } from '../../../logger/index.js';
import { OpenAIService } from './openai.js';
import { AnthropicService } from './anthropic.js';
import { OpenRouterService } from './openrouter.js';
import { OllamaService } from './ollama.js';
import { QwenService, QwenOptions } from './qwen.js';
import { AwsService } from './aws.js';
import { AzureService } from './azure.js';
import { GeminiService } from './gemini.js';
import { LMStudioService } from './lmstudio.js';

function extractApiKey(config: LLMConfig): string {
	const provider = config.provider.toLowerCase();

	// These providers don't require traditional API keys
	if (
		provider === 'ollama' ||
		provider === 'lmstudio' ||
		provider === 'aws' ||
		provider === 'azure'
	) {
		return 'not-required';
	}

	// Get API key from config (already expanded)
	let apiKey = config.apiKey || '';

	if (!apiKey) {
		const errorMsg = `Error: API key for ${provider} not found`;
		logger.error(errorMsg);
		logger.error(`Please set your ${provider} API key in the config file or .env file`);
		throw new Error(errorMsg);
	}
	logger.debug('Verified API key');
	return apiKey;
}

function getOpenAICompatibleBaseURL(llmConfig: LLMConfig): string {
	if (llmConfig.baseURL) {
		let baseUrl = llmConfig.baseURL.replace(/\/$/, '');

		// For Ollama, ensure /v1 suffix for OpenAI-compatible endpoint
		const provider = llmConfig.provider.toLowerCase();
		if (provider === 'ollama' && !baseUrl.endsWith('/v1') && !baseUrl.endsWith('/api')) {
			baseUrl = baseUrl + '/v1';
		}

		return baseUrl;
	}

	// Provider-specific defaults and environment fallbacks
	const provider = llmConfig.provider.toLowerCase();

	if (provider === 'openrouter') {
		return 'https://openrouter.ai/api/v1';
	}

	if (provider === 'ollama') {
		// Use environment variable if set, otherwise default to localhost:11434/v1
		let baseUrl = env.OLLAMA_BASE_URL || 'http://localhost:11434/v1';

		// Ensure /v1 suffix for OpenAI-compatible endpoint
		if (!baseUrl.endsWith('/v1') && !baseUrl.endsWith('/api')) {
			baseUrl = baseUrl.replace(/\/$/, '') + '/v1';
		}

		return baseUrl;
	}

	if (provider === 'lmstudio') {
		// Use environment variable if set, otherwise default to localhost:1234/v1
		return env.LMSTUDIO_BASE_URL || 'http://localhost:1234/v1';
	}

	// Check for environment variable as fallback for OpenAI
	if (provider === 'openai' && env.OPENAI_BASE_URL) {
		return env.OPENAI_BASE_URL.replace(/\/$/, '');
	}

	return '';
}

function _createLLMService(
	config: LLMConfig,
	mcpManager: MCPManager,
	contextManager: ContextManager,
	unifiedToolManager?: UnifiedToolManager
): ILLMService {
	// Extract and validate API key
	const apiKey = extractApiKey(config);

	switch (config.provider.toLowerCase()) {
		case 'openai': {
			const baseURL = getOpenAICompatibleBaseURL(config);
			// Use require for OpenAI SDK for compatibility
			// @ts-ignore

			const OpenAIClass = require('openai');
			const openai = new OpenAIClass({ apiKey, ...(baseURL ? { baseURL } : {}) });
			return new OpenAIService(
				openai,
				config.model,
				mcpManager,
				contextManager,
				config.maxIterations,
				unifiedToolManager
			);
		}
		case 'openrouter': {
			const baseURL = getOpenAICompatibleBaseURL(config);
			// Use require for OpenAI SDK for compatibility
			// @ts-ignore

			const OpenAIClass = require('openai');
			const openai = new OpenAIClass({
				apiKey,
				baseURL,
				defaultHeaders: {
					'HTTP-Referer': 'https://github.com/byterover/cipher',
					'X-Title': 'Cipher Memory Agent',
				},
			});
			return new OpenRouterService(
				openai,
				config.model,
				mcpManager,
				contextManager,
				config.maxIterations,
				unifiedToolManager
			);
		}
		case 'lmstudio': {
			const baseURL = getOpenAICompatibleBaseURL(config);
			// Use require for OpenAI SDK for compatibility
			// @ts-ignore

			const OpenAIClass = require('openai');
			const openai = new OpenAIClass({
				apiKey: 'lm-studio', // LM Studio uses "lm-studio" as the API key
				baseURL,
			});
			return new LMStudioService(
				openai,
				config.model,
				mcpManager,
				contextManager,
				config.maxIterations,
				unifiedToolManager
			);
		}
		case 'anthropic': {
			// Use require for Anthropic SDK for compatibility
			// @ts-ignore

			const AnthropicClass = require('@anthropic-ai/sdk');
			const anthropic = new AnthropicClass({ apiKey });
			return new AnthropicService(
				anthropic,
				config.model,
				mcpManager,
				contextManager,
				config.maxIterations,
				unifiedToolManager
			);
		}
		case 'ollama': {
			const baseURL = getOpenAICompatibleBaseURL(config);
			// Use require for OpenAI SDK for compatibility
			// @ts-ignore

			const OpenAIClass = require('openai');
			// Ollama uses OpenAI-compatible API but runs locally
			const openai = new OpenAIClass({
				apiKey: 'not-required', // Ollama doesn't require an API key
				baseURL,
			});
			return new OllamaService(
				openai,
				config.model,
				mcpManager,
				contextManager,
				config.maxIterations,
				unifiedToolManager
			);
		}
		case 'aws': {
			return new AwsService(
				config.model,
				mcpManager,
				contextManager,
				unifiedToolManager,
				config.maxIterations,
				config.aws
			);
		}
		case 'azure': {
			return new AzureService(
				config.model,
				mcpManager,
				contextManager,
				unifiedToolManager,
				config.maxIterations,
				config.azure
			);
		}
		case 'qwen': {
			// QwenService: OpenAI-compatible endpoint for Alibaba Cloud Qwen
			// Accepts Qwen-specific options via config.qwenOptions
			// Default endpoint: https://dashscope-intl.aliyuncs.com/compatible-mode/v1
			const baseURL = config.baseURL || 'https://dashscope-intl.aliyuncs.com/compatible-mode/v1';
			// Use require for OpenAI SDK for compatibility
			// @ts-ignore

			const OpenAIClass = require('openai');
			const openai = new OpenAIClass({ apiKey, baseURL });
			const qwenOptions: QwenOptions = {
				...(config.qwenOptions?.enableThinking !== undefined && {
					enableThinking: config.qwenOptions.enableThinking,
				}),
				...(config.qwenOptions?.thinkingBudget !== undefined && {
					thinkingBudget: config.qwenOptions.thinkingBudget,
				}),
				...(config.qwenOptions?.temperature !== undefined && {
					temperature: config.qwenOptions.temperature,
				}),
				...(config.qwenOptions?.top_p !== undefined && { top_p: config.qwenOptions.top_p }),
			};
			return new QwenService(
				openai,
				config.model,
				mcpManager,
				contextManager,
				config.maxIterations,
				qwenOptions,
				unifiedToolManager
			);
		}
		case 'gemini': {
			logger.debug('Creating Gemini service', { model: config.model, hasApiKey: !!apiKey });
			try {
				return new GeminiService(
					apiKey,
					config.model,
					mcpManager,
					contextManager,
					config.maxIterations,
					unifiedToolManager
				);
			} catch (error) {
				logger.error('Failed to create Gemini service', {
					error: error instanceof Error ? error.message : String(error),
					model: config.model,
				});
				throw error;
			}
		}
		default:
			throw new Error(`Unsupported LLM provider: ${config.provider}`);
	}
}

export function createLLMService(
	config: LLMConfig,
	mcpManager: MCPManager,
	contextManager: ContextManager,
	unifiedToolManager?: UnifiedToolManager,
	eventManager?: any
): ILLMService {
	const service = _createLLMService(config, mcpManager, contextManager, unifiedToolManager);

	// Set event manager if provided
	if (eventManager && typeof (service as any).setEventManager === 'function') {
		(service as any).setEventManager(eventManager);
	}

	// Configure token-aware compression for the context manager
	configureCompressionForService(config, contextManager);

	return service;
}

/**
 * Configure compression settings for the context manager based on LLM config
 */
async function configureCompressionForService(
	config: LLMConfig,
	contextManager: ContextManager
): Promise<void> {
	try {
		// Extract provider and model info
		const provider = config.provider.toLowerCase();
		const model = config.model;

		// Get context window size from defaults since it's not in config
		const contextWindow = getDefaultContextWindow(provider, model);

		// Configure compression asynchronously to avoid blocking service creation
		setImmediate(async () => {
			try {
				await contextManager.configureCompression(provider, model, contextWindow);
				logger.debug('Token-aware compression configured for LLM service', {
					provider,
					model,
					contextWindow,
				});
			} catch (error) {
				logger.warn('Failed to configure compression for LLM service', {
					error: (error as Error).message,
					provider,
					model,
				});
			}
		});
	} catch (error) {
		logger.error('Error in compression configuration', { error });
	}
}

/**
 * Get default context window size for provider/model combinations
 */
function getDefaultContextWindow(provider: string, model?: string): number {
	const defaults: Record<string, Record<string, number>> = {
		openai: {
			'gpt-3.5-turbo': 16385,
			'gpt-4': 8192,
			'gpt-4-32k': 32768,
			'gpt-4-turbo': 128000,
			'gpt-4o': 128000,
			'gpt-4o-mini': 128000,
			'o1-preview': 128000,
			'o1-mini': 128000,
			default: 8192,
		},
		anthropic: {
			'claude-3-opus': 200000,
			'claude-3-sonnet': 200000,
			'claude-3-haiku': 200000,
			'claude-3-5-sonnet': 200000,
			'claude-2.1': 200000,
			'claude-2.0': 100000,
			'claude-instant-1.2': 100000,
			default: 200000,
		},
		gemini: {
			'gemini-pro': 32760,
			'gemini-pro-vision': 16384,
			'gemini-ultra': 32760,
			'gemini-1.5-pro': 1000000,
			'gemini-1.5-flash': 1000000,
			'gemini-1.5-pro-latest': 2000000,
			'gemini-1.5-flash-latest': 1000000,
			'gemini-2.0-flash': 1000000,
			'gemini-2.0-flash-exp': 1000000,
			'gemini-2.5-pro': 2000000,
			'gemini-2.5-flash': 1000000,
			'gemini-2.5-flash-lite': 1000000,
			default: 1000000,
		},
		ollama: {
			default: 8192, // Conservative default for local models
		},
		openrouter: {
			default: 8192, // Varies by model, conservative default
		},
	};

	const providerDefaults = defaults[provider];
	if (!providerDefaults) {
		return 8192; // Global fallback
	}

	return providerDefaults[model || 'default'] || providerDefaults.default || 8192;
}

import { GoogleGenerativeAI, GenerativeModel } from '@google/generative-ai';
import { ILLMService } from './types.js';
import { ImageData } from '../messages/types.js';
import { MCPManager } from '../../../mcp/manager.js';
import { UnifiedToolManager } from '../../tools/unified-tool-manager.js';
import { ContextManager } from '../messages/manager.js';
import { logger } from '../../../logger/index.js';
import { formatToolResult } from '../utils/tool-result-formatter.js';
import { EventManager } from '../../../events/event-manager.js';
import { SessionEvents } from '../../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

export class GeminiService implements ILLMService {
	private genAI: GoogleGenerativeAI;
	private model: GenerativeModel;
	private modelName: string;
	private mcpManager: MCPManager;
	private contextManager: ContextManager;
	private maxIterations: number;
	private unifiedToolManager: UnifiedToolManager | null = null;
	private eventManager?: EventManager;

	constructor(
		apiKey: string,
		modelName: string,
		mcpManager: MCPManager,
		contextManager: ContextManager,
		maxIterations: number = 50,
		unifiedToolManager?: UnifiedToolManager
	) {
		try {
			this.genAI = new GoogleGenerativeAI(apiKey);
			this.modelName = modelName;
			this.mcpManager = mcpManager;
			this.contextManager = contextManager;
			this.maxIterations = maxIterations;
			this.unifiedToolManager = unifiedToolManager || null;

			// Initialize the model
			this.model = this.genAI.getGenerativeModel({ model: modelName });

			logger.debug('Gemini service initialized successfully', {
				model: modelName,
				hasUnifiedToolManager: !!unifiedToolManager,
			});
		} catch (error) {
			logger.error('Failed to initialize Gemini service', {
				error: error instanceof Error ? error.message : String(error),
				model: modelName,
			});
			throw error;
		}
	}

	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	async generate(userInput: string, imageData?: ImageData, _stream?: boolean): Promise<string> {
		await this.contextManager.addUserMessage(userInput, imageData);

		const messageId = uuidv4();
		const startTime = Date.now();

		// Try to get sessionId from contextManager if available, otherwise undefined
		const sessionId = (this.contextManager as any)?.sessionId;

		// Emit LLM response started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
				sessionId,
				messageId,
				model: this.modelName,
				timestamp: startTime,
			});
		}

		// Use unified tool manager if available, otherwise fall back to MCP manager
		let formattedTools: any[];
		if (this.unifiedToolManager) {
			formattedTools = await this.unifiedToolManager.getToolsForProvider('gemini');
		} else {
			const rawTools = await this.mcpManager.getAllTools();
			formattedTools = this.formatToolsForGemini(rawTools);
		}

		logger.silly(`Formatted tools for Gemini: ${JSON.stringify(formattedTools, null, 2)}`);

		let iterationCount = 0;
		let toolsUsedInThisConversation = false;

		try {
			while (iterationCount < this.maxIterations) {
				iterationCount++;

				// Check if tools have already been used in this conversation
				const conversationHistory = await this.contextManager.getAllFormattedMessages();
				const hasToolCallsInHistory = conversationHistory.some(
					msg => msg.tool_calls && msg.tool_calls.length > 0
				);

				if (hasToolCallsInHistory) {
					toolsUsedInThisConversation = true;
				}

				// Attempt to get a response, with retry logic
				const { message } = await this.getAIResponseWithRetries(
					formattedTools,
					userInput,
					toolsUsedInThisConversation
				);

				// If there are no tool calls, we're done
				if (!message.tool_calls || message.tool_calls.length === 0) {
					const responseText = message.content || '';
					// Add assistant message to history
					await this.contextManager.addAssistantMessage(responseText);

					// Emit LLM response completed event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_COMPLETED, {
							sessionId,
							messageId,
							model: this.modelName,
							duration: Date.now() - startTime,
							timestamp: Date.now(),
							response: responseText,
						});
					}

					return responseText;
				}

				// Log thinking steps when assistant provides reasoning before tool calls
				if (message.content && message.content.trim()) {
					logger.info(`💭 ${message.content.trim()}`);

					// Emit thinking event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_THINKING, {
							sessionId,
							messageId,
							timestamp: Date.now(),
						});
					}
				}

				// Add assistant message with tool calls to history
				await this.contextManager.addAssistantMessage(message.content, message.tool_calls);

				// Handle tool calls
				for (const toolCall of message.tool_calls) {
					logger.debug(`Gemini tool call initiated: ${JSON.stringify(toolCall, null, 2)}`);
					logger.info(`🔧 Using tool: ${toolCall.function.name}`);
					const toolName = toolCall.function.name;
					let args: any = {};

					try {
						args = JSON.parse(toolCall.function.arguments);
					} catch (e) {
						logger.error(`Error parsing arguments for ${toolName}:`, e);
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: `Failed to parse arguments: ${e}`,
						});
						continue;
					}

					// Execute tool
					try {
						let result: any;
						if (this.unifiedToolManager) {
							result = await this.unifiedToolManager.executeTool(toolName, args, sessionId);
						} else {
							result = await this.mcpManager.executeTool(toolName, args);
						}

						// Display formatted tool result
						const formattedResult = formatToolResult(toolName, result);
						logger.info(`📋 Tool Result:\n${formattedResult}`);

						// Add tool result to message manager
						await this.contextManager.addToolResult(toolCall.id, toolName, result);

						// Mark that tools have been used
						toolsUsedInThisConversation = true;
					} catch (error) {
						// Handle tool execution error
						const errorMessage = error instanceof Error ? error.message : String(error);
						logger.error(`Tool execution error for ${toolName}: ${errorMessage}`);

						// Add error as tool result
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: errorMessage,
						});
					}
				}
			}

			// If we reached max iterations, return a message
			logger.warn(`Reached maximum iterations (${this.maxIterations}) for task.`);
			const finalResponse = 'Task completed but reached maximum tool call iterations.';
			await this.contextManager.addAssistantMessage(finalResponse);
			return finalResponse;
		} catch (error) {
			// Handle API errors
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(`Error in Gemini service API call: ${errorMessage}`, { error });
			await this.contextManager.addAssistantMessage(`Error processing request: ${errorMessage}`);
			return `Error processing request: ${errorMessage}`;
		}
	}

	async directGenerate(prompt: string): Promise<string> {
		try {
			logger.debug('Gemini service direct generation', {
				model: this.modelName,
				promptLength: prompt.length,
			});

			const result = await this.model.generateContent(prompt);
			const response = result.response.text();

			logger.debug('Gemini service direct response generated', {
				responseLength: response.length,
			});

			return response;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('Error in Gemini service direct generation', {
				error: errorMessage,
				model: this.modelName,
			});
			throw new Error(`Gemini direct generation failed: ${errorMessage}`);
		}
	}

	async getAllTools(): Promise<Record<string, any>> {
		const mcpTools = await this.mcpManager.getAllTools();
		const internalTools = this.unifiedToolManager
			? await this.unifiedToolManager.getAllTools()
			: {};

		return {
			...mcpTools,
			...internalTools,
		};
	}

	getConfig(): { provider: string; model: string } {
		return {
			provider: 'gemini',
			model: this.modelName,
		};
	}

	// Helper methods
	private async getAIResponseWithRetries(
		tools: any[],
		userInput: string,
		toolsUsedInHistory: boolean
	): Promise<{ message: any }> {
		let attempts = 0;
		const MAX_ATTEMPTS = 3;

		// Add a log of the number of tools in response
		logger.debug(`Tools in Gemini response: ${tools.length}`);

		while (attempts < MAX_ATTEMPTS) {
			attempts++;
			try {
				// Use the new method that implements proper flow: get system prompt, compress history, format messages
				const formattedMessages = await this.contextManager.getFormattedMessage({
					role: 'user',
					content: userInput,
				});

				// Debug log: Show exactly what messages are being sent to Gemini
				logger.debug(`Sending ${formattedMessages.length} formatted messages to Gemini:`, {
					messages: formattedMessages.map((msg, idx) => ({
						index: idx,
						role: msg.role,
						hasContent: !!msg.content,
						hasToolCalls: !!msg.tool_calls,
						toolCallId: msg.tool_call_id,
						name: msg.name,
					})),
				});

				// Convert messages to Gemini format and create prompt
				const prompt = this.convertMessagesToPrompt(formattedMessages);

				// Add tool information to the prompt if tools are available and haven't been used yet
				let finalPrompt = prompt;
				if (attempts === 1 && tools.length > 0 && !toolsUsedInHistory) {
					finalPrompt = this.addToolsToPrompt(prompt, tools);
				} else if (toolsUsedInHistory) {
					// If tools have already been used, add instruction to provide final response
					finalPrompt = `${prompt}

IMPORTANT: Tools have already been used in this conversation. Please provide a final response based on the tool results that are already available. Do NOT make any additional tool calls.

CONVERSATION STYLE:
While you are primarily a programming assistant, you can engage in general conversation topics when appropriate. You don't need to restrict yourself to only programming discussions. Feel free to discuss various topics including sports, general knowledge, and other subjects when the user asks about them.`;
				}

				// Call Gemini API
				const result = await this.model.generateContent(finalPrompt);
				const response = result.response;
				const rawText = response.text();

				// Parse the response to extract tool calls
				const parsedResponse = this.parseGeminiResponse(rawText);

				logger.silly('GEMINI GENERATE CONTENT RESPONSE: ', JSON.stringify(parsedResponse, null, 2));

				// Get the response message
				const message = parsedResponse;
				if (!message) {
					throw new Error('Received empty message from Gemini API');
				}

				return { message };
			} catch (error) {
				const errorMessage = error instanceof Error ? error.message : String(error);
				logger.error(`Gemini API call attempt ${attempts} failed: ${errorMessage}`, { error });

				if (attempts === MAX_ATTEMPTS) {
					throw new Error(`Gemini API call failed after ${MAX_ATTEMPTS} attempts: ${errorMessage}`);
				}

				// Wait before retrying
				await new Promise(resolve => setTimeout(resolve, 1000 * attempts));
			}
		}

		throw new Error('Gemini API call failed after all retry attempts');
	}

	private convertMessagesToPrompt(messages: any[]): string {
		logger.debug('convertMessagesToPrompt called with:', {
			messagesType: typeof messages,
			isArray: Array.isArray(messages),
			length: messages?.length,
			messages: messages,
		});

		if (!Array.isArray(messages) || messages.length === 0) {
			logger.debug('convertMessagesToPrompt returning empty string - no valid messages');
			return '';
		}

		const result = messages
			.filter(msg => msg && (msg.content || msg.role)) // Filter out invalid messages
			.map(msg => {
				// Handle different content formats
				let content = '';
				if (typeof msg.content === 'string') {
					content = msg.content;
				} else if (typeof msg.content === 'object' && msg.content !== null) {
					content = JSON.stringify(msg.content);
				} else if (typeof msg === 'string') {
					// Handle case where the message itself is a string
					return msg;
				} else {
					content = String(msg.content || '');
				}

				// Format based on role
				if (msg.role === 'system') {
					return `System: ${content}`;
				} else if (msg.role === 'user') {
					return `User: ${content}`;
				} else if (msg.role === 'assistant') {
					return `Assistant: ${content}`;
				} else {
					// Default formatting
					return content;
				}
			})
			.filter(line => line.trim().length > 0) // Remove empty lines
			.join('\n\n');

		logger.debug('convertMessagesToPrompt result:', {
			resultType: typeof result,
			resultLength: result?.length || 0,
			result: result,
		});

		// Ensure we always return a string
		return result || '';
	}

	private addToolsToPrompt(prompt: string, tools: any[]): string {
		const toolDescriptions = tools
			.map(tool => {
				const func = tool.function;
				const params = func.parameters ? JSON.stringify(func.parameters, null, 2) : '{}';
				return `Tool: ${func.name}
Description: ${func.description}
Parameters: ${params}`;
			})
			.join('\n\n');

		return `${prompt}

IMPORTANT: You have access to the following tools. If the user's request requires using any of these tools, you MUST respond with a tool call in the exact format shown below.

Available tools:
${toolDescriptions}

TOOL CALLING FORMAT:
When you need to use a tool, respond with ONLY the tool call in this exact format:

\`\`\`tool_code
{
  "tool": "tool_name",
  "arguments": {
    "param1": "value1",
    "param2": "value2"
  }
}
\`\`\`

CRITICAL RULES:
1. If the user asks to search for information, use the appropriate search tool ONCE
2. If the user asks to store or save information, use the appropriate storage tool ONCE
3. After using a tool, provide a final response based on the tool results - DO NOT make additional tool calls
4. Only respond with a tool call if you need to use a tool
5. If you don't need to use any tools, provide a direct response
6. NEVER include both a tool call and regular text in the same response
7. NEVER make multiple tool calls for the same request - one tool call maximum per user request

CONVERSATION STYLE:
While you are primarily a programming assistant, you can engage in general conversation topics when appropriate. You don't need to restrict yourself to only programming discussions. Feel free to discuss various topics including sports, general knowledge, and other subjects when the user asks about them.

For the current request, determine if you need to use any tools and respond accordingly. If you've already used a tool in a previous response, provide a final answer based on those results.`;
	}

	private parseGeminiResponse(text: string): any {
		// Look for tool calls in the response first
		const toolCallPattern = /```tool_code\s*\n?([^`]*)\n?```/gi;
		const toolCalls: any[] = [];
		let match;

		while ((match = toolCallPattern.exec(text)) !== null) {
			try {
				if (match[1]) {
					const toolCallData = JSON.parse(match[1].trim());
					toolCalls.push({
						id: `gemini_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
						type: 'function',
						function: {
							name: toolCallData.tool,
							arguments: JSON.stringify(toolCallData.arguments || {}),
						},
					});
				}
			} catch (e) {
				logger.warn('Failed to parse tool call from Gemini response', {
					toolCallText: match[1],
					error: e instanceof Error ? e.message : String(e),
				});
			}
		}

		// Extract text content (everything except tool calls)
		let textContent = '';
		if (toolCalls.length > 0) {
			// If we found tool calls, extract text before the first tool call
			const firstToolCallIndex = text.search(/```tool_code/);
			if (firstToolCallIndex > 0) {
				textContent = text.substring(0, firstToolCallIndex).trim();
			}
		} else {
			// No tool calls found, use the cleaned text
			textContent = this.cleanToolMetadata(text);
		}

		// CRITICAL FIX: If there's significant text content AND tool calls,
		// prioritize the text content and ignore tool calls to prevent redundant calls
		if (textContent.trim().length > 20 && toolCalls.length > 0) {
			logger.debug(
				'Gemini response contains both text and tool calls - prioritizing text to prevent redundant calls',
				{
					textContentLength: textContent.length,
					toolCallCount: toolCalls.length,
					textPreview: textContent.substring(0, 100),
				}
			);

			// Return only the text content, no tool calls
			return {
				content: textContent,
				tool_calls: undefined,
			};
		}

		// Log what we found
		logger.debug('Parsed Gemini response:', {
			hasToolCalls: toolCalls.length > 0,
			toolCallCount: toolCalls.length,
			textContentLength: textContent.length,
			toolCalls: toolCalls.map(tc => tc.function.name),
		});

		return {
			content: textContent,
			tool_calls: toolCalls.length > 0 ? toolCalls : undefined,
		};
	}

	/**
	 * Clean tool-related metadata from Gemini responses
	 * Removes code blocks containing tool instructions that shouldn't be shown to users
	 */
	private cleanToolMetadata(text: string): string {
		if (!text) return text;

		// Remove all tool_code blocks regardless of content
		// These are metadata that shouldn't be shown to users
		const toolCodePattern = /```tool_code\s*\n?[^`]*\n?```\s*/gi;
		let cleaned = text.replace(toolCodePattern, '');

		// Remove any standalone tool instruction comments
		const toolCommentPattern = /^\s*#\s*(No tools needed|Tool:|Query:).*$/gm;
		cleaned = cleaned.replace(toolCommentPattern, '');

		// Remove empty lines that might be left after cleaning
		cleaned = cleaned.replace(/\n\s*\n\s*\n/g, '\n\n');

		// Trim leading/trailing whitespace
		cleaned = cleaned.trim();

		return cleaned;
	}

	private formatToolsForGemini(tools: Record<string, any>): any[] {
		// Convert the ToolSet object to an array of tools in Gemini's format
		return Object.entries(tools).map(([name, tool]) => {
			return {
				type: 'function',
				function: {
					name,
					description: tool.description,
					parameters: tool.parameters,
				},
			};
		});
	}
}

export * from './types.js';
export * from './openrouter.js';
export * from './ollama.js';
export * from './lmstudio.js';
export * from './aws.js';
export * from './azure.js';

import { ToolSet } from '../../../mcp/types.js';
import { MCPManager } from '../../../mcp/manager.js';
import { UnifiedToolManager, CombinedToolSet } from '../../tools/unified-tool-manager.js';
import { ContextManager } from '../messages/manager.js';
import { ImageData } from '../messages/types.js';
import { ILLMService, LLMServiceConfig } from './types.js';
import OpenAI from 'openai';
import { logger } from '../../../logger/index.js';
import { formatToolResult } from '../utils/tool-result-formatter.js';
import { EventManager } from '../../../events/event-manager.js';
import { SessionEvents } from '../../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

export class LMStudioService implements ILLMService {
	private openai: OpenAI;
	private model: string;
	private mcpManager: MCPManager;
	private unifiedToolManager: UnifiedToolManager | undefined;
	private contextManager: ContextManager;
	private maxIterations: number;
	private eventManager?: EventManager;

	constructor(
		openai: OpenAI,
		model: string,
		mcpManager: MCPManager,
		contextManager: ContextManager,
		maxIterations: number = 5,
		unifiedToolManager?: UnifiedToolManager
	) {
		this.openai = openai;
		this.model = model;
		this.mcpManager = mcpManager;
		this.contextManager = contextManager;
		this.maxIterations = maxIterations;
		this.unifiedToolManager = unifiedToolManager;
	}

	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	async generate(userInput: string, imageData?: ImageData): Promise<string> {
		await this.contextManager.addUserMessage(userInput, imageData);

		const messageId = uuidv4();
		const startTime = Date.now();

		// Try to get sessionId from contextManager if available, otherwise undefined
		const sessionId = (this.contextManager as any)?.sessionId;

		// Emit LLM response started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
				sessionId,
				messageId,
				model: this.model,
				timestamp: startTime,
			});
		}

		// Use unified tool manager if available, otherwise fall back to MCP manager
		let formattedTools: any[];
		if (this.unifiedToolManager) {
			formattedTools = await this.unifiedToolManager.getToolsForProvider('openai');
		} else {
			const rawTools = await this.mcpManager.getAllTools();
			formattedTools = this.formatToolsForLMStudio(rawTools);
		}

		logger.silly(`Formatted tools for LM Studio: ${JSON.stringify(formattedTools, null, 2)}`);

		let iterationCount = 0;
		try {
			while (iterationCount < this.maxIterations) {
				iterationCount++;

				// Attempt to get a response, with retry logic
				const { message } = await this.getAIResponseWithRetries(formattedTools, userInput);

				// If there are no tool calls, we're done
				if (!message.tool_calls || message.tool_calls.length === 0) {
					const responseText = message.content || '';
					// Add assistant message to history
					await this.contextManager.addAssistantMessage(responseText);

					// Emit LLM response completed event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_COMPLETED, {
							sessionId,
							messageId,
							model: this.model,
							duration: Date.now() - startTime,
							timestamp: Date.now(),
							response: responseText,
						});
					}

					return responseText;
				}

				// Log thinking steps when assistant provides reasoning before tool calls
				if (message.content && message.content.trim()) {
					logger.info(`💭 ${message.content.trim()}`);

					// Emit thinking event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_THINKING, {
							sessionId,
							messageId,
							timestamp: Date.now(),
						});
					}
				}

				// Add assistant message with tool calls to history
				await this.contextManager.addAssistantMessage(message.content, message.tool_calls);

				// Handle tool calls
				for (const toolCall of message.tool_calls) {
					logger.debug(`LM Studio tool call initiated: ${JSON.stringify(toolCall, null, 2)}`);
					logger.info(`🔧 Using tool: ${toolCall.function.name}`);
					const toolName = toolCall.function.name;
					let args: any = {};

					try {
						args = JSON.parse(toolCall.function.arguments);
					} catch (e) {
						logger.error(`Error parsing arguments for ${toolName}:`, e);
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: `Failed to parse arguments: ${e}`,
						});
						continue;
					}

					// Execute tool
					try {
						let result: any;
						if (this.unifiedToolManager) {
							result = await this.unifiedToolManager.executeTool(toolName, args, sessionId);
						} else {
							result = await this.mcpManager.executeTool(toolName, args);
						}

						// Display formatted tool result
						const formattedResult = formatToolResult(toolName, result);
						logger.info(`📋 Tool Result:\n${formattedResult}`);

						// Add tool result to message manager
						await this.contextManager.addToolResult(toolCall.id, toolName, result);
					} catch (error) {
						// Handle tool execution error
						const errorMessage = error instanceof Error ? error.message : String(error);
						logger.error(`Tool execution error for ${toolName}: ${errorMessage}`);

						// Add error as tool result
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: errorMessage,
						});
					}
				}
			}

			// If we reached max iterations, return a message
			logger.warn(`Reached maximum iterations (${this.maxIterations}) for task.`);
			const finalResponse = 'Task completed but reached maximum tool call iterations.';
			await this.contextManager.addAssistantMessage(finalResponse);
			return finalResponse;
		} catch (error) {
			// Handle API errors
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(`Error in LM Studio service API call: ${errorMessage}`, { error });
			await this.contextManager.addAssistantMessage(`Error processing request: ${errorMessage}`);
			return `Error processing request: ${errorMessage}`;
		}
	}

	/**
	 * Direct generate method that bypasses conversation context
	 * Used for internal tool operations that shouldn't pollute conversation history
	 * @param userInput - The input to generate a response for
	 * @param systemPrompt - Optional system prompt to use
	 * @returns Promise<string> - The generated response
	 */
	async directGenerate(userInput: string, systemPrompt?: string): Promise<string> {
		try {
			logger.debug('LMStudioService: Direct generate call (bypassing conversation context)', {
				inputLength: userInput.length,
				hasSystemPrompt: !!systemPrompt,
			});

			// Create a minimal message array for direct API call
			const messages: any[] = [];

			if (systemPrompt) {
				messages.push({
					role: 'system',
					content: systemPrompt,
				});
			}

			messages.push({
				role: 'user',
				content: userInput,
			});

			// Make direct API call without adding to conversation context
			const response = await this.openai.chat.completions.create({
				model: this.model,
				messages: messages,
				// No tools for direct calls - this is for simple text generation
			});

			const responseText = response.choices[0]?.message?.content || '';

			logger.debug('LMStudioService: Direct generate completed', {
				responseLength: responseText.length,
			});

			return responseText;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('LMStudioService: Direct generate failed', {
				error: errorMessage,
				inputLength: userInput.length,
			});
			throw new Error(`Direct generate failed: ${errorMessage}`);
		}
	}

	async getAllTools(): Promise<ToolSet | CombinedToolSet> {
		if (this.unifiedToolManager) {
			return await this.unifiedToolManager.getAllTools();
		}
		return this.mcpManager.getAllTools();
	}

	getConfig(): LLMServiceConfig {
		return {
			provider: 'lmstudio',
			model: this.model,
		};
	}

	// Helper methods
	private async getAIResponseWithRetries(
		tools: any[],
		userInput: string
	): Promise<{ message: any }> {
		let attempts = 0;
		const MAX_ATTEMPTS = 3;

		// Add a log of the number of tools in response
		logger.debug(`Tools in LM Studio response: ${tools.length}`);

		while (attempts < MAX_ATTEMPTS) {
			attempts++;
			try {
				// Use the new method that implements proper flow: get system prompt, compress history, format messages
				const formattedMessages = await this.contextManager.getFormattedMessage({
					role: 'user',
					content: userInput,
				});

				// Call LM Studio API via OpenAI SDK (LM Studio is OpenAI-compatible)
				const response = await this.openai.chat.completions.create({
					model: this.model,
					messages: formattedMessages,
					tools: attempts === 1 ? tools : [], // Only offer tools on first attempt
					tool_choice: attempts === 1 ? 'auto' : 'none', // Disable tool choice on retry
				});

				logger.silly('LM STUDIO CHAT COMPLETION RESPONSE: ', JSON.stringify(response, null, 2));

				// Get the response message
				const message = response.choices[0]?.message;
				if (!message) {
					throw new Error('Received empty message from LM Studio API');
				}

				return { message };
			} catch (error) {
				const apiError = error as any;
				logger.error(
					`Error in LM Studio API call (Attempt ${attempts}/${MAX_ATTEMPTS}): ${apiError.message || JSON.stringify(apiError, null, 2)}`,
					{ status: apiError.status, headers: apiError.headers }
				);

				// LM Studio-specific error handling
				if (apiError.status === 400) {
					logger.warn(
						`LM Studio API error - check if model '${this.model}' is loaded. Error details: ${JSON.stringify(apiError.error)}`
					);
				}

				// Connection errors might indicate LM Studio is not running
				if (apiError.code === 'ECONNREFUSED' || apiError.code === 'ENOTFOUND') {
					logger.error(
						'Failed to connect to LM Studio server. Please ensure LM Studio is running and accessible.'
					);
				}

				if (attempts >= MAX_ATTEMPTS) {
					logger.error(`Failed to get response from LM Studio after ${MAX_ATTEMPTS} attempts.`);
					throw error;
				}

				await new Promise(resolve => setTimeout(resolve, 500 * attempts));
			}
		}

		throw new Error('Failed to get response after maximum retry attempts');
	}

	private formatToolsForLMStudio(tools: ToolSet): any[] {
		// LM Studio uses the same format as OpenAI for tools
		// Convert the ToolSet object to an array of tools in OpenAI's format
		return Object.entries(tools).map(([name, tool]) => {
			return {
				type: 'function',
				function: {
					name,
					description: tool.description,
					parameters: tool.parameters,
				},
			};
		});
	}
}

import { ToolSet } from '../../../mcp/types.js';
import { MCPManager } from '../../../mcp/manager.js';
import { UnifiedToolManager, CombinedToolSet } from '../../tools/unified-tool-manager.js';
import { ContextManager } from '../messages/manager.js';
import { ImageData } from '../messages/types.js';
import { ILLMService, LLMServiceConfig } from './types.js';
import OpenAI from 'openai';
import { logger } from '../../../logger/index.js';
import { formatToolResult } from '../utils/tool-result-formatter.js';
import { EventManager } from '../../../events/event-manager.js';
import { SessionEvents } from '../../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

export class OllamaService implements ILLMService {
	private openai: OpenAI;
	private model: string;
	private mcpManager: MCPManager;
	private unifiedToolManager: UnifiedToolManager | undefined;
	private contextManager: ContextManager;
	private maxIterations: number;
	private eventManager?: EventManager;

	constructor(
		openai: OpenAI,
		model: string,
		mcpManager: MCPManager,
		contextManager: ContextManager,
		maxIterations: number = 5,
		unifiedToolManager?: UnifiedToolManager
	) {
		this.openai = openai;
		this.model = model;
		this.mcpManager = mcpManager;
		this.unifiedToolManager = unifiedToolManager;
		this.contextManager = contextManager;
		this.maxIterations = maxIterations;
	}

	/**
	 * Set the event manager for emitting LLM response events
	 */
	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	async generate(userInput: string, imageData?: ImageData): Promise<string> {
		await this.contextManager.addUserMessage(userInput, imageData);

		const messageId = uuidv4();
		const startTime = Date.now();

		// Try to get sessionId from contextManager if available, otherwise undefined
		const sessionId = (this.contextManager as any)?.sessionId;

		// Emit LLM response started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
				sessionId,
				messageId,
				model: this.model,
				timestamp: startTime,
			});
		}

		// Use unified tool manager if available, otherwise fall back to MCP manager
		let formattedTools: any[];
		if (this.unifiedToolManager) {
			formattedTools = await this.unifiedToolManager.getToolsForProvider('openai');
		} else {
			const rawTools = await this.mcpManager.getAllTools();
			formattedTools = this.formatToolsForOpenAI(rawTools);
		}

		let iterationCount = 0;
		try {
			while (iterationCount < this.maxIterations) {
				iterationCount++;

				// Attempt to get a response, with retry logic
				const { message } = await this.getAIResponseWithRetries(formattedTools, userInput);

				// If there are no tool calls, we're done
				if (!message.tool_calls || message.tool_calls.length === 0) {
					const responseText = message.content || '';

					// Add assistant message to history
					await this.contextManager.addAssistantMessage(responseText);

					// Emit LLM response completed event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_COMPLETED, {
							sessionId,
							messageId,
							model: this.model,
							duration: Date.now() - startTime,
							timestamp: Date.now(),
							response: responseText,
						});
					}

					return responseText;
				}

				// Log thinking steps when assistant provides reasoning before tool calls
				if (message.content && message.content.trim()) {
					logger.info(`💭 ${message.content.trim()}`);

					// Emit thinking event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_THINKING, {
							sessionId,
							messageId,
							timestamp: Date.now(),
						});
					}
				}

				// Add assistant message with tool calls to history
				await this.contextManager.addAssistantMessage(message.content, message.tool_calls);

				// Handle tool calls
				for (const toolCall of message.tool_calls) {
					logger.debug(`Tool call initiated: ${JSON.stringify(toolCall, null, 2)}`);
					logger.info(`🔧 Using tool: ${toolCall.function.name}`);
					const toolName = toolCall.function.name;
					let args: any = {};

					try {
						args = JSON.parse(toolCall.function.arguments);
					} catch (e) {
						logger.error(`Error parsing arguments for ${toolName}:`, e);
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: `Failed to parse arguments: ${e}`,
						});
						continue;
					}

					// Execute tool
					try {
						let result: any;
						if (this.unifiedToolManager) {
							result = await this.unifiedToolManager.executeTool(toolName, args, sessionId);
						} else {
							result = await this.mcpManager.executeTool(toolName, args);
						}

						// Display formatted tool result
						const formattedResult = formatToolResult(toolName, result);
						logger.info(`📋 Tool Result:\n${formattedResult}`);

						// Add tool result to context
						await this.contextManager.addToolResult(toolCall.id, toolName, result);
					} catch (error) {
						logger.error(`Error executing tool ${toolName}:`, error);
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: error instanceof Error ? error.message : String(error),
						});
					}
				}
			}

			throw new Error(`Maximum iterations (${this.maxIterations}) exceeded`);
		} catch (error) {
			logger.error('Error in Ollama service:', error);
			throw error;
		}
	}

	/**
	 * Direct generate method that bypasses conversation context
	 * Used for internal tool operations that shouldn't pollute conversation history
	 * @param userInput - The input to generate a response for
	 * @param systemPrompt - Optional system prompt to use
	 * @returns Promise<string> - The generated response
	 */
	async directGenerate(userInput: string, systemPrompt?: string): Promise<string> {
		try {
			logger.debug('OllamaService: Direct generate call (bypassing conversation context)', {
				inputLength: userInput.length,
				hasSystemPrompt: !!systemPrompt,
			});

			// Create a minimal message array for direct API call
			const messages: any[] = [];

			if (systemPrompt) {
				messages.push({
					role: 'system',
					content: systemPrompt,
				});
			}

			messages.push({
				role: 'user',
				content: userInput,
			});

			// Make direct API call without adding to conversation context
			const response = await this.openai.chat.completions.create({
				model: this.model,
				messages: messages,
				// No tools for direct calls - this is for simple text generation
			});

			const responseText = response.choices[0]?.message?.content || '';

			logger.debug('OllamaService: Direct generate completed', {
				responseLength: responseText.length,
			});

			return responseText;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('OllamaService: Direct generate failed', {
				error: errorMessage,
				inputLength: userInput.length,
			});
			throw new Error(`Direct generate failed: ${errorMessage}`);
		}
	}

	async getAllTools(): Promise<ToolSet | CombinedToolSet> {
		if (this.unifiedToolManager) {
			return await this.unifiedToolManager.getAllTools();
		}
		return this.mcpManager.getAllTools();
	}

	getConfig(): LLMServiceConfig {
		return {
			provider: 'ollama',
			model: this.model,
		};
	}

	// Helper methods
	private async getAIResponseWithRetries(
		tools: any[],
		userInput: string
	): Promise<{ message: any }> {
		let attempts = 0;
		const MAX_ATTEMPTS = 3;

		// Add a log of the number of tools in response
		logger.debug(`Tools in Ollama response: ${tools.length}`);

		while (attempts < MAX_ATTEMPTS) {
			attempts++;
			try {
				// Use the new method that implements proper flow: get system prompt, compress history, format messages
				const formattedMessages = await this.contextManager.getFormattedMessage({
					role: 'user',
					content: userInput,
				});

				// Call Ollama API via OpenAI SDK (Ollama is OpenAI-compatible)
				const response = await this.openai.chat.completions.create({
					model: this.model,
					messages: formattedMessages,
					tools: attempts === 1 ? tools : [], // Only offer tools on first attempt
					tool_choice: attempts === 1 ? 'auto' : 'none', // Disable tool choice on retry
				});

				logger.silly('OLLAMA CHAT COMPLETION RESPONSE: ', JSON.stringify(response, null, 2));

				// Get the response message
				const message = response.choices[0]?.message;
				if (!message) {
					throw new Error('Received empty message from Ollama API');
				}

				return { message };
			} catch (error) {
				const apiError = error as any;
				logger.error(
					`Error in Ollama API call (Attempt ${attempts}/${MAX_ATTEMPTS}): ${apiError.message || JSON.stringify(apiError, null, 2)}`,
					{ status: apiError.status, headers: apiError.headers }
				);

				// Ollama-specific error handling
				if (apiError.status === 400) {
					logger.warn(
						`Ollama API error - check if model '${this.model}' is available locally. Error details: ${JSON.stringify(apiError.error)}`
					);
				}

				// Connection errors might indicate Ollama is not running
				if (apiError.code === 'ECONNREFUSED' || apiError.code === 'ENOTFOUND') {
					logger.error(
						'Failed to connect to Ollama server. Please ensure Ollama is running and accessible.'
					);
				}

				if (attempts >= MAX_ATTEMPTS) {
					logger.error(`Failed to get response from Ollama after ${MAX_ATTEMPTS} attempts.`);
					throw error;
				}

				await new Promise(resolve => setTimeout(resolve, 500 * attempts));
			}
		}

		throw new Error('Failed to get response after maximum retry attempts');
	}

	private formatToolsForOpenAI(tools: ToolSet): any[] {
		// Ollama uses the same format as OpenAI for tools
		// Convert the ToolSet object to an array of tools in OpenAI's format
		return Object.entries(tools).map(([name, tool]) => {
			return {
				type: 'function',
				function: {
					name,
					description: tool.description,
					parameters: tool.parameters,
				},
			};
		});
	}
}

import { ToolSet } from '../../../mcp/types.js';
import { MCPManager } from '../../../mcp/manager.js';
import { UnifiedToolManager, CombinedToolSet } from '../../tools/unified-tool-manager.js';
import { ContextManager } from '../messages/manager.js';
import { ImageData } from '../messages/types.js';
import { ILLMService, LLMServiceConfig } from './types.js';
import OpenAI from 'openai';
import { logger } from '../../../logger/index.js';
import { formatToolResult } from '../utils/tool-result-formatter.js';
import { EventManager } from '../../../events/event-manager.js';
import { SessionEvents } from '../../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

export class OpenAIService implements ILLMService {
	private openai: OpenAI;
	private model: string;
	private mcpManager: MCPManager;
	private unifiedToolManager: UnifiedToolManager | undefined;
	private contextManager: ContextManager;
	private maxIterations: number;
	private eventManager?: EventManager;

	constructor(
		openai: OpenAI,
		model: string,
		mcpManager: MCPManager,
		contextManager: ContextManager,
		maxIterations: number = 5,
		unifiedToolManager?: UnifiedToolManager
	) {
		this.openai = openai;
		this.model = model;
		this.mcpManager = mcpManager;
		this.unifiedToolManager = unifiedToolManager;
		this.contextManager = contextManager;
		this.maxIterations = maxIterations;
	}

	/**
	 * Set the event manager for emitting LLM response events
	 */
	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	async generate(userInput: string, imageData?: ImageData): Promise<string> {
		await this.contextManager.addUserMessage(userInput, imageData);

		const messageId = uuidv4();
		const startTime = Date.now();

		// Try to get sessionId from contextManager if available, otherwise undefined
		const sessionId = (this.contextManager as any)?.sessionId;

		// Emit LLM response started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
				sessionId,
				messageId,
				model: this.model,
				timestamp: startTime,
			});
		}

		// Use unified tool manager if available, otherwise fall back to MCP manager
		let formattedTools: any[];
		if (this.unifiedToolManager) {
			formattedTools = await this.unifiedToolManager.getToolsForProvider('openai');
		} else {
			const rawTools = await this.mcpManager.getAllTools();
			formattedTools = this.formatToolsForOpenAI(rawTools);
		}

		let iterationCount = 0;
		try {
			while (iterationCount < this.maxIterations) {
				iterationCount++;

				// Attempt to get a response, with retry logic
				const { message } = await this.getAIResponseWithRetries(formattedTools, userInput);

				// If there are no tool calls, we're done
				if (!message.tool_calls || message.tool_calls.length === 0) {
					const responseText = message.content || '';

					// Add assistant message to history
					await this.contextManager.addAssistantMessage(responseText);

					// Emit LLM response completed event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_COMPLETED, {
							sessionId,
							messageId,
							model: this.model,
							duration: Date.now() - startTime,
							timestamp: Date.now(),
							response: responseText,
						});
					}

					return responseText;
				}

				// Log thinking steps when assistant provides reasoning before tool calls
				if (message.content && message.content.trim()) {
					logger.info(`💭 ${message.content.trim()}`);

					// Emit thinking event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_THINKING, {
							sessionId,
							messageId,
							timestamp: Date.now(),
						});
					}
				}

				// Add assistant message with tool calls to history
				await this.contextManager.addAssistantMessage(message.content, message.tool_calls);

				// Handle tool calls
				for (const toolCall of message.tool_calls) {
					logger.debug(`Tool call initiated: ${JSON.stringify(toolCall, null, 2)}`);
					logger.info(`🔧 Using tool: ${toolCall.function.name}`);
					const toolName = toolCall.function.name;
					let args: any = {};

					try {
						args = JSON.parse(toolCall.function.arguments);
					} catch (e) {
						logger.error(`Error parsing arguments for ${toolName}:`, e);
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: `Failed to parse arguments: ${e}`,
						});
						continue;
					}

					// Execute tool
					try {
						let result: any;
						if (this.unifiedToolManager) {
							result = await this.unifiedToolManager.executeTool(toolName, args, sessionId);
						} else {
							result = await this.mcpManager.executeTool(toolName, args);
						}

						// Display formatted tool result
						const formattedResult = formatToolResult(toolName, result);
						logger.info(`📋 Tool Result:\n${formattedResult}`);

						// Add tool result to context
						await this.contextManager.addToolResult(toolCall.id, toolName, result);
					} catch (error) {
						logger.error(`Error executing tool ${toolName}:`, error);
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: error instanceof Error ? error.message : String(error),
						});
					}
				}
			}

			throw new Error(`Maximum iterations (${this.maxIterations}) exceeded`);
		} catch (error) {
			logger.error('Error in OpenAI service:', error);
			throw error;
		}
	}

	/**
	 * Direct generate method that bypasses conversation context
	 * Used for internal tool operations that shouldn't pollute conversation history
	 * @param userInput - The input to generate a response for
	 * @param systemPrompt - Optional system prompt to use
	 * @returns Promise<string> - The generated response
	 */
	async directGenerate(userInput: string, systemPrompt?: string): Promise<string> {
		try {
			logger.debug('OpenAIService: Direct generate call (bypassing conversation context)', {
				inputLength: userInput.length,
				hasSystemPrompt: !!systemPrompt,
			});

			// Create a minimal message array for direct API call
			const messages: any[] = [];

			if (systemPrompt) {
				messages.push({
					role: 'system',
					content: systemPrompt,
				});
			}

			messages.push({
				role: 'user',
				content: userInput,
			});

			// Make direct API call without adding to conversation context
			const response = await this.openai.chat.completions.create({
				model: this.model,
				messages: messages,
				// No tools for direct calls - this is for simple text generation
			});

			const responseText = response.choices[0]?.message?.content || '';

			logger.debug('OpenAIService: Direct generate completed', {
				responseLength: responseText.length,
			});

			return responseText;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('OpenAIService: Direct generate failed', {
				error: errorMessage,
				inputLength: userInput.length,
			});
			throw new Error(`Direct generate failed: ${errorMessage}`);
		}
	}

	async getAllTools(): Promise<ToolSet | CombinedToolSet> {
		if (this.unifiedToolManager) {
			return await this.unifiedToolManager.getAllTools();
		}
		return this.mcpManager.getAllTools();
	}

	getConfig(): LLMServiceConfig {
		return {
			provider: 'openai',
			model: this.model,
		};
	}

	// Helper methods
	private async getAIResponseWithRetries(
		tools: any[],
		userInput: string
	): Promise<{ message: any }> {
		let attempts = 0;
		const MAX_ATTEMPTS = 3;

		// Add a log of the number of tools in response
		logger.debug(`Tools in response: ${tools.length}`);

		while (attempts < MAX_ATTEMPTS) {
			attempts++;
			try {
				// Use the new method that implements proper flow: get system prompt, compress history, format messages
				const formattedMessages = await this.contextManager.getFormattedMessage({
					role: 'user',
					content: userInput,
				});

				// Debug log: Show exactly what messages are being sent to OpenAI
				logger.debug(`Sending ${formattedMessages.length} formatted messages to OpenAI:`, {
					messages: formattedMessages.map((msg, idx) => ({
						index: idx,
						role: msg.role,
						hasContent: !!msg.content,
						hasToolCalls: !!msg.tool_calls,
						toolCallId: msg.tool_call_id,
						name: msg.name,
					})),
				});

				// Call OpenAI API
				const response = await this.openai.chat.completions.create({
					model: this.model,
					messages: formattedMessages,
					tools: attempts === 1 ? tools : [], // Only offer tools on first attempt
					tool_choice: attempts === 1 ? 'auto' : 'none', // Disable tool choice on retry
				});

				logger.silly('OPENAI CHAT COMPLETION RESPONSE: ', JSON.stringify(response, null, 2));

				// Get the response message
				const message = response.choices[0]?.message;
				if (!message) {
					throw new Error('Received empty message from OpenAI API');
				}

				return { message };
			} catch (error) {
				const apiError = error as any;
				logger.error(
					`Error in OpenAI API call (Attempt ${attempts}/${MAX_ATTEMPTS}): ${apiError.message || JSON.stringify(apiError, null, 2)}`,
					{ status: apiError.status, headers: apiError.headers }
				);

				if (apiError.status === 400 && apiError.error?.code === 'context_length_exceeded') {
					logger.warn(
						`Context length exceeded. ContextManager compression might not be sufficient. Error details: ${JSON.stringify(apiError.error)}`
					);
				}

				if (attempts >= MAX_ATTEMPTS) {
					logger.error(`Failed to get response from OpenAI after ${MAX_ATTEMPTS} attempts.`);
					throw error;
				}

				await new Promise(resolve => setTimeout(resolve, 500 * attempts));
			}
		}

		throw new Error('Failed to get response after maximum retry attempts');
	}

	private formatToolsForOpenAI(tools: ToolSet): any[] {
		// Keep the existing implementation
		// Convert the ToolSet object to an array of tools in OpenAI's format
		return Object.entries(tools).map(([name, tool]) => {
			return {
				type: 'function',
				function: {
					name,
					description: tool.description,
					parameters: tool.parameters,
				},
			};
		});
	}
}

import { ToolSet } from '../../../mcp/types.js';
