			const response = await this.client.chat.completions.create({
				model: this.model,
				messages: messages,
				// No tools for direct calls - this is for simple text generation
			});

			const responseText = response.choices[0]?.message?.content || '';

			logger.debug('OpenRouterService: Direct generate completed', {
				responseLength: responseText.length,
			});

			return responseText;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('OpenRouterService: Direct generate failed', {
				error: errorMessage,
				inputLength: userInput.length,
			});
			throw new Error(`Direct generate failed: ${errorMessage}`);
		}
	}

	async getAllTools(): Promise<ToolSet | CombinedToolSet> {
		if (this.unifiedToolManager) {
			return await this.unifiedToolManager.getAllTools();
		}
		return this.mcpManager.getAllTools();
	}

	getConfig(): LLMServiceConfig {
		return {
			provider: 'openrouter',
			model: this.model,
		};
	}

	// Helper methods
	private async getAIResponseWithRetries(
		tools: any[],
		userInput: string
	): Promise<{ message: any }> {
		let attempts = 0;
		const MAX_ATTEMPTS = 3;

		// Add a log of the number of tools in response
		logger.debug(`Tools in OpenRouter response: ${tools.length}`);

		while (attempts < MAX_ATTEMPTS) {
			attempts++;
			try {
				// Use the new method that implements proper flow: get system prompt, compress history, format messages
				const formattedMessages = await this.contextManager.getFormattedMessage({
					role: 'user',
					content: userInput,
				});

				// Call OpenRouter API via OpenAI SDK (OpenRouter is OpenAI-compatible)
				const response = await this.client.chat.completions.create({
					model: this.model,
					messages: formattedMessages,
					tools: attempts === 1 ? tools : [], // Only offer tools on first attempt
					tool_choice: attempts === 1 ? 'auto' : 'none', // Disable tool choice on retry
				});

				logger.silly('OPENROUTER CHAT COMPLETION RESPONSE: ', JSON.stringify(response, null, 2));

				// Get the response message
				const message = response.choices[0]?.message;
				if (!message) {
					throw new Error('Received empty message from OpenRouter API');
				}

				return { message };
			} catch (error) {
				const apiError = error as any;
				logger.error(
					`Error in OpenRouter API call (Attempt ${attempts}/${MAX_ATTEMPTS}): ${apiError.message || JSON.stringify(apiError, null, 2)}`,
					{ status: apiError.status, headers: apiError.headers }
				);

				if (apiError.status === 400 && apiError.error?.code === 'context_length_exceeded') {
					logger.warn(
						`Context length exceeded. ContextManager compression might not be sufficient. Error details: ${JSON.stringify(apiError.error)}`
					);
				}

				if (attempts >= MAX_ATTEMPTS) {
					logger.error(`Failed to get response from OpenRouter after ${MAX_ATTEMPTS} attempts.`);
					throw error;
				}

				await new Promise(resolve => setTimeout(resolve, 500 * attempts));
			}
		}

		throw new Error('Failed to get response after maximum retry attempts');
	}

	private formatToolsForOpenRouter(tools: ToolSet): any[] {
		// OpenRouter uses the same format as OpenAI for tools
		// Convert the ToolSet object to an array of tools in OpenAI's format
		return Object.entries(tools).map(([name, tool]) => {
			return {
				type: 'function',
				function: {
					name,
					description: tool.description,
					parameters: tool.parameters,
				},
			};
		});
	}
}

import { ToolSet } from '../../../mcp/types.js';
import { MCPManager } from '../../../mcp/manager.js';
import { UnifiedToolManager, CombinedToolSet } from '../../tools/unified-tool-manager.js';
import { ContextManager } from '../messages/manager.js';
import { ImageData } from '../messages/types.js';
import { ILLMService, LLMServiceConfig } from './types.js';
// Fix OpenAI import for compatibility
// @ts-ignore

// const OpenAI = require('openai');
import { logger } from '../../../logger/index.js';
import { formatToolResult } from '../utils/tool-result-formatter.js';
import { EventManager } from '../../../events/event-manager.js';
import { SessionEvents } from '../../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

export interface QwenOptions {
	enableThinking?: boolean;
	thinkingBudget?: number;
	[key: string]: any;
}

export class QwenService implements ILLMService {
	private openai: any;
	private model: string;
	private mcpManager: MCPManager;
	private unifiedToolManager: UnifiedToolManager | undefined;
	private contextManager: ContextManager;
	private maxIterations: number;
	private qwenOptions: QwenOptions;
	private eventManager?: EventManager;

	constructor(
		openai: any,
		model: string,
		mcpManager: MCPManager,
		contextManager: ContextManager,
		maxIterations: number = 5,
		qwenOptions: QwenOptions = {},
		unifiedToolManager?: UnifiedToolManager
	) {
		this.openai = openai;
		this.model = model;
		this.mcpManager = mcpManager;
		this.unifiedToolManager = unifiedToolManager;
		this.contextManager = contextManager;
		this.maxIterations = maxIterations;
		this.qwenOptions = qwenOptions;
	}

	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	async generate(userInput: string, imageData?: ImageData, stream?: boolean): Promise<string> {
		await this.contextManager.addUserMessage(userInput, imageData);

		const messageId = uuidv4();
		const startTime = Date.now();

		// Try to get sessionId from contextManager if available, otherwise undefined
		const sessionId = (this.contextManager as any)?.sessionId;

		// Emit LLM response started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
				sessionId,
				messageId,
				model: this.model,
				timestamp: startTime,
			});
		}

		let formattedTools: any[] = [];
		if (this.unifiedToolManager) {
			// Use 'qwen' for Qwen-specific tool formatting
			formattedTools = (await this.unifiedToolManager.getToolsForProvider('qwen')) || [];
		} else {
			const rawTools = await this.mcpManager.getAllTools();
			formattedTools = this.formatToolsForOpenAI(rawTools) || [];
		}

		logger.silly(`[Qwen] Formatted tools: ${JSON.stringify(formattedTools, null, 2)}`);

		let iterationCount = 0;
		try {
			while (iterationCount < this.maxIterations) {
				iterationCount++;
				const { message } = await this.getAIResponseWithRetries(formattedTools, userInput, stream);

				if (
					!message.tool_calls ||
					!Array.isArray(message.tool_calls) ||
					message.tool_calls.length === 0
				) {
					const responseText = message.content || '';
					await this.contextManager.addAssistantMessage(responseText);

					// Emit LLM response completed event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_COMPLETED, {
							sessionId,
							messageId,
							model: this.model,
							duration: Date.now() - startTime,
							timestamp: Date.now(),
							response: responseText,
						});
					}

					return responseText;
				}

				if (message.content && message.content.trim()) {
					logger.info(`[Qwen] 💭 ${message.content.trim()}`);

					// Emit thinking event
					if (this.eventManager && sessionId) {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_THINKING, {
							sessionId,
							messageId,
							timestamp: Date.now(),
						});
					}
				}

				await this.contextManager.addAssistantMessage(message.content, message.tool_calls);

				for (const toolCall of message.tool_calls) {
					logger.debug(`[Qwen] Tool call initiated: ${JSON.stringify(toolCall, null, 2)}`);
					logger.info(`[Qwen] 🔧 Using tool: ${toolCall.function.name}`);
					const toolName = toolCall.function.name;
					let args: any = {};

					try {
						args = JSON.parse(toolCall.function.arguments);
					} catch (e) {
						logger.error(`[Qwen] Error parsing arguments for ${toolName}:`, e);
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: `Failed to parse arguments: ${e}`,
						});
						continue;
					}

					try {
						let result: any;
						if (this.unifiedToolManager) {
							result = await this.unifiedToolManager.executeTool(toolName, args, sessionId);
						} else {
							result = await this.mcpManager.executeTool(toolName, args);
						}
						const formattedResult = formatToolResult(toolName, result);
						logger.info(`[Qwen] 📋 Tool Result:\n${formattedResult}`);
						await this.contextManager.addToolResult(toolCall.id, toolName, result);
					} catch (error) {
						const errorMessage = error instanceof Error ? error.message : String(error);
						logger.error(`[Qwen] Tool execution error for ${toolName}: ${errorMessage}`);
						await this.contextManager.addToolResult(toolCall.id, toolName, {
							error: errorMessage,
						});
					}
				}
			}
			logger.warn(`[Qwen] Reached maximum iterations (${this.maxIterations}) for task.`);
			const finalResponse = 'Task completed but reached maximum tool call iterations.';
			await this.contextManager.addAssistantMessage(finalResponse);
			return finalResponse;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(`[Qwen] Error in Qwen service API call: ${errorMessage}`, { error });
			await this.contextManager.addAssistantMessage(
				`[Qwen] Error processing request: ${errorMessage}`
			);
			return `[Qwen] Error processing request: ${errorMessage}`;
		}
	}

	async directGenerate(userInput: string, systemPrompt?: string): Promise<string> {
		try {
			logger.debug('[QwenService] Direct generate call (bypassing conversation context)', {
				inputLength: userInput.length,
				hasSystemPrompt: !!systemPrompt,
			});
			const messages: any[] = [];
			if (systemPrompt) {
				messages.push({
					role: 'system',
					content: systemPrompt,
				});
			}
			messages.push({
				role: 'user',
				content: userInput,
			});
			// Transform qwenOptions to API format (camelCase to snake_case) for direct generate
			const apiOptions: any = {};

			// Always set enable_thinking explicitly for non-streaming calls
			// Qwen API requires this to be explicitly set to false for non-streaming calls
			apiOptions.enable_thinking = this.qwenOptions.enableThinking ?? false;

			if (this.qwenOptions.thinkingBudget !== undefined) {
				apiOptions.thinking_budget = this.qwenOptions.thinkingBudget;
			}
			if (this.qwenOptions.temperature !== undefined) {
				apiOptions.temperature = this.qwenOptions.temperature;
			}
			if (this.qwenOptions.top_p !== undefined) {
				apiOptions.top_p = this.qwenOptions.top_p;
			}

			const response = await this.openai.chat.completions.create({
				model: this.model,
				messages: messages,
				...apiOptions,
			});
			const responseText = response.choices[0]?.message?.content || '';
			logger.debug('[QwenService] Direct generate completed', {
				responseLength: responseText.length,
			});
			return responseText;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('[QwenService] Direct generate failed', {
				error: errorMessage,
				inputLength: userInput.length,
			});
			throw new Error(`[QwenService] Direct generate failed: ${errorMessage}`);
		}
	}

	async getAllTools(): Promise<ToolSet | CombinedToolSet> {
		if (this.unifiedToolManager) {
			return await this.unifiedToolManager.getAllTools();
		}
		return this.mcpManager.getAllTools();
	}

	getConfig(): LLMServiceConfig {
		return {
			provider: 'qwen',
			model: this.model,
		};
	}

	private async getAIResponseWithRetries(
		tools: any[],
		userInput: string,
		stream?: boolean
	): Promise<{ message: any }> {
		let attempts = 0;
		const MAX_ATTEMPTS = 3;
		logger.debug(`[Qwen] Tools in response: ${tools?.length || 0}`);
		while (attempts < MAX_ATTEMPTS) {
			attempts++;
			try {
				const formattedMessages = await this.contextManager.getFormattedMessage({
					role: 'user',
					content: userInput,
				});
				logger.debug(`[Qwen] Sending ${formattedMessages.length} formatted messages to Qwen:`, {
					messages: formattedMessages.map((msg, idx) => ({
						index: idx,
						role: msg.role,
						hasContent: !!msg.content,
						hasToolCalls: !!msg.tool_calls,
						toolCallId: msg.tool_call_id,
						name: msg.name,
					})),
				});
				// Transform qwenOptions to API format (camelCase to snake_case)
				const apiOptions: any = {};

				// Always set enable_thinking explicitly for non-streaming calls
				// Qwen API requires this to be explicitly set to false for non-streaming calls
				apiOptions.enable_thinking = this.qwenOptions.enableThinking ?? false;

				if (this.qwenOptions.thinkingBudget !== undefined) {
					apiOptions.thinking_budget = this.qwenOptions.thinkingBudget;
				}
				if (this.qwenOptions.temperature !== undefined) {
					apiOptions.temperature = this.qwenOptions.temperature;
				}
				if (this.qwenOptions.top_p !== undefined) {
					apiOptions.top_p = this.qwenOptions.top_p;
				}

				// Debug logging to see what's being sent
				logger.debug('[Qwen] QwenOptions being sent to API:', {
					qwenOptions: this.qwenOptions,
					apiOptions: apiOptions,
					enableThinking: this.qwenOptions.enableThinking,
					enable_thinking: apiOptions.enable_thinking,
				});

				const requestBody: any = {
					model: this.model,
					messages: formattedMessages,
					tools: attempts === 1 ? tools || [] : [],
					tool_choice: attempts === 1 ? 'auto' : 'none',
					...apiOptions,
				};
				if (stream !== undefined) {
					requestBody.stream = stream;
				}
				const response = await this.openai.chat.completions.create(requestBody);
				logger.silly('[Qwen] QWEN CHAT COMPLETION RESPONSE: ', JSON.stringify(response, null, 2));
				const message = response.choices[0]?.message;
				if (!message) {
					throw new Error('[Qwen] Received empty message from Qwen API');
				}
				return { message };
			} catch (error) {
				const apiError = error as any;
				logger.error(
					`[Qwen] Error in Qwen API call (Attempt ${attempts}/${MAX_ATTEMPTS}): ${apiError.message || JSON.stringify(apiError, null, 2)}`,
					{ status: apiError.status, headers: apiError.headers }
				);
				if (apiError.status === 400 && apiError.error?.code === 'context_length_exceeded') {
					logger.warn(
						`[Qwen] Context length exceeded. ContextManager compression might not be sufficient. Error details: ${JSON.stringify(apiError.error)}`
					);
				}
				if (attempts >= MAX_ATTEMPTS) {
					logger.error(`[Qwen] Failed to get response from Qwen after ${MAX_ATTEMPTS} attempts.`);
					throw error;
				}
				await new Promise(resolve => setTimeout(resolve, 500 * attempts));
			}
		}
		throw new Error('[Qwen] Failed to get response after maximum retry attempts');
	}

	private formatToolsForOpenAI(tools: ToolSet): any[] {
		if (!tools || typeof tools !== 'object') {
			return [];
		}
		return Object.entries(tools).map(([name, tool]) => {
			return {
				type: 'function',
				function: {
					name,
					description: tool.description,
					parameters: tool.parameters,
				},
			};
		});
	}
}

import { ToolSet } from '../../../mcp/types.js';
import { ImageData } from '../messages/types.js';

/**
 * The LLMService interface provides a contract for interacting with an LLM service.
 * It defines methods for generating text, retrieving available tools, and retrieving the service configuration.
 */

export interface ILLMService {
	generate(userInput: string, imageData?: ImageData, stream?: boolean): Promise<string>;
	directGenerate(userInput: string, systemPrompt?: string): Promise<string>;
	getAllTools(): Promise<ToolSet>;
	getConfig(): LLMServiceConfig;
}

/**
 * The LLMServiceConfig interface defines the configuration for an LLM service.
 * It includes the provider and model information.
 */

export type LLMServiceConfig = {
	provider: string;
	model: string;
};

import { describe, it, expect, beforeEach, vi, afterEach } from 'vitest';
import { TokenizerCache, getTokenizerCache } from '../cache.js';
import { ITokenizer, TokenizerConfig } from '../types.js';

// Mock tokenizer for testing
class MockTokenizer implements ITokenizer {
	constructor(
		public provider: string,
		public model: string,
		private creationId = Math.random()
	) {}

	async countTokens(): Promise<any> {
		return {
			total: 100,
			characters: 400,
			estimated: false,
			provider: this.provider,
			model: this.model,
		};
	}

	async countMessages(): Promise<any> {
		return {
			total: 200,
			characters: 800,
			estimated: false,
			provider: this.provider,
			model: this.model,
		};
	}

	getMaxTokens(): number {
		return 4096;
	}
	getContextWindow(): number {
		return 4096;
	}
	estimateTokens(): number {
		return 100;
	}
	isWithinLimit(): boolean {
		return true;
	}
	getRemainingTokens(): number {
		return 3996;
	}

	// Helper to verify instance uniqueness
	getCreationId(): number {
		return this.creationId;
	}
}

describe('TokenizerCache', () => {
	let cache: TokenizerCache;
	let mockFactory: vi.MockedFunction<(config: TokenizerConfig) => ITokenizer>;

	beforeEach(() => {
		// Clear any existing cache instance
		(TokenizerCache as any).instance = null;
		cache = TokenizerCache.getInstance();
		cache.clear();

		// Mock factory function
		mockFactory = vi.fn((config: TokenizerConfig) => {
			return new MockTokenizer(config.provider, config.model || 'default');
		});
	});

	afterEach(() => {
		cache.clear();
		vi.clearAllMocks();
	});

	describe('Singleton Pattern', () => {
		it('should return the same instance', () => {
			const instance1 = TokenizerCache.getInstance();
			const instance2 = TokenizerCache.getInstance();
			const instance3 = getTokenizerCache();

			expect(instance1).toBe(instance2);
			expect(instance2).toBe(instance3);
		});

		it('should maintain cache across getInstance calls', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const instance1 = TokenizerCache.getInstance();
			const tokenizer1 = instance1.get(config, mockFactory);

			const instance2 = TokenizerCache.getInstance();
			const tokenizer2 = instance2.get(config, mockFactory);

			expect(tokenizer1).toBe(tokenizer2);
			expect(mockFactory).toHaveBeenCalledTimes(1);
		});
	});

	describe('Cache Operations', () => {
		it('should cache tokenizer on first access', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			expect(cache.has(config)).toBe(false);
			expect(cache.size()).toBe(0);

			const tokenizer = cache.get(config, mockFactory);

			expect(mockFactory).toHaveBeenCalledTimes(1);
			expect(mockFactory).toHaveBeenCalledWith(config);
			expect(cache.has(config)).toBe(true);
			expect(cache.size()).toBe(1);
			expect(tokenizer).toBeInstanceOf(MockTokenizer);
		});

		it('should return cached tokenizer on subsequent access', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const tokenizer1 = cache.get(config, mockFactory);
			const tokenizer2 = cache.get(config, mockFactory);
			const tokenizer3 = cache.get(config, mockFactory);

			expect(tokenizer1).toBe(tokenizer2);
			expect(tokenizer2).toBe(tokenizer3);
			expect(mockFactory).toHaveBeenCalledTimes(1);
			expect(cache.size()).toBe(1);
		});

		it('should create different tokenizers for different configs', () => {
			const config1: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const config2: TokenizerConfig = {
				provider: 'anthropic',
				model: 'claude-3',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const config3: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-3.5',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const tokenizer1 = cache.get(config1, mockFactory);
			const tokenizer2 = cache.get(config2, mockFactory);
			const tokenizer3 = cache.get(config3, mockFactory);

			expect(tokenizer1).not.toBe(tokenizer2);
			expect(tokenizer2).not.toBe(tokenizer3);
			expect(tokenizer1).not.toBe(tokenizer3);
			expect(mockFactory).toHaveBeenCalledTimes(3);
			expect(cache.size()).toBe(3);
		});

		it('should handle configuration variations correctly', () => {
			const baseConfig: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const configWithDefaults: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const configWithDifferentDefaults: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: false,
				hybridTracking: false,
			};

			const tokenizer1 = cache.get(baseConfig, mockFactory);
			const tokenizer2 = cache.get(configWithDefaults, mockFactory);
			const tokenizer3 = cache.get(configWithDifferentDefaults, mockFactory);

			// Base config and configWithDefaults are identical, so they should return the same instance
			expect(tokenizer1).toBe(tokenizer2);
			// configWithDifferentDefaults has different values, so it should be a different instance
			expect(tokenizer1).not.toBe(tokenizer3);
			expect(tokenizer2).not.toBe(tokenizer3);
			expect(mockFactory).toHaveBeenCalledTimes(2); // Called twice: once for identical configs, once for different config
		});
	});

	describe('Cache Management', () => {
		it('should enforce maximum cache size with LRU eviction', async () => {
			// Mock the max cache size to a smaller value for testing
			const originalMaxSize = (cache as any).maxCacheSize;
			(cache as any).maxCacheSize = 3;

			try {
				// Fill cache to capacity
				const config0: TokenizerConfig = {
					provider: 'openai',
					model: 'gpt-0',
					fallbackToApproximation: true,
					hybridTracking: true,
				};
				const config1: TokenizerConfig = {
					provider: 'openai',
					model: 'gpt-1',
					fallbackToApproximation: true,
					hybridTracking: true,
				};
				const config2: TokenizerConfig = {
					provider: 'openai',
					model: 'gpt-2',
					fallbackToApproximation: true,
					hybridTracking: true,
				};

				cache.get(config0, mockFactory);
				await new Promise(resolve => setTimeout(resolve, 1)); // Small delay to ensure different timestamps
				cache.get(config1, mockFactory);
				await new Promise(resolve => setTimeout(resolve, 1)); // Small delay to ensure different timestamps
				cache.get(config2, mockFactory);

				expect(cache.size()).toBe(3);

				// Access first tokenizer to make it more recently used
				await new Promise(resolve => setTimeout(resolve, 1)); // Small delay to ensure different timestamps
				cache.get(config0, mockFactory); // This should update access time for config0

				// Add fourth tokenizer - should evict least recently used (config1)
				await new Promise(resolve => setTimeout(resolve, 1)); // Small delay to ensure different timestamps
				const config3: TokenizerConfig = {
					provider: 'openai',
					model: 'gpt-3',
					fallbackToApproximation: true,
					hybridTracking: true,
				};
				cache.get(config3, mockFactory);

				expect(cache.size()).toBe(3);
				expect(cache.has(config0)).toBe(true); // Recently accessed, should still be there
				expect(cache.has(config1)).toBe(false); // Should be evicted (least recently used)
				expect(cache.has(config2)).toBe(true); // Should still be there
				expect(cache.has(config3)).toBe(true); // Newly added
			} finally {
				(cache as any).maxCacheSize = originalMaxSize;
			}
		});

		it('should invalidate specific tokenizer', () => {
			const config1: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const config2: TokenizerConfig = {
				provider: 'anthropic',
				model: 'claude-3',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			cache.get(config1, mockFactory);
			cache.get(config2, mockFactory);
			expect(cache.size()).toBe(2);

			const removed = cache.invalidate(config1);

			expect(removed).toBe(true);
			expect(cache.has(config1)).toBe(false);
			expect(cache.has(config2)).toBe(true);
			expect(cache.size()).toBe(1);
		});

		it('should return false when invalidating non-existent tokenizer', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const removed = cache.invalidate(config);

			expect(removed).toBe(false);
			expect(cache.size()).toBe(0);
		});

		it('should clear all cached tokenizers', () => {
			// Add multiple tokenizers
			for (let i = 0; i < 5; i++) {
				const config: TokenizerConfig = {
					provider: 'openai',
					model: `gpt-${i}`,
					fallbackToApproximation: true,
					hybridTracking: true,
				};
				cache.get(config, mockFactory);
			}

			expect(cache.size()).toBe(5);

			cache.clear();

			expect(cache.size()).toBe(0);
			expect(mockFactory).toHaveBeenCalledTimes(5); // Should not call factory again
		});
	});

	describe('Statistics and Monitoring', () => {
		it('should track cache hits correctly', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			// First access - cache miss
			cache.get(config, mockFactory);

			// Multiple subsequent accesses - cache hits
			cache.get(config, mockFactory);
			cache.get(config, mockFactory);
			cache.get(config, mockFactory);

			const stats = cache.getStats();
			expect(stats.cacheSize).toBe(1);
			expect(stats.totalHits).toBe(4); // 1 initial + 3 hits
			expect(stats.hitRate).toBe(0.8); // 4 hits out of 5 total requests
			expect(stats.entries).toHaveLength(1);
			expect(stats.entries[0]!.hits).toBe(4);
		});

		it('should track multiple tokenizers statistics', () => {
			const config1: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const config2: TokenizerConfig = {
				provider: 'anthropic',
				model: 'claude-3',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			// Access first tokenizer multiple times
			cache.get(config1, mockFactory);
			cache.get(config1, mockFactory);
			cache.get(config1, mockFactory);

			// Access second tokenizer once
			cache.get(config2, mockFactory);

			const stats = cache.getStats();
			expect(stats.cacheSize).toBe(2);
			expect(stats.totalHits).toBe(4); // 3 + 1
			expect(stats.entries).toHaveLength(2);

			// Find entries by hits count
			const firstEntry = stats.entries.find(e => e.hits === 3);
			const secondEntry = stats.entries.find(e => e.hits === 1);

			expect(firstEntry).toBeDefined();
			expect(secondEntry).toBeDefined();
		});

		it('should track last access times', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const beforeTime = Date.now();
			cache.get(config, mockFactory);
			const afterTime = Date.now();

			const stats = cache.getStats();
			expect(stats.entries[0]!.lastAccess).toBeGreaterThanOrEqual(beforeTime);
			expect(stats.entries[0]!.lastAccess).toBeLessThanOrEqual(afterTime);
		});
	});

	describe('Error Handling', () => {
		it('should handle factory function errors gracefully', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const errorFactory = vi.fn(() => {
				throw new Error('Factory error');
			});

			expect(() => cache.get(config, errorFactory)).toThrow('Factory error');
			expect(cache.size()).toBe(0);
			expect(cache.has(config)).toBe(false);
		});

		it('should not cache failed tokenizer creation', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			let shouldFail = true;

			const conditionalFactory = vi.fn((config: TokenizerConfig) => {
				if (shouldFail) {
					throw new Error('Factory error');
				}
				return new MockTokenizer(config.provider, config.model || 'default');
			});

			// First call fails
			expect(() => cache.get(config, conditionalFactory)).toThrow('Factory error');
			expect(cache.size()).toBe(0);

			// Second call succeeds
			shouldFail = false;
			const tokenizer = cache.get(config, conditionalFactory);

			expect(tokenizer).toBeInstanceOf(MockTokenizer);
			expect(cache.size()).toBe(1);
			expect(conditionalFactory).toHaveBeenCalledTimes(2); // Both failed and successful calls
		});
	});

	describe('Thread Safety Simulation', () => {
		it('should handle concurrent access to same config', async () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			// Simulate concurrent access
			const promises = Array.from({ length: 10 }, () =>
				Promise.resolve(cache.get(config, mockFactory))
			);

			const tokenizers = await Promise.all(promises);

			// All should be the same instance
			const firstTokenizer = tokenizers[0];
			tokenizers.forEach(tokenizer => {
				expect(tokenizer).toBe(firstTokenizer);
			});

			// Factory should only be called once
			expect(mockFactory).toHaveBeenCalledTimes(1);
			expect(cache.size()).toBe(1);
		});
	});
});

