describe('Factory Integration with Cache', () => {
	let mockOpenAITokenizer: any;
	let mockAnthropicTokenizer: any;
	let mockGoogleTokenizer: any;
	let mockDefaultTokenizer: any;

	beforeEach(async () => {
		// Clear cache before each test
		const cache = getTokenizerCache();
		cache.clear();
		vi.clearAllMocks();

		// Get mocked constructors
		const openaiModule = await import('../providers/openai.js');
		const anthropicModule = await import('../providers/anthropic.js');
		const googleModule = await import('../providers/google.js');
		const defaultModule = await import('../providers/default.js');

		mockOpenAITokenizer = openaiModule.OpenAITokenizer as any;
		mockAnthropicTokenizer = anthropicModule.AnthropicTokenizer as any;
		mockGoogleTokenizer = googleModule.GoogleTokenizer as any;
		mockDefaultTokenizer = defaultModule.DefaultTokenizer as any;
	});

	afterEach(() => {
		const cache = getTokenizerCache();
		cache.clear();
	});

	describe('createTokenizer with Caching', () => {
		it('should cache tokenizer instances', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const tokenizer1 = createTokenizer(config);
			const tokenizer2 = createTokenizer(config);
			const tokenizer3 = createTokenizer(config);

			// Should return the same instance
			expect(tokenizer1).toBe(tokenizer2);
			expect(tokenizer2).toBe(tokenizer3);

			// Mock constructor should only be called once
			expect(mockOpenAITokenizer).toHaveBeenCalledTimes(1);
			// Config will have defaults applied by schema
			expect(mockOpenAITokenizer).toHaveBeenCalledWith({
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			});
		});

		it('should create different instances for different providers', () => {
			const openaiConfig: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const anthropicConfig: TokenizerConfig = {
				provider: 'anthropic',
				model: 'claude-3',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const openaiTokenizer = createTokenizer(openaiConfig);
			const anthropicTokenizer = createTokenizer(anthropicConfig);

			expect(openaiTokenizer).not.toBe(anthropicTokenizer);
			expect(openaiTokenizer.provider).toBe('openai');
			expect(anthropicTokenizer.provider).toBe('anthropic');

			expect(mockOpenAITokenizer).toHaveBeenCalledTimes(1);
			expect(mockAnthropicTokenizer).toHaveBeenCalledTimes(1);
		});

		it('should create different instances for different models', () => {
			const gpt4Config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			const gpt35Config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-3.5-turbo',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const gpt4Tokenizer = createTokenizer(gpt4Config);
			const gpt35Tokenizer = createTokenizer(gpt35Config);

			expect(gpt4Tokenizer).not.toBe(gpt35Tokenizer);
			expect(gpt4Tokenizer.model).toBe('gpt-4');
			expect(gpt35Tokenizer.model).toBe('gpt-3.5-turbo');

			expect(mockOpenAITokenizer).toHaveBeenCalledTimes(2);
		});

		it('should handle all provider types', () => {
			const providers: Array<TokenizerConfig> = [
				{ provider: 'openai', model: 'gpt-4', fallbackToApproximation: true, hybridTracking: true },
				{
					provider: 'anthropic',
					model: 'claude-3',
					fallbackToApproximation: true,
					hybridTracking: true,
				},
				{
					provider: 'google',
					model: 'gemini-pro',
					fallbackToApproximation: true,
					hybridTracking: true,
				},
				{
					provider: 'default',
					model: 'unknown-model',
					fallbackToApproximation: true,
					hybridTracking: true,
				},
			];

			const tokenizers = providers.map(config => createTokenizer(config));

			// Each should be different
			for (let i = 0; i < tokenizers.length; i++) {
				for (let j = i + 1; j < tokenizers.length; j++) {
					expect(tokenizers[i]).not.toBe(tokenizers[j]);
				}
			}

			// Verify provider-specific behavior
			expect(tokenizers[0]!.provider).toBe('openai');
			expect(tokenizers[1]!.provider).toBe('anthropic');
			expect(tokenizers[2]!.provider).toBe('google');
			expect(tokenizers[3]!.provider).toBe('default');

			// Verify each constructor was called once
			expect(mockOpenAITokenizer).toHaveBeenCalledTimes(1);
			expect(mockAnthropicTokenizer).toHaveBeenCalledTimes(1);
			expect(mockGoogleTokenizer).toHaveBeenCalledTimes(1);
			expect(mockDefaultTokenizer).toHaveBeenCalledTimes(1);
		});
	});

	describe('getTokenizerConfigForModel Integration', () => {
		it('should cache tokenizers created from config recommendations', () => {
			const gptConfig = getTokenizerConfigForModel('gpt-4');
			const claudeConfig = getTokenizerConfigForModel('claude-3-opus');
			const geminiConfig = getTokenizerConfigForModel('gemini-pro');

			// Create tokenizers multiple times
			const gpt1 = createTokenizer(gptConfig);
			const gpt2 = createTokenizer(gptConfig);
			const claude1 = createTokenizer(claudeConfig);
			const claude2 = createTokenizer(claudeConfig);
			const gemini1 = createTokenizer(geminiConfig);
			const gemini2 = createTokenizer(geminiConfig);

			// Should cache same configs
			expect(gpt1).toBe(gpt2);
			expect(claude1).toBe(claude2);
			expect(gemini1).toBe(gemini2);

			// But different providers should be different
			expect(gpt1).not.toBe(claude1);
			expect(claude1).not.toBe(gemini1);
			expect(gpt1).not.toBe(gemini1);
		});

		it('should handle model variations correctly', () => {
			const models = [
				'gpt-4',
				'gpt-4-turbo',
				'gpt-3.5-turbo',
				'claude-3-opus',
				'claude-3-sonnet',
				'gemini-pro',
				'gemini-2.0-flash',
				'unknown-model',
			];

			const configs = models.map(model => getTokenizerConfigForModel(model));
			const tokenizers = configs.map(config => createTokenizer(config));

			// Verify correct provider assignment
			expect(tokenizers[0]!.provider).toBe('openai'); // gpt-4
			expect(tokenizers[1]!.provider).toBe('openai'); // gpt-4-turbo
			expect(tokenizers[2]!.provider).toBe('openai'); // gpt-3.5-turbo
			expect(tokenizers[3]!.provider).toBe('anthropic'); // claude-3-opus
			expect(tokenizers[4]!.provider).toBe('anthropic'); // claude-3-sonnet
			expect(tokenizers[5]!.provider).toBe('google'); // gemini-pro
			expect(tokenizers[6]!.provider).toBe('google'); // gemini-2.0-flash
			expect(tokenizers[7]!.provider).toBe('default'); // unknown-model

			// Verify caching works across different models of same provider
			const gpt4Again = createTokenizer(getTokenizerConfigForModel('gpt-4'));
			expect(gpt4Again).toBe(tokenizers[0]!);
		});
	});

	describe('Performance and Memory', () => {
		it('should demonstrate caching performance benefits', () => {
			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			// Measure time for first creation (cache miss)
			const start1 = performance.now();
			const tokenizer1 = createTokenizer(config);
			const time1 = performance.now() - start1;

			// Measure time for subsequent creations (cache hits)
			const start2 = performance.now();
			const tokenizer2 = createTokenizer(config);
			const time2 = performance.now() - start2;

			const start3 = performance.now();
			const tokenizer3 = createTokenizer(config);
			const time3 = performance.now() - start3;

			// Cache hits should be significantly faster
			expect(tokenizer1).toBe(tokenizer2);
			expect(tokenizer2).toBe(tokenizer3);
			expect(time2).toBeLessThan(time1); // Cache hit should be faster
			expect(time3).toBeLessThan(time1); // Cache hit should be faster

			expect(mockOpenAITokenizer).toHaveBeenCalledTimes(1);
		});

		it('should handle many different configurations efficiently', () => {
			const cache = getTokenizerCache();
			const initialStats = cache.getStats();

			// Create many different tokenizer configurations
			const configs: TokenizerConfig[] = [];
			for (let i = 0; i < 20; i++) {
				configs.push({
					provider: i % 2 === 0 ? 'openai' : 'anthropic',
					model: `model-${i}`,
					fallbackToApproximation: i % 3 === 0,
					hybridTracking: i % 4 === 0,
				});
			}

			// Create tokenizers
			const tokenizers = configs.map(config => createTokenizer(config));

			// Access some tokenizers multiple times to test hit tracking
			createTokenizer(configs[0]!); // Should be cache hit
			createTokenizer(configs[5]!); // Should be cache hit
			createTokenizer(configs[10]!); // Should be cache hit

			const finalStats = cache.getStats();

			expect(finalStats.cacheSize).toBeGreaterThan(initialStats.cacheSize);
			expect(finalStats.totalHits).toBeGreaterThan(3); // At least the 3 repeated accesses
			expect(finalStats.hitRate).toBeGreaterThan(0); // Should have some cache hits

			// Verify all created tokenizers are different
			for (let i = 0; i < tokenizers.length; i++) {
				for (let j = i + 1; j < tokenizers.length; j++) {
					if (JSON.stringify(configs[i]) !== JSON.stringify(configs[j])) {
						expect(tokenizers[i]).not.toBe(tokenizers[j]);
					}
				}
			}
		});
	});

	describe('Error Handling Integration', () => {
		it('should not cache failed tokenizer creation', () => {
			// Clear cache first
			const cache = getTokenizerCache();
			cache.clear();

			// Mock a provider to fail on first call, succeed on second
			let callCount = 0;
			mockOpenAITokenizer.mockImplementation((config: TokenizerConfig) => {
				callCount++;
				if (callCount === 1) {
					throw new Error('Initialization failed');
				}
				return {
					provider: config.provider,
					model: config.model,
					countTokens: vi.fn().mockResolvedValue({
						total: 100,
						characters: 400,
						estimated: false,
						provider: config.provider,
						model: config.model,
					}),
					getMaxTokens: vi.fn().mockReturnValue(4096),
					_mockId: Math.random(),
				};
			});

			const config: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};
			// Use the normalized config with defaults that the cache will use
			const normalizedConfig: TokenizerConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			// First call should fail
			expect(() => createTokenizer(config)).toThrow('Initialization failed');

			// Cache should not contain the failed tokenizer (using normalized config for check)
			expect(cache.has(normalizedConfig)).toBe(false);
			expect(cache.size()).toBe(0);

			// Second call should succeed and be cached
			const tokenizer = createTokenizer(config);
			expect(tokenizer).toBeDefined();
			expect(cache.has(normalizedConfig)).toBe(true);
			expect(cache.size()).toBe(1);

			// Third call should use cache
			const cachedTokenizer = createTokenizer(config);
			expect(cachedTokenizer).toBe(tokenizer);

			// Should have called constructor twice (failed + successful)
			expect(mockOpenAITokenizer).toHaveBeenCalledTimes(2);
		});
	});
});

import { describe, it, expect } from 'vitest';
import { createTokenizer, getTokenizerConfigForModel } from '../factory.js';
import { OpenAITokenizer } from '../providers/openai.js';
import { AnthropicTokenizer } from '../providers/anthropic.js';
import { GoogleTokenizer } from '../providers/google.js';
import { DefaultTokenizer } from '../providers/default.js';
import { TokenizerConfigSchema } from '../types.js';

describe('Tokenizer Factory', () => {
	describe('createTokenizer', () => {
		it('should create OpenAI tokenizer for openai provider', () => {
			const config = {
				provider: 'openai' as const,
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const tokenizer = createTokenizer(config);
			expect(tokenizer).toBeInstanceOf(OpenAITokenizer);
			expect(tokenizer.provider).toBe('openai');
			expect(tokenizer.model).toBe('gpt-4');
		});

		it('should create Anthropic tokenizer for anthropic provider', () => {
			const config = {
				provider: 'anthropic' as const,
				model: 'claude-3-sonnet',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const tokenizer = createTokenizer(config);
			expect(tokenizer).toBeInstanceOf(AnthropicTokenizer);
			expect(tokenizer.provider).toBe('anthropic');
		});

		it('should create Google tokenizer for google provider', () => {
			const config = {
				provider: 'google' as const,
				model: 'gemini-pro',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			const tokenizer = createTokenizer(config);
			expect(tokenizer).toBeInstanceOf(GoogleTokenizer);
			expect(tokenizer.provider).toBe('google');
		});

		it('should create Default tokenizer for default provider', () => {
			const config = {
				provider: 'default' as const,
				model: 'unknown-model',
				fallbackToApproximation: true,
				hybridTracking: false,
			};

			const tokenizer = createTokenizer(config);
			expect(tokenizer).toBeInstanceOf(DefaultTokenizer);
			expect(tokenizer.provider).toBe('default');
		});

		it('should validate config schema', () => {
			const invalidConfig = {
				provider: 'invalid-provider',
				model: 'test-model',
			};

			expect(() => createTokenizer(invalidConfig as any)).toThrow();
		});
	});

	describe('getTokenizerConfigForModel', () => {
		it('should return OpenAI config for GPT models', () => {
			const gptConfig = getTokenizerConfigForModel('gpt-4');
			expect(gptConfig.provider).toBe('openai');
			expect(gptConfig.model).toBe('gpt-4');
			expect(gptConfig.hybridTracking).toBe(true);

			const o1Config = getTokenizerConfigForModel('o1-preview');
			expect(o1Config.provider).toBe('openai');
			expect(o1Config.model).toBe('o1-preview');
		});

		it('should return Anthropic config for Claude models', () => {
			const claudeConfig = getTokenizerConfigForModel('claude-3-sonnet');
			expect(claudeConfig.provider).toBe('anthropic');
			expect(claudeConfig.model).toBe('claude-3-sonnet');
			expect(claudeConfig.hybridTracking).toBe(true);
		});

		it('should return Google config for Gemini models', () => {
			const geminiConfig = getTokenizerConfigForModel('gemini-pro');
			expect(geminiConfig.provider).toBe('google');
			expect(geminiConfig.model).toBe('gemini-pro');
			expect(geminiConfig.hybridTracking).toBe(true);
		});

		it('should return OpenAI config for LM Studio models', () => {
			const llamaConfig = getTokenizerConfigForModel('llama-3.1-8b-instruct');
			expect(llamaConfig.provider).toBe('openai');
			expect(llamaConfig.model).toBe('llama-3.1-8b-instruct');
			expect(llamaConfig.hybridTracking).toBe(true);

			const mistralConfig = getTokenizerConfigForModel('mistral-7b-instruct');
			expect(mistralConfig.provider).toBe('openai');
			expect(mistralConfig.model).toBe('mistral-7b-instruct');
			expect(mistralConfig.hybridTracking).toBe(true);
		});

		it('should return default config for unknown models', () => {
			const unknownConfig = getTokenizerConfigForModel('unknown-model');
			expect(unknownConfig.provider).toBe('default');
			expect(unknownConfig.model).toBe('unknown-model');
			expect(unknownConfig.hybridTracking).toBe(false);
		});
	});

	describe('TokenizerConfigSchema validation', () => {
		it('should validate correct config', () => {
			const validConfig = {
				provider: 'openai',
				model: 'gpt-4',
				fallbackToApproximation: true,
				hybridTracking: true,
			};

			expect(() => TokenizerConfigSchema.parse(validConfig)).not.toThrow();
		});

		it('should apply defaults for optional fields', () => {
			const minimalConfig = {
				provider: 'openai',
			};

			const parsed = TokenizerConfigSchema.parse(minimalConfig);
			expect(parsed.fallbackToApproximation).toBe(true);
			expect(parsed.hybridTracking).toBe(true);
		});

		it('should reject invalid provider', () => {
			const invalidConfig = {
				provider: 'invalid',
			};

			expect(() => TokenizerConfigSchema.parse(invalidConfig)).toThrow();
		});
	});
});

import { ITokenizer, TokenizerConfig } from './types.js';
import { logger } from '../../../logger/index.js';
import crypto from 'crypto';

/**
 * Thread-safe singleton cache for tokenizer instances
 * Prevents redundant tokenizer creation by caching instances based on configuration
 */
export class TokenizerCache {
	private static instance: TokenizerCache | null = null;
	private cache: Map<string, ITokenizer> = new Map();
	private readonly maxCacheSize = 50; // Prevent memory bloat
	private readonly cacheHits = new Map<string, number>();
	private readonly cacheAccess = new Map<string, number>(); // Track access times for LRU

	private constructor() {
		// Private constructor for singleton pattern
	}

	/**
	 * Get the singleton instance of TokenizerCache
	 */
	static getInstance(): TokenizerCache {
		if (!TokenizerCache.instance) {
			TokenizerCache.instance = new TokenizerCache();
		}
		return TokenizerCache.instance;
	}

	/**
	 * Generate a unique cache key based on tokenizer configuration
	 */
	private generateCacheKey(config: TokenizerConfig): string {
		// Create a deterministic hash of the configuration
		const configString = JSON.stringify({
			provider: config.provider,
			model: config.model || 'default',
			fallbackToApproximation: config.fallbackToApproximation,
			hybridTracking: config.hybridTracking,
		});

		// Use a short hash to keep keys manageable
		return crypto.createHash('md5').update(configString).digest('hex').substring(0, 16);
	}

	/**
	 * Get a tokenizer from cache or create new one
	 */
	get(config: TokenizerConfig, factory: (config: TokenizerConfig) => ITokenizer): ITokenizer {
		const cacheKey = this.generateCacheKey(config);

		// Check if tokenizer exists in cache
		if (this.cache.has(cacheKey)) {
			// Update access tracking
			this.cacheHits.set(cacheKey, (this.cacheHits.get(cacheKey) || 0) + 1);
			this.cacheAccess.set(cacheKey, Date.now());

			const tokenizer = this.cache.get(cacheKey)!;
			logger.debug('TokenizerCache: Cache hit', {
				cacheKey,
				provider: config.provider,
				model: config.model,
				totalHits: this.cacheHits.get(cacheKey),
				cacheSize: this.cache.size,
			});

			return tokenizer;
		}

		// Create new tokenizer if not in cache
		logger.debug('TokenizerCache: Cache miss, creating new tokenizer', {
			cacheKey,
			provider: config.provider,
			model: config.model,
			cacheSize: this.cache.size,
		});

		// Manage cache size with LRU eviction BEFORE creating new tokenizer
		if (this.cache.size >= this.maxCacheSize) {
			this.evictLeastRecentlyUsed();
		}

		const tokenizer = factory(config);

		// Store in cache
		this.cache.set(cacheKey, tokenizer);
		this.cacheHits.set(cacheKey, 1);
		this.cacheAccess.set(cacheKey, Date.now());

		logger.debug('TokenizerCache: Tokenizer cached', {
			cacheKey,
			provider: config.provider,
			model: config.model,
			cacheSize: this.cache.size,
		});

		return tokenizer;
	}

	/**
	 * Evict the least recently used tokenizer from cache
	 */
	private evictLeastRecentlyUsed(): void {
		let oldestKey: string | null = null;
		let oldestTime = Date.now();

		for (const [key, accessTime] of this.cacheAccess) {
			if (accessTime < oldestTime) {
				oldestTime = accessTime;
				oldestKey = key;
			}
		}

		if (oldestKey) {
			logger.debug('TokenizerCache: Evicting LRU tokenizer', {
				evictedKey: oldestKey,
				cacheSize: this.cache.size,
			});

			this.cache.delete(oldestKey);
			this.cacheHits.delete(oldestKey);
			this.cacheAccess.delete(oldestKey);
		}
	}

	/**
	 * Clear specific tokenizer from cache
	 */
	invalidate(config: TokenizerConfig): boolean {
		const cacheKey = this.generateCacheKey(config);
		const removed = this.cache.delete(cacheKey);

		if (removed) {
			this.cacheHits.delete(cacheKey);
			this.cacheAccess.delete(cacheKey);

			logger.debug('TokenizerCache: Tokenizer invalidated', {
				cacheKey,
				provider: config.provider,
				model: config.model,
			});
		}

		return removed;
	}

	/**
	 * Clear all cached tokenizers
	 */
	clear(): void {
		const size = this.cache.size;
		this.cache.clear();
		this.cacheHits.clear();
		this.cacheAccess.clear();

		logger.debug('TokenizerCache: All tokenizers cleared', {
			previousSize: size,
		});
	}

	/**
	 * Get cache statistics for monitoring
	 */
	getStats(): {
		cacheSize: number;
		maxCacheSize: number;
		totalHits: number;
		hitRate: number;
		entries: Array<{
			key: string;
			hits: number;
			lastAccess: number;
		}>;
	} {
		const totalHits = Array.from(this.cacheHits.values()).reduce((sum, hits) => sum + hits, 0);
		const totalRequests = totalHits + (this.cache.size > 0 ? this.cache.size : 1); // Avoid division by zero

		const entries = Array.from(this.cache.keys()).map(key => ({
			key,
			hits: this.cacheHits.get(key) || 0,
			lastAccess: this.cacheAccess.get(key) || 0,
		}));

		return {
			cacheSize: this.cache.size,
			maxCacheSize: this.maxCacheSize,
			totalHits,
			hitRate: totalHits / totalRequests,
			entries,
		};
	}

	/**
	 * Check if a tokenizer is cached
	 */
	has(config: TokenizerConfig): boolean {
		const cacheKey = this.generateCacheKey(config);
		return this.cache.has(cacheKey);
	}

	/**
	 * Get current cache size
	 */
	size(): number {
		return this.cache.size;
	}
}

/**
 * Convenience function to get the global tokenizer cache instance
 */
export const getTokenizerCache = (): TokenizerCache => {
	return TokenizerCache.getInstance();
};

import { ITokenizer, TokenizerConfigSchema, TokenizerConfig } from './types.js';
import { OpenAITokenizer } from './providers/openai.js';
import { AnthropicTokenizer } from './providers/anthropic.js';
import { GoogleTokenizer } from './providers/google.js';
import { DefaultTokenizer } from './providers/default.js';
import { logger } from '../../../logger/index.js';
import { getTokenizerCache } from './cache.js';

/**
 * Create a tokenizer instance based on provider configuration
 * Uses caching to avoid redundant tokenizer creation
 */
export function createTokenizer(config: TokenizerConfig): ITokenizer {
	const validatedConfig = TokenizerConfigSchema.parse(config);

	// Use cache to get or create tokenizer
	const cache = getTokenizerCache();
	return cache.get(validatedConfig, config => {
		logger.debug('Creating tokenizer', {
			provider: config.provider,
			model: config.model,
		});

		switch (config.provider) {
			case 'openai':
				return new OpenAITokenizer(config);
			case 'anthropic':
				return new AnthropicTokenizer(config);
			case 'google':
				return new GoogleTokenizer(config);
			case 'default':
			default:
				logger.warn('Using default tokenizer, token counting may be less accurate');
				return new DefaultTokenizer(config);
		}
	});
}

/**
 * Get recommended tokenizer config for a given model
 */
export function getTokenizerConfigForModel(model: string): TokenizerConfig {
	if (model.startsWith('gpt-') || model.startsWith('o1-') || model.includes('openai')) {
		return {
			provider: 'openai',
			model,
			fallbackToApproximation: true,
			hybridTracking: true,
		};
	}

	if (model.startsWith('claude-') || model.includes('anthropic')) {
		return {
			provider: 'anthropic',
			model,
			fallbackToApproximation: true,
			hybridTracking: true,
		};
	}

	if (model.startsWith('gemini-') || model.includes('google')) {
		return {
			provider: 'google',
			model,
			fallbackToApproximation: true,
			hybridTracking: true,
		};
	}

	if (model.startsWith('qwen') || model.includes('qwen')) {
		return {
			provider: 'openai', // Qwen uses OpenAI-compatible tokenization
			model,
			fallbackToApproximation: true,
			hybridTracking: true,
		};
	}

	// LM Studio models use OpenAI-compatible tokenization
	if (model.includes('lmstudio') || model.includes('llama') || model.includes('mistral')) {
		return {
			provider: 'openai', // LM Studio uses OpenAI-compatible tokenization
			model,
			fallbackToApproximation: true,
			hybridTracking: true,
		};
	}

	return {
		provider: 'default',
		model,
		fallbackToApproximation: true,
		hybridTracking: false,
	};
}

// Tokenizer module exports
export * from './types.js';
export * from './factory.js';
export * from './utils.js';
export * from './cache.js';

// Provider exports
export { OpenAITokenizer } from './providers/openai.js';
export { AnthropicTokenizer } from './providers/anthropic.js';
export { GoogleTokenizer } from './providers/google.js';
export { DefaultTokenizer } from './providers/default.js';

import { ITokenizer, TokenCount, ProviderTokenLimits, TokenizerConfig } from '../types.js';
import { estimateTokensFromText, logTokenCount } from '../utils.js';
import { logger } from '../../../../logger/index.js';

/**
 * Anthropic tokenizer using 4-chars-per-token approximation
 * Supports Claude models including Claude-3 series
 */
export class AnthropicTokenizer implements ITokenizer {
	public readonly provider = 'anthropic';
	public readonly model: string;

	private config: TokenizerConfig;
	private tokenLimits: ProviderTokenLimits;
	private tokencountflag: boolean = false;

	// Calibrated token density for this provider
	private avgTokenDensity = 0.25; // 4 chars per token

	constructor(config: TokenizerConfig) {
		this.config = config;
		this.model = config.model ?? 'claude-default';
		this.tokenLimits = this.getTokenLimitsForModel(config.model || 'claude-3-sonnet');

		logger.debug('Anthropic tokenizer initialized', { model: this.model });
	}

	private getTokenLimitsForModel(model: string): ProviderTokenLimits {
		const limits: Record<string, ProviderTokenLimits> = {
			'claude-3-opus': { maxTokens: 4096, contextWindow: 200000 },
			'claude-3-sonnet': { maxTokens: 4096, contextWindow: 200000 },
			'claude-3-haiku': { maxTokens: 4096, contextWindow: 200000 },
			'claude-3-5-sonnet': { maxTokens: 8192, contextWindow: 200000 },
			'claude-2.1': { maxTokens: 4096, contextWindow: 200000 },
			'claude-2.0': { maxTokens: 4096, contextWindow: 100000 },
			'claude-instant-1.2': { maxTokens: 4096, contextWindow: 100000 },
		};

		return limits[model] || { maxTokens: 4096, contextWindow: 200000 };
	}

	async countTokens(text: string): Promise<TokenCount> {
		if (!text) {
			return {
				total: 0,
				characters: 0,
				estimated: true,
				provider: this.provider,
				model: this.model,
			};
		}

		// Use enhanced approximation for Anthropic models
		const tokenCount = this.estimateTokensWithCalibration(text);

		const count: TokenCount = {
			total: tokenCount,
			characters: text.length,
			estimated: true,
			provider: this.provider,
			model: this.model,
		};
		if (!this.tokencountflag) {
			logTokenCount('anthropic', count);
			this.tokencountflag = true;
		}
		return count;
	}

	async countMessages(messages: Array<{ role: string; content: string }>): Promise<TokenCount> {
		let totalTokens = 0;
		let totalCharacters = 0;

		for (const message of messages) {
			// Add tokens for role and formatting
			const roleText = `${message.role}: `;
			const roleTokens = await this.countTokens(roleText);
			const contentTokens = await this.countTokens(message.content);

			totalTokens += roleTokens.total + contentTokens.total + 2; // 2 tokens for message formatting
			totalCharacters += roleTokens.characters + contentTokens.characters;
		}

		// Add tokens for conversation formatting (Claude uses different formatting)
		totalTokens += 5; // 5 tokens for conversation start/formatting

		return {
			total: totalTokens,
			characters: totalCharacters,
			estimated: true,
			provider: this.provider,
			model: this.model,
		};
	}

	getMaxTokens(): number {
		return this.tokenLimits.maxTokens;
	}

	getContextWindow(): number {
		return this.tokenLimits.contextWindow;
	}

	estimateTokens(text: string): number {
		return this.estimateTokensWithCalibration(text);
	}

	private estimateTokensWithCalibration(text: string): number {
		if (!text) return 0;

		// Enhanced estimation for Claude models
		// Claude tends to be more efficient with natural language
		// but similar to GPT models for code

		const baseEstimate = estimateTokensFromText(text);

		// Adjust for Claude's tokenization characteristics
		let adjustment = 1.0;

		// Natural language tends to be more efficient in Claude
		const codePatterns = /[{}()[\];=><]/g;
		const codeMatches = text.match(codePatterns)?.length || 0;
		const codeRatio = codeMatches / text.length;

		if (codeRatio < 0.01) {
			// Mostly natural language - Claude is slightly more efficient
			adjustment = 0.95;
		} else if (codeRatio > 0.05) {
			// Code-heavy content
			adjustment = 1.05;
		}

		// Apply provider-specific density
		const charBasedEstimate = Math.ceil(text.length * this.avgTokenDensity * adjustment);

		// Return the more conservative estimate
		return Math.max(baseEstimate, charBasedEstimate);
	}

	isWithinLimit(tokenCount: number): boolean {
		return tokenCount <= this.tokenLimits.contextWindow;
	}

	getRemainingTokens(currentCount: number): number {
		return Math.max(0, this.tokenLimits.contextWindow - currentCount);
	}

	/**
	 * Update token density based on actual API responses
	 * This can be called when actual token usage is known from API responses
	 */
	calibrateDensity(text: string, actualTokens: number): void {
		if (text && actualTokens > 0) {
			const actualDensity = actualTokens / text.length;

			// Exponential moving average for calibration
			const alpha = 0.1;
			this.avgTokenDensity = alpha * actualDensity + (1 - alpha) * this.avgTokenDensity;

			logger.debug('Anthropic tokenizer density calibrated', {
				actualDensity,
				newAvgDensity: this.avgTokenDensity,
				textLength: text.length,
				actualTokens,
			});
		}
	}

	/**
	 * Get current calibrated token density
	 */
	getTokenDensity(): number {
		return this.avgTokenDensity;
	}

	/**
	 * Reset density to default
	 */
	resetCalibration(): void {
		this.avgTokenDensity = 0.25; // Reset to default 4 chars per token
	}
}

import { ITokenizer, TokenCount, ProviderTokenLimits, TokenizerConfig } from '../types.js';
import { estimateTokensFromText, logTokenCount } from '../utils.js';
import { logger } from '../../../../logger/index.js';

/**
 * Default tokenizer for unknown or unsupported providers
 * Uses conservative character-based approximation
 */
export class DefaultTokenizer implements ITokenizer {
	public readonly provider = 'default';
	public readonly model: string;

	private config: TokenizerConfig;
	private tokenLimits: ProviderTokenLimits;
	private tokencountflag: boolean = false;
	// Conservative token density
	private avgTokenDensity = 0.3; // ~3.3 chars per token (conservative)

	constructor(config: TokenizerConfig) {
		this.config = config;
		this.model = config.model ?? 'default-model';
		this.tokenLimits = this.getDefaultTokenLimits();

		logger.debug('Default tokenizer initialized', { model: this.model });
	}

	private getDefaultTokenLimits(): ProviderTokenLimits {
		// Conservative defaults for unknown models
		return {
			maxTokens: 4096,
			contextWindow: 8192,
		};
	}

	async countTokens(text: string): Promise<TokenCount> {
		if (!text) {
			return {
				total: 0,
				characters: 0,
				estimated: true,
				provider: this.provider,
				model: this.model,
			};
		}

		// Use conservative approximation
		const tokenCount = this.estimateTokensConservatively(text);

		const count: TokenCount = {
			total: tokenCount,
			characters: text.length,
			estimated: true,
			provider: this.provider,
			model: this.model,
		};
		if (!this.tokencountflag) {
			logTokenCount('default', count);
			this.tokencountflag = true;
		}
		return count;
	}

	async countMessages(messages: Array<{ role: string; content: string }>): Promise<TokenCount> {
		let totalTokens = 0;
		let totalCharacters = 0;

		for (const message of messages) {
			// Conservative estimation for role and formatting
			const roleText = `${message.role}: `;
			const roleTokens = await this.countTokens(roleText);
			const contentTokens = await this.countTokens(message.content);

			// Add extra tokens for unknown formatting overhead
			totalTokens += roleTokens.total + contentTokens.total + 5; // 5 tokens for conservative message formatting
			totalCharacters += roleTokens.characters + contentTokens.characters;
		}

		// Add conservative tokens for conversation formatting
		totalTokens += 10; // 10 tokens for conservative conversation formatting

		return {
			total: totalTokens,
			characters: totalCharacters,
			estimated: true,
			provider: this.provider,
			model: this.model,
		};
	}

	getMaxTokens(): number {
		return this.tokenLimits.maxTokens;
	}

	getContextWindow(): number {
		return this.tokenLimits.contextWindow;
	}

	estimateTokens(text: string): number {
		return this.estimateTokensConservatively(text);
	}

	private estimateTokensConservatively(text: string): number {
		if (!text) return 0;

		// Very conservative estimation for unknown models
		const baseEstimate = estimateTokensFromText(text);

		// Apply conservative multiplier to avoid underestimation
		const conservativeMultiplier = 1.25; // 25% safety margin

		// Character-based estimation with conservative density
		const charBasedEstimate = Math.ceil(text.length * this.avgTokenDensity);

		// Return the higher of the two estimates (more conservative)
		const finalEstimate = Math.max(
			Math.ceil(baseEstimate * conservativeMultiplier),
			charBasedEstimate
		);

		return finalEstimate;
	}

	isWithinLimit(tokenCount: number): boolean {
		return tokenCount <= this.tokenLimits.contextWindow;
	}

	getRemainingTokens(currentCount: number): number {
		return Math.max(0, this.tokenLimits.contextWindow - currentCount);
	}

	/**
	 * Update token limits for better model support
	 */
	updateTokenLimits(limits: Partial<ProviderTokenLimits>): void {
		this.tokenLimits = {
			...this.tokenLimits,
			...limits,
		};

		logger.debug('Default tokenizer limits updated', this.tokenLimits);
	}

	/**
	 * Update token density based on observed behavior
	 */
	calibrateDensity(text: string, actualTokens: number): void {
		if (text && actualTokens > 0) {
			const actualDensity = actualTokens / text.length;

			// More conservative calibration for unknown models
			const alpha = 0.05; // Slower adaptation
			this.avgTokenDensity = alpha * actualDensity + (1 - alpha) * this.avgTokenDensity;

			// Ensure we don't go below a minimum conservative density
			this.avgTokenDensity = Math.max(this.avgTokenDensity, 0.2); // At least 5 chars per token

			logger.debug('Default tokenizer density calibrated', {
				actualDensity,
				newAvgDensity: this.avgTokenDensity,
				textLength: text.length,
				actualTokens,
			});
		}
	}

	/**
	 * Get current calibrated token density
	 */
	getTokenDensity(): number {
		return this.avgTokenDensity;
	}

	/**
	 * Reset density to default
	 */
	resetCalibration(): void {
		this.avgTokenDensity = 0.3; // Reset to conservative default
	}

	/**
	 * Set model-specific limits if known
	 */
	setModelLimits(model: string, limits: ProviderTokenLimits): void {
		this.tokenLimits = limits;
		logger.debug('Default tokenizer configured for specific model', { model, limits });
	}
}

import { ITokenizer, TokenCount, ProviderTokenLimits, TokenizerConfig } from '../types.js';
import { estimateTokensFromText, logTokenCount } from '../utils.js';
import { logger } from '../../../../logger/index.js';

/**
 * Google (Gemini) tokenizer using 4-chars-per-token approximation
 * Supports Gemini models including Gemini Pro and Ultra
 */
export class GoogleTokenizer implements ITokenizer {
	public readonly provider = 'google';
	public readonly model: string;

	private config: TokenizerConfig;
	private tokenLimits: ProviderTokenLimits;
	private tokencountflag: boolean = false;
	// Calibrated token density for Google models
	private avgTokenDensity = 0.28; // Slightly higher than other providers

	constructor(config: TokenizerConfig) {
		this.config = config;
		this.model = config.model ?? 'gemini-default';
		this.tokenLimits = this.getTokenLimitsForModel(config.model || 'gemini-pro');

		logger.debug('Google tokenizer initialized', { model: this.model });
	}

	private getTokenLimitsForModel(model: string): ProviderTokenLimits {
		const limits: Record<string, ProviderTokenLimits> = {
			'gemini-pro': { maxTokens: 8192, contextWindow: 32760 },
			'gemini-pro-vision': { maxTokens: 4096, contextWindow: 16384 },
			'gemini-ultra': { maxTokens: 8192, contextWindow: 32760 },
			'gemini-1.5-pro': { maxTokens: 8192, contextWindow: 1000000 }, // 1M token context
			'gemini-1.5-flash': { maxTokens: 8192, contextWindow: 1000000 },
		};

		return limits[model] || { maxTokens: 8192, contextWindow: 32760 };
	}

	async countTokens(text: string): Promise<TokenCount> {
		if (!text) {
			return {
				total: 0,
				characters: 0,
				estimated: true,
				provider: this.provider,
				model: this.model,
			};
		}

		// Use enhanced approximation for Google models
		const tokenCount = this.estimateTokensWithCalibration(text);

		const count: TokenCount = {
			total: tokenCount,
			characters: text.length,
			estimated: true,
			provider: this.provider,
			model: this.model,
		};
		if (!this.tokencountflag) {
			logTokenCount('google', count);
			this.tokencountflag = true;
		}
		return count;
	}

	async countMessages(messages: Array<{ role: string; content: string }>): Promise<TokenCount> {
		let totalTokens = 0;
		let totalCharacters = 0;

		for (const message of messages) {
			// Google uses different role formatting
			const roleMapping = this.mapRoleForGoogle(message.role);
			const roleText = `${roleMapping}: `;

			const roleTokens = await this.countTokens(roleText);
			const contentTokens = await this.countTokens(message.content);

			totalTokens += roleTokens.total + contentTokens.total + 3; // 3 tokens for message formatting
			totalCharacters += roleTokens.characters + contentTokens.characters;
		}

		// Add tokens for conversation formatting
		totalTokens += 4; // 4 tokens for conversation start/formatting

		return {
			total: totalTokens,
			characters: totalCharacters,
			estimated: true,
			provider: this.provider,
			model: this.model,
		};
	}

	private mapRoleForGoogle(role: string): string {
		// Google uses different role names
		const roleMap: Record<string, string> = {
			user: 'user',
			assistant: 'model',
			system: 'user', // Google doesn't have explicit system role
			tool: 'function',
		};

		return roleMap[role] || role;
	}

	getMaxTokens(): number {
		return this.tokenLimits.maxTokens;
	}

	getContextWindow(): number {
		return this.tokenLimits.contextWindow;
	}

	estimateTokens(text: string): number {
		return this.estimateTokensWithCalibration(text);
	}

	private estimateTokensWithCalibration(text: string): number {
		if (!text) return 0;

		// Enhanced estimation for Gemini models
		// Gemini tends to be slightly less efficient than GPT models
		// but handles multilingual content well

		const baseEstimate = estimateTokensFromText(text);

		// Adjust for Gemini's tokenization characteristics
		let adjustment = 1.1; // Gemini tends to use slightly more tokens

		// Check for non-English content (Gemini handles this well)
		// const nonAsciiCount = Array.from(text).filter(c => c.charCodeAt(0) > 127).length;
		// const nonAsciiRatio = nonAsciiCount / text.length;

		// Check for structured content (JSON, XML, etc.)
		const structuredPatterns = /[{}"':,\]<>]/g;
		const structuredMatches = text.match(structuredPatterns)?.length || 0;
		const structuredRatio = structuredMatches / text.length;

		if (structuredRatio > 0.1) {
			// Structured content - Gemini uses more tokens
			adjustment = 1.15;
		}

		// Apply provider-specific density
		const charBasedEstimate = Math.ceil(text.length * this.avgTokenDensity * adjustment);

		// Return the more conservative estimate
		return Math.max(baseEstimate, charBasedEstimate);
	}

	isWithinLimit(tokenCount: number): boolean {
		return tokenCount <= this.tokenLimits.contextWindow;
	}

	getRemainingTokens(currentCount: number): number {
		return Math.max(0, this.tokenLimits.contextWindow - currentCount);
	}

	/**
	 * Update token density based on actual API responses
	 */
	calibrateDensity(text: string, actualTokens: number): void {
		if (text && actualTokens > 0) {
			const actualDensity = actualTokens / text.length;

			// Exponential moving average for calibration
			const alpha = 0.1;
			this.avgTokenDensity = alpha * actualDensity + (1 - alpha) * this.avgTokenDensity;

			logger.debug('Google tokenizer density calibrated', {
				actualDensity,
				newAvgDensity: this.avgTokenDensity,
				textLength: text.length,
				actualTokens,
			});
		}
	}

	/**
	 * Get current calibrated token density
	 */
	getTokenDensity(): number {
		return this.avgTokenDensity;
	}

	/**
	 * Reset density to default
	 */
	resetCalibration(): void {
		this.avgTokenDensity = 0.28; // Reset to default for Google models
	}

	/**
	 * Check if model supports very large context windows
	 */
	isLargeContextModel(): boolean {
		return this.model?.includes('1.5') || false;
	}
}

import { ITokenizer, TokenCount, ProviderTokenLimits, TokenizerConfig } from '../types.js';
import { estimateTokensFromText, createFallbackTokenCount, logTokenCount } from '../utils.js';
import { logger } from '../../../../logger/index.js';

/**
 * OpenAI tokenizer using tiktoken for accurate token counting
 * Supports GPT models including GPT-3.5, GPT-4, and o1 series
 */
export class OpenAITokenizer implements ITokenizer {
	public readonly provider = 'openai';
	public readonly model: string;

	private config: TokenizerConfig;
	private tokenLimits: ProviderTokenLimits;
	private tiktoken: any = null;
	private encoding: any = null;
	private tiktokencountflag: boolean = false;
	private approximationcountflag: boolean = false;

	// Token density calibration for hybrid tracking
	private densityHistory: number[] = [];
	private maxHistorySize = 100;

	constructor(config: TokenizerConfig) {
		this.config = config;
		this.model = config.model ?? 'gpt-3.5-turbo';
		this.tokenLimits = this.getTokenLimitsForModel(config.model || 'gpt-3.5-turbo');

		// Initialize tiktoken if available
		this.initializeTiktoken();
	}

	private async initializeTiktoken(): Promise<void> {
		try {
			// Use dynamic import instead of eval to avoid bundler warnings
			const tiktokenModule = await import('tiktoken').catch(() => null);

			if (!tiktokenModule) {
				logger.warn('tiktoken not available, using approximation');
				return;
			}

			this.tiktoken = tiktokenModule;

			const modelName = this.model || 'gpt-3.5-turbo';

			// Get encoding for the specific model
			try {
				if (this.isO1Model(modelName)) {
					// o1 models use o200k_base encoding
					this.encoding = this.tiktoken.encoding_for_model('gpt-4o');
				} else if (this.isQwenModel(modelName)) {
					// Qwen models use cl100k_base encoding (same as GPT-4)
					this.encoding = this.tiktoken.encoding_for_model('gpt-4');
				} else {
					this.encoding = this.tiktoken.encoding_for_model(modelName);
				}
			} catch (encodingError) {
				// If the specific model encoding fails, try with a fallback
				logger.debug('Failed to get encoding for specific model, trying fallback', {
					model: modelName,
					error: (encodingError as Error).message,
				});

				// Use gpt-4 encoding as fallback for most models
				this.encoding = this.tiktoken.encoding_for_model('gpt-4');
			}

			logger.debug('OpenAI tokenizer initialized with tiktoken', { model: modelName });
		} catch (error) {
			logger.warn('Failed to initialize tiktoken, falling back to approximation', {
				error: (error as Error).message,
			});
			this.tiktoken = null;
			this.encoding = null;
		}
	}

	private isO1Model(model: string): boolean {
		return model.startsWith('o1-');
	}

	private isQwenModel(model: string): boolean {
		return model.startsWith('qwen') || model.includes('qwen');
	}

	private getTokenLimitsForModel(model: string): ProviderTokenLimits {
		const limits: Record<string, ProviderTokenLimits> = {
			'gpt-3.5-turbo': { maxTokens: 4096, contextWindow: 16385 },
			'gpt-3.5-turbo-16k': { maxTokens: 4096, contextWindow: 16385 },
			'gpt-4': { maxTokens: 4096, contextWindow: 8192 },
			'gpt-4-32k': { maxTokens: 4096, contextWindow: 32768 },
			'gpt-4-turbo': { maxTokens: 4096, contextWindow: 128000 },
			'gpt-4o': { maxTokens: 4096, contextWindow: 128000 },
			'gpt-4o-mini': { maxTokens: 16384, contextWindow: 128000 },
			'o1-preview': { maxTokens: 32768, contextWindow: 128000 },
			'o1-mini': { maxTokens: 65536, contextWindow: 128000 },
		};

		return limits[model] || { maxTokens: 4096, contextWindow: 8192 };
	}

	async countTokens(text: string): Promise<TokenCount> {
		if (!text) {
			return {
				total: 0,
				characters: 0,
				estimated: false,
				provider: this.provider,
				model: this.model,
			};
		}

		try {
			if (this.encoding) {
				// Use tiktoken for accurate counting
				const tokens = this.encoding.encode(text);
				const count: TokenCount = {
					total: tokens.length,
					characters: text.length,
					estimated: false,
					provider: this.provider,
					model: this.model,
				};

				// Update density history for hybrid tracking
				if (this.config.hybridTracking) {
					this.updateDensityHistory(text.length, tokens.length);
				}
				if (!this.tiktokencountflag) {
					logTokenCount('tiktoken count', count);
					this.tiktokencountflag = true;
				}
				return count;
			} else {
				// Fallback to approximation
				const estimated = this.estimateTokens(text);
				const count = createFallbackTokenCount(text, this.provider, this.model);
				count.total = estimated;
				if (!this.approximationcountflag) {
					logTokenCount('openai approximation', count);
					this.approximationcountflag = true;
				}
				return count;
			}
		} catch (error) {
			logger.warn('Error in OpenAI token counting, falling back to approximation', {
				error: (error as Error).message,
			});

			const estimated = this.estimateTokens(text);
			const count = createFallbackTokenCount(text, this.provider, this.model);
			count.total = estimated;

			return count;
		}
	}

	async countMessages(messages: Array<{ role: string; content: string }>): Promise<TokenCount> {
		let totalTokens = 0;
		let totalCharacters = 0;
		let isEstimated = false;

		for (const message of messages) {
			// Add tokens for role and formatting
			const roleTokens = await this.countTokens(`${message.role}: `);
			const contentTokens = await this.countTokens(message.content);

			totalTokens += roleTokens.total + contentTokens.total + 3; // 3 tokens for message formatting
			totalCharacters += roleTokens.characters + contentTokens.characters;

			if (roleTokens.estimated || contentTokens.estimated) {
				isEstimated = true;
			}
		}

		// Add tokens for conversation formatting
		totalTokens += 3; // 3 tokens for conversation start

		return {
			total: totalTokens,
			characters: totalCharacters,
			estimated: isEstimated,
			provider: this.provider,
			model: this.model,
		};
	}

	getMaxTokens(): number {
		return this.tokenLimits.maxTokens;
	}

	getContextWindow(): number {
		return this.tokenLimits.contextWindow;
	}

	estimateTokens(text: string): number {
		if (this.config.hybridTracking && this.densityHistory.length > 0) {
			// Use calibrated density from previous actual counts
			const avgDensity =
				this.densityHistory.reduce((a, b) => a + b, 0) / this.densityHistory.length;
			return Math.ceil(text.length * avgDensity);
		}

		return estimateTokensFromText(text);
	}

	isWithinLimit(tokenCount: number): boolean {
		return tokenCount <= this.tokenLimits.contextWindow;
	}

	getRemainingTokens(currentCount: number): number {
		return Math.max(0, this.tokenLimits.contextWindow - currentCount);
	}

	private updateDensityHistory(characters: number, tokens: number): void {
		if (characters > 0 && tokens > 0) {
			const density = tokens / characters;
			this.densityHistory.push(density);

			// Keep only recent history
			if (this.densityHistory.length > this.maxHistorySize) {
				this.densityHistory.shift();
			}
		}
	}

	/**
	 * Get current calibrated token density
	 */
	getTokenDensity(): number {
		if (this.densityHistory.length === 0) {
			return 0.25; // Default for OpenAI models
		}

		return this.densityHistory.reduce((a, b) => a + b, 0) / this.densityHistory.length;
	}

	/**
	 * Reset density calibration
	 */
	resetCalibration(): void {
		this.densityHistory = [];
	}
}

import { z } from 'zod';

export const TokenizerConfigSchema = z.object({
	provider: z.enum(['openai', 'anthropic', 'google', 'default']),
	model: z.string().optional(),
	fallbackToApproximation: z.boolean().default(true),
	hybridTracking: z.boolean().default(true),
});

export type TokenizerConfig = z.infer<typeof TokenizerConfigSchema>;

export interface ProviderTokenLimits {
	maxTokens: number;
	contextWindow: number;
	outputTokens?: number;
}
export interface TokenCount {
	total: number;
	characters: number;
	estimated: boolean;
	provider: string;
	model: string;
}

export interface ITokenizer {
	provider: string;
	model: string;

	countTokens(text: string): Promise<TokenCount>;
	countMessages(messages: Array<{ role: string; content: string }>): Promise<TokenCount>;

	getMaxTokens(): number;
	getContextWindow(): number;

	estimateTokens(text: string): number;
	isWithinLimit(tokenCount: number): boolean;
	getRemainingTokens(currentCount: number): number;
}

import { TokenCount } from './types.js';
import { InternalMessage } from '../messages/types.js';
import { logger } from '../../../logger/index.js';

/**
 * Extract text content from various message content formats
 */
export function extractTextFromMessage(message: InternalMessage): string {
	if (typeof message.content === 'string') {
		return message.content;
	}

	if (Array.isArray(message.content)) {
		return message.content
			.filter(part => part.type === 'text')
			.map(part => part.text)
			.join(' ');
	}

	return '';
}

/**
 * Calculate approximate token count using character-based estimation
 * Uses the common approximation of 4 characters per token for English text
 */
export function estimateTokensFromText(text: string): number {
	if (!text) return 0;

	// More sophisticated estimation that accounts for:
	// - Average English word length
	// - Punctuation and whitespace
	// - Code vs natural language patterns

	const words = text.split(/\s+/).filter(word => word.length > 0);
	const avgCharsPerToken = 4;

	// Adjust for different content types
	let adjustment = 1.0;

	// Code-like content (lots of symbols, shorter words)
	if (text.includes('{') && text.includes('}') && text.includes(';')) {
		adjustment = 0.8; // Code tends to have more tokens per character
	}

	// Very short words (common in code/structured data)
	const avgWordLength = words.reduce((sum, word) => sum + word.length, 0) / (words.length || 1);
	if (avgWordLength < 3) {
		adjustment = 0.7;
	}

	return Math.ceil((text.length / avgCharsPerToken) * adjustment);
}

/**
 * Combine multiple token counts
 */
export function combineTokenCounts(counts: TokenCount[]): TokenCount {
	if (counts.length === 0) {
		return {
			total: 0,
			characters: 0,
			estimated: true,
			provider: 'unknown',
			model: 'unknown',
		};
	}

	const combined: TokenCount = counts.reduce(
		(acc, count) => ({
			total: acc.total + count.total,
			characters: acc.characters + count.characters,
			estimated: acc.estimated || count.estimated,
			provider: acc.provider || count.provider,
			model: acc.model || count.model,
		}),
		{
			total: 0,
			characters: 0,
			estimated: false,
			provider: '',
			model: '',
		}
	);

	return combined;
}

/**
 * Format token count for logging
 */
export function formatTokenCount(count: TokenCount): string {
	const estimated = count.estimated ? ' (estimated)' : '';
	const model = count.model ? ` [${count.model}]` : '';
	return `${count.total} tokens${estimated}${model}`;
}

/**
 * Calculate token density (tokens per character) for calibration
 */
export function calculateTokenDensity(text: string, actualTokens: number): number {
	if (!text || actualTokens <= 0) return 0.25; // Default density
	return actualTokens / text.length;
}

/**
 * Validate token count result
 */
export function validateTokenCount(count: TokenCount): boolean {
	return (
		typeof count.total === 'number' &&
		count.total >= 0 &&
		typeof count.characters === 'number' &&
		count.characters >= 0 &&
		typeof count.estimated === 'boolean' &&
		typeof count.provider === 'string' &&
		count.provider.length > 0
	);
}

/**
 * Create a basic token count for fallback scenarios
 */
export function createFallbackTokenCount(
	text: string,
	provider: string,
	model: string = 'unknown'
): TokenCount {
	const estimated = estimateTokensFromText(text);
	return {
		total: estimated,
		characters: text.length,
		estimated: true,
		provider,
		model,
	};
}

/**
 * Log token counting operation
 */
export function logTokenCount(operation: string, count: TokenCount, context?: any): void {
	logger.info(`Token counting: ${operation}`, {
		...count,
		formatted: formatTokenCount(count),
		...context,
	});
}

import chalk from 'chalk';
import { logger } from '../../../logger/index.js';
// import { KnowledgeGraph } from '@core/index.js';

/**
 * Tool Result Formatter
 *
 * This utility formats different types of tool results in a visually appealing way
 * for display to the user, replacing the raw JSON output with clean, readable formatting.
 */

interface MemorySearchResult {
	success: boolean;
	query: string;
	error?: string;
	results: Array<{
		id: string;
		text: string;
		tags: string[];
		timestamp: string;
		similarity: number;
		source: string;
		memoryType: string;
		confidence?: number;
		domain?: string;
	}>;
	metadata: {
		totalResults: number;
		searchTime: number;
		maxSimilarity: number;
		minSimilarity: number;
		averageSimilarity: number;
		usedFallback?: boolean;
	};
}

interface KnowledgeGraphResult {
	success: boolean;
	error?: string;
	nodes?: Array<{
		id: string;
		name: string;
		type?: string;
		properties?: Record<string, any>;
		score?: number;
		matchReason?: string;
	}>;
	edges?: Array<{
		id: string;
		type: string;
		source: string;
		target: string;
		properties?: Record<string, any>;
		score?: number;
	}>;
	related?: Array<{
		entity: any;
		relationship: any;
		distance: number;
	}>;
	totalCount?: number;
	executionTime?: number;
	message?: string;
}

interface ReasoningResult {
	success: boolean;
	error?: string;
	steps?: Array<{
		type: string;
		content: string;
	}>;
	evaluation?: {
		qualityScore: number;
		issues: Array<{
			type: string;
			description: string;
			severity?: string;
		}>;
		suggestions: string[];
	};
	trace?: any;
	patterns?: Array<{
		id: string;
		similarity: number;
		context: string;
		steps: Array<{
			type: string;
			content: string;
		}>;
	}>;
}

interface GenericToolResult {
	success?: boolean;
	message?: string;
	error?: string;
	data?: any;
	content?: any; // For MCP tools that use content property
}

/**
 * Format tool results based on tool name and result structure
 */
export function formatToolResult(toolName: string, result: any): string {
	// Handle null/undefined results
	if (!result) {
		return chalk.gray('(no result)');
	}

	// Handle string results
	if (typeof result === 'string') {
		return result;
	}

	// Handle error results (but only for results that don't have specific handlers)
	// We'll let specific handlers deal with their own errors

	// Handle different tool types
	try {
		// Memory search tools
		if (toolName.includes('memory_search') || toolName.includes('search_memory')) {
			return formatMemorySearchResult(result as MemorySearchResult);
		}

		// Knowledge graph search tools
		if (
			toolName.includes('search_graph') ||
			toolName.includes('query_graph') ||
			toolName.includes('get_neighbors')
		) {
			console.log('Knowledge graph result');
			return formatKnowledgeGraphResult(result as KnowledgeGraphResult);
		}

		// Reasoning tools
		if (
			toolName.includes('reasoning') ||
			toolName.includes('extract_reasoning') ||
			toolName.includes('evaluate_reasoning')
		) {
			return formatReasoningResult(result as ReasoningResult);
		}

		// Memory operation tools
		if (toolName.includes('extract_and_operate') || toolName.includes('memory_operation')) {
			return formatMemoryOperationResult(result);
		}

		// Knowledge graph modification tools
		if (
			toolName.includes('add_node') ||
			toolName.includes('add_edge') ||
			toolName.includes('update_node') ||
			toolName.includes('delete_node')
		) {
			return formatKnowledgeGraphModificationResult(result);
		}

		// MCP file tools (read_file, write_file, list_files, etc.)
		if (
			toolName.includes('read_file') ||
			toolName.includes('write_file') ||
			toolName.includes('list_files')
		) {
			return formatMCPFileResult(toolName, result);
		}

		// Generic success/failure result
		return formatGenericResult(result as GenericToolResult);
	} catch (error) {
		logger.debug('Error formatting tool result, falling back to JSON', { error, toolName });
		// If there's an error in the result, show it properly
		if (result && result.error) {
			return chalk.red(`❌ Error: ${result.error}`);
		}
		return JSON.stringify(result, null, 2);
	}
}

/**
 * Format memory search results
 */
function formatMemorySearchResult(result: MemorySearchResult): string {
	if (!result.success) {
		return chalk.red(`❌ Search failed: ${result.error || 'Unknown error'}`);
	}

	const output = [];

	// Header
	output.push(chalk.blue.bold(`🔍 Memory Search Results`));
	output.push(chalk.gray(`Query: "${result.query}"`));
	output.push(
		chalk.gray(`Found ${result.results.length} result(s) in ${result.metadata.searchTime}ms`)
	);
	output.push('');

	// Results
	if (result.results.length === 0) {
		output.push(chalk.yellow('No results found'));
	} else {
		result.results.forEach((item, index) => {
			output.push(
				chalk.cyan(
					`${index + 1}. ${chalk.bold(item.text.substring(0, 80))}${item.text.length > 80 ? '...' : ''}`
				)
			);
			output.push(chalk.gray(`   📊 Similarity: ${(item.similarity * 100).toFixed(1)}%`));
			if (item.confidence) {
				output.push(chalk.gray(`   🎯 Confidence: ${(item.confidence * 100).toFixed(1)}%`));
			}
			if (item.domain) {
				output.push(chalk.gray(`   🏷️  Domain: ${item.domain}`));
			}
			output.push(chalk.gray(`   🏷️  Tags: ${item.tags.join(', ')}`));
			output.push(chalk.gray(`   📅 ${new Date(item.timestamp).toLocaleString()}`));
			output.push('');
		});

		// Summary
		output.push(chalk.gray(`📊 Summary:`));
		output.push(
			chalk.gray(`   • Max similarity: ${(result.metadata.maxSimilarity * 100).toFixed(1)}%`)
		);
		output.push(
			chalk.gray(`   • Min similarity: ${(result.metadata.minSimilarity * 100).toFixed(1)}%`)
		);
		output.push(
			chalk.gray(
				`   • Average similarity: ${(result.metadata.averageSimilarity * 100).toFixed(1)}%`
			)
		);
		if (result.metadata.usedFallback) {
			output.push(chalk.yellow(`   ⚠️  Used fallback search`));
		}
	}

	return output.join('\n');
}

/**
 * Format knowledge graph results
 */
function formatKnowledgeGraphResult(result: KnowledgeGraphResult): string {
	if (!result.success) {
		console.log('Knowledge graph result', result.error);
		return chalk.red(`❌ Graph query failed: ${result.error || 'Unknown error'}`);
	}

	const output = [];

	// Header
	output.push(chalk.blue.bold(`🕸️  Knowledge Graph Results`));
	if (result.message) {
		output.push(chalk.gray(result.message));
	}
	if (result.executionTime) {
		output.push(chalk.gray(`Execution time: ${result.executionTime}ms`));
	}
	output.push('');

	// Nodes
	if (result.nodes && result.nodes.length > 0) {
		output.push(chalk.cyan.bold(`📍 Nodes (${result.nodes.length}):`));
		result.nodes.slice(0, 10).forEach((node, index) => {
			output.push(
				chalk.cyan(
					`  ${index + 1}. ${chalk.bold(node.name)} ${node.type ? chalk.gray(`(${node.type})`) : ''}`
				)
			);
			if (node.score) {
				output.push(chalk.gray(`     📊 Score: ${(node.score * 100).toFixed(1)}%`));
			}
			if (node.matchReason) {
				output.push(chalk.gray(`     🎯 Match: ${node.matchReason}`));
			}
			if (node.properties && Object.keys(node.properties).length > 0) {
				const propStr = Object.entries(node.properties)
					.slice(0, 3)
					.map(([k, v]) => `${k}: ${v}`)
					.join(', ');
				output.push(chalk.gray(`     🏷️  ${propStr}`));
			}
		});
		if (result.nodes.length > 10) {
			output.push(chalk.gray(`  ... and ${result.nodes.length - 10} more`));
		}
		output.push('');
	}

	// Edges
	if (result.edges && result.edges.length > 0) {
		output.push(chalk.magenta.bold(`🔗 Relationships (${result.edges.length}):`));
		result.edges.slice(0, 10).forEach((edge, index) => {
			output.push(
				chalk.magenta(
					`  ${index + 1}. ${chalk.bold(edge.source)} ${chalk.gray('→')} ${chalk.bold(edge.target)}`
				)
			);
			output.push(chalk.gray(`     🏷️  Type: ${edge.type}`));
			if (edge.score) {
				output.push(chalk.gray(`     📊 Score: ${(edge.score * 100).toFixed(1)}%`));
			}
		});
		if (result.edges.length > 10) {
			output.push(chalk.gray(`  ... and ${result.edges.length - 10} more`));
		}
		output.push('');
	}

	// Related entities
	if (result.related && result.related.length > 0) {
		output.push(chalk.yellow.bold(`🔗 Related Entities (${result.related.length}):`));
		result.related.slice(0, 5).forEach((rel, index) => {
			output.push(
				chalk.yellow(
					`  ${index + 1}. ${chalk.bold(rel.entity.name)} ${chalk.gray(`(distance: ${rel.distance})`)}`
				)
			);
			output.push(chalk.gray(`     🔗 via ${rel.relationship.type}`));
		});
		if (result.related.length > 5) {
			output.push(chalk.gray(`  ... and ${result.related.length - 5} more`));
		}
		output.push('');
	}

	// Summary
	if (result.totalCount) {
		output.push(chalk.gray(`📊 Total results: ${result.totalCount}`));
	}

	return output.join('\n');
}

/**
 * Format reasoning results
 */
function formatReasoningResult(result: ReasoningResult): string {
	if (!result.success) {
		return chalk.red(`❌ Reasoning analysis failed: ${result.error || 'Unknown error'}`);
	}

	const output = [];

	// Header
	output.push(chalk.blue.bold(`🧠 Reasoning Analysis`));
	output.push('');

	// Steps
	if (result.steps && result.steps.length > 0) {
		output.push(chalk.cyan.bold(`💭 Reasoning Steps (${result.steps.length}):`));
		result.steps.forEach((step, index) => {
			const typeIcon = getStepTypeIcon(step.type);
			output.push(chalk.cyan(`  ${index + 1}. ${typeIcon} ${chalk.bold(step.type)}`));
			output.push(
				chalk.gray(
					`     ${step.content.substring(0, 100)}${step.content.length > 100 ? '...' : ''}`
				)
			);
		});
		output.push('');
	}

	// Evaluation
	if (result.evaluation) {
		output.push(chalk.yellow.bold(`📊 Quality Evaluation:`));
		output.push(
			chalk.yellow(`  Quality Score: ${(result.evaluation.qualityScore * 100).toFixed(1)}%`)
		);

		if (result.evaluation.issues && result.evaluation.issues.length > 0) {
			output.push(chalk.red(`  Issues Found (${result.evaluation.issues.length}):`));
			result.evaluation.issues.forEach((issue, index) => {
				const severityColor =
					issue.severity === 'high'
						? chalk.red
						: issue.severity === 'medium'
							? chalk.yellow
							: chalk.gray;
				output.push(severityColor(`    ${index + 1}. ${issue.description}`));
			});
		}

		if (result.evaluation.suggestions && result.evaluation.suggestions.length > 0) {
			output.push(chalk.green(`  Suggestions (${result.evaluation.suggestions.length}):`));
			result.evaluation.suggestions.forEach((suggestion, index) => {
				output.push(chalk.green(`    ${index + 1}. ${suggestion}`));
			});
		}
		output.push('');
	}

	// Patterns
	if (result.patterns && result.patterns.length > 0) {
		output.push(chalk.magenta.bold(`🔍 Similar Patterns (${result.patterns.length}):`));
		result.patterns.slice(0, 3).forEach((pattern, index) => {
			output.push(
				chalk.magenta(
					`  ${index + 1}. ${chalk.bold(pattern.context)} ${chalk.gray(`(${(pattern.similarity * 100).toFixed(1)}% match)`)}`
				)
			);
			output.push(chalk.gray(`     ${pattern.steps.length} steps`));
		});
		if (result.patterns.length > 3) {
			output.push(chalk.gray(`  ... and ${result.patterns.length - 3} more`));
		}
		output.push('');
	}

	return output.join('\n');
}

/**
 * Format memory operation results
 */
function formatMemoryOperationResult(result: any): string {
	if (!result.success) {
		return chalk.red(`❌ Memory operation failed: ${result.error || 'Unknown error'}`);
	}

	const output = [];

	// Header
	output.push(chalk.blue.bold(`💾 Memory Operation Results`));
	output.push('');

	// Operations summary
	if (result.operations) {
		const ops = result.operations;
		const summary = [];
		if (ops.added > 0) summary.push(chalk.green(`${ops.added} added`));
		if (ops.updated > 0) summary.push(chalk.yellow(`${ops.updated} updated`));
		if (ops.deleted > 0) summary.push(chalk.red(`${ops.deleted} deleted`));
		if (ops.unchanged > 0) summary.push(chalk.gray(`${ops.unchanged} unchanged`));

		if (summary.length > 0) {
			output.push(chalk.cyan(`📊 Summary: ${summary.join(', ')}`));
			output.push('');
		}
	}

	// Memory entries
	if (result.memories && result.memories.length > 0) {
		output.push(chalk.cyan.bold(`📝 Memory Entries (${result.memories.length}):`));
		result.memories.slice(0, 5).forEach((memory: any, index: number) => {
			const eventIcon = getMemoryEventIcon(memory.event);
			output.push(
				chalk.cyan(
					`  ${index + 1}. ${eventIcon} ${chalk.bold(memory.event)} - ${memory.text.substring(0, 60)}${memory.text.length > 60 ? '...' : ''}`
				)
			);
			if (memory.confidence) {
				output.push(chalk.gray(`     🎯 Confidence: ${(memory.confidence * 100).toFixed(1)}%`));
			}
			if (memory.tags && memory.tags.length > 0) {
				output.push(chalk.gray(`     🏷️  Tags: ${memory.tags.join(', ')}`));
			}
			if (memory.reasoning) {
				output.push(
					chalk.gray(
						`     💭 Reasoning: ${memory.reasoning.substring(0, 80)}${memory.reasoning.length > 80 ? '...' : ''}`
					)
				);
			}
		});
		if (result.memories.length > 5) {
			output.push(chalk.gray(`  ... and ${result.memories.length - 5} more`));
		}
		output.push('');
	}

	return output.join('\n');
}

/**
 * Format knowledge graph modification results
 */
function formatKnowledgeGraphModificationResult(result: any): string {
	if (!result.success) {
		return chalk.red(`❌ Graph modification failed: ${result.error || 'Unknown error'}`);
	}

	const output = [];

	// Header
	output.push(chalk.blue.bold(`🕸️  Knowledge Graph Updated`));
	if (result.message) {
		output.push(chalk.gray(result.message));
	}
	output.push('');

	// Node/Edge details
	if (result.node) {
		output.push(
			chalk.green(
				`✅ Node: ${chalk.bold(result.node.name)} ${result.node.type ? chalk.gray(`(${result.node.type})`) : ''}`
			)
		);
		if (result.node.properties && Object.keys(result.node.properties).length > 0) {
			const propStr = Object.entries(result.node.properties)
				.slice(0, 3)
				.map(([k, v]) => `${k}: ${v}`)
				.join(', ');
			output.push(chalk.gray(`   🏷️  Properties: ${propStr}`));
		}
	}

	if (result.edge) {
		output.push(
			chalk.green(
				`✅ Relationship: ${chalk.bold(result.edge.source)} ${chalk.gray('→')} ${chalk.bold(result.edge.target)}`
			)
		);
		output.push(chalk.gray(`   🏷️  Type: ${result.edge.type}`));
		if (result.edge.properties && Object.keys(result.edge.properties).length > 0) {
			const propStr = Object.entries(result.edge.properties)
				.slice(0, 3)
				.map(([k, v]) => `${k}: ${v}`)
				.join(', ');
			output.push(chalk.gray(`   🏷️  Properties: ${propStr}`));
		}
	}

	// Statistics
	if (result.statistics) {
		output.push('');
		output.push(chalk.gray(`📊 Graph Statistics:`));
		if (result.statistics.totalNodes) {
			output.push(chalk.gray(`   • Total nodes: ${result.statistics.totalNodes}`));
		}
		if (result.statistics.totalEdges) {
			output.push(chalk.gray(`   • Total edges: ${result.statistics.totalEdges}`));
		}
	}

	return output.join('\n');
}

/**
 * Format MCP file tool results
 */
function formatMCPFileResult(toolName: string, result: any): string {
	// Handle explicit errors
	if (result.error) {
		return chalk.red(`❌ ${toolName} failed: ${result.error}`);
	}

	// Handle successful file operations
	if (result.content) {
		const output = [];
		output.push(chalk.green(`✅ ${toolName} completed successfully`));

		if (toolName.includes('read_file') && Array.isArray(result.content)) {
			// For read_file, show content summary
			const textContent = result.content.find((item: any) => item.type === 'text');
			if (textContent && textContent.text) {
				const lines = textContent.text.split('\n').length;
				const chars = textContent.text.length;
				output.push(chalk.gray(`📄 File read: ${lines} lines, ${chars} characters`));
			}
		} else if (toolName.includes('list_files') && Array.isArray(result.content)) {
			// For list_files, show directory contents summary
			const files = result.content.filter((item: any) => item.type === 'file').length;
			const dirs = result.content.filter((item: any) => item.type === 'directory').length;
			output.push(chalk.gray(`📁 Listed: ${files} files, ${dirs} directories`));
		}

		return output.join('\n');
	}

	// For other successful operations
	return chalk.green(`✅ ${toolName} completed successfully`);
}

/**
 * Format generic tool results
 */
function formatGenericResult(result: GenericToolResult): string {
	// Check for explicit failure conditions
	if (result.success === false || result.error) {
		return chalk.red(`❌ ${result.error || result.message || 'Operation failed'}`);
	}

	// For results without explicit success/error properties (like MCP tools),
	// treat them as successful if they contain data
	const hasData = result.data || (result.content && !result.error);
	const isExplicitSuccess = result.success === true;

	if (isExplicitSuccess || hasData) {
		const output = [];
		output.push(chalk.green(`✅ ${result.message || 'Operation completed successfully'}`));

		if (result.data) {
			// Try to format data in a readable way
			if (typeof result.data === 'object' && result.data !== null) {
				const keys = Object.keys(result.data);
				if (keys.length > 0) {
					output.push('');
					output.push(chalk.gray('📄 Data:'));
					keys.slice(0, 5).forEach(key => {
						const value = result.data[key];
						const displayValue = typeof value === 'string' ? value : JSON.stringify(value);
						output.push(
							chalk.gray(
								`   • ${key}: ${displayValue.substring(0, 50)}${displayValue.length > 50 ? '...' : ''}`
							)
						);
					});
					if (keys.length > 5) {
						output.push(chalk.gray(`   ... and ${keys.length - 5} more fields`));
					}
				}
			}
		}

		return output.join('\n');
	}

	// If no clear success/failure indicators, treat as successful
	return chalk.green(`✅ ${result.message || 'Operation completed successfully'}`);
}

/**
 * Get icon for reasoning step type
 */
function getStepTypeIcon(type: string): string {
	switch (type.toLowerCase()) {
		case 'thought':
			return '💭';
		case 'action':
			return '⚡';
		case 'observation':
			return '👁️';
		case 'decision':
			return '🎯';
		case 'conclusion':
			return '🎓';
		case 'reflection':
			return '🪞';
		default:
			return '•';
	}
}

/**
 * Get icon for memory event type
 */
function getMemoryEventIcon(event: string): string {
	switch (event.toUpperCase()) {
		case 'ADD':
			return '➕';
		case 'UPDATE':
			return '✏️';
		case 'DELETE':
			return '🗑️';
		case 'NONE':
			return '⚪';
		default:
			return '•';
	}
}

