		// Mock the service initializer
		const { createAgentServices } = await import('../../../utils/service-initializer.js');
		vi.mocked(createAgentServices).mockResolvedValue(mockServices);

		// Valid configuration for tests
		validConfig = {
			systemPrompt: 'You are a helpful assistant',
			llm: {
				provider: 'openai',
				model: 'gpt-4',
				apiKey: 'test-api-key',
			},
			mcpServers: {},
		};
	});

	afterEach(() => {
		vi.clearAllMocks();
	});

	describe('Basic Validation', () => {
		it('should require model or provider parameter', () => {
			const invalidConfigs = [
				{
					// Missing both model and provider
					systemPrompt: 'You are a helpful assistant',
					llm: {
						apiKey: 'test-api-key',
					},
				},
				{
					// Missing model
					systemPrompt: 'You are a helpful assistant',
					llm: {
						provider: 'openai',
						apiKey: 'test-api-key',
					},
				},
				{
					// Missing provider
					systemPrompt: 'You are a helpful assistant',
					llm: {
						model: 'gpt-4',
						apiKey: 'test-api-key',
					},
				},
				{
					// Empty provider
					systemPrompt: 'You are a helpful assistant',
					llm: {
						provider: '',
						model: 'gpt-4',
						apiKey: 'test-api-key',
					},
				},
				{
					// Empty model
					systemPrompt: 'You are a helpful assistant',
					llm: {
						provider: 'openai',
						model: '',
						apiKey: 'test-api-key',
					},
				},
			];

			invalidConfigs.forEach((config, _index) => {
				expect(() => {
					AgentConfigSchema.parse(config);
				}).toThrow(ZodError);
			});
		});

		it('should handle validation failure', () => {
			const invalidConfig = {
				systemPrompt: 'You are a helpful assistant',
				llm: {
					provider: 'invalid-provider',
					model: 'gpt-4',
					apiKey: 'test-api-key',
				},
			};

			expect(() => {
				AgentConfigSchema.parse(invalidConfig);
			}).toThrow(ZodError);

			try {
				AgentConfigSchema.parse(invalidConfig);
			} catch (error) {
				expect(error).toBeInstanceOf(ZodError);
				const zodError = error as ZodError;
				expect(zodError.issues).toHaveLength(1);
				expect(zodError.issues[0]?.path).toEqual(['llm', 'provider']);
				expect(zodError.issues[0]?.message).toContain('not supported');
			}
		});

		it('should validate LLM config separately', () => {
			const validLLMConfig = {
				provider: 'openai',
				model: 'gpt-4',
				apiKey: 'test-api-key',
			};

			const result = LLMConfigSchema.safeParse(validLLMConfig);
			expect(result.success).toBe(true);

			const invalidLLMConfig = {
				provider: 'unsupported-provider',
				model: 'gpt-4',
				apiKey: 'test-api-key',
			};

			const invalidResult = LLMConfigSchema.safeParse(invalidLLMConfig);
			expect(invalidResult.success).toBe(false);
			if (!invalidResult.success) {
				expect(invalidResult.error.issues[0]?.message).toContain('not supported');
			}
		});

		it('should require API key', () => {
			const configWithoutApiKey = {
				systemPrompt: 'You are a helpful assistant',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
				},
			};

			expect(() => {
				AgentConfigSchema.parse(configWithoutApiKey);
			}).toThrow(ZodError);
		});

		it('should reject empty API key', () => {
			const configWithEmptyApiKey = {
				systemPrompt: 'You are a helpful assistant',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: '',
				},
			};

			expect(() => {
				AgentConfigSchema.parse(configWithEmptyApiKey);
			}).toThrow(ZodError);
		});

		it('should validate supported providers', () => {
			const supportedProviders = ['openai', 'anthropic', 'qwen'];
			const unsupportedProviders = ['google', 'cohere', 'huggingface', 'custom'];

			// Test supported providers
			supportedProviders.forEach(provider => {
				const config = {
					systemPrompt: 'You are a helpful assistant',
					llm: {
						provider,
						model: 'test-model',
						apiKey: 'test-api-key',
					},
				};

				expect(() => {
					AgentConfigSchema.parse(config);
				}).not.toThrow();
			});

			// Test unsupported providers
			unsupportedProviders.forEach(provider => {
				const config = {
					systemPrompt: 'You are a helpful assistant',
					llm: {
						provider,
						model: 'test-model',
						apiKey: 'test-api-key',
					},
				};

				expect(() => {
					AgentConfigSchema.parse(config);
				}).toThrow(ZodError);
			});
		});

		it('should validate configuration structure', () => {
			const incompleteConfig = {
				// Missing systemPrompt and llm
			};

			expect(() => {
				AgentConfigSchema.parse(incompleteConfig);
			}).toThrow(ZodError);

			const configWithInvalidType = {
				systemPrompt: 123, // Should be string
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-api-key',
				},
			};

			expect(() => {
				AgentConfigSchema.parse(configWithInvalidType);
			}).toThrow(ZodError);
		});

		it('should accept valid configuration', () => {
			expect(() => {
				AgentConfigSchema.parse(validConfig);
			}).not.toThrow();

			const parsedConfig = AgentConfigSchema.parse(validConfig);
			expect(parsedConfig.llm.provider).toBe('openai');
			expect(parsedConfig.llm.model).toBe('gpt-4');
			expect(parsedConfig.llm.apiKey).toBe('test-api-key');
		});

		it('should handle optional configuration fields', () => {
			const configWithOptionals = {
				...validConfig,
				llm: {
					...validConfig.llm,
					maxIterations: 30,
					baseURL: 'https://api.openai.com/v1',
				},
			};

			expect(() => {
				AgentConfigSchema.parse(configWithOptionals);
			}).not.toThrow();

			const parsedConfig = AgentConfigSchema.parse(configWithOptionals);
			expect(parsedConfig.llm.maxIterations).toBe(30);
			expect(parsedConfig.llm.baseURL).toBe('https://api.openai.com/v1');
		});

		it('should validate baseURL format when provided', () => {
			const configWithInvalidBaseURL = {
				...validConfig,
				llm: {
					...validConfig.llm,
					baseURL: 'not-a-valid-url',
				},
			};

			expect(() => {
				AgentConfigSchema.parse(configWithInvalidBaseURL);
			}).toThrow(ZodError);
		});

		it('should validate maxIterations is positive', () => {
			const configWithNegativeIterations = {
				...validConfig,
				llm: {
					...validConfig.llm,
					maxIterations: -1,
				},
			};

			expect(() => {
				AgentConfigSchema.parse(configWithNegativeIterations);
			}).toThrow(ZodError);

			const configWithZeroIterations = {
				...validConfig,
				llm: {
					...validConfig.llm,
					maxIterations: 0,
				},
			};

			expect(() => {
				AgentConfigSchema.parse(configWithZeroIterations);
			}).toThrow(ZodError);
		});
	});

	describe('Agent Initialization', () => {
		it('should create agent with valid config', () => {
			const agent = new MemAgent(validConfig);
			expect(agent).toBeInstanceOf(MemAgent);
			expect(agent.getIsStarted()).toBe(false);
			expect(agent.getIsStopped()).toBe(false);
		});

		it('should fail to start with invalid configuration during service creation', async () => {
			const { createAgentServices } = await import('../../../utils/service-initializer.js');
			vi.mocked(createAgentServices).mockRejectedValue(
				new Error('Configuration validation failed')
			);

			const agent = new MemAgent(validConfig);

			await expect(agent.start()).rejects.toThrow('Configuration validation failed');
			expect(agent.getIsStarted()).toBe(false);
		});

		it('should start successfully with valid configuration', async () => {
			const agent = new MemAgent(validConfig);

			await agent.start();

			expect(agent.getIsStarted()).toBe(true);
			expect(agent.getIsStopped()).toBe(false);
		});

		it('should throw error when starting already started agent', async () => {
			const agent = new MemAgent(validConfig);
			await agent.start();

			await expect(agent.start()).rejects.toThrow('MemAgent is already started');
		});
	});

	describe('Service Validation', () => {
		it('should fail if required services are missing', async () => {
			const incompleteServices = {
				mcpManager: mockServices.mcpManager,
				promptManager: undefined,
				stateManager: mockServices.stateManager,
				sessionManager: mockServices.sessionManager,
				internalToolManager: mockServices.internalToolManager,
				unifiedToolManager: mockServices.unifiedToolManager,
			};

			const { createAgentServices } = await import('../../../utils/service-initializer.js');
			vi.mocked(createAgentServices).mockResolvedValue(incompleteServices as any);

			const agent = new MemAgent(validConfig);

			await expect(agent.start()).rejects.toThrow('Required service promptManager is missing');
		});

		it('should validate all required services are present', async () => {
			const agent = new MemAgent(validConfig);
			await agent.start();

			expect(agent.mcpManager).toBeDefined();
			expect(agent.promptManager).toBeDefined();
			expect(agent.stateManager).toBeDefined();
			expect(agent.sessionManager).toBeDefined();
			expect(agent.internalToolManager).toBeDefined();
			expect(agent.unifiedToolManager).toBeDefined();
			expect(agent.services).toBeDefined();
		});
	});

	describe('Metadata Propagation', () => {
		it('should propagate memoryMetadata and sessionOptions to session.run', async () => {
			const agent = new MemAgent(validConfig);
			await agent.start();

			const mockSession = {
				id: 'test-session',
				run: vi.fn().mockResolvedValue({
					response: 'Mock response',
					backgroundOperations: Promise.resolve(),
				}),
			};
			mockServices.sessionManager.getSession.mockResolvedValue(mockSession);

			const memoryMetadata = { foo: 'bar' };
			const sessionOptions = { baz: 'qux' };

			await agent.run('test input', undefined, undefined, false, {
				memoryMetadata,
				sessionOptions,
			});

			expect(mockSession.run).toHaveBeenCalledWith('test input', undefined, false, {
				memoryMetadata,
				contextOverrides: sessionOptions,
			});
		});
	});
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { loadAgentConfig } from '../loader.js';
import { promises as fs } from 'fs';
import { parse as parseYaml } from 'yaml';

// Mock external dependencies
vi.mock('fs', () => ({
	promises: {
		readFile: vi.fn(),
	},
}));

vi.mock('yaml', () => ({
	parse: vi.fn(),
}));

vi.mock('../../../logger/index.js', () => ({
	logger: {
		info: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
		debug: vi.fn(),
		silly: vi.fn(),
	},
}));

describe('Loader', () => {
	const mockFs = vi.mocked(fs);
	const mockParseYaml = vi.mocked(parseYaml);

	beforeEach(() => {
		vi.clearAllMocks();
		// Reset environment variables
		delete process.env.TEST_VAR;
		delete process.env.API_KEY;
		delete process.env.PORT;
		delete process.env.TIMEOUT;
	});

	afterEach(() => {
		vi.clearAllMocks();
	});

	describe('Environment Variable Expansion', () => {
		it('should expand simple environment variables', async () => {
			process.env.TEST_VAR = 'test-value';
			process.env.API_KEY = 'secret-key';

			const mockConfig = {
				systemPrompt: '$TEST_VAR',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: '${API_KEY}',
				},
			};

			mockFs.readFile.mockResolvedValue(JSON.stringify(mockConfig));
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.systemPrompt).toBe('test-value');
			expect(result.llm.apiKey).toBe('secret-key');
		});

		it('should handle missing environment variables by replacing with empty string', async () => {
			const mockConfig = {
				systemPrompt: '$MISSING_VAR',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: '${ALSO_MISSING}',
				},
			};

			mockFs.readFile.mockResolvedValue(JSON.stringify(mockConfig));
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.systemPrompt).toBe('');
			expect(result.llm.apiKey).toBe('');
		});

		it('should convert numeric environment variables to numbers', async () => {
			process.env.PORT = '3000';
			process.env.TIMEOUT = '30.5';
			process.env.SCIENTIFIC = '1.23e-4';

			const mockConfig = {
				systemPrompt: 'test prompt',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-key',
					maxTokens: '$PORT',
					temperature: '${TIMEOUT}',
				},
				sessions: {
					sessionTTL: '$SCIENTIFIC',
				},
			};

			mockFs.readFile.mockResolvedValue(JSON.stringify(mockConfig));
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.llm.maxTokens).toBe(3000);
			expect(result.llm.temperature).toBe(30.5);
			expect(result.sessions.sessionTTL).toBe(1.23e-4);
		});

		it('should not convert non-numeric strings to numbers', async () => {
			process.env.TEXT_VAR = 'not-a-number';

			const mockConfig = {
				systemPrompt: '$TEXT_VAR',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-key',
				},
			};

			mockFs.readFile.mockResolvedValue(JSON.stringify(mockConfig));
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.systemPrompt).toBe('not-a-number');
		});

		it('should handle environment variables in nested objects', async () => {
			process.env.DB_HOST = 'localhost';
			process.env.DB_PORT = '5432';

			const mockConfig = {
				systemPrompt: 'test prompt',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-key',
					baseURL: 'https://$DB_HOST:$DB_PORT',
				},
				mcpServers: {
					testServer: {
						command: 'test',
						env: {
							HOST: '$DB_HOST',
							PORT: '$DB_PORT',
							USERNAME: '${USERNAME}',
						},
					},
				},
			};

			mockFs.readFile.mockResolvedValue(JSON.stringify(mockConfig));
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.llm.baseURL).toBe('https://localhost:5432');
			expect(result.mcpServers.testServer.env.HOST).toBe('localhost');
			expect(result.mcpServers.testServer.env.PORT).toBe(5432);
			expect(result.mcpServers.testServer.env.USERNAME).toBe('');
		});

		it('should handle environment variables in arrays', async () => {
			process.env.SERVER1 = 'server1.com';
			process.env.SERVER2 = 'server2.com';

			const mockConfig = {
				systemPrompt: 'test prompt',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-key',
				},
				mcpServers: {
					testServer: {
						command: 'test',
						args: ['$SERVER1', '${SERVER2}', 'static.com'],
					},
				},
			};

			mockFs.readFile.mockResolvedValue(JSON.stringify(mockConfig));
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.mcpServers.testServer.args).toEqual([
				'server1.com',
				'server2.com',
				'static.com',
			]);
		});

		it('should handle mixed content with environment variables', async () => {
			process.env.HOST = 'api.example.com';
			process.env.VERSION = 'v1';

			const mockConfig = {
				systemPrompt: 'test prompt',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-key',
					baseURL: 'https://$HOST/${VERSION}/users',
				},
			};

			mockFs.readFile.mockResolvedValue(JSON.stringify(mockConfig));
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.llm.baseURL).toBe('https://api.example.com/v1/users');
		});

		it('should preserve non-string values unchanged', async () => {
			const mockConfig = {
				systemPrompt: 'test prompt',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-key',
				},
				sessions: {
					maxSessions: 42,
					sessionTTL: 3600000,
				},
				mcpServers: {
					testServer: {
						command: 'test',
						disabled: true,
						timeout: null,
						env: { key: 'value' },
						args: [1, 2, 3],
					},
				},
			};

			mockFs.readFile.mockResolvedValue(JSON.stringify(mockConfig));
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.sessions.maxSessions).toBe(42);
			expect(result.mcpServers.testServer.disabled).toBe(true);
			expect(result.mcpServers.testServer.timeout).toBe(null);
			expect(result.mcpServers.testServer.env).toEqual({ key: 'value' });
			expect(result.mcpServers.testServer.args).toEqual([1, 2, 3]);
		});

		it('should handle case-insensitive environment variable names', async () => {
			process.env.test_var = 'lowercase';
			process.env.TEST_VAR = 'uppercase';

			const mockConfig = {
				systemPrompt: '$test_var',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: '$TEST_VAR',
				},
			};

			mockFs.readFile.mockResolvedValue(JSON.stringify(mockConfig));
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.systemPrompt).toBe('lowercase');
			expect(result.llm.apiKey).toBe('uppercase');
		});
	});

	describe('Config File Loading', () => {
		it('should successfully load and parse YAML config', async () => {
			const yamlContent = `
systemPrompt: "You are a helpful assistant"
llm:
  provider: "openai"
  model: "gpt-4"
  apiKey: "test-key"
`;
			const expectedConfig = {
				systemPrompt: 'You are a helpful assistant',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-key',
				},
			};

			mockFs.readFile.mockResolvedValue(yamlContent);
			mockParseYaml.mockReturnValue(expectedConfig);

			const result = await loadAgentConfig('/path/to/config.yml');

			expect(mockFs.readFile).toHaveBeenCalledWith('/path/to/config.yml', 'utf-8');
			expect(mockParseYaml).toHaveBeenCalledWith(yamlContent);
			expect(result).toEqual(expectedConfig);
		});

		it('should log debug message with config path', async () => {
			const { logger } = await import('../../../logger/index.js');
			const mockConfig = { test: 'value' };

			mockFs.readFile.mockResolvedValue('test: value');
			mockParseYaml.mockReturnValue(mockConfig);

			await loadAgentConfig('/custom/path/config.yml');

			expect(logger.debug).toHaveBeenCalledWith(
				'Loading cipher config from: /custom/path/config.yml'
			);
		});

		it('should handle file read errors', async () => {
			const readError = new Error('File not found');
			mockFs.readFile.mockRejectedValue(readError);

			await expect(loadAgentConfig('/nonexistent/config.yml')).rejects.toThrow(
				'Failed to load config file at /nonexistent/config.yml: File not found'
			);
		});

		it('should handle YAML parsing errors', async () => {
			const yamlContent = 'invalid: yaml: content: [unclosed';
			const parseError = new Error('Invalid YAML syntax');

			mockFs.readFile.mockResolvedValue(yamlContent);
			mockParseYaml.mockImplementation(() => {
				throw parseError;
			});

			await expect(loadAgentConfig('/path/to/config.yml')).rejects.toThrow(
				'Failed to parse YAML: Invalid YAML syntax'
			);
		});

		it('should handle non-Error parsing exceptions', async () => {
			const yamlContent = 'test: value';

			mockFs.readFile.mockResolvedValue(yamlContent);
			mockParseYaml.mockImplementation(() => {
				throw 'String error';
			});

			await expect(loadAgentConfig('/path/to/config.yml')).rejects.toThrow(
				'Failed to parse YAML: String error'
			);
		});

		it('should handle file system errors with path property', async () => {
			const fsError = Object.assign(new Error('Permission denied'), {
				path: '/restricted/config.yml',
			});

			mockFs.readFile.mockRejectedValue(fsError);

			await expect(loadAgentConfig('/path/to/config.yml')).rejects.toThrow(
				'Failed to load config file at /restricted/config.yml: Permission denied'
			);
		});

		it('should handle complex configuration with environment variables', async () => {
			process.env.API_KEY = 'secret-123';
			process.env.MAX_ITERATIONS = '50';
			process.env.BASE_URL = 'https://api.openai.com/v1';

			const yamlContent = `
systemPrompt: "You are a helpful assistant"
llm:
  provider: "openai"
  model: "gpt-4"
  apiKey: "\${API_KEY}"
  maxIterations: \${MAX_ITERATIONS}
  baseURL: \${BASE_URL}
mcpServers:
  filesystem:
    type: "stdio"
    command: "npx"
    args: ["@modelcontextprotocol/server-filesystem"]
    env:
      ROOT_PATH: "/tmp"
`;

			const parsedConfig = {
				systemPrompt: 'You are a helpful assistant',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: '${API_KEY}',
					maxIterations: '${MAX_ITERATIONS}',
					baseURL: '${BASE_URL}',
				},
				mcpServers: {
					filesystem: {
						type: 'stdio',
						command: 'npx',
						args: ['@modelcontextprotocol/server-filesystem'],
						env: {
							ROOT_PATH: '/tmp',
						},
					},
				},
			};

			mockFs.readFile.mockResolvedValue(yamlContent);
			mockParseYaml.mockReturnValue(parsedConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.llm.apiKey).toBe('secret-123');
			expect(result.llm.maxIterations).toBe(50);
			expect(result.llm.baseURL).toBe('https://api.openai.com/v1');
			expect(result.mcpServers.filesystem.env.ROOT_PATH).toBe('/tmp');
		});
	});

	describe('Edge Cases', () => {
		it('should handle empty config file', async () => {
			mockFs.readFile.mockResolvedValue('');
			mockParseYaml.mockReturnValue({});

			const result = await loadAgentConfig('/path/to/empty.yml');

			expect(result).toEqual({});
		});

		it('should handle config with only environment variables', async () => {
			process.env.ONLY_ENV = 'env-value';

			const mockConfig = '$ONLY_ENV';

			mockFs.readFile.mockResolvedValue('value');
			mockParseYaml.mockReturnValue(mockConfig);

			const result = await loadAgentConfig('/path/to/config.yml');

			expect(result).toBe('env-value');
		});

		it('should handle deeply nested configuration', async () => {
			process.env.DEEP_VALUE = 'found-it';

			const mockConfig = {
				systemPrompt: 'test prompt',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-key',
				},
				mcpServers: {
					testServer: {
						type: 'stdio',
						command: 'test',
						env: {
							level1: {
								level2: {
									level3: {
										level4: {
											value: '$DEEP_VALUE',
										},
									},
								},
							},
						},
					},
				},
			};

			mockFs.readFile.mockResolvedValue('nested');
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.mcpServers.testServer.env.level1.level2.level3.level4.value).toBe('found-it');
		});

		it('should handle environment variables with underscores and numbers', async () => {
			process.env.VAR_WITH_123 = 'underscore-and-numbers';
			process.env.VAR123 = 'just-numbers';

			const mockConfig = {
				systemPrompt: '$VAR_WITH_123',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: '$VAR123',
				},
			};

			mockFs.readFile.mockResolvedValue('test');
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.systemPrompt).toBe('underscore-and-numbers');
			expect(result.llm.apiKey).toBe('just-numbers');
		});

		it('should handle negative numbers in environment variables', async () => {
			process.env.NEGATIVE_INT = '-42';
			process.env.NEGATIVE_FLOAT = '-3.14';

			const mockConfig = {
				systemPrompt: 'test prompt',
				llm: {
					provider: 'openai',
					model: 'gpt-4',
					apiKey: 'test-key',
					maxIterations: '$NEGATIVE_INT',
				},
				sessions: {
					sessionTTL: '$NEGATIVE_FLOAT',
				},
			};

			mockFs.readFile.mockResolvedValue('negative');
			mockParseYaml.mockReturnValue(mockConfig);

			const result = (await loadAgentConfig('/path/to/config.yml')) as any;

			expect(result.llm.maxIterations).toBe(-42);
			expect(result.sessions.sessionTTL).toBe(-3.14);
		});
	});
});

import { MCPManager } from '@core/mcp/manager.js';
import { AgentServices } from '../../utils/service-initializer.js';
import { createAgentServices } from '../../utils/service-initializer.js';
import {
	createEnhancedAgentServices,
	shouldEnableLazyLoading,
	LazyAgentServices,
} from '../memory/enhanced-service-initializer.js';
import { EnhancedPromptManager } from '../systemPrompt/enhanced-manager.js';
import { MemAgentStateManager } from './state-manager.js';
import { SessionManager } from '../../session/session-manager.js';
import { ConversationSession } from '../../session/coversation-session.js';
import { AgentConfig } from './config.js';
import { logger } from '../../logger/index.js';
import { LLMConfig } from '../llm/config.js';
import { IMCPClient, McpServerConfig } from '../../mcp/types.js';

const requiredServices: (keyof AgentServices)[] = [
	'mcpManager',
	'promptManager',
	'stateManager',
	'sessionManager',
	'internalToolManager',
	'unifiedToolManager',
];

export class MemAgent {
	public readonly mcpManager!: MCPManager;
	public readonly promptManager!: EnhancedPromptManager;
	public readonly stateManager!: MemAgentStateManager;
	public readonly sessionManager!: SessionManager;
	public readonly internalToolManager!: any; // Will be properly typed later
	public readonly unifiedToolManager!: any; // Will be properly typed later
	public readonly services!: AgentServices;

	private defaultSession: ConversationSession | null = null;

	private currentDefaultSessionId: string = 'default';
	private currentActiveSessionId: string = 'default'; // Will be set properly in constructor

	private isStarted: boolean = false;
	private isStopped: boolean = false;

	private config: AgentConfig;
	private appMode: 'cli' | 'mcp' | 'api' | null = null;

	constructor(config: AgentConfig, appMode?: 'cli' | 'mcp' | 'api') {
		this.config = config;
		this.appMode = appMode || null;

		// Set session ID based on mode
		if (appMode === 'cli') {
			// For CLI, use default session to enable persistence
			this.currentActiveSessionId = this.currentDefaultSessionId;
		} else {
			// For API/MCP, generate unique session IDs
			this.currentActiveSessionId = this.generateUniqueSessionId();
		}

		if (appMode !== 'cli') {
			logger.debug('MemAgent created');
		}
	}

	/**
	 * Generate a unique session ID for API/MCP modes
	 * CLI mode uses the default session for persistence
	 */
	private generateUniqueSessionId(): string {
		const timestamp = Date.now();
		const random = Math.random().toString(36).substring(2, 8);
		return `session-${timestamp}-${random}`;
	}

	/**
	 * Start the MemAgent
	 */
	public async start(): Promise<void> {
		if (this.isStarted) {
			throw new Error('MemAgent is already started');
		}

		try {
			if (this.appMode !== 'cli') {
				logger.debug('Starting MemAgent...');
			}

			// 1. Initialize services with optional lazy loading
			const useLazyLoading = shouldEnableLazyLoading({
				appMode: this.appMode || undefined,
			});
			let services: AgentServices | LazyAgentServices;

			if (useLazyLoading) {
				logger.debug('MemAgent: Using enhanced services with lazy loading');
				services = await createEnhancedAgentServices(this.config, {
					enableLazyLoading: true,
					...(this.appMode && { appMode: this.appMode }),
				});
			} else {
				logger.debug('MemAgent: Using standard services');
				services = await createAgentServices(this.config, this.appMode || undefined);
			}

			for (const service of requiredServices) {
				if (!services[service]) {
					throw new Error(`Required service ${service} is missing during agent start`);
				}
			}

			Object.assign(this, {
				mcpManager: services.mcpManager,
				promptManager: services.promptManager,
				stateManager: services.stateManager,
				sessionManager: services.sessionManager,
				internalToolManager: services.internalToolManager,
				unifiedToolManager: services.unifiedToolManager,
				services: services,
			});

			// Sessions are already loaded during SessionManager initialization
			// No need to load them again here

			this.isStarted = true;
			if (this.appMode !== 'cli') {
				logger.debug('MemAgent started successfully');
			}
		} catch (error) {
			logger.error('Failed to start MemAgent:', error);
			throw error;
		}
	}

	/**
	 * Stop the MemAgent
	 */
	public async stop(): Promise<void> {
		if (this.isStopped) {
			logger.warn('MemAgent is already stopped');
			return;
		}

		if (!this.isStarted) {
			throw new Error('MemAgent must be started before stopping');
		}

		try {
			logger.info('Stopping MemAgent...');
			const shutdownErrors: Error[] = [];

			// Save all sessions before shutdown
			try {
				if (this.sessionManager) {
					logger.info('Saving all sessions before shutdown...');
					await this.sessionManager.shutdown(); // This will call saveAllSessions internally
					logger.debug('SessionManager shutdown completed');
				}
			} catch (error) {
				const err = error instanceof Error ? error : new Error(String(error));
				shutdownErrors.push(new Error(`SessionManager shutdown failed: ${err.message}`));
			}

			try {
				if (this.mcpManager) {
					await this.mcpManager.disconnectAll();
					logger.debug('MCPManager disconnected all clients successfully');
				}
			} catch (error) {
				const err = error instanceof Error ? error : new Error(String(error));
				shutdownErrors.push(new Error(`MCPManager disconnect failed: ${err.message}`));
			}

			this.isStopped = true;
			this.isStarted = false;
			if (shutdownErrors.length > 0) {
				const errorMessages = shutdownErrors.map(e => e.message).join('; ');
				logger.warn(`MemAgent stopped with some errors: ${errorMessages}`);
				// Still consider it stopped, but log the errors
			} else {
				logger.info('MemAgent stopped successfully.');
			}
		} catch (error) {
			logger.error('Failed to stop MemAgent:', error);
			throw error;
		}
	}

	/**
	 * Get the status of the MemAgent
	 */
	public getIsStarted(): boolean {
		return this.isStarted;
	}

	/**
	 * Get the status of the MemAgent
	 */
	public getIsStopped(): boolean {
		return this.isStopped;
	}

	private ensureStarted(): void {
		if (this.isStopped) {
			throw new Error('MemAgent has been stopped and cannot be used');
		}
		if (!this.isStarted) {
			throw new Error('MemAgent must be started before use. Call agent.start() first.');
		}
	}

	/**
	 * Run the MemAgent
	 */
	public async run(
		userInput: string,
		imageDataInput?: { image: string; mimeType: string },
		sessionId?: string,
		stream: boolean = false,
		options?: {
			memoryMetadata?: Record<string, any>;
			sessionOptions?: Record<string, any>;
		}
	): Promise<{ response: string | null; backgroundOperations: Promise<void> }> {
		this.ensureStarted();
		try {
			let session: ConversationSession;
			if (sessionId) {
				session =
					(await this.sessionManager.getSession(sessionId)) ??
					(await this.sessionManager.createSession(sessionId));
				this.currentActiveSessionId = sessionId;
			} else {
				// Use current active session or fall back to default
				session =
					(await this.sessionManager.getSession(this.currentActiveSessionId)) ??
					(await this.sessionManager.createSession(this.currentActiveSessionId));
			}
			logger.debug(`MemAgent.run: using session ${session.id}`);
			const { response, backgroundOperations } = await session.run(
				userInput,
				imageDataInput,
				stream,
				{
					...(options?.memoryMetadata !== undefined && { memoryMetadata: options.memoryMetadata }),
					...(options?.sessionOptions !== undefined && {
						contextOverrides: options.sessionOptions,
					}),
				}
			);

			const finalResponse = response && response.trim() !== '' ? response : null;
			return { response: finalResponse, backgroundOperations };
		} catch (error) {
			logger.error('MemAgent.run: error', error);
			throw error;
		}
	}

	public async createSession(sessionId?: string): Promise<ConversationSession> {
		this.ensureStarted();
		logger.debug(`MemAgent: Creating session with ID: ${sessionId || 'auto-generated'}`);
		const session = await this.sessionManager.createSession(sessionId);
		logger.info(`MemAgent: Created session: ${session.id}`);
		return session;
	}

	public async getSession(sessionId: string): Promise<ConversationSession | null> {
		this.ensureStarted();
		let session = await this.sessionManager.getSession(sessionId);

		// For CLI mode, automatically create the default session if it doesn't exist
		if (!session && this.appMode === 'cli' && sessionId === 'default') {
			logger.debug(
				'MemAgent: Default session not found, creating new default session for CLI mode'
			);
			try {
				session = await this.sessionManager.createSession('default');
				logger.info('MemAgent: Created default session for CLI mode');
			} catch (error) {
				logger.error('MemAgent: Failed to create default session:', error);
				return null;
			}
		}

		return session;
	}

	/**
	 * Get the current active session ID
	 */
	public getCurrentSessionId(): string {
		this.ensureStarted();
		return this.currentActiveSessionId;
	}

	/**
	 * Load conversation history for a specific session
	 */
	public async loadSessionHistory(sessionId: string): Promise<void> {
		this.ensureStarted();
		const session = await this.sessionManager.getSession(sessionId);

		if (!session) {
			throw new Error(`Session not found: ${sessionId}`);
		}

		try {
			await session.refreshConversationHistory();
		} catch (error) {
			logger.warn(`MemAgent: Failed to load conversation history for session ${sessionId}:`, error);
			throw error;
		}
	}

	/**
	 * Load (switch to) a specific session
	 */
	public async loadSession(sessionId: string): Promise<ConversationSession> {
		this.ensureStarted();
		let session = await this.sessionManager.getSession(sessionId);

		if (!session) {
			throw new Error(`Session not found: ${sessionId}`);
		}

		// Initialize services and load conversation history
		try {
			logger.debug(`MemAgent: Loading session ${sessionId}...`);
			await session.init(); // Initialize services first

			// Load conversation history so AI can see previous messages
			await session.refreshConversationHistory();
			logger.info(`MemAgent: Successfully loaded session ${sessionId} with conversation history`);
		} catch (error) {
			logger.warn(`MemAgent: Failed to initialize session ${sessionId}:`, error);
			// Continue even if initialization fails
		}

		this.currentActiveSessionId = sessionId;
		logger.debug(`MemAgent: Switched to session ${sessionId}`);
		return session;
	}

	/**
	 * Get all active session IDs
	 */
	public async listSessions(): Promise<string[]> {
		this.ensureStarted();
		return await this.sessionManager.getActiveSessionIds();
	}

	/**
	 * Remove a session
	 */
	public async removeSession(sessionId: string): Promise<boolean> {
		this.ensureStarted();

		// Prevent removing the currently active session
		if (sessionId === this.currentActiveSessionId) {
			throw new Error(
				'Cannot remove the currently active session. Switch to another session first.'
			);
		}

		return await this.sessionManager.removeSession(sessionId);
	}

	/**
	 * Get session metadata including message count
	 */
	public async getSessionMetadata(sessionId: string): Promise<{
		id: string;
		createdAt?: number;
		lastActivity?: number;
		messageCount?: number;
	} | null> {
		this.ensureStarted();

		// Check if session exists
		const session = await this.sessionManager.getSession(sessionId);
		if (!session) {
			return null;
		}

		// Get actual message count from the session
		let messageCount = 0;
		try {
			// Ensure the session is properly initialized
			if (!session.getContextManager) {
				await session.init();
			}

			const history = await session.getConversationHistory();
			messageCount = history.length;
		} catch (error) {
			logger.warn(`Failed to get message count for session ${sessionId}:`, error);
			// Try alternative method to get message count
			try {
				const contextManager = session.getContextManager();
				if (contextManager) {
					const rawMessages = contextManager.getRawMessages();
					messageCount = rawMessages.length;
				}
			} catch (fallbackError) {
				logger.warn(
					`Failed to get message count via fallback for session ${sessionId}:`,
					fallbackError
				);
			}
		}

		// For now, return basic metadata since SessionManager doesn't expose internal metadata
		// This could be enhanced later to track more detailed session statistics
		return {
			id: sessionId,
			createdAt: Date.now(), // Placeholder - actual creation time would need to be tracked
			lastActivity: Date.now(), // Placeholder - actual last activity would need to be tracked
			messageCount,
		};
	}

	/**
	 * Get conversation history for the current session
	 */
	public async getCurrentSessionHistory(): Promise<any[]> {
		this.ensureStarted();
		const session = await this.sessionManager.getSession(this.currentActiveSessionId);
		if (!session) {
			return [];
		}
		return await session.getConversationHistory();
	}

	/**
	 * Get conversation history for a specific session
	 */
	public async getSessionHistory(sessionId: string): Promise<any[]> {
		this.ensureStarted();

		// Get the session
		const session = await this.sessionManager.getSession(sessionId);
		if (!session) {
			throw new Error(`Session not found: ${sessionId}`);
		}

		// Access the context manager to get raw messages
		// Note: We need to access the private contextManager property
		// This is a temporary solution until we add a proper public method to ConversationSession
		const contextManager = (session as any).contextManager;
		if (!contextManager) {
			// Session might not be initialized yet
			return [];
		}

		// Get raw messages and convert them to a format suitable for API response
		const rawMessages = contextManager.getRawMessages();

		// Transform the messages to a more user-friendly format
		return rawMessages.map((msg: any, index: number) => ({
			id: index + 1,
			role: msg.role,
			content: msg.content,
			timestamp: new Date().toISOString(), // Placeholder - actual timestamps would need to be tracked
			...(msg.toolCalls && { toolCalls: msg.toolCalls }),
			...(msg.toolCallId && { toolCallId: msg.toolCallId }),
			...(msg.name && { name: msg.name }),
		}));
	}

	public getCurrentLLMConfig(): LLMConfig {
		this.ensureStarted();
		return structuredClone(this.stateManager.getLLMConfig());
	}

	public async connectMcpServer(name: string, config: McpServerConfig): Promise<void> {
		this.ensureStarted();
		try {
			// Add to runtime state first with validation
			const validation = this.stateManager.addMcpServer(name, config);

			if (!validation.isValid) {
				const errorMessages = validation.errors.map(e => e.message).join(', ');
				throw new Error(`Invalid MCP server configuration: ${errorMessages}`);
			}

			// Then connect the server
			await this.mcpManager.connectServer(name, config);
			logger.info(`MemAgent: Successfully added and connected to MCP server '${name}'.`);
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(`MemAgent: Failed to add MCP server '${name}': ${errorMessage}`);

			// Clean up state if connection failed
			this.stateManager.removeMcpServer(name);
			throw error;
		}
	}

	public async removeMcpServer(name: string): Promise<void> {
		this.ensureStarted();
		// Disconnect the client first
		await this.mcpManager.removeClient(name);

		// Then remove from runtime state
		this.stateManager.removeMcpServer(name);
	}

	public async executeMcpTool(toolName: string, args: any): Promise<any> {
		this.ensureStarted();
		return await this.mcpManager.executeTool(toolName, args);
	}

	public async getAllMcpTools(): Promise<any> {
		this.ensureStarted();
		return await this.mcpManager.getAllTools();
	}

	public getMcpClients(): Map<string, IMCPClient> {
		this.ensureStarted();
		return this.mcpManager.getClients();
	}

	public getMcpFailedConnections(): Record<string, string> {
		this.ensureStarted();
		return this.mcpManager.getFailedConnections();
	}

	public getAllMcpServers(): Array<{ id: string; name: string; status: string; error?: string }> {
		this.ensureStarted();
		const clients = this.mcpManager.getClients();
		const failedConnections = this.mcpManager.getFailedConnections();

		const servers: Array<{ id: string; name: string; status: string; error?: string }> = [];

		// Add connected servers
		for (const [name, client] of clients.entries()) {
			try {
				client.getServerInfo(); // Get server info but don't use it
				servers.push({
					id: name, // Use client name as id for API compatibility
					name,
					status: 'connected',
				});
			} catch (error) {
				servers.push({
					id: name, // Use client name as id for API compatibility
					name,
					status: 'error',
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}

		// Add failed connections
		for (const [name, error] of Object.entries(failedConnections)) {
			servers.push({
				id: name, // Use client name as id for API compatibility
				name,
				status: 'error',
				error,
			});
		}

		return servers;
	}

	public getEffectiveConfig(sessionId?: string): Readonly<AgentConfig> {
		this.ensureStarted();
		return sessionId
			? this.stateManager.getRuntimeConfig(sessionId)
			: this.stateManager.getRuntimeConfig();
	}

	public getCurrentActiveSessionId() {
		return this.currentActiveSessionId;
	}

	/**
	 * Manually save all sessions to persistent storage
	 */
	public async saveAllSessions(): Promise<{ saved: number; failed: number; total: number }> {
		this.ensureStarted();
		const stats = await this.sessionManager.saveAllSessions();
		return {
			saved: stats.savedSessions,
			failed: stats.failedSessions,
			total: stats.totalSessions,
		};
	}

	/**
	 * Manually load all sessions from persistent storage
	 */
	public async loadAllSessions(): Promise<{ restored: number; failed: number; total: number }> {
		this.ensureStarted();
		const stats = await this.sessionManager.loadAllSessions();
		return {
			restored: stats.restoredSessions,
			failed: stats.failedSessions,
			total: stats.totalSessions,
		};
	}
}

import { ServerConfigsSchema } from '../../mcp/config.js';
import { LLMConfigSchema } from '../llm/config.js';
import { EmbeddingConfigSchema } from '../embedding/config.js';
import { z } from 'zod';
export const AgentCardSchema = z
	.object({
		name: z.string().default('cipher'),
		description: z
			.string()
			.default(
				'cipher is an AI assistant capable of store valuable software development knowledge for your  vibe coding agents'
			),
		provider: z
			.object({
				organization: z.string().default('byterover-inc'),
				url: z.string().url().default('https://byterover.dev'),
			})
			.optional(),
		version: z.string().default('1.0.0'),
		defaultInputModes: z.array(z.string()).default(['application/json', 'text/plain']),
		defaultOutputModes: z
			.array(z.string())
			.default(['application/json', 'text/event-stream', 'text/plain']),
		skills: z
			.array(
				z.object({
					id: z.string(),
					name: z.string(),
					description: z.string(),
					tags: z.array(z.string()),
					examples: z.array(z.string()).optional(),
					inputModes: z.array(z.string()).optional().default(['text/plain']),
					outputModes: z.array(z.string()).optional().default(['text/plain']),
				})
			)
			.default([
				{
					id: 'chat_with_agent',
					name: 'chat_with_agent',
					description: 'Allows you to chat with an AI agent. Send a message to interact.',
					tags: ['chat', 'AI', 'assistant', 'mcp', 'natural language'],
					examples: [
						`Send a JSON-RPC request to /mcp with method: "chat_with_agent" and params: {"message":"Your query..."}`,
						'Alternatively, use a compatible MCP client library.',
					],
				},
			]),
	})
	.strict();
export const EventPersistenceConfigSchema = z.object({
	enabled: z.boolean().default(true),
	storageType: z.enum(['file', 'memory', 'database']).default('file'),
	maxEvents: z.number().optional(),
	rotationSize: z.number().optional(),
	retentionDays: z.number().optional(),
	filePath: z.string().optional(),
});
export const AgentConfigSchema = z
	.object({
		agentCard: AgentCardSchema.describe('Configuration for the agent card').optional(),
		systemPrompt: z
			.string()
			.describe(
				'The system prompt content as a string, or a structured system prompt configuration'
			),
		mcpServers: ServerConfigsSchema.default({}).describe(
			'Configurations for MCP (Model Context Protocol) servers used by the agent'
		),
		llm: LLMConfigSchema.describe('Core LLM configuration for the agent'),
		evalLlm: LLMConfigSchema.optional().describe(
			'Evaluation LLM configuration for non-thinking tasks (optional, falls back to main LLM if not provided)'
		),
		embedding: z
			.union([EmbeddingConfigSchema, z.object({ disabled: z.boolean() }), z.boolean(), z.null()])
			.optional()
			.describe(
				'Embedding configuration for the agent (optional, falls back to environment auto-detection if not provided). Set to false, null, or {disabled: true} to disable embeddings.'
			),
		sessions: z
			.object({
				maxSessions: z
					.number()
					.int()
					.positive()
					.default(100)
					.describe('Maximum number of concurrent sessions allowed, defaults to 100'),
				sessionTTL: z
					.number()
					.int()
					.positive()
					.default(3600000)
					.describe('Session time-to-live in milliseconds, defaults to 3600000ms (1 hour)'),
			})
			.default({
				maxSessions: 100,
				sessionTTL: 3600000,
			})
			.describe('Session management configuration'),
		eventPersistence: EventPersistenceConfigSchema.optional(),
	})
	.strict()
	.describe('Main configuration for an agent, including its LLM and server connections');
// Input type for user-facing API (pre-parsing) - makes fields with defaults optional
export type AgentConfig = z.input<typeof AgentConfigSchema>;

export { MemAgent } from './agent.js';
export { AgentConfig, AgentConfigSchema } from './config.js';
export { ConversationSession, SessionManager } from '../../session/index.js';

import { logger } from '../../logger/index.js';
import { AgentConfig } from './config.js';
import { parse as parseYaml } from 'yaml';
import { promises as fs } from 'fs';
import { env } from '../../env.js';

function expandEnvVars(config: any): any {
	if (typeof config === 'string') {
		const expanded = config.replace(
			/\$([A-Z_][A-Z0-9_]*)|\${([A-Z_][A-Z0-9_]*)}/gi,
			(_, v1, v2) => {
				const key = v1 || v2;
				return (env as any)[key] || '';
			}
		);

		// Try to convert numeric strings to numbers
		if (expanded !== config && /^-?\d+(\.\d+)?([eE][+-]?\d+)?$/.test(expanded.trim())) {
			return Number(expanded); // handles int, float, sci-notation
		}

		return expanded;
	} else if (Array.isArray(config)) {
		return config.map(expandEnvVars);
	} else if (typeof config === 'object' && config !== null) {
		const result: any = {};
		for (const key in config) {
			result[key] = expandEnvVars(config[key]);
		}
		return result;
	}
	return config;
}

export async function loadAgentConfig(configPath: string): Promise<AgentConfig> {
	try {
		// Determine where to load from: absolute, default, or user-relative

		logger.debug(`Loading cipher config from: ${configPath}`);

		// Read and parse the config file
		const fileContent = await fs.readFile(configPath, 'utf-8');

		try {
			// Parse YAML content
			const config = parseYaml(fileContent);
			// Expand env vars everywhere
			const expandedConfig = expandEnvVars(config);
			return expandedConfig;
		} catch (parseError) {
			throw new Error(
				`Failed to parse YAML: ${parseError instanceof Error ? parseError.message : String(parseError)}`
			);
		}
	} catch (error: any) {
		// Include path & cause for better diagnostics
		throw new Error(`Failed to load config file at ${error.path || configPath}: ${error.message}`);
	}
}

import { LLMConfig } from '../llm/config.js';
import { AgentConfig } from './config.js';
import { logger } from '../../logger/index.js';
import { McpServerValidationResult, validateMcpServerConfig } from '../../mcp/validation.js';
import { McpServerConfig } from '../../mcp/types.js';

export interface SessionOverride {
	/** Override LLM config for this session */
	llm?: Partial<LLMConfig>;
	/** Override evaluation LLM config for this session */
	evalLlm?: Partial<LLMConfig>;
}

export class MemAgentStateManager {
	private runtimeConfig: AgentConfig;
	private readonly baselineConfig: AgentConfig;
	private sessionOverrides: Map<string, SessionOverride> = new Map();

	constructor(staticConfig: AgentConfig) {
		this.baselineConfig = structuredClone(staticConfig);
		this.runtimeConfig = structuredClone(staticConfig);
	}

	public addMcpServer(
		serverName: string,
		serverConfig: McpServerConfig
	): McpServerValidationResult {
		logger.debug(`Adding/updating MCP server: ${serverName}`);

		// Ensure mcpServers is initialized
		if (!this.runtimeConfig.mcpServers) {
			this.runtimeConfig.mcpServers = {};
		}

		// Validate the server configuration
		const existingServerNames = Object.keys(this.runtimeConfig.mcpServers);
		const validation = validateMcpServerConfig(serverName, serverConfig, existingServerNames);

		if (!validation.isValid) {
			logger.warn('MCP server configuration validation failed', {
				serverName,
				errors: validation.errors.map(e => e.message),
				warnings: validation.warnings,
			});
			return validation;
		}

		// Log warnings if any
		if (validation.warnings.length > 0) {
			logger.warn('MCP server configuration warnings', {
				serverName,
				warnings: validation.warnings,
			});
		}

		const isUpdate = this.runtimeConfig.mcpServers && serverName in this.runtimeConfig.mcpServers;
		// Use the validated config with defaults applied from validation result
		this.runtimeConfig.mcpServers[serverName] = validation.config!;

		logger.info(`MCP server '${serverName}' ${isUpdate ? 'updated' : 'added'} successfully`);

		return validation;
	}

	public removeMcpServer(serverName: string): void {
		logger.debug(`Removing MCP server: ${serverName}`);

		if (this.runtimeConfig.mcpServers && serverName in this.runtimeConfig.mcpServers) {
			delete this.runtimeConfig.mcpServers[serverName];

			logger.info(`MCP server '${serverName}' removed successfully`);
		} else {
			logger.warn(`MCP server '${serverName}' not found for removal`);
		}
	}

	public getRuntimeConfig(sessionId?: string): Readonly<AgentConfig> {
		if (!sessionId) {
			return structuredClone(this.runtimeConfig);
		}

		const override = this.sessionOverrides.get(sessionId);
		if (!override) {
			return structuredClone(this.runtimeConfig);
		}

		const result = {
			...this.runtimeConfig,
			llm: { ...this.runtimeConfig.llm, ...override.llm },
		} as AgentConfig;

		if (override.evalLlm && this.runtimeConfig.evalLlm) {
			result.evalLlm = { ...this.runtimeConfig.evalLlm, ...override.evalLlm };
		} else if (override.evalLlm) {
			result.evalLlm = override.evalLlm as LLMConfig;
		} else {
			result.evalLlm = this.runtimeConfig.evalLlm;
		}

		return result;
	}

	public getLLMConfig(sessionId?: string): Readonly<LLMConfig> {
		const config = this.getRuntimeConfig(sessionId);
		return {
			...config.llm,
			maxIterations: config.llm.maxIterations ?? 10, // Provide default value
		};
	}

	/**
	 * Get evaluation LLM configuration with fallback to main LLM config
	 * Used for evaluation tasks that typically require non-thinking models
	 */
	public getEvalLLMConfig(sessionId?: string): Readonly<LLMConfig> {
		const config = this.getRuntimeConfig(sessionId);

		// If evalLlm is provided and valid, use it
		if (config.evalLlm) {
			try {
				// Validate the evalLlm configuration
				const evalConfig = {
					...config.evalLlm,
					maxIterations: config.evalLlm.maxIterations ?? 5, // Default for eval tasks
				};

				// Check if required fields are present
				if (evalConfig.provider && evalConfig.model) {
					logger.debug('Using configured evalLlm for evaluation tasks', {
						provider: evalConfig.provider,
						model: evalConfig.model,
					});
					return evalConfig;
				}
			} catch (error) {
				logger.warn('Invalid evalLlm configuration, falling back to main LLM', {
					error: error instanceof Error ? error.message : String(error),
					sessionId,
				});
			}
		}

		// Fallback to main LLM configuration
		const fallbackConfig = {
			...config.llm,
			maxIterations: 5, // Use lower iterations for eval tasks
		};

		logger.debug('Using fallback LLM configuration for evaluation tasks', {
			provider: fallbackConfig.provider,
			model: fallbackConfig.model,
			sessionId,
		});

		return fallbackConfig;
	}

	/**
	 * Update LLM configuration globally or for a specific session
	 */
	public updateLLMConfig(newConfig: Partial<LLMConfig>, sessionId?: string): void {
		if (sessionId) {
			// Update session-specific config
			const existingOverride = this.sessionOverrides.get(sessionId) || {};
			this.sessionOverrides.set(sessionId, {
				...existingOverride,
				llm: { ...existingOverride.llm, ...newConfig },
			});
			logger.info(`Updated LLM config for session ${sessionId}`, { newConfig });
		} else {
			// Update global runtime config
			this.runtimeConfig.llm = { ...this.runtimeConfig.llm, ...newConfig };
			logger.info('Updated global LLM config', { newConfig });
		}
	}

	/**
	 * Remove session-specific LLM configuration override
	 */
	public clearSessionLLMOverride(sessionId: string): void {
		const override = this.sessionOverrides.get(sessionId);
		if (override) {
			if (override.llm) {
				delete override.llm;
				if (Object.keys(override).length === 0) {
					this.sessionOverrides.delete(sessionId);
				}
				logger.info(`Cleared LLM config override for session ${sessionId}`);
			}
		}
	}

	/**
	 * Get all active session overrides (for debugging/inspection)
	 */
	public getSessionOverrides(): Map<string, SessionOverride> {
		return new Map(this.sessionOverrides);
	}
}

/**
 * Enhanced Service Initializer with Lazy Loading Support
 *
 * Extends the existing service initializer to support lazy loading of expensive services.
 * This provides backward compatibility while adding performance optimizations.
 */

import { AgentConfig } from '../memAgent/config.js';
import { createAgentServices } from '../../utils/service-initializer.js';
import { logger } from '../../logger/index.js';
import { EmbeddingManager } from '../embedding/index.js';
import { VectorStoreManager, DualCollectionVectorManager } from '../../vector_storage/index.js';
import { ILLMService } from '../llm/index.js';
import { createLLMService } from '../llm/services/factory.js';
import { createContextManager } from '../llm/messages/factory.js';
import {
	createVectorStoreFromEnv,
	createDualCollectionVectorStoreFromEnv,
} from '../../vector_storage/factory.js';
import { env } from '../../env.js';
import {
	LazyEmbeddingManager,
	LazyVectorStoreManager,
	LazyLLMService,
	type LazyAgentServices,
	type LazyServiceConfig,
	getDefaultLazyConfig,
} from './lazy-service-wrapper.js';

// Re-export LazyAgentServices for external use
export type { LazyAgentServices };

/**
 * Enhanced service creation options
 */
export interface EnhancedServiceOptions {
	/**
	 * Enable lazy loading optimizations
	 */
	enableLazyLoading?: boolean;

	/**
	 * Lazy loading configuration
	 */
	lazyConfig?: LazyServiceConfig;

	/**
	 * App mode for service initialization
	 */
	appMode?: 'cli' | 'mcp' | 'api' | undefined;
}

/**
 * Create agent services with optional lazy loading support
 */
export async function createEnhancedAgentServices(
	agentConfig: AgentConfig,
	options: EnhancedServiceOptions = {}
): Promise<LazyAgentServices> {
	const startTime = Date.now();

	// Get lazy loading configuration
	const lazyConfig: LazyServiceConfig = {
		...getDefaultLazyConfig(),
		...options.lazyConfig,
		// Override with explicit option
		...(options.enableLazyLoading !== undefined && {
			enableEmbeddingLazy: options.enableLazyLoading,
			enableVectorStoreLazy: options.enableLazyLoading,
			enableLLMServiceLazy: options.enableLazyLoading,
		}),
	};

	const shouldUseLazyLoading =
		options.enableLazyLoading ??
		(env.ENABLE_LAZY_LOADING === 'true' || lazyConfig.skipHeavyServicesOnStartup);

	logger.debug('EnhancedServiceInitializer: Starting service initialization', {
		lazyLoading: shouldUseLazyLoading,
		appMode: options.appMode,
		skipHeavyServices: lazyConfig.skipHeavyServicesOnStartup,
	});

	if (!shouldUseLazyLoading) {
		// Use standard service initialization
		logger.debug('EnhancedServiceInitializer: Using standard service initialization');
		const services = await createAgentServices(agentConfig, options.appMode);
		const initTime = Date.now() - startTime;

		logger.debug(`EnhancedServiceInitializer: Standard initialization completed in ${initTime}ms`);

		return {
			...services,
			lazyConfig,
		};
	}

	// Use lazy loading initialization
	logger.debug('EnhancedServiceInitializer: Using lazy loading initialization');

	// Create a modified config that skips heavy services initially
	const modifiedConfig = { ...agentConfig };

	// Temporarily disable embedding if lazy loading is enabled for it
	let originalEmbeddingConfig: any = null;
	if (lazyConfig.enableEmbeddingLazy && lazyConfig.skipHeavyServicesOnStartup) {
		originalEmbeddingConfig = modifiedConfig.embedding;
		(modifiedConfig as any).embedding = { disabled: true };
	}

	// Create core services (lightweight initialization)
	const coreServices = await createAgentServices(modifiedConfig, options.appMode);

	// Restore original config
	if (originalEmbeddingConfig !== null) {
		(modifiedConfig as any).embedding = originalEmbeddingConfig;
	}

	// Create lazy service wrappers
	const lazyServices: LazyAgentServices = {
		...coreServices,
		lazyConfig,
	};

	// Create lazy embedding manager if needed
	if (lazyConfig.enableEmbeddingLazy) {
		lazyServices.lazyEmbeddingManager = new LazyEmbeddingManager(async () => {
			logger.debug('LazyEmbeddingManager: Creating embedding manager');
			const embeddingManager = new EmbeddingManager();

			if (agentConfig.embedding && typeof agentConfig.embedding === 'object') {
				const result = await embeddingManager.createEmbedderFromConfig(
					agentConfig.embedding as any,
					'default'
				);
				if (!result) {
					throw new Error('Failed to create embedder from config');
				}
			}

			return embeddingManager;
		}, lazyConfig);

		// Remove the original embedding manager to ensure lazy loading is used
		if (lazyConfig.skipHeavyServicesOnStartup) {
			delete lazyServices.embeddingManager;
		}
	}

	// Create lazy vector store manager if needed
	if (lazyConfig.enableVectorStoreLazy) {
		lazyServices.lazyVectorStoreManager = new LazyVectorStoreManager(async () => {
			logger.debug('LazyVectorStoreManager: Creating vector store manager');

			// Check if reflection memory is enabled
			const reflectionEnabled =
				!env.DISABLE_REFLECTION_MEMORY &&
				env.REFLECTION_VECTOR_STORE_COLLECTION &&
				env.REFLECTION_VECTOR_STORE_COLLECTION.trim() !== '';

			if (reflectionEnabled) {
				const { manager } = await createDualCollectionVectorStoreFromEnv(agentConfig);
				return manager;
			} else {
				const { manager } = await createVectorStoreFromEnv(agentConfig);
				return manager;
			}
		}, lazyConfig);
	}

	// Create lazy LLM service if needed
	if (lazyConfig.enableLLMServiceLazy) {
		lazyServices.lazyLLMService = new LazyLLMService(async () => {
			logger.debug('LazyLLMService: Creating LLM service');

			const llmConfig = { ...agentConfig.llm, maxIterations: agentConfig.llm.maxIterations || 50 };
			const contextManager = createContextManager(
				llmConfig,
				coreServices.promptManager,
				undefined,
				undefined
			);

			const llmService = createLLMService(llmConfig, coreServices.mcpManager, contextManager);

			return llmService;
		}, lazyConfig);

		// Remove the original LLM service to ensure lazy loading is used
		if (lazyConfig.skipHeavyServicesOnStartup) {
			delete lazyServices.llmService;
		}
	}

	const initTime = Date.now() - startTime;

	logger.info('EnhancedServiceInitializer: Lazy initialization completed', {
		initTime: `${initTime}ms`,
		lazyEmbedding: !!lazyServices.lazyEmbeddingManager,
		lazyVectorStore: !!lazyServices.lazyVectorStoreManager,
		lazyLLMService: !!lazyServices.lazyLLMService,
	});

	return lazyServices;
}

/**
 * Check if lazy loading should be enabled based on environment and configuration
 */
export function shouldEnableLazyLoading(options: EnhancedServiceOptions = {}): boolean {
	if (options.enableLazyLoading !== undefined) {
		return options.enableLazyLoading;
	}

	const lazyConfig = getDefaultLazyConfig();

	return (
		env.ENABLE_LAZY_LOADING === 'true' ||
		Boolean(lazyConfig.skipHeavyServicesOnStartup) ||
		Boolean(lazyConfig.enableEmbeddingLazy) ||
		Boolean(lazyConfig.enableVectorStoreLazy) ||
		Boolean(lazyConfig.enableLLMServiceLazy)
	);
}

/**
 * Utility to get a service from lazy or regular services
 */
export async function getEmbeddingManager(
	services: LazyAgentServices
): Promise<EmbeddingManager | undefined> {
	if (services.lazyEmbeddingManager) {
		try {
			return await services.lazyEmbeddingManager.getInstance();
		} catch (error) {
			logger.warn('Failed to get lazy embedding manager', {
				error: error instanceof Error ? error.message : String(error),
			});
			return undefined;
		}
	}
	return services.embeddingManager;
}

/**
 * Utility to get vector store manager from lazy or regular services
 */
export async function getVectorStoreManager(
	services: LazyAgentServices
): Promise<VectorStoreManager | DualCollectionVectorManager | undefined> {
	if (services.lazyVectorStoreManager) {
		try {
			return await services.lazyVectorStoreManager.getInstance();
		} catch (error) {
			logger.warn('Failed to get lazy vector store manager', {
				error: error instanceof Error ? error.message : String(error),
			});
			return undefined;
		}
	}
	return services.vectorStoreManager;
}

/**
 * Utility to get LLM service from lazy or regular services
 */
export async function getLLMService(services: LazyAgentServices): Promise<ILLMService | undefined> {
	if (services.lazyLLMService) {
		try {
			return await services.lazyLLMService.getInstance();
		} catch (error) {
			logger.warn('Failed to get lazy LLM service', {
				error: error instanceof Error ? error.message : String(error),
			});
			return undefined;
		}
	}
	return services.llmService;
}

/**
 * Memory System with Lazy Loading Optimizations
 *
 * Memory-related functionality for the Cipher agent with performance optimizations.
 * Phase 3: Memory operations lazy loading - properly integrated into the application.
 */

// Export lazy loading service wrappers
export {
	LazyEmbeddingManager,
	LazyVectorStoreManager,
	LazyLLMService,
	getDefaultLazyConfig,
	type LazyServiceConfig,
	type LazyAgentServices,
} from './lazy-service-wrapper.js';

// Export enhanced service initializer
export {
	createEnhancedAgentServices,
	shouldEnableLazyLoading,
	getEmbeddingManager,
	getVectorStoreManager,
	getLLMService,
	type EnhancedServiceOptions,
} from './enhanced-service-initializer.js';

// Export lazy memory tool
export { lazyExtractAndOperateMemoryTool } from './lazy-extract-and-operate.js';

/**
 * Lazy Extract and Operate Memory Tool
 *
 * Enhanced version of the extract_and_operate_memory tool that uses lazy loading
 * to defer expensive operations until they are actually needed.
 */

import { InternalTool, InternalToolContext } from '../tools/types.js';
import { logger } from '../../logger/index.js';
import {
	getEmbeddingManager,
	getVectorStoreManager,
	getLLMService,
	LazyAgentServices,
} from './enhanced-service-initializer.js';

// Import the original tool's functionality
import { extractAndOperateMemoryTool } from '../tools/definitions/memory/extract_and_operate_memory.js';
import { env } from '../../env.js';

/**
 * Lazy loading configuration for memory operations
 */
interface LazyMemoryOperationConfig {
	/**
	 * Enable lazy loading for memory operations
	 */
	enableLazyLoading?: boolean;

	/**
	 * Minimum facts threshold to trigger lazy loading
	 */
	lazyLoadingThreshold?: number;

	/**
	 * Enable lightweight processing for simple operations
	 */
	enableLightweightProcessing?: boolean;

	/**
	 * Timeout for lazy operations (ms)
	 */
	operationTimeout?: number;
}

/**
 * Get lazy memory operation configuration from environment
 */
function getLazyMemoryConfig(): LazyMemoryOperationConfig {
	return {
		enableLazyLoading: env.ENABLE_LAZY_LOADING === 'true',
		lazyLoadingThreshold: 3,
		enableLightweightProcessing: true,
		operationTimeout: 8000,
	};
}

/**
 * Enhanced extract and operate memory tool with lazy loading
 */
export const lazyExtractAndOperateMemoryTool: InternalTool = {
	name: 'lazy_extract_and_operate_memory',
	category: 'memory',
	internal: true,
	description: extractAndOperateMemoryTool.description + ' (with lazy loading optimizations)',
	version: '2.0.0',
	parameters: extractAndOperateMemoryTool.parameters,

	handler: async (args: any, context?: InternalToolContext) => {
		const startTime = Date.now();
		const lazyConfig = getLazyMemoryConfig();

		try {
			// Check if we should use lazy loading
			const shouldUseLazyLoading =
				lazyConfig.enableLazyLoading &&
				context?.services &&
				'lazyEmbeddingManager' in context.services;

			if (!shouldUseLazyLoading) {
				// Fall back to original tool
				logger.debug('LazyExtractAndOperate: Using standard processing');
				return await extractAndOperateMemoryTool.handler(args, context);
			}

			const lazyServices = context!.services as LazyAgentServices;

			// Check if this is a simple operation that can be processed without heavy services
			const interaction = args.interaction || '';
			const isSimpleOperation =
				interaction.length < 100 &&
				!interaction.includes('```') &&
				!interaction.includes('function') &&
				!interaction.includes('class');

			if (lazyConfig.enableLightweightProcessing && isSimpleOperation) {
				logger.debug('LazyExtractAndOperate: Using lightweight processing for simple operation');
				return processLightweight(args, startTime);
			}

			// For complex operations, load services lazily
			logger.debug('LazyExtractAndOperate: Loading services lazily for complex operation');

			// Load only the services we actually need
			const embeddingManager = await getEmbeddingManager(lazyServices);
			if (!embeddingManager) {
				logger.warn('LazyExtractAndOperate: No embedding manager available, skipping');
				return createEmptyResult(args, startTime);
			}

			// Create enhanced context with loaded services
			const vectorStoreManager = await getVectorStoreManager(lazyServices);
			const llmService = await getLLMService(lazyServices);

			const enhancedContext: InternalToolContext = {
				...context,
				services: {
					embeddingManager,
					vectorStoreManager: vectorStoreManager as any,
					llmService: llmService!,
					knowledgeGraphManager: lazyServices.knowledgeGraphManager,
				},
			};

			// Use the original tool with enhanced context
			const result = await extractAndOperateMemoryTool.handler(args, enhancedContext);

			const processingTime = Date.now() - startTime;
			logger.debug(`LazyExtractAndOperate: Completed lazy processing in ${processingTime}ms`);

			return result;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			logger.error('LazyExtractAndOperate: Error during lazy processing', {
				error: error instanceof Error ? error.message : String(error),
				processingTime: `${processingTime}ms`,
			});

			// Fall back to original tool on error
			try {
				return await extractAndOperateMemoryTool.handler(args, context);
			} catch (fallbackError) {
				logger.error('LazyExtractAndOperate: Fallback also failed', {
					fallbackError:
						fallbackError instanceof Error ? fallbackError.message : String(fallbackError),
				});
				throw error; // Throw original error
			}
		}
	},
};

/**
 * Process simple operations without heavy services
 */
function processLightweight(args: any, startTime: number) {
	// const interaction = args.interaction || '';
	const processingTime = Date.now() - startTime;

	logger.debug(`LazyExtractAndOperate: Lightweight processing completed in ${processingTime}ms`);

	// Return a simple response for lightweight operations
	return {
		success: true,
		extracted_facts: [],
		memory_operations: [],
		processing_summary: {
			total_facts: 0,
			memory_operations: 0,
			processing_mode: 'lightweight',
			processing_time_ms: processingTime,
		},
		message: 'Processed with lightweight optimization - no significant technical content detected.',
	};
}

/**
 * Create empty result for operations that cannot be processed
 */
function createEmptyResult(args: any, startTime: number) {
	const processingTime = Date.now() - startTime;

	return {
		success: false,
		extracted_facts: [],
		memory_operations: [],
		processing_summary: {
			total_facts: 0,
			memory_operations: 0,
			processing_mode: 'skipped',
			processing_time_ms: processingTime,
		},
		message: 'Memory operations skipped - required services not available.',
	};
}

/**
 * Lazy Service Wrapper
 *
 * Provides lazy loading wrappers for expensive services that can be deferred
 * until they are actually needed. This integrates with the existing service
 * initializer without breaking the current architecture.
 */

import { logger } from '../../logger/index.js';
import { EmbeddingManager } from '../embedding/index.js';
import { VectorStoreManager, DualCollectionVectorManager } from '../../vector_storage/index.js';
import { ILLMService } from '../llm/index.js';
import { env } from '../../env.js';

/**
 * Configuration for lazy loading services
 */
export interface LazyServiceConfig {
	/**
	 * Enable lazy loading for embedding manager
	 */
	enableEmbeddingLazy?: boolean;

	/**
	 * Enable lazy loading for vector store manager
	 */
	enableVectorStoreLazy?: boolean;

	/**
	 * Enable lazy loading for LLM service
	 */
	enableLLMServiceLazy?: boolean;

	/**
	 * Timeout for lazy initialization (ms)
	 */
	lazyInitTimeout?: number;

	/**
	 * Skip heavy services during initial startup
	 */
	skipHeavyServicesOnStartup?: boolean;
}

/**
 * Default lazy service configuration from environment
 */
export function getDefaultLazyConfig(): LazyServiceConfig {
	return {
		enableEmbeddingLazy: env.ENABLE_LAZY_LOADING === 'true',
		enableVectorStoreLazy: env.ENABLE_LAZY_LOADING === 'true',
		enableLLMServiceLazy: env.ENABLE_LAZY_LOADING === 'true',
		lazyInitTimeout: parseInt(env.LAZY_INIT_TIMEOUT || '10000', 10),
		skipHeavyServicesOnStartup: env.ENABLE_LAZY_LOADING === 'true',
	};
}

/**
 * Lazy wrapper for EmbeddingManager
 */
export class LazyEmbeddingManager {
	private _instance: EmbeddingManager | null = null;
	private _loading: Promise<EmbeddingManager> | null = null;
	private _factory: (() => Promise<EmbeddingManager>) | null = null;
	private _config: LazyServiceConfig;

	constructor(factory: () => Promise<EmbeddingManager>, config: LazyServiceConfig = {}) {
		this._factory = factory;
		this._config = { ...getDefaultLazyConfig(), ...config };
	}

	/**
	 * Get the embedding manager, loading it lazily if needed
	 */
	async getInstance(): Promise<EmbeddingManager> {
		if (this._instance) {
			return this._instance;
		}

		if (this._loading) {
			return this._loading;
		}

		if (!this._factory) {
			throw new Error('LazyEmbeddingManager: No factory provided');
		}

		logger.debug('LazyEmbeddingManager: Loading embedding manager');
		const startTime = Date.now();

		this._loading = Promise.race([
			this._factory(),
			new Promise<never>((_, reject) => {
				setTimeout(() => {
					reject(
						new Error(`LazyEmbeddingManager: Timeout after ${this._config.lazyInitTimeout}ms`)
					);
				}, this._config.lazyInitTimeout || 10000);
			}),
		]);

		try {
			this._instance = await this._loading;
			const loadTime = Date.now() - startTime;
			logger.debug(`LazyEmbeddingManager: Loaded in ${loadTime}ms`);
			return this._instance;
		} catch (error) {
			this._loading = null;
			throw error;
		}
	}

	/**
	 * Check if the service is already loaded
	 */
	isLoaded(): boolean {
		return this._instance !== null;
	}

	/**
	 * Get the instance if already loaded, otherwise return null
	 */
	getLoadedInstance(): EmbeddingManager | null {
		return this._instance;
	}
}

