	 */
	getLoadedInstance(): ILLMService | null {
		return this._instance;
	}
}

/**
 * Enhanced agent services with lazy loading support
 */
export interface LazyAgentServices {
	[key: string]: any;
	// Always loaded core services
	mcpManager: any;
	promptManager: any;
	stateManager: any;
	sessionManager: any;
	internalToolManager: any;
	unifiedToolManager: any;
	eventManager: any;

	// Original services for compatibility (may be undefined if lazy)
	embeddingManager?: EmbeddingManager;
	vectorStoreManager?: VectorStoreManager | DualCollectionVectorManager;
	llmService?: ILLMService;
	knowledgeGraphManager?: any;

	// Lazy service wrappers
	lazyEmbeddingManager?: LazyEmbeddingManager;
	lazyVectorStoreManager?: LazyVectorStoreManager;
	lazyLLMService?: LazyLLMService;

	// Configuration
	lazyConfig?: LazyServiceConfig;
}

/**
 * Service Cache
 *
 * Global cache for expensive service instances to avoid redundant initializations
 */

import { logger } from '../../logger/index.js';

/**
 * Global service cache to prevent redundant initializations
 */
class ServiceCache {
	private static instance: ServiceCache | null = null;
	private cache = new Map<string, any>();
	private initPromises = new Map<string, Promise<any>>();

	static getInstance(): ServiceCache {
		if (!ServiceCache.instance) {
			ServiceCache.instance = new ServiceCache();
		}
		return ServiceCache.instance;
	}

	/**
	 * Get or create a cached service
	 */
	async getOrCreate<T>(
		key: string,
		factory: () => Promise<T>,
		options: { ttl?: number } = {}
	): Promise<T> {
		// Return cached instance if available
		if (this.cache.has(key)) {
			logger.debug(`ServiceCache: Cache hit for ${key}`);
			return this.cache.get(key);
		}

		// Return existing promise if creation is in progress
		if (this.initPromises.has(key)) {
			logger.debug(`ServiceCache: Waiting for in-progress creation of ${key}`);
			return await this.initPromises.get(key)!;
		}

		// Create new instance
		logger.debug(`ServiceCache: Cache miss, creating ${key}`, {
			cacheSize: this.cache.size,
			pendingPromises: this.initPromises.size,
			existingKeys: Array.from(this.cache.keys()).slice(0, 5), // Show first 5 keys for debugging
		});
		const promise = factory();
		this.initPromises.set(key, promise);

		try {
			const instance = await promise;
			this.cache.set(key, instance);
			this.initPromises.delete(key);

			// Set TTL if specified
			if (options.ttl) {
				setTimeout(() => {
					this.cache.delete(key);
					logger.debug(`ServiceCache: Expired ${key} after ${options.ttl}ms`);
				}, options.ttl);
			}

			logger.debug(`ServiceCache: Cached ${key}`);
			return instance;
		} catch (error) {
			this.initPromises.delete(key);
			throw error;
		}
	}

	/**
	 * Check if a service is cached
	 */
	has(key: string): boolean {
		return this.cache.has(key);
	}

	/**
	 * Clear the cache
	 */
	clear(): void {
		this.cache.clear();
		this.initPromises.clear();
		logger.debug('ServiceCache: Cache cleared');
	}

	/**
	 * Get cache statistics
	 */
	getStats() {
		return {
			cacheSize: this.cache.size,
			pendingPromises: this.initPromises.size,
			cachedKeys: Array.from(this.cache.keys()),
		};
	}
}

/**
 * Convenience function to get the global service cache
 */
export function getServiceCache(): ServiceCache {
	return ServiceCache.getInstance();
}

/**
 * Create a cache key for a service
 */
export function createServiceKey(type: string, config?: any): string {
	if (!config) {
		return type;
	}

	// Normalize config to ensure consistent cache keys
	const normalizedConfig = normalizeConfigForCache(config);

	// Create a simple hash of the normalized config
	const configStr = JSON.stringify(normalizedConfig);
	const hash = Array.from(configStr).reduce((hash, char) => {
		return (hash << 5) - hash + char.charCodeAt(0);
	}, 0);

	const cacheKey = `${type}:${Math.abs(hash)}`;

	return cacheKey;
}

/**
 * Normalize configuration for consistent cache key generation
 */
function normalizeConfigForCache(config: any): any {
	if (!config || typeof config !== 'object') {
		return config;
	}

	const normalized: any = {};

	for (const [key, value] of Object.entries(config)) {
		// Normalize undefined/null values to empty strings
		if (value === undefined || value === null) {
			normalized[key] = '';
		}
		// Normalize boolean values
		else if (typeof value === 'boolean') {
			normalized[key] = value;
		}
		// Normalize strings (trim and lowercase for case-insensitive keys)
		else if (typeof value === 'string') {
			normalized[key] = value.trim().toLowerCase();
		}
		// Keep numbers and other primitives as-is
		else if (typeof value !== 'object') {
			normalized[key] = value;
		}
		// Recursively normalize nested objects
		else {
			normalized[key] = normalizeConfigForCache(value);
		}
	}

	return normalized;
}

/**
 * Tests for Content-Based Reasoning Detection
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ReasoningContentDetector } from '../content-detector.js';
import { MCPManager } from '../../../mcp/manager.js';
import { UnifiedToolManager } from '../../tools/unified-tool-manager.js';
import { EnhancedPromptManager } from '../../systemPrompt/enhanced-manager.js';

// Mock dependencies
vi.mock('../../../mcp/manager.js');
vi.mock('../../tools/unified-tool-manager.js');
vi.mock('../../../logger/index.js', () => ({
	logger: {
		debug: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
	},
}));

describe('ReasoningContentDetector', () => {
	let detector: ReasoningContentDetector;
	let mockMcpManager: MCPManager;
	let mockUnifiedToolManager: UnifiedToolManager;
	let mockEvalLlmConfig: any;
	let mockPromptManager: EnhancedPromptManager;

	beforeEach(() => {
		mockPromptManager = {} as EnhancedPromptManager;
		mockMcpManager = {} as MCPManager;
		mockUnifiedToolManager = {} as UnifiedToolManager;

		// Mock evalLlmConfig for testing
		mockEvalLlmConfig = {
			provider: 'openai',
			model: 'gpt-4o-mini',
			apiKey: 'test-api-key',
			maxIterations: 3,
		};

		detector = new ReasoningContentDetector(
			mockPromptManager,
			mockMcpManager,
			mockUnifiedToolManager,
			mockEvalLlmConfig,
			undefined
		);
	});

	describe('LLM-based detection', () => {
		it('should detect reasoning content', async () => {
			const input =
				'Let me think about this problem step by step. First, I need to analyze the requirements.';

			const result = await detector.detectReasoningContent(input);

			// Since we're mocking the LLM service, we expect it to return false
			// In real usage, this would be determined by the LLM analysis
			expect(result.containsReasoning).toBeDefined();
			expect(result.confidence).toBeGreaterThanOrEqual(0);
			expect(result.confidence).toBeLessThanOrEqual(1);
		});

		it('should handle simple statements', async () => {
			const input = 'Hello, how are you today?';

			const result = await detector.detectReasoningContent(input);

			expect(result.containsReasoning).toBeDefined();
			expect(result.confidence).toBeGreaterThanOrEqual(0);
			expect(result.confidence).toBeLessThanOrEqual(1);
		});

		it('should handle technical reasoning patterns', async () => {
			const input = 'I need to optimize this algorithm for better performance and scalability.';

			const result = await detector.detectReasoningContent(input);

			expect(result.containsReasoning).toBeDefined();
			expect(result.confidence).toBeGreaterThanOrEqual(0);
			expect(result.confidence).toBeLessThanOrEqual(1);
		});
	});

	describe('Options and configuration', () => {
		it('should use default options when none provided', () => {
			const options = detector.getOptions();

			expect(options.confidenceThreshold).toBe(0.7);
			expect(options.maxPatterns).toBe(10);
		});

		it('should allow custom options', () => {
			const customOptions = {
				confidenceThreshold: 0.9,
				maxPatterns: 5,
			};

			detector.updateOptions(customOptions);
			const options = detector.getOptions();

			expect(options.confidenceThreshold).toBe(0.9);
			expect(options.maxPatterns).toBe(5);
		});

		it('should limit detected patterns to maxPatterns', async () => {
			detector.updateOptions({ maxPatterns: 3 });

			const input =
				'Let me think about this: First, I need to analyze the problem. Then I can figure out the solution. Finally, I can implement it.';

			const result = await detector.detectReasoningContent(input);

			expect(result.detectedPatterns.length).toBeLessThanOrEqual(3);
		});
	});

	describe('Error handling', () => {
		it('should handle empty input gracefully', async () => {
			const result = await detector.detectReasoningContent('');

			expect(result.containsReasoning).toBe(false);
			expect(result.confidence).toBe(0);
			expect(result.detectedPatterns).toHaveLength(0);
		});

		it('should handle very short input', async () => {
			const result = await detector.detectReasoningContent('Hi');

			expect(result.containsReasoning).toBe(false);
			expect(result.confidence).toBeLessThan(0.6);
		});

		it('should handle input with only whitespace', async () => {
			const result = await detector.detectReasoningContent('   \n\t   ');

			expect(result.containsReasoning).toBe(false);
			expect(result.confidence).toBe(0);
		});
	});

	describe('Context handling', () => {
		it('should accept context parameters', async () => {
			const input = 'Let me analyze this problem.';
			const context = {
				sessionId: 'test-session',
				taskType: 'debugging',
				recentMessages: ['Previous message'],
			};

			const result = await detector.detectReasoningContent(input, context);

			// Since we're mocking the LLM service, we expect it to return false
			// In real usage, this would be determined by the LLM analysis
			expect(result.containsReasoning).toBeDefined();
			expect(result.confidence).toBeGreaterThanOrEqual(0);
			expect(result.confidence).toBeLessThanOrEqual(1);
		});
	});
});

/**
 * Tests for Search Context Manager
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { SearchContextManager } from '../search-context-manager.js';

// Mock logger
vi.mock('../../../../logger/index.js', () => ({
	logger: {
		debug: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
	},
}));

describe('SearchContextManager', () => {
	let manager: SearchContextManager;

	beforeEach(() => {
		manager = new SearchContextManager();
	});

	describe('Processing search results', () => {
		it('should process empty search results', async () => {
			const searchResults = {};

			const result = await manager.processSearchResults(searchResults);

			expect(result.primaryResults).toHaveLength(0);
			expect(result.secondaryResults).toHaveLength(0);
			expect(result.totalResults).toBe(0);
			expect(result.summary).toBe('No relevant search results found.');
			expect(result.sourcesUsed).toHaveLength(0);
		});

		it('should process graph search results', async () => {
			const searchResults = {
				graph: [
					{
						content: 'Graph node 1',
						relevance: 0.8,
						metadata: { nodeType: 'concept' },
					},
					{
						content: 'Graph node 2',
						relevance: 0.6,
						metadata: { nodeType: 'entity' },
					},
				],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.primaryResults).toHaveLength(2);
			expect(result.secondaryResults).toHaveLength(0);
			expect(result.totalResults).toBe(2);
			expect(result.sourcesUsed).toContain('graph');
			expect(result.primaryResults[0]?.source).toBe('graph');
			expect(result.primaryResults[0]?.content).toBe('Graph node 1');
			expect(result.primaryResults[0]?.relevance).toBe(0.8);
		});

		it('should process memory search results', async () => {
			const searchResults = {
				memory: [
					{
						content: 'Memory fact 1',
						relevance: 0.9,
						metadata: { memoryType: 'fact' },
					},
					{
						content: 'Memory fact 2',
						relevance: 0.7,
						metadata: { memoryType: 'experience' },
					},
				],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.primaryResults).toHaveLength(2);
			expect(result.sourcesUsed).toContain('memory');
			expect(result.primaryResults[0]?.source).toBe('memory');
			expect(result.primaryResults[0]?.content).toBe('Memory fact 1');
			expect(result.primaryResults[0]?.relevance).toBe(0.9);
		});

		it('should process reasoning patterns search results', async () => {
			const searchResults = {
				reasoning_patterns: [
					{
						content: 'Reasoning pattern 1',
						relevance: 0.85,
						metadata: { patternType: 'problem_solving' },
					},
				],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.primaryResults).toHaveLength(1);
			expect(result.sourcesUsed).toContain('reasoning_patterns');
			expect(result.primaryResults[0]?.source).toBe('reasoning_patterns');
			expect(result.primaryResults[0]?.content).toBe('Reasoning pattern 1');
		});

		it('should process mixed search results', async () => {
			const searchResults = {
				graph: [{ content: 'Graph result', relevance: 0.8 }],
				memory: [{ content: 'Memory result', relevance: 0.7 }],
				reasoning_patterns: [{ content: 'Reasoning result', relevance: 0.9 }],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.totalResults).toBe(3);
			expect(result.sourcesUsed).toContain('graph');
			expect(result.sourcesUsed).toContain('memory');
			expect(result.sourcesUsed).toContain('reasoning_patterns');
			expect(result.primaryResults).toHaveLength(3);
		});

		it('should sort results by relevance', async () => {
			const searchResults = {
				memory: [
					{ content: 'Low relevance', relevance: 0.5 },
					{ content: 'High relevance', relevance: 0.9 },
					{ content: 'Medium relevance', relevance: 0.7 },
				],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.primaryResults[0]?.content).toBe('High relevance');
			expect(result.primaryResults[0]?.relevance).toBe(0.9);
			expect(result.primaryResults[1]?.content).toBe('Medium relevance');
			expect(result.primaryResults[1]?.relevance).toBe(0.7);
			// Note: Low relevance result might be filtered out due to relevance threshold
		});

		it('should filter results by relevance threshold', async () => {
			manager.updateOptions({ relevanceThreshold: 0.7 });

			const searchResults = {
				memory: [
					{ content: 'High relevance', relevance: 0.9 },
					{ content: 'Medium relevance', relevance: 0.6 },
					{ content: 'Low relevance', relevance: 0.3 },
				],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.totalResults).toBe(1);
			expect(result.primaryResults[0]?.content).toBe('High relevance');
		});

		it('should split results into primary and secondary', async () => {
			manager.updateOptions({ maxPrimaryResults: 2, maxSecondaryResults: 2 });

			const searchResults = {
				memory: [
					{ content: 'Result 1', relevance: 0.9 },
					{ content: 'Result 2', relevance: 0.8 },
					{ content: 'Result 3', relevance: 0.7 },
					{ content: 'Result 4', relevance: 0.6 },
					{ content: 'Result 5', relevance: 0.5 },
				],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.primaryResults).toHaveLength(2);
			expect(result.secondaryResults).toHaveLength(2);
			expect(result.primaryResults[0]?.content).toBe('Result 1');
			expect(result.primaryResults[1]?.content).toBe('Result 2');
			expect(result.secondaryResults[0]?.content).toBe('Result 3');
			expect(result.secondaryResults[1]?.content).toBe('Result 4');
		});
	});

	describe('Deduplication', () => {
		it('should deduplicate identical results', async () => {
			const searchResults = {
				memory: [
					{ content: 'Same content', relevance: 0.8 },
					{ content: 'Same content', relevance: 0.9 },
					{ content: 'Different content', relevance: 0.7 },
				],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.totalResults).toBe(2);
			expect(result.primaryResults[0]?.content).toBe('Same content');
			expect(result.primaryResults[0]?.relevance).toBe(0.9); // Higher relevance kept
		});

		it('should not deduplicate when disabled', async () => {
			manager.updateOptions({ enableDeduplication: false });

			const searchResults = {
				memory: [
					{ content: 'Same content', relevance: 0.8 },
					{ content: 'Same content', relevance: 0.9 },
				],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.totalResults).toBe(2);
		});
	});

	// Content extraction is tested implicitly through other tests

	describe('Metadata extraction', () => {
		it('should extract source-specific metadata', async () => {
			const searchResults = {
				graph: [
					{
						content: 'Graph node',
						relevance: 0.8,
						type: 'concept',
						relationships: ['rel1', 'rel2'],
					},
				],
				memory: [
					{
						content: 'Memory fact',
						relevance: 0.8,
						memoryType: 'fact',
						sessionId: 'session-1',
						extractedAt: '2023-01-01',
					},
				],
				reasoning_patterns: [
					{
						content: 'Reasoning pattern',
						relevance: 0.8,
						patternType: 'problem_solving',
						qualityScore: 0.9,
						stepCount: 5,
					},
				],
			};

			const result = await manager.processSearchResults(searchResults);

			const graphResult = result.primaryResults.find(r => r.source === 'graph');
			const memoryResult = result.primaryResults.find(r => r.source === 'memory');
			const reasoningResult = result.primaryResults.find(r => r.source === 'reasoning_patterns');

			expect(graphResult?.metadata?.nodeType).toBe('concept');
			expect(graphResult?.metadata?.relationships).toEqual(['rel1', 'rel2']);

			expect(memoryResult?.metadata?.memoryType).toBe('fact');
			expect(memoryResult?.metadata?.sessionId).toBe('session-1');
			expect(memoryResult?.metadata?.extractedAt).toBe('2023-01-01');

			expect(reasoningResult?.metadata?.patternType).toBe('problem_solving');
			expect(reasoningResult?.metadata?.qualityScore).toBe(0.9);
			expect(reasoningResult?.metadata?.stepCount).toBe(5);
		});
	});

	describe('Caching', () => {
		it('should cache search results', async () => {
			const searchResults = {
				memory: [{ content: 'Cached result', relevance: 0.8 }],
			};

			await manager.processSearchResults(searchResults, 'test query');

			const cached = manager.getCachedResults('test query');
			expect(cached).toBeDefined();
			expect(cached).toHaveLength(1);
			expect(cached?.[0]?.content).toBe('Cached result');
		});

		it('should return null for non-existent cached results', () => {
			const cached = manager.getCachedResults('nonexistent query');
			expect(cached).toBeNull();
		});

		it('should clear cache', async () => {
			const searchResults = {
				memory: [{ content: 'Cached result', relevance: 0.8 }],
			};

			await manager.processSearchResults(searchResults, 'test query');
			manager.clearCache();

			const cached = manager.getCachedResults('test query');
			expect(cached).toBeNull();
		});
	});

	describe('Options management', () => {
		it('should use default options', () => {
			const options = manager.getOptions();

			expect(options.maxPrimaryResults).toBe(5);
			expect(options.maxSecondaryResults).toBe(10);
			expect(options.relevanceThreshold).toBe(0.6);
			expect(options.enableDeduplication).toBe(true);
			expect(options.enableSummarization).toBe(true);
			expect(options.sortByRelevance).toBe(true);
		});

		it('should allow updating options', () => {
			const newOptions = {
				maxPrimaryResults: 10,
				relevanceThreshold: 0.8,
			};

			manager.updateOptions(newOptions);
			const options = manager.getOptions();

			expect(options.maxPrimaryResults).toBe(10);
			expect(options.relevanceThreshold).toBe(0.8);
			expect(options.maxSecondaryResults).toBe(10); // Unchanged
		});
	});

	describe('Error handling', () => {
		it('should handle malformed search results gracefully', async () => {
			const searchResults = {
				memory: [
					{ relevance: 0.8 }, // Missing content
					null, // Null result
					{ content: 'Valid result', relevance: 0.9 },
				],
			};

			const result = await manager.processSearchResults(searchResults);

			expect(result.totalResults).toBeGreaterThan(0);
			expect(result.primaryResults.some(r => r.content === 'Valid result')).toBe(true);
		});
	});
});

/**
 * Content-Based Reasoning Detection Service
 *
 * Analyzes user input to determine if it contains reasoning content that should
 * trigger reflection memory tools. This replaces the model-based activation mechanism.
 */

import { logger } from '../../logger/index.js';
import { ILLMService, LLMConfig } from '../llm/index.js';
import { createContextManager } from '../llm/messages/factory.js';
import { createLLMService } from '../llm/services/factory.js';
import { EnhancedPromptManager } from '../systemPrompt/enhanced-manager.js';
import { MCPManager } from '../../mcp/manager.js';
import { UnifiedToolManager } from '../tools/unified-tool-manager.js';

export interface ReasoningDetectionResult {
	containsReasoning: boolean;
	confidence: number;
	detectedPatterns: string[];
	explanation?: string;
}

export interface ReasoningDetectionOptions {
	confidenceThreshold?: number;
	maxPatterns?: number;
	enableDetailedAnalysis?: boolean;
}

/**
 * Default reasoning detection options
 */
const DEFAULT_OPTIONS: Required<ReasoningDetectionOptions> = {
	confidenceThreshold: 0.7,
	maxPatterns: 10,
	enableDetailedAnalysis: false,
};

// Keyword analysis removed - only LLM analysis is used

/**
 * Reasoning content detector that analyzes user input to determine
 * if it contains reasoning patterns that should trigger reflection tools.
 */
export class ReasoningContentDetector {
	private llmService?: ILLMService;
	private promptManager: EnhancedPromptManager;
	private mcpManager: MCPManager;
	private unifiedToolManager: UnifiedToolManager;
	private options: Required<ReasoningDetectionOptions>;
	private evalLlmConfig: LLMConfig;

	constructor(
		promptManager: EnhancedPromptManager,
		mcpManager: MCPManager,
		unifiedToolManager: UnifiedToolManager,
		evalLlmConfig: LLMConfig,
		options?: ReasoningDetectionOptions
	) {
		this.promptManager = promptManager;
		this.mcpManager = mcpManager;
		this.unifiedToolManager = unifiedToolManager;
		this.options = { ...DEFAULT_OPTIONS, ...options };
		this.evalLlmConfig = evalLlmConfig;
	}

	/**
	 * Initialize the LLM service for reasoning analysis
	 */
	private async initializeLLMService(): Promise<void> {
		if (this.llmService) return;

		try {
			// Use the provided evaluation LLM configuration
			const evalConfig = {
				...this.evalLlmConfig,
				maxIterations: this.evalLlmConfig.maxIterations ?? 3, // Default for eval tasks
			};

			const contextManager = createContextManager(
				evalConfig,
				this.promptManager,
				undefined,
				undefined
			);
			this.llmService = createLLMService(
				evalConfig,
				this.mcpManager,
				contextManager,
				this.unifiedToolManager
			);

			logger.debug('ReasoningContentDetector: LLM service initialized for analysis', {
				provider: evalConfig.provider,
				model: evalConfig.model,
			});
		} catch (error) {
			logger.warn('ReasoningContentDetector: Failed to initialize LLM service for analysis', {
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}

	/**
	 * Detect if user input contains reasoning content
	 */
	async detectReasoningContent(
		userInput: string,
		context?: {
			sessionId?: string;
			recentMessages?: string[];
			taskType?: string;
		}
	): Promise<ReasoningDetectionResult> {
		try {
			logger.debug('ReasoningContentDetector: Analyzing user input for reasoning content', {
				inputLength: userInput.length,
			});

			// Handle empty or very short input
			if (!userInput || userInput.trim().length < 3) {
				return {
					containsReasoning: false,
					confidence: 0,
					detectedPatterns: [],
					explanation: 'Input too short for reasoning analysis',
				};
			}

			// LLM-based analysis
			await this.initializeLLMService();
			if (this.llmService) {
				const result = await this.detectReasoningByLLM(userInput, context);

				logger.debug('ReasoningContentDetector: Detection completed', {
					containsReasoning: result.containsReasoning,
					confidence: result.confidence,
					patternCount: result.detectedPatterns.length,
				});

				return result;
			} else {
				// Fallback when LLM service is not available
				logger.warn(
					'ReasoningContentDetector: LLM service not available, cannot detect reasoning content'
				);
				return {
					containsReasoning: false,
					confidence: 0,
					detectedPatterns: [],
					explanation: 'LLM service not available for reasoning analysis',
				};
			}
		} catch (error) {
			logger.error('ReasoningContentDetector: Error during reasoning detection', {
				error: error instanceof Error ? error.message : String(error),
			});

			return {
				containsReasoning: false,
				confidence: 0,
				detectedPatterns: [],
				explanation: 'Error during reasoning detection',
			};
		}
	}

	// Keyword analysis removed - only LLM analysis is used

	/**
	 * Detect reasoning content using LLM analysis
	 */
	private async detectReasoningByLLM(
		userInput: string,
		context?: {
			sessionId?: string;
			recentMessages?: string[];
			taskType?: string;
		}
	): Promise<ReasoningDetectionResult> {
		if (!this.llmService) {
			throw new Error('LLM service not available for reasoning analysis');
		}

		try {
			const analysisPrompt = `Analyze the following user input to determine if it contains reasoning content that would benefit from reflection memory tools.

User Input: "${userInput}"

Context: ${context?.taskType ? `Task type: ${context.taskType}` : 'General conversation'}

Please analyze this input and respond with a JSON object containing:
- "containsReasoning": boolean (true if the input contains reasoning patterns, thought processes, problem-solving steps, or analytical content)
- "confidence": number (0.0 to 1.0, how confident you are in this assessment)
- "detectedPatterns": array of strings (specific reasoning patterns you identified)
- "explanation": string (brief explanation of your reasoning)

Consider these factors:
1. Explicit reasoning markers (because, therefore, let me think, etc.)
2. Problem-solving language (debug, analyze, figure out, etc.)
3. Decision-making patterns (consider, evaluate, compare, etc.)
4. Technical reasoning (optimize, design, architecture, etc.)
5. Learning and reflection content (learn, understand, reflect, etc.)

Respond only with the JSON object, no additional text.`;

			const response = await this.llmService.directGenerate(analysisPrompt);

			try {
				// Clean the response to handle common LLM formatting issues
				let cleanedResponse = response.trim();

				logger.debug('ReasoningContentDetector: Raw LLM response', {
					rawResponse: response.substring(0, 300),
					responseLength: response.length,
				});

				// Remove markdown code block formatting if present
				if (cleanedResponse.startsWith('```json')) {
					cleanedResponse = cleanedResponse.replace(/^```json\s*/, '');
				}
				if (cleanedResponse.startsWith('```')) {
					cleanedResponse = cleanedResponse.replace(/^```\s*/, '');
				}
				if (cleanedResponse.endsWith('```')) {
					cleanedResponse = cleanedResponse.replace(/\s*```$/, '');
				}

				// Extract JSON if there's additional text around it
				const jsonMatch = cleanedResponse.match(/\{[\s\S]*\}/);
				if (jsonMatch) {
					cleanedResponse = jsonMatch[0];
				}

				logger.debug('ReasoningContentDetector: Cleaned response for JSON parsing', {
					cleanedResponse: cleanedResponse.substring(0, 300),
					cleanedLength: cleanedResponse.length,
				});

				const result = JSON.parse(cleanedResponse);
				return {
					containsReasoning: result.containsReasoning || false,
					confidence: Math.max(0, Math.min(1, result.confidence || 0)),
					detectedPatterns: Array.isArray(result.detectedPatterns)
						? result.detectedPatterns.slice(0, this.options.maxPatterns)
						: [],
					explanation: result.explanation || 'LLM analysis',
				};
			} catch (parseError) {
				logger.warn('ReasoningContentDetector: Failed to parse LLM response', {
					response: response.substring(0, 200),
					error: parseError instanceof Error ? parseError.message : String(parseError),
				});
				return {
					containsReasoning: false,
					confidence: 0,
					detectedPatterns: [],
					explanation: 'Failed to parse LLM response for reasoning detection',
				};
			}
		} catch (error) {
			logger.warn('ReasoningContentDetector: LLM analysis failed', {
				error: error instanceof Error ? error.message : String(error),
			});
			return {
				containsReasoning: false,
				confidence: 0,
				detectedPatterns: [],
				explanation: 'LLM analysis failed for reasoning detection',
			};
		}
	}

	// Combined analysis removed - only LLM analysis is used

	/**
	 * Update detection options
	 */
	updateOptions(newOptions: Partial<ReasoningDetectionOptions>): void {
		this.options = { ...this.options, ...newOptions };
		logger.debug('ReasoningContentDetector: Updated options', { newOptions });
	}

	/**
	 * Get current detection options
	 */
	getOptions(): Required<ReasoningDetectionOptions> {
		return { ...this.options };
	}
}

/**
 * Reasoning Services
 *
 * Content-based reasoning detection and search context management
 * for reflection memory tools activation.
 */

export {
	ReasoningContentDetector,
	ReasoningDetectionResult,
	ReasoningDetectionOptions,
} from './content-detector.js';
export {
	SearchContextManager,
	SearchResult,
	SortedContext,
	SearchContextOptions,
} from './search-context-manager.js';

/**
 * Search Context Manager
 *
 * Handles multiple search tool calls and provides well-sorted context
 * to feed into the agent. This ensures efficient use of search results
 * from cipher_search_graph, cipher_memory_search, and cipher_search_reasoning_patterns.
 */

import { logger } from '../../logger/index.js';

export interface SearchResult {
	source: 'graph' | 'memory' | 'reasoning_patterns';
	content: string;
	relevance: number;
	metadata?: Record<string, any>;
	timestamp?: string;
}

export interface SortedContext {
	primaryResults: SearchResult[];
	secondaryResults: SearchResult[];
	summary: string;
	totalResults: number;
	sourcesUsed: string[];
}

export interface SearchContextOptions {
	maxPrimaryResults?: number;
	maxSecondaryResults?: number;
	relevanceThreshold?: number;
	enableDeduplication?: boolean;
	enableSummarization?: boolean;
	sortByRelevance?: boolean;
}

/**
 * Default search context options
 */
const DEFAULT_OPTIONS: Required<SearchContextOptions> = {
	maxPrimaryResults: 5,
	maxSecondaryResults: 10,
	relevanceThreshold: 0.6,
	enableDeduplication: true,
	enableSummarization: true,
	sortByRelevance: true,
};

/**
 * Manages multiple search tool results and provides well-sorted context
 */
export class SearchContextManager {
	private options: Required<SearchContextOptions>;
	private recentSearches: Map<string, { timestamp: number; results: SearchResult[] }> = new Map();

	constructor(options?: SearchContextOptions) {
		this.options = { ...DEFAULT_OPTIONS, ...options };
	}

	/**
	 * Process multiple search tool results and return well-sorted context
	 */
	async processSearchResults(
		searchResults: {
			graph?: any[];
			memory?: any[];
			reasoning_patterns?: any[];
		},
		query?: string
	): Promise<SortedContext> {
		try {
			logger.debug('SearchContextManager: Processing search results', {
				graphResults: searchResults.graph?.length || 0,
				memoryResults: searchResults.memory?.length || 0,
				reasoningResults: searchResults.reasoning_patterns?.length || 0,
			});

			// Step 1: Normalize and validate search results
			const normalizedResults = this.normalizeSearchResults(searchResults);

			// Step 2: Deduplicate results if enabled
			const deduplicatedResults = this.options.enableDeduplication
				? this.deduplicateResults(normalizedResults)
				: normalizedResults;

			// Step 3: Sort results by relevance
			const sortedResults = this.options.sortByRelevance
				? this.sortByRelevance(deduplicatedResults)
				: deduplicatedResults;

			// Step 4: Filter by relevance threshold
			const filteredResults = this.filterByRelevance(sortedResults);

			// Step 5: Split into primary and secondary results
			const { primaryResults, secondaryResults } = this.splitResults(filteredResults);

			// Step 6: Generate summary
			const summary = this.options.enableSummarization
				? await this.generateSummary(primaryResults, query)
				: this.generateBasicSummary(primaryResults);

			// Step 7: Cache results for future reference
			if (query) {
				this.cacheSearchResults(query, [...primaryResults, ...secondaryResults]);
			}

			const context: SortedContext = {
				primaryResults,
				secondaryResults,
				summary,
				totalResults: primaryResults.length + secondaryResults.length,
				sourcesUsed: this.getSourcesUsed([...primaryResults, ...secondaryResults]),
			};

			logger.debug('SearchContextManager: Context processing completed', {
				primaryCount: primaryResults.length,
				secondaryCount: secondaryResults.length,
				totalResults: context.totalResults,
				sourcesUsed: context.sourcesUsed,
			});

			return context;
		} catch (error) {
			logger.error('SearchContextManager: Error processing search results', {
				error: error instanceof Error ? error.message : String(error),
			});

			// Return empty context on error
			return {
				primaryResults: [],
				secondaryResults: [],
				summary: 'Error processing search results',
				totalResults: 0,
				sourcesUsed: [],
			};
		}
	}

	/**
	 * Normalize search results from different sources
	 */
	private normalizeSearchResults(searchResults: {
		graph?: any[];
		memory?: any[];
		reasoning_patterns?: any[];
	}): SearchResult[] {
		const normalized: SearchResult[] = [];

		// Normalize graph search results
		if (searchResults.graph && Array.isArray(searchResults.graph)) {
			for (const result of searchResults.graph) {
				if (result && typeof result === 'object') {
					const content = this.extractContent(result, 'graph');
					if (
						content &&
						content !== 'Invalid result object' &&
						content !== 'No content available'
					) {
						const metadata = this.extractMetadata(result, 'graph');
						const timestamp = this.extractTimestamp(result, 'graph');
						normalized.push({
							source: 'graph',
							content,
							relevance: this.extractRelevance(result, 'graph'),
							...(metadata && { metadata }),
							...(timestamp && { timestamp }),
						});
					}
				}
			}
		}

		// Normalize memory search results
		if (searchResults.memory && Array.isArray(searchResults.memory)) {
			for (const result of searchResults.memory) {
				if (result && typeof result === 'object') {
					const content = this.extractContent(result, 'memory');
					if (
						content &&
						content !== 'Invalid result object' &&
						content !== 'No content available'
					) {
						const metadata = this.extractMetadata(result, 'memory');
						const timestamp = this.extractTimestamp(result, 'memory');
						normalized.push({
							source: 'memory',
							content,
							relevance: this.extractRelevance(result, 'memory'),
							...(metadata && { metadata }),
							...(timestamp && { timestamp }),
						});
					}
				}
			}
		}

		// Normalize reasoning patterns search results
		if (searchResults.reasoning_patterns && Array.isArray(searchResults.reasoning_patterns)) {
			for (const result of searchResults.reasoning_patterns) {
				if (result && typeof result === 'object') {
					const content = this.extractContent(result, 'reasoning_patterns');
					if (
						content &&
						content !== 'Invalid result object' &&
						content !== 'No content available'
					) {
						const metadata = this.extractMetadata(result, 'reasoning_patterns');
						const timestamp = this.extractTimestamp(result, 'reasoning_patterns');
						normalized.push({
							source: 'reasoning_patterns',
							content,
							relevance: this.extractRelevance(result, 'reasoning_patterns'),
							...(metadata && { metadata }),
							...(timestamp && { timestamp }),
						});
					}
				}
			}
		}

		return normalized;
	}

	/**
	 * Extract content from search result based on source
	 */
	private extractContent(result: any, source: string): string {
		if (!result || typeof result !== 'object') {
			return 'Invalid result object';
		}

		let content: string | undefined;
		switch (source) {
			case 'graph':
				content = result.content || result.text || result.description || result.name;
				break;
			case 'memory':
				content = result.content || result.text || result.fact || result.memory;
				break;
			case 'reasoning_patterns':
				content = result.content || result.text || result.pattern || result.reasoning;
				break;
			default:
				content = result.content || result.text;
				break;
		}

		// If no content found, try to stringify the result
		if (!content) {
			try {
				content = JSON.stringify(result);
			} catch {
				content = String(result);
			}
		}

		return content || 'No content available';
	}

	/**
	 * Extract relevance score from search result
	 */
	private extractRelevance(result: any, _source: string): number {
		// Try to extract relevance from various possible fields
		const relevance =
			result.relevance || result.score || result.similarity || result.confidence || 0.5;
		return Math.max(0, Math.min(1, relevance));
	}

	/**
	 * Extract metadata from search result
	 */
	private extractMetadata(result: any, source: string): Record<string, any> | undefined {
		const metadata = result.metadata || result.meta || {};

		// Add source-specific metadata
		switch (source) {
			case 'graph':
				return {
					...metadata,
					nodeType: result.type || result.nodeType,
					relationships: result.relationships || result.connections,
				};
			case 'memory':
				return {
					...metadata,
					memoryType: result.memoryType || result.type,
					sessionId: result.sessionId,
					extractedAt: result.extractedAt,
				};
			case 'reasoning_patterns':
				return {
					...metadata,
					patternType: result.patternType || result.type,
					qualityScore: result.qualityScore,
					stepCount: result.stepCount,
				};
			default:
				return metadata;
		}
	}

	/**
	 * Extract timestamp from search result
	 */
	private extractTimestamp(result: any, _source: string): string | undefined {
		return result.timestamp || result.createdAt || result.updatedAt || result.date;
	}

	/**
	 * Deduplicate search results based on content similarity
	 */
	private deduplicateResults(results: SearchResult[]): SearchResult[] {
		const unique: SearchResult[] = [];
		const seen: Set<string> = new Set();

		for (const result of results) {
			// Create a normalized content hash for deduplication
			const normalizedContent = result.content.toLowerCase().trim().replace(/\s+/g, ' ');
			const contentHash = `${result.source}:${normalizedContent.substring(0, 100)}`;

			if (!seen.has(contentHash)) {
				seen.add(contentHash);
				unique.push(result);
			} else {
				// If duplicate found, keep the one with higher relevance
				const existingIndex = unique.findIndex(r => {
					const existingNormalized = r.content.toLowerCase().trim().replace(/\s+/g, ' ');
					const existingHash = `${r.source}:${existingNormalized.substring(0, 100)}`;
					return existingHash === contentHash;
				});

				if (
					existingIndex >= 0 &&
					unique[existingIndex] &&
					result.relevance > unique[existingIndex].relevance
				) {
					unique[existingIndex] = result;
				}
			}
		}

		return unique;
	}

	/**
	 * Sort results by relevance score
	 */
	private sortByRelevance(results: SearchResult[]): SearchResult[] {
		return [...results].sort((a, b) => b.relevance - a.relevance);
	}

	/**
	 * Filter results by relevance threshold
	 */
	private filterByRelevance(results: SearchResult[]): SearchResult[] {
		return results.filter(result => result.relevance >= this.options.relevanceThreshold);
	}

	/**
	 * Split results into primary and secondary based on relevance and limits
	 */
	private splitResults(results: SearchResult[]): {
		primaryResults: SearchResult[];
		secondaryResults: SearchResult[];
	} {
		const primaryResults = results.slice(0, this.options.maxPrimaryResults);
		const secondaryResults = results.slice(
			this.options.maxPrimaryResults,
			this.options.maxPrimaryResults + this.options.maxSecondaryResults
		);

		return { primaryResults, secondaryResults };
	}

	/**
	 * Generate a summary of the primary search results
	 */
	private async generateSummary(primaryResults: SearchResult[], _query?: string): Promise<string> {
		if (primaryResults.length === 0) {
			return 'No relevant search results found.';
		}

		const resultCounts = this.countResultsBySource(primaryResults);
		const topResults = primaryResults.slice(0, 3);

		let summary = `Found ${primaryResults.length} relevant results`;
		if ((resultCounts.graph || 0) > 0)
			summary += ` (${resultCounts.graph || 0} from knowledge graph`;
		if ((resultCounts.memory || 0) > 0)
			summary += `${(resultCounts.graph || 0) > 0 ? ', ' : ' ('}${resultCounts.memory || 0} from memory`;
		if ((resultCounts.reasoning_patterns || 0) > 0)
			summary += `${(resultCounts.graph || 0) > 0 || (resultCounts.memory || 0) > 0 ? ', ' : ' ('}${resultCounts.reasoning_patterns || 0} reasoning patterns`;
		summary += ')';

		if (topResults.length > 0) {
			summary += '. Top results include: ';
			summary += topResults
				.map(
					(result, index) =>
						`${index + 1}) ${result.content.substring(0, 100)}${result.content.length > 100 ? '...' : ''}`
				)
				.join('; ');
		}

		return summary;
	}

	/**
	 * Generate a basic summary without LLM processing
	 */
	private generateBasicSummary(primaryResults: SearchResult[]): string {
		if (primaryResults.length === 0) {
			return 'No relevant search results found.';
		}

		const resultCounts = this.countResultsBySource(primaryResults);
		let summary = `Found ${primaryResults.length} relevant results`;

		const sources = [];
		if ((resultCounts.graph || 0) > 0)
			sources.push(`${resultCounts.graph || 0} from knowledge graph`);
		if ((resultCounts.memory || 0) > 0) sources.push(`${resultCounts.memory || 0} from memory`);
		if ((resultCounts.reasoning_patterns || 0) > 0)
			sources.push(`${resultCounts.reasoning_patterns || 0} reasoning patterns`);

		if (sources.length > 0) {
			summary += ` (${sources.join(', ')})`;
		}

		return summary;
	}

	/**
	 * Count results by source
	 */
	private countResultsBySource(results: SearchResult[]): Record<string, number> {
		return results.reduce(
			(counts, result) => {
				counts[result.source] = (counts[result.source] || 0) + 1;
				return counts;
			},
			{} as Record<string, number>
		);
	}

	/**
	 * Get list of sources used in results
	 */
	private getSourcesUsed(results: SearchResult[]): string[] {
		const sources = new Set<string>();
		for (const result of results) {
			sources.add(result.source);
		}
		return Array.from(sources);
	}

	/**
	 * Cache search results for future reference
	 */
	private cacheSearchResults(_query: string, results: SearchResult[]): void {
		const now = Date.now();
		this.recentSearches.set(_query, { timestamp: now, results });

		// Clean up old cache entries (older than 1 hour)
		const oneHourAgo = now - 3600000;
		for (const [key, value] of this.recentSearches.entries()) {
			if (value.timestamp < oneHourAgo) {
				this.recentSearches.delete(key);
			}
		}
	}

	/**
	 * Get cached search results for a query
	 */
	getCachedResults(query: string): SearchResult[] | null {
		const cached = this.recentSearches.get(query);
		if (cached && Date.now() - cached.timestamp < 300000) {
			// 5 minutes
			return cached.results;
		}
		return null;
	}

	/**
	 * Update search context options
	 */
	updateOptions(newOptions: Partial<SearchContextOptions>): void {
		this.options = { ...this.options, ...newOptions };
		logger.debug('SearchContextManager: Updated options', { newOptions });
	}

	/**
	 * Get current search context options
	 */
	getOptions(): Required<SearchContextOptions> {
		return { ...this.options };
	}

	/**
	 * Clear search cache
	 */
	clearCache(): void {
		this.recentSearches.clear();
		logger.debug('SearchContextManager: Cache cleared');
	}
}

/**
 * Tests for Built-in Dynamic Content Generators
 */

import { describe, it, expect, beforeEach } from 'vitest';
import {
	timestampGenerator,
	sessionContextGenerator,
	memoryContextGenerator,
	environmentGenerator,
	conditionalGenerator,
	registerBuiltInGenerators,
	getBuiltInGeneratorNames,
} from '../built-in-generators.js';
import { ProviderContext } from '../interfaces.js';

describe('Built-in Dynamic Content Generators', () => {
	let mockContext: ProviderContext;

	beforeEach(() => {
		mockContext = {
			timestamp: new Date('2023-06-15T10:30:00Z'),
			sessionId: 'session-123',
			userId: 'user-456',
			memoryContext: {
				previousTopics: ['JavaScript', 'TypeScript'],
				userPreferences: { theme: 'dark', language: 'en' },
			},
			metadata: {
				clientVersion: '1.0.0',
			},
		};
	});

	describe('timestampGenerator', () => {
		it('should generate ISO timestamp by default', async () => {
			const result = await timestampGenerator(mockContext, {});
			expect(result).toBe('2023-06-15T10:30:00.000Z');
		});

		it('should generate locale formatted timestamp', async () => {
			const config = { format: 'locale' };
			const result = await timestampGenerator(mockContext, config);
			expect(result).toMatch(/June 15, 2023/);
		});

		it('should generate date-only format', async () => {
			const config = { format: 'date-only' };
			const result = await timestampGenerator(mockContext, config);
			expect(result).toBe('2023-06-15');
		});

		it('should generate time-only format', async () => {
			const config = { format: 'time-only' };
			const result = await timestampGenerator(mockContext, config);
			expect(result).toBe('10:30:00');
		});

		it('should include timezone when requested', async () => {
			const config = { format: 'locale', includeTimezone: true };
			const result = await timestampGenerator(mockContext, config);
			expect(result.includes('GMT') || result.includes('UTC')).toBe(true);
		});
	});

	describe('sessionContextGenerator', () => {
		it('should generate context info in list format by default', async () => {
			const result = await sessionContextGenerator(mockContext, {});

			expect(result).toContain('Session ID: session-123');
			expect(result).toContain('User ID: user-456');
			expect(result).toContain('\n');
		});

		it('should generate inline format', async () => {
			const config = { format: 'inline' };
			const result = await sessionContextGenerator(mockContext, config);

			expect(result).toContain('Session ID: session-123');
			expect(result).toContain('User ID: user-456');
			expect(result).toContain(', ');
		});

		it('should generate JSON format', async () => {
			const config = { format: 'json' };
			const result = await sessionContextGenerator(mockContext, config);

			const parsed = JSON.parse(result);
			expect(parsed.sessionId).toBe('session-123');
			expect(parsed.userId).toBe('user-456');
		});

		it('should include only specified fields', async () => {
			const config = { includeFields: ['sessionId'] };
			const result = await sessionContextGenerator(mockContext, config);

			expect(result).toContain('Session ID: session-123');
			expect(result).not.toContain('User ID');
		});

		it('should include timestamp when requested', async () => {
			const config = { includeFields: ['sessionId', 'timestamp'] };
			const result = await sessionContextGenerator(mockContext, config);

			expect(result).toContain('Session ID: session-123');
			expect(result).toContain('Timestamp: 2023-06-15T10:30:00.000Z');
		});

		it('should return empty string when no fields match', async () => {
			const contextWithoutIds: ProviderContext = {
				timestamp: new Date(),
				metadata: {},
			};

			const result = await sessionContextGenerator(contextWithoutIds, {});
			expect(result).toBe('');
		});
	});

	describe('memoryContextGenerator', () => {
		it('should generate summary format by default', async () => {
			const result = await memoryContextGenerator(mockContext, {});
			expect(result).toBe('Memory context contains 2 items');
		});

		it('should generate list format', async () => {
			const config = { format: 'list' };
			const result = await memoryContextGenerator(mockContext, config);

			expect(result).toContain('previousTopics:');
			expect(result).toContain('userPreferences:');
		});

		it('should generate JSON format', async () => {
			const config = { format: 'json' };
			const result = await memoryContextGenerator(mockContext, config);

			const parsed = JSON.parse(result);
			expect(parsed.previousTopics).toEqual(['JavaScript', 'TypeScript']);
			expect(parsed.userPreferences.theme).toBe('dark');
		});

		it('should limit items in list format', async () => {
			const config = { format: 'list', maxItems: 1 };
			const result = await memoryContextGenerator(mockContext, config);

			const lines = result.split('\n');
			expect(lines).toHaveLength(1);
		});

		it('should handle empty memory context', async () => {
			const contextWithoutMemory: ProviderContext = {
				timestamp: new Date(),
				sessionId: 'test',
			};

			const result = await memoryContextGenerator(contextWithoutMemory, {});
			expect(result).toBe('No memory context available');
		});

		it('should use custom empty message', async () => {
			const contextWithoutMemory: ProviderContext = {
				timestamp: new Date(),
				sessionId: 'test',
			};

			const config = { emptyMessage: 'Custom empty message' };
			const result = await memoryContextGenerator(contextWithoutMemory, config);
			expect(result).toBe('Custom empty message');
		});
	});

	describe('environmentGenerator', () => {
		it('should use production environment by default', async () => {
			const result = await environmentGenerator(mockContext, {});
			expect(result).toBe('Production environment: Exercise caution with all operations.');
		});

		it('should use specified environment', async () => {
			const config = { environment: 'development' };
			const result = await environmentGenerator(mockContext, config);
			expect(result).toBe(
				'Development mode: Enhanced logging and debugging features are available.'
			);
		});

		it('should use custom messages', async () => {
			const config = {
				environment: 'custom',
				messages: {
					custom: 'Custom environment message',
				},
			};
			const result = await environmentGenerator(mockContext, config);
			expect(result).toBe('Custom environment message');
		});

		it('should fallback to default format for unknown environment', async () => {
			const config = { environment: 'unknown' };
			const result = await environmentGenerator(mockContext, config);
			expect(result).toBe('Environment: unknown');
		});
	});

	describe('conditionalGenerator', () => {
		it('should evaluate string conditions', async () => {
			const config = {
				conditions: [
					{
						if: 'userId',
						then: 'User is logged in',
					},
				],
				else: 'Anonymous user',
			};

			const result = await conditionalGenerator(mockContext, config);
			expect(result).toBe('User is logged in');
		});

		it('should evaluate object conditions', async () => {
			const config = {
				conditions: [
					{
						if: { field: 'sessionId', operator: 'exists' },
						then: 'Session is active',
					},
				],
				else: 'No active session',
			};

			const result = await conditionalGenerator(mockContext, config);
			expect(result).toBe('Session is active');
		});

		it('should evaluate equals operator', async () => {
			const config = {
				conditions: [
					{
						if: { field: 'userId', operator: 'equals', value: 'user-456' },
						then: 'Correct user',
					},
				],
				else: 'Wrong user',
			};

			const result = await conditionalGenerator(mockContext, config);
			expect(result).toBe('Correct user');
		});

		it('should return else clause when no conditions match', async () => {
			const contextWithoutIds: ProviderContext = {
				timestamp: new Date(),
				metadata: {},
			};

			const config = {
				conditions: [
					{
						if: 'userId',
						then: 'User found',
					},
				],
				else: 'No user',
			};

			const result = await conditionalGenerator(contextWithoutIds, config);
			expect(result).toBe('No user');
		});

		it('should return empty string when no else clause and no matches', async () => {
			const contextWithoutIds: ProviderContext = {
				timestamp: new Date(),
				metadata: {},
			};

			const config = {
				conditions: [
					{
						if: 'userId',
						then: 'User found',
					},
				],
			};

			const result = await conditionalGenerator(contextWithoutIds, config);
			expect(result).toBe('');
		});

		it('should evaluate multiple conditions in order', async () => {
			const config = {
				conditions: [
					{
						if: 'nonExistentField',
						then: 'Should not match',
					},
					{
						if: 'sessionId',
						then: 'Session found',
					},
					{
						if: 'userId',
						then: 'User found',
					},
				],
			};

			const result = await conditionalGenerator(mockContext, config);
			expect(result).toBe('Session found');
		});
	});

	describe('utility functions', () => {
		it('should return all built-in generator names', () => {
			const names = getBuiltInGeneratorNames();

			expect(names).toContain('timestamp');
			expect(names).toContain('session-context');
			expect(names).toContain('memory-context');
			expect(names).toContain('environment');
			expect(names).toContain('conditional');
			expect(names).toHaveLength(5);
		});

		it('should register built-in generators', async () => {
			// This test mainly ensures the function exists and can be called
			await expect(registerBuiltInGenerators()).resolves.toBeUndefined();
		});
	});
});

/**
 * Tests for System Prompt Configuration Manager
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { promises as fs } from 'fs';
import path from 'path';
import { SystemPromptConfigManager } from '../config-manager.js';
import { SystemPromptConfig, ProviderType } from '../interfaces.js';

describe('SystemPromptConfigManager', () => {
	let configManager: SystemPromptConfigManager;
	let tempDir: string;

	beforeEach(async () => {
		configManager = new SystemPromptConfigManager();

		// Create temporary directory for test config files
		tempDir = path.join(process.cwd(), 'temp-test-configs');
		try {
			await fs.mkdir(tempDir, { recursive: true });
		} catch (error) {
			// If directory already exists, that's fine
			if ((error as any).code !== 'EEXIST') {
				throw error;
			}
		}
	});

	afterEach(async () => {
		// Clean up temporary files
		try {
			await fs.rm(tempDir, { recursive: true, force: true });
		} catch {
			// Ignore cleanup errors
		}
	});

	describe('loadFromObject', () => {
		it('should load valid configuration', () => {
			const config: SystemPromptConfig = {
				providers: [
					{
						name: 'test-provider',
						type: ProviderType.STATIC,
						priority: 100,
						enabled: true,
						config: { content: 'test' },
					},
				],
				settings: {
					maxGenerationTime: 5000,
					failOnProviderError: false,
					contentSeparator: '\n\n',
				},
			};

			expect(() => configManager.loadFromObject(config)).not.toThrow();
			expect(configManager.isLoaded()).toBe(true);
		});

		it('should validate configuration by default', () => {
			const invalidConfig = {
				providers: 'not an array',
			} as any;

			expect(() => configManager.loadFromObject(invalidConfig)).toThrow('providers');
		});

		it('should skip validation when requested', () => {
			const invalidConfig = {
				providers: 'not an array',
			} as any;

			expect(() => configManager.loadFromObject(invalidConfig, { validate: false })).not.toThrow();
		});

		it('should process environment variables', () => {
			const config: SystemPromptConfig = {
				providers: [
					{
						name: 'env-provider',
						type: ProviderType.STATIC,
						priority: 100,
						enabled: true,
						config: {
							content: 'Environment: ${ENV_NAME}',
							variables: { version: '${APP_VERSION}' },
						},
					},
				],
				settings: {
					maxGenerationTime: 5000,
					failOnProviderError: false,
					contentSeparator: '\n\n',
				},
			};

			const envVars = { ENV_NAME: 'test', APP_VERSION: '1.0.0' };
			configManager.loadFromObject(config, { envVariables: envVars });

			const loadedConfig = configManager.getConfig();
			expect(loadedConfig.providers[0]!.config!.content).toBe('Environment: test');
			expect(loadedConfig.providers[0]!.config!.variables.version).toBe('1.0.0');
		});
	});

	describe('loadFromFile', () => {
		it('should load configuration from JSON file', async () => {
			const config: SystemPromptConfig = {
				providers: [
					{
						name: 'file-provider',
						type: ProviderType.STATIC,
						priority: 100,
						enabled: true,
						config: { content: 'from file' },
					},
				],
				settings: {
					maxGenerationTime: 5000,
					failOnProviderError: false,
					contentSeparator: '\n\n',
				},
			};

			const configFile = path.join(tempDir, 'test-config.json');
			await fs.writeFile(configFile, JSON.stringify(config, null, 2));

			await configManager.loadFromFile(configFile);

			expect(configManager.isLoaded()).toBe(true);
			const loadedConfig = configManager.getConfig();
			expect(loadedConfig.providers[0]!.name).toBe('file-provider');
		});

		it('should handle relative file paths', async () => {
			const config: SystemPromptConfig = {
				providers: [
					{
						name: 'test',
						type: ProviderType.FILE_BASED,
						priority: 100,
						enabled: true,
						config: { filePath: 'relative/path.txt' },
					},
				],
				settings: {
					maxGenerationTime: 5000,
					failOnProviderError: false,
					contentSeparator: '\n\n',
				},
			};

			const configFile = path.join(tempDir, 'config.json');
			await fs.writeFile(configFile, JSON.stringify(config));

			await configManager.loadFromFile(configFile);

			const loadedConfig = configManager.getConfig();
			const filePath = loadedConfig.providers[0]!.config!.filePath;
			expect(path.isAbsolute(filePath)).toBe(true);
			expect(filePath).toContain('relative/path.txt');
		});

		it('should throw error for non-existent file', async () => {
			const nonExistentFile = path.join(tempDir, 'non-existent.json');

			await expect(configManager.loadFromFile(nonExistentFile)).rejects.toThrow(
				'Failed to load configuration'
			);
		});

		it('should throw error for invalid JSON', async () => {
			const invalidJsonFile = path.join(tempDir, 'invalid.json');
			await fs.writeFile(invalidJsonFile, 'invalid json content');

			await expect(configManager.loadFromFile(invalidJsonFile)).rejects.toThrow(
				'Failed to load configuration'
			);
		});
	});

	describe('getters', () => {
		beforeEach(() => {
			const config: SystemPromptConfig = {
				providers: [
					{
						name: 'high-priority',
						type: ProviderType.STATIC,
						priority: 100,
						enabled: true,
						config: { content: 'high' },
					},
					{
						name: 'low-priority',
						type: ProviderType.STATIC,
						priority: 50,
						enabled: true,
						config: { content: 'low' },
					},
					{
						name: 'disabled',
						type: ProviderType.STATIC,
						priority: 75,
						enabled: false,
						config: { content: 'disabled' },
					},
				],
				settings: {
					maxGenerationTime: 8000,
					failOnProviderError: true,
					contentSeparator: '\n---\n',
				},
			};

			configManager.loadFromObject(config);
		});

		it('should throw error when configuration not loaded', () => {
			const emptyManager = new SystemPromptConfigManager();
			expect(() => emptyManager.getConfig()).toThrow('Configuration not loaded');
		});

		it('should return providers sorted by priority', () => {
			const providers = configManager.getProviders();

			expect(providers).toHaveLength(3);
			expect(providers[0]!.name).toBe('high-priority');
			expect(providers[1]!.name).toBe('disabled');
			expect(providers[2]!.name).toBe('low-priority');
		});

		it('should return only enabled providers', () => {
			const enabledProviders = configManager.getEnabledProviders();

			expect(enabledProviders).toHaveLength(2);
			expect(enabledProviders.find(p => p.name === 'disabled')).toBeUndefined();
		});

		it('should find provider by name', () => {
			const provider = configManager.getProvider('high-priority');

			expect(provider).toBeDefined();
			expect(provider!.name).toBe('high-priority');
			expect(provider!.priority).toBe(100);
		});

		it('should return undefined for non-existent provider', () => {
			const provider = configManager.getProvider('non-existent');
			expect(provider).toBeUndefined();
		});

		it('should return settings', () => {
			const settings = configManager.getSettings();

			expect(settings.maxGenerationTime).toBe(8000);
			expect(settings.failOnProviderError).toBe(true);
			expect(settings.contentSeparator).toBe('\n---\n');
		});

		it('should report loaded status correctly', () => {
			expect(configManager.isLoaded()).toBe(true);

			const emptyManager = new SystemPromptConfigManager();
			expect(emptyManager.isLoaded()).toBe(false);
		});
	});

	describe('createDefault', () => {
		it('should create valid default configuration', () => {
			const defaultConfig = SystemPromptConfigManager.createDefault();

			expect(defaultConfig.providers).toHaveLength(1);
			expect(defaultConfig.providers[0]!.name).toBe('built-in-instructions');
			expect(defaultConfig.providers[0]!.type).toBe(ProviderType.STATIC);
			expect(defaultConfig.settings.maxGenerationTime).toBe(5000);
			expect(defaultConfig.settings.failOnProviderError).toBe(false);
		});

		it('should pass validation', () => {
			const defaultConfig = SystemPromptConfigManager.createDefault();
			expect(() => configManager.loadFromObject(defaultConfig)).not.toThrow();
		});
	});

	describe('validation', () => {
		it('should reject configuration without providers', () => {
			const invalidConfig = {
				settings: {
					maxGenerationTime: 5000,
					failOnProviderError: false,
					contentSeparator: '\n\n',
				},
			} as any;

			expect(() => configManager.loadFromObject(invalidConfig)).toThrow('providers');
		});

		it('should reject configuration without settings', () => {
			const invalidConfig = {
				providers: [],
			} as any;

			expect(() => configManager.loadFromObject(invalidConfig)).toThrow('settings');
		});

		it('should reject provider without required fields', () => {
			const invalidConfig = {
				providers: [
					{
						name: 'test',
						// missing type, priority, enabled
					},
				],
				settings: {
					maxGenerationTime: 5000,
					failOnProviderError: false,
					contentSeparator: '\n\n',
				},
			} as any;

			expect(() => configManager.loadFromObject(invalidConfig)).toThrow('Provider at index 0');
		});

		it('should reject provider with invalid type', () => {
			const invalidConfig = {
				providers: [
					{
						name: 'test',
						type: 'invalid-type',
						priority: 100,
						enabled: true,
					},
				],
				settings: {
					maxGenerationTime: 5000,
					failOnProviderError: false,
					contentSeparator: '\n\n',
				},
			} as any;

			expect(() => configManager.loadFromObject(invalidConfig)).toThrow('valid "type"');
		});

		it('should reject settings with invalid values', () => {
			const invalidConfig = {
				providers: [],
				settings: {
					maxGenerationTime: -1, // invalid
					failOnProviderError: false,
					contentSeparator: '\n\n',
				},
			} as any;

			expect(() => configManager.loadFromObject(invalidConfig)).toThrow('positive number');
		});
	});
});

/**
 * Tests for Configuration Schemas and Examples
 */

import { describe, it, expect } from 'vitest';
import {
	SYSTEM_PROMPT_CONFIG_SCHEMA,
	BASIC_CONFIG_EXAMPLE,
	DYNAMIC_CONFIG_EXAMPLE,
	FILE_BASED_CONFIG_EXAMPLE,
	CONDITIONAL_CONFIG_EXAMPLE,
	MINIMAL_CONFIG_EXAMPLE,
	getAllExampleConfigs,
} from '../config-schemas.js';
import { SystemPromptConfigManager } from '../config-manager.js';
import { ProviderType } from '../interfaces.js';

describe('Configuration Schemas and Examples', () => {
	describe('SYSTEM_PROMPT_CONFIG_SCHEMA', () => {
		it('should have correct structure', () => {
			expect(SYSTEM_PROMPT_CONFIG_SCHEMA.$schema).toBe('http://json-schema.org/draft-07/schema#');
			expect(SYSTEM_PROMPT_CONFIG_SCHEMA.type).toBe('object');
			expect(SYSTEM_PROMPT_CONFIG_SCHEMA.required).toContain('providers');
			expect(SYSTEM_PROMPT_CONFIG_SCHEMA.required).toContain('settings');
		});

		it('should define provider schema correctly', () => {
			const providerSchema = SYSTEM_PROMPT_CONFIG_SCHEMA.properties.providers.items;

			expect(providerSchema.required).toContain('name');
			expect(providerSchema.required).toContain('type');
			expect(providerSchema.required).toContain('priority');
			expect(providerSchema.required).toContain('enabled');

			expect(providerSchema.properties.type.enum).toEqual(Object.values(ProviderType));
		});

		it('should define settings schema correctly', () => {
			const settingsSchema = SYSTEM_PROMPT_CONFIG_SCHEMA.properties.settings;

			expect(settingsSchema.required).toContain('maxGenerationTime');
			expect(settingsSchema.required).toContain('failOnProviderError');
			expect(settingsSchema.required).toContain('contentSeparator');
		});
	});

	describe('example configurations', () => {
		let configManager: SystemPromptConfigManager;

		beforeEach(() => {
			configManager = new SystemPromptConfigManager();
		});

		it('should validate BASIC_CONFIG_EXAMPLE', () => {
			expect(() => configManager.loadFromObject(BASIC_CONFIG_EXAMPLE)).not.toThrow();

			const config = configManager.getConfig();
			expect(config.providers).toHaveLength(2);
			expect(config.providers[0]!.name).toBe('user-prompt');
			expect(config.providers[1]!.name).toBe('built-in-instructions');
		});

		it('should validate DYNAMIC_CONFIG_EXAMPLE', () => {
			expect(() => configManager.loadFromObject(DYNAMIC_CONFIG_EXAMPLE)).not.toThrow();

			const config = configManager.getConfig();
			const dynamicProviders = config.providers.filter(p => p.type === ProviderType.DYNAMIC);
			expect(dynamicProviders).toHaveLength(2);

			const contextProvider = config.providers.find(p => p.name === 'context-info');
			expect(contextProvider?.config?.generator).toBe('session-context');
		});

		it('should validate FILE_BASED_CONFIG_EXAMPLE', () => {
			expect(() => configManager.loadFromObject(FILE_BASED_CONFIG_EXAMPLE)).not.toThrow();

			const config = configManager.getConfig();
			const fileProviders = config.providers.filter(p => p.type === ProviderType.FILE_BASED);
			expect(fileProviders).toHaveLength(2);

			expect(config.settings.failOnProviderError).toBe(true);
		});

		it('should validate CONDITIONAL_CONFIG_EXAMPLE', () => {
			expect(() => configManager.loadFromObject(CONDITIONAL_CONFIG_EXAMPLE)).not.toThrow();

			const config = configManager.getConfig();
			const conditionalProvider = config.providers.find(p => p.name === 'adaptive-prompt');
			expect(conditionalProvider?.config?.generator).toBe('conditional');
			expect(conditionalProvider?.config?.generatorConfig.conditions).toHaveLength(2);
		});

		it('should validate MINIMAL_CONFIG_EXAMPLE', () => {
			expect(() => configManager.loadFromObject(MINIMAL_CONFIG_EXAMPLE)).not.toThrow();

			const config = configManager.getConfig();
			expect(config.providers).toHaveLength(1);
			expect(config.providers[0]!.name).toBe('basic-prompt');
		});

		it('should have correct priority ordering in examples', () => {
			configManager.loadFromObject(DYNAMIC_CONFIG_EXAMPLE);
			const providers = configManager.getProviders();

			// Should be sorted by priority (highest first)
			for (let i = 1; i < providers.length; i++) {
				expect(providers[i - 1]!.priority).toBeGreaterThanOrEqual(providers[i]!.priority);
			}
		});

		it('should have realistic settings in examples', () => {
			const examples = [
				BASIC_CONFIG_EXAMPLE,
				DYNAMIC_CONFIG_EXAMPLE,
				FILE_BASED_CONFIG_EXAMPLE,
				CONDITIONAL_CONFIG_EXAMPLE,
				MINIMAL_CONFIG_EXAMPLE,
			];

			examples.forEach(config => {
				expect(config.settings.maxGenerationTime).toBeGreaterThan(0);
				expect(config.settings.maxGenerationTime).toBeLessThanOrEqual(30000); // Reasonable upper limit
				expect(typeof config.settings.failOnProviderError).toBe('boolean');
				expect(typeof config.settings.contentSeparator).toBe('string');
			});
		});
	});

	describe('getAllExampleConfigs', () => {
		it('should return all example configurations', () => {
			const examples = getAllExampleConfigs();

			expect(examples).toHaveProperty('basic');
			expect(examples).toHaveProperty('dynamic');
			expect(examples).toHaveProperty('fileBased');
			expect(examples).toHaveProperty('conditional');
			expect(examples).toHaveProperty('minimal');

			expect(examples.basic).toBe(BASIC_CONFIG_EXAMPLE);
			expect(examples.dynamic).toBe(DYNAMIC_CONFIG_EXAMPLE);
			expect(examples.fileBased).toBe(FILE_BASED_CONFIG_EXAMPLE);
			expect(examples.conditional).toBe(CONDITIONAL_CONFIG_EXAMPLE);
			expect(examples.minimal).toBe(MINIMAL_CONFIG_EXAMPLE);
		});

		it('should have all examples validate successfully', () => {
			const examples = getAllExampleConfigs();
			const configManager = new SystemPromptConfigManager();

			Object.entries(examples).forEach(([name, config]) => {
				expect(
					() => configManager.loadFromObject(config),
					`Example "${name}" should validate successfully`
				).not.toThrow();
			});
		});
	});

	describe('provider type coverage', () => {
		it('should have examples for all provider types', () => {
			const allExamples = Object.values(getAllExampleConfigs());
			const usedTypes = new Set<string>();

			allExamples.forEach(config => {
				config.providers.forEach(provider => {
					usedTypes.add(provider.type);
				});
			});

			Object.values(ProviderType).forEach(type => {
				expect(usedTypes.has(type), `Provider type ${type} should have examples`).toBe(true);
			});
		});

		it('should demonstrate various configuration patterns', () => {
			// Test that examples show different configuration patterns

			// Template variables in static provider
			const basicExample = BASIC_CONFIG_EXAMPLE;
			expect(basicExample.providers.some(p => p.config?.variables)).toBeFalsy(); // Basic doesn't use variables

			// Dynamic content generation
			const dynamicExample = DYNAMIC_CONFIG_EXAMPLE;
			expect(dynamicExample.providers.some(p => p.type === ProviderType.DYNAMIC)).toBe(true);

			// File watching
			const fileExample = FILE_BASED_CONFIG_EXAMPLE;
			const fileProvider = fileExample.providers.find(p => p.type === ProviderType.FILE_BASED);
			expect(fileProvider?.config?.watchForChanges).toBeDefined();

			// Conditional logic
			const conditionalExample = CONDITIONAL_CONFIG_EXAMPLE;
			const conditionalProvider = conditionalExample.providers.find(
				p => p.config?.generator === 'conditional'
			);
			expect(conditionalProvider?.config?.generatorConfig?.conditions).toBeDefined();
		});
	});
});

