/**
 * Tests for Provider Registry
 */

import { describe, it, expect, beforeEach } from 'vitest';
import { DefaultProviderRegistry } from '../registry.js';
import { ProviderConfig, ProviderType, PromptProvider } from '../interfaces.js';

describe('DefaultProviderRegistry', () => {
	let registry: DefaultProviderRegistry;

	beforeEach(() => {
		registry = new DefaultProviderRegistry();
	});

	describe('constructor', () => {
		it('should register built-in provider types', () => {
			const types = registry.getRegisteredTypes();
			expect(types).toContain(ProviderType.STATIC);
			expect(types).toContain(ProviderType.DYNAMIC);
			expect(types).toContain(ProviderType.FILE_BASED);
		});
	});

	describe('register', () => {
		it('should register a new provider type', () => {
			const mockGenerator = async (_name: string, _generator: any) => ({}) as PromptProvider;

			registry.register('custom-type', mockGenerator);

			expect(registry.isRegistered('custom-type')).toBe(true);
			expect(registry.getRegisteredTypes()).toContain('custom-type');
		});

		it('should throw error for invalid type', () => {
			const mockGenerator = async (_name: string, _generator: any) => ({}) as PromptProvider;

			expect(() => registry.register('', mockGenerator)).toThrow(
				'Provider type must be a non-empty string'
			);
			expect(() => registry.register(null as any, mockGenerator)).toThrow(
				'Provider type must be a non-empty string'
			);
		});

		it('should throw error for invalid generator', () => {
			expect(() => registry.register('test', null as any)).toThrow('Generator must be a function');
			expect(() => registry.register('test', 'not a function' as any)).toThrow(
				'Generator must be a function'
			);
		});
	});

	describe('create', () => {
		it('should create static provider', async () => {
			const config: ProviderConfig = {
				name: 'test-static',
				type: ProviderType.STATIC,
				priority: 100,
				enabled: true,
				config: {
					content: 'Static test content',
				},
			};

			const provider = await registry.create(config);

			expect(provider.id).toBe('test-static');
			expect(provider.name).toBe('test-static');
			expect(provider.type).toBe(ProviderType.STATIC);
			expect(provider.priority).toBe(100);
			expect(provider.enabled).toBe(true);
		});

		it('should create dynamic provider', async () => {
			// First register a test generator
			// const mockDynamicProvider = {
			// 	registerGenerator: (name: string, generator: any) => {
			// 		// Mock implementation
			// 	},
			// };

			const config: ProviderConfig = {
				name: 'test-dynamic',
				type: ProviderType.DYNAMIC,
				priority: 50,
				enabled: true,
				config: {
					generator: 'test-gen',
					generatorConfig: { test: 'value' },
				},
			};

			// This will fail because we haven't registered the generator
			await expect(registry.create(config)).rejects.toThrow();
		});

		it('should throw error for unregistered type', async () => {
			const config: ProviderConfig = {
				name: 'test',
				type: 'unregistered-type' as any,
				priority: 100,
				enabled: true,
			};

			await expect(registry.create(config)).rejects.toThrow(
				"Provider type 'unregistered-type' is not registered"
			);
		});

		it('should handle generator errors', async () => {
			const failingGenerator = async () => {
				throw new Error('Generator failed');
			};

			registry.register('failing-type', failingGenerator);

			const config: ProviderConfig = {
				name: 'test',
				type: 'failing-type' as any,
				priority: 100,
				enabled: true,
			};

			await expect(registry.create(config)).rejects.toThrow("Failed to create provider 'test'");
		});
	});

	describe('isRegistered', () => {
		it('should return true for registered types', () => {
			expect(registry.isRegistered(ProviderType.STATIC)).toBe(true);
			expect(registry.isRegistered(ProviderType.DYNAMIC)).toBe(true);
			expect(registry.isRegistered(ProviderType.FILE_BASED)).toBe(true);
		});

		it('should return false for unregistered types', () => {
			expect(registry.isRegistered('unregistered')).toBe(false);
		});
	});

	describe('getRegisteredTypes', () => {
		it('should return all registered types', () => {
			const types = registry.getRegisteredTypes();

			expect(types).toContain(ProviderType.STATIC);
			expect(types).toContain(ProviderType.DYNAMIC);
			expect(types).toContain(ProviderType.FILE_BASED);
			expect(types.length).toBeGreaterThanOrEqual(3);
		});

		it('should include custom registered types', () => {
			const mockGenerator = async (_name: string, _generator: any) => ({}) as PromptProvider;
			registry.register('custom', mockGenerator);

			const types = registry.getRegisteredTypes();
			expect(types).toContain('custom');
		});
	});

	describe('unregister', () => {
		it('should unregister a provider type', () => {
			const mockGenerator = async (_name: string, _generator: any) => ({}) as PromptProvider;
			registry.register('temp-type', mockGenerator);

			expect(registry.isRegistered('temp-type')).toBe(true);

			const result = registry.unregister('temp-type');

			expect(result).toBe(true);
			expect(registry.isRegistered('temp-type')).toBe(false);
		});

		it('should return false for non-existent types', () => {
			const result = registry.unregister('non-existent');
			expect(result).toBe(false);
		});
	});

	describe('clear', () => {
		it('should clear all registered types', () => {
			const mockGenerator = async (_name: string, _generator: any) => ({}) as PromptProvider;
			registry.register('temp1', mockGenerator);
			registry.register('temp2', mockGenerator);

			expect(registry.getRegisteredTypes().length).toBeGreaterThan(0);

			registry.clear();

			expect(registry.getRegisteredTypes()).toHaveLength(0);
		});
	});
});

/**
 * Built-in Dynamic Content Generators
 *
 * Provides common dynamic content generators for system prompts.
 * These generators can be used in dynamic providers to inject runtime context.
 */

import { DynamicContentGenerator } from './providers/dynamic-provider.js';
import { ProviderContext } from './interfaces.js';

/**
 * Generate timestamp-based content
 */
export const timestampGenerator: DynamicContentGenerator = async (
	context: ProviderContext,
	config: Record<string, any>
): Promise<string> => {
	const format = config.format || 'iso';
	const includeTimezone = config.includeTimezone || false;

	switch (format) {
		case 'iso':
			return context.timestamp.toISOString();
		case 'locale': {
			const options: Intl.DateTimeFormatOptions = {
				year: 'numeric',
				month: 'long',
				day: 'numeric',
				hour: '2-digit',
				minute: '2-digit',
				...(includeTimezone && { timeZoneName: 'short' }),
			};
			return context.timestamp.toLocaleString('en-US', options);
		}
		case 'date-only':
			return context.timestamp.toISOString().split('T')[0]!;
		case 'time-only':
			return context.timestamp.toISOString().split('T')[1]!.split('.')[0]!;
		default:
			return context.timestamp.toString();
	}
};

/**
 * Generate session context information
 */
export const sessionContextGenerator: DynamicContentGenerator = async (
	context: ProviderContext,
	config: Record<string, any>
) => {
	const includeFields = config.includeFields || ['sessionId', 'userId'];
	const format = config.format || 'list';

	const contextInfo: string[] = [];

	if (includeFields.includes('sessionId') && context.sessionId) {
		contextInfo.push(`Session ID: ${context.sessionId}`);
	}

	if (includeFields.includes('userId') && context.userId) {
		contextInfo.push(`User ID: ${context.userId}`);
	}

	if (includeFields.includes('timestamp')) {
		contextInfo.push(`Timestamp: ${context.timestamp.toISOString()}`);
	}

	if (contextInfo.length === 0) {
		return '';
	}

	switch (format) {
		case 'list': {
			return contextInfo.join('\n');
		}
		case 'inline': {
			return contextInfo.join(', ');
		}
		case 'json': {
			const obj: Record<string, any> = {};
			if (includeFields.includes('sessionId') && context.sessionId)
				obj.sessionId = context.sessionId;
			if (includeFields.includes('userId') && context.userId) obj.userId = context.userId;
			if (includeFields.includes('timestamp')) obj.timestamp = context.timestamp.toISOString();
			return JSON.stringify(obj, null, 2);
		}
		default: {
			return contextInfo.join('\n');
		}
	}
};

/**
 * Generate memory-related context
 */
export const memoryContextGenerator: DynamicContentGenerator = async (
	context: ProviderContext,
	config: Record<string, any>
) => {
	if (!context.memoryContext) {
		return config.emptyMessage || 'No memory context available';
	}

	const format = config.format || 'summary';
	const maxItems = config.maxItems || 5;

	switch (format) {
		case 'summary': {
			const itemCount = Object.keys(context.memoryContext).length;
			return `Memory context contains ${itemCount} items`;
		}
		case 'list': {
			const items = Object.entries(context.memoryContext).slice(0, maxItems);
			return items.map(([key, value]) => `${key}: ${JSON.stringify(value)}`).join('\n');
		}
		case 'json': {
			return JSON.stringify(context.memoryContext, null, 2);
		}
		default: {
			return 'Memory context is available';
		}
	}
};

/**
 * Generate environment-specific instructions
 */
export const environmentGenerator: DynamicContentGenerator = async (
	context: ProviderContext,
	config: Record<string, any>
) => {
	const environment = config.environment || 'production';
	const customMessages = config.messages || {};

	const defaultMessages = {
		development: 'Development mode: Enhanced logging and debugging features are available.',
		staging: 'Staging environment: Please verify all changes before promoting to production.',
		production: 'Production environment: Exercise caution with all operations.',
		testing: 'Testing mode: Automated testing features are enabled.',
	};

	return (
		customMessages[environment] ||
		defaultMessages[environment as keyof typeof defaultMessages] ||
		`Environment: ${environment}`
	);
};

/**
 * Generate conditional content based on context
 */
export const conditionalGenerator: DynamicContentGenerator = async (
	context: ProviderContext,
	config: Record<string, any>
) => {
	const conditions = config.conditions || [];

	for (const condition of conditions) {
		if (evaluateCondition(condition.if, context)) {
			return condition.then || '';
		}
	}

	return config.else || '';
};

/**
 * Simple condition evaluator for conditional generator
 */
function evaluateCondition(condition: any, context: ProviderContext): boolean {
	if (typeof condition === 'string') {
		// Simple string conditions like 'userId' (checks if userId exists)
		return !!(context as any)[condition];
	}

	if (typeof condition === 'object' && condition !== null) {
		// Object conditions like { field: 'userId', operator: 'exists' }
		const { field, operator, value } = condition;
		const fieldValue = (context as any)[field];

		switch (operator) {
			case 'exists':
				return fieldValue !== undefined && fieldValue !== null && fieldValue !== '';
			case 'equals':
				return fieldValue === value;
			case 'contains':
				return typeof fieldValue === 'string' && fieldValue.includes(value);
			case 'gt':
				return typeof fieldValue === 'number' && fieldValue > value;
			case 'lt':
				return typeof fieldValue === 'number' && fieldValue < value;
			default:
				return false;
		}
	}

	return false;
}

/**
 * Helper to fetch session history for dynamic LLM-driven generators
 */
async function fetchSessionHistory(
	context: ProviderContext,
	config: Record<string, any>
): Promise<string[]> {
	const sessionId = context.sessionId;
	const historyConfig = config.history || 'all';
	const metadata = context.metadata || {};
	const storageManager = metadata.storageManager;
	if (!sessionId || !storageManager) return [];
	// Import here to avoid circular deps
	const { createDatabaseHistoryProvider } = await import('../llm/messages/history/factory.js');
	const historyProvider = createDatabaseHistoryProvider(storageManager);
	let limit = 1000;
	if (typeof historyConfig === 'number') limit = historyConfig;
	if (typeof historyConfig === 'string' && historyConfig !== 'all')
		limit = parseInt(historyConfig, 10) || 1000;
	const messages = await historyProvider.getHistory(sessionId, limit);
	// Map content to string
	return messages.map(m => {
		if (typeof m.content === 'string') return m.content;
		if (Array.isArray(m.content)) {
			return m.content.map(seg => (seg.type === 'text' ? seg.text : '[Image]')).join(' ');
		}
		return '';
	});
}

/**
 * Helper to get llmService from context.metadata
 */
function getLLMService(context: ProviderContext): any {
	return context.metadata?.llmService;
}

/**
 * LLM-driven summary generator
 */
export const summaryGenerator: DynamicContentGenerator = async (context, config) => {
	const llmService = getLLMService(context);
	if (!llmService) return '[LLM service unavailable: cannot generate summary]';
	const history = await fetchSessionHistory(context, config);
	if (!history.length) return '[No session history to summarize]';
	const prompt = `Summarize the following conversation in a concise paragraph (maximum 4-5 sentences) for the system prompt.\n\n${history.join('\n')}\n\nSummary:`;
	return await llmService.directGenerate(prompt);
};

/**
 * LLM-driven rules/specs extraction generator
 */
export const rulesGenerator: DynamicContentGenerator = async (context, config) => {
	const llmService = getLLMService(context);
	if (!llmService) return '[LLM service unavailable: cannot extract rules]';
	const history = await fetchSessionHistory(context, config);
	if (!history.length) return '[No session history to extract rules from]';
	const prompt = `Extract any rules, requirements, or project specifications set by the user in the following conversation. List them clearly and concisely for the system prompt (maximum 4-5 sentences).\n\n${history.join('\n')}\n\nRules/Specs:`;
	return await llmService.directGenerate(prompt);
};

/**
 * LLM-driven error/bug detection generator
 */
export const errorDetectionGenerator: DynamicContentGenerator = async (context, config) => {
	const llmService = getLLMService(context);
	if (!llmService) return '[LLM service unavailable: cannot detect errors]';
	const history = await fetchSessionHistory(context, config);
	if (!history.length) return '[No session history to detect errors from]';
	const prompt = `Identify any errors, bugs, or issues discussed or emphasized by the user in the following conversation. List them concisely for the system prompt (maximum 4-5 sentences).\n\n${history.join('\n')}\n\nErrors/Bugs:`;
	return await llmService.directGenerate(prompt);
};

/**
 * Register all built-in generators
 */
export async function registerBuiltInGenerators() {
	const { DynamicPromptProvider } = await import('./providers/dynamic-provider.js');

	DynamicPromptProvider.registerGenerator('timestamp', timestampGenerator);
	DynamicPromptProvider.registerGenerator('session-context', sessionContextGenerator);
	DynamicPromptProvider.registerGenerator('memory-context', memoryContextGenerator);
	DynamicPromptProvider.registerGenerator('environment', environmentGenerator);
	DynamicPromptProvider.registerGenerator('conditional', conditionalGenerator);
	// Register new LLM-driven generators
	DynamicPromptProvider.registerGenerator('summary', summaryGenerator);
	DynamicPromptProvider.registerGenerator('rules', rulesGenerator);
	DynamicPromptProvider.registerGenerator('error-detection', errorDetectionGenerator);
}

/**
 * Get all built-in generator names
 */
export function getBuiltInGeneratorNames(): string[] {
	return ['timestamp', 'session-context', 'memory-context', 'environment', 'conditional'];
}

/**
 * Configuration Manager for System Prompt Architecture
 *
 * Handles loading, parsing, and validation of system prompt configurations.
 * Supports both programmatic configuration and file-based configuration.
 */

import { promises as fs } from 'fs';
import path from 'path';
import { SystemPromptConfig, ProviderConfig, ProviderType } from './interfaces.js';

export interface ConfigLoadOptions {
	/** Base directory for resolving relative file paths */
	baseDir?: string;
	/** Environment variables to replace in configuration */
	envVariables?: Record<string, string>;
	/** Whether to validate configuration after loading */
	validate?: boolean;
}

export class SystemPromptConfigManager {
	private config: SystemPromptConfig | null = null;
	private baseDir: string = process.cwd();

	/**
	 * Load configuration from an object
	 */
	public loadFromObject(config: SystemPromptConfig, options: ConfigLoadOptions = {}): void {
		this.baseDir = options.baseDir || process.cwd();

		if (options.validate !== false) {
			this.validateConfig(config);
		}

		this.config = this.processConfiguration(config, options);
	}

	/**
	 * Load configuration from a JSON file
	 */
	public async loadFromFile(filePath: string, options: ConfigLoadOptions = {}): Promise<void> {
		const fullPath = path.isAbsolute(filePath)
			? filePath
			: path.resolve(options.baseDir || process.cwd(), filePath);
		this.baseDir = path.dirname(fullPath);

		try {
			const fileContent = await fs.readFile(fullPath, 'utf8');
			const rawConfig = JSON.parse(fileContent);

			if (options.validate !== false) {
				this.validateConfig(rawConfig);
			}

			this.config = this.processConfiguration(rawConfig, options);
		} catch (error) {
			throw new Error(
				`Failed to load configuration from ${filePath}: ${error instanceof Error ? error.message : 'Unknown error'}`
			);
		}
	}

	/**
	 * Get the current configuration
	 */
	public getConfig(): SystemPromptConfig {
		if (!this.config) {
			throw new Error('Configuration not loaded. Call loadFromObject() or loadFromFile() first.');
		}
		return this.config;
	}

	/**
	 * Get providers sorted by priority (highest first)
	 */
	public getProviders(): ProviderConfig[] {
		const config = this.getConfig();
		return [...config.providers].sort((a, b) => b.priority - a.priority);
	}

	/**
	 * Get enabled providers sorted by priority
	 */
	public getEnabledProviders(): ProviderConfig[] {
		return this.getProviders().filter(provider => provider.enabled);
	}

	/**
	 * Get a specific provider by name
	 */
	public getProvider(name: string): ProviderConfig | undefined {
		const config = this.getConfig();
		return config.providers.find(provider => provider.name === name);
	}

	/**
	 * Check if configuration is loaded
	 */
	public isLoaded(): boolean {
		return this.config !== null;
	}

	/**
	 * Get configuration settings
	 */
	public getSettings() {
		const config = this.getConfig();
		return config.settings;
	}

	/**
	 * Create a default configuration
	 */
	public static createDefault(): SystemPromptConfig {
		return {
			providers: [
				{
					name: 'built-in-instructions',
					type: ProviderType.STATIC,
					priority: 0,
					enabled: true,
					config: {
						content:
							'# Built-in System Instructions\nThis section contains built-in tool instructions and agent behavior guidelines.',
					},
				},
			],
			settings: {
				maxGenerationTime: 5000,
				failOnProviderError: false,
				contentSeparator: '\n\n',
			},
		};
	}

	/**
	 * Validate configuration structure and content
	 */
	private validateConfig(config: any): void {
		if (!config || typeof config !== 'object') {
			throw new Error('Configuration must be an object');
		}

		// Validate providers array
		if (!Array.isArray(config.providers)) {
			throw new Error('Configuration must have a "providers" array');
		}

		// Validate each provider
		config.providers.forEach((provider: any, index: number) => {
			this.validateProvider(provider, index);
		});

		// Validate settings
		if (!config.settings || typeof config.settings !== 'object') {
			throw new Error('Configuration must have a "settings" object');
		}

		this.validateSettings(config.settings);
	}

	/**
	 * Validate a single provider configuration
	 */
	private validateProvider(provider: any, index: number): void {
		const prefix = `Provider at index ${index}`;

		if (!provider || typeof provider !== 'object') {
			throw new Error(`${prefix} must be an object`);
		}

		// Validate required fields
		if (typeof provider.name !== 'string' || !provider.name.trim()) {
			throw new Error(`${prefix} must have a non-empty "name" string`);
		}

		if (
			typeof provider.type !== 'string' ||
			!Object.values(ProviderType).includes(provider.type as ProviderType)
		) {
			throw new Error(
				`${prefix} must have a valid "type" (${Object.values(ProviderType).join(', ')})`
			);
		}

		if (typeof provider.priority !== 'number') {
			throw new Error(`${prefix} must have a numeric "priority"`);
		}

		if (typeof provider.enabled !== 'boolean') {
			throw new Error(`${prefix} must have a boolean "enabled" field`);
		}

		// Validate config field if present
		if (
			provider.config !== undefined &&
			(typeof provider.config !== 'object' || provider.config === null)
		) {
			throw new Error(`${prefix} "config" must be an object if provided`);
		}
	}

	/**
	 * Validate settings configuration
	 */
	private validateSettings(settings: any): void {
		if (typeof settings.maxGenerationTime !== 'number' || settings.maxGenerationTime <= 0) {
			throw new Error('Settings "maxGenerationTime" must be a positive number');
		}

		if (typeof settings.failOnProviderError !== 'boolean') {
			throw new Error('Settings "failOnProviderError" must be a boolean');
		}

		if (typeof settings.contentSeparator !== 'string') {
			throw new Error('Settings "contentSeparator" must be a string');
		}
	}

	/**
	 * Process configuration with environment variable replacement and path resolution
	 */
	private processConfiguration(
		config: SystemPromptConfig,
		options: ConfigLoadOptions
	): SystemPromptConfig {
		const processed = JSON.parse(JSON.stringify(config)); // Deep clone

		// Process environment variables if provided
		if (options.envVariables) {
			this.replaceEnvironmentVariables(processed, options.envVariables);
		}

		// Process file paths for file-based providers - only if providers is an array
		if (Array.isArray(processed.providers)) {
			processed.providers.forEach((provider: any) => {
				if (provider.type === ProviderType.FILE_BASED && provider.config?.filePath) {
					if (!path.isAbsolute(provider.config.filePath)) {
						provider.config.filePath = path.resolve(this.baseDir, provider.config.filePath);
					}
				}
			});
		}

		return processed;
	}

	/**
	 * Replace environment variables in configuration
	 */
	private replaceEnvironmentVariables(obj: any, envVars: Record<string, string>): void {
		for (const key in obj) {
			if (typeof obj[key] === 'string') {
				// Replace ${VAR_NAME} patterns
				obj[key] = obj[key].replace(/\$\{([^}]+)\}/g, (match: string, varName: string) => {
					return envVars[varName] || match;
				});
			} else if (typeof obj[key] === 'object' && obj[key] !== null) {
				this.replaceEnvironmentVariables(obj[key], envVars);
			}
		}
	}
}

/**
 * Configuration Schema Definitions and Examples
 *
 * Provides schema definitions and example configurations for the system prompt architecture.
 * These can be used for validation, documentation, and as templates for new configurations.
 */

import { SystemPromptConfig, ProviderType } from './interfaces.js';

/**
 * JSON Schema for SystemPromptConfig validation
 */
export const SYSTEM_PROMPT_CONFIG_SCHEMA = {
	$schema: 'http://json-schema.org/draft-07/schema#',
	type: 'object',
	required: ['providers', 'settings'],
	properties: {
		providers: {
			type: 'array',
			items: {
				type: 'object',
				required: ['name', 'type', 'priority', 'enabled'],
				properties: {
					name: {
						type: 'string',
						minLength: 1,
						description: 'Unique identifier for the provider',
					},
					type: {
						type: 'string',
						enum: Object.values(ProviderType),
						description: 'Type of provider (static, dynamic, file-based)',
					},
					priority: {
						type: 'number',
						description: 'Execution priority (higher numbers execute first)',
					},
					enabled: {
						type: 'boolean',
						description: 'Whether this provider is enabled',
					},
					config: {
						type: 'object',
						description: 'Provider-specific configuration',
					},
				},
			},
		},
		settings: {
			type: 'object',
			required: ['maxGenerationTime', 'failOnProviderError', 'contentSeparator'],
			properties: {
				maxGenerationTime: {
					type: 'number',
					minimum: 1,
					description: 'Maximum time to wait for all providers (milliseconds)',
				},
				failOnProviderError: {
					type: 'boolean',
					description: 'Whether to fail if any provider fails',
				},
				contentSeparator: {
					type: 'string',
					description: 'Separator between provider outputs',
				},
			},
		},
	},
};

