/**
 * Enhanced Prompt Manager
 *
 * New plugin-based prompt manager that replaces the legacy PromptManager.
 * Provides extensible, configurable, and high-performance system prompt generation.
 */

import {
	PromptProvider,
	ProviderContext,
	PromptGenerationResult,
	ProviderResult,
	SystemPromptConfig,
} from './interfaces.js';
import { SystemPromptConfigManager } from './config-manager.js';
import { providerRegistry } from './registry.js';
import { registerBuiltInGenerators } from './built-in-generators.js';

export interface EnhancedPromptManagerOptions {
	/** Configuration for the prompt manager */
	config?: SystemPromptConfig;
	/** Whether to automatically register built-in generators */
	registerBuiltInGenerators?: boolean;
	/** Custom context to merge with runtime context */
	defaultContext?: Partial<ProviderContext>;
}

export class EnhancedPromptManager {
	private configManager: SystemPromptConfigManager;
	private providers: Map<string, PromptProvider> = new Map();
	private dynamicAndFileProviderConfigs: Map<string, any> = new Map(); // Store configs for runtime
	private defaultContext: Partial<ProviderContext>;
	private initialized: boolean = false;
	private llmService: any = undefined; // Store reference to llmService

	constructor(options: EnhancedPromptManagerOptions = {}) {
		this.configManager = new SystemPromptConfigManager();
		this.defaultContext = options.defaultContext || {};

		if (options.config) {
			this.configManager.loadFromObject(options.config);
		}

		// Register built-in generators by default
		if (options.registerBuiltInGenerators !== false) {
			this.initializeBuiltInGenerators();
		}
	}

	/**
	 * Set the LLM service reference for use in provider context
	 */
	public setLLMService(llmService: any) {
		this.llmService = llmService;
	}

	/**
	 * Initialize the manager with configuration
	 */
	public async initialize(config?: SystemPromptConfig): Promise<void> {
		if (config) {
			this.configManager.loadFromObject(config);
		}

		if (!this.configManager.isLoaded()) {
			// Use default configuration if none provided
			const defaultConfig = SystemPromptConfigManager.createDefault();
			this.configManager.loadFromObject(defaultConfig);
		}

		// Create provider instances
		await this.createProviders();

		this.initialized = true;
	}

	/**
	 * Load configuration from file
	 */
	public async loadConfigFromFile(filePath: string): Promise<void> {
		await this.configManager.loadFromFile(filePath);

		if (this.initialized) {
			// Recreate providers with new configuration
			await this.destroyProviders();
			await this.createProviders();
		}
	}

	/**
	 * Generate complete system prompt
	 */
	public async generateSystemPrompt(
		runtimeContext: Partial<ProviderContext> = {}
	): Promise<PromptGenerationResult> {
		this.ensureInitialized();

		const startTime = Date.now();
		const context = this.buildContext(runtimeContext);
		const settings = this.configManager.getSettings();
		const enabledProviders = this.getEnabledProviders();

		// Support useCache flag in context
		const useCache = (runtimeContext as any).useCache === true;

		const providerResults: ProviderResult[] = [];
		const errors: Error[] = [];
		let success = true;

		// Generate content from all enabled providers, but track all providers in results
		const allProviders = Array.from(this.providers.values()).sort(
			(a, b) => b.priority - a.priority
		);

		const promises = allProviders.map(async (provider): Promise<void> => {
			if (!provider.enabled) {
				// Add result for disabled provider
				providerResults.push({
					providerId: provider.id,
					content: '',
					generationTimeMs: 0,
					success: false,
					error: new Error('Provider is disabled'),
				});
				return;
			}
			const providerStartTime = Date.now();

			try {
				// If useCache is true and provider supports getCachedContent, use it
				if (useCache && typeof (provider as any).getCachedContent === 'function') {
					const cached = (provider as any).getCachedContent();
					if (cached !== null && cached !== undefined) {
						providerResults.push({
							providerId: provider.id,
							content: cached,
							generationTimeMs: 0,
							success: true,
						});
						return;
					}
				}
				const content = await this.executeWithTimeout(
					() => provider.generateContent(context),
					settings.maxGenerationTime
				);

				providerResults.push({
					providerId: provider.id,
					content,
					generationTimeMs: Date.now() - providerStartTime,
					success: true,
				});
			} catch (error) {
				const err = error instanceof Error ? error : new Error('Unknown error');

				providerResults.push({
					providerId: provider.id,
					content: '',
					generationTimeMs: Date.now() - providerStartTime,
					success: false,
					error: err,
				});

				errors.push(err);

				if (settings.failOnProviderError) {
					success = false;
				}
			}
		});

		await Promise.all(promises);

		// Sort results by provider priority (to maintain order)
		providerResults.sort((a, b) => {
			const providerA = enabledProviders.find(p => p.id === a.providerId);
			const providerB = enabledProviders.find(p => p.id === b.providerId);
			return (providerB?.priority || 0) - (providerA?.priority || 0);
		});

		// Combine successful results
		const successfulResults = providerResults.filter(r => r.success && r.content.trim());
		const content = successfulResults.map(r => r.content).join(settings.contentSeparator);

		return {
			content,
			providerResults,
			generationTimeMs: Date.now() - startTime,
			success: success && successfulResults.length > 0,
			errors,
		};
	}

	/**
	 * Get current configuration
	 */
	public getConfig(): SystemPromptConfig {
		return this.configManager.getConfig();
	}

	/**
	 * Get all providers (enabled and disabled)
	 */
	public getProviders(): PromptProvider[] {
		return Array.from(this.providers.values());
	}

	/**
	 * Get enabled providers sorted by priority
	 */
	public getEnabledProviders(): PromptProvider[] {
		return Array.from(this.providers.values())
			.filter(provider => provider.enabled)
			.sort((a, b) => b.priority - a.priority);
	}

	/**
	 * Get a specific provider by ID
	 */
	public getProvider(id: string): PromptProvider | undefined {
		return this.providers.get(id);
	}

	/**
	 * Enable or disable a provider
	 */
	public setProviderEnabled(id: string, enabled: boolean): void {
		const provider = this.providers.get(id);
		if (provider) {
			provider.enabled = enabled;
		}
	}

	/**
	 * Check if manager is initialized
	 */
	public isInitialized(): boolean {
		return this.initialized;
	}

	/**
	 * Get performance statistics
	 */
	public async getPerformanceStats(): Promise<{
		totalProviders: number;
		enabledProviders: number;
		averageGenerationTime: number;
		lastGenerationResult?: PromptGenerationResult;
	}> {
		const providers = this.getProviders();
		const enabledProviders = this.getEnabledProviders();

		// Generate a test prompt to measure performance
		const testResult = await this.generateSystemPrompt({
			timestamp: new Date(),
			sessionId: 'perf-test',
		});

		return {
			totalProviders: providers.length,
			enabledProviders: enabledProviders.length,
			averageGenerationTime: Math.max(testResult.generationTimeMs, 1), // Ensure at least 1ms
			lastGenerationResult: testResult,
		};
	}

	/**
	 * Destroy the manager and clean up resources
	 */
	public async destroy(): Promise<void> {
		await this.destroyProviders();
		this.initialized = false;
	}

	/**
	 * Initialize built-in generators
	 */
	private async initializeBuiltInGenerators(): Promise<void> {
		await registerBuiltInGenerators();
	}

	/**
	 * Create provider instances from configuration
	 * Only instantiate static providers at startup.
	 * Store dynamic and file-based provider configs for runtime activation.
	 */
	private async createProviders(): Promise<void> {
		const providerConfigs = this.configManager.getProviders();
		for (const config of providerConfigs) {
			if (config.type === 'static' && config.enabled) {
				try {
					const provider = await providerRegistry.create(config);
					this.providers.set(provider.id, provider);
				} catch (error) {
					console.warn(`Failed to create provider '${config.name}':`, error);
				}
			} else if (config.type === 'dynamic' || config.type === 'file-based') {
				// Store for runtime activation
				this.dynamicAndFileProviderConfigs.set(config.name, config);
			}
		}
	}

	/**
	 * Add or update a dynamic or file-based provider at runtime.
	 * If a provider with the same name exists, replace it.
	 * Triggers prompt rebuild.
	 */
	public async addOrUpdateProvider(config: any): Promise<void> {
		if (config.type === 'static') {
			throw new Error('Static providers cannot be added/updated at runtime.');
		}
		// Remove existing provider if present
		if (this.providers.has(config.name)) {
			await this.removeProvider(config.name);
		}
		// Create and add the new provider
		try {
			const provider = await providerRegistry.create(config);
			this.providers.set(provider.id, provider);
			this.dynamicAndFileProviderConfigs.set(config.name, config);
			// Trigger prompt rebuild (could be a callback or event in real system)
		} catch (error) {
			console.warn(`Failed to add/update provider '${config.name}':`, error);
		}
	}

	/**
	 * Remove a dynamic or file-based provider at runtime.
	 * Triggers prompt rebuild.
	 */
	public async removeProvider(name: string): Promise<void> {
		const provider = this.providers.get(name);
		if (provider) {
			await provider.destroy();
			this.providers.delete(name);
			this.dynamicAndFileProviderConfigs.delete(name);
			// Trigger prompt rebuild (could be a callback or event in real system)
		}
	}

	/**
	 * List all providers and their status.
	 */
	public listProviders(): { id: string; type: string; enabled: boolean }[] {
		return Array.from(this.providers.values()).map(p => ({
			id: p.id,
			type: p.type,
			enabled: p.enabled,
		}));
	}

	/**
	 * Destroy all provider instances
	 */
	private async destroyProviders(): Promise<void> {
		const destroyPromises = Array.from(this.providers.values()).map(async provider => {
			try {
				await provider.destroy();
			} catch (error) {
				console.warn(`Failed to destroy provider '${provider.id}':`, error);
			}
		});

		await Promise.all(destroyPromises);
		this.providers.clear();
	}

	/**
	 * Build context by merging default and runtime context
	 */
	private buildContext(runtimeContext: Partial<ProviderContext>): ProviderContext {
		// Merge llmService into metadata
		const base: ProviderContext = {
			timestamp: new Date(),
			...this.defaultContext,
			...runtimeContext,
		};
		// Always inject llmService into metadata
		return {
			...base,
			metadata: {
				...(base.metadata || {}),
				llmService: this.llmService,
			},
		};
	}

	/**
	 * Execute a function with timeout
	 */
	private async executeWithTimeout<T>(fn: () => Promise<T>, timeoutMs: number): Promise<T> {
		return new Promise((resolve, reject) => {
			const timeout = setTimeout(() => {
				reject(new Error(`Operation timed out after ${timeoutMs}ms`));
			}, timeoutMs);

			fn()
				.then(resolve)
				.catch(reject)
				.finally(() => clearTimeout(timeout));
		});
	}

	/**
	 * Ensure manager is initialized
	 */
	private ensureInitialized(): void {
		if (!this.initialized) {
			throw new Error('EnhancedPromptManager is not initialized. Call initialize() first.');
		}
	}
}

/**
 * System Prompt Architecture - Main Exports
 *
 * This module provides a complete plugin-based system prompt management solution
 * with backward compatibility for existing code.
 */

// Core interfaces and types
export * from './interfaces.js';

// Provider implementations
export * from './providers/index.js';

// Registry and configuration
export { providerRegistry, DefaultProviderRegistry } from './registry.js';
export { SystemPromptConfigManager } from './config-manager.js';
export * from './config-schemas.js';

// Built-in generators
export * from './built-in-generators.js';

// Enhanced manager
export { EnhancedPromptManager } from './enhanced-manager.js';

/**
 * Core interfaces for the System Prompt Plugin Architecture
 *
 * This module defines the foundational interfaces and types for the
 * extensible system prompt management system.
 */

/**
 * Context information passed to prompt providers for dynamic content generation
 */
export interface ProviderContext {
	/** Current timestamp */
	timestamp: Date;
	/** User ID or identifier if available */
	userId?: string;
	/** Session identifier */
	sessionId?: string;
	/** Current memory state or relevant memory chunks */
	memoryContext?: Record<string, any>;
	/** Additional runtime context data */
	metadata?: Record<string, any>;
}

/**
 * Configuration options for prompt providers
 */
export interface ProviderConfig {
	/** Provider name/identifier */
	name: string;
	/** Provider type */
	type: ProviderType;
	/** Execution priority (higher numbers execute first) */
	priority: number;
	/** Whether this provider is enabled */
	enabled: boolean;
	/** Provider-specific configuration */
	config?: Record<string, any>;
}

/**
 * Types of prompt providers supported by the system
 */
export enum ProviderType {
	/** Static content that doesn't change */
	STATIC = 'static',
	/** Dynamic content generated at runtime */
	DYNAMIC = 'dynamic',
	/** Content loaded from external files */
	FILE_BASED = 'file-based',
}

/**
 * Main interface for all prompt providers
 */
export interface PromptProvider {
	/** Unique identifier for this provider */
	readonly id: string;

	/** Human-readable name */
	readonly name: string;

	/** Provider type */
	readonly type: ProviderType;

	/** Execution priority */
	readonly priority: number;

	/** Whether this provider is currently enabled */
	enabled: boolean;

	/**
	 * Generate prompt content
	 * @param context Runtime context for dynamic content generation
	 * @returns Promise resolving to the generated prompt content
	 */
	generateContent(context: ProviderContext): Promise<string>;

	/**
	 * Validate provider configuration
	 * @param config Configuration to validate
	 * @returns True if configuration is valid
	 */
	validateConfig(config: Record<string, any>): boolean;

	/**
	 * Initialize the provider with configuration
	 * @param config Provider configuration
	 */
	initialize(config: Record<string, any>): Promise<void>;

	/**
	 * Clean up resources when provider is destroyed
	 */
	destroy(): Promise<void>;
}

/**
 * Registry for managing prompt provider generator functions
 */
export interface ProviderRegistry {
	/**
	 * Register a provider generator function
	 * @param type Provider type
	 * @param generator Function that creates provider instances
	 */
	register(type: string, generator: ProviderGenerator): void;

	/**
	 * Create a provider instance
	 * @param config Provider configuration
	 * @returns Created provider instance
	 */
	create(config: ProviderConfig): Promise<PromptProvider>;

	/**
	 * Get all registered provider types
	 */
	getRegisteredTypes(): string[];

	/**
	 * Check if a provider type is registered
	 * @param type Provider type to check
	 */
	isRegistered(type: string): boolean;
}

/**
 * Function type for creating provider instances
 */
export type ProviderGenerator = (config: ProviderConfig) => Promise<PromptProvider>;

/**
 * Configuration for the entire prompt management system
 */
export interface SystemPromptConfig {
	/** List of provider configurations */
	providers: ProviderConfig[];

	/** Global settings */
	settings: {
		/** Maximum time to wait for all providers (ms) */
		maxGenerationTime: number;
		/** Whether to fail if any provider fails */
		failOnProviderError: boolean;
		/** Separator between provider outputs */
		contentSeparator: string;
	};
}

/**
 * Result from generating system prompt content
 */
export interface PromptGenerationResult {
	/** The complete generated prompt */
	content: string;

	/** Individual provider results */
	providerResults: ProviderResult[];

	/** Total generation time in milliseconds */
	generationTimeMs: number;

	/** Whether generation was successful */
	success: boolean;

	/** Any errors that occurred */
	errors: Error[];
}

/**
 * Result from a single provider
 */
export interface ProviderResult {
	/** Provider ID */
	providerId: string;

	/** Generated content */
	content: string;

	/** Generation time for this provider */
	generationTimeMs: number;

	/** Whether this provider succeeded */
	success: boolean;

	/** Error if provider failed */
	error?: Error;
}

/**
 * Base abstract class for all prompt providers
 *
 * This provides common functionality and enforces the interface contract
 * for all prompt provider implementations.
 */

import { PromptProvider, ProviderType, ProviderContext } from '../interfaces.js';

export abstract class BasePromptProvider implements PromptProvider {
	public readonly id: string;
	public readonly name: string;
	public readonly type: ProviderType;
	public readonly priority: number;
	public enabled: boolean;

	protected config: Record<string, any> = {};
	protected initialized: boolean = false;

	constructor(
		id: string,
		name: string,
		type: ProviderType,
		priority: number,
		enabled: boolean = true
	) {
		this.id = id;
		this.name = name;
		this.type = type;
		this.priority = priority;
		this.enabled = enabled;
	}

	/**
	 * Abstract method that must be implemented by concrete providers
	 */
	public abstract generateContent(context: ProviderContext): Promise<string>;

	/**
	 * Default validation - can be overridden by concrete providers
	 */
	public validateConfig(config: Record<string, any>): boolean {
		// Basic validation - check if config is an object
		return typeof config === 'object' && config !== null;
	}

	/**
	 * Initialize the provider with configuration
	 */
	public async initialize(config: Record<string, any>): Promise<void> {
		if (!this.validateConfig(config)) {
			throw new Error(`Invalid configuration for provider ${this.id}`);
		}

		this.config = { ...config };
		this.initialized = true;
	}

	/**
	 * Default cleanup - can be overridden by concrete providers
	 */
	public async destroy(): Promise<void> {
		this.config = {};
		this.initialized = false;
	}

	/**
	 * Check if provider is initialized
	 */
	protected ensureInitialized(): void {
		if (!this.initialized) {
			throw new Error(`Provider ${this.id} is not initialized`);
		}
	}

	/**
	 * Check if provider is enabled and initialized
	 */
	protected canGenerate(): boolean {
		return this.enabled && this.initialized;
	}
}

/**
 * Dynamic Prompt Provider
 *
 * Provides content that is generated at runtime based on context.
 * Useful for time-sensitive information, user-specific data, or contextual instructions.
 */

import { ProviderType, ProviderContext } from '../interfaces.js';
import { BasePromptProvider } from './base-provider.js';

export type DynamicContentGenerator = (
	context: ProviderContext,
	config: Record<string, any>
) => Promise<string>;

export interface DynamicProviderConfig {
	/** The generator function name or identifier */
	generator: string;
	/** Configuration passed to the generator function */
	generatorConfig?: Record<string, any>;
	/** Template to wrap the generated content */
	template?: string;
}

export class DynamicPromptProvider extends BasePromptProvider {
	private generatorName: string = '';
	private generatorConfig: Record<string, any> = {};
	private template: string = '';
	private generatorFunction: DynamicContentGenerator | undefined;

	// Cached content for this provider
	private cachedContent: string | null = null;

	// Static registry of generator functions
	private static generators: Map<string, DynamicContentGenerator> = new Map();

	constructor(id: string, name: string, priority: number, enabled: boolean = true) {
		super(id, name, ProviderType.DYNAMIC, priority, enabled);
	}

	/**
	 * Register a dynamic content generator function
	 */
	public static registerGenerator(name: string, generator: DynamicContentGenerator): void {
		DynamicPromptProvider.generators.set(name, generator);
	}

	/**
	 * Get all registered generator names
	 */
	public static getRegisteredGenerators(): string[] {
		return Array.from(DynamicPromptProvider.generators.keys());
	}

	/**
	 * Check if a generator is registered
	 */
	public static isGeneratorRegistered(name: string): boolean {
		return DynamicPromptProvider.generators.has(name);
	}

	public override validateConfig(config: Record<string, any>): boolean {
		if (!super.validateConfig(config)) {
			return false;
		}

		const typedConfig = config as DynamicProviderConfig;

		// Generator name is required and must be a string
		if (typeof typedConfig.generator !== 'string' || !typedConfig.generator.trim()) {
			return false;
		}

		// Generator must be registered
		if (!DynamicPromptProvider.isGeneratorRegistered(typedConfig.generator)) {
			return false;
		}

		// GeneratorConfig is optional but must be an object if provided
		if (typedConfig.generatorConfig !== undefined) {
			if (typeof typedConfig.generatorConfig !== 'object' || typedConfig.generatorConfig === null) {
				return false;
			}
		}

		// Template is optional but must be a string if provided
		if (typedConfig.template !== undefined) {
			if (typeof typedConfig.template !== 'string') {
				return false;
			}
		}

		return true;
	}

	public override async initialize(config: Record<string, any>): Promise<void> {
		await super.initialize(config);

		const typedConfig = config as DynamicProviderConfig;
		this.generatorName = typedConfig.generator;
		this.generatorConfig = typedConfig.generatorConfig || {};
		this.template = typedConfig.template || '{{content}}';

		// Get the generator function
		const generatorFunction = DynamicPromptProvider.generators.get(this.generatorName);

		if (!generatorFunction) {
			throw new Error(`Generator function '${this.generatorName}' not found`);
		}

		this.generatorFunction = generatorFunction;
	}

	public async generateContent(context: ProviderContext): Promise<string> {
		this.ensureInitialized();

		if (!this.canGenerate() || !this.generatorFunction) {
			return '';
		}

		// If cached content is set, return it
		if (this.cachedContent !== null) {
			return this.cachedContent;
		}
		try {
			// Generate dynamic content
			const dynamicContent = await this.generatorFunction(context, this.generatorConfig);

			// Apply template if provided
			const result = this.template.replace('{{content}}', dynamicContent);

			// Optionally cache here (but for now, only set via setCachedContent)
			return result;
		} catch (error) {
			throw new Error(
				`Failed to generate dynamic content: ${error instanceof Error ? error.message : 'Unknown error'}`
			);
		}
	}

	/**
	 * Set the cached content for this provider
	 */
	public setCachedContent(content: string) {
		this.cachedContent = content;
	}

	/**
	 * Get the cached content for this provider
	 */
	public getCachedContent(): string | null {
		return this.cachedContent;
	}

	/**
	 * Clear the cached content (for cache invalidation)
	 */
	public clearCachedContent() {
		this.cachedContent = null;
	}

	public override async destroy(): Promise<void> {
		await super.destroy();
		this.generatorName = '';
		this.generatorConfig = {};
		this.template = '';
		this.generatorFunction = undefined;
		this.cachedContent = null;
	}
}

/**
 * File-based Prompt Provider
 *
 * Provides content loaded from external files.
 * Useful for large prompt templates, external instructions, or version-controlled prompts.
 */

import { promises as fs } from 'fs';
import path from 'path';
import { ProviderType, ProviderContext } from '../interfaces.js';
import { BasePromptProvider } from './base-provider.js';

export interface FileProviderConfig {
	/** Path to the file to load (relative or absolute) */
	filePath: string;
	/** Base directory for relative paths */
	baseDir?: string;
	/** Whether to watch file for changes and reload */
	watchForChanges?: boolean;
	/** Encoding for file reading */
	encoding?: string;
	/** Template variables to replace in file content */
	variables?: Record<string, string>;
	/** Whether to summarize the file content using an LLM */
	summarize?: boolean;
}

export class FilePromptProvider extends BasePromptProvider {
	private filePath: string = '';
	private baseDir: string = '';
	private watchForChanges: boolean = false;
	private encoding: string = 'utf8';
	private variables: Record<string, string> = {};
	private cachedContent: string = '';
	private lastModified: Date = new Date(0);

	constructor(id: string, name: string, priority: number, enabled: boolean = true) {
		super(id, name, ProviderType.FILE_BASED, priority, enabled);
	}

	public override validateConfig(config: Record<string, any>): boolean {
		if (!super.validateConfig(config)) {
			return false;
		}

		const typedConfig = config as FileProviderConfig;

		// File path is required and must be a string
		if (typeof typedConfig.filePath !== 'string' || !typedConfig.filePath.trim()) {
			return false;
		}

		// Base directory is optional but must be a string if provided
		if (typedConfig.baseDir !== undefined) {
			if (typeof typedConfig.baseDir !== 'string') {
				return false;
			}
		}

		// Watch for changes is optional but must be a boolean if provided
		if (typedConfig.watchForChanges !== undefined) {
			if (typeof typedConfig.watchForChanges !== 'boolean') {
				return false;
			}
		}

		// Encoding is optional but must be a valid encoding if provided
		if (typedConfig.encoding !== undefined) {
			if (typeof typedConfig.encoding !== 'string') {
				return false;
			}
		}

		// Variables are optional but must be a record if provided
		if (typedConfig.variables !== undefined) {
			if (typeof typedConfig.variables !== 'object' || typedConfig.variables === null) {
				return false;
			}

			// Check that all variable values are strings
			for (const [key, value] of Object.entries(typedConfig.variables)) {
				if (typeof key !== 'string' || typeof value !== 'string') {
					return false;
				}
			}
		}

		// Summarize is optional but must be a boolean if provided
		if (typedConfig.summarize !== undefined) {
			if (typeof typedConfig.summarize !== 'boolean') {
				return false;
			}
		}

		return true;
	}

	public override async initialize(config: Record<string, any>): Promise<void> {
		await super.initialize(config);

		const typedConfig = config as FileProviderConfig;
		this.filePath = typedConfig.filePath;
		this.baseDir = typedConfig.baseDir || process.cwd();
		this.watchForChanges = typedConfig.watchForChanges || false;
		this.encoding = typedConfig.encoding || 'utf8';
		this.variables = typedConfig.variables || {};

		// Load initial content
		await this.loadFileContent();
	}

	public async generateContent(context: ProviderContext): Promise<string> {
		this.ensureInitialized();

		if (!this.canGenerate()) {
			return '';
		}

		// Reload content if watching for changes
		if (this.watchForChanges) {
			await this.checkAndReloadFile();
		}

		// Replace template variables if any exist
		let result = this.cachedContent;
		for (const [key, value] of Object.entries(this.variables)) {
			const placeholder = `{{${key}}}`;
			result = result.replace(new RegExp(placeholder, 'g'), value);
		}

		// Summarization support
		const summarize =
			(this as any).config?.summarize === true || (context as any)?.summarize === true;
		if (summarize) {
			// Use LLM service from context
			const llmService = context?.metadata?.llmService;
			if (!llmService) {
				return '[LLM service unavailable: cannot summarize file]';
			}
			// Cache summary for this file content
			if ((this as any)._cachedSummary && (this as any)._cachedSummarySource === result) {
				return (this as any)._cachedSummary;
			}
			const prompt = `Summarize the following project document for the system prompt. Focus on key guidelines, rules, and standards. Keep the summary concise, maximum 4-5 sentences.\n\n${result}\n\nSummary:`;
			const summary = await llmService.directGenerate(prompt);
			(this as any)._cachedSummary = summary;
			(this as any)._cachedSummarySource = result;
			return summary;
		}

		return result;
	}

	public override async destroy(): Promise<void> {
		await super.destroy();
		this.filePath = '';
		this.baseDir = '';
		this.watchForChanges = false;
		this.encoding = 'utf8';
		this.variables = {};
		this.cachedContent = '';
		this.lastModified = new Date(0);
	}

	/**
	 * Get the full file path (resolves relative paths)
	 */
	private getFullPath(): string {
		if (path.isAbsolute(this.filePath)) {
			return this.filePath;
		}
		return path.resolve(this.baseDir, this.filePath);
	}

	/**
	 * Load file content and cache it
	 */
	private async loadFileContent(): Promise<void> {
		try {
			const fullPath = this.getFullPath();

			// Check if file exists
			const stats = await fs.stat(fullPath);
			this.lastModified = stats.mtime;

			// Read file content
			this.cachedContent = await fs.readFile(fullPath, 'utf8');
		} catch (error) {
			throw new Error(
				`Failed to load file ${this.filePath}: ${error instanceof Error ? error.message : 'Unknown error'}`
			);
		}
	}

	/**
	 * Check if file has been modified and reload if necessary
	 */
	private async checkAndReloadFile(): Promise<void> {
		try {
			const fullPath = this.getFullPath();
			const stats = await fs.stat(fullPath);

			// If file has been modified, reload it
			if (stats.mtime > this.lastModified) {
				await this.loadFileContent();
			}
		} catch (error) {
			// File might have been deleted or become inaccessible
			// Keep using cached content and log the error
			console.warn(
				`Failed to check file ${this.filePath}: ${error instanceof Error ? error.message : 'Unknown error'}`
			);
		}
	}
}

/**
 * Provider exports
 *
 * Central export file for all prompt provider implementations.
 */

export { BasePromptProvider } from './base-provider.js';
export { StaticPromptProvider, type StaticProviderConfig } from './static-provider.js';
export {
	DynamicPromptProvider,
	type DynamicProviderConfig,
	type DynamicContentGenerator,
} from './dynamic-provider.js';
export { FilePromptProvider, type FileProviderConfig } from './file-provider.js';

/**
 * Static Prompt Provider
 *
 * Provides static content that doesn't change based on runtime context.
 * Useful for fixed instructions, disclaimers, or constant prompt segments.
 */

import { ProviderType, ProviderContext } from '../interfaces.js';
import { BasePromptProvider } from './base-provider.js';

export interface StaticProviderConfig {
	/** The static content to provide */
	content: string;
	/** Optional template variables to replace in content */
	variables?: Record<string, string>;
}

export class StaticPromptProvider extends BasePromptProvider {
	private content: string = '';
	private variables: Record<string, string> = {};

	constructor(id: string, name: string, priority: number, enabled: boolean = true) {
		super(id, name, ProviderType.STATIC, priority, enabled);
	}

	public override validateConfig(config: Record<string, any>): boolean {
		if (!super.validateConfig(config)) {
			return false;
		}

		const typedConfig = config as StaticProviderConfig;

		// Content is required and must be a string
		if (typeof typedConfig.content !== 'string') {
			return false;
		}

		// Variables are optional but must be a record if provided
		if (typedConfig.variables !== undefined) {
			if (typeof typedConfig.variables !== 'object' || typedConfig.variables === null) {
				return false;
			}

			// Check that all variable values are strings
			for (const [key, value] of Object.entries(typedConfig.variables)) {
				if (typeof key !== 'string' || typeof value !== 'string') {
					return false;
				}
			}
		}

		return true;
	}

	public override async initialize(config: Record<string, any>): Promise<void> {
		await super.initialize(config);

		const typedConfig = config as StaticProviderConfig;
		this.content = typedConfig.content;
		this.variables = typedConfig.variables || {};
	}

	public async generateContent(_context: ProviderContext): Promise<string> {
		this.ensureInitialized();

		if (!this.canGenerate()) {
			return '';
		}

		// Replace template variables if any exist
		let result = this.content;

		for (const [key, value] of Object.entries(this.variables)) {
			const placeholder = `{{${key}}}`;
			result = result.replace(new RegExp(placeholder, 'g'), value);
		}

		return result;
	}

	public override async destroy(): Promise<void> {
		await super.destroy();
		this.content = '';
		this.variables = {};
	}
}

/**
 * Provider Registry
 *
 * Central registry for managing prompt provider generator functions.
 * Handles registration, creation, and type management for all provider types.
 */

import {
	ProviderRegistry,
	ProviderConfig,
	PromptProvider,
	ProviderGenerator,
	ProviderType,
} from './interfaces.js';
import { StaticPromptProvider } from './providers/static-provider.js';
import { DynamicPromptProvider } from './providers/dynamic-provider.js';
import { FilePromptProvider } from './providers/file-provider.js';

export class DefaultProviderRegistry implements ProviderRegistry {
	private generators: Map<string, ProviderGenerator> = new Map();

	constructor() {
		// Register built-in provider types
		this.registerBuiltInProviders();
	}

	/**
	 * Register a provider generator function
	 */
	public register(type: string, generator: ProviderGenerator): void {
		if (!type || typeof type !== 'string') {
			throw new Error('Provider type must be a non-empty string');
		}

		if (typeof generator !== 'function') {
			throw new Error('Generator must be a function');
		}

		this.generators.set(type, generator);
	}

	/**
	 * Create a provider instance
	 */
	public async create(config: ProviderConfig): Promise<PromptProvider> {
		if (!this.isRegistered(config.type)) {
			throw new Error(`Provider type '${config.type}' is not registered`);
		}

		const generator = this.generators.get(config.type)!;

		try {
			const provider = await generator(config);
			return provider;
		} catch (error) {
			throw new Error(
				`Failed to create provider '${config.name}': ${error instanceof Error ? error.message : 'Unknown error'}`
			);
		}
	}

	/**
	 * Get all registered provider types
	 */
	public getRegisteredTypes(): string[] {
		return Array.from(this.generators.keys());
	}

	/**
	 * Check if a provider type is registered
	 */
	public isRegistered(type: string): boolean {
		return this.generators.has(type);
	}

	/**
	 * Unregister a provider type
	 */
	public unregister(type: string): boolean {
		return this.generators.delete(type);
	}

	/**
	 * Clear all registered providers
	 */
	public clear(): void {
		this.generators.clear();
	}

	/**
	 * Register built-in provider types
	 */
	private registerBuiltInProviders(): void {
		// Static provider generator
		this.register(ProviderType.STATIC, async (config: ProviderConfig) => {
			const provider = new StaticPromptProvider(
				config.name,
				config.name,
				config.priority,
				config.enabled
			);

			if (config.config) {
				await provider.initialize(config.config);
			}

			return provider;
		});

		// Dynamic provider generator
		this.register(ProviderType.DYNAMIC, async (config: ProviderConfig) => {
			const provider = new DynamicPromptProvider(
				config.name,
				config.name,
				config.priority,
				config.enabled
			);

			if (config.config) {
				await provider.initialize(config.config);
			}

			return provider;
		});

		// File-based provider generator
		this.register(ProviderType.FILE_BASED, async (config: ProviderConfig) => {
			const provider = new FilePromptProvider(
				config.name,
				config.name,
				config.priority,
				config.enabled
			);

			if (config.config) {
				await provider.initialize(config.config);
			}

			return provider;
		});
	}
}

// Export a singleton instance for global use
export const providerRegistry = new DefaultProviderRegistry();

