import { describe, it, expect, vi, beforeEach } from 'vitest';
import { addNodeTool } from '../add-node.js';

const mockGraph = {
	addNode: vi.fn().mockResolvedValue(undefined),
	getNode: vi.fn().mockResolvedValue(null), // By default, node doesn't exist
};

const getContext = (opts: { withManager?: boolean; withGraph?: boolean } = {}) => {
	const kgManager = opts.withManager
		? { getGraph: vi.fn().mockReturnValue(opts.withGraph ? mockGraph : null) }
		: undefined;
	return {
		toolName: 'add_node',
		startTime: Date.now(),
		sessionId: 'test-session',
		metadata: {},
		services: {
			knowledgeGraphManager: kgManager as any,
		},
	};
};

describe('addNodeTool', () => {
	beforeEach(() => {
		vi.clearAllMocks();
		// Reset mocks to default states
		mockGraph.getNode.mockResolvedValue(null); // Node doesn't exist by default
		mockGraph.addNode.mockResolvedValue(undefined);
	});

	it('should add a node successfully', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await addNodeTool.handler(
			{
				id: 'node1',
				labels: ['Function', 'Code'],
				properties: { name: 'testFunction', language: 'typescript' },
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.nodeId).toBe('node1');
		expect(result.message).toContain("Node 'node1' added to knowledge graph");

		// Verify node existence was checked
		expect(mockGraph.getNode).toHaveBeenCalledWith('node1');

		// Verify node was added with correct parameters
		expect(mockGraph.addNode).toHaveBeenCalledWith({
			id: 'node1',
			labels: ['Function', 'Code'],
			properties: { name: 'testFunction', language: 'typescript' },
		});
	});

	it('should add a node without properties', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await addNodeTool.handler({ id: 'node2', labels: ['Class'] }, context);

		expect(result.success).toBe(true);
		expect(mockGraph.addNode).toHaveBeenCalledWith({
			id: 'node2',
			labels: ['Class'],
			properties: {},
		});
	});

	it('should fail if id is missing or empty', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await addNodeTool.handler({ id: '', labels: ['Test'], properties: {} }, context);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Node ID must be a non-empty string');
	});

	it('should fail if labels are missing', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await addNodeTool.handler({ id: 'node3', labels: [], properties: {} }, context);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Node must have at least one label');
	});

	it('should fail if labels contain empty strings', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await addNodeTool.handler(
			{ id: 'node4', labels: ['ValidLabel', '', 'AnotherLabel'], properties: {} },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('All labels must be non-empty strings');
	});

	it('should fail if node already exists', async () => {
		// Mock getNode to return an existing node
		mockGraph.getNode.mockResolvedValue({
			id: 'existing-node',
			labels: ['ExistingClass'],
			properties: { name: 'existing' },
		});

		const context = getContext({ withManager: true, withGraph: true });
		const result = await addNodeTool.handler(
			{ id: 'existing-node', labels: ['NewClass'], properties: {} },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain("Node 'existing-node' already exists in the knowledge graph");
		expect(result.nodeId).toBe('existing-node');

		// Verify addNode was not called
		expect(mockGraph.addNode).not.toHaveBeenCalled();
	});

	it('should fail if knowledgeGraphManager is missing', async () => {
		const context = getContext({ withManager: false });
		const result = await addNodeTool.handler(
			{ id: 'node5', labels: ['Test'], properties: {} },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('KnowledgeGraphManager not available in context.services');
	});

	it('should fail if backend is not connected', async () => {
		const context = getContext({ withManager: true, withGraph: false });
		const result = await addNodeTool.handler(
			{ id: 'node6', labels: ['Test'], properties: {} },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Knowledge graph backend is not connected');
	});

	it('should handle backend error during node existence check', async () => {
		const errorGraph = {
			getNode: vi.fn().mockRejectedValue(new Error('Database connection failed')),
			addNode: vi.fn().mockResolvedValue(undefined),
		};
		const context = {
			toolName: 'add_node',
			startTime: Date.now(),
			sessionId: 'test-session',
			metadata: {},
			services: { knowledgeGraphManager: { getGraph: vi.fn().mockReturnValue(errorGraph) } as any },
		};

		const result = await addNodeTool.handler(
			{ id: 'node7', labels: ['Test'], properties: {} },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Database connection failed');
	});

	it('should handle backend error during node creation', async () => {
		const errorGraph = {
			getNode: vi.fn().mockResolvedValue(null),
			addNode: vi.fn().mockRejectedValue(new Error('Node creation failed')),
		};
		const context = {
			toolName: 'add_node',
			startTime: Date.now(),
			sessionId: 'test-session',
			metadata: {},
			services: { knowledgeGraphManager: { getGraph: vi.fn().mockReturnValue(errorGraph) } as any },
		};

		const result = await addNodeTool.handler(
			{ id: 'node8', labels: ['Test'], properties: {} },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Node creation failed');
	});

	it('should trim whitespace from id and labels', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await addNodeTool.handler(
			{
				id: '  node9  ',
				labels: ['  Function  ', '  Code  '],
				properties: { name: 'test' },
			},
			context
		);

		expect(result.success).toBe(true);

		// Verify trimmed values were used
		expect(mockGraph.getNode).toHaveBeenCalledWith('node9');
		expect(mockGraph.addNode).toHaveBeenCalledWith({
			id: 'node9',
			labels: ['Function', 'Code'],
			properties: { name: 'test' },
		});
	});
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { deleteNodeTool } from '../delete-node.js';

const mockExistingNode = {
	id: 'existing-node',
	labels: ['TestClass'],
	properties: { name: 'test' },
};

const mockGraph = {
	deleteNode: vi.fn().mockResolvedValue(undefined),
	getNode: vi.fn().mockResolvedValue(mockExistingNode), // By default, node exists
};

const getContext = (opts: { withManager?: boolean; withGraph?: boolean } = {}) => {
	const kgManager = opts.withManager
		? { getGraph: vi.fn().mockReturnValue(opts.withGraph ? mockGraph : null) }
		: undefined;
	return {
		toolName: 'delete_node',
		startTime: Date.now(),
		sessionId: 'test-session',
		metadata: {},
		services: {
			knowledgeGraphManager: kgManager as any,
		},
	} as any;
};

describe('deleteNodeTool', () => {
	beforeEach(() => {
		vi.clearAllMocks();
		// Reset mocks to default states
		mockGraph.getNode.mockResolvedValue(mockExistingNode); // Node exists by default
		mockGraph.deleteNode.mockResolvedValue(undefined);
	});

	it('should delete an existing node successfully', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await deleteNodeTool.handler({ id: 'existing-node' }, context);

		expect(result.success).toBe(true);
		expect(result.nodeId).toBe('existing-node');
		expect(result.message).toContain('Node deleted from knowledge graph');

		// Verify node existence was checked
		expect(mockGraph.getNode).toHaveBeenCalledWith('existing-node');

		// Verify node was deleted
		expect(mockGraph.deleteNode).toHaveBeenCalledWith('existing-node');
	});

	it('should succeed when trying to delete non-existent node (idempotent)', async () => {
		// Mock getNode to return null (node doesn't exist)
		mockGraph.getNode.mockResolvedValue(null);

		const context = getContext({ withManager: true, withGraph: true });
		const result = await deleteNodeTool.handler({ id: 'nonexistent-node' }, context);

		expect(result.success).toBe(true);
		expect(result.nodeId).toBe('nonexistent-node');
		expect(result.message).toContain(
			"Node 'nonexistent-node' does not exist (already deleted or never existed)"
		);

		// Verify node existence was checked
		expect(mockGraph.getNode).toHaveBeenCalledWith('nonexistent-node');

		// Verify deleteNode was not called since node doesn't exist
		expect(mockGraph.deleteNode).not.toHaveBeenCalled();
	});

	it('should fail if id is missing or empty', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await deleteNodeTool.handler({ id: '' }, context);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Node ID must be a non-empty string');
	});

	it('should fail if knowledgeGraphManager is missing', async () => {
		const context = getContext({ withManager: false });
		const result = await deleteNodeTool.handler({ id: 'node1' }, context);

		expect(result.success).toBe(false);
		expect(result.message).toContain('KnowledgeGraphManager not available in context.services');
		expect(result.nodeId).toBe('node1');
	});

	it('should fail if backend is not connected', async () => {
		const context = getContext({ withManager: true, withGraph: false });
		const result = await deleteNodeTool.handler({ id: 'node2' }, context);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Knowledge graph backend is not connected');
		expect(result.nodeId).toBe('node2');
	});

	it('should handle backend error during node existence check', async () => {
		const errorGraph = {
			getNode: vi.fn().mockRejectedValue(new Error('Database connection failed')),
			deleteNode: vi.fn().mockResolvedValue(undefined),
		};
		const context = {
			toolName: 'delete_node',
			startTime: Date.now(),
			sessionId: 'test-session',
			metadata: {},
			services: { knowledgeGraphManager: { getGraph: vi.fn().mockReturnValue(errorGraph) } as any },
		};

		const result = await deleteNodeTool.handler({ id: 'node3' }, context);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Database connection failed');
	});

	it('should handle backend error during deletion', async () => {
		const errorGraph = {
			getNode: vi.fn().mockResolvedValue(mockExistingNode),
			deleteNode: vi.fn().mockRejectedValue(new Error('Deletion failed')),
		};
		const context = {
			toolName: 'delete_node',
			startTime: Date.now(),
			sessionId: 'test-session',
			metadata: {},
			services: { knowledgeGraphManager: { getGraph: vi.fn().mockReturnValue(errorGraph) } as any },
		};

		const result = await deleteNodeTool.handler({ id: 'node4' }, context);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Deletion failed');
	});

	it('should trim whitespace from node id', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await deleteNodeTool.handler({ id: '  existing-node  ' }, context);

		expect(result.success).toBe(true);

		// Verify trimmed value was used
		expect(mockGraph.getNode).toHaveBeenCalledWith('existing-node');
		expect(mockGraph.deleteNode).toHaveBeenCalledWith('existing-node');
	});
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { extractEntitiesTool } from '../extract-entities.js';

const mockGraph = {
	addNode: vi.fn().mockResolvedValue(undefined),
	addEdge: vi.fn().mockResolvedValue(undefined),
};

const mockLLMService: any = {
	generate: vi.fn().mockResolvedValue('[]'), // Empty JSON array by default
	directGenerate: vi.fn().mockResolvedValue('[]'),
	getAllTools: vi.fn().mockReturnValue([]),
	getConfig: vi.fn().mockReturnValue({}),
};

const getContext = (
	opts: { withManager?: boolean; withGraph?: boolean; withLLM?: boolean } = {}
) => {
	const kgManager = opts.withManager
		? { getGraph: vi.fn().mockReturnValue(opts.withGraph ? mockGraph : null) }
		: undefined;

	const llmService = opts.withLLM ? mockLLMService : undefined;

	return {
		toolName: 'extract_entities',
		startTime: Date.now(),
		sessionId: 'test-session',
		metadata: {},
		services: {
			...(kgManager ? { knowledgeGraphManager: kgManager } : {}),
			...(llmService ? { llmService } : {}),
		},
	} as any;
};

describe('extractEntitiesTool', () => {
	beforeEach(() => {
		vi.clearAllMocks();
		// Reset LLM mock to return empty array by default
		mockLLMService.generate.mockResolvedValue('[]');
	});

	it('should extract entities successfully with LLM', async () => {
		// Mock LLM response with entities
		mockLLMService.generate.mockResolvedValue(
			JSON.stringify([
				{
					name: 'TestFunction',
					type: 'Function',
					confidence: 0.9,
					context: 'function TestFunction()',
					description: 'A test function',
				},
			])
		);

		const context = getContext({ withManager: true, withGraph: true, withLLM: true });
		const result = await extractEntitiesTool.handler(
			{
				text: 'function TestFunction() { return true; }',
				options: {
					entityTypes: ['Function'],
					autoLink: true,
				},
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toContain('Entity extraction completed successfully');
		expect(result.entities).toBeDefined();
		expect(result.extracted).toBeGreaterThan(0);
		expect(mockGraph.addNode).toHaveBeenCalled();
		expect(mockLLMService.generate).toHaveBeenCalled();
	});

	it('should fall back to regex patterns when LLM fails', async () => {
		// Mock LLM to throw error
		mockLLMService.generate.mockRejectedValue(new Error('LLM service unavailable'));

		const context = getContext({ withManager: true, withGraph: true, withLLM: true });
		const result = await extractEntitiesTool.handler(
			{
				text: 'function TestFunction() { return true; }',
				options: {
					entityTypes: ['Function'],
					autoLink: false,
				},
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toContain('Entity extraction completed successfully');
		expect(result.entities).toBeDefined();
		expect(mockGraph.addNode).toHaveBeenCalled();
	});

	it('should work with legacy parameters', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await extractEntitiesTool.handler(
			{
				text: 'class TestClass {}',
				entityTypes: ['Class'],
				autoLink: true,
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toContain('Entity extraction completed successfully');
		expect(result.entities).toBeDefined();
	});

	it('should fail if text is missing', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await extractEntitiesTool.handler(
			{
				text: '',
				options: {
					entityTypes: ['Organization'],
					autoLink: true,
				},
			},
			context
		);

		expect(result.success).toBe(false);
		expect(result.error).toContain('Text is required and must be a non-empty string');
	});

	it('should work without knowledge graph manager', async () => {
		const context = getContext({ withManager: false });
		const result = await extractEntitiesTool.handler(
			{
				text: 'Sample text with entities',
				options: {
					entityTypes: ['Organization'],
					autoLink: true,
				},
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toContain('Entity extraction completed successfully');
		expect(result.extracted).toBe(0); // No graph to add to
	});

	it('should work without connected graph backend', async () => {
		const context = getContext({ withManager: true, withGraph: false });
		const result = await extractEntitiesTool.handler(
			{
				text: 'Sample text with entities',
				options: {
					entityTypes: ['Organization'],
					autoLink: true,
				},
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toContain('Entity extraction completed successfully');
		expect(result.extracted).toBe(0); // No graph to add to
	});

	it('should handle malformed LLM JSON response gracefully', async () => {
		// Mock LLM to return invalid JSON
		mockLLMService.generate.mockResolvedValue('invalid json response');

		const context = getContext({ withManager: true, withGraph: true, withLLM: true });
		const result = await extractEntitiesTool.handler(
			{
				text: 'function TestFunction() { return true; }',
				options: {
					entityTypes: ['Function'],
					autoLink: false,
				},
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toContain('Entity extraction completed successfully');
		// Should fall back to regex patterns
		expect(mockGraph.addNode).toHaveBeenCalled();
	});

	it('should create relationships when autoLink is enabled', async () => {
		// Mock LLM responses for both entities and relationships
		mockLLMService.generate
			.mockResolvedValueOnce(
				JSON.stringify([
					{
						name: 'TestFunction',
						type: 'Function',
						confidence: 0.9,
						context: 'function TestFunction()',
						description: 'A test function',
					},
					{
						name: 'TestClass',
						type: 'Class',
						confidence: 0.9,
						context: 'class TestClass',
						description: 'A test class',
					},
				])
			)
			.mockResolvedValueOnce(
				JSON.stringify([
					{
						sourceEntity: 'TestFunction',
						targetEntity: 'TestClass',
						relationshipType: 'BELONGS_TO',
						confidence: 0.8,
						reasoning: 'Function belongs to class',
					},
				])
			);

		const context = getContext({ withManager: true, withGraph: true, withLLM: true });
		const result = await extractEntitiesTool.handler(
			{
				text: 'class TestClass { function TestFunction() {} }',
				options: {
					entityTypes: ['Function', 'Class'],
					autoLink: true,
					linkTypes: ['BELONGS_TO', 'USES'],
				},
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.extracted).toBe(2);
		expect(result.linked).toBe(1);
		expect(mockGraph.addNode).toHaveBeenCalledTimes(2);
		expect(mockGraph.addEdge).toHaveBeenCalledTimes(1);
	});

	it('should handle graph backend errors gracefully', async () => {
		const errorGraph = {
			addNode: vi.fn().mockRejectedValue(new Error('Backend connection failed')),
			addEdge: vi.fn().mockResolvedValue(undefined),
		};
		const context = {
			toolName: 'extract_entities',
			startTime: Date.now(),
			sessionId: 'test-session',
			metadata: {},
			services: {
				knowledgeGraphManager: { getGraph: vi.fn().mockReturnValue(errorGraph) } as any,
				llmService: mockLLMService,
			},
		} as any;

		const result = await extractEntitiesTool.handler(
			{
				text: 'function TestFunction() {}',
				options: {
					entityTypes: ['Function'],
					autoLink: false,
				},
			},
			context
		);

		// Extract entities tool continues even if backend fails - it still extracts entities from text
		expect(result.success).toBe(true);
		expect(result.extracted).toBeGreaterThan(0);
		expect(result.linked).toBe(0); // No links created when autoLink is false
		expect(result.message).toContain('Entity extraction completed successfully');
	});
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { getNeighborsTool } from '../get-neighbors.js';

const mockNeighbors = [
	{
		node: { id: 'neighbor1', labels: ['Function'], properties: { name: 'relatedFunction' } },
		edge: {
			id: 'edge1',
			type: 'DEPENDS_ON',
			startNodeId: 'n1',
			endNodeId: 'neighbor1',
			properties: {},
		},
	},
	{
		node: { id: 'neighbor2', labels: ['Class'], properties: { name: 'RelatedClass' } },
		edge: { id: 'edge2', type: 'CALLS', startNodeId: 'neighbor2', endNodeId: 'n1', properties: {} },
	},
];

const mockGraph = {
	getNeighbors: vi.fn().mockResolvedValue(mockNeighbors),
};

const getContext = (opts: { withManager?: boolean; withGraph?: boolean } = {}) => {
	const kgManager = opts.withManager
		? { getGraph: vi.fn().mockReturnValue(opts.withGraph ? mockGraph : null) }
		: undefined;
	return {
		toolName: 'get_neighbors',
