describe('getNeighborsTool', () => {
	beforeEach(() => {
		vi.clearAllMocks();
		mockGraph.getNeighbors.mockResolvedValue(mockNeighbors);
	});

	it('should get neighbors successfully with all parameters', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await getNeighborsTool.handler(
			{ nodeId: 'node1', direction: 'both', edgeTypes: ['DEPENDS_ON', 'CALLS'], limit: 10 },
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toBe('Neighbors retrieved');
		expect(result.neighbors).toEqual(mockNeighbors);
		expect(mockGraph.getNeighbors).toHaveBeenCalledWith(
			'node1',
			'both',
			['DEPENDS_ON', 'CALLS'],
			10
		);
	});

	it('should get neighbors successfully with default parameters', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await getNeighborsTool.handler({ nodeId: 'node2' }, context);

		expect(result.success).toBe(true);
		expect(result.message).toBe('Neighbors retrieved');
		expect(result.neighbors).toEqual(mockNeighbors);

		// Should use default values: direction='both', edgeTypes=undefined, limit=10
		expect(mockGraph.getNeighbors).toHaveBeenCalledWith('node2', 'both', undefined, 10);
	});

	it('should handle outgoing direction', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await getNeighborsTool.handler(
			{ nodeId: 'node3', direction: 'outgoing', edgeTypes: ['DEPENDS_ON'] },
			context
		);

		expect(result.success).toBe(true);
		expect(mockGraph.getNeighbors).toHaveBeenCalledWith('node3', 'outgoing', ['DEPENDS_ON'], 10);
	});

	it('should handle incoming direction', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await getNeighborsTool.handler(
			{ nodeId: 'node4', direction: 'incoming', limit: 25 },
			context
		);

		expect(result.success).toBe(true);
		expect(mockGraph.getNeighbors).toHaveBeenCalledWith('node4', 'incoming', undefined, 25);
	});

	it('should return empty result when no neighbors found', async () => {
		mockGraph.getNeighbors.mockResolvedValue([]);

		const context = getContext({ withManager: true, withGraph: true });
		const result = await getNeighborsTool.handler({ nodeId: 'isolated-node' }, context);

		expect(result.success).toBe(true);
		expect(result.message).toBe('Neighbors retrieved');
		expect(result.neighbors).toEqual([]);
	});

	it('should fail if nodeId is missing or empty', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await getNeighborsTool.handler(
			{ nodeId: '', direction: 'both', edgeTypes: ['REL'], limit: 5 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Node ID must be a non-empty string');
	});

	it('should fail if knowledgeGraphManager is missing', async () => {
		const context = getContext({ withManager: false });
		const result = await getNeighborsTool.handler(
			{ nodeId: 'node5', direction: 'both', edgeTypes: ['REL'], limit: 5 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('KnowledgeGraphManager not available in context.services');
	});

	it('should fail if backend is not connected', async () => {
		const context = getContext({ withManager: true, withGraph: false });
		const result = await getNeighborsTool.handler(
			{ nodeId: 'node6', direction: 'both', edgeTypes: ['REL'], limit: 5 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Knowledge graph backend is not connected');
	});

	it('should handle backend error', async () => {
		const errorGraph = {
			getNeighbors: vi.fn().mockRejectedValue(new Error('Database query failed')),
		};
		const context = {
			toolName: 'get_neighbors',
			startTime: Date.now(),
			sessionId: 'test-session',
			metadata: {},
			services: { knowledgeGraphManager: { getGraph: vi.fn().mockReturnValue(errorGraph) } as any },
		};

		const result = await getNeighborsTool.handler(
			{ nodeId: 'node7', direction: 'both', edgeTypes: ['REL'], limit: 5 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Database query failed');
		// Note: actual implementation doesn't return nodeId or neighbors in error case
	});

	it('should trim whitespace from nodeId', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await getNeighborsTool.handler(
			{ nodeId: '  node8  ', direction: 'outgoing' },
			context
		);

		expect(result.success).toBe(true);

		// Note: actual implementation doesn't trim nodeId, so it uses the untrimmed value
		expect(mockGraph.getNeighbors).toHaveBeenCalledWith('  node8  ', 'outgoing', undefined, 10);
	});

	it('should handle single edge type as string', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await getNeighborsTool.handler(
			{ nodeId: 'node9', edgeTypes: 'DEPENDS_ON' },
			context
		);

		expect(result.success).toBe(true);
		// Single string should be treated as array with one element
		expect(mockGraph.getNeighbors).toHaveBeenCalledWith('node9', 'both', 'DEPENDS_ON', 10);
	});

	it('should validate direction parameter', async () => {
		const context = getContext({ withManager: true, withGraph: true });

		// Test that invalid directions would be caught by TypeScript, but we'll test a valid one
		const result = await getNeighborsTool.handler(
			{ nodeId: 'node10', direction: 'both' as any },
			context
		);

		expect(result.success).toBe(true);
		expect(mockGraph.getNeighbors).toHaveBeenCalledWith('node10', 'both', undefined, 10);
	});
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { queryGraphTool } from '../query-graph.js';

const mockQueryResult = {
	nodes: [
		{ id: 'node1', labels: ['Function'], properties: { name: 'testFunction' } },
		{ id: 'node2', labels: ['Class'], properties: { name: 'TestClass' } },
	],
	edges: [
		{ id: 'edge1', type: 'DEPENDS_ON', startNodeId: 'node1', endNodeId: 'node2', properties: {} },
	],
	metadata: {
		totalCount: 3,
		queryType: 'cypher',
		executionTime: 45,
		parameters: {},
	},
};

const mockGraph = {
	query: vi.fn().mockResolvedValue(mockQueryResult),
};

const getContext = (opts: { withManager?: boolean; withGraph?: boolean } = {}) => {
	const kgManager = opts.withManager
		? { getGraph: vi.fn().mockReturnValue(opts.withGraph ? mockGraph : null) }
		: undefined;
	return {
		toolName: 'query_graph',
		startTime: Date.now(),
		sessionId: 'test-session',
		metadata: {},
		services: {
			knowledgeGraphManager: kgManager as any,
		},
	} as any;
};

describe('queryGraphTool', () => {
	beforeEach(() => {
		vi.clearAllMocks();
		mockGraph.query.mockResolvedValue(mockQueryResult);
	});

	it('should execute a cypher query successfully', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler(
			{
				query: 'MATCH (n:Function) RETURN n LIMIT 10',
				queryType: 'cypher',
				limit: 10,
				parameters: { functionType: 'async' },
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toBe('Query executed');
		expect(result.results).toEqual(mockQueryResult);
		expect(result.query.type).toBe('cypher');
		expect(mockGraph.query).toHaveBeenCalledWith({
			type: 'cypher',
			query: 'MATCH (n:Function) RETURN n LIMIT 10',
			parameters: { functionType: 'async' },
			limit: 10,
		});
	});

	it('should execute a node query successfully', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler(
			{
				query: 'labels: [Function], properties: {language: "typescript"}',
				queryType: 'node',
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toBe('Query executed');
		expect(result.results).toEqual(mockQueryResult);
		expect(result.query.type).toBe('node');
		expect(mockGraph.query).toHaveBeenCalledWith({
			type: 'node',
			pattern: {
				labels: ['Function'],
			},
			parameters: {},
			limit: 100,
		});
	});

	it('should execute an edge query successfully', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler(
			{
				query: 'type: DEPENDS_ON',
				queryType: 'edge',
				limit: 25,
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.query.type).toBe('edge');
		expect(mockGraph.query).toHaveBeenCalledWith({
			type: 'edge',
			pattern: {
				type: 'DEPENDS_ON',
			},
			parameters: {},
			limit: 25,
		});
	});

	it('should use default values when not provided', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler({ query: 'MATCH (n) RETURN n' }, context);

		expect(result.success).toBe(true);
		expect(result.query.type).toBe('cypher'); // Default queryType
		expect(mockGraph.query).toHaveBeenCalledWith({
			type: 'cypher',
			query: 'MATCH (n) RETURN n',
			parameters: {},
			limit: 100, // Default limit
		});
	});

	it('should handle empty query results', async () => {
		const emptyResult = {
			nodes: [],
			edges: [],
			metadata: { totalCount: 0, queryType: 'cypher', executionTime: 2 },
		};
		mockGraph.query.mockResolvedValue(emptyResult);

		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler(
			{ query: 'MATCH (n:NonExistent) RETURN n', queryType: 'cypher' },
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toBe('Query executed');
		expect(result.results.nodes).toEqual([]);
		expect(result.results.edges).toEqual([]);
	});

	it('should fail if query is missing or empty', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler(
			{ query: '', queryType: 'cypher', limit: 10 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.error).toContain('Query is required and must be a non-empty string');
	});

	it('should fail if limit is out of range (too low)', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler(
			{ query: 'MATCH (n) RETURN n', queryType: 'cypher', limit: 0 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Limit must be between 1 and 1000');
	});

	it('should fail if limit is out of range (too high)', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler(
			{ query: 'MATCH (n) RETURN n', queryType: 'cypher', limit: 10001 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Limit must be between 1 and 1000');
	});

	it('should fail if knowledgeGraphManager is missing', async () => {
		const context = getContext({ withManager: false });
		const result = await queryGraphTool.handler(
			{ query: 'MATCH (n) RETURN n', queryType: 'cypher', limit: 10 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('KnowledgeGraphManager not available in context.services');
	});

	it('should fail if backend is not connected', async () => {
		const context = getContext({ withManager: true, withGraph: false });
		const result = await queryGraphTool.handler(
			{ query: 'MATCH (n) RETURN n', queryType: 'cypher', limit: 10 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Knowledge graph backend is not connected');
	});

	it('should handle backend error', async () => {
		const errorGraph = {
			query: vi.fn().mockRejectedValue(new Error('Cypher syntax error')),
		};
		const context = {
			toolName: 'query_graph',
			startTime: Date.now(),
			sessionId: 'test-session',
			metadata: {},
			services: { knowledgeGraphManager: { getGraph: vi.fn().mockReturnValue(errorGraph) } as any },
		};

		const result = await queryGraphTool.handler(
			{ query: 'INVALID CYPHER QUERY', queryType: 'cypher', limit: 10 },
			context
		);

		expect(result.success).toBe(false);
		expect(result.error).toContain('Cypher syntax error');
	});

	it('should handle complex cypher query with parameters', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const complexQuery = `
			MATCH (f:Function)-[r:DEPENDS_ON]->(c:Class)
			WHERE f.language = $lang AND r.strength > $minStrength
			RETURN f, r, c
			ORDER BY r.strength DESC
		`;
		const parameters = { lang: 'typescript', minStrength: 0.5 };

		const result = await queryGraphTool.handler(
			{
				query: complexQuery,
				queryType: 'cypher',
				parameters,
				limit: 50,
			},
			context
		);

		expect(result.success).toBe(true);
		expect(mockGraph.query).toHaveBeenCalledWith({
			type: 'cypher',
			query: complexQuery.trim(),
			parameters,
			limit: 50,
		});
	});

	it('should trim whitespace from query string', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler(
			{ query: '  MATCH (n) RETURN n  ', queryType: 'cypher' },
			context
		);

		expect(result.success).toBe(true);
		// Verify trimmed value was used
		expect(mockGraph.query).toHaveBeenCalledWith({
			type: 'cypher',
			query: 'MATCH (n) RETURN n',
			parameters: {},
			limit: 100,
		});
	});

	it('should handle structured query parameters for node search', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await queryGraphTool.handler(
			{
				query: 'properties: {name: "testFunction"}',
				queryType: 'node',
				parameters: { labels: ['Function'] },
			},
			context
		);

		expect(result.success).toBe(true);
		expect(mockGraph.query).toHaveBeenCalledWith({
			type: 'node',
			pattern: {},
			parameters: { labels: ['Function'] },
			limit: 100,
		});
	});
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { searchGraphTool } from '../search-graph.js';

const mockNodes = [
	{ id: 'node1', labels: ['Function'], properties: { name: 'testFunction' } },
	{ id: 'node2', labels: ['Class'], properties: { name: 'TestClass' } },
];

const mockEdges = [
	{
		id: 'edge1',
		type: 'DEPENDS_ON',
		startNodeId: 'node1',
		endNodeId: 'node2',
		properties: { strength: 0.8 },
	},
];

const mockGraph = {
	findNodes: vi.fn().mockResolvedValue(mockNodes),
	findEdges: vi.fn().mockResolvedValue(mockEdges),
};

const getContext = (opts: { withManager?: boolean; withGraph?: boolean } = {}) => {
	const kgManager = opts.withManager
		? { getGraph: vi.fn().mockReturnValue(opts.withGraph ? mockGraph : null) }
		: undefined;
	return {
		toolName: 'search_graph',
		startTime: Date.now(),
		sessionId: 'test-session',
		metadata: {},
		services: {
			knowledgeGraphManager: kgManager as any,
		},
	} as any;
};

describe('searchGraphTool', () => {
	beforeEach(() => {
		vi.clearAllMocks();
		mockGraph.findNodes.mockResolvedValue(mockNodes);
		mockGraph.findEdges.mockResolvedValue(mockEdges);
	});

	it('should search both nodes and edges successfully', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler(
			{
				searchType: 'both',
				nodeLabels: ['Function'],
				edgeTypes: ['DEPENDS_ON'],
				properties: { name: 'test' },
				limit: 10,
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.message).toContain('Search completed - found 2 nodes and 1 edges');
		expect(result.results.nodes).toEqual(mockNodes);
		expect(result.results.edges).toEqual(mockEdges);
		expect(result.results.totalCount).toBe(3);
		expect(result.results.searchMetadata).toBeDefined();
		expect(result.results.searchMetadata.appliedFilters.nodeLabels).toEqual(['Function']);
		expect(result.results.searchMetadata.appliedFilters.edgeTypes).toEqual(['DEPENDS_ON']);

		expect(mockGraph.findNodes).toHaveBeenCalledWith({ name: 'test' }, ['Function'], 10);
		expect(mockGraph.findEdges).toHaveBeenCalledWith({ name: 'test' }, 'DEPENDS_ON', 10);
	});

	it('should search only nodes successfully', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler(
			{
				searchType: 'nodes',
				nodeLabels: ['Function', 'Class'],
				properties: { language: 'typescript' },
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.results.nodes).toEqual(mockNodes);
		expect(result.results.edges).toEqual([]);
		expect(result.results.searchMetadata.searchType).toBe('nodes');

		expect(mockGraph.findNodes).toHaveBeenCalledWith(
			{ language: 'typescript' },
			['Function', 'Class'],
			50
		);
		expect(mockGraph.findEdges).not.toHaveBeenCalled();
	});

	it('should search only edges successfully', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler(
			{
				searchType: 'edges',
				edgeTypes: ['DEPENDS_ON', 'CALLS'],
				properties: { strength: { gte: 0.5 } },
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.results.nodes).toEqual([]);
		// When searching multiple edge types, results are flattened and may contain duplicates
		expect(result.results.edges).toEqual([mockEdges[0], mockEdges[0]]); // Duplicated because searched twice
		expect(result.results.searchMetadata.searchType).toBe('edges');

		expect(mockGraph.findNodes).not.toHaveBeenCalled();
		expect(mockGraph.findEdges).toHaveBeenCalled();
	});

	it('should support legacy labels parameter for nodes', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler(
			{
				searchType: 'nodes',
				labels: ['Function', 'Class'], // Legacy parameter
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.results.searchMetadata.appliedFilters.nodeLabels).toEqual(['Function', 'Class']);
		expect(result.results.searchMetadata.appliedFilters.legacyLabels).toEqual([
			'Function',
			'Class',
		]);

		expect(mockGraph.findNodes).toHaveBeenCalledWith(undefined, ['Function', 'Class'], 50);
	});

	it('should support legacy labels parameter for edges', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler(
			{
				searchType: 'edges',
				labels: ['DEPENDS_ON'], // Legacy parameter
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.results.searchMetadata.appliedFilters.edgeTypes).toEqual(['DEPENDS_ON']);
		expect(result.results.searchMetadata.appliedFilters.legacyLabels).toEqual(['DEPENDS_ON']);

		expect(mockGraph.findEdges).toHaveBeenCalled();
	});

	it('should handle text search for nodes', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler(
			{
				searchType: 'nodes',
				textSearch: 'testFunction',
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.results.searchMetadata.appliedFilters.textSearch).toBe('testFunction');

		// Text search should be converted to name filter for nodes
		expect(mockGraph.findNodes).toHaveBeenCalledWith({ name: 'testFunction' }, undefined, 50);
	});

	it('should handle text search for edges', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler(
			{
				searchType: 'edges',
				textSearch: 'dependency',
			},
			context
		);

		expect(result.success).toBe(true);

		// Text search should be converted to description filter for edges
		expect(mockGraph.findEdges).toHaveBeenCalledWith({ description: 'dependency' }, undefined, 50);
	});

	it('should use default searchType and limit', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler({}, context);

		expect(result.success).toBe(true);
		expect(result.results.searchMetadata.searchType).toBe('both');
		expect(result.results.searchMetadata.limit).toBe(50);
	});

	it('should fail if limit is out of range (too low)', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler({ searchType: 'nodes', limit: 0 }, context);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Limit must be between 1 and 1000');
	});

	it('should fail if limit is out of range (too high)', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler({ searchType: 'nodes', limit: 1001 }, context);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Limit must be between 1 and 1000');
	});

	it('should fail if knowledgeGraphManager is missing', async () => {
		const context = getContext({ withManager: false });
		const result = await searchGraphTool.handler(
			{ searchType: 'nodes', nodeLabels: ['Test'] },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('KnowledgeGraphManager not available in context.services');
		expect(result.results).toBeNull();
	});

	it('should fail if backend is not connected', async () => {
		const context = getContext({ withManager: true, withGraph: false });
		const result = await searchGraphTool.handler(
			{ searchType: 'edges', edgeTypes: ['Test'] },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Knowledge graph backend is not connected');
		expect(result.results).toBeNull();
	});

	it('should handle backend error during search', async () => {
		const errorGraph = {
			findNodes: vi.fn().mockRejectedValue(new Error('Search operation failed')),
			findEdges: vi.fn().mockRejectedValue(new Error('Search operation failed')),
		};
		const context = {
			toolName: 'search_graph',
			startTime: Date.now(),
			sessionId: 'test-session',
			metadata: {},
			services: { knowledgeGraphManager: { getGraph: vi.fn().mockReturnValue(errorGraph) } as any },
		};

		const result = await searchGraphTool.handler(
			{ searchType: 'nodes', nodeLabels: ['Test'] },
			context
		);

		expect(result.success).toBe(false);
		expect(result.message).toContain('Search operation failed');
		expect(result.results.nodes).toEqual([]);
		expect(result.results.edges).toEqual([]);
		expect(result.results.totalCount).toBe(0);
	});

	it('should handle multiple edge types search', async () => {
		// Mock different results for different edge types
		mockGraph.findEdges.mockImplementation((filters, edgeType) => {
			if (edgeType === 'DEPENDS_ON') return Promise.resolve([mockEdges[0]]);
			if (edgeType === 'CALLS') return Promise.resolve([]);
			return Promise.resolve(mockEdges);
		});

		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler(
			{
				searchType: 'edges',
				edgeTypes: ['DEPENDS_ON', 'CALLS'],
				limit: 20,
			},
			context
		);

		expect(result.success).toBe(true);
		expect(mockGraph.findEdges).toHaveBeenCalledTimes(2);
		expect(mockGraph.findEdges).toHaveBeenCalledWith(undefined, 'DEPENDS_ON', 10);
		expect(mockGraph.findEdges).toHaveBeenCalledWith(undefined, 'CALLS', 10);
	});

	it('should combine properties and text search filters', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await searchGraphTool.handler(
			{
				searchType: 'nodes',
				properties: { language: 'typescript' },
				textSearch: 'testFunction',
			},
			context
		);

		expect(result.success).toBe(true);

		// Should combine both property filters and text search
		expect(mockGraph.findNodes).toHaveBeenCalledWith(
			{ language: 'typescript', name: 'testFunction' },
			undefined,
			50
		);
	});
});

import { describe, it, expect, vi, beforeEach } from 'vitest';
import { updateNodeTool } from '../update-node.js';

const mockGraph = {
	updateNode: vi.fn().mockResolvedValue(undefined),
};

const getContext = (opts: { withManager?: boolean; withGraph?: boolean } = {}) => {
	const kgManager = opts.withManager
		? { getGraph: vi.fn().mockReturnValue(opts.withGraph ? mockGraph : null) }
		: undefined;
	return {
		toolName: 'update_node',
		startTime: Date.now(),
		sessionId: 'test-session',
		metadata: {},
		services: {
			knowledgeGraphManager: kgManager as any,
		},
	} as any;
};

describe('updateNodeTool', () => {
	beforeEach(() => {
		vi.clearAllMocks();
		mockGraph.updateNode.mockResolvedValue(undefined);
	});

	it('should update a node successfully with properties and labels', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await updateNodeTool.handler(
			{
				nodeId: 'node1',
				properties: { name: 'updated', version: '2.0' },
				labels: ['Function', 'Updated'],
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.nodeId).toBe('node1');
		expect(result.message).toContain("Node 'node1' updated in knowledge graph");
		expect(mockGraph.updateNode).toHaveBeenCalledWith(
			'node1',
			{ name: 'updated', version: '2.0' },
			['Function', 'Updated']
		);
	});

	it('should update a node successfully with only properties', async () => {
		const context = getContext({ withManager: true, withGraph: true });
		const result = await updateNodeTool.handler(
			{
				nodeId: 'node2',
				properties: { description: 'updated description', lastModified: Date.now() },
			},
			context
		);

		expect(result.success).toBe(true);
		expect(result.nodeId).toBe('node2');
		expect(result.message).toContain("Node 'node2' updated in knowledge graph");
		expect(mockGraph.updateNode).toHaveBeenCalledWith(
			'node2',
