			},
			tags: ['important', 'updated'],
			settings: {
				enabled: true,
				priority: 'high',
			},
		};

		const result = await updateNodeTool.handler(
			{
				nodeId: 'complex-node',
				properties: complexProperties,
				labels: ['ComplexNode', 'Updated'],
			},
