		expect(result.success).toBe(true);
		expect(mockGraph.updateNode).toHaveBeenCalledWith('complex-node', complexProperties, [
			'ComplexNode',
			'Updated',
		]);
	});
});

/**
 * Knowledge Graph Add Edge Tool
 *
 * Tool for adding edges (relationships) between nodes in the knowledge graph.
 * Validates that source and target nodes exist before creating relationships.
 */

import type { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';

/**
 * Input schema for the add edge tool
 */
interface AddEdgeInput {
	/** ID of the source node */
	sourceId: string;
	/** ID of the target node */
	targetId: string;
	/** Type/label of the relationship */
	edgeType: string;
	/** Optional properties for the edge */
	properties?: Record<string, any>;
}

/**
 * Add an edge to the knowledge graph
 *
 * @param args - Edge data including source, target, type, and properties
 * @param context - Execution context with services
 * @returns Success message or error details
 */
async function addEdgeHandler(
	args: AddEdgeInput,
	context?: InternalToolContext
): Promise<{ success: boolean; message: string; edgeId?: string; timestamp: string }> {
	try {
		logger.info('AddEdge: Processing add edge request', {
			sourceId: args.sourceId,
			targetId: args.targetId,
			edgeType: args.edgeType,
			hasProperties: !!args.properties,
			propertiesCount: args.properties ? Object.keys(args.properties).length : 0,
		});

		// Validate input
		if (!args.sourceId || typeof args.sourceId !== 'string' || args.sourceId.trim().length === 0) {
			return {
				success: false,
				message: 'Source node ID must be a non-empty string',
				timestamp: new Date().toISOString(),
			};
		}

		if (!args.targetId || typeof args.targetId !== 'string' || args.targetId.trim().length === 0) {
			return {
				success: false,
				message: 'Target node ID must be a non-empty string',
				timestamp: new Date().toISOString(),
			};
		}

		if (!args.edgeType || typeof args.edgeType !== 'string' || args.edgeType.trim().length === 0) {
			return {
				success: false,
				message: 'Edge type must be a non-empty string',
				timestamp: new Date().toISOString(),
			};
		}

		const kgManager = context?.services?.knowledgeGraphManager;
		if (!kgManager) {
			return {
				success: false,
				message: 'KnowledgeGraphManager not available in context.services',
				timestamp: new Date().toISOString(),
			};
		}

		const graph = kgManager.getGraph();
		if (!graph) {
			return {
				success: false,
				message: 'Knowledge graph backend is not connected',
				timestamp: new Date().toISOString(),
			};
		}

		// Verify that source and target nodes exist
		const sourceNode = await graph.getNode(args.sourceId.trim());
		if (!sourceNode) {
			return {
				success: false,
				message: `Source node '${args.sourceId}' does not exist in the knowledge graph`,
				timestamp: new Date().toISOString(),
			};
		}

		const targetNode = await graph.getNode(args.targetId.trim());
		if (!targetNode) {
			return {
				success: false,
				message: `Target node '${args.targetId}' does not exist in the knowledge graph`,
				timestamp: new Date().toISOString(),
			};
		}

		// Add the edge
		const edgeId = `edge_${args.sourceId.trim()}_${args.targetId.trim()}_${args.edgeType.trim()}_${Date.now()}`;
		await graph.addEdge({
			id: edgeId,
			type: args.edgeType.trim(),
			startNodeId: args.sourceId.trim(),
			endNodeId: args.targetId.trim(),
			properties: args.properties || {},
		});

		logger.info('AddEdge: Edge added successfully', {
			edgeId,
			sourceId: args.sourceId,
			targetId: args.targetId,
			edgeType: args.edgeType,
			properties: args.properties ? Object.keys(args.properties) : [],
		});

		return {
			success: true,
			message: `Edge '${args.edgeType}' added between '${args.sourceId}' and '${args.targetId}'`,
			edgeId,
			timestamp: new Date().toISOString(),
		};
	} catch (error) {
		const errorMessage = error instanceof Error ? error.message : String(error);
		logger.error('AddEdge: Failed to add edge', {
			error: errorMessage,
			sourceId: args.sourceId,
			targetId: args.targetId,
			edgeType: args.edgeType,
		});

		return {
			success: false,
			message: `Failed to add edge: ${errorMessage}`,
			timestamp: new Date().toISOString(),
		};
	}
}

/**
 * Add Edge Tool Definition
 */
export const addEdgeTool: InternalTool = {
	name: 'add_edge',
	description: 'Add an edge (relationship) between two nodes in the knowledge graph',
	category: 'knowledge_graph',
	internal: true,
	version: '1.0.0',
	handler: addEdgeHandler,
	parameters: {
		type: 'object',
		properties: {
			sourceId: {
				type: 'string',
				description: 'ID of the source node',
			},
			targetId: {
				type: 'string',
				description: 'ID of the target node',
			},
			edgeType: {
				type: 'string',
				description: 'Type/label of the relationship (e.g., "CALLS", "IMPORTS", "DEPENDS_ON")',
			},
			properties: {
				type: 'object',
				description: 'Optional properties for the edge',
				additionalProperties: true,
			},
		},
		required: ['sourceId', 'targetId', 'edgeType'],
	},
};

/**
 * Knowledge Graph Add Node Tool
 *
 * Tool for adding nodes to the knowledge graph.
 * Validates input data and adds nodes with proper labels and properties.
 */

import type { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';

/**
 * Input schema for the add node tool
 */
interface AddNodeInput {
	/** Unique identifier for the node */
	id: string;
	/** Array of labels/types for the node */
	labels: string[];
	/** Properties/attributes of the node */
	properties?: Record<string, any>;
}

/**
 * Add a node to the knowledge graph
 *
 * @param args - Node data including id, labels, and properties
 * @param context - Execution context with services
 * @returns Success message or error details
 */
async function addNodeHandler(
	args: AddNodeInput,
	context?: InternalToolContext
): Promise<{ success: boolean; message: string; nodeId?: string; timestamp: string }> {
	try {
		logger.info('AddNode: Processing add node request', {
			nodeId: args.id,
			labels: args.labels,
			hasProperties: !!args.properties,
			propertiesCount: args.properties ? Object.keys(args.properties).length : 0,
		});

		// Validate input
		if (!args.id || typeof args.id !== 'string' || args.id.trim().length === 0) {
			return {
				success: false,
				message: 'Node ID must be a non-empty string',
				timestamp: new Date().toISOString(),
			};
		}

		if (!Array.isArray(args.labels) || args.labels.length === 0) {
			return {
				success: false,
				message: 'Node must have at least one label',
				timestamp: new Date().toISOString(),
			};
		}

		// Validate labels are non-empty strings
		const invalidLabels = args.labels.filter(
			label => !label || typeof label !== 'string' || label.trim().length === 0
		);
		if (invalidLabels.length > 0) {
			return {
				success: false,
				message: 'All labels must be non-empty strings',
				timestamp: new Date().toISOString(),
			};
		}

		const kgManager = context?.services?.knowledgeGraphManager;
		if (!kgManager) {
			return {
				success: false,
				message: 'KnowledgeGraphManager not available in context.services',
				timestamp: new Date().toISOString(),
			};
		}

		const graph = kgManager.getGraph();
		if (!graph) {
			return {
				success: false,
				message: 'Knowledge graph backend is not connected',
				timestamp: new Date().toISOString(),
			};
		}

		// Check if node already exists
		const existingNode = await graph.getNode(args.id.trim());
		if (existingNode) {
			logger.warn('AddNode: Attempting to add node that already exists', {
				nodeId: args.id,
				existingLabels: existingNode.labels,
			});
			return {
				success: false,
				message: `Node '${args.id}' already exists in the knowledge graph`,
				nodeId: args.id,
				timestamp: new Date().toISOString(),
			};
		}

		// Add the node
		await graph.addNode({
			id: args.id.trim(),
			labels: args.labels.map(label => label.trim()),
			properties: args.properties || {},
		});

		logger.info('AddNode: Node added successfully', {
			nodeId: args.id,
			labels: args.labels,
			properties: args.properties ? Object.keys(args.properties) : [],
		});

		return {
			success: true,
			message: `Node '${args.id}' added to knowledge graph`,
			nodeId: args.id,
			timestamp: new Date().toISOString(),
		};
	} catch (error) {
		const errorMessage = error instanceof Error ? error.message : String(error);
		logger.error('AddNode: Failed to add node', {
			error: errorMessage,
			nodeId: args.id,
			labels: args.labels,
		});

		return {
			success: false,
			message: `Failed to add node: ${errorMessage}`,
			timestamp: new Date().toISOString(),
		};
	}
}

/**
 * Add Node Tool Definition
 */
export const addNodeTool: InternalTool = {
	name: 'add_node',
	description: 'Add a node to the knowledge graph with labels and properties',
	category: 'knowledge_graph',
	internal: true,
	version: '1.0.0',
	handler: addNodeHandler,
	parameters: {
		type: 'object',
		properties: {
			id: {
				type: 'string',
				description: 'Unique identifier for the node',
			},
			labels: {
				type: 'array',
				items: { type: 'string' },
				description: 'Array of labels/types for the node (e.g., ["Function", "Code"])',
				minItems: 1,
			},
			properties: {
				type: 'object',
				description: 'Optional properties/attributes for the node',
				additionalProperties: true,
			},
		},
		required: ['id', 'labels'],
	},
};

/**
 * Delete Node Tool
 *
 * Deletes a node and its relationships from the knowledge graph.
 */

import { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';

export const deleteNodeTool: InternalTool = {
	name: 'delete_node',
	category: 'knowledge_graph',
	internal: true,
	description: 'Delete a node and its relationships from the knowledge graph.',
	version: '1.0.0',
	parameters: {
		type: 'object',
		properties: {
			id: {
				type: 'string',
				description: 'Node ID to delete',
			},
		},
		required: ['id'],
	},
	handler: async (
		args: { id: string },
		context?: InternalToolContext
	): Promise<{
		success: boolean;
		message: string;
		nodeId?: string;
		timestamp: string;
	}> => {
		try {
			logger.info('DeleteNode: Processing delete request', {
				nodeId: args.id,
			});

			// Validate input
			if (!args.id || typeof args.id !== 'string' || args.id.trim().length === 0) {
				return {
					success: false,
					message: 'Node ID must be a non-empty string',
					timestamp: new Date().toISOString(),
				};
			}

			const kgManager = context?.services?.knowledgeGraphManager;
			if (!kgManager) {
				return {
					success: false,
					message: 'KnowledgeGraphManager not available in context.services',
					nodeId: args.id,
					timestamp: new Date().toISOString(),
				};
			}

			const graph = kgManager.getGraph();
			if (!graph) {
				return {
					success: false,
					message: 'Knowledge graph backend is not connected',
					nodeId: args.id,
					timestamp: new Date().toISOString(),
				};
			}

			// Check if node exists before deletion (optional, but provides better error messages)
			const existingNode = await graph.getNode(args.id.trim());
			if (!existingNode) {
				logger.warn('DeleteNode: Attempting to delete non-existent node', {
					nodeId: args.id,
				});
				// Still return success since the desired state (node not existing) is achieved
				return {
					success: true,
					message: `Node '${args.id}' does not exist (already deleted or never existed)`,
					nodeId: args.id,
					timestamp: new Date().toISOString(),
				};
			}

			// Perform deletion
			await graph.deleteNode(args.id.trim());

			logger.info('DeleteNode: Node deleted successfully', {
				nodeId: args.id,
				nodeLabels: existingNode.labels,
			});

			return {
				success: true,
				nodeId: args.id,
				message: 'Node deleted from knowledge graph',
				timestamp: new Date().toISOString(),
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('DeleteNode: Failed to delete node', {
				error: errorMessage,
				nodeId: args.id,
			});

			return {
				success: false,
				nodeId: args.id,
				message: `Failed to delete node: ${errorMessage}`,
				timestamp: new Date().toISOString(),
			};
		}
	},
};

/**
 * Enhanced Search Tool
 *
 * Advanced search capabilities for the knowledge graph with semantic search,
 * fuzzy matching, multi-property search, and intelligent query understanding.
 *
 * This tool addresses the limitations of the basic search by providing:
 * - Semantic search across multiple properties
 * - Fuzzy matching for partial names
 * - Intelligent query parsing
 * - Contextual search based on relationships
 * - Natural language query support
 */

import { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';
import type { GraphNode, GraphEdge } from '../../../../knowledge_graph/backend/types.js';

/**
 * Enhanced search configuration
 */
interface EnhancedSearchOptions {
	/** Enable semantic search using LLM */
	semanticSearch?: boolean;
	/** Enable fuzzy matching for entity names */
	fuzzyMatching?: boolean;
	/** Fuzzy match threshold (0.0-1.0) */
	fuzzyThreshold?: number;
	/** Include related entities in results */
	includeRelated?: boolean;
	/** Maximum depth for relationship traversal */
	relationDepth?: number;
	/** Search across multiple properties */
	searchProperties?: string[];
	/** Use natural language query understanding */
	naturalLanguage?: boolean;
}

/**
 * Enhanced search result
 */
interface EnhancedSearchResult {
	success: boolean;
	message: string;
	timestamp: string;
	query: {
		original: string;
		processed: string;
		type: 'exact' | 'fuzzy' | 'semantic' | 'natural';
		confidence: number;
	};
	results: {
		nodes: Array<GraphNode & { score?: number; matchReason?: string }>;
		edges: Array<GraphEdge & { score?: number; matchReason?: string }>;
		related: Array<{ entity: GraphNode; relationship: GraphEdge; distance: number }>;
		totalCount: number;
		executionTime: number;
	};
	suggestions?: string[];
	error?: string;
}

/**
 * Enhanced Search Tool
 */
export const enhancedSearchTool: InternalTool = {
	name: 'enhanced_search',
	category: 'knowledge_graph',
	internal: true,
	description:
		'Advanced search with semantic capabilities, fuzzy matching, and intelligent query understanding.',
	version: '1.0.0',
	parameters: {
		type: 'object',
		properties: {
			query: {
				type: 'string',
				description: 'Search query (can be natural language or structured)',
			},
			searchType: {
				type: 'string',
				enum: ['nodes', 'edges', 'both', 'auto'],
				description: 'Type of entities to search for',
				default: 'auto',
			},
			options: {
				type: 'object',
				description: 'Enhanced search configuration',
				properties: {
					semanticSearch: {
						type: 'boolean',
						description: 'Enable semantic search using LLM',
						default: true,
					},
					fuzzyMatching: {
						type: 'boolean',
						description: 'Enable fuzzy matching for entity names',
						default: true,
					},
					fuzzyThreshold: {
						type: 'number',
						description: 'Fuzzy match threshold (0.0-1.0)',
						minimum: 0.0,
						maximum: 1.0,
						default: 0.6,
					},
					includeRelated: {
						type: 'boolean',
						description: 'Include related entities in results',
						default: true,
					},
					relationDepth: {
						type: 'number',
						description: 'Maximum depth for relationship traversal',
						minimum: 1,
						maximum: 3,
						default: 2,
					},
					searchProperties: {
						type: 'array',
						items: { type: 'string' },
						description: 'Properties to search across',
						default: ['name', 'description', 'content', 'title'],
					},
					naturalLanguage: {
						type: 'boolean',
						description: 'Use natural language query understanding',
						default: true,
					},
				},
			},
			limit: {
				type: 'number',
				description: 'Maximum number of results to return',
				minimum: 1,
				maximum: 1000,
				default: 50,
			},
		},
		required: ['query'],
	},
	handler: async (
		args: {
			query: string;
			searchType?: 'nodes' | 'edges' | 'both' | 'auto';
			options?: EnhancedSearchOptions;
			limit?: number;
		},
		context?: InternalToolContext
	): Promise<EnhancedSearchResult> => {
		const startTime = Date.now();

		try {
			logger.info('EnhancedSearch: Processing enhanced search query', {
				queryLength: args.query?.length || 0,
				searchType: args.searchType,
				hasOptions: !!args.options,
			});

			// Validate input
			if (!args.query || typeof args.query !== 'string' || args.query.trim().length === 0) {
				throw new Error('Query is required and must be a non-empty string');
			}

			const query = args.query.trim();
			const searchType = args.searchType || 'auto';
			const limit = args.limit || 50;
			const options: EnhancedSearchOptions = {
				semanticSearch: true,
				fuzzyMatching: true,
				fuzzyThreshold: 0.6,
				includeRelated: true,
				relationDepth: 2,
				searchProperties: ['name', 'description', 'content', 'title'],
				naturalLanguage: true,
				...args.options,
			};

			const kgManager = context?.services?.knowledgeGraphManager;
			const llmService = context?.services?.llmService;

			if (!kgManager) {
				throw new Error('KnowledgeGraphManager not available in context.services');
			}

			const graph = kgManager.getGraph();
			if (!graph) {
				throw new Error('Knowledge graph backend is not connected');
			}

			// Initialize result structure
			const result: EnhancedSearchResult = {
				success: false,
				message: '',
				timestamp: new Date().toISOString(),
				query: {
					original: query,
					processed: query,
					type: 'exact',
					confidence: 1.0,
				},
				results: {
					nodes: [],
					edges: [],
					related: [],
					totalCount: 0,
					executionTime: 0,
				},
			};

			// Step 1: Process and understand the query
			const processedQuery = await processSearchQuery(query, options, llmService);
			result.query = processedQuery;

			// Step 2: Determine search type if auto
			const finalSearchType =
				searchType === 'auto' ? await determineSearchType(processedQuery, llmService) : searchType;

			// Step 3: Execute different search strategies
			const searchResults = await executeEnhancedSearch(
				processedQuery,
				finalSearchType,
				options,
				graph,
				llmService,
				limit
			);

			result.results = searchResults;

			// Step 4: Include related entities if requested
			if (options.includeRelated && searchResults.nodes.length > 0) {
				const relatedEntities = await findRelatedEntities(
					searchResults.nodes.slice(0, 5), // Limit to top 5 for performance
					options.relationDepth || 2,
					graph
				);
				result.results.related = relatedEntities;
			}

			// Step 5: Generate suggestions for better search
			if (searchResults.totalCount === 0 && llmService) {
				result.suggestions = await generateSearchSuggestions(query, graph, llmService);
			}

			result.results.executionTime = Date.now() - startTime;
			result.results.totalCount = result.results.nodes.length + result.results.edges.length;
			result.success = true;
			result.message = `Enhanced search completed - found ${result.results.nodes.length} nodes, ${result.results.edges.length} edges, ${result.results.related.length} related entities`;

			logger.info('EnhancedSearch: Search completed successfully', {
				queryType: result.query.type,
				queryConfidence: result.query.confidence,
				nodesFound: result.results.nodes.length,
				edgesFound: result.results.edges.length,
				relatedFound: result.results.related.length,
				executionTime: result.results.executionTime,
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('EnhancedSearch: Search failed', {
				error: errorMessage,
				queryLength: args.query?.length || 0,
			});

			return {
				success: false,
				message: `Enhanced search failed: ${errorMessage}`,
				timestamp: new Date().toISOString(),
				query: {
					original: args.query || '',
					processed: args.query || '',
					type: 'exact',
					confidence: 0.0,
				},
				results: {
					nodes: [],
					edges: [],
					related: [],
					totalCount: 0,
					executionTime: Date.now() - startTime,
				},
				error: errorMessage,
			};
		}
	},
};

/**
 * Process and understand the search query
 */
async function processSearchQuery(
	query: string,
	options: EnhancedSearchOptions,
	llmService?: any
): Promise<{
	original: string;
	processed: string;
	type: 'exact' | 'fuzzy' | 'semantic' | 'natural';
	confidence: number;
}> {
	// If natural language processing is disabled or LLM is not available, use exact search
	if (!options.naturalLanguage || !llmService) {
		return {
			original: query,
			processed: query,
			type: 'exact',
			confidence: 1.0,
		};
	}

	try {
		const queryProcessingPrompt = `
You are a query processing system for a knowledge graph search. Your job is to understand the user's search intent and convert it into an optimized search query.

Original query: "${query}"

Analyze the query and provide:
1. The search intent (what is the user looking for?)
2. Key entities or concepts to search for
3. Relationship context if any
4. Optimized search terms
5. Confidence level (0.0-1.0)

Examples:
- "find people who like ice cream" -> entities: ["people", "ice cream"], relationship: "LIKES", optimized: "Person LIKES ice cream"
- "Long's friends" -> entities: ["Long"], relationship: "KNOWS", optimized: "Long KNOWS Person"
- "companies in San Francisco" -> entities: ["companies", "San Francisco"], relationship: "LOCATED_IN", optimized: "Organization LOCATED_IN San Francisco"

Respond with a JSON object:
{
  "intent": "description of search intent",
  "entities": ["entity1", "entity2"],
  "relationships": ["RELATIONSHIP_TYPE"],
  "optimizedQuery": "optimized search terms",
  "searchType": "exact" | "fuzzy" | "semantic" | "natural",
  "confidence": 0.0-1.0
}

Respond ONLY with the JSON object:`;

		const response = await llmService.generate(queryProcessingPrompt);
		const cleanResponse = response.replace(/```json|```/g, '').trim();
		const analysis = JSON.parse(cleanResponse);

		return {
			original: query,
			processed: analysis.optimizedQuery || query,
			type: analysis.searchType || 'semantic',
			confidence: Math.max(0.1, Math.min(1.0, analysis.confidence || 0.8)),
		};
	} catch (error) {
		logger.debug('EnhancedSearch: Failed to process query with LLM, using fallback', {
			error: error instanceof Error ? error.message : String(error),
		});

		return {
			original: query,
			processed: query,
			type: 'fuzzy',
			confidence: 0.7,
		};
	}
}

/**
 * Determine the best search type for the query
 */
async function determineSearchType(
	processedQuery: any,
	_llmService?: any
): Promise<'nodes' | 'edges' | 'both'> {
	// Simple heuristics for search type determination
	if (processedQuery.type === 'semantic' || processedQuery.type === 'natural') {
		return 'both'; // Semantic queries often involve both entities and relationships
	}

	const queryLower = processedQuery.processed.toLowerCase();

	// Check for relationship keywords
	const relationshipKeywords = [
		'relationship',
		'connection',
		'relates',
		'connected',
		'links',
		'depends',
		'calls',
	];
	if (relationshipKeywords.some(keyword => queryLower.includes(keyword))) {
		return 'edges';
	}

	// Check for entity keywords
	const entityKeywords = ['person', 'people', 'company', 'organization', 'concept', 'thing'];
	if (entityKeywords.some(keyword => queryLower.includes(keyword))) {
		return 'nodes';
	}

	// Default to both for comprehensive search
	return 'both';
}

/**
 * Execute enhanced search with multiple strategies
 */
async function executeEnhancedSearch(
	processedQuery: any,
	searchType: 'nodes' | 'edges' | 'both',
	options: EnhancedSearchOptions,
	graph: any,
	llmService?: any,
	limit: number = 50
): Promise<{
	nodes: Array<GraphNode & { score?: number; matchReason?: string }>;
	edges: Array<GraphEdge & { score?: number; matchReason?: string }>;
	related: any[];
	totalCount: number;
	executionTime: number;
}> {
	const nodes: Array<GraphNode & { score?: number; matchReason?: string }> = [];
	const edges: Array<GraphEdge & { score?: number; matchReason?: string }> = [];

	try {
		// Strategy 1: Exact search
		if (searchType === 'nodes' || searchType === 'both') {
			const exactNodes = await searchNodesExact(processedQuery.processed, graph, limit / 2);
			exactNodes.forEach(node => {
				nodes.push({
					...node,
					score: 1.0,
					matchReason: 'Exact name match',
				});
			});
		}

		if (searchType === 'edges' || searchType === 'both') {
			const exactEdges = await searchEdgesExact(processedQuery.processed, graph, limit / 2);
			exactEdges.forEach(edge => {
				edges.push({
					...edge,
					score: 1.0,
					matchReason: 'Exact type match',
				});
			});
		}

		// Strategy 2: Fuzzy search (if enabled and exact search returned few results)
		if (options.fuzzyMatching && nodes.length + edges.length < limit / 2) {
			if (searchType === 'nodes' || searchType === 'both') {
				const fuzzyNodes = await searchNodesFuzzy(
					processedQuery.processed,
					graph,
					options.fuzzyThreshold || 0.6,
					limit / 2
				);
				fuzzyNodes.forEach(node => {
					if (!nodes.find(n => n.id === node.id)) {
						nodes.push({
							...node,
							score: 0.8,
							matchReason: 'Fuzzy name match',
						});
					}
				});
			}

			if (searchType === 'edges' || searchType === 'both') {
				const fuzzyEdges = await searchEdgesFuzzy(
					processedQuery.processed,
					graph,
					options.fuzzyThreshold || 0.6,
					limit / 2
				);
				fuzzyEdges.forEach(edge => {
					if (!edges.find(e => e.id === edge.id)) {
						edges.push({
							...edge,
							score: 0.8,
							matchReason: 'Fuzzy type match',
						});
					}
				});
			}
		}

		// Strategy 3: Multi-property search
		if (options.searchProperties && options.searchProperties.length > 0) {
			const propertyResults = await searchByProperties(
				processedQuery.processed,
				options.searchProperties,
				searchType,
				graph,
				limit / 2
			);

			propertyResults.nodes.forEach(node => {
				if (!nodes.find(n => n.id === node.id)) {
					nodes.push({
						...node,
						score: 0.7,
						matchReason: 'Property match',
					});
				}
			});

			propertyResults.edges.forEach(edge => {
				if (!edges.find(e => e.id === edge.id)) {
					edges.push({
						...edge,
						score: 0.7,
						matchReason: 'Property match',
					});
				}
			});
		}

		// Sort results by score
		nodes.sort((a, b) => (b.score || 0) - (a.score || 0));
		edges.sort((a, b) => (b.score || 0) - (a.score || 0));

		// Limit results
		const limitedNodes = nodes.slice(0, limit);
		const limitedEdges = edges.slice(0, limit);

		return {
			nodes: limitedNodes,
			edges: limitedEdges,
			related: [],
			totalCount: limitedNodes.length + limitedEdges.length,
			executionTime: 0, // Will be set by caller
		};
	} catch (error) {
		logger.error('EnhancedSearch: Error executing enhanced search', {
			error: error instanceof Error ? error.message : String(error),
		});

		return {
			nodes: [],
			edges: [],
			related: [],
			totalCount: 0,
			executionTime: 0,
		};
	}
}

/**
 * Search nodes with exact matching
 */
async function searchNodesExact(query: string, graph: any, limit: number): Promise<GraphNode[]> {
	try {
		// Search by exact name match
		const exactMatches = await graph.findNodes({ name: query }, undefined, limit);
		return exactMatches;
	} catch (error) {
		logger.debug('EnhancedSearch: Error in exact node search', {
			error: error instanceof Error ? error.message : String(error),
		});
		return [];
	}
}

/**
 * Search edges with exact matching
 */
async function searchEdgesExact(query: string, graph: any, limit: number): Promise<GraphEdge[]> {
	try {
		// Search by exact type match
		const exactMatches = await graph.findEdges({}, query, limit);
		return exactMatches;
	} catch (error) {
		logger.debug('EnhancedSearch: Error in exact edge search', {
			error: error instanceof Error ? error.message : String(error),
		});
		return [];
	}
}

/**
 * Search nodes with fuzzy matching
 */
async function searchNodesFuzzy(
	query: string,
	graph: any,
	threshold: number,
	limit: number
): Promise<GraphNode[]> {
	try {
		// Get all nodes and filter by fuzzy matching
		const allNodes = await graph.findNodes({}, undefined, limit * 5); // Get more for filtering
		const queryLower = query.toLowerCase();

		const fuzzyMatches = allNodes.filter((node: GraphNode) => {
			const name = node.properties.name?.toLowerCase() || '';
			return (
				name.includes(queryLower) ||
				queryLower.includes(name) ||
				calculateSimilarity(name, queryLower) >= threshold
			);
		});

		return fuzzyMatches.slice(0, limit);
	} catch (error) {
		logger.debug('EnhancedSearch: Error in fuzzy node search', {
			error: error instanceof Error ? error.message : String(error),
		});
		return [];
	}
}

/**
 * Search edges with fuzzy matching
 */
async function searchEdgesFuzzy(
	query: string,
	graph: any,
	threshold: number,
	limit: number
): Promise<GraphEdge[]> {
	try {
		// Get all edges and filter by fuzzy matching
		const allEdges = await graph.findEdges({}, undefined, limit * 5);
		const queryLower = query.toLowerCase();

		const fuzzyMatches = allEdges.filter((edge: GraphEdge) => {
			const type = edge.type.toLowerCase();
			return (
				type.includes(queryLower) ||
				queryLower.includes(type) ||
				calculateSimilarity(type, queryLower) >= threshold
			);
		});

		return fuzzyMatches.slice(0, limit);
	} catch (error) {
		logger.debug('EnhancedSearch: Error in fuzzy edge search', {
			error: error instanceof Error ? error.message : String(error),
		});
		return [];
	}
}

/**
 * Search by multiple properties
 */
async function searchByProperties(
	query: string,
	properties: string[],
	searchType: 'nodes' | 'edges' | 'both',
	graph: any,
	limit: number
): Promise<{ nodes: GraphNode[]; edges: GraphEdge[] }> {
	const nodes: GraphNode[] = [];
	const edges: GraphEdge[] = [];

	try {
		for (const property of properties) {
			if (searchType === 'nodes' || searchType === 'both') {
				const nodeMatches = await graph.findNodes({ [property]: query }, undefined, limit);
				nodes.push(...nodeMatches);
			}

			if (searchType === 'edges' || searchType === 'both') {
				const edgeMatches = await graph.findEdges({ [property]: query }, undefined, limit);
				edges.push(...edgeMatches);
			}
		}
	} catch (error) {
		logger.debug('EnhancedSearch: Error in property search', {
			error: error instanceof Error ? error.message : String(error),
		});
	}

	// Remove duplicates
	const uniqueNodes = nodes.filter(
		(node, index, self) => index === self.findIndex(n => n.id === node.id)
	);
	const uniqueEdges = edges.filter(
		(edge, index, self) => index === self.findIndex(e => e.id === edge.id)
	);

	return {
		nodes: uniqueNodes.slice(0, limit),
		edges: uniqueEdges.slice(0, limit),
	};
}

/**
 * Find entities related to the search results
 */
async function findRelatedEntities(
	nodes: GraphNode[],
	depth: number,
	graph: any
): Promise<Array<{ entity: GraphNode; relationship: GraphEdge; distance: number }>> {
	const related: Array<{ entity: GraphNode; relationship: GraphEdge; distance: number }> = [];

	try {
		for (const node of nodes.slice(0, 3)) {
			// Limit to top 3 for performance
			const neighbors = await graph.getNeighbors(node.id, 'both', undefined, 10);

			neighbors.forEach((neighbor: { node: GraphNode; edge: GraphEdge }) => {
				// Avoid self-references and duplicates
				if (neighbor.node.id !== node.id && !related.find(r => r.entity.id === neighbor.node.id)) {
					related.push({
						entity: neighbor.node,
						relationship: neighbor.edge,
						distance: 1,
					});
				}
			});
		}
	} catch (error) {
		logger.debug('EnhancedSearch: Error finding related entities', {
			error: error instanceof Error ? error.message : String(error),
		});
	}

	return related.slice(0, 10); // Limit results
}

/**
 * Generate search suggestions for better results
 */
async function generateSearchSuggestions(
	query: string,
	graph: any,
	llmService: any
): Promise<string[]> {
	try {
		const suggestionPrompt = `
The user searched for "${query}" in a knowledge graph but found no results. 
Generate 3-5 alternative search suggestions that might help them find what they're looking for.

Consider:
- Alternative spellings or synonyms
- Broader or more specific terms
- Related concepts
- Common entity types (Person, Organization, Concept, etc.)

Examples:
- If they searched "ice cream", suggest "dessert", "food", "frozen treats"
- If they searched "Google", suggest "technology company", "search engine", "Alphabet"

Respond with a JSON array of suggestion strings:
["suggestion1", "suggestion2", "suggestion3"]

Respond ONLY with the JSON array:`;

		const response = await llmService.generate(suggestionPrompt);
		const cleanResponse = response.replace(/```json|```/g, '').trim();
		const suggestions = JSON.parse(cleanResponse);

		return Array.isArray(suggestions) ? suggestions.slice(0, 5) : [];
	} catch (error) {
		logger.debug('EnhancedSearch: Error generating suggestions', {
			error: error instanceof Error ? error.message : String(error),
		});
		return [];
	}
}

/**
 * Calculate similarity between two strings using a simple algorithm
 */
function calculateSimilarity(str1: string, str2: string): number {
	const longer = str1.length > str2.length ? str1 : str2;
	const shorter = str1.length > str2.length ? str2 : str1;

	if (longer.length === 0) return 1.0;

	const distance = levenshteinDistance(longer, shorter);
	return (longer.length - distance) / longer.length;
}

/**
 * Calculate Levenshtein distance between two strings
 */
function levenshteinDistance(str1: string, str2: string): number {
	const matrix: number[][] = Array(str2.length + 1)
		.fill(null)
		.map(() => Array(str1.length + 1).fill(0));

	for (let i = 0; i <= str1.length; i++) {
		matrix[0]![i] = i;
	}
	for (let j = 0; j <= str2.length; j++) {
		matrix[j]![0] = j;
	}

	for (let j = 1; j <= str2.length; j++) {
		for (let i = 1; i <= str1.length; i++) {
			const indicator = str1[i - 1] === str2[j - 1] ? 0 : 1;
			matrix[j]![i] = Math.min(
				matrix[j]![i - 1]! + 1, // deletion
				matrix[j - 1]![i]! + 1, // insertion
				matrix[j - 1]![i - 1]! + indicator // substitution
			);
		}
	}

	return matrix[str2.length]![str1.length]!;
}

/**
 * Extract Entities Tool
 *
 * Extracts entities from text and adds them to the knowledge graph.
 * Uses NLP techniques to identify named entities and relationships.
 */

import { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';

/**
 * Extract entities tool for finding and adding entities from text to knowledge graph
 */
export const extractEntitiesTool: InternalTool = {
	name: 'extract_entities',
	category: 'knowledge_graph',
	internal: true,
	description: 'Extract entities from text and add them to the knowledge graph.',
	version: '1.0.0',
	parameters: {
		type: 'object',
		properties: {
			text: {
				type: 'string',
				description: 'Text to extract entities from',
			},
			options: {
				type: 'object',
				description: 'Extraction options',
				properties: {
					entityTypes: {
						type: 'array',
						items: { type: 'string' },
						description: 'Entity types to focus on (e.g., ["Person", "Organization"])',
					},
					autoLink: {
						type: 'boolean',
						description: 'Whether to automatically create relationships between extracted entities',
						default: true,
					},
					linkTypes: {
						type: 'array',
						items: { type: 'string' },
						description: 'Relationship types to create (e.g., ["IMPLEMENTS", "USES"])',
					},
				},
			},
			// Legacy parameters for backward compatibility
			entityTypes: {
				type: 'array',
				items: { type: 'string' },
				description: 'Optional entity types to focus on (deprecated, use options.entityTypes)',
			},
			autoLink: {
				type: 'boolean',
				description:
					'Whether to automatically create relationships (deprecated, use options.autoLink)',
				default: true,
			},
		},
		required: ['text'],
	},
	handler: async (
		args: {
			text: string;
			options?: {
				entityTypes?: string[];
				autoLink?: boolean;
				linkTypes?: string[];
			};
			// Legacy parameters
			entityTypes?: string[];
			autoLink?: boolean;
		},
		context?: InternalToolContext
	) => {
		try {
			logger.info('ExtractEntities: Processing text for entity extraction', {
				textLength: args.text?.length || 0,
				hasOptions: !!args.options,
			});

			// Validate input
			if (!args.text || typeof args.text !== 'string' || args.text.trim().length === 0) {
				throw new Error('Text is required and must be a non-empty string');
			}

			const text = args.text.trim();

			// Support both new options format and legacy parameters
			const entityTypes = args.options?.entityTypes ||
				args.entityTypes || [
					'Person',
					'Function',
					'Class',
					'Variable',
					'Project',
					'File',
					'Concept',
					'Technology',
					'Command',
					'Tool',
				];
			const autoLink =
				args.options?.autoLink !== undefined
					? args.options.autoLink
					: args.autoLink !== undefined
						? args.autoLink
						: true;
			const linkTypes = args.options?.linkTypes || [
				'IMPLEMENTS',
				'USES',
				'DEPENDS_ON',
				'CALLS',
				'CREATES',
				'MODIFIES',
				'MENTIONS',
				'WORKS_WITH',
			];

			// Extract entities using LLM-based analysis
			const llmService = context?.services?.llmService;
			const extractedEntities = await extractEntitiesFromText(text, entityTypes, llmService);
			const createdRelationships: any[] = [];

			const kgManager = context?.services?.knowledgeGraphManager;
			if (kgManager && extractedEntities.length > 0) {
				const graph = kgManager.getGraph();
				if (graph) {
					// Add entities to graph
					for (const entity of extractedEntities) {
						try {
							await graph.addNode({
								id: entity.id,
								labels: [entity.type],
								properties: {
									name: entity.name,
									confidence: entity.confidence,
									extractedAt: new Date().toISOString(),
									originalText: entity.originalText,
									position: { start: entity.start, end: entity.end },
								},
							});
						} catch (error) {
							logger.debug('ExtractEntities: Failed to add entity node', {
								entityId: entity.id,
								error: error instanceof Error ? error.message : String(error),
							});
						}
					}

					// Create relationships if autoLink is enabled
					if (autoLink && extractedEntities.length > 1) {
						const relationships = await generateEntityRelationships(
							extractedEntities,
							linkTypes,
							text,
							llmService
						);
						for (const rel of relationships) {
							try {
								await graph.addEdge({
									id: rel.id,
									type: rel.type,
									startNodeId: rel.startNodeId,
									endNodeId: rel.endNodeId,
									properties: {
										confidence: rel.confidence,
										extractedAt: new Date().toISOString(),
										basedOnText: rel.context,
									},
								});
								createdRelationships.push(rel);
							} catch (error) {
								logger.debug('ExtractEntities: Failed to add relationship edge', {
									relationshipId: rel.id,
									error: error instanceof Error ? error.message : String(error),
								});
							}
						}
					}
				}
			}

			const extractedCount = extractedEntities.length;
			const linkedCount = createdRelationships.length;

			logger.info('ExtractEntities: Entity extraction completed', {
				extractedCount,
				linkedCount,
				textLength: text.length,
				entityTypes: entityTypes.length,
			});

			return {
				success: true,
				extracted: extractedCount,
				linked: linkedCount,
				entities: extractedEntities,
				relationships: createdRelationships,
				message: 'Entity extraction completed successfully',
				timestamp: new Date().toISOString(),
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('ExtractEntities: Failed to extract entities', {
				error: errorMessage,
				textLength: args.text?.length || 0,
			});

			return {
				success: false,
				error: errorMessage,
				extracted: 0,
				linked: 0,
				timestamp: new Date().toISOString(),
			};
		}
	},
};

/**
 * Extract entities from text using LLM-based analysis
 */
async function extractEntitiesFromText(
	text: string,
	entityTypes: string[],
	llmService?: any
): Promise<
	Array<{
		id: string;
		name: string;
		type: string;
		confidence: number;
		start: number;
		end: number;
		originalText: string;
	}>
> {
	const entities: Array<{
		id: string;
		name: string;
		type: string;
		confidence: number;
		start: number;
		end: number;
		originalText: string;
	}> = [];

	const timestamp = Date.now();

	// Use LLM for entity extraction if available
	if (llmService && text.length > 20) {
		try {
			const entityExtractionPrompt = `
You are an expert entity extraction system. Analyze the following text and extract entities of the specified types.

Entity Types to Extract: ${entityTypes.join(', ')}

Text to Analyze:
"""
${text}
"""

For each entity found, respond with a JSON array containing objects with these fields:
- name: The entity name/identifier
- type: One of the specified entity types
- confidence: Confidence score from 0.0 to 1.0
- context: A brief phrase showing the entity in context
- description: Brief description of what this entity represents

Focus on meaningful entities that represent important concepts, objects, or relationships in the text. Avoid extracting overly generic terms.

Respond ONLY with the JSON array, no other text:`;

			const response = await llmService.generate(entityExtractionPrompt);

			// Parse LLM response
			try {
				const cleanResponse = response.replace(/```json|```/g, '').trim();
				const llmEntities = JSON.parse(cleanResponse);

				if (Array.isArray(llmEntities)) {
					llmEntities.forEach((entity: any, index: number) => {
						if (entity.name && entity.type && entityTypes.includes(entity.type)) {
							// Try to find the entity in the original text to get position
							const entityName = String(entity.name);
							const searchIndex = text.toLowerCase().indexOf(entityName.toLowerCase());

							entities.push({
								id: `${entity.type.toLowerCase()}_${entityName.replace(/[^a-zA-Z0-9]/g, '_')}_${timestamp}_${index}`,
								name: entityName,
								type: entity.type,
								confidence: Math.max(0.1, Math.min(1.0, Number(entity.confidence) || 0.8)),
								start: searchIndex >= 0 ? searchIndex : 0,
								end: searchIndex >= 0 ? searchIndex + entityName.length : entityName.length,
								originalText: entity.context || entityName,
							});
						}
					});
				}
			} catch (parseError) {
				logger.debug(
					'ExtractEntities: Failed to parse LLM response, falling back to regex patterns',
					{
						parseError: parseError instanceof Error ? parseError.message : String(parseError),
						response: response.substring(0, 200),
					}
				);
			}
		} catch (llmError) {
			logger.debug('ExtractEntities: LLM extraction failed, falling back to regex patterns', {
				llmError: llmError instanceof Error ? llmError.message : String(llmError),
			});
		}
	}

	// If LLM extraction didn't produce results, fall back to regex patterns
	if (entities.length === 0) {
		await extractEntitiesWithRegex(text, entityTypes, entities, timestamp);
	}

	// Remove duplicates by name and type
	const uniqueEntities = entities.filter(
		(entity, index, self) =>
			index === self.findIndex(e => e.name === entity.name && e.type === entity.type)
	);

	return uniqueEntities;
}

/**
 * Fallback regex-based entity extraction
 */
async function extractEntitiesWithRegex(
	text: string,
	entityTypes: string[],
	entities: Array<{
		id: string;
		name: string;
		type: string;
		confidence: number;
		start: number;
		end: number;
		originalText: string;
	}>,
	timestamp: number
): Promise<void> {
	// Function/Method extraction
	if (entityTypes.includes('Function')) {
		const functionPatterns = [
			/(?:function|def|fn)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/g,
			/(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)\s*=\s*(?:async\s+)?\(/g,
			/([a-zA-Z_$][a-zA-Z0-9_$]*)\s*\([^)]*\)\s*\{/g,
		];

		functionPatterns.forEach(pattern => {
			let match;
			while ((match = pattern.exec(text)) !== null) {
				const name = match[1];
				if (name && typeof name === 'string' && name.length > 1) {
					entities.push({
						id: `function_${name}_${timestamp}_${entities.length}`,
						name,
						type: 'Function',
						confidence: 0.85,
						start: match.index,
						end: match.index + match[0].length,
						originalText: match[0],
					});
				}
			}
		});
	}

	// Class extraction
	if (entityTypes.includes('Class')) {
		const classPattern = /class\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/g;
		let match;
		while ((match = classPattern.exec(text)) !== null) {
			const name = match[1];
			if (name && typeof name === 'string') {
				entities.push({
					id: `class_${name}_${timestamp}_${entities.length}`,
					name,
					type: 'Class',
					confidence: 0.9,
					start: match.index,
					end: match.index + match[0].length,
					originalText: match[0],
				});
			}
		}
	}

	// File path extraction
	if (entityTypes.includes('File')) {
		const filePattern =
			/['"`]([^'"`]*\.(?:js|ts|py|java|cpp|c|h|json|md|txt|yml|yaml|xml|css|scss|html))['"]/gi;
		let match;
		while ((match = filePattern.exec(text)) !== null) {
			const path = match[1];
			if (path && typeof path === 'string') {
				entities.push({
					id: `file_${path.replace(/[^a-zA-Z0-9]/g, '_')}_${timestamp}_${entities.length}`,
					name: path,
					type: 'File',
					confidence: 0.95,
					start: match.index,
					end: match.index + match[0].length,
					originalText: match[0],
				});
			}
		}
	}

	// Technology/Tool extraction
	if (entityTypes.includes('Technology') || entityTypes.includes('Tool')) {
		const techKeywords = [
			'React',
			'Vue',
			'Angular',
			'Node.js',
			'Python',
			'TypeScript',
			'JavaScript',
			'Java',
			'C++',
			'Docker',
			'Kubernetes',
			'Git',
			'npm',
			'yarn',
			'webpack',
			'babel',
			'MongoDB',
			'PostgreSQL',
			'Redis',
			'AWS',
			'Azure',
			'GCP',
		];

		techKeywords.forEach(tech => {
			const regex = new RegExp(`\\b${tech}\\b`, 'gi');
			let match;
			while ((match = regex.exec(text)) !== null) {
				entities.push({
					id: `tech_${tech}_${timestamp}_${entities.length}`,
					name: tech,
					type: 'Technology',
					confidence: 0.8,
					start: match.index,
					end: match.index + match[0].length,
					originalText: match[0],
				});
			}
		});
	}

	// Variable extraction
	if (entityTypes.includes('Variable')) {
		const varPattern = /(?:const|let|var)\s+([a-zA-Z_$][a-zA-Z0-9_$]*)/g;
		let match;
		while ((match = varPattern.exec(text)) !== null) {
			const name = match[1];
			if (
				name &&
				typeof name === 'string' &&
				name.length > 1 &&
				!['const', 'let', 'var'].includes(name)
			) {
				entities.push({
					id: `var_${name}_${timestamp}_${entities.length}`,
					name,
					type: 'Variable',
					confidence: 0.7,
					start: match.index,
					end: match.index + match[0].length,
					originalText: match[0],
				});
			}
		}
	}
}

/**
 * Generate relationships between extracted entities using LLM analysis
 */
async function generateEntityRelationships(
	entities: Array<{ id: string; name: string; type: string; start: number; end: number }>,
	linkTypes: string[],
	text: string,
	llmService?: any
): Promise<
	Array<{
		id: string;
		type: string;
		startNodeId: string;
		endNodeId: string;
		confidence: number;
		context: string;
	}>
> {
	const relationships: Array<{
		id: string;
		type: string;
		startNodeId: string;
		endNodeId: string;
		confidence: number;
		context: string;
	}> = [];

	// Use LLM for relationship analysis if available and we have multiple entities
	if (llmService && entities.length > 1 && text.length > 50) {
		try {
			const entityList = entities.map(e => `- ${e.name} (${e.type})`).join('\n');
			const relationshipPrompt = `
You are an expert relationship analyzer. Given the following entities extracted from text, identify meaningful relationships between them.

Entities:
${entityList}

Available Relationship Types: ${linkTypes.join(', ')}

Original Text Context:
"""
${text}
"""

For each meaningful relationship you identify, respond with a JSON array containing objects with these fields:
- sourceEntity: Name of the source entity
- targetEntity: Name of the target entity
- relationshipType: One of the available relationship types that best describes the connection
- confidence: Confidence score from 0.0 to 1.0
- reasoning: Brief explanation of why this relationship exists

Focus on relationships that are clearly evident from the text context. Avoid speculative connections.

Respond ONLY with the JSON array, no other text:`;

			const response = await llmService.generate(relationshipPrompt);

			// Parse LLM response
			try {
				const cleanResponse = response.replace(/```json|```/g, '').trim();
				const llmRelationships = JSON.parse(cleanResponse);

				if (Array.isArray(llmRelationships)) {
					llmRelationships.forEach((rel: any) => {
						if (rel.sourceEntity && rel.targetEntity && rel.relationshipType) {
							// Find the corresponding entities
							const sourceEntity = entities.find(e => e.name === rel.sourceEntity);
							const targetEntity = entities.find(e => e.name === rel.targetEntity);

							if (sourceEntity && targetEntity && linkTypes.includes(rel.relationshipType)) {
								// Calculate context around both entities
								const contextStart = Math.max(
									0,
									Math.min(sourceEntity.start, targetEntity.start) - 50
								);
								const contextEnd = Math.min(
									text.length,
									Math.max(sourceEntity.end, targetEntity.end) + 50
								);
								const context = text.substring(contextStart, contextEnd);

								relationships.push({
									id: `rel_${sourceEntity.id}_${targetEntity.id}_${Date.now()}_${relationships.length}`,
									type: rel.relationshipType,
									startNodeId: sourceEntity.id,
									endNodeId: targetEntity.id,
									confidence: Math.max(0.1, Math.min(1.0, Number(rel.confidence) || 0.7)),
									context: context,
								});
							}
						}
					});
				}
			} catch (parseError) {
				logger.debug(
					'ExtractEntities: Failed to parse LLM relationship response, falling back to rule-based approach',
					{
						parseError: parseError instanceof Error ? parseError.message : String(parseError),
						response: response.substring(0, 200),
					}
				);
			}
		} catch (llmError) {
			logger.debug(
				'ExtractEntities: LLM relationship analysis failed, falling back to rule-based approach',
				{
					llmError: llmError instanceof Error ? llmError.message : String(llmError),
				}
			);
		}
	}

	// If LLM analysis didn't produce results, fall back to rule-based approach
	if (relationships.length === 0) {
		for (let i = 0; i < entities.length; i++) {
			for (let j = i + 1; j < entities.length; j++) {
				const entity1 = entities[i];
				const entity2 = entities[j];

				// Skip if either entity is undefined
				if (!entity1 || !entity2) continue;

				// Determine relationship type based on entity types and proximity
				const relType = determineRelationshipType(entity1, entity2, linkTypes);
				if (!relType) continue;

				// Calculate confidence based on proximity and context
				const distance = Math.abs(entity1.start - entity2.start);
				const maxDistance = 500; // characters
				const proximityScore = Math.max(0, 1 - distance / maxDistance);
				const confidence = Math.min(0.9, 0.3 + proximityScore * 0.6);

				// Extract context around the entities
				const contextStart = Math.max(0, Math.min(entity1.start, entity2.start) - 50);
				const contextEnd = Math.min(text.length, Math.max(entity1.end, entity2.end) + 50);
				const context = text.substring(contextStart, contextEnd);

				relationships.push({
					id: `rel_${entity1.id}_${entity2.id}_${Date.now()}`,
					type: relType,
					startNodeId: entity1.id,
					endNodeId: entity2.id,
					confidence,
					context,
				});
			}
		}
	}

	return relationships;
}

/**
 * Determine relationship type between two entities
 */
function determineRelationshipType(
	entity1: { type: string },
	entity2: { type: string },
	linkTypes: string[]
): string | null {
	const type1 = entity1.type;
	const type2 = entity2.type;

	// Function to Class relationships
	if ((type1 === 'Function' && type2 === 'Class') || (type1 === 'Class' && type2 === 'Function')) {
		return linkTypes.includes('BELONGS_TO') ? 'BELONGS_TO' : 'MENTIONS';
	}

	// File to Code relationships
	if (
		(type1 === 'File' && ['Function', 'Class', 'Variable'].includes(type2)) ||
		(['Function', 'Class', 'Variable'].includes(type1) && type2 === 'File')
	) {
		return linkTypes.includes('CONTAINS') ? 'CONTAINS' : 'MENTIONS';
	}

	// Technology relationships
	if (
		(type1 === 'Technology' && ['Function', 'Class', 'Project'].includes(type2)) ||
		(['Function', 'Class', 'Project'].includes(type1) && type2 === 'Technology')
	) {
		return linkTypes.includes('USES') ? 'USES' : 'MENTIONS';
	}

	// Function to Function relationships
	if (type1 === 'Function' && type2 === 'Function') {
		return linkTypes.includes('CALLS') ? 'CALLS' : 'MENTIONS';
	}

	// Default relationship
	return linkTypes.includes('MENTIONS') ? 'MENTIONS' : linkTypes[0] || 'RELATED_TO';
}

/**
 * Get Neighbors Tool
 *
 * Finds neighboring nodes in the knowledge graph with direction and type filtering.
 * Supports filtering by edge types and limiting the number of results.
 */

import { InternalTool } from '../../types.js';

/**
 * Input schema for the get neighbors tool
 */
interface GetNeighborsInput {
	/** ID of the node to get neighbors for */
	nodeId: string;
	/** Direction of relationships ('in', 'out', 'both') */
	direction?: 'in' | 'out' | 'both';
	/** Optional edge types to filter by */
	edgeTypes?: string[];
	/** Maximum number of neighbors to return */
	limit?: number;
}

/**
 * Get neighbors of a node in the knowledge graph
 *
 * @param args - Search parameters
 * @param context - Execution context with services
 * @returns List of neighbor nodes with their connecting edges
 */
async function getNeighborsHandler(
	args: GetNeighborsInput,
	context?: any
): Promise<{ success: boolean; message: string; neighbors?: Array<{ node: any; edge: any }> }> {
	try {
		// Validate input
		if (!args.nodeId || typeof args.nodeId !== 'string') {
			return {
				success: false,
				message: 'Node ID must be a non-empty string',
			};
		}
		const direction = args.direction || 'both';
		const limit = args.limit || 10;
		const kgManager = context?.services?.knowledgeGraphManager;
		if (!kgManager) {
			return {
				success: false,
				message: 'KnowledgeGraphManager not available in context.services',
			};
		}
		const graph = kgManager.getGraph();
		if (!graph) {
			return {
				success: false,
				message: 'Knowledge graph backend is not connected',
			};
		}
		const neighbors = await graph.getNeighbors(args.nodeId, direction, args.edgeTypes, limit);
		return {
			success: true,
			message: 'Neighbors retrieved',
			neighbors,
		};
	} catch (error) {
		return {
			success: false,
			message: `Failed to get neighbors: ${(error as Error).message}`,
		};
	}
}

/**
 * Get Neighbors Tool Definition
 */
export const getNeighborsTool: InternalTool = {
	name: 'get_neighbors',
	description: 'Get neighboring nodes in the knowledge graph with optional filtering',
	category: 'knowledge_graph',
	internal: true,
	handler: getNeighborsHandler,
	parameters: {
		type: 'object',
		properties: {
			nodeId: {
				type: 'string',
				description: 'ID of the node to get neighbors for',
			},
			direction: {
				type: 'string',
				enum: ['in', 'out', 'both'],
				description: 'Direction of relationships to traverse',
				default: 'both',
			},
			edgeTypes: {
				type: 'array',
				items: { type: 'string' },
				description: 'Optional edge types to filter by (e.g., ["DEPENDS_ON", "CALLS"])',
			},
			limit: {
				type: 'number',
				description: 'Maximum number of neighbors to return',
				minimum: 1,
				maximum: 100,
				default: 10,
			},
		},
		required: ['nodeId'],
	},
};

/**
 * Knowledge Graph Tools Module
 *
 * This module exports all knowledge graph-related internal tools for the Cipher agent.
 * These tools handle graph operations, entity management, and knowledge graph queries.
 */

import type { InternalToolSet } from '../../types.js';

// Export all knowledge graph tools with dynamic imports
export { addNodeTool } from './add-node.js';
export { addEdgeTool } from './add-edge.js';
export { searchGraphTool } from './search-graph.js';
export { getNeighborsTool } from './get-neighbors.js';
export { extractEntitiesTool } from './extract-entities.js';
export { updateNodeTool } from './update-node.js';
export { deleteNodeTool } from './delete-node.js';
export { queryGraphTool } from './query-graph.js';

// Export new intelligent knowledge graph tools
export { intelligentProcessorTool } from './intelligent-processor.js';
export { enhancedSearchTool } from './enhanced-search.js';
export { relationshipManagerTool } from './relationship-manager.js';

/**
 * Get all knowledge graph tools as a tool set
 */
export async function getKnowledgeGraphTools(): Promise<InternalToolSet> {
	const [
		{ addNodeTool },
		{ addEdgeTool },
		{ searchGraphTool },
		{ getNeighborsTool },
		{ extractEntitiesTool },
		{ updateNodeTool },
		{ deleteNodeTool },
		{ queryGraphTool },
		{ intelligentProcessorTool },
		{ enhancedSearchTool },
		{ relationshipManagerTool },
	] = await Promise.all([
		import('./add-node.js'),
		import('./add-edge.js'),
		import('./search-graph.js'),
		import('./get-neighbors.js'),
		import('./extract-entities.js'),
		import('./update-node.js'),
		import('./delete-node.js'),
		import('./query-graph.js'),
		import('./intelligent-processor.js'),
		import('./enhanced-search.js'),
		import('./relationship-manager.js'),
	]);

	return {
		[addNodeTool.name]: addNodeTool,
		[addEdgeTool.name]: addEdgeTool,
		[searchGraphTool.name]: searchGraphTool,
		[getNeighborsTool.name]: getNeighborsTool,
		[extractEntitiesTool.name]: extractEntitiesTool,
		[updateNodeTool.name]: updateNodeTool,
		[deleteNodeTool.name]: deleteNodeTool,
		[queryGraphTool.name]: queryGraphTool,
		[intelligentProcessorTool.name]: intelligentProcessorTool,
		[enhancedSearchTool.name]: enhancedSearchTool,
		[relationshipManagerTool.name]: relationshipManagerTool,
	};
}

/**
 * Intelligent Natural Language Processor Tool
 *
 * Advanced tool that intelligently processes natural language statements to automatically
 * extract, create, update, and manage entities and relationships in the knowledge graph.
 *
 * This tool can handle complex scenarios like:
 * - "Long and Trang likes ice-cream" -> Creates Long, Trang, ice-cream entities and LIKES relationships
 * - "not Long but Nam and Trang" -> Removes Long, adds Nam, maintains Trang and relationships
 * - "John works at Google as a software engineer" -> Creates entities and multiple relationships
 */

import { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';
import type { GraphNode, GraphEdge } from '../../../../knowledge_graph/backend/types.js';

/**
 * Configuration for intelligent processing
 */
interface ProcessingOptions {
	/** Whether to automatically resolve entity conflicts */
	autoResolve?: boolean;
	/** Confidence threshold for entity matching (0.0-1.0) */
	confidenceThreshold?: number;
	/** Whether to create relationships automatically */
	autoCreateRelationships?: boolean;
	/** Context to help with entity resolution */
	context?: string;
	/** Previous conversation context for updates */
	previousContext?: string;
}

/**
 * Result of intelligent processing
 */
interface ProcessingResult {
	success: boolean;
	message: string;
	timestamp: string;
	analysis: {
		originalText: string;
		intent: 'create' | 'update' | 'delete' | 'mixed';
		entities: {
			created: Array<{ id: string; name: string; type: string; confidence: number }>;
			updated: Array<{ id: string; name: string; changes: string[] }>;
			deleted: Array<{ id: string; name: string; reason: string }>;
			merged: Array<{ fromId: string; toId: string; reason: string }>;
		};
		relationships: {
			created: Array<{ id: string; type: string; from: string; to: string; confidence: number }>;
			updated: Array<{ id: string; changes: string[] }>;
			deleted: Array<{ id: string; reason: string }>;
		};
		conflicts: Array<{ type: string; description: string; resolution?: string }>;
	};
	error?: string;
}

/**
 * Intelligent Natural Language Processor Tool
 */
export const intelligentProcessorTool: InternalTool = {
	name: 'intelligent_processor',
	category: 'knowledge_graph',
	internal: true,
	description:
		'Intelligently process natural language to automatically manage entities and relationships in the knowledge graph.',
	version: '1.0.0',
	parameters: {
		type: 'object',
		properties: {
			text: {
				type: 'string',
				description: 'Natural language text to process',
			},
			options: {
				type: 'object',
				description: 'Processing configuration options',
				properties: {
					autoResolve: {
						type: 'boolean',
						description: 'Whether to automatically resolve entity conflicts',
						default: true,
					},
					confidenceThreshold: {
						type: 'number',
						description: 'Confidence threshold for entity matching (0.0-1.0)',
						minimum: 0.0,
						maximum: 1.0,
						default: 0.7,
					},
					autoCreateRelationships: {
						type: 'boolean',
						description: 'Whether to create relationships automatically',
						default: true,
					},
					context: {
						type: 'string',
						description: 'Additional context to help with processing',
					},
					previousContext: {
						type: 'string',
						description: 'Previous conversation context for handling updates',
					},
				},
			},
		},
		required: ['text'],
	},
	handler: async (
		args: {
			text: string;
			options?: ProcessingOptions;
		},
		context?: InternalToolContext
	): Promise<ProcessingResult> => {
		try {
			logger.info('IntelligentProcessor: Processing natural language text', {
				textLength: args.text?.length || 0,
				hasOptions: !!args.options,
			});

			// Validate input
			if (!args.text || typeof args.text !== 'string' || args.text.trim().length === 0) {
				throw new Error('Text is required and must be a non-empty string');
			}

			const text = args.text.trim();
			const options: ProcessingOptions = {
				autoResolve: true,
				confidenceThreshold: 0.7,
				autoCreateRelationships: true,
				...args.options,
			};

			const kgManager = context?.services?.knowledgeGraphManager;
			const llmService = context?.services?.llmService;

			if (!llmService) {
				throw new Error('LLM service is required for intelligent processing');
			}

			// Initialize result structure
			const result: ProcessingResult = {
				success: false,
				message: '',
				timestamp: new Date().toISOString(),
				analysis: {
					originalText: text,
					intent: 'create',
					entities: {
						created: [],
						updated: [],
						deleted: [],
						merged: [],
					},
					relationships: {
						created: [],
						updated: [],
						deleted: [],
					},
					conflicts: [],
				},
			};

			// Step 1: Analyze the text to understand intent and extract structured information
			const analysis = await analyzeTextIntent(text, options, llmService);
			result.analysis.intent = analysis.intent;

			// Step 2: Search for existing entities that might be related
			const existingEntities = kgManager
				? await findRelatedEntities(analysis.entities, kgManager)
				: [];

			// Step 3: Process entity operations based on intent
			await processEntityOperations(
				analysis,
				existingEntities,
				options,
				kgManager,
				llmService,
				result
			);

			// Step 4: Process relationship operations
			if (options.autoCreateRelationships && analysis.relationships.length > 0) {
				await processRelationshipOperations(analysis.relationships, result, kgManager, llmService);
			}

			// Step 5: Handle conflicts and resolutions
			if (result.analysis.conflicts.length > 0 && options.autoResolve) {
				await resolveConflicts(result.analysis.conflicts, options, kgManager, llmService);
			}

			result.success = true;
			result.message = `Intelligent processing completed: ${result.analysis.entities.created.length} entities created, ${result.analysis.entities.updated.length} updated, ${result.analysis.entities.deleted.length} deleted, ${result.analysis.relationships.created.length} relationships created`;

			logger.info('IntelligentProcessor: Processing completed successfully', {
				intent: result.analysis.intent,
				entitiesCreated: result.analysis.entities.created.length,
				entitiesUpdated: result.analysis.entities.updated.length,
				entitiesDeleted: result.analysis.entities.deleted.length,
				relationshipsCreated: result.analysis.relationships.created.length,
				conflicts: result.analysis.conflicts.length,
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('IntelligentProcessor: Processing failed', {
				error: errorMessage,
				textLength: args.text?.length || 0,
			});

			return {
				success: false,
				message: `Intelligent processing failed: ${errorMessage}`,
				timestamp: new Date().toISOString(),
				analysis: {
					originalText: args.text || '',
					intent: 'create',
					entities: { created: [], updated: [], deleted: [], merged: [] },
					relationships: { created: [], updated: [], deleted: [] },
					conflicts: [],
				},
				error: errorMessage,
			};
		}
	},
};

/**
 * Analyze text to understand intent and extract structured information
 */
async function analyzeTextIntent(
	text: string,
	options: ProcessingOptions,
	_llmService: any
): Promise<{
	intent: 'create' | 'update' | 'delete' | 'mixed';
	entities: Array<{
		name: string;
		type: string;
		action: 'create' | 'update' | 'delete';
		confidence: number;
		properties?: Record<string, any>;
		context?: string;
	}>;
	relationships: Array<{
		source: string;
		target: string;
		type: string;
		action: 'create' | 'update' | 'delete';
		confidence: number;
		properties?: Record<string, any>;
	}>;
	updateContext?: {
		replacements: Array<{ from: string; to: string }>;
		deletions: string[];
		additions: string[];
	};
}> {
	const analysisPrompt = `
You are an expert natural language processing system that analyzes text to extract entities and relationships for a knowledge graph. Your job is to understand the user's intent and provide structured information about entities and relationships.

Instructions:
1. Determine the primary intent: create (new information), update (modify existing), delete (remove information), or mixed (combination)
2. Extract all entities mentioned with their types and required actions
3. Identify relationships between entities
4. Handle negations and corrections (e.g., "not Long but Nam" means delete Long, add Nam)
5. Provide confidence scores for each extraction

Text to analyze:
"""
${text}
"""

${options.context ? `Additional context: ${options.context}` : ''}
${options.previousContext ? `Previous context: ${options.previousContext}` : ''}

Common entity types to consider:
- Person: Individual people (e.g., Long, Trang, Nam, John)
- Organization: Companies, institutions (e.g., Google, Microsoft)
- Concept: Abstract ideas, things (e.g., ice-cream, software engineering, happiness)
- Location: Places, addresses (e.g., San Francisco, home, office)
- Event: Activities, occasions (e.g., meeting, party, conference)
- Skill: Abilities, expertise (e.g., programming, cooking, singing)
- Object: Physical or digital items (e.g., book, computer, application)

Common relationship types:
- LIKES: Someone likes something
- WORKS_AT: Employment relationship
- LIVES_IN: Residence relationship
- KNOWS: Personal relationship
- HAS_SKILL: Skill possession
- PARTICIPATES_IN: Event participation
- OWNS: Ownership relationship
- RELATED_TO: General relationship

Examples:
- "Long and Trang likes ice-cream" -> Create entities: Long (Person), Trang (Person), ice-cream (Concept). Create relationships: Long LIKES ice-cream, Trang LIKES ice-cream
- "not Long but Nam and Trang" -> Delete: Long. Create: Nam (Person). Keep: Trang (if exists)
- "John works at Google as a software engineer" -> Create: John (Person), Google (Organization), software engineer (Skill). Relationships: John WORKS_AT Google, John HAS_SKILL software engineer

Respond with a JSON object in this format:
{
  "intent": "create" | "update" | "delete" | "mixed",
  "entities": [
    {
      "name": "entity name",
      "type": "entity type",
      "action": "create" | "update" | "delete",
      "confidence": 0.0-1.0,
      "properties": { "optional": "properties" },
      "context": "optional context from text"
    }
  ],
  "relationships": [
    {
      "source": "source entity name",
      "target": "target entity name", 
      "type": "relationship type",
      "action": "create" | "update" | "delete",
      "confidence": 0.0-1.0,
      "properties": { "optional": "properties" }
    }
  ],
  "updateContext": {
    "replacements": [{"from": "old entity", "to": "new entity"}],
    "deletions": ["entity to delete"],
    "additions": ["entity to add"]
  }
}

Respond ONLY with the JSON object, no other text:`;

	try {
		const response = await _llmService.generate(analysisPrompt);
		const cleanResponse = response.replace(/```json|```/g, '').trim();
		const analysis = JSON.parse(cleanResponse);

		// Validate and set defaults
		return {
			intent: analysis.intent || 'create',
			entities: Array.isArray(analysis.entities) ? analysis.entities : [],
			relationships: Array.isArray(analysis.relationships) ? analysis.relationships : [],
			updateContext: analysis.updateContext || undefined,
		};
	} catch (error) {
		logger.warn('IntelligentProcessor: Failed to parse LLM analysis, using fallback', {
			error: error instanceof Error ? error.message : String(error),
		});

		// Fallback: simple entity extraction
		return {
			intent: 'create',
			entities: extractSimpleEntities(text),
			relationships: [],
		};
	}
}

/**
 * Simple fallback entity extraction using patterns
 */
function extractSimpleEntities(text: string): Array<{
	name: string;
	type: string;
	action: 'create' | 'update' | 'delete';
	confidence: number;
}> {
	const entities: Array<{
		name: string;
		type: string;
		action: 'create' | 'update' | 'delete';
		confidence: number;
	}> = [];

	// Extract person names (capitalized words)
	const personPattern = /\b[A-Z][a-z]+\b/g;
	let match;
	while ((match = personPattern.exec(text)) !== null) {
		const name = match[0];
		if (name.length > 1 && !['The', 'And', 'Or', 'But', 'Not'].includes(name)) {
			entities.push({
				name,
				type: 'Person',
				action: 'create',
				confidence: 0.6,
			});
		}
	}

	return entities;
}

/**
 * Find existing entities that might be related to the extracted entities
 */
async function findRelatedEntities(
	extractedEntities: Array<{ name: string; type: string }>,
	kgManager: any
): Promise<GraphNode[]> {
	const graph = kgManager.getGraph();
	if (!graph) return [];

	const existingEntities: GraphNode[] = [];

	for (const entity of extractedEntities) {
		try {
			// Search by exact name match
			const exactMatches = await graph.findNodes({ name: entity.name }, [entity.type], 10);
			existingEntities.push(...exactMatches);

			// Search by fuzzy name match (case-insensitive)
			const fuzzyMatches = await graph.findNodes({}, [entity.type], 50);

			// Filter for similar names
			const similarEntities = fuzzyMatches.filter(
				(existing: GraphNode) =>
					(existing.properties.name &&
						existing.properties.name.toLowerCase().includes(entity.name.toLowerCase())) ||
					entity.name.toLowerCase().includes(existing.properties.name.toLowerCase())
			);

			existingEntities.push(...similarEntities);
		} catch (error) {
			logger.debug('IntelligentProcessor: Error searching for existing entities', {
				entityName: entity.name,
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}

	// Remove duplicates
	const uniqueEntities = existingEntities.filter(
		(entity, index, self) => index === self.findIndex(e => e.id === entity.id)
	);

	return uniqueEntities;
}

/**
 * Process entity operations (create, update, delete)
 */
async function processEntityOperations(
	analysis: any,
	existingEntities: GraphNode[],
	_options: ProcessingOptions,
	kgManager: any,
	_llmService: any,
	result: ProcessingResult
): Promise<void> {
	const graph = kgManager?.getGraph();
	if (!graph) return;

	for (const entityData of analysis.entities) {
		try {
			const existingEntity = existingEntities.find(
				e =>
					e.properties.name?.toLowerCase() === entityData.name.toLowerCase() &&
					e.labels.includes(entityData.type)
			);

			if (entityData.action === 'delete') {
				if (existingEntity) {
					await graph.deleteNode(existingEntity.id);
					result.analysis.entities.deleted.push({
						id: existingEntity.id,
						name: entityData.name,
						reason: 'Explicitly requested for deletion',
					});
				}
			} else if (entityData.action === 'create' || !existingEntity) {
				// Create new entity
				const entityId = `${entityData.type.toLowerCase()}_${entityData.name.replace(/[^a-zA-Z0-9]/g, '_')}_${Date.now()}`;

				const newNode: GraphNode = {
					id: entityId,
					labels: [entityData.type],
					properties: {
						name: entityData.name,
						confidence: entityData.confidence,
						createdAt: new Date().toISOString(),
						extractedFrom: result.analysis.originalText,
						...(entityData.properties || {}),
					},
				};

				await graph.addNode(newNode);
				result.analysis.entities.created.push({
					id: entityId,
					name: entityData.name,
					type: entityData.type,
					confidence: entityData.confidence,
				});
			} else if (entityData.action === 'update' && existingEntity) {
				// Update existing entity
				const updateProperties = {
					...entityData.properties,
					updatedAt: new Date().toISOString(),
					lastExtractedFrom: result.analysis.originalText,
				};

				await graph.updateNode(existingEntity.id, updateProperties);
				result.analysis.entities.updated.push({
					id: existingEntity.id,
					name: entityData.name,
					changes: Object.keys(updateProperties),
				});
			}
		} catch (error) {
			logger.error('IntelligentProcessor: Error processing entity operation', {
				entityName: entityData.name,
				action: entityData.action,
				error: error instanceof Error ? error.message : String(error),
			});

			result.analysis.conflicts.push({
				type: 'entity_operation_error',
				description: `Failed to ${entityData.action} entity ${entityData.name}: ${error instanceof Error ? error.message : String(error)}`,
			});
		}
	}
}

/**
 * Process relationship operations
 */
async function processRelationshipOperations(
	relationships: Array<{
		source: string;
		target: string;
		type: string;
		action: 'create' | 'update' | 'delete';
		confidence: number;
		properties?: Record<string, any>;
	}>,
	result: ProcessingResult,
	_kgManager: any,
	_llmService: any
): Promise<void> {
	const graph = _kgManager?.getGraph();
	if (!graph) return;

	for (const relData of relationships) {
		try {
			// Find source and target entities
			const sourceNodes = await graph.findNodes({ name: relData.source }, undefined, 10);
			const targetNodes = await graph.findNodes({ name: relData.target }, undefined, 10);

			if (sourceNodes.length === 0 || targetNodes.length === 0) {
				result.analysis.conflicts.push({
					type: 'missing_entity',
					description: `Cannot create relationship ${relData.type} between ${relData.source} and ${relData.target}: one or both entities not found`,
				});
				continue;
			}

			const sourceNode = sourceNodes[0];
			const targetNode = targetNodes[0];

			if (relData.action === 'create') {
				const relationshipId = `rel_${sourceNode.id}_${targetNode.id}_${relData.type}_${Date.now()}`;

				const newEdge: GraphEdge = {
					id: relationshipId,
					type: relData.type,
					startNodeId: sourceNode.id,
					endNodeId: targetNode.id,
					properties: {
						confidence: relData.confidence,
						createdAt: new Date().toISOString(),
						extractedFrom: result.analysis.originalText,
						...(relData.properties || {}),
					},
				};

				await graph.addEdge(newEdge);
				result.analysis.relationships.created.push({
					id: relationshipId,
					type: relData.type,
					from: relData.source,
					to: relData.target,
					confidence: relData.confidence,
				});
			}
		} catch (error) {
			logger.error('IntelligentProcessor: Error processing relationship operation', {
				relationship: `${relData.source} ${relData.type} ${relData.target}`,
				action: relData.action,
				error: error instanceof Error ? error.message : String(error),
			});

			result.analysis.conflicts.push({
				type: 'relationship_operation_error',
				description: `Failed to ${relData.action} relationship ${relData.source} ${relData.type} ${relData.target}: ${error instanceof Error ? error.message : String(error)}`,
			});
		}
	}
}

/**
 * Resolve conflicts automatically
 */
async function resolveConflicts(
	conflicts: Array<{ type: string; description: string; resolution?: string }>,
	_options: ProcessingOptions,
	_kgManager: any,
	_llmService: any
): Promise<void> {
	for (const conflict of conflicts) {
		try {
			// Add resolution strategies based on conflict type
			if (conflict.type === 'missing_entity') {
				conflict.resolution = 'Entities will be created automatically if needed';
			} else if (conflict.type === 'entity_operation_error') {
				conflict.resolution = 'Operation skipped, check entity data';
			} else if (conflict.type === 'relationship_operation_error') {
				conflict.resolution = 'Relationship creation skipped, check entity existence';
			}
		} catch (error) {
			logger.warn('IntelligentProcessor: Error resolving conflict', {
				conflictType: conflict.type,
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}
}

/**
 * Query Graph Tool
 *
 * Executes custom queries against the knowledge graph.
 * Supports different query types including Cypher-like queries and structured queries.
 */

import { InternalTool, InternalToolContext } from '../../types.js';
import type { GraphQuery } from '../../../../knowledge_graph/backend/types.js';

/**
 * Query graph tool for executing custom queries against the knowledge graph
 */
export const queryGraphTool: InternalTool = {
	name: 'query_graph',
	category: 'knowledge_graph',
	internal: true,
	description: 'Execute custom queries against the knowledge graph.',
	version: '1.0.0',
	parameters: {
		type: 'object',
		properties: {
			query: {
				type: 'string',
				description: 'Query string (Cypher-like syntax or structured query)',
			},
			queryType: {
				type: 'string',
				enum: ['node', 'edge', 'path', 'cypher'],
				description: 'Type of query to execute',
				default: 'cypher',
			},
			parameters: {
				type: 'object',
				description: 'Query parameters for parameterized queries',
				additionalProperties: true,
			},
			limit: {
				type: 'number',
				description: 'Maximum number of results to return',
				minimum: 1,
				maximum: 1000,
				default: 100,
			},
		},
		required: ['query'],
	},
	handler: async (
		args: {
			query: string;
			queryType?: 'node' | 'edge' | 'path' | 'cypher';
			parameters?: Record<string, any>;
			limit?: number;
		},
		context?: InternalToolContext
	) => {
		try {
			const queryType = args.queryType || 'cypher';
			const limit = args.limit !== undefined ? args.limit : 100;
			if (!args.query || typeof args.query !== 'string' || args.query.trim().length === 0) {
				throw new Error('Query is required and must be a non-empty string');
			}
			if (limit < 1 || limit > 1000) {
				return {
					success: false,
					message: 'Limit must be between 1 and 1000',
					results: null,
					timestamp: new Date().toISOString(),
				};
			}
			const kgManager = context?.services?.knowledgeGraphManager;
			if (!kgManager) {
				return {
					success: false,
					message: 'KnowledgeGraphManager not available in context.services',
					results: null,
					timestamp: new Date().toISOString(),
				};
			}
			const graph = kgManager.getGraph();
			if (!graph) {
				return {
					success: false,
					message: 'Knowledge graph backend is not connected',
					results: null,
					timestamp: new Date().toISOString(),
				};
			}
			const graphQuery: GraphQuery = {
				type: queryType,
				parameters: args.parameters || {},
				limit,
			};
			if (queryType === 'cypher') {
				graphQuery.query = args.query.trim();
			} else {
				// Structured query: parse pattern from query string if possible
				const pattern: any = {};
				if (args.query.includes('labels:')) {
					const labelsMatch = args.query.match(/labels:\s*\[([^\]]+)\]/);
					if (labelsMatch && labelsMatch[1]) {
						pattern.labels = labelsMatch[1].split(',').map(l => l.trim().replace(/['"]/g, ''));
					}
				}
				if (args.query.includes('type:')) {
					// Match quoted or unquoted values
					const typeMatch = args.query.match(/type:\s*(?:['"]([^'"]+)['"]|([A-Z_][A-Z0-9_]*))/);
					if (typeMatch) {
						pattern.type = typeMatch[1] || typeMatch[2]; // Use quoted value if present, otherwise unquoted
					}
				}
				graphQuery.pattern = pattern;
			}
			const result = await graph.query(graphQuery);
			return {
				success: true,
				results: result,
				query: {
					original: args.query,
					type: queryType,
					parameters: args.parameters || {},
					limit,
				},
				message: 'Query executed',
				timestamp: new Date().toISOString(),
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			return {
				success: false,
				error: errorMessage,
				results: {
					nodes: [],
					edges: [],
					metadata: {
						totalCount: 0,
						queryType: args.queryType || 'cypher',
					},
				},
				timestamp: new Date().toISOString(),
			};
		}
	},
};

/**
 * Intelligent Relationship Manager Tool
 *
 * Advanced tools for managing relationships and entities with intelligence.
 * Handles complex scenarios like entity replacement, relationship updates,
 * and smart merging based on natural language instructions.
 *
 * This tool can handle scenarios like:
 * - "not Long but Nam and Trang" -> Replace Long with Nam in all relationships
 * - "update John's role to senior engineer" -> Update specific relationship properties
 * - "merge Google and Alphabet" -> Intelligent entity merging
 * - "delete all connections to deprecated services" -> Bulk relationship management
 */

import { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';
import type { GraphNode, GraphEdge } from '../../../../knowledge_graph/backend/types.js';

/**
 * Relationship management operation types
 */
type RelationshipOperation =
	| 'replace_entity' // Replace one entity with another in all relationships
	| 'update_relationship' // Update specific relationship properties
	| 'merge_entities' // Merge two entities and their relationships
	| 'delete_relationships' // Delete relationships matching criteria
	| 'bulk_update' // Bulk update multiple relationships
	| 'conditional_update'; // Update based on conditions

/**
 * Relationship management configuration
 */
interface RelationshipManagerOptions {
	/** Whether to preserve historical data during operations */
	preserveHistory?: boolean;
	/** Confidence threshold for automatic operations */
	confidenceThreshold?: number;
	/** Whether to automatically resolve conflicts */
	autoResolveConflicts?: boolean;
	/** Maximum number of entities to affect in bulk operations */
	bulkLimit?: number;
	/** Whether to validate relationships before operations */
	validateRelationships?: boolean;
}

/**
 * Relationship operation result
 */
interface RelationshipOperationResult {
	success: boolean;
	message: string;
	timestamp: string;
	operation: {
		type: RelationshipOperation;
		description: string;
		affectedEntities: number;
		affectedRelationships: number;
		confidence: number;
	};
	changes: {
		entitiesCreated: Array<{ id: string; name: string; type: string }>;
		entitiesUpdated: Array<{ id: string; name: string; changes: string[] }>;
		entitiesDeleted: Array<{ id: string; name: string; reason: string }>;
		entitiesMerged: Array<{ fromId: string; toId: string; strategy: string }>;
		relationshipsCreated: Array<{ id: string; type: string; description: string }>;
		relationshipsUpdated: Array<{ id: string; changes: string[] }>;
		relationshipsDeleted: Array<{ id: string; reason: string }>;
	};
	conflicts: Array<{ type: string; description: string; resolution?: string }>;
	rollbackData?: any; // For potential rollback operations
	error?: string;
}

/**
 * Intelligent Relationship Manager Tool
 */
export const relationshipManagerTool: InternalTool = {
	name: 'relationship_manager',
	category: 'knowledge_graph',
	internal: true,
	description:
		'Intelligently manage entity relationships with support for complex operations like entity replacement, merging, and bulk updates.',
	version: '1.0.0',
	parameters: {
		type: 'object',
		properties: {
			instruction: {
				type: 'string',
				description: 'Natural language instruction for the relationship operation',
			},
			operation: {
				type: 'string',
				enum: [
					'replace_entity',
					'update_relationship',
					'merge_entities',
					'delete_relationships',
					'bulk_update',
					'conditional_update',
					'auto',
				],
				description: 'Type of relationship operation (auto will determine from instruction)',
				default: 'auto',
			},
			targets: {
				type: 'object',
				description: 'Target entities or relationships for the operation',
				properties: {
					sourceEntity: {
						type: 'string',
						description: 'Source entity name or ID',
					},
					targetEntity: {
						type: 'string',
						description: 'Target entity name or ID',
					},
					relationshipType: {
						type: 'string',
						description: 'Type of relationship to operate on',
					},
					criteria: {
						type: 'object',
						description: 'Criteria for bulk operations',
						additionalProperties: true,
					},
				},
			},
			options: {
				type: 'object',
				description: 'Operation configuration options',
				properties: {
					preserveHistory: {
						type: 'boolean',
						description: 'Whether to preserve historical data',
						default: true,
					},
					confidenceThreshold: {
						type: 'number',
						description: 'Confidence threshold for automatic operations',
						minimum: 0.0,
						maximum: 1.0,
						default: 0.8,
					},
					autoResolveConflicts: {
						type: 'boolean',
						description: 'Whether to automatically resolve conflicts',
						default: true,
					},
					bulkLimit: {
						type: 'number',
						description: 'Maximum entities to affect in bulk operations',
						minimum: 1,
						maximum: 1000,
						default: 100,
					},
					validateRelationships: {
						type: 'boolean',
						description: 'Whether to validate relationships before operations',
						default: true,
					},
				},
			},
		},
		required: ['instruction'],
	},
	handler: async (
		args: {
			instruction: string;
			operation?: RelationshipOperation | 'auto';
			targets?: any;
			options?: RelationshipManagerOptions;
		},
		context?: InternalToolContext
	): Promise<RelationshipOperationResult> => {
		try {
			logger.info('RelationshipManager: Processing relationship operation', {
				instructionLength: args.instruction?.length || 0,
				operation: args.operation,
				hasTargets: !!args.targets,
			});

			// Validate input
			if (
				!args.instruction ||
				typeof args.instruction !== 'string' ||
				args.instruction.trim().length === 0
			) {
				throw new Error('Instruction is required and must be a non-empty string');
			}

			const instruction = args.instruction.trim();
			const operation = args.operation || 'auto';
			const options: RelationshipManagerOptions = {
				preserveHistory: true,
				confidenceThreshold: 0.8,
				autoResolveConflicts: true,
				bulkLimit: 100,
				validateRelationships: true,
				...args.options,
			};

			const kgManager = context?.services?.knowledgeGraphManager;
			const llmService = context?.services?.llmService;

			if (!kgManager) {
				throw new Error('KnowledgeGraphManager not available in context.services');
			}

			if (!llmService) {
				throw new Error('LLM service is required for intelligent relationship management');
			}

			const graph = kgManager.getGraph();
			if (!graph) {
				throw new Error('Knowledge graph backend is not connected');
			}

			// Initialize result structure
			const result: RelationshipOperationResult = {
				success: false,
				message: '',
				timestamp: new Date().toISOString(),
				operation: {
					type: 'replace_entity',
					description: instruction,
					affectedEntities: 0,
					affectedRelationships: 0,
					confidence: 0.0,
				},
				changes: {
					entitiesCreated: [],
					entitiesUpdated: [],
					entitiesDeleted: [],
					entitiesMerged: [],
					relationshipsCreated: [],
					relationshipsUpdated: [],
					relationshipsDeleted: [],
				},
				conflicts: [],
			};

			// Step 1: Analyze the instruction to understand the operation
			const operationAnalysis = await analyzeRelationshipInstruction(
				instruction,
				args.targets,
				operation,
				llmService
			);
			result.operation = operationAnalysis;

			// Step 2: Execute the specific operation
			switch (operationAnalysis.type) {
				case 'replace_entity':
					await executeEntityReplacement(operationAnalysis, graph, options, result);
					break;
				case 'update_relationship':
					await executeRelationshipUpdate(operationAnalysis, graph, options, result);
					break;
				case 'merge_entities':
					await executeEntityMerge(operationAnalysis, graph, options, result);
					break;
				case 'delete_relationships':
					await executeRelationshipDeletion(operationAnalysis, graph, options, result);
					break;
				case 'bulk_update':
					await executeBulkUpdate(operationAnalysis, graph, options, result);
					break;
				case 'conditional_update':
					await executeConditionalUpdate(operationAnalysis, graph, options, result);
					break;
				default:
					throw new Error(`Unsupported operation type: ${operationAnalysis.type}`);
			}

			// Step 3: Handle conflicts if any
			if (result.conflicts.length > 0 && options.autoResolveConflicts) {
				await resolveOperationConflicts(result.conflicts, graph, llmService);
			}

			result.success = true;
			result.message = `Relationship operation completed: ${result.operation.description}. Affected ${result.operation.affectedEntities} entities and ${result.operation.affectedRelationships} relationships.`;

			logger.info('RelationshipManager: Operation completed successfully', {
				operationType: result.operation.type,
				confidence: result.operation.confidence,
				entitiesAffected: result.operation.affectedEntities,
				relationshipsAffected: result.operation.affectedRelationships,
				conflicts: result.conflicts.length,
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('RelationshipManager: Operation failed', {
				error: errorMessage,
				instructionLength: args.instruction?.length || 0,
			});

			return {
				success: false,
				message: `Relationship operation failed: ${errorMessage}`,
				timestamp: new Date().toISOString(),
				operation: {
					type: 'replace_entity',
					description: args.instruction || '',
					affectedEntities: 0,
					affectedRelationships: 0,
					confidence: 0.0,
				},
				changes: {
					entitiesCreated: [],
					entitiesUpdated: [],
					entitiesDeleted: [],
					entitiesMerged: [],
					relationshipsCreated: [],
					relationshipsUpdated: [],
					relationshipsDeleted: [],
				},
				conflicts: [],
				error: errorMessage,
			};
		}
	},
};

/**
 * Analyze the relationship instruction to understand the operation
 */
async function analyzeRelationshipInstruction(
	instruction: string,
	targets: any,
	operation: RelationshipOperation | 'auto',
	llmService: any
): Promise<{
	type: RelationshipOperation;
	description: string;
	affectedEntities: number;
	affectedRelationships: number;
	confidence: number;
	params?: any;
}> {
	if (operation !== 'auto') {
		return {
			type: operation,
			description: instruction,
			affectedEntities: 0,
			affectedRelationships: 0,
			confidence: 0.9,
			params: targets,
		};
	}

	try {
		const analysisPrompt = `
You are an expert at analyzing relationship management instructions for a knowledge graph. Your job is to understand what operation the user wants to perform and extract the relevant parameters.

Instruction: "${instruction}"

Possible operations:
1. replace_entity: Replace one entity with another in all relationships (e.g., "not Long but Nam", "replace Google with Alphabet")
2. update_relationship: Update properties of specific relationships (e.g., "update John's role to senior engineer")
3. merge_entities: Merge two entities and combine their relationships (e.g., "merge Google and Alphabet")
4. delete_relationships: Remove relationships matching criteria (e.g., "delete all connections to deprecated services")
5. bulk_update: Update multiple relationships at once (e.g., "update all employees' status to active")
6. conditional_update: Update relationships based on conditions (e.g., "promote all junior developers to mid-level")

Analyze the instruction and provide:
1. The operation type
2. Entities involved (source, target, etc.)
3. Relationship types or criteria
4. Confidence level (0.0-1.0)
5. Specific parameters for the operation

Examples:
- "not Long but Nam and Trang" -> replace_entity: replace "Long" with "Nam", keep "Trang"
- "John works at Microsoft now, not Google" -> replace_entity in WORKS_AT relationship
- "merge Google and Alphabet" -> merge_entities: combine all relationships
- "update John's role to senior engineer" -> update_relationship: modify role property

Respond with a JSON object:
{
  "operationType": "replace_entity" | "update_relationship" | "merge_entities" | "delete_relationships" | "bulk_update" | "conditional_update",
  "entities": {
    "source": "source entity name",
    "target": "target entity name", 
    "toReplace": "entity to replace",
    "replacement": "replacement entity"
  },
  "relationships": {
    "type": "relationship type",
    "properties": {"property": "value"}
  },
  "criteria": {
    "conditions": "matching criteria"
  },
  "confidence": 0.0-1.0,
  "description": "human-readable description of the operation"
}

Respond ONLY with the JSON object:`;

		const response = await llmService.generate(analysisPrompt);
		const cleanResponse = response.replace(/```json|```/g, '').trim();
		const analysis = JSON.parse(cleanResponse);

		return {
			type: analysis.operationType || 'replace_entity',
			description: analysis.description || instruction,
			affectedEntities: 0, // Will be calculated during execution
			affectedRelationships: 0, // Will be calculated during execution
			confidence: Math.max(0.1, Math.min(1.0, analysis.confidence || 0.8)),
			params: {
				entities: analysis.entities || {},
				relationships: analysis.relationships || {},
				criteria: analysis.criteria || {},
			},
		};
	} catch (error) {
		logger.warn('RelationshipManager: Failed to analyze instruction with LLM, using fallback', {
			error: error instanceof Error ? error.message : String(error),
		});

		// Fallback: simple pattern matching
		const instructionLower = instruction.toLowerCase();

		if (instructionLower.includes('not') && instructionLower.includes('but')) {
			return {
				type: 'replace_entity',
				description: 'Entity replacement based on pattern matching',
				affectedEntities: 0,
				affectedRelationships: 0,
				confidence: 0.6,
			};
		} else if (instructionLower.includes('merge')) {
			return {
				type: 'merge_entities',
				description: 'Entity merge based on pattern matching',
				affectedEntities: 0,
				affectedRelationships: 0,
				confidence: 0.6,
			};
		} else if (instructionLower.includes('update') || instructionLower.includes('change')) {
			return {
				type: 'update_relationship',
				description: 'Relationship update based on pattern matching',
				affectedEntities: 0,
				affectedRelationships: 0,
				confidence: 0.6,
			};
		} else if (instructionLower.includes('delete') || instructionLower.includes('remove')) {
			return {
				type: 'delete_relationships',
				description: 'Relationship deletion based on pattern matching',
				affectedEntities: 0,
				affectedRelationships: 0,
				confidence: 0.6,
			};
		}

		// Default fallback
		return {
			type: 'replace_entity',
			description: 'Default operation',
			affectedEntities: 0,
			affectedRelationships: 0,
			confidence: 0.5,
		};
	}
}

/**
 * Execute entity replacement operation
 */
async function executeEntityReplacement(
	operation: any,
	graph: any,
	options: RelationshipManagerOptions,
	result: RelationshipOperationResult
): Promise<void> {
	try {
		const params = operation.params || {};
		const entities = params.entities || {};

		// Find entities to replace and replacement entities
		const toReplace = entities.toReplace || entities.source;
		const replacement = entities.replacement || entities.target;

		if (!toReplace || !replacement) {
			throw new Error('Both source and target entities must be specified for replacement');
		}

		// Find the entity to replace
		const sourceEntities = await graph.findNodes({ name: toReplace }, undefined, 10);
		if (sourceEntities.length === 0) {
			result.conflicts.push({
				type: 'entity_not_found',
				description: `Entity to replace "${toReplace}" not found in graph`,
			});
			return;
		}

		// Find or create replacement entity
		let replacementEntities = await graph.findNodes({ name: replacement }, undefined, 10);
		let replacementEntity: GraphNode;

		if (replacementEntities.length === 0) {
			// Create new replacement entity
			const entityId = `person_${replacement.replace(/[^a-zA-Z0-9]/g, '_')}_${Date.now()}`;
			replacementEntity = {
				id: entityId,
				labels: ['Person'], // Default type, could be inferred
				properties: {
					name: replacement,
					createdAt: new Date().toISOString(),
					createdBy: 'relationship_manager',
				},
			};

			await graph.addNode(replacementEntity);
			result.changes.entitiesCreated.push({
				id: entityId,
				name: replacement,
				type: 'Person',
			});
		} else {
			replacementEntity = replacementEntities[0];
		}

		// Replace in all relationships
		for (const sourceEntity of sourceEntities) {
			// Get all relationships involving the source entity
			const neighbors = await graph.getNeighbors(sourceEntity.id, 'both', undefined, 1000);

			for (const neighbor of neighbors) {
				const edge = neighbor.edge;

				// Create new relationship with replacement entity
				const newEdgeId = `rel_${edge.startNodeId === sourceEntity.id ? replacementEntity.id : edge.startNodeId}_${edge.endNodeId === sourceEntity.id ? replacementEntity.id : edge.endNodeId}_${edge.type}_${Date.now()}`;

				const newEdge: GraphEdge = {
					id: newEdgeId,
					type: edge.type,
					startNodeId:
						edge.startNodeId === sourceEntity.id ? replacementEntity.id : edge.startNodeId,
					endNodeId: edge.endNodeId === sourceEntity.id ? replacementEntity.id : edge.endNodeId,
					properties: {
						...edge.properties,
						replacedFrom: sourceEntity.id,
						replacedAt: new Date().toISOString(),
					},
				};

				await graph.addEdge(newEdge);
				result.changes.relationshipsCreated.push({
					id: newEdgeId,
					type: edge.type,
					description: `Replaced relationship from ${sourceEntity.properties.name}`,
				});

				// Delete old relationship
				await graph.deleteEdge(edge.id);
				result.changes.relationshipsDeleted.push({
					id: edge.id,
					reason: 'Entity replacement',
				});

				result.operation.affectedRelationships++;
			}

			// Delete the source entity
			await graph.deleteNode(sourceEntity.id);
			result.changes.entitiesDeleted.push({
				id: sourceEntity.id,
				name: sourceEntity.properties.name || 'Unknown',
				reason: 'Replaced by another entity',
			});

			result.operation.affectedEntities++;
		}
	} catch (error) {
		logger.error('RelationshipManager: Error in entity replacement', {
			error: error instanceof Error ? error.message : String(error),
		});

		result.conflicts.push({
			type: 'operation_error',
			description: `Entity replacement failed: ${error instanceof Error ? error.message : String(error)}`,
		});
	}
}

