/**
 * Interface for memory operation arguments
 */
export interface MemoryOperationArgs {
	extractedFacts: string[];
	existingMemories?: {
		id: string;
		text: string;
		metadata?: Record<string, any>;
	}[];
	context?: {
		sessionId?: string;
		userId?: string;
		projectId?: string;
		conversationTopic?: string;
		recentMessages?: string[];
		sessionMetadata?: Record<string, any>;
	};
	memoryMetadata?: Record<string, any>;
	options?: {
		similarityThreshold?: number;
		maxSimilarResults?: number;
		enableBatchProcessing?: boolean;
		useLLMDecisions?: boolean; // Enable LLM decision making
		confidenceThreshold?: number; // Minimum confidence for operations
		enableDeleteOperations?: boolean; // Enable DELETE operations
	};
}

/**
 * Interface for memory action result following UPDATE_FACT_TOOL_MEMORY pattern
 */
export interface MemoryAction {
	id: number;
	text: string;
	event: 'ADD' | 'UPDATE' | 'DELETE' | 'NONE';
	tags: string[];
	old_memory?: string;
	code_pattern?: string;
	confidence: number; // Confidence score
}

/**
 * Interface for memory operation result
 */
export interface MemoryOperationResult {
	success: boolean;
	totalFacts: number;
	processedFacts: number;
	skippedFacts: number;
	memory: MemoryAction[];
	statistics: {
		addOperations: number;
		updateOperations: number;
		deleteOperations: number;
		noneOperations: number;
		totalSimilarMemories: number;
		averageConfidence: number;
		llmDecisionsUsed: number; // Count of LLM-assisted decisions
		fallbackDecisionsUsed: number; // Count of fallback decisions
	};
	timestamp: string;
	processingTime: number;
	error?: string;
}

/**
 * Default configuration options
 */
const DEFAULT_OPTIONS = {
	similarityThreshold: 0.7,
	maxSimilarResults: 5,
	enableBatchProcessing: true,
	useLLMDecisions: true, // Enable LLM decisions by default
	confidenceThreshold: 0.4, // Lowered to allow fallback operations to proceed
	enableDeleteOperations: true, // Enable DELETE operations
} as const;

/**
 * Prompts for LLM decision making
 */
const MEMORY_OPERATION_PROMPTS = {
	SYSTEM_PROMPT: `You analyze programming knowledge facts and decide ADD, UPDATE, DELETE, or NONE using similarity with existing memories and context.

Process only significant technical content (concepts, code details, patterns, implementations). Skip personal or trivial content.

Consider:
1) Technical relevance and value
2) Semantic similarity/overlap
3) Recency and contextual relevance
4) Quality and completeness
5) Conversation context and needs
6) Concrete code/pattern details

Rules:
- ADD: New, unique technical knowledge
- UPDATE: Improves/corrects existing technical knowledge
- DELETE: Outdated/incorrect/contradictory information
- NONE: Duplicate, already covered, or non-significant

Always preserve full code blocks/commands/patterns exactly as given.`,

	DECISION_PROMPT: `Analyze the knowledge fact and choose ADD, UPDATE, DELETE, or NONE.

Steps:
1) Compare with similar memories (semantic similarity, not keywords).
2) If none are similar (below threshold) -> ADD.
3) If more correct/complete than a similar memory -> UPDATE (include targetMemoryId).
4) If redundant/already present -> NONE.
5) If contradicts an existing memory -> DELETE (include targetMemoryId).
6) Always include a confidence score (0.0–1.0).

Examples:
- ADD
  Similar: none
  { "operation": "ADD", "confidence": 0.95, "targetMemoryId": null }

- UPDATE
  Similar: 12345 (0.91)
  { "operation": "UPDATE", "confidence": 0.90, "targetMemoryId": 12345 }

- NONE
  Similar: 67890 (0.95)
  { "operation": "NONE", "confidence": 0.98, "targetMemoryId": 67890 }

- DELETE
  Similar: 54321 (0.92)
  { "operation": "DELETE", "confidence": 0.93, "targetMemoryId": 54321 }

---
FACT: {fact}
SIMILAR: {similarMemories}
CONTEXT: {context}

Respond ONLY with:
{ "operation": "ADD|UPDATE|DELETE|NONE", "confidence": 0.0-1.0, "targetMemoryId": "id-if-updating-or-deleting-or-none" }`,
};

/**
 * Memory operation tool for intelligent memory management
 */
export const memoryOperationTool: InternalTool = {
	name: 'memory_operation',
	category: 'memory',
	internal: true,
	description:
		'Process extracted knowledge and determine memory operations (ADD, UPDATE, DELETE, NONE) using LLM-powered intelligent reasoning and similarity analysis with existing memories.',
	version: '2.0.0', // version
	parameters: {
		type: 'object',
		properties: {
			extractedFacts: {
				type: 'array',
				description:
					'Array of knowledge facts already extracted from interactions, containing technical details, code patterns, or implementation information.',
				items: {
					type: 'string',
				},
			},
			existingMemories: {
				type: 'array',
				description: 'Array of existing memory entries to compare against for similarity analysis.',
				items: {
					type: 'object',
					properties: {
						id: {
							type: 'string',
							description: 'Unique identifier of the existing memory',
						},
						text: {
							type: 'string',
							description: 'Content of the existing memory',
						},
						metadata: {
							type: 'object',
							description: 'Optional metadata for the memory',
						},
					},
					required: ['id', 'text'],
				},
			},
			context: {
				type: 'object',
				description: 'Optional context information for memory operations',
				properties: {
					sessionId: {
						type: 'string',
						description: 'Current session identifier',
					},
					userId: {
						type: 'string',
						description: 'User identifier for personalized memory',
					},
					projectId: {
						type: 'string',
						description: 'Project identifier for scoped memory',
					},
					conversationTopic: {
						type: 'string',
						description: 'Current conversation topic or theme',
					},
					recentMessages: {
						type: 'array',
						items: { type: 'string' },
						description: 'Recent conversation messages for context',
					},
					sessionMetadata: {
						type: 'object',
						description: 'Additional session metadata',
					},
				},
				additionalProperties: false,
			},
			options: {
				type: 'object',
				description: 'Configuration options for memory operations',
				properties: {
					similarityThreshold: {
						type: 'number',
						description: 'Similarity threshold for memory matching (0.0 to 1.0)',
						minimum: 0.0,
						maximum: 1.0,
					},
					maxSimilarResults: {
						type: 'number',
						description: 'Maximum number of similar memories to retrieve',
						minimum: 1,
						maximum: 20,
					},
					enableBatchProcessing: {
						type: 'boolean',
						description: 'Whether to process multiple knowledge items in batch',
					},
					useLLMDecisions: {
						type: 'boolean',
						description: 'Whether to use LLM-powered decision making',
					},
					confidenceThreshold: {
						type: 'number',
						description: 'Minimum confidence threshold for operations (0.0 to 1.0)',
						minimum: 0.0,
						maximum: 1.0,
					},
					enableDeleteOperations: {
						type: 'boolean',
						description: 'Whether to enable DELETE operations',
					},
				},
				additionalProperties: false,
			},
		},
		required: ['extractedFacts'],
	},
	handler: async (
		args: MemoryOperationArgs,
		context?: InternalToolContext
	): Promise<MemoryOperationResult> => {
		const startTime = Date.now();

		try {
			logger.info('MemoryOperation: Processing memory operation request', {
				factCount: args.extractedFacts?.length || 0,
				existingMemoryCount: args.existingMemories?.length || 0,
				hasContext: !!args.context,
				hasOptions: !!args.options,
			});

			// Phase 1: Basic parameter validation
			const validationResult = validateMemoryOperationArgs(args);
			if (!validationResult.isValid) {
				throw new Error(`Invalid arguments: ${validationResult.errors.join(', ')}`);
			}

			// Merge with default options
			const options = { ...DEFAULT_OPTIONS, ...args.options };

			logger.debug('MemoryOperation: Using configuration options', {
				similarityThreshold: options.similarityThreshold,
				maxSimilarResults: options.maxSimilarResults,
				enableBatchProcessing: options.enableBatchProcessing,
				useLLMDecisions: options.useLLMDecisions,
				confidenceThreshold: options.confidenceThreshold,
				enableDeleteOperations: options.enableDeleteOperations,
			});

			// Filter valid facts
			const validFacts = args.extractedFacts
				.filter(fact => fact && typeof fact === 'string' && fact.trim().length > 0)
				.map(fact => fact.trim());

			if (validFacts.length === 0) {
				throw new Error('No valid facts found after filtering');
			}

			// Phase 2: Get available services
			const memoryActions: MemoryAction[] = [];
			let totalSimilarMemories = 0;
			let confidenceSum = 0;
			let llmDecisionsUsed = 0;
			let fallbackDecisionsUsed = 0;

			// Try to get services from context
			const embeddingManager = context?.services?.embeddingManager;
			const vectorStoreManager = context?.services?.vectorStoreManager;
			const llmService = context?.services?.llmService; // LLM service access

			let embedder: any = null;
			let vectorStore: any = null;

			// Initialize embedding and vector services
			if (embeddingManager && vectorStoreManager) {
				try {
					embedder = embeddingManager.getEmbedder('default');
					vectorStore = vectorStoreManager.getStore();

					if (embedder && vectorStore) {
						logger.debug('MemoryOperation: Using embedding and vector storage services');
					} else {
						logger.warn(
							'MemoryOperation: Services available but not initialized, using basic analysis'
						);
					}
				} catch (error) {
					logger.debug('MemoryOperation: Failed to access embedding/vector services', {
						error: error instanceof Error ? error.message : String(error),
					});
				}
			} else {
				logger.debug(
					'MemoryOperation: No embedding/vector services available in context, using basic analysis'
				);
			}

			// Check LLM service availability
			if (options.useLLMDecisions && llmService) {
				logger.debug('MemoryOperation: LLM service available for decision making');
			} else if (options.useLLMDecisions) {
				logger.warn(
					'MemoryOperation: LLM decisions requested but service not available, falling back to similarity-based decisions'
				);
			}

			// Process each fact individually or in batch
			for (let i = 0; i < validFacts.length; i++) {
				const fact = validFacts[i];
				const codePattern = extractCodePattern(fact || '');
				const tags = extractTechnicalTags(fact || '');

				let memoryAction: MemoryAction;
				let similarMemories: any[] = [];

				if (embedder && vectorStore) {
					try {
						// Generate embedding for the fact
						logger.debug('MemoryOperation: Generating embedding for fact', {
							factIndex: i,
							factLength: (fact || '').length,
						});

						let embedding;
						try {
							embedding = await embedder.embed(fact || '');
						} catch (embedError) {
							logger.error(
								'MemoryOperation: Failed to generate embedding, disabling embeddings globally',
								{
									error: embedError instanceof Error ? embedError.message : String(embedError),
									factIndex: i,
									provider: embedder.getConfig().type,
								}
							);

							// Immediately disable embeddings globally on first failure
							if (context?.services?.embeddingManager && embedError instanceof Error) {
								context.services.embeddingManager.handleRuntimeFailure(
									embedError,
									embedder.getConfig().type
								);
							}

							// Fallback to ADD operation since embeddings are now disabled
							memoryAction = {
								id: generateMemoryId(i),
								text: fact || '',
								event: 'ADD',
								tags,
								confidence: 0.6,
								...(codePattern && { code_pattern: codePattern }),
							};
							fallbackDecisionsUsed++;
							continue;
						}

						// Search for similar memories
						const searchResults = await vectorStore.search(embedding, options.maxSimilarResults);

						// Apply similarity threshold filtering
						similarMemories = searchResults.filter(
							(result: any) => (result.score || 0) >= options.similarityThreshold
						);

						totalSimilarMemories += similarMemories.length;

						logger.debug('MemoryOperation: Found similar memories', {
							factIndex: i,
							totalResults: searchResults.length,
							filteredResults: similarMemories.length,
							threshold: options.similarityThreshold,
						});

						// Use LLM decision making if available and enabled
						if (options.useLLMDecisions && llmService) {
							try {
								memoryAction = await llmDetermineMemoryOperation(
									fact || '',
									similarMemories,
									args.context,
									options,
									llmService,
									i,
									codePattern,
									tags
								);
								llmDecisionsUsed++;

								logger.debug('MemoryOperation: Used LLM decision making', {
									factIndex: i,
									operation: memoryAction.event,
									confidence: memoryAction.confidence,
								});
							} catch (error) {
								logger.warn(
									'MemoryOperation: LLM decision failed, falling back to similarity analysis',
									{
										factIndex: i,
										error: error instanceof Error ? error.message : String(error),
									}
								);

								// Fallback to similarity-based decision
								memoryAction = await determineMemoryOperation(
									fact || '',
									similarMemories,
									options.similarityThreshold,
									i,
									codePattern,
									tags
								);
								fallbackDecisionsUsed++;
							}
						} else {
							// Use similarity-based decision making
							memoryAction = await determineMemoryOperation(
								fact || '',
								similarMemories,
								options.similarityThreshold,
								i,
								codePattern,
								tags
							);
							fallbackDecisionsUsed++;
						}
					} catch (error) {
						logger.warn('MemoryOperation: Error during similarity analysis, falling back to ADD', {
							factIndex: i,
							error: error instanceof Error ? error.message : String(error),
						});

						// Fallback to ADD operation with higher confidence
						memoryAction = {
							id: generateMemoryId(i),
							text: fact || '',
							event: 'ADD',
							tags,
							confidence: 0.6, // Increased from 0.5 to exceed threshold
							...(codePattern && { code_pattern: codePattern }),
						};
						fallbackDecisionsUsed++;
					}
				} else {
					// No embedding/vector storage available - basic analysis
					const isNew = !args.existingMemories?.some(
						mem => calculateTextSimilarity(fact || '', mem.text) > options.similarityThreshold
					);

					memoryAction = {
						id: generateMemoryId(i),
						text: fact || '',
						event: isNew ? 'ADD' : 'NONE',
						tags,
						confidence: isNew ? 0.7 : 0.5, // Higher confidence for new memories
						...(codePattern && { code_pattern: codePattern }),
					};
					fallbackDecisionsUsed++;
				}

				// Apply confidence threshold
				if (
					memoryAction.confidence < options.confidenceThreshold &&
					memoryAction.event !== 'NONE'
				) {
					logger.debug('MemoryOperation: Operation confidence below threshold, changing to NONE', {
						factIndex: i,
						operation: memoryAction.event,
						confidence: memoryAction.confidence,
						threshold: options.confidenceThreshold,
					});

					memoryAction.event = 'NONE';
				}

				memoryActions.push(memoryAction);
				confidenceSum += memoryAction.confidence;
			}

			const processingTime = Date.now() - startTime;
			const averageConfidence = memoryActions.length > 0 ? confidenceSum / memoryActions.length : 0;

			const result: MemoryOperationResult = {
				success: true,
				totalFacts: args.extractedFacts.length,
				processedFacts: validFacts.length,
				skippedFacts: args.extractedFacts.length - validFacts.length,
				memory: memoryActions,
				statistics: {
					addOperations: memoryActions.filter(a => a.event === 'ADD').length,
					updateOperations: memoryActions.filter(a => a.event === 'UPDATE').length,
					deleteOperations: memoryActions.filter(a => a.event === 'DELETE').length,
					noneOperations: memoryActions.filter(a => a.event === 'NONE').length,
					totalSimilarMemories,
					averageConfidence,
					llmDecisionsUsed,
					fallbackDecisionsUsed,
				},
				timestamp: new Date().toISOString(),
				processingTime,
			};

			logger.info('MemoryOperation: Successfully processed memory operations', {
				totalFacts: result.totalFacts,
				processedFacts: result.processedFacts,
				memoryActions: result.memory.length,
				llmDecisionsUsed: result.statistics.llmDecisionsUsed,
				fallbackDecisionsUsed: result.statistics.fallbackDecisionsUsed,
				averageConfidence: result.statistics.averageConfidence.toFixed(2),
				processingTime: `${processingTime}ms`,
			});

			// Persist memory actions to vector store if available
			if (vectorStore && embedder) {
				try {
					await persistMemoryActions(memoryActions, vectorStore, embedder);
					logger.info('MemoryOperation: Successfully persisted memories to vector store', {
						persistedCount: memoryActions.filter(a => a.event === 'ADD' || a.event === 'UPDATE')
							.length,
					});
				} catch (error) {
					logger.warn('MemoryOperation: Failed to persist memories to vector store', {
						error: error instanceof Error ? error.message : String(error),
					});
					// Don't fail the entire operation if persistence fails
				}
			} else {
				logger.debug(
					'MemoryOperation: Vector store or embedder not available, skipping persistence'
				);
			}

			return result;
		} catch (error) {
			const processingTime = Date.now() - startTime;
			const errorMessage = error instanceof Error ? error.message : String(error);

			logger.error('MemoryOperation: Failed to process memory operations', {
				error: errorMessage,
				factCount: args.extractedFacts?.length || 0,
				processingTime: `${processingTime}ms`,
			});

			return {
				success: false,
				totalFacts: args.extractedFacts?.length || 0,
				processedFacts: 0,
				skippedFacts: args.extractedFacts?.length || 0,
				memory: [],
				statistics: {
					addOperations: 0,
					updateOperations: 0,
					deleteOperations: 0,
					noneOperations: 0,
					totalSimilarMemories: 0,
					averageConfidence: 0,
					llmDecisionsUsed: 0,
					fallbackDecisionsUsed: 0,
				},
				timestamp: new Date().toISOString(),
				processingTime,
				error: errorMessage,
			};
		}
	},
};

/**
 * LLM-powered memory operation determination
 */
async function llmDetermineMemoryOperation(
	fact: string,
	similarMemories: any[],
	context: MemoryOperationArgs['context'],
	options: Required<MemoryOperationArgs['options']>,
	llmService: any,
	index: number,
	codePattern?: string,
	tags: string[] = []
): Promise<MemoryAction> {
	const factId = generateMemoryId(index);

	try {
		// Prepare context for LLM
		const contextStr = formatContextForLLM(context);
		const similarMemoriesStr = formatSimilarMemoriesForLLM(similarMemories);

		// Create decision prompt
		const prompt = MEMORY_OPERATION_PROMPTS.DECISION_PROMPT.replace('{fact}', fact)
			.replace('{similarMemories}', similarMemoriesStr)
			.replace('{context}', contextStr);

		logger.debug('MemoryOperation: Requesting LLM decision', {
			factIndex: index,
			factLength: (fact || '').length,
			similarMemoriesCount: similarMemories.length,
		});

		// Get LLM response using directGenerate to bypass conversation context
		const response = await llmService.directGenerate(prompt);

		// Parse LLM response
		const decision = parseLLMDecision(response);

		// Validate and apply decision
		if (!decision || !isValidOperation(decision.operation)) {
			throw new Error(`Invalid LLM decision: ${JSON.stringify(decision)}`);
		}

		// Create memory action based on LLM decision
		const memoryAction: MemoryAction = {
			id: decision.targetMemoryId || factId,
			text: fact || '',
			event: decision.operation as 'ADD' | 'UPDATE' | 'DELETE' | 'NONE',
			tags,
			confidence: Math.max(0, Math.min(1, decision.confidence || 0.7)),

			...(codePattern && { code_pattern: codePattern }),
		};

		// Add old_memory for UPDATE operations
		if (memoryAction.event === 'UPDATE' && decision.targetMemoryId) {
			const targetMemory = similarMemories.find(
				mem => mem.id === decision.targetMemoryId || mem.payload?.id === decision.targetMemoryId
			);
			if (targetMemory) {
				memoryAction.old_memory = targetMemory.payload?.data || targetMemory.text || '';
			}
		}

		// Validate that the final ID is a valid integer
		if (
			typeof memoryAction.id !== 'number' ||
			!Number.isInteger(memoryAction.id) ||
			memoryAction.id <= 0
		) {
			logger.warn('MemoryOperation: Invalid memory ID detected, using fallback', {
				invalidId: memoryAction.id,
				factIndex: index,
				factPreview: fact.substring(0, 80),
			});
			memoryAction.id = factId; // Use the safe generated ID as fallback
		}

		logger.debug('MemoryOperation: LLM decision applied', {
			factIndex: index,
			operation: memoryAction.event,
			confidence: memoryAction.confidence,
			memoryId: memoryAction.id,
		});

		return memoryAction;
	} catch (error) {
		logger.warn('MemoryOperation: LLM decision failed', {
			factIndex: index,
			error: error instanceof Error ? error.message : String(error),
		});

		// Re-throw to trigger fallback
		throw error;
	}
}

/**
 * Format context information for LLM prompt
 */
function formatContextForLLM(context?: MemoryOperationArgs['context']): string {
	if (!context) {
		return 'No specific context provided.';
	}

	const parts: string[] = [];

	if (context.conversationTopic) {
		parts.push(`Topic: ${context.conversationTopic}`);
	}

	if (context.recentMessages && context.recentMessages.length > 0) {
		parts.push(`Recent messages: ${context.recentMessages.slice(-3).join(', ')}`);
	}

	if (context.sessionMetadata) {
		const metadata = Object.entries(context.sessionMetadata)
			.map(([key, value]) => `${key}: ${value}`)
			.join(', ');
		parts.push(`Session info: ${metadata}`);
	}

	return parts.length > 0 ? parts.join('\n') : 'General context.';
}

/**
 * Format similar memories for LLM prompt
 */
function formatSimilarMemoriesForLLM(similarMemories: any[]): string {
	if (!similarMemories || similarMemories.length === 0) {
		return 'No similar memories found.';
	}

	return similarMemories
		.slice(0, 3) // Limit to top 3 for prompt efficiency
		.map((memory, index) => {
			const score = memory.score ? ` (similarity: ${memory.score.toFixed(2)})` : '';
			const text = memory.payload?.data || memory.text || 'No content';
			const id = memory.id || memory.payload?.id || `memory-${index}`;

			return `${index + 1}. ID: ${id}${score}\n   Content: ${text.substring(0, 200)}${text.length > 200 ? '...' : ''}`;
		})
		.join('\n\n');
}

/**
 * Parse LLM decision response with enhanced error handling and proper ID conversion
 */
function parseLLMDecision(response: string): any {
	try {
		if (!response || typeof response !== 'string') {
			logger.debug('MemoryOperation: Empty or invalid LLM response', {
				responseType: typeof response,
			});
			return null;
		}

		// Clean and normalize the response
		const cleanResponse = response.trim();

		// Helper function to safely convert ID to integer
		const safeConvertId = (id: any): number | null => {
			if (id === null || id === undefined) return null;
			const numId = parseInt(String(id), 10);
			return !isNaN(numId) && Number.isInteger(numId) && numId > 0 ? numId : null;
		};

		// Try to extract the first JSON object from the response
		const jsonMatch = cleanResponse.match(/\{[\s\S]*\}/);
		if (jsonMatch) {
			try {
				const decision = JSON.parse(jsonMatch[0]);
				if (decision && decision.operation && typeof decision.confidence === 'number') {
					// Normalize the decision object with proper ID conversion
					return {
						operation: decision.operation,
						confidence: Math.max(0, Math.min(1, decision.confidence)),
						reasoning: decision.reasoning || decision.reason || 'LLM decision',
						targetMemoryId: safeConvertId(
							decision.targetMemoryId || decision.target_id || decision.id
						),
					};
				}
			} catch (parseError) {
				logger.debug('MemoryOperation: Failed to parse JSON match', {
					jsonMatch: jsonMatch[0].substring(0, 100),
					error: parseError instanceof Error ? parseError.message : String(parseError),
				});
			}
		}

		// Fallback: try to find any substring that parses as JSON
		for (let start = 0; start < cleanResponse.length; start++) {
			for (let end = cleanResponse.length; end > start + 10; end--) {
				const substr = cleanResponse.slice(start, end);
				if (substr[0] !== '{' || substr[substr.length - 1] !== '}') continue;
				try {
					const obj = JSON.parse(substr);
					if (obj && obj.operation && typeof obj.confidence === 'number') {
						return {
							operation: obj.operation,
							confidence: Math.max(0, Math.min(1, obj.confidence)),
							reasoning: obj.reasoning || obj.reason || 'LLM decision',
							targetMemoryId: safeConvertId(obj.targetMemoryId || obj.target_id || obj.id),
						};
					}
				} catch {
					// Not valid JSON, continue
				}
			}
		}

		// Advanced fallback: try to extract decision components using regex
		const operationMatch = cleanResponse.match(/(?:operation|action)['"]?\s*:\s*['"]?(\w+)['"]?/i);
		const confidenceMatch = cleanResponse.match(/confidence['"]?\s*:\s*([0-9.]+)/i);
		const reasoningMatch = cleanResponse.match(
			/(?:reasoning|reason)['"]?\s*:\s*['"]([^'"]+)['"]?/i
		);

		if (operationMatch && confidenceMatch) {
			const operation = operationMatch[1]?.toUpperCase() || '';
			const confidence = parseFloat(confidenceMatch[1] || '0');

			if (['ADD', 'UPDATE', 'DELETE', 'NONE'].includes(operation) && !isNaN(confidence)) {
				logger.debug('MemoryOperation: Extracted decision using regex fallback', {
					operation,
					confidence,
					response: cleanResponse.substring(0, 200),
				});

				return {
					operation,
					confidence: Math.max(0, Math.min(1, confidence)),
					reasoning: reasoningMatch ? reasoningMatch[1] : 'Parsed from LLM response',
					targetMemoryId: null,
				};
			}
		}

		// Final fallback: look for operation keywords in the response
		const responseUpper = cleanResponse.toUpperCase();
		let detectedOperation = null;

		if (
			responseUpper.includes('ADD') ||
			responseUpper.includes('CREATE') ||
			responseUpper.includes('NEW')
		) {
			detectedOperation = 'ADD';
		} else if (
			responseUpper.includes('UPDATE') ||
			responseUpper.includes('MODIFY') ||
			responseUpper.includes('CHANGE')
		) {
			detectedOperation = 'UPDATE';
		} else if (responseUpper.includes('DELETE') || responseUpper.includes('REMOVE')) {
			detectedOperation = 'DELETE';
		} else if (
			responseUpper.includes('NONE') ||
			responseUpper.includes('SKIP') ||
			responseUpper.includes('IGNORE')
		) {
			detectedOperation = 'NONE';
		}

		if (detectedOperation) {
			logger.debug('MemoryOperation: Detected operation using keyword fallback', {
				operation: detectedOperation,
				response: cleanResponse.substring(0, 200),
			});

			return {
				operation: detectedOperation,
				confidence: 0.6, // Default confidence for keyword detection
				reasoning: 'Detected from LLM response keywords',
				targetMemoryId: null,
			};
		}

		// If all attempts fail, log the raw response and return null
		logger.debug('MemoryOperation: Failed to parse LLM decision using all methods', {
			response: cleanResponse.substring(0, 500),
			responseLength: cleanResponse.length,
		});

		return null;
	} catch (error) {
		logger.warn('MemoryOperation: Error parsing LLM decision', {
			error: error instanceof Error ? error.message : String(error),
			responsePreview: typeof response === 'string' ? response.substring(0, 100) : 'non-string',
		});
		return null;
	}
}

/**
 * Validate operation type
 */
function isValidOperation(operation: string): boolean {
	return ['ADD', 'UPDATE', 'DELETE', 'NONE'].includes(operation);
}

/**
 * Validation result interface
 */
interface ValidationResult {
	isValid: boolean;
	errors: string[];
}

/**
 * Validate memory operation arguments
 */
function validateMemoryOperationArgs(args: MemoryOperationArgs): ValidationResult {
	const errors: string[] = [];

	// Check required fields
	if (!args.extractedFacts) {
		errors.push('extractedFacts is required');
	} else if (!Array.isArray(args.extractedFacts)) {
		errors.push('extractedFacts must be an array');
	} else if (args.extractedFacts.length === 0) {
		errors.push('extractedFacts array cannot be empty');
	}

	// Validate existing memories if provided
	if (args.existingMemories) {
		if (!Array.isArray(args.existingMemories)) {
			errors.push('existingMemories must be an array');
		} else {
			args.existingMemories.forEach((memory, index) => {
				if (!memory.id || typeof memory.id !== 'string') {
					errors.push(`existingMemories[${index}].id must be a non-empty string`);
				}
				if (!memory.text || typeof memory.text !== 'string') {
					errors.push(`existingMemories[${index}].text must be a non-empty string`);
				}
			});
		}
	}

	// Validate context if provided
	if (args.context) {
		if (typeof args.context !== 'object') {
			errors.push('context must be an object');
		} else {
			if (args.context.sessionId && typeof args.context.sessionId !== 'string') {
				errors.push('context.sessionId must be a string');
			}
			if (args.context.userId && typeof args.context.userId !== 'string') {
				errors.push('context.userId must be a string');
			}
			if (args.context.projectId && typeof args.context.projectId !== 'string') {
				errors.push('context.projectId must be a string');
			}
		}
	}

	// Validate options if provided
	if (args.options) {
		if (typeof args.options !== 'object') {
			errors.push('options must be an object');
		} else {
			if (args.options.similarityThreshold !== undefined) {
				if (typeof args.options.similarityThreshold !== 'number') {
					errors.push('options.similarityThreshold must be a number');
				} else if (args.options.similarityThreshold < 0 || args.options.similarityThreshold > 1) {
					errors.push('options.similarityThreshold must be between 0.0 and 1.0');
				}
			}
			if (args.options.maxSimilarResults !== undefined) {
				if (typeof args.options.maxSimilarResults !== 'number') {
					errors.push('options.maxSimilarResults must be a number');
				} else if (args.options.maxSimilarResults < 1 || args.options.maxSimilarResults > 20) {
					errors.push('options.maxSimilarResults must be between 1 and 20');
				}
			}
			if (
				args.options.enableBatchProcessing !== undefined &&
				typeof args.options.enableBatchProcessing !== 'boolean'
			) {
				errors.push('options.enableBatchProcessing must be a boolean');
			}
			// Additional validation
			if (
				args.options.useLLMDecisions !== undefined &&
				typeof args.options.useLLMDecisions !== 'boolean'
			) {
				errors.push('options.useLLMDecisions must be a boolean');
			}
			if (args.options.confidenceThreshold !== undefined) {
				if (typeof args.options.confidenceThreshold !== 'number') {
					errors.push('options.confidenceThreshold must be a number');
				} else if (args.options.confidenceThreshold < 0 || args.options.confidenceThreshold > 1) {
					errors.push('options.confidenceThreshold must be between 0.0 and 1.0');
				}
			}
			if (
				args.options.enableDeleteOperations !== undefined &&
				typeof args.options.enableDeleteOperations !== 'boolean'
			) {
				errors.push('options.enableDeleteOperations must be a boolean');
			}
		}
	}

	return {
		isValid: errors.length === 0,
		errors,
	};
}

/**
 * Extract code pattern from fact content
 */
function extractCodePattern(fact: string): string | undefined {
	// Extract code blocks (```...```)
	const codeBlockMatch = fact.match(/```[\s\S]*?```/);
	if (codeBlockMatch) {
		return codeBlockMatch[0];
	}

	// Extract inline code (`...`)
	const inlineCodeMatch = fact.match(/`[^`]+`/);
	if (inlineCodeMatch) {
		return inlineCodeMatch[0];
	}

	// Extract command patterns (starting with $ or npm/git/etc)
	const commandPatterns = [
		/\$\s+[^\n]+/,
		/(npm|yarn|pnpm)\s+[^\n]+/,
		/(git)\s+[^\n]+/,
		/(docker)\s+[^\n]+/,
		/(curl|wget)\s+[^\n]+/,
	];

	for (const pattern of commandPatterns) {
		const match = fact.match(pattern);
		if (match) {
			return match[0];
		}
	}

	return undefined;
}

/**
 * Extract technical tags from fact content
 */
function extractTechnicalTags(fact: string): string[] {
	const tags: string[] = [];

	// Programming languages
	const languages = [
		'javascript',
		'typescript',
		'python',
		'java',
		'rust',
		'go',
		'php',
		'ruby',
		'swift',
		'kotlin',
	];
	languages.forEach(lang => {
		if (fact.toLowerCase().includes(lang)) {
			tags.push(lang);
		}
	});

	// Frameworks and libraries
	const frameworks = [
		'react',
		'vue',
		'angular',
		'svelte',
		'nextjs',
		'express',
		'fastify',
		'django',
		'flask',
	];
	frameworks.forEach(framework => {
		if (fact.toLowerCase().includes(framework)) {
			tags.push(framework);
		}
	});

	// Tools and technologies
	const tools = [
		'docker',
		'kubernetes',
		'git',
		'npm',
		'yarn',
		'webpack',
		'vite',
		'eslint',
		'prettier',
	];
	tools.forEach(tool => {
		if (fact.toLowerCase().includes(tool)) {
			tags.push(tool);
		}
	});

	// Content type tags
	if (fact.includes('```')) {
		tags.push('code-block');
	}
	if (
		fact.includes('function') ||
		fact.includes('class') ||
		fact.includes('const') ||
		fact.includes('let') ||
		fact.includes('var')
	) {
		tags.push('programming');
	}
	if (
		fact.includes('/') ||
		fact.includes('\\') ||
		fact.includes('.js') ||
		fact.includes('.ts') ||
		fact.includes('.py')
	) {
		tags.push('file-path');
	}
	if (
		fact.includes('error') ||
		fact.includes('exception') ||
		fact.includes('failed') ||
		fact.includes('bug')
	) {
		tags.push('error-handling');
	}
	if (fact.includes('config') || fact.includes('setting') || fact.includes('option')) {
		tags.push('configuration');
	}
	if (
		fact.includes('api') ||
		fact.includes('endpoint') ||
		fact.includes('request') ||
		fact.includes('response')
	) {
		tags.push('api');
	}

	// Add general tag if no specific patterns found
	if (tags.length === 0) {
		tags.push('general-knowledge');
	}

	// Remove duplicates and return lowercase singular nouns
	return Array.from(new Set(tags)).map(tag => tag.toLowerCase());
}

/**
 * Generate unique memory ID (integer)
 * Uses range 1-333333 to avoid conflicts with other memory systems
 */
function generateMemoryId(index: number): number {
	// Use timestamp-based approach to avoid conflicts
	// Range: 1-333333 for knowledge memory entries
	const now = Date.now();
	const randomSuffix = Math.floor(Math.random() * 1000); // 0-999
	let vectorId = 1 + (((now % 300000) * 1000 + randomSuffix + index) % 333333);

	// Ensure it's a positive integer
	if (vectorId <= 0) {
		vectorId = Math.floor(Math.random() * 333333) + 1;
	}

	return vectorId;
}

/**
 * Determine memory operation based on similarity analysis (fallback method)
 */
async function determineMemoryOperation(
	fact: string,
	similarMemories: any[],
	threshold: number,
	index: number,
	codePattern?: string,
	tags: string[] = []
): Promise<MemoryAction> {
	const factId = generateMemoryId(index);

	// If no similar memories found, ADD the new fact
	if (similarMemories.length === 0) {
		return {
			id: factId,
			text: fact,
			event: 'ADD',
			tags,
			confidence: 0.8,
			...(codePattern && { code_pattern: codePattern }),
		};
	}

	// Find the most similar memory
	const mostSimilar = similarMemories[0];
	const similarity = mostSimilar.score || 0;

	// High similarity (>0.9) - consider as duplicate, return NONE
	if (similarity > 0.9) {
		return {
			id: factId,
			text: fact,
			event: 'NONE',
			tags,
			confidence: 0.9,
			...(codePattern && { code_pattern: codePattern }),
		};
	}

	// Medium-high similarity (0.7-0.9) - consider updating existing memory
	if (similarity > threshold && similarity <= 0.9) {
		return {
			id: factId,
			text: fact,
			event: 'UPDATE',
			tags,
			confidence: 0.75,
			old_memory: mostSimilar.payload?.data || mostSimilar.text || '',
			...(codePattern && { code_pattern: codePattern }),
		};
	}

	// Low similarity - ADD as new memory
	return {
		id: factId,
		text: fact,
		event: 'ADD',
		tags,
		confidence: 0.7,
		...(codePattern && { code_pattern: codePattern }),
	};
}

/**
 * Calculate text similarity using simple token-based approach
 * This is a fallback when embeddings are not available
 */
function calculateTextSimilarity(text1: string, text2: string): number {
	const words1 = new Set(text1.toLowerCase().split(/\s+/));
	const words2 = new Set(text2.toLowerCase().split(/\s+/));

	const intersection = new Set(Array.from(words1).filter(word => words2.has(word)));
	const union = new Set(Array.from(words1).concat(Array.from(words2)));

	return intersection.size / union.size;
}

/**
 * Persist memory actions to vector store
 */
async function persistMemoryActions(
	memoryActions: MemoryAction[],
	vectorStore: any,
	embedder: any
): Promise<void> {
	const actionsToProcess = memoryActions.filter(
		action => action.event === 'ADD' || action.event === 'UPDATE'
	);

	if (actionsToProcess.length === 0) {
		logger.debug('MemoryOperation: No actions require persistence');
		return;
	}

	logger.info('MemoryOperation: Persisting memory actions', {
		totalActions: actionsToProcess.length,
		addActions: actionsToProcess.filter(a => a.event === 'ADD').length,
		updateActions: actionsToProcess.filter(a => a.event === 'UPDATE').length,
	});

	// Process each action
	for (const action of actionsToProcess) {
		try {
			// Generate embedding for the memory text
			let embedding;
			try {
				embedding = await embedder.embed(action.text || '');
			} catch (embedError) {
				logger.error(
					'MemoryOperation: Failed to generate embedding for persistence, disabling embeddings globally',
					{
						error: embedError instanceof Error ? embedError.message : String(embedError),
						actionId: action.id,
						provider: embedder.getConfig().type,
					}
				);

				// Immediately disable embeddings globally on first failure
				// Note: We don't have context here, so we'll just log the error
				// The global disable will be handled by the calling function
				logger.error(
					'MemoryOperation: Cannot disable embeddings globally from persistMemoryActions - error logged'
				);

				// Skip this action and continue with others
				continue;
			}

			// Determine quality source for V2 payload
			let qualitySource: 'similarity' | 'llm' | 'heuristic' = 'heuristic';

			// Create V2 payload with enhanced metadata
			const payload = createKnowledgePayload(
				action.id,
				action.text || '',
				action.tags,
				action.confidence,
				action.event,
				{
					qualitySource,
					...(action.code_pattern && { code_pattern: action.code_pattern }),
					...(action.old_memory && { old_memory: action.old_memory }),
				}
			);

			if (action.event === 'ADD') {
				// Insert new memory
				await vectorStore.insert([embedding], [action.id], [payload]);
				logger.debug('MemoryOperation: Added memory to vector store', {
					id: action.id,
					textLength: (action.text || '').length,
				});
			} else if (action.event === 'UPDATE') {
				// Update existing memory
				await vectorStore.update(action.id, embedding, payload);
				logger.debug('MemoryOperation: Updated memory in vector store', {
					id: action.id,
					textLength: (action.text || '').length,
				});
			}
		} catch (error) {
			logger.error('MemoryOperation: Failed to persist memory action', {
				actionId: action.id,
				event: action.event,
				error: error instanceof Error ? error.message : String(error),
			});
			// Continue with other actions even if one fails
		}
	}
}
/**
 * Step 1: Rewrite user query into sub-queries and disambiguate ambiguous terms
 * Uses LLM to generate more targeted queries for better retrieval
 *
 * @param originalInput - The original user query to rewrite
 * @param llmService - The LLM service to use for rewriting
 * @returns An object containing the rewritten queries
 */
async function rewriteUserQuery(
	originalInput: string,
	llmService: any
): Promise<{ queries: string[] }> {
	// Add debugging to track function calls
	const callId = Math.random().toString(36).substring(7);
	console.log(`🔄 [${callId}] rewriteUserQuery called with: "${originalInput}"`);

	try {
		const rewritePrompt = `
        You are a query decomposition and disambiguation expert. Break down this question into search queries for a knowledge base while handling ambiguous terms.

        QUESTION: "${originalInput}"

		TASK: Create 2-4 concise search queries that capture the core information needs of the question. Only include disambiguation if absolutely necessary.

		GUIDELINES:
		- Focus on the main intent of the question.
		- Use natural, searchable language (4-15 words per query).
		- Only create disambiguation queries for clearly ambiguous terms.
		- Avoid over-decomposing the question into too many subqueries.
		- Prefer fewer, more precise queries over exhaustive coverage.
		- Each query should stand alone and be understandable without additional context.

		DISAMBIGUATION (Only if needed):
		- For truly ambiguous terms (homonyms, abbreviations, etc.), include 1-2 alternate queries with different meanings.
		- Do not force disambiguation where the meaning is already clear from context.

        OUTPUT FORMAT:
        Respond with ONLY the queries, one per line, using this exact format:
        Query 1: [first query]
        Query 2: [second query]
        [continue as needed...]

        Do not include any explanations, introductions, or other text. Only the queries.

        EXAMPLES:
        Question: "What profession does Nicholas Ray and Elia Kazan have in common?"
        Query 1: Nicholas Ray profession career
        Query 2: Elia Kazan profession career

        Question: "Most total goals in a premier league season?"
        Query 1: Most total goals in a premier league season by a team
        Query 2: Most total goals in a premier league season by a player

        Now decompose and disambiguate: "${originalInput}"
        `;
		const rewriteResponse = await llmService.directGenerate(rewritePrompt);

		// Parse the response to extract individual queries
		const queries = rewriteResponse
			.split('\n')
			.map((line: string) => line.trim())
			.filter((line: string) => line.length > 0)
			.map((line: string) => {
				// Extract query content after "Query X:" prefix
				const match = line.match(/^Query\s*\d+:\s*(.+)$/i);
				return match && match[1] ? match[1].trim() : null;
			})
			.filter((query: string | null) => query !== null && query.length >= 3)
			.filter(
				(query: string | null, index: number, array: (string | null)[]) =>
					array.indexOf(query) === index
			); // Remove duplicates

		console.log(`🔄 [${callId}] Parsed queries:`, queries);
		console.log(`🔄 [${callId}] Query count: ${queries.length}`);

		// Ensure we have at least one query (fallback to original)
		if (queries.length === 0) {
			console.log(`🔄 [${callId}] No queries parsed, falling back to original input`);
			return {
				queries: [originalInput],
			};
		}

		console.log(`🔄 [${callId}] Returning ${queries.length} refined queries`);
		return {
			queries: queries,
		};
	} catch (error) {
		console.log(`🔄 [${callId}] Error in rewriteUserQuery:`, error);
		logger.warn('MemorySearch: Query rewriting failed', {
			originalInput: originalInput.substring(0, 100),
			error: error instanceof Error ? error.message : String(error),
		});
		return {
			queries: [originalInput],
		};
	}
}

export { parseLLMDecision, MEMORY_OPERATION_PROMPTS, extractTechnicalTags, rewriteUserQuery };

/**
 * Memory Payload Structures (V2 Only - Simplified)
 *
 * Clean, optimized payload structures for both knowledge and reasoning memory.
 * No migration complexity - all data is V2 format after collection cleanup.
 */

export interface BasePayload {
	id: number;
	text: string;
	timestamp: string;
	version: 2; // Always V2 after cleanup
	// Cross-tool sharing identifiers
	userId?: string;
	projectId?: string;
	workspaceMode?: 'shared' | 'isolated';
}

/**
 * Knowledge Memory Payload - For factual information and patterns
 */
export interface KnowledgePayload extends BasePayload {
	tags: string[];
	confidence: number;
	event: 'ADD' | 'UPDATE' | 'DELETE' | 'NONE';
	// Enhanced V2 fields
	domain?: string;
	sourceSessionId?: string;
	qualitySource: 'similarity' | 'llm' | 'heuristic';
	// Optional existing fields
	code_pattern?: string;
	old_memory?: string;
}

/**
 * Reasoning Memory Payload - Simplified format focusing on reasoning steps and evaluation
 * Append-only, stores raw reasoning steps + evaluation
 */
export interface ReasoningPayload extends BasePayload {
	tags: string[]; // Simplified: ['reasoning']
	// APPEND-ONLY: No event field - always appends new reasoning traces
	// RAW DATA STORAGE: Store complete reasoning steps and evaluation (no extraction)
	reasoningSteps: Array<{
		type: string;
		content: string;
		[key: string]: any; // Preserve any additional step data (except confidence/timestamp)
	}>;
	evaluation: {
		qualityScore: number;
		issues: Array<{
			type: string;
			description: string;
			severity?: string;
			[key: string]: any; // Preserve any additional issue data
		}>;
		suggestions: string[];
		[key: string]: any; // Preserve any additional evaluation data
	};
	context: string; // Single context field for reasoning steps
	stepCount: number; // Computed: reasoningSteps.length
	stepTypes: string[]; // Computed: unique step types
	issueCount: number; // Computed: evaluation.issues.length
	sourceSessionId?: string;
}

/**
 * Create new knowledge payload (V2 format)
 */
export function createKnowledgePayload(
	id: number,
	text: string,
	tags: string[],
	confidence: number,
	event: 'ADD' | 'UPDATE' | 'DELETE' | 'NONE',
	options: {
		domain?: string;
		sourceSessionId?: string;
		qualitySource: 'similarity' | 'llm' | 'heuristic';
		code_pattern?: string;
		old_memory?: string;
		userId?: string;
		projectId?: string;
		workspaceMode?: 'shared' | 'isolated';
	}
): KnowledgePayload {
	// Import env here to avoid circular dependencies
	const { env } = require('../../../../env.js');

	return {
		id,
		text,
		tags,
		confidence,
		event,
		timestamp: new Date().toISOString(),
		version: 2,
		...(options.domain && { domain: options.domain }),
		...(options.sourceSessionId && { sourceSessionId: options.sourceSessionId }),
		qualitySource: options.qualitySource,
		...(options.code_pattern && { code_pattern: options.code_pattern }),
		...(options.old_memory && { old_memory: options.old_memory }),
		// Add cross-tool sharing identifiers (env vars take precedence for security)
		userId: env.CIPHER_USER_ID || options.userId,
		projectId: env.CIPHER_PROJECT_NAME || options.projectId,
		workspaceMode: env.CIPHER_WORKSPACE_MODE || options.workspaceMode || 'isolated',
	};
}

/**
 * Extract knowledge-relevant information from text
 * Minimal fallback parser to avoid storing trivial/noisy data
 */
export function extractKnowledgeInfo(text: string): {
	domain?: string;
	codePattern?: string;
} {
	const result: { domain?: string; codePattern?: string } = {};

	if (!text || typeof text !== 'string') return result;

	// Extract first fenced code block as canonical code pattern
	const fenceMatch = text.match(/```[a-zA-Z0-9]*\n([\s\S]*?)```/);
	if (fenceMatch && fenceMatch[1]) {
		const snippet = fenceMatch[1].trim();
		if (snippet.length > 0 && snippet.length <= 4000) {
			result.codePattern = snippet;
		}
	}

	// Very light domain hinting (kept minimal to avoid noise)
	const lower = text.toLowerCase();
	if (/\b(react|vue|angular|frontend|ui|css|html|typescript|javascript)\b/.test(lower)) {
		result.domain = 'frontend';
	} else if (/\b(node|express|api|backend|django|flask|rails|spring)\b/.test(lower)) {
		result.domain = 'backend';
	} else if (/\b(docker|kubernetes|ci|cd|pipeline|devops|infrastructure)\b/.test(lower)) {
		result.domain = 'devops';
	}

	return result;
}

/**
 * Merge LLM-provided knowledge info with extracted info
 * LLM/agent-provided data takes precedence, extraction fills gaps
 */
export function mergeKnowledgeInfo(
	llmProvided: Partial<{ domain?: string; codePattern?: string }> = {},
	extracted: ReturnType<typeof extractKnowledgeInfo> = {}
): { domain?: string; codePattern?: string } {
	return {
		...((llmProvided.domain || extracted.domain) && {
			domain: llmProvided.domain || extracted.domain,
		}),
		...((llmProvided.codePattern || extracted.codePattern) && {
			codePattern: llmProvided.codePattern || extracted.codePattern,
		}),
	};
}

/**
 * Create new reasoning payload (simplified format)
 */
export function createReasoningPayload(
	id: number,
	text: string,
	reasoningSteps: Array<{
		type: string;
		content: string;
		[key: string]: any;
	}>,
	evaluation: {
		qualityScore: number;
		issues: Array<{
			type: string;
			description: string;
			severity?: string;
			[key: string]: any;
		}>;
		suggestions: string[];
		[key: string]: any;
	},
	context: string,
	options: {
		sourceSessionId?: string;
		userId?: string;
		projectId?: string;
		workspaceMode?: 'shared' | 'isolated';
	} = {}
): ReasoningPayload {
	// Import env here to avoid circular dependencies
	const { env } = require('../../../../env.js');

	// Compute derived metrics from raw data
	const stepCount = reasoningSteps.length;
	const stepTypes = Array.from(new Set(reasoningSteps.map(step => step.type)));
	const issueCount = evaluation.issues.length;

	return {
		id,
		text,
		timestamp: new Date().toISOString(),
		version: 2,
		tags: ['reasoning'],
		reasoningSteps,
		evaluation,
		context,
		stepCount,
		stepTypes,
		issueCount,
		...(options.sourceSessionId && { sourceSessionId: options.sourceSessionId }),
		// Add cross-tool sharing identifiers (env vars take precedence for security)
		userId: env.CIPHER_USER_ID || options.userId,
		projectId: env.CIPHER_PROJECT_NAME || options.projectId,
		workspaceMode: env.CIPHER_WORKSPACE_MODE || options.workspaceMode || 'isolated',
	};
}

import { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';
// Import payload migration utilities
import { KnowledgePayload } from './payloads.js';
import { env } from '../../../../env.js';

/**
 * Memory Search Tool Result Interface
 */
interface MemorySearchResult {
	success: boolean;
	query: string;
	results: Array<{
		id: string;
		text: string;
		tags: string[];
		timestamp: string;
		similarity: number;
		source: 'knowledge';
		memoryType: 'knowledge';
		version?: number;
		// Knowledge memory fields
		confidence?: number;
		reasoning?: string;
		event?: string;
		domain?: string;
		qualitySource?: string;
		code_pattern?: string;
		old_memory?: string;
		sourceSessionId?: string;
	}>;
	metadata: {
		totalResults: number;
		searchTime: number;
		embeddingTime: number;
		maxSimilarity: number;
		minSimilarity: number;
		averageSimilarity: number;
		knowledgeResults: number;
		reflectionResults: number; // Always 0 for knowledge-only search
		searchMode: 'knowledge';
		usedFallback?: boolean;
		queryRefinementApplied?: boolean;
	};
	timestamp: string;
}

/**
 * Memory Search Tool
 *
 * This tool enables semantic retrieval from the agent's knowledge memory system.
 * It searches over stored knowledge memories using vector similarity search
 * and returns relevant entries that can inform the current reasoning process.
 *
 * NOTE: This tool ONLY searches knowledge memory. For reflection memory, use cipher_search_reasoning_patterns.
 */
export const searchMemoryTool: InternalTool = {
	name: 'memory_search',
	category: 'memory',
	internal: true,
	agentAccessible: true, // Agent-accessible: searches knowledge memory only
	description:
		'Perform semantic search over stored knowledge memory entries to retrieve relevant knowledge that can inform current decision-making.',
	version: '1.0.0',
	parameters: {
		type: 'object',
		properties: {
			query: {
				type: 'string',
				description:
					'The search query to find relevant knowledge memories. Use natural language to describe what you are looking for.',
				minLength: 1,
				maxLength: 1000,
			},
			top_k: {
				type: 'number',
				description: 'Maximum number of results to return (default: 5)',
				minimum: 1,
				maximum: 50,
				default: 5,
			},
			similarity_threshold: {
				type: 'number',
				description: 'Minimum similarity score for results (0.0 to 1.0, default: 0.3)',
				minimum: 0.0,
				maximum: 1.0,
				default: 0.3,
			},
			include_metadata: {
				type: 'boolean',
				description: 'Whether to include detailed metadata in results (default: true)',
				default: true,
			},
			enable_query_refinement: {
				type: 'boolean',
				description: 'Whether to apply query refinement for better search results (default: false)',
				default: false,
			},
		},
		required: ['query'],
	},
	handler: async (args: any, context?: InternalToolContext): Promise<MemorySearchResult> => {
		const startTime = Date.now();
		const callId = Math.random().toString(36).substring(7);

		console.log(`🔍 [${callId}] search_memory tool called with:`, {
			query: args.query?.substring(0, 100),
			top_k: args.top_k,
			similarity_threshold: args.similarity_threshold,
			sessionId: context?.sessionId,
			toolName: context?.toolName,
		});

		try {
			logger.debug('MemorySearch: Processing knowledge memory search request', {
				query: args.query?.substring(0, 100) || 'undefined',
				top_k: args.top_k || 5,
				similarity_threshold: args.similarity_threshold || 0.3,
				enable_query_refinement: args.enable_query_refinement !== false,
			});

			// Check if embeddings are disabled for this session
			if (context?.services?.embeddingManager?.getSessionState()?.isDisabled()) {
				const reason = context.services.embeddingManager.getSessionState().getDisabledReason();
				logger.debug(
					'MemorySearch: Embeddings disabled for this session, returning empty results',
					{
						reason,
					}
				);
				return {
					success: true,
					query: args.query || '',
					results: [],
					metadata: {
						totalResults: 0,
						searchTime: Date.now() - startTime,
						embeddingTime: 0,
						maxSimilarity: 0,
						minSimilarity: 0,
						averageSimilarity: 0,
						knowledgeResults: 0,
						reflectionResults: 0,
						searchMode: 'knowledge',
						usedFallback: true,
						queryRefinementApplied: false,
					},
					timestamp: new Date().toISOString(),
				};
			}

			// Check if embedding manager indicates no available embeddings
			if (
				context?.services?.embeddingManager &&
				!context.services.embeddingManager.hasAvailableEmbeddings()
			) {
				logger.debug('MemorySearch: No available embeddings, returning empty results');
				return {
					success: true,
					query: args.query || '',
					results: [],
					metadata: {
						totalResults: 0,
						searchTime: Date.now() - startTime,
						embeddingTime: 0,
						maxSimilarity: 0,
						minSimilarity: 0,
						averageSimilarity: 0,
						knowledgeResults: 0,
						reflectionResults: 0,
						searchMode: 'knowledge',
						usedFallback: true,
						queryRefinementApplied: false,
					},
					timestamp: new Date().toISOString(),
				};
			}

			// Validate required parameters
			if (!args.query || typeof args.query !== 'string' || args.query.trim().length === 0) {
				throw new Error('Query is required and must be a non-empty string');
			}

			// Set defaults
			const originalQuery = args.query.trim();
			const topK = Math.max(1, Math.min(50, args.top_k || 5));
			const similarityThreshold = Math.max(0.0, Math.min(1.0, args.similarity_threshold || 0.3));
			const enableQueryRefinement =
				args.enable_query_refinement === true || env.ENABLE_QUERY_REFINEMENT === true;

			// Get required services from context
			if (!context?.services) {
				throw new Error('InternalToolContext.services is required for memory search');
			}

			const embeddingManager = context.services.embeddingManager;
			const vectorStoreManager = context.services.vectorStoreManager;

			if (!embeddingManager || !vectorStoreManager) {
				throw new Error('EmbeddingManager and VectorStoreManager are required in context.services');
			}

			const embedder = embeddingManager.getEmbedder('default');

			if (
				!embedder?.embed ||
				typeof embedder.embed !== 'function' ||
				!embedder.embedBatch ||
				typeof embedder.embedBatch !== 'function'
			) {
				throw new Error(
					'Embedder is not properly initialized or missing embed() or embedBatch() method'
				);
			}

			// Generate embedding for the search query
			const embeddingStartTime = Date.now();
			logger.debug('MemorySearch: Generating embedding for query', {
				originalQueryLength: originalQuery.length,
				originalQueryPreview: originalQuery.substring(0, 50),
			});

			let finalQuery: string[] = [originalQuery];
			let queryEmbeddings: number[][];
			// Rewrite query if enabled
			try {
				if (enableQueryRefinement) {
					const rewrittenQueries = await rewriteUserQuery(
						originalQuery,
						context.services.llmService
					);
					finalQuery = rewrittenQueries.queries;
				}
				logger.info('Embedding final query:', finalQuery);
				queryEmbeddings = await embedder.embedBatch(finalQuery);
			} catch (embedError) {
				logger.error('MemorySearch: Failed to generate embedding, disabling embeddings globally', {
					error: embedError instanceof Error ? embedError.message : String(embedError),
					provider: embedder.getConfig().type,
				});

				// Immediately disable embeddings globally on first failure
				if (context?.services?.embeddingManager && embedError instanceof Error) {
					context.services.embeddingManager.handleRuntimeFailure(
						embedError,
						embedder.getConfig().type
					);
				}

				// Return empty results since embeddings are now disabled
				return {
					success: true,
					query: args.query || '',
					results: [],
					metadata: {
						totalResults: 0,
						searchTime: Date.now() - startTime,
						embeddingTime: 0,
						maxSimilarity: 0,
						minSimilarity: 0,
						averageSimilarity: 0,
						knowledgeResults: 0,
						reflectionResults: 0,
						searchMode: 'knowledge',
						usedFallback: true,
					},
					timestamp: new Date().toISOString(),
				};
			}

			const embeddingTime = Date.now() - embeddingStartTime;

			logger.debug('MemorySearch: Embedding generated successfully', {
				embeddingTime: `${embeddingTime}ms`,
				embeddingDimensions: Array.isArray(queryEmbeddings[0])
					? queryEmbeddings[0].length
					: 'unknown',
			});
			// Search knowledge memory only
			const searchStartTime = Date.now();
			let allResults: any[] = [];
			let knowledgeResultCount = 0;
			// let reflectionResultCount = 0; // Always 0 for knowledge-only search
			let usedFallback = false;

			// Check if we have a DualCollectionVectorManager
			const isDualManager =
				vectorStoreManager.constructor.name === 'DualCollectionVectorManager' ||
				(typeof vectorStoreManager.getStore === 'function' &&
					vectorStoreManager.getStore.length === 1); // getStore(type) signature

			let knowledgeStore = null;
			if (isDualManager) {
				logger.debug('MemorySearch: Using DualCollectionVectorManager for knowledge search', {
					isDualManager: true,
				});

				try {
					// Try dual manager API first for knowledge collection
					knowledgeStore = (vectorStoreManager as any).getStore('knowledge');
				} catch {
					// Fallback to default store
					try {
						knowledgeStore = vectorStoreManager.getStore();
						usedFallback = true;
					} catch (fallbackError) {
						throw new Error(
							`Knowledge collection failed and fallback to default store also failed: ${fallbackError instanceof Error ? fallbackError.message : String(fallbackError)}`
						);
					}
				}
			} else {
				// Single collection manager - get default store
				logger.debug('MemorySearch: Using single collection manager for knowledge search', {
					isDualManager: false,
				});

				knowledgeStore = vectorStoreManager.getStore();
			}

			if (!knowledgeStore) {
				throw new Error('Knowledge vector store not available');
			}
			// Retrieve knowledge for each query embedding
			for (const queryEmbedding of queryEmbeddings) {
				// Search knowledge collection
				const knowledgeResults = await knowledgeStore.search(queryEmbedding, topK * 2);

				// Mark results with source and add to allResults
				const markedResults = knowledgeResults.map((result: any) => ({
					...result,
					payload: {
						...result.payload,
						source: 'knowledge',
						memoryType: 'knowledge',
					},
				}));

				// Accumulate results instead of overwriting
				allResults.push(...markedResults);

				logger.debug('MemorySearch: Knowledge collection search completed for query embedding', {
					resultsFound: knowledgeResults.length,
					totalAccumulatedResults: allResults.length,
				});
			}

			const searchTime = Date.now() - searchStartTime;
			knowledgeResultCount = allResults.length;
			logger.info('Knowledge results:', allResults);
			logger.debug('MemorySearch: Knowledge search completed for all query embeddings', {
				searchTime: `${searchTime}ms`,
				totalResults: allResults.length,
				knowledgeResults: knowledgeResultCount,
			});

			// Filter, rank, and format knowledge memory results
			const filteredResults = allResults
				.filter(result => {
					// Apply similarity threshold filter
					if ((result.score || 0) < similarityThreshold) return false;

					// Apply cross-tool memory sharing filter if workspace mode is shared
					if (env.CIPHER_WORKSPACE_MODE === 'shared') {
						const payload = result.payload || {};

						// Check if memory matches shared workspace criteria
						const hasMatchingUserId =
							!env.CIPHER_USER_ID || !payload.userId || payload.userId === env.CIPHER_USER_ID;
						const hasMatchingProjectId =
							!env.CIPHER_PROJECT_NAME ||
							!payload.projectId ||
							payload.projectId === env.CIPHER_PROJECT_NAME;
						const isSharedMode = payload.workspaceMode === 'shared';

						// Include memory if:
						// 1. It's marked as shared mode AND (matches user OR project)
						// 2. OR it has no sharing identifiers (legacy memories)
						const shouldInclude =
							(isSharedMode && (hasMatchingUserId || hasMatchingProjectId)) ||
							(!payload.userId && !payload.projectId && !payload.workspaceMode);

						logger.debug('MemorySearch: Cross-tool sharing filter applied', {
							memoryId: result.id,
							memoryUserId: payload.userId,
							memoryProjectId: payload.projectId,
							memoryWorkspaceMode: payload.workspaceMode,
							envUserId: env.CIPHER_USER_ID,
							envProjectId: env.CIPHER_PROJECT_NAME,
							envWorkspaceMode: env.CIPHER_WORKSPACE_MODE,
							shouldInclude,
						});

						return shouldInclude;
					}

					return true; // No filtering in isolated mode
				})
				.sort((a, b) => (b.score || 0) - (a.score || 0)) // Sort by similarity score descending
				.slice(0, topK) // Take top K results overall
				.map(result => {
					const rawPayload = result.payload || {};

					// All data is V2 format after collection cleanup - no migration needed
					const payload = rawPayload as KnowledgePayload;

					// Return unified result format with V2 payload data
					const baseResult = {
						id: result.id || payload.id || 'unknown',
						text: payload.text || 'No content available',
						tags: payload.tags || [],
						timestamp: payload.timestamp || new Date().toISOString(),
						similarity: result.score || 0,
						version: payload.version || 2, // All data is V2 after cleanup
						source: 'knowledge' as const,
						memoryType: 'knowledge' as const,
					};

					// Add knowledge-specific fields
					const knowledgePayload = payload as KnowledgePayload;
					return {
						...baseResult,
						confidence: knowledgePayload.confidence || 0,
						reasoning: 'No reasoning available', // KnowledgePayload doesn't have reasoning field
						event: knowledgePayload.event,
						...(knowledgePayload.domain && { domain: knowledgePayload.domain }),
						qualitySource: knowledgePayload.qualitySource,
						...(knowledgePayload.sourceSessionId && {
							sourceSessionId: knowledgePayload.sourceSessionId,
						}),
						...(knowledgePayload.code_pattern && { code_pattern: knowledgePayload.code_pattern }),
						...(knowledgePayload.old_memory && { old_memory: knowledgePayload.old_memory }),
					};
				});

			// Calculate statistics for knowledge search results
			const totalResults = filteredResults.length;
			const similarities = filteredResults.map(r => r.similarity);
			const maxSimilarity = similarities.length > 0 ? Math.max(...similarities) : 0;
			const minSimilarity = similarities.length > 0 ? Math.min(...similarities) : 0;
			const averageSimilarity =
				similarities.length > 0 ? similarities.reduce((a, b) => a + b, 0) / similarities.length : 0;

			const totalTime = Date.now() - startTime;

			// Prepare result
			const result: MemorySearchResult = {
				success: true,
				query: originalQuery,
				results: filteredResults,
				metadata: {
					totalResults,
					searchTime: totalTime,
					embeddingTime,
					maxSimilarity,
					minSimilarity,
					averageSimilarity,
					knowledgeResults: totalResults, // All results are knowledge results
					reflectionResults: 0, // No reflection results in knowledge-only search
					searchMode: 'knowledge',
					usedFallback,
				},
				timestamp: new Date().toISOString(),
			};

			logger.debug('MemorySearch: Knowledge search completed successfully', {
				query: originalQuery.substring(0, 50),
				resultsFound: totalResults,
				knowledgeResults: totalResults,
				maxSimilarity: maxSimilarity.toFixed(3),
				averageSimilarity: averageSimilarity.toFixed(3),
				totalTime: `${totalTime}ms`,
				usedFallback,
			});
			// Return result to agent
			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			const totalTime = Date.now() - startTime;

			logger.error('MemorySearch: Search failed', {
				error: errorMessage,
				query: args.query?.substring(0, 50) || 'undefined',
				processingTime: `${totalTime}ms`,
			});

			// Check if this is a runtime failure that should disable embeddings globally
			if (context?.services?.embeddingManager && error instanceof Error) {
				const embeddingManager = context.services.embeddingManager;
				if (embeddingManager && typeof embeddingManager.handleRuntimeFailure === 'function') {
					const embedder = embeddingManager.getEmbedder('default');
					const providerType = embedder?.getConfig()?.type || 'unknown';
					embeddingManager.handleRuntimeFailure(error, providerType);
				}
			}

			return {
				success: false,
				query: args.query || 'undefined',
				results: [],
				metadata: {
					totalResults: 0,
					searchTime: totalTime,
					embeddingTime: 0,
					maxSimilarity: 0,
					minSimilarity: 0,
					averageSimilarity: 0,
					knowledgeResults: 0,
					reflectionResults: 0,
					searchMode: 'knowledge',
					usedFallback: true,
				},
				timestamp: new Date().toISOString(),
			};
		}
	},
};

/**
 * Step 1: Rewrite user query into sub-queries and disambiguate ambiguous terms
 * Uses LLM to generate more targeted queries for better retrieval
 *
 * @param originalInput - The original user query to rewrite
 * @param llmService - The LLM service to use for rewriting
 * @returns An object containing the rewritten queries
 */
export async function rewriteUserQuery(
	originalInput: string,
	llmService: any
): Promise<{ queries: string[] }> {
	try {
		const rewritePrompt = `
        You are a query decomposition and disambiguation expert. Break down this question into search queries for a knowledge base while handling ambiguous terms.

        QUESTION: "${originalInput}"

		TASK: Create 2-5 concise search queries that capture the core information needs of the question.

		GUIDELINES:
		- Focus on the main intent of the question.
		- Use natural, searchable language (4-15 words per query).
		- Only create disambiguation queries for clearly ambiguous terms.
		- Avoid over-decomposing the question into too many subqueries.
		- Prefer fewer, more precise queries over exhaustive coverage.
		- Each query should stand alone and be understandable without additional context.

		DISAMBIGUATION (Only if needed):
		- For truly ambiguous terms (homonyms, abbreviations, etc.), include 1-2 alternate queries with different meanings.
		- Do not force disambiguation where the meaning is already clear from context.

        OUTPUT FORMAT:
        Respond with ONLY the queries, one per line, using this exact format:
        Query 1: [first query]
        Query 2: [second query]
        [continue as needed...]

        Do not include any explanations, introductions, or other text. Only the queries.

        EXAMPLES:
        Question: "What profession does Nicholas Ray and Elia Kazan have in common?"
        Query 1: Nicholas Ray profession career
        Query 2: Elia Kazan profession career

        Question: "Most total goals in a premier league season?"
        Query 1: Most total goals in a premier league season by a team
        Query 2: Most total goals in a premier league season by a player

        Now decompose and disambiguate: "${originalInput}"
        `;
		const rewriteResponse = await llmService.directGenerate(rewritePrompt);

		// Parse the response to extract individual queries
		const queries = rewriteResponse
			.split('\n')
			.map((line: string) => line.trim())
			.filter((line: string) => line.length > 0)
			.map((line: string) => {
				// Extract query content after "Query X:" prefix
				const match = line.match(/^Query\s*\d+:\s*(.+)$/i);
				return match && match[1] ? match[1].trim() : null;
			})
			.filter((query: string | null) => query !== null && query.length >= 3)
			.filter(
				(query: string | null, index: number, array: (string | null)[]) =>
					array.indexOf(query) === index
			); // Remove duplicates

		logger.info(`Parsed queries:`, {
			queries: queries,
			queryCount: queries.length,
		});
		// Ensure we have at least one query (fallback to original)
		if (queries.length === 0) {
			return {
				queries: [originalInput],
			};
		}

		return {
			queries: queries,
		};
	} catch (error) {
		logger.warn('MemorySearch: Query rewriting failed', {
			originalInput: originalInput.substring(0, 100),
			error: error instanceof Error ? error.message : String(error),
		});
		return {
			queries: [originalInput],
		};
	}
}

import { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';
import { env } from '../../../../env.js';
// Import payload migration utilities
import { createReasoningPayload } from './payloads.js';

/**
 * Generate safer memory ID to avoid vector store insert failures
 * Uses range 666667-999999 for unified reasoning entries
 */
function generateSafeReasoningMemoryId(index: number): number {
	// Use timestamp-based approach to avoid conflicts
	// Range: 666667-999999 for unified reasoning entries
	const now = Date.now();
	const randomSuffix = Math.floor(Math.random() * 1000); // 0-999
	let vectorId = 666667 + (((now % 300000) * 1000 + randomSuffix + index) % 333333);

	// Ensure it's in the correct range
	if (vectorId <= 666666 || vectorId > 999999) {
		vectorId = Math.floor(Math.random() * 333333) + 666667;
	}

	return vectorId;
}

/**
 * Store Reasoning Memory Tool
 *
 * Stores reasoning traces and their evaluations as unified entries in the reflection vector store.
 * This ensures atomic storage and retrieval - you always get both reasoning steps and evaluation together.
 * This is an append-only operation that takes the complete trace output from cipher_extract_reasoning_steps
 * (which includes automatically extracted task context) and evaluation from cipher_evaluate_reasoning.
 */
export const storeReasoningMemoryTool: InternalTool = {
	name: 'store_reasoning_memory',
	category: 'memory',
	internal: true,
	agentAccessible: false, // Internal-only: programmatically called when reasoning content is detected
	description:
		'Store complete reasoning traces with task context and evaluations in reflection memory. Takes trace with auto-extracted context from cipher_extract_reasoning_steps and evaluation from cipher_evaluate_reasoning. Append-only operation.',
	version: '2.1.0',
	parameters: {
		type: 'object',
		properties: {
			trace: {
				type: 'object',
				description:
					'Complete reasoning trace from cipher_extract_reasoning_steps (includes steps and metadata with task context)',
				properties: {
					id: { type: 'string' },
					steps: {
						type: 'array',
						items: {
							type: 'object',
							properties: {
								type: {
									type: 'string',
									enum: [
										'thought',
										'action',
										'observation',
										'decision',
										'conclusion',
										'reflection',
									],
								},
								content: { type: 'string' },
							},
							required: ['type', 'content'],
						},
					},
					metadata: {
						type: 'object',
						properties: {
							extractedAt: { type: 'string' },
							conversationLength: { type: 'number' },
							stepCount: { type: 'number' },
							hasExplicitMarkup: { type: 'boolean' },
							sessionId: { type: 'string' },
							taskContext: {
								type: 'object',
								properties: {
									goal: { type: 'string', description: 'What the agent was trying to achieve' },
									input: {
										type: 'string',
										description: 'Original user request or problem statement',
									},
									taskType: {
										type: 'string',
										description: 'Type of task (e.g., code_generation, analysis, problem_solving)',
									},
									domain: {
										type: 'string',
										description: 'Problem domain (e.g., programming, math, planning)',
									},
									complexity: {
										type: 'string',
										enum: ['low', 'medium', 'high'],
										description: 'Task complexity level',
									},
								},
							},
						},
					},
				},
				required: ['id', 'steps', 'metadata'],
			},
			evaluation: {
				type: 'object',
				description: 'Quality evaluation of the reasoning trace from cipher_evaluate_reasoning',
				properties: {
					qualityScore: { type: 'number', minimum: 0, maximum: 1 },
					efficiencyScore: { type: 'number', minimum: 0, maximum: 1 },
					issues: {
						type: 'array',
						items: {
							type: 'object',
							properties: {
								type: { type: 'string' },
								description: { type: 'string' },
								severity: { type: 'string', enum: ['low', 'medium', 'high'] },
							},
						},
					},
					suggestions: { type: 'array', items: { type: 'string' } },
					shouldStore: { type: 'boolean' },
				},
				required: ['qualityScore', 'issues', 'suggestions'],
			},
		},
		required: ['trace', 'evaluation'],
	},
	handler: async (args: any, context?: InternalToolContext) => {
		const startTime = Date.now();

		logger.debug('StoreReasoningMemory: Processing unified reasoning storage request', {
			traceId: args.trace?.id || args.trace?.result?.trace?.id,
			stepCount: args.trace?.steps?.length || args.trace?.result?.trace?.steps?.length || 0,
			qualityScore:
				args.evaluation?.qualityScore || args.evaluation?.result?.evaluation?.qualityScore,
			hasTrace: !!args.trace,
			hasEvaluation: !!args.evaluation,
			hasTaskContext: !!(
				args.trace?.metadata?.taskContext || args.trace?.result?.trace?.metadata?.taskContext
			),
		});

		// Handle wrapped tool results (extraction/evaluation tools return { result: { trace/evaluation } })
		let trace = args.trace;
		let evaluation = args.evaluation;

		try {
			// Validate basic arguments
			if (!args) {
				throw new Error('No arguments provided to StoreReasoningMemory');
			}

			// Enhanced validation with better error messages and fallback handling
			const validationErrors: string[] = [];

			// Unwrap trace if it comes from extraction tool result
			if (args.trace && args.trace.result && args.trace.result.trace) {
				trace = args.trace.result.trace;
				logger.debug('StoreReasoningMemory: Unwrapped trace from extraction tool result');
			}

			// Unwrap evaluation if it comes from evaluation tool result
			if (args.evaluation && args.evaluation.result && args.evaluation.result.evaluation) {
				evaluation = args.evaluation.result.evaluation;
				logger.debug('StoreReasoningMemory: Unwrapped evaluation from evaluation tool result');
			}

			// Validate trace parameter
			if (!trace) {
				validationErrors.push(
					'trace parameter is missing - ensure cipher_extract_reasoning_steps was called successfully'
				);
			} else if (typeof trace !== 'object') {
				validationErrors.push('trace must be an object');
			} else {
				if (!trace.steps) {
					validationErrors.push('trace.steps is missing - invalid reasoning trace');
				} else if (!Array.isArray(trace.steps)) {
					validationErrors.push('trace.steps must be an array');
				} else if (trace.steps.length === 0) {
					validationErrors.push('trace.steps array is empty - no reasoning steps to store');
				}

				if (!trace.metadata) {
					validationErrors.push('trace.metadata is missing - invalid reasoning trace');
				}
			}

			// Validate evaluation parameter
			if (!evaluation) {
				validationErrors.push(
					'evaluation parameter is missing - ensure cipher_evaluate_reasoning was called successfully'
				);
			} else if (typeof evaluation !== 'object') {
				validationErrors.push('evaluation must be an object');
			}

			// If we have validation errors, provide detailed feedback about the pipeline failure
			if (validationErrors.length > 0) {
				const errorMessage = `Pipeline validation failed: ${validationErrors.join('; ')}`;
				logger.warn('StoreReasoningMemory: Validation failed, suggesting pipeline check', {
					errors: validationErrors,
					hasTrace: !!trace,
					hasEvaluation: !!evaluation,
					pipelineStage: !trace
						? 'extraction_failed'
						: !evaluation
							? 'evaluation_failed'
							: 'unknown',
				});

				return {
					success: false,
					result: {
						error: errorMessage,
						stored: false,
						validationErrors,
						suggestion:
							'Ensure both cipher_extract_reasoning_steps and cipher_evaluate_reasoning completed successfully before calling store_reasoning_memory',
					},
					metadata: {
						toolName: 'store_reasoning_memory',
						validationFailed: true,
						errors: validationErrors,
						missingDependencies: {
							trace: !trace,
							evaluation: !evaluation,
						},
					},
				};
			}

			// Additional safety checks for array elements
			const validSteps = trace.steps.filter(
				(step: any) => step && typeof step === 'object' && step.content && step.type
			);

			if (validSteps.length === 0) {
				logger.warn('StoreReasoningMemory: No valid reasoning steps found after filtering');
				return {
					success: false,
					result: {
						error:
							'No valid reasoning steps found - all steps are missing required fields (type, content)',
						stored: false,
					},
					metadata: {
						toolName: 'store_reasoning_memory',
						invalidSteps: true,
						originalStepCount: trace.steps.length,
						validStepCount: 0,
					},
				};
			}

			// Log if we filtered out some invalid steps
			if (validSteps.length < trace.steps.length) {
				logger.debug('StoreReasoningMemory: Filtered out invalid reasoning steps', {
					originalCount: trace.steps.length,
					validCount: validSteps.length,
					filteredCount: trace.steps.length - validSteps.length,
				});
			}

			// Check if should store based on evaluation
			if (evaluation.shouldStore === false) {
				logger.debug(
					'StoreReasoningMemory: Skipping storage - evaluation indicates should not store',
					{
						success: true,
						qualityScore: evaluation.qualityScore,
						shouldStore: evaluation.shouldStore,
					}
				);
				return {
					success: true,
					result: {
						message: 'Storage skipped - quality threshold not met',
						stored: false,
					},
					metadata: {
						toolName: 'store_reasoning_memory',
						skipped: true,
						reason: 'quality_threshold',
						qualityScore: evaluation.qualityScore,
					},
				};
			}

			// Enhanced service availability checking with fallback handling
			if (!context?.services) {
				logger.warn('StoreReasoningMemory: No services context available');
				return {
					success: false,
					result: {
						error: 'Services context is required for reasoning storage',
						stored: false,
					},
					metadata: {
						toolName: 'store_reasoning_memory',
						missingServices: true,
					},
				};
			}

			const embeddingManager = context.services.embeddingManager;
			const vectorStoreManager = context.services.vectorStoreManager;

			if (!embeddingManager || !vectorStoreManager) {
				logger.warn('StoreReasoningMemory: Required services not available');
				return {
					success: false,
					result: {
						error: 'EmbeddingManager and VectorStoreManager are required for reasoning storage',
						stored: false,
					},
					metadata: {
						toolName: 'store_reasoning_memory',
						missingEmbeddingManager: !embeddingManager,
						missingVectorStoreManager: !vectorStoreManager,
					},
				};
			}

			// Get reflection store from dual collection manager with enhanced error handling
			let reflectionStore = null;
			try {
				logger.debug('StoreReasoningMemory: Using dedicated reflection collection');
				reflectionStore = (vectorStoreManager as any).getStore('reflection');
			} catch (error) {
				logger.error('StoreReasoningMemory: Failed to get reflection store', {
					error: error instanceof Error ? error.message : String(error),
					hasVectorStoreManager: !!vectorStoreManager,
				});
				// For integration test mocks, fallback to default store
				if (typeof (vectorStoreManager as any).getStore === 'function') {
					reflectionStore = (vectorStoreManager as any).getStore();
				}
			}

			if (!reflectionStore) {
				logger.warn('StoreReasoningMemory: Reflection store not available');
				// For integration test mocks, fallback to default store
				if (typeof (vectorStoreManager as any).getStore === 'function') {
					reflectionStore = (vectorStoreManager as any).getStore();
				}
				if (!reflectionStore) {
					return {
						success: false,
						result: {
							error: 'Reflection vector store not available',
							stored: false,
						},
						metadata: {
							toolName: 'store_reasoning_memory',
							reflectionStoreUnavailable: true,
						},
					};
				}
			}

			const embedder = embeddingManager.getEmbedder('default');
			if (!embedder) {
				logger.warn('StoreReasoningMemory: Embedder not available');
				return {
					success: false,
					result: {
						error: 'Embedder not available for reasoning storage',
						stored: false,
					},
					metadata: {
						toolName: 'store_reasoning_memory',
						embedderUnavailable: true,
					},
				};
			}

			if (!embedder.embed || typeof embedder.embed !== 'function') {
				throw new Error('Embedder is not properly initialized or missing embed() method');
			}

			// Use trace ID from extraction step and generate vector ID
			const vectorId = generateSafeReasoningMemoryId(0);

			// Calculate derived metrics using validated steps
			// Note: confidence field removed from steps as per new requirements

			// const stepTypes = Array.from(new Set(validSteps.map((step: any) => step.type))) as string[];

			// Create simplified searchable content focusing on reasoning steps and evaluation
			const searchableContent = [
				// Core reasoning steps (most important for similarity search)
				...validSteps.map((step: any) => `${step.type}: ${step.content}`),
				// Quality score for filtering
				`Quality: ${evaluation.qualityScore.toFixed(2)}`,
			].join(' ');

			// Generate a context string for the reasoning trace
			let contextString = '';
			if (trace.metadata?.taskContext?.goal) {
				contextString = String(trace.metadata.taskContext.goal);
			} else if (trace.metadata?.taskContext?.input) {
				contextString = String(trace.metadata.taskContext.input);
			} else if (typeof args.userInput === 'string') {
				contextString = args.userInput.slice(0, 100);
			} else {
				contextString = 'No context provided';
			}

			logger.debug('StoreReasoningMemory: Generating embedding for unified reasoning content', {
				traceId: trace.id,
				vectorId,
				contentLength: searchableContent.length,
				stepCount: validSteps.length,
				qualityScore: evaluation.qualityScore,
			});

			// Generate embedding with error handling
			let embedding;
			try {
				embedding = await embedder.embed(searchableContent);
			} catch (embedError) {
				logger.error(
					'StoreReasoningMemory: Failed to generate embedding, disabling embeddings globally',
					{
						error: embedError instanceof Error ? embedError.message : String(embedError),
						contentLength: searchableContent.length,
						provider: embedder.getConfig().type,
					}
				);

				// Immediately disable embeddings globally on first failure
				if (context?.services?.embeddingManager && embedError instanceof Error) {
					context.services.embeddingManager.handleRuntimeFailure(
						embedError,
						embedder.getConfig().type
					);
				}

				// Return error response since embeddings are now disabled
				return {
					success: false,
					message: `Embeddings disabled due to failure: ${embedError instanceof Error ? embedError.message : String(embedError)}`,
					mode: 'chat-only',
					error: embedError instanceof Error ? embedError.message : String(embedError),
					metadata: {
						toolName: 'store_reasoning_memory',
						embeddingDisabled: true,
					},
				};
			}

			// CRITICAL: Ensure all data types are correct (avoid string numbers like "0.6")
			const safeQualityScore =
				typeof evaluation.qualityScore === 'number'
					? evaluation.qualityScore
					: parseFloat(String(evaluation.qualityScore)) || 0.5;

			// Validate quality score is a valid number
			if (isNaN(safeQualityScore) || !isFinite(safeQualityScore)) {
				logger.warn('StoreReasoningMemory: Invalid quality score, using fallback', {
					originalValue: evaluation.qualityScore,
					originalType: typeof evaluation.qualityScore,
					fallbackValue: 0.5,
				});
			}

			// Create simplified reasoning payload focusing only on reasoning steps, evaluation, and context
			const payload = createReasoningPayload(
				vectorId,
				String(searchableContent),
				validSteps, // Raw reasoning steps
				{
					qualityScore: Math.max(0, Math.min(1, safeQualityScore)),
					issues: evaluation.issues,
					suggestions: evaluation.suggestions,
				},
				contextString,
				{
					sourceSessionId: trace.metadata.sessionId || context?.sessionId,
				}
			);

			// Enhanced validation before insert with detailed debug logging
			logger.debug('StoreReasoningMemory: Pre-insert validation and analysis', {
				traceId: trace.id,
				vectorId,
				vectorIdType: typeof vectorId,
				vectorIdIsInteger: Number.isInteger(vectorId),
				vectorIdRange: `${vectorId} (should be 666667-999999)`,
				vectorIdValid: Number.isInteger(vectorId) && vectorId >= 666667 && vectorId <= 999999,
				embeddingType: typeof embedding,
				embeddingIsArray: Array.isArray(embedding),
				embeddingLength: Array.isArray(embedding) ? embedding.length : 'not-array',
				embeddingFirstFew: Array.isArray(embedding) ? embedding.slice(0, 3) : 'not-array',
				payloadType: typeof payload,
				payloadKeys: Object.keys(payload),
				payloadSize: JSON.stringify(payload).length,
				payloadIdType: typeof payload.id,
				payloadIdValue: payload.id,
				contentLength: searchableContent.length,
				stepCount: validSteps.length,
			});

			// Detailed validation with specific error messages
			if (!Array.isArray(embedding)) {
				const errorMsg = `Invalid embedding: expected array, got ${typeof embedding}`;
				logger.error('StoreReasoningMemory: Embedding validation failed', {
					error: errorMsg,
					embeddingType: typeof embedding,
					embeddingValue: embedding,
				});
				throw new Error(errorMsg);
			}

			if (embedding.length === 0) {
				const errorMsg = 'Invalid embedding: array is empty';
				logger.error('StoreReasoningMemory: Embedding validation failed', {
					error: errorMsg,
					embeddingLength: embedding.length,
				});
				throw new Error(errorMsg);
			}

			// Validate embedding contains valid numbers
			const invalidEmbeddingElements = embedding.filter(
				(val, _idx) => typeof val !== 'number' || isNaN(val) || !isFinite(val)
			);
			if (invalidEmbeddingElements.length > 0) {
				const errorMsg = `Invalid embedding: contains ${invalidEmbeddingElements.length} non-numeric/invalid values`;
				logger.error('StoreReasoningMemory: Embedding validation failed', {
					error: errorMsg,
					invalidCount: invalidEmbeddingElements.length,
					firstInvalid: invalidEmbeddingElements.slice(0, 3),
					embeddingLength: embedding.length,
				});
				throw new Error(errorMsg);
			}

			if (!Number.isInteger(vectorId)) {
				const errorMsg = `Invalid vector ID: expected integer, got ${typeof vectorId} (${vectorId})`;
				logger.error('StoreReasoningMemory: Vector ID validation failed', {
					error: errorMsg,
					vectorId,
					vectorIdType: typeof vectorId,
					isInteger: Number.isInteger(vectorId),
				});
				throw new Error(errorMsg);
			}

			if (vectorId <= 0) {
				const errorMsg = `Invalid vector ID: must be positive, got ${vectorId}`;
				logger.error('StoreReasoningMemory: Vector ID validation failed', {
					error: errorMsg,
					vectorId,
					isPositive: vectorId > 0,
				});
				throw new Error(errorMsg);
			}

			// Validate vector ID is in expected range for reasoning entries
			if (vectorId < 666667 || vectorId > 999999) {
				logger.warn('StoreReasoningMemory: Vector ID outside expected range', {
					vectorId,
					expectedRange: '666667-999999',
					actualRange: `${vectorId}`,
					willProceed: true,
				});
			}

			// Validate payload structure
			if (typeof payload !== 'object' || payload === null) {
				const errorMsg = `Invalid payload: expected object, got ${typeof payload}`;
				logger.error('StoreReasoningMemory: Payload validation failed', {
					error: errorMsg,
					payloadType: typeof payload,
					payload,
				});
				throw new Error(errorMsg);
			}

			// Validate payload.id matches vectorId
			if (payload.id !== vectorId) {
				const errorMsg = `Payload ID mismatch: payload.id=${payload.id}, vectorId=${vectorId}`;
				logger.error('StoreReasoningMemory: Payload ID validation failed', {
					error: errorMsg,
					payloadId: payload.id,
					vectorId: vectorId,
					payloadIdType: typeof payload.id,
					vectorIdType: typeof vectorId,
				});
				throw new Error(errorMsg);
			}

			// CRITICAL: Check collection existence and configuration with auto-creation
			let collectionExists = false;
			let collectionInfo = null;
			let collectionCreated = false;

			try {
				// Try to get collection info to verify it exists and is properly configured
				const reflectionCollectionName = env.REFLECTION_VECTOR_STORE_COLLECTION;

				// Method 1: Try backend collection info
				if (typeof reflectionStore.getCollectionInfo === 'function') {
					collectionInfo = await reflectionStore.getCollectionInfo();
					collectionExists = true;
					logger.debug('StoreReasoningMemory: Collection exists and accessible', {
						collectionName: reflectionCollectionName,
						vectorsCount: collectionInfo?.vectors_count || 'unknown',
						status: collectionInfo?.status || 'unknown',
					});
				}
				// Method 2: Direct Qdrant client access
				else if (typeof (reflectionStore as any).client?.getCollection === 'function') {
					const collection = await (reflectionStore as any).client.getCollection(
						reflectionCollectionName
					);
					collectionExists = true;
					collectionInfo = collection;
					logger.debug('StoreReasoningMemory: Collection verified via direct client', {
						collectionName: reflectionCollectionName,
						config: collection?.result?.config || 'unknown',
					});
				}
				// Method 3: Try a simple health check
				else if (typeof reflectionStore.isConnected === 'function') {
					collectionExists = reflectionStore.isConnected();
					logger.debug('StoreReasoningMemory: Collection status via isConnected', {
						collectionName: reflectionCollectionName,
						connected: collectionExists,
					});
				}
			} catch (collectionError) {
				logger.error(
					'StoreReasoningMemory: Collection verification failed - attempting auto-creation',
					{
						error:
							collectionError instanceof Error ? collectionError.message : String(collectionError),
						collectionName: env.REFLECTION_VECTOR_STORE_COLLECTION,
						errorType:
							collectionError instanceof Error
								? collectionError.constructor.name
								: typeof collectionError,
					}
				);

				// EMERGENCY: Try to create/recreate the collection
				try {
					console.error('=== COLLECTION AUTO-CREATION ATTEMPT ===');
					console.error(
						'Collection Error:',
						collectionError instanceof Error ? collectionError.message : String(collectionError)
					);
					console.error('Attempting to create collection:', env.REFLECTION_VECTOR_STORE_COLLECTION);

					// Get the DualCollectionVectorManager and try to reinitialize
					const dualManager = vectorStoreManager as any;
					if (dualManager && typeof dualManager.getManager === 'function') {
						const reflectionManager = dualManager.getManager('reflection');
						if (reflectionManager && typeof reflectionManager.connect === 'function') {
							console.error('Attempting to reconnect reflection manager...');
							await reflectionManager.connect();
							collectionCreated = true;
							collectionExists = true;
							console.error('Collection creation/reconnection successful!');
						}
					}

					console.error('======================================');
				} catch (creationError) {
					console.error('=== COLLECTION CREATION FAILED ===');
					console.error(
						'Creation Error:',
						creationError instanceof Error ? creationError.message : String(creationError)
					);
					console.error('Root cause: Collection does not exist and cannot be created');
					console.error('==================================');

					// This is likely the root cause of the "Bad Request" error
					throw new Error(
						`Reflection collection '${env.REFLECTION_VECTOR_STORE_COLLECTION}' does not exist and cannot be created: ${creationError instanceof Error ? creationError.message : String(creationError)}`
					);
				}
			}

			// Get reflection store info for debugging
			const storeInfo = {
				storeType: typeof reflectionStore,
				hasInsertMethod: typeof reflectionStore.insert === 'function',
				storeConstructor: reflectionStore.constructor?.name,
				isConnected:
					typeof reflectionStore.isConnected === 'function'
						? reflectionStore.isConnected()
						: 'unknown',
				collectionExists,
				collectionCreated,
				collectionName: env.REFLECTION_VECTOR_STORE_COLLECTION,
				collectionInfo: collectionInfo ? 'available' : 'not_available',
			};

			logger.debug('StoreReasoningMemory: Reflection store analysis', {
				traceId: trace.id,
				vectorId,
				storeInfo,
				embeddingLength: embedding.length,
				payloadKeys: Object.keys(payload).length,
				payloadSummary: {
					id: payload.id,
					qualityScore: payload.evaluation.qualityScore,
					stepCount: payload.stepCount,
					textLength: payload.text?.length || 0,
					tagsCount: Array.isArray(payload.tags) ? payload.tags.length : 'not_array',
				},
			});

			logger.debug('StoreReasoningMemory: Attempting vector store insert', {
				traceId: trace.id,
				vectorId,
				operation: 'reflectionStore.insert',
				parameters: {
					embeddings: `Array[${embedding.length}]`,
					ids: `[${vectorId}]`,
					payloads: `[Object with ${Object.keys(payload).length} keys]`,
				},
			});
			// console.log('Store Reasoning Memory Payload:', payload);
			// Store in reflection vector database using exact same pattern as successful function
			try {
				await reflectionStore.insert([embedding], [vectorId], [payload]);

				logger.debug('StoreReasoningMemory: Vector store insert successful', {
					traceId: trace.id,
					vectorId,
					insertedSuccessfully: true,
					embeddingLength: embedding.length,
					payloadSize: JSON.stringify(payload).length,
				});

				logger.debug('StoreReasoningMemory: ADD operation completed', {
					memoryId: vectorId,
					textPreview:
						searchableContent.substring(0, 60) + (searchableContent.length > 60 ? '...' : ''),
					stepCount: validSteps.length,
					qualityScore: evaluation.qualityScore.toFixed(3),
				});
			} catch (insertError) {
				// EMERGENCY DIAGNOSTIC: Output to console for immediate visibility
				console.error('=== EMERGENCY DIAGNOSTIC ===');
				console.error('Vector Store Insert Failed - Full Analysis:');
				console.error(
					'VectorId:',
					vectorId,
					'Type:',
					typeof vectorId,
					'IsInteger:',
					Number.isInteger(vectorId)
				);
				console.error(
					'Embedding Length:',
					Array.isArray(embedding) ? embedding.length : 'NOT_ARRAY'
				);
				console.error('Payload Keys:', Object.keys(payload));
				console.error('Payload.id:', payload.id, 'Type:', typeof payload.id);
				console.error('Store Type:', reflectionStore.constructor?.name);
				console.error('Collection Name:', env.REFLECTION_VECTOR_STORE_COLLECTION);
				console.error('Collection Exists:', collectionExists);
				console.error('Collection Created:', collectionCreated);
				console.error('Expected Vector Dimension:', env.VECTOR_STORE_DIMENSION);
				console.error(
					'Actual Embedding Dimension:',
					Array.isArray(embedding) ? embedding.length : 'NOT_ARRAY'
				);
				console.error(
					'Dimension Match:',
					Array.isArray(embedding) && embedding.length === env.VECTOR_STORE_DIMENSION
				);
				console.error(
					'Insert Error:',
					insertError instanceof Error ? insertError.message : String(insertError)
				);

				// EXTRACT UNDERLYING QDRANT ERROR
				const underlyingError = (insertError as any)?.cause || (insertError as any)?.originalError;
				if (underlyingError) {
					console.error(
						'Underlying Qdrant Error:',
						underlyingError instanceof Error ? underlyingError.message : String(underlyingError)
					);
					console.error(
						'Qdrant Error Stack:',
						underlyingError instanceof Error ? underlyingError.stack : 'No stack available'
					);
				}

				// FULL ERROR OBJECT INSPECTION
				console.error(
					'Full Error Object:',
					JSON.stringify(
						{
							message: insertError instanceof Error ? insertError.message : String(insertError),
							name: (insertError as any)?.name,
							cause: (insertError as any)?.cause?.message || 'No cause',
							stack:
								insertError instanceof Error
									? insertError.stack?.split('\n').slice(0, 3).join('\n')
									: 'No stack',
						},
						null,
						2
					)
				);

				console.error('===========================');
				// Super detailed error logging for debugging
				const detailedError =
					insertError instanceof Error ? insertError.message : String(insertError);
				const errorStack = insertError instanceof Error ? insertError.stack : undefined;

				logger.debug('StoreReasoningMemory: Detailed insert failure analysis', {
					traceId: trace.id,
					vectorId,
					errorType:
						insertError instanceof Error ? insertError.constructor.name : typeof insertError,
					errorMessage: detailedError,
					errorStack: errorStack?.split('\n').slice(0, 5).join('\n'), // First 5 lines of stack
					insertCallParameters: {
						embeddingsParam: {
							type: typeof [embedding],
							isArray: Array.isArray([embedding]),
							length: [embedding].length,
							firstElementType: typeof embedding,
							firstElementIsArray: Array.isArray(embedding),
							firstElementLength: Array.isArray(embedding) ? embedding.length : 'not-array',
						},
						idsParam: {
							type: typeof [vectorId],
							isArray: Array.isArray([vectorId]),
							length: [vectorId].length,
							firstElement: vectorId,
							firstElementType: typeof vectorId,
							firstElementIsInteger: Number.isInteger(vectorId),
						},
						payloadsParam: {
							type: typeof [payload],
							isArray: Array.isArray([payload]),
							length: [payload].length,
							firstElement: payload,
							firstElementType: typeof payload,
							firstElementKeys: Object.keys(payload),
						},
					},
					reflectionStoreInfo: storeInfo,
					possibleCauses: [
						'Qdrant collection not found or not accessible',
						'Vector dimension mismatch',
						'Payload contains invalid field types',
						'Connection timeout or network issue',
						'Insufficient permissions or API key issues',
						'Collection schema validation failed',
					],
				});

				logger.error(
					'StoreReasoningMemory: Vector store insert failed with comprehensive details',
					{
						traceId: trace.id,
						vectorId,
						vectorIdValid: Number.isInteger(vectorId) && vectorId > 0,
						vectorIdInRange: vectorId >= 666667 && vectorId <= 999999,
						embeddingValid: Array.isArray(embedding) && embedding.length > 0,
						embeddingLength: Array.isArray(embedding) ? embedding.length : 'not-array',
						embeddingHasValidNumbers:
							Array.isArray(embedding) &&
							embedding.every(x => typeof x === 'number' && isFinite(x)),
						payloadValid: typeof payload === 'object' && payload !== null,
						payloadSize: JSON.stringify(payload).length,
						payloadIdMatches: payload.id === vectorId,
						originalError: detailedError,
						errorType:
							insertError instanceof Error ? insertError.constructor.name : typeof insertError,
						storeConnected: storeInfo.isConnected,
					}
				);

				throw new Error(`Vector store insert failed: ${detailedError}`);
			}

			const processingTime = Date.now() - startTime;

			logger.debug(
				'StoreReasoningMemory: Successfully stored unified reasoning entry with task context',
				{
					traceId: trace.id,
					vectorId,
					stepCount: validSteps.length,
					qualityScore: evaluation.qualityScore.toFixed(3),
					issueCount: evaluation.issues.length,
					suggestionCount: evaluation.suggestions.length,
					taskType: trace.metadata.taskContext?.taskType,
					domain: trace.metadata.taskContext?.domain,
					processingTime: `${processingTime}ms`,
				}
			);

			return {
				success: true,
				result: {
					message: 'Reasoning trace with task context and evaluation stored successfully',
					stored: true,
					traceId: trace.id,
					vectorId,
					taskContext: trace.metadata.taskContext,
					metrics: {
						stepCount: validSteps.length,
						qualityScore: evaluation.qualityScore,
						issueCount: evaluation.issues.length,
					},
				},
				metadata: {
					toolName: 'store_reasoning_memory',
					traceId: trace.id,
					vectorId,
					processingTime,
					hasTaskContext: !!trace.metadata.taskContext,
				},
			};
		} catch (error) {
			const processingTime = Date.now() - startTime;
			const errorMessage = error instanceof Error ? error.message : String(error);

			logger.error('StoreReasoningMemory: Failed to store unified reasoning entry', {
				error: errorMessage,
				stepCount: trace?.steps?.length || 0,
				qualityScore: evaluation?.qualityScore,
				processingTime: `${processingTime}ms`,
			});

			return {
				success: false,
				result: {
					error: `Failed to store reasoning: ${errorMessage}`,
					stored: false,
				},
				metadata: {
					toolName: 'store_reasoning_memory',
					error: errorMessage,
					processingTime,
				},
			};
		}
	},
};

import { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';
import { WorkspacePayload } from './workspace-payloads.js';
import { env } from '../../../../env.js';
import { rewriteUserQuery } from './search_memory.js';
/**
 * Workspace Search Result Interface
 */
interface WorkspaceSearchResult {
	success: boolean;
	query: string;
	results: Array<{
		id: string;
		text: string;
		tags: string[];
		timestamp: string;
		similarity: number;
		source: 'workspace';
		memoryType: 'workspace';
		version?: number;
		// Workspace-specific fields
		teamMember?: string;
		currentProgress?: {
			feature: string;
			status: 'in-progress' | 'completed' | 'blocked' | 'reviewing';
			completion?: number;
		};
		bugsEncountered?: Array<{
			description: string;
			severity: 'low' | 'medium' | 'high' | 'critical';
			status: 'open' | 'in-progress' | 'fixed';
		}>;
		workContext?: {
			project?: string;
			repository?: string;
			branch?: string;
		};
		confidence?: number;
		event?: string;
		domain?: string;
		qualitySource?: string;
		sourceSessionId?: string;
	}>;
	metadata: {
		totalResults: number;
		searchTime: number;
		embeddingTime: number;
		maxSimilarity: number;
		minSimilarity: number;
		averageSimilarity: number;
		workspaceResults: number;
		searchMode: 'workspace';
		usedFallback?: boolean;
		filters?: {
			domain?: string;
			teamMember?: string;
			project?: string;
		};
	};
	timestamp: string;
}

/**
 * Workspace Search Tool
 *
 * This tool enables semantic retrieval from the workspace memory system.
 * It searches over stored workspace memories including team progress, project information,
 * bug reports, and collaboration context using vector similarity search.
 */
export const workspaceSearchTool: InternalTool = {
	name: 'workspace_search',
	category: 'memory',
	internal: true,
	agentAccessible: true, // Agent-accessible: searches workspace memory only
	description:
		'Search workspace memory for team and project information including progress, bugs, and collaboration context.',
	version: '1.0.0',
	parameters: {
		type: 'object',
		properties: {
			query: {
				type: 'string',
				description:
					'The search query to find relevant workspace memories. Use natural language to describe team activities, project progress, or collaboration context.',
				minLength: 1,
				maxLength: 1000,
			},
			top_k: {
				type: 'number',
				description: 'Maximum number of results to return (default: 10)',
				minimum: 1,
				maximum: 50,
				default: 10,
			},
			similarity_threshold: {
				type: 'number',
				description: `Minimum similarity score for results (0.0 to 1.0, default: ${env.WORKSPACE_SEARCH_THRESHOLD})`,
				minimum: 0.0,
				maximum: 1.0,
				default: env.WORKSPACE_SEARCH_THRESHOLD,
			},
			filters: {
				type: 'object',
				description: 'Optional filters to narrow search results',
				properties: {
					domain: {
						type: 'string',
						description: 'Filter by domain (frontend, backend, devops, quality-assurance, design)',
						enum: ['frontend', 'backend', 'devops', 'quality-assurance', 'design'],
					},
					team_member: {
						type: 'string',
						description: 'Filter by team member name or identifier',
					},
					project: {
						type: 'string',
						description: 'Filter by project name or identifier',
					},
					status: {
						type: 'string',
						description: 'Filter by progress status',
						enum: ['in-progress', 'completed', 'blocked', 'reviewing'],
					},
				},
				additionalProperties: false,
			},
			include_metadata: {
				type: 'boolean',
				description: 'Whether to include detailed metadata in results (default: true)',
				default: true,
			},
			enable_query_refinement: {
				type: 'boolean',
				description: 'Whether to apply query refinement for better search results (default: false)',
				default: false,
			},
		},
		required: ['query'],
	},
	handler: async (args: any, context?: InternalToolContext): Promise<WorkspaceSearchResult> => {
		const startTime = Date.now();

		try {
			// Check if workspace memory is enabled
			if (!env.USE_WORKSPACE_MEMORY) {
				logger.debug('WorkspaceSearch: Workspace memory is disabled, returning empty results');
				return {
					success: true,
					query: args.query || '',
					results: [],
					metadata: {
						totalResults: 0,
						searchTime: Date.now() - startTime,
						embeddingTime: 0,
						maxSimilarity: 0,
						minSimilarity: 0,
						averageSimilarity: 0,
						workspaceResults: 0,
						searchMode: 'workspace',
						usedFallback: true,
					},
					timestamp: new Date().toISOString(),
				};
			}

			logger.debug('WorkspaceSearch: Processing workspace memory search request', {
				query: args.query?.substring(0, 100) || 'undefined',
				top_k: args.top_k || 10,
				similarity_threshold: args.similarity_threshold || env.WORKSPACE_SEARCH_THRESHOLD,
				filters: args.filters,
			});

			// Check if embeddings are disabled for this session
			if (context?.services?.embeddingManager?.getSessionState()?.isDisabled()) {
				const reason = context.services.embeddingManager.getSessionState().getDisabledReason();
				logger.debug(
					'WorkspaceSearch: Embeddings disabled for this session, returning empty results',
					{ reason }
				);
				return {
					success: true,
					query: args.query || '',
					results: [],
					metadata: {
						totalResults: 0,
						searchTime: Date.now() - startTime,
						embeddingTime: 0,
						maxSimilarity: 0,
						minSimilarity: 0,
						averageSimilarity: 0,
						workspaceResults: 0,
						searchMode: 'workspace',
						usedFallback: true,
					},
					timestamp: new Date().toISOString(),
				};
			}

			// Check if embedding manager indicates no available embeddings
			if (
				context?.services?.embeddingManager &&
				!context.services.embeddingManager.hasAvailableEmbeddings()
			) {
				logger.debug('WorkspaceSearch: No available embeddings, returning empty results');
				return {
					success: true,
					query: args.query || '',
					results: [],
					metadata: {
						totalResults: 0,
						searchTime: Date.now() - startTime,
						embeddingTime: 0,
						maxSimilarity: 0,
						minSimilarity: 0,
						averageSimilarity: 0,
						workspaceResults: 0,
						searchMode: 'workspace',
						usedFallback: true,
					},
					timestamp: new Date().toISOString(),
				};
			}

			// Validate required parameters
			if (!args.query || typeof args.query !== 'string' || args.query.trim().length === 0) {
				throw new Error('Query is required and must be a non-empty string');
			}

			// Set defaults
			const originalQuery = args.query.trim();
			const topK = Math.max(1, Math.min(50, args.top_k || 10));
			const similarityThreshold = Math.max(
				0.0,
				Math.min(1.0, args.similarity_threshold || env.WORKSPACE_SEARCH_THRESHOLD)
			);
			const filters = args.filters || {};

			// Get required services from context
			if (!context?.services) {
				throw new Error('InternalToolContext.services is required for workspace search');
			}

			const embeddingManager = context.services.embeddingManager;
			const vectorStoreManager = context.services.vectorStoreManager;

			if (!embeddingManager || !vectorStoreManager) {
				throw new Error('EmbeddingManager and VectorStoreManager are required in context.services');
			}

			const embedder = embeddingManager.getEmbedder('default');

			if (!embedder?.embed || typeof embedder.embed !== 'function') {
				throw new Error('Embedder is not properly initialized or missing embed() method');
			}

			// Generate embedding for the search query
			const embeddingStartTime = Date.now();
			logger.debug('WorkspaceSearch: Generating embedding for query', {
				queryLength: originalQuery.length,
				queryPreview: originalQuery.substring(0, 50),
			});
			let queries: string[] = [originalQuery];
			const enableQueryRefinement =
				args.enable_query_refinement === true || env.ENABLE_QUERY_REFINEMENT === true;
			if (enableQueryRefinement) {
				const rewrittenQueries = await rewriteUserQuery(
					originalQuery,
					context?.services?.llmService
				);
				logger.debug('WorkspaceSearch: Rewritten queries', {
					rewrittenQueries,
				});
				queries = rewrittenQueries.queries;
			}
			let queryEmbeddings: number[][];
			try {
				queryEmbeddings = await embedder?.embedBatch(queries);
			} catch (embedError) {
				logger.error(
					'WorkspaceSearch: Failed to generate embedding, disabling embeddings globally',
					{
						error: embedError instanceof Error ? embedError.message : String(embedError),
						provider: embedder.getConfig().type,
					}
				);

				// Immediately disable embeddings globally on first failure
				if (context?.services?.embeddingManager && embedError instanceof Error) {
					context.services.embeddingManager.handleRuntimeFailure(
						embedError,
						embedder.getConfig().type
					);
				}

				// Return empty results since embeddings are now disabled
				return {
					success: true,
					query: args.query || '',
					results: [],
					metadata: {
						totalResults: 0,
						searchTime: Date.now() - startTime,
						embeddingTime: 0,
						maxSimilarity: 0,
						minSimilarity: 0,
						averageSimilarity: 0,
						workspaceResults: 0,
						searchMode: 'workspace',
						usedFallback: true,
					},
					timestamp: new Date().toISOString(),
				};
			}

			const embeddingTime = Date.now() - embeddingStartTime;

			logger.debug('WorkspaceSearch: Embedding generated successfully', {
				embeddingTime: `${embeddingTime}ms`,
				embeddingDimensions: Array.isArray(queryEmbeddings[0])
					? queryEmbeddings[0].length
					: 'unknown',
			});

			// Search workspace memory
			const searchStartTime = Date.now();
			let workspaceResults: any[] = [];
			let usedFallback = false;

			// Get workspace store
			const workspaceCollectionName = env.WORKSPACE_VECTOR_STORE_COLLECTION || 'workspace_memory';
			let workspaceStore = null;

			// Detect vector store manager type and get workspace store
			const managerName = vectorStoreManager.constructor.name;
			logger.debug('WorkspaceSearch: Detecting vector manager type', {
				managerName,
				collectionName: workspaceCollectionName,
				hasGetStore: typeof vectorStoreManager.getStore === 'function',
			});

			// Try workspace collection access methods in order of preference
			try {
				// Method 1: Try workspace-specific getter (MultiCollectionVectorManager)
				if (managerName === 'MultiCollectionVectorManager' || managerName.includes('Multi')) {
					logger.debug('WorkspaceSearch: Using MultiCollectionVectorManager for workspace search');
					workspaceStore = (vectorStoreManager as any).getStore('workspace');
				}
				// Method 2: Try dual collection manager (DualCollectionVectorManager)
				else if (managerName === 'DualCollectionVectorManager' || managerName.includes('Dual')) {
					logger.debug(
						'WorkspaceSearch: Using DualCollectionVectorManager - trying workspace store'
					);
					try {
						workspaceStore = (vectorStoreManager as any).getStore('workspace');
					} catch {
						// DualCollectionVectorManager doesn't have workspace, fall back
						logger.debug(
							'WorkspaceSearch: DualCollectionVectorManager has no workspace - using knowledge store'
						);
						workspaceStore = (vectorStoreManager as any).getStore('knowledge');
						usedFallback = true;
					}
				}
				// Method 3: Single collection manager or named store
				else {
					logger.debug('WorkspaceSearch: Using single collection manager');
					workspaceStore =
						(vectorStoreManager as any).getNamedStore?.(workspaceCollectionName) ||
						vectorStoreManager.getStore();
					if (!(vectorStoreManager as any).getNamedStore) {
						usedFallback = true;
					}
				}
			} catch (error) {
				// Final fallback to default store
				logger.debug('WorkspaceSearch: All workspace access methods failed, using default store', {
					error: error instanceof Error ? error.message : String(error),
				});
				workspaceStore = vectorStoreManager.getStore();
				usedFallback = true;
			}

			if (!workspaceStore) {
				throw new Error('Workspace vector store not available');
			}

			// Search workspace collection
			for (const queryEmbedding of queryEmbeddings) {
				const results = await workspaceStore.search(queryEmbedding, topK * 2);
				workspaceResults.push(...results);
			}

			// Mark results with source
			const allResults = workspaceResults.map((result: any) => ({
				...result,
				payload: {
					...result.payload,
					source: 'workspace',
					memoryType: 'workspace',
				},
			}));

			logger.debug('WorkspaceSearch: Workspace collection search completed', {
				resultsFound: workspaceResults.length,
			});

			const searchTime = Date.now() - searchStartTime;

			logger.debug('WorkspaceSearch: Workspace search completed', {
				searchTime: `${searchTime}ms`,
				totalResults: allResults.length,
				workspaceResults: workspaceResults.length,
			});

			// Filter, rank, and format workspace memory results
			let filteredResults = allResults
				.filter(result => {
					// Apply similarity threshold filter
					if ((result.score || 0) < similarityThreshold) return false;

					// Apply cross-tool memory sharing filter if workspace mode is shared
					if (env.CIPHER_WORKSPACE_MODE === 'shared') {
						const payload = result.payload || {};

						// Check if memory matches shared workspace criteria
						const hasMatchingUserId =
							!env.CIPHER_USER_ID || !payload.userId || payload.userId === env.CIPHER_USER_ID;
						const hasMatchingProjectId =
							!env.CIPHER_PROJECT_NAME ||
							!payload.projectId ||
							payload.projectId === env.CIPHER_PROJECT_NAME;
						const isSharedMode = payload.workspaceMode === 'shared';

						// Include memory if:
						// 1. It's marked as shared mode AND (matches user OR project)
						// 2. OR it has no sharing identifiers (legacy memories)
						const shouldInclude =
							(isSharedMode && (hasMatchingUserId || hasMatchingProjectId)) ||
							(!payload.userId && !payload.projectId && !payload.workspaceMode);

						logger.debug('WorkspaceSearch: Cross-tool sharing filter applied', {
							memoryId: result.id,
							memoryUserId: payload.userId,
							memoryProjectId: payload.projectId,
							memoryWorkspaceMode: payload.workspaceMode,
							envUserId: env.CIPHER_USER_ID,
							envProjectId: env.CIPHER_PROJECT_NAME,
							envWorkspaceMode: env.CIPHER_WORKSPACE_MODE,
							shouldInclude,
						});

						return shouldInclude;
					}

					return true; // No filtering in isolated mode
				})
				.sort((a, b) => (b.score || 0) - (a.score || 0)); // Sort by similarity score descending

			// Apply additional filters
			if (filters.domain) {
				filteredResults = filteredResults.filter(
					result => result.payload?.domain === filters.domain
				);
			}

			if (filters.team_member) {
				filteredResults = filteredResults.filter(result =>
					result.payload?.teamMember?.toLowerCase().includes(filters.team_member.toLowerCase())
				);
			}

			if (filters.project) {
				filteredResults = filteredResults.filter(result =>
					result.payload?.workContext?.project
						?.toLowerCase()
						.includes(filters.project.toLowerCase())
				);
			}

			if (filters.status) {
				filteredResults = filteredResults.filter(
					result => result.payload?.currentProgress?.status === filters.status
				);
			}

			// Take top K results overall and format
			const finalResults = filteredResults.slice(0, topK).map(result => {
				const rawPayload = result.payload || {};
				const payload = rawPayload as WorkspacePayload;

				// Return unified result format with workspace payload data
				const baseResult = {
					id: result.id || payload.id || 'unknown',
					text: payload.text || 'No content available',
					tags: payload.tags || [],
					timestamp: payload.timestamp || new Date().toISOString(),
					similarity: result.score || 0,
					version: payload.version || 2,
					source: 'workspace' as const,
					memoryType: 'workspace' as const,
				};

				// Add workspace-specific fields
				return {
					...baseResult,
					...(payload.teamMember && { teamMember: payload.teamMember }),
					...(payload.currentProgress && { currentProgress: payload.currentProgress }),
					...(payload.bugsEncountered && { bugsEncountered: payload.bugsEncountered }),
					...(payload.workContext && { workContext: payload.workContext }),
					confidence: payload.confidence || 0,
					event: payload.event,
					...(payload.domain && { domain: payload.domain }),
					qualitySource: payload.qualitySource,
					...(payload.sourceSessionId && { sourceSessionId: payload.sourceSessionId }),
				};
			});

			// Calculate statistics
			const totalResults = finalResults.length;
			const similarities = finalResults.map(r => r.similarity);
			const maxSimilarity = similarities.length > 0 ? Math.max(...similarities) : 0;
			const minSimilarity = similarities.length > 0 ? Math.min(...similarities) : 0;
			const averageSimilarity =
				similarities.length > 0 ? similarities.reduce((a, b) => a + b, 0) / similarities.length : 0;

			const totalTime = Date.now() - startTime;

			// Prepare result
			const result: WorkspaceSearchResult = {
				success: true,
				query: originalQuery,
				results: finalResults,
				metadata: {
					totalResults,
					searchTime: totalTime,
					embeddingTime,
					maxSimilarity,
					minSimilarity,
					averageSimilarity,
					workspaceResults: totalResults,
					searchMode: 'workspace',
					usedFallback,
					...(Object.keys(filters).length > 0 && { filters }),
				},
				timestamp: new Date().toISOString(),
			};

			logger.debug('WorkspaceSearch: Workspace search completed successfully', {
				query: originalQuery.substring(0, 50),
				resultsFound: totalResults,
				workspaceResults: totalResults,
				maxSimilarity: maxSimilarity.toFixed(3),
				averageSimilarity: averageSimilarity.toFixed(3),
				totalTime: `${totalTime}ms`,
				usedFallback,
				appliedFilters: Object.keys(filters),
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			const totalTime = Date.now() - startTime;

			logger.error('WorkspaceSearch: Search failed', {
				error: errorMessage,
				query: args.query?.substring(0, 50) || 'undefined',
				processingTime: `${totalTime}ms`,
			});

			// Check if this is a runtime failure that should disable embeddings globally
			if (context?.services?.embeddingManager && error instanceof Error) {
				const embeddingManager = context.services.embeddingManager;
				if (embeddingManager && typeof embeddingManager.handleRuntimeFailure === 'function') {
					const embedder = embeddingManager.getEmbedder('default');
					const providerType = embedder?.getConfig()?.type || 'unknown';
					embeddingManager.handleRuntimeFailure(error, providerType);
				}
			}

			return {
				success: false,
				query: args.query || 'undefined',
				results: [],
				metadata: {
					totalResults: 0,
					searchTime: totalTime,
					embeddingTime: 0,
					maxSimilarity: 0,
					minSimilarity: 0,
					averageSimilarity: 0,
					workspaceResults: 0,
					searchMode: 'workspace',
					usedFallback: true,
				},
				timestamp: new Date().toISOString(),
			};
		}
	},
};

import { InternalTool, InternalToolContext } from '../../types.js';
import { logger } from '../../../../logger/index.js';
import {
	createWorkspacePayload,
	extractWorkspaceInfo,
	mergeWorkspaceInfo,
} from './workspace-payloads.js';
import { env } from '../../../../env.js';

/**
 * Type definition for LLM-provided workspace information
 */
export interface LLMWorkspaceInfo {
	teamMember?: string;
	currentProgress?: {
		feature: string;
		status: 'in-progress' | 'completed' | 'blocked' | 'reviewing';
		completion?: number;
	};
	bugsEncountered?: Array<{
		description: string;
		severity: 'low' | 'medium' | 'high' | 'critical';
		status: 'open' | 'in-progress' | 'fixed';
	}>;
	workContext?: {
		project?: string;
		repository?: string;
		branch?: string;
	};
	domain?: string;
}

/**
 * Determines if a piece of content is significant for workspace memory
 * Focuses on team collaboration, project progress, and work context
 */
function isWorkspaceSignificantContent(content: string): boolean {
	if (!content || content.trim().length === 0) {
		return false;
	}

	const text = content.toLowerCase().trim();

	// Skip patterns that are not workspace-relevant
	const skipPatterns = [
		// Personal information and identity queries
		/\b(my name|user['']?s? name|find my name|search.*name|who am i|what['']?s my name)\b/i,
		/\b(personal|profile|identity|username|login|password|email|address|phone)\b/i,

		// Tool results and system messages
		/^(cipher_.*|workspace_search|workspace_store):\s*(found|completed|no results|error)/i,
		/^(retrieved|result|results|found|matches|search completed|query executed):/i,

		// Simple greetings and social interactions
		/^(user:|assistant:)?\s*(hello|hi|hey|good morning|good afternoon|good evening|thanks|thank you|please|sorry|excuse me|bye|goodbye)\b/i,

		// Generic status messages without context
		/^(task completed|operation successful|processing|loading|waiting|done|finished|ready)\b/i,

		// Simple yes/no responses
		/^(user:|assistant:)?\s*(yes|no|ok|okay|sure|fine|great|good|right|correct|wrong|true|false)\s*[.!?]?\s*$/i,
	];

	// Check if content matches skip patterns
	for (const pattern of skipPatterns) {
		if (pattern.test(text)) {
			return false;
		}
	}

	// Prioritize workspace and team collaboration content
	const workspacePatterns = [
		// Team and collaboration
		/\b(team|teammate|colleague|collaborat|pair programm|code review|pull request|merge request)\b/i,
		/\b(assigned to|working with|helping|mentoring|onboarding|standup|meeting|discussion)\b/i,
		/\b(project manager|tech lead|senior|junior|intern|developer|engineer|designer|qa)\b/i,

		// Project and work progress
		/\b(project|milestone|deadline|sprint|iteration|epic|story|task|ticket|issue|feature)\b/i,
		/\b(progress|status|update|completion|percentage|completed|finished|deployed|released)\b/i,
		/\b(blocked|blocker|impediment|waiting|pending|reviewing|testing|in progress)\b/i,
		/\b(priority|urgent|critical|high|medium|low|backlog|todo|done|wip)\b/i,

		// Bug tracking and issues
		/\b(bug|error|issue|problem|defect|crash|failure|exception|fix|patch|hotfix)\b/i,
		/\b(severity|critical|high|medium|low|reported|reproduced|investigated|resolved)\b/i,

		// Repository and version control
		/\b(repository|repo|branch|commit|push|pull|merge|git|github|gitlab|bitbucket)\b/i,
		/\b(main|master|develop|feature|hotfix|bugfix|release|version|tag)\b/i,

		// Deployment and environment
		/\b(deploy|deployment|environment|staging|production|dev|test|ci|cd|pipeline)\b/i,
		/\b(build|compile|test|integration|e2e|unit|smoke|regression)\b/i,

		// Technical domains and architecture
		/\b(frontend|backend|fullstack|devops|infrastructure|database|api|microservice)\b/i,
		/\b(architecture|design|pattern|framework|library|component|module|service)\b/i,

		// Work context mentions
		/@[a-zA-Z_]+/, // @username mentions
		/\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\s+(?:is working on|completed|fixed|implemented|assigned)/i,
	];

	// Check if content contains workspace patterns
	for (const pattern of workspacePatterns) {
		if (pattern.test(text)) {
			return true;
		}
	}

	// Check for percentage completion patterns
	if (/\d+%/.test(text) && /\b(complete|done|progress|finish)\b/i.test(text)) {
		return true;
	}

	// Check for date/time patterns with work context
	if (
		/\b(today|yesterday|tomorrow|monday|tuesday|wednesday|thursday|friday|weekend)\b/i.test(text) &&
		/\b(deadline|due|meeting|standup|demo|release|deploy)\b/i.test(text)
	) {
		return true;
	}

	// Check minimum length and complexity for workspace context
	if (text.length < 15) {
		return false;
	}

	// Check for work-related keywords density
	const workKeywords = [
		'work',
		'task',
		'project',
		'team',
		'feature',
		'bug',
		'fix',
		'implement',
		'develop',
		'build',
		'deploy',
		'test',
		'review',
		'merge',
		'commit',
		'branch',
		'issue',
		'ticket',
		'milestone',
		'deadline',
		'progress',
		'status',
		'complete',
		'done',
		'blocked',
		'priority',
		'assign',
		'collaborate',
		'pair',
		'help',
		'support',
		'discuss',
		'meeting',
		'standup',
	];

	const words = text.split(/\s+/);
	const workKeywordCount = words.filter(word =>
		workKeywords.includes(word.replace(/[^\w]/g, '').toLowerCase())
	).length;

	// If more than 15% of words are work-related, consider it significant
	const workDensity = workKeywordCount / words.length;
	if (workDensity > 0.15 && words.length > 5) {
		return true;
	}

	return false;
}

/**
 * Determines if a message is a retrieved result from workspace search or other tools
 */
function isRetrievedWorkspaceResult(content: string): boolean {
	if (!content || typeof content !== 'string') return false;
	const text = content.toLowerCase();

	const retrievedPatterns = [
		/^(cipher_workspace_search|workspace_search|cipher_workspace_store|workspace_store):/i,
		/^(workspace results|team results|project results|collaboration results):/i,
		/^(team member|current progress|bugs encountered|work context):/i,
		/^(retrieved workspace|workspace search|team search|project search):/i,
		/^(observation:|action:|thought:|conclusion:|reflection:)/i,
		/^(id:|timestamp:|similarity:|source:|memorytype:)/i,
		/^(message: 'workspace query executed'|message: 'workspace search completed')/i,
		/^(workspaceresults:|teamresults:|projectresults:)/i,
	];

	for (const pattern of retrievedPatterns) {
		if (pattern.test(text)) return true;
	}
	return false;
}

/**
 * Generate a safe workspace memory ID from index
 */
function generateSafeWorkspaceId(index: number): number {
	const timestamp = Math.floor(Date.now() / 1000);
	return timestamp * 1000 + (index % 1000) + 500000; // Offset to avoid conflicts with other memory types
}

/**
 * Extract workspace-relevant tags from content
 */
function extractWorkspaceTags(content: string): string[] {
	const tags = new Set<string>();
	const text = content.toLowerCase();

	// Domain tags
	const domainPatterns = [
		{
			pattern: /\b(?:frontend|front-end|ui|ux|react|vue|angular|html|css|javascript|typescript)\b/i,
			tag: 'frontend',
		},
		{
			pattern: /\b(?:backend|back-end|server|api|database|sql|node|express|django|flask)\b/i,
			tag: 'backend',
		},
		{
			pattern: /\b(?:devops|deployment|docker|kubernetes|ci|cd|pipeline|infrastructure)\b/i,
			tag: 'devops',
		},
		{ pattern: /\b(?:testing|qa|quality|unit test|integration test|e2e)\b/i, tag: 'testing' },
		{ pattern: /\b(?:design|ux|ui|mockup|wireframe|prototype)\b/i, tag: 'design' },
	];

	for (const domainPattern of domainPatterns) {
		if (domainPattern.pattern.test(text)) {
			tags.add(domainPattern.tag);
		}
	}

	// Status tags
	const statusPatterns = [
		{ pattern: /\b(?:completed|done|finished|deployed|released)\b/i, tag: 'completed' },
		{ pattern: /\b(?:blocked|stuck|waiting|pending)\b/i, tag: 'blocked' },
		{ pattern: /\b(?:reviewing|review|testing|qa)\b/i, tag: 'reviewing' },
		{ pattern: /\b(?:in progress|ongoing|working|developing)\b/i, tag: 'in-progress' },
	];

	for (const statusPattern of statusPatterns) {
		if (statusPattern.pattern.test(text)) {
			tags.add(statusPattern.tag);
		}
	}

	// Type tags
	const typePatterns = [
		{ pattern: /\b(?:bug|error|issue|problem|defect)\b/i, tag: 'bug' },
		{ pattern: /\b(?:feature|enhancement|improvement)\b/i, tag: 'feature' },
		{ pattern: /\b(?:task|ticket|story|epic)\b/i, tag: 'task' },
		{ pattern: /\b(?:team|collaboration|pair|meeting)\b/i, tag: 'collaboration' },
		{ pattern: /\b(?:project|milestone|deadline|release)\b/i, tag: 'project' },
	];

	for (const typePattern of typePatterns) {
		if (typePattern.pattern.test(text)) {
			tags.add(typePattern.tag);
		}
	}

	// Always add workspace tag
	tags.add('workspace');

	return Array.from(tags);
}

/**
 * Workspace Store Tool
 *
 * Background tool that automatically stores team-related information including
 * project progress, bugs, collaboration context, and workspace activities.
 * This tool has skipping mechanisms similar to cipher_extract_and_operate_memory.
 */
export const workspaceStoreTool: InternalTool = {
	name: 'workspace_store',
	category: 'memory',
	internal: true,
	agentAccessible: false, // Internal-only: programmatically called after each interaction
	description:
		'Background tool that automatically stores team-related information including project progress, bugs, and collaboration context.',
	version: '1.0.0',
	parameters: {
		type: 'object',
		properties: {
			interaction: {
				oneOf: [
					{
						type: 'string',
						description:
							'A single user interaction or conversation text to extract workspace information from.',
					},
					{
						type: 'array',
						items: { type: 'string' },
						description:
							'Multiple user interactions or conversation texts to extract workspace information from.',
					},
				],
				description:
					'Raw user interaction(s) or conversation text(s) to extract workspace information from.',
			},
			workspaceInfo: {
				type: 'object',
				description:
					'Optional LLM-provided structured workspace information (takes precedence over regex extraction)',
				properties: {
					teamMember: {
						type: 'string',
						description: 'Name/ID of team member',
					},
					currentProgress: {
						type: 'object',
						description: 'Current feature progress information',
						properties: {
							feature: { type: 'string', description: 'Feature being worked on' },
							status: {
								type: 'string',
								enum: ['in-progress', 'completed', 'blocked', 'reviewing'],
								description: 'Current status of the feature',
							},
							completion: {
								type: 'number',
								minimum: 0,
								maximum: 100,
								description: 'Completion percentage (0-100)',
							},
						},
						required: ['feature', 'status'],
						additionalProperties: false,
					},
					bugsEncountered: {
						type: 'array',
						description: 'Array of bug information',
						items: {
							type: 'object',
							properties: {
								description: { type: 'string', description: 'Bug description' },
								severity: {
									type: 'string',
									enum: ['low', 'medium', 'high', 'critical'],
									description: 'Bug severity level',
								},
								status: {
									type: 'string',
									enum: ['open', 'in-progress', 'fixed'],
									description: 'Bug resolution status',
								},
							},
							required: ['description', 'severity', 'status'],
							additionalProperties: false,
						},
					},
					workContext: {
						type: 'object',
						description: 'Work context information',
						properties: {
							project: { type: 'string', description: 'Project identifier' },
							repository: { type: 'string', description: 'Git repository if relevant' },
							branch: { type: 'string', description: 'Current working branch' },
						},
						additionalProperties: false,
					},
					domain: {
						type: 'string',
						description: 'Technical domain (e.g., frontend, backend, devops)',
					},
				},
				additionalProperties: false,
			},
			context: {
				type: 'object',
				description: 'Optional context information for workspace operations',
				properties: {
					sessionId: { type: 'string', description: 'Current session identifier' },
					projectId: {
						type: 'string',
						description: 'Project identifier for scoped workspace memory',
					},
					userId: { type: 'string', description: 'User identifier' },
				},
				additionalProperties: false,
			},
			options: {
				type: 'object',
				description: 'Configuration options for workspace memory operations',
				properties: {
					similarityThreshold: {
						type: 'number',
						description: 'Similarity threshold for workspace memory matching (0.0 to 1.0)',
						minimum: 0.0,
						maximum: 1.0,
						default: 0.8,
					},
					confidenceThreshold: {
						type: 'number',
						description: 'Minimum confidence threshold for operations (0.0 to 1.0)',
						minimum: 0.0,
						maximum: 1.0,
						default: 0.6,
					},
					enableBatchProcessing: {
						type: 'boolean',
						description: 'Whether to process multiple workspace items in batch',
						default: true,
					},
					autoExtractWorkspaceInfo: {
						type: 'boolean',
						description: 'Whether to automatically extract workspace context',
						default: true,
					},
				},
				additionalProperties: false,
			},
		},
		required: ['interaction'],
	},
	handler: async (
		args: {
			interaction: string | string[];
			workspaceInfo?: LLMWorkspaceInfo;
			context?: any;
			options?: any;
		},
		context?: InternalToolContext
	) => {
		try {
			// Check if workspace memory is enabled
			if (!env.USE_WORKSPACE_MEMORY) {
				logger.debug('WorkspaceStore: Workspace memory is disabled, skipping workspace operations');
				return {
					success: true,
					mode: 'disabled',
					message: 'Workspace memory is disabled',
					extractedFacts: 0,
					workspaceActions: 0,
					skipped: true,
				};
			}

			// Check if embeddings are disabled for this session
			const sessionState = context?.services?.embeddingManager?.getSessionState?.();
			if (sessionState?.isDisabled()) {
				const reason = sessionState.getDisabledReason();
				logger.debug(
					'WorkspaceStore: Embeddings disabled for this session, skipping workspace operations',
					{ reason }
				);
				return {
					success: true,
					mode: 'chat-only',
					message: `Workspace operations disabled: ${reason}`,
					extractedFacts: 0,
					workspaceActions: 0,
					skipped: true,
				};
			}

			// Check if embedding manager indicates no available embeddings
			if (
				context?.services?.embeddingManager &&
				!context.services.embeddingManager.hasAvailableEmbeddings()
			) {
				logger.debug('WorkspaceStore: No available embeddings, skipping workspace operations');
				return {
					success: true,
					mode: 'chat-only',
					message: 'No available embeddings - operating in chat-only mode',
					extractedFacts: 0,
					workspaceActions: 0,
					skipped: true,
				};
			}

			// Step 1: Extract workspace information from interaction(s)
			let workspaceContentArray: string[];
			if (!args.interaction) {
				throw new Error('No interaction(s) provided for workspace extraction');
			}
			if (typeof args.interaction === 'string') {
				workspaceContentArray = [args.interaction];
			} else if (Array.isArray(args.interaction)) {
				workspaceContentArray = args.interaction;
			} else {
				throw new Error('Interaction must be a string or array of strings');
			}

			// Filter out empty or invalid content
			const validContent = workspaceContentArray
				.filter(content => content && typeof content === 'string' && content.trim().length > 0)
				.map(content => content.trim());

			// Apply significance filtering to extract only workspace-relevant content
			const significantContent = validContent.filter(content => {
				if (isRetrievedWorkspaceResult(content)) {
					logger.debug('WorkspaceStore: Skipping retrieved workspace result', {
						contentPreview: content.substring(0, 100) + (content.length > 100 ? '...' : ''),
						reason: 'Content is a retrieved result from workspace search tool',
					});
					return false;
				}
				const isSignificant = isWorkspaceSignificantContent(content);
				if (!isSignificant) {
					logger.debug('WorkspaceStore: Skipping non-workspace-significant content', {
						contentPreview: content.substring(0, 100) + (content.length > 100 ? '...' : ''),
						reason: 'Does not contain significant workspace or team collaboration information',
					});
				}
				return isSignificant;
			});

			if (significantContent.length === 0) {
				logger.debug('WorkspaceStore: No significant workspace content found after filtering', {
					originalContent: validContent.length,
					filteredContent: significantContent.length,
					interactionLength: args.interaction.length,
				});
				return {
					success: true,
					extraction: {
						extracted: 0,
						skipped: workspaceContentArray.length,
						content: [],
					},
					workspace: [],
					summary: [],
					timestamp: new Date().toISOString(),
				};
			}

			// Extraction stats
			const extractionStats = {
				extracted: significantContent.length,
				skipped: workspaceContentArray.length - significantContent.length,
				content: significantContent.map((content, i) => ({
					id: `workspace_content_${Math.floor(Date.now() / 1000)}_${i}`,
					preview: content.substring(0, 100) + (content.length > 100 ? '...' : ''),
					metadata: {
						hasTeamMention:
							/@[a-zA-Z_]+/.test(content) || /\b(team|colleague|developer)\b/i.test(content),
						hasProgress: /\b(progress|complete|done|finish|\d+%)\b/i.test(content),
						hasBugInfo: /\b(bug|error|issue|fix|resolve)\b/i.test(content),
						hasProjectInfo: /\b(project|milestone|deadline|feature)\b/i.test(content),
						length: content.length,
					},
				})),
			};

			// Step 2: Enhanced error handling for service dependencies
			if (!context?.services) {
				logger.warn('WorkspaceStore: No services context available, using basic processing');
				// Return basic processing without vector operations
				const basicWorkspaceActions = significantContent.map((content, i) => ({
					id: generateSafeWorkspaceId(i),
					text: content,
					event: 'ADD' as const,
					tags: extractWorkspaceTags(content),
					confidence: 0.6,
				}));

				return {
					success: true,
					extraction: extractionStats,
					workspace: basicWorkspaceActions,
					summary: basicWorkspaceActions.map(action => ({
						contentPreview: action.text.substring(0, 80),
						action: action.event,
						confidence: action.confidence,
						targetId: action.id,
					})),
					timestamp: new Date().toISOString(),
				};
			}

			const embeddingManager = context.services.embeddingManager;
			const vectorStoreManager = context.services.vectorStoreManager;

			if (!embeddingManager || !vectorStoreManager) {
				logger.warn(
					'WorkspaceStore: Missing embedding or vector services, falling back to basic processing'
				);
				const basicWorkspaceActions = significantContent.map((content, i) => ({
					id: generateSafeWorkspaceId(i),
					text: content,
					event: 'ADD' as const,
					tags: extractWorkspaceTags(content),
					confidence: 0.5,
					reasoning: 'Fallback processing due to missing services',
				}));

				return {
					success: true,
					extraction: extractionStats,
					workspace: basicWorkspaceActions,
					summary: basicWorkspaceActions.map(action => ({
						contentPreview: action.text.substring(0, 80),
						action: action.event,
						confidence: action.confidence,
						reason: action.reasoning,
						targetId: action.id,
					})),
					timestamp: new Date().toISOString(),
				};
			}

			const embedder = embeddingManager.getEmbedder('default');

			// Get workspace store - try to get workspace-specific store, fall back to default
			const workspaceCollectionName = env.WORKSPACE_VECTOR_STORE_COLLECTION || 'workspace_memory';
			let workspaceStore;
			try {
				logger.debug('WorkspaceStore: Using workspace collection', {
					collectionName: workspaceCollectionName,
					hasWorkspaceSpecificType: !!env.WORKSPACE_VECTOR_STORE_TYPE,
					hasWorkspaceSpecificHost: !!(
						env.WORKSPACE_VECTOR_STORE_HOST || env.WORKSPACE_VECTOR_STORE_URL
					),
				});

				// Try to get workspace-specific store through various methods
				workspaceStore =
					(vectorStoreManager as any).getStore('workspace') ||
					(vectorStoreManager as any).getNamedStore?.(workspaceCollectionName) ||
					vectorStoreManager.getStore();
			} catch (error) {
				logger.debug('WorkspaceStore: Falling back to default store', {
					error: error instanceof Error ? error.message : String(error),
				});
				workspaceStore = vectorStoreManager.getStore();
			}

			if (!embedder || !workspaceStore) {
				logger.warn(
					'WorkspaceStore: Embedder or workspace store not available, using basic processing'
				);
				const basicWorkspaceActions = significantContent.map((content, i) => ({
					id: generateSafeWorkspaceId(i),
					text: content,
					event: 'ADD' as const,
					tags: extractWorkspaceTags(content),
					confidence: 0.5,
					reasoning: 'Basic processing - embedder/workspace store unavailable',
				}));

				return {
					success: true,
					extraction: extractionStats,
					workspace: basicWorkspaceActions,
					summary: basicWorkspaceActions.map(action => ({
						contentPreview: action.text.substring(0, 80),
						action: action.event,
						confidence: action.confidence,
						reason: action.reasoning,
						targetId: action.id,
					})),
					timestamp: new Date().toISOString(),
				};
			}

			if (!embedder.embed || typeof embedder.embed !== 'function') {
				throw new Error('Embedder is not properly initialized or missing embed() method');
			}

			const options = {
				similarityThreshold: args.options?.similarityThreshold ?? 0.8,
				confidenceThreshold: args.options?.confidenceThreshold ?? 0.6,
				autoExtractWorkspaceInfo: args.options?.autoExtractWorkspaceInfo ?? true,
			};

			const workspaceActions = [];
			const workspaceSummaries = [];

			for (let i = 0; i < significantContent.length; i++) {
				const content = significantContent[i];

				if (!content) {
					logger.warn(`WorkspaceStore: Skipping undefined content at index ${i}`);
					continue;
				}

				logger.debug(`WorkspaceStore: Processing content ${i + 1}/${significantContent.length}`, {
					contentPreview: content.substring(0, 80) + (content.length > 80 ? '...' : ''),
					contentLength: content.length,
				});

				try {
					// Embed the content with error handling
					let embedding;
					try {
						embedding = await embedder.embed(content);
					} catch (embedError) {
						logger.error(
							`WorkspaceStore: Failed to embed content ${i + 1}, disabling embeddings for session`,
							{
								error: embedError instanceof Error ? embedError.message : String(embedError),
								contentPreview: content.substring(0, 50),
								provider: embedder.getConfig().type,
							}
						);

						// Disable embeddings for this session on failure
						if (context?.services?.embeddingManager && embedError instanceof Error) {
							context.services.embeddingManager.handleRuntimeFailure(
								embedError,
								embedder.getConfig().type
							);
						}

						// Return immediately with chat-only mode since embeddings are now disabled
						return {
							success: true,
							mode: 'chat-only',
							message: `Embeddings disabled due to failure: ${embedError instanceof Error ? embedError.message : String(embedError)}`,
							extractedFacts: significantContent.length,
							workspaceActions: 0,
							skipped: true,
							error: embedError instanceof Error ? embedError.message : String(embedError),
						};
					}

					// Perform similarity search to check for existing workspace memories
					let similar = [];
					try {
						similar = await workspaceStore.search(embedding, 5);
					} catch (searchError) {
						logger.warn(
							`WorkspaceStore: Failed to search similar workspace memories for content ${i + 1}`,
							{
								error: searchError instanceof Error ? searchError.message : String(searchError),
								contentPreview: content.substring(0, 50),
							}
						);
						// Continue with empty similar array
					}

					logger.debug(`WorkspaceStore: Similarity search completed for content ${i + 1}`, {
						similarMemoriesFound: similar.length,
						topSimilarity: similar.length > 0 ? similar[0]?.score?.toFixed(3) : 'N/A',
					});

					// Determine action based on similarity
					let action = 'ADD';
					let targetId = null;
					let reason = '';
					let confidence = options.confidenceThreshold;

					const mostSimilar = similar.length > 0 ? similar[0] : null;
					const similarity = mostSimilar?.score ?? 0;

					if (!mostSimilar || similarity < options.similarityThreshold) {
						action = 'ADD';
						reason = 'No highly similar workspace memory found; adding as new.';
						confidence = Math.max(options.confidenceThreshold, similarity);
					} else {
						if (content === mostSimilar.payload?.text) {
							action = 'NONE';
							reason = 'Content is redundant; already present in workspace memory.';
							targetId = mostSimilar.id;
							confidence = similarity;
						} else if (content.length > (mostSimilar.payload?.text?.length ?? 0)) {
							action = 'UPDATE';
							targetId = mostSimilar.id;
							reason =
								'Content provides more complete workspace information; updating existing memory.';
							confidence = similarity;
						} else {
							action = 'NONE';
							reason = 'Content is similar but not more complete; ignoring.';
							targetId = mostSimilar.id;
							confidence = similarity;
						}
					}

					// Extract workspace-specific information using hybrid approach
					let workspaceInfo = {};
					if (options.autoExtractWorkspaceInfo) {
						// Get LLM-provided workspace info if available
						const llmWorkspaceInfo = args.workspaceInfo || {};

						// Always extract from text as fallback/supplement
						const regexWorkspaceInfo = extractWorkspaceInfo(content);

						// Merge LLM data (priority) with regex data (fallback)
						workspaceInfo = mergeWorkspaceInfo(llmWorkspaceInfo, regexWorkspaceInfo);
					}

					workspaceActions.push({
						id:
							action === 'ADD'
								? generateSafeWorkspaceId(i)
								: targetId && !isNaN(Number(targetId)) && Number(targetId) > 0
									? Number(targetId)
									: generateSafeWorkspaceId(i),
						text: content,
						event: action,
						tags: extractWorkspaceTags(content),
						confidence,
						reasoning: reason,
						workspaceInfo,
					});

					workspaceSummaries.push({
						contentPreview: content.substring(0, 80),
						action,
						confidence,
						reason,
						targetId,
						workspaceInfo: Object.keys(workspaceInfo).length > 0 ? workspaceInfo : undefined,
					});

					logger.debug(`WorkspaceStore: Decision for content ${i + 1}`, {
						contentPreview: content.substring(0, 80) + (content.length > 80 ? '...' : ''),
						decision: action,
						confidence: confidence.toFixed(3),
						reasoning: reason,
						targetMemoryId: targetId,
						decisionMethod: 'Heuristic',
						topSimilarityScore: mostSimilar?.score?.toFixed(3) || 'N/A',
						similarityThreshold: options.similarityThreshold.toFixed(2),
						extractedWorkspaceInfo: Object.keys(workspaceInfo).length,
					});
				} catch (contentError) {
					logger.error(`WorkspaceStore: Failed to process content ${i + 1}`, {
						error: contentError instanceof Error ? contentError.message : String(contentError),
						contentPreview: content.substring(0, 50),
					});

					// Add fallback action for failed content
					workspaceActions.push({
						id: generateSafeWorkspaceId(i),
						text: content,
						event: 'ADD',
						tags: extractWorkspaceTags(content),
						confidence: 0.4,
						reasoning: `Fallback due to processing error: ${contentError instanceof Error ? contentError.message : String(contentError)}`,
						workspaceInfo: {},
					});
				}
			}

			// Step 3: Enhanced persistence with better error handling
			logger.debug('WorkspaceStore: Starting workspace memory persistence operations', {
				totalActions: workspaceActions.length,
				persistableActions: workspaceActions.filter(a =>
					['ADD', 'UPDATE', 'DELETE'].includes(a.event)
				).length,
				skippableActions: workspaceActions.filter(a => a.event === 'NONE').length,
			});

			let persistedCount = 0;
			for (const action of workspaceActions) {
				if (['ADD', 'UPDATE', 'DELETE'].includes(action.event)) {
					if (!action.text) {
						logger.warn(`WorkspaceStore: Skipping action with undefined text`, {
							workspaceId: action.id,
							event: action.event,
						});
						continue;
					}

					try {
						const embedding = await embedder.embed(action.text);

						// Create workspace payload with extracted information
						const qualitySource: 'similarity' | 'llm' | 'heuristic' = 'heuristic';
						const options: any = {
							qualitySource,
							...action.workspaceInfo,
						};

						if (context?.sessionId) {
							options.sourceSessionId = context.sessionId;
						}

						const payload = await createWorkspacePayload(
							action.id,
							action.text,
							action.tags,
							action.confidence,
							action.event as 'ADD' | 'UPDATE' | 'DELETE' | 'NONE',
							options
						);

						if (action.event === 'ADD') {
							await workspaceStore.insert([embedding], [action.id], [payload]);
							logger.debug(`WorkspaceStore: ${action.event} operation completed`, {
								workspaceId: action.id,
								textPreview: action.text.substring(0, 60) + (action.text.length > 60 ? '...' : ''),
								tags: action.tags,
								confidence: action.confidence.toFixed(3),
								workspaceInfo: Object.keys(action.workspaceInfo || {}).length,
							});
						} else if (action.event === 'UPDATE') {
							await workspaceStore.update(action.id, embedding, payload);
							logger.debug(`WorkspaceStore: ${action.event} operation completed`, {
								workspaceId: action.id,
								textPreview: action.text.substring(0, 60) + (action.text.length > 60 ? '...' : ''),
								tags: action.tags,
								confidence: action.confidence.toFixed(3),
								workspaceInfo: Object.keys(action.workspaceInfo || {}).length,
							});
						} else if (action.event === 'DELETE') {
							await workspaceStore.delete(action.id);
							logger.debug(`WorkspaceStore: ${action.event} operation completed`, {
								workspaceId: action.id,
								reasoning: action.reasoning,
							});
						}
						persistedCount++;
					} catch (persistError) {
						logger.error(
							`WorkspaceStore: ${action.event} operation failed, continuing with others`,
							{
								workspaceId: action.id,
								textPreview: action.text.substring(0, 60) + (action.text.length > 60 ? '...' : ''),
								error: persistError instanceof Error ? persistError.message : String(persistError),
							}
						);

						// Check if this is a runtime failure that should disable embeddings globally
						if (context?.services?.embeddingManager && persistError instanceof Error) {
							context.services.embeddingManager.handleRuntimeFailure(
								persistError,
								embedder.getConfig().type
							);
						}

						// Continue with other actions even if one fails
					}
				}
			}

			logger.debug('WorkspaceStore: Workspace memory persistence completed', {
				totalProcessed: workspaceActions.length,
				successfullyPersisted: persistedCount,
				actionsSummary: {
					ADD: workspaceActions.filter(a => a.event === 'ADD').length,
					UPDATE: workspaceActions.filter(a => a.event === 'UPDATE').length,
					DELETE: workspaceActions.filter(a => a.event === 'DELETE').length,
					NONE: workspaceActions.filter(a => a.event === 'NONE').length,
				},
			});

			// Return successful result even if some operations failed
			return {
				success: true,
				extraction: extractionStats,
				workspace: workspaceActions,
				summary: workspaceSummaries,
				timestamp: new Date().toISOString(),
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('WorkspaceStore: Critical failure in workspace store', {
				error: errorMessage,
				stack: error instanceof Error ? error.stack : undefined,
			});

			return {
				success: false,
				error: errorMessage,
				extraction: {
					extracted: 0,
					skipped: Array.isArray(args.interaction) ? args.interaction.length : 1,
					content: [],
				},
				workspace: [],
				summary: [],
				timestamp: new Date().toISOString(),
			};
		}
	},
};

/**
 * Workspace Memory Payload Structures
 *
 * Specialized payload structures for workspace memory that focuses on team
 * collaboration, project progress tracking, and shared context.
 */

import { BasePayload } from './payloads.js';

/**
 * Workspace Memory Payload - For team and project information
 */
export interface WorkspacePayload extends BasePayload {
	tags: string[];
	confidence: number;
	event: 'ADD' | 'UPDATE' | 'DELETE' | 'NONE';

	// Workspace-specific fields
	teamMember?: string; // Name/ID of team member
	currentProgress?: {
		feature: string; // Feature being worked on
		status: 'in-progress' | 'completed' | 'blocked' | 'reviewing';
		completion?: number; // 0-100 percentage
	};

	bugsEncountered?: Array<{
		description: string;
		severity: 'low' | 'medium' | 'high' | 'critical';
		status: 'open' | 'in-progress' | 'fixed';
	}>;

	workContext?: {
		project?: string; // Project identifier
		repository?: string; // Git repo if relevant
		branch?: string; // Current working branch
	};

	domain?: string; // e.g., 'frontend', 'backend', 'devops'
	sourceSessionId?: string; // Session that created this memory
	qualitySource: 'similarity' | 'llm' | 'heuristic'; // How quality was determined
}

/**
 * Create new workspace payload
 */
export async function createWorkspacePayload(
	id: string | number,
	text: string,
	tags: string[],
	confidence: number,
	event: 'ADD' | 'UPDATE' | 'DELETE' | 'NONE',
	options: {
		teamMember?: string;
		currentProgress?: {
			feature: string;
			status: 'in-progress' | 'completed' | 'blocked' | 'reviewing';
			completion?: number;
		};
		bugsEncountered?: Array<{
			description: string;
			severity: 'low' | 'medium' | 'high' | 'critical';
			status: 'open' | 'in-progress' | 'fixed';
		}>;
		workContext?: {
			project?: string;
			repository?: string;
			branch?: string;
		};
		domain?: string;
		sourceSessionId?: string;
		qualitySource: 'similarity' | 'llm' | 'heuristic';
		userId?: string;
		projectId?: string;
		workspaceMode?: 'shared' | 'isolated';
	}
): Promise<WorkspacePayload> {
	// Import env here to avoid circular dependencies
	const { env } = await import('../../../../env.js');

	return {
		id: typeof id === 'string' ? parseInt(id, 10) || 0 : id,
		text,
		tags,
		confidence,
		event,
		timestamp: new Date().toISOString(),
		version: 2,
		...(options.teamMember && { teamMember: options.teamMember }),
		...(options.currentProgress && { currentProgress: options.currentProgress }),
		...(options.bugsEncountered && { bugsEncountered: options.bugsEncountered }),
		...(options.workContext && { workContext: options.workContext }),
		...(options.domain && { domain: options.domain }),
		...(options.sourceSessionId && { sourceSessionId: options.sourceSessionId }),
		qualitySource: options.qualitySource,
		// Add cross-tool sharing identifiers (env vars take precedence for security)
		...((env.CIPHER_USER_ID || options.userId) && { userId: env.CIPHER_USER_ID || options.userId }),
		...((env.CIPHER_PROJECT_NAME || options.projectId) && {
			projectId: env.CIPHER_PROJECT_NAME || options.projectId,
		}),
		workspaceMode: env.CIPHER_WORKSPACE_MODE || options.workspaceMode || 'isolated',
	};
}

/**
 * Merge LLM-provided workspace info with regex-extracted info
 * LLM data takes precedence, regex fills gaps
 */
export function mergeWorkspaceInfo(
	llmProvided: Partial<{
		teamMember?: string;
		currentProgress?: {
			feature: string;
			status: 'in-progress' | 'completed' | 'blocked' | 'reviewing';
			completion?: number;
		};
		bugsEncountered?: Array<{
			description: string;
			severity: 'low' | 'medium' | 'high' | 'critical';
			status: 'open' | 'in-progress' | 'fixed';
		}>;
		workContext?: {
			project?: string;
			repository?: string;
			branch?: string;
		};
		domain?: string;
	}> = {},
	regexExtracted: ReturnType<typeof extractWorkspaceInfo>
): {
	teamMember?: string;
	currentProgress?: {
		feature: string;
		status: 'in-progress' | 'completed' | 'blocked' | 'reviewing';
		completion?: number;
	};
	bugsEncountered?: Array<{
		description: string;
		severity: 'low' | 'medium' | 'high' | 'critical';
		status: 'open' | 'in-progress' | 'fixed';
	}>;
	workContext?: {
		project?: string;
		repository?: string;
		branch?: string;
	};
	domain?: string;
} {
	const result: any = {};

	// Team member: LLM takes precedence
	result.teamMember = llmProvided.teamMember || regexExtracted.teamMember;

	// Current progress: merge intelligently
	if (llmProvided.currentProgress || regexExtracted.currentProgress) {
		result.currentProgress = {
			...regexExtracted.currentProgress,
			...llmProvided.currentProgress,
		};
	}

	// Bugs encountered: LLM takes precedence, or use regex if LLM not provided
	result.bugsEncountered = llmProvided.bugsEncountered || regexExtracted.bugsEncountered;

	// Work context: merge individual fields
	if (llmProvided.workContext || regexExtracted.workContext) {
		result.workContext = {
			...regexExtracted.workContext,
			...llmProvided.workContext,
		};
	}

	// Domain: LLM takes precedence
	result.domain = llmProvided.domain || regexExtracted.domain;

	return result;
}

/**
 * Extract workspace-relevant information from text
 */
export function extractWorkspaceInfo(text: string): {
	teamMember?: string;
	currentProgress?: {
		feature: string;
		status: 'in-progress' | 'completed' | 'blocked' | 'reviewing';
		completion?: number;
	};
	bugsEncountered?: Array<{
		description: string;
		severity: 'low' | 'medium' | 'high' | 'critical';
		status: 'open' | 'in-progress' | 'fixed';
	}>;
	workContext?: {
		project?: string;
		repository?: string;
		branch?: string;
	};
	domain?: string;
} {
	const result: any = {};

	// Extract team member patterns
	const teamMemberPatterns = [
		/(?:worked on by|assigned to|developer|dev|team member|teammate)\s+([a-zA-Z]+(?:\s+[a-zA-Z]+)?)/i,
		/(@[a-zA-Z_]+)/, // @username mentions
		/([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)\s+(?:is working on|completed|fixed|implemented)/i,
	];

	for (const pattern of teamMemberPatterns) {
		const match = text.match(pattern);
		if (match && match[1]) {
			result.teamMember = match[1].replace('@', '').trim();
			break;
		}
	}

	// Extract progress information
	const progressPatterns = [
		/(?:working on|implementing|developing|building)\s+([^.!?]+)/i,
		/(?:blocked on|stuck on|waiting on)\s+([^.!?]+)/i,
		/(?:feature|component|module):\s*([^.!?]+)/i,
		/(?:task|ticket|issue):\s*([^.!?]+)/i,
	];

	const statusPatterns = [
		{ pattern: /\b(?:completed|done|finished|deployed|released)\b/i, status: 'completed' as const },
		{ pattern: /\b(?:blocked|stuck|waiting|pending)\b/i, status: 'blocked' as const },
		{ pattern: /\b(?:reviewing|review|testing|qa)\b/i, status: 'reviewing' as const },
		{ pattern: /\b(?:in progress|ongoing|working|developing)\b/i, status: 'in-progress' as const },
	];

	for (const pattern of progressPatterns) {
		const match = text.match(pattern);
		if (match && match[1]) {
			const feature = match[1].trim();

			// Determine status
			let status: 'in-progress' | 'completed' | 'blocked' | 'reviewing' = 'in-progress';
			for (const statusPattern of statusPatterns) {
				if (statusPattern.pattern.test(text)) {
					status = statusPattern.status;
					break;
				}
			}

			// Extract completion percentage
			let completion: number | undefined;
			const completionMatch = text.match(/(\d+)%/);
			if (completionMatch && completionMatch[1]) {
				completion = parseInt(completionMatch[1], 10);
			}

			result.currentProgress = { feature, status, completion };
			break;
		}
	}

	// Extract bug information
	const bugPatterns = [
		/(?:bug|issue|error|problem):\s*([^.!?]+)/i,
		/(?:fixed|resolved|closed)\s+(?:bug|issue|error):\s*([^.!?]+)/i,
		/(?:critical|high|medium|low)\s+(?:priority|severity)\s+(?:bug|issue):\s*([^.!?]+)/i,
	];

	const severityPatterns = [
		{ pattern: /\bcritical\b/i, severity: 'critical' as const },
		{ pattern: /\bhigh\b/i, severity: 'high' as const },
		{ pattern: /\bmedium\b/i, severity: 'medium' as const },
		{ pattern: /\blow\b/i, severity: 'low' as const },
	];

	for (const pattern of bugPatterns) {
		const match = text.match(pattern);
		if (match && match[1]) {
			const description = match[1].trim();

			// Determine severity
			let severity: 'low' | 'medium' | 'high' | 'critical' = 'medium';
			for (const severityPattern of severityPatterns) {
				if (severityPattern.pattern.test(text)) {
					severity = severityPattern.severity;
					break;
				}
			}

			// Determine status
			let status: 'open' | 'in-progress' | 'fixed' = 'open';
			if (/\b(?:fixed|resolved|closed)\b/i.test(text)) {
				status = 'fixed';
			} else if (/\b(?:fixing|working on|investigating)\b/i.test(text)) {
				status = 'in-progress';
			}

			result.bugsEncountered = [{ description, severity, status }];
			break;
		}
	}

	// Extract work context
	const workContext: any = {};

	// Project patterns
	const projectPatterns = [
		/(?:project|app|application):\s*([a-zA-Z0-9_-]+)/i,
		/(?:in|for|on)\s+(?:the\s+)?([a-zA-Z0-9_-]+)\s+project/i,
	];

	for (const pattern of projectPatterns) {
		const match = text.match(pattern);
		if (match && match[1]) {
			workContext.project = match[1].trim();
			break;
		}
	}

	// Repository patterns
	const repoPatterns = [
		/(?:repo|repository):\s*([a-zA-Z0-9_/.-]+)/i,
		/(?:github\.com|gitlab\.com)\/([a-zA-Z0-9_/-]+)/i,
		/git\s+clone\s+.*\/([a-zA-Z0-9_-]+)\.git/i,
	];

	for (const pattern of repoPatterns) {
		const match = text.match(pattern);
		if (match && match[1]) {
			workContext.repository = match[1].trim();
			break;
		}
	}

	// Branch patterns
	const branchPatterns = [
		/(?:branch|git checkout)\s+([a-zA-Z0-9_/-]+)/i,
		/(?:on|in)\s+(?:the\s+)?([a-zA-Z0-9_/-]+)\s+branch/i,
		/(?:feature|hotfix|bugfix)\/([a-zA-Z0-9_/-]+)/i,
	];

	for (const pattern of branchPatterns) {
		const match = text.match(pattern);
		if (match && match[1]) {
			workContext.branch = match[1].trim();
			break;
		}
	}

	if (Object.keys(workContext).length > 0) {
		result.workContext = workContext;
	}

	// Extract domain
	const domainPatterns = [
		{
			pattern: /\b(?:frontend|front-end|ui|ux|react|vue|angular|html|css|javascript|typescript)\b/i,
			domain: 'frontend',
		},
		{
			pattern: /\b(?:backend|back-end|server|api|database|sql|node|express|django|flask)\b/i,
			domain: 'backend',
		},
		{
			pattern: /\b(?:devops|deployment|docker|kubernetes|ci|cd|pipeline|infrastructure)\b/i,
			domain: 'devops',
		},
		{
			pattern: /\b(?:testing|qa|quality|unit test|integration test|e2e)\b/i,
			domain: 'quality-assurance',
		},
		{ pattern: /\b(?:design|ux|ui|mockup|wireframe|prototype)\b/i, domain: 'design' },
	];

	for (const domainPattern of domainPatterns) {
		if (domainPattern.pattern.test(text)) {
			result.domain = domainPattern.domain;
			break;
		}
	}

	return result;
}

/**
 * Workspace Memory Tools Module
 *
 * This module exports workspace memory tools for team collaboration,
 * project progress tracking, and shared context management.
 */

import { workspaceSearchTool } from './workspace_search.js';
import { workspaceStoreTool } from './workspace_store.js';
import type { InternalTool } from '../../types.js';
import { env } from '../../../../env.js';
import { logger } from '../../../../logger/index.js';

// Export individual workspace tools
export { workspaceSearchTool, workspaceStoreTool };

// Export workspace payload utilities
export {
	createWorkspacePayload,
	extractWorkspaceInfo,
	type WorkspacePayload,
} from './workspace-payloads.js';

// Export workspace configuration
export {
	loadWorkspaceConfigFromEnv,
	validateWorkspaceMemoryConfig,
	DEFAULT_WORKSPACE_CONFIG,
	type WorkspaceMemoryConfig,
	type WorkspaceToolConfig,
	type WorkspaceBehaviorConfig,
} from '../../../../config/workspace-memory-config.schema.js';

/**
 * Array of all workspace memory tools
 */
export async function getWorkspaceToolsArray(
	options: { embeddingEnabled?: boolean } = {}
): Promise<InternalTool[]> {
	const toolMap = await getAllWorkspaceToolDefinitions(options);
	return Object.values(toolMap);
}

/**
 * Get all workspace tools as a map
 */
export async function getWorkspaceTools(
	options: { embeddingEnabled?: boolean } = {}
): Promise<Record<string, InternalTool>> {
	const { embeddingEnabled = true } = options;

	// Check if workspace memory is enabled
	if (env.USE_WORKSPACE_MEMORY !== true) {
		logger.debug('Workspace memory is disabled - excluding all workspace tools');
		return {};
	}

	// If embeddings are disabled, exclude all embedding-dependent tools
	if (!embeddingEnabled) {
		logger.warn('Embeddings disabled - excluding all embedding-dependent workspace tools', {
			excludedTools: ['cipher_workspace_search', 'cipher_workspace_store'],
		});
		return {};
	}

	return {
		cipher_workspace_search: workspaceSearchTool,
		cipher_workspace_store: workspaceStoreTool,
	};
}

/**
 * Get workspace tool definitions for registration
 */
export async function getAllWorkspaceToolDefinitions(
	options: { embeddingEnabled?: boolean } = {}
): Promise<Record<string, InternalTool>> {
	const { embeddingEnabled = true } = options;

	// Check if workspace memory is enabled
	if (env.USE_WORKSPACE_MEMORY !== true) {
		logger.debug('Workspace memory is disabled - no workspace tool definitions');
		return {};
	}

	// If embeddings are disabled, return empty tools
	if (!embeddingEnabled) {
		return {};
	}

	// Base workspace tools available when embeddings are enabled
	const tools: Record<string, InternalTool> = {
		workspace_search: workspaceSearchTool,
		workspace_store: workspaceStoreTool,
	};

	return tools;
}

/**
 * Check if default memory should be disabled when workspace memory is active
 */
export function shouldDisableDefaultMemory(): boolean {
	// Only disable default memory if BOTH conditions are explicitly true
	return env.USE_WORKSPACE_MEMORY === true && env.DISABLE_DEFAULT_MEMORY === true;
}

/**
 * Get the workspace vector store collection name
 */
export function getWorkspaceCollectionName(): string {
	return env.WORKSPACE_VECTOR_STORE_COLLECTION || 'workspace_memory';
}

/**
 * Workspace tool categories and descriptions
 */
export const WORKSPACE_TOOL_INFO = {
	workspace_search: {
		category: 'memory',
		purpose:
			'Search workspace memory for team and project information including progress, bugs, and collaboration context.',
		useCase:
			'Use when you need to find information about team activities, project status, bug reports, or collaboration history.',
	},
	workspace_store: {
		category: 'memory',
		purpose:
			'Background tool that automatically stores team-related information including project progress, bugs, and collaboration context.',
		useCase:
			'Automatically captures workspace information in the background to build team knowledge and project context.',
	},
} as const;

/**
 * Check if workspace memory is properly configured
 */
export function validateWorkspaceMemorySetup(): {
	isValid: boolean;
	issues: string[];
	warnings: string[];
} {
	const issues: string[] = [];
	const warnings: string[] = [];

	// Check if workspace memory is enabled
	if (!env.USE_WORKSPACE_MEMORY) {
		warnings.push('Workspace memory is disabled (USE_WORKSPACE_MEMORY=false)');
	}

	// Check if both workspace and default memory are enabled
	if (env.USE_WORKSPACE_MEMORY && !env.DISABLE_DEFAULT_MEMORY) {
		warnings.push(
			'Both workspace and default memory are enabled - consider setting DISABLE_DEFAULT_MEMORY=true for workspace-only mode'
		);
	}

	// Check collection name
	const collectionName = env.WORKSPACE_VECTOR_STORE_COLLECTION;
	if (!collectionName) {
		warnings.push('WORKSPACE_VECTOR_STORE_COLLECTION not set, using default "workspace_memory"');
	} else if (collectionName === env.VECTOR_STORE_COLLECTION) {
		issues.push(
			'Workspace and default memory collections have the same name - this will cause conflicts'
		);
	}

	// Check workspace vector store type
	if (
		env.WORKSPACE_VECTOR_STORE_TYPE &&
		env.WORKSPACE_VECTOR_STORE_TYPE !== env.VECTOR_STORE_TYPE
	) {
		warnings.push(
			`Workspace memory will use ${env.WORKSPACE_VECTOR_STORE_TYPE} while default memory uses ${env.VECTOR_STORE_TYPE}`
		);
	}

	return {
		isValid: issues.length === 0,
		issues,
		warnings,
	};
}

/**
 * Log workspace memory configuration status
 */
export function logWorkspaceMemoryStatus(): void {
	const validation = validateWorkspaceMemorySetup();

	if (env.USE_WORKSPACE_MEMORY) {
		logger.info('Workspace memory is enabled', {
			collection: getWorkspaceCollectionName(),
			disableDefault: env.DISABLE_DEFAULT_MEMORY,
			workspaceVectorStoreType: env.WORKSPACE_VECTOR_STORE_TYPE || 'same as default',
		});

		if (validation.warnings.length > 0) {
			logger.warn('Workspace memory configuration warnings', {
				warnings: validation.warnings,
			});
		}

		if (validation.issues.length > 0) {
			logger.error('Workspace memory configuration issues', {
				issues: validation.issues,
			});
		}
	} else {
		logger.debug('Workspace memory is disabled');
	}
}

