/**
 * Bash Command Tool for Cipher
 *
 * Provides bash command execution capabilities within the Cipher agent framework.
 * Adapted from OpenHands implementation with Cipher-specific integrations.
 */

import { spawn, ChildProcess } from 'child_process';
import { EventEmitter } from 'events';
import {
	createInternalToolName,
	type InternalTool,
	type InternalToolHandler,
} from '../../types.js';
import { logger } from '../../../../logger/index.js';

/**
 * Command execution result structure
 */
interface CommandResult {
	output: string;
	error: string;
	exitCode: number;
	command: string;
	duration: number;
	pid: number | undefined;
	workingDir: string | undefined;
}

/**
 * Command execution options
 */
interface CommandOptions {
	command: string;
	timeout?: number;
	workingDir?: string;
	environment?: Record<string, string>;
	shell?: string;
}

/**
 * Bash session manager for persistent command execution
 */
class BashSession extends EventEmitter {
	private process: ChildProcess | null = null;
	private outputBuffer = '';
	private errorBuffer = '';
	private isRunning = false;
	private currentWorkingDir: string;
	private sessionId: string;

	constructor(sessionId: string, workingDir: string = process.cwd()) {
		super();
		this.sessionId = sessionId;
		this.currentWorkingDir = workingDir;
	}

	/**
	 * Initialize the bash session
	 */
	async initialize(): Promise<void> {
		if (this.process) {
			logger.warn(`BashSession ${this.sessionId}: Already initialized`);
			return;
		}

		try {
			// Start bash process with non-interactive mode to avoid prompt issues
			this.process = spawn('/bin/bash', [], {
				cwd: this.currentWorkingDir,
				stdio: ['pipe', 'pipe', 'pipe'],
				env: { ...process.env },
			});

			this.isRunning = true;

			// Handle process output
			this.process.stdout?.on('data', (data: Buffer) => {
				this.outputBuffer += data.toString();
			});

			this.process.stderr?.on('data', (data: Buffer) => {
				this.errorBuffer += data.toString();
			});

			this.process.on('exit', (code, signal) => {
				this.isRunning = false;
				logger.debug(
					`BashSession ${this.sessionId}: Process exited with code ${code}, signal ${signal}`
				);
				this.emit('exit', { code, signal });
			});

			this.process.on('error', error => {
				this.isRunning = false;
				logger.error(`BashSession ${this.sessionId}: Process error`, error);
				this.emit('error', error);
			});

			// Give the process a moment to start
			await new Promise(resolve => setTimeout(resolve, 100));

			logger.debug(`BashSession ${this.sessionId}: Initialized successfully`);
		} catch (error) {
			logger.error(`BashSession ${this.sessionId}: Failed to initialize`, error);
			throw error;
		}
	}

	/**
	 * Execute a command in the session
	 */
	async executeCommand(command: string, timeout: number = 30000): Promise<CommandResult> {
		if (!this.process || !this.isRunning) {
			throw new Error('Bash session is not running');
		}

		const startTime = Date.now();

		// Clear buffers for this command
		this.outputBuffer = '';
		this.errorBuffer = '';

		return new Promise<CommandResult>((resolve, reject) => {
			const timeoutId = setTimeout(() => {
				reject(new Error(`Command timeout after ${timeout}ms`));
			}, timeout);

			// Send command with a unique marker to detect completion
			const marker = `CMD_COMPLETE_${Date.now()}`;
			const fullCommand = `${command}; echo "${marker}"; echo "EXIT_CODE:$?" `;
			this.process!.stdin?.write(`${fullCommand}\n`);

			// Wait for command completion
			const checkCompletion = () => {
				if (this.outputBuffer.includes(marker)) {
					clearTimeout(timeoutId);

					// Extract output before the marker
					const parts = this.outputBuffer.split(marker);
					const output = parts[0]?.trim() || '';

					// Try to extract exit code
					const exitCodeMatch = this.outputBuffer.match(/EXIT_CODE:(\d+)/);
					const exitCode = exitCodeMatch?.[1] ? parseInt(exitCodeMatch[1], 10) : 0;

					const result: CommandResult = {
						output,
						error: this.errorBuffer.trim(),
						exitCode,
						command,
						duration: Date.now() - startTime,
						pid: this.process?.pid,
						workingDir: this.currentWorkingDir || undefined,
					};

					resolve(result);
				} else {
					setTimeout(checkCompletion, 100);
				}
			};

			// Start checking after a brief delay
			setTimeout(checkCompletion, 50);
		});
	}

	/**
	 * Close the bash session
	 */
	async close(): Promise<void> {
		if (this.process) {
			this.process.stdin?.write('exit\n');
			this.process.kill();
			this.process = null;
			this.isRunning = false;
			logger.debug(`BashSession ${this.sessionId}: Closed`);
		}
	}

	/**
	 * Check if session is running
	 */
	isActive(): boolean {
		return this.isRunning && this.process !== null;
	}
}

/**
 * Session manager for maintaining multiple bash sessions
 */
class BashSessionManager {
	private sessions = new Map<string, BashSession>();
	private static instance: BashSessionManager;

	static getInstance(): BashSessionManager {
		if (!BashSessionManager.instance) {
			BashSessionManager.instance = new BashSessionManager();
		}
		return BashSessionManager.instance;
	}

	/**
	 * Get or create a bash session
	 */
	async getSession(sessionId: string, workingDir?: string): Promise<BashSession> {
		let session = this.sessions.get(sessionId);

		if (!session || !session.isActive()) {
			session = new BashSession(sessionId, workingDir);
			await session.initialize();
			this.sessions.set(sessionId, session);
		}

		return session;
	}

	/**
	 * Close a specific session
	 */
	async closeSession(sessionId: string): Promise<void> {
		const session = this.sessions.get(sessionId);
		if (session) {
			await session.close();
			this.sessions.delete(sessionId);
		}
	}

	/**
	 * Close all sessions
	 */
	async closeAllSessions(): Promise<void> {
		const closePromises = Array.from(this.sessions.values()).map(session => session.close());
		await Promise.all(closePromises);
		this.sessions.clear();
	}
}

/**
 * Execute a bash command with optional session persistence
 */
async function executeBashCommand(options: CommandOptions): Promise<CommandResult> {
	const { command, timeout = 30000, workingDir, environment, shell = '/bin/bash' } = options;

	logger.debug('Executing bash command', { command, timeout, workingDir });

	const startTime = Date.now();

	return new Promise<CommandResult>((resolve, reject) => {
		const timeoutId = setTimeout(() => {
			reject(new Error(`Command timeout after ${timeout}ms`));
		}, timeout);

		let output = '';
		let error = '';

		const childProcess = spawn(shell, ['-c', command], {
			cwd: workingDir || process.cwd(),
			env: { ...process.env, ...environment },
			stdio: ['pipe', 'pipe', 'pipe'],
		});

		childProcess.stdout?.on('data', (data: Buffer) => {
			output += data.toString();
		});

		childProcess.stderr?.on('data', (data: Buffer) => {
			error += data.toString();
		});

		childProcess.on('close', (code: number | null) => {
			clearTimeout(timeoutId);

			const result: CommandResult = {
				output: output.trim(),
				error: error.trim(),
				exitCode: code || 0,
				command,
				duration: Date.now() - startTime,
				pid: childProcess.pid,
				workingDir: workingDir || process.cwd() || undefined,
			};

			logger.debug('Bash command completed', {
				command,
				exitCode: result.exitCode,
				duration: result.duration,
			});

			resolve(result);
		});

		childProcess.on('error', (err: Error) => {
			clearTimeout(timeoutId);
			logger.error('Bash command failed', { command, error: err.message });
			reject(err);
		});
	});
}

/**
 * Bash tool handler implementation
 */
const bashHandler: InternalToolHandler = async (args, context) => {
	const {
		command,
		timeout = 30000,
		workingDir,
		persistent = false,
		sessionId: customSessionId,
	} = args;

	if (!command || typeof command !== 'string') {
		return {
			content: 'Error: Command is required and must be a string',
			isError: true,
		};
	}

	try {
		let result: CommandResult;

		if (persistent) {
			// Use persistent session
			const sessionManager = BashSessionManager.getInstance();
			const sessionId = customSessionId || context?.sessionId || 'default';
			const session = await sessionManager.getSession(sessionId, workingDir);
			result = await session.executeCommand(command, timeout);
		} else {
			// Execute as one-off command
			result = await executeBashCommand({
				command,
				timeout,
				workingDir,
			});
		}

		// Format result for agent consumption
		const formattedOutput = [
			`Command: ${result.command}`,
			`Exit Code: ${result.exitCode}`,
			`Duration: ${result.duration}ms`,
			result.workingDir ? `Working Dir: ${result.workingDir}` : '',
			'',
			'Output:',
			result.output || '(no output)',
			result.error ? '\nError:' : '',
			result.error || '',
		]
			.filter(Boolean)
			.join('\n');

		// Store command result in memory if context has services
		if (context?.services?.vectorStoreManager && result.output) {
			try {
				// This would typically go through the memory extraction system
				logger.debug('Command result could be stored in memory', { command });
			} catch (memoryError) {
				logger.warn('Failed to store command result in memory', memoryError);
			}
		}

		return {
			content: formattedOutput,
			isError: result.exitCode !== 0,
		};
	} catch (error) {
		const errorMessage = error instanceof Error ? error.message : String(error);
		logger.error('Bash tool execution failed', { command, error: errorMessage });

		return {
			content: `Error executing command: ${errorMessage}`,
			isError: true,
		};
	}
};

/**
 * Bash tool definition
 */
export const bashTool: InternalTool = {
	name: createInternalToolName('bash'),
	category: 'system',
	internal: true,
	agentAccessible: true,
	description:
		'Execute bash commands in the system shell. Supports both one-off commands and persistent session execution.',
	parameters: {
		type: 'object',
		properties: {
			command: {
				type: 'string',
				description:
					'The bash command to execute. Can be a single command or a chain of commands using && or ;',
			},
			timeout: {
				type: 'number',
				description: 'Timeout in milliseconds for command execution (default: 30000)',
				default: 30000,
			},
			workingDir: {
				type: 'string',
				description: 'Working directory for command execution (defaults to current directory)',
			},
			persistent: {
				type: 'boolean',
				description: 'Whether to use a persistent bash session (maintains state between commands)',
				default: false,
			},
			sessionId: {
				type: 'string',
				description: 'Session ID for persistent sessions (defaults to context session ID)',
			},
		},
		required: ['command'],
	},
	handler: bashHandler,
	version: '1.0.0',
};

// Export session manager for cleanup
export { BashSessionManager };

/**
 * System Tools Module
 *
 * Provides system-level operations including bash command execution,
 * file operations, and system information gathering.
 */

import type { InternalToolSet } from '../../types.js';
import { bashTool } from './bash.js';

/**
 * Get all system tools
 */
export function getSystemTools(): InternalToolSet {
	return {
		[bashTool.name]: bashTool,
	};
}

export { bashTool };

/**
 * Internal Tools Module
 *
 * This module provides internal tools for the Cipher agent, including
 * memory management, session control, and system operations.
 *
 * @example
 * ```typescript
 * import { InternalToolManager, InternalToolRegistry } from '@core/brain/tools';
 *
 * const manager = new InternalToolManager();
 * await manager.initialize();
 *
 * // Register a tool
 * const result = manager.registerTool(myTool);
 *
 * // Execute a tool
 * const output = await manager.executeTool('cipher_my_tool', args);
 * ```
 */

// Core types
export type {
	InternalTool,
	InternalToolSet,
	InternalToolCategory,
	InternalToolHandler,
	InternalToolManagerConfig,
	InternalToolContext,
	ToolExecutionStats,
	ToolRegistrationResult,
	IInternalToolManager,
} from './types.js';

// Constants and utilities
export { INTERNAL_TOOL_PREFIX, createInternalToolName, isInternalToolName } from './types.js';

// Core classes
export { InternalToolRegistry } from './registry.js';
export { InternalToolManager } from './manager.js';
export { UnifiedToolManager } from './unified-tool-manager.js';
export type { UnifiedToolManagerConfig, CombinedToolSet } from './unified-tool-manager.js';

// Import types for use in functions
import type { InternalToolCategory, InternalToolManagerConfig } from './types.js';
import { InternalToolManager } from './manager.js';
import { InternalToolRegistry } from './registry.js';

// Version and metadata
export const INTERNAL_TOOLS_VERSION = '1.0.0';
export const SUPPORTED_CATEGORIES: InternalToolCategory[] = ['memory', 'session', 'system'];

/**
 * Create a new internal tool manager with optional configuration
 */
export function createInternalToolManager(config?: InternalToolManagerConfig): InternalToolManager {
	return new InternalToolManager(config);
}

/**
 * Get the singleton registry instance
 */
export function getInternalToolRegistry(): InternalToolRegistry {
	return InternalToolRegistry.getInstance();
}

/**
 * Internal Tool Manager
 *
 * Manages execution of internal tools with caching, statistics tracking,
 * and integration with the broader agent architecture.
 */

import { logger } from '../../logger/index.js';
import { ToolExecutionResult } from '../../mcp/types.js';
import { InternalToolRegistry } from './registry.js';
import {
	IInternalToolManager,
	InternalTool,
	InternalToolSet,
	InternalToolCategory,
	InternalToolManagerConfig,
	InternalToolContext,
	ToolExecutionStats,
	createInternalToolName,
} from './types.js';
import { EventManager } from '../../events/event-manager.js';
import { SessionEvents } from '../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

/**
 * Cache entry for tool execution statistics
 */
interface StatsEntry {
	stats: ToolExecutionStats;
	executionTimes: number[];
	maxHistorySize: number;
}

/**
 * Default configuration for the internal tool manager
 */
const DEFAULT_CONFIG: Required<InternalToolManagerConfig> = {
	enabled: true,
	timeout: 30000, // 30 seconds
	enableCache: true,
	cacheTimeout: 300000, // 5 minutes
};

/**
 * Internal Tool Manager implementation
 */
export class InternalToolManager implements IInternalToolManager {
	private config: Required<InternalToolManagerConfig>;
	private registry: InternalToolRegistry;
	private initialized = false;
	private stats = new Map<string, StatsEntry>();
	private readonly maxExecutionHistorySize = 100;
	private eventManager?: EventManager;
	private services?: {
		embeddingManager?: any;
		vectorStoreManager?: any;
		llmService?: any;
		knowledgeGraphManager?: any;
	};

	constructor(config: InternalToolManagerConfig = {}) {
		this.config = { ...DEFAULT_CONFIG, ...config };
		this.registry = InternalToolRegistry.getInstance();

		// Initialize with mock services for testing environments
		this.services = {
			embeddingManager: {
				getEmbedder: () => ({
					embed: async (_text: string) =>
						Array(128)
							.fill(0)
							.map(() => Math.random()),
				}),
			},
			vectorStoreManager: {
				getStore: () => ({
					search: async (_embedding: number[], _maxResults: number = 5) => [
						{
							id: 1,
							score: 0.7,
							payload: { text: 'Similar existing memory', tags: ['programming'] },
						},
					],
					insert: async (_embeddings: number[][], _ids: number[], _payloads: any[]) => {
						// Mock successful insert
						return;
					},
					update: async (_id: number, _embedding: number[], _payload: any) => {
						// Mock successful update
						return;
					},
					delete: async (_id: number) => {
						// Mock successful delete
						return;
					},
				}),
			},
			llmService: {
				directGenerate: async (_prompt: string) =>
					'Operation: ADD\nConfidence: 0.8\nReasoning: New technical information to store',
			},
		};
	}

	/**
	 * Initialize the internal tool manager
	 */
	public async initialize(): Promise<void> {
		if (this.initialized) {
			logger.warn('InternalToolManager: Already initialized');
			return;
		}

		if (!this.config.enabled) {
			logger.debug('InternalToolManager: Disabled by configuration');
			this.initialized = true; // Mark as initialized even when disabled
			return;
		}

		try {
			// InternalToolManager initialization logging reduced for cleaner CLI

			// Initialize the registry
			await this.registry.initialize();

			this.initialized = true;
			// InternalToolManager initialization success logging reduced for cleaner CLI
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(`InternalToolManager: Initialization failed: ${errorMessage}`);
			throw error;
		}
	}

	/**
	 * Register a new internal tool
	 */
	public registerTool(tool: InternalTool): {
		success: boolean;
		message: string;
		conflictedWith?: string;
	} {
		this.ensureInitialized();

		const result = this.registry.registerTool(tool);

		if (result.success) {
			// Initialize stats for the new tool using normalized name
			const normalizedName = createInternalToolName(tool.name);
			this.initializeToolStats(normalizedName);
			// Individual tool registration logging removed to reduce CLI noise
		} else {
			logger.warn(`InternalToolManager: Failed to register tool '${tool.name}': ${result.message}`);
		}

		return result;
	}

	/**
	 * Unregister an internal tool
	 */
	public unregisterTool(toolName: string): boolean {
		this.ensureInitialized();

		const normalizedName = createInternalToolName(toolName);
		const result = this.registry.unregisterTool(normalizedName);

		if (result) {
			// Clear stats for the removed tool
			this.stats.delete(normalizedName);
			logger.info(`InternalToolManager: Successfully unregistered tool '${normalizedName}'`);
		}

		return result;
	}

	/**
	 * Get all registered internal tools
	 */
	public getAllTools(): InternalToolSet {
		this.ensureInitialized();
		return this.registry.getAllTools();
	}

	/**
	 * Get a specific internal tool by name
	 */
	public getTool(toolName: string): InternalTool | undefined {
		this.ensureInitialized();
		return this.registry.getTool(toolName);
	}

	/**
	 * Check if a tool name is an internal tool
	 */
	public isInternalTool(toolName: string): boolean {
		if (!this.initialized || !this.config.enabled) {
			return false;
		}
		// Check both prefixed and non-prefixed versions
		const normalizedName = createInternalToolName(toolName);
		return this.registry.isInternalTool(toolName) || this.registry.isInternalTool(normalizedName);
	}

	/**
	 * Execute an internal tool
	 */
	public async executeTool(
		toolName: string,
		args: any,
		context?: Partial<InternalToolContext>
	): Promise<ToolExecutionResult> {
		this.ensureInitialized();

		const startTime = Date.now();
		const normalizedName = createInternalToolName(toolName);
		const executionId = uuidv4();

		// Get the tool
		const tool = this.registry.getTool(normalizedName);
		if (!tool) {
			throw new Error(`Internal tool '${normalizedName}' not found`);
		}

		// Create execution context
		const execContext: InternalToolContext = {
			toolName,
			startTime,
			sessionId: context?.sessionId,
			userId: context?.userId || '',
			metadata: context?.metadata,
			services: {
				...this.services,
				...context?.services,
			},
		};

		// Emit tool execution started event
		if (this.eventManager && execContext.sessionId) {
			this.eventManager.emitSessionEvent(
				execContext.sessionId,
				SessionEvents.TOOL_EXECUTION_STARTED,
				{
					toolName: normalizedName,
					toolType: 'internal',
					sessionId: execContext.sessionId,
					executionId,
					timestamp: startTime,
				}
			);
		}

		logger.debug(`InternalToolManager: Executing tool '${normalizedName}'`, {
			toolName: normalizedName,
			category: tool.category,
			hasArgs: !!args,
			sessionId: execContext.sessionId,
			executionId,
		});

		try {
			// Execute with timeout
			const result = await this.executeWithTimeout(tool, args, execContext);

			// Record successful execution
			const executionTime = Date.now() - startTime;
			this.recordExecution(normalizedName, true, executionTime);

			// Emit tool execution completed event
			if (this.eventManager && execContext.sessionId) {
				this.eventManager.emitSessionEvent(
					execContext.sessionId,
					SessionEvents.TOOL_EXECUTION_COMPLETED,
					{
						toolName: normalizedName,
						toolType: 'internal',
						sessionId: execContext.sessionId,
						executionId,
						duration: executionTime,
						success: true,
						timestamp: Date.now(),
					}
				);
			}

			logger.debug(`InternalToolManager: Tool '${normalizedName}' executed successfully`, {
				toolName: normalizedName,
				executionTime,
				executionId,
			});

			return result;
		} catch (error) {
			// Record failed execution
			const executionTime = Date.now() - startTime;
			this.recordExecution(normalizedName, false, executionTime);

			const errorMessage = error instanceof Error ? error.message : String(error);

			// Emit tool execution failed event
			if (this.eventManager && execContext.sessionId) {
				this.eventManager.emitSessionEvent(
					execContext.sessionId,
					SessionEvents.TOOL_EXECUTION_FAILED,
					{
						toolName: normalizedName,
						toolType: 'internal',
						sessionId: execContext.sessionId,
						executionId,
						error: errorMessage,
						duration: executionTime,
						timestamp: Date.now(),
					}
				);
			}

			logger.error(`InternalToolManager: Tool '${normalizedName}' execution failed`, {
				toolName: normalizedName,
				error: errorMessage,
				executionTime,
				executionId,
			});

			throw new Error(`Internal tool execution failed: ${errorMessage}`);
		}
	}

	/**
	 * Get tools by category
	 */
	public getToolsByCategory(category: InternalToolCategory): InternalToolSet {
		this.ensureInitialized();
		return this.registry.getToolsByCategory(category);
	}

	/**
	 * Get execution statistics for a tool
	 */
	public getToolStats(toolName: string): ToolExecutionStats | undefined {
		const normalizedName = createInternalToolName(toolName);
		const entry = this.stats.get(normalizedName);
		return entry ? { ...entry.stats } : undefined;
	}

	/**
	 * Get overall manager statistics
	 */
	public getManagerStats(): {
		totalTools: number;
		toolsByCategory: Record<InternalToolCategory, number>;
		totalExecutions: number;
	} {
		this.ensureInitialized();

		const registryStats = this.registry.getRegistryStats();
		let totalExecutions = 0;

		for (const entry of this.stats.values()) {
			totalExecutions += entry.stats.totalExecutions;
		}

		return {
			totalTools: registryStats.totalTools,
			toolsByCategory: registryStats.toolsByCategory,
			totalExecutions,
		};
	}

	/**
	 * Get all tool statistics
	 */
	public getStatistics(): Record<string, ToolExecutionStats> {
		const allStats: Record<string, ToolExecutionStats> = {};

		for (const [toolName, entry] of this.stats.entries()) {
			allStats[toolName] = { ...entry.stats };
		}

		return allStats;
	}

	/**
	 * Get available tools list
	 */
	public async getAvailableTools(): Promise<
		Array<{ name: string; description: string; category: string }>
	> {
		this.ensureInitialized();

		const tools = this.registry.getAllTools();
		return Object.values(tools).map(tool => ({
			name: tool.name,
			description: tool.description,
			category: tool.category,
		}));
	}

	/**
	 * Clear all execution statistics
	 */
	public clearStats(): void {
		this.stats.clear();
		logger.info('InternalToolManager: Cleared all execution statistics');
	}

	/**
	 * Shutdown the internal tool manager
	 */
	public async shutdown(): Promise<void> {
		if (!this.initialized) {
			return;
		}

		try {
			logger.info('InternalToolManager: Shutting down...');

			// Clear all data
			this.clearStats();
			this.registry.clear();

			this.initialized = false;
			logger.info('InternalToolManager: Shutdown completed');
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(`InternalToolManager: Shutdown failed: ${errorMessage}`);
			throw error;
		}
	}

	/**
	 * Execute tool with timeout handling
	 */
	private async executeWithTimeout(
		tool: InternalTool,
		args: any,
		context: InternalToolContext
	): Promise<ToolExecutionResult> {
		return new Promise((resolve, reject) => {
			const timeoutId = setTimeout(() => {
				reject(new Error(`Tool execution timeout after ${this.config.timeout}ms`));
			}, this.config.timeout);

			tool
				.handler(args, context)
				.then(result => {
					clearTimeout(timeoutId);
					resolve(result);
				})
				.catch(error => {
					clearTimeout(timeoutId);
					reject(error);
				});
		});
	}

	/**
	 * Record tool execution statistics
	 */
	private recordExecution(toolName: string, success: boolean, executionTime: number): void {
		let entry = this.stats.get(toolName);

		if (!entry) {
			entry = this.createStatsEntry(toolName);
			this.stats.set(toolName, entry);
		}

		// Update statistics
		entry.stats.totalExecutions++;
		entry.stats.lastExecution = new Date().toISOString();

		if (success) {
			entry.stats.successfulExecutions++;
		} else {
			entry.stats.failedExecutions++;
		}

		// Update execution times for average calculation
		entry.executionTimes.push(executionTime);

		// Keep only recent execution times for memory efficiency
		if (entry.executionTimes.length > entry.maxHistorySize) {
			entry.executionTimes = entry.executionTimes.slice(-entry.maxHistorySize);
		}

		// Calculate average execution time
		entry.stats.averageExecutionTime =
			entry.executionTimes.reduce((sum, time) => sum + time, 0) / entry.executionTimes.length;
	}

	/**
	 * Initialize statistics for a tool
	 */
	private initializeToolStats(toolName: string): void {
		// toolName should already be normalized when called from registerTool
		if (!this.stats.has(toolName)) {
			this.stats.set(toolName, this.createStatsEntry(toolName));
		}
	}

	/**
	 * Create a new stats entry
	 */
	private createStatsEntry(toolName: string): StatsEntry {
		return {
			stats: {
				toolName,
				totalExecutions: 0,
				successfulExecutions: 0,
				failedExecutions: 0,
				averageExecutionTime: 0,
			},
			executionTimes: [],
			maxHistorySize: this.maxExecutionHistorySize,
		};
	}

	/**
	 * Ensure the manager is initialized
	 */
	private ensureInitialized(): void {
		if (!this.initialized) {
			throw new Error(
				'InternalToolManager must be initialized before use. Call initialize() first.'
			);
		}

		if (!this.config.enabled) {
			throw new Error('InternalToolManager is disabled by configuration');
		}
	}

	/**
	 * Get configuration
	 */
	public getConfig(): Required<InternalToolManagerConfig> {
		return { ...this.config };
	}

	/**
	 * Check if manager is initialized
	 */
	public isInitialized(): boolean {
		return this.initialized;
	}

	/**
	 * Check if manager is enabled
	 */
	public isEnabled(): boolean {
		return this.config.enabled;
	}

	/**
	 * Set agent services for tools that need access to them
	 */
	public setServices(services: {
		embeddingManager?: any;
		vectorStoreManager?: any;
		llmService?: any;
		knowledgeGraphManager?: any;
	}): void {
		this.services = services;
		// InternalToolManager services configuration logging reduced for cleaner CLI
	}

	/**
	 * Set the event manager for emitting tool execution events
	 */
	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}
}

/**
 * Internal Tool Registry
 *
 * Singleton registry for managing internal tool registration, validation,
 * and lookup operations with O(1) performance.
 */

import { logger } from '../../logger/index.js';
import {
	InternalTool,
	InternalToolSet,
	InternalToolCategory,
	createInternalToolName,
} from './types.js';

/**
 * Registry for managing internal tools with singleton pattern
 */
export class InternalToolRegistry {
	private static instance: InternalToolRegistry | null = null;

	private tools = new Map<string, InternalTool>();
	private toolsByCategory = new Map<InternalToolCategory, Set<string>>();
	private initialized = false;

	private constructor() {
		// Initialize category maps
		this.toolsByCategory.set('memory', new Set());
		this.toolsByCategory.set('session', new Set());
		this.toolsByCategory.set('system', new Set());
	}

	/**
	 * Get the singleton instance of the registry
	 */
	public static getInstance(): InternalToolRegistry {
		if (!InternalToolRegistry.instance) {
			InternalToolRegistry.instance = new InternalToolRegistry();
		}
		return InternalToolRegistry.instance;
	}

	/**
	 * Initialize the registry
	 */
	public async initialize(): Promise<void> {
		if (this.initialized) {
			logger.warn('InternalToolRegistry: Already initialized');
			return;
		}

		logger.info('InternalToolRegistry: Initializing...');
		this.initialized = true;
		logger.info('InternalToolRegistry: Initialized successfully');
	}

	/**
	 * Register a new internal tool
	 */
	public registerTool(tool: InternalTool): {
		success: boolean;
		message: string;
		conflictedWith?: string;
	} {
		try {
			// Validate tool structure
			const validation = this.validateTool(tool);
			if (!validation.valid) {
				return {
					success: false,
					message: `Tool validation failed: ${validation.error}`,
				};
			}

			// Ensure proper naming
			const toolName = createInternalToolName(tool.name);

			// Check for conflicts
			if (this.tools.has(toolName)) {
				return {
					success: false,
					message: `Tool '${toolName}' is already registered`,
					conflictedWith: toolName,
				};
			}

			// Update tool name if it was modified
			const normalizedTool: InternalTool = {
				...tool,
				name: toolName,
			};

			// Register the tool
			this.tools.set(toolName, normalizedTool);

			// Update category index
			const categorySet = this.toolsByCategory.get(tool.category);
			if (categorySet) {
				categorySet.add(toolName);
			}

			// Individual tool registration logging removed to reduce CLI noise

			return {
				success: true,
				message: `Tool '${toolName}' registered successfully`,
			};
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(`InternalToolRegistry: Failed to register tool '${tool.name}': ${errorMessage}`);

			return {
				success: false,
				message: `Registration failed: ${errorMessage}`,
			};
		}
	}

	/**
	 * Unregister an internal tool
	 */
	public unregisterTool(toolName: string): boolean {
		try {
			const normalizedName = createInternalToolName(toolName);

			const tool = this.tools.get(normalizedName);
			if (!tool) {
				logger.warn(`InternalToolRegistry: Tool '${normalizedName}' not found for unregistration`);
				return false;
			}

			// Remove from main registry
			this.tools.delete(normalizedName);

			// Remove from category index
			const categorySet = this.toolsByCategory.get(tool.category);
			if (categorySet) {
				categorySet.delete(normalizedName);
			}

			logger.debug(`InternalToolRegistry: Unregistered tool '${normalizedName}'`);
			return true;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error(
				`InternalToolRegistry: Failed to unregister tool '${toolName}': ${errorMessage}`
			);
			return false;
		}
	}

	/**
	 * Get a specific tool by name
	 */
	public getTool(toolName: string): InternalTool | undefined {
		const normalizedName = createInternalToolName(toolName);
		return this.tools.get(normalizedName);
	}

	/**
	 * Get all registered tools
	 */
	public getAllTools(): InternalToolSet {
		const toolSet: InternalToolSet = {};

		for (const [name, tool] of this.tools) {
			toolSet[name] = tool;
		}

		return toolSet;
	}

	/**
	 * Get tools by category
	 */
	public getToolsByCategory(category: InternalToolCategory): InternalToolSet {
		const toolSet: InternalToolSet = {};
		const categorySet = this.toolsByCategory.get(category);

		if (categorySet) {
			for (const toolName of categorySet) {
				const tool = this.tools.get(toolName);
				if (tool) {
					toolSet[toolName] = tool;
				}
			}
		}

		return toolSet;
	}

	/**
	 * Check if a tool is registered
	 */
	public hasTool(toolName: string): boolean {
		const normalizedName = createInternalToolName(toolName);
		return this.tools.has(normalizedName);
	}

	/**
	 * Check if a tool name is an internal tool
	 */
	public isInternalTool(toolName: string): boolean {
		// Check both prefixed and non-prefixed versions
		const normalizedName = createInternalToolName(toolName);
		return this.hasTool(normalizedName) || this.hasTool(toolName);
	}

	/**
	 * Get the total number of registered tools
	 */
	public getToolCount(): number {
		return this.tools.size;
	}

	/**
	 * Get tool count by category
	 */
	public getToolCountByCategory(): Record<InternalToolCategory, number> {
		const memoryCount = this.toolsByCategory.get('memory')?.size || 0;
		const sessionCount = this.toolsByCategory.get('session')?.size || 0;
		const systemCount = this.toolsByCategory.get('system')?.size || 0;
		const knowledgeGraphCount = this.toolsByCategory.get('knowledge_graph')?.size || 0;

		return {
			memory: memoryCount,
			session: sessionCount,
			system: systemCount,
			knowledge_graph: knowledgeGraphCount,
		};
	}

	/**
	 * Get all tool names
	 */
	public getToolNames(): string[] {
		return Array.from(this.tools.keys());
	}

	/**
	 * Get tool names by category
	 */
	public getToolNamesByCategory(category: InternalToolCategory): string[] {
		const categorySet = this.toolsByCategory.get(category);
		return categorySet ? Array.from(categorySet) : [];
	}

	/**
	 * Clear all registered tools
	 */
	public clear(): void {
		this.tools.clear();

		for (const categorySet of this.toolsByCategory.values()) {
			categorySet.clear();
		}

		logger.info('InternalToolRegistry: Cleared all registered tools');
	}

	/**
	 * Validate tool structure and properties
	 */
	private validateTool(tool: InternalTool): { valid: boolean; error?: string } {
		// Check required properties
		if (!tool.name || typeof tool.name !== 'string') {
			return { valid: false, error: 'Tool name is required and must be a string' };
		}

		if (!tool.description || typeof tool.description !== 'string') {
			return { valid: false, error: 'Tool description is required and must be a string' };
		}

		// Use all available categories instead of hardcoded list
		const validCategories: InternalToolCategory[] = [
			'memory',
			'session',
			'system',
			'knowledge_graph',
		];
		if (!tool.category || !validCategories.includes(tool.category)) {
			return { valid: false, error: `Tool category must be one of: ${validCategories.join(', ')}` };
		}

		if (tool.internal !== true) {
			return { valid: false, error: 'Tool must have internal property set to true' };
		}

		if (!tool.handler || typeof tool.handler !== 'function') {
			return { valid: false, error: 'Tool handler is required and must be a function' };
		}

		if (!tool.parameters || typeof tool.parameters !== 'object') {
			return { valid: false, error: 'Tool parameters are required and must be an object' };
		}

		// Validate parameters structure
		if (tool.parameters.type !== 'object') {
			return { valid: false, error: 'Tool parameters type must be "object"' };
		}

		if (!tool.parameters.properties || typeof tool.parameters.properties !== 'object') {
			return { valid: false, error: 'Tool parameters must have a properties object' };
		}

		// Tool name should not conflict with MCP naming conventions
		if (tool.name.includes('.') && !tool.name.startsWith('cipher_')) {
			return { valid: false, error: 'Tool names with dots should start with cipher_ prefix' };
		}

		return { valid: true };
	}

	/**
	 * Get registry statistics
	 */
	public getRegistryStats(): {
		totalTools: number;
		toolsByCategory: Record<InternalToolCategory, number>;
		initialized: boolean;
	} {
		return {
			totalTools: this.getToolCount(),
			toolsByCategory: this.getToolCountByCategory(),
			initialized: this.initialized,
		};
	}

	/**
	 * Reset the singleton instance (mainly for testing)
	 */
	public static reset(): void {
		InternalToolRegistry.instance = null;
	}
}

/**
 * Core types and interfaces for the internal tools system.
 *
 * This module defines the type system for internal tools that work alongside
 * MCP tools to provide built-in agent capabilities like memory management,
 * session control, and system operations.
 */

import { Tool, ToolExecutionResult } from '../../mcp/types.js';
import type { EmbeddingManager } from '../embedding/index.js';
import type { VectorStoreManager } from '../../vector_storage/index.js';
import type { ILLMService } from '../llm/index.js';
import type { KnowledgeGraphManager } from '../../knowledge_graph/manager.js';

/**
 * Categories for organizing internal tools
 */
export type InternalToolCategory = 'memory' | 'session' | 'system' | 'knowledge_graph';

/**
 * Internal tool handler function signature
 */
export type InternalToolHandler<T = any, R = any> = (
	args: T,
	context?: InternalToolContext
) => Promise<R>;

/**
 * Internal tool definition extending the base Tool interface
 */
export interface InternalTool extends Tool {
	/**
	 * Unique name for the tool (should be prefixed with 'cipher_')
	 */
	name: string;

	/**
	 * Category for organizing tools
	 */
	category: InternalToolCategory;

	/**
	 * Marker to identify this as an internal tool
	 */
	internal: true;

	/**
	 * Whether this tool should be accessible to agents
	 * - true: Tool can be called by agents (e.g., search tools)
	 * - false: Tool is internal-only, used for background processing (e.g., extraction, storage)
	 * @default true
	 */
	agentAccessible?: boolean;

	/**
	 * Handler function that executes the tool
	 */
	handler: InternalToolHandler;

	/**
	 * Optional version for tool evolution
	 */
	version?: string;

	/**
	 * Human-readable description
	 */
	description: string;

	/**
	 * JSON schema for parameters
	 */
	parameters: {
		type: 'object';
		properties: Record<string, any>;
		required?: string[];
	};
}

/**
 * Collection of internal tools indexed by their names
 */
export interface InternalToolSet {
	[toolName: string]: InternalTool;
}

/**
 * Configuration for the internal tool manager
 */
export interface InternalToolManagerConfig {
	/**
	 * Whether to enable internal tools
	 * @default true
	 */
	enabled?: boolean;

	/**
	 * Maximum execution timeout for internal tools in milliseconds
	 * @default 30000 (30 seconds)
	 */
	timeout?: number;

	/**
	 * Whether to cache tool lookups for performance
	 * @default true
	 */
	enableCache?: boolean;

	/**
	 * Cache timeout in milliseconds
	 * @default 300000 (5 minutes)
	 */
	cacheTimeout?: number;
}

/**
 * Tool registration result
 */
export interface ToolRegistrationResult {
	/**
	 * Total tools attempted to register
	 */
	total: number;

	/**
	 * Successfully registered tools
	 */
	registered: string[];

	/**
	 * Failed tool registrations
	 */
	failed: Array<{
		name: string;
		error: string;
	}>;
}

/**
 * Tool execution context provided to handlers
 */
export interface InternalToolContext {
	/**
	 * Tool name being executed
	 */
	toolName: string;

	/**
	 * Execution start time
	 */
	startTime: number;

	/**
	 * Optional session ID if available
	 */
	sessionId: string | undefined;

	/**
	 * Any additional metadata
	 */
	metadata: Record<string, any> | undefined;

	/**
	 * Optional agent services for advanced tool operations
	 */
	services?: {
		/**
		 * Embedding manager for text embeddings
		 */
		embeddingManager?: EmbeddingManager;

		/**
		 * Vector storage manager for similarity search
		 */
		vectorStoreManager?: VectorStoreManager;

		/**
		 * LLM service for intelligent reasoning (Phase 3)
		 */
		llmService?: ILLMService;

		/**
		 * Knowledge graph manager for graph operations
		 */
		knowledgeGraphManager?: KnowledgeGraphManager;
	};

	/**
	 * User ID for personalized behavior
	 */
	userId?: string;
}

/**
 * Statistics for internal tool usage
 */
export interface ToolExecutionStats {
	/**
	 * Tool name
	 */
	toolName: string;

	/**
	 * Total executions
	 */
	totalExecutions: number;

	/**
	 * Successful executions
	 */
	successfulExecutions: number;

	/**
	 * Failed executions
	 */
	failedExecutions: number;

	/**
	 * Average execution time in milliseconds
	 */
	averageExecutionTime: number;

	/**
	 * Last execution timestamp
	 */
	lastExecution?: string;

	/**
	 * Last error message
	 */
	lastError?: string;
}

/**
 * Interface for internal tool manager
 */
export interface IInternalToolManager {
	/**
	 * Initialize the internal tool manager
	 */
	initialize(): Promise<void>;

	/**
	 * Register a new internal tool
	 */
	registerTool(tool: InternalTool): { success: boolean; message: string; conflictedWith?: string };

	/**
	 * Unregister an internal tool
	 */
	unregisterTool(toolName: string): boolean;

	/**
	 * Get all registered internal tools
	 */
	getAllTools(): InternalToolSet;

	/**
	 * Get a specific internal tool by name
	 */
	getTool(toolName: string): InternalTool | undefined;

	/**
	 * Check if a tool name is an internal tool
	 */
	isInternalTool(toolName: string): boolean;

	/**
	 * Execute an internal tool
	 */
	executeTool(
		toolName: string,
		args: any,
		context?: Partial<InternalToolContext>
	): Promise<ToolExecutionResult>;

	/**
	 * Get tools by category
	 */
	getToolsByCategory(category: InternalToolCategory): InternalToolSet;

	/**
	 * Get execution statistics for a tool
	 */
	getToolStats(toolName: string): ToolExecutionStats | undefined;

	/**
	 * Get overall manager statistics
	 */
	getManagerStats(): {
		totalTools: number;
		toolsByCategory: Record<InternalToolCategory, number>;
		totalExecutions: number;
	};

	/**
	 * Clear all execution statistics
	 */
	clearStats(): void;

	/**
	 * Shutdown the internal tool manager
	 */
	shutdown(): Promise<void>;
}

/**
 * Prefix for all internal tool names to avoid conflicts
 */
export const INTERNAL_TOOL_PREFIX = 'cipher_';

/**
 * Helper function to create internal tool name
 */
export function createInternalToolName(baseName: string): string {
	return baseName.startsWith(INTERNAL_TOOL_PREFIX)
		? baseName
		: `${INTERNAL_TOOL_PREFIX}${baseName}`;
}

/**
 * Helper function to check if a tool name is internal
 */
export function isInternalToolName(toolName: string): boolean {
	return toolName.startsWith(INTERNAL_TOOL_PREFIX);
}

/**
 * Unified Tool Manager
 *
 * Combines MCP tools and internal tools into a single interface for LLM services.
 * Handles tool routing, execution, and conflict resolution between different tool sources.
 */

import { logger } from '../../logger/index.js';
import { MCPManager } from '../../mcp/manager.js';
import { InternalToolManager } from './manager.js';
import { ToolExecutionResult } from '../../mcp/types.js';
import { isInternalToolName } from './types.js';
import { EventManager } from '../../events/event-manager.js';
import { SessionEvents } from '../../events/event-types.js';
import { v4 as uuidv4 } from 'uuid';

/**
 * Configuration for the unified tool manager
 */
export interface UnifiedToolManagerConfig {
	/**
	 * Whether to enable internal tools
	 * @default true
	 */
	enableInternalTools?: boolean;

	/**
	 * Whether to enable MCP tools
	 * @default true
	 */
	enableMcpTools?: boolean;

	/**
	 * How to handle tool name conflicts
	 * @default 'prefix-internal'
	 */
	conflictResolution?: 'prefix-internal' | 'prefer-internal' | 'prefer-mcp' | 'error';

	/**
	 * Timeout for tool execution in milliseconds
	 * @default 30000
	 */
	executionTimeout?: number;

	/**
	 * Operating mode - affects which tools are exposed
	 * - 'cli': Only search tools exposed to Cipher's LLM (background tools still executable)
	 * - 'default': Only ask_cipher tool exposed to external MCP clients
	 * - 'aggregator': All tools exposed to external MCP clients
	 * - 'api': Similar to CLI mode
	 * @default 'default'
	 */
	mode?: 'cli' | 'default' | 'aggregator' | 'api';
}

/**
 * Combined tool information for LLM services
 */
export interface CombinedToolSet {
	[toolName: string]: {
		description: string;
		parameters: any;
		source: 'internal' | 'mcp';
	};
}

/**
 * Unified Tool Manager that combines MCP and internal tools
 */
export class UnifiedToolManager {
	private mcpManager: MCPManager;
	private internalToolManager: InternalToolManager;
	private config: Required<UnifiedToolManagerConfig>;
	private eventManager?: EventManager;
	private toolsAlreadyLogged = false;
	private embeddingManager?: any; // Reference to embedding manager for status checking

	constructor(
		mcpManager: MCPManager,
		internalToolManager: InternalToolManager,
		config: UnifiedToolManagerConfig = {}
	) {
		this.mcpManager = mcpManager;
		this.internalToolManager = internalToolManager;
		this.config = {
			enableInternalTools: true,
			enableMcpTools: true,
			conflictResolution: 'prefix-internal',
			executionTimeout: 30000,
			mode: 'default',
			...config,
		};
	}

	/**
	 * Set the event manager for emitting tool execution events
	 */
	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	/**
	 * Set the embedding manager for checking embedding status
	 */
	setEmbeddingManager(embeddingManager: any): void {
		this.embeddingManager = embeddingManager;
	}

	/**
	 * Check if embeddings are disabled globally
	 */
	private areEmbeddingsDisabled(): boolean {
		// Simple check: if embedding manager doesn't have available embeddings, disable tools
		if (this.embeddingManager) {
			return !this.embeddingManager.hasAvailableEmbeddings();
		}
		return true; // No embedding manager means embeddings disabled
	}

	/**
	 * Check if a tool is embedding-related and should be excluded when embeddings are disabled
	 */
	private isEmbeddingRelatedTool(toolName: string): boolean {
		const embeddingToolPatterns = [
			'extract_and_operate_memory',
			'search_memory',
			'search_reasoning',
			'store_reasoning_memory',
			'extract_reasoning_steps',
			'evaluate_reasoning',
			'memory_operation',
			'knowledge_search',
			'vector_search',
			'embedding',
			'similarity',
			'cipher_extract_and_operate_memory',
			'cipher_search_memory',
			'cipher_store_reasoning_memory',
			'cipher_extract_reasoning_steps',
			'cipher_evaluate_reasoning',
			'cipher_search_reasoning_patterns',
			// Workspace memory tools still need embeddings
			'cipher_workspace_search',
			'cipher_workspace_store',
			'workspace_search',
			'workspace_store',
		];

		return embeddingToolPatterns.some(pattern =>
			toolName.toLowerCase().includes(pattern.toLowerCase())
		);
	}

	/**
	 * Get all available tools from both sources
	 * Filters tools based on mode:
	 * - CLI mode: Only search tools + MCP tools (background tools excluded from agent access)
	 * - Default MCP mode: Only ask_cipher tool
	 * - Aggregator MCP mode: All tools
	 */
	async getAllTools(): Promise<CombinedToolSet> {
		if (!this.toolsAlreadyLogged && this.config.mode !== 'aggregator') {
			logger.debug('UnifiedToolManager: Getting all tools');
		}
		const combinedTools: CombinedToolSet = {};

		try {
			// MCP Default mode: Only expose ask_cipher tool
			if (this.config.mode === 'default') {
				// TODO: Add ask_cipher tool implementation
				combinedTools['ask_cipher'] = {
					description: 'Ask Cipher to perform tasks using its internal tools and capabilities',
					parameters: {
						type: 'object',
						properties: {
							query: {
								type: 'string',
								description: 'The task or question to ask Cipher',
							},
						},
						required: ['query'],
					},
					source: 'internal',
				};
				logger.debug('UnifiedToolManager: Default MCP mode - only ask_cipher tool exposed');
				return combinedTools;
			}

			// Get MCP tools if enabled (for CLI and aggregator modes)
			if (
				this.config.enableMcpTools &&
				(this.config.mode === 'cli' ||
					this.config.mode === 'aggregator' ||
					this.config.mode === 'api')
			) {
				if (!this.toolsAlreadyLogged && this.config.mode !== 'aggregator') {
					logger.debug('UnifiedToolManager: Loading MCP tools');
				}
				try {
					const mcpTools = await this.mcpManager.getAllTools();
					if (!this.toolsAlreadyLogged && this.config.mode !== 'aggregator') {
						logger.debug(`UnifiedToolManager: Retrieved ${Object.keys(mcpTools).length} MCP tools`);
					}
					for (const [toolName, tool] of Object.entries(mcpTools)) {
						combinedTools[toolName] = {
							description: tool.description,
							parameters: tool.parameters,
							source: 'mcp',
						};
					}
					if (!this.toolsAlreadyLogged && this.config.mode !== 'aggregator') {
						logger.debug(`UnifiedToolManager: Loaded ${Object.keys(mcpTools).length} MCP tools`);
					}
				} catch (error) {
					logger.warn('UnifiedToolManager: Failed to load MCP tools', { error });
				}
			}

			// Get internal tools if enabled
			if (this.config.enableInternalTools) {
				if (!this.toolsAlreadyLogged && this.config.mode !== 'aggregator') {
					logger.debug('UnifiedToolManager: Loading internal tools');
				}
				try {
					const internalTools = this.internalToolManager.getAllTools();
					if (!this.toolsAlreadyLogged && this.config.mode !== 'aggregator') {
						logger.debug(
							`UnifiedToolManager: Retrieved ${Object.keys(internalTools).length} internal tools`
						);
					}

					for (const [toolName, tool] of Object.entries(internalTools)) {
						// Check if embeddings are disabled and this is an embedding-related tool
						if (this.areEmbeddingsDisabled() && this.isEmbeddingRelatedTool(toolName)) {
							logger.debug(
								`UnifiedToolManager: Skipping embedding-related tool '${toolName}' - embeddings are disabled`
							);
							continue;
						}

						// Mode-specific tool filtering
						if (this.config.mode === 'cli') {
							// In CLI mode, only search-related tools are exposed to the agent.
							// Background tools are executed after the AI response and are not directly callable.
							const isAgentAccessible =
								(tool.agentAccessible ?? true) && // Default to true if not specified
								!toolName.includes('extract_and_operate_memory') &&
								!toolName.includes('store_reasoning');

							if (!isAgentAccessible) {
								continue;
							}
						} else if (this.config.mode === 'aggregator') {
							// Aggregator mode: Expose ALL tools (no filtering)
						} else {
							// Default/API modes: Skip background tools that are not agent-accessible
							if (tool.agentAccessible === false) {
								logger.debug(
									`UnifiedToolManager: Skipping internal-only tool '${toolName}' in ${
										this.config.mode
									} mode`
								);
								continue;
							}
						}

						const normalizedName = toolName.startsWith('cipher_') ? toolName : `cipher_${toolName}`;

						// Handle conflicts
						if (combinedTools[normalizedName]) {
							const conflictHandled = this.handleToolConflict(normalizedName, tool, combinedTools);
							if (!conflictHandled) continue;
						}

						combinedTools[normalizedName] = {
							description: tool.description,
							parameters: tool.parameters,
							source: 'internal',
						};
					}

					// Logging for different modes
					if (this.config.mode === 'cli') {
						const searchToolCount = Object.keys(combinedTools).filter(
							name =>
								combinedTools[name]?.source === 'internal' &&
								(name.includes('search') || name.includes('memory_') || name.includes('knowledge_'))
						).length;
						logger.debug(
							`UnifiedToolManager: CLI mode - ${searchToolCount} search tools accessible to LLM`
						);
					} else if (this.config.mode !== 'aggregator') {
						logger.debug(
							`UnifiedToolManager: Loaded ${Object.keys(internalTools).length} internal tools (${Object.keys(combinedTools).filter(name => combinedTools[name]?.source === 'internal').length} agent-accessible)`
						);
					}
				} catch (error) {
					logger.warn('UnifiedToolManager: Failed to load internal tools', { error });
				}
			}

			if (!this.toolsAlreadyLogged && this.config.mode !== 'aggregator') {
				logger.debug(
					`UnifiedToolManager: Combined tools loaded successfully (mode: ${this.config.mode})`
				);
				this.toolsAlreadyLogged = true;
			}
			return combinedTools;
		} catch (error) {
			logger.error('UnifiedToolManager: Failed to get all tools', { error });
			throw error;
		}
	}

	/**
	 * Execute a tool by routing to the appropriate manager
	 */
	async executeTool(toolName: string, args: any, sessionId?: string): Promise<ToolExecutionResult> {
		const executionId = uuidv4();
		const startTime = Date.now();
		const toolType =
			this.config.enableInternalTools && isInternalToolName(toolName) ? 'internal' : 'mcp';

		// Emit tool execution started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_STARTED, {
				toolName,
				toolType,
				sessionId,
				executionId,
				timestamp: startTime,
			});
		}

		try {
			logger.debug(`UnifiedToolManager: Executing tool '${toolName}'`, {
				toolName,
				hasArgs: !!args,
				sessionId,
				executionId,
			});

			let result: ToolExecutionResult;

			// Check if embeddings are disabled and this is an embedding-related tool
			if (this.areEmbeddingsDisabled() && this.isEmbeddingRelatedTool(toolName)) {
				logger.warn(
					`UnifiedToolManager: Blocking execution of embedding-related tool '${toolName}' - embeddings are disabled`
				);
				throw new Error(
					`Tool '${toolName}' is not available - embeddings are disabled for this session`
				);
			}

			// Determine which manager should handle this tool
			if (this.config.enableInternalTools && isInternalToolName(toolName)) {
				// Internal tool execution
				if (!this.internalToolManager.isInternalTool(toolName)) {
					throw new Error(`Internal tool '${toolName}' not found`);
				}

				logger.debug(`UnifiedToolManager: Routing '${toolName}' to internal tool manager`);
				result = await this.internalToolManager.executeTool(toolName, args);
			} else if (this.config.enableMcpTools) {
				// MCP tool execution
				logger.debug(`UnifiedToolManager: Routing '${toolName}' to MCP manager`);
				result = await this.mcpManager.executeTool(toolName, args);
			} else {
				throw new Error(`Tool '${toolName}' not available - no suitable manager enabled`);
			}

			// Emit tool execution completed event
			if (this.eventManager && sessionId) {
				this.eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_COMPLETED, {
					toolName,
					toolType,
					sessionId,
					executionId,
					duration: Date.now() - startTime,
					success: true,
					timestamp: Date.now(),
				});
			}

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			const duration = Date.now() - startTime;

			// Emit tool execution failed event
			if (this.eventManager && sessionId) {
				this.eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_FAILED, {
					toolName,
					toolType,
					sessionId,
					executionId,
					error: errorMessage,
					duration,
					timestamp: Date.now(),
				});
			}

			logger.error(`UnifiedToolManager: Tool execution failed for '${toolName}'`, {
				toolName,
				error: errorMessage,
				sessionId,
				executionId,
				duration,
			});
			throw error;
		}
	}

	/**
	 * Execute a tool without triggering redundant tool loading (for background operations)
	 * This method bypasses the normal tool loading process when tools are already loaded
	 */
	async executeToolWithoutLoading(
		toolName: string,
		args: any,
		sessionId?: string
	): Promise<ToolExecutionResult> {
		const executionId = uuidv4();
		const startTime = Date.now();
		const toolType =
			this.config.enableInternalTools && isInternalToolName(toolName) ? 'internal' : 'mcp';

		// Emit tool execution started event
		if (this.eventManager && sessionId) {
			this.eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_STARTED, {
				toolName,
				toolType,
				sessionId,
				executionId,
				timestamp: startTime,
			});
		}

		try {
			logger.debug(`UnifiedToolManager: Executing tool '${toolName}' (without loading)`, {
				toolName,
				hasArgs: !!args,
				sessionId,
				executionId,
			});

			let result: ToolExecutionResult;

			// Determine which manager should handle this tool
			if (this.config.enableInternalTools && isInternalToolName(toolName)) {
				// Internal tool execution
				if (!this.internalToolManager.isInternalTool(toolName)) {
					throw new Error(`Internal tool '${toolName}' not found`);
				}

				logger.debug(
					`UnifiedToolManager: Routing '${toolName}' to internal tool manager (without loading)`
				);
				result = await this.internalToolManager.executeTool(toolName, args);
			} else if (this.config.enableMcpTools) {
				// MCP tool execution
				logger.debug(`UnifiedToolManager: Routing '${toolName}' to MCP manager (without loading)`);
				result = await this.mcpManager.executeTool(toolName, args);
			} else {
				throw new Error(`Tool '${toolName}' not available - no suitable manager enabled`);
			}

			// Emit tool execution completed event
			if (this.eventManager && sessionId) {
				this.eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_COMPLETED, {
					toolName,
					toolType,
					sessionId,
					executionId,
					duration: Date.now() - startTime,
					success: true,
					result: result,
					timestamp: Date.now(),
				});
			}

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			const duration = Date.now() - startTime;

			// Emit tool execution failed event
			if (this.eventManager && sessionId) {
				this.eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_FAILED, {
					toolName,
					toolType,
					sessionId,
					executionId,
					error: errorMessage,
					duration,
					timestamp: Date.now(),
				});
			}

			logger.error(
				`UnifiedToolManager: Tool execution failed for '${toolName}' (without loading)`,
				{
					toolName,
					error: errorMessage,
					sessionId,
					executionId,
					duration,
				}
			);
			throw error;
		}
	}

	/**
	 * Check if a background tool exists (for internal execution, not agent access)
	 */
	isBackgroundToolAvailable(toolName: string): boolean {
		try {
			if (this.config.enableInternalTools && isInternalToolName(toolName)) {
				const tool = this.internalToolManager.getTool(toolName);
				return !!tool;
			}
			return false;
		} catch {
			return false;
		}
	}

	/**
	 * Check if a tool is available (to agents) based on current mode
	 */
	async isToolAvailable(toolName: string): Promise<boolean> {
		try {
			// Default MCP mode: Only ask_cipher tool available
			if (this.config.mode === 'default') {
				return toolName === 'ask_cipher';
			}

			if (this.config.enableInternalTools && isInternalToolName(toolName)) {
				// Check if tool exists
				const tool = this.internalToolManager.getTool(toolName);
				if (!tool) return false;

				// Mode-specific availability
				if (this.config.mode === 'cli') {
					// CLI mode: Only search tools accessible to LLM
					const isSearchTool =
						toolName.includes('search') ||
						toolName.includes('memory_') ||
						toolName.includes('knowledge_') ||
						toolName.includes('vector_') ||
						toolName === 'extract_and_operate_memory' ||
						toolName === 'cipher_extract_and_operate_memory';

					return isSearchTool && tool.agentAccessible !== false;
				} else if (this.config.mode === 'aggregator') {
					// Aggregator mode: All tools available
					return true;
				} else {
					// API mode: Only agent-accessible tools
					return tool.agentAccessible !== false;
				}
			} else if (
				this.config.enableMcpTools &&
				(this.config.mode === 'cli' ||
					this.config.mode === 'aggregator' ||
					this.config.mode === 'api')
			) {
				const mcpTools = await this.mcpManager.getAllTools();
				return toolName in mcpTools;
			}
			return false;
		} catch (error) {
			logger.error(`UnifiedToolManager: Error checking tool availability for '${toolName}'`, {
				error,
			});
			return false;
		}
	}

	/**
	 * Get tool source (internal or mcp) for agent-accessible tools
	 */
	async getToolSource(toolName: string): Promise<'internal' | 'mcp' | null> {
		try {
			// Default MCP mode: Only ask_cipher tool
			if (this.config.mode === 'default') {
				return toolName === 'ask_cipher' ? 'internal' : null;
			}

			if (this.config.enableInternalTools && isInternalToolName(toolName)) {
				// Check if tool exists
				const tool = this.internalToolManager.getTool(toolName);
				if (!tool) return null;

				// Mode-specific source determination
				if (this.config.mode === 'cli') {
					// CLI mode: Only search tools accessible
					const isSearchTool =
						toolName.includes('search') ||
						toolName.includes('memory_') ||
						toolName.includes('knowledge_') ||
						toolName.includes('vector_') ||
						toolName === 'extract_and_operate_memory' ||
						toolName === 'cipher_extract_and_operate_memory';

					return isSearchTool && tool.agentAccessible !== false ? 'internal' : null;
				} else if (this.config.mode === 'aggregator') {
					// Aggregator mode: All tools available
					return 'internal';
				} else {
					// API mode: Only agent-accessible tools
					return tool.agentAccessible !== false ? 'internal' : null;
				}
			} else if (
				this.config.enableMcpTools &&
				(this.config.mode === 'cli' ||
					this.config.mode === 'aggregator' ||
					this.config.mode === 'api')
			) {
				const mcpTools = await this.mcpManager.getAllTools();
				return toolName in mcpTools ? 'mcp' : null;
			}
			return null;
		} catch (error) {
			logger.error(`UnifiedToolManager: Error determining tool source for '${toolName}'`, {
				error,
			});
			return null;
		}
	}

	/**
	 * Get tools formatted for specific LLM providers
	 */

	async getToolsForProvider(
		provider: 'openai' | 'anthropic' | 'openrouter' | 'aws' | 'azure' | 'qwen' | 'gemini'
	): Promise<any[]> {
		logger.info(`UnifiedToolManager: Getting tools for provider: ${provider}`);
		const allTools = await this.getAllTools();
		logger.info(`UnifiedToolManager: Got ${Object.keys(allTools).length} total tools`);

		switch (provider) {
			case 'openai':
			case 'openrouter':
				logger.info('UnifiedToolManager: Formatting tools for OpenAI');
				return this.formatToolsForOpenAI(allTools);
			case 'qwen':
				return this.formatToolsForOpenAI(allTools);
			case 'gemini':
				logger.info('UnifiedToolManager: Formatting tools for Gemini');
				return this.formatToolsForGemini(allTools);
			case 'anthropic':
				logger.info('UnifiedToolManager: Formatting tools for Anthropic');
				return this.formatToolsForAnthropic(allTools);
			case 'aws':
				logger.info('UnifiedToolManager: Formatting tools for AWS (Anthropic-compatible)');
				return this.formatToolsForAnthropic(allTools); // AWS Bedrock uses Anthropic-compatible format
			case 'azure':
				logger.info('UnifiedToolManager: Formatting tools for Azure (OpenAI-compatible)');
				return this.formatToolsForOpenAI(allTools); // Azure OpenAI uses OpenAI-compatible format
			default:
				throw new Error(`Unsupported provider: ${provider}`);
		}
	}

	/**
	 * Get manager statistics
	 */
	getStats(): {
		internalTools: any;
		mcpTools: any;
		config: Required<UnifiedToolManagerConfig>;
	} {
		return {
			internalTools: this.config.enableInternalTools
				? this.internalToolManager.getManagerStats()
				: null,
			mcpTools: this.config.enableMcpTools
				? {
						clientCount: this.mcpManager.getClients().size,
						failedConnections: Object.keys(this.mcpManager.getFailedConnections()).length,
					}
				: null,
			config: this.config,
		};
	}

	/**
	 * Handle tool name conflicts
	 */
	private handleToolConflict(
		toolName: string,
		_internalTool: any,
		_existingTools: CombinedToolSet
	): boolean {
		switch (this.config.conflictResolution) {
			case 'prefix-internal':
				// Tool already has cipher_ prefix, so conflict shouldn't occur
				return true;

			case 'prefer-internal':
				logger.warn(
					`UnifiedToolManager: Tool conflict for '${toolName}', preferring internal tool`
				);
				return true;

			case 'prefer-mcp':
				logger.warn(`UnifiedToolManager: Tool conflict for '${toolName}', preferring MCP tool`);
				return false;

			case 'error':
				throw new Error(`Tool name conflict: '${toolName}' exists in both MCP and internal tools`);

			default:
				return true;
		}
	}

	/**
	 * Format tools for OpenAI/OpenRouter (function calling format)
	 */
	private formatToolsForOpenAI(tools: CombinedToolSet): any[] {
		return Object.entries(tools).map(([name, tool]) => ({
			type: 'function',
			function: {
				name,
				description: tool.description,
				parameters: tool.parameters,
			},
		}));
	}

	/**
	 * Format tools for Anthropic (tool use format)
	 */
	private formatToolsForAnthropic(tools: CombinedToolSet): any[] {
		return Object.entries(tools).map(([name, tool]) => ({
			name,
			description: tool.description,
			input_schema: tool.parameters,
		}));
	}

	/**
	 * Format tools for Gemini (function calling format - same as OpenAI)
	 */
	private formatToolsForGemini(tools: CombinedToolSet): any[] {
		return Object.entries(tools).map(([name, tool]) => ({
			type: 'function',
			function: {
				name,
				description: tool.description,
				parameters: tool.parameters,
			},
		}));
	}
}

/**
 * Memory Configuration Schema
 *
 * Comprehensive Zod schemas for validating YAML configuration files
 * that define custom memory types in the Cipher system.
 */

import { z } from 'zod';

/**
 * Base validation types
 */
export const FieldValidationType = z.enum([
	'non_empty',
	'url',
	'email',
	'range',
	'enum',
	'regex',
	'custom',
	'uuid',
	'json',
	'positive_number',
	'identifier',
	'path',
]);

export const FieldType = z.enum(['string', 'number', 'boolean', 'array', 'object']);

/**
 * Field configuration schema
 */
export const FieldConfigSchema = z
	.object({
		name: z.string().min(1, 'Field name is required'),
		type: FieldType,
		required: z.boolean().default(false),
		description: z.string().optional(),
		validation: FieldValidationType.optional(),
		default: z.any().optional(),

		// Type-specific validations
		min_value: z.number().optional(),
		max_value: z.number().optional(),
		allowed_values: z.array(z.string()).optional(),
		pattern: z.string().optional(),

		// Array-specific
		item_type: z.string().optional(),

		// Object-specific
		properties: z.record(z.string()).optional(),
	})
	.refine(
		data => {
			// Array fields must specify item_type
			if (data.type === 'array' && !data.item_type) {
				return false;
			}
			// Range validation requires min/max for numbers
			if (data.validation === 'range' && data.type === 'number') {
				return data.min_value !== undefined || data.max_value !== undefined;
			}
			// Enum validation requires allowed_values
			if (data.validation === 'enum' && !data.allowed_values) {
				return false;
			}
			// Regex validation requires pattern
			if (data.validation === 'regex' && !data.pattern) {
				return false;
			}
			return true;
		},
		{
			message: 'Field configuration validation failed',
		}
	);

/**
 * Schema configuration
 */
export const SchemaConfigSchema = z.object({
	version: z.string().default('1.0'),
	custom_fields: z.array(FieldConfigSchema).default([]),
	cross_validations: z
		.array(
			z.object({
				rule: z.string(),
				message: z.string(),
			})
		)
		.optional(),
	business_rules: z
		.array(
			z.object({
				rule: z.string(),
				message: z.string(),
			})
		)
		.optional(),
});

/**
 * Embedding configuration schema
 */
export const EmbeddingConfigSchema = z.object({
	model: z
		.enum(['text-embedding-3-small', 'text-embedding-3-large', 'text-embedding-ada-002'])
		.default('text-embedding-3-small'),
	dimension: z.number().positive().default(1536),
	batch_size: z.number().positive().default(100),
	timeout_ms: z.number().positive().default(30000),

	// Optional preprocessing
	preprocessing: z
		.object({
			normalize_whitespace: z.boolean().default(false),
			preserve_structure: z.boolean().default(false),
			include_comments: z.boolean().default(true),
		})
		.optional(),
});

/**
 * Vector store configuration schema
 */
export const VectorStoreConfigSchema = z.object({
	similarity_threshold: z.number().min(0).max(1).default(0.7),
	max_results: z.number().positive().default(10),
	rerank: z.boolean().default(false),
	time_decay_factor: z.number().min(0).max(1).optional(),

	// Search options
	search_options: z
		.object({
			include_metadata: z.boolean().default(true),
			include_values: z.boolean().default(false),
		})
		.optional(),
});

/**
 * Behavior trigger configuration
 */
export const BehaviorTriggerSchema = z.object({
	keyword_triggers: z.array(z.string()).optional(),
	pattern_triggers: z.array(z.string()).optional(),
	semantic_triggers: z.array(z.string()).optional(),
	conditions: z.string().optional(),
	exclusions: z.array(z.string()).optional(),

	// Store-specific field extraction rules
	field_extraction: z.record(z.string()).optional(),
});

/**
 * Behavior configuration schema
 */
export const BehaviorConfigSchema = z
	.object({
		search: BehaviorTriggerSchema.optional(),
		store: BehaviorTriggerSchema.optional(),
	})
	.refine(
		data => {
			return data.search || data.store;
		},
		{
			message: 'At least one of search or store behavior must be defined',
		}
	);

/**
 * Memory type configuration schema
 */
export const MemoryTypeConfigSchema = z.object({
	name: z
		.string()
		.min(1, 'Memory type name is required')
		.regex(/^[a-zA-Z][a-zA-Z0-9_]*$/, 'Name must be a valid identifier'),
	collection_name: z
		.string()
		.min(1, 'Collection name is required')
		.regex(/^[a-zA-Z][a-zA-Z0-9_]*$/, 'Collection name must be a valid identifier'),
	description: z.string().default(''),
	priority: z.number().int().min(0).default(0),

	embedding: EmbeddingConfigSchema,
	vector_store: VectorStoreConfigSchema,
	schema: SchemaConfigSchema,
	behavior: BehaviorConfigSchema,
});

/**
 * Global configuration schema
 */
export const GlobalConfigSchema = z.object({
	enabled: z.boolean().default(true),
	fallback_to_default: z.boolean().default(true),
	max_memory_types: z.number().positive().optional(),
	id_range_size: z.number().positive().default(100000),
});

/**
 * Advanced configuration schema
 */
export const AdvancedConfigSchema = z.object({
	orchestrator: z
		.object({
			decision_algorithm: z
				.enum(['priority_weighted', 'round_robin', 'semantic_routing'])
				.default('priority_weighted'),
			parallel_search: z.boolean().default(true),
			max_concurrent_searches: z.number().positive().default(3),
			search_timeout_ms: z.number().positive().default(5000),
		})
		.optional(),

	performance: z
		.object({
			cache_enabled: z.boolean().default(true),
			cache_ttl_seconds: z.number().positive().default(300),
			batch_operations: z.boolean().default(true),
			async_storage: z.boolean().default(true),
		})
		.optional(),

	monitoring: z
		.object({
			enable_metrics: z.boolean().default(true),
			log_decisions: z.boolean().default(true),
			performance_tracking: z.boolean().default(true),
			usage_analytics: z.boolean().default(true),
		})
		.optional(),

	error_handling: z
		.object({
			retry_attempts: z.number().int().min(0).default(3),
			retry_delay_ms: z.number().positive().default(1000),
			fallback_on_error: z.boolean().default(true),
			strict_validation: z.boolean().default(false),
		})
		.optional(),
});

/**
 * Main custom memory configuration schema
 */
export const CustomMemoryConfigSchema = z
	.object({
		global: GlobalConfigSchema,
		custom_memory_types: z
			.array(MemoryTypeConfigSchema)
			.min(1, 'At least one memory type must be defined'),
		advanced: AdvancedConfigSchema.optional(),
	})
	.refine(
		data => {
			// Validate unique memory type names
			const names = data.custom_memory_types.map(t => t.name);
			const uniqueNames = new Set(names);
			if (names.length !== uniqueNames.size) {
				return false;
			}

			// Validate unique collection names
			const collections = data.custom_memory_types.map(t => t.collection_name);
			const uniqueCollections = new Set(collections);
			if (collections.length !== uniqueCollections.size) {
				return false;
			}

			// Validate max memory types limit
			if (
				data.global.max_memory_types &&
				data.custom_memory_types.length > data.global.max_memory_types
			) {
				return false;
			}

			return true;
		},
		{
			message:
				'Memory type names and collection names must be unique, and count must not exceed max_memory_types',
		}
	);

/**
 * Type inference for configuration objects
 */
export type FieldConfig = z.infer<typeof FieldConfigSchema>;
export type SchemaConfig = z.infer<typeof SchemaConfigSchema>;
export type EmbeddingConfig = z.infer<typeof EmbeddingConfigSchema>;
export type VectorStoreConfig = z.infer<typeof VectorStoreConfigSchema>;
export type BehaviorTrigger = z.infer<typeof BehaviorTriggerSchema>;
export type BehaviorConfig = z.infer<typeof BehaviorConfigSchema>;
export type MemoryTypeConfig = z.infer<typeof MemoryTypeConfigSchema>;
export type GlobalConfig = z.infer<typeof GlobalConfigSchema>;
export type AdvancedConfig = z.infer<typeof AdvancedConfigSchema>;
export type CustomMemoryConfig = z.infer<typeof CustomMemoryConfigSchema>;

/**
 * Validation errors
 */
export class ConfigValidationError extends Error {
	constructor(
		message: string,
		public readonly issues?: z.ZodIssue[]
	) {
		super(message);
		this.name = 'ConfigValidationError';
	}
}

/**
 * Validate custom memory configuration
 */
export function validateCustomMemoryConfig(config: unknown): CustomMemoryConfig {
	const result = CustomMemoryConfigSchema.safeParse(config);

	if (!result.success) {
		throw new ConfigValidationError('Configuration validation failed', result.error.issues);
	}

	return result.data;
}

/**
 * Validate a single memory type configuration
 */
export function validateMemoryTypeConfig(config: unknown): MemoryTypeConfig {
	const result = MemoryTypeConfigSchema.safeParse(config);

	if (!result.success) {
		throw new ConfigValidationError(
			'Memory type configuration validation failed',
			result.error.issues
		);
	}

	return result.data;
}

