			.array(z.string())
			.default([
				'who.*working.*on',
				'what.*status.*of',
				'progress.*on.*feature',
				'bugs.*in.*project',
				'team.*member.*assigned',
				'repository.*branch',
				'current.*milestone',
			]),
		semantic_triggers: z
			.array(z.string())
			.default([
				'asking about team member activities',
				'inquiring about project status',
				'requesting progress updates',
				'looking for bug reports',
				'checking collaboration history',
			]),
	}),

	// Store behavior triggers
	store_triggers: z.object({
		keywords: z
			.array(z.string())
			.default([
				'completed',
				'working on',
				'implemented',
				'fixed',
				'bug',
				'issue',
				'feature',
				'milestone',
				'deployed',
				'released',
				'blocked',
				'reviewing',
				'testing',
				'merged',
				'committed',
			]),
		patterns: z
			.array(z.string())
			.default([
				'.*completed.*feature',
				'.*working.*on.*task',
				'.*fixed.*bug',
				'.*implemented.*component',
				'.*deployed.*to.*environment',
				'.*merged.*pull.*request',
				'.*created.*branch',
				'.*assigned.*to.*team',
