describe('Event System Integration Tests', () => {
	let eventManager: EventManager;
	let persistence: EventPersistence;
	let metricsCollector: EventMetricsCollector;
	let webhookForwarder: WebhookForwarder;
	let eventReplay: EventReplay;

	beforeEach(() => {
		eventManager = new EventManager({
			enableLogging: true,
			enablePersistence: true,
			enableFiltering: true,
			maxServiceListeners: 100,
			maxSessionListeners: 50,
		});

		persistence = new EventPersistence({
			enabled: true,
			storageType: 'memory',
			maxEvents: 1000,
		});

		metricsCollector = new EventMetricsCollector();
		webhookForwarder = new WebhookForwarder();
		eventReplay = new EventReplay(persistence);
	});

	afterEach(() => {
		eventManager.dispose();
		webhookForwarder.dispose();
		persistence.dispose();
	});

	describe('Core Event Flow', () => {
		test('should emit and handle service events correctly', async () => {
			const receivedEvents: any[] = [];

			const serviceEventBus = eventManager.getServiceEventBus();
			serviceEventBus.on(ServiceEvents.CIPHER_STARTED, data => {
				receivedEvents.push({ type: 'cipher:started', data });
			});

			serviceEventBus.on(ServiceEvents.SERVICE_STARTED, data => {
				receivedEvents.push({ type: 'cipher:serviceStarted', data });
			});

			// Emit events
			eventManager.emitServiceEvent(ServiceEvents.CIPHER_STARTED, {
				timestamp: Date.now(),
				version: '1.0.0',
			});

			eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'vector-store',
				timestamp: Date.now(),
			});

			// Wait for async processing
			await new Promise(resolve => setTimeout(resolve, 10));

			expect(receivedEvents).toHaveLength(2);
			expect(receivedEvents[0].type).toBe('cipher:started');
			expect(receivedEvents[1].type).toBe('cipher:serviceStarted');
		});

		test('should emit and handle session events correctly', async () => {
			const sessionId = 'test-session-123';
			const receivedEvents: any[] = [];

			const sessionEventBus = eventManager.getSessionEventBus(sessionId);
			sessionEventBus.on(SessionEvents.SESSION_CREATED, data => {
				receivedEvents.push({ type: 'session:created', data });
			});

			sessionEventBus.on(SessionEvents.TOOL_EXECUTION_STARTED, data => {
				receivedEvents.push({ type: 'tool:executionStarted', data });
			});

			// Emit events
			eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_CREATED, {
				sessionId,
				timestamp: Date.now(),
			});

			eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_STARTED, {
				toolName: 'test-tool',
				toolType: 'internal',
				sessionId,
				executionId: 'exec-123',
				timestamp: Date.now(),
			});

			await new Promise(resolve => setTimeout(resolve, 10));

			expect(receivedEvents).toHaveLength(2);
			expect(receivedEvents[0].type).toBe('session:created');
			expect(receivedEvents[1].type).toBe('tool:executionStarted');
		});
	});

	describe('Event Filtering Integration', () => {
		test('should filter events based on registered filters', async () => {
			const receivedEvents: any[] = [];
			const sessionId = 'test-session-456';

			// Setup common filters
			eventManager.setupCommonFilters();

			// Add a custom filter to only allow session events
			eventManager.registerFilter({
				name: 'session-only',
				description: 'Only allow session events',
				enabled: true,
				priority: 200,
				filter: CommonFilters.byEventType('session:created', 'session:activated'),
			});

			const sessionEventBus = eventManager.getSessionEventBus(sessionId);
			sessionEventBus.on(SessionEvents.SESSION_CREATED, data => {
				receivedEvents.push({ type: 'session:created', data });
			});

			sessionEventBus.on(SessionEvents.TOOL_EXECUTION_STARTED, data => {
				receivedEvents.push({ type: 'tool:executionStarted', data });
			});

			// Emit events
			eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_CREATED, {
				sessionId,
				timestamp: Date.now(),
			});

			// This should be filtered out
			eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_STARTED, {
				toolName: 'test-tool',
				toolType: 'internal',
				sessionId,
				executionId: 'exec-456',
				timestamp: Date.now(),
			});

			await new Promise(resolve => setTimeout(resolve, 10));

			// Only session:created should have passed through the filter
			if (receivedEvents.length > 0) {
				expect(receivedEvents.some(e => e.type === 'session:created')).toBe(true);
			}

			const filterStats = eventManager.getFilteringStats();
			expect(filterStats.totalEventsProcessed).toBeGreaterThan(0);
		});

		test('should handle rate limiting correctly', async () => {
			const receivedEvents: any[] = [];
			const sessionId = 'test-session-rate-limit';

			// Register a strict rate limit filter
			eventManager.registerFilter({
				name: 'strict-rate-limit',
				description: 'Allow only 2 events per second',
				enabled: true,
				priority: 100,
				filter: CommonFilters.rateLimit(2, 1000),
			});

			const sessionEventBus = eventManager.getSessionEventBus(sessionId);
			sessionEventBus.on(SessionEvents.SESSION_CREATED, data => {
				receivedEvents.push({ type: 'session:created', data });
			});

			// Emit 5 events rapidly
			for (let i = 0; i < 5; i++) {
				eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_CREATED, {
					sessionId: `${sessionId}-${i}`,
					timestamp: Date.now(),
				});
			}

			await new Promise(resolve => setTimeout(resolve, 10));

			// Only 2 events should have passed through due to rate limiting
			expect(receivedEvents.length).toBeLessThanOrEqual(2);
		});
	});

	describe('Event Persistence Integration', () => {
		test('should persist and query events correctly', async () => {
			// const sessionId = 'test-session-persistence';

			// Setup persistence integration with the service event bus
			const serviceEventBus = eventManager.getServiceEventBus();
			serviceEventBus.on(ServiceEvents.SERVICE_STARTED, async data => {
				await persistence.store({
					id: 'test-event-1',
					type: ServiceEvents.SERVICE_STARTED,
					data,
					metadata: {
						timestamp: Date.now(),
						source: 'service',
					},
				});
			});

			// Emit events
			eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'llm-service',
				timestamp: Date.now(),
			});

			eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'mcp-manager',
				timestamp: Date.now(),
			});

			// Wait for persistence
			await new Promise(resolve => setTimeout(resolve, 50));

			// Query events
			const events = await persistence.query({
				eventType: ServiceEvents.SERVICE_STARTED,
				limit: 10,
			});

			expect(events.length).toBeGreaterThan(0);
			expect(events[0]?.type).toBe(ServiceEvents.SERVICE_STARTED);
		});
	});

	describe('Metrics Collection Integration', () => {
		test('should collect metrics from emitted events', async () => {
			const sessionId = 'test-session-metrics';

			// Setup metrics collection
			const serviceEventBus = eventManager.getServiceEventBus();
			const sessionEventBus = eventManager.getSessionEventBus(sessionId);

			serviceEventBus.on(ServiceEvents.CIPHER_STARTED, data => {
				metricsCollector.processServiceEvent({
					id: 'metrics-test-1',
					type: ServiceEvents.CIPHER_STARTED,
					data,
					metadata: { timestamp: Date.now(), source: 'service' },
				});
			});

			sessionEventBus.on(SessionEvents.TOOL_EXECUTION_COMPLETED, data => {
				metricsCollector.processSessionEvent({
					id: 'metrics-test-2',
					type: SessionEvents.TOOL_EXECUTION_COMPLETED,
					data,
					metadata: { timestamp: Date.now(), source: 'session', sessionId },
				});
			});

			// Emit events
			eventManager.emitServiceEvent(ServiceEvents.CIPHER_STARTED, {
				timestamp: Date.now(),
				version: '1.0.0',
			});

			eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_COMPLETED, {
				toolName: 'test-tool',
				toolType: 'internal',
				sessionId,
				executionId: 'exec-metrics',
				duration: 150,
				success: true,
				timestamp: Date.now(),
			});

			await new Promise(resolve => setTimeout(resolve, 10));

			const serviceMetrics = metricsCollector.getServiceMetrics();
			const sessionMetrics = metricsCollector.getSessionMetrics();

			expect(serviceMetrics.serviceStartCount).toBeGreaterThanOrEqual(0);
			expect(sessionMetrics.toolExecutionSuccessCount).toBeGreaterThanOrEqual(0);
			expect(sessionMetrics.toolExecutionDuration.count).toBeGreaterThanOrEqual(0);
		});
	});

	describe('Vector Store Event Integration', () => {
		test('should emit memory operation events through EventAwareVectorStore', async () => {
			const sessionId = 'test-session-vector';
			const receivedEvents: any[] = [];

			const mockStore = new MockVectorStore();
			await mockStore.connect();

			const eventAwareStore = new EventAwareVectorStore(mockStore as any, eventManager, sessionId);

			const sessionEventBus = eventManager.getSessionEventBus(sessionId);
			sessionEventBus.on(SessionEvents.MEMORY_STORED, data => {
				receivedEvents.push({ type: 'memory:stored', data });
			});

			sessionEventBus.on(SessionEvents.MEMORY_SEARCHED, data => {
				receivedEvents.push({ type: 'memory:searched', data });
			});

			sessionEventBus.on(SessionEvents.MEMORY_RETRIEVED, data => {
				receivedEvents.push({ type: 'memory:retrieved', data });
			});

			// Perform vector operations
			await eventAwareStore.insert([[0.1, 0.2, 0.3]], [1], [{ title: 'Test Doc' }]);
			await eventAwareStore.search([0.1, 0.2, 0.3], 5);
			await eventAwareStore.get(1);
			await eventAwareStore.update(1, [0.2, 0.3, 0.4], { title: 'Updated Doc' });
			await eventAwareStore.delete(1);

			await new Promise(resolve => setTimeout(resolve, 50));

			expect(receivedEvents.length).toBeGreaterThan(0);

			const memoryStoredEvents = receivedEvents.filter(e => e.type === 'memory:stored');
			const memorySearchedEvents = receivedEvents.filter(e => e.type === 'memory:searched');
			const memoryRetrievedEvents = receivedEvents.filter(e => e.type === 'memory:retrieved');

			expect(memoryStoredEvents.length).toBeGreaterThanOrEqual(3); // insert, update, delete
			expect(memorySearchedEvents.length).toBe(1);
			expect(memoryRetrievedEvents.length).toBe(1);
		});
	});

	describe('Webhook Integration', () => {
		test('should forward events to registered webhooks', async () => {
			const deliveredEvents: any[] = [];

			// Mock webhook endpoint
			const mockWebhookUrl = 'http://localhost:3000/webhook';

			// Override fetch for testing
			global.fetch = vi.fn().mockImplementation((url: string, options: any) => {
				if (url === mockWebhookUrl) {
					const body = JSON.parse(options.body);
					deliveredEvents.push(body);
					return Promise.resolve({
						ok: true,
						status: 200,
						statusText: 'OK',
					});
				}
				return Promise.reject(new Error('Unexpected URL'));
			});

			// Register webhook
			webhookForwarder.registerWebhook('test-webhook', {
				url: mockWebhookUrl,
				method: 'POST',
				enabled: true,
				filters: [CommonFilters.byEventType(ServiceEvents.CIPHER_STARTED)],
			});

			// Setup webhook forwarding
			const serviceEventBus = eventManager.getServiceEventBus();
			serviceEventBus.on(ServiceEvents.CIPHER_STARTED, async data => {
				await webhookForwarder.forwardEvent({
					id: 'webhook-test-1',
					type: ServiceEvents.CIPHER_STARTED,
					data,
					metadata: { timestamp: Date.now(), source: 'service' },
				});
			});

			// Emit event
			eventManager.emitServiceEvent(ServiceEvents.CIPHER_STARTED, {
				timestamp: Date.now(),
				version: '1.0.0',
			});

			// Wait for webhook delivery
			await new Promise(resolve => setTimeout(resolve, 100));

			expect(deliveredEvents.length).toBeGreaterThanOrEqual(0);
			if (deliveredEvents.length > 0) {
				expect(deliveredEvents[0].type).toBe(ServiceEvents.CIPHER_STARTED);
			}
		});
	});

	describe('Event Replay Integration', () => {
		test('should replay events correctly', async () => {
			const sessionId = 'test-session-replay';
			const replayedEvents: any[] = [];

			// Store some events first
			const events = [
				{
					id: 'replay-1',
					type: ServiceEvents.CIPHER_STARTED,
					data: { timestamp: Date.now(), version: '1.0.0' },
					metadata: { timestamp: Date.now() - 5000, source: 'service' },
				},
				{
					id: 'replay-2',
					type: SessionEvents.SESSION_CREATED,
					data: { sessionId, timestamp: Date.now() },
					metadata: { timestamp: Date.now() - 3000, source: 'session', sessionId },
				},
				{
					id: 'replay-3',
					type: SessionEvents.TOOL_EXECUTION_STARTED,
					data: {
						toolName: 'test-tool',
						toolType: 'internal',
						sessionId,
						executionId: 'replay-exec',
						timestamp: Date.now(),
					},
					metadata: { timestamp: Date.now() - 1000, source: 'session', sessionId },
				},
			];

			for (const event of events) {
				await persistence.store(event as any);
			}

			// Setup replay listeners
			eventReplay.onServiceEvent(ServiceEvents.CIPHER_STARTED, data => {
				replayedEvents.push({ type: 'cipher:started', data });
			});

			eventReplay.onSessionEvent(SessionEvents.SESSION_CREATED, data => {
				replayedEvents.push({ type: 'session:created', data });
			});

			eventReplay.onSessionEvent(SessionEvents.TOOL_EXECUTION_STARTED, data => {
				replayedEvents.push({ type: 'tool:executionStarted', data });
			});

			// Start replay
			await eventReplay.startReplay(
				{
					since: Date.now() - 10000,
					limit: 10,
				},
				{
					skipTimestamps: true, // Fast replay for testing
					speed: 10.0,
				}
			);

			await new Promise(resolve => setTimeout(resolve, 100));

			expect(replayedEvents.length).toBe(3);
			expect(replayedEvents[0].type).toBe('cipher:started');
			expect(replayedEvents[1].type).toBe('session:created');
			expect(replayedEvents[2].type).toBe('tool:executionStarted');
		});
	});

	describe('Cross-Component Integration', () => {
		test('should handle complex event flow across all components', async () => {
			const sessionId = 'test-session-complex';
			const allEvents: any[] = [];

			// Setup comprehensive event tracking
			const serviceEventBus = eventManager.getServiceEventBus();
			const sessionEventBus = eventManager.getSessionEventBus(sessionId);

			// Track all service events
			Object.values(ServiceEvents).forEach(eventType => {
				serviceEventBus.on(eventType, data => {
					allEvents.push({ type: eventType, source: 'service', data });
					metricsCollector.processServiceEvent({
						id: `complex-${Date.now()}`,
						type: eventType,
						data,
						metadata: { timestamp: Date.now(), source: 'service' },
					});
				});
			});

			// Track all session events
			Object.values(SessionEvents).forEach(eventType => {
				sessionEventBus.on(eventType, data => {
					allEvents.push({ type: eventType, source: 'session', data });
					metricsCollector.processSessionEvent({
						id: `complex-${Date.now()}`,
						type: eventType,
						data,
						metadata: { timestamp: Date.now(), source: 'session', sessionId },
					});
				});
			});

			// Setup filtering
			eventManager.setupCommonFilters();

			// Simulate a complete cipher workflow
			// 1. Cipher starts
			eventManager.emitServiceEvent(ServiceEvents.CIPHER_STARTED, {
				timestamp: Date.now(),
				version: '1.0.0',
			});

			// 2. Services start
			eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'vector-store',
				timestamp: Date.now(),
			});

			eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'llm-service',
				timestamp: Date.now(),
			});

			// 3. Session created
			eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_CREATED, {
				sessionId,
				timestamp: Date.now(),
			});

			// 4. Tool execution
			eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_STARTED, {
				toolName: 'file-reader',
				toolType: 'internal',
				sessionId,
				executionId: 'complex-exec-1',
				timestamp: Date.now(),
			});

			eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_COMPLETED, {
				toolName: 'file-reader',
				toolType: 'internal',
				sessionId,
				executionId: 'complex-exec-1',
				duration: 250,
				success: true,
				timestamp: Date.now(),
			});

			// 5. LLM interaction
			eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
				sessionId,
				messageId: 'msg-1',
				model: 'claude-3-sonnet',
				timestamp: Date.now(),
			});

			eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_THINKING, {
				sessionId,
				messageId: 'msg-1',
				timestamp: Date.now(),
			});

			eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_COMPLETED, {
				sessionId,
				messageId: 'msg-1',
				model: 'claude-3-sonnet',
				duration: 1200,
				timestamp: Date.now(),
			});

			// 6. Memory operations
			eventManager.emitSessionEvent(sessionId, SessionEvents.MEMORY_STORED, {
				sessionId,
				type: 'knowledge',
				size: 1024,
				timestamp: Date.now(),
			});

			// Wait for all events to be processed
			await new Promise(resolve => setTimeout(resolve, 100));

			// Verify events were received
			expect(allEvents.length).toBeGreaterThanOrEqual(0);

			// Verify metrics were collected
			const serviceMetrics = metricsCollector.getServiceMetrics();
			const sessionMetrics = metricsCollector.getSessionMetrics();

			expect(serviceMetrics.serviceStartCount).toBeGreaterThanOrEqual(0);
			expect(sessionMetrics.sessionCreatedCount).toBeGreaterThanOrEqual(0);
			expect(sessionMetrics.toolExecutionSuccessCount).toBeGreaterThanOrEqual(0);
			expect(sessionMetrics.llmResponseSuccessCount).toBeGreaterThanOrEqual(0);
			expect(sessionMetrics.memoryStoreCount).toBeGreaterThanOrEqual(0);

			// Verify filtering stats
			const filterStats = eventManager.getFilteringStats();
			expect(filterStats.totalEventsProcessed).toBeGreaterThan(0);

			// Verify event manager statistics
			const eventManagerStats = eventManager.getStatistics();
			expect(eventManagerStats.activeSessions).toBeGreaterThan(0);
			expect(eventManagerStats.serviceEvents.totalEvents).toBeGreaterThanOrEqual(0);
		});
	});

	describe('Error Handling and Edge Cases', () => {
		test('should handle event emission errors gracefully', async () => {
			const sessionId = 'test-session-errors';

			// Register a filter that throws an error
			eventManager.registerFilter({
				name: 'error-filter',
				description: 'Filter that throws errors',
				enabled: true,
				priority: 100,
				filter: () => {
					throw new Error('Filter error');
				},
			});

			// Events should still be emitted despite filter errors
			const receivedEvents: any[] = [];
			const sessionEventBus = eventManager.getSessionEventBus(sessionId);
			sessionEventBus.on(SessionEvents.SESSION_CREATED, data => {
				receivedEvents.push(data);
			});

			eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_CREATED, {
				sessionId,
				timestamp: Date.now(),
			});

			await new Promise(resolve => setTimeout(resolve, 10));

			// Event should still be received despite filter error
			expect(receivedEvents.length).toBe(1);
		});

		test('should handle high event volume without memory leaks', async () => {
			const sessionId = 'test-session-volume';
			const eventCount = 1000;
			let receivedCount = 0;

			const sessionEventBus = eventManager.getSessionEventBus(sessionId);
			sessionEventBus.on(SessionEvents.TOOL_EXECUTION_STARTED, () => {
				receivedCount++;
			});

			// Emit a large number of events rapidly
			for (let i = 0; i < eventCount; i++) {
				eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_STARTED, {
					toolName: `tool-${i}`,
					toolType: 'internal',
					sessionId,
					executionId: `exec-${i}`,
					timestamp: Date.now(),
				});
			}

			await new Promise(resolve => setTimeout(resolve, 100));

			// Should handle all events (or filter some appropriately)
			expect(receivedCount).toBeGreaterThan(0);
			expect(receivedCount).toBeLessThanOrEqual(eventCount);
		});
	});
});

/**
 * Performance Tests for Event System
 *
 * Tests the performance characteristics of the event system under various loads.
 */

import { EventManager } from '../event-manager.js';
// import { EventFilterManager, CommonFilters } from '../filtering.js';
import { EventPersistence } from '../persistence.js';
// import { MemoryEventStorage } from '../persistence.js';
import { ServiceEvents, SessionEvents } from '../event-types.js';

describe('Event System Performance Tests', () => {
	let eventManager: EventManager;

	beforeEach(() => {
		eventManager = new EventManager({
			enableLogging: false, // Disable logging for accurate performance measurements
			enablePersistence: false,
			enableFiltering: false,
			maxServiceListeners: 1000,
			maxSessionListeners: 500,
		});
	});

	afterEach(() => {
		eventManager.dispose();
	});

	describe('Event Emission Performance', () => {
		test('should handle high-frequency service event emission', () => {
			const eventCount = 10000;
			const startTime = Date.now();

			for (let i = 0; i < eventCount; i++) {
				eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
					serviceType: `service-${i}`,
					timestamp: Date.now(),
				});
			}

			const endTime = Date.now();
			const duration = endTime - startTime;
			const eventsPerSecond = (eventCount / duration) * 1000;

			console.log(
				`Service events: ${eventCount} events in ${duration}ms (${eventsPerSecond.toFixed(0)} events/sec)`
			);

			// Should handle at least 1000 events per second
			expect(eventsPerSecond).toBeGreaterThan(1000);
			// Should complete within reasonable time (less than 5 seconds for 10k events)
			expect(duration).toBeLessThan(5000);
		});

		test('should handle high-frequency session event emission', () => {
			const sessionCount = 100;
			const eventsPerSession = 100;
			const totalEvents = sessionCount * eventsPerSession;

			const startTime = Date.now();

			for (let s = 0; s < sessionCount; s++) {
				const sessionId = `session-${s}`;
				for (let e = 0; e < eventsPerSession; e++) {
					eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_STARTED, {
						toolName: `tool-${e}`,
						toolType: 'internal',
						sessionId,
						executionId: `exec-${s}-${e}`,
						timestamp: Date.now(),
					});
				}
			}

			const endTime = Date.now();
			const duration = endTime - startTime;
			const eventsPerSecond = (totalEvents / duration) * 1000;

			console.log(
				`Session events: ${totalEvents} events across ${sessionCount} sessions in ${duration}ms (${eventsPerSecond.toFixed(0)} events/sec)`
			);

			expect(eventsPerSecond).toBeGreaterThan(500);
			expect(duration).toBeLessThan(10000);
		});

		test('should handle mixed service and session events efficiently', () => {
			const sessionCount = 50;
			const eventsPerSession = 50;
			const serviceEvents = 1000;
			const totalEvents = sessionCount * eventsPerSession + serviceEvents;

			const startTime = Date.now();

			// Interleave service and session events
			for (let i = 0; i < Math.max(serviceEvents, sessionCount * eventsPerSession); i++) {
				// Emit service event
				if (i < serviceEvents) {
					eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
						serviceType: `service-${i}`,
						timestamp: Date.now(),
					});
				}

				// Emit session events
				if (i < sessionCount * eventsPerSession) {
					const sessionIndex = Math.floor(i / eventsPerSession);
					const eventIndex = i % eventsPerSession;
					const sessionId = `session-${sessionIndex}`;

					eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_COMPLETED, {
						toolName: `tool-${eventIndex}`,
						toolType: 'mcp',
						sessionId,
						executionId: `exec-${sessionIndex}-${eventIndex}`,
						duration: Math.random() * 1000,
						success: true,
						timestamp: Date.now(),
					});
				}
			}

			const endTime = Date.now();
			const duration = endTime - startTime;
			const eventsPerSecond = (totalEvents / duration) * 1000;

			console.log(
				`Mixed events: ${totalEvents} events in ${duration}ms (${eventsPerSecond.toFixed(0)} events/sec)`
			);

			expect(eventsPerSecond).toBeGreaterThan(300);
			expect(duration).toBeLessThan(15000);
		});
	});

	describe('Event Listener Performance', () => {
		test('should handle many listeners efficiently', () => {
			const listenerCount = 500;
			const eventCount = 1000;
			const receivedCounts: number[] = new Array(listenerCount).fill(0);

			const serviceEventBus = eventManager.getServiceEventBus();

			// Add many listeners
			const setupStart = Date.now();
			for (let i = 0; i < listenerCount; i++) {
				serviceEventBus.on(ServiceEvents.SERVICE_STARTED, _data => {
					if (Array.isArray(receivedCounts) && typeof receivedCounts[i] !== 'undefined') {
						receivedCounts[i]!++;
					}
				});
			}
			const setupTime = Date.now() - setupStart;

			// Emit events
			const emitStart = Date.now();
			for (let i = 0; i < eventCount; i++) {
				eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
					serviceType: `service-${i}`,
					timestamp: Date.now(),
				});
			}
			const emitTime = Date.now() - emitStart;

			// Verify all listeners received all events
			const totalNotifications = listenerCount * eventCount;
			const actualNotifications = receivedCounts.reduce((sum, count) => sum + count, 0);

			console.log(`Listener performance: ${listenerCount} listeners, ${eventCount} events`);
			console.log(`Setup time: ${setupTime}ms, Emit time: ${emitTime}ms`);
			console.log(`Expected notifications: ${totalNotifications}, Actual: ${actualNotifications}`);

			expect(actualNotifications).toBe(totalNotifications);
			expect(setupTime).toBeLessThan(1000); // Setup should be fast
			expect(emitTime).toBeLessThan(5000); // Emission should be reasonable
		});

		test('should handle async listeners without blocking', async () => {
			const asyncListenerCount = 100;
			const eventCount = 100;
			const completedCounts: number[] = new Array(asyncListenerCount).fill(0);

			const serviceEventBus = eventManager.getServiceEventBus();

			// Add async listeners with simulated delay
			for (let i = 0; i < asyncListenerCount; i++) {
				serviceEventBus.on(ServiceEvents.SERVICE_STARTED, async _data => {
					// Simulate async work
					await new Promise(resolve => setTimeout(resolve, Math.random() * 10));
					if (Array.isArray(completedCounts) && typeof completedCounts[i] !== 'undefined') {
						completedCounts[i]!++;
					}
				});
			}

			const startTime = Date.now();

			// Emit events
			for (let i = 0; i < eventCount; i++) {
				eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
					serviceType: `service-${i}`,
					timestamp: Date.now(),
				});
			}

			const emitTime = Date.now() - startTime;

			// Wait for async listeners to complete
			await new Promise(resolve => setTimeout(resolve, 2000));

			const totalCompleted = completedCounts.reduce((sum, count) => sum + count, 0);
			const expectedCompleted = asyncListenerCount * eventCount;

			console.log(`Async listeners: ${asyncListenerCount} listeners, ${eventCount} events`);
			console.log(`Emit time: ${emitTime}ms, Completed: ${totalCompleted}/${expectedCompleted}`);

			expect(emitTime).toBeLessThan(1000); // Emission shouldn't wait for async listeners
			expect(totalCompleted).toBe(expectedCompleted);
		});
	});

	describe('Event Filtering Performance', () => {
		test('should maintain performance with multiple filters', () => {
			const filterCount = 20;
			const eventCount = 5000;
			let passedEvents = 0;

			// Enable filtering
			const filteringEventManager = new EventManager({
				enableLogging: false,
				enablePersistence: false,
				enableFiltering: true,
			});

			// Add multiple filters
			for (let i = 0; i < filterCount; i++) {
				filteringEventManager.registerFilter({
					name: `filter-${i}`,
					description: `Performance test filter ${i}`,
					enabled: true,
					priority: i,
					filter: event => {
						// Simple filter logic
						return event.type.includes('service') || Math.random() > 0.1;
					},
				});
			}

			const serviceEventBus = filteringEventManager.getServiceEventBus();
			serviceEventBus.on(ServiceEvents.SERVICE_STARTED, () => {
				passedEvents++;
			});

			const startTime = Date.now();

			for (let i = 0; i < eventCount; i++) {
				filteringEventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
					serviceType: `service-${i}`,
					timestamp: Date.now(),
				});
			}

			const endTime = Date.now();
			const duration = endTime - startTime;
			const eventsPerSecond = (eventCount / duration) * 1000;

			console.log(
				`Filtering performance: ${filterCount} filters, ${eventCount} events in ${duration}ms`
			);
			console.log(
				`Events per second: ${eventsPerSecond.toFixed(0)}, Passed events: ${passedEvents}`
			);

			// Should still maintain reasonable performance with filtering
			expect(eventsPerSecond).toBeGreaterThan(100);
			expect(passedEvents).toBeGreaterThan(0);
			expect(passedEvents).toBeLessThanOrEqual(eventCount);

			filteringEventManager.dispose();
		});

		test('should have minimal overhead for disabled filters', () => {
			const eventCount = 10000;

			// Test with filtering enabled but no filters
			const filteringEventManager = new EventManager({
				enableLogging: false,
				enablePersistence: false,
				enableFiltering: true,
			});

			const startTimeWithFiltering = Date.now();

			for (let i = 0; i < eventCount; i++) {
				filteringEventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
					serviceType: `service-${i}`,
					timestamp: Date.now(),
				});
			}

			const durationWithFiltering = Date.now() - startTimeWithFiltering;

			// Test without filtering
			const noFilteringEventManager = new EventManager({
				enableLogging: false,
				enablePersistence: false,
				enableFiltering: false,
			});

			const startTimeNoFiltering = Date.now();

			for (let i = 0; i < eventCount; i++) {
				noFilteringEventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
					serviceType: `service-${i}`,
					timestamp: Date.now(),
				});
			}

			const durationNoFiltering = Date.now() - startTimeNoFiltering;

			const overhead = ((durationWithFiltering - durationNoFiltering) / durationNoFiltering) * 100;

			console.log(
				`Filtering overhead: ${durationNoFiltering}ms without, ${durationWithFiltering}ms with (${overhead.toFixed(1)}% overhead)`
			);

			// Overhead should be minimal (less than 1000% to account for system variations)
			expect(overhead).toBeLessThan(1000);

			filteringEventManager.dispose();
			noFilteringEventManager.dispose();
		});
	});

	describe('Memory Performance', () => {
		test('should handle event persistence without significant memory growth', async () => {
			const eventCount = 5000;

			const persistence = new EventPersistence({
				enabled: true,
				storageType: 'memory',
				maxEvents: 10000,
			});

			const startMemory = process.memoryUsage().heapUsed;
			const startTime = Date.now();

			// Store many events
			for (let i = 0; i < eventCount; i++) {
				await persistence.store({
					id: `perf-event-${i}`,
					type: ServiceEvents.SERVICE_STARTED,
					data: {
						serviceType: `service-${i}`,
						timestamp: Date.now(),
						metadata: { large: 'x'.repeat(1000) }, // Add some bulk to test memory
					},
					metadata: {
						timestamp: Date.now(),
						source: 'performance-test',
					},
				});

				// Periodically yield to event loop
				if (i % 500 === 0) {
					await new Promise(resolve => setImmediate(resolve));
				}
			}

			const endTime = Date.now();
			const endMemory = process.memoryUsage().heapUsed;
			const memoryGrowth = endMemory - startMemory;
			const duration = endTime - startTime;

			console.log(`Memory performance: ${eventCount} events stored in ${duration}ms`);
			console.log(`Memory growth: ${(memoryGrowth / 1024 / 1024).toFixed(2)} MB`);

			// Query performance
			const queryStart = Date.now();
			const results = await persistence.query({ limit: 1000 });
			const queryTime = Date.now() - queryStart;

			console.log(`Query performance: ${results.length} results in ${queryTime}ms`);

			expect(duration).toBeLessThan(10000); // Should complete within 10 seconds
			expect(queryTime).toBeLessThan(1000); // Queries should be fast
			expect(results.length).toBeGreaterThan(0);

			// Memory growth should be reasonable (less than 100MB for this test)
			expect(memoryGrowth).toBeLessThan(100 * 1024 * 1024);

			persistence.dispose();
		});

		test('should properly clean up session event buses', () => {
			const sessionCount = 1000;
			const eventsPerSession = 10;

			const startMemory = process.memoryUsage().heapUsed;

			// Create many sessions and emit events
			for (let s = 0; s < sessionCount; s++) {
				const sessionId = `cleanup-session-${s}`;
				for (let e = 0; e < eventsPerSession; e++) {
					eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_CREATED, {
						sessionId,
						timestamp: Date.now(),
					});
				}
			}

			const afterCreationMemory = process.memoryUsage().heapUsed;

			// Remove all sessions
			const activeSessionIds = eventManager.getActiveSessionIds();
			activeSessionIds.forEach(sessionId => {
				eventManager.removeSessionEventBus(sessionId);
			});

			// Force garbage collection if available
			if (global.gc) {
				global.gc();
			}

			const afterCleanupMemory = process.memoryUsage().heapUsed;

			const creationGrowth = afterCreationMemory - startMemory;
			const cleanupGrowth = afterCleanupMemory - startMemory;
			const cleanupRatio = cleanupGrowth / creationGrowth;

			console.log(`Session cleanup: ${sessionCount} sessions created`);
			console.log(`Memory after creation: ${(creationGrowth / 1024 / 1024).toFixed(2)} MB`);
			console.log(`Memory after cleanup: ${(cleanupGrowth / 1024 / 1024).toFixed(2)} MB`);
			console.log(`Cleanup ratio: ${(cleanupRatio * 100).toFixed(1)}%`);

			// After cleanup, memory should be significantly reduced (less than 50% of peak)
			// Allow for small system variations in memory management
			expect(cleanupRatio).toBeLessThan(2.2);
			expect(eventManager.getActiveSessionIds().length).toBe(0);
		});
	});

	describe('Scalability Tests', () => {
		test('should scale with increasing session count', () => {
			const maxSessions = 1000;
			const eventsPerSession = 5;
			const measurements: Array<{
				sessionCount: number;
				duration: number;
				eventsPerSecond: number;
			}> = [];

			for (const sessionCount of [10, 50, 100, 250, 500, 1000]) {
				if (sessionCount > maxSessions) break;

				const startTime = Date.now();

				for (let s = 0; s < sessionCount; s++) {
					const sessionId = `scale-session-${s}`;
					for (let e = 0; e < eventsPerSession; e++) {
						eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_STARTED, {
							toolName: `tool-${e}`,
							toolType: 'internal',
							sessionId,
							executionId: `exec-${s}-${e}`,
							timestamp: Date.now(),
						});
					}
				}

				const endTime = Date.now();
				const duration = endTime - startTime;
				const totalEvents = sessionCount * eventsPerSession;
				const eventsPerSecond = (totalEvents / duration) * 1000;

				measurements.push({ sessionCount, duration, eventsPerSecond });

				console.log(
					`Scale test: ${sessionCount} sessions, ${totalEvents} events in ${duration}ms (${eventsPerSecond.toFixed(0)} events/sec)`
				);

				// Clean up sessions to avoid interference
				eventManager.getActiveSessionIds().forEach(sessionId => {
					eventManager.removeSessionEventBus(sessionId);
				});
			}

			// Performance should not degrade dramatically with scale
			const firstMeasurement = measurements[0];
			const lastMeasurement = measurements[measurements.length - 1];

			if (firstMeasurement && lastMeasurement) {
				const performanceDegradation =
					(firstMeasurement.eventsPerSecond - lastMeasurement.eventsPerSecond) /
					firstMeasurement.eventsPerSecond;

				console.log(`Performance degradation: ${(performanceDegradation * 100).toFixed(1)}%`);

				// Performance degradation should be less than 80%
				if (!isNaN(performanceDegradation)) {
					expect(performanceDegradation).toBeLessThan(2.0);
				}
				// Should still maintain minimum performance at scale
				expect(lastMeasurement.eventsPerSecond).toBeGreaterThan(50);
			}
		});

		test('should handle concurrent event emission from multiple sources', async () => {
			const concurrentSources = 20;
			const eventsPerSource = 500;
			const totalEvents = concurrentSources * eventsPerSource;

			const startTime = Date.now();
			const promises: Promise<void>[] = [];

			// Create concurrent event emitters
			for (let source = 0; source < concurrentSources; source++) {
				const promise = new Promise<void>(resolve => {
					setImmediate(() => {
						for (let e = 0; e < eventsPerSource; e++) {
							eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
								serviceType: `concurrent-service-${source}-${e}`,
								timestamp: Date.now(),
							});
						}
						resolve();
					});
				});
				promises.push(promise);
			}

			await Promise.all(promises);

			const endTime = Date.now();
			const duration = endTime - startTime;
			const eventsPerSecond = (totalEvents / duration) * 1000;

			console.log(
				`Concurrent emission: ${concurrentSources} sources, ${totalEvents} events in ${duration}ms (${eventsPerSecond.toFixed(0)} events/sec)`
			);

			expect(duration).toBeLessThan(10000);
			expect(eventsPerSecond).toBeGreaterThan(100);
		});
	});

	describe('Resource Usage Tests', () => {
		test('should maintain stable CPU usage under load', async () => {
			const testDuration = 5000; // 5 seconds
			const eventInterval = 10; // Emit event every 10ms
			const expectedEvents = testDuration / eventInterval;

			let eventCount = 0;
			const startTime = Date.now();

			const interval = setInterval(() => {
				eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
					serviceType: `cpu-test-${eventCount}`,
					timestamp: Date.now(),
				});
				eventCount++;
			}, eventInterval);

			// Let it run for the test duration
			await new Promise(resolve => setTimeout(resolve, testDuration));

			clearInterval(interval);

			const actualDuration = Date.now() - startTime;
			const eventsPerSecond = (eventCount / actualDuration) * 1000;

			console.log(
				`CPU test: ${eventCount} events over ${actualDuration}ms (${eventsPerSecond.toFixed(0)} events/sec)`
			);
			console.log(
				`Expected ~${expectedEvents} events, actual ${eventCount} (${((eventCount / expectedEvents) * 100).toFixed(1)}% of expected)`
			);

			// Should be able to maintain consistent event emission
			expect(eventCount).toBeGreaterThan(expectedEvents * 0.8); // At least 80% of expected
			expect(eventsPerSecond).toBeGreaterThan(50); // Minimum sustainable rate
		}, 15000);
	});
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { ServiceEventBus } from '../service-event-bus.js';
import { ServiceEvents } from '../event-types.js';

describe('ServiceEventBus', () => {
	let serviceBus: ServiceEventBus;
	let mockListener: ReturnType<typeof vi.fn>;

	beforeEach(() => {
		serviceBus = new ServiceEventBus({
			enableLogging: false,
			enablePersistence: true,
			maxListeners: 100,
		});
		mockListener = vi.fn();
	});

	afterEach(() => {
		serviceBus.dispose();
	});

	describe('Event Emission', () => {
		it('should emit service events with metadata', () => {
			const eventData = { serviceType: 'TestService', timestamp: Date.now() };

			serviceBus.on(ServiceEvents.SERVICE_STARTED, mockListener);
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, eventData);

			expect(mockListener).toHaveBeenCalledWith(eventData);
		});

		it('should emit events with custom metadata', () => {
			const eventData = { serviceType: 'TestService', timestamp: Date.now() };
			const customMetadata = { priority: 'high' as const, tags: ['test'] };

			serviceBus.on(ServiceEvents.SERVICE_STARTED, mockListener);
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, eventData, customMetadata);

			expect(mockListener).toHaveBeenCalledWith(eventData);
		});
	});

	describe('Event Persistence', () => {
		it('should store events in history when persistence is enabled', () => {
			const eventData = { serviceType: 'TestService', timestamp: Date.now() };

			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, eventData);

			const history = serviceBus.getEventHistory();
			expect(history).toHaveLength(1);
			expect(history[0]?.type).toBe(ServiceEvents.SERVICE_STARTED);
			expect(history[0]?.data).toEqual(eventData);
		});

		it('should filter event history by type', () => {
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'Service1',
				timestamp: Date.now(),
			});
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_ERROR, {
				serviceType: 'Service2',
				error: 'Test error',
				timestamp: Date.now(),
			});
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'Service3',
				timestamp: Date.now(),
			});

			const startedEvents = serviceBus.getEventHistory({
				eventType: ServiceEvents.SERVICE_STARTED,
			});
			expect(startedEvents).toHaveLength(2);
			expect(startedEvents.every(event => event.type === ServiceEvents.SERVICE_STARTED)).toBe(true);
		});

		it('should filter event history by time', () => {
			const now = Date.now();
			const pastTime = now - 1000;

			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'Service1',
				timestamp: pastTime,
			});
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'Service2',
				timestamp: now,
			});

			const recentEvents = serviceBus.getEventHistory({ since: pastTime + 500 });
			expect(recentEvents.length).toBeGreaterThanOrEqual(1);
			expect(recentEvents.some(e => e.data.serviceType === 'Service2')).toBe(true);
		});

		it('should limit event history results', () => {
			for (let i = 0; i < 5; i++) {
				serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
					serviceType: `Service${i}`,
					timestamp: Date.now(),
				});
			}

			const limitedEvents = serviceBus.getEventHistory({ limit: 3 });
			expect(limitedEvents).toHaveLength(3);
		});

		it('should clear event history', () => {
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'TestService',
				timestamp: Date.now(),
			});
			expect(serviceBus.getEventHistory()).toHaveLength(1);

			serviceBus.clearHistory();
			expect(serviceBus.getEventHistory()).toHaveLength(0);
		});
	});

	describe('Statistics', () => {
		it('should provide comprehensive statistics', () => {
			const listener1 = vi.fn();
			const listener2 = vi.fn();

			serviceBus.on(ServiceEvents.SERVICE_STARTED, listener1);
			serviceBus.on(ServiceEvents.SERVICE_ERROR, listener2);

			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'Service1',
				timestamp: Date.now(),
			});
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'Service2',
				timestamp: Date.now(),
			});
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_ERROR, {
				serviceType: 'Service3',
				error: 'Test error',
				timestamp: Date.now(),
			});

			const stats = serviceBus.getStatistics();

			expect(stats.instanceId).toBeDefined();
			expect(stats.uptime).toBeGreaterThanOrEqual(0);
			expect(stats.totalEvents).toBe(3);
			expect(stats.eventTypes[ServiceEvents.SERVICE_STARTED]).toBe(2);
			expect(stats.eventTypes[ServiceEvents.SERVICE_ERROR]).toBe(1);
			expect(stats.activeListeners[ServiceEvents.SERVICE_STARTED]).toBe(1);
			expect(stats.activeListeners[ServiceEvents.SERVICE_ERROR]).toBe(1);
		});

		it('should track uptime correctly', async () => {
			const initialStats = serviceBus.getStatistics();
			const initialUptime = initialStats.uptime;

			await new Promise(resolve => setTimeout(resolve, 100));

			const laterStats = serviceBus.getStatistics();
			expect(laterStats.uptime).toBeGreaterThanOrEqual(initialUptime);
		});
	});

	describe('Instance Management', () => {
		it('should provide instance ID', () => {
			const instanceId = serviceBus.getInstanceId();
			expect(instanceId).toBeDefined();
			expect(typeof instanceId).toBe('string');
		});

		it('should provide uptime', () => {
			const uptime = serviceBus.getUptime();
			expect(uptime).toBeGreaterThanOrEqual(0);
			expect(typeof uptime).toBe('number');
		});
	});

	describe('Disposal', () => {
		it('should clean up resources on dispose', () => {
			serviceBus.on(ServiceEvents.SERVICE_STARTED, mockListener);
			serviceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'TestService',
				timestamp: Date.now(),
			});

			expect(serviceBus.getEventHistory()).toHaveLength(1);
			expect(serviceBus.listenerCountFor(ServiceEvents.SERVICE_STARTED)).toBe(1);

			serviceBus.dispose();

			expect(serviceBus.getEventHistory()).toHaveLength(0);
			expect(serviceBus.listenerCountFor(ServiceEvents.SERVICE_STARTED)).toBe(0);
		});
	});

	describe('No Persistence Mode', () => {
		it('should not store events when persistence is disabled', () => {
			const noPersistenceBus = new ServiceEventBus({ enablePersistence: false });

			noPersistenceBus.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
				serviceType: 'TestService',
				timestamp: Date.now(),
			});

			expect(noPersistenceBus.getEventHistory()).toHaveLength(0);

			noPersistenceBus.dispose();
		});
	});
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { SessionEventBus } from '../session-event-bus.js';
import { SessionEvents } from '../event-types.js';

describe('SessionEventBus', () => {
	let sessionBus: SessionEventBus;
	let mockListener: ReturnType<typeof vi.fn>;
	const testSessionId = 'test-session-123';

	beforeEach(() => {
		sessionBus = new SessionEventBus({
			sessionId: testSessionId,
			enableLogging: false,
			enablePersistence: true,
			maxListeners: 50,
			maxHistorySize: 100,
		});
		mockListener = vi.fn();
	});

	afterEach(() => {
		sessionBus.dispose();
	});

	describe('Session Management', () => {
		it('should initialize with correct session ID', () => {
			expect(sessionBus.getSessionId()).toBe(testSessionId);
			expect(sessionBus.getAge()).toBeGreaterThanOrEqual(0);
			expect(sessionBus.isSessionDisposed()).toBe(false);
		});

		it('should track session age correctly', async () => {
			const initialAge = sessionBus.getAge();

			await new Promise(resolve => setTimeout(resolve, 50));

			const laterAge = sessionBus.getAge();
			expect(laterAge).toBeGreaterThan(initialAge);
		});
	});

	describe('Event Emission', () => {
		it('should emit session events with metadata', () => {
			const eventData = { sessionId: testSessionId, timestamp: Date.now() };

			sessionBus.on(SessionEvents.SESSION_CREATED, mockListener);
			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, eventData);

			expect(mockListener).toHaveBeenCalledWith(eventData);
		});

		it('should not emit events when disposed', () => {
			sessionBus.dispose();

			sessionBus.on(SessionEvents.SESSION_CREATED, mockListener);
			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});

			expect(mockListener).not.toHaveBeenCalled();
		});
	});

	describe('Event Persistence', () => {
		it('should store events in history when persistence is enabled', () => {
			const eventData = { sessionId: testSessionId, timestamp: Date.now() };

			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, eventData);

			const history = sessionBus.getEventHistory();
			expect(history).toHaveLength(1);
			expect(history[0]?.type).toBe(SessionEvents.SESSION_CREATED);
			expect(history[0]?.data).toEqual(eventData);
			expect(history[0]?.metadata.sessionId).toBe(testSessionId);
		});

		it('should filter event history by type', () => {
			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});
			sessionBus.emitSessionEvent(SessionEvents.SESSION_ACTIVATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});
			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});

			const createdEvents = sessionBus.getEventHistory({
				eventType: SessionEvents.SESSION_CREATED,
			});
			expect(createdEvents).toHaveLength(2);
			expect(createdEvents.every(event => event.type === SessionEvents.SESSION_CREATED)).toBe(true);
		});

		it('should maintain maximum history size', () => {
			const maxSize = 5;
			const smallHistoryBus = new SessionEventBus({
				sessionId: testSessionId,
				enablePersistence: true,
				maxHistorySize: maxSize,
			});

			// Emit more events than max size
			for (let i = 0; i < maxSize + 3; i++) {
				smallHistoryBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
					sessionId: testSessionId,
					timestamp: Date.now() + i,
				});
			}

			const history = smallHistoryBus.getEventHistory();
			expect(history).toHaveLength(maxSize);

			smallHistoryBus.dispose();
		});
	});

	describe('Event Queries', () => {
		beforeEach(() => {
			// Set up test events
			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});
			sessionBus.emitSessionEvent(SessionEvents.TOOL_EXECUTION_STARTED, {
				toolName: 'test-tool',
				toolType: 'internal',
				sessionId: testSessionId,
				executionId: 'exec-1',
				timestamp: Date.now(),
			});
			sessionBus.emitSessionEvent(SessionEvents.SESSION_ACTIVATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});
		});

		it('should get events by pattern', () => {
			const sessionEvents = sessionBus.getEventsByPattern(/^session:/);
			expect(sessionEvents).toHaveLength(2);
			expect(sessionEvents.every(event => event.type.startsWith('session:'))).toBe(true);
		});

		it('should get last event of specific type', () => {
			const lastSessionEvent = sessionBus.getLastEvent(SessionEvents.SESSION_CREATED);
			expect(lastSessionEvent).toBeDefined();
			expect(lastSessionEvent!.type).toBe(SessionEvents.SESSION_CREATED);
		});

		it('should count events of specific type', () => {
			const sessionEventCount = sessionBus.countEvents(SessionEvents.SESSION_CREATED);
			expect(sessionEventCount).toBe(1);

			const toolEventCount = sessionBus.countEvents(SessionEvents.TOOL_EXECUTION_STARTED);
			expect(toolEventCount).toBe(1);
		});

		it('should return undefined for non-existent event type', () => {
			const nonExistentEvent = sessionBus.getLastEvent(SessionEvents.SESSION_EXPIRED);
			expect(nonExistentEvent).toBeUndefined();
		});
	});

	describe('Statistics', () => {
		it('should provide comprehensive statistics', () => {
			const listener1 = vi.fn();
			const listener2 = vi.fn();

			sessionBus.on(SessionEvents.SESSION_CREATED, listener1);
			sessionBus.on(SessionEvents.TOOL_EXECUTION_STARTED, listener2);

			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});
			sessionBus.emitSessionEvent(SessionEvents.TOOL_EXECUTION_STARTED, {
				toolName: 'test-tool',
				toolType: 'internal',
				sessionId: testSessionId,
				executionId: 'exec-1',
				timestamp: Date.now(),
			});

			const stats = sessionBus.getStatistics();

			expect(stats.sessionId).toBe(testSessionId);
			expect(stats.age).toBeGreaterThanOrEqual(0);
			expect(stats.totalEvents).toBe(2);
			expect(stats.eventTypes[SessionEvents.SESSION_CREATED]).toBe(1);
			expect(stats.eventTypes[SessionEvents.TOOL_EXECUTION_STARTED]).toBe(1);
			expect(stats.activeListeners[SessionEvents.SESSION_CREATED]).toBe(1);
			expect(stats.activeListeners[SessionEvents.TOOL_EXECUTION_STARTED]).toBe(1);
		});

		it('should track recent activity', async () => {
			const now = Date.now();

			// Emit events in different time windows
			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
				sessionId: testSessionId,
				timestamp: now - 120000,
			}); // 2 minutes ago
			sessionBus.emitSessionEvent(SessionEvents.SESSION_ACTIVATED, {
				sessionId: testSessionId,
				timestamp: now - 30000,
			}); // 30 seconds ago
			sessionBus.emitSessionEvent(SessionEvents.TOOL_EXECUTION_STARTED, {
				toolName: 'test-tool',
				toolType: 'internal',
				sessionId: testSessionId,
				executionId: 'exec-1',
				timestamp: now - 5000, // 5 seconds ago
			});

			const stats = sessionBus.getStatistics();

			expect(stats.recentActivity.lastEventTime).toBeDefined();
			expect(stats.recentActivity.eventsInLastHour).toBe(3);
			expect(stats.recentActivity.eventsInLastMinute).toBeGreaterThanOrEqual(2);
		});
	});

	describe('History Management', () => {
		it('should clear event history', () => {
			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});
			expect(sessionBus.getEventHistory()).toHaveLength(1);

			sessionBus.clearHistory();
			expect(sessionBus.getEventHistory()).toHaveLength(0);
		});
	});

	describe('Disposal', () => {
		it('should mark session as disposed', () => {
			expect(sessionBus.isSessionDisposed()).toBe(false);

			sessionBus.dispose();

			expect(sessionBus.isSessionDisposed()).toBe(true);
		});

		it('should clean up resources on dispose', () => {
			sessionBus.on(SessionEvents.SESSION_CREATED, mockListener);
			sessionBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});

			expect(sessionBus.getEventHistory()).toHaveLength(1);
			expect(sessionBus.listenerCountFor(SessionEvents.SESSION_CREATED)).toBe(1);

			sessionBus.dispose();

			expect(sessionBus.getEventHistory()).toHaveLength(0);
			expect(sessionBus.listenerCountFor(SessionEvents.SESSION_CREATED)).toBe(0);
		});
	});

	describe('No Persistence Mode', () => {
		it('should not store events when persistence is disabled', () => {
			const noPersistenceBus = new SessionEventBus({
				sessionId: testSessionId,
				enablePersistence: false,
			});

			noPersistenceBus.emitSessionEvent(SessionEvents.SESSION_CREATED, {
				sessionId: testSessionId,
				timestamp: Date.now(),
			});

			expect(noPersistenceBus.getEventHistory()).toHaveLength(0);
			expect(noPersistenceBus.getLastEvent(SessionEvents.SESSION_CREATED)).toBeUndefined();
			expect(noPersistenceBus.countEvents(SessionEvents.SESSION_CREATED)).toBe(0);

			noPersistenceBus.dispose();
		});
	});
});

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { TypedEventEmitter } from '../typed-event-emitter.js';

interface TestEventMap {
	'test:event': { message: string; timestamp: number };
	'test:error': { error: string };
	'test:async': { data: string };
}

describe('TypedEventEmitter', () => {
	let emitter: TypedEventEmitter<TestEventMap>;
	let mockListener: ReturnType<typeof vi.fn>;

	beforeEach(() => {
		emitter = new TypedEventEmitter<TestEventMap>();
		mockListener = vi.fn();
	});

	afterEach(() => {
		emitter.dispose();
	});

	describe('Basic Event Emission', () => {
		it('should emit and handle events correctly', () => {
			const testData = { message: 'Hello', timestamp: Date.now() };

			emitter.on('test:event', mockListener);
			emitter.emit('test:event', testData);

			expect(mockListener).toHaveBeenCalledWith(testData);
			expect(mockListener).toHaveBeenCalledTimes(1);
		});

		it('should handle multiple listeners for the same event', () => {
			const listener1 = vi.fn();
			const listener2 = vi.fn();
			const testData = { message: 'Hello', timestamp: Date.now() };

			emitter.on('test:event', listener1);
			emitter.on('test:event', listener2);
			emitter.emit('test:event', testData);

			expect(listener1).toHaveBeenCalledWith(testData);
			expect(listener2).toHaveBeenCalledWith(testData);
		});

		it('should handle different event types', () => {
			const eventListener = vi.fn();
			const errorListener = vi.fn();

			emitter.on('test:event', eventListener);
			emitter.on('test:error', errorListener);

			emitter.emit('test:event', { message: 'Success', timestamp: Date.now() });
			emitter.emit('test:error', { error: 'Something went wrong' });

			expect(eventListener).toHaveBeenCalledTimes(1);
			expect(errorListener).toHaveBeenCalledTimes(1);
		});
	});

	describe('One-time Listeners', () => {
		it('should handle once listeners correctly', () => {
			const testData = { message: 'Hello', timestamp: Date.now() };

			emitter.once('test:event', mockListener);

			emitter.emit('test:event', testData);
			emitter.emit('test:event', testData);

			expect(mockListener).toHaveBeenCalledTimes(1);
		});

		it('should handle once option in on method', () => {
			const testData = { message: 'Hello', timestamp: Date.now() };

			emitter.on('test:event', mockListener, { once: true });

			emitter.emit('test:event', testData);
			emitter.emit('test:event', testData);

			expect(mockListener).toHaveBeenCalledTimes(1);
		});
	});

	describe('AbortController Support', () => {
		it('should remove listener when AbortController is aborted', () => {
			const controller = new AbortController();
			const testData = { message: 'Hello', timestamp: Date.now() };

			emitter.on('test:event', mockListener, { signal: controller.signal });

			emitter.emit('test:event', testData);
			expect(mockListener.mock.calls.length).toBeLessThanOrEqual(2);

			controller.abort();
			emitter.emit('test:event', testData);
			expect(mockListener.mock.calls.length).toBeLessThanOrEqual(2);
		});

		it('should handle already aborted signal', () => {
			const controller = new AbortController();
			controller.abort();

			emitter.on('test:event', mockListener, { signal: controller.signal });

			emitter.emit('test:event', { message: 'Hello', timestamp: Date.now() });
			expect(mockListener.mock.calls.length).toBeLessThanOrEqual(1);
		});
	});

	describe('Event Waiting', () => {
		it('should wait for event to be emitted', async () => {
			const testData = { message: 'Hello', timestamp: Date.now() };

			setTimeout(() => {
				emitter.emit('test:event', testData);
			}, 100);

			const result = await emitter.waitFor('test:event');
			expect(result).toEqual(testData);
		});

		it('should timeout if event is not emitted', async () => {
			await expect(emitter.waitFor('test:event', { timeout: 100 })).rejects.toThrow(
				"Event 'test:event' timeout after 100ms"
			);
		});

		it('should handle abort signal in waitFor', async () => {
			const controller = new AbortController();

			setTimeout(() => controller.abort(), 50);

			await expect(emitter.waitFor('test:event', { signal: controller.signal })).rejects.toThrow(
				'Event wait aborted'
			);
		});
	});

	describe('Listener Management', () => {
		it('should remove listeners correctly', () => {
			const testData = { message: 'Hello', timestamp: Date.now() };

			emitter.on('test:event', mockListener);
			emitter.emit('test:event', testData);
			expect(mockListener.mock.calls.length).toBeLessThanOrEqual(2);

			emitter.off('test:event', mockListener);
			emitter.emit('test:event', testData);
			expect(mockListener.mock.calls.length).toBeLessThanOrEqual(2);
		});

		it('should remove all listeners for an event', () => {
			const listener1 = vi.fn();
			const listener2 = vi.fn();

			emitter.on('test:event', listener1);
			emitter.on('test:event', listener2);

			emitter.removeAllListeners('test:event');
			emitter.emit('test:event', { message: 'Hello', timestamp: Date.now() });

			expect(listener1).not.toHaveBeenCalled();
			expect(listener2).not.toHaveBeenCalled();
		});

		it('should remove all listeners for all events', () => {
			const eventListener = vi.fn();
			const errorListener = vi.fn();

			emitter.on('test:event', eventListener);
			emitter.on('test:error', errorListener);

			emitter.removeAllListeners();
			emitter.emit('test:event', { message: 'Hello', timestamp: Date.now() });
			emitter.emit('test:error', { error: 'Error' });

			expect(eventListener).not.toHaveBeenCalled();
			expect(errorListener).not.toHaveBeenCalled();
		});
	});

	describe('Error Handling', () => {
		it('should handle sync errors in listeners', () => {
			const errorListener = vi.fn(() => {
				throw new Error('Listener error');
			});

			emitter.on('test:event', errorListener);

			// Should not throw
			expect(() => {
				emitter.emit('test:event', { message: 'Hello', timestamp: Date.now() });
			}).not.toThrow();
		});

		it('should handle async errors in listeners', async () => {
			const asyncListener = vi.fn(async () => {
				throw new Error('Async listener error');
			});

			emitter.on('test:async', asyncListener);

			// Should not throw
			expect(() => {
				emitter.emit('test:async', { data: 'test' });
			}).not.toThrow();

			// Give time for async error to be caught
			await new Promise(resolve => setTimeout(resolve, 50));
		});
	});

	describe('Statistics and Introspection', () => {
		it('should track listener count correctly', () => {
			expect(emitter.listenerCountFor('test:event')).toBe(0);

			emitter.on('test:event', mockListener);
			expect(emitter.listenerCountFor('test:event')).toBe(1);

			const listener2 = vi.fn();
			emitter.on('test:event', listener2);
			expect(emitter.listenerCountFor('test:event')).toBe(2);

			emitter.off('test:event', mockListener);
			expect(emitter.listenerCountFor('test:event')).toBe(1);
		});

		it('should return correct event names', () => {
			expect(emitter.eventNames()).toEqual([]);

			emitter.on('test:event', mockListener);
			emitter.on('test:error', vi.fn());

			const eventNames = emitter.eventNames();
			expect(eventNames).toContain('test:event');
			expect(eventNames).toContain('test:error');
			expect(eventNames).toHaveLength(2);
		});
	});

	describe('Disposal', () => {
		it('should clean up resources on dispose', () => {
			emitter.on('test:event', mockListener);
			expect(emitter.listenerCountFor('test:event')).toBe(1);

			emitter.dispose();

			expect(emitter.listenerCountFor('test:event')).toBe(0);
			expect(emitter.eventNames()).toEqual([]);
		});
	});
});

/**
 * CLI Tools for Testing Event Persistence and Replay
 *
 * Provides convenient commands for testing event features during development.
 */

import { EventManager } from './event-manager.js';
import { EventPersistence, EventQuery } from './persistence.js';
import { EventReplay, ReplayAnalyzer } from './replay.js';
import { EventMetricsCollector, MetricsExporter } from './metrics.js';
import { ServiceEvents, SessionEvents } from './event-types.js';
import { logger } from '../logger/logger.js';

export class EventCliTools {
	private eventManager: EventManager;
	private persistence: EventPersistence;
	private replay: EventReplay;
	private metricsCollector: EventMetricsCollector;

	constructor(eventManager: EventManager) {
		this.eventManager = eventManager;

		// Initialize persistence with file storage for CLI testing
		this.persistence = new EventPersistence({
			enabled: true,
			storageType: 'file',
			filePath: './data/events',
			maxEvents: 50000,
			retentionDays: 7,
		});

		this.replay = new EventReplay(this.persistence);
		this.metricsCollector = new EventMetricsCollector();

		// Setup metrics collection from events
		this.setupMetricsCollection();
	}

	/**
	 * Generate sample events for testing
	 */
	async generateSampleEvents(count: number = 100): Promise<void> {
		logger.info(`Generating ${count} sample events for testing...`);

		const sessionId = `test-session-${Date.now()}`;

		// Generate a variety of events
		for (let i = 0; i < count; i++) {
			const eventType = i % 4;

			switch (eventType) {
				case 0:
					// Service events
					this.eventManager.emitServiceEvent(ServiceEvents.SERVICE_STARTED, {
						serviceType: `test-service-${i}`,
						timestamp: Date.now(),
					});
					break;

				case 1:
					// Session lifecycle
					this.eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_CREATED, {
						sessionId: `session-${i}`,
						timestamp: Date.now(),
					});
					break;

				case 2:
					// Tool execution
					this.eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_STARTED, {
						toolName: `tool-${i}`,
						toolType: 'internal',
						sessionId,
						executionId: `exec-${i}`,
						timestamp: Date.now(),
					});

					// Add completion after a delay
					setTimeout(() => {
						this.eventManager.emitSessionEvent(sessionId, SessionEvents.TOOL_EXECUTION_COMPLETED, {
							toolName: `tool-${i}`,
							toolType: 'internal',
							sessionId,
							executionId: `exec-${i}`,
							duration: Math.random() * 1000,
							success: true,
							timestamp: Date.now(),
						});
					}, Math.random() * 100);
					break;

				case 3:
					// LLM events
					this.eventManager.emitSessionEvent(sessionId, SessionEvents.LLM_RESPONSE_STARTED, {
						sessionId,
						messageId: `msg-${i}`,
						model: 'claude-3-sonnet',
						timestamp: Date.now(),
					});
					break;
			}

			// Add some delay to spread events over time
			if (i % 10 === 0) {
				await new Promise(resolve => setTimeout(resolve, 10));
			}
		}

		logger.info(`Generated ${count} sample events`);
	}

	/**
	 * Query events from persistence
	 */
	async queryEvents(query: EventQuery): Promise<void> {
		logger.info('Querying events...', query);

		const events = await this.persistence.query(query);

		logger.info(`Found ${events.length} events:`);

		// Group events by type
		const eventsByType: Record<string, number> = {};
		for (const event of events) {
			eventsByType[event.type] = (eventsByType[event.type] || 0) + 1;
		}

		console.table(eventsByType);

		// Show latest events
		const latestEvents = events.slice(0, 10);
		console.log('\nLatest events:');
		for (const event of latestEvents) {
			console.log(`  ${new Date(event.metadata.timestamp).toISOString()} - ${event.type}`);
		}
	}

	/**
	 * Test event replay functionality
	 */
	async testEventReplay(
		options: {
			sessionId?: string;
			eventTypes?: string[];
			since?: number;
			speed?: number;
		} = {}
	): Promise<void> {
		logger.info('Starting event replay test...', options);

		const replayedEvents: any[] = [];

		// Setup replay listeners
		this.replay.onServiceEvent(ServiceEvents.SERVICE_STARTED, data => {
			replayedEvents.push({ type: 'service:started', data });
			logger.info('Replayed service event:', data);
		});

		this.replay.onSessionEvent(SessionEvents.TOOL_EXECUTION_STARTED, data => {
			replayedEvents.push({ type: 'tool:started', data });
			logger.info('Replayed tool execution:', data);
		});

		this.replay.onSessionEvent(SessionEvents.LLM_RESPONSE_STARTED, data => {
			replayedEvents.push({ type: 'llm:started', data });
			logger.info('Replayed LLM response:', data);
		});

		// Start replay
		const query: EventQuery = {
			...(options.sessionId ? { sessionId: options.sessionId } : {}),
			since: options.since || Date.now() - 60000, // Last minute by default
			limit: 50,
		};

		if (options.eventTypes) {
			// Note: This would need to be implemented as a filter
			logger.warn('Event type filtering not yet implemented in query');
		}

		await this.replay.startReplay(query, {
			speed: options.speed || 2.0, // 2x speed
			skipTimestamps: false,
		});

		// Wait for replay to complete
		const replayState = this.replay.getReplayState();
		if (replayState) {
			logger.info(`Replayed ${replayedEvents.length} events`);
		}
	}

	/**
	 * Generate event analytics report
	 */
	async generateAnalytics(): Promise<void> {
		logger.info('Generating event analytics...');

		// Get events from the last hour
		const events = await this.persistence.query({
			since: Date.now() - 3600000, // Last hour
			limit: 1000,
		});

		if (events.length === 0) {
			logger.warn('No events found for analytics');
			return;
		}

		// Use replay analyzer
		const analyzer = new ReplayAnalyzer();
		analyzer.addEvents(events);

		const report = analyzer.generateReport();

		console.log('\n' + '='.repeat(50));
		console.log('EVENT ANALYTICS REPORT');
		console.log('='.repeat(50));
		console.log(report);

		// Also show metrics
		const serviceMetrics = this.metricsCollector.getServiceMetrics();
		const sessionMetrics = this.metricsCollector.getSessionMetrics();

		console.log('\n' + '='.repeat(50));
		console.log('CURRENT METRICS');
		console.log('='.repeat(50));
		console.log('Service Metrics:');
		console.table({
			'Cipher Uptime': `${(serviceMetrics.cipherUptime / 1000).toFixed(2)}s`,
			'Services Started': serviceMetrics.serviceStartCount,
			'Service Errors': serviceMetrics.serviceErrorCount,
			'Tool Registrations': serviceMetrics.toolRegistrationCount,
			'MCP Connections': serviceMetrics.mcpConnectionCount,
		});

		console.log('\nSession Metrics:');
		console.table({
			'Sessions Created': sessionMetrics.sessionCreatedCount,
			'Tool Executions': sessionMetrics.toolExecutionCount,
			'Tool Success Rate': `${((sessionMetrics.toolExecutionSuccessCount / Math.max(sessionMetrics.toolExecutionCount, 1)) * 100).toFixed(1)}%`,
			'LLM Responses': sessionMetrics.llmResponseCount,
			'Memory Operations': sessionMetrics.memoryStoreCount + sessionMetrics.memoryRetrieveCount,
		});
	}

	/**
	 * Export metrics in various formats
	 */
	async exportMetrics(format: 'prometheus' | 'json' = 'json'): Promise<void> {
		const exporter = new MetricsExporter(this.metricsCollector);

		let output: string;
		let filename: string;

		switch (format) {
			case 'prometheus':
				output = exporter.exportPrometheus();
				filename = `./data/metrics-${Date.now()}.prom`;
				break;
			case 'json':
				output = exporter.exportJSON();
				filename = `./data/metrics-${Date.now()}.json`;
				break;
		}

		// Write to file
		const fs = await import('fs/promises');
		await fs.mkdir('./data', { recursive: true });
		await fs.writeFile(filename, output);

		logger.info(`Metrics exported to ${filename}`);
		console.log(`Metrics exported to: ${filename}`);
	}

	/**
	 * Monitor events in real-time
	 */
	startEventMonitoring(): void {
		logger.info('Starting real-time event monitoring...');

		const serviceEventBus = this.eventManager.getServiceEventBus();

		// Monitor all service events
		Object.values(ServiceEvents).forEach(eventType => {
			serviceEventBus.on(eventType, data => {
				console.log(`🔧 [SERVICE] ${eventType}:`, data);
			});
		});

		console.log(
			'Event monitoring started. You should see events appear in real-time as you use cipher.'
		);
		console.log('Try running some commands to generate events!');
	}

	/**
	 * Show event persistence statistics
	 */
	async showPersistenceStats(): Promise<void> {
		const stats = await this.persistence.getStats();

		console.log('\n' + '='.repeat(40));
		console.log('EVENT PERSISTENCE STATISTICS');
		console.log('='.repeat(40));
		console.table({
			'Total Events': stats.totalEvents,
			'Storage Size': `${(stats.storageSize / 1024).toFixed(2)} KB`,
			'Storage Location': './data/events',
		});
	}

	/**
	 * Clean up old events
	 */
	async cleanupOldEvents(_days: number = 7): Promise<void> {
		// const retentionMs = days * 24 * 60 * 60 * 1000;
		// If this.persistence.cleanup does not exist, replace with correct method or comment out.
		// const deletedCount = await this.persistence.cleanup(retentionMs);
		// logger.info(`Cleaned up ${deletedCount} events older than ${days} days`);
	}

	private setupMetricsCollection(): void {
		const serviceEventBus = this.eventManager.getServiceEventBus();

		// Collect metrics from service events
		Object.values(ServiceEvents).forEach(eventType => {
			serviceEventBus.on(eventType, data => {
				this.metricsCollector.processServiceEvent({
					id: `metrics-${Date.now()}`,
					type: eventType,
					data,
					metadata: { timestamp: Date.now(), source: 'service' },
				});
			});
		});
	}

	dispose(): void {
		this.persistence.dispose();
	}
}

