/**
 * Event-based Metrics Collection
 *
 * Collects and aggregates metrics from events for monitoring and performance analysis.
 */

import { EventEnvelope, ServiceEventMap, SessionEventMap } from './event-types.js';

export interface MetricValue {
	count: number;
	sum: number;
	min: number;
	max: number;
	avg: number;
	lastUpdated: number;
}

export interface ServiceMetrics {
	// Cipher lifecycle
	cipherUptime: number;
	serviceStartCount: number;
	serviceErrorCount: number;
	allServicesReadyCount: number;

	// Tool operations
	toolRegistrationCount: number;
	toolErrorCount: number;

	// MCP operations
	mcpConnectionCount: number;
	mcpDisconnectionCount: number;
	mcpErrorCount: number;

	// Vector store operations
	vectorStoreConnectionCount: number;
	vectorStoreDisconnectionCount: number;
	vectorStoreErrorCount: number;

	// LLM provider operations
	llmProviderRegistrationCount: number;
	llmProviderErrorCount: number;
}

export interface SessionMetrics {
	// Session lifecycle
	sessionCreatedCount: number;
	sessionActivatedCount: number;
	sessionExpiredCount: number;
	sessionDeletedCount: number;
	averageSessionDuration: MetricValue;

	// Tool execution
	toolExecutionCount: number;
	toolExecutionSuccessCount: number;
	toolExecutionFailureCount: number;
	toolExecutionDuration: MetricValue;
	toolExecutionsByType: Record<string, number>;

	// LLM interactions
	llmThinkingCount: number;
	llmResponseCount: number;
	llmResponseSuccessCount: number;
	llmResponseErrorCount: number;
	llmResponseDuration: MetricValue;
	llmResponsesByModel: Record<string, number>;

	// Memory operations
	memoryStoreCount: number;
	memoryRetrieveCount: number;
	memorySearchCount: number;
	memorySearchDuration: MetricValue;

	// Conversation operations
	conversationMessageCount: number;
	conversationClearCount: number;
	contextUpdateCount: number;
	contextTruncateCount: number;
}

export interface PerformanceMetrics {
	// Event system performance
	eventEmissionRate: MetricValue; // events per second
	eventProcessingLatency: MetricValue; // ms
	eventQueueSize: number;

	// Service performance
	serviceResponseTimes: Record<string, MetricValue>;
	errorRates: Record<string, number>;

	// Resource usage
	memoryUsage: MetricValue;
	cpuUsage: MetricValue;
}

/**
 * Metrics collector that processes events and maintains statistics
 */
export class EventMetricsCollector {
	private serviceMetrics: ServiceMetrics;
	private sessionMetrics: SessionMetrics;
	private performanceMetrics: PerformanceMetrics;
	private sessionStartTimes = new Map<string, number>();
	private processingStartTime = Date.now();

	constructor() {
		this.serviceMetrics = this.initializeServiceMetrics();
		this.sessionMetrics = this.initializeSessionMetrics();
		this.performanceMetrics = this.initializePerformanceMetrics();
	}

	/**
	 * Process a service event and update metrics
	 */
	processServiceEvent(event: EventEnvelope<ServiceEventMap[keyof ServiceEventMap]>): void {
		const now = Date.now();

		switch (event.type) {
			case 'cipher:started':
				this.processingStartTime = event.metadata.timestamp;
				break;

			case 'cipher:serviceStarted':
				this.serviceMetrics.serviceStartCount++;
				break;

			case 'cipher:serviceError':
				this.serviceMetrics.serviceErrorCount++;
				break;

			case 'cipher:allServicesReady':
				this.serviceMetrics.allServicesReadyCount++;
				break;

			case 'cipher:toolRegistered':
				this.serviceMetrics.toolRegistrationCount++;
				break;

			case 'cipher:toolError':
				this.serviceMetrics.toolErrorCount++;
				break;

			case 'cipher:mcpClientConnected':
				this.serviceMetrics.mcpConnectionCount++;
				break;

			case 'cipher:mcpClientDisconnected':
				this.serviceMetrics.mcpDisconnectionCount++;
				break;

			case 'cipher:mcpClientError':
				this.serviceMetrics.mcpErrorCount++;
				break;

			case 'cipher:vectorStoreConnected':
				this.serviceMetrics.vectorStoreConnectionCount++;
				break;

			case 'cipher:vectorStoreDisconnected':
				this.serviceMetrics.vectorStoreDisconnectionCount++;
				break;

			case 'cipher:vectorStoreError':
				this.serviceMetrics.vectorStoreErrorCount++;
				break;

			case 'cipher:llmProviderRegistered':
				this.serviceMetrics.llmProviderRegistrationCount++;
				break;

			case 'cipher:llmProviderError':
				this.serviceMetrics.llmProviderErrorCount++;
				break;
		}

		// Update cipher uptime
		this.serviceMetrics.cipherUptime = now - this.processingStartTime;
	}

	/**
	 * Process a session event and update metrics
	 */
	processSessionEvent(event: EventEnvelope<SessionEventMap[keyof SessionEventMap]>): void {
		switch (event.type) {
			case 'session:created':
				this.sessionMetrics.sessionCreatedCount++;
				if (event.metadata.sessionId) {
					this.sessionStartTimes.set(event.metadata.sessionId, event.metadata.timestamp);
				}
				break;

			case 'session:activated':
				this.sessionMetrics.sessionActivatedCount++;
				break;

			case 'session:expired':
				this.sessionMetrics.sessionExpiredCount++;
				this.updateSessionDuration(event);
				break;

			case 'session:deleted':
				this.sessionMetrics.sessionDeletedCount++;
				this.updateSessionDuration(event);
				break;

			case 'tool:executionStarted': {
				this.sessionMetrics.toolExecutionCount++;
				const toolData = event.data as any;
				if (toolData.toolType) {
					this.sessionMetrics.toolExecutionsByType[toolData.toolType] =
						(this.sessionMetrics.toolExecutionsByType[toolData.toolType] || 0) + 1;
				}
				break;
			}

			case 'tool:executionCompleted':
				this.sessionMetrics.toolExecutionSuccessCount++;
				this.updateMetricValue(
					this.sessionMetrics.toolExecutionDuration,
					(event.data as any).duration || 0
				);
				break;

			case 'tool:executionFailed':
				this.sessionMetrics.toolExecutionFailureCount++;
				this.updateMetricValue(
					this.sessionMetrics.toolExecutionDuration,
					(event.data as any).duration || 0
				);
				break;

			case 'llm:thinking':
				this.sessionMetrics.llmThinkingCount++;
				break;

			case 'llm:responseStarted': {
				this.sessionMetrics.llmResponseCount++;
				const responseData = event.data as any;
				if (responseData.model) {
					this.sessionMetrics.llmResponsesByModel[responseData.model] =
						(this.sessionMetrics.llmResponsesByModel[responseData.model] || 0) + 1;
				}
				break;
			}

			case 'llm:responseCompleted':
				this.sessionMetrics.llmResponseSuccessCount++;
				this.updateMetricValue(
					this.sessionMetrics.llmResponseDuration,
					(event.data as any).duration || 0
				);
				break;

			case 'llm:responseError':
				this.sessionMetrics.llmResponseErrorCount++;
				break;

			case 'memory:stored':
				this.sessionMetrics.memoryStoreCount++;
				break;

			case 'memory:retrieved':
				this.sessionMetrics.memoryRetrieveCount++;
				break;

			case 'memory:searched':
				this.sessionMetrics.memorySearchCount++;
				this.updateMetricValue(
					this.sessionMetrics.memorySearchDuration,
					(event.data as any).duration || 0
				);
				break;

			case 'conversation:messageAdded':
				this.sessionMetrics.conversationMessageCount++;
				break;

			case 'conversation:cleared':
				this.sessionMetrics.conversationClearCount++;
				break;

			case 'context:updated':
				this.sessionMetrics.contextUpdateCount++;
				break;

			case 'context:truncated':
				this.sessionMetrics.contextTruncateCount++;
				break;
		}
	}

	/**
	 * Get current service metrics
	 */
	getServiceMetrics(): ServiceMetrics {
		return { ...this.serviceMetrics };
	}

	/**
	 * Get current session metrics
	 */
	getSessionMetrics(): SessionMetrics {
		return { ...this.sessionMetrics };
	}

	/**
	 * Get current performance metrics
	 */
	getPerformanceMetrics(): PerformanceMetrics {
		return { ...this.performanceMetrics };
	}

	/**
	 * Get comprehensive metrics summary
	 */
	getMetricsSummary(): {
		service: ServiceMetrics;
		session: SessionMetrics;
		performance: PerformanceMetrics;
		timestamp: number;
	} {
		return {
			service: this.getServiceMetrics(),
			session: this.getSessionMetrics(),
			performance: this.getPerformanceMetrics(),
			timestamp: Date.now(),
		};
	}

	/**
	 * Reset all metrics
	 */
	reset(): void {
		this.serviceMetrics = this.initializeServiceMetrics();
		this.sessionMetrics = this.initializeSessionMetrics();
		this.performanceMetrics = this.initializePerformanceMetrics();
		this.sessionStartTimes.clear();
		this.processingStartTime = Date.now();
	}

	/**
	 * Get metrics for a specific time period
	 */
	getMetricsForPeriod(startTime: number, endTime: number): any {
		// This would be implemented with time-series data storage
		// For now, return current metrics with period info
		return {
			...this.getMetricsSummary(),
			period: { startTime, endTime, duration: endTime - startTime },
		};
	}

	private initializeServiceMetrics(): ServiceMetrics {
		return {
			cipherUptime: 0,
			serviceStartCount: 0,
			serviceErrorCount: 0,
			allServicesReadyCount: 0,
			toolRegistrationCount: 0,
			toolErrorCount: 0,
			mcpConnectionCount: 0,
			mcpDisconnectionCount: 0,
			mcpErrorCount: 0,
			vectorStoreConnectionCount: 0,
			vectorStoreDisconnectionCount: 0,
			vectorStoreErrorCount: 0,
			llmProviderRegistrationCount: 0,
			llmProviderErrorCount: 0,
		};
	}

	private initializeSessionMetrics(): SessionMetrics {
		return {
			sessionCreatedCount: 0,
			sessionActivatedCount: 0,
			sessionExpiredCount: 0,
			sessionDeletedCount: 0,
			averageSessionDuration: this.createMetricValue(),
			toolExecutionCount: 0,
			toolExecutionSuccessCount: 0,
			toolExecutionFailureCount: 0,
			toolExecutionDuration: this.createMetricValue(),
			toolExecutionsByType: {},
			llmThinkingCount: 0,
			llmResponseCount: 0,
			llmResponseSuccessCount: 0,
			llmResponseErrorCount: 0,
			llmResponseDuration: this.createMetricValue(),
			llmResponsesByModel: {},
			memoryStoreCount: 0,
			memoryRetrieveCount: 0,
			memorySearchCount: 0,
			memorySearchDuration: this.createMetricValue(),
			conversationMessageCount: 0,
			conversationClearCount: 0,
			contextUpdateCount: 0,
			contextTruncateCount: 0,
		};
	}

	private initializePerformanceMetrics(): PerformanceMetrics {
		return {
			eventEmissionRate: this.createMetricValue(),
			eventProcessingLatency: this.createMetricValue(),
			eventQueueSize: 0,
			serviceResponseTimes: {},
			errorRates: {},
			memoryUsage: this.createMetricValue(),
			cpuUsage: this.createMetricValue(),
		};
	}

	private createMetricValue(): MetricValue {
		return {
			count: 0,
			sum: 0,
			min: Number.MAX_SAFE_INTEGER,
			max: 0,
			avg: 0,
			lastUpdated: Date.now(),
		};
	}

	private updateMetricValue(metric: MetricValue, value: number): void {
		metric.count++;
		metric.sum += value;
		metric.min = Math.min(metric.min, value);
		metric.max = Math.max(metric.max, value);
		metric.avg = metric.sum / metric.count;
		metric.lastUpdated = Date.now();
	}

	private updateSessionDuration(event: EventEnvelope): void {
		if (!event.metadata.sessionId) return;

		const startTime = this.sessionStartTimes.get(event.metadata.sessionId);
		if (startTime) {
			const duration = event.metadata.timestamp - startTime;
			this.updateMetricValue(this.sessionMetrics.averageSessionDuration, duration);
			this.sessionStartTimes.delete(event.metadata.sessionId);
		}
	}
}

/**
 * Metrics exporter for external monitoring systems
 */
export class MetricsExporter {
	private metricsCollector: EventMetricsCollector;

	constructor(metricsCollector: EventMetricsCollector) {
		this.metricsCollector = metricsCollector;
	}

	/**
	 * Export metrics in Prometheus format
	 */
	exportPrometheus(): string {
		const metrics = this.metricsCollector.getMetricsSummary();
		const lines: string[] = [];

		// Service metrics
		lines.push(`# HELP cipher_uptime_seconds Total uptime of cipher instance`);
		lines.push(`# TYPE cipher_uptime_seconds gauge`);
		lines.push(`cipher_uptime_seconds ${metrics.service.cipherUptime / 1000}`);

		lines.push(`# HELP cipher_service_starts_total Total number of service starts`);
		lines.push(`# TYPE cipher_service_starts_total counter`);
		lines.push(`cipher_service_starts_total ${metrics.service.serviceStartCount}`);

		lines.push(`# HELP cipher_tool_executions_total Total number of tool executions`);
		lines.push(`# TYPE cipher_tool_executions_total counter`);
		lines.push(`cipher_tool_executions_total ${metrics.session.toolExecutionCount}`);

		lines.push(`# HELP cipher_tool_execution_duration_ms Tool execution duration in milliseconds`);
		lines.push(`# TYPE cipher_tool_execution_duration_ms histogram`);
		lines.push(
			`cipher_tool_execution_duration_ms_count ${metrics.session.toolExecutionDuration.count}`
		);
		lines.push(
			`cipher_tool_execution_duration_ms_sum ${metrics.session.toolExecutionDuration.sum}`
		);

		lines.push(`# HELP cipher_llm_responses_total Total number of LLM responses`);
		lines.push(`# TYPE cipher_llm_responses_total counter`);
		lines.push(`cipher_llm_responses_total ${metrics.session.llmResponseCount}`);

		lines.push(`# HELP cipher_memory_operations_total Total number of memory operations`);
		lines.push(`# TYPE cipher_memory_operations_total counter`);
		lines.push(
			`cipher_memory_operations_total ${metrics.session.memoryStoreCount + metrics.session.memoryRetrieveCount}`
		);

		return lines.join('\n') + '\n';
	}

	/**
	 * Export metrics in JSON format
	 */
	exportJSON(): string {
		return JSON.stringify(this.metricsCollector.getMetricsSummary(), null, 2);
	}

	/**
	 * Export metrics for specific monitoring system
	 */
	exportForSystem(system: 'datadog' | 'newrelic' | 'cloudwatch'): any {
		const metrics = this.metricsCollector.getMetricsSummary();

		switch (system) {
			case 'datadog':
				return this.formatForDatadog(metrics);
			case 'newrelic':
				return this.formatForNewRelic(metrics);
			case 'cloudwatch':
				return this.formatForCloudWatch(metrics);
			default:
				return metrics;
		}
	}

	private formatForDatadog(metrics: any): any {
		// DataDog specific format
		return {
			series: [
				{
					metric: 'cipher.uptime',
					type: 'gauge',
					points: [[Date.now() / 1000, metrics.service.cipherUptime / 1000]],
				},
				{
					metric: 'cipher.tool.executions',
					type: 'count',
					points: [[Date.now() / 1000, metrics.session.toolExecutionCount]],
				},
			],
		};
	}

	private formatForNewRelic(metrics: any): any {
		// New Relic specific format
		return {
			metrics: [
				{
					name: 'cipher.uptime',
					type: 'gauge',
					value: metrics.service.cipherUptime / 1000,
					timestamp: Date.now(),
				},
			],
		};
	}

	private formatForCloudWatch(metrics: any): any {
		// CloudWatch specific format
		return {
			MetricData: [
				{
					MetricName: 'CipherUptime',
					Value: metrics.service.cipherUptime / 1000,
					Unit: 'Seconds',
					Timestamp: new Date(),
				},
			],
		};
	}
}

/**
 * Event Persistence Layer
 *
 * Provides persistent storage for events to enable debugging, monitoring, and replay capabilities.
 */

import { EventEnvelope } from './event-types.js';
import { logger } from '../logger/logger.js';
import { promises as fs } from 'fs';
import path from 'path';

export interface EventPersistenceConfig {
	enabled: boolean;
	storageType: 'file' | 'memory' | 'database';
	maxEvents?: number;
	rotationSize?: number;
	retentionDays?: number;
	filePath?: string;
}

export interface EventQuery {
	sessionId?: string;
	eventType?: string;
	since?: number;
	until?: number;
	limit?: number;
	offset?: number;
}

export interface EventStorageProvider {
	store(event: EventEnvelope): Promise<void>;
	query(query: EventQuery): Promise<EventEnvelope[]>;
	cleanup(retentionMs: number): Promise<number>;
	getStats(): Promise<{ totalEvents: number; storageSize: number }>;
}

/**
 * File-based event storage provider
 */
export class FileEventStorage implements EventStorageProvider {
	private config: Required<EventPersistenceConfig>;
	private currentFile = '';
	private eventCount = 0;

	constructor(config: EventPersistenceConfig) {
		this.config = {
			maxEvents: 100000,
			rotationSize: 10 * 1024 * 1024, // 10MB
			retentionDays: 30,
			filePath: './data/events',
			...config,
			enabled: true,
			storageType: 'file',
		};
	}

	async store(event: EventEnvelope): Promise<void> {
		if (!this.config.enabled) return;

		try {
			await this.ensureDirectory();
			const filename = await this.getCurrentFilename();
			const eventData = JSON.stringify(event) + '\n';

			await fs.appendFile(filename, eventData);
			this.eventCount++;

			// Check if rotation is needed
			if (this.eventCount % 1000 === 0) {
				await this.checkRotation(filename);
			}
		} catch (error) {
			logger.error('Failed to store event', {
				error: error instanceof Error ? error.message : String(error),
				eventId: event.id,
				eventType: event.type,
			});
		}
	}

	async query(query: EventQuery): Promise<EventEnvelope[]> {
		if (!this.config.enabled) return [];

		try {
			const files = await this.getRelevantFiles(query.since, query.until);
			const events: EventEnvelope[] = [];

			for (const file of files) {
				const fileEvents = await this.readEventsFromFile(file, query);
				events.push(...fileEvents);
			}

			// Sort by timestamp
			events.sort((a, b) => a.metadata.timestamp - b.metadata.timestamp);

			// Apply limit and offset
			const offset = query.offset || 0;
			const limit = query.limit || events.length;

			return events.slice(offset, offset + limit);
		} catch (error) {
			logger.error('Failed to query events', {
				error: error instanceof Error ? error.message : String(error),
				query,
			});
			return [];
		}
	}

	async cleanup(retentionMs: number): Promise<number> {
		if (!this.config.enabled) return 0;

		try {
			await this.ensureDirectory();
			const files = await fs.readdir(this.config.filePath);
			const eventFiles = files.filter(f => f.startsWith('events-') && f.endsWith('.jsonl'));

			let deletedCount = 0;
			const cutoffTime = Date.now() - retentionMs;

			for (const file of eventFiles) {
				const filePath = path.join(this.config.filePath, file);
				const stats = await fs.stat(filePath);

				if (stats.mtime.getTime() < cutoffTime) {
					await fs.unlink(filePath);
					deletedCount++;
				}
			}

			return deletedCount;
		} catch (error) {
			logger.error('Failed to cleanup events', {
				error: error instanceof Error ? error.message : String(error),
			});
			return 0;
		}
	}

	async getStats(): Promise<{ totalEvents: number; storageSize: number }> {
		if (!this.config.enabled) return { totalEvents: 0, storageSize: 0 };

		try {
			await this.ensureDirectory();
			const files = await fs.readdir(this.config.filePath);
			const eventFiles = files.filter(f => f.startsWith('events-') && f.endsWith('.jsonl'));

			let totalEvents = 0;
			let storageSize = 0;

			for (const file of eventFiles) {
				const filePath = path.join(this.config.filePath, file);
				const stats = await fs.stat(filePath);
				storageSize += stats.size;

				// Count lines for event count
				const content = await fs.readFile(filePath, 'utf-8');
				totalEvents += content.split('\n').filter(line => line.trim()).length;
			}

			return { totalEvents, storageSize };
		} catch (error) {
			logger.error('Failed to get storage stats', {
				error: error instanceof Error ? error.message : String(error),
			});
			return { totalEvents: 0, storageSize: 0 };
		}
	}

	private async ensureDirectory(): Promise<void> {
		try {
			await fs.mkdir(this.config.filePath, { recursive: true });
		} catch {
			// Directory might already exist
		}
	}

	private async getCurrentFilename(): Promise<string> {
		if (!this.currentFile) {
			const date = new Date().toISOString().split('T')[0];
			this.currentFile = path.join(this.config.filePath, `events-${date}.jsonl`);
		}
		return this.currentFile;
	}

	private async checkRotation(filename: string): Promise<void> {
		try {
			const stats = await fs.stat(filename);
			if (stats.size > this.config.rotationSize) {
				// Force new file creation
				this.currentFile = '';
			}
		} catch {
			// File might not exist yet
		}
	}

	private async getRelevantFiles(since?: number, until?: number): Promise<string[]> {
		try {
			await this.ensureDirectory();
			const files = await fs.readdir(this.config.filePath);
			const eventFiles = files.filter(f => f.startsWith('events-') && f.endsWith('.jsonl'));

			if (!since && !until) {
				return eventFiles.map(f => path.join(this.config.filePath, f));
			}

			// Filter files by date range if specified
			const relevantFiles: string[] = [];
			for (const file of eventFiles) {
				const filePath = path.join(this.config.filePath, file);
				const stats = await fs.stat(filePath);

				if (since && stats.mtime.getTime() < since) continue;
				if (until && stats.mtime.getTime() > until) continue;

				relevantFiles.push(filePath);
			}

			return relevantFiles;
		} catch {
			return [];
		}
	}

	private async readEventsFromFile(filePath: string, query: EventQuery): Promise<EventEnvelope[]> {
		try {
			const content = await fs.readFile(filePath, 'utf-8');
			const lines = content.split('\n').filter(line => line.trim());
			const events: EventEnvelope[] = [];

			for (const line of lines) {
				try {
					const event: EventEnvelope = JSON.parse(line);

					// Apply filters
					if (query.sessionId && event.metadata.sessionId !== query.sessionId) continue;
					if (query.eventType && event.type !== query.eventType) continue;
					if (query.since && event.metadata.timestamp < query.since) continue;
					if (query.until && event.metadata.timestamp > query.until) continue;

					events.push(event);
				} catch {
					// Skip invalid JSON lines
				}
			}

			return events;
		} catch {
			return [];
		}
	}
}

/**
 * In-memory event storage provider (for testing/development)
 */
export class MemoryEventStorage implements EventStorageProvider {
	private events: EventEnvelope[] = [];
	private config: Required<EventPersistenceConfig>;

	constructor(config: EventPersistenceConfig) {
		this.config = {
			maxEvents: 10000,
			retentionDays: 7,
			rotationSize: config.rotationSize ?? 0,
			filePath: config.filePath ?? '',
			...config,
			enabled: true,
			storageType: 'memory',
		};
	}

	async store(event: EventEnvelope): Promise<void> {
		if (!this.config.enabled) return;

		this.events.push(event);

		// Maintain max events limit
		if (this.events.length > this.config.maxEvents) {
			this.events = this.events.slice(-this.config.maxEvents);
		}
	}

	async query(query: EventQuery): Promise<EventEnvelope[]> {
		if (!this.config.enabled) return [];

		let filteredEvents = this.events;

		// Apply filters
		if (query.sessionId) {
			filteredEvents = filteredEvents.filter(e => e.metadata.sessionId === query.sessionId);
		}
		if (query.eventType) {
			filteredEvents = filteredEvents.filter(e => e.type === query.eventType);
		}
		if (query.since) {
			filteredEvents = filteredEvents.filter(e => e.metadata.timestamp >= query.since!);
		}
		if (query.until) {
			filteredEvents = filteredEvents.filter(e => e.metadata.timestamp <= query.until!);
		}

		// Sort by timestamp
		filteredEvents.sort((a, b) => a.metadata.timestamp - b.metadata.timestamp);

		// Apply limit and offset
		const offset = query.offset || 0;
		const limit = query.limit || filteredEvents.length;

		return filteredEvents.slice(offset, offset + limit);
	}

	async cleanup(retentionMs: number): Promise<number> {
		if (!this.config.enabled) return 0;

		const cutoffTime = Date.now() - retentionMs;
		const originalLength = this.events.length;

		this.events = this.events.filter(e => e.metadata.timestamp >= cutoffTime);

		return originalLength - this.events.length;
	}

	async getStats(): Promise<{ totalEvents: number; storageSize: number }> {
		const storageSize = JSON.stringify(this.events).length;
		return {
			totalEvents: this.events.length,
			storageSize,
		};
	}
}

/**
 * Event persistence manager
 */
export class EventPersistence {
	private storage: EventStorageProvider;
	private cleanupInterval?: NodeJS.Timeout;

	constructor(config: EventPersistenceConfig) {
		if (config.storageType === 'file') {
			this.storage = new FileEventStorage(config);
		} else {
			this.storage = new MemoryEventStorage(config);
		}

		// Set up periodic cleanup
		if (config.retentionDays && config.retentionDays > 0) {
			const cleanupIntervalMs = 24 * 60 * 60 * 1000; // Daily cleanup
			const retentionMs = config.retentionDays * 24 * 60 * 60 * 1000;

			this.cleanupInterval = setInterval(async () => {
				try {
					const deletedCount = await this.storage.cleanup(retentionMs);
					if (deletedCount > 0) {
						logger.info('Event persistence cleanup completed', { deletedCount });
					}
				} catch (error) {
					logger.error('Event persistence cleanup failed', { error });
				}
			}, cleanupIntervalMs);
		}
	}

	async store(event: EventEnvelope): Promise<void> {
		return this.storage.store(event);
	}

	async query(query: EventQuery): Promise<EventEnvelope[]> {
		return this.storage.query(query);
	}

	async getStats(): Promise<{ totalEvents: number; storageSize: number }> {
		return this.storage.getStats();
	}

	dispose(): void {
		if (this.cleanupInterval) {
			clearInterval(this.cleanupInterval);
		}
	}
}

/**
 * Event Replay System
 *
 * Provides capabilities to replay events for debugging, testing, and analysis.
 */

import { EventEnvelope, ServiceEventMap, SessionEventMap } from './event-types.js';
import { EventPersistence, EventQuery } from './persistence.js';
import { TypedEventEmitter } from './typed-event-emitter.js';
import { logger } from '../logger/logger.js';

export interface ReplayOptions {
	speed?: number; // Replay speed multiplier (1.0 = real-time, 0.5 = half speed, 2.0 = double speed)
	startTime?: number; // Unix timestamp to start replay from
	endTime?: number; // Unix timestamp to end replay at
	sessionId?: string; // Only replay events for specific session
	eventTypes?: string[]; // Only replay specific event types
	skipTimestamps?: boolean; // Skip timing delays and replay as fast as possible
}

export interface ReplayState {
	isReplaying: boolean;
	currentEventIndex: number;
	totalEvents: number;
	startTime: number;
	progress: number; // 0.0 to 1.0
	eventsReplayed: number;
	replayStartedAt: number;
}

/**
 * Event replay manager
 */
export class EventReplay {
	private persistence: EventPersistence;
	private isReplaying = false;
	private currentReplay?: {
		events: EventEnvelope[];
		options: ReplayOptions;
		startTime: number;
		abortController: AbortController;
		currentIndex: number;
	};

	// Event emitters for replayed events
	private serviceEventEmitter = new TypedEventEmitter<ServiceEventMap>();
	private sessionEventEmitter = new TypedEventEmitter<SessionEventMap>();

	constructor(persistence: EventPersistence) {
		this.persistence = persistence;
	}

	/**
	 * Start replaying events based on query and options
	 */
	async startReplay(query: EventQuery, options: ReplayOptions = {}): Promise<void> {
		if (this.isReplaying) {
			throw new Error('Replay is already in progress');
		}

		logger.info('Starting event replay', { query, options });

		try {
			// Fetch events to replay
			const events = await this.persistence.query(query);

			if (events.length === 0) {
				logger.warn('No events found for replay query', { query });
				return;
			}

			// Sort events by timestamp to ensure correct order
			events.sort((a, b) => a.metadata.timestamp - b.metadata.timestamp);

			// Set up replay state
			this.isReplaying = true;
			this.currentReplay = {
				events,
				options,
				startTime: Date.now(),
				abortController: new AbortController(),
				currentIndex: 0,
			};

			logger.info('Event replay started', {
				eventCount: events.length,
				timeRange: {
					start: events[0] ? new Date(events[0].metadata.timestamp).toISOString() : 'unknown',
					end: events[events.length - 1]
						? new Date(events[events.length - 1]!.metadata.timestamp).toISOString()
						: 'unknown',
				},
				options,
			});

			// Start the replay process
			await this.executeReplay();
		} catch (error) {
			this.isReplaying = false;
			this.currentReplay = undefined as unknown as {
				events: EventEnvelope<any>[];
				options: ReplayOptions;
				startTime: number;
				abortController: AbortController;
				currentIndex: number;
			};
			logger.error('Failed to start event replay', {
				error: error instanceof Error ? error.message : String(error),
			});
			throw error;
		}
	}

	/**
	 * Stop the current replay
	 */
	stopReplay(): void {
		if (!this.isReplaying || !this.currentReplay) {
			return;
		}

		logger.info('Stopping event replay');
		this.currentReplay.abortController.abort();
		this.isReplaying = false;
		this.currentReplay = undefined as unknown as {
			events: EventEnvelope<any>[];
			options: ReplayOptions;
			startTime: number;
			abortController: AbortController;
			currentIndex: number;
		};
	}

	/**
	 * Get current replay state
	 */
	getReplayState(): ReplayState | null {
		if (!this.isReplaying || !this.currentReplay) {
			return null;
		}

		const progress = this.currentReplay.currentIndex / this.currentReplay.events.length;

		return {
			isReplaying: this.isReplaying,
			currentEventIndex: this.currentReplay.currentIndex,
			totalEvents: this.currentReplay.events.length,
			startTime: this.currentReplay.startTime,
			progress,
			eventsReplayed: this.currentReplay.currentIndex,
			replayStartedAt: this.currentReplay.startTime,
		};
	}

	/**
	 * Subscribe to replayed service events
	 */
	onServiceEvent<K extends keyof ServiceEventMap>(
		event: K,
		listener: (data: ServiceEventMap[K]) => void,
		options?: { signal?: AbortSignal }
	): void {
		this.serviceEventEmitter.on(event, listener, options);
	}

	/**
	 * Subscribe to replayed session events
	 */
	onSessionEvent<K extends keyof SessionEventMap>(
		event: K,
		listener: (data: SessionEventMap[K]) => void,
		options?: { signal?: AbortSignal }
	): void {
		this.sessionEventEmitter.on(event, listener, options);
	}

	/**
	 * Wait for a specific replayed event
	 */
	async waitForReplayedEvent<K extends keyof ServiceEventMap>(
		event: K,
		options?: { timeout?: number; signal?: AbortSignal }
	): Promise<ServiceEventMap[K]> {
		return this.serviceEventEmitter.waitFor(event, options);
	}

	/**
	 * Get replay statistics
	 */
	getReplayStats(): {
		totalReplays: number;
		lastReplayDuration?: number;
		lastReplayEventCount?: number;
	} {
		// This could be enhanced to track replay history
		const result: {
			totalReplays: number;
			lastReplayDuration?: number;
			lastReplayEventCount?: number;
		} = {
			totalReplays: 0, // Would track in persistent state
		};

		if (this.currentReplay) {
			result.lastReplayDuration = Date.now() - this.currentReplay.startTime;
			result.lastReplayEventCount = this.currentReplay.events.length;
		}

		return result;
	}

	private async executeReplay(): Promise<void> {
		const replay = this.currentReplay!;
		const { events, options, abortController } = replay;

		try {
			let lastEventTime = events[0]?.metadata.timestamp || Date.now();

			for (let i = 0; i < events.length; i++) {
				// Check if replay was aborted
				if (abortController.signal.aborted) {
					logger.info('Event replay was aborted');
					break;
				}

				const event = events[i];
				replay.currentIndex = i;

				// Calculate delay if not skipping timestamps
				if (!options.skipTimestamps && i > 0) {
					const realTimeDelta =
						event?.metadata.timestamp !== undefined ? event.metadata.timestamp - lastEventTime : 0;
					const speed = options.speed || 1.0;
					const adjustedDelay = realTimeDelta / speed;

					if (adjustedDelay > 0) {
						await this.sleep(adjustedDelay, abortController.signal);
					}
				}

				// Emit the replayed event
				if (event) {
					await this.emitReplayedEvent(event);
					lastEventTime = event.metadata.timestamp;
				}

				// Log progress occasionally
				if (i % 100 === 0 || i === events.length - 1) {
					const progress = (((i + 1) / events.length) * 100).toFixed(1);
					logger.debug(`Event replay progress: ${progress}% (${i + 1}/${events.length})`);
				}
			}

			if (!abortController.signal.aborted) {
				logger.info('Event replay completed successfully', {
					eventsReplayed: events.length,
					duration: Date.now() - replay.startTime,
				});
			}
		} catch (error) {
			logger.error('Error during event replay', {
				error: error instanceof Error ? error.message : String(error),
				currentIndex: replay.currentIndex,
			});
			throw error;
		} finally {
			this.isReplaying = false;
			this.currentReplay = undefined as unknown as {
				events: EventEnvelope<any>[];
				options: ReplayOptions;
				startTime: number;
				abortController: AbortController;
				currentIndex: number;
			};
		}
	}

	private async emitReplayedEvent(event: EventEnvelope): Promise<void> {
		try {
			// Determine if this is a service or session event and emit accordingly
			if (this.isServiceEvent(event.type)) {
				this.serviceEventEmitter.emit(event.type as keyof ServiceEventMap, event.data);
			} else if (this.isSessionEvent(event.type)) {
				this.sessionEventEmitter.emit(event.type as keyof SessionEventMap, event.data);
			}

			logger.silly('Replayed event', {
				type: event.type,
				id: event.id,
				originalTimestamp: new Date(event.metadata.timestamp).toISOString(),
			});
		} catch (error) {
			logger.warn('Failed to emit replayed event', {
				eventType: event.type,
				eventId: event.id,
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}

	private isServiceEvent(eventType: string): boolean {
		// Service events typically start with 'cipher:' prefix
		return eventType.startsWith('cipher:');
	}

	private isSessionEvent(eventType: string): boolean {
		// Session events have various prefixes: session:, tool:, llm:, memory:, conversation:, context:
		return !this.isServiceEvent(eventType);
	}

	private async sleep(ms: number, signal?: AbortSignal): Promise<void> {
		return new Promise((resolve, reject) => {
			if (signal?.aborted) {
				reject(new Error('Sleep aborted'));
				return;
			}

			const timeout = setTimeout(resolve, ms);

			signal?.addEventListener('abort', () => {
				clearTimeout(timeout);
				reject(new Error('Sleep aborted'));
			});
		});
	}
}

/**
 * Event replay analyzer for extracting insights from replayed events
 */
export class ReplayAnalyzer {
	private events: EventEnvelope[] = [];
	private analysis: any = null;

	/**
	 * Add events for analysis
	 */
	addEvents(events: EventEnvelope[]): void {
		this.events.push(...events);
		this.analysis = null; // Reset analysis cache
	}

	/**
	 * Analyze the events and generate insights
	 */
	analyze(): {
		summary: {
			totalEvents: number;
			timeSpan: { start: string; end: string; duration: number };
			eventTypes: Record<string, number>;
			sessionsInvolved: string[];
		};
		patterns: {
			mostActiveSession?: string;
			commonEventSequences: Array<{ sequence: string[]; count: number }>;
			averageEventRate: number; // events per second
		};
		performance: {
			slowestOperations: Array<{ type: string; duration: number; timestamp: string }>;
			errorEvents: Array<{ type: string; error: string; timestamp: string }>;
		};
	} {
		if (this.analysis) {
			return this.analysis;
		}

		if (this.events.length === 0) {
			throw new Error('No events to analyze');
		}

		// Sort events by timestamp
		const sortedEvents = [...this.events].sort(
			(a, b) => a.metadata.timestamp - b.metadata.timestamp
		);

		// Calculate summary
		const eventTypes: Record<string, number> = {};
		const sessionsInvolved = new Set<string>();

		for (const event of sortedEvents) {
			eventTypes[event.type] = (eventTypes[event.type] || 0) + 1;
			if (event.metadata.sessionId) {
				sessionsInvolved.add(event.metadata.sessionId);
			}
		}

		const timeSpan = {
			start: new Date(
				sortedEvents[0]?.metadata.timestamp ? sortedEvents[0].metadata.timestamp : Date.now()
			).toISOString(),
			end: new Date(
				sortedEvents[sortedEvents.length - 1]?.metadata.timestamp
					? sortedEvents[sortedEvents.length - 1]!.metadata.timestamp
					: Date.now()
			).toISOString(),
			duration:
				sortedEvents[sortedEvents.length - 1] && sortedEvents[0]
					? sortedEvents[sortedEvents.length - 1]!.metadata.timestamp -
						sortedEvents[0]!.metadata.timestamp
					: 0,
		};

		// Analyze patterns
		const sessionEventCounts: Record<string, number> = {};
		const slowOperations: Array<{ type: string; duration: number; timestamp: string }> = [];
		const errorEvents: Array<{ type: string; error: string; timestamp: string }> = [];

		for (const event of sortedEvents) {
			if (event.metadata.sessionId) {
				sessionEventCounts[event.metadata.sessionId] =
					(sessionEventCounts[event.metadata.sessionId] || 0) + 1;
			}

			// Check for slow operations (those with duration > 1000ms)
			if (event.data && typeof event.data === 'object' && 'duration' in event.data) {
				const duration = event.data.duration as number;
				if (duration > 1000) {
					slowOperations.push({
						type: event.type,
						duration,
						timestamp: new Date(event.metadata.timestamp).toISOString(),
					});
				}
			}

			// Check for error events
			if (event.data && typeof event.data === 'object' && 'error' in event.data) {
				errorEvents.push({
					type: event.type,
					error: event.data.error as string,
					timestamp: new Date(event.metadata.timestamp).toISOString(),
				});
			}
		}

		const mostActiveSession = Object.entries(sessionEventCounts).sort(
			([, a], [, b]) => b - a
		)[0]?.[0];

		const averageEventRate = sortedEvents.length / (timeSpan.duration / 1000);

		this.analysis = {
			summary: {
				totalEvents: sortedEvents.length,
				timeSpan,
				eventTypes,
				sessionsInvolved: Array.from(sessionsInvolved),
			},
			patterns: {
				mostActiveSession,
				commonEventSequences: [], // Could implement sequence detection
				averageEventRate,
			},
			performance: {
				slowestOperations: slowOperations.sort((a, b) => b.duration - a.duration).slice(0, 10),
				errorEvents,
			},
		};

		return this.analysis;
	}

	/**
	 * Generate a human-readable report
	 */
	generateReport(): string {
		const analysis = this.analyze();

		let report = `# Event Replay Analysis Report\n\n`;

		report += `## Summary\n`;
		report += `- **Total Events**: ${analysis.summary.totalEvents}\n`;
		report += `- **Time Span**: ${analysis.summary.timeSpan.start} to ${analysis.summary.timeSpan.end}\n`;
		report += `- **Duration**: ${(analysis.summary.timeSpan.duration / 1000).toFixed(2)} seconds\n`;
		report += `- **Sessions Involved**: ${analysis.summary.sessionsInvolved.length}\n`;
		report += `- **Average Event Rate**: ${analysis.patterns.averageEventRate.toFixed(2)} events/sec\n\n`;

		report += `## Event Types\n`;
		const sortedEventTypes = Object.entries(analysis.summary.eventTypes).sort(
			([, a], [, b]) => b - a
		);
		for (const [type, count] of sortedEventTypes) {
			report += `- **${type}**: ${count}\n`;
		}
		report += `\n`;

		if (analysis.patterns.mostActiveSession) {
			report += `## Most Active Session\n`;
			report += `- **Session ID**: ${analysis.patterns.mostActiveSession}\n\n`;
		}

		if (analysis.performance.slowestOperations.length > 0) {
			report += `## Slowest Operations\n`;
			for (const op of analysis.performance.slowestOperations.slice(0, 5)) {
				report += `- **${op.type}**: ${op.duration}ms at ${op.timestamp}\n`;
			}
			report += `\n`;
		}

		if (analysis.performance.errorEvents.length > 0) {
			report += `## Error Events\n`;
			for (const error of analysis.performance.errorEvents.slice(0, 5)) {
				report += `- **${error.type}**: ${error.error} at ${error.timestamp}\n`;
			}
			report += `\n`;
		}

		return report;
	}
}

import { TypedEventEmitter } from './typed-event-emitter.js';
import { ServiceEventMap, EventEnvelope, EventMetadata } from './event-types.js';
import { logger } from '../logger/logger.js';
import { v4 as uuidv4 } from 'uuid';
import { EventPersistence } from './persistence.js';

export interface ServiceEventBusOptions {
	enableLogging?: boolean;
	maxListeners?: number;
	enablePersistence?: boolean;
	eventPersistence?: EventPersistence;
}

export class ServiceEventBus extends TypedEventEmitter<ServiceEventMap> {
	private readonly instanceId: string;
	private readonly startTime: number;
	private eventHistory: EventEnvelope[] = [];
	private readonly enablePersistence: boolean;
	private readonly maxHistorySize = 10000;
	private readonly eventPersistence?: EventPersistence;

	constructor(options: ServiceEventBusOptions = {}) {
		super({
			maxListeners: options.maxListeners ?? 200,
			enableLogging: options.enableLogging ?? true,
		});

		this.instanceId = uuidv4();
		this.startTime = Date.now();
		this.enablePersistence = options.enablePersistence ?? false;
		this.eventPersistence = options.eventPersistence!;

		logger.debug('ServiceEventBus initialized', {
			instanceId: this.instanceId,
			maxListeners: options.maxListeners ?? 200,
			enablePersistence: this.enablePersistence,
		});
	}

	/**
	 * Emit a service event with metadata and optional persistence
	 */
	emitServiceEvent<K extends keyof ServiceEventMap>(
		event: K,
		data: ServiceEventMap[K],
		metadata: Partial<EventMetadata> = {}
	): void {
		const envelope: EventEnvelope<ServiceEventMap[K]> = {
			id: uuidv4(),
			type: event as string,
			data,
			metadata: {
				timestamp: Date.now(),
				source: 'service',
				priority: 'normal',
				...metadata,
			},
		};

		// Store in history if persistence is enabled
		if (this.enablePersistence) {
			this.addToHistory(envelope);
		}

		// Persist event if eventPersistence is provided
		if (this.eventPersistence) {
			void this.eventPersistence.store(envelope);
		}

		// Emit the event
		this.emit(event, data);

		// Log high priority events
		if (envelope.metadata.priority === 'high') {
			logger.info('High priority service event emitted', {
				eventType: event,
				eventId: envelope.id,
				instanceId: this.instanceId,
			});
		}
	}

	/**
	 * Get event history (if persistence is enabled)
	 */
	getEventHistory(filter?: {
		eventType?: keyof ServiceEventMap;
		since?: number;
		limit?: number;
	}): EventEnvelope[] {
		if (!this.enablePersistence) {
			return [];
		}

		let history = this.eventHistory;

		if (filter) {
			if (filter.eventType) {
				history = history.filter(event => event.type === filter.eventType);
			}

			if (filter.since) {
				history = history.filter(event => event.metadata.timestamp >= filter.since!);
			}

			if (filter.limit) {
				history = history.slice(-filter.limit);
			}
		}

		return history;
	}

	/**
	 * Get service event bus statistics
	 */
	getStatistics(): {
		instanceId: string;
		uptime: number;
		totalEvents: number;
		eventTypes: Record<string, number>;
		activeListeners: Record<string, number>;
	} {
		const eventTypes: Record<string, number> = {};
		const activeListeners: Record<string, number> = {};

		// Count events by type
		this.eventHistory.forEach(event => {
			eventTypes[event.type] = (eventTypes[event.type] || 0) + 1;
		});

		// Count active listeners by event type
		this.eventNames().forEach(eventName => {
			activeListeners[eventName as string] = this.listenerCountFor(eventName);
		});

		return {
			instanceId: this.instanceId,
			uptime: Date.now() - this.startTime,
			totalEvents: this.eventHistory.length,
			eventTypes,
			activeListeners,
		};
	}

	/**
	 * Clear event history
	 */
	clearHistory(): void {
		this.eventHistory = [];
		logger.info('Service event history cleared', {
			instanceId: this.instanceId,
		});
	}

	/**
	 * Dispose of the service event bus
	 */
	public override dispose(): void {
		this.clearHistory();
		super.dispose();
		logger.info('ServiceEventBus disposed', {
			instanceId: this.instanceId,
		});
	}

	/**
	 * Add event to history with size management
	 */
	private addToHistory(envelope: EventEnvelope): void {
		this.eventHistory.push(envelope);

		// Maintain maximum history size
		if (this.eventHistory.length > this.maxHistorySize) {
			this.eventHistory = this.eventHistory.slice(-this.maxHistorySize);
		}
	}

	/**
	 * Get instance ID
	 */
	getInstanceId(): string {
		return this.instanceId;
	}

	/**
	 * Get uptime in milliseconds
	 */
	getUptime(): number {
		return Date.now() - this.startTime;
	}
}

import { TypedEventEmitter } from './typed-event-emitter.js';
import { SessionEventMap, EventEnvelope, EventMetadata } from './event-types.js';
import { logger } from '../logger/logger.js';
import { v4 as uuidv4 } from 'uuid';
import { EventPersistence } from './persistence.js';

export interface SessionEventBusOptions {
	sessionId: string;
	enableLogging?: boolean;
	maxListeners?: number;
	enablePersistence?: boolean;
	maxHistorySize?: number;
	eventPersistence?: EventPersistence;
}

export class SessionEventBus extends TypedEventEmitter<SessionEventMap> {
	private readonly sessionId: string;
	private readonly createdAt: number;
	private eventHistory: EventEnvelope[] = [];
	private readonly enablePersistence: boolean;
	private readonly maxHistorySize: number;
	private readonly eventPersistence?: EventPersistence;
	private isDisposed = false;

	constructor(options: SessionEventBusOptions) {
		super({
			maxListeners: options.maxListeners ?? 100,
			enableLogging: options.enableLogging ?? true,
		});

		this.sessionId = options.sessionId;
		this.createdAt = Date.now();
		this.enablePersistence = options.enablePersistence ?? false;
		this.maxHistorySize = options.maxHistorySize ?? 1000;
		this.eventPersistence = options.eventPersistence!;

		logger.debug('SessionEventBus initialized', {
			sessionId: this.sessionId,
			maxListeners: options.maxListeners ?? 100,
			enablePersistence: this.enablePersistence,
		});
	}

	/**
	 * Emit a session event with metadata and optional persistence
	 */
	emitSessionEvent<K extends keyof SessionEventMap>(
		event: K,
		data: SessionEventMap[K],
		metadata: Partial<EventMetadata> = {}
	): void {
		if (this.isDisposed) {
			logger.warn('Attempted to emit event on disposed SessionEventBus', {
				sessionId: this.sessionId,
				eventType: event,
			});
			return;
		}

		const envelope: EventEnvelope<SessionEventMap[K]> = {
			id: uuidv4(),
			type: event as string,
			data,
			metadata: {
				timestamp: Date.now(),
				sessionId: this.sessionId,
				source: 'session',
				priority: 'normal',
				...metadata,
			},
		};

		// Store in history if persistence is enabled
		if (this.enablePersistence) {
			this.addToHistory(envelope);
		}

		// Persist event if eventPersistence is provided
		if (this.eventPersistence) {
			void this.eventPersistence.store(envelope);
		}

		// Emit the event
		this.emit(event, data);

		// Log important session events
		if (this.shouldLogEvent(event)) {
			logger.info('Session event emitted', {
				sessionId: this.sessionId,
				eventType: event,
				eventId: envelope.id,
			});
		}
	}

	/**
	 * Get session event history (if persistence is enabled)
	 */
	getEventHistory(filter?: {
		eventType?: keyof SessionEventMap;
		since?: number;
		limit?: number;
	}): EventEnvelope[] {
		if (!this.enablePersistence) {
			return [];
		}

		let history = this.eventHistory;

		if (filter) {
			if (filter.eventType) {
				history = history.filter(event => event.type === filter.eventType);
			}

			if (filter.since) {
				history = history.filter(event => event.metadata.timestamp >= filter.since!);
			}

			if (filter.limit) {
				history = history.slice(-filter.limit);
			}
		}

		return history;
	}

	/**
	 * Get session event bus statistics
	 */
	getStatistics(): {
		sessionId: string;
		age: number;
		totalEvents: number;
		eventTypes: Record<string, number>;
		activeListeners: Record<string, number>;
		recentActivity: {
			lastEventTime?: number;
			eventsInLastMinute: number;
			eventsInLastHour: number;
		};
	} {
		const eventTypes: Record<string, number> = {};
		const activeListeners: Record<string, number> = {};
		const now = Date.now();
		const oneMinuteAgo = now - 60000;
		const oneHourAgo = now - 3600000;

		// Count events by type
		this.eventHistory.forEach(event => {
			eventTypes[event.type] = (eventTypes[event.type] || 0) + 1;
		});

		// Count active listeners by event type
		this.eventNames().forEach(eventName => {
			activeListeners[eventName as string] = this.listenerCountFor(eventName);
		});

		// Calculate recent activity
		const recentEvents = this.eventHistory.filter(event => event.metadata.timestamp >= oneHourAgo);
		const eventsInLastMinute = recentEvents.filter(
			event => event.metadata.timestamp >= oneMinuteAgo
		).length;
		const eventsInLastHour = recentEvents.length;
		const lastEvent =
			this.eventHistory.length > 0 ? this.eventHistory[this.eventHistory.length - 1] : undefined;
		const lastEventTime = lastEvent ? lastEvent.metadata.timestamp : undefined;

		return {
			sessionId: this.sessionId,
			age: now - this.createdAt,
			totalEvents: this.eventHistory.length,
			eventTypes,
			activeListeners,
			recentActivity: {
				...(lastEventTime !== undefined ? { lastEventTime } : {}),
				eventsInLastMinute,
				eventsInLastHour,
			},
		};
	}

	/**
	 * Clear event history
	 */
	clearHistory(): void {
		this.eventHistory = [];
		logger.debug('Session event history cleared', {
			sessionId: this.sessionId,
		});
	}

	/**
	 * Get session ID
	 */
	getSessionId(): string {
		return this.sessionId;
	}

	/**
	 * Get session age in milliseconds
	 */
	getAge(): number {
		return Date.now() - this.createdAt;
	}

	/**
	 * Check if session event bus is disposed
	 */
	isSessionDisposed(): boolean {
		return this.isDisposed;
	}

	/**
	 * Dispose of the session event bus
	 */
	public override dispose(): void {
		if (this.isDisposed) {
			return;
		}

		this.isDisposed = true;
		this.clearHistory();
		super.dispose();

		logger.debug('SessionEventBus disposed', {
			sessionId: this.sessionId,
			age: this.getAge(),
		});
	}

	/**
	 * Add event to history with size management
	 */
	private addToHistory(envelope: EventEnvelope): void {
		this.eventHistory.push(envelope);

		// Maintain maximum history size
		if (this.eventHistory.length > this.maxHistorySize) {
			this.eventHistory = this.eventHistory.slice(-this.maxHistorySize);
		}
	}

	/**
	 * Determine if an event should be logged based on its importance
	 */
	private shouldLogEvent(event: keyof SessionEventMap): boolean {
		const importantEvents = [
			'session:created',
			'session:expired',
			'session:deleted',
			'tool:executionFailed',
			'llm:responseError',
		];

		return importantEvents.includes(event as string);
	}

	/**
	 * Get events matching a pattern
	 */
	getEventsByPattern(pattern: RegExp): EventEnvelope[] {
		if (!this.enablePersistence) {
			return [];
		}

		return this.eventHistory.filter(event => pattern.test(event.type));
	}

	/**
	 * Get the most recent event of a specific type
	 */
	getLastEvent<K extends keyof SessionEventMap>(
		eventType: K
	): EventEnvelope<SessionEventMap[K]> | undefined {
		if (!this.enablePersistence) {
			return undefined;
		}

		const events = this.eventHistory.filter(event => event.type === eventType);
		return events.length > 0
			? (events[events.length - 1] as EventEnvelope<SessionEventMap[K]>)
			: undefined;
	}

	/**
	 * Count events of a specific type
	 */
	countEvents<K extends keyof SessionEventMap>(eventType: K): number {
		if (!this.enablePersistence) {
			return 0;
		}

		return this.eventHistory.filter(event => event.type === eventType).length;
	}
}

import EventEmitter from 'events';
import { logger } from '../logger/logger.js';

export type EventListener<T> = (event: T) => void | Promise<void>;
export type EventListenerOptions = {
	signal?: AbortSignal;
	once?: boolean;
	priority?: 'high' | 'normal' | 'low';
};

export class TypedEventEmitter<EventMap extends Record<string, any>> {
	private emitter = new EventEmitter();
	private readonly maxListeners: number;
	private readonly enableLogging: boolean;
	private listenerCount = new Map<string, number>();

	constructor(options: { maxListeners?: number; enableLogging?: boolean } = {}) {
		this.maxListeners = options.maxListeners ?? 100;
		this.enableLogging = options.enableLogging ?? false;
		this.emitter.setMaxListeners(this.maxListeners);
	}

	/**
	 * Emit an event with type safety
	 */
	emit<K extends keyof EventMap>(event: K, data: EventMap[K]): void {
		if (this.enableLogging) {
			logger.debug('Event emitted', { event: event as string, data });
		}

		// Emit with error handling for async listeners
		this.emitter.emit(event as string, data);
	}

	/**
	 * Add a typed event listener with AbortController support
	 */
	on<K extends keyof EventMap>(
		event: K,
		listener: EventListener<EventMap[K]>,
		options: EventListenerOptions = {}
	): void {
		const wrappedListener = this.wrapListener(listener, event as string, options);

		if (options.once) {
			this.emitter.once(event as string, wrappedListener);
		} else {
			this.emitter.on(event as string, wrappedListener);
		}

		// Track listener count
		const currentCount = this.listenerCount.get(event as string) || 0;
		this.listenerCount.set(event as string, currentCount + 1);

		// Handle AbortController
		if (options.signal) {
			options.signal.addEventListener('abort', () => {
				this.off(event, listener);
			});
		}
	}

	/**
	 * Add a one-time event listener
	 */
	once<K extends keyof EventMap>(
		event: K,
		listener: EventListener<EventMap[K]>,
		options: Omit<EventListenerOptions, 'once'> = {}
	): void {
		this.on(event, listener, { ...options, once: true });
	}

	/**
	 * Remove an event listener
	 */
	off<K extends keyof EventMap>(event: K, listener: EventListener<EventMap[K]>): void {
		this.emitter.off(event as string, listener as any);

		// Update listener count
		const currentCount = this.listenerCount.get(event as string) || 0;
		if (currentCount > 0) {
			this.listenerCount.set(event as string, currentCount - 1);
		}
	}

	/**
	 * Remove all listeners for an event
	 */
	removeAllListeners<K extends keyof EventMap>(event?: K): void {
		if (event) {
			this.emitter.removeAllListeners(event as string);
			this.listenerCount.set(event as string, 0);
		} else {
			this.emitter.removeAllListeners();
			this.listenerCount.clear();
		}
	}

	/**
	 * Get the number of listeners for an event
	 */
	listenerCountFor<K extends keyof EventMap>(event: K): number {
		return this.listenerCount.get(event as string) || 0;
	}

	/**
	 * Get all event names that have listeners
	 */
	eventNames(): (keyof EventMap)[] {
		return this.emitter.eventNames() as (keyof EventMap)[];
	}

	/**
	 * Wait for a specific event to be emitted
	 */
	waitFor<K extends keyof EventMap>(
		event: K,
		options: { timeout?: number; signal?: AbortSignal } = {}
	): Promise<EventMap[K]> {
		return new Promise((resolve, reject) => {
			const timeoutMs = options.timeout ?? 30000; // 30 second default
			let timeoutId: NodeJS.Timeout | undefined;

			const cleanup = () => {
				if (timeoutId) {
					clearTimeout(timeoutId);
				}
			};

			const listener = (data: EventMap[K]) => {
				cleanup();
				resolve(data);
			};

			// Set up timeout
			if (timeoutMs > 0) {
				timeoutId = setTimeout(() => {
					this.off(event, listener);
					reject(new Error(`Event '${event as string}' timeout after ${timeoutMs}ms`));
				}, timeoutMs);
			}

			// Handle AbortController
			if (options.signal) {
				options.signal.addEventListener('abort', () => {
					cleanup();
					this.off(event, listener);
					reject(new Error('Event wait aborted'));
				});
			}

			this.once(event, listener);
		});
	}

	/**
	 * Dispose of the event emitter and clean up resources
	 */
	dispose(): void {
		this.removeAllListeners();
		this.emitter.removeAllListeners();
	}

	/**
	 * Wrap listener with error handling and async support
	 */
	private wrapListener<K extends keyof EventMap>(
		listener: EventListener<EventMap[K]>,
		event: string,
		_options: EventListenerOptions
	): (data: EventMap[K]) => void {
		return (data: EventMap[K]) => {
			try {
				const result = listener(data);

				// Handle async listeners
				if (result instanceof Promise) {
					result.catch(error => {
						logger.error('Error in async event listener', {
							event,
							error: error.message,
							stack: error.stack,
						});
					});
				}
			} catch (error) {
				logger.error('Error in event listener', {
					event,
					error: error instanceof Error ? error.message : String(error),
					stack: error instanceof Error ? error.stack : undefined,
				});
			}
		};
	}
}

/**
 * Webhook Forwarding System
 *
 * Forwards events to external systems via HTTP webhooks for integrations and monitoring.
 */

import { EventEnvelope, EventFilter } from './event-types.js';
import { logger } from '../logger/logger.js';

// Import fetch and Response for Node.js compatibility
import { fetch, Response } from 'undici';

export interface WebhookConfig {
	url: string;
	method?: 'POST' | 'PUT' | 'PATCH';
	headers?: Record<string, string>;
	timeout?: number;
	retries?: number;
	retryDelay?: number;
	secret?: string;
	filters?: EventFilter[];
	enabled?: boolean;
	batchSize?: number;
	batchTimeout?: number;
}

export interface WebhookDelivery {
	id: string;
	webhookId: string;
	event: EventEnvelope;
	url: string;
	status: 'pending' | 'delivered' | 'failed' | 'retrying';
	attempts: number;
	createdAt: number;
	lastAttemptAt?: number;
	deliveredAt?: number;
	error?: string;
}

export interface WebhookStats {
	totalEvents: number;
	deliveredEvents: number;
	failedEvents: number;
	pendingEvents: number;
	averageDeliveryTime: number;
	errorRate: number;
}

/**
 * Webhook delivery manager
 */
export class WebhookForwarder {
	private webhooks = new Map<string, WebhookConfig>();
	private deliveryQueue: WebhookDelivery[] = [];
	private deliveryHistory: WebhookDelivery[] = [];
	private processingInterval?: NodeJS.Timeout;
	private batchQueues = new Map<string, EventEnvelope[]>();
	private batchTimeouts = new Map<string, NodeJS.Timeout>();
	private stats = new Map<string, WebhookStats>();

	constructor() {
		// Start processing queue
		this.processingInterval = setInterval(() => {
			this.processDeliveryQueue();
		}, 1000);
	}

	/**
	 * Register a webhook endpoint
	 */
	registerWebhook(id: string, config: WebhookConfig): void {
		const fullConfig: Required<WebhookConfig> = {
			method: 'POST',
			headers: { 'Content-Type': 'application/json' },
			timeout: 5000,
			retries: 3,
			retryDelay: 1000,
			secret: '',
			filters: [],
			enabled: true,
			batchSize: 1,
			batchTimeout: 1000,
			...config,
		};

		this.webhooks.set(id, fullConfig);
		this.stats.set(id, this.createWebhookStats());

		logger.info('Webhook registered', {
			webhookId: id,
			url: config.url,
			enabled: fullConfig.enabled,
		});
	}

	/**
	 * Unregister a webhook endpoint
	 */
	unregisterWebhook(id: string): void {
		this.webhooks.delete(id);
		this.stats.delete(id);

		// Clear any pending batches
		const timeout = this.batchTimeouts.get(id);
		if (timeout) {
			clearTimeout(timeout);
			this.batchTimeouts.delete(id);
		}
		this.batchQueues.delete(id);

		logger.info('Webhook unregistered', { webhookId: id });
	}

	/**
	 * Forward an event to registered webhooks
	 */
	async forwardEvent(event: EventEnvelope): Promise<void> {
		for (const [webhookId, config] of this.webhooks) {
			if (!config.enabled) continue;

			// Apply filters
			if (config.filters && config.filters.length > 0) {
				const passesFilters = config.filters.some(filter => filter(event));
				if (!passesFilters) continue;
			}

			// Handle batching
			if ((config.batchSize ?? 1) > 1) {
				await this.addToBatch(webhookId, event, config);
			} else {
				await this.queueDelivery(webhookId, event, config);
			}
		}
	}

	/**
	 * Get webhook statistics
	 */
	getWebhookStats(webhookId?: string): WebhookStats | Record<string, WebhookStats> {
		if (webhookId) {
			return this.stats.get(webhookId) || this.createWebhookStats();
		}

		const allStats: Record<string, WebhookStats> = {};
		for (const [id, stats] of this.stats) {
			allStats[id] = { ...stats };
		}
		return allStats;
	}

	/**
	 * Get delivery history
	 */
	getDeliveryHistory(webhookId?: string, limit = 100): WebhookDelivery[] {
		let history = this.deliveryHistory;

		if (webhookId) {
			history = history.filter(d => d.webhookId === webhookId);
		}

		return history.sort((a, b) => b.createdAt - a.createdAt).slice(0, limit);
	}

	/**
	 * Retry failed deliveries
	 */
	async retryFailedDeliveries(webhookId?: string): Promise<number> {
		const failedDeliveries = this.deliveryHistory.filter(
			d => d.status === 'failed' && (!webhookId || d.webhookId === webhookId)
		);

		for (const delivery of failedDeliveries) {
			delivery.status = 'pending';
			delivery.error = undefined as unknown as string;
			this.deliveryQueue.push(delivery);
		}

		logger.info('Retrying failed deliveries', {
			count: failedDeliveries.length,
			webhookId,
		});

		return failedDeliveries.length;
	}

	/**
	 * Update webhook configuration
	 */
	updateWebhook(id: string, updates: Partial<WebhookConfig>): void {
		const existing = this.webhooks.get(id);
		if (!existing) {
			throw new Error(`Webhook ${id} not found`);
		}

		const updated = { ...existing, ...updates };
		this.webhooks.set(id, updated);

		logger.info('Webhook configuration updated', {
			webhookId: id,
			updates: Object.keys(updates),
		});
	}

	/**
	 * Test webhook connectivity
	 */
	async testWebhook(id: string): Promise<{ success: boolean; latency: number; error?: string }> {
		const config = this.webhooks.get(id);
		if (!config) {
			throw new Error(`Webhook ${id} not found`);
		}

		const testEvent: EventEnvelope = {
			id: `test-${Date.now()}`,
			type: 'cipher:test',
			data: { message: 'Webhook connectivity test', timestamp: Date.now() },
			metadata: { timestamp: Date.now(), source: 'webhook-test' },
		};

		const startTime = Date.now();
		try {
			const response = await this.deliverEvent(config, testEvent);
			const latency = Date.now() - startTime;

			return {
				success: response.ok,
				latency,
				...(response.ok ? {} : { error: `HTTP ${response.status}: ${response.statusText}` }),
			};
		} catch (error) {
			const latency = Date.now() - startTime;
			return {
				success: false,
				latency,
				error: error instanceof Error ? error.message : String(error),
			};
		}
	}

	/**
	 * Dispose of the webhook forwarder
	 */
	dispose(): void {
		if (this.processingInterval) {
			clearInterval(this.processingInterval);
		}

		// Clear all batch timeouts
		for (const timeout of this.batchTimeouts.values()) {
			clearTimeout(timeout);
		}
		this.batchTimeouts.clear();
		this.batchQueues.clear();

		logger.info('Webhook forwarder disposed');
	}

	private async addToBatch(
		webhookId: string,
		event: EventEnvelope,
		config: WebhookConfig
	): Promise<void> {
		if (!this.batchQueues.has(webhookId)) {
			this.batchQueues.set(webhookId, []);
		}

		const batch = this.batchQueues.get(webhookId)!;
		batch.push(event);

		// Check if batch is full
		if (batch.length >= (config.batchSize || 1)) {
			await this.flushBatch(webhookId, config);
			return;
		}

		// Set timeout for batch if not already set
		if (!this.batchTimeouts.has(webhookId)) {
			const timeout = setTimeout(() => {
				this.flushBatch(webhookId, config);
			}, config.batchTimeout);
			this.batchTimeouts.set(webhookId, timeout);
		}
	}

	private async flushBatch(webhookId: string, config: WebhookConfig): Promise<void> {
		const batch = this.batchQueues.get(webhookId);
		if (!batch || batch.length === 0) return;

		// Clear timeout
		const timeout = this.batchTimeouts.get(webhookId);
		if (timeout) {
			clearTimeout(timeout);
			this.batchTimeouts.delete(webhookId);
		}

		// Create batch event
		const batchEvent: EventEnvelope = {
			id: `batch-${Date.now()}`,
			type: 'cipher:batch',
			data: { events: batch, count: batch.length },
			metadata: { timestamp: Date.now(), source: 'batch' },
		};

		await this.queueDelivery(webhookId, batchEvent, config);

		// Clear batch
		this.batchQueues.set(webhookId, []);
	}

	private async queueDelivery(
		webhookId: string,
		event: EventEnvelope,
		config: WebhookConfig
	): Promise<void> {
		const delivery: WebhookDelivery = {
			id: `delivery-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
			webhookId,
			event,
			url: config.url,
			status: 'pending',
			attempts: 0,
			createdAt: Date.now(),
		};

		this.deliveryQueue.push(delivery);
		this.updateStats(webhookId, stats => stats.totalEvents++);
	}

	private async processDeliveryQueue(): Promise<void> {
		const pendingDeliveries = this.deliveryQueue.filter(d => d.status === 'pending');

		for (const delivery of pendingDeliveries.slice(0, 10)) {
			// Process max 10 at a time
			await this.processDelivery(delivery);
		}

		// Clean up old completed deliveries
		this.deliveryQueue = this.deliveryQueue.filter(
			d => d.status === 'pending' || d.status === 'retrying'
		);
	}

	private async processDelivery(delivery: WebhookDelivery): Promise<void> {
		const config = this.webhooks.get(delivery.webhookId);
		if (!config || !config.enabled) {
			delivery.status = 'failed';
			delivery.error = 'Webhook disabled or not found';
			this.moveToHistory(delivery);
			return;
		}

		delivery.attempts++;
		delivery.lastAttemptAt = Date.now();
		delivery.status = 'retrying';

		try {
			const response = await this.deliverEvent(config, delivery.event);

			if (response.ok) {
				delivery.status = 'delivered';
				delivery.deliveredAt = Date.now();
				this.updateStats(delivery.webhookId, stats => {
					stats.deliveredEvents++;
					if (delivery.deliveredAt && delivery.createdAt) {
						const deliveryTime = delivery.deliveredAt - delivery.createdAt;
						stats.averageDeliveryTime = (stats.averageDeliveryTime + deliveryTime) / 2;
					}
				});
			} else {
				throw new Error(`HTTP ${response.status}: ${response.statusText}`);
			}
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);

			if ((delivery.attempts ?? 0) >= (config.retries ?? 0)) {
				delivery.status = 'failed';
				delivery.error = errorMessage;
				this.updateStats(delivery.webhookId, stats => {
					stats.failedEvents++;
					stats.errorRate = stats.failedEvents / stats.totalEvents;
				});
			} else {
				delivery.status = 'pending';
				// Add delay before retry
				setTimeout(
					() => {
						delivery.status = 'pending';
					},
					(config.retryDelay ?? 0) * delivery.attempts
				);
			}

			logger.warn('Webhook delivery failed', {
				deliveryId: delivery.id,
				webhookId: delivery.webhookId,
				attempt: delivery.attempts,
				error: errorMessage,
			});
		}

		if (delivery.status === 'delivered' || delivery.status === 'failed') {
			this.moveToHistory(delivery);
		}
	}

	private async deliverEvent(config: WebhookConfig, event: EventEnvelope): Promise<Response> {
		const body = JSON.stringify(event);
		const headers = { ...config.headers };

		// Add signature if secret is provided
		if (config.secret) {
			const crypto = await import('crypto');
			const signature = crypto.createHmac('sha256', config.secret).update(body).digest('hex');
			headers['X-Webhook-Signature'] = `sha256=${signature}`;
		}

		return fetch(config.url, {
			method: config.method || 'POST',
			headers,
			body,
			signal: AbortSignal.timeout(config.timeout || 30000),
		});
	}

	private moveToHistory(delivery: WebhookDelivery): void {
		this.deliveryHistory.push(delivery);

		// Maintain history size (keep last 1000)
		if (this.deliveryHistory.length > 1000) {
			this.deliveryHistory = this.deliveryHistory.slice(-1000);
		}
	}

	private updateStats(webhookId: string, updater: (stats: WebhookStats) => void): void {
		const stats = this.stats.get(webhookId);
		if (stats) {
			updater(stats);
		}
	}

	private createWebhookStats(): WebhookStats {
		return {
			totalEvents: 0,
			deliveredEvents: 0,
			failedEvents: 0,
			pendingEvents: 0,
			averageDeliveryTime: 0,
			errorRate: 0,
		};
	}
}

/**
 * Webhook filter builders for common use cases
 */
export class WebhookFilters {
	/**
	 * Filter by event type
	 */
	static byEventType(...eventTypes: string[]): EventFilter {
		return (event: EventEnvelope) => eventTypes.includes(event.type);
	}

	/**
	 * Filter by session ID
	 */
	static bySessionId(sessionId: string): EventFilter {
		return (event: EventEnvelope) => event.metadata.sessionId === sessionId;
	}

	/**
	 * Filter by event source
	 */
	static bySource(source: string): EventFilter {
		return (event: EventEnvelope) => event.metadata.source === source;
	}

	/**
	 * Filter by priority
	 */
	static byPriority(priority: 'high' | 'normal' | 'low'): EventFilter {
		return (event: EventEnvelope) => event.metadata.priority === priority;
	}

	/**
	 * Filter by time range
	 */
	static byTimeRange(start: number, end: number): EventFilter {
		return (event: EventEnvelope) =>
			event.metadata.timestamp >= start && event.metadata.timestamp <= end;
	}

	/**
	 * Combine filters with AND logic
	 */
	static and(...filters: EventFilter[]): EventFilter {
		return (event: EventEnvelope) => filters.every(filter => filter(event));
	}

	/**
	 * Combine filters with OR logic
	 */
	static or(...filters: EventFilter[]): EventFilter {
		return (event: EventEnvelope) => filters.some(filter => filter(event));
	}

	/**
	 * Negate a filter
	 */
	static not(filter: EventFilter): EventFilter {
		return (event: EventEnvelope) => !filter(event);
	}
}

export * from './logger/index.js';
export * from './mcp/index.js';
export * from './brain/index.js';
export * from './utils/index.js';
