// Storage modules with namespace disambiguation
export * as Storage from './storage/index.js';
export * as VectorStorage from './vector_storage/index.js';
export * as KnowledgeGraph from './knowledge_graph/index.js';

/**
 * In-Memory Knowledge Graph Backend
 *
 * Fast local storage implementation for development, testing, and small datasets.
 * All data is stored in memory using Map structures with optional indexing for performance.
 *
 * @module knowledge_graph/backend/in-memory
 */

import { Logger, createLogger } from '../../logger/logger.js';
import type { KnowledgeGraph } from './knowledge-graph.js';
import type {
	GraphNode,
	GraphEdge,
	GraphQuery,
	GraphResult,
	NodeFilters,
	EdgeFilters,
} from './types.js';
import {
	KnowledgeGraphConnectionError,
	NodeNotFoundError,
	EdgeNotFoundError,
	InvalidQueryError,
	GraphValidationError,
} from './types.js';
import type { InMemoryBackendConfig } from '../config.js';
import { DEFAULTS, ERROR_MESSAGES, LOG_PREFIXES } from '../constants.js';

/**
 * In-memory storage entry for tracking metadata
 */
interface StorageEntry<T> {
	data: T;
	createdAt: number;
	updatedAt: number;
}

/**
 * Index structure for faster lookups
 */
interface Index {
	labels: Map<string, Set<string>>; // label -> set of node IDs
	edgeTypes: Map<string, Set<string>>; // edge type -> set of edge IDs
	properties: Map<string, Map<any, Set<string>>>; // property name -> value -> set of IDs
}

/**
 * In-Memory Knowledge Graph Backend
 *
 * Provides a fast, local implementation of the knowledge graph interface.
 * All data is stored in memory and lost when the process terminates.
 *
 * @example
 * ```typescript
 * const backend = new InMemoryBackend({
 *   type: 'in-memory',
 *   maxNodes: 10000,
 *   maxEdges: 50000,
 *   enableIndexing: true
 * });
 *
 * await backend.connect();
 * await backend.addNode({
 *   id: 'node1',
 *   labels: ['Function'],
 *   properties: { name: 'myFunction' }
 * });
 * ```
 */
export class InMemoryBackend implements KnowledgeGraph {
	private readonly config: InMemoryBackendConfig;
	private readonly logger: Logger;
	private connected = false;

	// Core storage
	private nodes = new Map<string, StorageEntry<GraphNode>>();
	private edges = new Map<string, StorageEntry<GraphEdge>>();

	// Adjacency lists for graph traversal
	private outgoingEdges = new Map<string, Set<string>>(); // node ID -> set of outgoing edge IDs
	private incomingEdges = new Map<string, Set<string>>(); // node ID -> set of incoming edge IDs

	// Indexes for performance
	private nodeIndex: Index = {
		labels: new Map(),
		edgeTypes: new Map(),
		properties: new Map(),
	};

	private edgeIndex: Index = {
		labels: new Map(),
		edgeTypes: new Map(),
		properties: new Map(),
	};

	// Statistics
	private stats = {
		nodeCount: 0,
		edgeCount: 0,
		operations: 0,
		queriesExecuted: 0,
		lastOperation: 0,
	};

	constructor(config: InMemoryBackendConfig) {
		this.config = {
			...config,
			maxNodes: config.maxNodes ?? DEFAULTS.MAX_NODES,
			maxEdges: config.maxEdges ?? DEFAULTS.MAX_EDGES,
			enableIndexing: config.enableIndexing ?? true,
			enableGarbageCollection: config.enableGarbageCollection ?? false,
		};

		this.logger = createLogger({
			level: 'debug',
		});

		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Initialized with config:`, {
			maxNodes: this.config.maxNodes,
			maxEdges: this.config.maxEdges,
			enableIndexing: this.config.enableIndexing,
			enableGarbageCollection: this.config.enableGarbageCollection,
		});
	}

	// Connection management

	async connect(): Promise<void> {
		if (this.connected) {
			this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Already connected`);
			return;
		}

		try {
			// Clear any existing data
			this.clear();

			this.connected = true;
			this.logger.info(`${LOG_PREFIXES.IN_MEMORY} Connected successfully`);
		} catch (error) {
			const connectionError = new KnowledgeGraphConnectionError(
				ERROR_MESSAGES.CONNECTION_FAILED,
				'in-memory',
				error as Error
			);
			this.logger.error(`${LOG_PREFIXES.IN_MEMORY} Connection failed:`, connectionError);
			throw connectionError;
		}
	}

	async disconnect(): Promise<void> {
		if (!this.connected) {
			this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Already disconnected`);
			return;
		}

		try {
			// Clear all data if garbage collection is enabled
			if (this.config.enableGarbageCollection) {
				this.clear();
			}

			this.connected = false;
			this.logger.info(`${LOG_PREFIXES.IN_MEMORY} Disconnected successfully`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.IN_MEMORY} Error during disconnect:`, error);
			throw error;
		}
	}

	isConnected(): boolean {
		return this.connected;
	}

	getBackendType(): string {
		return 'in-memory';
	}

	// Node operations

	async addNode(node: GraphNode): Promise<void> {
		this.ensureConnected();
		this.validateNode(node);

		if (this.nodes.has(node.id)) {
			throw new GraphValidationError(`Node with ID '${node.id}' already exists`, 'node');
		}

		if (this.stats.nodeCount >= this.config.maxNodes) {
			throw new GraphValidationError(
				`Maximum number of nodes (${this.config.maxNodes}) exceeded`,
				'node'
			);
		}

		const entry: StorageEntry<GraphNode> = {
			data: this.deepClone(node),
			createdAt: Date.now(),
			updatedAt: Date.now(),
		};

		this.nodes.set(node.id, entry);
		this.stats.nodeCount++;
		this.stats.operations++;
		this.stats.lastOperation = Date.now();

		// Update indexes
		if (this.config.enableIndexing) {
			this.updateNodeIndex(node.id, node, 'add');
		}

		// Initialize adjacency lists
		this.outgoingEdges.set(node.id, new Set());
		this.incomingEdges.set(node.id, new Set());

		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Added node:`, {
			id: node.id,
			labels: node.labels,
		});
	}

	async addNodes(nodes: GraphNode[]): Promise<void> {
		this.ensureConnected();

		if (this.stats.nodeCount + nodes.length > this.config.maxNodes) {
			throw new GraphValidationError(
				`Adding ${nodes.length} nodes would exceed maximum (${this.config.maxNodes})`,
				'node'
			);
		}

		// Validate all nodes first
		for (const node of nodes) {
			this.validateNode(node);
			if (this.nodes.has(node.id)) {
				throw new GraphValidationError(`Node with ID '${node.id}' already exists`, 'node');
			}
		}

		// Add all nodes
		for (const node of nodes) {
			await this.addNode(node);
		}

		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Added ${nodes.length} nodes`);
	}

	async getNode(nodeId: string): Promise<GraphNode | null> {
		this.ensureConnected();

		const entry = this.nodes.get(nodeId);
		if (!entry) {
			return null;
		}

		return this.deepClone(entry.data);
	}

	async updateNode(
		nodeId: string,
		properties: Record<string, any>,
		labels?: string[]
	): Promise<void> {
		this.ensureConnected();

		const entry = this.nodes.get(nodeId);
		if (!entry) {
			throw new NodeNotFoundError(ERROR_MESSAGES.NODE_NOT_FOUND, nodeId);
		}

		// Remove old indexes
		if (this.config.enableIndexing) {
			this.updateNodeIndex(nodeId, entry.data, 'remove');
		}

		// Update node data
		const updatedNode: GraphNode = {
			...entry.data,
			properties: { ...entry.data.properties, ...properties },
			labels: labels ?? entry.data.labels,
		};

		entry.data = updatedNode;
		entry.updatedAt = Date.now();
		this.stats.operations++;
		this.stats.lastOperation = Date.now();

		// Update indexes
		if (this.config.enableIndexing) {
			this.updateNodeIndex(nodeId, updatedNode, 'add');
		}

		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Updated node:`, { id: nodeId });
	}

	async deleteNode(nodeId: string): Promise<void> {
		this.ensureConnected();

		const entry = this.nodes.get(nodeId);
		if (!entry) {
			// Silently ignore if node doesn't exist
			return;
		}

		// Delete all edges connected to this node
		const outgoing = this.outgoingEdges.get(nodeId) || new Set();
		const incoming = this.incomingEdges.get(nodeId) || new Set();

		for (const edgeId of [...outgoing, ...incoming]) {
			await this.deleteEdge(edgeId);
		}

		// Remove from indexes
		if (this.config.enableIndexing) {
			this.updateNodeIndex(nodeId, entry.data, 'remove');
		}

		// Remove node
		this.nodes.delete(nodeId);
		this.outgoingEdges.delete(nodeId);
		this.incomingEdges.delete(nodeId);
		this.stats.nodeCount--;
		this.stats.operations++;
		this.stats.lastOperation = Date.now();

		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Deleted node:`, { id: nodeId });
	}

	async findNodes(filters?: NodeFilters, labels?: string[], limit?: number): Promise<GraphNode[]> {
		this.ensureConnected();

		const maxResults = limit ?? DEFAULTS.QUERY_LIMIT;
		const results: GraphNode[] = [];

		// Use index for label filtering if available
		let candidateIds = new Set<string>();
		if (labels && labels.length > 0 && this.config.enableIndexing) {
			for (const label of labels) {
				const labelIds = this.nodeIndex.labels.get(label) || new Set();
				if (candidateIds.size === 0) {
					candidateIds = new Set(labelIds);
				} else {
					candidateIds = new Set([...candidateIds].filter(id => labelIds.has(id)));
				}
			}
		} else {
			candidateIds = new Set(this.nodes.keys());
		}

		for (const nodeId of candidateIds) {
			if (results.length >= maxResults) break;

			const entry = this.nodes.get(nodeId);
			if (!entry) continue;

			const node = entry.data;

			// Check label filters
			if (labels && labels.length > 0) {
				if (!labels.some(label => node.labels.includes(label))) {
					continue;
				}
			}

			// Check property filters
			if (filters && !this.matchesNodeFilters(node, filters)) {
				continue;
			}

			results.push(this.deepClone(node));
		}

		this.stats.queriesExecuted++;
		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Found ${results.length} nodes`);

		return results;
	}

	// Edge operations

	async addEdge(edge: GraphEdge): Promise<void> {
		this.ensureConnected();
		this.validateEdge(edge);

		if (this.edges.has(edge.id)) {
			throw new GraphValidationError(`Edge with ID '${edge.id}' already exists`, 'edge');
		}

		if (this.stats.edgeCount >= this.config.maxEdges) {
			throw new GraphValidationError(
				`Maximum number of edges (${this.config.maxEdges}) exceeded`,
				'edge'
			);
		}

		// Check that start and end nodes exist
		if (!this.nodes.has(edge.startNodeId)) {
			throw new GraphValidationError(`Start node '${edge.startNodeId}' not found`, 'edge');
		}

		if (!this.nodes.has(edge.endNodeId)) {
			throw new GraphValidationError(`End node '${edge.endNodeId}' not found`, 'edge');
		}

		const entry: StorageEntry<GraphEdge> = {
			data: this.deepClone(edge),
			createdAt: Date.now(),
			updatedAt: Date.now(),
		};

		this.edges.set(edge.id, entry);
		this.stats.edgeCount++;
		this.stats.operations++;
		this.stats.lastOperation = Date.now();

		// Update adjacency lists
		this.outgoingEdges.get(edge.startNodeId)!.add(edge.id);
		this.incomingEdges.get(edge.endNodeId)!.add(edge.id);

		// Update indexes
		if (this.config.enableIndexing) {
			this.updateEdgeIndex(edge.id, edge, 'add');
		}

		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Added edge:`, {
			id: edge.id,
			type: edge.type,
			from: edge.startNodeId,
			to: edge.endNodeId,
		});
	}

	async addEdges(edges: GraphEdge[]): Promise<void> {
		this.ensureConnected();

		if (this.stats.edgeCount + edges.length > this.config.maxEdges) {
			throw new GraphValidationError(
				`Adding ${edges.length} edges would exceed maximum (${this.config.maxEdges})`,
				'edge'
			);
		}

		// Validate all edges first
		for (const edge of edges) {
			this.validateEdge(edge);
			if (this.edges.has(edge.id)) {
				throw new GraphValidationError(`Edge with ID '${edge.id}' already exists`, 'edge');
			}
		}

		// Add all edges
		for (const edge of edges) {
			await this.addEdge(edge);
		}

		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Added ${edges.length} edges`);
	}

	async getEdge(edgeId: string): Promise<GraphEdge | null> {
		this.ensureConnected();

		const entry = this.edges.get(edgeId);
		if (!entry) {
			return null;
		}

		return this.deepClone(entry.data);
	}

	async updateEdge(edgeId: string, properties: Record<string, any>): Promise<void> {
		this.ensureConnected();

		const entry = this.edges.get(edgeId);
		if (!entry) {
			throw new EdgeNotFoundError(ERROR_MESSAGES.EDGE_NOT_FOUND, edgeId);
		}

		// Remove old indexes
		if (this.config.enableIndexing) {
			this.updateEdgeIndex(edgeId, entry.data, 'remove');
		}

		// Update edge data
		const updatedEdge: GraphEdge = {
			...entry.data,
			properties: { ...entry.data.properties, ...properties },
		};

		entry.data = updatedEdge;
		entry.updatedAt = Date.now();
		this.stats.operations++;
		this.stats.lastOperation = Date.now();

		// Update indexes
		if (this.config.enableIndexing) {
			this.updateEdgeIndex(edgeId, updatedEdge, 'add');
		}

		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Updated edge:`, { id: edgeId });
	}

	async deleteEdge(edgeId: string): Promise<void> {
		this.ensureConnected();

		const entry = this.edges.get(edgeId);
		if (!entry) {
			// Silently ignore if edge doesn't exist
			return;
		}

		const edge = entry.data;

		// Remove from adjacency lists
		this.outgoingEdges.get(edge.startNodeId)?.delete(edgeId);
		this.incomingEdges.get(edge.endNodeId)?.delete(edgeId);

		// Remove from indexes
		if (this.config.enableIndexing) {
			this.updateEdgeIndex(edgeId, edge, 'remove');
		}

		// Remove edge
		this.edges.delete(edgeId);
		this.stats.edgeCount--;
		this.stats.operations++;
		this.stats.lastOperation = Date.now();

		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Deleted edge:`, { id: edgeId });
	}

	async findEdges(filters?: EdgeFilters, edgeType?: string, limit?: number): Promise<GraphEdge[]> {
		this.ensureConnected();

		const maxResults = limit ?? DEFAULTS.QUERY_LIMIT;
		const results: GraphEdge[] = [];

		// Use index for type filtering if available
		let candidateIds = new Set<string>();
		if (edgeType && this.config.enableIndexing) {
			candidateIds = this.edgeIndex.edgeTypes.get(edgeType) || new Set();
		} else {
			candidateIds = new Set(this.edges.keys());
		}

		for (const edgeId of candidateIds) {
			if (results.length >= maxResults) break;

			const entry = this.edges.get(edgeId);
			if (!entry) continue;

			const edge = entry.data;

			// Check type filter
			if (edgeType && edge.type !== edgeType) {
				continue;
			}

			// Check property filters
			if (filters && !this.matchesEdgeFilters(edge, filters)) {
				continue;
			}

			results.push(this.deepClone(edge));
		}

		this.stats.queriesExecuted++;
		this.logger.debug(`${LOG_PREFIXES.IN_MEMORY} Found ${results.length} edges`);

		return results;
	}

	// Advanced operations

	async query(query: GraphQuery): Promise<GraphResult> {
		this.ensureConnected();

		const startTime = Date.now();
		let result: GraphResult;

		try {
			switch (query.type) {
				case 'node':
					result = await this.executeNodeQuery(query);
					break;
				case 'edge':
					result = await this.executeEdgeQuery(query);
					break;
				case 'path':
					result = await this.executePathQuery(query);
					break;
				case 'cypher':
					throw new InvalidQueryError('Cypher queries not supported in in-memory backend', query);
				default:
					throw new InvalidQueryError(`Unsupported query type: ${(query as any).type}`, query);
			}

			result.metadata.executionTime = Date.now() - startTime;
			this.stats.queriesExecuted++;

			return result;
		} catch (error) {
			throw new InvalidQueryError(
				`Query execution failed: ${(error as Error).message}`,
				query,
				error as Error
			);
		}
	}

	async getNeighbors(
		nodeId: string,
		direction: 'in' | 'out' | 'both' = 'both',
		edgeTypes?: string[],
		limit?: number
	): Promise<Array<{ node: GraphNode; edge: GraphEdge }>> {
		this.ensureConnected();

		if (!this.nodes.has(nodeId)) {
			throw new NodeNotFoundError(ERROR_MESSAGES.NODE_NOT_FOUND, nodeId);
		}

		const maxResults = limit ?? DEFAULTS.MAX_NEIGHBORS;
		const results: Array<{ node: GraphNode; edge: GraphEdge }> = [];

		const edgeIds = new Set<string>();

		// Collect relevant edge IDs based on direction
		if (direction === 'out' || direction === 'both') {
			const outgoing = this.outgoingEdges.get(nodeId) || new Set();
			outgoing.forEach(id => edgeIds.add(id));
		}

		if (direction === 'in' || direction === 'both') {
			const incoming = this.incomingEdges.get(nodeId) || new Set();
			incoming.forEach(id => edgeIds.add(id));
		}

		for (const edgeId of edgeIds) {
			if (results.length >= maxResults) break;

			const edgeEntry = this.edges.get(edgeId);
			if (!edgeEntry) continue;

			const edge = edgeEntry.data;

			// Check edge type filter
			if (edgeTypes && edgeTypes.length > 0 && !edgeTypes.includes(edge.type)) {
				continue;
			}

			// Get the neighbor node
			const neighborId = edge.startNodeId === nodeId ? edge.endNodeId : edge.startNodeId;
			const neighborEntry = this.nodes.get(neighborId);
			if (!neighborEntry) continue;

			results.push({
				node: this.deepClone(neighborEntry.data),
				edge: this.deepClone(edge),
			});
		}

		this.logger.debug(
			`${LOG_PREFIXES.IN_MEMORY} Found ${results.length} neighbors for node ${nodeId}`
		);

		return results;
	}

	async findPath(
		startNodeId: string,
		endNodeId: string,
		maxDepth: number = DEFAULTS.MAX_PATH_DEPTH,
		edgeTypes?: string[]
	): Promise<{ nodes: GraphNode[]; edges: GraphEdge[] } | null> {
		this.ensureConnected();

		if (!this.nodes.has(startNodeId)) {
			throw new NodeNotFoundError(`Start node not found`, startNodeId);
		}

		if (!this.nodes.has(endNodeId)) {
			throw new NodeNotFoundError(`End node not found`, endNodeId);
		}

		// Use BFS to find shortest path
		const queue: Array<{ nodeId: string; path: string[]; edgePath: string[] }> = [
			{ nodeId: startNodeId, path: [startNodeId], edgePath: [] },
		];
		const visited = new Set<string>();

		while (queue.length > 0) {
			const current = queue.shift()!;

			if (current.nodeId === endNodeId) {
				// Found path - construct result
				const nodes: GraphNode[] = [];
				const edges: GraphEdge[] = [];

				for (const nodeId of current.path) {
					const nodeEntry = this.nodes.get(nodeId);
					if (nodeEntry) {
						nodes.push(this.deepClone(nodeEntry.data));
					}
				}

				for (const edgeId of current.edgePath) {
					const edgeEntry = this.edges.get(edgeId);
					if (edgeEntry) {
						edges.push(this.deepClone(edgeEntry.data));
					}
				}

				this.logger.debug(
					`${LOG_PREFIXES.IN_MEMORY} Found path from ${startNodeId} to ${endNodeId} with ${edges.length} edges`
				);

				return { nodes, edges };
			}

			if (current.path.length >= maxDepth || visited.has(current.nodeId)) {
				continue;
			}

			visited.add(current.nodeId);

			// Explore neighbors
			const outgoing = this.outgoingEdges.get(current.nodeId) || new Set();
			for (const edgeId of outgoing) {
				const edgeEntry = this.edges.get(edgeId);
				if (!edgeEntry) continue;

				const edge = edgeEntry.data;

				// Check edge type filter
				if (edgeTypes && edgeTypes.length > 0 && !edgeTypes.includes(edge.type)) {
					continue;
				}

				const nextNodeId = edge.endNodeId;
				if (!visited.has(nextNodeId)) {
					queue.push({
						nodeId: nextNodeId,
						path: [...current.path, nextNodeId],
						edgePath: [...current.edgePath, edgeId],
					});
				}
			}
		}

		this.logger.debug(
			`${LOG_PREFIXES.IN_MEMORY} No path found from ${startNodeId} to ${endNodeId}`
		);
		return null;
	}

	// Graph management

	async clearGraph(): Promise<void> {
		this.ensureConnected();
		this.clear();
		this.logger.info(`${LOG_PREFIXES.IN_MEMORY} Graph cleared`);
	}

	async getStatistics(): Promise<{
		nodeCount: number;
		edgeCount: number;
		labelCounts: Record<string, number>;
		edgeTypeCounts: Record<string, number>;
	}> {
		this.ensureConnected();

		const labelCounts: Record<string, number> = {};
		const edgeTypeCounts: Record<string, number> = {};

		// Count node labels
		for (const entry of this.nodes.values()) {
			for (const label of entry.data.labels) {
				labelCounts[label] = (labelCounts[label] || 0) + 1;
			}
		}

		// Count edge types
		for (const entry of this.edges.values()) {
			const type = entry.data.type;
			edgeTypeCounts[type] = (edgeTypeCounts[type] || 0) + 1;
		}

		return {
			nodeCount: this.stats.nodeCount,
			edgeCount: this.stats.edgeCount,
			labelCounts,
			edgeTypeCounts,
		};
	}

	// Private helper methods

	private ensureConnected(): void {
		if (!this.connected) {
			throw new KnowledgeGraphConnectionError(ERROR_MESSAGES.NOT_CONNECTED, 'in-memory');
		}
	}

	private validateNode(node: GraphNode): void {
		if (!node.id || typeof node.id !== 'string') {
			throw new GraphValidationError('Node ID must be a non-empty string', 'node');
		}

		if (!Array.isArray(node.labels) || node.labels.length === 0) {
			throw new GraphValidationError('Node must have at least one label', 'node');
		}

		if (!node.properties || typeof node.properties !== 'object') {
			throw new GraphValidationError('Node properties must be an object', 'node');
		}
	}

	private validateEdge(edge: GraphEdge): void {
		if (!edge.id || typeof edge.id !== 'string') {
			throw new GraphValidationError('Edge ID must be a non-empty string', 'edge');
		}

		if (!edge.type || typeof edge.type !== 'string') {
			throw new GraphValidationError('Edge type must be a non-empty string', 'edge');
		}

		if (!edge.startNodeId || typeof edge.startNodeId !== 'string') {
			throw new GraphValidationError('Edge startNodeId must be a non-empty string', 'edge');
		}

		if (!edge.endNodeId || typeof edge.endNodeId !== 'string') {
			throw new GraphValidationError('Edge endNodeId must be a non-empty string', 'edge');
		}

		if (!edge.properties || typeof edge.properties !== 'object') {
			throw new GraphValidationError('Edge properties must be an object', 'edge');
		}
	}

	private deepClone<T>(obj: T): T {
		return JSON.parse(JSON.stringify(obj));
	}

	private clear(): void {
		this.nodes.clear();
		this.edges.clear();
		this.outgoingEdges.clear();
		this.incomingEdges.clear();
		this.clearIndexes();
		this.stats = {
			nodeCount: 0,
			edgeCount: 0,
			operations: 0,
			queriesExecuted: 0,
			lastOperation: 0,
		};
	}

	private clearIndexes(): void {
		this.nodeIndex.labels.clear();
		this.nodeIndex.edgeTypes.clear();
		this.nodeIndex.properties.clear();
		this.edgeIndex.labels.clear();
		this.edgeIndex.edgeTypes.clear();
		this.edgeIndex.properties.clear();
	}

	private updateNodeIndex(nodeId: string, node: GraphNode, operation: 'add' | 'remove'): void {
		if (!this.config.enableIndexing) return;

		const { labels, properties } = this.nodeIndex;

		// Update label indexes
		for (const label of node.labels) {
			if (!labels.has(label)) {
				labels.set(label, new Set());
			}
			const labelSet = labels.get(label)!;

			if (operation === 'add') {
				labelSet.add(nodeId);
			} else {
				labelSet.delete(nodeId);
				if (labelSet.size === 0) {
					labels.delete(label);
				}
			}
		}

		// Update property indexes
		for (const [key, value] of Object.entries(node.properties)) {
			if (!properties.has(key)) {
				properties.set(key, new Map());
			}
			const propMap = properties.get(key)!;

			if (!propMap.has(value)) {
				propMap.set(value, new Set());
			}
			const valueSet = propMap.get(value)!;

			if (operation === 'add') {
				valueSet.add(nodeId);
			} else {
				valueSet.delete(nodeId);
				if (valueSet.size === 0) {
					propMap.delete(value);
					if (propMap.size === 0) {
						properties.delete(key);
					}
				}
			}
		}
	}

	private updateEdgeIndex(edgeId: string, edge: GraphEdge, operation: 'add' | 'remove'): void {
		if (!this.config.enableIndexing) return;

		const { edgeTypes, properties } = this.edgeIndex;

		// Update edge type indexes
		if (!edgeTypes.has(edge.type)) {
			edgeTypes.set(edge.type, new Set());
		}
		const typeSet = edgeTypes.get(edge.type)!;

		if (operation === 'add') {
			typeSet.add(edgeId);
		} else {
			typeSet.delete(edgeId);
			if (typeSet.size === 0) {
				edgeTypes.delete(edge.type);
			}
		}

		// Update property indexes
		for (const [key, value] of Object.entries(edge.properties)) {
			if (!properties.has(key)) {
				properties.set(key, new Map());
			}
			const propMap = properties.get(key)!;

			if (!propMap.has(value)) {
				propMap.set(value, new Set());
			}
			const valueSet = propMap.get(value)!;

			if (operation === 'add') {
				valueSet.add(edgeId);
			} else {
				valueSet.delete(edgeId);
				if (valueSet.size === 0) {
					propMap.delete(value);
					if (propMap.size === 0) {
						properties.delete(key);
					}
				}
			}
		}
	}

	private matchesNodeFilters(node: GraphNode, filters: NodeFilters): boolean {
		for (const [key, filter] of Object.entries(filters)) {
			const value = node.properties[key];

			if (!this.matchesFilter(value, filter)) {
				return false;
			}
		}
		return true;
	}

	private matchesEdgeFilters(edge: GraphEdge, filters: EdgeFilters): boolean {
		for (const [key, filter] of Object.entries(filters)) {
			const value = edge.properties[key];

			if (!this.matchesFilter(value, filter)) {
				return false;
			}
		}
		return true;
	}

	private matchesFilter(value: any, filter: any): boolean {
		if (filter === null || filter === undefined) {
			return value === filter;
		}

		if (typeof filter === 'object' && !Array.isArray(filter)) {
			// Range filters
			if ('gte' in filter && value < filter.gte) return false;
			if ('gt' in filter && value <= filter.gt) return false;
			if ('lte' in filter && value > filter.lte) return false;
			if ('lt' in filter && value >= filter.lt) return false;

			// Array filters
			if ('any' in filter) {
				return Array.isArray(filter.any) && filter.any.includes(value);
			}
			if ('all' in filter) {
				return (
					Array.isArray(filter.all) &&
					Array.isArray(value) &&
					filter.all.every((item: any) => value.includes(item))
				);
			}

			return true;
		}

		// Direct equality
		return value === filter;
	}

	private async executeNodeQuery(query: GraphQuery): Promise<GraphResult> {
		const { pattern, limit } = query;
		const labels = pattern?.labels;
		const properties = pattern?.properties;

		const nodes = await this.findNodes(properties, labels, limit);

		return {
			nodes,
			edges: [],
			metadata: {
				totalCount: nodes.length,
				queryType: 'node',
			},
		};
	}

	private async executeEdgeQuery(query: GraphQuery): Promise<GraphResult> {
		const { pattern, limit } = query;
		const edgeType = pattern?.type;
		const properties = pattern?.properties;

		const edges = await this.findEdges(properties, edgeType, limit);

		return {
			nodes: [],
			edges,
			metadata: {
				totalCount: edges.length,
				queryType: 'edge',
			},
		};
	}

	private async executePathQuery(query: GraphQuery): Promise<GraphResult> {
		const { pattern, parameters } = query;
		const startNode = pattern?.startNode;
		const endNode = pattern?.endNode;
		const maxDepth = parameters?.maxDepth ?? DEFAULTS.MAX_PATH_DEPTH;

		if (!startNode?.id || !endNode?.id) {
			throw new InvalidQueryError('Path query requires startNode.id and endNode.id', query);
		}

		const path = await this.findPath(startNode.id, endNode.id, maxDepth);

		if (path) {
			return {
				nodes: path.nodes,
				edges: path.edges,
				paths: [
					{
						nodes: path.nodes,
						edges: path.edges,
						length: path.edges.length,
					},
				],
				metadata: {
					totalCount: 1,
					queryType: 'path',
				},
			};
		}

		return {
			nodes: [],
			edges: [],
			paths: [],
			metadata: {
				totalCount: 0,
				queryType: 'path',
			},
		};
	}

	// Debug methods for testing

	getInternalStats() {
		return {
			...this.stats,
			memoryUsage: {
				nodes: this.nodes.size,
				edges: this.edges.size,
				outgoingEdges: this.outgoingEdges.size,
				incomingEdges: this.incomingEdges.size,
			},
			indexSizes: this.config.enableIndexing
				? {
						nodeLabels: this.nodeIndex.labels.size,
						nodeProperties: this.nodeIndex.properties.size,
						edgeTypes: this.edgeIndex.edgeTypes.size,
						edgeProperties: this.edgeIndex.properties.size,
					}
				: null,
		};
	}
}

/** * Knowledge Graph Interface * * Defines the contract for knowledge graph implementations. * Knowledge graphs are optimized for entity-relationship storage and graph traversal operations. * * Implementations can include: * - Neo4j: Production-grade graph database * - ArangoDB: Multi-model database with graph capabilities * - In-Memory: Fast local storage for development/testing * * @module knowledge_graph/backend/knowledge-graph */
import type { GraphNode, GraphEdge, GraphQuery, GraphResult, NodeFilters, EdgeFilters, } from './types.js';
/** * KnowledgeGraph Interface * * Provides a unified API for different knowledge graph implementations. * All methods are asynchronous to support both local and network-based backends. * * @example * ```typescript * class Neo4jBackend implements KnowledgeGraph { * async addNode(node: GraphNode): Promise<void> { * const session = this.driver.session(); * await session.run( * 'CREATE (n:' + node.labels.join(':') + ' {properties})', * { properties: node.properties } * ); * await session.close(); * } * // ... other methods * } * ``` */ export interface KnowledgeGraph { // Basic node operations
/** * Add a new node to the knowledge graph * * @param node - The node to add with labels and properties * @throws {GraphValidationError} If node data is invalid * @throws {KnowledgeGraphError} If the operation fails * * @example * ```typescript * await graph.addNode({ * id: 'func_123', * labels: ['Function', 'Code'], * properties: { * name: 'calculateTotal', * language: 'typescript' * } * }); * ``` */ addNode(node: GraphNode): Promise<void>;
/** * Add multiple nodes to the knowledge graph in batch * * @param nodes - Array of nodes to add * @throws {GraphValidationError} If any node data is invalid * @throws {KnowledgeGraphError} If the operation fails * * @example * ```typescript * await graph.addNodes([node1, node2, node3]); * ``` */ addNodes(nodes: GraphNode[]): Promise<void>;
/** * Get a node by its ID * * @param nodeId - The unique identifier of the node * @returns The node if found, null otherwise * * @example * ```typescript * const node = await graph.getNode('func_123'); * if (node) { * console.log(node.properties.name); * } * ``` */ getNode(nodeId: string): Promise<GraphNode | null>;
/** * Update a node's properties * * @param nodeId - The unique identifier of the node * @param properties - New properties to set (merged with existing) * @param labels - Optional new labels to set * @throws {NodeNotFoundError} If node doesn't exist * @throws {KnowledgeGraphError} If the operation fails * * @example * ```typescript * await graph.updateNode('func_123', { * updated_at: Date.now(), * complexity: 'high' * }, ['Function', 'Code', 'Complex']); * ``` */ updateNode(nodeId: string, properties: Record<string, any>, labels?: string[]): Promise<void>;
/** * Delete a node and all its relationships * * @param nodeId - The unique identifier of the node to delete * @throws {KnowledgeGraphError} If the operation fails * * @example * ```typescript * await graph.deleteNode('func_123'); * ``` */ deleteNode(nodeId: string): Promise<void>;
/** * Find nodes matching the given filters * * @param filters - Property filters to apply * @param labels - Optional labels to filter by * @param limit - Maximum number of results to return * @returns Array of matching nodes * * @example * ```typescript * const functions = await graph.findNodes( * { language: 'typescript' }, * ['Function'], * 10 * ); * ``` */ findNodes(filters?: NodeFilters, labels?: string[], limit?: number): Promise<GraphNode[]>;
// Basic edge operations
/** * Add a new edge (relationship) to the knowledge graph * * @param edge - The edge to add with type and properties * @throws {GraphValidationError} If edge data is invalid * @throws {NodeNotFoundError} If start or end node doesn't exist * @throws {KnowledgeGraphError} If the operation fails * * @example * ```typescript * await graph.addEdge({ * id: 'rel_456', * type: 'DEPENDS_ON', * startNodeId: 'func_123', * endNodeId: 'func_456', * properties: { strength: 0.9 } * }); * ``` */ addEdge(edge: GraphEdge): Promise<void>;
/** * Add multiple edges to the knowledge graph in batch * * @param edges - Array of edges to add * @throws {GraphValidationError} If any edge data is invalid * @throws {KnowledgeGraphError} If the operation fails * * @example * ```typescript * await graph.addEdges([edge1, edge2, edge3]); * ``` */ addEdges(edges: GraphEdge[]): Promise<void>;
/** * Get an edge by its ID * * @param edgeId - The unique identifier of the edge * @returns The edge if found, null otherwise * * @example * ```typescript * const edge = await graph.getEdge('rel_456'); * if (edge) { * console.log(edge.properties.strength); * } * ``` */ getEdge(edgeId: string): Promise<GraphEdge | null>;
/** * Update an edge's properties * * @param edgeId - The unique identifier of the edge * @param properties - New properties to set (merged with existing) * @throws {EdgeNotFoundError} If edge doesn't exist * @throws {KnowledgeGraphError} If the operation fails * * @example * ```typescript * await graph.updateEdge('rel_456', { * updated_at: Date.now(), * strength: 0.95 * }); * ``` */ updateEdge(edgeId: string, properties: Record<string, any>): Promise<void>;
/** * Delete an edge * * @param edgeId - The unique identifier of the edge to delete * @throws {KnowledgeGraphError} If the operation fails * * @example * ```typescript * await graph.deleteEdge('rel_456'); * ``` */ deleteEdge(edgeId: string): Promise<void>;
/** * Find edges matching the given filters * * @param filters - Property filters to apply * @param edgeType - Optional edge type to filter by * @param limit - Maximum number of results to return * @returns Array of matching edges * * @example * ```typescript * const dependencies = await graph.findEdges( * { strength: { gte: 0.8 } }, * 'DEPENDS_ON', * 20 * ); * ``` */ findEdges(filters?: EdgeFilters, edgeType?: string, limit?: number): Promise<GraphEdge[]>;
// Advanced graph operations
/** * Execute a complex graph query * * @param query - The graph query to execute * @returns Query results containing nodes, edges, and metadata * @throws {InvalidQueryError} If query is malformed * @throws {KnowledgeGraphError} If the operation fails * * @example * ```typescript * const result = await graph.query({ * type: 'cypher', * query: 'MATCH (n:Function)-[r:DEPENDS_ON]->(m:Function) RETURN n, r, m', * limit: 100 * }); * ``` */ query(query: GraphQuery): Promise<GraphResult>;
/** * Get neighbors of a node (nodes connected by edges) * * @param nodeId - The node to get neighbors for * @param direction - Direction of relationships ('in', 'out', 'both') * @param edgeTypes - Optional edge types to filter by * @param limit - Maximum number of neighbors to return * @returns Array of neighbor nodes with their connecting edges * * @example * ```typescript * const neighbors = await graph.getNeighbors( * 'func_123', * 'out', * ['DEPENDS_ON', 'CALLS'], * 10 * ); * ``` */ getNeighbors( nodeId: string, direction?: 'in' | 'out' | 'both', edgeTypes?: string[], limit?: number ): Promise<Array<{ node: GraphNode; edge: GraphEdge }>>;
/** * Find shortest path between two nodes * * @param startNodeId - Starting node ID * @param endNodeId - Target node ID * @param maxDepth - Maximum path length to search * @param edgeTypes - Optional edge types to traverse * @returns Path if found, null otherwise * * @example * ```typescript * const path = await graph.findPath('func_123', 'func_789', 5); * if (path) { * console.log(`Path length: ${path.edges.length}`); * } * ``` */ findPath( startNodeId: string, endNodeId: string, maxDepth?: number, edgeTypes?: string[] ): Promise<{ nodes: GraphNode[]; edges: GraphEdge[] } | null>;
// Graph management
/** * Clear all nodes and edges from the graph * * WARNING: This will permanently delete all graph data. * * @example * ```typescript * // Use with caution! * await graph.clearGraph(); * ``` */ clearGraph(): Promise<void>;
/** * Get statistics about the graph * * @returns Object containing graph statistics * * @example * ```typescript * const stats = await graph.getStatistics(); * console.log(`Nodes: ${stats.nodeCount}, Edges: ${stats.edgeCount}`); * ``` */ getStatistics(): Promise<{ nodeCount: number; edgeCount: number; labelCounts: Record<string, number>; edgeTypeCounts: Record<string, number>; }>;
// Connection management
/** * Establishes connection to the knowledge graph backend * * Should be called before performing any operations. * Implementations should handle reconnection logic internally. * * @throws {KnowledgeGraphConnectionError} If connection fails * * @example * ```typescript * const graph = new Neo4jBackend(config); * await graph.connect(); * // Now ready to use * ``` */ connect(): Promise<void>;
/** * Gracefully closes the connection to the knowledge graph * * Should clean up resources and close any open connections. * After disconnect, connect() must be called again before use. * * @example * ```typescript * // Clean shutdown * await graph.disconnect(); * ``` */ disconnect(): Promise<void>;
/** * Checks if the backend is currently connected and ready * * @returns true if connected and operational, false otherwise * * @example * ```typescript * if (!graph.isConnected()) { * await graph.connect(); * } * ``` */ isConnected(): boolean;
/** * Returns the backend type identifier * * Useful for logging, monitoring, and conditional logic based on backend type. * * @returns Backend type string (e.g., 'neo4j', 'in-memory') * * @example * ```typescript * console.log(`Using ${graph.getBackendType()} for knowledge graph`); * ``` */ getBackendType(): string; }

/**
 * Neo4j Knowledge Graph Backend
 *
 * Production-grade graph database implementation using Neo4j.
 * Provides full Cipher query support and advanced graph operations.
 *
 * @module knowledge_graph/backend/neo4j
 */

import neo4j from 'neo4j-driver';
// TODO: Install neo4j-driver package: pnpm install neo4j-driver
type Driver = any;
type Session = any;

// Stub for neo4j when package is not installed
// const neo4j = {
// 	auth: {
// 		basic: (username: string, password: string) => ({ username, password }),
// 	},
// 	driver: (uri: string, auth: any, config: any) => {
// 		throw new Error('neo4j-driver package not installed. Please run: npm install neo4j-driver');
// 	},
// };
import { Logger, createLogger } from '../../logger/logger.js';
import type { KnowledgeGraph } from './knowledge-graph.js';
import type {
	GraphNode,
	GraphEdge,
	GraphQuery,
	GraphResult,
	NodeFilters,
	EdgeFilters,
} from './types.js';
import {
	KnowledgeGraphConnectionError,
	NodeNotFoundError,
	EdgeNotFoundError,
	InvalidQueryError,
	GraphValidationError,
} from './types.js';
import type { Neo4jBackendConfig } from '../config.js';
import { DEFAULTS, ERROR_MESSAGES, LOG_PREFIXES } from '../constants.js';

/**
 * Neo4j Knowledge Graph Backend
 *
 * Provides a production-grade implementation using Neo4j graph database.
 * Supports Cypher queries, transactions, and advanced graph operations.
 *
 * @example
 * ```typescript
 * const backend = new Neo4jBackend({
 *   type: 'neo4j',
 *   host: 'localhost',
 *   port: 7687,
 *   username: 'neo4j',
 *   password: 'password',
 *   database: 'neo4j'
 * });
 *
 * await backend.connect();
 * await backend.addNode({
 *   id: 'node1',
 *   labels: ['Function'],
 *   properties: { name: 'myFunction' }
 * });
 * ```
 */
export class Neo4jBackend implements KnowledgeGraph {
	private readonly config: Neo4jBackendConfig;
	private readonly logger: Logger;
	private driver: Driver | null = null;
	private connected = false;

	constructor(config: Neo4jBackendConfig) {
		this.config = {
			...config,
			timeout: config.timeout ?? DEFAULTS.CONNECTION_TIMEOUT,
			maxRetries: config.maxRetries ?? DEFAULTS.MAX_RETRIES,
			enablePooling: config.enablePooling ?? true,
			poolSize: config.poolSize ?? DEFAULTS.POOL_SIZE,
			database: config.database ?? DEFAULTS.NEO4J_DATABASE,
			encrypted: config.encrypted ?? false,
			trustServerCertificate: config.trustServerCertificate ?? false,
			maxTransactionRetryTime:
				config.maxTransactionRetryTime ?? DEFAULTS.NEO4J_MAX_TRANSACTION_RETRY_TIME,
			connectionAcquisitionTimeout:
				config.connectionAcquisitionTimeout ?? DEFAULTS.NEO4J_CONNECTION_ACQUISITION_TIMEOUT,
			maxConnectionLifetime: config.maxConnectionLifetime ?? DEFAULTS.NEO4J_MAX_CONNECTION_LIFETIME,
			connectionLivenessCheckTimeout:
				config.connectionLivenessCheckTimeout ?? DEFAULTS.NEO4J_CONNECTION_LIVENESS_CHECK_TIMEOUT,
		};

		this.logger = createLogger({
			level: 'debug',
		});

		this.logger.debug(`${LOG_PREFIXES.NEO4J} Initialized with config:`, {
			uri: this.buildConnectionUri(),
			database: this.config.database,
			encrypted: this.config.encrypted,
			poolSize: this.config.poolSize,
		});
	}

	// Connection management

	async connect(): Promise<void> {
		if (this.connected && this.driver) {
			this.logger.debug(`${LOG_PREFIXES.NEO4J} Already connected`);
			return;
		}

		try {
			const uri = this.buildConnectionUri();
			const auth = neo4j.auth.basic(this.config.username, this.config.password);

			const driverConfig: any = {
				maxConnectionPoolSize: this.config.poolSize,
				connectionAcquisitionTimeout: this.config.connectionAcquisitionTimeout,
				maxTransactionRetryTime: this.config.maxTransactionRetryTime,
				maxConnectionLifetime: this.config.maxConnectionLifetime,
				connectionLivenessCheckTimeout: this.config.connectionLivenessCheckTimeout,
			};

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Creating driver for ${uri}`);
			this.driver = neo4j.driver(uri, auth, driverConfig);

			// Test connection
			await this.driver.verifyConnectivity();

			this.connected = true;
			this.logger.info(`${LOG_PREFIXES.NEO4J} Connected successfully to ${uri}`);

			// Create indexes for performance
			await this.createIndexes();
		} catch (error) {
			console.error('Neo4j connect error:', error);
			const connectionError = new KnowledgeGraphConnectionError(
				`${ERROR_MESSAGES.CONNECTION_FAILED}: ${(error as Error).message}`,
				'neo4j',
				error as Error
			);
			this.logger.error(`${LOG_PREFIXES.NEO4J} Connection failed:`, connectionError);
			throw connectionError;
		}
	}

	async disconnect(): Promise<void> {
		if (!this.connected || !this.driver) {
			this.logger.debug(`${LOG_PREFIXES.NEO4J} Already disconnected`);
			return;
		}

		try {
			await this.driver.close();
			this.driver = null;
			this.connected = false;
			this.logger.info(`${LOG_PREFIXES.NEO4J} Disconnected successfully`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.NEO4J} Error during disconnect:`, error);
			throw error;
		}
	}

	isConnected(): boolean {
		return this.connected && this.driver !== null;
	}

	getBackendType(): string {
		return 'neo4j';
	}

	// Node operations

	async addNode(node: GraphNode): Promise<void> {
		this.ensureConnected();
		this.validateNode(node);

		const session = this.getSession();
		try {
			const labelsStr = node.labels.map(label => `\`${label}\``).join(':');
			const query = `CREATE (n:${labelsStr}) SET n = $properties, n.id = $id RETURN n`;

			const result = await session.run(query, {
				id: node.id,
				properties: node.properties,
			});

			if (result.records.length === 0) {
				throw new GraphValidationError('Failed to create node', 'node');
			}

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Added node:`, { id: node.id, labels: node.labels });
		} catch (error) {
			if ((error as any).code === 'Neo.ClientError.Schema.ConstraintValidationFailed') {
				throw new GraphValidationError(
					`Node with ID '${node.id}' already exists`,
					'node',
					error as Error
				);
			}
			throw error;
		} finally {
			await session.close();
		}
	}

	async addNodes(nodes: GraphNode[]): Promise<void> {
		this.ensureConnected();

		// Validate all nodes first
		for (const node of nodes) {
			this.validateNode(node);
		}

		const session = this.getSession();
		try {
			const tx = session.beginTransaction();

			for (const node of nodes) {
				const labelsStr = node.labels.map(label => `\`${label}\``).join(':');
				const query = `CREATE (n:${labelsStr}) SET n = $properties, n.id = $id`;

				await tx.run(query, {
					id: node.id,
					properties: node.properties,
				});
			}

			await tx.commit();
			this.logger.debug(`${LOG_PREFIXES.NEO4J} Added ${nodes.length} nodes`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.NEO4J} Error adding nodes:`, error);
			throw error;
		} finally {
			await session.close();
		}
	}

	async getNode(nodeId: string): Promise<GraphNode | null> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			const query = 'MATCH (n) WHERE n.id = $id RETURN n, labels(n) as nodeLabels';
			const result = await session.run(query, { id: nodeId });

			if (result.records.length === 0) {
				return null;
			}

			const record = result.records[0];
			const nodeData = record.get('n').properties;
			const labels = record.get('nodeLabels');

			return {
				id: nodeId,
				labels: labels,
				properties: this.convertNeo4jProperties(nodeData),
			};
		} finally {
			await session.close();
		}
	}

	async updateNode(
		nodeId: string,
		properties: Record<string, any>,
		labels?: string[]
	): Promise<void> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			// Check if node exists
			const existsResult = await session.run('MATCH (n) WHERE n.id = $id RETURN n', { id: nodeId });

			if (existsResult.records.length === 0) {
				throw new NodeNotFoundError(ERROR_MESSAGES.NODE_NOT_FOUND, nodeId);
			}

			// Update properties
			let query = 'MATCH (n) WHERE n.id = $id SET n += $properties';
			const params: any = { id: nodeId, properties };

			// Update labels if provided
			if (labels && labels.length > 0) {
				// Remove all existing labels and add new ones
				const labelsStr = labels.map(label => `\`${label}\``).join(':');
				query = `MATCH (n) WHERE n.id = $id REMOVE n:${labelsStr} SET n:${labelsStr}, n += $properties`;
			}

			await session.run(query, params);

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Updated node:`, { id: nodeId });
		} finally {
			await session.close();
		}
	}

	async deleteNode(nodeId: string): Promise<void> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			const query = 'MATCH (n) WHERE n.id = $id DETACH DELETE n';
			await session.run(query, { id: nodeId });

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Deleted node:`, { id: nodeId });
		} finally {
			await session.close();
		}
	}

	async findNodes(filters?: NodeFilters, labels?: string[], limit?: number): Promise<GraphNode[]> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			let query = 'MATCH (n)';
			const params: any = {};

			// Add label filters
			if (labels && labels.length > 0) {
				const labelConstraints = labels.map(label => `n:\`${label}\``).join(' OR ');
				query += ` WHERE (${labelConstraints})`;
			}

			// Add property filters
			if (filters) {
				const filterConstraints = this.buildFilterConstraints(filters, 'n', params);
				if (filterConstraints) {
					query +=
						labels && labels.length > 0
							? ` AND ${filterConstraints}`
							: ` WHERE ${filterConstraints}`;
				}
			}

			query += ' RETURN n, labels(n) as nodeLabels';

			// Add limit
			if (limit) {
				query += ` LIMIT ${limit}`;
			}

			const result = await session.run(query, params);
			const nodes: GraphNode[] = [];

			for (const record of result.records) {
				const nodeData = record.get('n').properties;
				const nodeLabels = record.get('nodeLabels');

				nodes.push({
					id: nodeData.id,
					labels: nodeLabels,
					properties: this.convertNeo4jProperties(nodeData),
				});
			}

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Found ${nodes.length} nodes`);
			return nodes;
		} finally {
			await session.close();
		}
	}

	// Edge operations

	async addEdge(edge: GraphEdge): Promise<void> {
		this.ensureConnected();
		this.validateEdge(edge);

		const session = this.getSession();
		try {
			const query = `
				MATCH (a), (b) 
				WHERE a.id = $startId AND b.id = $endId 
				CREATE (a)-[r:\`${edge.type}\`]->(b) 
				SET r = $properties, r.id = $edgeId 
				RETURN r
			`;

			const result = await session.run(query, {
				startId: edge.startNodeId,
				endId: edge.endNodeId,
				edgeId: edge.id,
				properties: edge.properties,
			});

			if (result.records.length === 0) {
				throw new GraphValidationError(
					`Failed to create edge: start node '${edge.startNodeId}' or end node '${edge.endNodeId}' not found`,
					'edge'
				);
			}

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Added edge:`, {
				id: edge.id,
				type: edge.type,
				from: edge.startNodeId,
				to: edge.endNodeId,
			});
		} catch (error) {
			if ((error as any).code === 'Neo.ClientError.Schema.ConstraintValidationFailed') {
				throw new GraphValidationError(
					`Edge with ID '${edge.id}' already exists`,
					'edge',
					error as Error
				);
			}
			throw error;
		} finally {
			await session.close();
		}
	}

	async addEdges(edges: GraphEdge[]): Promise<void> {
		this.ensureConnected();

		// Validate all edges first
		for (const edge of edges) {
			this.validateEdge(edge);
		}

		const session = this.getSession();
		try {
			const tx = session.beginTransaction();

			for (const edge of edges) {
				const query = `
					MATCH (a), (b) 
					WHERE a.id = $startId AND b.id = $endId 
					CREATE (a)-[r:\`${edge.type}\`]->(b) 
					SET r = $properties, r.id = $edgeId
				`;

				await tx.run(query, {
					startId: edge.startNodeId,
					endId: edge.endNodeId,
					edgeId: edge.id,
					properties: edge.properties,
				});
			}

			await tx.commit();
			this.logger.debug(`${LOG_PREFIXES.NEO4J} Added ${edges.length} edges`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.NEO4J} Error adding edges:`, error);
			throw error;
		} finally {
			await session.close();
		}
	}

	async getEdge(edgeId: string): Promise<GraphEdge | null> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			const query = `
				MATCH (a)-[r]->(b) 
				WHERE r.id = $id 
				RETURN r, a.id as startId, b.id as endId, type(r) as edgeType
			`;
			const result = await session.run(query, { id: edgeId });

			if (result.records.length === 0) {
				return null;
			}

			const record = result.records[0];
			const edgeData = record.get('r').properties;
			const startId = record.get('startId');
			const endId = record.get('endId');
			const edgeType = record.get('edgeType');

			return {
				id: edgeId,
				type: edgeType,
				startNodeId: startId,
				endNodeId: endId,
				properties: this.convertNeo4jProperties(edgeData),
			};
		} finally {
			await session.close();
		}
	}

	async updateEdge(edgeId: string, properties: Record<string, any>): Promise<void> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			// Check if edge exists
			const existsResult = await session.run('MATCH ()-[r]-() WHERE r.id = $id RETURN r', {
				id: edgeId,
			});

			if (existsResult.records.length === 0) {
				throw new EdgeNotFoundError(ERROR_MESSAGES.EDGE_NOT_FOUND, edgeId);
			}

			// Update properties
			const query = 'MATCH ()-[r]-() WHERE r.id = $id SET r += $properties';
			await session.run(query, { id: edgeId, properties });

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Updated edge:`, { id: edgeId });
		} finally {
			await session.close();
		}
	}

	async deleteEdge(edgeId: string): Promise<void> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			const query = 'MATCH ()-[r]-() WHERE r.id = $id DELETE r';
			await session.run(query, { id: edgeId });

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Deleted edge:`, { id: edgeId });
		} finally {
			await session.close();
		}
	}

	async findEdges(filters?: EdgeFilters, edgeType?: string, limit?: number): Promise<GraphEdge[]> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			let query = 'MATCH (a)-[r]->(b)';
			const params: any = {};

			// Add type filter
			if (edgeType) {
				query = `MATCH (a)-[r:\`${edgeType}\`]->(b)`;
			}

			// Add property filters
			if (filters) {
				const filterConstraints = this.buildFilterConstraints(filters, 'r', params);
				if (filterConstraints) {
					query += ` WHERE ${filterConstraints}`;
				}
			}

			query += ' RETURN r, a.id as startId, b.id as endId, type(r) as edgeType';

			// Add limit
			if (limit) {
				query += ` LIMIT ${limit}`;
			}

			const result = await session.run(query, params);
			const edges: GraphEdge[] = [];

			for (const record of result.records) {
				const edgeData = record.get('r').properties;
				const startId = record.get('startId');
				const endId = record.get('endId');
				const type = record.get('edgeType');

				edges.push({
					id: edgeData.id,
					type: type,
					startNodeId: startId,
					endNodeId: endId,
					properties: this.convertNeo4jProperties(edgeData),
				});
			}

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Found ${edges.length} edges`);
			return edges;
		} finally {
			await session.close();
		}
	}

	// Advanced operations

	async query(query: GraphQuery): Promise<GraphResult> {
		this.ensureConnected();

		const startTime = Date.now();
		const session = this.getSession();

		try {
			let result: GraphResult;

			switch (query.type) {
				case 'node':
					result = await this.executeNodeQuery(query, session);
					break;
				case 'edge':
					result = await this.executeEdgeQuery(query, session);
					break;
				case 'path':
					result = await this.executePathQuery(query, session);
					break;
				case 'cypher':
					result = await this.executeCypherQuery(query, session);
					break;
				default:
					throw new InvalidQueryError(`Unsupported query type: ${(query as any).type}`, query);
			}

			result.metadata.executionTime = Date.now() - startTime;
			return result;
		} catch (error) {
			throw new InvalidQueryError(
				`Query execution failed: ${(error as Error).message}`,
				query,
				error as Error
			);
		} finally {
			await session.close();
		}
	}

	async getNeighbors(
		nodeId: string,
		direction: 'in' | 'out' | 'both' = 'both',
		edgeTypes?: string[],
		limit?: number
	): Promise<Array<{ node: GraphNode; edge: GraphEdge }>> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			let relationshipPattern: string;

			switch (direction) {
				case 'in':
					relationshipPattern = '<-[r]-';
					break;
				case 'out':
					relationshipPattern = '-[r]->';
					break;
				case 'both':
					relationshipPattern = '-[r]-';
					break;
			}

			// Add edge type filters
			if (edgeTypes && edgeTypes.length > 0) {
				const typeStr = edgeTypes.map(type => `\`${type}\``).join('|');
				relationshipPattern = relationshipPattern.replace('[r]', `[r:${typeStr}]`);
			}

			let query = `
				MATCH (n)${relationshipPattern}(m) 
				WHERE n.id = $nodeId 
				RETURN m, labels(m) as nodeLabels, r, type(r) as edgeType, n.id as startId, m.id as endId
			`;

			if (limit) {
				query += ` LIMIT ${limit}`;
			}

			const result = await session.run(query, { nodeId });
			const neighbors: Array<{ node: GraphNode; edge: GraphEdge }> = [];

			for (const record of result.records) {
				const nodeData = record.get('m').properties;
				const nodeLabels = record.get('nodeLabels');
				const edgeData = record.get('r').properties;
				const edgeType = record.get('edgeType');
				const startId = record.get('startId');
				const endId = record.get('endId');

				neighbors.push({
					node: {
						id: nodeData.id,
						labels: nodeLabels,
						properties: this.convertNeo4jProperties(nodeData),
					},
					edge: {
						id: edgeData.id,
						type: edgeType,
						startNodeId: startId,
						endNodeId: endId,
						properties: this.convertNeo4jProperties(edgeData),
					},
				});
			}

			this.logger.debug(
				`${LOG_PREFIXES.NEO4J} Found ${neighbors.length} neighbors for node ${nodeId}`
			);
			return neighbors;
		} finally {
			await session.close();
		}
	}

	async findPath(
		startNodeId: string,
		endNodeId: string,
		maxDepth: number = DEFAULTS.MAX_PATH_DEPTH,
		edgeTypes?: string[]
	): Promise<{ nodes: GraphNode[]; edges: GraphEdge[] } | null> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			let relationshipPattern = '*1..' + maxDepth;

			if (edgeTypes && edgeTypes.length > 0) {
				const typeStr = edgeTypes.map(type => `\`${type}\``).join('|');
				relationshipPattern = `:${typeStr}${relationshipPattern}`;
			}

			const query = `
				MATCH path = shortestPath((a)-[${relationshipPattern}]-(b)) 
				WHERE a.id = $startId AND b.id = $endId 
				RETURN path
			`;

			const result = await session.run(query, {
				startId: startNodeId,
				endId: endNodeId,
			});

			if (result.records.length === 0) {
				this.logger.debug(
					`${LOG_PREFIXES.NEO4J} No path found from ${startNodeId} to ${endNodeId}`
				);
				return null;
			}

			const path = result.records[0].get('path');
			const nodes: GraphNode[] = [];
			const edges: GraphEdge[] = [];

			// Extract nodes
			for (const nodeRecord of path.segments.flatMap((segment: any) => [
				segment.start,
				segment.end,
			])) {
				const nodeData = nodeRecord.properties;
				const labels = nodeRecord.labels;

				nodes.push({
					id: nodeData.id,
					labels: labels,
					properties: this.convertNeo4jProperties(nodeData),
				});
			}

			// Extract edges
			for (const segment of path.segments) {
				const edgeData = segment.relationship.properties;
				const startNodeData = segment.start.properties;
				const endNodeData = segment.end.properties;

				edges.push({
					id: edgeData.id,
					type: segment.relationship.type,
					startNodeId: startNodeData.id,
					endNodeId: endNodeData.id,
					properties: this.convertNeo4jProperties(edgeData),
				});
			}

			// Remove duplicates
			const uniqueNodes = nodes.filter(
				(node, index, self) => index === self.findIndex(n => n.id === node.id)
			);

			this.logger.debug(
				`${LOG_PREFIXES.NEO4J} Found path from ${startNodeId} to ${endNodeId} with ${edges.length} edges`
			);

			return { nodes: uniqueNodes, edges };
		} finally {
			await session.close();
		}
	}

	// Graph management

	async clearGraph(): Promise<void> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			await session.run('MATCH (n) DETACH DELETE n');
			this.logger.info(`${LOG_PREFIXES.NEO4J} Graph cleared`);
		} finally {
			await session.close();
		}
	}

	async getStatistics(): Promise<{
		nodeCount: number;
		edgeCount: number;
		labelCounts: Record<string, number>;
		edgeTypeCounts: Record<string, number>;
	}> {
		this.ensureConnected();

		const session = this.getSession();
		try {
			// Get node count
			const nodeCountResult = await session.run('MATCH (n) RETURN count(n) as count');
			const nodeCount = nodeCountResult.records[0].get('count').toNumber();

			// Get edge count
			const edgeCountResult = await session.run('MATCH ()-[r]-() RETURN count(r) as count');
			const edgeCount = edgeCountResult.records[0].get('count').toNumber();

			// Get label counts
			const labelCountsResult = await session.run(`
				CALL db.labels() YIELD label
				CALL apoc.cypher.run('MATCH (n:\`' + label + '\`) RETURN count(n) as count', {}) YIELD value
				RETURN label, value.count as count
			`);

			const labelCounts: Record<string, number> = {};
			for (const record of labelCountsResult.records) {
				const label = record.get('label');
				const count = record.get('count').toNumber();
				labelCounts[label] = count;
			}

			// Get edge type counts
			const edgeTypeCountsResult = await session.run(`
				CALL db.relationshipTypes() YIELD relationshipType
				CALL apoc.cypher.run('MATCH ()-[r:\`' + relationshipType + '\`]-() RETURN count(r) as count', {}) YIELD value
				RETURN relationshipType, value.count as count
			`);

			const edgeTypeCounts: Record<string, number> = {};
			for (const record of edgeTypeCountsResult.records) {
				const type = record.get('relationshipType');
				const count = record.get('count').toNumber();
				edgeTypeCounts[type] = count;
			}

			return {
				nodeCount,
				edgeCount,
				labelCounts,
				edgeTypeCounts,
			};
		} finally {
			await session.close();
		}
	}

	// Private helper methods

	private ensureConnected(): void {
		if (!this.connected || !this.driver) {
			throw new KnowledgeGraphConnectionError(ERROR_MESSAGES.NOT_CONNECTED, 'neo4j');
		}
	}

	private getSession(): Session {
		if (!this.driver) {
			throw new KnowledgeGraphConnectionError(ERROR_MESSAGES.NOT_CONNECTED, 'neo4j');
		}

		return this.driver.session({
			database: this.config.database,
			defaultAccessMode: neo4j.session.WRITE,
		});
	}

	private buildConnectionUri(): string {
		if (this.config.uri) {
			return this.config.uri;
		}

		const protocol = this.config.encrypted ? 'neo4j+s' : 'neo4j';
		const port = this.config.port ?? DEFAULTS.NEO4J_PORT;
		return `${protocol}://${this.config.host}:${port}`;
	}

	private validateNode(node: GraphNode): void {
		if (!node.id || typeof node.id !== 'string') {
			throw new GraphValidationError('Node ID must be a non-empty string', 'node');
		}

		if (!Array.isArray(node.labels) || node.labels.length === 0) {
			throw new GraphValidationError('Node must have at least one label', 'node');
		}

		if (!node.properties || typeof node.properties !== 'object') {
			throw new GraphValidationError('Node properties must be an object', 'node');
		}
	}

	private validateEdge(edge: GraphEdge): void {
		if (!edge.id || typeof edge.id !== 'string') {
			throw new GraphValidationError('Edge ID must be a non-empty string', 'edge');
		}

		if (!edge.type || typeof edge.type !== 'string') {
			throw new GraphValidationError('Edge type must be a non-empty string', 'edge');
		}

		if (!edge.startNodeId || typeof edge.startNodeId !== 'string') {
			throw new GraphValidationError('Edge startNodeId must be a non-empty string', 'edge');
		}

		if (!edge.endNodeId || typeof edge.endNodeId !== 'string') {
			throw new GraphValidationError('Edge endNodeId must be a non-empty string', 'edge');
		}

		if (!edge.properties || typeof edge.properties !== 'object') {
			throw new GraphValidationError('Edge properties must be an object', 'edge');
		}
	}

	private convertNeo4jProperties(properties: any): Record<string, any> {
		const converted: Record<string, any> = {};

		for (const [key, value] of Object.entries(properties)) {
			// Convert Neo4j integers to regular numbers if they're within safe range
			if (value && typeof value === 'object' && 'toNumber' in value) {
				converted[key] = (value as any).toNumber();
			} else {
				converted[key] = value;
			}
		}

		return converted;
	}

	private buildFilterConstraints(
		filters: NodeFilters | EdgeFilters,
		prefix: string,
		params: any
	): string {
		const constraints: string[] = [];

		for (const [, filter] of Object.entries(filters)) {
			const paramKey = `${prefix}_${Object.keys(params).length}`;

			if (typeof filter === 'object' && filter !== null && !Array.isArray(filter)) {
				// Range filters
				if ('gte' in filter) {
					constraints.push(`${prefix}.${Object.keys(params).length} >= $${paramKey}_gte`);
					params[`${paramKey}_gte`] = filter.gte;
				}
				if ('gt' in filter) {
					constraints.push(`${prefix}.${Object.keys(params).length} > $${paramKey}_gt`);
					params[`${paramKey}_gt`] = filter.gt;
				}
				if ('lte' in filter) {
					constraints.push(`${prefix}.${Object.keys(params).length} <= $${paramKey}_lte`);
					params[`${paramKey}_lte`] = filter.lte;
				}
				if ('lt' in filter) {
					constraints.push(`${prefix}.${Object.keys(params).length} < $${paramKey}_lt`);
					params[`${paramKey}_lt`] = filter.lt;
				}

				// Array filters
				if ('any' in filter && Array.isArray(filter.any)) {
					constraints.push(`${prefix}.${Object.keys(params).length} IN $${paramKey}`);
					params[paramKey] = filter.any;
				}
				if ('all' in filter && Array.isArray(filter.all)) {
					// For 'all' filter, check if the property (assumed to be array) contains all values
					constraints.push(
						`all(x IN $${paramKey} WHERE x IN ${prefix}.${Object.keys(params).length})`
					);
					params[paramKey] = filter.all;
				}
			} else {
				// Direct equality
				constraints.push(`${prefix}.${Object.keys(params).length} = $${paramKey}`);
				params[paramKey] = filter;
			}
		}

		return constraints.join(' AND ');
	}

	private async createIndexes(): Promise<void> {
		const session = this.getSession();
		try {
			// Create unique constraint on node ID
			await session.run(
				'CREATE CONSTRAINT node_id_unique IF NOT EXISTS FOR (n:Entity) REQUIRE n.id IS UNIQUE'
			);

			// Create index on node IDs for faster lookups
			await session.run('CREATE INDEX node_id_index IF NOT EXISTS FOR (n:Entity) ON (n.id)');

			// Create index on edge IDs
			await session.run(
				'CREATE INDEX edge_id_index IF NOT EXISTS FOR ()-[r:CONNECTED_TO]-() ON (r.id)'
			);

			this.logger.debug(`${LOG_PREFIXES.NEO4J} Created indexes`);
		} catch (_error) {
			console.log(_error);
			this.logger.warn(`${LOG_PREFIXES.NEO4J} Could not create indexes:`, _error);
		} finally {
			await session.close();
		}
	}

	private async executeNodeQuery(query: GraphQuery, _session: Session): Promise<GraphResult> {
		const { pattern, limit } = query;
		const labels = pattern?.labels;
		const properties = pattern?.properties;

		const nodes = await this.findNodes(properties, labels, limit);

		return {
			nodes,
			edges: [],
			metadata: {
				totalCount: nodes.length,
				queryType: 'node',
			},
		};
	}

	private async executeEdgeQuery(query: GraphQuery, _session: Session): Promise<GraphResult> {
		const { pattern, limit } = query;
		const edgeType = pattern?.type;
		const properties = pattern?.properties;

		const edges = await this.findEdges(properties, edgeType, limit);

		return {
			nodes: [],
			edges,
			metadata: {
				totalCount: edges.length,
				queryType: 'edge',
			},
		};
	}

	private async executePathQuery(query: GraphQuery, _session: Session): Promise<GraphResult> {
		const { pattern, parameters } = query;
		const startNode = pattern?.startNode;
		const endNode = pattern?.endNode;
		const maxDepth = parameters?.maxDepth ?? DEFAULTS.MAX_PATH_DEPTH;

		if (!startNode?.id || !endNode?.id) {
			throw new InvalidQueryError('Path query requires startNode.id and endNode.id', query);
		}

		const path = await this.findPath(startNode.id, endNode.id, maxDepth);

		if (path) {
			return {
				nodes: path.nodes,
				edges: path.edges,
				paths: [
					{
						nodes: path.nodes,
						edges: path.edges,
						length: path.edges.length,
					},
				],
				metadata: {
					totalCount: 1,
					queryType: 'path',
				},
			};
		}

		return {
			nodes: [],
			edges: [],
			paths: [],
			metadata: {
				totalCount: 0,
				queryType: 'path',
			},
		};
	}

	private async executeCypherQuery(query: GraphQuery, session: Session): Promise<GraphResult> {
		if (!query.query) {
			throw new InvalidQueryError('Cypher query requires query string', query);
		}

		const result = await session.run(query.query, query.parameters || {});
		const nodes: GraphNode[] = [];
		const edges: GraphEdge[] = [];

		// Extract nodes and edges from result
		for (const record of result.records) {
			for (const [, value] of record.entries()) {
				if (value && typeof value === 'object') {
					// Check if it's a node
					if ('labels' in value && 'properties' in value) {
						nodes.push({
							id: value.properties.id,
							labels: value.labels,
							properties: this.convertNeo4jProperties(value.properties),
						});
					}
					// Check if it's a relationship
					else if ('type' in value && 'start' in value && 'end' in value) {
						edges.push({
							id: value.properties.id,
							type: value.type,
							startNodeId: value.start.properties.id,
							endNodeId: value.end.properties.id,
							properties: this.convertNeo4jProperties(value.properties),
						});
					}
				}
			}
		}

		return {
			nodes,
			edges,
			metadata: {
				totalCount: result.records.length,
				queryType: 'cypher',
			},
		};
	}
}

/**
 * Knowledge Graph Backend Types and Error Classes
 *
 * This module defines the core types and error classes for the knowledge graph system.
 * The knowledge graph system provides entity-relationship storage and graph traversal capabilities.
 *
 * @module knowledge_graph/backend/types
 */

import type { KnowledgeGraph } from './knowledge-graph.js';

// Re-export the knowledge graph interface for convenience
export type { KnowledgeGraph };

// Re-export config types for convenience (imported from config module)
export type { BackendConfig, KnowledgeGraphConfig } from '../config.js';

/**
 * Filters for node searches
 *
 * Supports various comparison operations for filtering nodes by properties.
 *
 * @example
 * ```typescript
 * const filters: NodeFilters = {
 *   type: 'Function',
 *   name: { any: ['getData', 'setData'] },
 *   created_at: { gte: Date.now() - 86400000 }
 * };
 * ```
 */
export interface NodeFilters {
	[key: string]:
		| string
		| number
		| boolean
		| { gte?: number; gt?: number; lte?: number; lt?: number }
		| { any?: Array<string | number> }
		| { all?: Array<string | number> };
}

/**
 * Filters for edge searches
 *
 * Similar to NodeFilters but for relationship filtering.
 *
 * @example
 * ```typescript
 * const edgeFilters: EdgeFilters = {
 *   type: 'DEPENDS_ON',
 *   strength: { gte: 0.8 }
 * };
 * ```
 */
export interface EdgeFilters {
	[key: string]:
		| string
		| number
		| boolean
		| { gte?: number; gt?: number; lte?: number; lt?: number }
		| { any?: Array<string | number> }
		| { all?: Array<string | number> };
}

/**
 * Graph node representation
 *
 * Represents an entity in the knowledge graph with properties and metadata.
 *
 * @example
 * ```typescript
 * const functionNode: GraphNode = {
 *   id: 'func_123',
 *   labels: ['Function', 'Code'],
 *   properties: {
 *     name: 'calculateTotal',
 *     language: 'typescript',
 *     file_path: 'src/utils.ts',
 *     created_at: Date.now()
 *   }
 * };
 * ```
 */
export interface GraphNode {
	/** Unique identifier for the node */
	id: string;

	/** Array of labels/types for the node */
	labels: string[];

	/** Properties/attributes of the node */
	properties: Record<string, any>;
}

/**
 * Graph edge/relationship representation
 *
 * Represents a relationship between two nodes in the knowledge graph.
 *
 * @example
 * ```typescript
 * const dependency: GraphEdge = {
 *   id: 'rel_456',
 *   type: 'DEPENDS_ON',
 *   startNodeId: 'func_123',
 *   endNodeId: 'func_456',
 *   properties: {
 *     strength: 0.9,
 *     context: 'function call',
 *     created_at: Date.now()
 *   }
 * };
 * ```
 */
export interface GraphEdge {
	/** Unique identifier for the edge */
	id: string;

	/** Type/label of the relationship */
	type: string;

	/** ID of the source node */
	startNodeId: string;

	/** ID of the target node */
	endNodeId: string;

	/** Properties/attributes of the relationship */
	properties: Record<string, any>;
}

/**
 * Graph query structure
 *
 * Defines different types of queries that can be executed on the knowledge graph.
 *
 * @example
 * ```typescript
 * // Find nodes by pattern
 * const nodeQuery: GraphQuery = {
 *   type: 'node',
 *   pattern: {
 *     labels: ['Function'],
 *     properties: { language: 'typescript' }
 *   },
 *   limit: 10
 * };
 *
 * // Find relationships
 * const edgeQuery: GraphQuery = {
 *   type: 'edge',
 *   pattern: {
 *     type: 'DEPENDS_ON',
 *     properties: { strength: { gte: 0.8 } }
 *   }
 * };
 *
 * // Custom Cypher query for Neo4j
 * const cypherQuery: GraphQuery = {
 *   type: 'cypher',
 *   query: 'MATCH (n:Function)-[r:DEPENDS_ON]->(m:Function) RETURN n, r, m',
 *   parameters: {}
 * };
 * ```
 */
export interface GraphQuery {
	/** Type of query to execute */
	type: 'node' | 'edge' | 'path' | 'cypher';

	/** Query pattern (for structured queries) */
	pattern?: {
		labels?: string[];
		type?: string;
		properties?: Record<string, any>;
		startNode?: Partial<GraphNode>;
		endNode?: Partial<GraphNode>;
	};

	/** Raw query string (for cypher queries) */
	query?: string;

	/** Query parameters */
	parameters?: Record<string, any>;

	/** Maximum number of results to return */
	limit?: number;

	/** Number of results to skip (for pagination) */
	skip?: number;
}

/**
 * Graph query result
 *
 * Contains the results of a graph query operation.
 *
 * @example
 * ```typescript
 * const result: GraphResult = {
 *   nodes: [functionNode],
 *   edges: [dependency],
 *   paths: [],
 *   metadata: {
 *     totalCount: 1,
 *     executionTime: 15,
 *     queryType: 'node'
 *   }
 * };
 * ```
 */
export interface GraphResult {
	/** Nodes returned by the query */
	nodes: GraphNode[];

	/** Edges returned by the query */
	edges: GraphEdge[];

	/** Paths returned by the query (for path queries) */
	paths?: Array<{
		nodes: GraphNode[];
		edges: GraphEdge[];
		length: number;
	}>;

	/** Query execution metadata */
	metadata: {
		/** Total count of available results */
		totalCount?: number;
		/** Query execution time in milliseconds */
		executionTime?: number;
		/** Type of query that was executed */
		queryType: string;
		/** Additional backend-specific metadata */
		[key: string]: any;
	};
}

/**
 * Knowledge graph error base class
 *
 * Base error class for all knowledge graph related errors.
 */
export class KnowledgeGraphError extends Error {
	constructor(
		override message: string,
		/** The operation that failed (e.g., 'addNode', 'query', 'connect') */
		public readonly operation: string,
		/** The underlying error that caused this error, if any */
		public override readonly cause?: Error
	) {
		super(message);
		this.name = 'KnowledgeGraphError';

		// Maintain proper stack trace for where the error was thrown
		if (Error.captureStackTrace) {
			Error.captureStackTrace(this, KnowledgeGraphError);
		}

		// Include cause in the error message if available
		if (cause) {
			this.message = `${message}: ${cause.message}`;
		}
	}
}

/**
 * Knowledge graph connection error
 *
 * Thrown when connection to the knowledge graph backend fails.
 */
export class KnowledgeGraphConnectionError extends KnowledgeGraphError {
	constructor(
		override message: string,
		/** The type of backend that failed to connect (e.g., 'neo4j', 'in-memory') */
		public readonly backendType: string,
		/** The underlying connection error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'connection', cause);
		this.name = 'KnowledgeGraphConnectionError';

		// Update message to include backend type
		this.message = `${backendType} connection failed: ${message}`;
	}
}

/**
 * Node not found error
 *
 * Thrown when a requested node cannot be found in the knowledge graph.
 */
export class NodeNotFoundError extends KnowledgeGraphError {
	constructor(
		override message: string,
		/** The ID of the node that was not found */
		public readonly nodeId: string,
		/** The underlying error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'get', cause);
		this.name = 'NodeNotFoundError';

		// Update message to include node ID
		this.message = `Node not found: ${nodeId} - ${message}`;
	}
}

/**
 * Edge not found error
 *
 * Thrown when a requested edge cannot be found in the knowledge graph.
 */
export class EdgeNotFoundError extends KnowledgeGraphError {
	constructor(
		override message: string,
		/** The ID of the edge that was not found */
		public readonly edgeId: string,
		/** The underlying error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'get', cause);
		this.name = 'EdgeNotFoundError';

		// Update message to include edge ID
		this.message = `Edge not found: ${edgeId} - ${message}`;
	}
}

/**
 * Invalid query error
 *
 * Thrown when a graph query is malformed or invalid.
 */
export class InvalidQueryError extends KnowledgeGraphError {
	constructor(
		override message: string,
		/** The invalid query that caused the error */
		public readonly query: string | GraphQuery,
		/** The underlying error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'query', cause);
		this.name = 'InvalidQueryError';

		// Update message to include query info
		this.message = `Invalid query: ${message}`;
	}
}

/**
 * Graph validation error
 *
 * Thrown when graph data fails validation (e.g., duplicate nodes, invalid relationships).
 */
export class GraphValidationError extends KnowledgeGraphError {
	constructor(
		override message: string,
		/** The type of validation that failed */
		public readonly validationType: 'node' | 'edge' | 'schema',
		/** The underlying error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'validation', cause);
		this.name = 'GraphValidationError';

		// Update message to include validation type
		this.message = `${validationType} validation failed: ${message}`;
	}
}

/**
 * Knowledge Graph Configuration Schemas
 *
 * Provides Zod schemas for validating knowledge graph backend configurations.
 * These schemas ensure type safety and runtime validation of configuration objects.
 *
 * @module knowledge_graph/config
 */

import { z } from 'zod';

/**
 * Base schema for all knowledge graph backends
 *
 * Contains common configuration options shared across all backend types.
 */
const BaseBackendSchema = z.object({
	/** Backend type identifier */
	type: z.string(),
	/** Connection timeout in milliseconds */
	timeout: z.number().min(1000).max(300000).default(30000),
	/** Maximum number of retry attempts for failed operations */
	maxRetries: z.number().min(0).max(10).default(3),
	/** Whether to enable connection pooling (if supported by backend) */
	enablePooling: z.boolean().default(true),
	/** Pool size for connections (if pooling is enabled) */
	poolSize: z.number().min(1).max(100).default(10),
});

/**
 * In-Memory Backend Configuration Schema
 *
 * Configuration for the in-memory knowledge graph backend.
 * Used for development, testing, and as a fallback option.
 *
 * @example
 * ```typescript
 * const config: InMemoryBackendConfig = {
 *   type: 'in-memory',
 *   maxNodes: 10000,
 *   maxEdges: 50000,
 *   enableIndexing: true
 * };
 * ```
 */
export const InMemoryBackendSchema = BaseBackendSchema.extend({
	type: z.literal('in-memory'),
	/** Maximum number of nodes to store in memory */
	maxNodes: z.number().min(100).max(1000000).default(10000),
	/** Maximum number of edges to store in memory */
	maxEdges: z.number().min(100).max(5000000).default(50000),
	/** Whether to enable indexing for faster lookups */
	enableIndexing: z.boolean().default(true),
	/** Whether to enable automatic garbage collection of orphaned nodes */
	enableGarbageCollection: z.boolean().default(false),
});

/**
 * Neo4j Backend Configuration Schema (without refinement)
 *
 * Configuration for connecting to a Neo4j graph database.
 * Supports both direct connection and URI-based connection.
 *
 * @example
 * ```typescript
 * // Direct connection
 * const config: Neo4jBackendConfig = {
 *   type: 'neo4j',
 *   host: 'localhost',
 *   port: 7687,
 *   username: 'neo4j',
 *   password: 'password',
 *   database: 'neo4j'
 * };
 *
 * // URI-based connection
 * const uriConfig: Neo4jBackendConfig = {
 *   type: 'neo4j',
 *   uri: 'neo4j://localhost:7687',
 *   username: 'neo4j',
 *   password: 'password'
 * };
 * ```
 */
export const Neo4jBackendSchema = BaseBackendSchema.extend({
	type: z.literal('neo4j'),
	/** Neo4j server hostname (alternative to uri) */
	host: z.string().optional(),
	/** Neo4j server port (alternative to uri) */
	port: z.number().min(1).max(65535).optional(),
	/** Complete Neo4j connection URI (alternative to host/port) */
	uri: z.string().url().optional(),
	/** Database username */
	username: z.string().min(1),
	/** Database password */
	password: z.string().min(1),
	/** Database name to connect to */
	database: z.string().min(1).default('neo4j'),
	/** Whether to use encrypted connection */
	encrypted: z.boolean().default(false),
	/** Whether to trust the server certificate (for encrypted connections) */
	trustServerCertificate: z.boolean().default(false),
	/** Maximum transaction retry time in milliseconds */
	maxTransactionRetryTime: z.number().min(1000).max(300000).default(30000),
	/** Connection acquisition timeout in milliseconds */
	connectionAcquisitionTimeout: z.number().min(1000).max(60000).default(60000),
	/** Maximum connection lifetime in milliseconds */
	maxConnectionLifetime: z.number().min(60000).max(3600000).default(3600000),
	/** Connection liveness check timeout in milliseconds */
	connectionLivenessCheckTimeout: z.number().min(1000).max(30000).default(30000),
});

/**
 * Union schema for all supported backend configurations
 */
export const BackendConfigSchema = z.discriminatedUnion('type', [
	InMemoryBackendSchema,
	Neo4jBackendSchema,
]);

/**
 * Knowledge Graph System Configuration Schema
 *
 * Top-level configuration for the knowledge graph system.
 * Includes backend configuration and system-level settings.
 *
 * @example
 * ```typescript
 * const config: KnowledgeGraphConfig = {
 *   type: 'neo4j',
 *   host: 'localhost',
 *   port: 7687,
 *   username: 'neo4j',
 *   password: 'password',
 *   database: 'knowledge',
 *   enableAutoIndexing: true,
 *   enableMetrics: true
 * };
 * ```
 */
export const KnowledgeGraphSchema = z.intersection(
	BackendConfigSchema,
	z.object({
		/** Whether to enable automatic indexing of node properties */
		enableAutoIndexing: z.boolean().default(true),
		/** Whether to enable performance metrics collection */
		enableMetrics: z.boolean().default(false),
		/** Whether to enable query caching (if supported by backend) */
		enableQueryCache: z.boolean().default(true),
		/** Query cache TTL in milliseconds */
		queryCacheTTL: z.number().min(1000).max(3600000).default(300000),
		/** Whether to enable schema validation for nodes and edges */
		enableSchemaValidation: z.boolean().default(true),
		/** Default batch size for bulk operations */
		defaultBatchSize: z.number().min(1).max(10000).default(1000),
	})
);

/**
 * Environment-based configuration schema
 *
 * Defines how to load knowledge graph configuration from environment variables.
 */
export const KnowledgeGraphEnvConfigSchema = z.object({
	/** Whether knowledge graph is enabled */
	KNOWLEDGE_GRAPH_ENABLED: z.boolean().default(false),
	/** Backend type */
	KNOWLEDGE_GRAPH_TYPE: z.enum(['neo4j', 'in-memory']).default('in-memory'),
	/** Neo4j host */
	KNOWLEDGE_GRAPH_HOST: z.string().optional(),
	/** Neo4j port */
	KNOWLEDGE_GRAPH_PORT: z.number().optional(),
	/** Neo4j URI */
	KNOWLEDGE_GRAPH_URI: z.string().optional(),
	/** Neo4j username */
	KNOWLEDGE_GRAPH_USERNAME: z.string().optional(),
	/** Neo4j password */
	KNOWLEDGE_GRAPH_PASSWORD: z.string().optional(),
	/** Neo4j database name */
	KNOWLEDGE_GRAPH_DATABASE: z.string().default('neo4j'),
});

// Export inferred types
export type InMemoryBackendConfig = z.infer<typeof InMemoryBackendSchema>;
export type Neo4jBackendConfig = z.infer<typeof Neo4jBackendSchema>;
export type BackendConfig = z.infer<typeof BackendConfigSchema>;
export type KnowledgeGraphConfig = z.infer<typeof KnowledgeGraphSchema>;
export type KnowledgeGraphEnvConfig = z.infer<typeof KnowledgeGraphEnvConfigSchema>;

/**
 * Parse and validate knowledge graph configuration
 *
 * @param config - Raw configuration object to validate
 * @returns Parsed and validated configuration
 * @throws {z.ZodError} If configuration is invalid
 *
 * @example
 * ```typescript
 * const config = parseKnowledgeGraphConfig({
 *   type: 'neo4j',
 *   host: 'localhost',
 *   port: 7687,
 *   username: 'neo4j',
 *   password: 'password'
 * });
 * ```
 */
export function parseKnowledgeGraphConfig(config: unknown): KnowledgeGraphConfig {
	return KnowledgeGraphSchema.parse(config);
}

/**
 * Parse knowledge graph configuration from environment variables
 *
 * @param env - Environment variables object (defaults to process.env)
 * @returns Parsed configuration or null if knowledge graph is disabled
 *
 * @example
 * ```typescript
 * const config = parseKnowledgeGraphConfigFromEnv();
 * if (config) {
 *   // Knowledge graph is enabled
 *   const graph = await createKnowledgeGraph(config);
 * }
 * ```
 */
export function parseKnowledgeGraphConfigFromEnv(
	env: Record<string, string | undefined> = process.env
): KnowledgeGraphConfig | null {
	// Parse environment configuration
	const envConfig = KnowledgeGraphEnvConfigSchema.parse({
		KNOWLEDGE_GRAPH_ENABLED: env.KNOWLEDGE_GRAPH_ENABLED === 'true',
		KNOWLEDGE_GRAPH_TYPE: env.KNOWLEDGE_GRAPH_TYPE || 'in-memory',
		KNOWLEDGE_GRAPH_HOST: env.KNOWLEDGE_GRAPH_HOST,
		KNOWLEDGE_GRAPH_PORT: env.KNOWLEDGE_GRAPH_PORT
			? parseInt(env.KNOWLEDGE_GRAPH_PORT, 10)
			: undefined,
		KNOWLEDGE_GRAPH_URI: env.KNOWLEDGE_GRAPH_URI,
		KNOWLEDGE_GRAPH_USERNAME: env.KNOWLEDGE_GRAPH_USERNAME,
		KNOWLEDGE_GRAPH_PASSWORD: env.KNOWLEDGE_GRAPH_PASSWORD,
		KNOWLEDGE_GRAPH_DATABASE: env.KNOWLEDGE_GRAPH_DATABASE || 'neo4j',
	});

	// Return null if knowledge graph is disabled
	if (!envConfig.KNOWLEDGE_GRAPH_ENABLED) {
		return null;
	}

	// Build configuration based on type
	if (envConfig.KNOWLEDGE_GRAPH_TYPE === 'neo4j') {
		const neo4jConfig: Partial<Neo4jBackendConfig> = {
			type: 'neo4j',
			database: envConfig.KNOWLEDGE_GRAPH_DATABASE,
		};

		// Add connection details
		if (envConfig.KNOWLEDGE_GRAPH_URI) {
			neo4jConfig.uri = envConfig.KNOWLEDGE_GRAPH_URI;
		} else if (envConfig.KNOWLEDGE_GRAPH_HOST && envConfig.KNOWLEDGE_GRAPH_PORT) {
			neo4jConfig.host = envConfig.KNOWLEDGE_GRAPH_HOST;
			neo4jConfig.port = envConfig.KNOWLEDGE_GRAPH_PORT;
		} else {
			throw new Error(
				'For Neo4j backend, either KNOWLEDGE_GRAPH_URI or both KNOWLEDGE_GRAPH_HOST and KNOWLEDGE_GRAPH_PORT must be provided'
			);
		}

		// Add authentication
		if (!envConfig.KNOWLEDGE_GRAPH_USERNAME || !envConfig.KNOWLEDGE_GRAPH_PASSWORD) {
			throw new Error(
				'For Neo4j backend, both KNOWLEDGE_GRAPH_USERNAME and KNOWLEDGE_GRAPH_PASSWORD must be provided'
			);
		}

		neo4jConfig.username = envConfig.KNOWLEDGE_GRAPH_USERNAME;
		neo4jConfig.password = envConfig.KNOWLEDGE_GRAPH_PASSWORD;

		// Validate the connection requirements
		if (!neo4jConfig.uri && (!neo4jConfig.host || !neo4jConfig.port)) {
			throw new Error(
				'For Neo4j backend, either KNOWLEDGE_GRAPH_URI or both KNOWLEDGE_GRAPH_HOST and KNOWLEDGE_GRAPH_PORT must be provided'
			);
		}

		return parseKnowledgeGraphConfig(neo4jConfig);
	} else {
		// In-memory configuration
		return parseKnowledgeGraphConfig({
			type: 'in-memory',
		});
	}
}

/**
 * Validate knowledge graph configuration without throwing
 *
 * @param config - Configuration object to validate
 * @returns Validation result with success flag and errors
 *
 * @example
 * ```typescript
 * const { success, data, errors } = validateKnowledgeGraphConfig(config);
 * if (success) {
 *   // Use data
 * } else {
 *   console.error('Configuration errors:', errors);
 * }
 * ```
 */
export function validateKnowledgeGraphConfig(config: unknown): {
	success: boolean;
	data?: KnowledgeGraphConfig;
	errors?: z.ZodError;
} {
	try {
		const data = parseKnowledgeGraphConfig(config);
		return { success: true, data };
	} catch (error) {
		if (error instanceof z.ZodError) {
			return { success: false, errors: error };
		}
		throw error;
	}
}

