/**
 * Query templates for common operations
 */
export const QUERY_TEMPLATES = {
	// Node operations
	CREATE_NODE: 'CREATE (n:{labels} {properties}) RETURN n',
	GET_NODE: 'MATCH (n) WHERE n.id = $id RETURN n',
	UPDATE_NODE: 'MATCH (n) WHERE n.id = $id SET n += $properties RETURN n',
	DELETE_NODE: 'MATCH (n) WHERE n.id = $id DETACH DELETE n',

	// Edge operations
	CREATE_EDGE:
		'MATCH (a), (b) WHERE a.id = $startId AND b.id = $endId CREATE (a)-[r:{type} {properties}]->(b) RETURN r',
	GET_EDGE: 'MATCH ()-[r]-() WHERE r.id = $id RETURN r',
	UPDATE_EDGE: 'MATCH ()-[r]-() WHERE r.id = $id SET r += $properties RETURN r',
	DELETE_EDGE: 'MATCH ()-[r]-() WHERE r.id = $id DELETE r',

	// Search operations
	FIND_NODES: 'MATCH (n:{labels}) WHERE {filters} RETURN n LIMIT $limit',
	FIND_EDGES: 'MATCH ()-[r:{type}]-() WHERE {filters} RETURN r LIMIT $limit',

	// Graph traversal
	GET_NEIGHBORS: 'MATCH (n)-[r:{types}]-(m) WHERE n.id = $id RETURN m, r LIMIT $limit',
	FIND_PATH:
		'MATCH path = shortestPath((a)-[*..{maxDepth}]-(b)) WHERE a.id = $startId AND b.id = $endId RETURN path',

	// Statistics
	COUNT_NODES: 'MATCH (n) RETURN count(n) as count',
	COUNT_EDGES: 'MATCH ()-[r]-() RETURN count(r) as count',
	GET_LABELS: 'CALL db.labels() YIELD label RETURN collect(label) as labels',
	GET_RELATIONSHIP_TYPES:
		'CALL db.relationshipTypes() YIELD relationshipType RETURN collect(relationshipType) as types',
} as const;

/**
 * Index templates for performance optimization
 */
export const INDEX_TEMPLATES = {
	// Node indexes
	NODE_ID_INDEX: 'CREATE INDEX node_id_index IF NOT EXISTS FOR (n:{label}) ON (n.id)',
	NODE_NAME_INDEX: 'CREATE INDEX node_name_index IF NOT EXISTS FOR (n:{label}) ON (n.name)',
	NODE_TYPE_INDEX: 'CREATE INDEX node_type_index IF NOT EXISTS FOR (n:{label}) ON (n.type)',

	// Edge indexes
	EDGE_ID_INDEX: 'CREATE INDEX edge_id_index IF NOT EXISTS FOR ()-[r:{type}]-() ON (r.id)',
	EDGE_TYPE_INDEX: 'CREATE INDEX edge_type_index IF NOT EXISTS FOR ()-[r:{type}]-() ON (r.type)',

	// Composite indexes
	NODE_COMPOUND_INDEX:
		'CREATE INDEX node_compound_index IF NOT EXISTS FOR (n:{label}) ON (n.id, n.type)',
	EDGE_COMPOUND_INDEX:
		'CREATE INDEX edge_compound_index IF NOT EXISTS FOR ()-[r:{type}]-() ON (r.id, r.type)',
} as const;

/**
 * Knowledge Graph Factory
 *
 * Factory functions for creating and initializing knowledge graph instances.
 * Provides a simplified API for common knowledge graph setup patterns.
 *
 * @module knowledge_graph/factory
 */

import { KnowledgeGraphManager } from './manager.js';
import type { KnowledgeGraph } from './backend/knowledge-graph.js';
import type { KnowledgeGraphConfig } from './config.js';
import { parseKnowledgeGraphConfigFromEnv } from './config.js';
import { createLogger } from '../logger/logger.js';
import { LOG_PREFIXES, BACKEND_TYPES, DEFAULTS } from './constants.js';
import { env } from '../env.js';

/**
 * Factory result containing both the manager and knowledge graph
 */
export interface KnowledgeGraphFactory {
	/** The knowledge graph manager instance for lifecycle control */
	manager: KnowledgeGraphManager;
	/** The connected knowledge graph ready for use */
	graph: KnowledgeGraph;
}

/**
 * Creates and connects knowledge graph backend
 *
 * This is the primary factory function for initializing the knowledge graph system.
 * It creates a KnowledgeGraphManager, connects to the configured backend, and
 * returns both the manager and the connected knowledge graph.
 *
 * @param config - Knowledge graph configuration
 * @returns Promise resolving to manager and connected knowledge graph
 * @throws {KnowledgeGraphConnectionError} If connection fails and no fallback is available
 *
 * @example
 * ```typescript
 * // Basic usage with Neo4j
 * const { manager, graph } = await createKnowledgeGraph({
 *   type: 'neo4j',
 *   host: 'localhost',
 *   port: 7687,
 *   username: 'neo4j',
 *   password: 'password',
 *   database: 'knowledge'
 * });
 *
 * // Use the knowledge graph
 * await graph.addNode({
 *   id: 'entity1',
 *   labels: ['Person'],
 *   properties: { name: 'John Doe' }
 * });
 *
 * // Cleanup when done
 * await manager.disconnect();
 * ```
 *
 * @example
 * ```typescript
 * // Development configuration with in-memory
 * const { manager, graph } = await createKnowledgeGraph({
 *   type: 'in-memory',
 *   maxNodes: 1000,
 *   maxEdges: 5000,
 *   enableIndexing: true
 * });
 * ```
 */
export async function createKnowledgeGraph(
	config: KnowledgeGraphConfig
): Promise<KnowledgeGraphFactory> {
	const logger = createLogger({ level: env.CIPHER_LOG_LEVEL });

	logger.debug(`${LOG_PREFIXES.FACTORY} Creating knowledge graph system`, {
		type: config.type,
		enableAutoIndexing: config.enableAutoIndexing,
		enableMetrics: config.enableMetrics,
	});

	// Create manager
	const manager = new KnowledgeGraphManager(config);

	try {
		// Connect to backend
		await manager.connect();
		const graph = manager.getGraph();

		if (!graph) {
			throw new Error('Failed to get knowledge graph instance after connection');
		}

		logger.info(`${LOG_PREFIXES.FACTORY} Knowledge graph system created successfully`, {
			type: manager.getInfo().backend.type,
			connected: manager.isConnected(),
			fallback: manager.getInfo().backend.fallback,
		});

		return { manager, graph };
	} catch (error) {
		// If connection fails, ensure cleanup
		await manager.disconnect().catch(() => {
			// Ignore disconnect errors during cleanup
		});

		logger.error(`${LOG_PREFIXES.FACTORY} Failed to create knowledge graph system`, {
			error: error instanceof Error ? error.message : String(error),
		});

		throw error;
	}
}

/**
 * Creates knowledge graph with default configuration
 *
 * Convenience function that creates knowledge graph with in-memory backend.
 * Useful for testing or development environments.
 *
 * @param maxNodes - Optional maximum nodes (default: 10000)
 * @param maxEdges - Optional maximum edges (default: 50000)
 * @returns Promise resolving to manager and connected knowledge graph
 *
 * @example
 * ```typescript
 * const { manager, graph } = await createDefaultKnowledgeGraph();
 * // Uses in-memory backend with default settings
 *
 * const { manager, graph } = await createDefaultKnowledgeGraph(1000, 5000);
 * // Uses in-memory backend with custom limits
 * ```
 */
export async function createDefaultKnowledgeGraph(
	maxNodes: number = DEFAULTS.MAX_NODES,
	maxEdges: number = DEFAULTS.MAX_EDGES
): Promise<KnowledgeGraphFactory> {
	return createKnowledgeGraph({
		type: BACKEND_TYPES.IN_MEMORY,
		timeout: 30000,
		maxRetries: 3,
		enablePooling: true,
		poolSize: 10,
		maxNodes,
		maxEdges,
		enableIndexing: true,
		enableGarbageCollection: false,
		enableAutoIndexing: true,
		enableMetrics: false,
		enableQueryCache: true,
		queryCacheTTL: 300000,
		enableSchemaValidation: true,
		defaultBatchSize: 1000,
	});
}

/**
 * Creates knowledge graph from environment variables
 *
 * Reads knowledge graph configuration from environment variables and creates
 * the knowledge graph system. Returns null if knowledge graph is disabled.
 *
 * Environment variables:
 * - KNOWLEDGE_GRAPH_ENABLED: Whether knowledge graph is enabled (true/false)
 * - KNOWLEDGE_GRAPH_TYPE: Backend type (neo4j, in-memory)
 * - KNOWLEDGE_GRAPH_HOST: Neo4j host (if using Neo4j)
 * - KNOWLEDGE_GRAPH_PORT: Neo4j port (if using Neo4j)
 * - KNOWLEDGE_GRAPH_URI: Neo4j URI (if using Neo4j)
 * - KNOWLEDGE_GRAPH_USERNAME: Neo4j username (if using Neo4j)
 * - KNOWLEDGE_GRAPH_PASSWORD: Neo4j password (if using Neo4j)
 * - KNOWLEDGE_GRAPH_DATABASE: Neo4j database name
 *
 * @returns Promise resolving to manager and connected knowledge graph, or null if disabled
 *
 * @example
 * ```typescript
 * // Set environment variables
 * process.env.KNOWLEDGE_GRAPH_ENABLED = 'true';
 * process.env.KNOWLEDGE_GRAPH_TYPE = 'neo4j';
 * process.env.KNOWLEDGE_GRAPH_HOST = 'localhost';
 * process.env.KNOWLEDGE_GRAPH_USERNAME = 'neo4j';
 * process.env.KNOWLEDGE_GRAPH_PASSWORD = 'password';
 *
 * const result = await createKnowledgeGraphFromEnv();
 * if (result) {
 *   const { manager, graph } = result;
 *   // Use the knowledge graph
 * } else {
 *   console.log('Knowledge graph is disabled');
 * }
 * ```
 */
export async function createKnowledgeGraphFromEnv(): Promise<KnowledgeGraphFactory | null> {
	const logger = createLogger({ level: env.CIPHER_LOG_LEVEL });

	// Get configuration from environment variables
	const config = parseKnowledgeGraphConfigFromEnv();

	if (!config) {
		logger.info(`${LOG_PREFIXES.FACTORY} Knowledge graph is disabled in environment`);
		return null;
	}

	logger.info(`${LOG_PREFIXES.FACTORY} Creating knowledge graph from environment`, {
		type: config.type,
		enableAutoIndexing: config.enableAutoIndexing,
		enableMetrics: config.enableMetrics,
	});

	return createKnowledgeGraph(config);
}

/**
 * Creates Neo4j knowledge graph with specific configuration
 *
 * Convenience function for creating Neo4j backend with commonly used settings.
 *
 * @param connectionConfig - Neo4j connection configuration
 * @param options - Optional system configuration
 * @returns Promise resolving to manager and connected knowledge graph
 *
 * @example
 * ```typescript
 * const { manager, graph } = await createNeo4jKnowledgeGraph({
 *   host: 'localhost',
 *   port: 7687,
 *   username: 'neo4j',
 *   password: 'password',
 *   database: 'knowledge'
 * });
 * ```
 *
 * @example
 * ```typescript
 * // Using URI connection
 * const { manager, graph } = await createNeo4jKnowledgeGraph({
 *   uri: 'neo4j://localhost:7687',
 *   username: 'neo4j',
 *   password: 'password',
 *   database: 'knowledge'
 * });
 * ```
 */
export async function createNeo4jKnowledgeGraph(
	connectionConfig: {
		uri?: string;
		host?: string;
		port?: number;
		username: string;
		password: string;
		database?: string;
		encrypted?: boolean;
		trustServerCertificate?: boolean;
		connectionTimeout?: number;
		maxPoolSize?: number;
	},
	options: {
		enableAutoIndexing?: boolean;
		enableMetrics?: boolean;
		enableQueryCache?: boolean;
		queryCacheTTL?: number;
		enableSchemaValidation?: boolean;
		defaultBatchSize?: number;
	} = {}
): Promise<KnowledgeGraphFactory> {
	const config: KnowledgeGraphConfig = {
		type: BACKEND_TYPES.NEO4J,
		timeout: connectionConfig.connectionTimeout ?? 30000,
		maxRetries: 3,
		enablePooling: true,
		poolSize: connectionConfig.maxPoolSize ?? 10,
		...connectionConfig,
		database: connectionConfig.database || 'neo4j',
		encrypted: connectionConfig.encrypted ?? false,
		trustServerCertificate: connectionConfig.trustServerCertificate ?? false,
		// Required Neo4j-specific properties with defaults
		maxTransactionRetryTime: 30000,
		connectionAcquisitionTimeout: 60000,
		maxConnectionLifetime: 3600000,
		connectionLivenessCheckTimeout: 30000,
		enableAutoIndexing: options.enableAutoIndexing ?? true,
		enableMetrics: options.enableMetrics ?? false,
		enableQueryCache: options.enableQueryCache ?? true,
		queryCacheTTL: options.queryCacheTTL ?? 300000,
		enableSchemaValidation: options.enableSchemaValidation ?? true,
		defaultBatchSize: options.defaultBatchSize ?? 1000,
	};

	return createKnowledgeGraph(config);
}

/**
 * Creates in-memory knowledge graph with specific configuration
 *
 * Convenience function for creating in-memory backend with commonly used settings.
 *
 * @param options - Optional configuration options
 * @returns Promise resolving to manager and connected knowledge graph
 *
 * @example
 * ```typescript
 * const { manager, graph } = await createInMemoryKnowledgeGraph({
 *   maxNodes: 5000,
 *   maxEdges: 25000,
 *   enableIndexing: true,
 *   enableGarbageCollection: true
 * });
 * ```
 */
export async function createInMemoryKnowledgeGraph(
	options: {
		maxNodes?: number;
		maxEdges?: number;
		enableIndexing?: boolean;
		enableGarbageCollection?: boolean;
		enableAutoIndexing?: boolean;
		enableMetrics?: boolean;
		enableQueryCache?: boolean;
		queryCacheTTL?: number;
		enableSchemaValidation?: boolean;
		defaultBatchSize?: number;
	} = {}
): Promise<KnowledgeGraphFactory> {
	const config: KnowledgeGraphConfig = {
		type: BACKEND_TYPES.IN_MEMORY,
		timeout: 30000,
		maxRetries: 3,
		enablePooling: true,
		poolSize: 10,
		maxNodes: options.maxNodes ?? DEFAULTS.MAX_NODES,
		maxEdges: options.maxEdges ?? DEFAULTS.MAX_EDGES,
		enableIndexing: options.enableIndexing ?? true,
		enableGarbageCollection: options.enableGarbageCollection ?? false,
		enableAutoIndexing: options.enableAutoIndexing ?? true,
		enableMetrics: options.enableMetrics ?? false,
		enableQueryCache: options.enableQueryCache ?? true,
		queryCacheTTL: options.queryCacheTTL ?? 300000,
		enableSchemaValidation: options.enableSchemaValidation ?? true,
		defaultBatchSize: options.defaultBatchSize ?? 1000,
	};

	return createKnowledgeGraph(config);
}

/**
 * Get knowledge graph configuration from environment variables
 *
 * Returns the configuration object that would be used by createKnowledgeGraphFromEnv
 * without actually creating the knowledge graph. Useful for debugging and validation.
 *
 * @returns Knowledge graph configuration based on environment variables, or null if disabled
 *
 * @example
 * ```typescript
 * const config = getKnowledgeGraphConfigFromEnv();
 * if (config) {
 *   console.log('Knowledge graph configuration:', config);
 *   // Then use the config to create the graph
 *   const { manager, graph } = await createKnowledgeGraph(config);
 * } else {
 *   console.log('Knowledge graph is disabled');
 * }
 * ```
 */
export function getKnowledgeGraphConfigFromEnv(): KnowledgeGraphConfig | null {
	return parseKnowledgeGraphConfigFromEnv();
}

/**
 * Type guard to check if an object is a KnowledgeGraphFactory
 *
 * @param obj - Object to check
 * @returns True if the object is a KnowledgeGraphFactory
 *
 * @example
 * ```typescript
 * const factory = await createKnowledgeGraph(config);
 * if (isKnowledgeGraphFactory(factory)) {
 *   // TypeScript knows factory has manager and graph properties
 *   console.log('Manager connected:', factory.manager.isConnected());
 * }
 * ```
 */
export function isKnowledgeGraphFactory(obj: unknown): obj is KnowledgeGraphFactory {
	return (
		typeof obj === 'object' &&
		obj !== null &&
		'manager' in obj &&
		'graph' in obj &&
		typeof (obj as any).manager === 'object' &&
		typeof (obj as any).graph === 'object'
	);
}

/**
 * Check if Neo4j configuration is available in environment
 *
 * @returns True if Neo4j connection can be configured from environment variables
 *
 * @example
 * ```typescript
 * if (isNeo4jConfigAvailable()) {
 *   console.log('Neo4j configuration is available');
 *   const factory = await createKnowledgeGraphFromEnv();
 * } else {
 *   console.log('Using fallback configuration');
 *   const factory = await createDefaultKnowledgeGraph();
 * }
 * ```
 */
export function isNeo4jConfigAvailable(): boolean {
	return !!(
		process.env.KNOWLEDGE_GRAPH_ENABLED === 'true' &&
		process.env.KNOWLEDGE_GRAPH_TYPE === 'neo4j' &&
		process.env.KNOWLEDGE_GRAPH_USERNAME &&
		process.env.KNOWLEDGE_GRAPH_PASSWORD &&
		(process.env.KNOWLEDGE_GRAPH_URI ||
			(process.env.KNOWLEDGE_GRAPH_HOST && process.env.KNOWLEDGE_GRAPH_PORT))
	);
}

/**
 * Check if knowledge graph is enabled in environment
 *
 * @returns True if knowledge graph is enabled in environment variables
 *
 * @example
 * ```typescript
 * if (isKnowledgeGraphEnabled()) {
 *   const factory = await createKnowledgeGraphFromEnv();
 *   // Knowledge graph is available
 * } else {
 *   // Skip knowledge graph functionality
 * }
 * ```
 */
export function isKnowledgeGraphEnabled(): boolean {
	return process.env.KNOWLEDGE_GRAPH_ENABLED === 'true';
}

export * from './types.js';
export * from './config.js';
export * from './constants.js';
export * from './factory.js';
export * from './manager.js';
export * from './backend/knowledge-graph.js';
export * from './backend/neo4j.js';
export * from './backend/in-memory.js';
export * from './backend/types.js';

/**
 * Knowledge Graph Manager
 *
 * Manages the lifecycle of knowledge graph backends and provides a unified interface
 * for knowledge graph operations. Handles connection management, health checks,
 * fallback scenarios, and statistics tracking.
 *
 * @module knowledge_graph/manager
 */

import { Logger, createLogger } from '../logger/logger.js';
import type { KnowledgeGraph } from './backend/knowledge-graph.js';
import { KnowledgeGraphConnectionError } from './backend/types.js';
import type { KnowledgeGraphConfig } from './config.js';
import { BACKEND_TYPES, DEFAULTS, ERROR_MESSAGES, LOG_PREFIXES, TIMEOUTS } from './constants.js';

/**
 * Health check result for knowledge graph
 */
export interface HealthCheckResult {
	backend: boolean;
	overall: boolean;
	details?: {
		backend?: { status: string; latency?: number; error?: string };
	};
}

/**
 * Knowledge graph information for monitoring
 */
export interface KnowledgeGraphInfo {
	connected: boolean;
	backend: {
		type: string;
		connected: boolean;
		fallback: boolean;
	};
	connectionAttempts: number;
	lastError: string | undefined;
}

/**
 * Statistics for knowledge graph operations
 */
export interface KnowledgeGraphStats {
	totalNodes: number;
	totalEdges: number;
	totalQueries: number;
	totalOperations: number;
	averageQueryTime: number;
	lastOperationTime: number;
	connectionUptime: number;
}

/**
 * Knowledge Graph Manager
 *
 * Provides a high-level interface for managing knowledge graph operations.
 * Handles backend lifecycle, connection management, and error recovery.
 *
 * @example
 * ```typescript
 * const manager = new KnowledgeGraphManager(config);
 * await manager.connect();
 *
 * const graph = manager.getGraph();
 * await graph.addNode({
 *   id: 'node1',
 *   labels: ['Function'],
 *   properties: { name: 'myFunction' }
 * });
 * ```
 */
export class KnowledgeGraphManager {
	private graph: KnowledgeGraph | undefined;
	private connected = false;
	private readonly config: KnowledgeGraphConfig;
	private readonly logger: Logger;

	// Connection tracking
	private connectionAttempts = 0;
	private lastConnectionError?: Error;
	private connectionStartTime = 0;

	// Backend metadata
	private backendMetadata = {
		type: 'unknown',
		connected: false,
		fallback: false,
		lastHealthCheck: 0,
	};

	// Statistics
	private stats: KnowledgeGraphStats = {
		totalNodes: 0,
		totalEdges: 0,
		totalQueries: 0,
		totalOperations: 0,
		averageQueryTime: 0,
		lastOperationTime: 0,
		connectionUptime: 0,
	};

	// Module loading cache
	private static neo4jModule?: any;
	private static inMemoryModule?: any;

	// Health check configuration
	private readonly healthCheckInterval = TIMEOUTS.HEALTH_CHECK;
	private healthCheckTimer?: NodeJS.Timeout;

	/**
	 * Creates a new Knowledge Graph Manager
	 *
	 * @param config - Knowledge graph configuration
	 */
	constructor(config: KnowledgeGraphConfig) {
		this.config = config;
		this.logger = createLogger({
			level: 'debug',
		});

		this.logger.debug(`${LOG_PREFIXES.MANAGER} Initialized with backend type: ${config.type}`);
	}

	/**
	 * Get the current configuration
	 */
	public getConfig(): Readonly<KnowledgeGraphConfig> {
		return this.config;
	}

	/**
	 * Get manager information for monitoring
	 */
	public getInfo(): KnowledgeGraphInfo {
		return {
			connected: this.connected,
			backend: {
				type: this.backendMetadata.type,
				connected: this.backendMetadata.connected,
				fallback: this.backendMetadata.fallback,
			},
			connectionAttempts: this.connectionAttempts,
			lastError: this.lastConnectionError?.message,
		};
	}

	/**
	 * Get the knowledge graph instance
	 */
	public getGraph(): KnowledgeGraph | null {
		if (!this.connected || !this.graph) {
			return null;
		}
		return this.graph;
	}

	/**
	 * Check if the manager is connected and ready
	 */
	public isConnected(): boolean {
		return this.connected && this.graph?.isConnected() === true;
	}

	/**
	 * Connect to the knowledge graph backend
	 */
	public async connect(): Promise<KnowledgeGraph> {
		if (this.connected && this.graph) {
			this.logger.debug(`${LOG_PREFIXES.MANAGER} Already connected`);
			return this.graph;
		}

		this.connectionAttempts++;
		this.connectionStartTime = Date.now();

		try {
			this.logger.info(`${LOG_PREFIXES.MANAGER} Connecting to ${this.config.type} backend...`);

			// Create backend instance
			this.graph = await this.createBackend();

			// Connect to backend
			await this.graph.connect();

			// Verify connection
			if (!this.graph.isConnected()) {
				throw new KnowledgeGraphConnectionError(
					'Backend reports as not connected after connection attempt',
					this.config.type
				);
			}

			// Update metadata
			this.backendMetadata = {
				type: this.graph.getBackendType(),
				connected: true,
				fallback: false,
				lastHealthCheck: Date.now(),
			};

			this.connected = true;
			delete this.lastConnectionError;

			// Start health monitoring
			this.startHealthMonitoring();

			// Load initial statistics
			await this.updateStatistics();

			this.logger.info(
				`${LOG_PREFIXES.MANAGER} Connected successfully to ${this.backendMetadata.type} backend`
			);

			return this.graph;
		} catch (error) {
			this.lastConnectionError = error as Error;
			this.backendMetadata.connected = false;

			this.logger.error(`${LOG_PREFIXES.MANAGER} Connection failed:`, error);

			// Try fallback to in-memory backend if configured
			if (this.config.type !== BACKEND_TYPES.IN_MEMORY) {
				this.logger.warn(`${LOG_PREFIXES.MANAGER} Attempting fallback to in-memory backend...`);

				try {
					this.graph = await this.createInMemoryFallback();
					await this.graph.connect();

					this.backendMetadata = {
						type: this.graph.getBackendType(),
						connected: true,
						fallback: true,
						lastHealthCheck: Date.now(),
					};

					this.connected = true;
					this.startHealthMonitoring();

					this.logger.warn(`${LOG_PREFIXES.MANAGER} Connected to fallback in-memory backend`);
					return this.graph;
				} catch (fallbackError) {
					this.logger.error(
						`${LOG_PREFIXES.MANAGER} Fallback connection also failed:`,
						fallbackError
					);
				}
			}

			throw error;
		}
	}

	/**
	 * Disconnect from the knowledge graph backend
	 */
	public async disconnect(): Promise<void> {
		if (!this.connected || !this.graph) {
			this.logger.debug(`${LOG_PREFIXES.MANAGER} Already disconnected`);
			return;
		}

		try {
			// Stop health monitoring
			this.stopHealthMonitoring();

			// Update uptime
			if (this.connectionStartTime > 0) {
				this.stats.connectionUptime = Date.now() - this.connectionStartTime;
			}

			// Disconnect from backend
			await this.graph.disconnect();

			// Reset state
			this.graph = undefined;
			this.connected = false;
			this.backendMetadata.connected = false;

			this.logger.info(`${LOG_PREFIXES.MANAGER} Disconnected successfully`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.MANAGER} Error during disconnect:`, error);
			throw error;
		}
	}

	/**
	 * Perform health check on the knowledge graph backend
	 */
	public async healthCheck(): Promise<HealthCheckResult> {
		const startTime = Date.now();
		let backendHealth = false;
		let backendDetails: any = {};

		try {
			if (this.graph && this.connected) {
				// Test basic connectivity
				backendHealth = this.graph.isConnected();

				if (backendHealth) {
					// Test basic operation
					await this.graph.getStatistics();
					backendDetails = {
						status: 'healthy',
						latency: Date.now() - startTime,
					};
				} else {
					backendDetails = {
						status: 'disconnected',
						error: 'Backend reports as not connected',
					};
				}
			} else {
				backendDetails = {
					status: 'not_initialized',
					error: 'Knowledge graph not initialized',
				};
			}
		} catch (error) {
			backendHealth = false;
			backendDetails = {
				status: 'error',
				error: (error as Error).message,
				latency: Date.now() - startTime,
			};
		}

		// Update last health check time
		this.backendMetadata.lastHealthCheck = Date.now();

		const result: HealthCheckResult = {
			backend: backendHealth,
			overall: backendHealth,
			details: {
				backend: backendDetails,
			},
		};

		// this.logger.debug(`${LOG_PREFIXES.MANAGER} Health check completed:`, result);

		return result;
	}

	/**
	 * Get current statistics
	 */
	public getStats(): KnowledgeGraphStats {
		return { ...this.stats };
	}

	/**
	 * Reset statistics
	 */
	public resetStats(): void {
		this.stats = {
			totalNodes: 0,
			totalEdges: 0,
			totalQueries: 0,
			totalOperations: 0,
			averageQueryTime: 0,
			lastOperationTime: 0,
			connectionUptime: this.connectionStartTime > 0 ? Date.now() - this.connectionStartTime : 0,
		};

		this.logger.debug(`${LOG_PREFIXES.MANAGER} Statistics reset`);
	}

	/**
	 * Execute a knowledge graph operation with statistics tracking
	 */
	public async executeOperation<T>(
		operation: (graph: KnowledgeGraph) => Promise<T>,
		operationType: 'read' | 'write' | 'query' = 'read'
	): Promise<T> {
		if (!this.graph || !this.connected) {
			throw new KnowledgeGraphConnectionError(
				ERROR_MESSAGES.NOT_CONNECTED,
				this.backendMetadata.type
			);
		}

		const startTime = Date.now();

		try {
			const result = await operation(this.graph);

			// Update statistics
			const executionTime = Date.now() - startTime;
			this.updateOperationStats(operationType, executionTime, true);

			return result;
		} catch (error) {
			// Update error statistics
			const executionTime = Date.now() - startTime;
			this.updateOperationStats(operationType, executionTime, false);

			this.logger.error(`${LOG_PREFIXES.MANAGER} Operation failed:`, error);
			throw error;
		}
	}

	/**
	 * Get backend-specific debug information
	 */
	public getDebugInfo(): Record<string, any> {
		return {
			config: this.config,
			backendMetadata: this.backendMetadata,
			connectionAttempts: this.connectionAttempts,
			lastConnectionError: this.lastConnectionError?.message,
			stats: this.stats,
			connected: this.connected,
			healthMonitoring: !!this.healthCheckTimer,
		};
	}

	// Private methods

	private async createBackend(): Promise<KnowledgeGraph> {
		switch (this.config.type) {
			case BACKEND_TYPES.NEO4J:
				return this.createNeo4jBackend();
			case BACKEND_TYPES.IN_MEMORY:
				return this.createInMemoryBackend();
			default:
				throw new KnowledgeGraphConnectionError(
					`Unsupported backend type: ${(this.config as any).type}`,
					(this.config as any).type
				);
		}
	}

	private async createNeo4jBackend(): Promise<KnowledgeGraph> {
		try {
			// Lazy load Neo4j module
			if (!KnowledgeGraphManager.neo4jModule) {
				this.logger.debug(`${LOG_PREFIXES.MANAGER} Loading Neo4j backend module...`);
				const module = await import('./backend/neo4j.js');
				KnowledgeGraphManager.neo4jModule = module;
			}

			const { Neo4jBackend } = KnowledgeGraphManager.neo4jModule;
			return new Neo4jBackend(this.config);
		} catch (error) {
			throw new KnowledgeGraphConnectionError(
				`Failed to create Neo4j backend: ${(error as Error).message}`,
				BACKEND_TYPES.NEO4J,
				error as Error
			);
		}
	}

	private async createInMemoryBackend(): Promise<KnowledgeGraph> {
		try {
			// Lazy load in-memory module
			if (!KnowledgeGraphManager.inMemoryModule) {
				this.logger.debug(`${LOG_PREFIXES.MANAGER} Loading in-memory backend module...`);
				const module = await import('./backend/in-memory.js');
				KnowledgeGraphManager.inMemoryModule = module;
			}

			const { InMemoryBackend } = KnowledgeGraphManager.inMemoryModule;
			return new InMemoryBackend(this.config);
		} catch (error) {
			throw new KnowledgeGraphConnectionError(
				`Failed to create in-memory backend: ${(error as Error).message}`,
				BACKEND_TYPES.IN_MEMORY,
				error as Error
			);
		}
	}

	private async createInMemoryFallback(): Promise<KnowledgeGraph> {
		// Create fallback in-memory configuration
		const fallbackConfig = {
			...this.config,
			type: BACKEND_TYPES.IN_MEMORY,
			maxNodes: DEFAULTS.MAX_NODES,
			maxEdges: DEFAULTS.MAX_EDGES,
			enableIndexing: true,
			enableGarbageCollection: false,
		};

		if (!KnowledgeGraphManager.inMemoryModule) {
			const module = await import('./backend/in-memory.js');
			KnowledgeGraphManager.inMemoryModule = module;
		}

		const { InMemoryBackend } = KnowledgeGraphManager.inMemoryModule;
		return new InMemoryBackend(fallbackConfig);
	}

	private async updateStatistics(): Promise<void> {
		if (!this.graph || !this.connected) {
			return;
		}

		try {
			const graphStats = await this.graph.getStatistics();
			this.stats.totalNodes = graphStats.nodeCount;
			this.stats.totalEdges = graphStats.edgeCount;

			// Update connection uptime
			if (this.connectionStartTime > 0) {
				this.stats.connectionUptime = Date.now() - this.connectionStartTime;
			}
		} catch (error) {
			console.log(error);
			this.logger.warn(`${LOG_PREFIXES.MANAGER} Failed to update statistics:`, error);
		}
	}

	private updateOperationStats(
		operationType: 'read' | 'write' | 'query',
		executionTime: number,
		success: boolean
	): void {
		this.stats.totalOperations++;
		this.stats.lastOperationTime = Date.now();

		if (operationType === 'query') {
			this.stats.totalQueries++;

			// Update average query time
			const totalQueryTime = this.stats.averageQueryTime * (this.stats.totalQueries - 1);
			this.stats.averageQueryTime = (totalQueryTime + executionTime) / this.stats.totalQueries;
		}

		if (success) {
			this.logger.debug(
				`${LOG_PREFIXES.MANAGER} ${operationType} operation completed in ${executionTime}ms`
			);
		} else {
			this.logger.warn(
				`${LOG_PREFIXES.MANAGER} ${operationType} operation failed after ${executionTime}ms`
			);
		}
	}

	private startHealthMonitoring(): void {
		if (this.healthCheckTimer) {
			this.stopHealthMonitoring();
		}

		this.healthCheckTimer = setInterval(async () => {
			try {
				await this.healthCheck();
			} catch (error) {
				this.logger.warn(`${LOG_PREFIXES.MANAGER} Health check failed:`, error);
			}
		}, this.healthCheckInterval);

		this.logger.debug(
			`${LOG_PREFIXES.MANAGER} Started health monitoring (interval: ${this.healthCheckInterval}ms)`
		);
	}

	private stopHealthMonitoring(): void {
		if (this.healthCheckTimer) {
			clearInterval(this.healthCheckTimer);
			delete this.healthCheckTimer;
			this.logger.debug(`${LOG_PREFIXES.MANAGER} Stopped health monitoring`);
		}
	}

	/**
	 * Create a new manager instance from environment configuration
	 */
	public static async createFromEnv(): Promise<KnowledgeGraphManager | null> {
		const { parseKnowledgeGraphConfigFromEnv } = await import('./config.js');
		const config = parseKnowledgeGraphConfigFromEnv();

		if (!config) {
			return null;
		}

		return new KnowledgeGraphManager(config);
	}

	/**
	 * Create a default in-memory manager for testing/development
	 */
	public static createDefault(): KnowledgeGraphManager {
		const config = {
			type: BACKEND_TYPES.IN_MEMORY,
			maxNodes: DEFAULTS.MAX_NODES,
			maxEdges: DEFAULTS.MAX_EDGES,
			enableIndexing: true,
			enableGarbageCollection: false,
			enableAutoIndexing: true,
			enableMetrics: false,
			enableQueryCache: false,
			queryCacheTTL: DEFAULTS.QUERY_CACHE_TTL,
			enableSchemaValidation: true,
			defaultBatchSize: DEFAULTS.BATCH_SIZE,
			timeout: DEFAULTS.CONNECTION_TIMEOUT,
			maxRetries: DEFAULTS.MAX_RETRIES,
			enablePooling: true,
			poolSize: DEFAULTS.POOL_SIZE,
		};

		return new KnowledgeGraphManager(config);
	}
}

/**
 * Knowledge Graph Module Public API
 *
 * This module re-exports all the necessary types and interfaces for the knowledge graph system.
 * It provides a simplified, clean API surface for consumers of the knowledge graph module.
 *
 * The knowledge graph system architecture:
 * - Single backend design for graph operations and traversal
 * - Multiple backend implementations: Neo4j, In-Memory, etc.
 * - Consistent API across different backend types
 * - Strong type safety with TypeScript and runtime validation with Zod
 *
 * @module knowledge_graph
 *
 * @example
 * ```typescript
 * import type { KnowledgeGraphConfig, KnowledgeGraph } from './knowledge_graph/types.js';
 *
 * // Configure knowledge graph
 * const config: KnowledgeGraphConfig = {
 *   type: 'neo4j',
 *   host: 'localhost',
 *   port: 7687,
 *   username: 'neo4j',
 *   password: 'password',
 *   database: 'neo4j'
 * };
 *
 * // Use knowledge graph
 * const graph: KnowledgeGraph = createKnowledgeGraph(config);
 * ```
 */

/**
 * Re-export simplified knowledge graph types
 *
 * These exports provide the complete type system needed to work with
 * the knowledge graph module without exposing internal implementation details.
 */
export type {
	// Core interfaces
	KnowledgeGraph, // Interface for knowledge graph implementations
	GraphNode, // Node structure in the graph
	GraphEdge, // Edge/relationship structure in the graph
	GraphQuery, // Query structure for graph operations
	GraphResult, // Search/query result structure
	NodeFilters, // Metadata filters for node search
	EdgeFilters, // Metadata filters for edge search

	// Configuration types
	BackendConfig, // Union type for all backend configurations
	KnowledgeGraphConfig, // Top-level knowledge graph system configuration
} from './backend/types.js';

/**
 * Re-export configuration schemas
 */
export {
	// Configuration parsers and validators
	parseKnowledgeGraphConfig,
	validateKnowledgeGraphConfig,
} from './config.js';

/**
 * Re-export factory functions
 */
export {
	createKnowledgeGraph,
	createDefaultKnowledgeGraph,
	createKnowledgeGraphFromEnv,
} from './factory.js';

/**
 * Re-export manager
 */
export { KnowledgeGraphManager } from './manager.js';

/**
 * Re-export constants
 */
export { BACKEND_TYPES, DEFAULTS, ERROR_MESSAGES } from './constants.js';

