		getClient: vi.fn().mockReturnValue({}),
		getServerInfo: vi.fn().mockReturnValue({
			spawned: false,
			pid: null,
			command: null,
			originalArgs: null,
			resolvedArgs: null,
			env: null,
			alias: null,
		}),
		getConnectedClient: vi.fn().mockResolvedValue({}),
		connect: vi.fn(),
		disconnect: vi.fn(),
	};
}

