	describe('Connection Management', () => {
		it('should initialize from config with mixed connection modes', async () => {
			const serverConfigs: ServerConfigs = {
				strictServer: {
					type: 'stdio',
					command: 'node',
					args: ['strict-server.js'],
					env: {},
					timeout: 30000,
					connectionMode: 'strict',
				},
				lenientServer: {
					type: 'stdio',
					command: 'node',
					args: ['lenient-server.js'],
					env: {},
					timeout: 30000,
					connectionMode: 'lenient',
				},
			};

			mockClient.connect
				.mockResolvedValueOnce({}) // strictServer succeeds
				.mockRejectedValueOnce(new Error('Connection failed')); // lenientServer fails

			// Should not throw since lenient server can fail
			await expect(manager.initializeFromConfig(serverConfigs)).resolves.not.toThrow();

			expect(mockClient.connect).toHaveBeenCalledTimes(2);
		});

		it('should fail when strict server cannot connect', async () => {
			const serverConfigs: ServerConfigs = {
				strictServer: {
					type: 'stdio',
					command: 'node',
					args: ['strict-server.js'],
					env: {},
					timeout: 30000,
					connectionMode: 'strict',
				},
			};

			mockClient.connect.mockRejectedValue(new Error('Connection failed'));

			await expect(manager.initializeFromConfig(serverConfigs)).rejects.toThrow(
				ERROR_MESSAGES.MISSING_REQUIRED_SERVERS
			);
		});

		it('should connect to a new server successfully', async () => {
			const config: McpServerConfig = {
				type: 'stdio',
				command: 'node',
				args: ['test-server.js'],
				env: {},
				timeout: 30000,
				connectionMode: 'lenient',
			};

			mockClient.connect.mockResolvedValue({});

			await manager.connectServer('test-server', config);

			expect(mockClient.connect).toHaveBeenCalledWith(config, 'test-server');

			const clients = manager.getClients();
			expect(clients.has('test-server')).toBe(true);
		});

		it('should handle connection failures for lenient servers', async () => {
			const config: McpServerConfig = {
				type: 'stdio',
				command: 'node',
				args: ['failing-server.js'],
				env: {},
				timeout: 30000,
				connectionMode: 'lenient',
			};

			mockClient.connect.mockRejectedValue(new Error('Connection failed'));

			// Should not throw for lenient servers
			await expect(manager.connectServer('failing-server', config)).resolves.not.toThrow();

			const failedConnections = manager.getFailedConnections();
			expect(failedConnections['failing-server']).toBe('Connection failed');
		});

		it('should remove a client successfully', async () => {
			await registerAndConnectClient('test-client', mockClient);

			await manager.removeClient('test-client');

			expect(mockClient.disconnect).toHaveBeenCalled();

			const clients = manager.getClients();
			expect(clients.has('test-client')).toBe(false);
		});

		it('should handle removal of non-existent client gracefully', async () => {
			await expect(manager.removeClient('non-existent-client')).resolves.not.toThrow();
		});

		it('should disconnect all clients', async () => {
			await registerAndConnectClient('client1', mockClient);
			const client2 = { ...mockClient, disconnect: vi.fn().mockResolvedValue(undefined) };
			await registerAndConnectClient('client2', client2);

			await manager.disconnectAll();

			expect(mockClient.disconnect).toHaveBeenCalled();
			expect(client2.disconnect).toHaveBeenCalled();

			const clients = manager.getClients();
			expect(clients.size).toBe(0);
		});
	});

	describe('Error Handling', () => {
		beforeEach(async () => {
			await registerAndConnectClient('client1', mockClient);
		});

		it('should handle client failures gracefully when getting tools', async () => {
			const client2 = { ...mockClient, getTools: vi.fn() };
			await registerAndConnectClient('client2', client2);

			// client1 succeeds, client2 fails
			mockClient.getTools.mockResolvedValue({
				tool1: { description: 'Tool 1', parameters: { type: 'object', properties: {} } },
			});
			client2.getTools.mockRejectedValue(new Error('Client failed'));

			const tools = await manager.getAllTools();

			expect(tools).toHaveProperty('tool1');
			expect(Object.keys(tools)).toHaveLength(1);
		});

		it('should throw error when all clients fail to get tools', async () => {
			// Ensure the client is connected but getTools fails
			mockClient.getTools.mockRejectedValue(new Error('All clients failed'));

			await expect(manager.getAllTools()).rejects.toThrow(
				'Failed to retrieve tools from all clients'
			);
		});

		it('should handle cache refresh when tool client not found', async () => {
			// Test that when a tool is not found, the manager attempts to refresh the cache
			// by calling getAllTools again before giving up

			// Execute tool that doesn't exist - should trigger cache refresh and then throw
			await expect(manager.executeTool('non-existent-tool', {})).rejects.toThrow(
				ERROR_MESSAGES.NO_CLIENT_FOR_TOOL
			);

			// Verify that getTools was called more than once (initial connection + cache refresh)
			expect(mockClient.getTools).toHaveBeenCalled();
		});
	});

	describe('Cache Management', () => {
		beforeEach(async () => {
			await registerAndConnectClient('client1', mockClient);
		});

		it('should cache tool lookups for O(1) performance', async () => {
			const mockTools: ToolSet = {
				'cached-tool': {
					description: 'A cached tool',
					parameters: { type: 'object', properties: {} },
				},
			};

			mockClient.getTools.mockResolvedValue(mockTools);

			// First call populates cache
			await manager.getAllTools();

			// Second call should use cache (client should be found without additional getTools call)
			const client1 = manager.getToolClient('cached-tool');
			const client2 = manager.getToolClient('cached-tool');

			expect(client1).toBe(mockClient);
			expect(client2).toBe(mockClient);
			expect(mockClient.getTools).toHaveBeenCalled();
		});

		it('should clear cache when client is removed', async () => {
			const mockTools: ToolSet = {
				'tool-to-remove': {
					description: 'Tool that will be removed',
					parameters: { type: 'object', properties: {} },
				},
			};

			mockClient.getTools.mockResolvedValue(mockTools);
			await manager.getAllTools(); // Populate cache

			// Tool should be found
			expect(manager.getToolClient('tool-to-remove')).toBe(mockClient);

			// Remove client
			await manager.removeClient('client1');

			// Tool should no longer be found
			expect(manager.getToolClient('tool-to-remove')).toBeUndefined();
		});
	});

	describe('Concurrent Operations', () => {
		it('should handle multiple concurrent tool executions', async () => {
			await registerAndConnectClient('client1', mockClient);

			const mockTools: ToolSet = {
				'concurrent-tool': {
					description: 'Tool for concurrent testing',
					parameters: { type: 'object', properties: {} },
				},
			};

			mockClient.getTools.mockResolvedValue(mockTools);
			mockClient.callTool.mockImplementation((name: string, args: any) =>
				Promise.resolve({ result: `executed-${name}-${args.id}` })
			);

			await manager.getAllTools(); // Populate cache

			// Execute multiple tools concurrently
			const promises = Array.from({ length: 5 }, (_, i) =>
				manager.executeTool('concurrent-tool', { id: i })
			);

			const results = await Promise.all(promises);

			expect(results).toHaveLength(5);
			results.forEach((result, index) => {
				expect(result.result).toBe(`executed-concurrent-tool-${index}`);
			});
			expect(mockClient.callTool).toHaveBeenCalledTimes(5);
		});

		it('should handle concurrent initialization of multiple servers', async () => {
			const serverConfigs: ServerConfigs = {
				server1: {
					type: 'stdio',
					command: 'node',
					args: ['server1.js'],
					env: {},
					timeout: 30000,
					connectionMode: 'lenient',
				},
				server2: {
					type: 'stdio',
					command: 'node',
					args: ['server2.js'],
					env: {},
					timeout: 30000,
					connectionMode: 'lenient',
				},
				server3: {
					type: 'stdio',
					command: 'node',
					args: ['server3.js'],
					env: {},
					timeout: 30000,
					connectionMode: 'lenient',
				},
			};

			mockClient.connect.mockResolvedValue({});

			await manager.initializeFromConfig(serverConfigs);

			expect(mockClient.connect).toHaveBeenCalledTimes(3);

			const clients = manager.getClients();
			expect(clients.size).toBe(3);
		});
	});
});

/**
 * Tests for JSON Schema to Zod conversion utility
 */

import { describe, it, expect } from 'vitest';
import { z } from 'zod';
import {
	jsonSchemaToZod,
	toolParametersToZod,
	createToolArgumentValidator,
	validateToolArguments,
	createSafeValidator,
} from '../schema-converter.js';
import type { ToolParameters } from '../types.js';

describe('Schema Converter', () => {
	describe('jsonSchemaToZod', () => {
		it('should convert primitive types correctly', () => {
			// String
			const stringSchema = jsonSchemaToZod({ type: 'string' });
			expect(stringSchema.parse('test')).toBe('test');
			expect(() => stringSchema.parse(123)).toThrow();

			// Number
			const numberSchema = jsonSchemaToZod({ type: 'number' });
			expect(numberSchema.parse(123)).toBe(123);
			expect(numberSchema.parse(123.45)).toBe(123.45);
			expect(() => numberSchema.parse('123')).toThrow();

			// Integer
			const integerSchema = jsonSchemaToZod({ type: 'integer' });
			expect(integerSchema.parse(123)).toBe(123);
			expect(() => integerSchema.parse(123.45)).toThrow();

			// Boolean
			const booleanSchema = jsonSchemaToZod({ type: 'boolean' });
			expect(booleanSchema.parse(true)).toBe(true);
			expect(booleanSchema.parse(false)).toBe(false);
			expect(() => booleanSchema.parse('true')).toThrow();

			// Null
			const nullSchema = jsonSchemaToZod({ type: 'null' });
			expect(nullSchema.parse(null)).toBe(null);
			expect(() => nullSchema.parse(undefined)).toThrow();
		});

		it('should handle string constraints', () => {
			const schema = jsonSchemaToZod({
				type: 'string',
				minLength: 2,
				maxLength: 10,
				pattern: '^[a-z]+$',
			});

			expect(schema.parse('abc')).toBe('abc');
			expect(() => schema.parse('a')).toThrow(); // Too short
			expect(() => schema.parse('abcdefghijk')).toThrow(); // Too long
			expect(() => schema.parse('ABC')).toThrow(); // Pattern mismatch
		});

		it('should handle string formats', () => {
			const emailSchema = jsonSchemaToZod({ type: 'string', format: 'email' });
			expect(emailSchema.parse('test@example.com')).toBe('test@example.com');
			expect(() => emailSchema.parse('invalid-email')).toThrow();

			const urlSchema = jsonSchemaToZod({ type: 'string', format: 'url' });
			expect(urlSchema.parse('https://example.com')).toBe('https://example.com');
			expect(() => urlSchema.parse('not-a-url')).toThrow();

			const uuidSchema = jsonSchemaToZod({ type: 'string', format: 'uuid' });
			expect(uuidSchema.parse('123e4567-e89b-12d3-a456-426614174000')).toBe(
				'123e4567-e89b-12d3-a456-426614174000'
			);
			expect(() => uuidSchema.parse('not-a-uuid')).toThrow();
		});

		it('should handle number constraints', () => {
			const schema = jsonSchemaToZod({
				type: 'number',
				minimum: 0,
				maximum: 100,
				multipleOf: 5,
			});

			expect(schema.parse(25)).toBe(25);
			expect(() => schema.parse(-1)).toThrow(); // Below minimum
			expect(() => schema.parse(101)).toThrow(); // Above maximum
			expect(() => schema.parse(7)).toThrow(); // Not multiple of 5
		});

		it('should handle array types', () => {
			const stringArraySchema = jsonSchemaToZod({
				type: 'array',
				items: { type: 'string' },
				minItems: 1,
				maxItems: 3,
			});

			expect(stringArraySchema.parse(['a', 'b'])).toEqual(['a', 'b']);
			expect(() => stringArraySchema.parse([])).toThrow(); // Too few items
			expect(() => stringArraySchema.parse(['a', 'b', 'c', 'd'])).toThrow(); // Too many items
			expect(() => stringArraySchema.parse(['a', 123])).toThrow(); // Wrong item type
		});

		it('should handle object types', () => {
			const objectSchema = jsonSchemaToZod({
				type: 'object',
				properties: {
					name: { type: 'string' },
					age: { type: 'number' },
					email: { type: 'string', format: 'email' },
				},
				required: ['name', 'age'],
			});

			expect(
				objectSchema.parse({
					name: 'John',
					age: 30,
					email: 'john@example.com',
				})
			).toEqual({
				name: 'John',
				age: 30,
				email: 'john@example.com',
			});

			expect(objectSchema.parse({ name: 'Jane', age: 25 })).toEqual({
				name: 'Jane',
				age: 25,
			});

			expect(() => objectSchema.parse({ name: 'John' })).toThrow(); // Missing required age
			expect(() => objectSchema.parse({ age: 30 })).toThrow(); // Missing required name
		});

		it('should handle enum types', () => {
			const enumSchema = jsonSchemaToZod({
				enum: ['red', 'green', 'blue'],
			});

			expect(enumSchema.parse('red')).toBe('red');
			expect(enumSchema.parse('green')).toBe('green');
			expect(() => enumSchema.parse('yellow')).toThrow();
		});

		it('should handle union types (anyOf)', () => {
			const unionSchema = jsonSchemaToZod({
				anyOf: [{ type: 'string' }, { type: 'number' }],
			});

			expect(unionSchema.parse('test')).toBe('test');
			expect(unionSchema.parse(123)).toBe(123);
			expect(() => unionSchema.parse(true)).toThrow();
		});

		it('should handle oneOf types', () => {
			const oneOfSchema = jsonSchemaToZod({
				oneOf: [{ type: 'string', pattern: '^[0-9]+$' }, { type: 'number' }],
			});

			expect(oneOfSchema.parse('123')).toBe('123');
			expect(oneOfSchema.parse(456)).toBe(456);
			expect(() => oneOfSchema.parse('abc')).toThrow();
		});

		it('should handle allOf types (intersection)', () => {
			const allOfSchema = jsonSchemaToZod({
				allOf: [
					{
						type: 'object',
						properties: { name: { type: 'string' } },
						required: ['name'],
					},
					{
						type: 'object',
						properties: { age: { type: 'number' } },
						required: ['age'],
					},
				],
			});

			expect(allOfSchema.parse({ name: 'John', age: 30 })).toEqual({
				name: 'John',
				age: 30,
			});

			expect(() => allOfSchema.parse({ name: 'John' })).toThrow(); // Missing age
		});

		it('should handle unknown or missing types', () => {
			const anySchema = jsonSchemaToZod({});
			expect(anySchema.parse('anything')).toBe('anything');
			expect(anySchema.parse(123)).toBe(123);
			expect(anySchema.parse(true)).toBe(true);

			const unknownTypeSchema = jsonSchemaToZod({ type: 'unknown' as any });
			expect(unknownTypeSchema.parse('anything')).toBe('anything');
		});
	});

	describe('toolParametersToZod', () => {
		it('should convert tool parameters correctly', () => {
			const toolParams: ToolParameters = {
				type: 'object',
				properties: {
					message: {
						type: 'string',
						description: 'The message to send',
					},
					count: {
						type: 'number',
						description: 'How many times to repeat',
					},
				},
				required: ['message'],
			};

			const zodSchema = toolParametersToZod(toolParams);

			expect(zodSchema.parse({ message: 'hello', count: 3 })).toEqual({
				message: 'hello',
				count: 3,
			});

			expect(zodSchema.parse({ message: 'hello' })).toEqual({
				message: 'hello',
			});

			expect(() => zodSchema.parse({ count: 3 })).toThrow(); // Missing required message
		});
	});

	describe('createToolArgumentValidator', () => {
		it('should create a working validator', () => {
			const toolParams: ToolParameters = {
				type: 'object',
				properties: {
					text: { type: 'string' },
					number: { type: 'number' },
				},
				required: ['text'],
			};

			const validator = createToolArgumentValidator(toolParams);

			expect(validator.parse({ text: 'hello', number: 42 })).toEqual({
				text: 'hello',
				number: 42,
			});

			expect(() => validator.parse({ number: 42 })).toThrow(); // Missing text
		});

		it('should fallback to any schema on conversion error', () => {
			// Mock console.warn to suppress warning
			const originalWarn = console.warn;
			console.warn = () => {};

			const invalidParams = null as any;
			const validator = createToolArgumentValidator(invalidParams);

			// Should accept anything due to fallback
			expect(validator.parse('anything')).toBe('anything');

			console.warn = originalWarn;
		});
	});

	describe('validateToolArguments', () => {
		it('should validate successfully with correct data', () => {
			const validator = z.object({
				name: z.string(),
				age: z.number(),
			});

			const result = validateToolArguments({ name: 'John', age: 30 }, validator);

			expect(result.success).toBe(true);
			if (result.success) {
				expect(result.data).toEqual({ name: 'John', age: 30 });
			}
		});

		it('should return error with invalid data', () => {
			const validator = z.object({
				name: z.string(),
				age: z.number(),
			});

			const result = validateToolArguments({ name: 'John', age: 'thirty' }, validator);

			expect(result.success).toBe(false);
			if (!result.success) {
				expect(result.error).toContain('age');
			}
		});

		it('should handle non-Zod errors', () => {
			const throwingValidator = {
				parse: () => {
					throw new Error('Custom error');
				},
			} as any;

			const result = validateToolArguments({}, throwingValidator);

			expect(result.success).toBe(false);
			if (!result.success) {
				expect(result.error).toBe('Custom error');
			}
		});
	});

	describe('createSafeValidator', () => {
		it('should create a safe validator that returns success/error objects', () => {
			const toolParams: ToolParameters = {
				type: 'object',
				properties: {
					value: { type: 'string' },
				},
				required: ['value'],
			};

			const safeValidator = createSafeValidator(toolParams);

			const successResult = safeValidator({ value: 'test' });
			expect(successResult.success).toBe(true);
			expect(successResult.data).toEqual({ value: 'test' });

			const errorResult = safeValidator({ value: 123 });
			expect(errorResult.success).toBe(false);
			expect(errorResult.error).toContain('value');
		});
	});
});

/**
 * AggregatorMCPManager implementation for the Model Context Protocol (MCP) aggregator mode.
 *
 * This file contains the AggregatorMCPManager class that extends MCPManager to provide
 * server-to-server aggregation capabilities, tool conflict resolution, and unified API exposure.
 */

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import {
	CallToolRequestSchema,
	ListToolsRequestSchema,
	ListResourcesRequestSchema,
	ReadResourceRequestSchema,
	GetPromptRequestSchema,
	ListPromptsRequestSchema,
} from '@modelcontextprotocol/sdk/types.js';

import type {
	IAggregatorManager,
	AggregatorConfig,
	ToolRegistryEntry,
	ServerConfigs,
	ToolSet,
} from './types.js';

import { MCPManager } from './manager.js';
import { LOG_PREFIXES } from './constants.js';

/**
 * Implementation of the IAggregatorManager interface for MCP server aggregation.
 * Extends MCPManager to provide server-to-server connection capabilities.
 */
export class AggregatorMCPManager extends MCPManager implements IAggregatorManager {
	private server: Server | null = null;
	private config: AggregatorConfig | null = null;
	private toolRegistry = new Map<string, ToolRegistryEntry>();
	private conflictCount = 0;
	private startTime = 0;

	constructor() {
		super();
		this.logger.info(`${LOG_PREFIXES.MANAGER} AggregatorMCPManager initialized`);
	}

	/**
	 * Start the aggregator server and connect to downstream servers.
	 */
	async startServer(config: AggregatorConfig): Promise<void> {
		this.config = config;
		this.startTime = Date.now();

		this.logger.info(`${LOG_PREFIXES.MANAGER} Starting aggregator server`, {
			transport: 'stdio',
			serverCount: Object.keys(config.servers).length,
		});

		// Initialize connections to downstream servers
		await this.initializeFromConfig(config.servers);

		// Create MCP server instance
		this.server = new Server(
			{
				name: 'cipher-aggregator',
				version: '1.0.0',
			},
			{
				capabilities: {
					tools: {},
					prompts: {},
					resources: {},
				},
			}
		);

		// Register aggregated tools
		await this._registerAggregatedTools();

		// Register aggregated prompts
		await this._registerAggregatedPrompts();

		// Register aggregated resources
		await this._registerAggregatedResources();

		// Start the server transport
		await this._startServerTransport(config);

		this.logger.info(`${LOG_PREFIXES.MANAGER} Aggregator server started successfully`, {
			toolCount: this.toolRegistry.size,
			conflicts: this.conflictCount,
		});
	}

	/**
	 * Stop the aggregator server and disconnect from all downstream servers.
	 */
	async stopServer(): Promise<void> {
		this.logger.info(`${LOG_PREFIXES.MANAGER} Stopping aggregator server`);

		if (this.server) {
			await this.server.close();
			this.server = null;
		}

		await this.disconnectAll();
		this.toolRegistry.clear();
		this.conflictCount = 0;
		this.config = null;

		this.logger.info(`${LOG_PREFIXES.MANAGER} Aggregator server stopped`);
	}

	/**
	 * Get the aggregated tool registry.
	 */
	getToolRegistry(): Map<string, ToolRegistryEntry> {
		return new Map(this.toolRegistry);
	}

	/**
	 * Discover available MCP servers in the network.
	 */
	async discoverServers(): Promise<ServerConfigs> {
		// TODO: Implement network discovery
		// For now, return empty config as discovery is not implemented
		this.logger.info(`${LOG_PREFIXES.MANAGER} Server discovery not yet implemented`);
		return {};
	}

	/**
	 * Get aggregator statistics.
	 */
	getStats(): {
		connectedServers: number;
		totalTools: number;
		totalPrompts: number;
		totalResources: number;
		conflicts: number;
		uptime: number;
	} {
		return {
			connectedServers: this.getClients().size,
			totalTools: this.toolRegistry.size,
			totalPrompts: 0, // TODO: Implement prompt counting
			totalResources: 0, // TODO: Implement resource counting
			conflicts: this.conflictCount,
			uptime: this.startTime ? Date.now() - this.startTime : 0,
		};
	}

	/**
	 * Override getAllTools to use conflict resolution strategy.
	 */
	override async getAllTools(): Promise<ToolSet> {
		const allTools: ToolSet = {};
		const errors: string[] = [];

		// Clear and rebuild registry
		this.toolRegistry.clear();
		this.conflictCount = 0;

		// Process clients in parallel
		const toolPromises = Array.from(this.getClients().entries()).map(async ([name, client]) => {
			try {
				const tools = await client.getTools();

				// Process each tool with conflict resolution
				Object.entries(tools).forEach(([toolName, toolDef]) => {
					const resolvedName = this._resolveToolNameConflict(toolName, name, toolDef);
					allTools[resolvedName] = toolDef;

					// Update registry
					this.toolRegistry.set(resolvedName, {
						tool: toolDef,
						clientName: name,
						originalName: toolName,
						registeredName: resolvedName,
						timestamp: Date.now(),
					});
				});

				this.logger.debug(
					`${LOG_PREFIXES.MANAGER} Retrieved ${Object.keys(tools).length} tools from ${name}`,
					{ clientName: name, toolCount: Object.keys(tools).length }
				);
			} catch (error) {
				const errorMessage = error instanceof Error ? error.message : String(error);
				errors.push(`${name}: ${errorMessage}`);

				this.logger.error(`${LOG_PREFIXES.MANAGER} Failed to get tools from ${name}`, {
					clientName: name,
					error: errorMessage,
				});
			}
		});

		await Promise.allSettled(toolPromises);

		if (errors.length > 0 && Object.keys(allTools).length === 0) {
			throw new Error(`Failed to retrieve tools from all clients: ${errors.join('; ')}`);
		}

		this.logger.info(
			`${LOG_PREFIXES.MANAGER} Retrieved ${Object.keys(allTools).length} total tools with ${this.conflictCount} conflicts resolved`,
			{
				toolCount: Object.keys(allTools).length,
				clientCount: this.getClients().size,
				conflicts: this.conflictCount,
			}
		);

		return allTools;
	}

	// ======================================================
	// Private Methods
	// ======================================================

	/**
	 * Resolve tool name conflicts based on configuration strategy.
	 */
	private _resolveToolNameConflict(toolName: string, clientName: string, _toolDef: any): string {
		const strategy = this.config?.conflictResolution || 'prefix';

		// Check if tool already exists
		const existingEntry = Array.from(this.toolRegistry.values()).find(
			entry => entry.originalName === toolName
		);

		if (!existingEntry) {
			// No conflict, use original name
			return toolName;
		}

		// Handle conflict based on strategy
		switch (strategy) {
			case 'first-wins': {
				this.logger.warn(
					`${LOG_PREFIXES.MANAGER} Tool name conflict: ${toolName} already exists, skipping from ${clientName}`,
					{ toolName, clientName, strategy }
				);
				this.conflictCount++;
				return `${clientName}__conflict__${toolName}__${Date.now()}`;
			}

			case 'error': {
				this.conflictCount++;
				const errorMsg = `Tool name conflict: ${toolName} exists in both ${existingEntry.clientName} and ${clientName}`;
				this.logger.error(`${LOG_PREFIXES.MANAGER} ${errorMsg}`, {
					toolName,
					clientName,
					strategy,
				});
				throw new Error(errorMsg);
			}

			case 'prefix':
			default: {
				this.conflictCount++;
				const prefixedName = `${clientName}.${toolName}`;
				this.logger.info(
					`${LOG_PREFIXES.MANAGER} Tool name conflict resolved: ${toolName} -> ${prefixedName}`,
					{ toolName, clientName, resolvedName: prefixedName, strategy }
				);
				return prefixedName;
			}
		}
	}

	/**
	 * Register all aggregated tools with the MCP server.
	 */
	private async _registerAggregatedTools(): Promise<void> {
		if (!this.server) {
			throw new Error('Server not initialized');
		}

		const tools = await this.getAllTools();

		// Register list tools handler
		this.server.setRequestHandler(ListToolsRequestSchema, async () => {
			const currentTools = await this.getAllTools();
			const toolList = Object.entries(currentTools).map(([name, tool]) => ({
				name,
				description: tool.description,
				inputSchema: tool.parameters,
			}));
			return { tools: toolList };
		});

		// Register call tool handler
		this.server.setRequestHandler(CallToolRequestSchema, async request => {
			const { name, arguments: args } = request.params;
			return await this.executeTool(name, args || {});
		});

		this.logger.info(
			`${LOG_PREFIXES.MANAGER} Registered ${Object.keys(tools).length} aggregated tools`
		);
	}

	/**
	 * Register all aggregated prompts with the MCP server.
	 */
	private async _registerAggregatedPrompts(): Promise<void> {
		if (!this.server) {
			throw new Error('Server not initialized');
		}

		const prompts = await this.listAllPrompts();

		// Register prompt handlers
		this.server.setRequestHandler(ListPromptsRequestSchema, async () => {
			return {
				prompts: prompts.map(name => ({
					name,
					description: `Aggregated prompt: ${name}`,
				})),
			};
		});

		this.server.setRequestHandler(GetPromptRequestSchema, async request => {
			const { name, arguments: args } = request.params;
			return await this.getPrompt(name, args);
		});

		this.logger.info(`${LOG_PREFIXES.MANAGER} Registered ${prompts.length} aggregated prompts`);
	}

	/**
	 * Register all aggregated resources with the MCP server.
	 */
	private async _registerAggregatedResources(): Promise<void> {
		if (!this.server) {
			throw new Error('Server not initialized');
		}

		const resources = await this.listAllResources();

		// Register resource handlers
		this.server.setRequestHandler(ListResourcesRequestSchema, async () => {
			return {
				resources: resources.map(uri => ({
					uri,
					name: uri.split('/').pop() || uri,
					description: `Aggregated resource: ${uri}`,
				})),
			};
		});

		this.server.setRequestHandler(ReadResourceRequestSchema, async request => {
			const { uri } = request.params;
			return await this.readResource(uri);
		});

		this.logger.info(`${LOG_PREFIXES.MANAGER} Registered ${resources.length} aggregated resources`);
	}

	/**
	 * Start the server transport based on configuration.
	 */
	private async _startServerTransport(_config: AggregatorConfig): Promise<void> {
		if (!this.server) {
			throw new Error('Server not initialized');
		}

		// For now, only support stdio transport for the aggregator server
		// TODO: Add HTTP/SSE transport support
		const transport = new StdioServerTransport();
		await this.server.connect(transport);

		this.logger.info(`${LOG_PREFIXES.MANAGER} Aggregator server transport started (stdio)`);
	}
}

/**
 * MCPClient implementation for the Model Context Protocol (MCP) module.
 *
 * This file contains the MCPClient class that handles connection management,
 * transport abstraction, and operations for a single MCP server.
 */

import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { Transport } from '@modelcontextprotocol/sdk/shared/transport.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { SSEClientTransport } from '@modelcontextprotocol/sdk/client/sse.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';
import { GetPromptResult, ReadResourceResult } from '@modelcontextprotocol/sdk/types.js';
import * as path from 'path';
import * as fs from 'fs';
import { fileURLToPath } from 'url';

import type {
	IMCPClient,
	McpServerConfig,
	StdioServerConfig,
	SseServerConfig,
	StreamableHttpServerConfig,
	ToolSet,
	ToolExecutionResult,
} from './types.js';

import {
	DEFAULT_TIMEOUT_MS,
	ERROR_MESSAGES,
	LOG_PREFIXES,
	TRANSPORT_TYPES,
	ENV_VARS,
} from './constants.js';

import { Logger, createLogger } from '../logger/index.js';

/**
 * Implementation of the IMCPClient interface for managing connections to MCP servers.
 * Supports stdio, SSE, and HTTP transports with comprehensive error handling and timeout management.
 */
export class MCPClient implements IMCPClient {
	private client: Client | null = null;
	private transport: Transport | null = null;
	private connected: boolean = false;
	private serverConfig: McpServerConfig | null = null;
	private serverName: string = '';
	private logger: Logger;
	private connectionPromise: Promise<Client> | null = null;
	private quietMode = false;

	// Server process information (for stdio connections)
	private serverInfo = {
		spawned: false,
		pid: null as number | null,
		command: null as string | null,
		originalArgs: null as string[] | null,
		resolvedArgs: null as string[] | null,
		env: null as Record<string, string> | null,
		alias: null as string | null,
	};

	constructor() {
		this.logger = createLogger({ level: 'info' });
	}

	/**
	 * Enable quiet mode to reduce logging verbosity (useful for CLI mode)
	 */
	setQuietMode(quiet: boolean): void {
		this.quietMode = quiet;
	}

	/**
	 * Connect to an MCP server using the provided configuration.
	 */
	async connect(config: McpServerConfig, serverName: string): Promise<Client> {
		if (this.connected && this.client) {
			this.logger.warn(`${LOG_PREFIXES.CONNECT} Already connected to ${serverName}`);
			return this.client;
		}

		// If connection is already in progress, return the existing promise
		if (this.connectionPromise) {
			return this.connectionPromise;
		}

		this.connectionPromise = this._performConnection(config, serverName);

		try {
			const client = await this.connectionPromise;
			this.connectionPromise = null;
			return client;
		} catch (error) {
			this.connectionPromise = null;
			throw error;
		}
	}

	/**
	 * Internal method to perform the actual connection.
	 */
	private async _performConnection(config: McpServerConfig, serverName: string): Promise<Client> {
		this.serverConfig = config;
		this.serverName = serverName;

		if (!this.quietMode) {
			this.logger.info(`${LOG_PREFIXES.CONNECT} Connecting to ${serverName} (${config.type})`, {
				serverName,
				transportType: config.type,
			});
		}

		try {
			// Create transport based on configuration type
			this.transport = await this._createTransport(config);

			// Create and connect the client
			this.client = new Client(
				{
					name: `cipher-mcp-client-${serverName}`,
					version: '1.0.0',
				},
				{
					capabilities: {
						tools: {},
						prompts: {},
						resources: {},
					},
				}
			);

			const timeout = this._getOperationTimeout(config);

			// Connect with timeout
			await this._connectWithTimeout(this.transport, timeout);

			this.connected = true;

			if (!this.quietMode) {
				this.logger.info(`${LOG_PREFIXES.CONNECT} Successfully connected to ${serverName}`, {
					serverName,
					timeout,
				});
			}

			return this.client;
		} catch (error) {
			await this._cleanup();

			const errorMessage = error instanceof Error ? error.message : String(error);
			this.logger.error(
				`${LOG_PREFIXES.CONNECT} ${ERROR_MESSAGES.CONNECTION_FAILED}: ${serverName}`,
				{ serverName, error: errorMessage, transportType: config.type }
			);

			throw new Error(`${ERROR_MESSAGES.CONNECTION_FAILED}: ${errorMessage}`);
		}
	}

	/**
	 * Create transport based on server configuration.
	 */
	private async _createTransport(config: McpServerConfig): Promise<Transport> {
		switch (config.type) {
			case TRANSPORT_TYPES.STDIO:
				return this._createStdioTransport(config as StdioServerConfig);

			case TRANSPORT_TYPES.SSE:
				return this._createSseTransport(config as SseServerConfig);

			case TRANSPORT_TYPES.STREAMABLE_HTTP:
				return this._createStreamableHttpTransport(config as StreamableHttpServerConfig);

			default:
				throw new Error(`${ERROR_MESSAGES.UNSUPPORTED_SERVER_TYPE}: ${(config as any).type}`);
		}
	}

	/**
	 * Create stdio transport.
	 */
	private async _createStdioTransport(config: StdioServerConfig): Promise<Transport> {
		const resolvedCommand = this._resolveCommand(config.command);
		const resolvedArgs = this._resolveArgs(config.args || []);
		const env = this._mergeEnvironment(config.env || {});

		// Store server info for stdio connections
		this.serverInfo = {
			spawned: true,
			pid: null, // Will be set after spawn
			command: resolvedCommand,
			originalArgs: config.args || [],
			resolvedArgs,
			env,
			alias: this.serverName,
		};

		this.logger.debug(`${LOG_PREFIXES.CONNECT} Creating stdio transport`, {
			command: resolvedCommand,
			args: resolvedArgs,
			serverName: this.serverName,
		});

		const transport = new StdioClientTransport({
			command: resolvedCommand,
			args: resolvedArgs,
			env,
		});

		return transport;
	}

	/**
	 * Create SSE transport.
	 */
	private async _createSseTransport(config: SseServerConfig): Promise<Transport> {
		this.logger.debug(`${LOG_PREFIXES.CONNECT} Creating SSE transport`, {
			url: config.url,
			serverName: this.serverName,
		});

		// Create SSE transport with optional headers support via requestInit
		const transportOptions = config.headers
			? { requestInit: { headers: config.headers } }
			: undefined;
		const transport = new SSEClientTransport(new URL(config.url), transportOptions);
		return transport;
	}

	/**
	 * Create streamable HTTP transport.
	 */
	private async _createStreamableHttpTransport(
		config: StreamableHttpServerConfig
	): Promise<Transport> {
		this.logger.debug(`${LOG_PREFIXES.CONNECT} Creating streamable HTTP transport`, {
			url: config.url,
			serverName: this.serverName,
		});

		// Create streamable HTTP transport with optional headers support via requestInit
		const transportOptions = config.headers
			? { requestInit: { headers: config.headers } }
			: undefined;
		const transport = new StreamableHTTPClientTransport(new URL(config.url), transportOptions);
		// Ensure sessionId is always a string to satisfy Transport interface
		if (transport.sessionId === undefined) {
			Object.defineProperty(transport, 'sessionId', {
				value: '',
				writable: true,
				enumerable: true,
				configurable: true,
			});
		}
		return transport as Transport;
	}

	/**
	 * Connect client to transport with timeout.
	 */
	private async _connectWithTimeout(transport: Transport, timeout: number): Promise<void> {
		if (!this.client) {
			throw new Error('Client not initialized');
		}

		return new Promise((resolve, reject) => {
			const timeoutId = setTimeout(() => {
				reject(new Error(`Connection timeout after ${timeout}ms`));
			}, timeout);

			this.client!.connect(transport)
				.then(() => {
					clearTimeout(timeoutId);
					resolve();
				})
				.catch(error => {
					clearTimeout(timeoutId);
					reject(error);
				});
		});
	}

	/**
	 * Disconnect from the MCP server.
	 */
	async disconnect(): Promise<void> {
		if (!this.connected) {
			this.logger.warn(`${LOG_PREFIXES.CONNECT} Already disconnected from ${this.serverName}`);
			return;
		}

		this.logger.info(`${LOG_PREFIXES.CONNECT} Disconnecting from ${this.serverName}`);

		try {
			await this._cleanup();
			this.logger.info(`${LOG_PREFIXES.CONNECT} Successfully disconnected from ${this.serverName}`);
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			this.logger.error(
				`${LOG_PREFIXES.CONNECT} ${ERROR_MESSAGES.DISCONNECTION_FAILED}: ${this.serverName}`,
				{ serverName: this.serverName, error: errorMessage }
			);
			throw new Error(`${ERROR_MESSAGES.DISCONNECTION_FAILED}: ${errorMessage}`);
		}
	}

	/**
	 * Call a tool with the given name and arguments.
	 */
	async callTool(name: string, args: any): Promise<ToolExecutionResult> {
		this._ensureConnected();

		const timeout = this._getOperationTimeout();

		this.logger.info(`${LOG_PREFIXES.TOOL} Calling tool: ${name}`, {
			toolName: name,
			serverName: this.serverName,
			timeout,
		});

		try {
			const result = await this._executeWithTimeout(
				() => this.client!.callTool({ name, arguments: args }),
				timeout,
				`Tool execution timeout: ${name}`
			);

			this.logger.info(`${LOG_PREFIXES.TOOL} Tool executed successfully: ${name}`, {
				toolName: name,
				serverName: this.serverName,
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			this.logger.error(`${LOG_PREFIXES.TOOL} ${ERROR_MESSAGES.TOOL_EXECUTION_FAILED}: ${name}`, {
				toolName: name,
				serverName: this.serverName,
				error: errorMessage,
			});
			throw new Error(`${ERROR_MESSAGES.TOOL_EXECUTION_FAILED}: ${errorMessage}`);
		}
	}

	/**
	 * Get all tools provided by this client.
	 */
	async getTools(): Promise<ToolSet> {
		this._ensureConnected();

		const timeout = this._getOperationTimeout();

		try {
			const result = await this._executeWithTimeout(
				() => this.client!.listTools(),
				timeout,
				'List tools timeout'
			);

			const toolSet: ToolSet = {};
			result.tools.forEach(tool => {
				toolSet[tool.name] = {
					description: tool.description || '',
					parameters: tool.inputSchema as any,
				};
			});

			this.logger.debug(`${LOG_PREFIXES.TOOL} Retrieved ${Object.keys(toolSet).length} tools`, {
				serverName: this.serverName,
				toolCount: Object.keys(toolSet).length,
			});

			return toolSet;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			this.logger.error(`${LOG_PREFIXES.TOOL} Failed to list tools`, {
				serverName: this.serverName,
				error: errorMessage,
			});
			throw error;
		}
	}

	/**
	 * List all prompts provided by this client.
	 */
	async listPrompts(): Promise<string[]> {
		this._ensureConnected();

		const timeout = this._getOperationTimeout();

		try {
			const result = await this._executeWithTimeout(
				() => this.client!.listPrompts(),
				timeout,
				'List prompts timeout'
			);

			const promptNames = result.prompts.map(prompt => prompt.name);

			this.logger.debug(`${LOG_PREFIXES.PROMPT} Retrieved ${promptNames.length} prompts`, {
				serverName: this.serverName,
				promptCount: promptNames.length,
			});

			return promptNames;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);

			// Check if this is a "capability not supported" error (common for filesystem servers)
			const isCapabilityError =
				errorMessage.includes('not implemented') ||
				errorMessage.includes('not supported') ||
				errorMessage.includes('Method not found') ||
				errorMessage.includes('prompts') === false; // Some servers just don't respond to prompt requests

			if (isCapabilityError) {
				this.logger.debug(
					`${LOG_PREFIXES.PROMPT} Prompts not supported by server (this is normal)`,
					{
						serverName: this.serverName,
						reason: 'Server does not implement prompt capability',
					}
				);
				return []; // Return empty array instead of throwing
			}

			// Real error - log as error and throw
			this.logger.error(`${LOG_PREFIXES.PROMPT} Failed to list prompts`, {
				serverName: this.serverName,
				error: errorMessage,
			});
			throw error;
		}
	}

	/**
	 * Get a prompt by name.
	 */
	async getPrompt(name: string, args?: any): Promise<GetPromptResult> {
		this._ensureConnected();

		const timeout = this._getOperationTimeout();

		this.logger.info(`${LOG_PREFIXES.PROMPT} Getting prompt: ${name}`, {
			promptName: name,
			serverName: this.serverName,
		});

		try {
			const result = await this._executeWithTimeout(
				() => this.client!.getPrompt({ name, arguments: args }),
				timeout,
				`Get prompt timeout: ${name}`
			);

			this.logger.info(`${LOG_PREFIXES.PROMPT} Retrieved prompt successfully: ${name}`, {
				promptName: name,
				serverName: this.serverName,
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			this.logger.error(`${LOG_PREFIXES.PROMPT} Failed to get prompt: ${name}`, {
				promptName: name,
				serverName: this.serverName,
				error: errorMessage,
			});
			throw error;
		}
	}

	/**
	 * List all resources provided by this client.
	 */
	async listResources(): Promise<string[]> {
		this._ensureConnected();

		const timeout = this._getOperationTimeout();

		try {
			const result = await this._executeWithTimeout(
				() => this.client!.listResources(),
				timeout,
				'List resources timeout'
			);

			const resourceUris = result.resources.map(resource => resource.uri);

			this.logger.debug(`${LOG_PREFIXES.RESOURCE} Retrieved ${resourceUris.length} resources`, {
				serverName: this.serverName,
				resourceCount: resourceUris.length,
			});

			return resourceUris;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);

			// Check if this is a "capability not supported" error (common for filesystem servers)
			const isCapabilityError =
				errorMessage.includes('not implemented') ||
				errorMessage.includes('not supported') ||
				errorMessage.includes('Method not found') ||
				errorMessage.includes('resources') === false; // Some servers just don't respond to resource requests

			if (isCapabilityError) {
				this.logger.debug(
					`${LOG_PREFIXES.RESOURCE} Resources not supported by server (this is normal)`,
					{
						serverName: this.serverName,
						reason: 'Server does not implement resource capability',
					}
				);
				return []; // Return empty array instead of throwing
			}

			// Real error - log as error and throw
			this.logger.error(`${LOG_PREFIXES.RESOURCE} Failed to list resources`, {
				serverName: this.serverName,
				error: errorMessage,
			});
			throw error;
		}
	}

	/**
	 * Read a resource by URI.
	 */
	async readResource(uri: string): Promise<ReadResourceResult> {
		this._ensureConnected();

		const timeout = this._getOperationTimeout();

		this.logger.info(`${LOG_PREFIXES.RESOURCE} Reading resource: ${uri}`, {
			resourceUri: uri,
			serverName: this.serverName,
		});

		try {
			const result = await this._executeWithTimeout(
				() => this.client!.readResource({ uri }),
				timeout,
				`Read resource timeout: ${uri}`
			);

			this.logger.info(`${LOG_PREFIXES.RESOURCE} Read resource successfully: ${uri}`, {
				resourceUri: uri,
				serverName: this.serverName,
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			this.logger.error(`${LOG_PREFIXES.RESOURCE} Failed to read resource: ${uri}`, {
				resourceUri: uri,
				serverName: this.serverName,
				error: errorMessage,
			});
			throw error;
		}
	}

	/**
	 * Get the connection status of the client.
	 */
	getConnectionStatus(): boolean {
		return this.connected;
	}

	/**
	 * Get the underlying MCP client instance.
	 */
	getClient(): Client | null {
		return this.client;
	}

	/**
	 * Get information about the connected server.
	 */
	getServerInfo() {
		return { ...this.serverInfo };
	}

	/**
	 * Get the client instance once connected.
	 */
	async getConnectedClient(): Promise<Client> {
		if (this.connected && this.client) {
			return this.client;
		}

		if (this.connectionPromise) {
			return this.connectionPromise;
		}

		throw new Error(ERROR_MESSAGES.NOT_CONNECTED);
	}

	// ======================================================
	// Private Utility Methods
	// ======================================================

	/**
	 * Ensure the client is connected before performing operations.
	 */
	private _ensureConnected(): void {
		if (!this.connected || !this.client) {
			throw new Error(ERROR_MESSAGES.NOT_CONNECTED);
		}
	}

	/**
	 * Get the operation timeout from configuration or default.
	 */
	private _getOperationTimeout(config?: McpServerConfig): number {
		if (config?.timeout) {
			return config.timeout;
		}

		if (this.serverConfig?.timeout) {
			return this.serverConfig.timeout;
		}

		// Check environment variable
		const envTimeout = process.env[ENV_VARS.GLOBAL_TIMEOUT];
		if (envTimeout) {
			const parsed = parseInt(envTimeout, 10);
			if (!isNaN(parsed) && parsed > 0) {
				return parsed;
			}
		}

		return DEFAULT_TIMEOUT_MS;
	}

	/**
	 * Execute a function with timeout.
	 */
	private async _executeWithTimeout<T>(
		operation: () => Promise<T>,
		timeout: number,
		timeoutMessage: string
	): Promise<T> {
		return new Promise((resolve, reject) => {
			const timeoutId = setTimeout(() => {
				reject(new Error(timeoutMessage));
			}, timeout);

			operation()
				.then(result => {
					clearTimeout(timeoutId);
					resolve(result);
				})
				.catch(error => {
					clearTimeout(timeoutId);
					reject(error);
				});
		});
	}

	/**
	 * Resolve command path, handling bundled scripts and relative paths.
	 */
	private _resolveCommand(command: string): string {
		// If it's already an absolute path, return as-is
		if (path.isAbsolute(command)) {
			return command;
		}

		// Check if it's a relative path from current working directory
		const cwdPath = path.resolve(process.cwd(), command);
		if (fs.existsSync(cwdPath)) {
			return cwdPath;
		}

		// Check if it's a bundled script relative to module
		try {
			const moduleDir = path.dirname(fileURLToPath(import.meta.url));
			const bundledPath = path.resolve(moduleDir, '../../../', command);
			if (fs.existsSync(bundledPath)) {
				return bundledPath;
			}
		} catch {
			// Ignore errors from import.meta.url resolution
		}

		// Return original command (might be in PATH)
		return command;
	}

	/**
	 * Resolve arguments, performing any necessary path resolution.
	 */
	private _resolveArgs(args: string[]): string[] {
		return args.map(arg => {
			// If argument looks like a path (contains / or \), try to resolve it
			if (arg.includes('/') || arg.includes('\\')) {
				const resolved = this._resolveCommand(arg);
				return resolved;
			}
			return arg;
		});
	}

	/**
	 * Merge environment variables with current process environment.
	 */
	private _mergeEnvironment(configEnv: Record<string, string>): Record<string, string> {
		// Filter out undefined values from env and convert to proper process.env format
		const processEnv = Object.fromEntries(
			Object.entries(process.env).filter(([_, value]) => value !== undefined)
		) as Record<string, string>;

		return {
			...processEnv,
			...configEnv,
		};
	}

	/**
	 * Clean up resources and reset state.
	 */
	private async _cleanup(): Promise<void> {
		this.connected = false;

		if (this.client) {
			try {
				await this.client.close();
			} catch (_error) {
				// Log but don't throw cleanup errors
				this.logger.warn(`${LOG_PREFIXES.CONNECT} Error during client cleanup`, {
					error: _error instanceof Error ? _error.message : String(_error),
				});
			}
			this.client = null;
		}

		if (this.transport) {
			try {
				await this.transport.close();
			} catch (_error) {
				// Log but don't throw cleanup errors
				this.logger.warn(`${LOG_PREFIXES.CONNECT} Error during transport cleanup`, {
					error: _error instanceof Error ? _error.message : String(_error),
				});
			}
			this.transport = null;
		}

		// Reset server info
		this.serverInfo = {
			spawned: false,
			pid: null,
			command: null,
			originalArgs: null,
			resolvedArgs: null,
			env: null,
			alias: null,
		};

		this.serverConfig = null;
		this.serverName = '';
	}
}

