/**
 * Constants for the Model Context Protocol (MCP) module.
 *
 * This file contains all constant values used throughout the MCP implementation,
 * including default values, error messages, and configuration constants.
 */

// ======================================================
// Connection and Timeout Constants
// ======================================================

/**
 * Default timeout for MCP operations in milliseconds.
 * Used for all operations if not overridden in the server configuration.
 */
export const DEFAULT_TIMEOUT_MS = 60000; // 1 minute

/**
 * Default connection mode for servers.
 */
export const DEFAULT_CONNECTION_MODE = 'lenient';

/**
 * Minimum timeout value allowed for operations.
 */
export const MIN_TIMEOUT_MS = 5000; // 5 seconds

/**
 * Maximum timeout value allowed for operations.
 */
export const MAX_TIMEOUT_MS = 300000; // 5 minutes

// ======================================================
// Transport Types
// ======================================================

/**
 * Available transport types for MCP servers.
 */
export const TRANSPORT_TYPES = {
	STDIO: 'stdio',
	SSE: 'sse',
	STREAMABLE_HTTP: 'streamable-http',
} as const;

// ======================================================
// Connection Modes
// ======================================================

/**
 * Available connection modes.
 */
export const CONNECTION_MODES = {
	/**
	 * Strict mode requires the server to successfully connect.
	 * If connection fails, an error will be thrown.
	 */
	STRICT: 'strict',

	/**
	 * Lenient mode allows the server to fail connecting.
	 * If connection fails, a warning will be logged but no error will be thrown.
	 */
	LENIENT: 'lenient',
} as const;

// ======================================================
// Error Messages
// ======================================================

/**
 * Error messages used throughout the MCP module.
 */
export const ERROR_MESSAGES = {
	// Connection errors
	CONNECTION_FAILED: 'Failed to connect to MCP server',
	DISCONNECTION_FAILED: 'Failed to disconnect from MCP server',
	NOT_CONNECTED: 'Client not connected. Please call connect() first',

	// Tool execution errors
	TOOL_EXECUTION_FAILED: 'Tool execution failed',
	NO_CLIENT_FOR_TOOL: 'No client found for tool',

	// Prompt and resource errors
	NO_CLIENT_FOR_PROMPT: 'No client found for prompt',
	NO_CLIENT_FOR_RESOURCE: 'No client found for resource',
	PROMPT_NOT_FOUND: 'Prompt not found',
	RESOURCE_NOT_FOUND: 'Resource not found',

	// Server configuration errors
	INVALID_CONFIG: 'Invalid server configuration',
	UNSUPPORTED_SERVER_TYPE: 'Unsupported server type',

	// Client registry errors
	CLIENT_ALREADY_REGISTERED: 'Client already registered',
	MISSING_REQUIRED_SERVERS: 'Failed to connect to required strict servers',
};

// ======================================================
// Logging Constants
// ======================================================

/**
 * Log message prefixes for the MCP module.
 */
export const LOG_PREFIXES = {
	CONNECT: 'MCP Connection:',
	TOOL: 'MCP Tool:',
	PROMPT: 'MCP Prompt:',
	RESOURCE: 'MCP Resource:',
	MANAGER: 'MCP Manager:',
};

// ======================================================
// Environment Flags
// ======================================================

/**
 * Environment variables that affect the behavior of the MCP module.
 */
export const ENV_VARS = {
	/**
	 * Environment variable to set the global timeout for all MCP operations.
	 */
	GLOBAL_TIMEOUT: 'MCP_GLOBAL_TIMEOUT',

	/**
	 * Environment variable to set the default connection mode.
	 */
	DEFAULT_CONNECTION_MODE: 'MCP_DEFAULT_CONNECTION_MODE',
};

export * from './client.js';
export * from './manager.js';
export * from './constants.js';

/**
 * MCPManager implementation for the Model Context Protocol (MCP) module.
 *
 * This file contains the MCPManager class that orchestrates multiple MCP clients,
 * provides caching for O(1) lookups, and handles connection strategies.
 */

import { GetPromptResult, ReadResourceResult } from '@modelcontextprotocol/sdk/types.js';

import type {
	IMCPManager,
	IMCPClient,
	ServerConfigs,
	McpServerConfig,
	ToolSet,
	ToolExecutionResult,
} from './types.js';

import { ERROR_MESSAGES, LOG_PREFIXES, CONNECTION_MODES } from './constants.js';

import { MCPClient } from './client.js';
import { Logger, createLogger } from '../logger/index.js';
import { EventManager } from '../events/event-manager.js';
import { ServiceEvents } from '../events/event-types.js';

/**
 * Cache entry for tools, prompts, and resources.
 */
interface CacheEntry<T> {
	data: T;
	timestamp: number;
	clientName: string;
}

/**
 * Registry entry for tracking client metadata.
 */
interface ClientRegistryEntry {
	client: IMCPClient;
	config: McpServerConfig;
	connected: boolean;
	lastSeen: number;
	failureCount: number;
}

/**
 * Implementation of the IMCPManager interface for orchestrating multiple MCP clients.
 * Provides O(1) cached lookups, connection management, and error handling strategies.
 */
export class MCPManager implements IMCPManager {
	private clients = new Map<string, ClientRegistryEntry>();
	private failedConnections: Record<string, string> = {};
	protected logger: Logger;
	private eventManager?: EventManager;
	private quietMode = false;

	// O(1) lookup caches
	private toolCache = new Map<string, CacheEntry<any>>();
	private toolClientMap = new Map<string, string>(); // toolName -> clientName
	private promptCache = new Map<string, CacheEntry<string[]>>();
	private promptClientMap = new Map<string, string>(); // promptName -> clientName
	private resourceCache = new Map<string, CacheEntry<string[]>>();
	private resourceClientMap = new Map<string, string>(); // resourceUri -> clientName

	// Cache configuration
	private cacheTimeout = 5 * 60 * 1000; // 5 minutes
	private maxCacheSize = 1000;

	constructor() {
		this.logger = createLogger({ level: 'info' });
		// Note: quiet mode can be set after construction, so this initial log may still appear
		this.logger.info(`${LOG_PREFIXES.MANAGER} MCPManager initialized`);
	}

	/**
	 * Set the event manager for emitting connection lifecycle events
	 */
	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	/**
	 * Enable quiet mode to reduce logging verbosity (useful for CLI mode)
	 */
	setQuietMode(quiet: boolean): void {
		this.quietMode = quiet;
	}

	/**
	 * Register a client with the manager.
	 */
	registerClient(name: string, client: IMCPClient): void {
		if (this.clients.has(name)) {
			this.logger.warn(
				`${LOG_PREFIXES.MANAGER} ${ERROR_MESSAGES.CLIENT_ALREADY_REGISTERED}: ${name}`,
				{ clientName: name }
			);
			return;
		}

		this.clients.set(name, {
			client,
			config: {} as McpServerConfig, // Will be set during connection
			connected: false,
			lastSeen: Date.now(),
			failureCount: 0,
		});

		this.logger.info(`${LOG_PREFIXES.MANAGER} Registered client: ${name}`, {
			clientName: name,
			totalClients: this.clients.size,
		});
	}

	/**
	 * Get all available tools from all connected clients.
	 */
	async getAllTools(): Promise<ToolSet> {
		const allTools: ToolSet = {};
		const errors: string[] = [];

		// Process clients in parallel for better performance
		const toolPromises = Array.from(this.clients.entries()).map(async ([name, entry]) => {
			if (!entry.connected) {
				return;
			}

			try {
				const tools = await entry.client.getTools();

				// Merge tools and update cache
				Object.entries(tools).forEach(([toolName, toolDef]) => {
					// Handle tool name conflicts by prefixing with client name
					const finalToolName = allTools[toolName] ? `${name}.${toolName}` : toolName;
					allTools[finalToolName] = toolDef;

					// Update O(1) lookup cache
					this.toolClientMap.set(finalToolName, name);
					this.toolCache.set(finalToolName, {
						data: toolDef,
						timestamp: Date.now(),
						clientName: name,
					});
				});

				this.logger.debug(
					`${LOG_PREFIXES.MANAGER} Retrieved ${Object.keys(tools).length} tools from ${name}`,
					{ clientName: name, toolCount: Object.keys(tools).length }
				);
			} catch (error) {
				const errorMessage = error instanceof Error ? error.message : String(error);
				errors.push(`${name}: ${errorMessage}`);
				this._updateClientFailure(name);

				this.logger.error(`${LOG_PREFIXES.MANAGER} Failed to get tools from ${name}`, {
					clientName: name,
					error: errorMessage,
				});
			}
		});

		await Promise.allSettled(toolPromises);

		if (errors.length > 0 && Object.keys(allTools).length === 0) {
			throw new Error(`Failed to retrieve tools from all clients: ${errors.join('; ')}`);
		}

		this._cleanupCache(this.toolCache);

		this.logger.debug(
			`${LOG_PREFIXES.MANAGER} Retrieved ${Object.keys(allTools).length} total tools`,
			{ toolCount: Object.keys(allTools).length, clientCount: this.clients.size }
		);

		return allTools;
	}

	/**
	 * Get the client that provides a specific tool.
	 */
	getToolClient(toolName: string): IMCPClient | undefined {
		const clientName = this.toolClientMap.get(toolName);
		if (!clientName) {
			return undefined;
		}

		const entry = this.clients.get(clientName);
		return entry?.connected ? entry.client : undefined;
	}

	/**
	 * Execute a tool with the given name and arguments.
	 */
	async executeTool(toolName: string, args: any): Promise<ToolExecutionResult> {
		const client = this.getToolClient(toolName);

		if (!client) {
			// Try to find the tool by refreshing cache
			await this._refreshToolCache();
			const refreshedClient = this.getToolClient(toolName);

			if (!refreshedClient) {
				throw new Error(`${ERROR_MESSAGES.NO_CLIENT_FOR_TOOL}: ${toolName}`);
			}

			return refreshedClient.callTool(toolName, args);
		}

		this.logger.info(`${LOG_PREFIXES.MANAGER} Executing tool: ${toolName}`, {
			toolName,
			hasArgs: !!args,
		});

		try {
			const result = await client.callTool(toolName, args);

			this.logger.info(`${LOG_PREFIXES.MANAGER} Tool executed successfully: ${toolName}`, {
				toolName,
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			this.logger.error(`${LOG_PREFIXES.MANAGER} Tool execution failed: ${toolName}`, {
				toolName,
				error: errorMessage,
			});
			throw error;
		}
	}

	/**
	 * List all available prompts from all connected clients.
	 */
	async listAllPrompts(): Promise<string[]> {
		const allPrompts = new Set<string>();
		const errors: string[] = [];

		const promptPromises = Array.from(this.clients.entries()).map(async ([name, entry]) => {
			if (!entry.connected) {
				return;
			}

			try {
				const prompts = await entry.client.listPrompts();

				prompts.forEach(promptName => {
					// Handle prompt name conflicts by prefixing with client name
					const finalPromptName = allPrompts.has(promptName) ? `${name}.${promptName}` : promptName;
					allPrompts.add(finalPromptName);

					// Update O(1) lookup cache
					this.promptClientMap.set(finalPromptName, name);
				});

				if (prompts.length > 0) {
					this.logger.debug(
						`${LOG_PREFIXES.MANAGER} Retrieved ${prompts.length} prompts from ${name}`,
						{ clientName: name, promptCount: prompts.length }
					);
				}
			} catch (error) {
				const errorMessage = error instanceof Error ? error.message : String(error);
				errors.push(`${name}: ${errorMessage}`);
				this._updateClientFailure(name);

				this.logger.error(`${LOG_PREFIXES.MANAGER} Failed to list prompts from ${name}`, {
					clientName: name,
					error: errorMessage,
				});
			}
		});

		await Promise.allSettled(promptPromises);

		const promptList = Array.from(allPrompts);

		if (!this.quietMode) {
			this.logger.info(`${LOG_PREFIXES.MANAGER} Retrieved ${promptList.length} total prompts`, {
				promptCount: promptList.length,
				clientCount: this.clients.size,
			});
		}

		return promptList;
	}

	/**
	 * Get the client that provides a specific prompt.
	 */
	getPromptClient(promptName: string): IMCPClient | undefined {
		const clientName = this.promptClientMap.get(promptName);
		if (!clientName) {
			return undefined;
		}

		const entry = this.clients.get(clientName);
		return entry?.connected ? entry.client : undefined;
	}

	/**
	 * Get a prompt by name.
	 */
	async getPrompt(name: string, args?: any): Promise<GetPromptResult> {
		const client = this.getPromptClient(name);

		if (!client) {
			// Try to find the prompt by refreshing cache
			await this._refreshPromptCache();
			const refreshedClient = this.getPromptClient(name);

			if (!refreshedClient) {
				throw new Error(`${ERROR_MESSAGES.NO_CLIENT_FOR_PROMPT}: ${name}`);
			}

			return refreshedClient.getPrompt(name, args);
		}

		this.logger.info(`${LOG_PREFIXES.MANAGER} Getting prompt: ${name}`, {
			promptName: name,
			hasArgs: !!args,
		});

		try {
			const result = await client.getPrompt(name, args);

			this.logger.info(`${LOG_PREFIXES.MANAGER} Prompt retrieved successfully: ${name}`, {
				promptName: name,
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			this.logger.error(`${LOG_PREFIXES.MANAGER} Failed to get prompt: ${name}`, {
				promptName: name,
				error: errorMessage,
			});
			throw error;
		}
	}

	/**
	 * List all available resources from all connected clients.
	 */
	async listAllResources(): Promise<string[]> {
		const allResources = new Set<string>();
		const errors: string[] = [];

		const resourcePromises = Array.from(this.clients.entries()).map(async ([name, entry]) => {
			if (!entry.connected) {
				return;
			}

			try {
				const resources = await entry.client.listResources();

				resources.forEach(resourceUri => {
					allResources.add(resourceUri);

					// Update O(1) lookup cache
					this.resourceClientMap.set(resourceUri, name);
				});

				if (resources.length > 0) {
					this.logger.debug(
						`${LOG_PREFIXES.MANAGER} Retrieved ${resources.length} resources from ${name}`,
						{ clientName: name, resourceCount: resources.length }
					);
				}
			} catch (error) {
				const errorMessage = error instanceof Error ? error.message : String(error);
				errors.push(`${name}: ${errorMessage}`);
				this._updateClientFailure(name);

				this.logger.error(`${LOG_PREFIXES.MANAGER} Failed to list resources from ${name}`, {
					clientName: name,
					error: errorMessage,
				});
			}
		});

		await Promise.allSettled(resourcePromises);

		const resourceList = Array.from(allResources);

		if (!this.quietMode) {
			this.logger.info(`${LOG_PREFIXES.MANAGER} Retrieved ${resourceList.length} total resources`, {
				resourceCount: resourceList.length,
				clientCount: this.clients.size,
			});
		}

		return resourceList;
	}

	/**
	 * Get the client that provides a specific resource.
	 */
	getResourceClient(resourceUri: string): IMCPClient | undefined {
		const clientName = this.resourceClientMap.get(resourceUri);
		if (!clientName) {
			return undefined;
		}

		const entry = this.clients.get(clientName);
		return entry?.connected ? entry.client : undefined;
	}

	/**
	 * Read a resource by URI.
	 */
	async readResource(uri: string): Promise<ReadResourceResult> {
		const client = this.getResourceClient(uri);

		if (!client) {
			// Try to find the resource by refreshing cache
			await this._refreshResourceCache();
			const refreshedClient = this.getResourceClient(uri);

			if (!refreshedClient) {
				throw new Error(`${ERROR_MESSAGES.NO_CLIENT_FOR_RESOURCE}: ${uri}`);
			}

			return refreshedClient.readResource(uri);
		}

		this.logger.info(`${LOG_PREFIXES.MANAGER} Reading resource: ${uri}`, { resourceUri: uri });

		try {
			const result = await client.readResource(uri);

			this.logger.info(`${LOG_PREFIXES.MANAGER} Resource read successfully: ${uri}`, {
				resourceUri: uri,
			});

			return result;
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			this.logger.error(`${LOG_PREFIXES.MANAGER} Failed to read resource: ${uri}`, {
				resourceUri: uri,
				error: errorMessage,
			});
			throw error;
		}
	}

	/**
	 * Initialize clients from server configurations.
	 */
	async initializeFromConfig(serverConfigs: ServerConfigs): Promise<void> {
		const enabledServers = Object.entries(serverConfigs).filter(
			([, config]) => config.enabled !== false
		);
		if (!this.quietMode) {
			this.logger.info(
				`${LOG_PREFIXES.MANAGER} Initializing ${enabledServers.length} servers (${Object.keys(serverConfigs).length - enabledServers.length} disabled)`,
				{
					enabledServerCount: enabledServers.length,
					totalServerCount: Object.keys(serverConfigs).length,
					disabledServerCount: Object.keys(serverConfigs).length - enabledServers.length,
				}
			);
		}

		const strictServers: string[] = [];
		const connectionPromises: Promise<void>[] = [];

		// Process all server configurations
		for (const [name, config] of Object.entries(serverConfigs)) {
			// Skip disabled servers
			if (config.enabled === false) {
				this.logger.info(`${LOG_PREFIXES.MANAGER} Skipping disabled server: ${name}`, {
					serverName: name,
				});
				continue;
			}

			if (config.connectionMode === CONNECTION_MODES.STRICT) {
				strictServers.push(name);
			}

			const connectionPromise = this.connectServer(name, config);
			connectionPromises.push(connectionPromise);
		}

		// Wait for all connections to complete
		const results = await Promise.allSettled(connectionPromises);

		// Check if any strict servers failed
		const failedStrictServers = strictServers.filter(
			name => this.failedConnections[name] !== undefined
		);

		if (failedStrictServers.length > 0) {
			const errorMessage = `${ERROR_MESSAGES.MISSING_REQUIRED_SERVERS}: ${failedStrictServers.join(', ')}`;
			this.logger.error(`${LOG_PREFIXES.MANAGER} ${errorMessage}`, {
				failedServers: failedStrictServers,
			});
			throw new Error(errorMessage);
		}

		const successCount = results.filter(result => result.status === 'fulfilled').length;
		const failureCount = results.filter(result => result.status === 'rejected').length;

		if (!this.quietMode) {
			this.logger.info(`${LOG_PREFIXES.MANAGER} Initialization complete`, {
				successCount,
				failureCount,
				totalCount: Object.keys(serverConfigs).length,
				strictServerCount: strictServers.length,
			});
		}
	}

	/**
	 * Connect to a new MCP server.
	 */
	async connectServer(name: string, config: McpServerConfig): Promise<void> {
		if (!this.quietMode) {
			this.logger.info(`${LOG_PREFIXES.MANAGER} Connecting to server: ${name}`, {
				serverName: name,
				transportType: config.type,
				connectionMode: config.connectionMode,
			});
		}

		try {
			// Create and register client if not already registered
			if (!this.clients.has(name)) {
				const client = new MCPClient();
				if (this.quietMode) {
					client.setQuietMode(true);
				}
				this.registerClient(name, client);
			}

			const entry = this.clients.get(name)!;
			entry.config = config;

			// Connect the client
			await entry.client.connect(config, name);

			// Update registry
			entry.connected = true;
			entry.lastSeen = Date.now();
			entry.failureCount = 0;

			// Clear any previous failure record
			delete this.failedConnections[name];

			// Emit MCP client connected event
			if (this.eventManager) {
				this.eventManager.emitServiceEvent(ServiceEvents.MCP_CLIENT_CONNECTED, {
					clientId: name,
					serverName: name,
					timestamp: Date.now(),
				});
			}

			if (!this.quietMode) {
				this.logger.info(`${LOG_PREFIXES.MANAGER} Successfully connected to server: ${name}`, {
					serverName: name,
				});
			}

			// Refresh caches to include new client's capabilities
			await this._refreshAllCaches();
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			this.failedConnections[name] = errorMessage;
			this._updateClientFailure(name);

			// Emit MCP client connection error event
			if (this.eventManager) {
				this.eventManager.emitServiceEvent(ServiceEvents.MCP_CLIENT_ERROR, {
					clientId: name,
					serverName: name,
					error: errorMessage,
					timestamp: Date.now(),
				});
			}

			this.logger.error(`${LOG_PREFIXES.MANAGER} Failed to connect to server: ${name}`, {
				serverName: name,
				error: errorMessage,
				connectionMode: config.connectionMode,
			});

			// Re-throw error for strict servers
			if (config.connectionMode === CONNECTION_MODES.STRICT) {
				throw error;
			}
		}
	}

	/**
	 * Get all registered clients.
	 */
	getClients(): Map<string, IMCPClient> {
		const clientMap = new Map<string, IMCPClient>();

		for (const [name, entry] of this.clients.entries()) {
			clientMap.set(name, entry.client);
		}

		return clientMap;
	}

	/**
	 * Get errors from failed connections.
	 */
	getFailedConnections(): { [key: string]: string } {
		return { ...this.failedConnections };
	}

	/**
	 * Disconnect and remove a specific client.
	 */
	async removeClient(name: string): Promise<void> {
		const entry = this.clients.get(name);

		if (!entry) {
			this.logger.warn(`${LOG_PREFIXES.MANAGER} Client not found for removal: ${name}`, {
				clientName: name,
			});
			return;
		}

		this.logger.info(`${LOG_PREFIXES.MANAGER} Removing client: ${name}`, { clientName: name });

		try {
			if (entry.connected) {
				await entry.client.disconnect();
			}
		} catch (error) {
			this.logger.warn(
				`${LOG_PREFIXES.MANAGER} Error disconnecting client during removal: ${name}`,
				{ clientName: name, error: error instanceof Error ? error.message : String(error) }
			);
		}

		// Emit MCP client disconnected event
		if (this.eventManager) {
			this.eventManager.emitServiceEvent(ServiceEvents.MCP_CLIENT_DISCONNECTED, {
				clientId: name,
				serverName: name,
				reason: 'Client removed',
				timestamp: Date.now(),
			});
		}

		// Remove from registry
		this.clients.delete(name);

		// Clear from caches
		this._removeClientFromCaches(name);

		// Clear failure record
		delete this.failedConnections[name];

		this.logger.info(`${LOG_PREFIXES.MANAGER} Client removed successfully: ${name}`, {
			clientName: name,
			remainingClients: this.clients.size,
		});
	}

	/**
	 * Disconnect all clients and clear caches.
	 */
	async disconnectAll(): Promise<void> {
		this.logger.info(`${LOG_PREFIXES.MANAGER} Disconnecting all clients`, {
			clientCount: this.clients.size,
		});

		const disconnectPromises = Array.from(this.clients.entries()).map(async ([name, entry]) => {
			try {
				if (entry.connected) {
					await entry.client.disconnect();
				}
			} catch (error) {
				this.logger.warn(`${LOG_PREFIXES.MANAGER} Error disconnecting client: ${name}`, {
					clientName: name,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		});

		await Promise.allSettled(disconnectPromises);

		// Clear all state
		this.clients.clear();
		this.failedConnections = {};
		this._clearAllCaches();

		this.logger.info(`${LOG_PREFIXES.MANAGER} All clients disconnected and caches cleared`);
	}

	// ======================================================
	// Private Cache Management Methods
	// ======================================================

	/**
	 * Refresh tool cache from all connected clients.
	 */
	private async _refreshToolCache(): Promise<void> {
		this.toolCache.clear();
		this.toolClientMap.clear();

		await this.getAllTools(); // This will repopulate the cache
	}

	/**
	 * Refresh prompt cache from all connected clients.
	 */
	private async _refreshPromptCache(): Promise<void> {
		this.promptCache.clear();
		this.promptClientMap.clear();

		await this.listAllPrompts(); // This will repopulate the cache
	}

	/**
	 * Refresh resource cache from all connected clients.
	 */
	private async _refreshResourceCache(): Promise<void> {
		this.resourceCache.clear();
		this.resourceClientMap.clear();

		await this.listAllResources(); // This will repopulate the cache
	}

	/**
	 * Refresh all caches.
	 */
	private async _refreshAllCaches(): Promise<void> {
		await Promise.allSettled([
			this._refreshToolCache(),
			this._refreshPromptCache(),
			this._refreshResourceCache(),
		]);
	}

	/**
	 * Clean up expired cache entries.
	 */
	private _cleanupCache<T>(cache: Map<string, CacheEntry<T>>): void {
		if (cache.size <= this.maxCacheSize) {
			return;
		}

		const now = Date.now();
		const entriesToRemove: string[] = [];

		for (const [key, entry] of cache.entries()) {
			if (now - entry.timestamp > this.cacheTimeout) {
				entriesToRemove.push(key);
			}
		}

		// Remove expired entries
		entriesToRemove.forEach(key => cache.delete(key));

		// If still over limit, remove oldest entries
		if (cache.size > this.maxCacheSize) {
			const sortedEntries = Array.from(cache.entries()).sort(
				([, a], [, b]) => a.timestamp - b.timestamp
			);

			const toRemove = sortedEntries.slice(0, cache.size - this.maxCacheSize);
			toRemove.forEach(([key]) => cache.delete(key));
		}
	}

	/**
	 * Remove a client from all caches.
	 */
	private _removeClientFromCaches(clientName: string): void {
		// Remove from tool cache
		for (const [toolName, entry] of this.toolCache.entries()) {
			if (entry.clientName === clientName) {
				this.toolCache.delete(toolName);
				this.toolClientMap.delete(toolName);
			}
		}

		// Remove from prompt cache
		for (const [promptName, clientMapName] of this.promptClientMap.entries()) {
			if (clientMapName === clientName) {
				this.promptClientMap.delete(promptName);
			}
		}

		// Remove from resource cache
		for (const [resourceUri, clientMapName] of this.resourceClientMap.entries()) {
			if (clientMapName === clientName) {
				this.resourceClientMap.delete(resourceUri);
			}
		}
	}

	/**
	 * Clear all caches.
	 */
	private _clearAllCaches(): void {
		this.toolCache.clear();
		this.toolClientMap.clear();
		this.promptCache.clear();
		this.promptClientMap.clear();
		this.resourceCache.clear();
		this.resourceClientMap.clear();
	}

	/**
	 * Update client failure count and connected status.
	 */
	private _updateClientFailure(clientName: string): void {
		const entry = this.clients.get(clientName);
		if (entry) {
			entry.failureCount++;
			entry.connected = false;
			entry.lastSeen = Date.now();
		}
	}
}

/**
 * JSON Schema to Zod conversion utility for MCP aggregator mode.
 *
 * This file provides utilities to convert JSON Schema definitions (used by MCP tools)
 * into Zod schemas for runtime validation and type safety.
 */

import { z } from 'zod';
import type { ToolParameters } from './types.js';

/**
 * Convert a JSON Schema object to a Zod schema.
 */
export function jsonSchemaToZod(schema: any): z.ZodType<any> {
	if (!schema || typeof schema !== 'object') {
		return z.any();
	}

	const { type, properties, required = [], items, enum: enumValues, anyOf, oneOf, allOf } = schema;

	// Handle union types (anyOf, oneOf)
	if (anyOf && Array.isArray(anyOf)) {
		const unionSchemas = anyOf.map((subSchema: any) => jsonSchemaToZod(subSchema));
		return z.union(unionSchemas as [z.ZodType<any>, z.ZodType<any>, ...z.ZodType<any>[]]);
	}

	if (oneOf && Array.isArray(oneOf)) {
		const unionSchemas = oneOf.map((subSchema: any) => jsonSchemaToZod(subSchema));
		return z.union(unionSchemas as [z.ZodType<any>, z.ZodType<any>, ...z.ZodType<any>[]]);
	}

	// Handle intersection types (allOf)
	if (allOf && Array.isArray(allOf)) {
		return allOf.reduce((acc: z.ZodType<any>, subSchema: any) => {
			const zodSchema = jsonSchemaToZod(subSchema);
			return z.intersection(acc, zodSchema);
		}, z.object({}));
	}

	// Handle enum types
	if (enumValues && Array.isArray(enumValues)) {
		if (enumValues.length === 0) {
			return z.never();
		}
		if (enumValues.length === 1) {
			return z.literal(enumValues[0]);
		}
		return z.enum(enumValues as [string, ...string[]]);
	}

	// Handle primitive types
	switch (type) {
		case 'string': {
			let stringSchema = z.string();
			if (schema.minLength !== undefined) {
				stringSchema = stringSchema.min(schema.minLength);
			}
			if (schema.maxLength !== undefined) {
				stringSchema = stringSchema.max(schema.maxLength);
			}
			if (schema.pattern) {
				stringSchema = stringSchema.regex(new RegExp(schema.pattern));
			}
			if (schema.format === 'email') {
				stringSchema = stringSchema.email();
			}
			if (schema.format === 'url') {
				stringSchema = stringSchema.url();
			}
			if (schema.format === 'uuid') {
				stringSchema = stringSchema.uuid();
			}
			return stringSchema;
		}

		case 'number':
		case 'integer': {
			let numberSchema = type === 'integer' ? z.number().int() : z.number();
			if (schema.minimum !== undefined) {
				numberSchema = numberSchema.min(schema.minimum);
			}
			if (schema.maximum !== undefined) {
				numberSchema = numberSchema.max(schema.maximum);
			}
			if (schema.multipleOf !== undefined) {
				numberSchema = numberSchema.multipleOf(schema.multipleOf);
			}
			return numberSchema;
		}

		case 'boolean':
			return z.boolean();

		case 'null':
			return z.null();

		case 'array': {
			const itemSchema = items ? jsonSchemaToZod(items) : z.any();
			let arraySchema = z.array(itemSchema);
			if (schema.minItems !== undefined) {
				arraySchema = arraySchema.min(schema.minItems);
			}
			if (schema.maxItems !== undefined) {
				arraySchema = arraySchema.max(schema.maxItems);
			}
			return arraySchema;
		}

		case 'object': {
			if (!properties || typeof properties !== 'object') {
				return z.record(z.any());
			}

			const zodProperties: Record<string, z.ZodType<any>> = {};
			const requiredFields = new Set(required);

			for (const [key, propSchema] of Object.entries(properties)) {
				let propZodSchema = jsonSchemaToZod(propSchema);

				// Make optional if not in required array
				if (!requiredFields.has(key)) {
					propZodSchema = propZodSchema.optional();
				}

				zodProperties[key] = propZodSchema;
			}

			let objectSchema = z.object(zodProperties);

			// Handle additional properties
			if (schema.additionalProperties === false) {
				objectSchema = objectSchema.strict() as any;
			} else if (schema.additionalProperties && typeof schema.additionalProperties === 'object') {
				// Convert to passthrough and let additional validation happen at runtime
				objectSchema = objectSchema.passthrough() as any;
			} else if (schema.additionalProperties !== false) {
				objectSchema = objectSchema.passthrough() as any;
			}

			return objectSchema;
		}

		default:
			// Handle unknown types or missing type
			return z.any();
	}
}

/**
 * Convert MCP tool parameters to Zod schema.
 */
export function toolParametersToZod(parameters: ToolParameters): z.ZodType<any> {
	return jsonSchemaToZod(parameters);
}

/**
 * Create a Zod schema for validating tool arguments.
 */
export function createToolArgumentValidator(parameters: ToolParameters): z.ZodType<any> {
	try {
		return toolParametersToZod(parameters);
	} catch (error) {
		// Fallback to any if conversion fails
		console.warn('Failed to convert tool parameters to Zod schema:', error);
		return z.any();
	}
}

/**
 * Validate tool arguments against a Zod schema.
 */
export function validateToolArguments(
	args: any,
	validator: z.ZodType<any>
): { success: true; data: any } | { success: false; error: string } {
	try {
		const result = validator.parse(args);
		return { success: true, data: result };
	} catch (error) {
		if (error instanceof z.ZodError) {
			const errorMessage = error.errors
				.map(err => `${err.path.join('.')}: ${err.message}`)
				.join('; ');
			return { success: false, error: errorMessage };
		}
		return { success: false, error: error instanceof Error ? error.message : String(error) };
	}
}

/**
 * Create a safe version of a tool parameter schema that doesn't throw on invalid input.
 */
export function createSafeValidator(parameters: ToolParameters): (args: any) => {
	success: boolean;
	data?: any;
	error?: string;
} {
	const validator = createToolArgumentValidator(parameters);

	return (args: any) => {
		const result = validateToolArguments(args, validator);
		if (result.success) {
			return { success: true, data: result.data };
		} else {
			return { success: false, error: (result as { success: false; error: string }).error };
		}
	};
}

/**
 * Convert Zod schema back to JSON Schema (for documentation/introspection).
 */
export function zodToJsonSchema(zodSchema: z.ZodType<any>): any {
	// This is a basic implementation - for production use consider using a library like zod-to-json-schema
	if (zodSchema instanceof z.ZodString) {
		return { type: 'string' };
	}
	if (zodSchema instanceof z.ZodNumber) {
		return { type: 'number' };
	}
	if (zodSchema instanceof z.ZodBoolean) {
		return { type: 'boolean' };
	}
	if (zodSchema instanceof z.ZodArray) {
		return {
			type: 'array',
			items: zodToJsonSchema(zodSchema.element),
		};
	}
	if (zodSchema instanceof z.ZodObject) {
		const properties: Record<string, any> = {};
		const required: string[] = [];

		for (const [key, value] of Object.entries(zodSchema.shape)) {
			properties[key] = zodToJsonSchema(value as z.ZodType<any>);
			// Note: This is simplified - proper detection of required fields would need more sophisticated logic
		}

		return {
			type: 'object',
			properties,
			required: required.length > 0 ? required : undefined,
		};
	}

	// Fallback for unsupported types
	return { type: 'any' };
}

/**
 * Core types and interfaces for the Model Context Protocol (MCP) module.
 *
 * This file contains all the type definitions needed for working with MCP servers,
 * including client interfaces, server configurations, and tool/prompt/resource types.
 */

import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { GetPromptResult, ReadResourceResult } from '@modelcontextprotocol/sdk/types.js';

// ======================================================
// Transport and Connection Types
// ======================================================

/**
 * Available MCP client transport types for connecting to MCP servers.
 * These define the communication protocol used to connect to individual MCP servers.
 */
export type TransportType = 'stdio' | 'sse' | 'streamable-http';

/**
 * Available server configuration types.
 * Includes both transport types (for direct server connections) and operational modes (like aggregator).
 */
export type ServerConfigType = TransportType | 'aggregator';

/**
 * Base configuration for any MCP server.
 */
export interface BaseServerConfig {
	/**
	 * Configuration type: transport protocol for direct connections or operational mode.
	 * - Transport types ('stdio', 'sse', 'streamable-http'): Connect directly to MCP servers
	 * - Operational modes ('aggregator'): Special server modes that aggregate other servers
	 */
	type: ServerConfigType;

	/**
	 * Whether this server is enabled. Disabled servers will be skipped during initialization.
	 * @default true
	 */
	enabled?: boolean;

	/**
	 * Connection mode determines how failures to connect are handled.
	 * - 'strict': Connection failures will throw errors and halt initialization.
	 * - 'lenient': Connection failures will be logged but won't stop other servers from connecting.
	 * @default 'lenient'
	 */
	connectionMode?: 'strict' | 'lenient';

	/**
	 * Timeout in milliseconds for server operations.
	 * @default 60000 (1 minute)
	 */
	timeout?: number;
}

/**
 * Configuration for a stdio-based MCP server.
 */
export interface StdioServerConfig extends BaseServerConfig {
	type: 'stdio';

	/**
	 * Command to run the server.
	 */
	command: string;

	/**
	 * Arguments to pass to the command.
	 */
	args: string[];

	/**
	 * Environment variables to set for the command.
	 */
	env?: Record<string, string>;
}

/**
 * Configuration for an SSE-based MCP server.
 */
export interface SseServerConfig extends BaseServerConfig {
	type: 'sse';

	/**
	 * URL of the SSE server.
	 */
	url: string;

	/**
	 * Headers to include with requests.
	 */
	headers?: Record<string, string>;
}

/**
 * Configuration for a streamable HTTP-based MCP server.
 */
export interface StreamableHttpServerConfig extends BaseServerConfig {
	type: 'streamable-http';

	/**
	 * URL of the streamable HTTP server.
	 */
	url: string;

	/**
	 * Headers to include with requests.
	 */
	headers?: Record<string, string>;
}

/**
 * Union type representing any valid MCP server configuration.
 */
export type McpServerConfig = StdioServerConfig | SseServerConfig | StreamableHttpServerConfig;

/**
 * Configuration for aggregator mode.
 */
export interface AggregatorConfig extends BaseServerConfig {
	type: 'aggregator';

	/**
	 * Servers to aggregate from.
	 */
	servers: ServerConfigs;

	/**
	 * Strategy for handling tool name conflicts.
	 * - 'prefix': Prefix conflicting tools with server name
	 * - 'first-wins': First registered tool takes precedence
	 * - 'error': Throw error on conflicts
	 * @default 'prefix'
	 */
	conflictResolution?: 'prefix' | 'first-wins' | 'error';

	/**
	 * Whether to auto-discover new servers in the network.
	 * @default false
	 */
	autoDiscovery?: boolean;
}

/**
 * Union type representing any valid MCP server configuration including aggregator.
 */
export type ExtendedMcpServerConfig = McpServerConfig | AggregatorConfig;

/**
 * Record mapping server names to their configurations.
 */
export type ServerConfigs = Record<string, McpServerConfig>;

// ======================================================
// Tool and Resource Types
// ======================================================

/**
 * Represents a tool parameter schema.
 */
export interface ToolParameterSchema {
	type: string;
	description?: string;
	[key: string]: any;
}

/**
 * Represents a tool parameter definition.
 */
export interface ToolParameterDefinition {
	[parameterName: string]: ToolParameterSchema;
}

/**
 * Represents a tool's parameter definitions and requirements.
 */
export interface ToolParameters {
	type: string;
	properties: ToolParameterDefinition;
	required?: string[];
}

/**
 * Represents a single tool definition.
 */
export interface Tool {
	description: string;
	parameters: ToolParameters;
}

/**
 * A collection of tools indexed by their names.
 */
export interface ToolSet {
	[toolName: string]: Tool;
}

/**
 * Result of a tool execution.
 */
export type ToolExecutionResult = any;

// ======================================================
// Client Interface
// ======================================================

/**
 * Interface for an MCP client that communicates with a single MCP server.
 */
export interface IMCPClient {
	/**
	 * Connect to an MCP server using the provided configuration.
	 */
	connect(config: McpServerConfig, serverName: string): Promise<Client>;

	/**
	 * Disconnect from the MCP server.
	 */
	disconnect(): Promise<void>;

	/**
	 * Call a tool with the given name and arguments.
	 */
	callTool(name: string, args: any): Promise<ToolExecutionResult>;

	/**
	 * Get all tools provided by this client.
	 */
	getTools(): Promise<ToolSet>;

	/**
	 * List all prompts provided by this client.
	 */
	listPrompts(): Promise<string[]>;

	/**
	 * Get a prompt by name.
	 */
	getPrompt(name: string, args?: any): Promise<GetPromptResult>;

	/**
	 * List all resources provided by this client.
	 */
	listResources(): Promise<string[]>;

	/**
	 * Read a resource by URI.
	 */
	readResource(uri: string): Promise<ReadResourceResult>;

	/**
	 * Get the connection status of the client.
	 */
	getConnectionStatus(): boolean;

	/**
	 * Get the underlying MCP client instance.
	 */
	getClient(): Client | null;

	/**
	 * Get information about the connected server.
	 */
	getServerInfo(): {
		spawned: boolean;
		pid: number | null;
		command: string | null;
		originalArgs: string[] | null;
		resolvedArgs: string[] | null;
		env: Record<string, string> | null;
		alias: string | null;
	};

	/**
	 * Get the client instance once connected.
	 */
	getConnectedClient(): Promise<Client>;
}

// ======================================================
// Manager Interface
// ======================================================

/**
 * Interface for the MCP Manager that orchestrates multiple MCP clients.
 */
export interface IMCPManager {
	/**
	 * Register a client with the manager.
	 */
	registerClient(name: string, client: IMCPClient): void;

	/**
	 * Get all available tools from all connected clients.
	 */
	getAllTools(): Promise<ToolSet>;

	/**
	 * Get the client that provides a specific tool.
	 */
	getToolClient(toolName: string): IMCPClient | undefined;

	/**
	 * Execute a tool with the given name and arguments.
	 */
	executeTool(toolName: string, args: any): Promise<ToolExecutionResult>;

	/**
	 * List all available prompts from all connected clients.
	 */
	listAllPrompts(): Promise<string[]>;

	/**
	 * Get the client that provides a specific prompt.
	 */
	getPromptClient(promptName: string): IMCPClient | undefined;

	/**
	 * Get a prompt by name.
	 */
	getPrompt(name: string, args?: any): Promise<GetPromptResult>;

	/**
	 * List all available resources from all connected clients.
	 */
	listAllResources(): Promise<string[]>;

	/**
	 * Get the client that provides a specific resource.
	 */
	getResourceClient(resourceUri: string): IMCPClient | undefined;

	/**
	 * Read a resource by URI.
	 */
	readResource(uri: string): Promise<ReadResourceResult>;

	/**
	 * Initialize clients from server configurations.
	 */
	initializeFromConfig(serverConfigs: ServerConfigs): Promise<void>;

	/**
	 * Connect to a new MCP server.
	 */
	connectServer(name: string, config: McpServerConfig): Promise<void>;

	/**
	 * Get all registered clients.
	 */
	getClients(): Map<string, IMCPClient>;

	/**
	 * Get errors from failed connections.
	 */
	getFailedConnections(): { [key: string]: string };

	/**
	 * Disconnect and remove a specific client.
	 */
	removeClient(name: string): Promise<void>;

	/**
	 * Disconnect all clients and clear caches.
	 */
	disconnectAll(): Promise<void>;
}

/**
 * Tool registry entry for tracking tool metadata.
 */
export interface ToolRegistryEntry {
	tool: Tool;
	clientName: string;
	originalName: string;
	registeredName: string;
	timestamp: number;
}

/**
 * Interface for aggregator-specific functionality.
 */
export interface IAggregatorManager extends IMCPManager {
	/**
	 * Start the aggregator server.
	 */
	startServer(config: AggregatorConfig): Promise<void>;

	/**
	 * Stop the aggregator server.
	 */
	stopServer(): Promise<void>;

	/**
	 * Get the aggregated tool registry.
	 */
	getToolRegistry(): Map<string, ToolRegistryEntry>;

	/**
	 * Discover available MCP servers in the network.
	 */
	discoverServers(): Promise<ServerConfigs>;

	/**
	 * Get aggregator statistics.
	 */
	getStats(): {
		connectedServers: number;
		totalTools: number;
		totalPrompts: number;
		totalResources: number;
		conflicts: number;
		uptime: number;
	};
}

import { ZodError } from 'zod';
import { McpServerConfigSchema } from './config.js';
import { McpServerConfig } from './types.js';

export type ValidationErrorType =
	| 'missing_api_key'
	| 'invalid_model'
	| 'invalid_provider'
	| 'incompatible_model_provider'
	| 'unsupported_router'
	| 'invalid_base_url'
	| 'invalid_max_tokens'
	| 'schema_validation'
	| 'general';

export interface ValidationError {
	type: ValidationErrorType;
	message: string;
	field?: string;
	provider?: string;
	model?: string;
	router?: string;
	suggestedAction?: string;
}
export interface McpServerValidationResult {
	isValid: boolean;
	errors: ValidationError[];
	warnings: string[];
	config: McpServerConfig | undefined;
}

export function validateMcpServerConfig(
	serverName: string,
	serverConfig: McpServerConfig,
	existingServerNames: string[] = []
): McpServerValidationResult {
	const errors: ValidationError[] = [];
	const warnings: string[] = [];

	// Validate server name
	if (!serverName || typeof serverName !== 'string' || serverName.trim() === '') {
		errors.push({
			type: 'schema_validation',
			message: 'Server name must be a non-empty string',
			field: 'serverName',
			suggestedAction: 'Provide a valid server name',
		});
	}

	// Validate server config using Zod schema
	try {
		McpServerConfigSchema.parse(serverConfig);
	} catch (error) {
		if (error instanceof ZodError) {
			for (const issue of error.errors) {
				errors.push({
					type: 'schema_validation',
					message: `Invalid server configuration: ${issue.message}`,
					field: issue.path.join('.'),
					suggestedAction: 'Check the server configuration format and required fields',
				});
			}
		} else {
			errors.push({
				type: 'schema_validation',
				message: `Invalid server configuration: ${error instanceof Error ? error.message : 'Unknown validation error'}`,
				suggestedAction: 'Check the server configuration format and required fields',
			});
		}
	}

	// Additional business logic validation
	if (errors.length === 0) {
		// Check for duplicate server names (case-insensitive)
		const duplicateName = existingServerNames.find(
			name => name.toLowerCase() === serverName.toLowerCase() && name !== serverName
		);
		if (duplicateName) {
			warnings.push(
				`Server name '${serverName}' is similar to existing server '${duplicateName}' (case difference only)`
			);
		}

		// Type-specific validation - we know it's valid McpServerConfig at this point
		if (serverConfig.type === 'stdio') {
			if (!serverConfig.command || serverConfig.command.trim() === '') {
				errors.push({
					type: 'schema_validation',
					message: 'Stdio server requires a non-empty command',
					field: 'command',
					suggestedAction: 'Provide a valid command to execute',
				});
			}
		} else if (serverConfig.type === 'sse' || serverConfig.type === 'streamable-http') {
			const url = serverConfig.url;
			if (!url) {
				errors.push({
					type: 'schema_validation',
					message: 'URL is required for streamable-http/sse server types',
					field: 'url',
					suggestedAction: 'Provide a non-empty url string',
				});
			} else {
				try {
					new URL(url);
				} catch {
					errors.push({
						type: 'schema_validation',
						message: `Invalid URL format: ${url}`,
						field: 'url',
						suggestedAction: 'Provide a valid URL with protocol (http:// or https://)',
					});
				}
			}
		}
	}

	// If validation passed, parse through schema to apply defaults
	let validatedConfig: McpServerConfig | undefined;
	if (errors.length === 0) {
		try {
			validatedConfig = McpServerConfigSchema.parse(serverConfig) as McpServerConfig;
		} catch (schemaError) {
			if (schemaError instanceof ZodError) {
				for (const issue of schemaError.errors) {
					errors.push({
						type: 'schema_validation',
						message: `Schema parsing failed: ${issue.message}`,
						field: issue.path.join('.'),
					});
				}
			}
		}
	}

	return {
		isValid: errors.length === 0,
		errors,
		warnings,
		config: validatedConfig,
	};
}

