				maxSessions: 50,
				sessionTTL: 1800000, // 30 minutes
			};

			const customSessionManager = new SessionManager(mockServices, customConfig);
			await customSessionManager.init();

			expect(customSessionManager).toBeDefined();
			await customSessionManager.shutdown();
		});

		it('should handle multiple initialization calls gracefully', async () => {
			await sessionManager.init();
			await sessionManager.init(); // Second call should be no-op

			const sessionCount = await sessionManager.getSessionCount();
			expect(sessionCount).toBe(0);
		});

		it('should auto-initialize when methods are called', async () => {
			// Don't call init() explicitly
			const session = await sessionManager.createSession();

			expect(session).toBeDefined();
			expect(session.id).toBeDefined();
		});
	});

	describe('Session Creation', () => {
		beforeEach(async () => {
			await sessionManager.init();
		});

		it('should create a new session with auto-generated ID', async () => {
			const session = await sessionManager.createSession();

			expect(session).toBeDefined();
			expect(session.id).toBeDefined();
			expect(typeof session.id).toBe('string');
			expect(session.init).toHaveBeenCalled();
		});

		it('should create a new session with custom ID', async () => {
			const customId = 'custom-session-123';
			const session = await sessionManager.createSession(customId);

			expect(session).toBeDefined();
			expect(session.id).toBe(customId);
		});

		it('should return existing session if ID already exists', async () => {
			const sessionId = 'duplicate-test';
			const session1 = await sessionManager.createSession(sessionId);
			const session2 = await sessionManager.createSession(sessionId);

			expect(session1).toBe(session2);
			expect(session1.id).toBe(sessionId);
		});

		it('should handle concurrent session creation with same ID', async () => {
			const sessionId = 'concurrent-test';

			const [session1, session2, session3] = await Promise.all([
				sessionManager.createSession(sessionId),
				sessionManager.createSession(sessionId),
				sessionManager.createSession(sessionId),
			]);

			expect(session1).toBe(session2);
			expect(session2).toBe(session3);
			expect(session1.id).toBe(sessionId);
		});

		it('should evict oldest session when max limit is reached', async () => {
			const smallSessionManager = new SessionManager(mockServices, { maxSessions: 2 });
			await smallSessionManager.init();

			const session1 = await smallSessionManager.createSession('session1');
			const session2 = await smallSessionManager.createSession('session2');

			// Small delay to ensure different timestamps
			await new Promise(resolve => setTimeout(resolve, 1));

			const session3 = await smallSessionManager.createSession('session3');

			expect(session1).toBeDefined();
			expect(session2).toBeDefined();
			expect(session3).toBeDefined();

			const sessionCount = await smallSessionManager.getSessionCount();
			expect(sessionCount).toBe(2);

			// session1 should have been evicted, session2 and session3 should remain
			const retrievedSession1 = await smallSessionManager.getSession('session1');
			const retrievedSession2 = await smallSessionManager.getSession('session2');
			const retrievedSession3 = await smallSessionManager.getSession('session3');

			expect(retrievedSession1).toBeNull();
			expect(retrievedSession2).toBeDefined();
			expect(retrievedSession3).toBeDefined();

			await smallSessionManager.shutdown();
		});

		it('should handle session creation errors gracefully', async () => {
			const MockedConversationSession = vi.mocked(ConversationSession);
			MockedConversationSession.mockImplementationOnce(() => {
				throw new Error('Session creation failed');
			});

			await expect(sessionManager.createSession()).rejects.toThrow('Session creation failed');
		});
	});

	describe('Session Retrieval', () => {
		beforeEach(async () => {
			await sessionManager.init();
		});

		it('should retrieve existing session', async () => {
			const sessionId = 'retrieve-test';
			const createdSession = await sessionManager.createSession(sessionId);
			const retrievedSession = await sessionManager.getSession(sessionId);

			expect(retrievedSession).toBe(createdSession);
			expect(retrievedSession?.id).toBe(sessionId);
		});

		it('should return null for non-existent session', async () => {
			const session = await sessionManager.getSession('non-existent');
			expect(session).toBeNull();
		});

		it('should return null for expired session', async () => {
			const shortTTLManager = new SessionManager(mockServices, { sessionTTL: 1 }); // 1ms TTL
			await shortTTLManager.init();

			const sessionId = 'expired-test';
			await shortTTLManager.createSession(sessionId);

			// Wait for session to expire
			await new Promise(resolve => setTimeout(resolve, 10));

			const session = await shortTTLManager.getSession(sessionId);
			expect(session).toBeNull();

			await shortTTLManager.shutdown();
		});

		it('should update session activity on retrieval', async () => {
			const sessionId = 'activity-test';
			await sessionManager.createSession(sessionId);

			const session1 = await sessionManager.getSession(sessionId);
			const session2 = await sessionManager.getSession(sessionId);

			expect(session1).toBe(session2);
		});
	});

	describe('Session Removal', () => {
		beforeEach(async () => {
			await sessionManager.init();
		});

		it('should remove existing session', async () => {
			const sessionId = 'remove-test';
			await sessionManager.createSession(sessionId);

			const removed = await sessionManager.removeSession(sessionId);
			expect(removed).toBe(true);

			const session = await sessionManager.getSession(sessionId);
			expect(session).toBeNull();
		});

		it('should return false when removing non-existent session', async () => {
			const removed = await sessionManager.removeSession('non-existent');
			expect(removed).toBe(false);
		});

		it('should handle multiple removal attempts', async () => {
			const sessionId = 'multi-remove-test';
			await sessionManager.createSession(sessionId);

			const removed1 = await sessionManager.removeSession(sessionId);
			const removed2 = await sessionManager.removeSession(sessionId);

			expect(removed1).toBe(true);
			expect(removed2).toBe(false);
		});
	});

	describe('Session Management', () => {
		beforeEach(async () => {
			await sessionManager.init();
		});

		it('should get all active sessions', async () => {
			await sessionManager.createSession('session1');
			await sessionManager.createSession('session2');
			await sessionManager.createSession('session3');

			const allSessions = await sessionManager.getAllSessions();
			expect(allSessions).toHaveLength(3);

			const sessionIds = allSessions.map(session => session.id);
			expect(sessionIds).toContain('session1');
			expect(sessionIds).toContain('session2');
			expect(sessionIds).toContain('session3');
		});

		it('should get active session IDs', async () => {
			await sessionManager.createSession('session1');
			await sessionManager.createSession('session2');

			const sessionIds = await sessionManager.getActiveSessionIds();
			expect(sessionIds).toHaveLength(2);
			expect(sessionIds).toContain('session1');
			expect(sessionIds).toContain('session2');
		});

		it('should get session count', async () => {
			await sessionManager.createSession('session1');
			await sessionManager.createSession('session2');

			const count = await sessionManager.getSessionCount();
			expect(count).toBe(2);
		});

		it('should clean up expired sessions automatically', async () => {
			const shortTTLManager = new SessionManager(mockServices, { sessionTTL: 10 }); // 10ms TTL
			await shortTTLManager.init();

			await shortTTLManager.createSession('session1');
			await shortTTLManager.createSession('session2');

			// Wait for sessions to expire
			await new Promise(resolve => setTimeout(resolve, 20));

			// Getting active session IDs should trigger cleanup
			const sessionIds = await shortTTLManager.getActiveSessionIds();
			expect(sessionIds).toHaveLength(0);

			await shortTTLManager.shutdown();
		});
	});

	describe('Concurrent Operations', () => {
		beforeEach(async () => {
			await sessionManager.init();
		});

		it('should handle concurrent session operations', async () => {
			const operations = Array.from({ length: 10 }, (_, i) =>
				sessionManager.createSession(`concurrent-${i}`)
			);

			const sessions = await Promise.all(operations);
			expect(sessions).toHaveLength(10);

			const sessionCount = await sessionManager.getSessionCount();
			expect(sessionCount).toBe(10);
		});

		it('should handle mixed concurrent operations', async () => {
			// Create some initial sessions
			await sessionManager.createSession('concurrent1');
			await sessionManager.createSession('concurrent2');

			const operations = [
				sessionManager.getSession('concurrent1'),
				sessionManager.createSession('concurrent3'),
				sessionManager.removeSession('concurrent2'),
				sessionManager.getActiveSessionIds(),
				sessionManager.getSessionCount(),
			];

			const results = await Promise.all(operations);

			expect(results[0]).toBeDefined(); // getSession result
			expect(results[1]).toBeDefined(); // createSession result
			expect(results[2]).toBe(true); // removeSession result
			expect(Array.isArray(results[3])).toBe(true); // getActiveSessionIds result
			expect(typeof results[4]).toBe('number'); // getSessionCount result
		});
	});

	describe('Error Handling', () => {
		beforeEach(async () => {
			await sessionManager.init();
		});

		it('should handle session initialization errors', async () => {
			const MockedConversationSession = vi.mocked(ConversationSession);
			MockedConversationSession.mockImplementationOnce(
				(services, sessionId) =>
					({
						id: sessionId,
						init: vi.fn().mockRejectedValue(new Error('Init failed')),
						run: vi.fn(),
						getContextManager: vi.fn(),
						getLLMService: vi.fn(),
					}) as any
			);

			await expect(sessionManager.createSession()).rejects.toThrow('Init failed');
		});

		it('should handle service errors gracefully', async () => {
			const MockedConversationSession = vi.mocked(ConversationSession);
			MockedConversationSession.mockImplementationOnce((services, sessionId) => {
				// Access the state manager to trigger the error
				services.stateManager.getLLMConfig(sessionId);
				return {
					id: sessionId,
					init: vi.fn().mockResolvedValue(undefined),
					run: vi.fn().mockResolvedValue('Mock response'),
					getContextManager: vi.fn(),
					getLLMService: vi.fn(),
				} as any;
			});

			mockStateManager.getLLMConfig.mockImplementation(() => {
				throw new Error('State manager error');
			});

			await expect(sessionManager.createSession()).rejects.toThrow('State manager error');
		});
	});

	describe('Cleanup and Shutdown', () => {
		it('should clean up resources on shutdown', async () => {
			await sessionManager.init();
			await sessionManager.createSession('test1');
			await sessionManager.createSession('test2');

			let sessionCount = await sessionManager.getSessionCount();
			expect(sessionCount).toBe(2);

			await sessionManager.shutdown();

			// After shutdown, operations should auto-initialize, but previous sessions should be gone
			sessionCount = await sessionManager.getSessionCount();
			expect(sessionCount).toBe(0);
		});

		it('should handle shutdown when not initialized', async () => {
			// Should not throw error
			await expect(sessionManager.shutdown()).resolves.toBeUndefined();
		});

		it('should handle multiple shutdown calls', async () => {
			await sessionManager.init();

			await sessionManager.shutdown();
			await sessionManager.shutdown(); // Second call should be safe

			expect(true).toBe(true); // Test passes if no errors thrown
		});
	});

	describe('Configuration Edge Cases', () => {
		it('should handle zero max sessions configuration', async () => {
			const zeroMaxManager = new SessionManager(mockServices, { maxSessions: 0 });
			await zeroMaxManager.init();

			// Should still be able to create sessions (eviction will happen immediately)
			const session = await zeroMaxManager.createSession();
			expect(session).toBeDefined();

			await zeroMaxManager.shutdown();
		});

		it('should handle very short session TTL', async () => {
			const shortTTLManager = new SessionManager(mockServices, { sessionTTL: 1 });
			await shortTTLManager.init();

			const session = await shortTTLManager.createSession('short-lived');
			expect(session).toBeDefined();

			// Session should expire almost immediately
			await new Promise(resolve => setTimeout(resolve, 5));
			const retrievedSession = await shortTTLManager.getSession('short-lived');
			expect(retrievedSession).toBeNull();

			await shortTTLManager.shutdown();
		});

		it('should handle very long session TTL', async () => {
			const longTTLManager = new SessionManager(mockServices, {
				sessionTTL: Number.MAX_SAFE_INTEGER,
			});
			await longTTLManager.init();

			const session = await longTTLManager.createSession('long-lived');
			expect(session).toBeDefined();

			// Session should not expire
			await new Promise(resolve => setTimeout(resolve, 10));
			const retrievedSession = await longTTLManager.getSession('long-lived');
			expect(retrievedSession).toBe(session);

			await longTTLManager.shutdown();
		});
	});
});

import { ContextManager, ILLMService } from '../brain/llm/index.js';
import { MCPManager } from '../mcp/manager.js';
import { UnifiedToolManager } from '../brain/tools/unified-tool-manager.js';
import { logger } from '../logger/index.js';
import { env } from '../env.js';
import { createContextManager } from '../brain/llm/messages/factory.js';
import { createLLMService } from '../brain/llm/services/factory.js';
import { MemAgentStateManager } from '../brain/memAgent/state-manager.js';
import { ReasoningContentDetector } from '../brain/reasoning/content-detector.js';
import { SearchContextManager } from '../brain/reasoning/search-context-manager.js';
import {
	createMultiBackendHistoryProvider,
	createDatabaseHistoryProvider,
} from '../brain/llm/messages/history/factory.js';
import { WALHistoryProvider } from '../brain/llm/messages/history/wal.js';
import { StorageManager } from '../storage/manager.js';
import type { ZodSchema } from 'zod';
import { setImmediate } from 'timers';
import { IConversationHistoryProvider } from '../brain/llm/messages/history/types.js';
import type { SerializedSession } from './persistence-types.js';
import { SESSION_PERSISTENCE_CONSTANTS, SessionPersistenceError } from './persistence-types.js';
import { IMessageFormatter } from '../brain/llm/messages/formatters/types.js';
import { OpenAIMessageFormatter } from '../brain/llm/messages/formatters/openai.js';
import { AzureMessageFormatter } from '../brain/llm/messages/formatters/azure.js';
import { AnthropicMessageFormatter } from '../brain/llm/messages/formatters/anthropic.js';

// This function is currently unused but kept for potential future use
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function extractReasoningContentBlocks(aiResponse: any): string {
	// If the response is an object with a content array (Anthropic API best practice)
	if (aiResponse && Array.isArray(aiResponse.content)) {
		// Extract all 'thinking' and 'redacted_thinking' blocks
		const reasoningBlocks = aiResponse.content
			.filter((block: any) => block.type === 'thinking' || block.type === 'redacted_thinking')
			.map((block: any) => block.thinking)
			.filter(Boolean);
		if (reasoningBlocks.length > 0) {
			return reasoningBlocks.join('\n\n');
		}
		// Fallback: join all text blocks if no thinking blocks found
		const textBlocks = aiResponse.content
			.filter((block: any) => block.type === 'text' && block.text)
			.map((block: any) => block.text);
		if (textBlocks.length > 0) {
			return textBlocks.join('\n\n');
		}
		return '';
	}
	// Fallback: support legacy string input (regex for <thinking> tags)
	if (typeof aiResponse === 'string') {
		const matches = Array.from(aiResponse.matchAll(/<thinking>([\s\S]*?)<\/thinking>/gi));
		if (matches.length > 0) {
			return matches.map(m => m[1]?.trim() || '').join('\n\n');
		}
		return aiResponse;
	}
	return '';
}
import { EnhancedPromptManager } from '../brain/systemPrompt/enhanced-manager.js';
export class ConversationSession {
	private contextManager!: ContextManager;
	private _llmService?: ILLMService; // Changed to lazy-loaded
	private reasoningDetector?: ReasoningContentDetector;
	private searchContextManager?: SearchContextManager;
	private _historyProvider?: IConversationHistoryProvider | undefined; // Changed to lazy-loaded
	private _storageManager?: StorageManager; // Added for lazy loading
	private historyEnabled: boolean = true;
	private historyBackend: 'database' | 'memory' = 'database';

	private sessionMemoryMetadata?: Record<string, any>;
	private mergeMetadata?: (
		sessionMeta: Record<string, any>,
		runMeta: Record<string, any>
	) => Record<string, any>;
	private metadataSchema?: ZodSchema<any>;
	private beforeMemoryExtraction?: (
		meta: Record<string, any>,
		context: Record<string, any>
	) => void;

	// Lazy initialization flags
	private _servicesInitialized = false;
	private _llmServiceInitialized = false;
	private _storageInitialized = false;

	/**
	 * @param services - Required dependencies for the session, including unifiedToolManager
	 * @param id - Session identifier
	 * @param options - Optional advanced metadata options
	 */
	constructor(
		private services: {
			stateManager: MemAgentStateManager;
			promptManager: EnhancedPromptManager;
			contextManager: ContextManager;
			mcpManager: MCPManager;
			unifiedToolManager: UnifiedToolManager;
			embeddingManager?: any; // Optional embedding manager for status checking
			eventManager?: any; // Add event manager to services
		},
		public readonly id: string,
		options?: {
			sessionMemoryMetadata?: Record<string, any>;
			mergeMetadata?: (
				sessionMeta: Record<string, any>,
				runMeta: Record<string, any>
			) => Record<string, any>;
			metadataSchema?: ZodSchema<any>;
			beforeMemoryExtraction?: (meta: Record<string, any>, context: Record<string, any>) => void;
			historyEnabled?: boolean;
			historyBackend?: 'database' | 'memory';
			sharedStorageManager?: StorageManager; // Allow sharing storage manager
		}
	) {
		if (options?.sessionMemoryMetadata) {
			this.sessionMemoryMetadata = options.sessionMemoryMetadata;
		}
		if (options?.mergeMetadata) {
			this.mergeMetadata = options.mergeMetadata;
		}
		if (options?.metadataSchema) {
			this.metadataSchema = options.metadataSchema;
		}
		if (options?.beforeMemoryExtraction) {
			this.beforeMemoryExtraction = options.beforeMemoryExtraction;
		}
		if (typeof options?.historyEnabled === 'boolean') {
			this.historyEnabled = options.historyEnabled;
		}
		if (options?.historyBackend) {
			this.historyBackend = options.historyBackend;
		}
		if (options?.sharedStorageManager) {
			this._storageManager = options.sharedStorageManager;
			this._storageInitialized = true;
		}
	}

	/**
	 * Update session-level memory metadata after construction.
	 */
	public updateSessionMetadata(newMeta: Record<string, any>) {
		this.sessionMemoryMetadata = { ...this.sessionMemoryMetadata, ...newMeta };
	}

	/**
	 * Initialize all services for the session, including history provider.
	 */
	public async init(): Promise<void> {
		await this.initializeServices();
		// Note: History restoration will happen lazily when history is first accessed
		// This improves startup performance by not initializing storage until needed
	}

	/**
	 * Initializes the services for the session, including the history provider.
	 */
	private async initializeServices(): Promise<void> {
		// Create a session-specific context manager instead of using the shared one
		const llmConfig = this.services.stateManager.getLLMConfig(this.id);
		const formatter = this.getFormatterForProvider(llmConfig.provider);
		this.contextManager = new ContextManager(
			formatter,
			this.services.promptManager,
			undefined, // historyProvider will be lazy-loaded
			this.id // sessionId
		);

		// CRITICAL FIX: Initialize history provider early if shared storage manager is available
		// This ensures conversation history is available immediately for new sessions
		if (this._storageManager && this.historyEnabled) {
			try {
				this._historyProvider = createDatabaseHistoryProvider(this._storageManager);
				logger.debug(
					`Session ${this.id}: History provider initialized during service initialization.`
				);

				// Set the history provider in the context manager
				(this.contextManager as any).historyProvider = this._historyProvider;
			} catch (error) {
				logger.warn(
					`Session ${this.id}: Failed to initialize history provider during service initialization:`,
					error
				);
			}
		}

		this._servicesInitialized = true;
	}

	/**
	 * Get the appropriate formatter for the provider
	 */
	private getFormatterForProvider(provider: string): IMessageFormatter {
		const normalizedProvider = provider.toLowerCase();
		switch (normalizedProvider) {
			case 'openai':
			case 'openrouter':
			case 'ollama':
			case 'lmstudio':
			case 'qwen':
			case 'gemini':
				return new OpenAIMessageFormatter();
			case 'azure':
				return new AzureMessageFormatter();
			case 'anthropic':
			case 'aws':
				return new AnthropicMessageFormatter();
			default:
				throw new Error(
					`Unsupported provider: ${provider}. Supported providers: openai, anthropic, openrouter, ollama, lmstudio, qwen, aws, azure, gemini`
				);
		}
	}

	/**
	 * Lazy initialization of LLM service
	 */
	private async getLLMServiceLazy(): Promise<ILLMService> {
		if (!this._servicesInitialized || !this.contextManager) {
			throw new Error(
				'ConversationSession is not initialized. Call init() before accessing services.'
			);
		}

		if (!this._llmServiceInitialized) {
			try {
				const llmConfig = this.services.stateManager.getLLMConfig(this.id);
				this._llmService = createLLMService(
					llmConfig,
					this.services.mcpManager,
					this.contextManager,
					this.services.unifiedToolManager,
					this.services.eventManager
				);
				this._llmServiceInitialized = true;
				logger.debug(`Session ${this.id}: LLM service lazy-initialized`);
			} catch (error) {
				logger.error(`Session ${this.id}: Failed to lazy-initialize LLM service`, { error });
				throw error;
			}
		}
		return this._llmService!;
	}

	/**
	 * Lazy initialization of storage manager and history provider with PostgreSQL/SQLite support
	 */
	private async getStorageManagerLazy(): Promise<StorageManager | undefined> {
		if (!this._storageInitialized) {
			try {
				if (this.historyEnabled) {
					// Multi-backend config example (can be extended to use env/config)
					const multiBackendEnabled = !!process.env.CIPHER_MULTI_BACKEND;
					const flushIntervalMs = process.env.CIPHER_WAL_FLUSH_INTERVAL
						? parseInt(process.env.CIPHER_WAL_FLUSH_INTERVAL, 10)
						: 5000;

					if (multiBackendEnabled) {
						// Example: primary = Postgres, backup = SQLite, WAL = in-memory
						const primaryStorage = new StorageManager({
							database: { type: 'postgres' as const, url: process.env.CIPHER_PG_URL },
							cache: { type: 'in-memory' as const },
						});
						await primaryStorage.connect();
						const backupStorage = new StorageManager({
							database: { type: 'sqlite' as const, path: './cipher-backup.db' },
							cache: { type: 'in-memory' as const },
						});
						await backupStorage.connect();
						const primaryProvider = createDatabaseHistoryProvider(primaryStorage);
						const backupProvider = createDatabaseHistoryProvider(backupStorage);
						const wal = new WALHistoryProvider();
						this._historyProvider = createMultiBackendHistoryProvider(
							primaryProvider,
							backupProvider,
							wal,
							flushIntervalMs
						);
						logger.debug(`Session ${this.id}: Multi-backend history provider lazy-initialized.`);
					} else if (this.historyBackend === 'database') {
						// CRITICAL FIX: Add a small delay to prevent storage manager conflicts
						// This prevents race conditions when multiple sessions are initializing storage
						if (!this._storageManager) {
							await new Promise(resolve => setTimeout(resolve, 25));
						}

						// Use shared storage manager if available, otherwise create new one
						if (!this._storageManager) {
							// Use the same storage configuration as the session manager
							// This ensures both session data and conversation history use the same backend
							const postgresUrl = process.env.CIPHER_PG_URL;
							const postgresHost = process.env.STORAGE_DATABASE_HOST;
							const postgresDatabase = process.env.STORAGE_DATABASE_NAME;

							let storageConfig: any;

							if (postgresUrl || (postgresHost && postgresDatabase)) {
								// Use PostgreSQL if configured
								if (postgresUrl) {
									storageConfig = {
										database: { type: 'postgres' as const, url: postgresUrl },
										cache: { type: 'in-memory' as const },
									};
								} else {
									storageConfig = {
										database: {
											type: 'postgres' as const,
											host: postgresHost,
											database: postgresDatabase,
											port: process.env.STORAGE_DATABASE_PORT
												? parseInt(process.env.STORAGE_DATABASE_PORT, 10)
												: 5432,
											user: process.env.STORAGE_DATABASE_USER,
											password: process.env.STORAGE_DATABASE_PASSWORD,
											ssl: process.env.STORAGE_DATABASE_SSL === 'true',
										},
										cache: { type: 'in-memory' as const },
									};
								}
								logger.debug(
									`Session ${this.id}: Using PostgreSQL for history provider (lazy-loaded)`
								);
							} else {
								// Fallback to SQLite
								storageConfig = {
									database: {
										type: 'sqlite' as const,
										path: env.STORAGE_DATABASE_PATH || './data',
										database: env.STORAGE_DATABASE_NAME || 'cipher-sessions.db',
									},
									cache: { type: 'in-memory' as const },
								};
								logger.debug(`Session ${this.id}: Using SQLite for history provider (lazy-loaded)`);
							}

							this._storageManager = new StorageManager(storageConfig);
							await this._storageManager.connect();
							logger.debug(
								`Session ${this.id}: Database history provider lazy-initialized with ${storageConfig.database.type} backend.`
							);
						} else {
							logger.debug(
								`Session ${this.id}: Using shared storage manager for history provider.`
							);
						}

						// CRITICAL FIX: Always create the history provider, whether using shared or new storage manager
						this._historyProvider = createDatabaseHistoryProvider(this._storageManager);
						logger.debug(`Session ${this.id}: History provider created with storage manager.`);
					} else {
						// TODO: Implement or import an in-memory provider if needed
						logger.debug(`Session ${this.id}: In-memory history provider selected (lazy-loaded).`);
					}
				}
				this._storageInitialized = true;
			} catch (error) {
				logger.warn(`Session ${this.id}: Failed to initialize storage manager:`, error);
				// Continue without storage manager
			}
		}
		return this._storageManager;
	}

	/**
	 * Lazy initialization of history provider
	 */
	private async getHistoryProviderLazy(): Promise<IConversationHistoryProvider | undefined> {
		if (!this._storageInitialized) {
			await this.getStorageManagerLazy();
		}

		// CRITICAL FIX: If history provider is still not available after storage initialization,
		// try to create it again
		if (!this._historyProvider && this.historyEnabled && this._storageManager) {
			try {
				this._historyProvider = createDatabaseHistoryProvider(this._storageManager);
				logger.debug(`Session ${this.id}: History provider created in lazy initialization.`);
			} catch (error) {
				logger.warn(
					`Session ${this.id}: Failed to create history provider in lazy initialization:`,
					error
				);
			}
		}

		return this._historyProvider;
	}

	/**
	 * Restore history when history provider is lazy-loaded
	 */
	private async restoreHistoryLazy(): Promise<void> {
		if (this.historyEnabled) {
			try {
				const historyProvider = await this.getHistoryProviderLazy();
				if (historyProvider && this.contextManager) {
					// Update context manager with the lazy-loaded history provider
					(this.contextManager as any).historyProvider = historyProvider;
					await this.contextManager.restoreHistory?.();
					logger.debug(`Session ${this.id}: Conversation history restored (lazy-loaded)`);
				}
			} catch (err) {
				logger.warn(`Session ${this.id}: Failed to restore conversation history: ${err}`);
			}
		}
	}

	/**
	 * Extract session-level metadata, merging defaults, session, and per-run metadata.
	 * Uses custom merge and validation if provided.
	 * Now supports environment and extensible context.
	 */
	private getSessionMetadata(customMetadata?: Record<string, any>): Record<string, any> {
		const base = {
			sessionId: this.id,
			source: 'conversation-session',
			timestamp: new Date().toISOString(),
			environment: process.env.NODE_ENV || 'development',
			...this.getSessionContext(),
		};
		const sessionMeta = this.sessionMemoryMetadata || {};
		const customMeta =
			customMetadata && typeof customMetadata === 'object' && !Array.isArray(customMetadata)
				? customMetadata
				: {};
		let merged = this.mergeMetadata
			? this.mergeMetadata(sessionMeta, customMeta)
			: { ...base, ...sessionMeta, ...customMeta };
		if (this.metadataSchema && !this.metadataSchema.safeParse(merged).success) {
			logger.warn(
				'ConversationSession: Metadata validation failed, using session-level metadata only.'
			);
			merged = { ...base, ...sessionMeta };
		}
		return merged;
	}

	/**
	 * Optionally override to provide additional session context for metadata.
	 */
	protected getSessionContext(): Record<string, any> {
		return {};
	}

	/**
	 * Run a conversation session with input, optional image data, streaming, and custom options.
	 * @param input - User input string
	 * @param imageDataInput - Optional image data
	 * @param stream - Optional stream flag
	 * @param options - Optional parameters for memory extraction:
	 *   - memoryMetadata: Custom metadata to attach to memory extraction (merged with session defaults)
	 *   - contextOverrides: Overrides for context fields passed to memory extraction
	 *   - historyTracking: Enable/disable history tracking
	 * @returns An object containing the response and a promise for background operations
	 */
	public async run(
		input: string,
		imageDataInput?: { image: string; mimeType: string },
		stream?: boolean,
		options?: {
			memoryMetadata?: Record<string, any>;
			contextOverrides?: Record<string, any>;
			historyTracking?: boolean;
		}
	): Promise<{ response: string; backgroundOperations: Promise<void> }> {
		// --- Input validation ---
		if (typeof input !== 'string' || input.trim() === '') {
			logger.error('ConversationSession.run: input must be a non-empty string');
			throw new Error('Input must be a non-empty string');
		}

		// --- Session initialization check ---
		if (!this._servicesInitialized || !this.contextManager) {
			logger.error('ConversationSession.run: Session not initialized. Call init() before run().');
			throw new Error('ConversationSession is not initialized. Call init() before run().');
		}

		// --- imageDataInput validation ---
		if (
			imageDataInput !== undefined &&
			(typeof imageDataInput !== 'object' ||
				!imageDataInput.image ||
				typeof imageDataInput.image !== 'string' ||
				!imageDataInput.mimeType ||
				typeof imageDataInput.mimeType !== 'string')
		) {
			logger.error(
				'ConversationSession.run: imageDataInput must have image and mimeType as non-empty strings'
			);
			throw new Error('imageDataInput must have image and mimeType as non-empty strings');
		}

		// --- stream validation ---
		if (stream !== undefined && typeof stream !== 'boolean') {
			logger.warn('ConversationSession.run: stream should be a boolean. Coercing to boolean.');
			stream = Boolean(stream);
		}

		// --- options validation ---
		if (options && typeof options === 'object') {
			const allowedKeys = ['memoryMetadata', 'contextOverrides', 'historyTracking'];
			const unknownKeys = Object.keys(options).filter(k => !allowedKeys.includes(k));
			if (unknownKeys.length > 0) {
				logger.warn(
					`ConversationSession.run: Unknown option keys provided: ${unknownKeys.join(', ')}`
				);
			}
		}

		logger.debug('ConversationSession.run called');
		logger.debug(
			`Running session ${this.id} with input: ${input} and imageDataInput: ${imageDataInput} and stream: ${stream}`
		);

		// Initialize reasoning detector and search context manager if not already done
		await this.initializeReasoningServices();

		// Restore history if enabled (lazy-loaded)
		await this.restoreHistoryLazy();

		// Lazy initialize LLM service when first needed
		const llmService = await this.getLLMServiceLazy();

		// Emit thinking event before starting generation
		if (this.services.eventManager) {
			try {
				const sessionBus = this.services.eventManager.getSessionEventBus(this.id);
				sessionBus.emit('llm:thinking', {
					sessionId: this.id,
					timestamp: Date.now(),
				});
				logger.debug('Emitted llm:thinking event', { sessionId: this.id });
			} catch (error) {
				logger.warn('Failed to emit thinking event', {
					sessionId: this.id,
					error: error instanceof Error ? error.message : String(error),
				});
			}
		}

		// Generate response
		const response = await llmService.generate(input, imageDataInput, stream);

		// PROGRAMMATIC ENFORCEMENT: Run memory extraction asynchronously in background AFTER response is returned
		// This ensures users see the response immediately without waiting for memory operations
		const backgroundOperations = new Promise<void>(resolve => {
			setImmediate(async () => {
				// Quick check to skip all background operations if embeddings are disabled
				const embeddingsDisabled = env.DISABLE_EMBEDDINGS || env.EMBEDDING_DISABLED;

				// Also check embedding manager status if available
				let embeddingManagerDisabled = false;
				if (this.services.embeddingManager) {
					// Check global embedding state
					try {
						const { EmbeddingSystemState } = require('../embedding/manager.js');
						if (EmbeddingSystemState.getInstance().isDisabled()) {
							embeddingManagerDisabled = true;
						}
					} catch {
						// If EmbeddingSystemState is not available, continue with other checks
					}

					// Check if no embeddings are available
					if (!this.services.embeddingManager?.hasAvailableEmbeddings()) {
						embeddingManagerDisabled = true;
					}

					// Check if any embedders are disabled
					const embeddingStatus = this.services.embeddingManager?.getEmbeddingStatus();
					if (embeddingStatus) {
						const disabledEmbedders = Object.values(embeddingStatus).filter(
							(status: any) => status.status === 'DISABLED'
						);
						if (disabledEmbedders.length > 0) {
							embeddingManagerDisabled = true;
						}
					}
				}

				if (embeddingsDisabled || embeddingManagerDisabled) {
					logger.debug('Skipping all background memory operations - embeddings disabled', {
						sessionId: this.id,
						envDisabled: embeddingsDisabled,
						managerDisabled: embeddingManagerDisabled,
					});
					resolve();
					return;
				}

				logger.debug('Starting background memory operations', { sessionId: this.id });
				try {
					await this.enforceMemoryExtraction(input, response, options);
					logger.debug('Background memory operations completed successfully', {
						sessionId: this.id,
					});
				} catch (error) {
					logger.debug('Background memory extraction failed', {
						sessionId: this.id,
						error: error instanceof Error ? error.message : String(error),
					});
					// Silently continue - memory extraction failures shouldn't affect user experience
				}
				resolve();
			});
		});

		return { response, backgroundOperations };
	}

	/**
	 * Programmatically enforce memory extraction after each user interaction (runs in background)
	 * This ensures the extract_and_operate_memory tool is always called, regardless of AI decisions
	 * NOTE: This method runs asynchronously in the background to avoid delaying the user response
	 */
	private async enforceMemoryExtraction(
		userInput: string,
		aiResponse: string,
		options?: {
			memoryMetadata?: Record<string, any>;
			contextOverrides?: Record<string, any>;
			historyTracking?: boolean;
		}
	): Promise<void> {
		logger.debug('ConversationSession.enforceMemoryExtraction called');
		logger.debug('enforceMemoryExtraction: unifiedToolManager at entry', {
			unifiedToolManager: this.services.unifiedToolManager,
			type: typeof this.services.unifiedToolManager,
		});
		try {
			logger.debug('ConversationSession: Enforcing memory extraction for interaction');

			// Check if embeddings are disabled via environment variables or configuration
			const embeddingsDisabled = env.DISABLE_EMBEDDINGS || env.EMBEDDING_DISABLED;

			// Also check embedding manager status if available
			let embeddingManagerDisabled = false;
			if (this.services.embeddingManager) {
				// Check global embedding state
				try {
					const { EmbeddingSystemState } = require('../embedding/manager.js');
					if (EmbeddingSystemState.getInstance().isDisabled()) {
						embeddingManagerDisabled = true;
					}
				} catch {
					// If EmbeddingSystemState is not available, continue with other checks
				}

				// Check if no embeddings are available
				if (!this.services.embeddingManager?.hasAvailableEmbeddings()) {
					embeddingManagerDisabled = true;
				}

				// Check if any embedders are disabled
				const embeddingStatus = this.services.embeddingManager?.getEmbeddingStatus();
				if (embeddingStatus) {
					const disabledCount = Object.values(embeddingStatus).filter(
						(status: any) => status.status === 'DISABLED'
					).length;
					if (disabledCount > 0) {
						embeddingManagerDisabled = true;
					}
				}
			}

			if (embeddingsDisabled || embeddingManagerDisabled) {
				logger.debug('ConversationSession: Embeddings disabled, skipping memory extraction', {
					envDisabled: embeddingsDisabled,
					managerDisabled: embeddingManagerDisabled,
				});
				return;
			}

			// Check if the unifiedToolManager is available
			if (!this.services.unifiedToolManager) {
				logger.debug(
					'ConversationSession: UnifiedToolManager not available, skipping memory extraction'
				);
				return;
			}

			// Check if workspace memory is enabled
			const workspaceMemoryEnabled = env.USE_WORKSPACE_MEMORY;
			const shouldDisableDefaultMemory = workspaceMemoryEnabled && env.DISABLE_DEFAULT_MEMORY;

			// Determine which memory tools to run based on configuration
			const shouldRunWorkspace = workspaceMemoryEnabled;
			const shouldRunDefault = !shouldDisableDefaultMemory;

			if (embeddingsDisabled) {
				logger.debug('ConversationSession: Memory extraction skipped - embeddings disabled', {
					embeddingsDisabled,
					workspaceMemoryEnabled,
					shouldDisableDefaultMemory,
				});
				return;
			}

			logger.debug('ConversationSession: Memory tools to execute', {
				workspaceMemoryEnabled,
				shouldDisableDefaultMemory,
				shouldRunWorkspace,
				shouldRunDefault,
			});

			// Extract comprehensive interaction data including tool usage
			const comprehensiveInteractionData = await this.extractComprehensiveInteractionData(
				userInput,
				aiResponse
			);

			// Prepare context with overrides
			const defaultContext = {
				sessionId: this.id,
				conversationTopic: 'Interactive CLI session',
				recentMessages: comprehensiveInteractionData,
			};
			const mergedContext = {
				...defaultContext,
				...(options?.contextOverrides &&
				typeof options.contextOverrides === 'object' &&
				!Array.isArray(options.contextOverrides)
					? options.contextOverrides
					: {}),
			};

			// Prepare memory metadata (merge session-level and per-run, per-run takes precedence)
			let memoryMetadata: Record<string, any> = {};
			if (options?.memoryMetadata !== undefined) {
				if (typeof options.memoryMetadata === 'object' && !Array.isArray(options.memoryMetadata)) {
					memoryMetadata = this.getSessionMetadata(options.memoryMetadata);
				} else {
					logger.warn(
						'ConversationSession: Invalid memoryMetadata provided, expected a plain object. Using session-level or default metadata.'
					);
					memoryMetadata = this.getSessionMetadata();
				}
			} else {
				memoryMetadata = this.getSessionMetadata();
			}

			// Execute memory tools based on configuration
			const memoryResults: any[] = [];

			// Execute workspace memory tool if enabled
			if (shouldRunWorkspace) {
				const workspaceArgs = {
					interaction: comprehensiveInteractionData,
					context: mergedContext,
					options: {
						similarityThreshold: 0.8,
						confidenceThreshold: 0.6,
						enableBatchProcessing: true,
						autoExtractWorkspaceInfo: true,
					},
				};

				try {
					const workspaceResult = await this.services.unifiedToolManager.executeToolWithoutLoading(
						'cipher_workspace_store',
						workspaceArgs
					);
					memoryResults.push({ tool: 'cipher_workspace_store', result: workspaceResult });
					logger.debug('ConversationSession: Workspace memory tool executed successfully');
				} catch (error) {
					logger.debug('ConversationSession: Workspace memory tool execution failed', {
						error: error instanceof Error ? error.message : String(error),
					});
				}
			}

			// Execute default memory tool if not disabled
			if (shouldRunDefault) {
				const defaultArgs = {
					interaction: comprehensiveInteractionData,
					context: mergedContext,
					memoryMetadata,
					options: {
						similarityThreshold: 0.7,
						maxSimilarResults: 5,
						useLLMDecisions: true,
						confidenceThreshold: 0.4,
						enableDeleteOperations: true,
						historyTracking: options?.historyTracking ?? true,
					},
				};

				try {
					const defaultResult = await this.services.unifiedToolManager.executeToolWithoutLoading(
						'cipher_extract_and_operate_memory',
						defaultArgs
					);
					memoryResults.push({ tool: 'cipher_extract_and_operate_memory', result: defaultResult });
					logger.debug('ConversationSession: Default memory tool executed successfully');
				} catch (error) {
					logger.debug('ConversationSession: Default memory tool execution failed', {
						error: error instanceof Error ? error.message : String(error),
					});
				}
			}

			// If no tools were executed successfully, return early
			if (memoryResults.length === 0) {
				logger.debug('ConversationSession: No memory tools executed successfully');
				return;
			}

			// Aggregate results from all executed tools
			let totalExtractedFacts = 0;
			let totalMemoryActions = 0;
			const toolSummary: any = {};
			const combinedActions: any[] = [];

			for (const { tool, result } of memoryResults) {
				if (result.success) {
					totalExtractedFacts += result.extraction?.extracted || 0;

					// Get actions from the appropriate field based on tool type
					const actions =
						tool === 'cipher_workspace_store' ? result.workspace || [] : result.memory || [];

					totalMemoryActions += actions.length;
					combinedActions.push(...actions);

					toolSummary[tool] = {
						success: true,
						extractedFacts: result.extraction?.extracted || 0,
						memoryActions: actions.length,
					};
				} else {
					toolSummary[tool] = { success: false };
				}
			}

			logger.debug('ConversationSession: Memory extraction completed', {
				toolsExecuted: memoryResults.map(r => r.tool),
				shouldRunWorkspace,
				shouldRunDefault,
				totalExtractedFacts,
				totalMemoryActions,
				toolSummary,
				actionBreakdown:
					combinedActions.length > 0
						? {
								ADD: combinedActions.filter((a: any) => a.event === 'ADD').length,
								UPDATE: combinedActions.filter((a: any) => a.event === 'UPDATE').length,
								DELETE: combinedActions.filter((a: any) => a.event === 'DELETE').length,
								NONE: combinedActions.filter((a: any) => a.event === 'NONE').length,
							}
						: {},
			});

			// **NEW: Automatic Reflection Memory Processing**
			// Process reasoning traces in the background, similar to knowledge memory
			// Load tools for reflection processing (separate from background memory extraction)
			const allTools = await this.services.unifiedToolManager.getAllTools();
			await this.enforceReflectionMemoryProcessing(userInput, aiResponse, allTools);
		} catch (error) {
			const errorMessage = error instanceof Error ? error.message : String(error);
			logger.error('ConversationSession: Memory extraction failed', {
				error: errorMessage,
			});
			// Continue execution even if memory extraction fails
		}
	}

	/**
	 * Initialize reasoning services (content detector and search context manager)
	 */
	private async initializeReasoningServices(): Promise<void> {
		if (this.reasoningDetector && this.searchContextManager) {
			return; // Already initialized
		}

		try {
			// Initialize reasoning content detector with evaluation LLM config
			const evalLlmConfig = this.services.stateManager.getEvalLLMConfig(this.id);
			this.reasoningDetector = new ReasoningContentDetector(
				this.services.promptManager,
				this.services.mcpManager,
				this.services.unifiedToolManager,
				evalLlmConfig,
				undefined // Use default options
			);

			// Initialize search context manager
			this.searchContextManager = new SearchContextManager();

			logger.debug('ConversationSession: Reasoning services initialized', { sessionId: this.id });
		} catch (error) {
			logger.warn('ConversationSession: Failed to initialize reasoning services', {
				sessionId: this.id,
				error: error instanceof Error ? error.message : String(error),
			});
		}
	}

	/**
	 * Programmatically enforce reflection memory processing after each interaction (runs in background)
	 * This automatically extracts, evaluates, and stores reasoning patterns in the background
	 * NOTE: This method is called from enforceMemoryExtraction which already runs asynchronously
	 * @param userInput - The user input string
	 * @param aiResponse - The AI response string
	 * @param allTools - Pre-loaded tools to avoid redundant loading
	 */
	private async enforceReflectionMemoryProcessing(
		userInput: string,
		_aiResponse: string,
		allTools: Record<string, any>
	): Promise<void> {
		try {
			logger.debug('ConversationSession: Enforcing reflection memory processing');

			// Check if embeddings are disabled via environment variables or configuration
			const embeddingsDisabled = env.DISABLE_EMBEDDINGS || env.EMBEDDING_DISABLED;

			// Check if the unifiedToolManager is available
			if (!this.services.unifiedToolManager) {
				logger.debug(
					'ConversationSession: UnifiedToolManager not available, skipping reflection memory processing'
				);
				return;
			}

			// Check if reflection memory tools are available (using pre-loaded tools)
			const reflectionToolsAvailable =
				allTools['cipher_extract_reasoning_steps'] && allTools['cipher_store_reasoning_memory'];
			if (embeddingsDisabled || !reflectionToolsAvailable) {
				logger.debug('ConversationSession: Reflection memory processing skipped', {
					embeddingsDisabled,
					reflectionToolsAvailable: !!reflectionToolsAvailable,
					reason: embeddingsDisabled ? 'embeddings disabled' : 'reflection tools unavailable',
				});
				return;
			}

			// Check if reflection memory is force disabled
			if (env.DISABLE_REFLECTION_MEMORY) {
				logger.debug(
					'ConversationSession: Reflection memory force disabled via DISABLE_REFLECTION_MEMORY, skipping processing'
				);
				return;
			}

			// Initialize reasoning services if not already done
			await this.initializeReasoningServices();

			// Check if reasoning content is detected in user input
			if (!this.reasoningDetector) {
				logger.debug(
					'ConversationSession: Reasoning detector not available, skipping reflection processing'
				);
				return;
			}

			const reasoningDetection = await this.reasoningDetector.detectReasoningContent(userInput, {
				sessionId: this.id,
				taskType: 'conversation',
			});

			// Only proceed if reasoning content is detected
			if (!reasoningDetection.containsReasoning) {
				logger.debug(
					'ConversationSession: No reasoning content detected in user input, skipping reflection processing',
					{
						confidence: reasoningDetection.confidence,
						detectedPatterns: reasoningDetection.detectedPatterns,
					}
				);
				return;
			}

			logger.debug(
				'ConversationSession: Reasoning content detected, proceeding with reflection processing',
				{
					confidence: reasoningDetection.confidence,
					detectedPatterns: reasoningDetection.detectedPatterns,
				}
			);

			// Step 1: Extract reasoning steps from the interaction (only from user input)
			let extractionResult: any;
			try {
				extractionResult = await this.services.unifiedToolManager.executeTool(
					'cipher_extract_reasoning_steps',
					{
						userInput: userInput,
						options: {
							extractExplicit: true,
							extractImplicit: true,
							includeMetadata: true,
						},
					},
					this.id
				);

				logger.debug('ConversationSession: Reasoning extraction completed', {
					success: extractionResult.success,
					stepCount: extractionResult.result?.trace?.steps?.length || 0,
					traceId: extractionResult.result?.trace?.id,
				});
			} catch (extractError) {
				logger.debug('ConversationSession: Reasoning extraction failed', {
					error: extractError instanceof Error ? extractError.message : String(extractError),
				});
				return; // Skip if extraction fails
			}

			// Only proceed if we extracted reasoning steps
			if (!extractionResult.success || !extractionResult.result?.trace?.steps?.length) {
				return;
			}

			const reasoningTrace = extractionResult.result.trace;

			// Step 2: Evaluate the reasoning quality using a non-thinking model
			let evaluationResult: any;
			try {
				// Use configured evaluation model or fallback to main LLM
				const evalConfig = this.services.stateManager.getEvalLLMConfig(this.id);
				const evalContextManager = createContextManager(
					evalConfig,
					this.services.promptManager,
					undefined,
					undefined
				);
				const evalLLMService = createLLMService(
					evalConfig,
					this.services.mcpManager,
					evalContextManager,
					this.services.unifiedToolManager
				);
				// Directly call the evaluation tool using the non-thinking model
				evaluationResult = await this.services.unifiedToolManager.executeTool(
					'cipher_evaluate_reasoning',
					{
						trace: reasoningTrace,
						options: {
							checkEfficiency: true,
							detectLoops: true,
							generateSuggestions: true,
						},
						llmService: evalLLMService,
					},
					this.id
				);

				logger.debug('ConversationSession: Reasoning evaluation completed', {
					success: evaluationResult.success,
					qualityScore: evaluationResult.result?.evaluation?.qualityScore,
					shouldStore: evaluationResult.result?.evaluation?.shouldStore,
				});
			} catch (evalError) {
				logger.debug('ConversationSession: Reasoning evaluation failed', {
					error: evalError instanceof Error ? evalError.message : String(evalError),
					traceId: reasoningTrace.id,
				});
				return; // Skip if evaluation fails
			}

			// Only proceed if evaluation was successful and indicates we should store
			if (!evaluationResult.result?.evaluation?.shouldStore) {
				logger.debug(
					'ConversationSession: Evaluation indicates should not store, skipping storage',
					{
						shouldStore: evaluationResult.result?.evaluation?.shouldStore,
						qualityScore: evaluationResult.result?.evaluation?.qualityScore,
					}
				);
				return;
			}

			const evaluation = evaluationResult.result.evaluation;

			// Step 3: Store the unified reasoning entry
			try {
				const storageResult = await this.services.unifiedToolManager.executeTool(
					'cipher_store_reasoning_memory',
					{
						trace: reasoningTrace,
						evaluation: evaluation,
					},
					this.id
				);

				logger.debug('ConversationSession: Reflection memory storage completed', {
					success: storageResult.success,
					stored: storageResult.result?.stored,
					traceId: storageResult.result?.traceId,
					vectorId: storageResult.result?.vectorId,
					stepCount: storageResult.result?.metrics?.stepCount,
					qualityScore: storageResult.result?.metrics?.qualityScore,
				});

				// Log successful end-to-end reflection processing
				if (storageResult.success && storageResult.result?.stored) {
					logger.debug('ConversationSession: Reflection memory processing completed successfully', {
						pipeline: 'extract → evaluate → store',
						traceId: storageResult.result.traceId,
						stepCount: reasoningTrace.steps.length,
						qualityScore: evaluation.qualityScore.toFixed(3),
						issueCount: evaluation.issues?.length || 0,
						suggestionCount: evaluation.suggestions?.length || 0,
					});
				}
			} catch (storageError) {
				logger.debug('ConversationSession: Reflection memory storage failed', {
					error: storageError instanceof Error ? storageError.message : String(storageError),
					traceId: reasoningTrace.id,
					qualityScore: evaluation.qualityScore,
				});
				// Continue execution even if storage fails
			}
		} catch (error) {
			logger.debug('ConversationSession: Reflection memory processing failed', {
				error: error instanceof Error ? error.message : String(error),
			});
			// Continue execution even if reflection processing fails
		}
	}

	/**
	 * Extract comprehensive interaction data including tool calls and results
	 * This captures the complete technical workflow, not just user input and final response
	 */
	private async extractComprehensiveInteractionData(
		userInput: string,
		aiResponse: string
	): Promise<string[]> {
		const interactionData: string[] = [];

		// Start with the user input
		interactionData.push(`User: ${userInput}`);

		// Get recent messages from context manager to extract tool usage
		const recentMessages = this.contextManager.getRawMessages();

		// Find messages from this current interaction (after the user input)
		// We'll look for the most recent assistant and tool messages
		const currentInteractionMessages = [];
		let foundUserMessage = false;

		// Process messages in reverse to get the most recent interaction
		for (let i = recentMessages.length - 1; i >= 0; i--) {
			const message = recentMessages[i];

			if (!message) {
				continue;
			}

			// Skip if we haven't reached the current user message yet
			if (!foundUserMessage) {
				if (
					message.role === 'user' &&
					Array.isArray(message.content) &&
					message.content.length > 0 &&
					message.content[0] &&
					message.content[0].type === 'text' &&
					'text' in message.content[0] &&
					message.content[0].text === userInput
				) {
					foundUserMessage = true;
				}
				continue;
			}

			// Add messages from this interaction
			if (message.role === 'assistant' || message.role === 'tool') {
				currentInteractionMessages.unshift(message);
			} else {
				// Stop when we hit another user message (previous interaction)
				break;
			}
		}

		// Process the interaction messages to extract technical details
		const toolsUsed: string[] = [];
		const toolResults: string[] = [];

		for (const message of currentInteractionMessages) {
			if (!message) {
				continue;
			}

			if (message.role === 'assistant' && message.toolCalls && message.toolCalls.length > 0) {
				// Extract tool calls
				for (const toolCall of message.toolCalls) {
					const toolName = toolCall.function.name;
					let args = '';
					try {
						const parsedArgs = JSON.parse(toolCall.function.arguments);
						// Summarize key arguments for memory (avoid storing full large content)
						const keyArgs = this.summarizeToolArguments(toolName, parsedArgs);
						args = keyArgs ? ` with ${keyArgs}` : '';
					} catch {
						// If parsing fails, just note that there were arguments
						args = ' with arguments';
					}
					toolsUsed.push(`${toolName}${args}`);
				}
			} else if (message.role === 'tool') {
				// Extract tool results (summarized)
				const toolName = message.name || 'unknown_tool';
				const resultSummary = this.summarizeToolResult(toolName, message.content);
				toolResults.push(`${toolName}: ${resultSummary}`);
			}
		}

		// Add tool usage information to interaction data
		if (toolsUsed.length > 0) {
			interactionData.push(`Tools used: ${toolsUsed.join(', ')}`);
		}

		if (toolResults.length > 0) {
			interactionData.push(`Tool results: ${toolResults.join('; ')}`);
		}

		// Finally add the assistant response
		interactionData.push(`Assistant: ${aiResponse}`);

		logger.debug('ConversationSession: Extracted comprehensive interaction data', {
			userInput: userInput.substring(0, 50),
			toolsUsed: toolsUsed.length,
			toolResults: toolResults.length,
			totalDataPoints: interactionData.length,
		});

		return interactionData;
	}

	/**
	 * Summarize tool arguments for memory storage
	 */
	private summarizeToolArguments(toolName: string, args: any): string {
		switch (toolName) {
			case 'read_file':
				return args.path ? `path: ${args.path}` : 'file read';
			case 'write_file':
				return args.path ? `path: ${args.path}` : 'file write';
			case 'list_files':
				return args.path ? `directory: ${args.path}` : 'directory listing';
			case 'cipher_memory_search':
				return args.query
					? `query: "${args.query.substring(0, 50)}${args.query.length > 50 ? '...' : ''}"`
					: 'memory search';
			default:
				// For other tools, try to extract key identifying information
				if (args.query) {
					return `query: "${args.query.substring(0, 30)}${args.query.length > 30 ? '...' : ''}"`;
				}
				if (args.path) {
					return `path: ${args.path}`;
				}
				if (args.file) {
					return `file: ${args.file}`;
				}
				return 'arguments provided';
		}
	}

	/**
	 * Summarize tool results for memory storage
	 */
	private summarizeToolResult(toolName: string, content: any): string {
		try {
			// Handle string content
			if (typeof content === 'string') {
				const parsed = JSON.parse(content);
				return this.formatToolResultSummary(toolName, parsed);
			}

			// Handle object content
			if (typeof content === 'object') {
				return this.formatToolResultSummary(toolName, content);
			}

			return 'result received';
		} catch {
			// If parsing fails, provide a basic summary
			const contentStr = String(content);
			return contentStr.length > 100 ? `${contentStr.substring(0, 100)}...` : contentStr;
		}
	}

	/**
	 * Format tool result summary based on tool type
	 */
	private formatToolResultSummary(toolName: string, result: any): string {
		switch (toolName) {
			case 'read_file':
				if (result.content && Array.isArray(result.content) && result.content.length > 0) {
					const text = result.content[0].text || '';
					const lines = text.split('\n').length;
					const size = text.length;
					return `file read (${lines} lines, ${size} chars)`;
				}
				return 'file read';

			case 'cipher_memory_search':
				if (result.results && Array.isArray(result.results)) {
					return `found ${result.results.length} memory entries`;
				}
				return 'memory search completed';

			case 'list_files':
				if (result.content && Array.isArray(result.content)) {
					const files = result.content.filter((item: any) => item.type === 'file').length;
					const dirs = result.content.filter((item: any) => item.type === 'directory').length;
					return `listed ${files} files, ${dirs} directories`;
				}
				return 'directory listing';

			default:
				// Generic result summary
				if (result.success !== undefined) {
					return result.success ? 'completed successfully' : 'failed';
				}
				if (result.error) {
					return `error: ${String(result.error).substring(0, 50)}`;
				}
				return 'completed';
		}
	}

	/**
	 * Disconnects the history provider if it exists (for session teardown).
	 */
	public async disconnect(): Promise<void> {
		if (this._historyProvider && typeof (this._historyProvider as any).disconnect === 'function') {
			try {
				await (this._historyProvider as any).disconnect();
				logger.debug(`Session ${this.id}: History provider disconnected.`);
			} catch (err) {
				logger.warn(`Session ${this.id}: Failed to disconnect history provider: ${err}`);
			}
		}
	}

	public getContextManager(): ContextManager {
		return this.contextManager;
	}

	/**
	 * Get LLM service with lazy initialization
	 */
	public async getLLMService(): Promise<ILLMService> {
		return await this.getLLMServiceLazy();
	}

	public getUnifiedToolManager(): UnifiedToolManager {
		return this.services.unifiedToolManager;
	}

	/**
	 * Get the storageManager with lazy initialization
	 */
	public async getStorageManager(): Promise<StorageManager | undefined> {
		return await this.getStorageManagerLazy();
	}

	/**
	 * Get the history provider with lazy initialization
	 */
	public async getHistoryProvider(): Promise<IConversationHistoryProvider | undefined> {
		return await this.getHistoryProviderLazy();
	}

	/**
	 * Force refresh conversation history from the database
	 */
	public async refreshConversationHistory(): Promise<void> {
		if (this.historyEnabled && this.contextManager) {
			try {
				// CRITICAL FIX: Clear context manager first to prevent stale message conflicts
				if (typeof (this.contextManager as any).clearMessages === 'function') {
					(this.contextManager as any).clearMessages();
					logger.debug(`Session ${this.id}: Cleared existing messages from context manager`);
				}

				// Ensure history provider is initialized
				const historyProvider = await this.getHistoryProviderLazy();
				if (historyProvider) {
					// CRITICAL FIX: Always set history provider in context manager
					(this.contextManager as any).historyProvider = historyProvider;
					logger.debug(`Session ${this.id}: Set/updated history provider in context manager`);

					// Get fresh history from provider
					const history = await historyProvider.getHistory(this.id);
					logger.debug(
						`Session ${this.id}: Retrieved ${history.length} messages from history provider`
					);

					// CRITICAL FIX: Use multiple methods to restore history for maximum compatibility
					let historyRestored = false;

					// Method 1: Try context manager's restoreHistory if available
					if (this.contextManager.restoreHistory && !historyRestored) {
						try {
							await this.contextManager.restoreHistory();
							historyRestored = true;
							logger.debug(
								`Session ${this.id}: Successfully restored history via context manager restoreHistory`
							);
						} catch (restoreError) {
							logger.debug(`Session ${this.id}: restoreHistory failed:`, restoreError);
						}
					}

					// Method 2: Try setMessages if available
					if (!historyRestored && typeof (this.contextManager as any).setMessages === 'function') {
						try {
							(this.contextManager as any).setMessages(history);
							historyRestored = true;
							logger.debug(
								`Session ${this.id}: Successfully restored ${history.length} messages via setMessages`
							);
						} catch (setError) {
							logger.debug(`Session ${this.id}: setMessages failed:`, setError);
						}
					}

					// Method 3: Manual message addition as final fallback
					if (!historyRestored && history.length > 0) {
						try {
							let addedCount = 0;
							for (const message of history) {
								try {
									await this.contextManager.addMessage(message);
									addedCount++;
								} catch (addError) {
									logger.warn(
										`Session ${this.id}: Failed to add message ${addedCount + 1}:`,
										addError
									);
								}
							}
							historyRestored = addedCount > 0;
							logger.debug(
								`Session ${this.id}: Manually added ${addedCount}/${history.length} messages to context manager`
							);
						} catch (manualError) {
							logger.warn(`Session ${this.id}: Manual message addition failed:`, manualError);
						}
					}

					// CRITICAL FIX: Verify history restoration success
					const contextMessages = this.contextManager.getRawMessages();
					logger.info(
						`Session ${this.id}: History refresh complete - Provider: ${history.length} messages, Context: ${contextMessages.length} messages, Restored: ${historyRestored}`
					);
				} else {
					logger.debug(`Session ${this.id}: No history provider available for refresh`);
					// Try to get existing history from context manager
					try {
						const messages = this.contextManager.getRawMessages();
						logger.debug(
							`Session ${this.id}: Context manager has ${messages.length} existing messages`
						);
					} catch (fallbackError) {
						logger.debug(
							`Session ${this.id}: Failed to get history from context manager:`,
							fallbackError
						);
					}
				}
			} catch (error) {
				logger.warn(`Session ${this.id}: Failed to refresh conversation history:`, error);
				// Don't throw the error, just log it and continue
			}
		} else {
			logger.debug(`Session ${this.id}: History not enabled or context manager not available`);
		}
	}

	/**
	 * Get the current conversation history for debugging
	 */
	public async getConversationHistory(): Promise<any[]> {
		if (this._historyProvider && this.historyEnabled) {
			try {
				const history = await this._historyProvider.getHistory(this.id);
				logger.debug(
					`Session ${this.id}: Current conversation history has ${history.length} messages`
				);
				return history;
			} catch (error) {
				logger.warn(`Session ${this.id}: Failed to get conversation history:`, error);
				return [];
			}
		} else {
			// Try to get history from context manager as fallback
			try {
				if (this.contextManager) {
					const messages = this.contextManager.getRawMessages();
					logger.debug(
						`Session ${this.id}: Got ${messages.length} messages from context manager as fallback`
					);
					return messages;
				}
			} catch (fallbackError) {
				logger.debug(
					`Session ${this.id}: Failed to get history from context manager:`,
					fallbackError
				);
			}

			logger.debug(`Session ${this.id}: No history provider available`);
			return [];
		}
	}

	/**
	 * Get the current conversation history from context manager
	 */
	public getContextHistory(): any[] {
		if (this.contextManager) {
			const messages = this.contextManager.getRawMessages();
			logger.debug(`Session ${this.id}: Context manager has ${messages.length} messages`);
			return messages;
		} else {
			logger.debug(`Session ${this.id}: No context manager available`);
			return [];
		}
	}

	/**
	 * Serialize the current session state for persistence
	 * @returns SerializedSession containing all necessary data to restore this session
	 */
	public async serialize(): Promise<SerializedSession> {
		try {
			// Get conversation history from the history provider
			let conversationHistory: any[] = [];
			if (this._historyProvider && this.historyEnabled) {
				try {
					conversationHistory = await this._historyProvider.getHistory(this.id);
				} catch (error) {
					logger.warn(
						`Session ${this.id}: Failed to retrieve history for session during serialization:`,
						error
					);
				}
			}

			// CRITICAL FIX: If no history from provider, try to get from context manager as fallback
			if (conversationHistory.length === 0 && this.contextManager) {
				try {
					const contextHistory = this.contextManager.getRawMessages();
					if (contextHistory.length > 0) {
						conversationHistory = contextHistory;
						logger.debug(
							`Session ${this.id}: Using context manager history as fallback (${contextHistory.length} messages)`
						);
					}
				} catch (fallbackError) {
					logger.debug(
						`Session ${this.id}: Failed to get history from context manager during serialization:`,
						fallbackError
					);
				}
			}

			// Note: We don't serialize functions (mergeMetadata, beforeMemoryExtraction)
			// as they're unsafe to deserialize and restore. These will need to be
			// re-configured when the session is restored.
			const options: any = {};
			if (this.metadataSchema) {
				// For Zod schemas, we only store a basic indicator that a schema existed
				// The actual schema will need to be re-provided during restoration
				try {
					options.hadMetadataSchema = true;
				} catch (error) {
					logger.warn(`Failed to serialize metadata schema for session ${this.id}:`, error);
				}
			}

			const serialized: SerializedSession = {
				id: this.id,
				metadata: {
					createdAt: Date.now(), // We don't track creation time currently, use now as fallback
					lastActivity: Date.now(),
					...(this.sessionMemoryMetadata && {
						sessionMemoryMetadata: { ...this.sessionMemoryMetadata },
					}),
					historyEnabled: this.historyEnabled,
					historyBackend: this.historyBackend,
				},
				conversationHistory: conversationHistory,
				options: Object.keys(options).length > 0 ? options : undefined,
				version: SESSION_PERSISTENCE_CONSTANTS.CURRENT_VERSION,
				serializedAt: Date.now(),
			};

			logger.info(`Session ${this.id}: Serialized with ${conversationHistory.length} messages`);
			return serialized;
		} catch (error) {
			throw new SessionPersistenceError(
				`Failed to serialize session ${this.id}`,
				'serialize',
				this.id,
				error as Error
			);
		}
	}

	/**
	 * Deserialize and restore a session from serialized data
	 * @param data - Serialized session data
	 * @param services - Service dependencies required for session creation
	 * @returns A new ConversationSession instance restored from the data
	 */
	public static async deserialize(
		data: SerializedSession,
		services: {
			stateManager: MemAgentStateManager;
			promptManager: EnhancedPromptManager;
			mcpManager: MCPManager;
			unifiedToolManager: UnifiedToolManager;
			embeddingManager?: any;
		}
	): Promise<ConversationSession> {
		try {
			// Validate version compatibility
			if (data.version !== SESSION_PERSISTENCE_CONSTANTS.CURRENT_VERSION) {
				logger.warn(
					`Session ${data.id} has version ${data.version}, current is ${SESSION_PERSISTENCE_CONSTANTS.CURRENT_VERSION}. Attempting to restore anyway.`
				);
			}

			// Reconstruct options
			const options: any = {
				sessionMemoryMetadata: data.metadata.sessionMemoryMetadata,
				historyEnabled: data.metadata.historyEnabled,
				historyBackend: data.metadata.historyBackend,
			};

			// Note: Functions (mergeMetadata, beforeMemoryExtraction) are not restored from
			// serialized data for security reasons. These need to be re-configured by the
			// application when creating sessions that require these custom behaviors.
			if (data.options?.hadMetadataSchema) {
				logger.debug(
					`Session ${data.id} had a metadata schema, but it will need to be re-provided during configuration.`
				);
			}

			// Create new session instance
			// Ensure contextManager is included in services if available
			const sessionServices = {
				...services,
				...((services as any).contextManager && {
					contextManager: (services as any).contextManager,
				}),
			};
			const session = new ConversationSession(sessionServices as any, data.id, options);

			// Initialize the session
			await session.init();

			// Restore conversation history if we have serialized history
			if (data.conversationHistory.length > 0) {
				try {
					// Ensure history provider is initialized
					const historyProvider = await session.getHistoryProvider();

					if (historyProvider) {
						// Clear any existing history first
						await historyProvider.clearHistory(data.id);

						// Restore messages one by one to maintain order and validation
						for (const message of data.conversationHistory) {
							await historyProvider.saveMessage(data.id, message);
						}

						logger.debug(
							`Session ${data.id}: Restored ${data.conversationHistory.length} messages to history provider`
						);
					} else {
						logger.warn(`Session ${data.id}: No history provider available for restoration`);
					}

					// Always try to refresh conversation history to context manager
					// This is critical for UI mode to see previous messages
					await session.refreshConversationHistory();
					logger.info(
						`Session ${data.id}: Restored ${data.conversationHistory.length} messages and refreshed context manager`
					);
				} catch (error) {
					logger.warn(
						`Session ${data.id}: Failed to restore conversation history from serialized data:`,
						error
					);
					// Continue without history rather than failing
				}
			} else {
				logger.debug(`Session ${data.id}: No conversation history to restore`);
			}

			return session;
		} catch (error) {
			throw new SessionPersistenceError(
				`Failed to deserialize session ${data.id}`,
				'deserialize',
				data.id,
				error as Error
			);
		}
	}
}

export { ConversationSession } from './coversation-session.js';
export { SessionManager } from './session-manager.js';
export type { SessionMetadata } from './session-manager.js';

/**
 * Session Persistence Types
 *
 * Defines the types and interfaces for serializing and deserializing
 * conversation sessions and their complete state for persistence.
 *
 * @module session/persistence-types
 */

import type { InternalMessage } from '../brain/llm/messages/types.js';

/**
 * Serialized form of a ConversationSession for storage
 */
export interface SerializedSession {
	/** Unique session identifier */
	id: string;

	/** Session metadata */
	metadata: {
		/** When the session was created */
		createdAt: number;
		/** Last activity timestamp */
		lastActivity: number;
		/** Session-specific memory metadata if any */
		sessionMemoryMetadata?: Record<string, any>;
		/** History settings */
		historyEnabled: boolean;
		historyBackend: 'database' | 'memory';
	};

	/** Complete conversation history */
	conversationHistory: InternalMessage[];

	/** Session configuration options */
	options?: {
		hadMetadataSchema?: boolean; // Indicates if the session had a metadata schema
		// Note: Functions (mergeMetadata, beforeMemoryExtraction) are not serialized
		// for security reasons and must be re-configured on session restoration
	};

	/** Version for schema evolution */
	version: string;

	/** When this serialization was created */
	serializedAt: number;
}

/**
 * Session persistence statistics
 */
export interface SessionPersistenceStats {
	/** Total number of sessions processed */
	totalSessions: number;
	/** Number of sessions successfully saved */
	savedSessions: number;
	/** Number of sessions that failed to save */
	failedSessions: number;
	/** Total time taken for persistence operation (ms) */
	persistenceTime: number;
	/** Session IDs that failed to persist (for debugging) */
	failedSessionIds: string[];
	/** Any error messages encountered */
	errors: string[];
}

/**
 * Session restoration statistics
 */
export interface SessionRestorationStats {
	/** Total number of sessions found in storage */
	totalSessions: number;
	/** Number of sessions successfully restored */
	restoredSessions: number;
	/** Number of sessions that failed to restore */
	failedSessions: number;
	/** Total time taken for restoration operation (ms) */
	restorationTime: number;
	/** Session IDs that failed to restore (for debugging) */
	failedSessionIds: string[];
	/** Any error messages encountered */
	errors: string[];
}

/**
 * Configuration for session persistence behavior
 */
export interface SessionPersistenceConfig {
	/** Storage key prefix for session data */
	storageKeyPrefix?: string;

	/** Maximum number of sessions to persist */
	maxSessionsToSave?: number;

	/** Maximum age of sessions to restore (ms) */
	maxSessionAge?: number;

	/** Whether to compress session data */
	compress?: boolean;

	/** Timeout for save operations (ms) */
	saveTimeout?: number;

	/** Timeout for load operations (ms) */
	loadTimeout?: number;

	/** Whether to validate restored sessions */
	validateOnRestore?: boolean;
}

/**
 * Session persistence error types
 */
export class SessionPersistenceError extends Error {
	constructor(
		message: string,
		public readonly operation: 'save' | 'load' | 'serialize' | 'deserialize',
		public readonly sessionId?: string,
		public override readonly cause?: Error
	) {
		super(message);
		this.name = 'SessionPersistenceError';
	}
}

/**
 * Constants for session persistence
 */
export const SESSION_PERSISTENCE_CONSTANTS = {
	/** Current version of the serialization format */
	CURRENT_VERSION: '1.0.0',

	/** Default storage key prefix */
	DEFAULT_STORAGE_PREFIX: 'cipher:sessions:',

	/** Default maximum number of sessions to save */
	DEFAULT_MAX_SESSIONS: 50,

	/** Default maximum session age (24 hours) */
	DEFAULT_MAX_AGE: 24 * 60 * 60 * 1000,

	/** Default save timeout (30 seconds) */
	DEFAULT_SAVE_TIMEOUT: 30 * 1000,

	/** Default load timeout (30 seconds) */
	DEFAULT_LOAD_TIMEOUT: 30 * 1000,
} as const;

import { randomUUID } from 'crypto';
import { EnhancedPromptManager } from '../brain/systemPrompt/enhanced-manager.js';
import { MemAgentStateManager } from '../brain/memAgent/state-manager.js';
import { ConversationSession } from './coversation-session.js';
import { MCPManager } from '../mcp/manager.js';
import { UnifiedToolManager } from '../brain/tools/unified-tool-manager.js';
import { logger } from '@core/logger/index.js';
import { EventManager } from '../events/event-manager.js';
import { SessionEvents } from '../events/event-types.js';
import { StorageManager } from '../storage/manager.js';
import type {
	SerializedSession,
	SessionPersistenceConfig,
	SessionPersistenceStats,
	SessionRestorationStats,
} from './persistence-types.js';
import { SESSION_PERSISTENCE_CONSTANTS, SessionPersistenceError } from './persistence-types.js';

export interface SessionManagerConfig {
	maxSessions?: number;
	sessionTTL?: number;
	persistence?: SessionPersistenceConfig;
}

// Re-export persistence types for convenience
export type {
	SerializedSession,
	SessionPersistenceConfig,
	SessionPersistenceStats,
	SessionRestorationStats,
} from './persistence-types.js';
export { SESSION_PERSISTENCE_CONSTANTS, SessionPersistenceError } from './persistence-types.js';

export interface SessionMetadata {
	session: ConversationSession;
	lastActivity: number;
	createdAt: number;
}

export class SessionManager {
	private sessions: Map<string, SessionMetadata> = new Map();
	private readonly maxSessions: number;
	private readonly sessionTTL: number;
	private initialized = false;
	private cleanupInterval?: NodeJS.Timeout | undefined;
	private initializationPromise!: Promise<void>;
	private readonly pendingCreations = new Map<string, Promise<ConversationSession>>();

	// Performance optimizations
	private readonly sessionMetadataCache = new Map<
		string,
		{ metadata: SessionMetadata; cachedAt: number; expiresAt: number }
	>();
	private readonly messageCountCache = new Map<
		string,
		{ count: number; cachedAt: number; expiresAt: number }
	>();
	private readonly requestDeduplicator = new Map<string, Promise<any>>();
	private readonly CACHE_TTL = 30000; // 30 seconds
	private readonly BATCH_SIZE = 10; // Parallel processing batch size
	private performanceMetrics = {
		cacheHits: 0,
		cacheMisses: 0,
		parallelLoads: 0,
		sequentialLoads: 0,
		averageLoadTime: 0,
	};

	// Persistence-related fields
	private readonly persistenceConfig: SessionPersistenceConfig;
	private storageManager?: StorageManager | undefined;

	constructor(
		private services: {
			stateManager: MemAgentStateManager;
			promptManager: EnhancedPromptManager;
			contextManager: any;
			mcpManager: MCPManager;
			unifiedToolManager: UnifiedToolManager;
			eventManager: EventManager;
			embeddingManager?: any; // Optional embedding manager for status checking
		},
		config: SessionManagerConfig = {}
	) {
		this.maxSessions = config.maxSessions ?? 100;
		this.sessionTTL = config.sessionTTL ?? 24 * 3600000; // 24 hours (instead of 1 hour)

		// Initialize persistence configuration with defaults
		this.persistenceConfig = {
			storageKeyPrefix: SESSION_PERSISTENCE_CONSTANTS.DEFAULT_STORAGE_PREFIX,
			maxSessionsToSave: SESSION_PERSISTENCE_CONSTANTS.DEFAULT_MAX_SESSIONS,
			maxSessionAge: SESSION_PERSISTENCE_CONSTANTS.DEFAULT_MAX_AGE,
			compress: false,
			saveTimeout: SESSION_PERSISTENCE_CONSTANTS.DEFAULT_SAVE_TIMEOUT,
			loadTimeout: SESSION_PERSISTENCE_CONSTANTS.DEFAULT_LOAD_TIMEOUT,
			validateOnRestore: true,
			...config.persistence,
		};
	}

	public async init(): Promise<void> {
		if (this.initialized) {
			return;
		}
		this.initialized = true;

		logger.debug('SessionManager: Starting initialization...');

		// Initialize storage manager for persistence
		await this.initializePersistenceStorage();

		// Load existing sessions from persistent storage
		const restorationStats = await this.loadAllSessions();

		if (restorationStats.totalSessions > 0) {
			logger.info(
				`SessionManager: Initialization complete. Loaded ${restorationStats.restoredSessions}/${restorationStats.totalSessions} sessions from storage. Current in-memory sessions: ${this.sessions.size}`
			);
		} else {
			logger.debug(
				`SessionManager: Initialization complete. No sessions found in storage. Current in-memory sessions: ${this.sessions.size}`
			);
		}

		// Start cleanup interval for expired sessions
		this.startCleanupInterval();

		logger.debug(
			`SessionManager initialized with max sessions: ${this.maxSessions}, TTL: ${this.sessionTTL}ms`
		);
	}

	private async ensureInitialized(): Promise<void> {
		if (!this.initialized) {
			if (!this.initializationPromise) {
				logger.debug('SessionManager: Starting initialization...');
				this.initializationPromise = this.init();
			}
			try {
				await this.initializationPromise;
				logger.debug('SessionManager: Initialization completed successfully');
			} catch (error) {
				logger.error('SessionManager: Initialization failed:', error);
				throw error;
			}
		}
	}

	public async createSession(sessionId?: string): Promise<ConversationSession> {
		await this.ensureInitialized();

		const id = sessionId ?? randomUUID();

		// Check if there's already a pending creation for this session ID
		if (this.pendingCreations.has(id)) {
			return await this.pendingCreations.get(id)!;
		}

		// Check if session already exists
		if (this.sessions.has(id)) {
			await this.updateSessionActivity(id);
			return this.sessions.get(id)!.session;
		}

		// Create a promise for the session creation and track it to prevent concurrent operations
		const creationPromise = this.createSessionInternal(id);
		this.pendingCreations.set(id, creationPromise);

		try {
			const session = await creationPromise;
			return session;
		} finally {
			// Always clean up the pending creation tracker
			this.pendingCreations.delete(id);
		}
	}

	private async createSessionInternal(sessionId: string): Promise<ConversationSession> {
		logger.debug(`SessionManager: Creating new session ${sessionId}...`);

		// Check if we need to evict old sessions to make room
		if (this.sessions.size >= this.maxSessions) {
			logger.warn(
				`SessionManager: Reached max sessions limit (${this.maxSessions}), evicting oldest session...`
			);
			await this.evictOldestSession();
		}

		// CRITICAL FIX: Add a small delay to prevent race conditions when creating multiple sessions
		// This prevents storage conflicts when sessions are created in quick succession
		if (this.sessions.size > 0) {
			await new Promise(resolve => setTimeout(resolve, 50));
		}

		// Create new conversation session with shared storage manager
		logger.debug(
			`SessionManager: Creating session ${sessionId} with storage manager: ${this.storageManager ? 'available' : 'undefined'}`
		);
		const session = new ConversationSession(
			{
				...this.services,
				contextManager: this.services.contextManager,
			},
			sessionId,
			{
				...(this.storageManager && { sharedStorageManager: this.storageManager }),
			}
		);
		await session.init();

		// CRITICAL FIX: Ensure conversation history is properly initialized for new sessions
		// This is essential for UI mode to display messages correctly
		try {
			// Force initialize the history provider
			const historyProvider = await session.getHistoryProvider();
			if (historyProvider) {
				logger.debug(`SessionManager: History provider initialized for new session ${sessionId}`);
			}

			await session.refreshConversationHistory();
			logger.debug(`SessionManager: Initialized conversation history for new session ${sessionId}`);

			// Verify that the session has proper initialization
			const contextHistory = session.getContextHistory();
			const history = await session.getConversationHistory();
			logger.debug(
				`SessionManager: New session ${sessionId} - Context: ${contextHistory.length} messages, History: ${history.length} messages`
			);
		} catch (error) {
			logger.warn(
				`SessionManager: Failed to initialize conversation history for new session ${sessionId}:`,
				error
			);
			// Continue even if history initialization fails
		}

		// Store session with metadata
		const now = Date.now();
		this.sessions.set(sessionId, {
			session,
			lastActivity: now,
			createdAt: now,
		});

		// Emit session created event
		this.services.eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_CREATED, {
			sessionId,
			timestamp: now,
		});

		// Save session to persistent storage immediately
		try {
			await this.saveSession(sessionId, session);
			logger.info(
				`SessionManager: Session ${sessionId} created and saved to persistent storage. Total active sessions: ${this.sessions.size}`
			);
		} catch (error) {
			logger.warn(
				`SessionManager: Failed to save session ${sessionId} to persistent storage:`,
				error
			);
			// Continue even if save fails
		}

		return session;
	}

	private async updateSessionActivity(sessionId: string): Promise<void> {
		const sessionMetadata = this.sessions.get(sessionId);
		if (sessionMetadata) {
			const now = Date.now();
			sessionMetadata.lastActivity = now;

			// Emit session activated event
			this.services.eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_ACTIVATED, {
				sessionId,
				timestamp: now,
			});

			// Save updated session activity to persistent storage
			try {
				await this.saveSession(sessionId, sessionMetadata.session);
				logger.debug(`Updated activity for session: ${sessionId}`);
			} catch (error) {
				logger.warn(`Failed to save updated session ${sessionId} to persistent storage:`, error);
			}
		}
	}

	public async getSession(sessionId: string): Promise<ConversationSession | null> {
		await this.ensureInitialized();

		const sessionMetadata = this.sessions.get(sessionId);
		if (!sessionMetadata) {
			logger.debug(
				`SessionManager: Session ${sessionId} not found in memory (${this.sessions.size} active sessions), attempting to restore from persistent storage...`
			);

			// Session not in memory, try to load from persistent storage
			try {
				const restoredSession = await this.loadSession(sessionId);
				if (restoredSession) {
					logger.info(
						`SessionManager: Successfully restored session ${sessionId} from persistent storage. Total active sessions: ${this.sessions.size}`
					);
					return restoredSession;
				} else {
					logger.debug(
						`SessionManager: Session ${sessionId} not found in persistent storage either`
					);
				}
			} catch (error) {
				logger.warn(
					`SessionManager: Failed to restore session ${sessionId} from persistent storage:`,
					error
				);
			}
			return null;
		}

		// Check if session has expired
		if (this.isSessionExpired(sessionMetadata)) {
			logger.debug(`SessionManager: Session ${sessionId} has expired, removing...`);
			await this.removeSession(sessionId);
			return null;
		}

		// Update activity and return session
		await this.updateSessionActivity(sessionId);
		logger.debug(
			`SessionManager: Retrieved active session ${sessionId}. Total active sessions: ${this.sessions.size}`
		);
		return sessionMetadata.session;
	}

	public async removeSession(sessionId: string): Promise<boolean> {
		await this.ensureInitialized();

		// Handle null or invalid session IDs
		if (!sessionId || sessionId === 'null' || sessionId === 'undefined') {
			logger.debug(`SessionManager: Cannot remove session with invalid ID: ${sessionId}`);
			return false;
		}

		// CRITICAL FIX: Check if session exists before deletion
		const sessionMetadata = this.sessions.get(sessionId);
		if (!sessionMetadata && !this.storageManager?.isConnected()) {
			logger.debug(
				`SessionManager: Session ${sessionId} not found in memory and storage unavailable`
			);
			return false;
		}

		// CRITICAL FIX: Use transaction-like approach for consistent deletion
		let memoryDeleted = false;
		let storageDeleted = false;
		const deletionErrors: string[] = [];

		try {
			// Step 1: Delete from memory
			memoryDeleted = this.sessions.delete(sessionId);
			logger.debug(`SessionManager: Memory deletion for ${sessionId}: ${memoryDeleted}`);

			// Step 2: Delete from persistent storage if available
			if (this.storageManager?.isConnected()) {
				try {
					const backends = this.storageManager.getBackends();
					if (backends?.database) {
						// Delete both session data and conversation history
						const sessionKey = this.getSessionStorageKey(sessionId);
						const historyKey = `messages:${sessionId}`;

						// Delete session data
						try {
							await backends.database.delete(sessionKey);
							logger.debug(`SessionManager: Deleted session data ${sessionKey}`);
						} catch (sessionDeleteError) {
							deletionErrors.push(`Session data: ${sessionDeleteError}`);
						}

						// Delete conversation history
						try {
							await backends.database.delete(historyKey);
							logger.debug(`SessionManager: Deleted conversation history ${historyKey}`);
						} catch (historyDeleteError) {
							deletionErrors.push(`History data: ${historyDeleteError}`);
						}

						storageDeleted = true;
					}
				} catch (storageError) {
					deletionErrors.push(`Storage operation: ${storageError}`);
					logger.warn(`SessionManager: Storage deletion failed for ${sessionId}:`, storageError);
				}
			} else {
				logger.debug(`SessionManager: Storage manager not available for deletion of ${sessionId}`);
				storageDeleted = true; // Consider successful if no storage to delete from
			}

			// Step 3: Clear all caches for this session
			this.clearSessionFromAllCaches(sessionId);

			// Step 4: Emit events and log results
			if (memoryDeleted || storageDeleted) {
				// Emit session deleted event
				this.services.eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_DELETED, {
					sessionId,
					timestamp: Date.now(),
				});

				if (deletionErrors.length > 0) {
					logger.warn(
						`SessionManager: Session ${sessionId} partially deleted with errors: ${deletionErrors.join('; ')}. Remaining active sessions: ${this.sessions.size}`
					);
				} else {
					logger.info(
						`SessionManager: Successfully deleted session ${sessionId} from memory and storage. Remaining active sessions: ${this.sessions.size}`
					);
				}
				return true;
			}

			logger.warn(
				`SessionManager: Failed to delete session ${sessionId} - not found in memory or storage`
			);
			return false;
		} catch (error) {
			logger.error(
				`SessionManager: Critical error during session deletion for ${sessionId}:`,
				error
			);
			// If we deleted from memory but failed storage, still return true as session is functionally deleted
			return memoryDeleted;
		}
	}

	public async getAllSessions(): Promise<ConversationSession[]> {
		await this.ensureInitialized();
		return Array.from(this.sessions.values()).map(metadata => metadata.session);
	}

	/**
	 * Optimized session listing with parallel processing and caching
	 */
	public async getActiveSessionIds(): Promise<string[]> {
		await this.ensureInitialized();

		const startTime = Date.now();
		const cacheKey = 'active_session_ids';

		// CRITICAL FIX: Don't use cache for session IDs to prevent phantom sessions
		// Always fetch fresh data to ensure UI shows accurate session list

		// Prevent duplicate requests
		if (this.requestDeduplicator.has(cacheKey)) {
			logger.debug('SessionManager: Deduplicating concurrent request for active session IDs');
			return await this.requestDeduplicator.get(cacheKey)!;
		}

		try {
			this.performanceMetrics.cacheMisses++;

			const fetchPromise = this.fetchActiveSessionIds();
			this.requestDeduplicator.set(cacheKey, fetchPromise);

			const result = await fetchPromise;

			// CRITICAL FIX: Filter out sessions with 0 messages to prevent phantom sessions
			const validSessions = await this.filterValidSessions(result);

			const loadTime = Date.now() - startTime;
			this.updateAverageLoadTime(loadTime);

			logger.debug(
				`SessionManager: Fetched ${validSessions.length}/${result.length} valid session IDs in ${loadTime}ms`
			);
			return validSessions;
		} catch (error) {
			logger.error('SessionManager: Failed to get active session IDs:', error);
			// Return in-memory sessions as fallback
			const inMemorySessionIds = Array.from(this.sessions.keys());
			logger.debug(
				`SessionManager: Returning ${inMemorySessionIds.length} in-memory sessions as fallback`
			);
			return inMemorySessionIds;
		} finally {
			this.requestDeduplicator.delete(cacheKey);
		}
	}

	/**
	 * Internal method to fetch active session IDs with optimized queries
	 */
	private async fetchActiveSessionIds(): Promise<string[]> {
		// Clean up expired sessions first
		await this.cleanupExpiredSessions();

		// Get in-memory sessions
		const inMemorySessionIds = Array.from(this.sessions.keys());
		logger.debug(`SessionManager: Found ${inMemorySessionIds.length} in-memory sessions`);

		// Get persisted sessions from storage in parallel
		let persistedSessionIds: string[] = [];
		try {
			const [sessionKeys, messageKeys] = await Promise.allSettled([
				this.getAllSessionKeys(),
				this.getAllMessageKeys(),
			]);

			// Extract session IDs from both sources
			const sessionIdsFromKeys =
				sessionKeys.status === 'fulfilled'
					? sessionKeys.value.map(key => this.extractSessionIdFromKey(key))
					: [];

			const sessionIdsFromMessages =
				messageKeys.status === 'fulfilled'
					? messageKeys.value.map(key => key.replace('messages:', ''))
					: [];

			persistedSessionIds = [...new Set([...sessionIdsFromKeys, ...sessionIdsFromMessages])];
			logger.debug(`SessionManager: Found ${persistedSessionIds.length} persisted sessions`);
		} catch (storageError) {
			logger.warn('SessionManager: Failed to get persisted sessions from storage:', storageError);
		}

		// Combine and deduplicate
		const allSessionIds = [...new Set([...inMemorySessionIds, ...persistedSessionIds])];
		logger.debug(`SessionManager: Combined ${allSessionIds.length} unique session IDs`);

		return allSessionIds;
	}

	public async getSessionCount(): Promise<number> {
		await this.ensureInitialized();
		return this.sessions.size;
	}

	/**
	 * Get detailed session statistics for monitoring
	 */
	public async getSessionStats(): Promise<{
		activeSessions: number;
		storageConnected: boolean;
		storageType: string;
		persistenceEnabled: boolean;
		performanceMetrics: {
			cacheHitRate: number;
			parallelLoadRatio: number;
			averageLoadTime: number;
			cacheSize: number;
		};
	}> {
		await this.ensureInitialized();

		const backends = this.storageManager?.getBackends();
		const storageType = backends?.database?.getBackendType?.() || 'none';

		const totalRequests = this.performanceMetrics.cacheHits + this.performanceMetrics.cacheMisses;
		const cacheHitRate =
			totalRequests > 0 ? (this.performanceMetrics.cacheHits / totalRequests) * 100 : 0;
		const totalLoads =
			this.performanceMetrics.parallelLoads + this.performanceMetrics.sequentialLoads;
		const parallelLoadRatio =
			totalLoads > 0 ? (this.performanceMetrics.parallelLoads / totalLoads) * 100 : 0;

		return {
			activeSessions: this.sessions.size,
			storageConnected: this.storageManager?.isConnected() || false,
			storageType,
			persistenceEnabled: !!this.storageManager,
			performanceMetrics: {
				cacheHitRate: Math.round(cacheHitRate * 100) / 100,
				parallelLoadRatio: Math.round(parallelLoadRatio * 100) / 100,
				averageLoadTime: Math.round(this.performanceMetrics.averageLoadTime * 100) / 100,
				cacheSize: this.sessionMetadataCache.size + this.messageCountCache.size,
			},
		};
	}

	private isSessionExpired(sessionMetadata: SessionMetadata): boolean {
		const now = Date.now();
		return now - sessionMetadata.lastActivity > this.sessionTTL;
	}

	private async evictOldestSession(): Promise<void> {
		if (this.sessions.size === 0) {
			return;
		}

		let oldestSessionId: string | null = null;
		let oldestActivity = Number.MAX_SAFE_INTEGER; // Initialize to maximum value to find minimum

		for (const [sessionId, metadata] of this.sessions) {
			if (metadata.lastActivity < oldestActivity) {
				oldestActivity = metadata.lastActivity;
				oldestSessionId = sessionId;
			}
		}

		if (oldestSessionId) {
			await this.removeSession(oldestSessionId);
			logger.debug(`Evicted oldest session: ${oldestSessionId}`);
		}
	}

	private async cleanupExpiredSessions(): Promise<void> {
		const expiredSessionIds: string[] = [];

		for (const [sessionId, metadata] of this.sessions) {
			if (this.isSessionExpired(metadata)) {
				expiredSessionIds.push(sessionId);
			}
		}

		if (expiredSessionIds.length > 0) {
			logger.info(`SessionManager: Cleaning up ${expiredSessionIds.length} expired sessions...`);

			for (const sessionId of expiredSessionIds) {
				// Emit session expired event before removing
				this.services.eventManager.emitSessionEvent(sessionId, SessionEvents.SESSION_EXPIRED, {
					sessionId,
					timestamp: Date.now(),
				});

				await this.removeSession(sessionId);
			}

			logger.info(
				`SessionManager: Cleanup complete. Remaining active sessions: ${this.sessions.size}`
			);
		}
	}

	private startCleanupInterval(): void {
		// Run cleanup every 5 minutes
		const cleanupIntervalMs = 5 * 60 * 1000;

		// Only start cleanup if sessionTTL is not 0 (disabled)
		if (this.sessionTTL > 0) {
			this.cleanupInterval = setInterval(async () => {
				try {
					await this.cleanupExpiredSessions();
					// Also cleanup expired cache entries
					this.cleanupExpiredCache();
				} catch (error) {
					logger.error('Error during session cleanup:', error);
				}
			}, cleanupIntervalMs);
		} else {
			logger.debug('Session cleanup disabled (sessionTTL = 0)');
		}
	}

	/**
	 * Save all active sessions to persistent storage
	 * @returns Statistics about the save operation
	 */
	public async saveAllSessions(): Promise<SessionPersistenceStats> {
		await this.ensureInitialized();

		const startTime = Date.now();
		const stats: SessionPersistenceStats = {
			totalSessions: 0,
			savedSessions: 0,
			failedSessions: 0,
			persistenceTime: 0,
			failedSessionIds: [],
			errors: [],
		};

		if (!this.storageManager) {
			const error = 'No storage manager available for session persistence';
			stats.errors.push(error);
			logger.warn(`SessionManager.saveAllSessions: ${error}`);
			return stats;
		}

		if (!this.storageManager.isConnected()) {
			const error = 'Storage manager is not connected';
			stats.errors.push(error);
			logger.warn(`SessionManager.saveAllSessions: ${error}`);
			return stats;
		}

		try {
			logger.info(
				`SessionManager: Starting to save ${this.sessions.size} sessions to persistent storage...`
			);

			// Get all active sessions
			const activeSessions = Array.from(this.sessions.entries());
			stats.totalSessions = activeSessions.length;

			if (activeSessions.length === 0) {
				logger.debug('SessionManager.saveAllSessions: No active sessions to save');
				stats.persistenceTime = Date.now() - startTime;
				return stats;
			}

			// Save sessions with timeout
			const saveTimeout = this.persistenceConfig.saveTimeout!;
			const maxSessionsToSave = this.persistenceConfig.maxSessionsToSave!;

			const savePromises = activeSessions
				.slice(0, maxSessionsToSave)
				.map(async ([sessionId, metadata]) => {
					try {
						const savePromise = this.saveSession(sessionId, metadata.session);
						await Promise.race([
							savePromise,
							new Promise<void>((_, reject) =>
								setTimeout(() => reject(new Error('Save timeout')), saveTimeout)
							),
						]);

						stats.savedSessions++;
						logger.debug(`SessionManager: Successfully saved session ${sessionId}`);
					} catch (error) {
						stats.failedSessions++;
						stats.failedSessionIds.push(sessionId);
						const errorMsg = error instanceof Error ? error.message : String(error);
						stats.errors.push(`Session ${sessionId}: ${errorMsg}`);
						logger.error(`SessionManager: Failed to save session ${sessionId}:`, error);
					}
				});

			// Execute all saves in parallel
			await Promise.allSettled(savePromises);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			stats.errors.push(`Save operation failed: ${errorMsg}`);
			logger.error('SessionManager: Failed to save sessions:', error);
		}

		stats.persistenceTime = Date.now() - startTime;

		logger.info(`SessionManager: Session persistence completed`, {
			totalSessions: stats.totalSessions,
			savedSessions: stats.savedSessions,
			failedSessions: stats.failedSessions,
			persistenceTime: stats.persistenceTime,
		});

		return stats;
	}

	/**
	 * Load all sessions from persistent storage
	 * @returns Statistics about the load operation
	 */
	public async loadAllSessions(): Promise<SessionRestorationStats> {
		await this.ensureInitialized();

		const startTime = Date.now();
		const stats: SessionRestorationStats = {
			totalSessions: 0,
			restoredSessions: 0,
			failedSessions: 0,
			restorationTime: 0,
			failedSessionIds: [],
			errors: [],
		};

		if (!this.storageManager) {
			const error = 'No storage manager available for session persistence';
			stats.errors.push(error);
			logger.debug(`SessionManager.loadAllSessions: ${error}`);
			return stats;
		}

		if (!this.storageManager.isConnected()) {
			const error = 'Storage manager is not connected';
			stats.errors.push(error);
			logger.warn(`SessionManager.loadAllSessions: ${error}`);
			return stats;
		}

		try {
			// Get all session keys from storage
			const backends = this.storageManager.getBackends();
			if (!backends) {
				throw new SessionPersistenceError('No storage backends available', 'load');
			}

			// Scan for session keys (this might need to be implemented differently depending on backend)
			const sessionKeys = await this.getAllSessionKeys();
			stats.totalSessions = sessionKeys.length;

			if (sessionKeys.length === 0) {
				logger.debug('SessionManager.loadAllSessions: No sessions found in storage');
				stats.restorationTime = Date.now() - startTime;
				return stats;
			}

			// Load sessions with timeout
			const loadTimeout = this.persistenceConfig.loadTimeout!;
			const maxAge = this.persistenceConfig.maxSessionAge!;
			const now = Date.now();

			const loadPromises = sessionKeys.map(async key => {
				try {
					const sessionId = this.extractSessionIdFromKey(key);

					const loadPromise = this.loadSession(sessionId);
					const session = await Promise.race([
						loadPromise,
						new Promise<ConversationSession | null>((_, reject) =>
							setTimeout(() => reject(new Error('Load timeout')), loadTimeout)
						),
					]);

					if (session) {
						// Check if session is too old
						const sessionAge = now - (this.sessions.get(sessionId)?.createdAt || now);
						if (sessionAge > maxAge) {
							logger.debug(
								`SessionManager: Session ${sessionId} is too old (${sessionAge}ms), skipping`
							);
							return;
						}

						stats.restoredSessions++;
						logger.debug(`SessionManager: Successfully restored session ${sessionId}`);
					}
				} catch (error) {
					const sessionId = this.extractSessionIdFromKey(key);
					stats.failedSessions++;
					stats.failedSessionIds.push(sessionId);
					const errorMsg = error instanceof Error ? error.message : String(error);
					stats.errors.push(`Session ${sessionId}: ${errorMsg}`);
					logger.error(`SessionManager: Failed to restore session ${sessionId}:`, error);
				}
			});

			// Execute all loads in parallel
			await Promise.allSettled(loadPromises);
		} catch (error) {
			const errorMsg = error instanceof Error ? error.message : String(error);
			stats.errors.push(`Load operation failed: ${errorMsg}`);
			logger.error('SessionManager: Failed to load sessions:', error);
		}

		stats.restorationTime = Date.now() - startTime;

		// Only log if there are issues or in debug mode
		if (stats.failedSessions > 0 || stats.errors.length > 0) {
			logger.warn(`SessionManager: Session restoration completed with issues`, {
				totalSessions: stats.totalSessions,
				restoredSessions: stats.restoredSessions,
				failedSessions: stats.failedSessions,
				restorationTime: stats.restorationTime,
			});
		} else if (stats.totalSessions > 0) {
			logger.debug(`SessionManager: Session restoration completed`, {
				totalSessions: stats.totalSessions,
				restoredSessions: stats.restoredSessions,
				restorationTime: stats.restorationTime,
			});
		}

		return stats;
	}

	/**
	 * Initialize storage manager for session persistence
	 */
	private async initializePersistenceStorage(): Promise<void> {
		logger.info('SessionManager: Initializing persistence storage...');

		// Check for PostgreSQL environment variables
		const postgresUrl = process.env.CIPHER_PG_URL;
		const postgresHost = process.env.STORAGE_DATABASE_HOST;
		const postgresDatabase = process.env.STORAGE_DATABASE_NAME;

		if (postgresUrl || (postgresHost && postgresDatabase)) {
			try {
				// Try PostgreSQL first if PostgreSQL environment variables are set
				logger.debug('SessionManager: Attempting to initialize PostgreSQL storage...');

				let postgresConfig: any = {
					type: 'postgres' as const,
				};

				if (postgresUrl) {
					// Use connection URL if provided
					postgresConfig.url = postgresUrl;
					logger.debug('SessionManager: Using PostgreSQL connection URL');
				} else {
					// Use individual parameters
					postgresConfig.host = postgresHost;
					postgresConfig.database = postgresDatabase;
					postgresConfig.port = process.env.STORAGE_DATABASE_PORT
						? parseInt(process.env.STORAGE_DATABASE_PORT, 10)
						: 5432;
					postgresConfig.user = process.env.STORAGE_DATABASE_USER;
					postgresConfig.password = process.env.STORAGE_DATABASE_PASSWORD;
					postgresConfig.ssl = process.env.STORAGE_DATABASE_SSL === 'true';
					logger.debug('SessionManager: Using PostgreSQL individual parameters');
				}

				this.storageManager = new StorageManager({
					database: postgresConfig,
					cache: {
						type: 'in-memory',
					},
				});

				await this.storageManager.connect();
				logger.info('SessionManager: PostgreSQL persistence storage initialized successfully');
			} catch (postgresError) {
				logger.warn(
					'SessionManager: PostgreSQL failed, falling back to SQLite storage',
					postgresError
				);
				await this.initializeSqliteStorage();
			}
		} else {
			// No PostgreSQL configuration, try SQLite
			await this.initializeSqliteStorage();
		}

		if (this.storageManager) {
			const backends = this.storageManager.getBackends();
			logger.info(
				`SessionManager: Storage initialized with database backend: ${backends?.database?.getBackendType?.() || 'unknown'}`
			);
		} else {
			logger.warn('SessionManager: No storage manager available - sessions will not persist');
		}
	}

	/**
	 * Initialize SQLite storage as fallback
	 */
	private async initializeSqliteStorage(): Promise<void> {
		try {
			// Try SQLite as fallback
			logger.debug('SessionManager: Attempting to initialize SQLite storage...');
			this.storageManager = new StorageManager({
				database: {
					type: 'sqlite',
					path: './data',
					database: 'cipher-sessions.db',
				},
				cache: {
					type: 'in-memory',
				},
			});

			await this.storageManager.connect();
			logger.info('SessionManager: SQLite persistence storage initialized successfully');
		} catch (sqliteError) {
			logger.warn(
				'SessionManager: SQLite failed, falling back to in-memory storage for sessions',
				sqliteError
			);

			try {
				// Fallback to in-memory storage for session persistence
				logger.debug('SessionManager: Attempting to initialize in-memory storage...');
				this.storageManager = new StorageManager({
					database: {
						type: 'in-memory',
					},
					cache: {
						type: 'in-memory',
					},
				});

				await this.storageManager.connect();
				logger.warn(
					'SessionManager: In-memory persistence storage initialized (sessions will not persist across restarts)'
				);
			} catch (fallbackError) {
				logger.error(
					'SessionManager: Failed to initialize any persistence storage, continuing without session persistence',
					fallbackError
				);
				this.storageManager = undefined;
				// Continue without persistence rather than failing
			}
		}
	}

	/**
	 * Save a single session to storage
	 */
	private async saveSession(sessionId: string, session: ConversationSession): Promise<void> {
		if (!this.storageManager?.isConnected()) {
			throw new SessionPersistenceError('Storage manager not connected', 'save', sessionId);
		}

		const serialized = await session.serialize();

		// CRITICAL FIX: Don't save sessions with 0 messages to prevent phantom sessions
		if (serialized.conversationHistory.length === 0) {
			logger.debug(`SessionManager: Skipping save of session ${sessionId} with 0 messages`);
			return;
		}

		const key = this.getSessionStorageKey(sessionId);

		const backends = this.storageManager.getBackends();
		if (!backends) {
			throw new SessionPersistenceError('No storage backends available', 'save', sessionId);
		}

		await backends.database.set(key, serialized);
		logger.debug(
			`SessionManager: Saved session ${sessionId} to persistent storage with ${serialized.conversationHistory.length} messages`
		);
	}

	/**
	 * Load a single session from storage
	 */
	private async loadSession(sessionId: string): Promise<ConversationSession | null> {
		// Handle null or invalid session IDs
		if (!sessionId || sessionId === 'null' || sessionId === 'undefined') {
			logger.debug(`SessionManager: Invalid session ID provided: ${sessionId}`);
			return null;
		}

		if (!this.storageManager?.isConnected()) {
			throw new SessionPersistenceError('Storage manager not connected', 'load', sessionId);
		}

		const key = this.getSessionStorageKey(sessionId);
		const backends = this.storageManager.getBackends();

		if (!backends) {
			throw new SessionPersistenceError('No storage backends available', 'load', sessionId);
		}

		const serialized = await backends.database.get<SerializedSession>(key);
		if (!serialized) {
			logger.debug(`SessionManager: No serialized data found for session ${sessionId}`);
			return null;
		}

		// Validate the serialized data if configured to do so
		if (this.persistenceConfig.validateOnRestore) {
			if (!this.validateSerializedSession(serialized)) {
				throw new SessionPersistenceError('Invalid serialized session data', 'load', sessionId);
			}
		}

		// Deserialize and restore the session
		const session = await ConversationSession.deserialize(serialized, this.services);

		// Add to active sessions
		// const now = Date.now();
		this.sessions.set(sessionId, {
			session,
			lastActivity: serialized.metadata.lastActivity,
			createdAt: serialized.metadata.createdAt,
		});

		// CRITICAL FIX: Force refresh conversation history after session is loaded
		// This ensures the context manager has the conversation history when switching sessions
		try {
			await session.refreshConversationHistory();
			logger.debug(`SessionManager: Refreshed conversation history for session ${sessionId}`);

			// Verify that the context manager has the messages
			const contextHistory = session.getContextHistory();
			logger.debug(
				`SessionManager: Context manager for session ${sessionId} has ${contextHistory.length} messages`
			);

			// Also verify history provider has messages
			const history = await session.getConversationHistory();
			logger.debug(
				`SessionManager: History provider for session ${sessionId} has ${history.length} messages`
			);
		} catch (error) {
			logger.warn(
				`SessionManager: Failed to refresh conversation history for session ${sessionId}:`,
				error
			);
			// Continue even if history refresh fails
		}

		logger.debug(
			`SessionManager: Loaded session ${sessionId} from persistent storage with ${serialized.conversationHistory.length} messages`
		);
		return session;
	}

	/**
	 * Get all session keys from storage with optimized batch processing
	 */
	private async getAllSessionKeys(): Promise<string[]> {
		if (!this.storageManager?.isConnected()) {
			logger.warn('SessionManager: Storage manager not connected, cannot get session keys');
			return [];
		}

		const backends = this.storageManager.getBackends();
		if (!backends) {
			logger.warn('SessionManager: No storage backends available');
			return [];
		}

		try {
			// Use the database backend's list method to get all keys with our prefix
			const prefix = this.persistenceConfig.storageKeyPrefix!;
			logger.debug(`SessionManager: Searching for session keys with prefix '${prefix}'`);

			const sessionKeys = await backends.database.list(prefix);

			logger.debug(
				`SessionManager: Found ${sessionKeys.length} session keys in storage with prefix '${prefix}'`
			);
			return sessionKeys;
		} catch (error) {
			logger.warn('SessionManager: Failed to get session keys from storage:', error);
			return [];
		}
	}

	/**
	 * Get all message keys from storage for session discovery
	 */
	private async getAllMessageKeys(): Promise<string[]> {
		if (!this.storageManager?.isConnected()) {
			return [];
		}

		const backends = this.storageManager.getBackends();
		if (!backends) {
			return [];
		}

		try {
			const messageKeys = await backends.database.list('messages:');
			logger.debug(`SessionManager: Found ${messageKeys.length} message keys in storage`);
			return messageKeys;
		} catch (error) {
			logger.warn('SessionManager: Failed to get message keys from storage:', error);
			return [];
		}
	}

	/**
	 * Get the storage key for a session
	 */
	private getSessionStorageKey(sessionId: string): string {
		return `${this.persistenceConfig.storageKeyPrefix}${sessionId}`;
	}

	/**
	 * Extract session ID from storage key
	 */
	private extractSessionIdFromKey(key: string): string {
		const prefix = this.persistenceConfig.storageKeyPrefix!;
		return key.startsWith(prefix) ? key.substring(prefix.length) : key;
	}

	/**
	 * Validate a serialized session object
	 */
	private validateSerializedSession(data: SerializedSession): boolean {
		try {
			return (
				typeof data.id === 'string' &&
				typeof data.version === 'string' &&
				typeof data.serializedAt === 'number' &&
				data.metadata &&
				typeof data.metadata.createdAt === 'number' &&
				typeof data.metadata.lastActivity === 'number' &&
				Array.isArray(data.conversationHistory)
			);
		} catch {
			return false;
		}
	}

	public async shutdown(): Promise<void> {
		logger.info(
			`SessionManager: Starting shutdown process for ${this.sessions.size} active sessions...`
		);

		// Save all sessions before shutting down
		try {
			const saveStats = await this.saveAllSessions();
			logger.info(
				`SessionManager: Shutdown save completed - ${saveStats.savedSessions}/${saveStats.totalSessions} sessions saved`
			);
		} catch (error) {
			logger.error('SessionManager: Failed to save sessions during shutdown:', error);
		}

		// Stop cleanup interval
		if (this.cleanupInterval) {
			clearInterval(this.cleanupInterval);
			this.cleanupInterval = undefined;
		}

		// Clear performance caches and request deduplicators
		this.sessionMetadataCache.clear();
		this.messageCountCache.clear();
		this.requestDeduplicator.clear();

		// Log performance metrics
		logger.info('SessionManager: Final performance metrics:', this.performanceMetrics);

		// Disconnect storage manager
		if (this.storageManager) {
			try {
				await this.storageManager.disconnect();
				logger.debug('SessionManager: Storage manager disconnected');
			} catch (error) {
				logger.warn('SessionManager: Failed to disconnect storage manager:', error);
			}
		}

		// Clear in-memory sessions
		const sessionCount = this.sessions.size;
		this.sessions.clear();

		logger.info(`SessionManager: Shutdown complete. Cleared ${sessionCount} in-memory sessions`);
	}

	/**
	 * Get the storageManager for a given session (if available)
	 */
	public getStorageManagerForSession(sessionId: string): any {
		const sessionMetadata = this.sessions.get(sessionId);
		if (
			sessionMetadata &&
			sessionMetadata.session &&
			typeof sessionMetadata.session.getStorageManager === 'function'
		) {
			return sessionMetadata.session.getStorageManager();
		}
		return undefined;
	}

	/**
	 * Performance optimization: Cache management methods
	 */
	private getCachedResult<T>(key: string): T | null {
		const now = Date.now();

		// Check session metadata cache
		const metadataEntry = this.sessionMetadataCache.get(key);
		if (metadataEntry && now < metadataEntry.expiresAt) {
			return metadataEntry.metadata as unknown as T;
		}

		// Check message count cache
		const countEntry = this.messageCountCache.get(key);
		if (countEntry && now < countEntry.expiresAt) {
			return countEntry.count as unknown as T;
		}

		return null;
	}

	private setCacheResult<T>(key: string, value: T): void {
		const now = Date.now();
		const expiresAt = now + this.CACHE_TTL;

		if (Array.isArray(value)) {
			// For arrays (like session IDs), create a special cache entry
			this.sessionMetadataCache.set(key, {
				metadata: value as unknown as SessionMetadata,
				cachedAt: now,
				expiresAt,
			});
		} else if (typeof value === 'number') {
			// For numbers (like message counts)
			this.messageCountCache.set(key, {
				count: value,
				cachedAt: now,
				expiresAt,
			});
		}
	}

	private cleanupExpiredCache(): void {
		const now = Date.now();

		// Clean up expired session metadata cache entries
		for (const [key, entry] of this.sessionMetadataCache.entries()) {
			if (now >= entry.expiresAt) {
				this.sessionMetadataCache.delete(key);
			}
		}

		// Clean up expired message count cache entries
		for (const [key, entry] of this.messageCountCache.entries()) {
			if (now >= entry.expiresAt) {
				this.messageCountCache.delete(key);
			}
		}
	}

	private updateAverageLoadTime(loadTime: number): void {
		const alpha = 0.1; // Exponential moving average factor
		this.performanceMetrics.averageLoadTime =
			this.performanceMetrics.averageLoadTime === 0
				? loadTime
				: alpha * loadTime + (1 - alpha) * this.performanceMetrics.averageLoadTime;
	}

	/**
	 * Clear session from all caches to prevent phantom sessions
	 */
	private clearSessionFromAllCaches(sessionId: string): void {
		// Clear from metadata cache
		this.sessionMetadataCache.delete(`metadata_${sessionId}`);

		// Clear from message count cache
		this.messageCountCache.delete(`count_${sessionId}`);

		// Clear from active session IDs cache (invalidate the list)
		this.sessionMetadataCache.delete('active_session_ids');

		logger.debug(`SessionManager: Cleared all caches for session ${sessionId}`);
	}

	/**
	 * Filter out invalid sessions (empty sessions with 0 messages)
	 */
	private async filterValidSessions(sessionIds: string[]): Promise<string[]> {
		const validSessions: string[] = [];

		for (const sessionId of sessionIds) {
			try {
				// Check if session has messages or is in active memory
				const isInMemory = this.sessions.has(sessionId);
				const messageCount = await this.getSessionMessageCount(sessionId);

				// Keep sessions that are either in memory OR have messages
				if (isInMemory || messageCount > 0) {
					validSessions.push(sessionId);
				} else {
					// Clean up phantom sessions with 0 messages
					logger.debug(`SessionManager: Cleaning up phantom session ${sessionId} with 0 messages`);
					await this.cleanupPhantomSession(sessionId);
				}
			} catch (error) {
				logger.warn(`SessionManager: Error validating session ${sessionId}:`, error);
				// Include session in case of validation error to be safe
				validSessions.push(sessionId);
			}
		}

		return validSessions;
	}

	/**
	 * Clean up phantom sessions that have no messages
	 */
	private async cleanupPhantomSession(sessionId: string): Promise<void> {
		try {
			if (this.storageManager?.isConnected()) {
				const backends = this.storageManager.getBackends();
				if (backends?.database) {
					// Delete phantom session data
					const sessionKey = this.getSessionStorageKey(sessionId);
					const historyKey = `messages:${sessionId}`;

					await Promise.allSettled([
						backends.database.delete(sessionKey),
						backends.database.delete(historyKey),
					]);

					logger.debug(`SessionManager: Cleaned up phantom session ${sessionId}`);
				}
			}
		} catch (error) {
			logger.warn(`SessionManager: Failed to cleanup phantom session ${sessionId}:`, error);
		}
	}

	/**
	 * Get batch session metadata with parallel processing and caching
	 */
	public async getBatchSessionMetadata(
		sessionIds: string[]
	): Promise<
		Map<string, { id: string; messageCount: number; createdAt: number; lastActivity: number }>
	> {
		const startTime = Date.now();
		const result = new Map<
			string,
			{ id: string; messageCount: number; createdAt: number; lastActivity: number }
		>();

		// Process sessions in parallel batches
		const batches = [];
		for (let i = 0; i < sessionIds.length; i += this.BATCH_SIZE) {
			batches.push(sessionIds.slice(i, i + this.BATCH_SIZE));
		}

		for (const batch of batches) {
			const batchPromises = batch.map(async sessionId => {
				try {
					// Check cache first
					const cacheKey = `metadata_${sessionId}`;
					const cached = this.getCachedResult<{
						id: string;
						messageCount: number;
						createdAt: number;
						lastActivity: number;
					}>(cacheKey);

					if (cached) {
						this.performanceMetrics.cacheHits++;
						return { sessionId, metadata: cached };
					}

					this.performanceMetrics.cacheMisses++;

					// Get metadata from session or storage
					let metadata: {
						id: string;
						messageCount: number;
						createdAt: number;
						lastActivity: number;
					} | null = null;

					// Try in-memory session first
					const sessionMetadata = this.sessions.get(sessionId);
					if (sessionMetadata) {
						metadata = {
							id: sessionId,
							messageCount: await this.getSessionMessageCount(sessionId),
							createdAt: sessionMetadata.createdAt,
							lastActivity: sessionMetadata.lastActivity,
						};
					} else {
						// Load from storage
						metadata = await this.getSessionMetadataFromStorage(sessionId);
					}

					if (metadata) {
						// Cache the result
						this.setCacheResult(cacheKey, metadata);
						return { sessionId, metadata };
					}

					return { sessionId, metadata: null };
				} catch (error) {
					logger.warn(`Failed to get metadata for session ${sessionId}:`, error);
					return { sessionId, metadata: null };
				}
			});

			// Process batch in parallel
			const batchResults = await Promise.allSettled(batchPromises);
			this.performanceMetrics.parallelLoads += batchResults.length;

			// Collect results
			for (const promiseResult of batchResults) {
				if (promiseResult.status === 'fulfilled' && promiseResult.value.metadata) {
					result.set(promiseResult.value.sessionId, promiseResult.value.metadata);
				}
			}
		}

		const loadTime = Date.now() - startTime;
		this.updateAverageLoadTime(loadTime);

		logger.debug(
			`SessionManager: Batch loaded ${result.size}/${sessionIds.length} session metadata in ${loadTime}ms`
		);
		return result;
	}

	/**
	 * Get session message count with caching
	 */
	private async getSessionMessageCount(sessionId: string): Promise<number> {
		const cacheKey = `count_${sessionId}`;
		const cached = this.getCachedResult<number>(cacheKey);

		if (cached !== null) {
			this.performanceMetrics.cacheHits++;
			return cached;
		}

		this.performanceMetrics.cacheMisses++;

		try {
			// Try to get from active session
			const sessionMetadata = this.sessions.get(sessionId);
			if (sessionMetadata) {
				const history = await sessionMetadata.session.getConversationHistory();
				// Filter to only include user and assistant messages (excluding tool calls)
				const filteredHistory = history.filter((msg: any) => {
					// Include user messages
					if (msg.role === 'user') return true;
					// Include assistant messages that don't have tool calls
					if (msg.role === 'assistant' && (!msg.toolCalls || msg.toolCalls.length === 0))
						return true;
					// Exclude everything else
					return false;
				});
				const count = filteredHistory.length;
				this.setCacheResult(cacheKey, count);
				return count;
			}

			// Try to get from storage
			if (this.storageManager?.isConnected()) {
				const backends = this.storageManager.getBackends();
				if (backends?.database) {
					// Try messages key first
					const historyKey = `messages:${sessionId}`;
					const historyData = await backends.database.get(historyKey);
					if (historyData && Array.isArray(historyData)) {
						// Filter to only include user and assistant messages (excluding tool calls)
						const filteredHistory = historyData.filter((msg: any) => {
							// Include user messages
							if (msg.role === 'user') return true;
							// Include assistant messages that don't have tool calls
							if (msg.role === 'assistant' && (!msg.toolCalls || msg.toolCalls.length === 0))
								return true;
							// Exclude everything else
							return false;
						});
						const count = filteredHistory.length;
						this.setCacheResult(cacheKey, count);
						return count;
					}

					// Try session data
					const sessionKey = this.getSessionStorageKey(sessionId);
					const sessionData = await backends.database.get(sessionKey);
					if ((sessionData as any)?.conversationHistory?.length) {
						// Filter to only include user and assistant messages (excluding tool calls)
						const filteredHistory = (sessionData as any).conversationHistory.filter((msg: any) => {
							// Include user messages
							if (msg.role === 'user') return true;
							// Include assistant messages that don't have tool calls
							if (msg.role === 'assistant' && (!msg.toolCalls || msg.toolCalls.length === 0))
								return true;
							// Exclude everything else
							return false;
						});
						const count = filteredHistory.length;
						this.setCacheResult(cacheKey, count);
						return count;
					}
				}
			}

			// Default to 0 if not found
			this.setCacheResult(cacheKey, 0);
			return 0;
		} catch (error) {
			logger.warn(`Failed to get message count for session ${sessionId}:`, error);
			this.setCacheResult(cacheKey, 0);
			return 0;
		}
	}

	/**
	 * Get session metadata from storage
	 */
	private async getSessionMetadataFromStorage(
		sessionId: string
	): Promise<{ id: string; messageCount: number; createdAt: number; lastActivity: number } | null> {
		if (!this.storageManager?.isConnected()) {
			return null;
		}

		const backends = this.storageManager.getBackends();
		if (!backends?.database) {
			return null;
		}

		try {
			// Get message count and session data in parallel
			const [messageCount, sessionData] = await Promise.allSettled([
				this.getSessionMessageCount(sessionId),
				backends.database.get(this.getSessionStorageKey(sessionId)),
			]);

			const count = messageCount.status === 'fulfilled' ? messageCount.value : 0;
			const data = sessionData.status === 'fulfilled' ? sessionData.value : null;

			// Create metadata with best available information
			const now = Date.now();
			return {
				id: sessionId,
				messageCount: count,
				createdAt: (data as any)?.metadata?.createdAt || now - count * 60000, // Estimate based on message count
				lastActivity: (data as any)?.metadata?.lastActivity || now,
			};
		} catch (error) {
			logger.warn(`Failed to get session metadata from storage for ${sessionId}:`, error);
			return null;
		}
	}
}

/**
 * Storage Factory Tests
 *
 * Tests for the factory functions that create and initialize storage systems.
