describe('Storage Factory', () => {
	// Store original env vars
	const originalEnv = { ...process.env };

	afterEach(() => {
		// Restore environment variables
		process.env = { ...originalEnv };
	});

	describe('createStorageBackends', () => {
		it('should create and connect storage backends', async () => {
			const config: StorageConfig = {
				cache: { type: 'in-memory' },
				database: { type: 'in-memory' },
			};

			const result = await createStorageBackends(config);

			// Verify structure
			expect(result).toHaveProperty('manager');
			expect(result).toHaveProperty('backends');
			expect(result.manager).toBeInstanceOf(StorageManager);
			expect(result.backends.cache).toBeInstanceOf(InMemoryBackend);
			expect(result.backends.database).toBeInstanceOf(InMemoryBackend);

			// Verify connected
			expect(result.manager.isConnected()).toBe(true);
			expect(result.backends.cache.isConnected()).toBe(true);
			expect(result.backends.database.isConnected()).toBe(true);

			// Cleanup
			await result.manager.disconnect();
		});

		it('should handle connection failures gracefully', async () => {
			const config: StorageConfig = {
				cache: { type: 'in-memory' },
				database: { type: 'in-memory' },
			};

			// Mock connection failure
			const originalConnect = StorageManager.prototype.connect;
			StorageManager.prototype.connect = vi.fn().mockRejectedValue(new Error('Connection failed'));

			try {
				await expect(createStorageBackends(config)).rejects.toThrow('Connection failed');
			} finally {
				// Restore original method
				StorageManager.prototype.connect = originalConnect;
			}
		});

		it('should work with fallback backends', async () => {
			const config: StorageConfig = {
				cache: { type: 'redis', host: 'invalid-host', connectionTimeoutMillis: 1000 },
				database: { type: 'sqlite', path: '/root/nonexistent/readonly/test.db' },
			};

			const result = await createStorageBackends(config);

			// Should fallback to in-memory
			expect(result.backends.cache).toBeInstanceOf(InMemoryBackend);
			expect(result.backends.database).toBeInstanceOf(InMemoryBackend);

			const info = result.manager.getInfo();
			expect(info.backends.cache.fallback).toBe(true);
			expect(info.backends.database.fallback).toBe(true);

			// Cleanup
			await result.manager.disconnect();
		}, 10000); // Increase timeout for this test
	});

	describe('createDefaultStorage', () => {
		it('should create storage with in-memory backends', async () => {
			const result = await createDefaultStorage();

			expect(result.manager).toBeInstanceOf(StorageManager);
			expect(result.backends.cache).toBeInstanceOf(InMemoryBackend);
			expect(result.backends.database).toBeInstanceOf(InMemoryBackend);

			const info = result.manager.getInfo();
			expect(info.backends.cache.type).toBe('in-memory');
			expect(info.backends.database.type).toBe('in-memory');
			expect(info.backends.cache.fallback).toBe(false);
			expect(info.backends.database.fallback).toBe(false);

			// Cleanup
			await result.manager.disconnect();
		});
	});

	describe('createStorageFromEnv', () => {
		it('should create default storage when no env vars are set', async () => {
			// Clear relevant env vars
			delete process.env.STORAGE_CACHE_TYPE;
			delete process.env.STORAGE_DATABASE_TYPE;

			const result = await createStorageFromEnv();

			const info = result.manager.getInfo();
			expect(info.backends.cache.type).toBe('in-memory');
			expect(info.backends.database.type).toBe('in-memory');

			// Cleanup
			await result.manager.disconnect();
		});

		it('should create SQLite database from env vars', async () => {
			process.env.STORAGE_DATABASE_TYPE = 'sqlite';
			process.env.STORAGE_DATABASE_PATH = '/root/nonexistent/readonly';
			process.env.STORAGE_DATABASE_NAME = 'test.db';

			const result = await createStorageFromEnv();

			// Will fallback to in-memory due to connection failure
			const info = result.manager.getInfo();
			expect(info.backends.database.fallback).toBe(true);
			expect(info.backends.database.type).toBe('in-memory');

			// Cleanup
			await result.manager.disconnect();
		});

		it('should handle postgres type with fallback', async () => {
			process.env.STORAGE_DATABASE_TYPE = 'postgres';

			const result = await createStorageFromEnv();

			// Should use in-memory since postgres is not implemented
			const info = result.manager.getInfo();
			expect(info.backends.database.type).toBe('in-memory');
			expect(info.backends.database.fallback).toBe(false);

			// Cleanup
			await result.manager.disconnect();
		});

		it('should handle invalid Redis port configuration', async () => {
			// Test invalid port handling without actual connection
			process.env.STORAGE_CACHE_TYPE = 'redis';
			process.env.STORAGE_CACHE_PORT = 'invalid';
			process.env.STORAGE_CACHE_CONNECTION_TIMEOUT_MILLIS = '1000';

			// The factory should handle invalid config gracefully and fall back to in-memory
			const result = await createStorageFromEnv();

			// Should still create storage (with fallback due to invalid port)
			expect(result.manager).toBeInstanceOf(StorageManager);
			const info = result.manager.getInfo();
			expect(info.backends.cache.type).toBe('in-memory');

			// Cleanup
			await result.manager.disconnect();
		});

		it('should parse Redis cache config from env vars', async () => {
			// Test Redis config parsing - this will fail to connect and fallback to in-memory
			// but that's the expected behavior we want to test
			process.env.STORAGE_CACHE_TYPE = 'redis';
			process.env.STORAGE_CACHE_HOST = 'nonexistent-host-12345';
			process.env.STORAGE_CACHE_PORT = '6380';
			process.env.STORAGE_CACHE_PASSWORD = 'test-pass';
			process.env.STORAGE_CACHE_DATABASE = '1';
			process.env.STORAGE_CACHE_CONNECTION_TIMEOUT_MILLIS = '100'; // Very short timeout

			const result = await createStorageFromEnv();

			// Should fallback to in-memory due to connection failure
			const info = result.manager.getInfo();
			expect(info.backends.cache.fallback).toBe(true);
			expect(info.backends.cache.type).toBe('in-memory');

			// Cleanup
			await result.manager.disconnect();
		}, 15000); // Increase timeout to 15 seconds
	});

	describe('isStorageFactory', () => {
		it('should return true for valid StorageFactory objects', async () => {
			const result = await createDefaultStorage();

			expect(isStorageFactory(result)).toBe(true);

			// Cleanup
			await result.manager.disconnect();
		});

		it('should return false for invalid objects', () => {
			expect(isStorageFactory(null)).toBe(false);
			expect(isStorageFactory(undefined)).toBe(false);
			expect(isStorageFactory({})).toBe(false);
			expect(isStorageFactory({ manager: {} })).toBe(false);
			expect(isStorageFactory({ backends: {} })).toBe(false);
			expect(isStorageFactory({ manager: {}, backends: {} })).toBe(false);
		});
	});

	describe('Integration', () => {
		it('should support typical usage pattern', async () => {
			// Create storage
			const { manager, backends } = await createStorageBackends({
				cache: { type: 'in-memory' },
				database: { type: 'in-memory' },
			});

			// Use cache backend
			await backends.cache.set('session:123', { userId: 'user1' }, 300);
			const session = await backends.cache.get('session:123');
			expect(session).toEqual({ userId: 'user1' });

			// Use database backend
			await backends.database.set('user:1', { name: 'Alice', email: 'alice@example.com' });
			const user = await backends.database.get('user:1');
			expect(user).toEqual({ name: 'Alice', email: 'alice@example.com' });

			// List operations
			await backends.database.append('log:user:1', { action: 'login', timestamp: Date.now() });
			const logs = await backends.database.getRange('log:user:1', 0, 10);
			expect(logs).toHaveLength(1);

			// Get info
			const info = manager.getInfo();
			expect(info.connected).toBe(true);
			expect(info.backends.cache.connected).toBe(true);
			expect(info.backends.database.connected).toBe(true);

			// Cleanup
			await manager.disconnect();
			expect(manager.isConnected()).toBe(false);
		});

		it('should handle lifecycle correctly on error', async () => {
			// Create storage that will use fallbacks
			const { manager, backends } = await createStorageBackends({
				cache: { type: 'redis', host: 'nonexistent', connectionTimeoutMillis: 1000 },
				database: { type: 'sqlite', path: '/root/nonexistent/readonly/test.db' },
			});

			// Should still be usable with fallbacks
			await backends.cache.set('key', 'value');
			const value = await backends.cache.get('key');
			expect(value).toBe('value');

			// Info should show fallbacks
			const info = manager.getInfo();
			expect(info.backends.cache.fallback).toBe(true);
			expect(info.backends.database.fallback).toBe(true);

			// Cleanup should work
			await manager.disconnect();
			expect(manager.isConnected()).toBe(false);
		}, 10000); // Increase timeout for this test
	});
});

/**
 * Storage Manager Tests
 *
 * Tests for the storage manager implementation including
 * connection logic, fallback mechanisms, and lifecycle management.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { StorageManager } from '../manager.js';
import { InMemoryBackend } from '../backend/in-memory.js';
import { BACKEND_TYPES } from '../constants.js';
import type { StorageConfig } from '../types.js';

// Mock the logger to reduce noise in tests
vi.mock('../../logger/index.js', () => ({
	createLogger: () => ({
		info: vi.fn(),
		debug: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
	}),
}));

describe('StorageManager', () => {
	let manager: StorageManager;

	afterEach(async () => {
		// Ensure cleanup after each test
		if (manager && manager.isConnected()) {
			await manager.disconnect();
		}
	});

	describe('Configuration', () => {
		it('should validate configuration on construction', () => {
			expect(() => {
				new StorageManager({} as any);
			}).toThrow('Invalid storage configuration');

			expect(() => {
				new StorageManager({
					cache: { type: 'invalid' as any },
					database: { type: 'in-memory' },
				});
			}).toThrow('Invalid storage configuration');
		});

		it('should accept valid configuration', () => {
			const config: StorageConfig = {
				cache: { type: 'in-memory' },
				database: { type: 'in-memory' },
			};

			expect(() => {
				manager = new StorageManager(config);
			}).not.toThrow();

			expect(manager.getConfig()).toEqual(config);
		});
	});

	describe('Connection Management', () => {
		beforeEach(() => {
			const config: StorageConfig = {
				cache: { type: 'in-memory' },
				database: { type: 'in-memory' },
			};
			manager = new StorageManager(config);
		});

		it('should connect successfully with in-memory backends', async () => {
			expect(manager.isConnected()).toBe(false);

			const backends = await manager.connect();

			expect(manager.isConnected()).toBe(true);
			expect(backends.cache).toBeInstanceOf(InMemoryBackend);
			expect(backends.database).toBeInstanceOf(InMemoryBackend);
			expect(backends.cache.isConnected()).toBe(true);
			expect(backends.database.isConnected()).toBe(true);
		});

		it('should handle multiple connect calls (idempotency)', async () => {
			const backends1 = await manager.connect();
			const backends2 = await manager.connect();

			// Should return the same instances
			expect(backends1.cache).toBe(backends2.cache);
			expect(backends1.database).toBe(backends2.database);
			expect(manager.isConnected()).toBe(true);
		});

		it('should disconnect successfully', async () => {
			await manager.connect();
			expect(manager.isConnected()).toBe(true);

			await manager.disconnect();
			expect(manager.isConnected()).toBe(false);

			const backends = manager.getBackends();
			expect(backends).toBeNull();
		});

		it('should handle multiple disconnect calls', async () => {
			await manager.connect();
			await manager.disconnect();

			// Second disconnect should not throw
			await expect(manager.disconnect()).resolves.not.toThrow();
		});

		it('should clean up on connection failure', async () => {
			// Create a manager with SQLite config (will fail and fallback)
			const config: StorageConfig = {
				cache: { type: 'in-memory' },
				database: { type: 'sqlite', path: '/root/nonexistent/readonly/test.db' },
			};
			manager = new StorageManager(config);

			// Should still connect successfully with fallback
			const backends = await manager.connect();
			expect(backends.database).toBeInstanceOf(InMemoryBackend);

			const info = manager.getInfo();
			expect(info.backends.database.fallback).toBe(true);
		});
	});

	describe('Backend Fallback', () => {
		it('should fallback to in-memory for SQLite database', async () => {
			const config: StorageConfig = {
				cache: { type: 'in-memory' },
				database: { type: 'sqlite', path: '/root/nonexistent/readonly/test2.db' },
			};
			manager = new StorageManager(config);

			const backends = await manager.connect();

			// Should fallback to in-memory
			expect(backends.database).toBeInstanceOf(InMemoryBackend);
			expect(backends.database.getBackendType()).toBe(BACKEND_TYPES.IN_MEMORY);

			const info = manager.getInfo();
			expect(info.backends.database.type).toBe(BACKEND_TYPES.IN_MEMORY);
			expect(info.backends.database.fallback).toBe(true);
		});
	});

	describe('State Management', () => {
		beforeEach(() => {
			const config: StorageConfig = {
				cache: { type: 'in-memory' },
				database: { type: 'in-memory' },
			};
			manager = new StorageManager(config);
		});

		it('should track connection attempts', async () => {
			const info1 = manager.getInfo();
			expect(info1.connectionAttempts).toBe(0);

			await manager.connect();

			const info2 = manager.getInfo();
			expect(info2.connectionAttempts).toBe(1);

			// Disconnect and reconnect
			await manager.disconnect();
			await manager.connect();

			const info3 = manager.getInfo();
			expect(info3.connectionAttempts).toBe(2);
		});

		it('should provide accurate info', async () => {
			const info1 = manager.getInfo();
			expect(info1.connected).toBe(false);
			expect(info1.backends.cache.connected).toBe(false);
			expect(info1.backends.database.connected).toBe(false);

			await manager.connect();

			const info2 = manager.getInfo();
			expect(info2.connected).toBe(true);
			expect(info2.backends.cache.connected).toBe(true);
			expect(info2.backends.database.connected).toBe(true);
			expect(info2.backends.cache.type).toBe(BACKEND_TYPES.IN_MEMORY);
			expect(info2.backends.database.type).toBe(BACKEND_TYPES.IN_MEMORY);
		});

		it('should return null backends when not connected', () => {
			expect(manager.getBackends()).toBeNull();
		});

		it('should return backends when connected', async () => {
			await manager.connect();

			const backends = manager.getBackends();
			expect(backends).not.toBeNull();
			expect(backends?.cache).toBeInstanceOf(InMemoryBackend);
			expect(backends?.database).toBeInstanceOf(InMemoryBackend);
		});
	});

	describe('Error Handling', () => {
		it('should handle backend creation errors gracefully', async () => {
			// This test verifies that even with invalid configs,
			// the manager falls back to in-memory backends
			const config: StorageConfig = {
				cache: { type: 'redis', host: 'invalid-host', connectionTimeoutMillis: 1000 },
				database: { type: 'sqlite', path: '/root/nonexistent/readonly/test.db' },
			};
			manager = new StorageManager(config);

			// Should not throw, but use fallbacks
			const backends = await manager.connect();
			expect(backends.cache).toBeInstanceOf(InMemoryBackend);
			expect(backends.database).toBeInstanceOf(InMemoryBackend);

			const info = manager.getInfo();
			expect(info.backends.cache.fallback).toBe(true);
			expect(info.backends.database.fallback).toBe(true);
		}, 10000); // Increase timeout for this test

		it('should reset state on connection failure', async () => {
			const config: StorageConfig = {
				cache: { type: 'in-memory' },
				database: { type: 'in-memory' },
			};
			manager = new StorageManager(config);

			// Mock a connection failure
			const originalConnect = InMemoryBackend.prototype.connect;
			let callCount = 0;
			InMemoryBackend.prototype.connect = async function () {
				callCount++;
				if (callCount === 2) {
					// Fail on database connection
					throw new Error('Mock connection failure');
				}
				return originalConnect.call(this);
			};

			try {
				await expect(manager.connect()).rejects.toThrow('Mock connection failure');

				// State should be reset
				expect(manager.isConnected()).toBe(false);
				expect(manager.getBackends()).toBeNull();
			} finally {
				// Restore original method
				InMemoryBackend.prototype.connect = originalConnect;
			}
		});
	});

	describe('Lifecycle Integration', () => {
		it('should support typical usage pattern', async () => {
			const config: StorageConfig = {
				cache: { type: 'in-memory' },
				database: { type: 'in-memory' },
			};

			// Initialize
			manager = new StorageManager(config);
			expect(manager.isConnected()).toBe(false);

			// Connect
			const { cache, database } = await manager.connect();
			expect(manager.isConnected()).toBe(true);

			// Use backends
			await cache.set('test-key', 'test-value', 60);
			const value = await cache.get('test-key');
			expect(value).toBe('test-value');

			await database.set('user:1', { name: 'Alice' });
			const user = await database.get('user:1');
			expect(user).toEqual({ name: 'Alice' });

			// Disconnect
			await manager.disconnect();
			expect(manager.isConnected()).toBe(false);
		});
	});
});

/**
 * In-Memory Backend Tests
 *
 * Tests for the in-memory storage backend implementation.
 * Verifies both CacheBackend and DatabaseBackend functionality.
 */

import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import { InMemoryBackend } from '../in-memory.js';
import { StorageError } from '../types.js';
import { BACKEND_TYPES } from '../../constants.js';

describe('InMemoryBackend', () => {
	let backend: InMemoryBackend;

	beforeEach(() => {
		backend = new InMemoryBackend();
	});

	afterEach(async () => {
		if (backend.isConnected()) {
			await backend.disconnect();
		}
	});

	describe('Connection Management', () => {
		it('should connect successfully', async () => {
			expect(backend.isConnected()).toBe(false);
			await backend.connect();
			expect(backend.isConnected()).toBe(true);
		});

		it('should handle multiple connect calls', async () => {
			await backend.connect();
			await backend.connect(); // Should not throw
			expect(backend.isConnected()).toBe(true);
		});

		it('should disconnect successfully', async () => {
			await backend.connect();
			await backend.disconnect();
			expect(backend.isConnected()).toBe(false);
		});

		it('should clear data on disconnect', async () => {
			await backend.connect();
			await backend.set('key', 'value');
			await backend.disconnect();
			await backend.connect();
			const value = await backend.get('key');
			expect(value).toBeUndefined();
		});

		it('should return correct backend type', () => {
			expect(backend.getBackendType()).toBe(BACKEND_TYPES.IN_MEMORY);
		});
	});

	describe('Basic Operations', () => {
		beforeEach(async () => {
			await backend.connect();
		});

		it('should set and get values', async () => {
			await backend.set('key1', 'value1');
			await backend.set('key2', { data: 'value2' });

			expect(await backend.get('key1')).toBe('value1');
			expect(await backend.get('key2')).toEqual({ data: 'value2' });
		});

		it('should return undefined for non-existent keys', async () => {
			expect(await backend.get('nonexistent')).toBeUndefined();
		});

		it('should delete values', async () => {
			await backend.set('key', 'value');
			expect(await backend.get('key')).toBe('value');

			await backend.delete('key');
			expect(await backend.get('key')).toBeUndefined();
		});

		it('should throw error when not connected', async () => {
			await backend.disconnect();

			await expect(backend.get('key')).rejects.toThrow(StorageError);
			await expect(backend.set('key', 'value')).rejects.toThrow(StorageError);
			await expect(backend.delete('key')).rejects.toThrow(StorageError);
		});
	});

	describe('TTL Support', () => {
		beforeEach(async () => {
			await backend.connect();
		});

		it('should respect TTL', async () => {
			await backend.set('ttl-key', 'value', 1); // 1 second TTL
			expect(await backend.get('ttl-key')).toBe('value');

			// Wait for expiration
			await new Promise(resolve => setTimeout(resolve, 1100));

			expect(await backend.get('ttl-key')).toBeUndefined();
		});

		it('should store values without TTL indefinitely', async () => {
			await backend.set('no-ttl', 'value');

			// Wait a bit
			await new Promise(resolve => setTimeout(resolve, 100));

			expect(await backend.get('no-ttl')).toBe('value');
		});
	});

	describe('List Operations', () => {
		beforeEach(async () => {
			await backend.connect();
		});

		it('should list keys with prefix', async () => {
			await backend.set('user:1', 'Alice');
			await backend.set('user:2', 'Bob');
			await backend.set('post:1', 'Hello');

			const userKeys = await backend.list('user:');
			expect(userKeys).toHaveLength(2);
			expect(userKeys).toContain('user:1');
			expect(userKeys).toContain('user:2');

			const postKeys = await backend.list('post:');
			expect(postKeys).toHaveLength(1);
			expect(postKeys).toContain('post:1');
		});

		it('should exclude expired keys from list', async () => {
			await backend.set('temp:1', 'value1', 1);
			await backend.set('temp:2', 'value2');

			// Wait for first key to expire
			await new Promise(resolve => setTimeout(resolve, 1100));

			const keys = await backend.list('temp:');
			expect(keys).toHaveLength(1);
			expect(keys).toContain('temp:2');
		});

		it('should append items to lists', async () => {
			await backend.append('log', 'entry1');
			await backend.append('log', 'entry2');
			await backend.append('log', 'entry3');

			const items = await backend.getRange('log', 0, 10);
			expect(items).toEqual(['entry1', 'entry2', 'entry3']);
		});

		it('should get range from lists', async () => {
			for (let i = 0; i < 10; i++) {
				await backend.append('numbers', i);
			}

			expect(await backend.getRange('numbers', 0, 3)).toEqual([0, 1, 2]);
			expect(await backend.getRange('numbers', 5, 3)).toEqual([5, 6, 7]);
			expect(await backend.getRange('numbers', 8, 5)).toEqual([8, 9]);
		});

		it('should handle negative indices in getRange', async () => {
			for (let i = 0; i < 5; i++) {
				await backend.append('items', i);
			}

			// Negative start: -2 means start from 2 positions before the end
			// List is [0, 1, 2, 3, 4], so -2 is index 3
			expect(await backend.getRange('items', -2, 3)).toEqual([3, 4]);

			// More negative index tests
			expect(await backend.getRange('items', -5, 3)).toEqual([0, 1, 2]);
			expect(await backend.getRange('items', -1, 1)).toEqual([4]);
		});

		it('should return empty array for non-existent lists', async () => {
			expect(await backend.getRange('nonexistent', 0, 10)).toEqual([]);
		});
	});

	describe('Data Isolation', () => {
		beforeEach(async () => {
			await backend.connect();
		});

		it('should clone values to prevent reference issues', async () => {
			const obj = { name: 'test', nested: { value: 42 } };
			await backend.set('obj', obj);

			// Modify original
			obj.name = 'modified';
			obj.nested.value = 100;

			// Retrieved value should be unchanged
			const retrieved = await backend.get<typeof obj>('obj');
			expect(retrieved).toEqual({ name: 'test', nested: { value: 42 } });
		});

		it('should clone values in lists', async () => {
			const item = { id: 1, data: 'test' };
			await backend.append('list', item);

			// Modify original
			item.id = 2;
			item.data = 'modified';

			const items = await backend.getRange<typeof item>('list', 0, 1);
			expect(items[0]).toEqual({ id: 1, data: 'test' });
		});
	});

	describe('Statistics and Utilities', () => {
		beforeEach(async () => {
			await backend.connect();
		});

		it('should track statistics', async () => {
			await backend.set('key1', 'value1');
			await backend.set('key2', 'value2');
			await backend.get('key1'); // hit
			await backend.get('nonexistent'); // miss
			await backend.delete('key1');

			const stats = backend.getStats();
			expect(stats.sets).toBe(2);
			expect(stats.hits).toBe(1);
			expect(stats.misses).toBe(1);
			expect(stats.deletes).toBe(1);
		});

		it('should report size correctly', async () => {
			await backend.set('key1', 'value1');
			await backend.set('key2', 'value2');
			await backend.append('list1', 'item');

			const size = backend.getSize();
			expect(size.keys).toBe(2);
			expect(size.lists).toBe(1);
			expect(size.total).toBe(3);
		});

		it('should manually cleanup expired entries', async () => {
			await backend.set('temp1', 'value', 0.1);
			await backend.set('temp2', 'value', 0.1);
			await backend.set('permanent', 'value');

			// Wait for expiration
			await new Promise(resolve => setTimeout(resolve, 150));

			const cleaned = await backend.cleanup();
			expect(cleaned).toBe(2);

			const size = backend.getSize();
			expect(size.keys).toBe(1);
		});
	});

	describe('Error Handling', () => {
		it('should throw on serialization errors', async () => {
			await backend.connect();

			// Create circular reference
			const obj: any = { a: 1 };
			obj.circular = obj;

			await expect(backend.set('circular', obj)).rejects.toThrow(StorageError);
		});
	});
});

