			const persistentList = await newBackend.getRange('persistent-list', 0, 10);
			expect(persistentList).toEqual(['item1', 'item2']);

			await newBackend.disconnect();
		});
	});

	describe('Error Handling', () => {
		it.skip('should throw error when not connected', async () => {
			expect(backend.isConnected()).toBe(false);

			await expect(backend.get('key')).rejects.toThrow(StorageError);
			await expect(backend.set('key', 'value')).rejects.toThrow(StorageError);
			await expect(backend.delete('key')).rejects.toThrow(StorageError);
			await expect(backend.list('prefix')).rejects.toThrow(StorageError);
			await expect(backend.append('key', 'item')).rejects.toThrow(StorageError);
			await expect(backend.getRange('key', 0, 10)).rejects.toThrow(StorageError);
		});

		it.skip('should handle serialization errors gracefully', async () => {
			await backend.connect();

			// Create circular reference (can't be JSON serialized)
			const circular: any = { name: 'circular' };
			circular.self = circular;

			await expect(backend.set('circular', circular)).rejects.toThrow(StorageError);
		});
	});

	describe('Database Information', () => {
		it.skip('should provide database info when connected', async () => {
			await backend.connect();

			const info = backend.getDbInfo();
			expect(info.path).toBe(fullDbPath);

			// Database info might not always be available depending on how data is stored
			// So just check that the fields are either numbers or undefined
			if (info.size !== undefined) {
				expect(typeof info.size).toBe('number');
				expect(info.size).toBeGreaterThan(0);
			}
			if (info.pageCount !== undefined) {
				expect(typeof info.pageCount).toBe('number');
			}
			if (info.pageSize !== undefined) {
				expect(typeof info.pageSize).toBe('number');
			}
		});

		it.skip('should provide basic info when not connected', () => {
			const info = backend.getDbInfo();
			expect(info.path).toBe(fullDbPath);
			expect(info.size).toBeUndefined();
			expect(info.pageCount).toBeUndefined();
			expect(info.pageSize).toBeUndefined();
		});
	});

	describe('Database Maintenance', () => {
		beforeEach(async () => {
			await backend.connect();
		});

		it.skip('should run maintenance without error', async () => {
			// Add some data first
			for (let i = 0; i < 100; i++) {
				await backend.set(`key:${i}`, { data: `value ${i}` });
			}

			await expect(backend.maintenance()).resolves.not.toThrow();
		});

		it.skip('should throw error when maintenance called without connection', async () => {
			await backend.disconnect();
			await expect(backend.maintenance()).rejects.toThrow(StorageError);
		});
	});

	describe('Complex Scenarios', () => {
		beforeEach(async () => {
			await backend.connect();
		});

		it.skip('should handle mixed operations', async () => {
			// Store some key-value pairs
			await backend.set('config:app', { version: '1.0.0' });
			await backend.set('config:debug', true);

			// Create some lists
			await backend.append('logs:error', { level: 'error', message: 'Test error' });
			await backend.append('logs:info', { level: 'info', message: 'Test info' });
			await backend.append('logs:error', { level: 'error', message: 'Another error' });

			// Verify key-value operations
			const configs = await backend.list('config:');
			expect(configs).toContain('config:app');
			expect(configs).toContain('config:debug');

			// Verify list operations
			const errorLogs = await backend.getRange('logs:error', 0, 10);
			expect(errorLogs).toHaveLength(2);

			// Clean up some data
			await backend.delete('config:debug');
			expect(await backend.get('config:debug')).toBeUndefined();
			expect(await backend.get('config:app')).toBeDefined();

			// Lists should still work
			const infoLogs = await backend.getRange('logs:info', 0, 10);
			expect(infoLogs).toHaveLength(1);
		});
	});
});

/** * Cache Backend Interface * * Defines the contract for cache storage implementations. * Cache backends are optimized for fast, ephemeral storage with optional TTL support. * * Implementations can include: * - Redis: Distributed caching with network access * - In-Memory: Fast local caching with no persistence * - Memcached: Distributed memory caching system * * @module storage/backend/cache-backend */
/** * CacheBackend Interface * * Provides a unified API for different cache storage implementations. * All methods are asynchronous to support both local and network-based backends. * * @example * ```typescript * class RedisBackend implements CacheBackend { * async get<T>(key: string): Promise<T | undefined> { * const value = await this.redis.get(key); * return value ? JSON.parse(value) : undefined; * } * // ... other methods * } * ``` */ export interface CacheBackend { // Basic operations
/** * Retrieves a value from the cache by key * * @template T - The type of the cached value * @param key - The cache key to retrieve * @returns The cached value if found, undefined otherwise * * @example * ```typescript * const user = await cache.get<User>('user:123'); * if (!user) { * // Cache miss - fetch from database * } * ``` */ get<T>(key: string): Promise<T | undefined>;
/** * Stores a value in the cache with optional TTL * * @template T - The type of the value to cache * @param key - The cache key * @param value - The value to cache (will be serialized) * @param ttlSeconds - Optional time-to-live in seconds * * @example * ```typescript * // Cache for 1 hour * await cache.set('user:123', userData, 3600); * * // Cache indefinitely * await cache.set('config', configData); * ``` */ set<T>(key: string, value: T, ttlSeconds?: number): Promise<void>;
/** * Removes a value from the cache * * @param key - The cache key to delete * * @example * ```typescript * // Invalidate user cache after update * await cache.delete('user:123'); * ``` */ delete(key: string): Promise<void>;
// Connection management
/** * Establishes connection to the cache backend * * Should be called before performing any operations. * Implementations should handle reconnection logic internally. * * @throws {StorageConnectionError} If connection fails * * @example * ```typescript * const cache = new RedisBackend(config); * await cache.connect(); * // Now ready to use * ``` */ connect(): Promise<void>;
/** * Gracefully closes the connection to the cache backend * * Should clean up resources and close any open connections. * After disconnect, connect() must be called again before use. * * @example * ```typescript * // Clean shutdown * await cache.disconnect(); * ``` */ disconnect(): Promise<void>;
/** * Checks if the backend is currently connected and ready * * @returns true if connected and operational, false otherwise * * @example * ```typescript * if (!cache.isConnected()) { * await cache.connect(); * } * ``` */ isConnected(): boolean;
/** * Returns the backend type identifier * * Useful for logging, monitoring, and conditional logic based on backend type. * * @returns Backend type string (e.g., 'redis', 'memory', 'memcached') * * @example * ```typescript * console.log(`Using ${cache.getBackendType()} for caching`); * ``` */ getBackendType(): string; }

/** * Database Backend Interface * * Defines the contract for persistent storage implementations. * Database backends are optimized for reliable, long-term data storage. * * Implementations can include: * - SQLite: Lightweight, file-based database * - PostgreSQL: Full-featured relational database * - In-Memory: For testing or temporary persistence * * @module storage/backend/database-backend */
/** * DatabaseBackend Interface * * Provides a unified API for different database storage implementations. * Extends basic key-value operations with list operations for collections. * * @example * ```typescript * class SqliteBackend implements DatabaseBackend { * async get<T>(key: string): Promise<T | undefined> { * const row = await this.db.get('SELECT value FROM store WHERE key = ?', key); * return row ? JSON.parse(row.value) : undefined; * } * // ... other methods * } * ``` */ export interface DatabaseBackend { // Basic key-value operations
/** * Retrieves a value from the database by key * * @template T - The type of the stored value * @param key - The storage key to retrieve * @returns The stored value if found, undefined otherwise * * @example * ```typescript * const settings = await db.get<AppSettings>('app:settings'); * ``` */ get<T>(key: string): Promise<T | undefined>;
/** * Stores a value in the database * * Unlike cache, database storage is persistent and doesn't support TTL. * * @template T - The type of the value to store * @param key - The storage key * @param value - The value to store (will be serialized) * * @example * ```typescript * await db.set('user:123', userData); * ``` */ set<T>(key: string, value: T): Promise<void>;
/** * Removes a value from the database * * @param key - The storage key to delete * * @example * ```typescript * await db.delete('user:123'); * ``` */ delete(key: string): Promise<void>;
// Collection operations
/** * Lists all keys matching a prefix * * Useful for finding related data or implementing namespaces. * * @param prefix - The key prefix to search for * @returns Array of keys matching the prefix * * @example * ```typescript * // Get all user keys * const userKeys = await db.list('user:'); * // Returns: ['user:123', 'user:456', ...] * ``` */ list(prefix: string): Promise<string[]>;
// List/Array operations
/** * Appends an item to a list stored at the given key * * Creates the list if it doesn't exist. Useful for logs, history, etc. * * @template T - The type of items in the list * @param key - The storage key for the list * @param item - The item to append * * @example * ```typescript * // Add to user's activity log * await db.append('activity:user:123', { * action: 'login', * timestamp: Date.now() * }); * ``` */ append<T>(key: string, item: T): Promise<void>;
/** * Retrieves a range of items from a list * * Supports pagination through stored lists. * * @template T - The type of items in the list * @param key - The storage key for the list * @param start - Starting index (0-based) * @param count - Number of items to retrieve * @returns Array of items in the specified range * * @example * ```typescript * // Get latest 10 activities * const activities = await db.getRange('activity:user:123', 0, 10); * ``` */ getRange<T>(key: string, start: number, count: number): Promise<T[]>;
// Connection management
/** * Establishes connection to the database backend * * Should be called before performing any operations. * May create database schema/tables if needed. * * @throws {StorageConnectionError} If connection fails * * @example * ```typescript * const db = new SqliteBackend(config); * await db.connect(); * ``` */ connect(): Promise<void>;
/** * Gracefully closes the database connection * * Should ensure all pending writes are completed before closing. * * @example * ```typescript * await db.disconnect(); * ``` */ disconnect(): Promise<void>;
/** * Checks if the backend is currently connected * * @returns true if connected and operational, false otherwise */ isConnected(): boolean;
/** * Returns the backend type identifier * * @returns Backend type string (e.g., 'sqlite', 'postgresql', 'memory') */ getBackendType(): string; }

/**
 * In-Memory Backend Implementation
 *
 * Provides a memory-based storage backend that implements both CacheBackend
 * and DatabaseBackend interfaces. Useful for development, testing, and as
 * a fallback when external backends are unavailable.
 *
 * Features:
 * - TTL support for cache operations
 * - List/collection operations for database functionality
 * - Automatic cleanup of expired entries
 * - No external dependencies
 *
 * @module storage/backend/in-memory
 */

import type { CacheBackend } from './cache-backend.js';
import type { DatabaseBackend } from './database-backend.js';
import { StorageError } from './types.js';
import { BACKEND_TYPES, ERROR_MESSAGES } from '../constants.js';
import { Logger, createLogger } from '../../logger/index.js';

/**
 * Storage entry with optional expiration
 */
interface StorageEntry<T = any> {
	value: T;
	expires?: number; // Timestamp when entry expires (undefined = never expires)
}

/**
 * In-Memory Storage Backend
 *
 * Implements both CacheBackend and DatabaseBackend interfaces using
 * JavaScript Maps for storage. All data is lost when the process exits.
 *
 * @example
 * ```typescript
 * // As cache backend
 * const cache = new InMemoryBackend();
 * await cache.connect();
 * await cache.set('key', value, 300); // 5 minute TTL
 *
 * // As database backend
 * const db = new InMemoryBackend();
 * await db.connect();
 * await db.append('log', { message: 'Hello' });
 * ```
 */
export class InMemoryBackend implements CacheBackend, DatabaseBackend {
	// Storage maps
	private store = new Map<string, StorageEntry>();
	private lists = new Map<string, any[]>();

	// Connection state
	private connected = false;

	// Cleanup interval
	private cleanupInterval: NodeJS.Timeout | undefined;
	private readonly cleanupIntervalMs = 60000; // 1 minute

	// Logger
	private readonly logger: Logger;

	// Statistics
	private stats = {
		hits: 0,
		misses: 0,
		sets: 0,
		deletes: 0,
		expirations: 0,
	};

	constructor() {
		this.logger = createLogger({ level: process.env.LOG_LEVEL || 'info' });
	}

	// Connection Management

	/**
	 * Connect to the in-memory backend
	 *
	 * For in-memory backend, this just sets the connected flag and
	 * starts the cleanup interval for expired entries.
	 */
	async connect(): Promise<void> {
		if (this.connected) {
			this.logger.debug('InMemoryBackend already connected');
			return;
		}

		this.connected = true;
		this.startCleanupInterval();

		this.logger.info('InMemoryBackend connected', {
			cleanupInterval: `${this.cleanupIntervalMs}ms`,
		});
	}

	/**
	 * Disconnect from the in-memory backend
	 *
	 * Clears all data and stops the cleanup interval.
	 */
	async disconnect(): Promise<void> {
		if (!this.connected) {
			return;
		}

		this.stopCleanupInterval();
		this.clear();
		this.connected = false;

		this.logger.info('InMemoryBackend disconnected', {
			stats: this.stats,
		});
	}

	/**
	 * Check if backend is connected
	 */
	isConnected(): boolean {
		return this.connected;
	}

	/**
	 * Get backend type identifier
	 */
	getBackendType(): string {
		return BACKEND_TYPES.IN_MEMORY;
	}

	// Basic Operations (shared by both interfaces)

	/**
	 * Get a value by key
	 *
	 * Checks expiration and removes expired entries.
	 */
	async get<T>(key: string): Promise<T | undefined> {
		this.checkConnection();

		const entry = this.store.get(key);

		if (!entry) {
			this.stats.misses++;
			return undefined;
		}

		// Check expiration
		if (entry.expires && Date.now() > entry.expires) {
			this.store.delete(key);
			this.stats.expirations++;
			this.stats.misses++;
			this.logger.debug('Entry expired', { key });
			return undefined;
		}

		this.stats.hits++;
		return this.cloneValue(entry.value);
	}

	/**
	 * Set a value with optional TTL (for CacheBackend)
	 */
	async set<T>(key: string, value: T, ttlSeconds?: number): Promise<void> {
		this.checkConnection();

		const entry: StorageEntry<T> = {
			value: this.cloneValue(value),
		};

		if (ttlSeconds && ttlSeconds > 0) {
			entry.expires = Date.now() + ttlSeconds * 1000;
		}

		this.store.set(key, entry);
		this.stats.sets++;

		this.logger.debug('Value set', {
			key,
			ttl: ttlSeconds,
			expires: entry.expires,
		});
	}

	/**
	 * Delete a value by key
	 */
	async delete(key: string): Promise<void> {
		this.checkConnection();

		const deleted = this.store.delete(key);
		// Also delete from lists if it exists
		this.lists.delete(key);

		if (deleted) {
			this.stats.deletes++;
		}

		this.logger.debug('Value deleted', { key, deleted });
	}

	// DatabaseBackend specific methods

	/**
	 * List all keys matching a prefix
	 */
	async list(prefix: string): Promise<string[]> {
		this.checkConnection();

		const keys: string[] = [];
		const now = Date.now();

		for (const [key, entry] of Array.from(this.store.entries())) {
			// Skip expired entries
			if (entry.expires && now > entry.expires) {
				continue;
			}

			if (key.startsWith(prefix)) {
				keys.push(key);
			}
		}

		// Also check list keys
		for (const key of Array.from(this.lists.keys())) {
			if (key.startsWith(prefix) && !keys.includes(key)) {
				keys.push(key);
			}
		}

		this.logger.debug('Listed keys', { prefix, count: keys.length });
		return keys;
	}

	/**
	 * Append an item to a list
	 */
	async append<T>(key: string, item: T): Promise<void> {
		this.checkConnection();

		let list = this.lists.get(key);
		if (!list) {
			list = [];
			this.lists.set(key, list);
		}

		list.push(this.cloneValue(item));

		this.logger.debug('Item appended to list', {
			key,
			listSize: list.length,
		});
	}

	/**
	 * Get a range of items from a list
	 */
	async getRange<T>(key: string, start: number, count: number): Promise<T[]> {
		this.checkConnection();

		const list = this.lists.get(key);
		if (!list) {
			return [];
		}

		// Handle negative indices (Python-style)
		if (start < 0) {
			start = Math.max(0, list.length + start);
		}

		const end = Math.min(start + count, list.length);
		const items = list.slice(start, end);

		this.logger.debug('Retrieved range from list', {
			key,
			start,
			count,
			returned: items.length,
			totalSize: list.length,
		});

		return items.map(item => this.cloneValue(item));
	}

	// Helper Methods

	/**
	 * Check if backend is connected
	 * @throws {StorageError} If not connected
	 */
	private checkConnection(): void {
		if (!this.connected) {
			throw new StorageError(
				ERROR_MESSAGES.NOT_CONNECTED,
				'operation',
				new Error('InMemoryBackend is not connected')
			);
		}
	}

	/**
	 * Clone a value to prevent reference issues
	 *
	 * Uses JSON serialization for deep cloning.
	 * This also ensures consistency with network-based backends
	 * that serialize data.
	 */
	private cloneValue<T>(value: T): T {
		try {
			return JSON.parse(JSON.stringify(value));
		} catch (error) {
			throw new StorageError(ERROR_MESSAGES.SERIALIZATION_ERROR, 'clone', error as Error);
		}
	}

	/**
	 * Clear all stored data
	 */
	private clear(): void {
		this.store.clear();
		this.lists.clear();
		this.logger.debug('All data cleared');
	}

	/**
	 * Start the cleanup interval for expired entries
	 */
	private startCleanupInterval(): void {
		if (this.cleanupInterval) {
			return;
		}

		this.cleanupInterval = setInterval(() => {
			this.cleanupExpired();
		}, this.cleanupIntervalMs);

		// Don't prevent process exit
		if (this.cleanupInterval.unref) {
			this.cleanupInterval.unref();
		}
	}

	/**
	 * Stop the cleanup interval
	 */
	private stopCleanupInterval(): void {
		if (this.cleanupInterval) {
			clearInterval(this.cleanupInterval);
			this.cleanupInterval = undefined;
		}
	}

	/**
	 * Remove expired entries from the store
	 */
	private cleanupExpired(): void {
		const now = Date.now();
		let cleaned = 0;

		for (const [key, entry] of Array.from(this.store.entries())) {
			if (entry.expires && now > entry.expires) {
				this.store.delete(key);
				cleaned++;
				this.stats.expirations++;
			}
		}

		if (cleaned > 0) {
			this.logger.debug('Cleaned up expired entries', {
				cleaned,
				remaining: this.store.size,
			});
		}
	}

	// Additional utility methods

	/**
	 * Get storage statistics
	 */
	getStats(): Readonly<typeof this.stats> {
		return { ...this.stats };
	}

	/**
	 * Get current storage size
	 */
	getSize(): { keys: number; lists: number; total: number } {
		return {
			keys: this.store.size,
			lists: this.lists.size,
			total: this.store.size + this.lists.size,
		};
	}

	/**
	 * Manually trigger cleanup of expired entries
	 */
	async cleanup(): Promise<number> {
		const before = this.store.size;
		this.cleanupExpired();
		const after = this.store.size;
		return before - after;
	}
}

/**
 * Storage Backend Exports
 *
 * Central export point for all storage backend implementations.
 *
 * @module storage/backend
 */

// Interface exports
export type { CacheBackend } from './cache-backend.js';
export type { DatabaseBackend } from './database-backend.js';

// Implementation exports
export { InMemoryBackend } from './in-memory.js';
export { RedisBackend } from './redis-backend.js';
export { SqliteBackend } from './sqlite.js';
export { PostgresBackend } from './postgresql.js';

// Type exports
export { StorageError, StorageConnectionError, StorageNotFoundError } from './types.js';

export type {
	StorageBackends,
	BackendConfig,
	InMemoryBackendConfig,
	RedisBackendConfig,
	SqliteBackendConfig,
	PostgresBackendConfig,
} from './types.js';

/**
 * PostgreSQL Database Backend Implementation
 *
 * High-performance PostgreSQL backend for persistent, reliable storage.
 * Supports connection pooling, prepared statements, and comprehensive error handling.
 *
 * Features:
 * - Connection pooling with configurable settings
 * - Prepared statements for SQL injection protection
 * - Schema creation and management
 * - Comprehensive error handling
 * - Performance monitoring and logging
 * - Support for both connection URLs and individual parameters
 *
 * @module storage/backend/postgresql
 */

import { Pool, type PoolConfig } from 'pg';
import type { DatabaseBackend } from './database-backend.js';
import type { PostgresBackendConfig } from '../config.js';
import { StorageError, StorageConnectionError } from './types.js';
import { createLogger, type Logger } from '../../logger/index.js';

/**
 * PostgreSQL Database Backend
 *
 * Implements the DatabaseBackend interface using PostgreSQL as the underlying storage.
 * Provides ACID compliance, strong consistency, and enterprise-grade reliability.
 *
 * Key Features:
 * - Connection pooling for high concurrency
 * - Prepared statements for performance and security
 * - Automatic schema creation and management
 * - Full CRUD operations with atomic transactions
 * - Comprehensive error handling and logging
 *
 * @example
 * ```typescript
 * const backend = new PostgresBackend({
 *   type: 'postgres',
 *   host: 'localhost',
 *   port: 5432,
 *   database: 'myapp',
 *   user: 'postgres',
 *   password: 'secret'
 * });
 *
 * await backend.connect();
 * await backend.set('user:123', userData);
 * const user = await backend.get('user:123');
 * await backend.disconnect();
 * ```
 */
export class PostgresBackend implements DatabaseBackend {
	private pool: Pool | undefined;
	private connected = false;
	private readonly config: PostgresBackendConfig;
	private readonly logger: Logger;

	// Prepared statement cache
	private statements: Map<string, string> = new Map();

	constructor(config: PostgresBackendConfig) {
		this.config = config;
		this.logger = createLogger();
		this.initializeStatements();
	}

	/**
	 * Initialize prepared statement definitions
	 */
	private initializeStatements(): void {
		this.statements.set('get', 'SELECT value FROM cipher_store WHERE key = $1');
		this.statements.set(
			'set',
			`
			INSERT INTO cipher_store (key, value, created_at, updated_at)
			VALUES ($1, $2, $3, $4)
			ON CONFLICT (key) DO UPDATE SET
				value = EXCLUDED.value,
				updated_at = EXCLUDED.updated_at
		`
		);
		this.statements.set('delete', 'DELETE FROM cipher_store WHERE key = $1');
		this.statements.set('list', 'SELECT key FROM cipher_store WHERE key LIKE $1 ORDER BY key');
		this.statements.set(
			'listAppend',
			`
			INSERT INTO cipher_lists (key, value, position, created_at)
			VALUES ($1, $2, COALESCE((SELECT MAX(position) + 1 FROM cipher_lists WHERE key = $1), 0), $3)
		`
		);
		this.statements.set(
			'getRange',
			`
			SELECT value FROM cipher_lists
			WHERE key = $1
			ORDER BY position
			LIMIT $2 OFFSET $3
		`
		);
		this.statements.set('deleteList', 'DELETE FROM cipher_lists WHERE key = $1');
		this.statements.set(
			'updateListMetadata',
			`
			INSERT INTO cipher_list_metadata (key, count, created_at, updated_at)
			VALUES ($1, (SELECT COUNT(*) FROM cipher_lists WHERE key = $1), $2, $3)
			ON CONFLICT (key) DO UPDATE SET
				count = (SELECT COUNT(*) FROM cipher_lists WHERE key = $1),
				updated_at = EXCLUDED.updated_at
		`
		);
	}

	/**
	 * Connect to PostgreSQL database
	 */
	async connect(): Promise<void> {
		if (this.connected) {
			this.logger.debug('PostgreSQL backend already connected');
			return;
		}

		try {
			this.logger.info('Connecting to PostgreSQL database');

			// Build connection configuration
			const poolConfig = this.buildPoolConfig();

			// Create connection pool
			this.pool = new Pool(poolConfig);

			// Test connection
			const client = await this.pool.connect();
			try {
				await client.query('SELECT 1');
				this.logger.debug('PostgreSQL connection test successful');
			} finally {
				client.release();
			}

			// Create tables if they don't exist
			await this.createTables();

			this.connected = true;
			this.logger.info('PostgreSQL backend connected successfully', {
				host: this.config.host || 'localhost',
				database: this.config.database,
				pool: {
					max: poolConfig.max,
					min: poolConfig.min,
				},
			});
		} catch (error) {
			this.logger.error('Failed to connect to PostgreSQL database', {
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageConnectionError(
				'Failed to connect to PostgreSQL database',
				'postgres',
				error as Error
			);
		}
	}

	/**
	 * Disconnect from PostgreSQL database
	 */
	async disconnect(): Promise<void> {
		if (!this.connected || !this.pool) {
			return;
		}

		try {
			await this.pool.end();
			this.connected = false;
			this.pool = undefined;
			this.logger.info('PostgreSQL backend disconnected');
		} catch (error) {
			this.logger.error('Error disconnecting from PostgreSQL', {
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to disconnect from PostgreSQL', 'disconnect', error as Error);
		}
	}

	/**
	 * Check if backend is connected
	 */
	isConnected(): boolean {
		return this.connected && this.pool !== undefined;
	}

	/**
	 * Get backend type identifier
	 */
	getBackendType(): string {
		return 'postgres';
	}

	/**
	 * Get value by key
	 */
	async get<T>(key: string): Promise<T | undefined> {
		this.checkConnection();

		try {
			const result = await this.pool!.query(this.statements.get('get')!, [key]);

			if (result.rows.length === 0) {
				return undefined;
			}

			const serialized = result.rows[0].value;
			return JSON.parse(serialized) as T;
		} catch (error) {
			this.logger.error('Error getting value from PostgreSQL', {
				key,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to get value from PostgreSQL', 'get', error as Error);
		}
	}

	/**
	 * Set key-value pair
	 */
	async set<T>(key: string, value: T): Promise<void> {
		this.checkConnection();

		try {
			const serialized = JSON.stringify(value);
			const now = new Date();
			await this.pool!.query(this.statements.get('set')!, [key, serialized, now, now]);
		} catch (error) {
			this.logger.error('Error setting value in PostgreSQL', {
				key,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to set value in PostgreSQL', 'set', error as Error);
		}
	}

	/**
	 * Delete key
	 */
	async delete(key: string): Promise<void> {
		this.checkConnection();

		try {
			// Use transaction to delete from both key-value store and lists
			const client = await this.pool!.connect();
			try {
				await client.query('BEGIN');
				await client.query(this.statements.get('delete')!, [key]);
				await client.query(this.statements.get('deleteList')!, [key]);
				await client.query('COMMIT');
			} catch (error) {
				await client.query('ROLLBACK');
				throw error;
			} finally {
				client.release();
			}
		} catch (error) {
			this.logger.error('Error deleting value from PostgreSQL', {
				key,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to delete value from PostgreSQL', 'delete', error as Error);
		}
	}

	/**
	 * List keys by prefix
	 */
	async list(prefix: string): Promise<string[]> {
		this.checkConnection();

		try {
			const result = await this.pool!.query(this.statements.get('list')!, [prefix + '%']);
			return result.rows.map(row => row.key);
		} catch (error) {
			this.logger.error('Error listing keys from PostgreSQL', {
				prefix,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to list keys from PostgreSQL', 'list', error as Error);
		}
	}

	/**
	 * Append item to list
	 */
	async append<T>(key: string, item: T): Promise<void> {
		this.checkConnection();

		try {
			const client = await this.pool!.connect();
			try {
				await client.query('BEGIN');

				const serialized = JSON.stringify(item);
				const now = new Date();

				await client.query(this.statements.get('listAppend')!, [key, serialized, now]);
				await client.query(this.statements.get('updateListMetadata')!, [key, now, now]);

				await client.query('COMMIT');
			} catch (error) {
				await client.query('ROLLBACK');
				throw error;
			} finally {
				client.release();
			}
		} catch (error) {
			this.logger.error('Error appending to list in PostgreSQL', {
				key,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to append to list in PostgreSQL', 'append', error as Error);
		}
	}

	/**
	 * Get range of items from list
	 */
	async getRange<T>(key: string, start: number, count: number): Promise<T[]> {
		this.checkConnection();

		try {
			const result = await this.pool!.query(this.statements.get('getRange')!, [key, count, start]);
			return result.rows.map(row => JSON.parse(row.value) as T);
		} catch (error) {
			this.logger.error('Error getting range from PostgreSQL', {
				key,
				start,
				count,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to get range from PostgreSQL', 'getRange', error as Error);
		}
	}

	/**
	 * Get database information
	 */
	getInfo(): Record<string, any> {
		const baseInfo = {
			type: 'postgres',
			connected: this.connected,
		};

		if (!this.connected || !this.pool) {
			return baseInfo;
		}

		return {
			...baseInfo,
			pool: {
				totalCount: this.pool.totalCount,
				idleCount: this.pool.idleCount,
				waitingCount: this.pool.waitingCount,
			},
			config: {
				host: this.config.host || 'localhost',
				port: this.config.port || 5432,
				database: this.config.database,
				ssl: this.config.ssl || false,
			},
		};
	}

	/**
	 * Perform database maintenance
	 */
	async maintenance(): Promise<void> {
		this.checkConnection();

		try {
			this.logger.info('Running PostgreSQL maintenance');

			// Analyze tables for query optimization
			await this.pool!.query('ANALYZE cipher_store');
			await this.pool!.query('ANALYZE cipher_lists');
			await this.pool!.query('ANALYZE cipher_list_metadata');

			this.logger.info('PostgreSQL maintenance completed successfully');
		} catch (error) {
			this.logger.error('Error during PostgreSQL maintenance', {
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('PostgreSQL maintenance failed', 'maintenance', error as Error);
		}
	}

	// Private helper methods

	/**
	 * Build connection pool configuration
	 */
	private buildPoolConfig(): PoolConfig {
		// If URL is provided, use it
		if (this.config.url) {
			return {
				connectionString: this.config.url,
				max: this.config.pool?.max || this.config.maxConnections || 10,
				min: this.config.pool?.min || 2,
				idleTimeoutMillis:
					this.config.pool?.idleTimeoutMillis || this.config.idleTimeoutMillis || 30000,
				connectionTimeoutMillis:
					this.config.pool?.acquireTimeoutMillis || this.config.connectionTimeoutMillis || 10000,
				ssl: this.config.ssl,
			};
		}

		// Build from individual parameters
		return {
			host: this.config.host || 'localhost',
			port: this.config.port || 5432,
			database: this.config.database,
			user: this.config.user,
			password: this.config.password,
			max: this.config.pool?.max || this.config.maxConnections || 10,
			min: this.config.pool?.min || 2,
			idleTimeoutMillis:
				this.config.pool?.idleTimeoutMillis || this.config.idleTimeoutMillis || 30000,
			connectionTimeoutMillis:
				this.config.pool?.acquireTimeoutMillis || this.config.connectionTimeoutMillis || 10000,
			ssl: this.config.ssl,
		};
	}

	/**
	 * Create database tables
	 */
	private async createTables(): Promise<void> {
		if (!this.pool) {
			throw new StorageError('Database not connected', 'createTables');
		}

		// Key-value store table
		await this.pool.query(`
			CREATE TABLE IF NOT EXISTS cipher_store (
				key TEXT PRIMARY KEY,
				value TEXT NOT NULL,
				created_at TIMESTAMP WITH TIME ZONE NOT NULL,
				updated_at TIMESTAMP WITH TIME ZONE NOT NULL
			)
		`);

		// Lists table for list operations
		await this.pool.query(`
			CREATE TABLE IF NOT EXISTS cipher_lists (
				key TEXT NOT NULL,
				value TEXT NOT NULL,
				position INTEGER NOT NULL,
				created_at TIMESTAMP WITH TIME ZONE NOT NULL,
				PRIMARY KEY (key, position)
			)
		`);

		// List metadata table
		await this.pool.query(`
			CREATE TABLE IF NOT EXISTS cipher_list_metadata (
				key TEXT PRIMARY KEY,
				count INTEGER NOT NULL DEFAULT 0,
				created_at TIMESTAMP WITH TIME ZONE NOT NULL,
				updated_at TIMESTAMP WITH TIME ZONE NOT NULL
			)
		`);

		// Create indexes for performance
		await this.pool.query(
			'CREATE INDEX IF NOT EXISTS idx_cipher_store_updated_at ON cipher_store(updated_at)'
		);
		await this.pool.query('CREATE INDEX IF NOT EXISTS idx_cipher_lists_key ON cipher_lists(key)');
		await this.pool.query(
			'CREATE INDEX IF NOT EXISTS idx_cipher_lists_created_at ON cipher_lists(created_at)'
		);

		this.logger.debug('PostgreSQL tables and indexes created');
	}

	/**
	 * Check if backend is connected
	 */
	private checkConnection(): void {
		if (!this.connected || !this.pool) {
			throw new StorageError('PostgreSQL backend not connected', 'checkConnection');
		}
	}
}

/**
 * Redis Backend Implementation
 *
 * Provides a Redis-based cache backend implementation using the ioredis library.
 * Supports all standard cache operations plus additional Redis-specific features.
 *
 * Features:
 * - Automatic JSON serialization/deserialization
 * - Connection pooling and retry logic
 * - TTL support for cache expiration
 * - Batch operations (mget/mset) for performance
 * - List operations for compatibility with DatabaseBackend patterns
 *
 * @module storage/backend/redis-backend
 */

import { Redis } from 'ioredis';
import type { CacheBackend } from './cache-backend.js';
import type { RedisBackendConfig } from '../config.js';

/**
 * Redis Cache Backend
 *
 * Implements the CacheBackend interface using Redis as the storage engine.
 * Handles connection management, error recovery, and data serialization.
 *
 * @example
 * ```typescript
 * const redis = new RedisBackend({
 *   type: 'redis',
 *   host: 'localhost',
 *   port: 6379,
 *   password: 'secret',
 *   database: 0
 * });
 *
 * await redis.connect();
 * await redis.set('key', { data: 'value' }, 3600); // 1 hour TTL
 * ```
 */
export class RedisBackend implements CacheBackend {
	/** The Redis client instance */
	private redis: Redis | null = null;

	/** Connection status flag */
	private connected = false;

	/**
	 * Creates a new Redis backend instance
	 *
	 * @param config - Redis configuration options
	 */
	constructor(private config: RedisBackendConfig) {}

	/**
	 * Establishes connection to Redis server
	 *
	 * Sets up connection with retry logic, error handling, and event listeners.
	 * Configuration supports both individual options and connection URL.
	 *
	 * @throws {StorageConnectionError} If connection fails after retries
	 */
	async connect(): Promise<void> {
		// Skip if already connected
		if (this.connected) return;

		// Create Redis client with configuration
		this.redis = new Redis({
			// Host and port configuration
			...(this.config.host && { host: this.config.host }),
			...(this.config.port && { port: this.config.port }),
			...(this.config.username && { username: this.config.username }),
			...(this.config.password && { password: this.config.password }),

			// Database selection (default: 0)
			db: this.config.database || 0,

			// Force IPv4 to avoid IPv6 issues
			family: 4,

			// Timeout configuration
			...(this.config.connectionTimeoutMillis && {
				connectTimeout: this.config.connectionTimeoutMillis,
			}),
			...(this.config.connectionTimeoutMillis && {
				commandTimeout: this.config.connectionTimeoutMillis,
			}),

			// Retry configuration
			maxRetriesPerRequest: 3,

			// Lazy connect for explicit connection control
			lazyConnect: true,

			// Merge any additional options from config
			...this.config.options,
		});

		// Explicitly connect since lazyConnect is enabled
		let connectionError: Error | null = null;
		this.redis.on('error', err => {
			connectionError = err;
		});

		await new Promise<void>((resolve, reject) => {
			const onReady = () => {
				this.connected = true;
				cleanup();
				resolve();
			};
			const onError = (err: Error) => {
				cleanup();
				reject(new Error('Redis connection failed: ' + err.message));
			};
			const cleanup = () => {
				this.redis?.off('ready', onReady);
				this.redis?.off('error', onError);
			};
			this.redis?.once('ready', onReady);
			this.redis?.once('error', onError);

			// Use configurable timeout or default to 10 seconds
			const timeoutMs = this.config.connectionTimeoutMillis || 10000;
			setTimeout(() => {
				cleanup();
				if (connectionError) {
					reject(new Error('Redis connection failed: ' + connectionError.message));
				} else {
					reject(new Error('Redis connection failed: timeout'));
				}
			}, timeoutMs);

			// Start the connection - this is critical for lazyConnect: true
			this.redis?.connect().catch(onError);
		});
	}

	/**
	 * Gracefully disconnects from Redis
	 *
	 * Ensures all pending commands are completed before closing the connection.
	 */
	async disconnect(): Promise<void> {
		if (this.redis) {
			await this.redis.quit();
			this.redis = null;
		}
		this.connected = false;
	}

	/**
	 * Checks if the Redis connection is active and ready
	 *
	 * @returns true if connected and Redis status is 'ready'
	 */
	isConnected(): boolean {
		return this.connected && this.redis?.status === 'ready';
	}

	/**
	 * Returns the backend type identifier
	 *
	 * @returns 'redis'
	 */
	getBackendType(): string {
		return 'redis';
	}

	// Core operations

	/**
	 * Retrieves and deserializes a value from Redis
	 *
	 * @template T - The expected type of the cached value
	 * @param key - The cache key
	 * @returns The cached value or undefined if not found
	 * @throws {StorageError} If deserialization fails
	 */
	async get<T>(key: string): Promise<T | undefined> {
		this.checkConnection();
		const value = await this.redis!.get(key);
		return value ? JSON.parse(value) : undefined;
	}

	/**
	 * Serializes and stores a value in Redis with optional TTL
	 *
	 * @template T - The type of the value to cache
	 * @param key - The cache key
	 * @param value - The value to cache
	 * @param ttlSeconds - Optional TTL in seconds
	 */
	async set<T>(key: string, value: T, ttlSeconds?: number): Promise<void> {
		this.checkConnection();
		const serialized = JSON.stringify(value);

		if (ttlSeconds) {
			// Use SETEX for atomic set with expiration
			await this.redis!.setex(key, ttlSeconds, serialized);
		} else {
			// Regular SET without expiration
			await this.redis!.set(key, serialized);
		}
	}

	/**
	 * Deletes a key from Redis
	 *
	 * @param key - The cache key to delete
	 */
	async delete(key: string): Promise<void> {
		this.checkConnection();
		await this.redis!.del(key);
	}

	/**
	 * Batch retrieval of multiple keys
	 *
	 * More efficient than multiple individual get() calls.
	 *
	 * @template T - The expected type of the cached values
	 * @param keys - Array of cache keys
	 * @returns Array of values (undefined for missing keys)
	 */
	async mget<T>(keys: string[]): Promise<(T | undefined)[]> {
		this.checkConnection();
		if (keys.length === 0) return [];

		const values = await this.redis!.mget(...keys);
		return values.map(value => (value ? JSON.parse(value) : undefined));
	}

	/**
	 * Batch storage of multiple key-value pairs
	 *
	 * Uses pipeline for atomic batch operation.
	 * Note: Does not support TTL for batch operations.
	 *
	 * @template T - The type of values to cache
	 * @param entries - Array of [key, value] tuples
	 */
	async mset<T>(entries: [string, T][]): Promise<void> {
		this.checkConnection();
		if (entries.length === 0) return;

		// Use pipeline for atomic batch operation
		const pipeline = this.redis!.pipeline();
		for (const [key, value] of entries) {
			pipeline.set(key, JSON.stringify(value));
		}
		await pipeline.exec();
	}

	/**
	 * Checks if a key exists in Redis
	 *
	 * @param key - The cache key to check
	 * @returns true if key exists, false otherwise
	 */
	async exists(key: string): Promise<boolean> {
		this.checkConnection();
		const result = await this.redis!.exists(key);
		return result === 1;
	}

	/**
	 * Sets expiration time for an existing key
	 *
	 * @param key - The cache key
	 * @param ttlSeconds - TTL in seconds
	 */
	async expire(key: string, ttlSeconds: number): Promise<void> {
		this.checkConnection();
		await this.redis!.expire(key, ttlSeconds);
	}

	// Cache-specific operations

	/**
	 * Atomically increments a numeric value
	 *
	 * Creates the key with value 0 if it doesn't exist.
	 *
	 * @param key - The cache key
	 * @param by - Increment amount (default: 1)
	 * @returns The new value after increment
	 */
	async increment(key: string, by: number = 1): Promise<number> {
		this.checkConnection();
		return await this.redis!.incrby(key, by);
	}

	/**
	 * Atomically decrements a numeric value
	 *
	 * @param key - The cache key
	 * @param by - Decrement amount (default: 1)
	 * @returns The new value after decrement
	 */
	async decrement(key: string, by: number = 1): Promise<number> {
		this.checkConnection();
		return await this.redis!.decrby(key, by);
	}

	// List operations (for compatibility with DatabaseBackend patterns)

	/**
	 * Appends an item to a Redis list
	 *
	 * Creates the list if it doesn't exist.
	 * Items are added to the end of the list (RPUSH).
	 *
	 * @template T - The type of list items
	 * @param key - The list key
	 * @param item - The item to append
	 */
	async append<T>(key: string, item: T): Promise<void> {
		this.checkConnection();
		await this.redis!.rpush(key, JSON.stringify(item));
	}

	/**
	 * Retrieves a range of items from a Redis list
	 *
	 * @template T - The type of list items
	 * @param key - The list key
	 * @param start - Starting index (0-based)
	 * @param count - Number of items to retrieve
	 * @returns Array of items in the specified range
	 */
	async getRange<T>(key: string, start: number, count: number): Promise<T[]> {
		this.checkConnection();
		const items = await this.redis!.lrange(key, start, start + count - 1);
		return items.map(item => JSON.parse(item));
	}

	/**
	 * Lists all keys matching a pattern
	 *
	 * Warning: KEYS command can be slow on large databases.
	 * Consider using SCAN for production use.
	 *
	 * @param prefix - Key prefix to search for
	 * @returns Array of matching keys
	 */
	async list(prefix: string): Promise<string[]> {
		this.checkConnection();
		return await this.redis!.keys(`${prefix}*`);
	}

	/**
	 * Validates connection status before operations
	 *
	 * @throws {Error} If not connected or Redis is not ready
	 * @private
	 */
	private checkConnection(): void {
		if (!this.connected || !this.redis || this.redis.status !== 'ready') {
			throw new Error('RedisBackend not connected');
		}
	}

	/**
	 * Flushes the current Redis database
	 *
	 * Warning: This will delete ALL data in the current database.
	 * Use with caution, typically only in development/testing.
	 */
	async flushdb(): Promise<void> {
		this.checkConnection();
		await this.redis!.flushdb();
	}

	/**
	 * Retrieves Redis server information
	 *
	 * Useful for monitoring and debugging.
	 *
	 * @returns Raw Redis INFO output
	 */
	async info(): Promise<string> {
		this.checkConnection();
		return await this.redis!.info();
	}
}

/**
 * SQLite Backend Implementation
 *
 * Provides persistent storage using SQLite database with better-sqlite3.
 * Implements the DatabaseBackend interface with file-based storage.
 *
 * @module storage/backend/sqlite
 */

import * as Database from 'better-sqlite3';
import { mkdir } from 'fs/promises';
import { dirname, join } from 'path';
import { existsSync } from 'fs';
import type { DatabaseBackend } from './database-backend.js';
import type { SqliteBackendConfig } from '../config.js';
import { StorageError, StorageConnectionError } from './types.js';
import { BACKEND_TYPES, ERROR_MESSAGES } from '../constants.js';
import { Logger, createLogger } from '../../logger/index.js';

/**
 * SQLite Database Backend
 *
 * Provides persistent storage using SQLite database.
 * Supports key-value operations and list operations for collections.
 *
 * Features:
 * - File-based storage with automatic directory creation
 * - Prepared statements for performance
 * - Transaction support for batch operations
 * - JSON serialization for complex objects
 * - Efficient list operations with indexes
 *
 * @example
 * ```typescript
 * const sqlite = new SqliteBackend({
 *   type: 'sqlite',
 *   path: './data',
 *   database: 'myapp.db'
 * });
 *
 * await sqlite.connect();
 * await sqlite.set('user:123', { name: 'John', email: 'john@example.com' });
 * ```
 */
export class SqliteBackend implements DatabaseBackend {
	private readonly logger: Logger;
	private connected = false;
	private db: Database.Database | undefined;
	private dbPath: string;

	// Prepared statements for performance
	private statements: {
		get?: Database.Statement;
		set?: Database.Statement;
		delete?: Database.Statement;
		list?: Database.Statement;
		getRange?: Database.Statement;
		listCount?: Database.Statement;
	} = {};

	constructor(private config: SqliteBackendConfig) {
		this.logger = createLogger({ level: process.env.LOG_LEVEL || 'info' });

		// Construct database path
		const dbPath = config.path || './data';
		const dbName = config.database || 'cipher.db';
		this.dbPath = join(dbPath, dbName);

		this.logger.debug('SQLite backend initialized', {
			path: this.dbPath,
			config: { ...config, path: dbPath, database: dbName },
		});
	}

	async connect(): Promise<void> {
		if (this.connected) {
			return;
		}

		try {
			// Ensure directory exists
			const dir = dirname(this.dbPath);
			if (!existsSync(dir)) {
				await mkdir(dir, { recursive: true });
				this.logger.debug('Created database directory', { dir });
			}
			// Open database
			this.db = new (Database as any).default(this.dbPath);
			if (!this.db) {
				throw new Error('Failed to create SQLite database connection');
			}
			this.db.pragma('journal_mode = WAL'); // Enable WAL mode for better performance
			this.db.pragma('synchronous = NORMAL'); // Balanced performance/durability
			this.db.pragma('foreign_keys = ON'); // Enable foreign keys

			// Create tables
			this.createTables();

			// Prepare statements
			this.prepareStatements();

			this.connected = true;
			this.logger.info('SQLite backend connected', { path: this.dbPath });
		} catch (error) {
			this.logger.error('Failed to connect to SQLite database', {
				path: this.dbPath,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageConnectionError(
				`Failed to connect to SQLite database: ${error instanceof Error ? error.message : String(error)}`,
				BACKEND_TYPES.SQLITE,
				error as Error
			);
		}
	}

	async disconnect(): Promise<void> {
		if (!this.connected || !this.db) {
			return;
		}

		try {
			// Close prepared statements
			Object.values(this.statements).forEach(_stmt => {
				try {
					// better-sqlite3 statements don't need explicit finalization
					// They are automatically cleaned up when the database is closed
				} catch (error) {
					this.logger.warn('Error finalizing statement', { error });
				}
			});
			this.statements = {};

			// Close database
			this.db.close();
			this.db = undefined;
			this.connected = false;

			this.logger.info('SQLite backend disconnected');
		} catch (error) {
			this.logger.error('Error disconnecting from SQLite database', {
				error: error instanceof Error ? error.message : String(error),
			});
			throw error;
		}
	}

	isConnected(): boolean {
		return this.connected;
	}

	getBackendType(): string {
		return BACKEND_TYPES.SQLITE;
	}

	// DatabaseBackend implementation

	async get<T>(key: string): Promise<T | undefined> {
		this.checkConnection();

		try {
			const row = this.statements.get!.get(key) as { value: string } | undefined;
			if (!row) {
				return undefined;
			}

			return JSON.parse(row.value) as T;
		} catch (error) {
			this.logger.error('Error getting value from SQLite', {
				key,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to get value from SQLite', 'get', error as Error);
		}
	}

	async set<T>(key: string, value: T): Promise<void> {
		this.checkConnection();

		try {
			const serialized = JSON.stringify(value);
			const now = Date.now();
			this.statements.set!.run(key, serialized, now, now);
		} catch (error) {
			this.logger.error('Error setting value in SQLite', {
				key,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to set value in SQLite', 'set', error as Error);
		}
	}

	async delete(key: string): Promise<void> {
		this.checkConnection();

		try {
			// Delete from both key-value store and lists
			const transaction = this.db!.transaction(() => {
				this.statements.delete!.run(key);
				// Also delete from lists table if it exists as a list
				this.db!.prepare('DELETE FROM lists WHERE key = ?').run(key);
			});

			transaction();
		} catch (error) {
			this.logger.error('Error deleting value from SQLite', {
				key,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to delete value from SQLite', 'delete', error as Error);
		}
	}

	async list(prefix: string): Promise<string[]> {
		this.checkConnection();

		try {
			const rows = this.statements.list!.all(prefix + '%') as { key: string }[];
			return rows.map(row => row.key);
		} catch (error) {
			this.logger.error('Error listing keys from SQLite', {
				prefix,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to list keys from SQLite', 'list', error as Error);
		}
	}

	async append<T>(key: string, item: T): Promise<void> {
		this.checkConnection();

		try {
			const serialized = JSON.stringify(item);
			const now = Date.now();

			// Get current max position for this key
			const maxPosResult = this.db!.prepare(
				'SELECT COALESCE(MAX(position), -1) + 1 as next_pos FROM lists WHERE key = ?'
			).get(key) as { next_pos: number };
			const nextPosition = maxPosResult.next_pos;

			// Insert the new item
			this.db!.prepare(
				'INSERT INTO lists (key, value, position, created_at) VALUES (?, ?, ?, ?)'
			).run(key, serialized, nextPosition, now);
		} catch (error) {
			this.logger.error('Error appending to list in SQLite', {
				key,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to append to list in SQLite', 'append', error as Error);
		}
	}

	async getRange<T>(key: string, start: number, count: number): Promise<T[]> {
		this.checkConnection();

		try {
			const rows = this.statements.getRange!.all(key, count, start) as { value: string }[];
			return rows.map(row => JSON.parse(row.value) as T);
		} catch (error) {
			this.logger.error('Error getting range from SQLite', {
				key,
				start,
				count,
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Failed to get range from SQLite', 'getRange', error as Error);
		}
	}

	// Private helper methods

	private checkConnection(): void {
		if (!this.connected || !this.db) {
			throw new StorageError(ERROR_MESSAGES.NOT_CONNECTED, 'operation');
		}
	}

	private createTables(): void {
		if (!this.db) {
			throw new StorageError('Database not initialized', 'createTables');
		}

		// Key-value store table
		this.db.exec(`
			CREATE TABLE IF NOT EXISTS store (
				key TEXT PRIMARY KEY,
				value TEXT NOT NULL,
				created_at INTEGER NOT NULL,
				updated_at INTEGER NOT NULL
			)
		`);

		// Lists table for list operations
		this.db.exec(`
			CREATE TABLE IF NOT EXISTS lists (
				key TEXT NOT NULL,
				value TEXT NOT NULL,
				position INTEGER NOT NULL,
				created_at INTEGER NOT NULL,
				PRIMARY KEY (key, position)
			)
		`);

		// List metadata table
		this.db.exec(`
			CREATE TABLE IF NOT EXISTS list_metadata (
				key TEXT PRIMARY KEY,
				count INTEGER NOT NULL DEFAULT 0,
				created_at INTEGER NOT NULL,
				updated_at INTEGER NOT NULL
			)
		`);

		// Create indexes for performance
		this.db.exec('CREATE INDEX IF NOT EXISTS idx_store_updated_at ON store(updated_at)');
		this.db.exec('CREATE INDEX IF NOT EXISTS idx_lists_key ON lists(key)');
		this.db.exec('CREATE INDEX IF NOT EXISTS idx_lists_created_at ON lists(created_at)');

		this.logger.debug('SQLite tables and indexes created');
	}

	private prepareStatements(): void {
		if (!this.db) {
			throw new StorageError('Database not initialized', 'prepareStatements');
		}

		this.statements = {
			get: this.db.prepare('SELECT value FROM store WHERE key = ?'),
			set: this.db.prepare(`
				INSERT OR REPLACE INTO store (key, value, created_at, updated_at)
				VALUES (?, ?, ?, ?)
			`),
			delete: this.db.prepare('DELETE FROM store WHERE key = ?'),
			list: this.db.prepare('SELECT key FROM store WHERE key LIKE ? ORDER BY key'),

			// Range query for lists
			getRange: this.db.prepare(`
				SELECT value FROM lists 
				WHERE key = ? 
				ORDER BY position 
				LIMIT ? OFFSET ?
			`),
			listCount: this.db.prepare('SELECT COUNT(*) as count FROM lists WHERE key = ?'),
		};

		this.logger.debug('SQLite prepared statements created');
	}

	/**
	 * Get database file size information
	 */
	getDbInfo(): { path: string; size?: number; pageCount?: number; pageSize?: number } {
		const info: any = { path: this.dbPath };

		if (this.connected && this.db) {
			try {
				const pragmaResult = this.db.pragma('page_count');
				const pageCount = Array.isArray(pragmaResult) ? pragmaResult[0] : pragmaResult;
				const numPageCount = typeof pageCount === 'number' ? pageCount : Number(pageCount);
				if (!isNaN(numPageCount)) {
					info.pageCount = numPageCount;
				}

				const pageSizeResult = this.db.pragma('page_size');
				const pageSize = Array.isArray(pageSizeResult) ? pageSizeResult[0] : pageSizeResult;
				const numPageSize = typeof pageSize === 'number' ? pageSize : Number(pageSize);
				if (!isNaN(numPageSize)) {
					info.pageSize = numPageSize;
				}

				if (info.pageCount && info.pageSize) {
					info.size = info.pageCount * info.pageSize;
				}
			} catch (error) {
				this.logger.warn('Error getting database info', { error });
			}
		}

		return info;
	}

	/**
	 * Run database maintenance operations
	 */
	async maintenance(): Promise<void> {
		this.checkConnection();

		try {
			// Analyze tables for query optimization
			this.db!.exec('ANALYZE');

			// Vacuum to reclaim space (if needed)
			const freeListResult = this.db!.pragma('freelist_count');
			const freePages = Array.isArray(freeListResult) ? freeListResult[0] : freeListResult;
			const freePageCount = typeof freePages === 'number' ? freePages : Number(freePages);

			if (freePageCount > 100) {
				this.db!.exec('VACUUM');
				this.logger.info('Database vacuumed', { freePages: freePageCount });
			}

			this.logger.debug('Database maintenance completed');
		} catch (error) {
			this.logger.error('Error during database maintenance', {
				error: error instanceof Error ? error.message : String(error),
			});
			throw new StorageError('Database maintenance failed', 'maintenance', error as Error);
		}
	}
}

/**
 * Storage Backend Types and Error Classes
 *
 * This module defines the core types and error classes for the storage system.
 * The storage system uses a dual-backend architecture:
 * - Cache Backend: For fast, ephemeral storage (e.g., Redis, in-memory)
 * - Database Backend: For persistent, reliable storage (e.g., SQLite, PostgreSQL)
 *
 * @module storage/backend/types
 */

import type { CacheBackend } from './cache-backend.js';
import type { DatabaseBackend } from './database-backend.js';

// Re-export the backend interfaces for convenience
export type { CacheBackend, DatabaseBackend };

// Re-export configuration types from the config module
export type {
	BackendConfig,
	StorageConfig,
	InMemoryBackendConfig,
	RedisBackendConfig,
	SqliteBackendConfig,
	PostgresBackendConfig,
} from '../config.js';

/**
 * StorageBackends Interface
 *
 * Represents the dual-backend storage system with separate backends for
 * different use cases:
 * - cache: Fast access for temporary data, session storage, etc.
 * - database: Persistent storage for long-term data, user data, etc.
 *
 * @example
 * ```typescript
 * const storage: StorageBackends = {
 *   cache: new RedisBackend(redisConfig),
 *   database: new SqliteBackend(sqliteConfig)
 * };
 * ```
 */
export interface StorageBackends {
	/** Fast, ephemeral storage backend (Redis, Memory) for caching and temporary data */
	cache: CacheBackend;

	/** Persistent, reliable storage backend (PostgreSQL, SQLite, Memory) for long-term data */
	database: DatabaseBackend;
}

/**
 * Base Storage Error Class
 *
 * All storage-related errors extend from this base class.
 * Provides consistent error structure with operation context and optional cause.
 *
 * @example
 * ```typescript
 * throw new StorageError('Failed to save data', 'set', originalError);
 * ```
 */
export class StorageError extends Error {
	constructor(
		message: string,
		/** The operation that failed (e.g., 'get', 'set', 'delete', 'connection') */
		public readonly operation: string,
		/** The underlying error that caused this error, if any */
		public override readonly cause?: Error
	) {
		super(message);
		this.name = 'StorageError';
		this.cause = cause;
	}
}

/**
 * Storage Connection Error
 *
 * Thrown when a storage backend fails to connect or loses connection.
 * Includes the backend type for easier debugging.
 *
 * @example
 * ```typescript
 * throw new StorageConnectionError(
 *   'Failed to connect to Redis',
 *   'redis',
 *   redisError
 * );
 * ```
 */
export class StorageConnectionError extends StorageError {
	constructor(
		override message: string,
		/** The type of backend that failed to connect (e.g., 'redis', 'sqlite') */
		public readonly backendType: string,
		/** The underlying connection error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'connection', cause);
		this.name = 'StorageConnectionError';
	}
}

/**
 * Storage Not Found Error
 *
 * Thrown when attempting to retrieve a key that doesn't exist in storage.
 * Useful for distinguishing between actual errors and missing data.
 *
 * @example
 * ```typescript
 * const value = await cache.get(key);
 * if (!value) {
 *   throw new StorageNotFoundError(`Key not found: ${key}`, key);
 * }
 * ```
 */
export class StorageNotFoundError extends StorageError {
	constructor(
		override message: string,
		/** The key that was not found */
		public readonly key: string,
		/** The underlying error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'not_found', cause);
		this.name = 'StorageNotFoundError';
	}
}

/**
 * Storage Configuration Module
 *
 * Defines the configuration schemas for the storage system using Zod for
 * runtime validation and type safety. Supports multiple backend types
 * with different configuration requirements.
 *
 * The storage system uses a dual-backend architecture:
 * - Cache Backend: For fast, ephemeral storage
 * - Database Backend: For persistent, reliable storage
 *
 * Supported backends:
 * - In-Memory: Fast local storage for development/testing
 * - Redis: Distributed cache for production use
 * - SQLite: Lightweight file-based database
 * - PostgreSQL: Full-featured relational database (planned)
 *
 * @module storage/config
 */

import { z } from 'zod';

/**
 * Base Backend Configuration Schema
 *
 * Common configuration options shared by all backend types.
 * These options control connection pooling and timeout behavior.
 */
const BaseBackendSchema = z.object({
	/** Maximum number of concurrent connections to the backend */
	maxConnections: z.number().int().positive().optional().describe('Maximum connections'),

	/** Time in milliseconds before an idle connection is closed */
	idleTimeoutMillis: z
		.number()
		.int()
		.positive()
		.optional()
		.describe('Idle timeout in milliseconds'),

	/** Time in milliseconds to wait for a connection to be established */
	connectionTimeoutMillis: z
		.number()
		.int()
		.positive()
		.optional()
		.describe('Connection timeout in milliseconds'),

	/** Backend-specific options that vary by implementation */
	options: z.record(z.any()).optional().describe('Backend-specific options'),
});

/**
 * In-Memory Backend Configuration
 *
 * Simple in-memory storage for development and testing.
 * Data is lost when the process exits.
 *
 * @example
 * ```typescript
 * const config: InMemoryBackendConfig = {
 *   type: 'in-memory',
 *   maxConnections: 1,
 *   options: { maxSize: '100mb' }
 * };
 * ```
 */
const InMemoryBackendSchema = BaseBackendSchema.extend({
	type: z.literal('in-memory'),
}).strict();

export type InMemoryBackendConfig = z.infer<typeof InMemoryBackendSchema>;

/**
 * Redis Backend Configuration
 *
 * Configuration for Redis-based cache backend.
 * Supports both direct connection parameters and connection URLs.
 *
 * @example
 * ```typescript
 * // Using connection URL
 * const config: RedisBackendConfig = {
 *   type: 'redis',
 *   url: 'redis://user:pass@localhost:6379/0'
 * };
 *
 * // Using individual parameters
 * const config: RedisBackendConfig = {
 *   type: 'redis',
 *   host: 'localhost',
 *   port: 6379,
 *   password: 'secret',
 *   database: 0
 * };
 * ```
 */
const RedisBackendSchema = BaseBackendSchema.extend({
	type: z.literal('redis'),

	/** Redis connection URL (redis://...) - overrides individual params if provided */
	url: z.string().optional().describe('Redis connection URL (redis://...)'),

	/** Redis server hostname */
	host: z.string().optional().describe('Redis host'),

	/** Redis server port (default: 6379) */
	port: z.number().int().positive().optional().describe('Redis port'),

	/** Redis authentication username */
	username: z.string().optional().describe('Redis username'),

	/** Redis authentication password */
	password: z.string().optional().describe('Redis password'),

	/** Redis database number (0-15, default: 0) */
	database: z.number().int().nonnegative().optional().describe('Redis database number'),
}).strict();

export type RedisBackendConfig = z.infer<typeof RedisBackendSchema>;

/**
 * SQLite Backend Configuration
 *
 * Configuration for SQLite file-based database backend.
 * Supports automatic path resolution if path is not provided.
 *
 * @example
 * ```typescript
 * const config: SqliteBackendConfig = {
 *   type: 'sqlite',
 *   path: './data',           // Directory for database file
 *   database: 'myapp.db',     // Database filename
 *   connectionTimeoutMillis: 5000
 * };
 * ```
 */
const SqliteBackendSchema = BaseBackendSchema.extend({
	type: z.literal('sqlite'),

	/**
	 * SQLite database file path.
	 * If not provided, will auto-detect using the path resolver.
	 */
	path: z
		.string()
		.optional()
		.describe(
			'SQLite database file path (optional, will auto-detect using path resolver if not provided)'
		),

	/** Database filename (default: cipher.db) */
	database: z.string().optional().describe('Database filename (default: cipher.db)'),
}).strict();

export type SqliteBackendConfig = z.infer<typeof SqliteBackendSchema>;

/**
 * PostgreSQL Backend Configuration
 *
 * Configuration for PostgreSQL database backend.
 * Supports both connection URL and individual connection parameters.
 *
 * @example
 * ```typescript
 * // Using connection URL
 * const config: PostgresBackendConfig = {
 *   type: 'postgres',
 *   url: 'postgresql://user:password@localhost:5432/mydb'
 * };
 *
 * // Using individual parameters
 * const config: PostgresBackendConfig = {
 *   type: 'postgres',
 *   host: 'localhost',
 *   port: 5432,
 *   database: 'mydb',
 *   user: 'postgres',
 *   password: 'secret'
 * };
 * ```
 */
const PostgresBackendSchema = BaseBackendSchema.extend({
	type: z.literal('postgres'),

	/** PostgreSQL connection URL (postgresql://...) - overrides individual params if provided */
	url: z.string().optional().describe('PostgreSQL connection URL (postgresql://...)'),

	/** PostgreSQL server hostname */
	host: z.string().optional().describe('PostgreSQL host'),

	/** PostgreSQL server port (default: 5432) */
	port: z.number().int().positive().optional().describe('PostgreSQL port'),

	/** Database name */
	database: z.string().optional().describe('Database name'),

	/** Username for authentication */
	user: z.string().optional().describe('Username'),

	/** Password for authentication */
	password: z.string().optional().describe('Password'),

	/** Enable SSL connection (default: false) */
	ssl: z.boolean().optional().describe('Enable SSL connection'),

	/** Connection pool settings */
	pool: z
		.object({
			/** Minimum number of connections in pool */
			min: z.number().int().nonnegative().optional().describe('Minimum pool size'),
			/** Maximum number of connections in pool */
			max: z.number().int().positive().optional().describe('Maximum pool size'),
			/** Connection idle timeout in ms */
			idleTimeoutMillis: z.number().int().positive().optional().describe('Connection idle timeout'),
			/** Connection acquire timeout in ms */
			acquireTimeoutMillis: z
				.number()
				.int()
				.positive()
				.optional()
				.describe('Connection acquire timeout'),
		})
		.optional()
		.describe('Connection pool settings'),
}).strict();

export type PostgresBackendConfig = z.infer<typeof PostgresBackendSchema>;

/**
 * Backend Configuration Union Schema
 *
 * Discriminated union of all supported backend configurations.
 * Uses the 'type' field to determine which configuration schema to apply.
 *
 * Includes custom validation to ensure Redis backends have required connection info.
 */
const BackendConfigSchema = z
	.discriminatedUnion(
		'type',
		[InMemoryBackendSchema, RedisBackendSchema, SqliteBackendSchema, PostgresBackendSchema],
		{
			errorMap: (issue, ctx) => {
				if (issue.code === z.ZodIssueCode.invalid_union_discriminator) {
					return {
						message: `Invalid backend type. Expected 'in-memory', 'redis', 'sqlite', or 'postgres'.`,
					};
				}
				return { message: ctx.defaultError };
			},
		}
	)
	.describe('Backend configuration for storage system')
	.superRefine((data, ctx) => {
		// Validate Redis backend requirements
		if (data.type === 'redis') {
			// Redis requires either a connection URL or a host
			if (!data.url && !data.host) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					message: "Redis backend requires either 'url' or 'host' to be specified",
					path: ['url'],
				});
			}
		}

		// Validate PostgreSQL backend requirements
		if (data.type === 'postgres') {
			// PostgreSQL requires either a connection URL or host + database
			if (!data.url && (!data.host || !data.database)) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					message:
						"PostgreSQL backend requires either 'url' or both 'host' and 'database' to be specified",
					path: ['url'],
				});
			}
		}
	});

export type BackendConfig = z.infer<typeof BackendConfigSchema>;

/**
 * Storage System Configuration Schema
 *
 * Top-level configuration for the dual-backend storage system.
 * Requires configuration for both cache and database backends.
 *
 * @example
 * ```typescript
 * const storageConfig: StorageConfig = {
 *   cache: {
 *     type: 'redis',
 *     host: 'localhost',
 *     port: 6379
 *   },
 *   database: {
 *     type: 'sqlite',
 *     path: './data',
 *     database: 'app.db'
 *   }
 * };
 * ```
 */
export const StorageSchema = z
	.object({
		/** Cache backend for fast, ephemeral storage (Redis, In-Memory) */
		cache: BackendConfigSchema.describe('Cache backend configuration (fast, ephemeral)'),

		/** Database backend for persistent, reliable storage (SQLite, PostgreSQL) */
		database: BackendConfigSchema.describe('Database backend configuration (persistent, reliable)'),
	})
	.strict()
	.describe('Storage configuration with cache and database backends');

export type StorageConfig = z.infer<typeof StorageSchema>;

/**
 * Storage Module Constants
 *
 * Central location for all storage-related constants including
 * error messages, log prefixes, timeouts, and configuration defaults.
 *
 * @module storage/constants
 */

/**
 * Log prefixes for consistent logging across the storage module
 */
export const LOG_PREFIXES = {
	MANAGER: '[StorageManager]',
	CACHE: '[StorageManager:Cache]',
	DATABASE: '[StorageManager:Database]',
	HEALTH: '[StorageManager:Health]',
	FACTORY: '[StorageFactory]',
	BACKEND: '[StorageBackend]',
} as const;

/**
 * Error messages for the storage module
 */
export const ERROR_MESSAGES = {
	// Connection errors
	CACHE_CONNECTION_FAILED: 'Failed to connect to cache backend',
	DATABASE_CONNECTION_FAILED: 'Failed to connect to database backend',
	ALREADY_CONNECTED: 'Storage manager is already connected',
	NOT_CONNECTED: 'Storage manager is not connected',

	// Backend errors
	BACKEND_NOT_FOUND: 'Storage backend not found',
	INVALID_BACKEND_TYPE: 'Invalid backend type specified',
	MODULE_LOAD_FAILED: 'Failed to load backend module',

	// Operation errors
	HEALTH_CHECK_FAILED: 'Health check failed',
	OPERATION_TIMEOUT: 'Storage operation timed out',
	SERIALIZATION_ERROR: 'Failed to serialize/deserialize data',

	// Configuration errors
	INVALID_CONFIG: 'Invalid storage configuration',
	MISSING_REQUIRED_CONFIG: 'Missing required configuration',
} as const;

/**
 * Storage operation timeouts (in milliseconds)
 */
export const TIMEOUTS = {
	CONNECTION: 10000, // 10 seconds
	HEALTH_CHECK: 5000, // 5 seconds
	OPERATION: 30000, // 30 seconds
	SHUTDOWN: 5000, // 5 seconds
} as const;

/**
 * Health check constants
 */
export const HEALTH_CHECK = {
	KEY: 'storage_manager_health_check',
	VALUE: 'ok',
	TTL_SECONDS: 10,
} as const;

/**
 * Backend type identifiers
 */
export const BACKEND_TYPES = {
	// Cache backends
	REDIS: 'redis',
	MEMCACHED: 'memcached',
	IN_MEMORY: 'in-memory',

	// Database backends
	SQLITE: 'sqlite',
	POSTGRES: 'postgres',
	MYSQL: 'mysql',
} as const;

/**
 * Default configuration values
 */
export const DEFAULTS = {
	MAX_RETRIES: 3,
	RETRY_DELAY: 1000, // 1 second
	CACHE_TTL: 3600, // 1 hour in seconds
	MAX_CONNECTIONS: 10,
	IDLE_TIMEOUT: 30000, // 30 seconds
} as const;

/**
 * Storage metrics event names
 */
export const METRICS_EVENTS = {
	CONNECTION_ATTEMPT: 'storage.connection.attempt',
	CONNECTION_SUCCESS: 'storage.connection.success',
	CONNECTION_FAILURE: 'storage.connection.failure',
	OPERATION_START: 'storage.operation.start',
	OPERATION_SUCCESS: 'storage.operation.success',
	OPERATION_FAILURE: 'storage.operation.failure',
	HEALTH_CHECK: 'storage.health.check',
	FALLBACK_USED: 'storage.fallback.used',
} as const;

/**
 * Storage Factory
 *
 * Factory functions for creating and initializing the storage system.
 * Provides a simplified API for common storage setup patterns.
 *
 * @module storage/factory
 */

import { StorageManager } from './manager.js';
import type { StorageConfig, StorageBackends } from './types.js';
import { createLogger } from '../logger/index.js';
import { LOG_PREFIXES } from './constants.js';
import { env } from '../env.js';

/**
 * Factory result containing both the manager and backends
 */
export interface StorageFactory {
	/** The storage manager instance for lifecycle control */
	manager: StorageManager;
	/** The connected storage backends ready for use */
	backends: StorageBackends;
}

/**
 * Creates and connects storage backends
 *
 * This is the primary factory function for initializing the storage system.
 * It creates a StorageManager, connects to the configured backends, and
 * returns both the manager and the connected backends.
 *
 * @param config - Storage configuration
 * @returns Promise resolving to manager and connected backends
 * @throws {StorageConnectionError} If connection fails and no fallback is available
 *
 * @example
 * ```typescript
 * // Basic usage
 * const { manager, backends } = await createStorageBackends({
 *   cache: { type: 'redis', host: 'localhost' },
 *   database: { type: 'sqlite', path: './data' }
 * });
 *
 * // Use the backends
 * await backends.cache.set('key', 'value', 300);
 * await backends.database.set('user:1', userData);
 *
 * // Cleanup when done
 * await manager.disconnect();
 * ```
 *
 * @example
 * ```typescript
 * // Development configuration
 * const { manager, backends } = await createStorageBackends({
 *   cache: { type: 'in-memory' },
 *   database: { type: 'in-memory' }
 * });
 * ```
 */
export async function createStorageBackends(config: StorageConfig): Promise<StorageFactory> {
	const logger = createLogger({ level: env.CIPHER_LOG_LEVEL });

	logger.debug(`${LOG_PREFIXES.FACTORY} Creating storage system`, {
		cacheType: config.cache.type,
		databaseType: config.database.type,
	});

	// Create manager
	const manager = new StorageManager(config);

	try {
		// Connect to backends
		const backends = await manager.connect();

		logger.info(`${LOG_PREFIXES.FACTORY} Storage system created successfully`, {
			cache: manager.getInfo().backends.cache,
			database: manager.getInfo().backends.database,
		});

		return { manager, backends };
	} catch (error) {
		// If connection fails, ensure cleanup
		await manager.disconnect().catch(() => {
			// Ignore disconnect errors during cleanup
		});

		logger.error(`${LOG_PREFIXES.FACTORY} Failed to create storage system`, {
			error: error instanceof Error ? error.message : String(error),
		});

		throw error;
	}
}

/**
 * Creates storage backends with default configuration
 *
 * Convenience function that creates storage with in-memory backends.
 * Useful for testing or development environments.
 *
 * @returns Promise resolving to manager and connected backends
 *
 * @example
 * ```typescript
 * const { manager, backends } = await createDefaultStorage();
 * // Uses in-memory backends for both cache and database
 * ```
 */
export async function createDefaultStorage(): Promise<StorageFactory> {
	return createStorageBackends({
		cache: { type: 'in-memory' },
		database: { type: 'in-memory' },
	});
}

/**
 * Creates storage backends from environment variables
 *
 * Reads storage configuration from environment variables and creates
 * the storage system. Falls back to in-memory if not configured.
 *
 * Environment variables:
 * - STORAGE_CACHE_TYPE: Cache backend type (redis, in-memory)
 * - STORAGE_CACHE_HOST: Redis host (if using Redis)
 * - STORAGE_CACHE_PORT: Redis port (if using Redis)
 * - STORAGE_CACHE_USERNAME: Redis username (if using Redis)
 * - STORAGE_CACHE_PASSWORD: Redis password (if using Redis)
 * - STORAGE_DATABASE_TYPE: Database backend type (sqlite, in-memory)
 * - STORAGE_DATABASE_PATH: SQLite database path (if using SQLite)
 *
 * @returns Promise resolving to manager and connected backends
 *
 * @example
 * ```typescript
 * // Set environment variables
 * process.env.STORAGE_CACHE_TYPE = 'redis';
 * process.env.STORAGE_CACHE_HOST = 'localhost';
 *
 * const { manager, backends } = await createStorageFromEnv();
 * ```
 */
export async function createStorageFromEnv(): Promise<StorageFactory> {
	const logger = createLogger({ level: env.CIPHER_LOG_LEVEL });

	// Build cache configuration from environment
	const cacheType = env.STORAGE_CACHE_TYPE;
	let cacheConfig: StorageConfig['cache'];

	if (cacheType === 'redis') {
		const port = env.STORAGE_CACHE_PORT || 6379;
		const database = env.STORAGE_CACHE_DATABASE;

		cacheConfig = {
			type: 'redis',
			host: env.STORAGE_CACHE_HOST || 'localhost',
			port: port,
			username: env.STORAGE_CACHE_USERNAME,
			password: env.STORAGE_CACHE_PASSWORD,
			database: database,
		};
	} else {
		cacheConfig = { type: 'in-memory' };
	}

	// Build database configuration from environment
	const dbType = env.STORAGE_DATABASE_TYPE;
	let dbConfig: StorageConfig['database'];

	if (dbType === 'sqlite') {
		dbConfig = {
			type: 'sqlite',
			path: env.STORAGE_DATABASE_PATH,
			database: env.STORAGE_DATABASE_NAME,
		};
	} else {
		// Use in-memory for any unsupported types or when not specified
		if (dbType && dbType !== 'in-memory') {
			logger.warn(
				`${LOG_PREFIXES.FACTORY} Database type '${dbType}' not yet supported, using in-memory`
			);
		}
		dbConfig = { type: 'in-memory' };
	}

	logger.info(`${LOG_PREFIXES.FACTORY} Creating storage from environment`, {
		cacheType,
		databaseType: dbType,
	});

	return createStorageBackends({
		cache: cacheConfig,
		database: dbConfig,
	});
}

/**
 * Type guard to check if an object is a StorageFactory
 *
 * @param obj - Object to check
 * @returns true if the object has manager and backends properties
 */
export function isStorageFactory(obj: unknown): obj is StorageFactory {
	return (
		typeof obj === 'object' &&
		obj !== null &&
		'manager' in obj &&
		'backends' in obj &&
		obj.manager instanceof StorageManager
	);
}

/**
 * Storage Module Public API
 *
 * This module provides a flexible dual-backend storage system with:
 * - Cache backend for fast, ephemeral storage
 * - Database backend for persistent, reliable storage
 *
 * Features:
 * - Lazy loading of external backends (Redis, SQLite, etc.)
 * - Graceful fallback to in-memory storage
 * - Health monitoring and connection management
 * - Type-safe configuration with runtime validation
 *
 * @module storage
 */

// Core exports
export { StorageManager } from './manager.js';
export type { HealthCheckResult, StorageInfo } from './manager.js';

// Type exports
export type {
	CacheBackend,
	DatabaseBackend,
	StorageBackends,
	BackendConfig,
	StorageConfig,
} from './types.js';

// Configuration exports
export { StorageSchema } from './config.js';
export type {
	InMemoryBackendConfig,
	RedisBackendConfig,
	SqliteBackendConfig,
	PostgresBackendConfig,
} from './config.js';

// Error exports
export { StorageError, StorageConnectionError, StorageNotFoundError } from './backend/types.js';

// Constants exports (for external use if needed)
export {
	LOG_PREFIXES,
	ERROR_MESSAGES,
	BACKEND_TYPES,
	TIMEOUTS,
	HEALTH_CHECK,
	DEFAULTS,
} from './constants.js';

// Backend implementations
export { InMemoryBackend } from './backend/in-memory.js';
// Redis and SQLite backends will be loaded lazily

// Memory History Service exports
export {
	MemoryHistoryStorageService,
	createMemoryHistoryService,
	createMemoryHistoryEntry,
} from './memory-history/index.js';
export type {
	MemoryHistoryEntry,
	MemoryHistoryService,
	HistoryFilters,
	QueryOptions,
	OperationStats,
	MemoryOperation,
} from './memory-history/index.js';

// Factory functions
export {
	createStorageBackends,
	createDefaultStorage,
	createStorageFromEnv,
	isStorageFactory,
	type StorageFactory,
} from './factory.js';

/**
 * Storage Manager Implementation
 *
 * Orchestrates the dual-backend storage system with cache and database backends.
 * Provides lazy loading, graceful fallbacks, and connection management.
 *
 * @module storage/manager
 */

import type { CacheBackend, DatabaseBackend, StorageBackends, StorageConfig } from './types.js';
import { StorageSchema } from './config.js';
import { Logger, createLogger } from '../logger/index.js';
import {
	LOG_PREFIXES,
	ERROR_MESSAGES,
	TIMEOUTS,
	HEALTH_CHECK,
	BACKEND_TYPES,
} from './constants.js';

/**
 * Health check result for storage backends
 */
export interface HealthCheckResult {
	cache: boolean;
	database: boolean;
	overall: boolean;
	details?: {
		cache?: { status: string; latency?: number; error?: string };
		database?: { status: string; latency?: number; error?: string };
	};
}

/**
 * Storage system information
 */
export interface StorageInfo {
	connected: boolean;
	backends: {
		cache: {
			type: string;
			connected: boolean;
			fallback: boolean;
		};
		database: {
			type: string;
			connected: boolean;
			fallback: boolean;
		};
	};
	connectionAttempts: number;
	lastError: string | undefined;
}

/**
 * Storage Manager
 *
 * Manages the lifecycle of storage backends with lazy loading and fallback support.
 * Follows the factory pattern with graceful degradation to in-memory storage.
 *
 * @example
 * ```typescript
 * const manager = new StorageManager(config);
 * const { cache, database } = await manager.connect();
 *
 * // Use backends
 * await cache.set('key', value, 300);
 * await database.set('user:123', userData);
 *
 * // Cleanup
 * await manager.disconnect();
 * ```
 */
export class StorageManager {
	// Core state
	private cache: CacheBackend | undefined;
	private database: DatabaseBackend | undefined;
	private connected = false;
	private readonly config: StorageConfig;
	private readonly logger: Logger;

	// Connection tracking
	private connectionAttempts = 0;
	private lastConnectionError?: Error;

	// Backend metadata
	private cacheMetadata = {
		type: 'unknown',
		isFallback: false,
		connectionTime: 0,
	};

	private databaseMetadata = {
		type: 'unknown',
		isFallback: false,
		connectionTime: 0,
	};

	// Lazy loading module references (static to share across instances)
	private static redisModule?: any;
	private static sqliteModule?: any;
	private static postgresModule?: any;

	// Health check configuration
	private readonly healthCheckKey = HEALTH_CHECK.KEY;
	private readonly healthCheckTimeout = TIMEOUTS.HEALTH_CHECK;

	/**
	 * Creates a new StorageManager instance
	 *
	 * @param config - Storage configuration with cache and database backend configs
	 * @throws {Error} If configuration is invalid
	 */
	constructor(config: StorageConfig) {
		// Validate configuration using Zod schema
		const validationResult = StorageSchema.safeParse(config);
		if (!validationResult.success) {
			throw new Error(
				`${ERROR_MESSAGES.INVALID_CONFIG}: ${validationResult.error.errors
					.map(e => `${e.path.join('.')}: ${e.message}`)
					.join(', ')}`
			);
		}

		this.config = validationResult.data;
		this.logger = createLogger({
			level: process.env.LOG_LEVEL || 'info',
		});

		this.logger.info(`${LOG_PREFIXES.MANAGER} Initialized with configuration`, {
			cacheType: this.config.cache.type,
			databaseType: this.config.database.type,
		});
	}

	/**
	 * Get the current storage configuration
	 *
	 * @returns The storage configuration
	 */
	public getConfig(): Readonly<StorageConfig> {
		return this.config;
	}

	/**
	 * Get information about the storage system
	 *
	 * @returns Storage system information including connection status and backend types
	 */
	public getInfo(): StorageInfo {
		return {
			connected: this.connected,
			backends: {
				cache: {
					type: this.cacheMetadata.type,
					connected: this.cache?.isConnected() ?? false,
					fallback: this.cacheMetadata.isFallback,
				},
				database: {
					type: this.databaseMetadata.type,
					connected: this.database?.isConnected() ?? false,
					fallback: this.databaseMetadata.isFallback,
				},
			},
			connectionAttempts: this.connectionAttempts,
			lastError: this.lastConnectionError?.message,
		};
	}

	/**
	 * Get the current storage backends if connected
	 *
	 * @returns The storage backends or null if not connected
	 */
	public getBackends(): StorageBackends | null {
		if (!this.connected || !this.cache || !this.database) {
			return null;
		}

		return {
			cache: this.cache,
			database: this.database,
		};
	}

	/**
	 * Check if the storage manager is connected
	 *
	 * @returns true if both backends are connected
	 */
	public isConnected(): boolean {
		return (
			this.connected && this.cache?.isConnected() === true && this.database?.isConnected() === true
		);
	}

	// Placeholder methods for next phases

	/**
	 * Connect to storage backends
	 *
	 * @returns The connected storage backends
	 * @throws {StorageConnectionError} If strict backends fail to connect
	 */
	public async connect(): Promise<StorageBackends> {
		// Check if already connected
		if (this.connected) {
			this.logger.debug(`${LOG_PREFIXES.MANAGER} Already connected`, {
				cacheType: this.cacheMetadata.type,
				databaseType: this.databaseMetadata.type,
			});

			return {
				cache: this.cache!,
				database: this.database!,
			};
		}

		this.connectionAttempts++;
		this.logger.info(
			`${LOG_PREFIXES.MANAGER} Starting connection attempt ${this.connectionAttempts}`
		);

		try {
			// Create and connect cache backend
			const cacheStartTime = Date.now();
			try {
				this.cache = await this.createCacheBackend();
				await this.cache.connect();
				this.cacheMetadata.connectionTime = Date.now() - cacheStartTime;

				this.logger.info(`${LOG_PREFIXES.CACHE} Connected successfully`, {
					type: this.cacheMetadata.type,
					isFallback: this.cacheMetadata.isFallback,
					connectionTime: `${this.cacheMetadata.connectionTime}ms`,
				});
			} catch (cacheError) {
				// If the configured backend fails, try fallback to in-memory
				this.logger.warn(`${LOG_PREFIXES.CACHE} Connection failed, attempting fallback`, {
					error: cacheError instanceof Error ? cacheError.message : String(cacheError),
					originalType: this.config.cache.type,
				});

				if (this.config.cache.type !== BACKEND_TYPES.IN_MEMORY) {
					const { InMemoryBackend } = await import('./backend/in-memory.js');
					this.cache = new InMemoryBackend();
					await this.cache.connect();
					this.cacheMetadata.type = BACKEND_TYPES.IN_MEMORY;
					this.cacheMetadata.isFallback = true;
					this.cacheMetadata.connectionTime = Date.now() - cacheStartTime;

					this.logger.info(`${LOG_PREFIXES.CACHE} Connected to fallback backend`, {
						type: this.cacheMetadata.type,
						originalType: this.config.cache.type,
					});
				} else {
					throw cacheError; // Re-throw if already using in-memory
				}
			}

			// Create and connect database backend
			const dbStartTime = Date.now();
			try {
				this.database = await this.createDatabaseBackend();
				await this.database.connect();
				this.databaseMetadata.connectionTime = Date.now() - dbStartTime;

				this.logger.info(`${LOG_PREFIXES.DATABASE} Connected successfully`, {
					type: this.databaseMetadata.type,
					isFallback: this.databaseMetadata.isFallback,
					connectionTime: `${this.databaseMetadata.connectionTime}ms`,
				});
			} catch (err) {
				this.logger.error('Failed to connect to database backend', {
					error: err instanceof Error ? err.message : String(err),
					type: this.config.database.type,
					stack: err instanceof Error ? err.stack : undefined,
				});

				// CRITICAL FIX: Enhanced fallback logic with retry mechanism
				if (this.config.database.type !== BACKEND_TYPES.IN_MEMORY) {
					this.logger.warn(
						`${LOG_PREFIXES.DATABASE} Primary backend failed, attempting fallback to in-memory`,
						{
							error: err instanceof Error ? err.message : String(err),
							originalType: this.config.database.type,
						}
					);

					try {
						const { InMemoryBackend } = await import('./backend/in-memory.js');
						this.database = new InMemoryBackend();
						await this.database.connect();
						this.databaseMetadata.type = BACKEND_TYPES.IN_MEMORY;
						this.databaseMetadata.isFallback = true;
						this.databaseMetadata.connectionTime = Date.now() - dbStartTime;

						this.logger.info(
							`${LOG_PREFIXES.DATABASE} Successfully connected to fallback backend`,
							{
								type: this.databaseMetadata.type,
								originalType: this.config.database.type,
								connectionTime: `${this.databaseMetadata.connectionTime}ms`,
							}
						);
					} catch (fallbackError) {
						this.logger.error(`${LOG_PREFIXES.DATABASE} Fallback to in-memory also failed`, {
							error: fallbackError instanceof Error ? fallbackError.message : String(fallbackError),
							originalError: err instanceof Error ? err.message : String(err),
						});
						throw new Error(
							`Database connection failed: Primary (${this.config.database.type}) and fallback (in-memory) both failed`
						);
					}
				} else {
					// Already using in-memory, can't fallback further
					this.logger.error(
						`${LOG_PREFIXES.DATABASE} In-memory backend failed, no fallback available`
					);
					throw err;
				}
			}

			this.connected = true;

			this.logger.info(`${LOG_PREFIXES.MANAGER} Storage system connected`, {
				cacheBackend: this.cacheMetadata.type,
				databaseBackend: this.databaseMetadata.type,
				totalConnectionTime: `${this.cacheMetadata.connectionTime + this.databaseMetadata.connectionTime}ms`,
			});

			return {
				cache: this.cache!,
				database: this.database!,
			};
		} catch (error) {
			// Store error for reporting
			this.lastConnectionError = error as Error;

			// Disconnect any successfully connected backends
			if (this.cache?.isConnected()) {
				await this.cache.disconnect().catch(err =>
					this.logger.error(`${LOG_PREFIXES.CACHE} Error during cleanup disconnect`, {
						error: err,
					})
				);
			}

			if (this.database?.isConnected()) {
				await this.database.disconnect().catch(err =>
					this.logger.error(`${LOG_PREFIXES.DATABASE} Error during cleanup disconnect`, {
						error: err,
					})
				);
			}

			// Reset state
			this.cache = undefined;
			this.database = undefined;
			this.connected = false;

			throw error;
		}
	}

	/**
	 * Disconnect from all storage backends
	 */
	public async disconnect(): Promise<void> {
		if (!this.connected) {
			this.logger.debug(`${LOG_PREFIXES.MANAGER} Already disconnected`);
			return;
		}

		this.logger.info(`${LOG_PREFIXES.MANAGER} Disconnecting storage backends`);

		const disconnectPromises: Promise<void>[] = [];

		// Disconnect cache backend
		if (this.cache?.isConnected()) {
			disconnectPromises.push(
				this.cache
					.disconnect()
					.then(() => {
						this.logger.info(`${LOG_PREFIXES.CACHE} Disconnected successfully`);
					})
					.catch(error => {
						this.logger.error(`${LOG_PREFIXES.CACHE} Disconnect error`, { error });
						throw error;
					})
			);
		}

		// Disconnect database backend
		if (this.database?.isConnected()) {
			disconnectPromises.push(
				this.database
					.disconnect()
					.then(() => {
						this.logger.info(`${LOG_PREFIXES.DATABASE} Disconnected successfully`);
					})
					.catch(error => {
						this.logger.error(`${LOG_PREFIXES.DATABASE} Disconnect error`, { error });
						throw error;
					})
			);
		}

		// Wait for all disconnects with timeout
		try {
			await Promise.race([
				Promise.all(disconnectPromises),
				new Promise((_, reject) =>
					setTimeout(() => reject(new Error('Disconnect timeout')), TIMEOUTS.SHUTDOWN)
				),
			]);
		} finally {
			// Always clean up state
			this.cache = undefined;
			this.database = undefined;
			this.connected = false;

			// Reset metadata
			this.cacheMetadata = {
				type: 'unknown',
				isFallback: false,
				connectionTime: 0,
			};

			this.databaseMetadata = {
				type: 'unknown',
				isFallback: false,
				connectionTime: 0,
			};

			this.logger.info(`${LOG_PREFIXES.MANAGER} Storage system disconnected`);
		}
	}

	/**
	 * Perform health check on all backends
	 *
	 * @returns Health check results for each backend
	 */
	public async healthCheck(): Promise<HealthCheckResult> {
		// Implementation in Phase 5
		throw new Error('Not implemented yet - Phase 5');
	}

	// Private helper methods

	/**
	 * Create cache backend based on configuration
	 */
	private async createCacheBackend(): Promise<CacheBackend> {
		const config = this.config.cache;

		this.logger.debug(`${LOG_PREFIXES.CACHE} Creating backend`, { type: config.type });

		switch (config.type) {
			case BACKEND_TYPES.REDIS: {
				try {
					// Lazy load Redis module
					if (!StorageManager.redisModule) {
						this.logger.debug(`${LOG_PREFIXES.CACHE} Lazy loading Redis module`);
						const { RedisBackend } = await import('./backend/redis-backend.js');
						StorageManager.redisModule = RedisBackend;
					}

					const RedisBackend = StorageManager.redisModule;
					this.cacheMetadata.type = BACKEND_TYPES.REDIS;
					this.cacheMetadata.isFallback = false;

					return new RedisBackend(config);
				} catch (error) {
					this.logger.debug(`${LOG_PREFIXES.CACHE} Failed to create Redis backend`, {
						error: error instanceof Error ? error.message : String(error),
					});
					throw error; // Let connection handler deal with fallback
				}
			}

			case BACKEND_TYPES.IN_MEMORY:
			default: {
				// Use in-memory backend
				const { InMemoryBackend } = await import('./backend/in-memory.js');
				this.cacheMetadata.type = BACKEND_TYPES.IN_MEMORY;
				this.cacheMetadata.isFallback = false;

				return new InMemoryBackend();
			}
		}
	}

	/**
	 * Create database backend based on configuration
	 */
	private async createDatabaseBackend(): Promise<DatabaseBackend> {
		const config = this.config.database;

		this.logger.debug(`${LOG_PREFIXES.DATABASE} Creating backend`, { type: config.type });

		switch (config.type) {
			case BACKEND_TYPES.SQLITE: {
				try {
					// Lazy load SQLite module
					if (!StorageManager.sqliteModule) {
						this.logger.debug(`${LOG_PREFIXES.DATABASE} Lazy loading SQLite module`);
						const { SqliteBackend } = await import('./backend/sqlite.js');
						StorageManager.sqliteModule = SqliteBackend;
					}

					const SqliteBackend = StorageManager.sqliteModule;
					this.databaseMetadata.type = BACKEND_TYPES.SQLITE;
					this.databaseMetadata.isFallback = false;

					return new SqliteBackend(config);
				} catch (error) {
					this.logger.debug(`${LOG_PREFIXES.DATABASE} Failed to create SQLite backend`, {
						error: error instanceof Error ? error.message : String(error),
					});
					throw error; // Let connection handler deal with fallback
				}
			}

			case BACKEND_TYPES.POSTGRES: {
				try {
					// Lazy load PostgreSQL module
					if (!StorageManager.postgresModule) {
						this.logger.debug(`${LOG_PREFIXES.DATABASE} Lazy loading PostgreSQL module`);
						const { PostgresBackend } = await import('./backend/postgresql.js');
						StorageManager.postgresModule = PostgresBackend;
					}

					const PostgresBackend = StorageManager.postgresModule;
					this.databaseMetadata.type = BACKEND_TYPES.POSTGRES;
					this.databaseMetadata.isFallback = false;

					return new PostgresBackend(config);
				} catch (error) {
					this.logger.debug(`${LOG_PREFIXES.DATABASE} Failed to create PostgreSQL backend`, {
						error: error instanceof Error ? error.message : String(error),
					});
					throw error; // Let connection handler deal with fallback
				}
			}

			case BACKEND_TYPES.IN_MEMORY:
			default: {
				// Use in-memory backend
				const { InMemoryBackend } = await import('./backend/in-memory.js');
				this.databaseMetadata.type = BACKEND_TYPES.IN_MEMORY;
				this.databaseMetadata.isFallback = false;

				return new InMemoryBackend();
			}
		}
	}
}

