// Mock environment variables
vi.mock('../../env.js', () => ({
	env: {
		CIPHER_LOG_LEVEL: 'debug',
		VECTOR_STORE_URL: 'http://localhost:19530',
		VECTOR_STORE_USERNAME: 'test-user',
		VECTOR_STORE_PASSWORD: 'test-pass',
	},
}));

describe('MilvusBackend Connection Pool Integration', () => {
	let backend1: MilvusBackend;
	let backend2: MilvusBackend;
	let config1: MilvusBackendConfig;
	let config2: MilvusBackendConfig;

	beforeEach(async () => {
		// Clear connection pool
		const pool = getMilvusConnectionPool();
		await pool.shutdown();
		(pool.constructor as any).instance = null;

		// Reset all mocks
		vi.clearAllMocks();

		// Create test configurations
		config1 = {
			type: 'milvus',
			url: 'http://localhost:19530',
			username: 'user1',
			password: 'pass1',
			collectionName: 'test-collection-1',
			dimension: 768,
		};

		config2 = {
			type: 'milvus',
			url: 'http://localhost:19530', // Same connection details
			username: 'user1',
			password: 'pass1',
			collectionName: 'test-collection-2', // Different collection
			dimension: 1024,
		};

		backend1 = new MilvusBackend(config1);
		backend2 = new MilvusBackend(config2);
	});

	afterEach(async () => {
		// Clean up
		if (backend1?.isConnected()) {
			await backend1.disconnect();
		}
		if (backend2?.isConnected()) {
			await backend2.disconnect();
		}

		const pool = getMilvusConnectionPool();
		await pool.shutdown();
		(pool.constructor as any).instance = null;
		vi.clearAllMocks();
	});

	describe('Connection Sharing', () => {
		it('should share connections between backends with same config', async () => {
			const pool = getMilvusConnectionPool();

			// Connect both backends
			await backend1.connect();
			await backend2.connect();

			// Should have created connection in pool
			expect(pool.size()).toBe(1);

			// Both should be connected
			expect(backend1.isConnected()).toBe(true);
			expect(backend2.isConnected()).toBe(true);

			// Connection should have reference count of 2
			const stats = pool.getStats();
			expect(stats.connectionDetails[0]!.refCount).toBe(2);
		});

		it('should create separate connections for different configurations', async () => {
			// Modify second config to use different connection details
			backend2 = new MilvusBackend({
				...config2,
				url: 'http://localhost:19531', // Different port
			});

			const pool = getMilvusConnectionPool();

			await backend1.connect();
			await backend2.connect();

			// Should have created two separate connections
			expect(pool.size()).toBe(2);
		});

		it('should handle backend disconnection correctly', async () => {
			const pool = getMilvusConnectionPool();

			await backend1.connect();
			await backend2.connect();

			expect(pool.size()).toBe(1);

			const initialStats = pool.getStats();
			expect(initialStats.connectionDetails[0]!.refCount).toBe(2);

			// Disconnect first backend
			await backend1.disconnect();

			const afterFirstDisconnect = pool.getStats();
			expect(afterFirstDisconnect.connectionDetails[0]!.refCount).toBe(1);
			expect(pool.size()).toBe(1); // Connection should still exist

			// Disconnect second backend
			await backend2.disconnect();

			const afterSecondDisconnect = pool.getStats();
			expect(afterSecondDisconnect.connectionDetails[0]!.refCount).toBe(0);
			expect(pool.size()).toBe(1); // Connection still exists but no references
		});
	});

	describe('Backend Operations with Pooled Connections', () => {
		it('should connect and maintain pool correctly', async () => {
			await backend1.connect();

			// Backend should be connected
			expect(backend1.isConnected()).toBe(true);

			// Pool should have one connection
			const pool = getMilvusConnectionPool();
			expect(pool.size()).toBe(1);
		});

		it('should handle operations when client is not connected', async () => {
			// Don't connect backend1
			expect(backend1.isConnected()).toBe(false);

			const vectors = [[1, 2, 3]];
			const ids = [1];
			const payloads = [{ type: 'test' }];

			await expect(backend1.insert(vectors, ids, payloads)).rejects.toThrow(
				'Vector store is not connected'
			);
		});

		it('should validate vector dimensions correctly', async () => {
			await backend1.connect();

			const wrongDimensionVector = [[1, 2]]; // Should be 768 dimensions
			const ids = [1];
			const payloads = [{ type: 'test' }];

			await expect(backend1.insert(wrongDimensionVector, ids, payloads)).rejects.toThrow(
				'Vector dimension mismatch'
			);
		});
	});

	describe('Performance and Resource Management', () => {
		it('should reuse connections efficiently across multiple operations', async () => {
			await backend1.connect();
			await backend2.connect();

			// Should have created only one connection
			const pool = getMilvusConnectionPool();
			expect(pool.size()).toBe(1);

			// Connection should have reference count of 2
			const stats = pool.getStats();
			expect(stats.connectionDetails[0]!.refCount).toBe(2);
		});

		it('should maintain connection statistics correctly', async () => {
			const pool = getMilvusConnectionPool();

			await backend1.connect();
			await backend2.connect();

			const stats = pool.getStats();
			expect(stats.totalConnections).toBe(1);
			expect(stats.connectionDetails[0]!.refCount).toBe(2);
			expect(stats.connectionDetails[0]!.isHealthy).toBe(true);

			// Disconnect one backend
			await backend1.disconnect();

			const updatedStats = pool.getStats();
			expect(updatedStats.connectionDetails[0]!.refCount).toBe(1);

			// Disconnect second backend
			await backend2.disconnect();

			const finalStats = pool.getStats();
			expect(finalStats.connectionDetails[0]!.refCount).toBe(0);
		});
	});

	describe('Concurrent Backend Operations', () => {
		it('should handle concurrent connections correctly', async () => {
			const backends = Array.from({ length: 5 }, () => new MilvusBackend(config1));

			// Connect all backends sequentially to avoid race conditions in tests
			for (const backend of backends) {
				await backend.connect();
			}

			const pool = getMilvusConnectionPool();
			expect(pool.size()).toBe(1);

			const stats = pool.getStats();
			expect(stats.connectionDetails[0]!.refCount).toBe(5);

			// All backends should be connected
			backends.forEach(backend => {
				expect(backend.isConnected()).toBe(true);
			});

			// Disconnect all
			for (const backend of backends) {
				await backend.disconnect();
			}

			const finalStats = pool.getStats();
			expect(finalStats.connectionDetails[0]!.refCount).toBe(0);
		});
	});
});

/**
 * Milvus Vector Storage Backend Tests
 *
 * Tests for the Milvus vector storage backend implementation.
 * Uses mocking since Milvus requires external service.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { MilvusBackend } from '../backend/milvus.js';
import {
	VectorStoreError,
	VectorStoreConnectionError,
	VectorDimensionError,
} from '../backend/types.js';

// Mock the Milvus client
const mockMilvusClient = {
	showCollections: vi.fn(),
	createCollection: vi.fn(),
	dropCollection: vi.fn(),
	createIndex: vi.fn(),
	loadCollection: vi.fn(),
	insert: vi.fn(),
	upsert: vi.fn(),
	query: vi.fn(),
	search: vi.fn(),
	deleteEntities: vi.fn(),
	describeIndex: vi.fn(),
};

vi.mock('@zilliz/milvus2-sdk-node', () => ({
	MilvusClient: vi.fn(() => mockMilvusClient),
	DataType: { VarChar: 'VarChar', FloatVector: 'FloatVector', JSON: 'JSON' },
}));

// Mock the logger to reduce noise in tests
vi.mock('../../logger/index.js', () => ({
	createLogger: () => ({
		info: vi.fn(),
		debug: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
	}),
	logger: {
		info: vi.fn(),
		debug: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
	},
}));

describe('MilvusBackend', () => {
	let backend: MilvusBackend;

	const validConfig = {
		type: 'milvus' as const,
		host: 'localhost',
		port: 19530,
		collectionName: 'test_collection',
		dimension: 3,
	};

	beforeEach(() => {
		backend = new MilvusBackend(validConfig);
		vi.clearAllMocks();
	});

	afterEach(async () => {
		if (backend.isConnected()) {
			await backend.disconnect();
		}
	});

	describe('Connection Management', () => {
		it('should connect successfully when collection exists', async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [{ name: 'test_collection' }] });
			mockMilvusClient.describeIndex.mockResolvedValue({
				index_descriptions: [{ index_name: 'vector_index' }],
			});
			mockMilvusClient.loadCollection.mockResolvedValue({});

			expect(backend.isConnected()).toBe(false);
			await backend.connect();
			expect(backend.isConnected()).toBe(true);
			expect(mockMilvusClient.showCollections).toHaveBeenCalled();
			expect(mockMilvusClient.describeIndex).toHaveBeenCalledWith({
				collection_name: 'test_collection',
				field_name: 'vector',
			});
			expect(mockMilvusClient.loadCollection).toHaveBeenCalled();
		});

		it('should create missing indexes for existing collection', async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [{ name: 'test_collection' }] });
			mockMilvusClient.describeIndex.mockResolvedValue({ index_descriptions: [] });
			mockMilvusClient.createIndex.mockResolvedValue({});
			mockMilvusClient.loadCollection.mockResolvedValue({});

			await backend.connect();

			expect(mockMilvusClient.showCollections).toHaveBeenCalled();
			expect(mockMilvusClient.describeIndex).toHaveBeenCalledWith({
				collection_name: 'test_collection',
				field_name: 'vector',
			});
			expect(mockMilvusClient.createIndex).toHaveBeenCalledWith({
				collection_name: 'test_collection',
				field_name: 'vector',
				index_name: 'vector_index',
				index_type: 'AUTOINDEX',
				metric_type: 'COSINE',
			});
			expect(mockMilvusClient.loadCollection).toHaveBeenCalled();
		});

		it('should handle describeIndex error by creating missing indexes', async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [{ name: 'test_collection' }] });
			mockMilvusClient.describeIndex.mockRejectedValue(new Error('Index not found'));
			mockMilvusClient.createIndex.mockResolvedValue({});
			mockMilvusClient.loadCollection.mockResolvedValue({});

			await backend.connect();

			expect(mockMilvusClient.showCollections).toHaveBeenCalled();
			expect(mockMilvusClient.describeIndex).toHaveBeenCalled();
			expect(mockMilvusClient.createIndex).toHaveBeenCalledWith({
				collection_name: 'test_collection',
				field_name: 'vector',
				index_name: 'vector_index',
				index_type: 'AUTOINDEX',
				metric_type: 'COSINE',
			});
			expect(mockMilvusClient.loadCollection).toHaveBeenCalled();
		});

		it('should create collection if it does not exist', async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [] });
			mockMilvusClient.createCollection.mockResolvedValue({});
			mockMilvusClient.loadCollection.mockResolvedValue({});

			await backend.connect();

			expect(mockMilvusClient.showCollections).toHaveBeenCalled();
			expect(mockMilvusClient.createCollection).toHaveBeenCalledWith({
				collection_name: 'test_collection',
				fields: expect.any(Array),
				// Expect index parameters to be included during collection creation
				index_params: [
					{
						field_name: 'vector',
						index_name: 'vector_index',
						index_type: 'AUTOINDEX',
						metric_type: 'COSINE',
					},
				],
			});
			// createIndex should NOT be called separately anymore
			expect(mockMilvusClient.createIndex).not.toHaveBeenCalled();
			expect(mockMilvusClient.loadCollection).toHaveBeenCalled();
		});

		it('should handle connection failures', async () => {
			mockMilvusClient.showCollections.mockRejectedValue(new Error('Connection failed'));
			await expect(backend.connect()).rejects.toThrow(VectorStoreConnectionError);
			expect(backend.isConnected()).toBe(false);
		});

		it('should disconnect successfully', async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [{ name: 'test_collection' }] });
			mockMilvusClient.loadCollection.mockResolvedValue({});
			await backend.connect();
			await backend.disconnect();
			expect(backend.isConnected()).toBe(false);
		});

		it('should return correct backend type', () => {
			expect(backend.getBackendType()).toBe('milvus');
		});

		it('should return correct metadata', () => {
			expect(backend.getDimension()).toBe(3);
			expect(backend.getCollectionName()).toBe('test_collection');
		});

		it('should not throw when disconnect is called while not connected', async () => {
			await expect(backend.disconnect()).resolves.not.toThrow();
		});
	});

	describe('Vector Operations', () => {
		beforeEach(async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [{ name: 'test_collection' }] });
			mockMilvusClient.loadCollection.mockResolvedValue({});
			await backend.connect();
		});

		it('should insert vectors successfully', async () => {
			mockMilvusClient.insert.mockResolvedValue({});
			const vectors = [
				[1, 2, 3],
				[4, 5, 6],
			];
			const ids = [1, 2];
			const payloads = [{ title: 'First' }, { title: 'Second' }];
			await backend.insert(vectors, ids, payloads);
			expect(mockMilvusClient.insert).toHaveBeenCalledWith({
				collection_name: 'test_collection',
				data: [
					{ id: 1, vector: [1, 2, 3], payload: { title: 'First' } },
					{ id: 2, vector: [4, 5, 6], payload: { title: 'Second' } },
				],
			});
		});

		it('should retrieve vectors by ID', async () => {
			mockMilvusClient.query.mockResolvedValue({
				data: [{ id: '1', vector: [1, 2, 3], payload: { title: 'Test' } }],
			});
			const result = await backend.get(1);
			expect(result).toEqual({
				id: 1,
				vector: [1, 2, 3],
				payload: { title: 'Test' },
				score: 1.0,
			});
		});

		it('should return null if vector not found', async () => {
			mockMilvusClient.query.mockResolvedValue({ data: [] });
			const result = await backend.get(999);
			expect(result).toBeNull();
		});

		it('should update vectors successfully', async () => {
			mockMilvusClient.upsert.mockResolvedValue({});
			await backend.update(1, [1, 2, 3], { title: 'Updated' });
			expect(mockMilvusClient.upsert).toHaveBeenCalledWith({
				collection_name: 'test_collection',
				data: [{ id: 1, vector: [1, 2, 3], payload: { title: 'Updated' } }],
			});
		});

		it('should delete vectors successfully', async () => {
			mockMilvusClient.deleteEntities.mockResolvedValue({});
			await backend.delete(1);
			expect(mockMilvusClient.deleteEntities).toHaveBeenCalledWith({
				collection_name: 'test_collection',
				expr: 'id == 1',
			});
		});

		it('should search vectors successfully', async () => {
			mockMilvusClient.search.mockResolvedValue({
				results: [{ id: '1', score: 0.99, payload: { title: 'Test' } }],
			});
			const result = await backend.search([1, 2, 3], 1);
			expect(result).toEqual([{ id: '1', score: 0.99, payload: { title: 'Test' } }]);
		});

		it('should list vectors successfully', async () => {
			mockMilvusClient.query.mockResolvedValue({
				data: [{ id: '1', vector: [1, 2, 3], payload: { title: 'Test' } }],
			});
			const [results, count] = await backend.list();
			expect(results).toEqual([
				{ id: '1', vector: [1, 2, 3], payload: { title: 'Test' }, score: 1.0 },
			]);
			expect(count).toBe(1);
		});

		it('should throw VectorStoreError if insert is called before connect', async () => {
			const backend = new MilvusBackend(validConfig);
			const vectors = [[1, 2, 3]];
			const ids = [1];
			const payloads = [{ title: 'Test' }];
			await expect(backend.insert(vectors, ids, payloads)).rejects.toThrow(VectorStoreError);
		});

		it('should throw VectorStoreError if update is called before connect', async () => {
			const backend = new MilvusBackend(validConfig);
			await expect(backend.update(1, [1, 2, 3], { title: 'Test' })).rejects.toThrow(
				VectorStoreError
			);
		});

		it('should throw VectorStoreError if delete is called before connect', async () => {
			const backend = new MilvusBackend(validConfig);
			await expect(backend.delete(1)).rejects.toThrow(VectorStoreError);
		});

		it('should throw VectorStoreError if get is called before connect', async () => {
			const backend = new MilvusBackend(validConfig);
			await expect(backend.get(1)).rejects.toThrow(VectorStoreError);
		});

		it('should throw VectorStoreError if vectors, ids, and payloads lengths do not match', async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [{ name: 'test_collection' }] });
			mockMilvusClient.loadCollection.mockResolvedValue({});
			await backend.connect();
			await expect(backend.insert([[1, 2, 3]], [1, 2], [{ title: 'Test' }])).rejects.toThrow(
				VectorStoreError
			);
		});

		it('should throw VectorDimensionError if update vector has wrong dimension', async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [{ name: 'test_collection' }] });
			mockMilvusClient.loadCollection.mockResolvedValue({});
			await backend.connect();
			await expect(backend.update(1, [1, 2], { title: 'Test' })).rejects.toThrow(
				VectorDimensionError
			);
		});

		it('should throw if payloads are null or undefined', async () => {
			await backend.connect();
			await expect(backend.insert([[1, 2, 3]], [1], null as any)).rejects.toThrow();
			await expect(backend.insert([[1, 2, 3]], [1], undefined as any)).rejects.toThrow();
		});

		it('should throw VectorDimensionError if search vector has wrong dimension', async () => {
			await backend.connect();
			await expect(backend.search([1, 2], 1)).rejects.toThrow(VectorDimensionError);
		});

		it('should throw VectorStoreError on get failure', async () => {
			mockMilvusClient.query.mockRejectedValue(new Error('Query failed'));
			await backend.connect();
			await expect(backend.get(1)).rejects.toThrow(VectorStoreError);
		});

		it('should throw VectorStoreError on list failure', async () => {
			mockMilvusClient.query.mockRejectedValue(new Error('Query failed'));
			await backend.connect();
			await expect(backend.list()).rejects.toThrow(VectorStoreError);
		});

		it('should throw VectorStoreError on upsert failure', async () => {
			mockMilvusClient.upsert.mockRejectedValue(new Error('Upsert failed'));
			await backend.connect();
			await expect(backend.update(1, [1, 2, 3], { title: 'Fail' })).rejects.toThrow(
				VectorStoreError
			);
		});

		it('should throw VectorStoreError on deleteEntities failure', async () => {
			mockMilvusClient.deleteEntities.mockRejectedValue(new Error('Delete failed'));
			await backend.connect();
			await expect(backend.delete(1)).rejects.toThrow(VectorStoreError);
		});
	});

	describe('Collection Management', () => {
		beforeEach(async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [{ name: 'test_collection' }] });
			mockMilvusClient.loadCollection.mockResolvedValue({});
			await backend.connect();
		});

		it('should delete collection successfully', async () => {
			mockMilvusClient.dropCollection.mockResolvedValue({});
			await backend.deleteCollection();
			expect(mockMilvusClient.dropCollection).toHaveBeenCalledWith({
				collection_name: 'test_collection',
			});
		});

		it('should list all collections', async () => {
			mockMilvusClient.showCollections.mockResolvedValue({
				data: [{ name: 'col1' }, { name: 'col2' }],
			});
			const backend = new MilvusBackend(validConfig);
			mockMilvusClient.loadCollection.mockResolvedValue({});
			await backend.connect();
			const collections = await backend.listCollections();
			expect(collections).toEqual(['col1', 'col2']);
		});

		it('should throw VectorStoreError if deleteCollection is called before connect', async () => {
			const backend = new MilvusBackend(validConfig);
			await expect(backend.deleteCollection()).rejects.toThrow(VectorStoreError);
		});

		it('should throw VectorStoreError if listCollections is called before connect', async () => {
			const backend = new MilvusBackend(validConfig);
			await expect(backend.listCollections()).rejects.toThrow(VectorStoreError);
		});

		it('should throw VectorStoreError on dropCollection failure', async () => {
			mockMilvusClient.dropCollection.mockRejectedValue(new Error('Drop failed'));
			await backend.connect();
			await expect(backend.deleteCollection()).rejects.toThrow(VectorStoreError);
		});
	});

	describe('Error Handling', () => {
		beforeEach(async () => {
			mockMilvusClient.showCollections.mockResolvedValue({ data: [{ name: 'test_collection' }] });
			mockMilvusClient.loadCollection.mockResolvedValue({});
			await backend.connect();
		});

		it('should throw VectorDimensionError on dimension mismatch', async () => {
			await expect(backend.insert([[1, 2]], [1], [{ title: 'Bad' }])).rejects.toThrow(
				VectorDimensionError
			);
		});

		it('should throw VectorStoreError on insert failure', async () => {
			mockMilvusClient.insert.mockRejectedValue(new Error('Insert failed'));
			await expect(backend.insert([[1, 2, 3]], [1], [{ title: 'Fail' }])).rejects.toThrow(
				VectorStoreError
			);
		});

		it('should throw VectorStoreError on search failure', async () => {
			mockMilvusClient.search.mockRejectedValue(new Error('Search failed'));
			await expect(backend.search([1, 2, 3], 1)).rejects.toThrow(VectorStoreError);
		});
	});
});

/**
 * Phase 1 Test: Reflection Memory Infrastructure
 *
 * Tests dual collection vector storage
 */

import { describe, it, test, expect, beforeEach, afterEach, vi } from 'vitest';
import { DualCollectionVectorManager } from '../dual-collection-manager.js';
import type { VectorStoreConfig } from '../types.js';

// Mock Qdrant client to prevent actual connections during tests
const mockQdrantClient = {
	getCollections: vi.fn(),
	getCollection: vi.fn(),
	createCollection: vi.fn(),
	upsert: vi.fn(),
	search: vi.fn(),
	retrieve: vi.fn(),
	delete: vi.fn(),
	deleteCollection: vi.fn(),
	count: vi.fn(),
	scroll: vi.fn(),
};

vi.mock('@qdrant/js-client-rest', () => ({
	QdrantClient: vi.fn(() => mockQdrantClient),
}));

// Mock logger to reduce test noise
vi.mock('../../logger/index.js', () => ({
	createLogger: () => ({
		info: vi.fn(),
		debug: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
	}),
}));

describe('Phase 1: Reflection Memory Infrastructure', () => {
	beforeEach(() => {
		// Reset all mocks
		vi.clearAllMocks();

		// Mock Qdrant to fail connections (to trigger fallback to in-memory)
		mockQdrantClient.getCollections.mockRejectedValue(new Error('Qdrant connection failed'));
	});

	describe('DualCollectionVectorManager', () => {
		let manager: DualCollectionVectorManager;

		beforeEach(async () => {
			// Enable reflection memory for these tests by setting both collection names
			process.env.REFLECTION_VECTOR_STORE_COLLECTION = 'reflection_memory';

			const config: VectorStoreConfig = {
				type: 'in-memory',
				collectionName: 'test_knowledge',
				dimension: 1536,
				maxVectors: 10000,
			};

			manager = new DualCollectionVectorManager(config);
			await manager.connect();
		});

		afterEach(async () => {
			if (manager) {
				await manager.disconnect();
			}
			delete process.env.REFLECTION_VECTOR_STORE_COLLECTION;
		});

		test('should create dual collection manager with reflection enabled', async () => {
			expect(manager).toBeInstanceOf(DualCollectionVectorManager);
			expect(manager.isConnected('knowledge')).toBe(true);
			expect(manager.isConnected('reflection')).toBe(true);
			expect(manager.getStore('knowledge')).not.toBeNull();
			expect(manager.getStore('reflection')).not.toBeNull();
		});

		test('should provide individual managers for advanced usage', async () => {
			const knowledgeManager = manager.getManager('knowledge');
			const reflectionManager = manager.getManager('reflection');

			expect(knowledgeManager).not.toBeNull();
			expect(reflectionManager).not.toBeNull();
			expect(knowledgeManager?.isConnected()).toBe(true);
			expect(reflectionManager?.isConnected()).toBe(true);
		});
	});

	describe('Collection Type Validation', () => {
		it('should throw error for invalid collection types', async () => {
			process.env.VECTOR_STORE_TYPE = 'in-memory';

			const manager = new DualCollectionVectorManager({
				type: 'in-memory',
				collectionName: 'test',
				dimension: 1536,
				maxVectors: 1000,
			});

			await manager.connect();

			// Testing invalid collection type
			expect(() => manager.getStore('invalid' as any)).toThrow('Unknown collection type');

			// Testing invalid collection type
			expect(() => manager.isConnected('invalid' as any)).toThrow('Unknown collection type');

			// Testing invalid collection type
			expect(() => manager.getManager('invalid' as any)).toThrow('Unknown collection type');

			await manager.disconnect();
		});
	});
});

/**
 * Qdrant Vector Storage Backend Tests
 *
 * Tests for the Qdrant vector storage backend implementation.
 * Uses mocking since Qdrant requires external service.
 */

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { QdrantBackend } from '../backend/qdrant.js';
import {
	VectorStoreError,
	VectorStoreConnectionError,
	VectorDimensionError,
} from '../backend/types.js';
import { BACKEND_TYPES } from '../constants.js';

// Mock the Qdrant client
const mockQdrantClient = {
	getCollections: vi.fn(),
	getCollection: vi.fn(),
	createCollection: vi.fn(),
	deleteCollection: vi.fn(),
	upsert: vi.fn(),
	retrieve: vi.fn(),
	search: vi.fn(),
	delete: vi.fn(),
	scroll: vi.fn(),
	count: vi.fn(),
};

vi.mock('@qdrant/js-client-rest', () => ({
	QdrantClient: vi.fn(() => mockQdrantClient),
}));

// Mock the logger to reduce noise in tests
vi.mock('../../logger/index.js', () => ({
	createLogger: () => ({
		info: vi.fn(),
		debug: vi.fn(),
		warn: vi.fn(),
		error: vi.fn(),
	}),
}));

describe('QdrantBackend', () => {
	let backend: QdrantBackend;

	const validConfig = {
		type: 'qdrant' as const,
		host: 'localhost',
		port: 6333,
		collectionName: 'test_collection',
		dimension: 3,
		distance: 'Cosine' as const,
	};

	beforeEach(() => {
		backend = new QdrantBackend(validConfig);
		// Clear all mock calls before each test
		vi.clearAllMocks();
	});

	afterEach(async () => {
		if (backend.isConnected()) {
			await backend.disconnect();
		}
	});

	describe('Connection Management', () => {
		it('should connect successfully when collection exists', async () => {
			mockQdrantClient.getCollections.mockResolvedValue({
				collections: [{ name: 'test_collection' }],
			});
			mockQdrantClient.getCollection.mockResolvedValue({
				config: {
					params: {
						vectors: {
							size: 3,
							distance: 'Cosine',
						},
					},
				},
			});

			expect(backend.isConnected()).toBe(false);
			await backend.connect();
			expect(backend.isConnected()).toBe(true);

			expect(mockQdrantClient.getCollections).toHaveBeenCalled();
		});

		it('should create collection if it does not exist', async () => {
			mockQdrantClient.getCollections.mockResolvedValue({
				collections: [],
			});
			mockQdrantClient.createCollection.mockResolvedValue({ result: true });

			await backend.connect();

			expect(mockQdrantClient.getCollections).toHaveBeenCalled();
			expect(mockQdrantClient.createCollection).toHaveBeenCalledWith('test_collection', {
				vectors: {
					size: 3,
					distance: 'Cosine',
				},
			});
		});

		it('should handle connection failures', async () => {
			mockQdrantClient.getCollections.mockRejectedValue(new Error('Connection failed'));

			await expect(backend.connect()).rejects.toThrow(VectorStoreConnectionError);
			expect(backend.isConnected()).toBe(false);
		});

		it('should disconnect successfully', async () => {
			mockQdrantClient.getCollections.mockResolvedValue({
				collections: [{ name: 'test_collection' }],
			});
			mockQdrantClient.getCollection.mockResolvedValue({
				config: {
					params: {
						vectors: {
							size: 3,
							distance: 'Cosine',
						},
					},
				},
			});

			await backend.connect();
			await backend.disconnect();
			expect(backend.isConnected()).toBe(false);
		});

		it('should return correct backend type', () => {
			expect(backend.getBackendType()).toBe(BACKEND_TYPES.QDRANT);
		});

		it('should return correct metadata', () => {
			expect(backend.getDimension()).toBe(3);
			expect(backend.getCollectionName()).toBe('test_collection');
		});
	});

	describe('Vector Operations', () => {
		beforeEach(async () => {
			mockQdrantClient.getCollections.mockResolvedValue({
				collections: [{ name: 'test_collection' }],
			});
			mockQdrantClient.getCollection.mockResolvedValue({
				config: {
					params: {
						vectors: {
							size: 3,
							distance: 'Cosine',
						},
					},
				},
			});
			await backend.connect();
		});

		it('should insert vectors successfully', async () => {
			mockQdrantClient.upsert.mockResolvedValue({ status: 'ok' });

			const vectors = [
				[1, 2, 3],
				[4, 5, 6],
			];
			const ids = [1, 2];
			const payloads = [{ title: 'First' }, { title: 'Second' }];
			await backend.insert(vectors, ids, payloads);

			expect(mockQdrantClient.upsert).toHaveBeenCalledWith('test_collection', {
				points: [
					{
						id: 1,
						vector: [1, 2, 3],
						payload: { title: 'First' },
					},
					{
						id: 2,
						vector: [4, 5, 6],
						payload: { title: 'Second' },
					},
				],
			});
		});

		it('should retrieve vectors by ID', async () => {
			mockQdrantClient.retrieve.mockResolvedValue({
				result: [
					{
						id: 1,
						vector: [1, 2, 3],
						payload: { title: 'Test' },
					},
				],
			});

			const result = await backend.get(1);

			expect(result).toBeTruthy();
			expect(result!.id).toBe(1);
			expect(result!.vector).toEqual([1, 2, 3]);
			expect(result!.payload).toEqual({ title: 'Test' });
			expect(result!.score).toBe(1.0);

			expect(mockQdrantClient.retrieve).toHaveBeenCalledWith('test_collection', {
				ids: [1],
				with_vector: true,
				with_payload: true,
			});
		});

		it('should return null for non-existent vectors', async () => {
			mockQdrantClient.retrieve.mockResolvedValue({
				result: [],
			});

			const result = await backend.get(999);
			expect(result).toBeNull();
		});

		it('should update vectors', async () => {
			mockQdrantClient.upsert.mockResolvedValue({ status: 'ok' });

			await backend.update(1, [7, 8, 9], { title: 'Updated' });

			expect(mockQdrantClient.upsert).toHaveBeenCalledWith('test_collection', {
				points: [
					{
						id: 1,
						vector: [7, 8, 9],
						payload: { title: 'Updated' },
					},
				],
			});
		});

		it('should delete vectors', async () => {
			mockQdrantClient.delete.mockResolvedValue({ status: 'ok' });

			await backend.delete(1);

			expect(mockQdrantClient.delete).toHaveBeenCalledWith('test_collection', {
				points: [1],
			});
		});

		it('should delete entire collection', async () => {
			mockQdrantClient.deleteCollection.mockResolvedValue({ result: true });

			await backend.deleteCollection();

			expect(mockQdrantClient.deleteCollection).toHaveBeenCalledWith('test_collection');
		});

		it('should validate vector dimensions', async () => {
			const wrongDimVector = [[1, 2]]; // Should be 3 dimensions
			const ids = [1];
			const payloads = [{}];

			await expect(backend.insert(wrongDimVector, ids, payloads)).rejects.toThrow(
				VectorDimensionError
			);
		});

		it('should require equal array lengths', async () => {
			const vectors = [
				[1, 2, 3],
				[4, 5, 6],
			];
			const ids = [1]; // Mismatched length
			const payloads = [{ title: 'First' }, { title: 'Second' }];

			await expect(backend.insert(vectors, ids, payloads)).rejects.toThrow(VectorStoreError);
		});

		it('should throw error when not connected', async () => {
			await backend.disconnect();

			await expect(backend.get(1)).rejects.toThrow(VectorStoreError);
			await expect(backend.insert([[1, 2, 3]], [1], [{}])).rejects.toThrow(VectorStoreError);
			await expect(backend.search([1, 2, 3])).rejects.toThrow(VectorStoreError);
		});
	});

	describe('Similarity Search', () => {
		beforeEach(async () => {
			mockQdrantClient.getCollections.mockResolvedValue({
				collections: [{ name: 'test_collection' }],
			});
			mockQdrantClient.getCollection.mockResolvedValue({
				config: {
					params: {
						vectors: {
							size: 3,
							distance: 'Cosine',
						},
					},
				},
			});
			await backend.connect();
		});

		it('should search for similar vectors', async () => {
			mockQdrantClient.search.mockResolvedValue({
				result: [
					{
						id: 1,
						version: 1,
						score: 0.95,
						payload: { title: 'First' },
						vector: [1, 2, 3],
					},
					{
						id: 2,
						version: 1,
						score: 0.85,
						payload: { title: 'Second' },
						vector: [4, 5, 6],
					},
				],
			});

			const query = [1, 0, 0];
			const results = await backend.search(query, 2);

			expect(results).toHaveLength(2);
			expect(results[0]?.id).toBe(1);
			expect(results[0]?.score).toBe(0.95);
			expect(results[0]?.payload).toEqual({ title: 'First' });
			expect(results[1]?.id).toBe(2);
			expect(results[1]?.score).toBe(0.85);

			expect(mockQdrantClient.search).toHaveBeenCalledWith('test_collection', {
				vector: [1, 0, 0],
				limit: 2,
				with_vector: true,
				with_payload: true,
			});
		});

		it('should search with metadata filters', async () => {
			mockQdrantClient.search.mockResolvedValue({
				result: [
					{
						id: 1,
						version: 1,
						score: 0.95,
						payload: { category: 'A', title: 'First' },
						vector: [1, 2, 3],
					},
				],
			});

			const query = [1, 0, 0];
			const results = await backend.search(query, 5, { category: 'A' });

			expect(results).toHaveLength(1);

			expect(mockQdrantClient.search).toHaveBeenCalledWith('test_collection', {
				vector: [1, 0, 0],
				limit: 5,
				with_vector: true,
				with_payload: true,
				filter: {
					must: [
						{
							key: 'category',
							match: { value: 'A' },
						},
					],
				},
			});
		});

		it('should handle complex metadata filters', async () => {
			mockQdrantClient.search.mockResolvedValue({ result: [] });

			const query = [1, 0, 0];
			const filters = {
				category: 'A',
				score: 0.8,
				active: true,
			};

			await backend.search(query, 5, filters);

			expect(mockQdrantClient.search).toHaveBeenCalledWith('test_collection', {
				vector: [1, 0, 0],
				limit: 5,
				with_vector: true,
				with_payload: true,
				filter: {
					must: [
						{
							key: 'category',
							match: { value: 'A' },
						},
						{
							key: 'score',
							match: { value: 0.8 },
						},
						{
							key: 'active',
							match: { value: true },
						},
					],
				},
			});
		});

		it('should validate query vector dimension', async () => {
			const wrongDimQuery = [1, 0]; // Should be 3 dimensions

			await expect(backend.search(wrongDimQuery)).rejects.toThrow(VectorDimensionError);
		});

		it('should handle empty search results', async () => {
			mockQdrantClient.search.mockResolvedValue({ result: [] });

			const query = [1, 0, 0];
			const results = await backend.search(query, 5);

			expect(results).toHaveLength(0);
		});
	});

	describe('List Operations', () => {
		beforeEach(async () => {
			mockQdrantClient.getCollections.mockResolvedValue({
				collections: [{ name: 'test_collection' }],
			});
			mockQdrantClient.getCollection.mockResolvedValue({
				config: {
					params: {
						vectors: {
							size: 3,
							distance: 'Cosine',
						},
					},
				},
			});
			mockQdrantClient.count.mockResolvedValue({ count: 2 });
			await backend.connect();
		});

		it('should list all vectors without filters', async () => {
			mockQdrantClient.scroll.mockResolvedValue({
				result: {
					points: [
						{
							id: 1,
							version: 1,
							payload: { title: 'First' },
							vector: [1, 2, 3],
						},
						{
							id: 2,
							version: 1,
							payload: { title: 'Second' },
							vector: [4, 5, 6],
						},
					],
					next_page_offset: null,
				},
			});

			const [results, total] = await backend.list();

			expect(results).toHaveLength(2);
			expect(total).toBe(2);
			expect(results[0]?.id).toBe(1);
			expect(results[1]?.id).toBe(2);

			expect(mockQdrantClient.scroll).toHaveBeenCalledWith('test_collection', {
				with_vector: true,
				with_payload: true,
				limit: 10000,
			});
		});

		it('should list vectors with metadata filters', async () => {
			mockQdrantClient.scroll.mockResolvedValue({
				result: {
					points: [
						{
							id: 1,
							version: 1,
							payload: { category: 'A', title: 'First' },
							vector: [1, 2, 3],
						},
					],
					next_page_offset: null,
				},
			});
			mockQdrantClient.count.mockResolvedValue({ count: 1 });

			const [results, total] = await backend.list({ category: 'A' });

			expect(results).toHaveLength(1);
			expect(total).toBe(1);
			expect(results[0]?.payload?.category).toBe('A');

			expect(mockQdrantClient.scroll).toHaveBeenCalledWith('test_collection', {
				with_vector: true,
				with_payload: true,
				limit: 10000,
				filter: {
					must: [
						{
							key: 'category',
							match: { value: 'A' },
						},
					],
				},
			});
		});

		it('should respect limit parameter', async () => {
			mockQdrantClient.scroll.mockResolvedValue({
				result: {
					points: [
						{
							id: 1,
							version: 1,
							payload: { title: 'First' },
							vector: [1, 2, 3],
						},
					],
					next_page_offset: null,
				},
			});
			mockQdrantClient.count.mockResolvedValue({ count: 1 });

			const [results, total] = await backend.list(undefined, 1);

			expect(results).toHaveLength(1);
			expect(total).toBe(1);

			expect(mockQdrantClient.scroll).toHaveBeenCalledWith('test_collection', {
				with_vector: true,
				with_payload: true,
				limit: 1,
			});
		});
	});

	describe('Error Handling', () => {
		beforeEach(async () => {
			mockQdrantClient.getCollections.mockResolvedValue({
				collections: [{ name: 'test_collection' }],
			});
			mockQdrantClient.getCollection.mockResolvedValue({
				config: {
					params: {
						vectors: {
							size: 3,
							distance: 'Cosine',
						},
					},
				},
			});
			await backend.connect();
		});

		it('should handle Qdrant API errors gracefully', async () => {
			mockQdrantClient.upsert.mockRejectedValue(new Error('Qdrant API error'));

			await expect(backend.insert([[1, 2, 3]], [1], [{}])).rejects.toThrow(VectorStoreError);
		});

		it('should handle search errors', async () => {
			mockQdrantClient.search.mockRejectedValue(new Error('Search failed'));

			await expect(backend.search([1, 2, 3])).rejects.toThrow(VectorStoreError);
		});

		it('should handle retrieve errors', async () => {
			mockQdrantClient.retrieve.mockRejectedValue(new Error('Retrieve failed'));

			await expect(backend.get(1)).rejects.toThrow(VectorStoreError);
		});
	});

	describe('Configuration Variants', () => {
		it('should handle URL-based configuration', async () => {
			const urlConfig = {
				type: 'qdrant' as const,
				url: 'http://localhost:6333',
				collectionName: 'test_collection',
				dimension: 3,
			};

			const urlBackend = new QdrantBackend(urlConfig);
			expect(urlBackend.getBackendType()).toBe(BACKEND_TYPES.QDRANT);
		});

		it('should handle API key authentication', async () => {
			const authConfig = {
				type: 'qdrant' as const,
				host: 'cloud.qdrant.io',
				port: 443,
				apiKey: 'test-api-key',
				collectionName: 'test_collection',
				dimension: 3,
			};

			const authBackend = new QdrantBackend(authConfig);
			expect(authBackend.getBackendType()).toBe(BACKEND_TYPES.QDRANT);
		});

		it('should handle different distance metrics', async () => {
			const euclideanConfig = {
				type: 'qdrant' as const,
				host: 'localhost',
				port: 6333,
				collectionName: 'test_collection',
				dimension: 3,
				distance: 'Euclidean' as const,
			};

			const euclideanBackend = new QdrantBackend(euclideanConfig);
			expect(euclideanBackend.getDimension()).toBe(3);
		});
	});

	describe('Update Operations', () => {
		beforeEach(async () => {
			mockQdrantClient.getCollections.mockResolvedValue({
				collections: [{ name: 'test_collection' }],
			});
			mockQdrantClient.getCollection.mockResolvedValue({
				config: {
					params: {
						vectors: {
							size: 3,
							distance: 'Cosine',
						},
					},
				},
			});
			await backend.connect();
		});

		it('should update a vector successfully', async () => {
			const id = 123;
			const updatedVector = [7, 8, 9];
			const updatedPayload = { title: 'Updated' };

			mockQdrantClient.upsert.mockResolvedValue({
				operation_id: 1,
				status: 'completed',
			});

			await backend.update(id, updatedVector, updatedPayload);

			expect(mockQdrantClient.upsert).toHaveBeenCalledWith('test_collection', {
				points: [
					{
						id,
						vector: updatedVector,
						payload: updatedPayload,
					},
				],
			});
		});

		it('should handle update errors gracefully', async () => {
			const id = 123;
			const vector = [1, 2, 3];
			const payload = { title: 'Test' };

			mockQdrantClient.upsert.mockRejectedValue(new Error('Update failed'));

			await expect(backend.update(id, vector, payload)).rejects.toThrow(VectorStoreError);
		});
	});
});

/**
 * ChromaDB Payload Adapter
 *
 * Handles transformation of complex payloads to ChromaDB-compatible flat metadata
 * and back to original format. ChromaDB only supports primitive types (string, number, boolean)
 * in metadata, so this adapter provides various strategies to handle complex nested objects.
 *
 * @module vector_storage/backend/chroma-payload-adapter
 */

import type {
	ChromaPayloadAdapter,
	PayloadTransformationConfig,
	FieldTransformationConfig,
	PayloadTransformationStrategy,
} from './types.js';
import { Logger, createLogger } from '../../logger/index.js';
import { LOG_PREFIXES } from '../constants.js';

/**
 * Default configuration for payload transformation
 */
const DEFAULT_CONFIG: PayloadTransformationConfig = {
	defaultStrategy: 'json-string',
	autoFlattenNested: true,
	maxNestingDepth: 3,
	fieldConfigs: {
		// Legacy field configurations for backward compatibility
		tags: { strategy: 'comma-separated' },
		currentProgress: { strategy: 'json-string' },
		bugsEncountered: { strategy: 'json-string' },
		workContext: { strategy: 'json-string' },
		// Common field patterns
		id: { strategy: 'preserve' },
		created_at: { strategy: 'preserve' },
		updated_at: { strategy: 'preserve' },
		timestamp: { strategy: 'preserve' },
		score: { strategy: 'preserve' },
		version: { strategy: 'preserve' },
	},
};

/**
 * Implementation of ChromaPayloadAdapter
 *
 * Provides flexible payload transformation with configurable strategies
 * for different field types and nested object handling.
 *
 * @example
 * ```typescript
 * const adapter = new DefaultChromaPayloadAdapter();
 *
 * // Transform complex payload for ChromaDB storage
 * const complexPayload = {
 *   user: { name: 'John', profile: { age: 30, skills: ['js', 'ts'] } },
 *   tags: ['important', 'reviewed'],
 *   metadata: { created: new Date(), version: 1 }
 * };
 *
 * const flatMetadata = adapter.serialize(complexPayload);
 * // Result: { user_name: 'John', user_profile_age: 30, user_profile_skills: 'js,ts', tags: 'important,reviewed', ... }
 *
 * // Transform back from ChromaDB metadata
 * const originalPayload = adapter.deserialize(flatMetadata);
 * ```
 */
export class DefaultChromaPayloadAdapter implements ChromaPayloadAdapter {
	private config: PayloadTransformationConfig;
	private readonly logger: Logger;

	constructor(config?: Partial<PayloadTransformationConfig>) {
		this.config = { ...DEFAULT_CONFIG, ...config };
		this.logger = createLogger({
			level: process.env.CIPHER_LOG_LEVEL || 'info',
		});

		// Merge field configs
		if (config?.fieldConfigs) {
			this.config.fieldConfigs = { ...DEFAULT_CONFIG.fieldConfigs, ...config.fieldConfigs };
		}
	}

	/**
	 * Serialize complex payload to ChromaDB-compatible metadata
	 */
	serialize(payload: Record<string, any>): Record<string, string | number | boolean> {
		if (!payload || typeof payload !== 'object') {
			return {};
		}

		const result: Record<string, string | number | boolean> = {};

		for (const [key, value] of Object.entries(payload)) {
			if (value === null || value === undefined) {
				continue;
			}

			const fieldConfig = this.config.fieldConfigs[key];
			const strategy = fieldConfig?.strategy || this.getStrategyForValue(value);

			try {
				const transformedEntries = this.serializeField(key, value, strategy, fieldConfig);
				Object.assign(result, transformedEntries);
			} catch (error) {
				this.logger.warn(`${LOG_PREFIXES.CHROMA} Failed to serialize field '${key}'`, {
					key,
					strategy,
					error: error instanceof Error ? error.message : String(error),
				});
				// Fallback to JSON string serialization
				if (strategy !== 'json-string') {
					try {
						result[key] = JSON.stringify(value);
					} catch (jsonError) {
						this.logger.error(`${LOG_PREFIXES.CHROMA} Failed JSON fallback for field '${key}'`, {
							key,
							jsonError: jsonError instanceof Error ? jsonError.message : String(jsonError),
						});
					}
				}
			}
		}

		return result;
	}

	/**
	 * Deserialize ChromaDB metadata back to original payload format
	 */
	deserialize(metadata: Record<string, any>): Record<string, any> {
		if (!metadata || typeof metadata !== 'object') {
			return {};
		}

		const result: Record<string, any> = {};
		const processedKeys = new Set<string>();

		// First pass: handle direct field mappings and identify grouped keys
		for (const [key, value] of Object.entries(metadata)) {
			if (processedKeys.has(key)) {
				continue;
			}

			const fieldConfig = this.config.fieldConfigs[key];
			if (fieldConfig) {
				try {
					result[key] = this.deserializeField(key, value, fieldConfig.strategy, fieldConfig);
					processedKeys.add(key);
				} catch (error) {
					this.logger.warn(`${LOG_PREFIXES.CHROMA} Failed to deserialize field '${key}'`, {
						key,
						strategy: fieldConfig.strategy,
						error: error instanceof Error ? error.message : String(error),
					});
					result[key] = value; // Fallback to original value
					processedKeys.add(key);
				}
			}
		}

		// Second pass: handle flattened nested objects (dot notation)
		if (this.config.autoFlattenNested) {
			const nestedGroups = this.groupFlattenedKeys(metadata, processedKeys);
			for (const [rootKey, nestedData] of Object.entries(nestedGroups)) {
				result[rootKey] = this.reconstructNestedObject(nestedData);
				// Mark all related keys as processed
				for (const flatKey in metadata) {
					if (flatKey.startsWith(rootKey + '_')) {
						processedKeys.add(flatKey);
					}
				}
			}
		}

		// Third pass: handle remaining unprocessed keys using heuristics
		for (const [key, value] of Object.entries(metadata)) {
			if (!processedKeys.has(key)) {
				// Determine strategy based on value characteristics
				const strategy = this.inferDeserializationStrategy(value);
				result[key] = this.deserializeField(key, value, strategy);
			}
		}

		return result;
	}

	/**
	 * Get transformation configuration
	 */
	getConfig(): PayloadTransformationConfig {
		return { ...this.config };
	}

	/**
	 * Update transformation configuration
	 */
	updateConfig(config: Partial<PayloadTransformationConfig>): void {
		// Merge the configuration properly, preserving existing field configs
		const mergedFieldConfigs = config.fieldConfigs
			? { ...this.config.fieldConfigs, ...config.fieldConfigs }
			: this.config.fieldConfigs;

		this.config = {
			...this.config,
			...config,
			fieldConfigs: mergedFieldConfigs,
		};
	}

	/**
	 * Determine the best strategy for a given value
	 */
	private getStrategyForValue(value: any): PayloadTransformationStrategy {
		if (value === null || value === undefined) {
			return 'preserve';
		}

		if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
			return 'preserve';
		}

		if (Array.isArray(value)) {
			// Check if array contains only strings/numbers for comma-separated
			if (value.every(item => typeof item === 'string' || typeof item === 'number')) {
				return 'comma-separated';
			}
			return 'json-string';
		}

		if (typeof value === 'object') {
			// Empty objects should use JSON string strategy to preserve them
			if (Object.keys(value).length === 0) {
				return 'json-string';
			}
			// Check if object is simple enough for dot notation
			if (this.isSimpleObject(value)) {
				return 'dot-notation';
			}
			return 'json-string';
		}

		return this.config.defaultStrategy;
	}

	/**
	 * Infer deserialization strategy based on stored value characteristics
	 */
	private inferDeserializationStrategy(value: any): PayloadTransformationStrategy {
		if (typeof value === 'string') {
			// Check if it looks like a comma-separated list
			if (value.includes(',') && !value.startsWith('{') && !value.startsWith('[')) {
				return 'comma-separated';
			}
			// Check if it looks like JSON
			if (
				(value.startsWith('{') && value.endsWith('}')) ||
				(value.startsWith('[') && value.endsWith(']'))
			) {
				return 'json-string';
			}
			// Check if this might be a single-item array that was originally serialized
			// This is a heuristic - if the original was ['single'], we need to detect this case
			// For now, we'll use the default behavior unless we have explicit configuration
		}
		return 'preserve';
	}

	/**
	 * Check if an object is simple enough for dot notation flattening
	 */
	private isSimpleObject(obj: any, depth: number = 0): boolean {
		if (depth >= this.config.maxNestingDepth) {
			return false;
		}

		if (!obj || typeof obj !== 'object' || Array.isArray(obj)) {
			return false;
		}

		// Count the total number of nested levels and complexity
		const keys = Object.keys(obj);
		if (keys.length > 10) {
			// Too many keys at this level
			return false;
		}

		return Object.values(obj).every(value => {
			if (value === null || value === undefined) return true;
			if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
				return true;
			}
			if (Array.isArray(value)) {
				// Only simple arrays with primitive values
				return (
					value.length <= 5 &&
					value.every(item => typeof item === 'string' || typeof item === 'number')
				);
			}
			if (typeof value === 'object') {
				return this.isSimpleObject(value, depth + 1);
			}
			return false;
		});
	}

	/**
	 * Serialize a single field based on strategy
	 */
	private serializeField(
		key: string,
		value: any,
		strategy: PayloadTransformationStrategy,
		config?: FieldTransformationConfig
	): Record<string, string | number | boolean> {
		const result: Record<string, string | number | boolean> = {};

		// Use custom transformer if available
		if (config?.customTransformer) {
			const transformed = config.customTransformer.serialize(value);
			if (typeof transformed === 'object' && !Array.isArray(transformed)) {
				return transformed;
			}
			result[key] = transformed;
			return result;
		}

		switch (strategy) {
			case 'preserve':
				if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
					result[key] = value;
				} else {
					result[key] = String(value);
				}
				break;

			case 'json-string':
				result[key] = JSON.stringify(value);
				break;

			case 'comma-separated':
				if (Array.isArray(value)) {
					result[key] = value.filter(item => item != null).join(',');
				} else {
					result[key] = String(value);
				}
				break;

			case 'boolean-flags':
				if (Array.isArray(value)) {
					const prefix = config?.prefix || key;
					for (const item of value) {
						if (item != null) {
							result[`${prefix}_${String(item)}`] = true;
						}
					}
				} else {
					result[key] = Boolean(value);
				}
				break;

			case 'dot-notation':
				if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
					const flattened = this.flattenObject(value, key);
					Object.assign(result, flattened);
				} else {
					result[key] = String(value);
				}
				break;

			default:
				result[key] = JSON.stringify(value);
		}

		return result;
	}

	/**
	 * Deserialize a single field based on strategy
	 */
	private deserializeField(
		key: string,
		value: any,
		strategy: PayloadTransformationStrategy,
		config?: FieldTransformationConfig
	): any {
		// Use custom transformer if available
		if (config?.customTransformer) {
			return config.customTransformer.deserialize(value);
		}

		switch (strategy) {
			case 'preserve':
				return value;

			case 'json-string':
				if (typeof value === 'string') {
					try {
						return JSON.parse(value);
					} catch {
						return value;
					}
				}
				return value;

			case 'comma-separated':
				if (typeof value === 'string') {
					if (value === '') {
						return [];
					}
					return value
						.split(',')
						.filter(item => item.trim().length > 0)
						.map(item => {
							const trimmed = item.trim();
							// Try to convert back to number if it looks like a number
							if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
								const num = Number(trimmed);
								return isNaN(num) ? trimmed : num;
							}
							return trimmed;
						});
				}
				return Array.isArray(value) ? value : [value];

			case 'boolean-flags':
				// This would be handled in the grouping logic
				return value;

			case 'dot-notation':
				// This would be handled in the nested object reconstruction
				return value;

			default:
				if (typeof value === 'string' && (value.startsWith('{') || value.startsWith('['))) {
					try {
						return JSON.parse(value);
					} catch {
						return value;
					}
				}
				return value;
		}
	}

	/**
	 * Flatten nested object using dot notation
	 */
	private flattenObject(
		obj: Record<string, any>,
		prefix: string = '',
		depth: number = 0
	): Record<string, string | number | boolean> {
		const result: Record<string, string | number | boolean> = {};

		if (depth >= this.config.maxNestingDepth) {
			result[prefix] = JSON.stringify(obj);
			return result;
		}

		for (const [key, value] of Object.entries(obj)) {
			if (value === null || value === undefined) {
				continue;
			}

			const newKey = prefix ? `${prefix}_${key}` : key;

			if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
				result[newKey] = value;
			} else if (Array.isArray(value)) {
				// Handle arrays as comma-separated for simple types
				if (value.every(item => typeof item === 'string' || typeof item === 'number')) {
					result[newKey] = value.join(',');
				} else {
					result[newKey] = JSON.stringify(value);
				}
			} else if (typeof value === 'object') {
				Object.assign(result, this.flattenObject(value, newKey, depth + 1));
			} else {
				result[newKey] = String(value);
			}
		}

		return result;
	}

	/**
	 * Group flattened keys by their root key
	 */
	private groupFlattenedKeys(
		metadata: Record<string, any>,
		processedKeys: Set<string>
	): Record<string, Record<string, any>> {
		const groups: Record<string, Record<string, any>> = {};

		for (const key in metadata) {
			if (processedKeys.has(key)) {
				continue;
			}

			const underscoreIndex = key.indexOf('_');
			if (underscoreIndex > 0) {
				const rootKey = key.substring(0, underscoreIndex);
				const remainingKey = key.substring(underscoreIndex + 1);

				if (!groups[rootKey]) {
					groups[rootKey] = {};
				}
				groups[rootKey][remainingKey] = metadata[key];
			}
		}

		return groups;
	}

	/**
	 * Reconstruct nested object from flattened keys
	 */
	private reconstructNestedObject(flatData: Record<string, any>): any {
		const result: Record<string, any> = {};

		for (const [key, value] of Object.entries(flatData)) {
			const parts = key.split('_');
			let current = result;

			for (let i = 0; i < parts.length - 1; i++) {
				const part = parts[i];
				if (!part) continue; // Skip undefined parts
				if (!(part in current)) {
					current[part] = {};
				}
				current = current[part];
			}

			const finalKey = parts[parts.length - 1];
			if (!finalKey) continue; // Skip if finalKey is undefined

			// Try to parse comma-separated values back to arrays
			if (typeof value === 'string' && value.includes(',')) {
				const arrayValue = value
					.split(',')
					.filter(item => item.trim().length > 0)
					.map(item => {
						const trimmed = item.trim();
						// Try to convert back to number if it looks like a number
						if (/^-?\d+(\.\d+)?$/.test(trimmed)) {
							const num = Number(trimmed);
							return isNaN(num) ? trimmed : num;
						}
						return trimmed;
					});
				// Only convert to array if it looks like it should be an array
				current[finalKey] = arrayValue.length > 1 ? arrayValue : value;
			} else {
				current[finalKey] = value;
			}
		}

		return result;
	}
}

/**
 * ChromaDB Vector Store Backend
 *
 * Implementation of the VectorStore interface for ChromaDB vector database.
 * ChromaDB is an open-source embedding database focused on developer experience.
 *
 * Features:
 * - HTTP-based client for remote ChromaDB servers
 * - Built-in embedding functions support
 * - Rich metadata filtering capabilities
 * - Multiple distance metrics support
 *
 * @module vector_storage/backend/chroma
 */

import { ChromaClient } from 'chromadb';
import type { VectorStore } from './vector-store.js';
import type {
	SearchFilters,
	VectorStoreResult,
	ChromaBackendConfig,
	ChromaPayloadAdapter,
	PayloadTransformationConfig,
} from './types.js';
import { VectorStoreError, VectorStoreConnectionError, VectorDimensionError } from './types.js';
import { Logger, createLogger } from '../../logger/index.js';
import { LOG_PREFIXES, DEFAULTS, ERROR_MESSAGES } from '../constants.js';
import { DefaultChromaPayloadAdapter } from './chroma-payload-adapter.js';

/**
 * ChromaDB filter structure
 */
interface ChromaFilter {
	[key: string]: any;
}

/**
 * ChromaBackend Class
 *
 * Implements the VectorStore interface for ChromaDB vector database.
 *
 * @example
 * ```typescript
 * const chroma = new ChromaBackend({
 *   type: 'chroma',
 *   url: 'http://localhost:8000',
 *   collectionName: 'documents',
 *   dimension: 1536
 * });
 *
 * await chroma.connect();
 * await chroma.insert([vector], [1], [{ title: 'Document' }]);
 * const results = await chroma.search(queryVector, 10);
 * ```
 */
export class ChromaBackend implements VectorStore {
	private client: ChromaClient;
	private collection: any = null;
	private readonly config: ChromaBackendConfig;
	private readonly collectionName: string;
	private readonly dimension: number;
	private readonly logger: Logger;
	private readonly payloadAdapter: ChromaPayloadAdapter;
	private connected = false;

	constructor(config: ChromaBackendConfig, payloadAdapter?: ChromaPayloadAdapter) {
		this.config = config;
		this.collectionName = config.collectionName;
		this.dimension = config.dimension;
		this.logger = createLogger({
			level: process.env.CIPHER_LOG_LEVEL || 'info',
		});

		// Initialize payload adapter with default configuration
		this.payloadAdapter = payloadAdapter || new DefaultChromaPayloadAdapter();

		// Initialize client
		const clientConfig: any = {};

		if (config.url) {
			// Parse URL to extract host, port, and ssl settings
			const url = new URL(config.url);
			clientConfig.host = url.hostname;
			clientConfig.port = parseInt(url.port) || (url.protocol === 'https:' ? 443 : 80);
			clientConfig.ssl = url.protocol === 'https:';
		} else if (config.host) {
			clientConfig.host = config.host;
			clientConfig.port = config.port || 8000;
			clientConfig.ssl = config.ssl || false;
		}

		if (config.headers) {
			clientConfig.fetchOptions = {
				headers: config.headers,
			};
		}

		this.client = new ChromaClient(clientConfig);

		this.logger.debug(`${LOG_PREFIXES.CHROMA} Initialized`, {
			collection: this.collectionName,
			dimension: this.dimension,
			url:
				config.url ||
				`${clientConfig.ssl ? 'https' : 'http'}://${clientConfig.host}:${clientConfig.port}` ||
				'embedded',
		});
	}

	/**
	 * Convert search filters to ChromaDB filter format
	 */
	private createFilter(filters?: SearchFilters): ChromaFilter | undefined {
		if (!filters) return undefined;

		const chromaFilter: ChromaFilter = {};

		for (const [key, value] of Object.entries(filters)) {
			if (value === null || value === undefined) continue;

			// Handle range queries
			if (
				typeof value === 'object' &&
				!Array.isArray(value) &&
				('gte' in value || 'gt' in value || 'lte' in value || 'lt' in value)
			) {
				// ChromaDB uses $gte, $gt, $lte, $lt operators
				const rangeConditions: any = {};
				if ('gte' in value && value.gte !== undefined) rangeConditions.$gte = value.gte;
				if ('gt' in value && value.gt !== undefined) rangeConditions.$gt = value.gt;
				if ('lte' in value && value.lte !== undefined) rangeConditions.$lte = value.lte;
				if ('lt' in value && value.lt !== undefined) rangeConditions.$lt = value.lt;
				chromaFilter[key] = rangeConditions;
			}
			// Handle array filters (any/all)
			else if (
				typeof value === 'object' &&
				!Array.isArray(value) &&
				('any' in value || 'all' in value)
			) {
				// ChromaDB uses $in for "any" operations
				if ('any' in value && Array.isArray(value.any)) {
					chromaFilter[key] = { $in: value.any };
				}
				// For 'all', we'd need multiple conditions - ChromaDB doesn't have direct support
				// so we'll use the first value as a fallback
				else if ('all' in value && Array.isArray(value.all) && value.all.length > 0) {
					chromaFilter[key] = value.all[0];
				}
			}
			// Handle exact matches
			else {
				chromaFilter[key] = value;
			}
		}

		return Object.keys(chromaFilter).length > 0 ? chromaFilter : undefined;
	}

	/**
	 * Validate vector dimension
	 */
	private validateDimension(vector: number[], operation: string): void {
		if (vector.length !== this.dimension) {
			throw new VectorDimensionError(
				`${ERROR_MESSAGES.INVALID_DIMENSION}: expected ${this.dimension}, got ${vector.length}`,
				this.dimension,
				vector.length
			);
		}
	}

	/**
	 * Validate ID (ChromaDB supports string and number IDs, we'll convert numbers to strings)
	 */
	private validateId(id: number): void {
		if (!Number.isInteger(id) || isNaN(id)) {
			throw new VectorStoreError('ChromaDB point IDs must be valid integers', 'id');
		}
	}

	/**
	 * Get the payload adapter instance
	 */
	getPayloadAdapter(): ChromaPayloadAdapter {
		return this.payloadAdapter;
	}

	// VectorStore implementation

	async insert(vectors: number[][], ids: number[], payloads: Record<string, any>[]): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'insert');
		}

		if (!this.collection) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} Collection is null during insert`);
			throw new VectorStoreError('ChromaDB collection not initialized', 'insert');
		}

		// Validate inputs
		if (vectors.length !== ids.length || vectors.length !== payloads.length) {
			throw new VectorStoreError('Vectors, IDs, and payloads must have the same length', 'insert');
		}

		// Validate dimensions and IDs
		for (let i = 0; i < vectors.length; i++) {
			const vector = vectors[i];
			const id = ids[i];

			if (!vector) {
				throw new VectorStoreError(`Vector missing at index ${i}`, 'insert');
			}
			if (id === undefined || id === null) {
				throw new VectorStoreError(`ID missing at index ${i}`, 'insert');
			}

			this.validateDimension(vector, 'insert');
			this.validateId(id);
		}

		this.logger.debug(`${LOG_PREFIXES.CHROMA} Inserting ${vectors.length} vectors`);

		// Convert IDs to strings as ChromaDB expects string IDs
		const stringIds = ids.map(id => id.toString());

		// Convert payloads to be ChromaDB compatible using the payload adapter
		const chromaCompatiblePayloads = payloads.map(payload =>
			this.payloadAdapter.serialize(payload)
		);

		const addParams = {
			ids: stringIds,
			embeddings: vectors,
			metadatas: chromaCompatiblePayloads,
		};

		try {
			// Use upsert to avoid duplicate ID errors on re-inserts
			await this.collection.upsert(addParams);

			this.logger.debug(`${LOG_PREFIXES.CHROMA} Successfully inserted ${vectors.length} vectors`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} Insert failed`, {
				error: error instanceof Error ? error.message : String(error),
				vectorCount: vectors.length,
				collectionName: this.collectionName,
			});
			throw new VectorStoreError('Failed to insert vectors', 'insert', error as Error);
		}
	}

	async search(
		query: number[],
		limit: number = DEFAULTS.SEARCH_LIMIT,
		filters?: SearchFilters
	): Promise<VectorStoreResult[]> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'search');
		}

		if (!this.collection) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} Collection is null during search`);
			throw new VectorStoreError('ChromaDB collection not initialized', 'search');
		}

		this.validateDimension(query, 'search');

		this.logger.debug(`${LOG_PREFIXES.CHROMA} Searching with limit ${limit}`, {
			hasFilters: !!filters,
		});

		try {
			const chromaFilter = this.createFilter(filters);

			const searchParams: any = {
				queryEmbeddings: [query],
				nResults: limit,
			};

			if (chromaFilter) {
				searchParams.where = chromaFilter;
			}

			const searchResponse = await this.collection.query(searchParams);

			// ChromaDB returns results in arrays
			const results: VectorStoreResult[] = [];
			if (searchResponse.ids && searchResponse.ids[0]) {
				for (let i = 0; i < searchResponse.ids[0].length; i++) {
					const id = searchResponse.ids[0][i];
					const distance = searchResponse.distances?.[0]?.[i] ?? 0;
					const metadata = searchResponse.metadatas?.[0]?.[i] ?? {};

					// Convert distance to similarity score (ChromaDB returns distances)
					// For cosine distance, similarity = 1 - distance
					const score = 1 - distance;

					results.push({
						id: parseInt(id, 10), // Convert back to number
						score,
						payload: this.payloadAdapter.deserialize(metadata),
					});
				}
			}

			this.logger.debug(`${LOG_PREFIXES.CHROMA} Found ${results.length} results`);

			return results;
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} Search failed`, {
				error: error instanceof Error ? error.message : String(error),
				queryLength: query.length,
				limit,
				collectionName: this.collectionName,
			});
			throw new VectorStoreError(ERROR_MESSAGES.SEARCH_FAILED, 'search', error as Error);
		}
	}

	async get(vectorId: number): Promise<VectorStoreResult | null> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'get');
		}

		this.validateId(vectorId);
		this.logger.debug(`${LOG_PREFIXES.CHROMA} Getting vector ${vectorId}`);

		try {
			const response = await this.collection.get({
				ids: [vectorId.toString()],
				include: ['embeddings', 'metadatas'],
			});

			if (!response.ids || response.ids.length === 0) {
				return null;
			}

			const id = response.ids[0];
			const embedding = response.embeddings?.[0];
			const metadata = response.metadatas?.[0] ?? {};

			return {
				id: parseInt(id, 10),
				vector: embedding || [],
				payload: this.payloadAdapter.deserialize(metadata),
				score: 1.0,
			};
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} Get failed`, { error });
			throw new VectorStoreError('Failed to retrieve vector', 'get', error as Error);
		}
	}

	async update(vectorId: number, vector: number[], payload: Record<string, any>): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'update');
		}

		this.validateDimension(vector, 'update');
		this.validateId(vectorId);
		this.logger.debug(`${LOG_PREFIXES.CHROMA} Updating vector ${vectorId}`);

		try {
			// Convert payload to be ChromaDB compatible using the payload adapter
			const convertedPayload = this.payloadAdapter.serialize(payload);

			// ChromaDB doesn't have a direct update method, so we use upsert
			await this.collection.upsert({
				ids: [vectorId.toString()],
				embeddings: [vector],
				metadatas: [convertedPayload],
			});

			this.logger.debug(`${LOG_PREFIXES.CHROMA} Successfully updated vector ${vectorId}`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} Update failed`, { error });
			throw new VectorStoreError('Failed to update vector', 'update', error as Error);
		}
	}

	async delete(vectorId: number): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'delete');
		}

		this.validateId(vectorId);
		this.logger.debug(`${LOG_PREFIXES.CHROMA} Deleting vector ${vectorId}`);

		try {
			await this.collection.delete({
				ids: [vectorId.toString()],
			});

			this.logger.debug(`${LOG_PREFIXES.CHROMA} Successfully deleted vector ${vectorId}`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} Delete failed`, { error });
			throw new VectorStoreError('Failed to delete vector', 'delete', error as Error);
		}
	}

	async deleteCollection(): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'deleteCollection');
		}

		this.logger.warn(`${LOG_PREFIXES.CHROMA} Deleting collection ${this.collectionName}`);

		try {
			await this.client.deleteCollection({ name: this.collectionName });
			this.logger.info(
				`${LOG_PREFIXES.CHROMA} Successfully deleted collection ${this.collectionName}`
			);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} Delete collection failed`, { error });
			throw new VectorStoreError('Failed to delete collection', 'deleteCollection', error as Error);
		}
	}

	async list(
		filters?: SearchFilters,
		limit: number = 10000
	): Promise<[VectorStoreResult[], number]> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'list');
		}

		this.logger.debug(`${LOG_PREFIXES.CHROMA} Listing vectors`, {
			hasFilters: !!filters,
			limit,
		});

		try {
			const chromaFilter = this.createFilter(filters);

			const getParams: any = {
				include: ['embeddings', 'metadatas'],
				limit,
			};

			if (chromaFilter) {
				getParams.where = chromaFilter;
			}

			const response = await this.collection.get(getParams);

			const results: VectorStoreResult[] = [];
			if (response.ids) {
				for (let i = 0; i < response.ids.length; i++) {
					const id = response.ids[i];
					const embedding = response.embeddings?.[i];
					const metadata = response.metadatas?.[i] ?? {};

					results.push({
						id: parseInt(id, 10),
						score: 1.0, // Default score for exact match
						payload: this.payloadAdapter.deserialize(metadata),
						vector: embedding,
					});
				}
			}

			// ChromaDB doesn't provide total count directly, so we return the result count
			this.logger.info(`${LOG_PREFIXES.CHROMA} Listed ${results.length} vectors`);

			return [results, results.length];
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} List failed`, { error });
			throw new VectorStoreError('Failed to list vectors', 'list', error as Error);
		}
	}

	async connect(): Promise<void> {
		if (this.connected) {
			this.logger.debug(`${LOG_PREFIXES.CHROMA} Already connected`);
			return;
		}

		this.logger.info(`${LOG_PREFIXES.CHROMA} Connecting to ChromaDB`);

		try {
			// Try to get or create the collection
			try {
				this.collection = await this.client.getCollection({
					name: this.collectionName,
					embeddingFunction: null as any, // Use null to indicate no embedding function
				});

				this.logger.debug(
					`${LOG_PREFIXES.CHROMA} Collection already exists: ${this.collectionName}`
				);
			} catch (error) {
				// Collection doesn't exist, create it
				this.logger.debug(`${LOG_PREFIXES.CHROMA} Creating collection ${this.collectionName}`);

				// Determine distance metric
				const distance = this.config.distance || 'cosine';
				let metricName = 'cosine';
				if (distance === 'euclidean' || distance === 'l2') {
					metricName = 'l2';
				} else if (distance === 'ip' || distance === 'dot') {
					metricName = 'ip';
				}

				this.collection = await this.client.createCollection({
					name: this.collectionName,
					metadata: {
						'hnsw:space': metricName,
					},
					embeddingFunction: null as any, // Use null to indicate no embedding function
				});
			}

			this.connected = true;
			this.logger.info(`${LOG_PREFIXES.CHROMA} Successfully connected`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.CHROMA} Connection failed`, { error });

			if (error instanceof VectorStoreConnectionError) {
				throw error;
			}

			throw new VectorStoreConnectionError(
				ERROR_MESSAGES.CONNECTION_FAILED,
				'chroma',
				error as Error
			);
		}
	}

	async disconnect(): Promise<void> {
		if (!this.connected) {
			this.logger.debug(`${LOG_PREFIXES.CHROMA} Already disconnected`);
			return;
		}

		this.logger.info(`${LOG_PREFIXES.CHROMA} Disconnecting from ChromaDB`);

		// ChromaDB client doesn't have explicit disconnect
		// Just mark as disconnected and clear collection reference
		this.collection = null;
		this.connected = false;

		this.logger.info(`${LOG_PREFIXES.CHROMA} Successfully disconnected`);
	}

	isConnected(): boolean {
		return this.connected;
	}

	getBackendType(): string {
		return 'chroma';
	}

	getDimension(): number {
		return this.dimension;
	}

	getCollectionName(): string {
		return this.collectionName;
	}
}

/**
 * In-Memory Vector Store Backend
 *
 * Simple in-memory implementation of the VectorStore interface.
 * Used for development, testing, and as a fallback when external stores are unavailable.
 *
 * Features:
 * - Fast local similarity search
 * - No external dependencies
 * - Automatic memory management with max vector limit
 * - Cosine similarity for search
 *
 * Limitations:
 * - Data is lost on process restart
 * - Limited by available memory
 * - No distributed capabilities
 *
 * @module vector_storage/backend/in-memory
 */

import type { VectorStore } from './vector-store.js';
import type { SearchFilters, VectorStoreResult, InMemoryBackendConfig } from './types.js';
import { VectorStoreError, VectorDimensionError } from './types.js';
import { Logger, createLogger } from '../../logger/index.js';
import { LOG_PREFIXES, DEFAULTS, ERROR_MESSAGES } from '../constants.js';

/**
 * In-memory vector entry
 */
interface VectorEntry {
	id: number;
	vector: number[];
	payload: Record<string, any>;
}

/**
 * InMemoryBackend Class
 *
 * Implements the VectorStore interface using in-memory storage.
 *
 * @example
 * ```typescript
 * const store = new InMemoryBackend({
 *   type: 'in-memory',
 *   collectionName: 'test',
 *   dimension: 1536,
 *   maxVectors: 10000
 * });
 *
 * await store.connect();
 * await store.insert([vector], ['doc1'], [{ title: 'Test' }]);
 * const results = await store.search(queryVector, 5);
 * ```
 */
export class InMemoryBackend implements VectorStore {
	private readonly config: InMemoryBackendConfig;
	private readonly collectionName: string;
	private readonly dimension: number;
	private readonly maxVectors: number;
	private readonly logger: Logger;
	private connected = false;

	// In-memory storage
	private vectors: Map<number, VectorEntry> = new Map();

	constructor(config: InMemoryBackendConfig) {
		this.config = config;
		this.collectionName = config.collectionName;
		this.dimension = config.dimension;
		this.maxVectors = config.maxVectors || 10000;
		this.logger = createLogger({
			level: process.env.LOG_LEVEL || 'info',
		});

		this.logger.debug(`${LOG_PREFIXES.MEMORY} Initialized`, {
			collection: this.collectionName,
			dimension: this.dimension,
			maxVectors: this.maxVectors,
		});
	}

	/**
	 * Calculate cosine similarity between two vectors
	 */
	private cosineSimilarity(a: number[], b: number[]): number {
		let dotProduct = 0;
		let normA = 0;
		let normB = 0;

		const minLength = Math.min(a.length, b.length);
		for (let i = 0; i < minLength; i++) {
			const aVal = a[i]!;
			const bVal = b[i]!;
			dotProduct += aVal * bVal;
			normA += aVal * aVal;
			normB += bVal * bVal;
		}

		normA = Math.sqrt(normA);
		normB = Math.sqrt(normB);

		if (normA === 0 || normB === 0) {
			return 0;
		}

		return dotProduct / (normA * normB);
	}

	/**
	 * Deep clone an object to prevent reference issues
	 */
	private deepClone<T>(obj: T): T {
		if (obj === null || typeof obj !== 'object') {
			return obj;
		}

		if (Array.isArray(obj)) {
			return obj.map(item => this.deepClone(item)) as unknown as T;
		}

		const cloned = {} as T;
		for (const key in obj) {
			if (Object.prototype.hasOwnProperty.call(obj, key)) {
				cloned[key] = this.deepClone(obj[key]);
			}
		}

		return cloned;
	}

	/**
	 * Check if a vector entry matches the given filters
	 */
	private matchesFilters(entry: VectorEntry, filters?: SearchFilters): boolean {
		if (!filters) return true;

		for (const [key, value] of Object.entries(filters)) {
			const payloadValue = entry.payload[key];

			// Handle null/undefined
			if (value === null || value === undefined) continue;

			// Handle range queries
			if (
				typeof value === 'object' &&
				!Array.isArray(value) &&
				('gte' in value || 'gt' in value || 'lte' in value || 'lt' in value)
			) {
				if (typeof payloadValue !== 'number') return false;

				if ('gte' in value && payloadValue < value.gte!) return false;
				if ('gt' in value && payloadValue <= value.gt!) return false;
				if ('lte' in value && payloadValue > value.lte!) return false;
				if ('lt' in value && payloadValue >= value.lt!) return false;
			}
			// Handle array filters
			else if (
				typeof value === 'object' &&
				!Array.isArray(value) &&
				('any' in value || 'all' in value)
			) {
				if ('any' in value && Array.isArray(value.any)) {
					// Check if payload value matches any of the values
					if (!value.any.includes(payloadValue)) return false;
				}
			}
			// Handle exact match
			else {
				if (payloadValue !== value) return false;
			}
		}

		return true;
	}

	/**
	 * Validate vector dimension
	 */
	private validateDimension(vector: number[], _operation: any): void {
		if (vector.length !== this.dimension) {
			throw new VectorDimensionError(
				`${ERROR_MESSAGES.INVALID_DIMENSION}: expected ${this.dimension}, got ${vector.length}`,
				this.dimension,
				vector.length
			);
		}
	}

	// VectorStore implementation

	async insert(vectors: number[][], ids: number[], payloads: Record<string, any>[]): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'insert');
		}

		// Validate inputs
		if (vectors.length !== ids.length || vectors.length !== payloads.length) {
			throw new VectorStoreError('Vectors, IDs, and payloads must have the same length', 'insert');
		}

		// Check max vectors limit
		if (this.vectors.size + vectors.length > this.maxVectors) {
			throw new VectorStoreError(
				`Cannot insert ${vectors.length} vectors. Would exceed max limit of ${this.maxVectors}`,
				'insert'
			);
		}

		// Validate dimensions and insert
		for (let i = 0; i < vectors.length; i++) {
			const vector = vectors[i];
			const id = ids[i];
			const payload = payloads[i];

			if (!vector || typeof id !== 'number' || !Number.isInteger(id) || !payload) {
				throw new VectorStoreError(
					`Invalid input at index ${i}: vector, integer id, and payload are required`,
					'insert'
				);
			}

			this.validateDimension(vector, 'insert');

			this.vectors.set(id, {
				id: id,
				vector: [...vector], // Clone to prevent external modification
				payload: this.deepClone(payload), // Deep clone payload
			});
		}

		this.logger.debug(`${LOG_PREFIXES.INDEX} Inserted ${vectors.length} vectors`);
	}

	async search(
		query: number[],
		limit: number = DEFAULTS.SEARCH_LIMIT,
		filters?: SearchFilters
	): Promise<VectorStoreResult[]> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'search');
		}

		this.validateDimension(query, 'search');

		// Calculate similarities for all vectors
		const results: Array<{ entry: VectorEntry; score: number }> = [];

		for (const entry of this.vectors.values()) {
			// Apply filters
			if (!this.matchesFilters(entry, filters)) {
				continue;
			}

			// Calculate similarity
			const score = this.cosineSimilarity(query, entry.vector);
			results.push({ entry, score });
		}

		// Sort by score (descending) and limit
		results.sort((a, b) => b.score - a.score);
		const topResults = results.slice(0, limit);

		// Format results
		const formattedResults = topResults.map(({ entry, score }) => ({
			id: entry.id,
			vector: [...entry.vector],
			payload: this.deepClone(entry.payload),
			score,
		}));

		this.logger.debug(`${LOG_PREFIXES.SEARCH} Found ${formattedResults.length} results`);

		return formattedResults;
	}

	async get(vectorId: number): Promise<VectorStoreResult | null> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'get');
		}

		const entry = this.vectors.get(vectorId);
		if (!entry) {
			return null;
		}

		return {
			id: entry.id,
			vector: [...entry.vector], // Clone vector
			payload: this.deepClone(entry.payload), // Deep clone payload
			score: 1.0, // Perfect match for direct retrieval
		};
	}

	async update(vectorId: number, vector: number[], payload: Record<string, any>): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'update');
		}

		this.validateDimension(vector, 'update');

		if (!this.vectors.has(vectorId)) {
			throw new VectorStoreError(`Vector with ID ${vectorId} not found`, 'update');
		}

		this.vectors.set(vectorId, {
			id: vectorId,
			vector: [...vector],
			payload: this.deepClone(payload),
		});

		this.logger.debug(`${LOG_PREFIXES.BACKEND} Updated vector ${vectorId}`);
	}

	async delete(vectorId: number): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'delete');
		}

		if (!this.vectors.has(vectorId)) {
			this.logger.warn(`${LOG_PREFIXES.BACKEND} Vector ${vectorId} not found for deletion`);
			return;
		}

		this.vectors.delete(vectorId);
		this.logger.debug(`${LOG_PREFIXES.BACKEND} Deleted vector ${vectorId}`);
	}

	async deleteCollection(): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'deleteCollection');
		}

		const count = this.vectors.size;
		this.vectors.clear();

		this.logger.info(
			`${LOG_PREFIXES.BACKEND} Deleted collection ${this.collectionName} with ${count} vectors`
		);
	}

	async list(filters?: SearchFilters, limit: number = 100): Promise<[VectorStoreResult[], number]> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'list');
		}

		const results: VectorStoreResult[] = [];
		let count = 0;

		for (const entry of this.vectors.values()) {
			if (this.matchesFilters(entry, filters)) {
				count++;
				if (results.length < limit) {
					results.push({
						id: entry.id,
						vector: [...entry.vector],
						payload: this.deepClone(entry.payload),
						score: 1.0, // Default score for list operations
					});
				}
			}
		}

		this.logger.info(`${LOG_PREFIXES.BACKEND} Listed ${results.length} of ${count} vectors`);

		return [results, count];
	}

	async connect(): Promise<void> {
		if (this.connected) {
			this.logger.debug(`${LOG_PREFIXES.MEMORY} Already connected`);
			return;
		}

		// In-memory doesn't need actual connection
		this.connected = true;
		this.logger.debug(`${LOG_PREFIXES.MEMORY} Connected (in-memory)`);
	}

	async disconnect(): Promise<void> {
		if (!this.connected) {
			this.logger.debug(`${LOG_PREFIXES.MEMORY} Already disconnected`);
			return;
		}

		this.connected = false;
		this.vectors.clear(); // Clear data on disconnect
		this.logger.info(`${LOG_PREFIXES.MEMORY} Disconnected and cleared data`);
	}

	isConnected(): boolean {
		return this.connected;
	}

	getBackendType(): string {
		return 'in-memory';
	}

	getDimension(): number {
		return this.dimension;
	}

	getCollectionName(): string {
		return this.collectionName;
	}
}

/**
 * Vector Storage Backend Exports
 *
 * Central export point for all backend types, interfaces, and implementations.
 * This module provides a clean API for accessing backend functionality.
 *
 * @module vector_storage/backend
 */

// Export core types and interfaces
export type { VectorStore, VectorStoreResult, SearchFilters } from './types.js';

// Export error classes
export {
	VectorStoreError,
	VectorStoreConnectionError,
	VectorDimensionError,
	CollectionNotFoundError,
} from './types.js';

// Export backend implementations
// Note: Implementations are lazily loaded by the manager to reduce startup time
// export { QdrantBackend } from './qdrant.js';
// export { InMemoryBackend } from './in-memory.js';

// Import the actual Milvus client
import { MilvusClient, DataType } from '@zilliz/milvus2-sdk-node';
import type { VectorStore } from './vector-store.js';
import type { SearchFilters, VectorStoreResult, MilvusBackendConfig } from './types.js';
import { VectorStoreError, VectorStoreConnectionError, VectorDimensionError } from './types.js';
import { Logger, createLogger } from '../../logger/index.js';
import { LOG_PREFIXES, ERROR_MESSAGES } from '../constants.js';
import { env } from '../../env.js';
import { getMilvusConnectionPool, type MilvusConnectionConfig } from '../connection-pool.js';

/**
 * MilvusBackend Class
 *
 * Implements the VectorStore interface for Milvus vector database.
 *
 * Note: Only address (url/host/port) is used for MilvusClient connection.
 * If authentication is needed, extend config and update here.
 */
export class MilvusBackend implements VectorStore {
	private client: MilvusClient | null = null;
	private readonly config: MilvusBackendConfig;
	private readonly collectionName: string;
	private readonly dimension: number;
	private readonly logger: Logger;
	private connected = false;
	private readonly connectionConfig: MilvusConnectionConfig;

	// Milvus collection configuration
	private readonly MILVUS_COLLECTION_CONFIG = {
		schema: [
			{
				name: 'id',
				description: 'Primary key',
				data_type: DataType.Int64,
				is_primary_key: true,
			},
			{
				name: 'vector',
				description: 'Vector field',
				data_type: DataType.FloatVector,
			},
			{
				name: 'payload',
				description: 'Payload',
				data_type: DataType.JSON,
			},
		],
	};

	constructor(config: MilvusBackendConfig) {
		this.config = config;
		this.collectionName = config.collectionName;
		this.dimension = config.dimension;
		this.logger = createLogger({
			level: env.CIPHER_LOG_LEVEL || 'info',
		});

		// Prepare connection configuration for pool
		this.connectionConfig = {
			url: config.url || undefined,
			host: config.host || undefined,
			port: config.port || undefined,
			username: config.username || env.VECTOR_STORE_USERNAME || undefined,
			password: config.password || env.VECTOR_STORE_PASSWORD || undefined,
		} as MilvusConnectionConfig;

		this.logger.debug(`${LOG_PREFIXES.MILVUS} Backend initialized with connection pooling`, {
			collection: this.collectionName,
			dimension: this.dimension,
			connectionKey: this.generateConnectionKey(),
		});
	}

	/**
	 * Generate a connection key for logging (without sensitive data)
	 */
	private generateConnectionKey(): string {
		const address =
			this.connectionConfig.url ||
			(this.connectionConfig.host && this.connectionConfig.port
				? `${this.connectionConfig.host}:${this.connectionConfig.port}`
				: env.VECTOR_STORE_URL);
		return `${address}:${this.connectionConfig.username || 'anonymous'}`;
	}

	/**
	 * Ensure the client is available and connected
	 */
	private ensureClient(): MilvusClient {
		if (!this.client) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'operation');
		}
		return this.client;
	}

	private validateDimension(vector: number[], _operation: string): void {
		if (vector.length !== this.dimension) {
			throw new VectorDimensionError(
				`${ERROR_MESSAGES.INVALID_DIMENSION}: expected ${this.dimension}, got ${vector.length}`,
				this.dimension,
				vector.length
			);
		}
	}

	async connect(): Promise<void> {
		if (this.connected) {
			this.logger.debug(`${LOG_PREFIXES.MILVUS} Already connected`);
			return;
		}

		this.logger.debug(`${LOG_PREFIXES.MILVUS} Connecting to Milvus via connection pool`);

		try {
			// Get client from connection pool
			const connectionPool = getMilvusConnectionPool();
			this.client = await connectionPool.getClient(this.connectionConfig);

			const client = this.ensureClient();
			const collections = await client.showCollections();
			const exists = collections.data.some((c: any) => c.name === this.collectionName);

			if (!exists) {
				this.logger.debug(`${LOG_PREFIXES.MILVUS} Creating collection ${this.collectionName}`);

				// Create schema with vector field dimension
				const schema = this.MILVUS_COLLECTION_CONFIG.schema.map(field =>
					field.name === 'vector' ? { ...field, dim: this.dimension } : { ...field }
				);

				// Create collection with index parameters for Cloud Milvus compatibility
				await client.createCollection({
					collection_name: this.collectionName,
					fields: schema,
					// Include index parameters during collection creation
					index_params: [
						{
							field_name: 'vector',
							index_name: 'vector_index',
							index_type: 'AUTOINDEX',
							metric_type: 'COSINE',
						},
					],
				});

				this.logger.debug(
					`${LOG_PREFIXES.MILVUS} Collection created with indexes: ${this.collectionName}`
				);
			} else {
				this.logger.debug(
					`${LOG_PREFIXES.MILVUS} Collection already exists: ${this.collectionName}`
				);

				// For existing collections, check if indexes exist and create them if needed
				try {
					const indexes = await client.describeIndex({
						collection_name: this.collectionName,
						field_name: 'vector',
					});

					if (!indexes || !indexes.index_descriptions || indexes.index_descriptions.length === 0) {
						this.logger.debug(`${LOG_PREFIXES.MILVUS} Creating missing vector index`);
						await this.createMissingIndexes();
					}
				} catch {
					this.logger.debug(`${LOG_PREFIXES.MILVUS} Creating missing vector index`);
					await this.createMissingIndexes();
				}
			}

			// Load collection
			const clientForLoad = this.ensureClient();
			await clientForLoad.loadCollection({ collection_name: this.collectionName });
			this.connected = true;
			this.logger.debug(`${LOG_PREFIXES.MILVUS} Successfully connected`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.MILVUS} Connection failed`, { error: error });
			if (error instanceof VectorStoreConnectionError) {
				throw error;
			}
			throw new VectorStoreConnectionError(
				ERROR_MESSAGES.CONNECTION_FAILED,
				'milvus',
				error as Error
			);
		}
	}

	/**
	 * Create missing indexes for existing collections
	 * This is a fallback method for collections that were created without indexes
	 */
	private async createMissingIndexes(): Promise<void> {
		try {
			// Create vector index with AUTOINDEX and COSINE metric
			const clientForIndex = this.ensureClient();
			await clientForIndex.createIndex({
				collection_name: this.collectionName,
				field_name: 'vector',
				index_name: 'vector_index',
				index_type: 'AUTOINDEX',
				metric_type: 'COSINE',
			});

			// Create payload field indexes for better filtering performance
			await this.createPayloadFieldIndexes();

			// Reload collection after index creation
			this.logger.debug(`${LOG_PREFIXES.MILVUS} Reloading collection after index creation`);
			const clientForReload = this.ensureClient();
			await clientForReload.loadCollection({ collection_name: this.collectionName });
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.MILVUS} Failed to create indexes and reload collection`);
			throw error;
		}
	}

	/**
	 * Create indexes for payload fields to improve filtering performance
	 */
	private async createPayloadFieldIndexes(): Promise<void> {
		const payloadFields = ['type', 'category', 'sessionId', 'traceId', 'timestamp'];

		for (const fieldName of payloadFields) {
			try {
				this.logger.debug(`${LOG_PREFIXES.MILVUS} Creating index for field: ${fieldName}`);
				const clientForFieldIndex = this.ensureClient();
				await clientForFieldIndex.createIndex({
					collection_name: this.collectionName,
					field_name: `payload.${fieldName}`,
					index_type: 'AUTOINDEX',
				});
			} catch (error) {
				// Continue with other fields even if one fails
				this.logger.warn(
					`${LOG_PREFIXES.MILVUS} Failed to create index for field ${fieldName}:`,
					error
				);
			}
		}
	}

	async insert(vectors: number[][], ids: number[], payloads: Record<string, any>[]): Promise<void> {
		if (!this.connected)
			return Promise.reject(new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'insert'));
		if (vectors.length !== ids.length || vectors.length !== payloads.length) {
			return Promise.reject(
				new VectorStoreError('Vectors, IDs, and payloads must have the same length', 'insert')
			);
		}
		for (const vector of vectors) this.validateDimension(vector, 'insert');
		const data = vectors.map((vector, idx) => ({
			id: ids[idx]!,
			vector,
			payload: payloads[idx],
		}));
		try {
			const clientForInsert = this.ensureClient();
			await clientForInsert.insert({
				collection_name: this.collectionName,
				data,
			});
			this.logger.debug(`Inserted ${vectors.length} vectors`);
		} catch (error) {
			this.logger.error(`Insert failed`, { error: error });
			throw new VectorStoreError('Failed to insert vectors', 'insert', error as Error);
		}
	}

	async search(
		query: number[],
		limit: number = 10,
		filters?: SearchFilters
	): Promise<VectorStoreResult[]> {
		if (!this.connected) throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'search');
		this.validateDimension(query, 'search');
		try {
			const expr = filtersToExpr(filters);
			const searchParams: any = {
				collection_name: this.collectionName,
				data: [query],
				anns_field: 'vector',
				params: { nprobe: 10 },
				limit,
				output_fields: ['id', 'payload'],
				...(expr ? { filter: expr } : {}),
			};
			const clientForSearch = this.ensureClient();
			const res = await clientForSearch.search(searchParams);
			return res.results.map((hit: any) => ({
				id: hit.id,
				score: hit.score,
				payload: hit.payload,
			}));
		} catch (error) {
			this.logger.error(`Search failed`, { error: error });
			throw new VectorStoreError(ERROR_MESSAGES.SEARCH_FAILED, 'search', error as Error);
		}
	}

	async get(vectorId: number): Promise<VectorStoreResult | null> {
		if (!this.connected)
			return Promise.reject(new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'get'));
		try {
			const clientForQuery = this.ensureClient();
			const res = await clientForQuery.query({
				collection_name: this.collectionName,
				output_fields: ['id', 'vector', 'payload'],
				filter: `id == ${vectorId}`,
			});
			if (!res.data.length || !res.data[0]) return null;
			const doc = res.data[0];
			if (!doc) return null;
			return {
				id: vectorId,
				vector: doc.vector,
				payload: doc.payload,
				score: 1.0,
			};
		} catch (error) {
			this.logger.error(`Get failed`, { error: error });
			throw new VectorStoreError('Failed to retrieve vector', 'get', error as Error);
		}
	}

	async update(vectorId: number, vector: number[], payload: Record<string, any>): Promise<void> {
		if (!this.connected)
			return Promise.reject(new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'update'));
		this.validateDimension(vector, 'update');
		try {
			const clientForUpsert = this.ensureClient();
			await clientForUpsert.upsert({
				collection_name: this.collectionName,
				data: [{ id: vectorId, vector, payload }],
			});
			this.logger.debug(`${LOG_PREFIXES.MILVUS} Updated vector ${vectorId}`);
		} catch (error) {
			this.logger.error(`Update failed`, { error: error });
			throw new VectorStoreError('Failed to update vector', 'update', error as Error);
		}
	}

	async delete(vectorId: number): Promise<void> {
		if (!this.connected)
			return Promise.reject(new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'delete'));
		try {
			const clientForDelete = this.ensureClient();
			await clientForDelete.deleteEntities({
				collection_name: this.collectionName,
				expr: `id == ${vectorId}`,
			});
			this.logger.debug(`${LOG_PREFIXES.MILVUS} Deleted vector ${vectorId}`);
		} catch (error) {
			this.logger.error(`Delete failed`, { error: error });
			throw new VectorStoreError('Failed to delete vector', 'delete', error as Error);
		}
	}

	async deleteCollection(): Promise<void> {
		if (!this.connected)
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'deleteCollection');
		try {
			const clientForDrop = this.ensureClient();
			await clientForDrop.dropCollection({ collection_name: this.collectionName });
			this.logger.info(`Deleted collection ${this.collectionName}`);
		} catch (error) {
			this.logger.error(`Delete collection failed`, { error: error });
			throw new VectorStoreError('Failed to delete collection', 'deleteCollection', error as Error);
		}
	}

	async list(
		filters?: SearchFilters,
		limit: number = 10000
	): Promise<[VectorStoreResult[], number]> {
		if (!this.connected) throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'list');
		try {
			const expr = filtersToExpr(filters);
			const queryParams: any = {
				collection_name: this.collectionName,
				output_fields: ['id', 'vector', 'payload'],
				limit,
				...(expr ? { filter: expr } : {}),
			};
			const clientForList = this.ensureClient();
			const res = await clientForList.query(queryParams);
			const results = (res.data || [])
				.map(
					(doc: any) =>
						doc && {
							id: doc.id,
							vector: doc.vector,
							payload: doc.payload,
							score: 1.0,
						}
				)
				.filter(Boolean);
			return [results, results.length];
		} catch (error) {
			this.logger.error(`List failed`, { error: error });
			throw new VectorStoreError('Failed to list vectors', 'list', error as Error);
		}
	}

	async disconnect(): Promise<void> {
		if (this.client) {
			// Release client back to connection pool
			const connectionPool = getMilvusConnectionPool();
			connectionPool.releaseClient(this.connectionConfig);
			this.client = null;
		}
		this.connected = false;
		this.logger.info(`${LOG_PREFIXES.MILVUS} Disconnected and released connection to pool`);
	}

	isConnected(): boolean {
		return this.connected;
	}

	getBackendType(): string {
		return 'milvus';
	}

	getDimension(): number {
		return this.dimension;
	}

	getCollectionName(): string {
		return this.collectionName;
	}

	async listCollections(): Promise<string[]> {
		if (!this.connected)
			return Promise.reject(new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'listCollections'));
		const clientForListCollections = this.ensureClient();
		const collections = await clientForListCollections.showCollections();
		return collections.data.map((c: any) => c.name);
	}
}

function filtersToExpr(filters?: SearchFilters): string | undefined {
	if (!filters) return undefined;
	// Support equality, 'in', and comparison operators (gte, lte, gt, lt)
	return Object.entries(filters)
		.map(([key, value]) => {
			if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
				return `${key} == "${value}"`;
			}
			if (value && typeof value === 'object') {
				// Support 'in' operator
				if ('any' in value && Array.isArray(value.any)) {
					const arr = value.any.map(v => `"${v}"`).join(', ');
					return `${key} in [${arr}]`;
				}
				// Support comparison operators
				const ops: Record<string, string> = { gte: '>=', lte: '<=', gt: '>', lt: '<' };
				return Object.entries(ops)
					.filter(([op]) => op in (value as Record<string, unknown>))
					.map(([op, symbol]) => `${key} ${symbol} ${(value as Record<string, unknown>)[op]}`)
					.join(' && ');
			}
			return '';
		})
		.filter(Boolean)
		.join(' && ');
}

/**
 * Qdrant Vector Store Backend
 *
 * Implementation of the VectorStore interface for Qdrant vector database.
 * Qdrant is a high-performance vector similarity search engine.
 *
 * Features:
 * - High-performance similarity search
 * - Rich filtering capabilities
 * - Persistent storage with optional on-disk vectors
 * - REST and gRPC API support
 *
 * @module vector_storage/backend/qdrant
 */

import { QdrantClient } from '@qdrant/js-client-rest';
import type { VectorStore } from './vector-store.js';
import type { SearchFilters, VectorStoreResult, QdrantBackendConfig } from './types.js';
import { VectorStoreError, VectorStoreConnectionError, VectorDimensionError } from './types.js';
import { Logger, createLogger } from '../../logger/index.js';
import { LOG_PREFIXES, DEFAULTS, ERROR_MESSAGES } from '../constants.js';

/**
 * Qdrant filter structure
 */
interface QdrantFilter {
	must?: QdrantCondition[];
	must_not?: QdrantCondition[];
	should?: QdrantCondition[];
}

/**
 * Qdrant condition for filtering
 */
interface QdrantCondition {
	key: string;
	match?: { value: any };
	range?: { gte?: number; gt?: number; lte?: number; lt?: number };
}

/**
 * QdrantBackend Class
 *
 * Implements the VectorStore interface for Qdrant vector database.
 *
 * @example
 * ```typescript
 * const qdrant = new QdrantBackend({
 *   type: 'qdrant',
 *   host: 'localhost',
 *   port: 6333,
 *   collectionName: 'documents',
 *   dimension: 1536
 * });
 *
 * await qdrant.connect();
 * await qdrant.insert([vector], ['doc1'], [{ title: 'Document' }]);
 * const results = await qdrant.search(queryVector, 10);
 * ```
 */
export class QdrantBackend implements VectorStore {
	private client: QdrantClient;
	private readonly config: QdrantBackendConfig;
	private readonly collectionName: string;
	private readonly dimension: number;
	private readonly logger: Logger;
	private connected = false;

	constructor(config: QdrantBackendConfig) {
		this.config = config;
		this.collectionName = config.collectionName;
		this.dimension = config.dimension;
		this.logger = createLogger({
			level: process.env.LOG_LEVEL || 'info',
		});

		// Initialize client
		if (config.url) {
			// Use URL if provided
			const clientParams: any = {
				url: config.url,
			};
			if (config.apiKey) {
				clientParams.apiKey = config.apiKey;
			}
			this.client = new QdrantClient(clientParams);
		} else {
			// Use host/port
			const params: any = {
				host: config.host || 'localhost',
				port: config.port || DEFAULTS.QDRANT_PORT,
			};

			if (config.apiKey) {
				params.apiKey = config.apiKey;
			}

			this.client = new QdrantClient(params);
		}

		this.logger.debug(`${LOG_PREFIXES.QDRANT} Initialized`, {
			collection: this.collectionName,
			dimension: this.dimension,
			host: config.host || config.url || 'local',
		});
	}

	/**
	 * Convert search filters to Qdrant filter format
	 */
	private createFilter(filters?: SearchFilters): QdrantFilter | undefined {
		if (!filters) return undefined;

		const conditions: QdrantCondition[] = [];

		for (const [key, value] of Object.entries(filters)) {
			if (value === null || value === undefined) continue;

			// Handle range queries
			if (
				typeof value === 'object' &&
				!Array.isArray(value) &&
				('gte' in value || 'gt' in value || 'lte' in value || 'lt' in value)
			) {
				conditions.push({
					key,
					range: value as any,
				});
			}
			// Handle array filters (any/all)
			else if (
				typeof value === 'object' &&
				!Array.isArray(value) &&
				('any' in value || 'all' in value)
			) {
				// Qdrant doesn't have direct any/all support in the same way
				// For 'any', we can use multiple should conditions
				// For 'all', we would need multiple must conditions
				// For now, we'll simplify to match any value
				if ('any' in value && Array.isArray(value.any)) {
					for (const item of value.any) {
						conditions.push({
							key,
							match: { value: item },
						});
					}
				}
			}
			// Handle exact matches
			else {
				conditions.push({
					key,
					match: { value },
				});
			}
		}

		return conditions.length ? { must: conditions } : undefined;
	}

	/**
	 * Validate vector dimension
	 */
	private validateDimension(vector: number[], _operation: any): void {
		if (vector.length !== this.dimension) {
			throw new VectorDimensionError(
				`${ERROR_MESSAGES.INVALID_DIMENSION}: expected ${this.dimension}, got ${vector.length}`,
				this.dimension,
				vector.length
			);
		}
	}

	// Qdrant only supports integer IDs for points in this deployment
	private validateId(id: number): void {
		if (!Number.isInteger(id) || isNaN(id)) {
			throw new VectorStoreError('Qdrant point IDs must be valid integers', 'id');
		}
	}

	// VectorStore implementation

	async insert(vectors: number[][], ids: number[], payloads: Record<string, any>[]): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'insert');
		}

		// Validate inputs
		if (vectors.length !== ids.length || vectors.length !== payloads.length) {
			throw new VectorStoreError('Vectors, IDs, and payloads must have the same length', 'insert');
		}

		// Validate dimensions and IDs
		for (let i = 0; i < vectors.length; i++) {
			const vector = vectors[i];
			const id = ids[i];

			if (!vector) {
				throw new VectorStoreError(`Vector missing at index ${i}`, 'insert');
			}
			if (id === undefined || id === null) {
				throw new VectorStoreError(`ID missing at index ${i}`, 'insert');
			}

			this.validateDimension(vector, 'insert');
			this.validateId(id);
		}

		this.logger.debug(`${LOG_PREFIXES.INDEX} Inserting ${vectors.length} vectors`);

		try {
			const points = vectors.map((vector, idx) => {
				const payload = payloads[idx];
				const id = ids[idx];

				if (!payload) throw new VectorStoreError(`Payload missing at index ${idx}`, 'insert');
				if (!vector) throw new VectorStoreError(`Vector missing at index ${idx}`, 'insert');
				if (id === undefined || id === null)
					throw new VectorStoreError(`ID missing at index ${idx}`, 'insert');

				return {
					id: id, // Always use integer IDs
					vector,
					payload,
				};
			});

			await this.client.upsert(this.collectionName, { points });

			this.logger.debug(`${LOG_PREFIXES.INDEX} Successfully inserted ${vectors.length} vectors`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.INDEX} Insert failed`, { error });
			throw new VectorStoreError('Failed to insert vectors', 'insert', error as Error);
		}
	}

	async search(
		query: number[],
		limit: number = DEFAULTS.SEARCH_LIMIT,
		filters?: SearchFilters
	): Promise<VectorStoreResult[]> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'search');
		}

		this.validateDimension(query, 'search');

		this.logger.debug(`${LOG_PREFIXES.SEARCH} Searching with limit ${limit}`, {
			hasFilters: !!filters,
		});

		try {
			const queryFilter = this.createFilter(filters);

			const searchParams: any = {
				vector: query,
				limit,
				with_vector: true,
				with_payload: true,
			};

			if (queryFilter) {
				searchParams.filter = queryFilter;
			}

			const searchResponse = await this.client.search(this.collectionName, searchParams);
			const results = (searchResponse as any).result || searchResponse;

			const formattedResults = results.map((hit: any) => ({
				id: hit.id,
				score: hit.score,
				payload: hit.payload,
			}));

			this.logger.debug(`${LOG_PREFIXES.SEARCH} Found ${formattedResults.length} results`);

			return formattedResults;
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.SEARCH} Search failed`, { error });
			throw new VectorStoreError(ERROR_MESSAGES.SEARCH_FAILED, 'search', error as Error);
		}
	}

	async get(vectorId: number): Promise<VectorStoreResult | null> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'get');
		}

		this.validateId(vectorId);
		this.logger.debug(`${LOG_PREFIXES.BACKEND} Getting vector ${vectorId}`);

		try {
			const response = await this.client.retrieve(this.collectionName, {
				ids: [vectorId],
				with_vector: true,
				with_payload: true,
			});

			const results = (response as any).result || response;

			if (!results.length) {
				return null;
			}

			const firstResult = results[0];
			if (!firstResult) {
				return null;
			}

			return {
				id: vectorId, // Qdrant uses integer IDs
				vector: (firstResult.vector as number[]) || [],
				payload: firstResult.payload || {},
				score: 1.0,
			};
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.BACKEND} Get failed`, { error });
			throw new VectorStoreError('Failed to retrieve vector', 'get', error as Error);
		}
	}

	async update(vectorId: number, vector: number[], payload: Record<string, any>): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'update');
		}

		this.validateDimension(vector, 'update');
		this.validateId(vectorId);
		this.logger.debug(`${LOG_PREFIXES.BACKEND} Updating vector ${vectorId}`);

		try {
			const point = {
				id: vectorId,
				vector: vector,
				payload,
			};

			await this.client.upsert(this.collectionName, {
				points: [point],
			});

			this.logger.debug(`${LOG_PREFIXES.BACKEND} Successfully updated vector ${vectorId}`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.BACKEND} Update failed`, { error });
			throw new VectorStoreError('Failed to update vector', 'update', error as Error);
		}
	}

	async delete(vectorId: number): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'delete');
		}

		this.validateId(vectorId);
		this.logger.debug(`${LOG_PREFIXES.BACKEND} Deleting vector ${vectorId}`);

		try {
			await this.client.delete(this.collectionName, {
				points: [vectorId],
			});

			this.logger.debug(`${LOG_PREFIXES.BACKEND} Successfully deleted vector ${vectorId}`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.BACKEND} Delete failed`, { error });
			throw new VectorStoreError('Failed to delete vector', 'delete', error as Error);
		}
	}

	async deleteCollection(): Promise<void> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'deleteCollection');
		}

		this.logger.warn(`${LOG_PREFIXES.BACKEND} Deleting collection ${this.collectionName}`);

		try {
			await this.client.deleteCollection(this.collectionName);
			this.logger.info(
				`${LOG_PREFIXES.BACKEND} Successfully deleted collection ${this.collectionName}`
			);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.BACKEND} Delete collection failed`, { error });
			throw new VectorStoreError('Failed to delete collection', 'deleteCollection', error as Error);
		}
	}

	async list(
		filters?: SearchFilters,
		limit: number = 10000
	): Promise<[VectorStoreResult[], number]> {
		if (!this.connected) {
			throw new VectorStoreError(ERROR_MESSAGES.NOT_CONNECTED, 'list');
		}

		this.logger.debug(`${LOG_PREFIXES.BACKEND} Listing vectors`, {
			hasFilters: !!filters,
			limit,
		});

		try {
			const queryFilter = this.createFilter(filters);

			const scrollRequest: any = {
				limit,
				with_payload: true,
				with_vector: true,
			};

			if (queryFilter) {
				scrollRequest.filter = queryFilter;
			}

			const response = await this.client.scroll(this.collectionName, scrollRequest);

			const results = ((response as any).result?.points || response.points || []).map(
				(point: any) => ({
					id: point.id,
					score: 1.0, // Default score for exact match
					payload: point.payload,
				})
			);

			// Get total count
			const countRequest: any = {};
			if (queryFilter) {
				countRequest.filter = queryFilter;
			}

			const countResponse = await this.client.count(this.collectionName, countRequest);

			this.logger.info(`${LOG_PREFIXES.BACKEND} Listed ${results.length} vectors`);

			return [results, countResponse.count];
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.BACKEND} List failed`, { error });
			throw new VectorStoreError('Failed to list vectors', 'list', error as Error);
		}
	}

	async connect(): Promise<void> {
		if (this.connected) {
			this.logger.debug(`${LOG_PREFIXES.QDRANT} Already connected`);
			return;
		}

		this.logger.info(`${LOG_PREFIXES.QDRANT} Connecting to Qdrant`);

		try {
			// Check if collection exists
			const collections = await this.client.getCollections();
			const exists = collections.collections.some(c => c.name === this.collectionName);

			if (!exists) {
				// Create collection
				this.logger.info(`${LOG_PREFIXES.QDRANT} Creating collection ${this.collectionName}`);

				const distanceMap = {
					Cosine: 'Cosine',
					Euclidean: 'Euclid',
					Dot: 'Dot',
					Manhattan: 'Manhattan',
				} as const;

				const distance = this.config.distance || DEFAULTS.QDRANT_DISTANCE;
				const qdrantDistance = distanceMap[distance as keyof typeof distanceMap] || 'Cosine';

				await this.client.createCollection(this.collectionName, {
					vectors: {
						size: this.dimension,
						distance: qdrantDistance,
					},
				});
			} else {
				// Verify dimension matches
				const collectionInfo = await this.client.getCollection(this.collectionName);
				const vectorConfig = collectionInfo?.config?.params?.vectors;

				if (vectorConfig && 'size' in vectorConfig && vectorConfig.size !== this.dimension) {
					throw new VectorStoreConnectionError(
						`Collection ${this.collectionName} exists with different dimension. ` +
							`Expected: ${this.dimension}, got: ${vectorConfig.size}`,
						'qdrant'
					);
				}
			}

			this.connected = true;
			this.logger.info(`${LOG_PREFIXES.QDRANT} Successfully connected`);
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.QDRANT} Connection failed`, { error });

			if (error instanceof VectorStoreConnectionError) {
				throw error;
			}

			throw new VectorStoreConnectionError(
				ERROR_MESSAGES.CONNECTION_FAILED,
				'qdrant',
				error as Error
			);
		}
	}

	async disconnect(): Promise<void> {
		if (!this.connected) {
			this.logger.debug(`${LOG_PREFIXES.QDRANT} Already disconnected`);
			return;
		}

		this.logger.info(`${LOG_PREFIXES.QDRANT} Disconnecting from Qdrant`);

		// Qdrant client doesn't have explicit disconnect
		// Just mark as disconnected
		this.connected = false;

		this.logger.info(`${LOG_PREFIXES.QDRANT} Successfully disconnected`);
	}

	isConnected(): boolean {
		return this.connected;
	}

	getBackendType(): string {
		return 'qdrant';
	}

	getDimension(): number {
		return this.dimension;
	}

	getCollectionName(): string {
		return this.collectionName;
	}
}

/**
 * Vector Storage Backend Types and Error Classes
 *
 * This module defines the core types and error classes for the vector storage system.
 * The vector storage system provides similarity search capabilities for high-dimensional vectors.
 *
 * @module vector_storage/backend/types
 */

import type { VectorStore } from './vector-store.js';

// Re-export the vector store interface for convenience
export type { VectorStore };

// Re-export configuration types from the config module
export type {
	BackendConfig,
	VectorStoreConfig,
	InMemoryBackendConfig,
	QdrantBackendConfig,
	MilvusBackendConfig,
	ChromaBackendConfig,
} from '../config.js';

/**
 * Search filters for vector queries
 *
 * Allows filtering search results based on metadata attached to vectors.
 * Supports exact matches and range queries.
 *
 * @example
 * ```typescript
 * const filters: SearchFilters = {
 *   category: 'documents',
 *   created_at: { gte: startDate, lte: endDate },
 *   tags: { any: ['important', 'reviewed'] }
 * };
 * ```
 */
export interface SearchFilters {
	[key: string]:
		| string
		| number
		| boolean
		| { gte?: number; gt?: number; lte?: number; lt?: number }
		| { any?: Array<string | number> }
		| { all?: Array<string | number> };
}

/**
 * Vector search result
 *
 * Represents a single result from a vector similarity search.
 * Includes the vector ID, similarity score, and associated metadata.
 *
 * @example
 * ```typescript
 * const result: VectorStoreResult = {
 *   id: 'doc-123', // or number for Qdrant
 *   score: 0.95,
 *   payload: {
 *     title: 'Important Document',
 *     category: 'reports',
 *     created_at: 1234567890
 *   }
 * };
 * ```
 */
export interface VectorStoreResult {
	/** Unique identifier for the vector - string for in-memory, number for Qdrant */
	id: string | number;

	/** Similarity score (higher is more similar, range depends on metric) */
	score?: number;

	/** Vector data (only returned if explicitly requested) */
	vector?: number[];

	/** Metadata associated with the vector */
	payload: Record<string, any>;
}

/**
 * Base Vector Storage Error Class
 *
 * All vector storage-related errors extend from this base class.
 * Provides consistent error structure with operation context and optional cause.
 *
 * @example
 * ```typescript
 * throw new VectorStoreError('Failed to index vectors', 'insert', originalError);
 * ```
 */
export class VectorStoreError extends Error {
	constructor(
		override message: string,
		/** The operation that failed (e.g., 'search', 'insert', 'delete', 'connection') */
		public readonly operation: string,
		/** The underlying error that caused this error, if any */
		public override readonly cause?: Error
	) {
		super(message);
		this.name = 'VectorStoreError';
		this.cause = cause;
	}
}

/**
 * Vector Store Connection Error
 *
 * Thrown when a vector store backend fails to connect or loses connection.
 * Includes the backend type for easier debugging.
 *
 * @example
 * ```typescript
 * throw new VectorStoreConnectionError(
 *   'Failed to connect to Qdrant',
 *   'qdrant',
 *   qdrantError
 * );
 * ```
 */
export class VectorStoreConnectionError extends VectorStoreError {
	constructor(
		override message: string,
		/** The type of backend that failed to connect (e.g., 'qdrant', 'pinecone') */
		public readonly backendType: string,
		/** The underlying connection error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'connection', cause);
		this.name = 'VectorStoreConnectionError';
	}
}

/**
 * Vector Dimension Error
 *
 * Thrown when vector dimensions don't match the configured dimension.
 * This is a common error when the embedding model changes.
 *
 * @example
 * ```typescript
 * throw new VectorDimensionError(
 *   `Expected dimension ${expected}, got ${actual}`,
 *   expected,
 *   actual
 * );
 * ```
 */
export class VectorDimensionError extends VectorStoreError {
	constructor(
		override message: string,
		/** The expected vector dimension */
		public readonly expectedDimension: number,
		/** The actual vector dimension received */
		public readonly actualDimension: number,
		/** The underlying error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'dimension_mismatch', cause);
		this.name = 'VectorDimensionError';
	}
}

/**
 * Collection Not Found Error
 *
 * Thrown when attempting to access a collection that doesn't exist.
 *
 * @example
 * ```typescript
 * throw new CollectionNotFoundError(
 *   `Collection '${collectionName}' does not exist`,
 *   collectionName
 * );
 * ```
 */
export class CollectionNotFoundError extends VectorStoreError {
	constructor(
		override message: string,
		/** The name of the collection that was not found */
		public readonly collectionName: string,
		/** The underlying error, if any */
		public override readonly cause?: Error
	) {
		super(message, 'collection_not_found', cause);
		this.name = 'CollectionNotFoundError';
	}
}

/**
 * Transformation strategy for handling complex payload fields
 */
export type PayloadTransformationStrategy =
	| 'json-string' // Serialize complex objects to JSON strings
	| 'dot-notation' // Flatten nested objects using dot notation (e.g., user.name -> user_name)
	| 'comma-separated' // Convert arrays to comma-separated strings
	| 'boolean-flags' // Convert arrays to multiple boolean fields
	| 'preserve'; // Keep as-is (for simple types)

/**
 * Configuration for field transformation
 */
export interface FieldTransformationConfig {
	/** The transformation strategy to use for this field */
	strategy: PayloadTransformationStrategy;
	/** Optional custom transformer function for complex scenarios */
	customTransformer?: {
		serialize: (value: any) => any;
		deserialize: (value: any) => any;
	};
	/** Prefix for flattened or boolean flag fields */
	prefix?: string;
}

/**
 * Payload transformation configuration
 */
export interface PayloadTransformationConfig {
	/** Default strategy for unknown fields */
	defaultStrategy: PayloadTransformationStrategy;
	/** Field-specific transformation rules */
	fieldConfigs: Record<string, FieldTransformationConfig>;
	/** Whether to handle nested objects automatically */
	autoFlattenNested: boolean;
	/** Maximum depth for auto-flattening nested objects */
	maxNestingDepth: number;
}

/**
 * Payload adapter interface for ChromaDB compatibility
 */
export interface ChromaPayloadAdapter {
	/**
	 * Transform a complex payload to ChromaDB-compatible format
	 * @param payload - The original payload with potentially nested data
	 * @returns ChromaDB-compatible flat metadata object
	 */
	serialize(payload: Record<string, any>): Record<string, string | number | boolean>;

	/**
	 * Transform ChromaDB metadata back to original payload format
	 * @param metadata - The flat metadata from ChromaDB
	 * @returns Reconstructed payload object
	 */
	deserialize(metadata: Record<string, any>): Record<string, any>;

	/**
	 * Get the transformation configuration
	 */
	getConfig(): PayloadTransformationConfig;

	/**
	 * Update the transformation configuration
	 */
	updateConfig(config: Partial<PayloadTransformationConfig>): void;
}

/** * Vector Store Interface * * Defines the contract for vector storage implementations. * Vector stores are optimized for similarity search over high-dimensional vectors. * * Implementations can include: * - Qdrant: High-performance vector similarity search engine * - Pinecone: Managed vector database service * - Weaviate: Open-source vector search engine * - In-Memory: Fast local storage for development/testing * * @module vector_storage/backend/vector-store */
import type { SearchFilters, VectorStoreResult } from './types.js';
/** * VectorStore Interface * * Provides a unified API for different vector storage implementations. * All methods are asynchronous to support both local and network-based backends. * * @example * ```typescript * class QdrantBackend implements VectorStore { * async search(query: number[], limit?: number): Promise<VectorStoreResult[]> { * const results = await this.client.search(this.collectionName, { * vector: query, * limit: limit || 10 * }); * return results.map(this.formatResult); * } * // ... other methods * } * ``` */ export interface VectorStore { // Basic vector operations
/** * Insert vectors with their metadata * * @param vectors - Array of embedding vectors * @param ids - Array of unique integer identifiers for each vector * @param payloads - Array of metadata objects for each vector * @throws {VectorDimensionError} If vector dimensions don't match configuration * @throws {VectorStoreError} If insertion fails * * @example * ```typescript * await store.insert( * [embedding1, embedding2], * [1, 2], * [{ title: 'Doc 1' }, { title: 'Doc 2' }] * ); * ``` */ insert(vectors: number[][], ids: number[], payloads: Record<string, any>[]): Promise<void>;
/** * Search for similar vectors * * @param query - Query vector to search for * @param limit - Maximum number of results to return * @param filters - Optional metadata filters * @returns Array of search results sorted by similarity * @throws {VectorDimensionError} If query dimension doesn't match configuration * * @example * ```typescript * const results = await store.search(queryVector, 5, { * category: 'technical', * date: { gte: startDate } * }); * ``` */ search(query: number[], limit?: number, filters?: SearchFilters): Promise<VectorStoreResult[]>;
/** * Retrieve a specific vector by ID * * @param vectorId - The unique integer identifier of the vector * @returns The vector result or null if not found * * @example * ```typescript * const vector = await store.get(123); * if (vector) { * console.log(vector.payload); * } * ``` */ get(vectorId: number): Promise<VectorStoreResult | null>;
/** * Update a vector and its metadata * * @param vectorId - The unique integer identifier of the vector * @param vector - The new embedding vector * @param payload - The new metadata * @throws {VectorDimensionError} If vector dimension doesn't match configuration * * @example * ```typescript * await store.update(123, newEmbedding, { * title: 'Updated Title', * modified_at: Date.now() * }); * ``` */ update(vectorId: number, vector: number[], payload: Record<string, any>): Promise<void>;
/** * Delete a vector * * @param vectorId - The unique integer identifier of the vector to delete * * @example * ```typescript * await store.delete(123); * ``` */ delete(vectorId: number): Promise<void>;
// Collection management
/** * Delete the entire collection * * WARNING: This will permanently delete all vectors in the collection. * * @example * ```typescript * // Use with caution! * await store.deleteCollection(); * ``` */ deleteCollection(): Promise<void>;
/** * List vectors with optional filtering * * @param filters - Optional metadata filters * @param limit - Maximum number of results * @returns Tuple of [results, total count] * * @example * ```typescript * const [vectors, totalCount] = await store.list( * { category: 'documents' }, * 100 * ); * console.log(`Found ${vectors.length} of ${totalCount} total`); * ``` */ list(filters?: SearchFilters, limit?: number): Promise<[VectorStoreResult[], number]>;
// Connection management
/** * Establishes connection to the vector store backend * * Should be called before performing any operations. * Implementations should handle reconnection logic internally. * * @throws {VectorStoreConnectionError} If connection fails * * @example * ```typescript * const store = new QdrantBackend(config); * await store.connect(); * // Now ready to use * ``` */ connect(): Promise<void>;
/** * Gracefully closes the connection to the vector store * * Should clean up resources and close any open connections. * After disconnect, connect() must be called again before use. * * @example * ```typescript * // Clean shutdown * await store.disconnect(); * ``` */ disconnect(): Promise<void>;
/** * Checks if the backend is currently connected and ready * * @returns true if connected and operational, false otherwise * * @example * ```typescript * if (!store.isConnected()) { * await store.connect(); * } * ``` */ isConnected(): boolean;
// Metadata
/** * Returns the backend type identifier * * Useful for logging, monitoring, and conditional logic based on backend type. * * @returns Backend type string (e.g., 'qdrant', 'pinecone', 'in-memory') * * @example * ```typescript * console.log(`Using ${store.getBackendType()} for vector storage`); * ``` */ getBackendType(): string;
/** * Get the configured vector dimension * * @returns The dimension of vectors this store expects * * @example * ```typescript * const dim = store.getDimension(); * console.log(`Store configured for ${dim}-dimensional vectors`); * ``` */ getDimension(): number;
/** * Get the collection name * * @returns The name of the collection this store operates on * * @example * ```typescript * console.log(`Operating on collection: ${store.getCollectionName()}`); * ``` */ getCollectionName(): string; }

/**
 * Vector Storage Configuration Module
 *
 * Defines the configuration schemas for the vector storage system using Zod for
 * runtime validation and type safety. Supports multiple backend types with
 * different configuration requirements.
 *
 * The vector storage system provides similarity search capabilities:
 * - Vector Backend: For similarity search over embeddings
 *
 * Supported backends:
 * - In-Memory: Fast local storage for development/testing
 * - Qdrant: High-performance vector similarity search engine
 * - Milvus: Open-source vector database with horizontal scaling
 * - ChromaDB: Developer-friendly open-source embedding database
 * - Pinecone: Managed vector database service (planned)
 * - Weaviate: Open-source vector search engine (planned)
 *
 * @module vector_storage/config
 */

import { z } from 'zod';
import { DEFAULTS, DISTANCE_METRICS } from './constants.js';

/**
 * Base Vector Store Configuration Schema
 *
 * Common configuration options shared by all vector store types.
 * These options control collection settings and connection behavior.
 */
const BaseVectorStoreSchema = z.object({
	/** Name of the collection/index to use */
	collectionName: z.string().min(1).describe('Collection name'),

	/** Dimension of vectors (must match embedding model output) */
	dimension: z.number().int().positive().default(DEFAULTS.DIMENSION).describe('Vector dimension'),

	/** Maximum number of concurrent connections */
	maxConnections: z.number().int().positive().optional().describe('Maximum connections'),

	/** Connection timeout in milliseconds */
	connectionTimeoutMillis: z.number().int().positive().optional().describe('Connection timeout'),

	/** Backend-specific options */
	options: z.record(z.any()).optional().describe('Backend-specific options'),
});

/**
 * In-Memory Vector Store Configuration
 *
 * Simple in-memory vector storage for development and testing.
 * Data is lost when the process exits.
 *
 * @example
 * ```typescript
 * const config: InMemoryBackendConfig = {
 *   type: 'in-memory',
 *   collectionName: 'test_vectors',
 *   dimension: 1536,
 *   maxVectors: 10000
 * };
 * ```
 */
const InMemoryBackendSchema = BaseVectorStoreSchema.extend({
	type: z.literal('in-memory'),

	/** Maximum number of vectors to store (prevents memory overflow) */
	maxVectors: z.number().int().positive().default(10000).describe('Maximum vectors to store'),
}).strict();

export type InMemoryBackendConfig = z.infer<typeof InMemoryBackendSchema>;

/**
 * Qdrant Backend Configuration
 *
 * Configuration for Qdrant vector database backend.
 * Supports both direct connection parameters and connection URLs.
 *
 * @example
 * ```typescript
 * // Using connection URL
 * const config: QdrantBackendConfig = {
 *   type: 'qdrant',
 *   url: 'http://localhost:6333',
 *   collectionName: 'documents',
 *   dimension: 1536
 * };
 *
 * // Using individual parameters
 * const config: QdrantBackendConfig = {
 *   type: 'qdrant',
 *   host: 'localhost',
 *   port: 6333,
 *   apiKey: 'secret',
 *   collectionName: 'documents',
 *   dimension: 1536
 * };
 * ```
 */
const QdrantBackendSchema = BaseVectorStoreSchema.extend({
	type: z.literal('qdrant'),

	/** Qdrant connection URL (http://...) - overrides individual params if provided */
	url: z.string().url().optional().describe('Qdrant connection URL'),

	/** Qdrant server hostname */
	host: z.string().optional().describe('Qdrant host'),

	/** Qdrant REST API port (default: 6333) */
	port: z
		.number()
		.int()
		.positive()
		.default(DEFAULTS.QDRANT_PORT)
		.optional()
		.describe('Qdrant port'),

	/** Qdrant API key for authentication */
	apiKey: z.string().optional().describe('Qdrant API key'),

	/** Store vectors on disk (for large datasets) */
	onDisk: z.boolean().optional().describe('Store vectors on disk'),

	/** Path for local Qdrant storage (if not using remote server) */
	path: z.string().optional().describe('Local storage path'),

	/** Distance metric for similarity search */
	distance: z
		.enum([
			DISTANCE_METRICS.COSINE,
			DISTANCE_METRICS.EUCLIDEAN,
			DISTANCE_METRICS.DOT_PRODUCT,
			DISTANCE_METRICS.MANHATTAN,
		] as const)
		.default(DEFAULTS.QDRANT_DISTANCE)
		.optional()
		.describe('Distance metric'),
}).strict();

export type QdrantBackendConfig = z.infer<typeof QdrantBackendSchema>;

/**
 * Milvus Backend Configuration
 *
 * Configuration for Milvus vector database backend.
 *
 * @example
 * ```typescript
 * const config: MilvusBackendConfig = {
 *   type: 'milvus',
 *   url: 'http://localhost:19530',
 *   collectionName: 'documents',
 *   dimension: 1536
 * };
 * ```
 */
const MilvusBackendSchema = BaseVectorStoreSchema.extend({
	type: z.literal('milvus'),

	/** Milvus connection URL (http://...) - overrides individual params if provided */
	url: z.string().url().optional().describe('Milvus connection URL'),

	/** Milvus server hostname */
	host: z.string().optional().describe('Milvus host'),

	/** Milvus REST API port (default: 19530) */
	port: z.number().int().positive().default(19530).optional().describe('Milvus port'),

	/** Milvus username for authentication (Zilliz Cloud) */
	username: z.string().optional().describe('Milvus username'),

	/** Milvus password for authentication (Zilliz Cloud) */
	password: z.string().optional().describe('Milvus password'),

	/** Milvus API token for authentication (Zilliz Cloud) */
	token: z.string().optional().describe('Milvus API token'),
}).strict();

export type MilvusBackendConfig = z.infer<typeof MilvusBackendSchema>;

/**
 * ChromaDB Backend Configuration
 *
 * Configuration for ChromaDB vector database backend.
 * Supports both HTTP client connection and embedded mode.
 *
 * @example
 * ```typescript
 * // Using connection URL
 * const config: ChromaBackendConfig = {
 *   type: 'chroma',
 *   url: 'http://localhost:8000',
 *   collectionName: 'documents',
 *   dimension: 1536
 * };
 *
 * // Using individual parameters
 * const config: ChromaBackendConfig = {
 *   type: 'chroma',
 *   host: 'localhost',
 *   port: 8000,
 *   collectionName: 'documents',
 *   dimension: 1536,
 *   headers: { 'Authorization': 'Bearer token' }
 * };
 * ```
 */
const ChromaBackendSchema = BaseVectorStoreSchema.extend({
	type: z.literal('chroma'),

	/** ChromaDB connection URL (http://...) - overrides individual params if provided */
	url: z.string().url().optional().describe('ChromaDB connection URL'),

	/** ChromaDB server hostname */
	host: z.string().optional().describe('ChromaDB host'),

	/** ChromaDB HTTP port (default: 8000) */
	port: z.number().int().positive().default(8000).optional().describe('ChromaDB port'),

	/** Use SSL/TLS for connection (default: false) */
	ssl: z.boolean().default(false).optional().describe('Use SSL/TLS for connection'),

	/** Custom HTTP headers for authentication */
	headers: z.record(z.string()).optional().describe('Custom HTTP headers'),

	/** Distance metric for similarity search */
	distance: z
		.enum(['cosine', 'l2', 'euclidean', 'ip', 'dot'] as const)
		.default('cosine')
		.optional()
		.describe('Distance metric'),

	/** Custom path for ChromaDB API endpoints */
	path: z.string().optional().describe('Custom API path'),
}).strict();

export type ChromaBackendConfig = z.infer<typeof ChromaBackendSchema>;

/**
 * Backend Configuration Union Schema
 *
 * Discriminated union of all supported backend configurations.
 * Uses the 'type' field to determine which configuration schema to apply.
 *
 * Includes custom validation to ensure backends have required connection info.
 */
const BackendConfigSchema = z
	.discriminatedUnion(
		'type',
		[InMemoryBackendSchema, QdrantBackendSchema, MilvusBackendSchema, ChromaBackendSchema],
		{
			errorMap: (issue, ctx) => {
				if (issue.code === z.ZodIssueCode.invalid_union_discriminator) {
					return {
						message: `Invalid backend type. Expected 'in-memory', 'qdrant', 'milvus', or 'chroma'.`,
					};
				}
				return { message: ctx.defaultError };
			},
		}
	)
	.describe('Backend configuration for vector storage system')
	.superRefine((data, ctx) => {
		// Validate Qdrant backend requirements
		if (data.type === 'qdrant') {
			// Qdrant requires either a connection URL or a host
			if (!data.url && !data.host) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					message: "Qdrant backend requires either 'url' or 'host' to be specified",
					path: ['url'],
				});
			}
		}
		// Validate Milvus backend requirements
		if (data.type === 'milvus') {
			if (!data.url && !data.host) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					message: "Milvus backend requires either 'url' or 'host' to be specified",
					path: ['url'],
				});
			}
		}
		// Validate ChromaDB backend requirements
		if (data.type === 'chroma') {
			// ChromaDB requires either a connection URL or a host
			if (!data.url && !data.host) {
				ctx.addIssue({
					code: z.ZodIssueCode.custom,
					message: "ChromaDB backend requires either 'url' or 'host' to be specified",
					path: ['url'],
				});
			}
		}
		// Validate collection name format
		if (!/^[a-zA-Z0-9_-]+$/.test(data.collectionName)) {
			ctx.addIssue({
				code: z.ZodIssueCode.custom,
				message: 'Collection name must contain only letters, numbers, underscores, and hyphens',
				path: ['collectionName'],
			});
		}
	});

export type BackendConfig = z.infer<typeof BackendConfigSchema>;

/**
 * Vector Storage System Configuration Schema
 *
 * Top-level configuration for the vector storage system.
 * Unlike the dual-backend storage system, vector storage uses a single backend.
 *
 * @example
 * ```typescript
 * const vectorConfig: VectorStoreConfig = {
 *   type: 'qdrant',
 *   host: 'localhost',
 *   port: 6333,
 *   collectionName: 'embeddings',
 *   dimension: 1536
 * };
 * ```
 */
export const VectorStoreSchema = BackendConfigSchema;

export type VectorStoreConfig = z.infer<typeof VectorStoreSchema>;

import { MilvusClient } from '@zilliz/milvus2-sdk-node';
import { logger } from '../logger/index.js';
import { env } from '../env.js';

/**
 * Connection configuration for Milvus client pool
 */
export interface MilvusConnectionConfig {
	url?: string;
	host?: string;
	port?: number;
	username?: string;
	password?: string;
}

/**
 * Pooled connection information
 */
interface PooledConnection {
	client: MilvusClient;
	createdAt: number;
	lastUsed: number;
	isHealthy: boolean;
	refCount: number; // Reference count for active usage
}

/**
 * Thread-safe singleton connection pool for Milvus clients
 * Reduces duplicate TCP connections by sharing client instances across collections
 */
export class MilvusConnectionPool {
	private static instance: MilvusConnectionPool | null = null;
	private connections: Map<string, PooledConnection> = new Map();
	private readonly maxConnections = 10; // Prevent connection bloat
	private readonly connectionTtl = 300000; // 5 minutes TTL
	private readonly healthCheckInterval = 60000; // 1 minute health checks
	private healthCheckTimer?: NodeJS.Timeout;

	private constructor() {
		// Private constructor for singleton pattern
		this.startHealthCheckTimer();
	}

	/**
	 * Get the singleton instance of MilvusConnectionPool
	 */
	static getInstance(): MilvusConnectionPool {
		if (!MilvusConnectionPool.instance) {
			MilvusConnectionPool.instance = new MilvusConnectionPool();
		}
		return MilvusConnectionPool.instance;
	}

	/**
	 * Generate a unique connection key based on configuration
	 */
	private generateConnectionKey(config: MilvusConnectionConfig): string {
		// Normalize the configuration for consistent keying
		const address =
			config.url ||
			(config.host && config.port ? `http://${config.host}:${config.port}` : env.VECTOR_STORE_URL);
		const username = config.username || env.VECTOR_STORE_USERNAME || '';
		const password = config.password ? '[REDACTED]' : ''; // Don't include actual password in key

		return `${address}:${username}:${!!password}`;
	}

	/**
	 * Get or create a Milvus client from the pool
	 */
	async getClient(config: MilvusConnectionConfig): Promise<MilvusClient> {
		const connectionKey = this.generateConnectionKey(config);

		// Check if connection exists and is healthy
		const existingConnection = this.connections.get(connectionKey);
		if (existingConnection && existingConnection.isHealthy) {
			// Update usage tracking
			existingConnection.lastUsed = Date.now();
			existingConnection.refCount++;

			logger.debug('MilvusConnectionPool: Reusing existing connection', {
				connectionKey,
				refCount: existingConnection.refCount,
				poolSize: this.connections.size,
			});

			return existingConnection.client;
		}

		// Remove unhealthy connection if it exists
		if (existingConnection && !existingConnection.isHealthy) {
			logger.debug('MilvusConnectionPool: Removing unhealthy connection', { connectionKey });
			this.connections.delete(connectionKey);
		}

		// Enforce max connections limit with LRU eviction
		if (this.connections.size >= this.maxConnections) {
			await this.evictLeastRecentlyUsedConnection();
		}

		// Create new connection
		logger.debug('MilvusConnectionPool: Creating new connection', {
			connectionKey,
			poolSize: this.connections.size,
		});

		const client = await this.createMilvusClient(config);
		const pooledConnection: PooledConnection = {
			client,
			createdAt: Date.now(),
			lastUsed: Date.now(),
			isHealthy: true,
			refCount: 1,
		};

		this.connections.set(connectionKey, pooledConnection);

		logger.debug('MilvusConnectionPool: Connection created and pooled', {
			connectionKey,
			poolSize: this.connections.size,
		});

		return client;
	}

	/**
	 * Release a client reference (decrement ref count)
	 */
	releaseClient(config: MilvusConnectionConfig): void {
		const connectionKey = this.generateConnectionKey(config);
		const connection = this.connections.get(connectionKey);

		if (connection) {
			connection.refCount = Math.max(0, connection.refCount - 1);
			logger.debug('MilvusConnectionPool: Client reference released', {
				connectionKey,
				refCount: connection.refCount,
			});
		}
	}

	/**
	 * Create a new Milvus client with the given configuration
	 */
	private async createMilvusClient(config: MilvusConnectionConfig): Promise<MilvusClient> {
		// Normalize configuration similar to existing backend
		const address =
			config.url ||
			(config.host && config.port
				? `http://${config.host}:${config.port}`
				: env.VECTOR_STORE_URL || '');
		const username = config.username || env.VECTOR_STORE_USERNAME || '';
		const password = config.password || env.VECTOR_STORE_PASSWORD || '';

		try {
			const client = new MilvusClient({
				address,
				username,
				password,
			});

			// Test the connection by trying to list collections
			await client.showCollections();

			return client;
		} catch (error) {
			logger.error('MilvusConnectionPool: Failed to create client', {
				error: error instanceof Error ? error.message : String(error),
				address,
			});
			throw error;
		}
	}

	/**
	 * Evict the least recently used connection to make room for new ones
	 */
	private async evictLeastRecentlyUsedConnection(): Promise<void> {
		let oldestKey: string | null = null;
		let oldestTime = Date.now();

		// Find connection with lowest ref count first, then oldest last used
		for (const [key, connection] of this.connections) {
			if (connection.refCount === 0 && connection.lastUsed < oldestTime) {
				oldestTime = connection.lastUsed;
				oldestKey = key;
			}
		}

		// If no unused connections, find least recently used with references
		if (!oldestKey) {
			for (const [key, connection] of this.connections) {
				if (connection.lastUsed < oldestTime) {
					oldestTime = connection.lastUsed;
					oldestKey = key;
				}
			}
		}

		if (oldestKey) {
			logger.debug('MilvusConnectionPool: Evicting LRU connection', {
				evictedKey: oldestKey,
				poolSize: this.connections.size,
			});

			await this.closeConnection(oldestKey);
		}
	}

	/**
	 * Start periodic health check timer
	 */
	private startHealthCheckTimer(): void {
		this.healthCheckTimer = setInterval(() => {
			this.performHealthChecks();
		}, this.healthCheckInterval);
	}

	/**
	 * Perform health checks on all pooled connections
	 */
	private async performHealthChecks(): Promise<void> {
		const now = Date.now();
		const connectionsToRemove: string[] = [];

		for (const [key, connection] of this.connections) {
			// Check if connection has expired
			if (now - connection.createdAt > this.connectionTtl) {
				logger.debug('MilvusConnectionPool: Connection expired', { key });
				connectionsToRemove.push(key);
				continue;
			}

			// Check if connection is healthy
			try {
				await connection.client.showCollections();
				connection.isHealthy = true;
			} catch (error) {
				logger.warn('MilvusConnectionPool: Connection health check failed', {
					key,
					error: error instanceof Error ? error.message : String(error),
				});
				connection.isHealthy = false;
				if (connection.refCount === 0) {
					connectionsToRemove.push(key);
				}
			}
		}

		// Remove unhealthy or expired connections
		for (const key of connectionsToRemove) {
			await this.closeConnection(key);
		}

		if (connectionsToRemove.length > 0) {
			logger.debug('MilvusConnectionPool: Health check completed', {
				removedConnections: connectionsToRemove.length,
				remainingConnections: this.connections.size,
			});
		}
	}

	/**
	 * Close and remove a connection from the pool
	 */
	private async closeConnection(key: string): Promise<void> {
		const connection = this.connections.get(key);
		if (connection) {
			try {
				// MilvusClient doesn't have an explicit close method
				// The connection will be cleaned up when the object is garbage collected
				this.connections.delete(key);
				logger.debug('MilvusConnectionPool: Connection closed and removed', { key });
			} catch (error) {
				logger.warn('MilvusConnectionPool: Error closing connection', {
					key,
					error: error instanceof Error ? error.message : String(error),
				});
				// Still remove it from the pool even if close failed
				this.connections.delete(key);
			}
		}
	}

	/**
	 * Get pool statistics for monitoring
	 */
	getStats(): {
		totalConnections: number;
		maxConnections: number;
		connectionDetails: Array<{
			key: string;
			createdAt: number;
			lastUsed: number;
			refCount: number;
			isHealthy: boolean;
			age: number;
		}>;
	} {
		const now = Date.now();
		const connectionDetails = Array.from(this.connections.entries()).map(([key, connection]) => ({
			key,
			createdAt: connection.createdAt,
			lastUsed: connection.lastUsed,
			refCount: connection.refCount,
			isHealthy: connection.isHealthy,
			age: now - connection.createdAt,
		}));

		return {
			totalConnections: this.connections.size,
			maxConnections: this.maxConnections,
			connectionDetails,
		};
	}

	/**
	 * Force close all connections and cleanup
	 */
	async shutdown(): Promise<void> {
		if (this.healthCheckTimer) {
			clearInterval(this.healthCheckTimer);
			this.healthCheckTimer = undefined as any;
		}

		const connectionKeys = Array.from(this.connections.keys());
		await Promise.allSettled(connectionKeys.map(key => this.closeConnection(key)));

		logger.debug('MilvusConnectionPool: Shutdown completed', {
			closedConnections: connectionKeys.length,
		});
	}

	/**
	 * Get current pool size
	 */
	size(): number {
		return this.connections.size;
	}

	/**
	 * Check if a connection exists for the given config
	 */
	hasConnection(config: MilvusConnectionConfig): boolean {
		const connectionKey = this.generateConnectionKey(config);
		const connection = this.connections.get(connectionKey);
		return connection !== undefined && connection.isHealthy;
	}
}

/**
 * Convenience function to get the global connection pool instance
 */
export const getMilvusConnectionPool = (): MilvusConnectionPool => {
	return MilvusConnectionPool.getInstance();
};

