			port,
			headers,
			distance,
		};
	} else {
		return {
			type: 'in-memory',
			collectionName,
			dimension,
			maxVectors,
		};
	}
}

/**
 * Multi Collection Vector Factory interface for workspace memory support
 */
export interface MultiCollectionVectorFactory {
	/** The multi collection manager instance */
	manager: any; // MultiCollectionVectorManager
	/** The knowledge vector store ready for use */
	knowledgeStore: VectorStore;
	/** The reflection vector store ready for use (null if disabled) */
	reflectionStore: VectorStore | null;
	/** The workspace vector store ready for use (null if disabled) */
	workspaceStore: VectorStore | null;
}

/**
 * Creates multi-collection vector storage from environment variables
 *
 * Creates a multi-collection manager that handles knowledge, reflection, and workspace
 * memory collections. This replaces DualCollectionVectorManager when workspace memory is enabled.
 *
 * @param agentConfig - Optional agent configuration to override dimension from embedding config
 * @returns Promise resolving to multi collection manager and stores
 */
export async function createMultiCollectionVectorStoreFromEnv(
	agentConfig?: any
): Promise<MultiCollectionVectorFactory> {
	const logger = createLogger({ level: env.CIPHER_LOG_LEVEL });

	// Import MultiCollectionVectorManager dynamically to avoid circular dependencies
	// const { MultiCollectionVectorManager } = await import('./multi-collection-manager.js'); // Not used in this scope

	// Get base configuration from environment variables
	const config = getVectorStoreConfigFromEnv(agentConfig);

	// Use ServiceCache to prevent duplicate multi collection vector store creation
	const serviceCache = getServiceCache();
	const cacheKey = createServiceKey('multiCollectionVectorStore', {
		type: config.type,
		collection: config.collectionName,
		reflectionCollection: env.REFLECTION_VECTOR_STORE_COLLECTION || '',
		workspaceCollection: env.WORKSPACE_VECTOR_STORE_COLLECTION || 'workspace_memory',
		workspaceEnabled: !!env.USE_WORKSPACE_MEMORY,
		// Include dimension for proper cache key differentiation
		dimension: config.dimension,
	});

	return await serviceCache.getOrCreate(cacheKey, async () => {
		logger.debug('Creating new multi collection vector store instance');
		return await createMultiCollectionVectorStoreInternal(config, logger);
	});
}

async function createMultiCollectionVectorStoreInternal(
	config: VectorStoreConfig,
	logger: any
): Promise<MultiCollectionVectorFactory> {
	// Import MultiCollectionVectorManager dynamically
	const { MultiCollectionVectorManager } = await import('./multi-collection-manager.js');

	logger.info(`${LOG_PREFIXES.FACTORY} Creating multi collection vector storage from environment`, {
		type: config.type,
		knowledgeCollection: config.collectionName,
		reflectionCollection: env.REFLECTION_VECTOR_STORE_COLLECTION || 'disabled',
		workspaceCollection: env.USE_WORKSPACE_MEMORY
			? env.WORKSPACE_VECTOR_STORE_COLLECTION || 'workspace_memory'
			: 'disabled',
		workspaceEnabled: !!env.USE_WORKSPACE_MEMORY,
	});

	// Create multi collection manager
	const manager = new MultiCollectionVectorManager(config);

	try {
		const connected = await manager.connect();

		if (!connected) {
			throw new Error('Failed to connect multi collection vector manager');
		}

		const knowledgeStore = manager.getStore('knowledge');
		const reflectionStore = manager.getStore('reflection');
		const workspaceStore = manager.getStore('workspace');

		if (!knowledgeStore) {
			throw new Error('Failed to get knowledge store from multi collection manager');
		}

		logger.info(`${LOG_PREFIXES.FACTORY} Multi collection vector storage created successfully`, {
			knowledge: !!knowledgeStore,
			reflection: !!reflectionStore,
			workspace: !!workspaceStore,
		});

		return {
			manager,
			knowledgeStore,
			reflectionStore,
			workspaceStore,
		};
	} catch (error) {
		// If connection fails, ensure cleanup
		await manager.disconnect().catch(() => {
			// Ignore disconnect errors during cleanup
		});

		logger.error(
			`${LOG_PREFIXES.FACTORY} Failed to create multi collection vector storage system`,
			{
				error: error instanceof Error ? error.message : String(error),
			}
		);

		throw error;
	}
}

/**
 * Creates workspace memory vector storage from environment variables
 *
 * Reads workspace memory vector storage configuration from environment variables and creates
 * the vector storage system specifically for workspace memory. Falls back to default
 * vector store configuration if workspace-specific variables are not set.
 *
 * Environment variables (with fallbacks to default VECTOR_STORE_* variables):
 * - WORKSPACE_VECTOR_STORE_TYPE: Backend type (qdrant, milvus, chroma, in-memory)
 * - WORKSPACE_VECTOR_STORE_HOST: Host (fallback to VECTOR_STORE_HOST)
 * - WORKSPACE_VECTOR_STORE_PORT: Port (fallback to VECTOR_STORE_PORT)
 * - WORKSPACE_VECTOR_STORE_URL: URL (fallback to VECTOR_STORE_URL)
 * - WORKSPACE_VECTOR_STORE_API_KEY: API key (fallback to VECTOR_STORE_API_KEY)
 * - WORKSPACE_VECTOR_STORE_COLLECTION: Collection name (default: workspace_memory)
 * - WORKSPACE_VECTOR_STORE_DIMENSION: Vector dimension (fallback to VECTOR_STORE_DIMENSION)
 * - WORKSPACE_VECTOR_STORE_DISTANCE: Distance metric for Qdrant (fallback to VECTOR_STORE_DISTANCE)
 * - WORKSPACE_VECTOR_STORE_ON_DISK: Store vectors on disk (default: false)
 * - WORKSPACE_VECTOR_STORE_MAX_VECTORS: Maximum vectors for in-memory storage
 *
 * @param agentConfig - Optional agent configuration to override dimension from embedding config
 * @returns Promise resolving to manager and connected workspace vector store
 *
 * @example
 * ```typescript
 * // Set workspace-specific environment variables
 * process.env.WORKSPACE_VECTOR_STORE_TYPE = 'milvus';
 * process.env.WORKSPACE_VECTOR_STORE_HOST = 'localhost';
 * process.env.WORKSPACE_VECTOR_STORE_COLLECTION = 'team_workspace';
 *
 * const { manager, store } = await createWorkspaceVectorStoreFromEnv();
 * ```
 */
export async function createWorkspaceVectorStoreFromEnv(
	agentConfig?: any
): Promise<VectorStoreFactory> {
	const logger = createLogger({ level: env.CIPHER_LOG_LEVEL });

	// Get workspace-specific configuration from environment variables
	const config = getWorkspaceVectorStoreConfigFromEnv(agentConfig);

	logger.info(`${LOG_PREFIXES.FACTORY} Creating workspace memory vector storage from environment`, {
		type: config.type,
		collection: config.collectionName,
		dimension: config.dimension,
		workspaceSpecific: config.collectionName !== env.VECTOR_STORE_COLLECTION,
	});

	return createVectorStore(config);
}

/**
 * Type guard to check if an object is a VectorStoreFactory
 *
 * @param obj - Object to check
 * @returns true if the object has manager and store properties
 */
export function isVectorStoreFactory(obj: unknown): obj is VectorStoreFactory {
	return (
		typeof obj === 'object' &&
		obj !== null &&
		'manager' in obj &&
		'store' in obj &&
		obj.manager instanceof VectorStoreManager
	);
}

/**
 * Check if Qdrant configuration is available in environment
 */
export function isQdrantConfigAvailable(): boolean {
	return !!(
		process.env.VECTOR_STORE_URL ||
		process.env.VECTOR_STORE_HOST ||
		process.env.VECTOR_STORE_PORT
	);
}

/**
 * Vector Storage Module
 *
 * High-performance vector storage and similarity search for embeddings.
 * Supports multiple backends with a unified API.
 *
 * Features:
 * - Multiple backend support (Qdrant, In-Memory, etc.)
 * - Similarity search with metadata filtering
 * - Batch operations for efficient indexing
 * - Type-safe configuration with runtime validation
 * - Graceful fallback to in-memory storage
 *
 * @module vector_storage
 *
 * @example
 * ```typescript
 * import { createVectorStore } from './vector_storage';
 *
 * // Create a vector store
 * const { store, manager } = await createVectorStore({
 *   type: 'qdrant',
 *   host: 'localhost',
 *   port: 6333,
 *   collectionName: 'documents',
 *   dimension: 1536
 * });
 *
 * // Index vectors
 * await store.insert(
 *   [embedding1, embedding2],
 *   ['doc1', 'doc2'],
 *   [{ title: 'Doc 1' }, { title: 'Doc 2' }]
 * );
 *
 * // Search for similar vectors
 * const results = await store.search(queryEmbedding, 5);
 *
 * // Cleanup
 * await manager.disconnect();
 * ```
 */

// Export types
export type {
	VectorStore,
	VectorStoreResult,
	SearchFilters,
	VectorStoreConfig,
	BackendConfig,
} from './types.js';

// Export error classes
export {
	VectorStoreError,
	VectorStoreConnectionError,
	VectorDimensionError,
	CollectionNotFoundError,
} from './backend/types.js';

// Export factory functions
export {
	createVectorStore,
	createDefaultVectorStore,
	createVectorStoreFromEnv,
	createDualCollectionVectorStoreFromEnv,
	createMultiCollectionVectorStoreFromEnv,
	getVectorStoreConfigFromEnv,
	createWorkspaceVectorStoreFromEnv,
	getWorkspaceVectorStoreConfigFromEnv,
	isVectorStoreFactory,
	type VectorStoreFactory,
	type DualCollectionVectorFactory,
	type MultiCollectionVectorFactory,
} from './factory.js';

// Export managers
export { VectorStoreManager, type HealthCheckResult, type VectorStoreInfo } from './manager.js';
export { DualCollectionVectorManager, type CollectionType } from './dual-collection-manager.js';

// Export constants for external use
export { BACKEND_TYPES, DEFAULTS, DISTANCE_METRICS } from './constants.js';

/**
 * Vector Storage Manager Implementation
 *
 * Orchestrates the vector storage system with backend management.
 * Provides lazy loading, graceful fallbacks, and connection management.
 *
 * @module vector_storage/manager
 */

import type { VectorStore, VectorStoreConfig } from './types.js';
import { VectorStoreSchema } from './config.js';
import { Logger, createLogger } from '../logger/index.js';
import { LOG_PREFIXES, ERROR_MESSAGES, TIMEOUTS, BACKEND_TYPES } from './constants.js';
import { EventManager } from '../events/event-manager.js';
import { ServiceEvents } from '../events/event-types.js';
import { EventAwareVectorStore } from './event-aware-store.js';

/**
 * Health check result for vector store backend
 */
export interface HealthCheckResult {
	backend: boolean;
	overall: boolean;
	details?: {
		backend?: { status: string; latency?: number; error?: string };
	};
}

/**
 * Vector storage system information
 */
export interface VectorStoreInfo {
	connected: boolean;
	backend: {
		type: string;
		connected: boolean;
		fallback: boolean;
		collectionName: string;
		dimension: number;
	};
	connectionAttempts: number;
	lastError: string | undefined;
}

/**
 * Vector Storage Manager
 *
 * Manages the lifecycle of vector storage backend with lazy loading and fallback support.
 * Follows the factory pattern with graceful degradation to in-memory storage.
 *
 * @example
 * ```typescript
 * const manager = new VectorStoreManager(config);
 * const store = await manager.connect();
 *
 * // Use vector store
 * await store.insert([vector], ['id1'], [{ title: 'Document' }]);
 * const results = await store.search(queryVector, 5);
 *
 * // Cleanup
 * await manager.disconnect();
 * ```
 */
export class VectorStoreManager {
	// Core state
	private store: VectorStore | undefined;
	private connected = false;
	private readonly config: VectorStoreConfig;
	private readonly logger: Logger;
	private eventManager?: EventManager;

	// Connection tracking
	private connectionAttempts = 0;
	private lastConnectionError?: Error;

	// Backend metadata
	private backendMetadata = {
		type: 'unknown',
		isFallback: false,
		connectionTime: 0,
	};

	// Lazy loading module references (static to share across instances)
	private static qdrantModule?: any;
	private static inMemoryModule?: any;
	private static milvusModule?: any;
	private static chromaModule?: any;

	// In VectorStoreManager, track if in-memory is used as fallback or primary
	private usedFallback = false;
	private factoryFallback = false;

	/**
	 * Creates a new VectorStoreManager instance
	 *
	 * @param config - Vector storage configuration
	 * @throws {Error} If configuration is invalid
	 */
	constructor(config: VectorStoreConfig) {
		// Check for factory-level fallback marker before validation
		const configWithFallback = config as any;
		if (configWithFallback._fallbackFrom) {
			this.factoryFallback = true;
			this.usedFallback = true;
			// Remove the marker before validation
			delete configWithFallback._fallbackFrom;
		}

		// Validate configuration using Zod schema
		const validationResult = VectorStoreSchema.safeParse(config);
		if (!validationResult.success) {
			throw new Error(
				`${ERROR_MESSAGES.INVALID_CONFIG}: ${validationResult.error.errors
					.map(e => `${e.path.join('.')}: ${e.message}`)
					.join(', ')}`
			);
		}

		this.config = validationResult.data;
		this.logger = createLogger({
			level: process.env.LOG_LEVEL || 'info',
		});

		// Use debug level to reduce redundant logging when used in dual collection setup
		this.logger.debug(`${LOG_PREFIXES.MANAGER} Initialized with configuration`, {
			type: this.config.type,
			collection: this.config.collectionName,
			dimension: this.config.dimension,
			fallback: this.usedFallback,
		});
	}

	/**
	 * Set the event manager for emitting memory operation events
	 */
	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
	}

	/**
	 * Get the current vector storage configuration
	 *
	 * @returns The vector storage configuration
	 */
	public getConfig(): Readonly<VectorStoreConfig> {
		return this.config;
	}

	/**
	 * Get information about the vector storage system
	 *
	 * @returns Vector storage system information including connection status and backend type
	 */
	public getInfo(): VectorStoreInfo {
		return {
			connected: this.connected,
			backend: {
				type: this.backendMetadata.type,
				connected: this.store?.isConnected() ?? false,
				fallback: this.usedFallback,
				collectionName: this.config.collectionName,
				dimension: this.config.dimension,
			},
			connectionAttempts: this.connectionAttempts,
			lastError: this.lastConnectionError?.message,
		};
	}

	/**
	 * Get the current vector store if connected
	 *
	 * @returns The vector store or null if not connected
	 */
	public getStore(): VectorStore | null {
		if (!this.connected || !this.store) {
			return null;
		}

		return this.store;
	}

	/**
	 * Get an event-aware vector store for a specific session
	 *
	 * @param sessionId - The session ID to associate with memory operations
	 * @returns Event-aware vector store or null if not connected
	 */
	public getEventAwareStore(sessionId: string): VectorStore | null {
		if (!this.connected || !this.store) {
			return null;
		}

		// Return event-aware wrapper if EventManager is available
		if (this.eventManager) {
			return new EventAwareVectorStore(this.store, this.eventManager, sessionId);
		}

		// Fallback to regular store if no event manager
		return this.store;
	}

	/**
	 * Check if the vector storage manager is connected
	 *
	 * @returns true if backend is connected
	 */
	public isConnected(): boolean {
		return this.connected && this.store?.isConnected() === true;
	}

	/**
	 * Connect to vector storage backend
	 *
	 * @returns The connected vector store
	 * @throws {VectorStoreConnectionError} If backend fails to connect
	 */
	public async connect(): Promise<VectorStore> {
		// Reset runtime fallback flag but preserve factory fallback
		if (!this.factoryFallback) {
			this.usedFallback = false;
		}
		// Check if already connected
		if (this.connected && this.store) {
			this.logger.debug(`${LOG_PREFIXES.MANAGER} Already connected`, {
				type: this.backendMetadata.type,
			});

			return this.store;
		}

		this.connectionAttempts++;
		this.logger.debug(
			`${LOG_PREFIXES.MANAGER} Starting connection attempt ${this.connectionAttempts} for ${this.config.collectionName}`
		);

		try {
			// Create and connect backend
			const startTime = Date.now();
			try {
				this.store = await this.createBackend();
				await this.store.connect();
				// Only reset fallback flag if this wasn't a factory-level fallback
				if (!this.factoryFallback) {
					this.usedFallback = false; // Not a fallback if primary backend succeeded
				}

				this.logger.debug(`${LOG_PREFIXES.MANAGER} Connected to ${this.config.collectionName}`, {
					type: this.backendMetadata.type,
					isFallback: this.backendMetadata.isFallback,
					connectionTime: `${this.backendMetadata.connectionTime}ms`,
				});
			} catch (backendError) {
				// If the configured backend fails, try fallback to in-memory
				this.logger.warn(`${LOG_PREFIXES.MANAGER} Backend connection failed, attempting fallback`, {
					error: backendError instanceof Error ? backendError.message : String(backendError),
					originalType: this.config.type,
				});

				if (this.config.type !== BACKEND_TYPES.IN_MEMORY) {
					const { InMemoryBackend } = await import('./backend/in-memory.js');
					this.store = new InMemoryBackend({
						type: 'in-memory',
						collectionName: this.config.collectionName,
						dimension: this.config.dimension,
						maxVectors: 10000,
					});
					await this.store.connect();
					this.backendMetadata.type = BACKEND_TYPES.IN_MEMORY;
					this.backendMetadata.isFallback = true;
					this.backendMetadata.connectionTime = Date.now() - startTime;
					this.usedFallback = true; // Mark as fallback

					this.logger.info(`${LOG_PREFIXES.MANAGER} Connected to fallback backend`, {
						type: this.backendMetadata.type,
						originalType: this.config.type,
					});
				} else {
					// In-memory is primary, not a fallback (unless factory fallback)
					if (!this.factoryFallback) {
						this.usedFallback = false;
					}
					throw backendError; // Re-throw if already using in-memory
				}
			}

			this.connected = true;

			// Emit vector store connected event
			if (this.eventManager) {
				this.eventManager.emitServiceEvent(ServiceEvents.VECTOR_STORE_CONNECTED, {
					provider: this.backendMetadata.type,
					timestamp: Date.now(),
				});
			}

			this.logger.info(`${LOG_PREFIXES.MANAGER} Vector storage system connected`, {
				backend: this.backendMetadata.type,
				totalConnectionTime: `${this.backendMetadata.connectionTime}ms`,
			});

			return this.store!;
		} catch (error) {
			// Store error for reporting
			this.lastConnectionError = error as Error;

			// Disconnect any successfully connected backend
			if (this.store?.isConnected()) {
				await this.store.disconnect().catch(err =>
					this.logger.error(`${LOG_PREFIXES.MANAGER} Error during cleanup disconnect`, {
						error: err,
					})
				);
			}

			// Reset state
			this.store = undefined;
			this.connected = false;
			this.usedFallback = false;

			throw error;
		}
	}

	/**
	 * Disconnect from vector storage backend
	 */
	public async disconnect(): Promise<void> {
		if (!this.connected) {
			this.logger.debug(`${LOG_PREFIXES.MANAGER} Already disconnected`);
			return;
		}

		this.logger.info(`${LOG_PREFIXES.MANAGER} Disconnecting vector storage backend`);

		try {
			if (this.store?.isConnected()) {
				await Promise.race([
					this.store.disconnect(),
					new Promise((_, reject) =>
						setTimeout(() => reject(new Error('Disconnect timeout')), TIMEOUTS.SHUTDOWN)
					),
				]);

				// Emit vector store disconnected event
				if (this.eventManager) {
					this.eventManager.emitServiceEvent(ServiceEvents.VECTOR_STORE_DISCONNECTED, {
						provider: this.backendMetadata.type,
						reason: 'Normal disconnection',
						timestamp: Date.now(),
					});
				}

				this.logger.info(`${LOG_PREFIXES.MANAGER} Disconnected successfully`);
			}
		} catch (error) {
			// Emit vector store error event
			if (this.eventManager) {
				this.eventManager.emitServiceEvent(ServiceEvents.VECTOR_STORE_ERROR, {
					provider: this.backendMetadata.type,
					error: error instanceof Error ? error.message : String(error),
					timestamp: Date.now(),
				});
			}

			this.logger.error(`${LOG_PREFIXES.MANAGER} Disconnect error`, { error });
			throw error;
		} finally {
			// Always clean up state
			this.store = undefined;
			this.connected = false;
			this.usedFallback = false;

			// Reset metadata
			this.backendMetadata = {
				type: 'unknown',
				isFallback: false,
				connectionTime: 0,
			};

			this.logger.info(`${LOG_PREFIXES.MANAGER} Vector storage system disconnected`);
		}
	}

	/**
	 * Perform health check on the backend
	 *
	 * @returns Health check results
	 */
	public async healthCheck(): Promise<HealthCheckResult> {
		if (!this.connected || !this.store) {
			return {
				backend: false,
				overall: false,
				details: {
					backend: { status: 'not_connected' },
				},
			};
		}

		this.logger.debug(`${LOG_PREFIXES.MANAGER} Performing health check`);

		try {
			const startTime = Date.now();

			// Test basic operations
			const isConnected = this.store.isConnected();
			const latency = Date.now() - startTime;

			const result = {
				backend: isConnected,
				overall: isConnected,
				details: {
					backend: {
						status: isConnected ? 'healthy' : 'unhealthy',
						latency,
					},
				},
			};

			this.logger.info(`${LOG_PREFIXES.MANAGER} Health check completed`, {
				overall: result.overall,
				latency: `${latency}ms`,
			});

			return result;
		} catch (error) {
			this.logger.error(`${LOG_PREFIXES.MANAGER} Health check failed`, { error });

			return {
				backend: false,
				overall: false,
				details: {
					backend: {
						status: 'error',
						error: error instanceof Error ? error.message : String(error),
					},
				},
			};
		}
	}

	// Private helper methods

	/**
	 * Create vector store backend based on configuration
	 */
	private async createBackend(): Promise<VectorStore> {
		const config = this.config;

		switch (config.type) {
			case BACKEND_TYPES.QDRANT: {
				try {
					// Lazy load Qdrant module
					if (!VectorStoreManager.qdrantModule) {
						this.logger.debug(`${LOG_PREFIXES.MANAGER} Lazy loading Qdrant module`);
						const { QdrantBackend } = await import('./backend/qdrant.js');
						VectorStoreManager.qdrantModule = QdrantBackend;
					}

					const QdrantBackend = VectorStoreManager.qdrantModule;
					this.backendMetadata.type = BACKEND_TYPES.QDRANT;
					this.backendMetadata.isFallback = false;

					return new QdrantBackend(config);
				} catch (error) {
					this.logger.debug(`${LOG_PREFIXES.MANAGER} Failed to create Qdrant backend`, {
						error: error instanceof Error ? error.message : String(error),
					});
					throw error; // Let connection handler deal with fallback
				}
			}

			case BACKEND_TYPES.MILVUS: {
				try {
					// Lazy load Milvus module (shared across all instances)
					if (!VectorStoreManager.milvusModule) {
						this.logger.debug(`${LOG_PREFIXES.MANAGER} Lazy loading Milvus module`);
						const { MilvusBackend } = await import('./backend/milvus.js');
						VectorStoreManager.milvusModule = MilvusBackend;
					}

					const MilvusBackend = VectorStoreManager.milvusModule;
					this.backendMetadata.type = BACKEND_TYPES.MILVUS;
					this.backendMetadata.isFallback = false;

					return new MilvusBackend(config);
				} catch (error) {
					this.logger.info(`${LOG_PREFIXES.MANAGER} Failed to create Milvus backend: ${error}`, {
						error: error instanceof Error ? error.message : String(error),
					});
					throw error; // Let connection handler deal with fallback
				}
			}

			case BACKEND_TYPES.CHROMA: {
				try {
					// Lazy load ChromaDB module (shared across all instances)
					if (!VectorStoreManager.chromaModule) {
						this.logger.debug(`${LOG_PREFIXES.MANAGER} Lazy loading ChromaDB module`);
						const { ChromaBackend } = await import('./backend/chroma.js');
						VectorStoreManager.chromaModule = ChromaBackend;
					}

					const ChromaBackend = VectorStoreManager.chromaModule;
					this.backendMetadata.type = BACKEND_TYPES.CHROMA;
					this.backendMetadata.isFallback = false;

					return new ChromaBackend(config);
				} catch (error) {
					this.logger.info(`${LOG_PREFIXES.MANAGER} Failed to create ChromaDB backend: ${error}`, {
						error: error instanceof Error ? error.message : String(error),
					});
					throw error; // Let connection handler deal with fallback
				}
			}

			case BACKEND_TYPES.IN_MEMORY:
			default: {
				// Use in-memory backend
				if (!VectorStoreManager.inMemoryModule) {
					this.logger.debug(`${LOG_PREFIXES.MANAGER} Lazy loading in-memory module`);
					const { InMemoryBackend } = await import('./backend/in-memory.js');
					VectorStoreManager.inMemoryModule = InMemoryBackend;
				}

				const InMemoryBackend = VectorStoreManager.inMemoryModule;
				this.backendMetadata.type = BACKEND_TYPES.IN_MEMORY;
				this.backendMetadata.isFallback = false;

				return new InMemoryBackend(config);
			}
		}
	}
}

/**
 * Multi Collection Vector Manager
 *
 * Manages multiple separate vector collections for knowledge, reflection, and workspace memory.
 * Built on top of the existing VectorStoreManager infrastructure.
 */

import { VectorStoreManager } from './manager.js';
import { VectorStore } from './backend/vector-store.js';
import type { VectorStoreConfig } from './types.js';
import { Logger, createLogger } from '../logger/index.js';
import { env } from '../env.js';
import { EventManager } from '../events/event-manager.js';

/**
 * Collection type identifier
 */
export type CollectionType = 'knowledge' | 'reflection' | 'workspace';

/**
 * Information about all collections
 */
export interface MultiCollectionInfo {
	knowledge: {
		connected: boolean;
		collectionName: string;
		manager: VectorStoreManager;
	};
	reflection: {
		connected: boolean;
		collectionName: string;
		manager: VectorStoreManager;
		enabled: boolean;
	};
	workspace: {
		connected: boolean;
		collectionName: string;
		manager: VectorStoreManager;
		enabled: boolean;
	};
	overallConnected: boolean;
}

/**
 * Multi Collection Vector Manager
 *
 * Manages separate vector collections for knowledge, reflection, and workspace memory.
 * Uses multiple VectorStoreManager instances under the hood.
 *
 * @example
 * ```typescript
 * const multiManager = new MultiCollectionVectorManager(baseConfig);
 * await multiManager.connect();
 *
 * // Get knowledge store
 * const knowledgeStore = multiManager.getStore('knowledge');
 *
 * // Get reflection store (if enabled)
 * const reflectionStore = multiManager.getStore('reflection');
 *
 * // Get workspace store (if enabled)
 * const workspaceStore = multiManager.getStore('workspace');
 * ```
 */
export class MultiCollectionVectorManager {
	private readonly knowledgeManager: VectorStoreManager;
	private readonly reflectionManager: VectorStoreManager | null;
	private readonly workspaceManager: VectorStoreManager | null;
	private readonly logger: Logger;
	private readonly reflectionEnabled: boolean;
	private readonly workspaceEnabled: boolean;
	private eventManager?: EventManager;

	constructor(baseConfig: VectorStoreConfig) {
		this.logger = createLogger({
			level: env.CIPHER_LOG_LEVEL || 'info',
		});

		// Check if reflection memory is enabled
		this.reflectionEnabled = !!(
			env.REFLECTION_VECTOR_STORE_COLLECTION && env.REFLECTION_VECTOR_STORE_COLLECTION.trim()
		);

		// Check if workspace memory is enabled
		this.workspaceEnabled = !!(
			env.USE_WORKSPACE_MEMORY &&
			env.WORKSPACE_VECTOR_STORE_COLLECTION &&
			env.WORKSPACE_VECTOR_STORE_COLLECTION.trim()
		);

		// Create knowledge manager with original collection name
		this.knowledgeManager = new VectorStoreManager(baseConfig);

		// Create reflection manager only if reflection collection name is set
		if (this.reflectionEnabled) {
			const reflectionConfig: VectorStoreConfig = {
				...baseConfig,
				collectionName: env.REFLECTION_VECTOR_STORE_COLLECTION,
			};
			this.reflectionManager = new VectorStoreManager(reflectionConfig);
		} else {
			this.reflectionManager = null;
		}

		// Create workspace manager only if workspace memory is enabled
		if (this.workspaceEnabled) {
			// Create workspace config with proper type handling
			const workspaceConfig = {
				...baseConfig,
				// Override collection name and dimension
				collectionName: env.WORKSPACE_VECTOR_STORE_COLLECTION,
				dimension: env.WORKSPACE_VECTOR_STORE_DIMENSION || baseConfig.dimension,
			} as VectorStoreConfig;

			// Override type if specified
			if (env.WORKSPACE_VECTOR_STORE_TYPE) {
				workspaceConfig.type = env.WORKSPACE_VECTOR_STORE_TYPE;
			}

			// Only add type-specific properties if they exist in the base config and environment
			if ('host' in baseConfig && env.WORKSPACE_VECTOR_STORE_HOST) {
				(workspaceConfig as any).host = env.WORKSPACE_VECTOR_STORE_HOST;
			}
			if ('port' in baseConfig && env.WORKSPACE_VECTOR_STORE_PORT) {
				(workspaceConfig as any).port = env.WORKSPACE_VECTOR_STORE_PORT;
			}
			if ('url' in baseConfig && env.WORKSPACE_VECTOR_STORE_URL) {
				(workspaceConfig as any).url = env.WORKSPACE_VECTOR_STORE_URL;
			}
			if ('apiKey' in baseConfig && env.WORKSPACE_VECTOR_STORE_API_KEY) {
				(workspaceConfig as any).apiKey = env.WORKSPACE_VECTOR_STORE_API_KEY;
			}
			if ('username' in baseConfig && env.WORKSPACE_VECTOR_STORE_USERNAME) {
				(workspaceConfig as any).username = env.WORKSPACE_VECTOR_STORE_USERNAME;
			}
			if ('password' in baseConfig && env.WORKSPACE_VECTOR_STORE_PASSWORD) {
				(workspaceConfig as any).password = env.WORKSPACE_VECTOR_STORE_PASSWORD;
			}
			if ('distance' in baseConfig && env.WORKSPACE_VECTOR_STORE_DISTANCE) {
				// Normalize distance per backend requirements
				let wsDistance: any = env.WORKSPACE_VECTOR_STORE_DISTANCE;
				const wsType = (workspaceConfig as any).type || baseConfig.type;
				if (wsType === 'chroma') {
					const d = String(wsDistance).toLowerCase();
					if (d === 'cosine') wsDistance = 'cosine';
					else if (d === 'euclidean' || d === 'l2') wsDistance = 'l2';
					else if (d === 'dot' || d === 'ip') wsDistance = 'ip';
					else wsDistance = 'cosine';
				}
				(workspaceConfig as any).distance = wsDistance;
			}
			if ('onDisk' in baseConfig && env.WORKSPACE_VECTOR_STORE_ON_DISK !== undefined) {
				(workspaceConfig as any).onDisk = env.WORKSPACE_VECTOR_STORE_ON_DISK;
			}
			if ('maxVectors' in baseConfig && env.WORKSPACE_VECTOR_STORE_MAX_VECTORS) {
				(workspaceConfig as any).maxVectors = env.WORKSPACE_VECTOR_STORE_MAX_VECTORS;
			}
			this.workspaceManager = new VectorStoreManager(workspaceConfig);

			this.logger.info('MultiCollectionVectorManager: Initialized with multiple collections', {
				backend: baseConfig.type,
				knowledgeCollection: baseConfig.collectionName,
				reflectionCollection: this.reflectionEnabled
					? env.REFLECTION_VECTOR_STORE_COLLECTION
					: 'disabled',
				workspaceCollection: env.WORKSPACE_VECTOR_STORE_COLLECTION,
				dimension: baseConfig.dimension,
			});
		} else {
			this.workspaceManager = null;

			this.logger.info('MultiCollectionVectorManager: Initialized without workspace memory', {
				backend: baseConfig.type,
				knowledgeCollection: baseConfig.collectionName,
				reflectionCollection: this.reflectionEnabled
					? env.REFLECTION_VECTOR_STORE_COLLECTION
					: 'disabled',
				workspaceCollection: 'disabled',
				dimension: baseConfig.dimension,
			});
		}
	}

	/**
	 * Set event manager for event-aware operations
	 */
	setEventManager(eventManager: EventManager): void {
		this.eventManager = eventManager;
		this.knowledgeManager.setEventManager(eventManager);
		if (this.reflectionManager) {
			this.reflectionManager.setEventManager(eventManager);
		}
		if (this.workspaceManager) {
			this.workspaceManager.setEventManager(eventManager);
		}
	}

	/**
	 * Connect to all enabled vector stores
	 */
	async connect(): Promise<boolean> {
		const promises: Promise<VectorStore>[] = [];

		// Always connect knowledge manager
		promises.push(this.knowledgeManager.connect());

		// Connect reflection manager if enabled
		if (this.reflectionManager) {
			promises.push(this.reflectionManager.connect());
		}

		// Connect workspace manager if enabled
		if (this.workspaceManager) {
			promises.push(this.workspaceManager.connect());
		}

		try {
			const results = await Promise.all(promises);

			// Check if at least the knowledge manager connected successfully
			const knowledgeConnected = !!results[0];

			if (!knowledgeConnected) {
				this.logger.error('MultiCollectionVectorManager: Failed to connect knowledge manager');
				return false;
			}

			this.logger.info('MultiCollectionVectorManager: Connection completed', {
				knowledge: knowledgeConnected,
				reflection: this.reflectionEnabled ? !!results[1] : 'disabled',
				workspace: this.workspaceEnabled ? !!results[results.length - 1] : 'disabled',
			});

			return true;
		} catch (error) {
			this.logger.error('MultiCollectionVectorManager: Connection failed', {
				error: error instanceof Error ? error.message : String(error),
			});
			return false;
		}
	}

	/**
	 * Disconnect from all vector stores
	 */
	async disconnect(): Promise<void> {
		const promises: Promise<void>[] = [];

		promises.push(this.knowledgeManager.disconnect());

		if (this.reflectionManager) {
			promises.push(this.reflectionManager.disconnect());
		}

		if (this.workspaceManager) {
			promises.push(this.workspaceManager.disconnect());
		}

		await Promise.all(promises);
	}

	/**
	 * Get vector store by collection type
	 */
	getStore(type: CollectionType): VectorStore | null {
		switch (type) {
			case 'knowledge':
				return this.knowledgeManager.getStore();
			case 'reflection':
				if (!this.reflectionEnabled || !this.reflectionManager) {
					this.logger.debug('MultiCollectionVectorManager: Reflection memory is disabled');
					return null;
				}
				return this.reflectionManager.getStore();
			case 'workspace':
				if (!this.workspaceEnabled || !this.workspaceManager) {
					this.logger.debug('MultiCollectionVectorManager: Workspace memory is disabled');
					return null;
				}
				return this.workspaceManager.getStore();
			default:
				throw new Error(`Unknown collection type: ${type}`);
		}
	}

	/**
	 * Get vector store by named collection (for backward compatibility)
	 */
	getNamedStore(collectionName: string): VectorStore | null {
		// Map collection names to types
		if (collectionName === env.WORKSPACE_VECTOR_STORE_COLLECTION) {
			return this.getStore('workspace');
		}
		if (collectionName === env.REFLECTION_VECTOR_STORE_COLLECTION) {
			return this.getStore('reflection');
		}
		// Default to knowledge store for other collection names
		return this.getStore('knowledge');
	}

	/**
	 * Get an event-aware vector store by collection type for a specific session
	 */
	getEventAwareStore(type: CollectionType, sessionId: string): VectorStore | null {
		switch (type) {
			case 'knowledge':
				return this.knowledgeManager.getEventAwareStore(sessionId);
			case 'reflection':
				if (!this.reflectionEnabled || !this.reflectionManager) {
					this.logger.debug('MultiCollectionVectorManager: Reflection memory is disabled');
					return null;
				}
				return this.reflectionManager.getEventAwareStore(sessionId);
			case 'workspace':
				if (!this.workspaceEnabled || !this.workspaceManager) {
					this.logger.debug('MultiCollectionVectorManager: Workspace memory is disabled');
					return null;
				}
				return this.workspaceManager.getEventAwareStore(sessionId);
			default:
				throw new Error(`Unknown collection type: ${type}`);
		}
	}

	/**
	 * Health check for all collections
	 */
	async healthCheck(): Promise<{
		knowledge: boolean;
		reflection: boolean;
		workspace: boolean;
		overall: boolean;
	}> {
		const knowledgeHealthy = (await this.knowledgeManager.healthCheck()).overall;

		let reflectionHealthy = true;
		if (this.reflectionEnabled && this.reflectionManager) {
			reflectionHealthy = (await this.reflectionManager.healthCheck()).overall;
		}

		let workspaceHealthy = true;
		if (this.workspaceEnabled && this.workspaceManager) {
			workspaceHealthy = (await this.workspaceManager.healthCheck()).overall;
		}

		return {
			knowledge: knowledgeHealthy,
			reflection: reflectionHealthy,
			workspace: workspaceHealthy,
			overall: knowledgeHealthy && reflectionHealthy && workspaceHealthy,
		};
	}

	/**
	 * Get vector store manager by collection type
	 */
	getManager(type: CollectionType): VectorStoreManager | null {
		switch (type) {
			case 'knowledge':
				return this.knowledgeManager;
			case 'reflection':
				return this.reflectionManager;
			case 'workspace':
				return this.workspaceManager;
			default:
				throw new Error(`Unknown collection type: ${type}`);
		}
	}

	/**
	 * Get information about all collections
	 */
	getInfo(): MultiCollectionInfo {
		return {
			knowledge: {
				connected: this.knowledgeManager.isConnected(),
				collectionName: this.knowledgeManager.getInfo().backend.collectionName,
				manager: this.knowledgeManager,
			},
			reflection: {
				connected: this.reflectionManager?.isConnected() ?? false,
				collectionName: env.REFLECTION_VECTOR_STORE_COLLECTION || '',
				manager: this.reflectionManager!,
				enabled: this.reflectionEnabled,
			},
			workspace: {
				connected: this.workspaceManager?.isConnected() ?? false,
				collectionName: env.WORKSPACE_VECTOR_STORE_COLLECTION || '',
				manager: this.workspaceManager!,
				enabled: this.workspaceEnabled,
			},
			overallConnected:
				this.knowledgeManager.isConnected() &&
				(!this.reflectionEnabled || this.reflectionManager?.isConnected() === true) &&
				(!this.workspaceEnabled || this.workspaceManager?.isConnected() === true),
		};
	}

	/**
	 * Check if any collection is connected
	 */
	isConnected(): boolean {
		return this.knowledgeManager.isConnected();
	}
}

/** * Vector Storage Module Public API * * This module re-exports all the necessary types and interfaces for the vector storage system. * It provides a simplified, clean API surface for consumers of the vector storage module. * * The vector storage system architecture: * - Single backend design for vector similarity search * - Multiple backend implementations: Qdrant, Pinecone, In-Memory, etc. * - Consistent API across different backend types * - Strong type safety with TypeScript and runtime validation with Zod * * @module vector_storage * * @example * ```typescript * import type { VectorStoreConfig, VectorStore } from './vector_storage/types.js'; * * // Configure vector storage * const config: VectorStoreConfig = { * type: 'qdrant', * host: 'localhost', * port: 6333, * collectionName: 'embeddings', * dimension: 1536 * }; * * // Use vector store * const store: VectorStore = createVectorStore(config); * ``` */
/** * Re-export simplified vector storage types * * These exports provide the complete type system needed to work with * the vector storage module without exposing internal implementation details. */ export type { // Core interfaces VectorStore, // Interface for vector store implementations VectorStoreResult, // Search result structure SearchFilters, // Metadata filters for search
// Configuration types BackendConfig, // Union type for all backend configurations VectorStoreConfig, // Top-level vector storage system configuration } from './backend/types.js';

import { defineConfig } from 'vitest/config';
import path from 'path';

export default defineConfig({
	resolve: {
		alias: {
			'@core': path.resolve(__dirname, 'src/core'),
			'@app': path.resolve(__dirname, 'src/app'),
		},
	},
	test: {
		globals: true,
		environment: 'node',
		include: process.env.INTEGRATION_TESTS_ONLY 
			? ['src/**/*integration*.test.ts']
			: ['src/**/*.test.ts', 'src/**/*.spec.ts'],
		exclude: [
			'**/node_modules/**',
			'**/dist/**',
			'**/build/**',
			...(process.env.CI ? ['**/integration/**'] : []),
			...(process.env.INTEGRATION_TESTS_ONLY ? [] : ['**/*integration*.test.ts']),
		],
		watch: true,
	},
});
